	public function ensure_required_pages(): void
	{
		if (! is_admin() || wp_doing_ajax() || $this->sn_defer_heavy_admin_runtime()) {
			return;
		}
		if ((string) get_option('sn_pages_repair_version', '') === SN_VERSION) {
			return;
		}
		if (class_exists('SN_Activator') && method_exists('SN_Activator', 'create_required_pages')) {
			SN_Activator::create_required_pages();
			update_option('sn_pages_repair_version', SN_VERSION, false);
		}
	}

