	private function sn_current_front_request_has_shortcode_reference(string $shortcode): bool
	{
		global $post;
		if (! $post || ! is_singular()) { return false; }
		static $source_cache = [];
		$post_id = (int) $post->ID;
		if (! isset($source_cache[$post_id])) {
			$source_cache[$post_id] = [
				'content' => (string) ($post->post_content ?? ''),
				'elementor' => (string) get_post_meta($post_id, '_elementor_data', true),
			];
		}
		$sources = $source_cache[$post_id];
		return has_shortcode((string) $sources['content'], $shortcode)
			|| strpos((string) $sources['elementor'], $shortcode) !== false;
	}

	private function sn_current_front_request_has_crm_shortcode(): bool
	{
		foreach ($this->sn_front_shortcodes_for_assets() as $shortcode) {
			if ($this->sn_current_front_request_has_shortcode_reference($shortcode)) { return true; }
		}
		return false;
	}

