			'asset_key'    => $asset_key,
			'invoice_token' => sanitize_text_field(wp_unslash($_GET['access_token'] ?? ($_GET['token'] ?? ''))),
		];
		if (wp_script_is('sn-public-base', 'enqueued')) {
			wp_localize_script('sn-public-base', 'snAjax', $sn_public_data);
			wp_localize_script('sn-public-base', 'snData', $sn_public_data);
		}
		if (wp_script_is('sn-public-dot-shared', 'enqueued')) {
			wp_localize_script('sn-public-dot-shared', 'snAjax', $sn_public_data);
			wp_localize_script('sn-public-dot-shared', 'snData', $sn_public_data);
		}
		wp_localize_script($handle, 'snAjax', $sn_public_data);
		wp_localize_script($handle, 'snData', $sn_public_data);
		if (is_user_logged_in() && class_exists('SN_Dot_Flow') && SN_Dot_Flow::instance()->is_sms_test_mode()) {
			$dot_test_css = 'assets/css/dot-test-sms.css';
			$dot_test_js = 'assets/js/public-dot-test-sms-1.0.160.js';
			$dot_test_css_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . $dot_test_css) ? (string) filemtime(SN_PLUGIN_DIR . $dot_test_css) : '0');
			$dot_test_js_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . $dot_test_js) ? (string) filemtime(SN_PLUGIN_DIR . $dot_test_js) : '0');
			wp_enqueue_style('sn-dot-test-sms', SN_PLUGIN_URL . $dot_test_css, ['sn-public'], $dot_test_css_version);
			wp_enqueue_script('sn-dot-test-sms', SN_PLUGIN_URL . $dot_test_js, ['sn-public-shell'], $dot_test_js_version, true);
			wp_localize_script('sn-dot-test-sms', 'snDotTestSms', [
				'ajaxUrl' => admin_url('admin-ajax.php'),
				'nonce' => wp_create_nonce('sn_dot_test_sms'),
				'runId' => SN_Dot_Flow::instance()->sms_test_runtime_id(),
				'pollInterval' => 4000,
				'label' => 'پیامک آزمایشی دات فلو',
			]);
		}
		if ($asset_key === 'supervisor') {
			$dot_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/js/public-dot.js') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/js/public-dot.js') : '0');
			wp_enqueue_script('sn-public-dot', SN_PLUGIN_URL . 'assets/js/public-dot.js', ['jquery', $handle], $dot_version, true);
			wp_localize_script('sn-public-dot', 'snDot', $sn_public_data);
		} elseif ($asset_key === 'dot') {
			wp_localize_script($handle, 'snDot', $sn_public_data);
		}
	}
	public function dequeue_external_fonts(): void
	{
		if (! $this->sn_current_front_request_has_crm_shortcode() && ! (function_exists('is_account_page') && is_account_page())) { return; }
		global $wp_styles;
		if (empty($wp_styles) || empty($wp_styles->registered)) {
			return;
		}
		foreach ($wp_styles->registered as $handle => $style) {
			$src = isset($style->src) ? (string) $style->src : '';
			if (false !== strpos($src, 'fonts.googleapis.com') || false !== strpos($src, 'fonts.gstatic.com')) {
				wp_dequeue_style($handle);
				wp_deregister_style($handle);
			}
		}
	}

	// ساخت جداول در صورت نبود (بدون نیاز به deactivate/activate)
	// غیرفعال کردن jwt-authentication در AJAX — این پلاگین header میفرسته و AJAX ما رو خراب میکنه
	public function disable_jwt_on_ajax(): void
	{
		if (! defined('DOING_AJAX') || ! DOING_AJAX) {
			return;
		}
		$action = sanitize_key(wp_unslash($_REQUEST['action'] ?? ''));
		// فقط برای action های پلاگین ما
		if (strpos($action, 'sn_') !== 0) {
			return;
		}
		add_filter('jwt_auth_do_jwt_check', '__return_false', 999);
		// پاک کردن output buffer از همان ابتدا
		if (! ob_get_level()) {
			ob_start();
		}
	}


	private function sn_is_crm_admin_context(): bool
	{
		$action = sanitize_key(wp_unslash($_REQUEST['action'] ?? ''));
		if ($action !== '' && strpos($action, 'sn_') === 0) { return true; }
		if (wp_doing_ajax()) { return $action !== '' && strpos($action, 'sn_') === 0; }
		$page = sanitize_key(wp_unslash($_GET['page'] ?? ''));
		if ($page !== '' && (strpos($page, 'sn-') === 0 || $page === 'sn-dashboard' || strpos($page, 'sn_') === 0)) { return true; }
		$hook = (string) ($GLOBALS['hook_suffix'] ?? '');
		if ($hook !== '' && (strpos($hook, 'sn-') !== false || strpos($hook, 'toplevel_page_sn') !== false)) { return true; }
		return false;
	}

	private function sn_defer_heavy_admin_runtime(): bool
	{
		return is_admin() && ! wp_doing_ajax() && ! $this->sn_is_crm_admin_context();
	}

	public function maybe_create_tables(): void
	{
		if ((string) get_option('sn_runtime_tables_version', '') === SN_VERSION) { return; }
		if ($this->sn_defer_heavy_admin_runtime()) { return; }
		global $wpdb;
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
		$charset = $wpdb->get_charset_collate();

		// ---- 1. جدول sn_lead_statuses ----
		$st_table = $wpdb->prefix . 'sn_lead_statuses';
		if ($wpdb->get_var("SHOW TABLES LIKE '{$st_table}'") !== $st_table) {
			dbDelta("CREATE TABLE {$st_table} (
				id INT UNSIGNED NOT NULL AUTO_INCREMENT,
				label VARCHAR(100) NOT NULL,
				color VARCHAR(20) NOT NULL DEFAULT '#6b7280',
				sort_order INT NOT NULL DEFAULT 0,
				is_active TINYINT(1) NOT NULL DEFAULT 1,
				destination_panel VARCHAR(50) DEFAULT NULL,
				move_to_destination TINYINT(1) NOT NULL DEFAULT 0,
				PRIMARY KEY (id)
			) {$charset};");
			$defaults = [
				['label' => 'جواب نداده', 'color' => '#f59e0b', 'sort_order' => 1],
				['label' => 'تماس مجدد', 'color' => '#3b82f6', 'sort_order' => 2],
				['label' => 'عدم خرید',   'color' => '#ef4444', 'sort_order' => 3],
				['label' => 'پیش‌فاکتور', 'color' => '#0ea5e9', 'sort_order' => 4],
			];
			foreach ($defaults as $s) {
				$wpdb->insert($st_table, $s);
			}
		}
		if ($wpdb->get_var("SHOW TABLES LIKE '{$st_table}'") === $st_table) {
			$st_cols = $wpdb->get_col("SHOW COLUMNS FROM {$st_table}", 0);
			if (! in_array('destination_panel', $st_cols, true)) { $wpdb->query("ALTER TABLE {$st_table} ADD COLUMN destination_panel VARCHAR(50) DEFAULT NULL AFTER is_active"); }
			if (! in_array('move_to_destination', $st_cols, true)) { $wpdb->query("ALTER TABLE {$st_table} ADD COLUMN move_to_destination TINYINT(1) NOT NULL DEFAULT 0 AFTER destination_panel"); }
		}


		// ---- جداول لاگ و تاریخچه وضعیت ----
		dbDelta("CREATE TABLE {$wpdb->prefix}sn_activity_logs (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			lead_id BIGINT UNSIGNED DEFAULT NULL,
			invoice_id BIGINT UNSIGNED DEFAULT NULL,
			user_id BIGINT UNSIGNED DEFAULT NULL,
			action VARCHAR(120) NOT NULL,
			old_value LONGTEXT DEFAULT NULL,
			new_value LONGTEXT DEFAULT NULL,
			description TEXT DEFAULT NULL,
			context LONGTEXT DEFAULT NULL,
			ip_address VARCHAR(64) DEFAULT NULL,
			user_agent TEXT DEFAULT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
