		$leads_table_extra = $wpdb->prefix . 'sn_leads';
		if ($wpdb->get_var("SHOW TABLES LIKE '{$leads_table_extra}'") === $leads_table_extra) {
			$lead_cols_extra = $wpdb->get_col("SHOW COLUMNS FROM {$leads_table_extra}", 0);
			if (! in_array('source_tag', $lead_cols_extra, true)) { $wpdb->query("ALTER TABLE {$leads_table_extra} ADD COLUMN source_tag VARCHAR(80) DEFAULT NULL AFTER destination_panel"); }
			if (! in_array('extra_number_request_id', $lead_cols_extra, true)) { $wpdb->query("ALTER TABLE {$leads_table_extra} ADD COLUMN extra_number_request_id BIGINT UNSIGNED DEFAULT NULL AFTER source_tag"); }
		}

		$invoice_table_extra = $wpdb->prefix . 'sn_invoices';
		if ($wpdb->get_var("SHOW TABLES LIKE '{$invoice_table_extra}'") === $invoice_table_extra) {
			$invoice_cols_extra = $wpdb->get_col("SHOW COLUMNS FROM {$invoice_table_extra}", 0);
			if (! in_array('parent_invoice_id', $invoice_cols_extra, true)) { $wpdb->query("ALTER TABLE {$invoice_table_extra} ADD COLUMN parent_invoice_id BIGINT UNSIGNED DEFAULT NULL AFTER lead_id"); }
			if (! in_array('repeat_action_status', $invoice_cols_extra, true)) { $wpdb->query("ALTER TABLE {$invoice_table_extra} ADD COLUMN repeat_action_status VARCHAR(60) DEFAULT NULL AFTER recontact_note"); }
			if (! in_array('repeat_action_cancel_reason', $invoice_cols_extra, true)) { $wpdb->query("ALTER TABLE {$invoice_table_extra} ADD COLUMN repeat_action_cancel_reason TEXT DEFAULT NULL AFTER repeat_action_status"); }
			if (! in_array('finance_edit_note', $invoice_cols_extra, true)) { $wpdb->query("ALTER TABLE {$invoice_table_extra} ADD COLUMN finance_edit_note TEXT DEFAULT NULL AFTER financial_reject_reason"); }
		}


		// ---- HR display-name isolation: internal panel names are stored in HR profile, not wp_users ----
		$hr_profiles_table = $wpdb->prefix . 'sn_hr_profiles';
		if ($wpdb->get_var("SHOW TABLES LIKE '{$hr_profiles_table}'") === $hr_profiles_table) {
			$hr_profile_cols = $wpdb->get_col("SHOW COLUMNS FROM {$hr_profiles_table}", 0);
			if (! in_array('hr_display_name', $hr_profile_cols, true)) {
				$wpdb->query("ALTER TABLE {$hr_profiles_table} ADD COLUMN hr_display_name VARCHAR(191) DEFAULT NULL AFTER user_id");
			}
			$wpdb->query("UPDATE {$hr_profiles_table} hp INNER JOIN {$wpdb->users} u ON u.ID=hp.user_id SET hp.hr_display_name = u.display_name WHERE (hp.hr_display_name IS NULL OR hp.hr_display_name='')");
		}


		// ---- 3. debug: log آخرین خطای DB ----
		if ($wpdb->last_error) {
			error_log('SN DB Error in maybe_create_tables: ' . $wpdb->last_error);
		}
		update_option('sn_runtime_tables_version', SN_VERSION, false);
	}

	public function maybe_run_migration_service(): void
	{
		if (! is_admin() || wp_doing_ajax() || $this->sn_defer_heavy_admin_runtime() || ! class_exists('SN_Migration_Service')) { return; }
		if ((string) get_option('sn_db_version', '') === SN_Migration_Service::DB_VERSION && (string) get_option('sn_perf_index_version', '') === SN_PERF_INDEX_VERSION) { return; }
		$service = new SN_Migration_Service();
		global $wpdb;
		$positions_table = $wpdb->prefix . 'sn_hr_positions';
		if ($service->get_db_version() !== SN_Migration_Service::DB_VERSION || ! $service->table_exists($positions_table) || ! $service->mis_tables_complete() || ! $service->distribution_tables_complete() || ! $service->after_sales_tables_complete() || ! $service->commission_tables_complete() || ! $service->hr_compensation_tables_complete() || ! $service->default_seed_data_is_complete()) {
			$service->migrate();
		}
		$this->sn_apply_performance_indexes();
		update_option('sn_perf_index_version', SN_PERF_INDEX_VERSION, false);
	}

	private function sn_table_has_column(string $table, string $column): bool
	{
		global $wpdb;
		$key = $table . '|' . $column;
		if (array_key_exists($key, $this->sn_runtime_column_exists_cache)) {
			return (bool) $this->sn_runtime_column_exists_cache[$key];
		}
		$exists = (bool) $wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s", $column));
		$this->sn_runtime_column_exists_cache[$key] = $exists;
		return $exists;
	}

	private function sn_index_exists(string $table, string $index): bool
	{
		global $wpdb;
		$key = $table . '|' . $index;
		if (array_key_exists($key, $this->sn_runtime_index_exists_cache)) {
			return (bool) $this->sn_runtime_index_exists_cache[$key];
		}
		$exists = (bool) $wpdb->get_var($wpdb->prepare("SHOW INDEX FROM {$table} WHERE Key_name=%s", $index));
		$this->sn_runtime_index_exists_cache[$key] = $exists;
		return $exists;
	}

	private function sn_add_index_if_possible(string $table, string $index, array $columns): void
	{
		global $wpdb;
		if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") !== $table || $this->sn_index_exists($table, $index)) { return; }
		foreach ($columns as $column) { if (! $this->sn_table_has_column($table, $column)) { return; } }
		$cols = implode(',', array_map(static fn($c) => '`' . esc_sql($c) . '`', $columns));
		if ($wpdb->query("ALTER TABLE {$table} ADD INDEX {$index} ({$cols})") !== false) {
			$this->sn_runtime_index_exists_cache[$table . '|' . $index] = true;
		}
	}

