	public function enqueue_admin_assets(string $hook): void
	{
		if (false === strpos($hook, 'sn-') && false === strpos($hook, 'toplevel_page_sn')) {
			return;
		}
		wp_enqueue_style('sn-admin', SN_PLUGIN_URL . 'assets/css/admin.css', [], SN_VERSION);
		wp_enqueue_script('sn-admin', SN_PLUGIN_URL . 'assets/js/admin.js', ['jquery'], SN_VERSION, true);
		wp_localize_script('sn-admin', 'snAdmin', [
			'ajaxurl' => admin_url('admin-ajax.php'),
			'nonce'   => wp_create_nonce('sn_admin'),
		]);
	}

