	public function sn_map_meta_caps(array $caps, string $cap, int $user_id, array $args): array
	{
		if ($cap !== 'sn_admin_menu_access') {
			return $caps;
		}
		$user = get_userdata($user_id);
		if (! $user instanceof WP_User) {
			return ['do_not_allow'];
		}
		$allcaps = (array) $user->allcaps;
		if (! empty($allcaps['manage_options']) || ! empty($allcaps['sn_view_wallet_commission'])) {
			return ['read'];
		}
		return ['do_not_allow'];
	}

