				var upgrades = document.getElementById('sn-product-upgrade-rules');
				var selfActivation = document.getElementById('sn-product-self-activation');
				var list = document.getElementById('sn-product-upgrade-list');
				var addUpgrade = document.getElementById('sn-add-product-upgrade');
