					cb.addEventListener('change', function() {
						wrap.style.display = this.checked ? '' : 'none';
					});
				}
				function toggleUpgrades() {
					var standalone = document.getElementById('sn-product-star-standalone');
					if (standalone && type) standalone.style.display = (type.value || type.getAttribute('data-resolved-type')) === 'product_star' || (type.value || type.getAttribute('data-resolved-type')) === 'subscription_star' ? 'block' : 'none';
