					var effective = type.value || type.getAttribute('data-resolved-type') || '';
					upgrades.style.display = effective === 'product_star' || effective === 'subscription_star' ? '' : 'none';
					if (selfActivation) selfActivation.style.display = effective === 'product_star' || effective === 'subscription_star' ? 'flex' : 'none';
