	public function save_product_meta(int $post_id, \WP_Post $post): void
	{
		if (! isset($_POST['sn_product_nonce']) || ! wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['sn_product_nonce'])), 'sn_product_meta')) {
			return;
		}
		if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
			return;
		}
		if (! current_user_can('edit_post', $post_id)) {
			return;
		}
		$enabled = isset($_POST['sn_enabled']) ? '1' : '0';
		update_post_meta($post_id, '_sn_enabled', $enabled);
		$previous_sales_product_type = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance()->product_type($post_id) : (sanitize_key((string) get_post_meta($post_id, '_sn_sales_product_type', true)) ?: 'product');
		$sales_product_type = sanitize_key(wp_unslash($_POST['sn_sales_product_type'] ?? ''));
		if ($sales_product_type === 'subscription_star') { $sales_product_type = 'product_star'; }
		// Freeze missing legacy invoice-item types before changing the live
		// product classification. Existing non-empty snapshots are immutable.
		global $wpdb;
		$items_table = $wpdb->prefix . 'sn_invoice_items';
		if ((string) $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $items_table)) === $items_table) {
			$item_columns = (array) $wpdb->get_col("SHOW COLUMNS FROM {$items_table}", 0);
			if (in_array('product_type', $item_columns, true)) {
				$wpdb->query($wpdb->prepare("UPDATE {$items_table} SET product_type=%s WHERE product_id=%d AND (product_type IS NULL OR product_type='')", $previous_sales_product_type, $post_id));
			}
		}
		if (in_array($sales_product_type, ['assessment', 'subscription', 'product', 'product_star'], true)) {
			update_post_meta($post_id, '_sn_sales_product_type', $sales_product_type);
		} else {
			delete_post_meta($post_id, '_sn_sales_product_type');
		}
		$sub_content = wp_kses_post(wp_unslash($_POST['sn_subscription_content'] ?? ''));
		update_post_meta($post_id, '_sn_subscription_content', $sub_content);
		update_post_meta($post_id, '_sn_short_description', wp_kses_post(wp_unslash($_POST['sn_short_description'] ?? '')));
		$previous_product_credit = get_post_meta($post_id, '_sn_product_credit_amount', true);
		$credit_raw = class_exists('SN_Helpers') ? SN_Helpers::to_english_nums(sanitize_text_field(wp_unslash($_POST['sn_product_credit_amount'] ?? '0'))) : sanitize_text_field(wp_unslash($_POST['sn_product_credit_amount'] ?? '0'));
		$credit_raw = str_replace([',', '٬', '،', ' '], '', $credit_raw);
		update_post_meta($post_id, '_sn_product_credit_amount', max(0, (float) $credit_raw));
		update_post_meta($post_id, '_sn_operations_self_activation_allowed', isset($_POST['sn_operations_self_activation_allowed']) ? '1' : '0');
		update_post_meta($post_id, '_sn_customer_upgrade_options_visible', isset($_POST['sn_customer_upgrade_options_visible']) ? '1' : '0');
		if (isset($_POST['sn_product_star_standalone_present'])) {
			update_post_meta($post_id, '_sn_product_star_standalone_visible', isset($_POST['sn_product_star_standalone_visible']) ? '1' : '0');
		}
		if (isset($_POST['sn_project_upgrade_rules_present']) && class_exists('SN_Projects')) {
			$effective_type = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance()->product_type($post_id) : $sales_product_type;
			if ($effective_type === 'product_star') {
				$upgrade_result = SN_Projects::instance()->save_product_upgrade_rules($post_id, (array) wp_unslash($_POST['sn_project_upgrade_rules'] ?? []), get_current_user_id());
				if (is_wp_error($upgrade_result)) {
					if ($previous_product_credit === '') { delete_post_meta($post_id, '_sn_product_credit_amount'); }
					else { update_post_meta($post_id, '_sn_product_credit_amount', $previous_product_credit); }
					update_post_meta($post_id, '_sn_upgrade_rules_save_error', $upgrade_result->get_error_message());
				}
				else { delete_post_meta($post_id, '_sn_upgrade_rules_save_error'); }
			}
		}
		update_post_meta($post_id, '_sn_lottery_chance_count', max(0, absint($_POST['sn_lottery_chance_count'] ?? 0)));
		update_post_meta($post_id, '_sn_has_lucky_wheel', isset($_POST['sn_has_lucky_wheel']) ? '1' : '0');
		update_post_meta($post_id, '_sn_payment_reward_enabled', isset($_POST['sn_payment_reward_enabled']) ? '1' : '0');
		update_post_meta($post_id, '_sn_has_discount_coupon', isset($_POST['sn_has_discount_coupon']) ? '1' : '0');
		update_post_meta($post_id, '_sn_wheel_id', sanitize_key($_POST['sn_wheel_id'] ?? ''));
		update_post_meta($post_id, '_sn_paid_referral_enabled', isset($_POST['sn_paid_referral_enabled']) ? '1' : '0');
		$ref_mode = sanitize_key(wp_unslash($_POST['sn_paid_referral_mode'] ?? 'auto'));
		if (! in_array($ref_mode, ['auto', 'manual'], true)) { $ref_mode = 'auto'; }
		update_post_meta($post_id, '_sn_paid_referral_mode', $ref_mode);
		$ref_target = sanitize_key(wp_unslash($_POST['sn_paid_referral_target'] ?? 'self'));
		if (! in_array($ref_target, ['self', 'supervisor', 'senior_supervisor'], true)) { $ref_target = 'self'; }
		update_post_meta($post_id, '_sn_paid_referral_target', $ref_target);
		update_post_meta($post_id, '_sn_paid_referral_product_id', max(0, absint($_POST['sn_paid_referral_product_id'] ?? 0)));
		update_post_meta($post_id, '_sn_paid_referral_note', sanitize_textarea_field(wp_unslash($_POST['sn_paid_referral_note'] ?? '')));
	}

	// =========================================================
	// AUTH HANDLERS
	// =========================================================

	private function sn_login_identifier_variants(string $identifier): array
	{
		$identifier = trim($identifier);
		$digits = $this->sn_digits_only($identifier);
		$normalized = class_exists('SN_Helpers') ? SN_Helpers::normalize_mobile($identifier) : $digits;
		$variants = [$identifier, $digits, $normalized];
		if ($digits !== '') {
			$no_zero = ltrim($digits, '0');
			$variants[] = $no_zero;
			if (strlen($no_zero) === 10) {
				$variants[] = '0' . $no_zero;
				$variants[] = '98' . $no_zero;
				$variants[] = '+98' . $no_zero;
				$variants[] = '0098' . $no_zero;
			}
			if (strpos($digits, '98') === 0 && strlen($digits) >= 12) {
				$variants[] = '0' . substr($digits, 2);
			}
		}
		return array_values(array_filter(array_unique(array_map('trim', $variants)), static fn($v) => $v !== ''));
	}

	private function sn_add_login_match(array &$matches, $user, string $source): void
	{
		if (! $user instanceof WP_User) { return; }
		$user_id = (int) $user->ID;
		if (! isset($matches[$user_id])) {
			$matches[$user_id] = ['user' => $user, 'sources' => []];
		}
		$matches[$user_id]['sources'][] = $source;
	}

	private function sn_find_user_for_crm_login(string $identifier, array $positions = [], array $legacy_roles = [], array $caps = []): array
	{
		global $wpdb;
		$identifier = trim($identifier);
		$normalized_mobile = SN_Helpers::normalize_mobile($identifier);
		$cache_key = md5($identifier . '|' . implode(',', $positions) . '|' . implode(',', $legacy_roles) . '|' . implode(',', $caps));
		static $request_cache = [];
		if (isset($request_cache[$cache_key])) { return $request_cache[$cache_key]; }

		$matches = [];
		$variants = $this->sn_login_identifier_variants($identifier);

		foreach ($variants as $variant) {
			$this->sn_add_login_match($matches, get_user_by('login', $variant), 'user_login');
		}
		if (is_email($identifier)) {
			$this->sn_add_login_match($matches, get_user_by('email', $identifier), 'user_email');
		}

		if ($normalized_mobile !== '') {
			$meta_keys = ['billing_phone','digits_phone','digits_phone_no','mobile','phone','sn_phone','user_phone'];
			$meta_placeholders = implode(',', array_fill(0, count($meta_keys), '%s'));
			$value_placeholders = implode(',', array_fill(0, count($variants), '%s'));
			$params = array_merge($meta_keys, $variants);
			$user_ids = $wpdb->get_col($wpdb->prepare(
				"SELECT DISTINCT user_id FROM {$wpdb->usermeta} WHERE meta_key IN ($meta_placeholders) AND meta_value IN ($value_placeholders) LIMIT 30",
				...$params
			)) ?: [];
			foreach ($user_ids as $user_id) {
				$this->sn_add_login_match($matches, get_user_by('id', (int) $user_id), 'user_meta_mobile');
			}

			$profiles_table = $wpdb->prefix . 'sn_hr_profiles';
			if ($this->sn_table_exists_quiet($profiles_table)) {
				$value_placeholders = implode(',', array_fill(0, count($variants), '%s'));
				$params = array_merge($variants, $variants);
				$profile_user_ids = $wpdb->get_col($wpdb->prepare(
					"SELECT DISTINCT user_id FROM {$profiles_table} WHERE (work_phone IN ($value_placeholders) OR emergency_phone IN ($value_placeholders)) AND user_id IS NOT NULL LIMIT 30",
					...$params
				)) ?: [];
				foreach ($profile_user_ids as $user_id) {
					$this->sn_add_login_match($matches, get_user_by('id', (int) $user_id), 'hr_profile_phone');
				}
			}
		}

		if (! $matches) {
			return $request_cache[$cache_key] = ['user' => null, 'error' => 'notfound'];
		}

		$crm_matches = [];
		foreach ($matches as $user_id => $match) {
			$user = $match['user'] ?? null;
			if (! $user instanceof WP_User) { continue; }
			if ($this->sn_user_matches_crm_login_scope($user, $positions, $legacy_roles, $caps)) {
				$crm_matches[(int) $user_id] = $match;
			}
		}
		if (count($crm_matches) === 1) {
			$match = reset($crm_matches);
			return $request_cache[$cache_key] = ['user' => $match['user'], 'error' => '', 'source' => implode(',', array_unique((array) ($match['sources'] ?? []))), 'crm_preferred' => true];
		}
		if (count($crm_matches) > 1) {
			return $request_cache[$cache_key] = ['user' => null, 'error' => 'duplicate_mobile', 'matched_user_ids' => array_keys($crm_matches), 'scope' => 'crm'];
		}

		if (count($matches) === 1) {
			$match = reset($matches);
			return $request_cache[$cache_key] = ['user' => $match['user'], 'error' => '', 'source' => implode(',', array_unique((array) ($match['sources'] ?? [])))];
		}

		return $request_cache[$cache_key] = ['user' => null, 'error' => 'duplicate_mobile', 'matched_user_ids' => array_keys($matches), 'scope' => 'all'];
	}

	private function sn_user_matches_crm_login_scope(WP_User $user, array $positions = [], array $legacy_roles = [], array $caps = []): bool
	{
		$user_id = (int) $user->ID;
		if ($user_id <= 0) { return false; }
		if ($positions || $legacy_roles || $caps) {
			return $this->sn_user_has_crm_access($user_id, $positions, $legacy_roles, $caps);
		}
		return $this->sn_user_can_use_unified_login($user);
	}

	private function sn_user_has_crm_access(int $user_id, array $positions = [], array $legacy_roles = [], array $caps = []): bool
	{
		if ($user_id <= 0) { return false; }
		if (user_can($user_id, 'manage_options')) { return true; }
		foreach ($caps as $cap) {
			if ($cap !== '' && user_can($user_id, $cap)) { return true; }
		}
		if ($positions && $this->sn_user_has_hr_position($user_id, $positions)) { return true; }
		$user = get_user_by('id', $user_id);
		if ($user instanceof WP_User && array_intersect(array_map('sanitize_key', (array) $user->roles), array_map('sanitize_key', $legacy_roles))) {
			return true;
		}
		return false;
	}

	private function sn_crm_login_rate_limit(string $context, string $identifier, int $limit = 20, int $window = 900): array
	{
		$subject = trim($identifier);
		$normalized = SN_Helpers::normalize_mobile($subject);
		if ($normalized !== '' && SN_Helpers::is_valid_mobile($normalized)) {
			$subject = $normalized;
		} else {
			$subject = strtolower($subject);
		}
		// v3 عمداً در کلید محدودکننده آمده تا تلاش‌های ناموفق ناشی از باگ پردازش رمز، کاربر را قفل نکند.
		return SN_Helpers::rate_limit('crm_login_v3_' . sanitize_key($context), $subject, $limit, $window);
	}

	/**
	 * Passwords must never pass through text sanitizers: they can change valid bytes
	 * such as percent sequences, whitespace and some Unicode characters.
	 */
	private function sn_login_password_from_request(string $key = 'password'): string
	{
		$value = $_POST[$key] ?? '';
		if (is_array($value) || is_object($value)) {
			return '';
		}
		return (string) wp_unslash($value);
	}

	/**
	 * Try the exact password first. The remaining candidates only preserve
	 * compatibility with passwords saved by older plugin versions or copied from
	 * Persian SMS clients that inject bidi characters/localised digits.
	 */
	private function sn_login_password_candidates(string $password): array
	{
		$candidates = [$password];
		$without_invisible = preg_replace('/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}\x{FEFF}]/u', '', $password);
		if (is_string($without_invisible)) {
			$candidates[] = $without_invisible;
		}

		foreach (array_values($candidates) as $candidate) {
			$candidates[] = SN_Helpers::to_english_nums($candidate);
		}
		foreach (array_values($candidates) as $candidate) {
			// Legacy registration/login sanitized passwords before storing/checking them.
			$candidates[] = sanitize_text_field($candidate);
		}

		return array_values(array_unique($candidates, SORT_STRING));
	}

	private function sn_login_password_is_valid(WP_User $user, string $password): bool
	{
		foreach ($this->sn_login_password_candidates($password) as $candidate) {
			if (wp_check_password($candidate, (string) $user->user_pass, (int) $user->ID)) {
				return true;
			}
		}
		return false;
	}

	private function sn_finalize_crm_login(WP_User $user, string $password, string $auth_url, string $panel_url, array $positions = [], array $legacy_roles = [], array $caps = []): void
	{
		if (! $this->sn_user_has_crm_access((int) $user->ID, $positions, $legacy_roles, $caps)) {
			wp_safe_redirect(add_query_arg('sn_err', 'notfound', $auth_url));
			exit;
		}
		if (! $this->sn_login_password_is_valid($user, $password)) {
			wp_safe_redirect(add_query_arg('sn_err', 'wrongpass', $auth_url));
			exit;
		}
		wp_set_auth_cookie($user->ID, true);
		wp_set_current_user($user->ID);
		wp_safe_redirect($panel_url);
		exit;
	}

	public function handle_seller_login(): void
	{
		$phone    = sanitize_text_field(wp_unslash($_POST['phone'] ?? ''));
		$password = $this->sn_login_password_from_request();

		// آدرس برگشت به صفحه auth با خطا
		$auth_page_id  = (int) get_option('sn_auth_page_id', 0);
		$auth_url      = $auth_page_id ? get_permalink($auth_page_id) : home_url();
		$panel_page_id = (int) get_option('sn_seller_panel_page_id', 0);
		$panel_url     = $panel_page_id ? get_permalink($panel_page_id) : home_url();

		$limited = $this->sn_crm_login_rate_limit('seller', $phone);
		if (empty($limited['allowed'])) {
			wp_safe_redirect(add_query_arg('sn_err', 'rate_limited', $auth_url));
			exit;
		}

		if ($phone === '' || $password === '') {
			wp_redirect(add_query_arg('sn_err', 'empty', $auth_url));
			exit;
		}

		$lookup = $this->sn_find_user_for_crm_login($phone, ['seller'], ['sn_seller']);
		if (($lookup['error'] ?? '') === 'duplicate_mobile') {
			wp_safe_redirect(add_query_arg('sn_err', 'duplicate_mobile', $auth_url));
			exit;
		}
		$user = $lookup['user'] ?? null;
		if (! $user instanceof WP_User) {
			wp_safe_redirect(add_query_arg('sn_err', 'notfound', $auth_url));
			exit;
		}
		$this->sn_finalize_crm_login($user, $password, $auth_url, $panel_url, ['seller'], ['sn_seller']);
	}

