	public function handle_my_panel_login(): void
	{
		$login = sanitize_text_field(wp_unslash($_POST['phone'] ?? ''));
		$password = $this->sn_login_password_from_request();
		$redirect = esc_url_raw(wp_unslash($_POST['redirect'] ?? ''));
		$redirect = $redirect ? wp_validate_redirect($redirect, home_url('/')) : home_url('/');
		$error_redirect = static function (string $code) use ($redirect): string {
			return add_query_arg('sn_err', sanitize_key($code), $redirect);
		};

		$limited = $this->sn_crm_login_rate_limit('my_panel', $login);
		if (empty($limited['allowed'])) {
			wp_safe_redirect($error_redirect('rate_limited'));
			exit;
		}
		if ($login === '' || $password === '') {
			wp_safe_redirect($error_redirect('empty'));
			exit;
		}
		$lookup = $this->sn_find_user_for_crm_login($login);
		if (($lookup['error'] ?? '') === 'duplicate_mobile') {
			wp_safe_redirect($error_redirect('duplicate_mobile'));
			exit;
		}
		$user = $lookup['user'] ?? null;
		if (! $user instanceof WP_User) {
			wp_safe_redirect($error_redirect('notfound'));
			exit;
		}
		$position = $this->sn_hr_position_for_user((int) $user->ID);
		if ($position === '' && ! user_can($user, 'manage_options') && ! user_can($user, 'sn_view_campaign_reports') && ! array_intersect((array) $user->roles, ['sn_shipping_expert','sn_operations_sales_manager','sn_operations_sales_supervisor','sn_operations_sales_expert','sn_operations_executive_manager','sn_operations_execution_expert'])) {
			wp_safe_redirect($error_redirect('notfound'));
			exit;
		}
		if (! $this->sn_login_password_is_valid($user, $password)) {
			wp_safe_redirect($error_redirect('wrongpass'));
			exit;
		}
		wp_set_auth_cookie($user->ID, true);
		wp_set_current_user($user->ID);
		wp_safe_redirect(remove_query_arg('sn_err', $redirect));
		exit;
	}


	private function sn_resolve_panel_url_for_login_user(int $user_id): string
	{
		if ($user_id <= 0) { return home_url('/'); }
		if (user_can($user_id, 'sn_view_campaign_reports') && ! user_can($user_id, 'manage_options')) {
			$partner_url = $this->sn_portal_page_url('campaign_partner');
			if ($partner_url !== '') { return $partner_url; }
		}
		// 1.0.125: do not run the full HR panel resolver during login redirect.
		// It can traverse scope/hierarchy on busy sites and turn login into a 504.
		$position = $this->sn_fast_hr_position_for_user($user_id);
		$position_to_portal = [
			'seller' => 'seller',
			'supervisor' => 'supervisor',
			'converter' => 'converter',
			'senior_supervisor' => 'senior_supervisor',
			'sales_manager' => 'sales_manager',
			'sales_deputy' => 'sales_deputy',
			'finance' => 'finance',
			'invoice_reviewer' => 'invoice_review',
			'hr' => 'hr',
			'mis' => 'mis',
			'after_sales' => 'after_sales',
			'project_manager' => 'operations_sales_manager',
			'project_expert' => 'operations_sales_expert',
			'shipping_expert' => 'shipping',
			'operations_sales_manager' => 'operations_sales_manager',
			'operations_sales_supervisor' => 'operations_sales_supervisor',
			'operations_sales_expert' => 'operations_sales_expert',
			'operations_executive_manager' => 'operations_executive_manager',
			'operations_execution_expert' => 'operations_execution_expert',
		];
		$portal_key = $position_to_portal[$position] ?? '';
		if ($portal_key !== '') {
			$url = $this->sn_portal_page_url($portal_key);
			if ($url !== '') { return $url; }
		}
		$user = get_user_by('id', $user_id);
		$user_roles = $user instanceof WP_User ? (array) $user->roles : [];
		foreach (['sn_project_manager' => 'operations_sales_manager', 'sn_project_expert' => 'operations_sales_expert', 'sn_shipping_expert' => 'shipping', 'sn_operations_sales_manager' => 'operations_sales_manager', 'sn_operations_sales_supervisor' => 'operations_sales_supervisor', 'sn_operations_sales_expert' => 'operations_sales_expert', 'sn_operations_executive_manager' => 'operations_executive_manager', 'sn_operations_execution_expert' => 'operations_execution_expert'] as $role_key => $project_portal) {
			if (in_array($role_key, $user_roles, true)) {
				$url = $this->sn_portal_page_url($project_portal);
				if ($url !== '') { return $url; }
			}
		}
		if (user_can($user_id, 'manage_options')) {
			$hr_url = $this->sn_portal_page_url('hr');
			return $hr_url !== '' ? $hr_url : admin_url('admin.php?page=sn-settings');
		}
		$dashboard_id = (int) get_option('sn_my_panel_page_id', 0);
		if ($dashboard_id > 0) {
			$dashboard_url = (string) get_permalink($dashboard_id);
			if ($dashboard_url !== '') { return $dashboard_url; }
		}
		$login_id = (int) get_option('sn_login_page_id', 0);
		$login_url = $login_id > 0 ? (string) get_permalink($login_id) : home_url('/');
		return add_query_arg('sn_err', 'no_panel', $login_url);
	}

	private function sn_user_can_use_unified_login(WP_User $user): bool
	{
		$user_id = (int) $user->ID;
		if ($user_id <= 0) { return false; }
		if (user_can($user_id, 'manage_options')) { return true; }
		if (user_can($user_id, 'sn_view_campaign_reports')) { return true; }
		$position = $this->sn_fast_hr_position_for_user($user_id);
		if (in_array($position, ['seller','supervisor','converter','senior_supervisor','sales_manager','sales_deputy','finance','invoice_reviewer','hr','mis','after_sales','project_manager','project_expert','shipping_expert','operations_sales_manager','operations_sales_supervisor','operations_sales_expert','operations_executive_manager','operations_execution_expert'], true)) { return true; }
		$crm_roles = ['sn_seller','sas_employee','sn_supervisor','sas_supervisor','sn_converter','sn_senior_supervisor','sas_senior_supervisor','sn_sales_manager','sas_sales_manager','sn_sales_deputy','sn_financial','sn_financial_approval','sn_finance','sn_invoice_reviewer','sn_hr','sn_mis','sn_after_sales','sn_project_manager','sn_project_expert','sn_shipping_expert','sn_operations_sales_manager','sn_operations_sales_supervisor','sn_operations_sales_expert','sn_operations_executive_manager','sn_operations_execution_expert'];
		return (bool) array_intersect(array_map('sanitize_key', (array) $user->roles), $crm_roles);
	}

	public function handle_unified_login(): void
	{
		$login = sanitize_text_field(wp_unslash($_POST['phone'] ?? ''));
		$password = $this->sn_login_password_from_request();
		$login_page_id = (int) get_option('sn_login_page_id', 0);
		$login_url = $login_page_id ? (string) get_permalink($login_page_id) : home_url('/');
		$error_redirect = static function (string $code) use ($login_url): string {
			return add_query_arg('sn_err', sanitize_key($code), $login_url ?: home_url('/'));
		};

		$limited = $this->sn_crm_login_rate_limit('unified', $login);
		if (empty($limited['allowed'])) { wp_safe_redirect($error_redirect('rate_limited')); exit; }
		if ($login === '' || $password === '') { wp_safe_redirect($error_redirect('empty')); exit; }

		$lookup = $this->sn_find_user_for_crm_login($login);
		if (($lookup['error'] ?? '') === 'duplicate_mobile') { wp_safe_redirect($error_redirect('duplicate_mobile')); exit; }
		$user = $lookup['user'] ?? null;
		if (! $user instanceof WP_User) { wp_safe_redirect($error_redirect('notfound')); exit; }
		if (! $this->sn_user_can_use_unified_login($user)) { wp_safe_redirect($error_redirect('no_panel')); exit; }
		if (! $this->sn_login_password_is_valid($user, $password)) { wp_safe_redirect($error_redirect('wrongpass')); exit; }

		wp_set_auth_cookie($user->ID, true);
		wp_set_current_user($user->ID);
		wp_safe_redirect($this->sn_resolve_panel_url_for_login_user((int) $user->ID));
		exit;
	}

	public function handle_supervisor_login(): void
	{
		$phone_or_login = sanitize_text_field(wp_unslash($_POST['phone'] ?? ''));
		$normalized     = SN_Helpers::normalize_mobile($phone_or_login);
