		$panel_page_id = (int) get_option('sn_supervisor_panel_page_id', 0);
		$panel_url     = $panel_page_id ? get_permalink($panel_page_id) : home_url();

		$limited = $this->sn_crm_login_rate_limit('supervisor', $phone_or_login);
		if (empty($limited['allowed'])) {
			wp_safe_redirect(add_query_arg('sn_err', 'rate_limited', $auth_url));
			exit;
		}

		if ($phone_or_login === '' || $password === '') {
			wp_redirect(add_query_arg('sn_err', 'empty', $auth_url));
			exit;
		}

		$lookup = $this->sn_find_user_for_crm_login($phone_or_login, ['supervisor','senior_supervisor'], ['sn_supervisor']);
		if (($lookup['error'] ?? '') === 'duplicate_mobile') {
			wp_safe_redirect(add_query_arg('sn_err', 'duplicate_mobile', $auth_url));
			exit;
		}
		$user = $lookup['user'] ?? null;
		if (! $user instanceof WP_User) {
			wp_safe_redirect(add_query_arg('sn_err', 'notfound', $auth_url));
			exit;
		}
		$this->sn_finalize_crm_login($user, $password, $auth_url, $panel_url, ['supervisor','senior_supervisor'], ['sn_supervisor']);
	}
	public function handle_seller_register(): void
	{
		$phone    = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($_POST['phone'] ?? '')));
		$name     = sanitize_text_field(wp_unslash($_POST['name'] ?? ''));
		$password = $this->sn_login_password_from_request();

		$auth_page_id  = (int) get_option('sn_auth_page_id', 0);
		$auth_url      = $auth_page_id ? get_permalink($auth_page_id) : home_url();
		$panel_page_id = (int) get_option('sn_seller_panel_page_id', 0);
		$panel_url     = $panel_page_id ? get_permalink($panel_page_id) : home_url();

		$limited = $this->sn_crm_login_rate_limit('seller_register', $phone, 8, HOUR_IN_SECONDS);
		if (empty($limited['allowed'])) {
			wp_safe_redirect(add_query_arg('sn_err', 'rate_limited', $auth_url));
			exit;
		}

		if (! SN_Helpers::is_valid_mobile($phone) || empty($name) || strlen($password) < 6) {
			wp_redirect(add_query_arg('sn_err', 'invalid', $auth_url));
			exit;
		}

		if (username_exists($phone)) {
			wp_redirect(add_query_arg('sn_err', 'exists', $auth_url));
			exit;
		}

		$user_id = wp_create_user($phone, $password, $phone . '@sn.local');
		if (is_wp_error($user_id)) {
			wp_redirect(add_query_arg('sn_err', 'create', $auth_url));
			exit;
		}

		$new_user = new WP_User($user_id);
		$new_user->set_role('sn_seller');
		wp_update_user(['ID' => $user_id, 'display_name' => $name, 'first_name' => $name]);

		wp_set_auth_cookie($user_id, true);
		wp_set_current_user($user_id);

		// redirect صریح به پنل فروشنده
		wp_redirect($panel_url);
		exit;
	}


	/**
	 * سرپرست و فروشنده فقط باید از پنل اختصاصی خودشان استفاده کنند.
	 * این متد دسترسی مستقیم به wp-admin را می‌بندد، ولی admin-ajax/admin-post را برای فرم‌ها و AJAXها آزاد می‌گذارد.
	 */
	public function block_front_roles_admin_access(): void
	{
		if (! is_user_logged_in()) {
			return;
		}
		if (wp_doing_ajax() || (defined('DOING_AJAX') && DOING_AJAX)) {
			return;
		}
		if (defined('DOING_CRON') && DOING_CRON) {
			return;
		}

		$script = basename($_SERVER['PHP_SELF'] ?? '');
		if (in_array($script, ['admin-ajax.php', 'admin-post.php'], true)) {
			return;
		}
		if (isset($_GET['sn_export']) && current_user_can('sn_export_sales_reports')) {
			return;
		}
		if ($script === 'admin.php' && sanitize_key(wp_unslash($_GET['page'] ?? '')) === 'sn-wallets' && current_user_can('sn_view_wallet_commission')) {
			return;
		}

		$user  = wp_get_current_user();
		$roles = (array) $user->roles;

		// ادمین واقعی نباید قفل شود؛ اما نقش‌های اختصاصی بدون capability مدیریتی وارد پیشخوان نمی‌شوند.
		if (current_user_can('manage_options')) {
			return;
		}

		$resolved_panel_url = $this->sn_get_user_panel_url((int) $user->ID);
		if ($resolved_panel_url !== '') {
			wp_safe_redirect($resolved_panel_url);
			exit;
		}

		$target_page_id = 0;
		if (in_array('sn_supervisor', $roles, true)) {
			$target_page_id = (int) get_option('sn_supervisor_panel_page_id', 0);
		} elseif (in_array('sn_sales_manager', $roles, true)) {
			$target_page_id = (int) get_option('sn_sales_manager_panel_page_id', 0);
		} elseif (in_array('sn_seller', $roles, true)) {
			$target_page_id = (int) get_option('sn_seller_panel_page_id', 0);
		} elseif (in_array('sn_after_sales', $roles, true)) {
			$target_page_id = (int) get_option('sn_after_sales_panel_page_id', 0);
		} elseif (in_array('sn_campaign_partner', $roles, true)) {
			$target_page_id = (int) get_option('sn_campaign_partner_page_id', 0);
		} elseif (in_array('sn_project_manager', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_sales_manager_panel_page_id', 0);
		} elseif (in_array('sn_project_expert', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_sales_expert_panel_page_id', 0);
		} elseif (in_array('sn_shipping_expert', $roles, true)) {
			$target_page_id = (int) get_option('sn_shipping_panel_page_id', 0);
		} elseif (in_array('sn_operations_sales_manager', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_sales_manager_panel_page_id', 0);
		} elseif (in_array('sn_operations_sales_supervisor', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_sales_supervisor_panel_page_id', 0);
		} elseif (in_array('sn_operations_sales_expert', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_sales_expert_panel_page_id', 0);
		} elseif (in_array('sn_operations_executive_manager', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_executive_manager_panel_page_id', 0);
		} elseif (in_array('sn_operations_execution_expert', $roles, true)) {
			$target_page_id = (int) get_option('sn_operations_execution_expert_panel_page_id', 0);
		}
		if (! $target_page_id) {
			return;
		}
		$target_url = get_permalink($target_page_id);
		if (! $target_url) {
			$target_url = home_url('/');
		}

		wp_safe_redirect($target_url);
		exit;
	}

	/** حذف admin bar برای سرپرست‌ها و فروشنده‌ها در فرانت */
	public function hide_front_roles_admin_bar(): void
	{
		if (! is_user_logged_in()) {
			return;
		}
		$user  = wp_get_current_user();
		$roles = (array) $user->roles;
