		if (array_intersect($roles, ['sn_supervisor','sn_senior_supervisor','sn_sales_deputy','sn_seller','sn_converter','sn_hr','sn_mis','sn_finance','sn_invoice_reviewer','sn_financial','sn_financial_approval','sn_after_sales','sn_sales_manager','sn_campaign_partner','sn_project_manager','sn_project_expert','sn_shipping_expert','sn_operations_sales_manager','sn_operations_sales_supervisor','sn_operations_sales_expert','sn_operations_executive_manager','sn_operations_execution_expert'])) {
			show_admin_bar(false);
		}
	}

	/**
	 * نقش‌های فرانت را سخت‌گیرانه نگه می‌دارد؛ اگر در نسخه‌های قبلی capability اضافه شده باشد پاک می‌شود.
	 */
	public function harden_front_roles_caps(): void
	{
		if ((string) get_option('sn_roles_hardened_version', '') === SN_VERSION) { return; }
		if ($this->sn_defer_heavy_admin_runtime()) { return; }
		$role_specs = [
			'sn_supervisor' => ['سرپرست فروش', []], 'sn_senior_supervisor' => ['سرپرست ارشد فروش', []],
			'sn_sales_deputy' => ['معاون فروش', []], 'sn_seller' => ['فروشنده', []],
			'sn_converter' => ['تبدیل‌کننده', ['sn_manage_dot_conversion']],
			'sn_invoice_reviewer' => ['بررسی فاکتور', ['sn_review_invoices']],
			'sn_hr' => ['منابع انسانی', []], 'sn_mis' => ['MIS', []], 'sn_finance' => ['مالی', []],
			'sn_after_sales' => ['خدمات پس از فروش', ['sn_view_customer_profiles']],
			'sn_sales_manager' => ['مدیر فروش', ['sn_view_sales_reports', 'sn_manage_supervisor_leads', 'sn_export_sales_reports']],
			'sn_campaign_partner' => ['پارتنر کمپین', ['sn_view_campaign_reports']],
			'sn_shipping_expert' => ['کارشناس ارسال', ['sn_manage_shipping']],
			'sn_operations_sales_manager' => ['مدیر فروش عملیات', ['sn_manage_operations_sales']],
			'sn_operations_sales_supervisor' => ['سرپرست فروش عملیات', ['sn_supervise_operations_sales']],
			'sn_operations_sales_expert' => ['کارشناس فروش عملیات', ['sn_work_operations_sales']],
			'sn_operations_executive_manager' => ['مدیر اجرایی عملیات', ['sn_manage_operations_execution']],
			'sn_operations_execution_expert' => ['کارشناس اجرایی عملیات', ['sn_work_operations_execution']],
		];
		foreach ($role_specs as $role_key => $role_spec) {
			$role_label = (string) ($role_spec[0] ?? $role_key);
			$role_caps = array_fill_keys(array_merge(['read'], (array) ($role_spec[1] ?? [])), true);
			if (! get_role($role_key)) {
				add_role($role_key, $role_label, $role_caps);
			}
			$role = get_role($role_key);
			if (! $role) {
				continue;
			}
			foreach (array_keys($role_caps) as $role_cap) { $role->add_cap($role_cap); }
			foreach (['edit_posts', 'delete_posts', 'publish_posts', 'upload_files', 'edit_pages', 'delete_pages', 'manage_options', 'list_users', 'create_users', 'edit_users', 'delete_users'] as $cap) {
				$role->remove_cap($cap);
			}
		}
		update_option('sn_roles_hardened_version', SN_VERSION, false);
	}

	// جلوگیری از redirect به wp-admin برای فروشندگان
	public function ajax_toggle_seller_active(): void
	{
		if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
			SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
			return;
		}
		$user      = wp_get_current_user();
		$seller_id = absint($_POST['seller_id'] ?? 0);
		if (! $seller_id) {
			SN_Helpers::send_json(false, 'شناسه نامعتبر');
			return;
		}

		$actor_position = $this->sn_hr_position_for_user((int) $user->ID);
		$can_manage = current_user_can('manage_options') || in_array('sn_hr', (array) $user->roles, true) || $actor_position === 'hr';
		if (! $can_manage) {
			SN_Helpers::send_json(false, 'فعال/غیرفعال‌کردن فروشنده فقط از منابع انسانی مجاز است.');
			return;
		}

		$current = get_user_meta($seller_id, 'sn_is_active', true);
		$new_val = ($current === '0') ? '1' : '0';
		update_user_meta($seller_id, 'sn_is_active', $new_val);

		// فروشنده‌های جدید ممکن است WP role فروشنده نداشته باشند؛ وضعیت عملیاتی باید با HR profile هم هم‌سو شود.
		global $wpdb;
		if ($this->sn_mis_table_exists('sn_hr_profiles')) {
			$hr_profile_table = $wpdb->prefix . 'sn_hr_profiles';
			$old_hr_profile = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$hr_profile_table} WHERE user_id=%d", $seller_id), ARRAY_A);
			$wpdb->update(
				$wpdb->prefix . 'sn_hr_profiles',
				[
					'is_active' => $new_val === '1' ? 1 : 0,
					'employment_status' => $new_val === '1' ? 'active' : 'inactive',
					'updated_at' => current_time('mysql'),
				],
				['user_id' => $seller_id],
				['%d', '%s', '%s'],
				['%d']
			);
			if ($old_hr_profile) {
				$new_hr_profile = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$hr_profile_table} WHERE user_id=%d", $seller_id), ARRAY_A);
				$this->sn_hr_panel_log_profile((int) ($old_hr_profile['id'] ?? 0), $seller_id, $new_val === '1' ? 'seller_reactivated_by_supervisor' : 'seller_deactivated_by_supervisor', $old_hr_profile, $new_hr_profile ?: null, ['actor_user_id' => (int) $user->ID, 'source' => 'supervisor_panel']);
			}
		}
		$this->sn_log_activity(null, null, $new_val === '1' ? 'seller_reactivated_by_supervisor' : 'seller_deactivated_by_supervisor', $new_val === '1' ? 'فعال‌سازی فروشنده توسط سرپرست/مدیر' : 'غیرفعال‌سازی فروشنده توسط سرپرست/مدیر', [
			'seller_id' => $seller_id,
			'actor_id' => (int) $user->ID,
			'source' => 'supervisor_panel',
		]);
		SN_Helpers::send_json(true, $new_val === '1' ? 'فروشنده فعال شد' : 'فروشنده غیرفعال شد', ['is_active' => $new_val === '1']);
	}

	public function seller_login_redirect(string $redirect_to, string $requested, $user): string
	{
		if (is_wp_error($user) || ! $user) {
			return $redirect_to;
		}
		$resolved_panel_url = $this->sn_get_user_panel_url((int) $user->ID);
		if ($resolved_panel_url !== '') { return $resolved_panel_url; }
		if (in_array('sn_seller', (array) $user->roles, true)) {
			$panel_id = (int) get_option('sn_seller_panel_page_id', 0);
			return $panel_id ? get_permalink($panel_id) : home_url();
		}
		if (in_array('sn_supervisor', (array) $user->roles, true)) {
			$panel_id = (int) get_option('sn_supervisor_panel_page_id', 0);
			return $panel_id ? get_permalink($panel_id) : home_url();
		}
		if (in_array('sn_sales_manager', (array) $user->roles, true)) {
			$panel_id = (int) get_option('sn_sales_manager_panel_page_id', 0);
			return $panel_id ? get_permalink($panel_id) : home_url();
		}
		return $redirect_to;
	}

	// ریدایرکت بعد از لاگین wp-login برای نقش‌های فرانت
	public function block_seller_admin_access(string $user_login, WP_User $user): void
	{
		if (wp_doing_ajax() || current_user_can('manage_options')) {
			return;
		}
		$resolved_panel_url = $this->sn_get_user_panel_url((int) $user->ID);
		if ($resolved_panel_url !== '') { wp_safe_redirect($resolved_panel_url); exit; }
		$roles = (array) $user->roles;
		$panel_id = 0;
		if (in_array('sn_supervisor', $roles, true)) {
			$panel_id = (int) get_option('sn_supervisor_panel_page_id', 0);
		} elseif (in_array('sn_sales_manager', $roles, true)) {
			$panel_id = (int) get_option('sn_sales_manager_panel_page_id', 0);
		} elseif (in_array('sn_seller', $roles, true)) {
			$panel_id = (int) get_option('sn_seller_panel_page_id', 0);
		}
		if (! $panel_id) {
			return;
		}
		$url = get_permalink($panel_id) ?: home_url('/');
		wp_safe_redirect($url);
		exit;
	}

