	private function sn_staff_view_data(): array
	{
		$token = isset($_COOKIE['sn_staff_view']) && is_string($_COOKIE['sn_staff_view']) ? (string) wp_unslash($_COOKIE['sn_staff_view']) : '';
		if (! preg_match('/^[a-f0-9]{64}$/', $token)) { return []; }
		$data = get_transient('sn_staff_view_' . hash('sha256', $token));
		return is_array($data) && (int) ($data['target'] ?? 0) === get_current_user_id() ? $data : [];
	}

	private function sn_staff_view_cookie(string $token, int $expires): void
	{
		setcookie('sn_staff_view', $token, [
			'expires' => $expires, 'path' => defined('COOKIEPATH') && COOKIEPATH ? COOKIEPATH : '/',
			'secure' => is_ssl(), 'httponly' => true, 'samesite' => 'Lax',
		]);
	}

	public function sn_clear_staff_view_cookie(): void
	{
		$data = $this->sn_staff_view_data();
		if ($data && isset($_COOKIE['sn_staff_view'])) {
			delete_transient('sn_staff_view_' . hash('sha256', (string) wp_unslash($_COOKIE['sn_staff_view'])));
		}
		$this->sn_staff_view_cookie('', time() - HOUR_IN_SECONDS);
	}

	public function handle_hr_view_staff_panel(): void
	{
		if (! $this->sn_can_manage_hr_panel() || $this->sn_staff_view_data()) { wp_die('دسترسی غیرمجاز'); }
		$target_id = absint($_POST['user_id'] ?? 0);
		check_admin_referer('sn_hr_view_staff_panel_' . $target_id);
		$target = get_user_by('id', $target_id);
		if (! $target || $target_id === get_current_user_id() || user_can($target, 'manage_options')
			|| ! $this->sn_hr_is_internal_user_id($target_id) || ! class_exists('SN_HR_Service')) {
			wp_die('پنل این نیرو در دسترس نیست.');
		}
		$resolved = (new SN_HR_Service())->resolve_panel_for_user($target_id);
		$url = $this->sn_resolved_panel_portal_url($resolved);
		if ($url === '' || (string) ($resolved['route_type'] ?? '') === 'placeholder') { wp_die('پنل این نیرو در دسترس نیست.'); }
		$token = bin2hex(random_bytes(32));
		set_transient('sn_staff_view_' . hash('sha256', $token), [
			'actor' => get_current_user_id(), 'target' => $target_id,
		], 30 * MINUTE_IN_SECONDS);
		$this->sn_staff_view_cookie($token, time() + 30 * MINUTE_IN_SECONDS);
		wp_clear_auth_cookie();
		wp_set_current_user($target_id);
		wp_set_auth_cookie($target_id, false, is_ssl());
		wp_safe_redirect($url);
		exit;
	}

	public function handle_hr_return_from_staff(): void
	{
		check_admin_referer('sn_hr_return_from_staff');
		$data = $this->sn_staff_view_data();
		if (! $data) { wp_die('زمان مشاهده پنل به پایان رسیده است.'); }
		$actor = get_user_by('id', (int) $data['actor']);
		if (! $actor) { wp_die('حساب منابع انسانی در دسترس نیست.'); }
		$this->sn_clear_staff_view_cookie();
		wp_clear_auth_cookie();
		wp_set_current_user((int) $actor->ID);
		wp_set_auth_cookie((int) $actor->ID, false, is_ssl());
		$url = $this->sn_portal_page_url('hr');
		wp_safe_redirect($url !== '' ? $url : home_url('/'));
		exit;
	}

