	public function sn_render_other_panel_password_link(): void
	{
		if (! is_user_logged_in() || ! is_singular()) { return; }
		$post = get_post();
		if (! $post instanceof WP_Post) { return; }
		$tags = ['sn_dot_converter_panel', 'sn_shipping_panel', 'sn_operations_sales_manager_panel', 'sn_operations_sales_supervisor_panel', 'sn_operations_sales_expert_panel', 'sn_operations_executive_manager_panel', 'sn_operations_execution_expert_panel', 'sn_project_manager_panel', 'sn_project_expert_panel'];
		$found = false;
		$elementor_data = (string) get_post_meta((int) $post->ID, '_elementor_data', true);
		// These Operations panels render the same account actions in their header.
		foreach (['sn_operations_sales_manager_panel','sn_operations_sales_supervisor_panel'] as $header_tag) {
			if (has_shortcode((string)$post->post_content,$header_tag) || strpos($elementor_data,$header_tag)!==false) { return; }
		}
		foreach ($tags as $tag) {
			if (has_shortcode((string) $post->post_content, $tag) || strpos($elementor_data, $tag) !== false) { $found = true; break; }
		}
		if (! $found) { return; }
		$page_id = (int) get_option('sn_my_password_page_id', 0);
		$url = $page_id ? get_permalink($page_id) : '';
		if (! $url) { return; }
		?>
		<div class="sn-panel-user-actions" dir="rtl" style="position:fixed;bottom:16px;left:16px;z-index:9999;background:#fff;padding:8px;border-radius:8px;box-shadow:0 2px 12px #0002">
			<a class="sn-btn sn-btn-sm sn-btn-secondary" href="<?php echo esc_url($url); ?>">رمز من</a>
			<?php if ($this->sn_staff_view_data()) : ?>
			<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="sn_hr_return_from_staff"><?php wp_nonce_field('sn_hr_return_from_staff'); ?><button class="sn-btn sn-btn-sm sn-btn-primary" type="submit">بازگشت به پنل HR</button></form>
			<?php endif; ?>
		</div>
		<?php
	}

	public function handle_change_own_password(): void
	{
		if (! is_user_logged_in()) { wp_die('ابتدا وارد شوید.'); }
		check_admin_referer('sn_change_own_password');
		$user = wp_get_current_user();
		$old = is_string($_POST['old_password'] ?? null) ? (string) wp_unslash($_POST['old_password']) : '';
		$new = is_string($_POST['new_password'] ?? null) ? (string) wp_unslash($_POST['new_password']) : '';
		$repeat = is_string($_POST['repeat_password'] ?? null) ? (string) wp_unslash($_POST['repeat_password']) : '';
		$status = 'invalid';
		if ($old !== '' && $new !== '' && strlen($new) >= 8 && hash_equals($new, $repeat)) {
			if (! wp_check_password($old, (string) $user->user_pass, (int) $user->ID)) {
				$status = 'wrong';
			} else {
				wp_set_password($new, (int) $user->ID);
				wp_clear_auth_cookie();
				wp_set_auth_cookie((int) $user->ID, false, is_ssl());
				$status = 'saved';
			}
		}
		$url = (int) get_option('sn_my_password_page_id', 0) ? get_permalink((int) get_option('sn_my_password_page_id')) : home_url('/');
		wp_safe_redirect(add_query_arg('sn_password_status', $status, $url));
		exit;
	}

