	private function export_sellers_csv(): void
	{
		$sellers = $this->sn_admin_hr_people_by_positions(['seller'], 5000);
		if (empty($sellers)) {
			foreach (get_users(['role' => 'sn_seller', 'number' => 5000]) as $u) {
				$sellers[] = ['user_id' => (int) $u->ID, 'display_name' => $u->display_name, 'user_login' => $u->user_login, 'parent_name' => '', 'parent_position_label' => '', 'is_active' => 1, 'employment_status' => 'active'];
			}
		}
		$user_ids = array_values(array_unique(array_filter(array_map('intval', array_column($sellers, 'user_id')))));
		$legacy_leads = $this->sn_admin_group_count_by_user('sn_leads', 'seller_id', $user_ids);
		$active_dist = str_replace('di.', '', $this->sn_admin_distribution_active_condition('di'));
		$owned_distribution = $this->sn_admin_group_count_by_user('sn_distribution_items', 'current_owner_user_id', $user_ids, $active_dist);
		$final_distribution = $this->sn_admin_group_count_by_user('sn_distribution_items', 'final_seller_user_id', $user_ids);
		$invoice_metrics = $this->sn_admin_invoice_metrics_by_seller($user_ids);
		$wallets = $this->sn_admin_wallet_map($user_ids);
		$this->sn_csv_header('sales-network-sellers-' . SN_Helpers::tehran_format('Y-m-d') . '.csv');
		$out = fopen('php://output', 'w');
		fputcsv($out, ['ID', 'نام', 'شماره/نام کاربری', 'بالادستی HR', 'وضعیت HR', 'آیتم در پنل فروشنده', 'تحویل نهایی', 'لید زنده', 'تعداد فاکتور', 'فاکتور تایید/پرداخت', 'فروش تاییدشده', 'موجودی کیف پول']);
		foreach ($sellers as $s) {
			$uid = (int) ($s['user_id'] ?? 0);
			$im = $invoice_metrics[$uid] ?? ['invoice_count' => 0, 'paid_count' => 0, 'paid_revenue' => 0];
			$wallet = $wallets[$uid]['seller'] ?? [];
			$parent = trim((string) (($s['parent_name'] ?? '') . (! empty($s['parent_position_label']) ? ' - ' . $s['parent_position_label'] : '')));
			fputcsv($out, [$uid, $s['display_name'] ?? '', $s['user_login'] ?? '', $parent, ($s['is_active'] ?? 0) ? ($s['employment_status'] ?? 'active') : 'inactive', (int) ($owned_distribution[$uid] ?? 0), (int) ($final_distribution[$uid] ?? 0), (int) ($legacy_leads[$uid] ?? 0), (int) ($im['invoice_count'] ?? 0), (int) ($im['paid_count'] ?? 0), (float) ($im['paid_revenue'] ?? 0), (float) ($wallet['balance'] ?? 0)]);
		}
		exit;
	}


