	private function get_lead_filters(): array
	{
		return ['search' => sanitize_text_field(wp_unslash($_GET['sn_search'] ?? '')), 'status' => sanitize_text_field(wp_unslash($_GET['sn_status'] ?? 'all')), 'lead_status' => sanitize_text_field(wp_unslash($_GET['sn_lead_status'] ?? '')), 'seller_id' => absint($_GET['sn_seller_id'] ?? 0), 'supervisor_id' => absint($_GET['sn_supervisor_id'] ?? 0), 'import_code' => sanitize_text_field(wp_unslash($_GET['sn_import_code'] ?? '')), 'date_from' => sanitize_text_field(wp_unslash($_GET['sn_date_from'] ?? '')), 'date_to' => sanitize_text_field(wp_unslash($_GET['sn_date_to'] ?? '')), 'time_from' => sanitize_text_field(wp_unslash($_GET['sn_time_from'] ?? '')), 'time_to' => sanitize_text_field(wp_unslash($_GET['sn_time_to'] ?? ''))];
	}

	private function get_sales_manager_filters(array $source): array
	{
		$value = static function (array $source, string $key, string $fallback = '') {
			$sn_key = 'sn_' . $key;
			if (isset($source[$key])) {
				return sanitize_text_field(wp_unslash($source[$key]));
			}
			if (isset($source[$sn_key])) {
				return sanitize_text_field(wp_unslash($source[$sn_key]));
			}
			return $fallback;
		};
		return [
			'search' => $value($source, 'search'),
			'status' => $value($source, 'status', 'all'),
			'assignment' => $value($source, 'assignment', 'all'),
			'lead_status' => $value($source, 'lead_status'),
			'seller_id' => absint($source['seller_id'] ?? $source['sn_seller_id'] ?? 0),
			'supervisor_id' => absint($source['supervisor_id'] ?? $source['sn_supervisor_id'] ?? 0),
			'import_code' => $value($source, 'import_code'),
			'date_from' => $value($source, 'date_from'),
			'date_to' => $value($source, 'date_to'),
			'time_from' => $value($source, 'time_from'),
			'time_to' => $value($source, 'time_to'),
		];
	}

	private function build_sales_manager_leads_where(array $f): array
	{
		global $wpdb;
		$where = ['1=1'];
		$args = [];
		$statuses = ['unassigned', 'supervisor_pool', 'assigned', 'invoiced'];
		$assignments = ['all', 'unassigned', 'supervisor_pool', 'assigned'];

		if ($f['search'] !== '') {
			$where[] = '(phone LIKE %s OR province LIKE %s OR city LIKE %s OR note LIKE %s OR import_code LIKE %s)';
			$like = '%' . $wpdb->esc_like($f['search']) . '%';
			array_push($args, $like, $like, $like, $like, $like);
		}
		if ($f['import_code'] !== '') {
			$where[] = 'import_code = %s';
			$args[] = $f['import_code'];
		}
		if (in_array($f['status'], $statuses, true)) {
			$where[] = 'status = %s';
			$args[] = $f['status'];
		}
		if ($f['lead_status'] !== '') {
			$where[] = 'lead_status = %s';
			$args[] = $f['lead_status'];
		}
		if ($f['seller_id']) {
			$where[] = 'seller_id = %d';
			$args[] = $f['seller_id'];
		}
		if ($f['supervisor_id']) {
			$where[] = 'supervisor_id = %d';
			$args[] = $f['supervisor_id'];
		}
		if (in_array($f['assignment'], $assignments, true)) {
			if ($f['assignment'] === 'unassigned') {
				$where[] = "status = 'unassigned' AND seller_id IS NULL AND supervisor_id IS NULL";
			} elseif ($f['assignment'] === 'supervisor_pool') {
				$where[] = "status = 'supervisor_pool' AND seller_id IS NULL AND supervisor_id IS NOT NULL";
			} elseif ($f['assignment'] === 'assigned') {
				$where[] = 'seller_id IS NOT NULL';
			}
		}
		$date_from = SN_Helpers::jalali_to_gregorian_date((string) $f['date_from']);
		$date_to = SN_Helpers::jalali_to_gregorian_date((string) $f['date_to']);
		if ($date_from) {
			$where[] = 'DATE(imported_at) >= %s';
			$args[] = $date_from;
		}
		if ($date_to) {
			$where[] = 'DATE(imported_at) <= %s';
			$args[] = $date_to;
		}
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_from'])) {
			$where[] = 'TIME(imported_at) >= %s';
			$args[] = $f['time_from'] . ':00';
		}
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_to'])) {
			$where[] = 'TIME(imported_at) <= %s';
			$args[] = $f['time_to'] . ':59';
		}
		return [implode(' AND ', $where), $args];
	}

	private function export_sales_manager_leads_csv(array $filters): void
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_leads';
		[$where, $args] = $this->build_sales_manager_leads_where($filters);
		$scope_decision = $this->sn_scope_decision('sales_manager_reports_readonly', get_current_user_id());
		if (! current_user_can('manage_options')) {
			$scope_seller_ids = $this->sn_get_seller_ids_in_hr_scope(get_current_user_id());
			if ($scope_seller_ids) {
				$where .= ' AND seller_id IN (' . implode(',', array_fill(0, count($scope_seller_ids), '%d')) . ')';
				$args = array_merge($args, $scope_seller_ids);
			} else {
				$where .= ' AND 1=0';
			}
		}
		$sql = "SELECT id, phone, import_code, province, city, status, lead_status, supervisor_id, seller_id, imported_at, assigned_at FROM {$table} WHERE {$where} ORDER BY imported_at DESC, id DESC LIMIT 5000";
		$rows = $args ? $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) : $wpdb->get_results($sql, ARRAY_A);
		header('Content-Type: text/csv; charset=utf-8');
		header('Content-Disposition: attachment; filename=sales-manager-leads-' . SN_Helpers::tehran_format('Ymd-His') . '.csv');
		$out = fopen('php://output', 'w');
		fprintf($out, chr(0xEF) . chr(0xBB) . chr(0xBF));
		fputcsv($out, ['ID', 'Phone', 'Import Code', 'Province', 'City', 'Status', 'Lead Status', 'Supervisor', 'Seller', 'Imported At', 'Assigned At']);
		foreach ($rows as $row) {
			$supervisor = ! empty($row['supervisor_id']) ? get_user_by('id', (int) $row['supervisor_id']) : null;
			$seller = ! empty($row['seller_id']) ? get_user_by('id', (int) $row['seller_id']) : null;
			fputcsv($out, [
				$row['id'],
				$row['phone'],
				$row['import_code'] ?? '',
				$row['province'],
				$row['city'],
				SN_Helpers::status_label((string) $row['status']),
				$row['lead_status'] ?: '—',
				$supervisor ? $supervisor->display_name : '—',
				$seller ? $seller->display_name : '—',
				SN_Helpers::gregorian_to_jalali_date($row['imported_at']),
				SN_Helpers::gregorian_to_jalali_date($row['assigned_at']),
			]);
		}
		exit;
	}

	private function build_leads_where(array $f): array
	{
		$where = ['1=1'];
		$args = [];
		if ($f['search'] !== '') {
			$where[] = '(phone LIKE %s OR province LIKE %s OR city LIKE %s OR note LIKE %s OR import_code LIKE %s)';
			$like = '%' . $GLOBALS['wpdb']->esc_like($f['search']) . '%';
			array_push($args, $like, $like, $like, $like, $like);
		}
		if (! empty($f['import_code'])) {
			$where[] = 'import_code = %s';
			$args[] = $f['import_code'];
		}
		if ($f['status'] !== '' && $f['status'] !== 'all') {
			$where[] = 'status = %s';
			$args[] = $f['status'];
		}
		if ($f['lead_status'] !== '') {
			$where[] = 'lead_status = %s';
			$args[] = $f['lead_status'];
		}
		if ($f['seller_id']) {
			$where[] = 'seller_id = %d';
			$args[] = $f['seller_id'];
		}
		if ($f['supervisor_id']) {
			$where[] = 'supervisor_id = %d';
			$args[] = $f['supervisor_id'];
		}
		$date_from = SN_Helpers::jalali_to_gregorian_date((string) $f['date_from']);
		$date_to = SN_Helpers::jalali_to_gregorian_date((string) $f['date_to']);
		if ($date_from) {
			$where[] = 'DATE(assigned_at) >= %s';
			$args[] = $date_from;
		}
		if ($date_to) {
			$where[] = 'DATE(assigned_at) <= %s';
			$args[] = $date_to;
		}
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_from'])) {
			$where[] = 'TIME(assigned_at) >= %s';
			$args[] = $f['time_from'] . ':00';
		}
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_to'])) {
			$where[] = 'TIME(assigned_at) <= %s';
			$args[] = $f['time_to'] . ':59';
		}
		return [implode(' AND ', $where), $args];
	}

	private function get_invoice_filters(): array
	{
		return [
			'status' => sanitize_text_field(wp_unslash($_GET['sn_status'] ?? 'all')),
			'search' => sanitize_text_field(wp_unslash($_GET['sn_search'] ?? '')),
			'sales_manager_ids' => $this->sn_admin_request_id_list('sn_sales_manager_ids', 'sn_sales_manager_id'),
			'senior_supervisor_ids' => $this->sn_admin_request_id_list('sn_senior_supervisor_ids', 'sn_senior_supervisor_id'),
			'supervisor_ids' => $this->sn_admin_request_id_list('sn_supervisor_ids', 'sn_supervisor_id'),
			'seller_ids' => $this->sn_admin_request_id_list('sn_seller_ids', 'sn_seller_id'),
			'supervisor_id' => absint($_GET['sn_supervisor_id'] ?? 0),
			'seller_id' => absint($_GET['sn_seller_id'] ?? 0),
			'date_from' => sanitize_text_field(wp_unslash($_GET['sn_date_from'] ?? '')),
			'date_to' => sanitize_text_field(wp_unslash($_GET['sn_date_to'] ?? '')),
			'time_from' => sanitize_text_field(wp_unslash($_GET['sn_time_from'] ?? '')),
			'time_to' => sanitize_text_field(wp_unslash($_GET['sn_time_to'] ?? '')),
		];
	}

	private function sn_admin_request_id_list(string $multi_key, string $single_key = ''): array
	{
		$raw = $_GET[$multi_key] ?? [];
		if (! is_array($raw)) { $raw = [$raw]; }
		if ($single_key !== '' && isset($_GET[$single_key]) && ! is_array($_GET[$single_key])) { $raw[] = $_GET[$single_key]; }
		return array_values(array_unique(array_filter(array_map('absint', array_map('wp_unslash', $raw)))));
	}

	private function sn_admin_invoice_user_options(array $positions, array $legacy_roles = []): array
	{
		$items = [];
		foreach ($positions as $position) {
			foreach ($this->sn_hr_all_users_by_position((string) $position) as $row) {
				$user_id = (int) ($row['user_id'] ?? 0);
				if ($user_id < 1) { continue; }
				$label = trim((string) ($row['display_name'] ?? '')) ?: ('#' . $user_id);
				$items[$user_id] = (object) ['ID' => $user_id, 'display_name' => $label, 'user_login' => (string) ($row['user_login'] ?? '')];
			}
		}
		foreach ($legacy_roles as $role) {
			foreach (get_users(['role' => (string) $role, 'number' => 3000]) as $user) {
				$user_id = (int) $user->ID;
				$items[$user_id] = (object) ['ID' => $user_id, 'display_name' => trim((string) $user->display_name) ?: ('#' . $user_id), 'user_login' => (string) $user->user_login];
			}
		}
		usort($items, static fn($a, $b) => strnatcasecmp((string) $a->display_name, (string) $b->display_name));
		return $items;
	}

	private function sn_admin_invoice_seller_ids_for_role_users(array $user_ids): array
	{
		$user_ids = array_values(array_unique(array_filter(array_map('intval', $user_ids))));
		if (! $user_ids) { return []; }
		$ids = [];
		foreach ($user_ids as $uid) {
			if ($this->sn_hr_position_for_user((int) $uid) === 'seller') { $ids[] = (int) $uid; }
			$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_direct_children((int) $uid, 'seller'), 'user_id')));
			$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_descendant_users((int) $uid, 'seller'), 'user_id')));
		}
		return array_values(array_unique(array_filter($ids)));
	}

	private function sn_admin_invoice_selected_scope_seller_ids(array $f): array
	{
		$scope_sets = [];
		foreach (['sales_manager_ids','senior_supervisor_ids','supervisor_ids'] as $key) {
			$ids = $this->sn_admin_invoice_seller_ids_for_role_users((array) ($f[$key] ?? []));
			if (! empty($f[$key])) { $scope_sets[] = $ids; }
		}
		if (! empty($f['seller_ids'])) { $scope_sets[] = array_values(array_unique(array_filter(array_map('intval', (array) $f['seller_ids'])))); }
		if (! $scope_sets) { return []; }
		$current = array_shift($scope_sets);
		foreach ($scope_sets as $set) { $current = array_values(array_intersect($current, $set)); }
		return array_values(array_unique(array_filter(array_map('intval', $current))));
	}

	private function sn_admin_invoice_owner_where_for_user_ids(array $user_ids, string $alias = ''): array
	{
		$user_ids = array_values(array_unique(array_filter(array_map('intval', $user_ids))));
		if (! $user_ids) { return ['0=1', []]; }
		$owner_fields = method_exists($this, 'sn_invoice_owner_fields') ? $this->sn_invoice_owner_fields() : ['seller_id'];
		if (! $owner_fields) { $owner_fields = ['seller_id']; }
		$parts = [];
		$args = [];
		$prefix = $alias !== '' ? rtrim($alias, '.') . '.' : '';
		foreach ($owner_fields as $field) {
			$parts[] = $prefix . $field . ' IN (' . implode(',', array_fill(0, count($user_ids), '%d')) . ')';
			$args = array_merge($args, $user_ids);
		}
		return ['(' . implode(' OR ', $parts) . ')', $args];
	}

	private function sn_admin_invoice_seller_ids_for_supervisor(int $supervisor_id): array
	{
		$supervisor_id = absint($supervisor_id);
		if ($supervisor_id < 1) { return []; }
		$ids = [];
		$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_direct_children($supervisor_id, 'seller'), 'user_id')));
		$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_descendant_users($supervisor_id, 'seller'), 'user_id')));
		$legacy = get_users(['role' => 'sn_seller', 'meta_key' => 'sn_supervisor_id', 'meta_value' => $supervisor_id, 'fields' => 'ids', 'number' => 3000]);
		$ids = array_merge($ids, array_map('intval', $legacy));
		return array_values(array_unique(array_filter($ids)));
	}

	private function build_invoices_where(array $f): array
	{
		global $wpdb;
		$where = ['1=1'];
		$args = [];
		if ($f['status'] === 'needs_review') {
			$where[] = "(status IN ('receipt_uploaded','pending_financial_approval') OR payment_status IN ('receipt_uploaded','pending_financial_approval') OR invoice_status IN ('receipt_uploaded','pending_financial_approval'))";
		} elseif ($f['status'] !== '' && $f['status'] !== 'all') {
			$where[] = 'status = %s';
			$args[] = $f['status'];
		}
		if ($f['search'] !== '') {
			$where[] = '(invoice_code LIKE %s OR customer_name LIKE %s OR customer_phone LIKE %s OR city LIKE %s)';
			$like = '%' . $wpdb->esc_like($f['search']) . '%';
			array_push($args, $like, $like, $like, $like);
		}
		$has_hierarchy_filter = ! empty($f['sales_manager_ids']) || ! empty($f['senior_supervisor_ids']) || ! empty($f['supervisor_ids']) || ! empty($f['seller_ids']);
		if (! $has_hierarchy_filter) {
			if (! empty($f['seller_id'])) { $f['seller_ids'] = [(int) $f['seller_id']]; $has_hierarchy_filter = true; }
			if (! empty($f['supervisor_id'])) { $f['supervisor_ids'] = [(int) $f['supervisor_id']]; $has_hierarchy_filter = true; }
		}
		if ($has_hierarchy_filter) {
			$seller_ids = $this->sn_admin_invoice_selected_scope_seller_ids($f);
			if (! $seller_ids) { $where[] = '0=1'; }
			else { [$owner_where, $owner_args] = $this->sn_admin_invoice_owner_where_for_user_ids($seller_ids); $where[] = $owner_where; $args = array_merge($args, $owner_args); }
		}
		$date_from = SN_Helpers::jalali_to_gregorian_date((string) $f['date_from']);
		$date_to = SN_Helpers::jalali_to_gregorian_date((string) $f['date_to']);
		if ($date_from) { $where[] = 'DATE(created_at) >= %s'; $args[] = $date_from; }
		if ($date_to) { $where[] = 'DATE(created_at) <= %s'; $args[] = $date_to; }
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_from'])) { $where[] = 'TIME(created_at) >= %s'; $args[] = $f['time_from'] . ':00'; }
		if (preg_match('/^\d{2}:\d{2}$/', $f['time_to'])) { $where[] = 'TIME(created_at) <= %s'; $args[] = $f['time_to'] . ':59'; }
		return [implode(' AND ', $where), $args];
	}

	private function sn_invoice_effective_seller_id_for_admin(array $invoice): int
	{
		foreach (['seller_id','original_seller_id','commission_seller_id','seller_user_id','sales_user_id','lead_seller_id','assigned_seller_id'] as $field) {
			if (! empty($invoice[$field]) && (int) $invoice[$field] > 0) { return (int) $invoice[$field]; }
		}
		return 0;
	}

	private function sn_invoice_status_label_for_admin(array $invoice): string
	{
		$status = (string) (($invoice['status'] ?? '') ?: ($invoice['invoice_status'] ?? '') ?: ($invoice['payment_status'] ?? ''));
		$labels = ['pre_invoice'=>'پیش‌فاکتور','pending'=>'در انتظار پرداخت','pending_payment'=>'در انتظار پرداخت','receipt_uploaded'=>'فیش بارگذاری‌شده','pending_financial_approval'=>'در انتظار تایید مالی','paid'=>'پرداخت‌شده','approved'=>'تاییدشده','cancelled'=>'لغوشده','rejected'=>'ردشده'];
		return $labels[$status] ?? ($status !== '' ? $status : '—');
	}

	private function sn_invoice_pay_method_label(string $method): string
	{
		if ($method === 'online') { return 'آنلاین'; }
		if (in_array($method, ['card','card_to_card','receipt'], true)) { return 'کارت‌به‌کارت'; }
		return $method !== '' ? $method : '—';
	}

	private function sn_invoice_is_paid_for_admin(array $invoice): bool
	{
		$approved = $this->sn_commission_approved_status_values();
		foreach (['status','invoice_status','payment_status'] as $field) { $value = (string) ($invoice[$field] ?? ''); if ($value !== '' && in_array($value, $approved, true)) { return true; } }
		return false;
	}

	private function sn_admin_invoice_hr_chain_map(array $user_ids): array
	{
		global $wpdb;
		$user_ids = array_values(array_unique(array_filter(array_map('intval', $user_ids))));
		$map = [];
		foreach ($user_ids as $uid) { $map[$uid] = ['seller_id' => $uid, 'seller_name' => $uid ? $this->sn_user_label($uid) : '—']; }
		if (! $user_ids || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles') || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_assignments')) { return $map; }
		$profiles = $wpdb->get_results("SELECT p.id,p.user_id,p.is_active,COALESCE(NULLIF(p.hr_display_name,''),u.display_name,CONCAT('#',p.user_id)) display_name,pos.slug position_slug FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id ORDER BY p.is_active DESC,p.id DESC", ARRAY_A) ?: [];
		$profile_by_id = []; $profile_by_user = [];
		foreach ($profiles as $p) { $pid = (int) ($p['id'] ?? 0); $uid = (int) ($p['user_id'] ?? 0); if ($pid < 1 || $uid < 1) { continue; } $profile_by_id[$pid] = $p; if (! isset($profile_by_user[$uid])) { $profile_by_user[$uid] = $p; } }
		$parents = [];
		$edges = $wpdb->get_results("SELECT child_profile_id,parent_profile_id FROM {$wpdb->prefix}sn_hr_assignments WHERE is_current=1 AND (relationship_type='reports_to' OR relationship_type='' OR relationship_type IS NULL) ORDER BY id DESC", ARRAY_A) ?: [];
		foreach ($edges as $edge) { $child = (int) ($edge['child_profile_id'] ?? 0); $parent = (int) ($edge['parent_profile_id'] ?? 0); if ($child > 0 && $parent > 0 && ! isset($parents[$child])) { $parents[$child] = $parent; } }
		foreach ($user_ids as $uid) {
			$profile = $profile_by_user[$uid] ?? null; if (! $profile) { continue; }
			$map[$uid]['seller_name'] = (string) ($profile['display_name'] ?? $map[$uid]['seller_name']);
			$current_profile_id = (int) ($profile['id'] ?? 0); $guard = 0;
			while ($current_profile_id > 0 && isset($parents[$current_profile_id]) && $guard++ < 12) {
				$parent_id = (int) $parents[$current_profile_id]; $p = $profile_by_id[$parent_id] ?? null; if (! $p) { break; }
				$slug = (string) ($p['position_slug'] ?? ''); $name = (string) ($p['display_name'] ?? ''); $pid_user = (int) ($p['user_id'] ?? 0);
				if ($slug === 'supervisor' && empty($map[$uid]['supervisor_id'])) { $map[$uid]['supervisor_id'] = $pid_user; $map[$uid]['supervisor_name'] = $name; }
				elseif ($slug === 'senior_supervisor' && empty($map[$uid]['senior_supervisor_id'])) { $map[$uid]['senior_supervisor_id'] = $pid_user; $map[$uid]['senior_supervisor_name'] = $name; }
				elseif ($slug === 'sales_manager' && empty($map[$uid]['sales_manager_id'])) { $map[$uid]['sales_manager_id'] = $pid_user; $map[$uid]['sales_manager_name'] = $name; }
				elseif (in_array($slug, ['deputy_sales','sales_deputy','deputy'], true) && empty($map[$uid]['deputy_id'])) { $map[$uid]['deputy_id'] = $pid_user; $map[$uid]['deputy_name'] = $name; }
				$current_profile_id = $parent_id;
			}
		}
		return $map;
	}

	private function sn_normalize_payment_card_number($value): string
	{
		$digits = preg_replace('/\\D+/', '', SN_Helpers::to_english_nums((string) $value));
		if (! is_string($digits) || strlen($digits) !== 16) { return ''; }
		return implode('-', str_split($digits, 4));
	}

	/**
	 * Normalize a destination-card entry without forcing staff to type the
	 * complete card number. Internal forms accept the last four digits; when
	 * those digits match an existing immutable snapshot we retain that snapshot
	 * for compatibility. Otherwise only the entered last-four is stored.
	 */
	private function sn_manual_destination_card_input($value, $invoice, bool $allow_empty = false): array
	{
		$digits = preg_replace('/\\D+/', '', SN_Helpers::to_english_nums((string) $value));
		if (! is_string($digits)) { $digits = ''; }
		if ($allow_empty && $digits === '') {
			return ['valid' => true, 'last4' => '', 'number' => ''];
		}
		$full_number = $this->sn_normalize_payment_card_number($digits);
		if ($full_number !== '') {
			return ['valid' => true, 'last4' => substr($digits, -4), 'number' => $full_number];
		}
		if (strlen($digits) !== 4) {
			return ['valid' => false, 'last4' => '', 'number' => ''];
		}

		$row = is_object($invoice) ? get_object_vars($invoice) : (is_array($invoice) ? $invoice : []);
		$candidates = [$row['manual_card_to_number'] ?? '', $row['payment_card_number'] ?? ''];
		$resolved = $this->sn_resolve_invoice_card($invoice);
		$candidates[] = $resolved['number'] ?? '';
		foreach ($candidates as $candidate) {
			$normalized = $this->sn_normalize_payment_card_number($candidate);
			$normalized_digits = preg_replace('/\\D+/', '', $normalized);
			if ($normalized !== '' && is_string($normalized_digits) && substr($normalized_digits, -4) === $digits) {
				$full_number = $normalized;
				break;
			}
		}
		return ['valid' => true, 'last4' => $digits, 'number' => $full_number];
	}

	/**
	 * Return only the destination last-four for Finance and operational panels.
	 * Full historical snapshots remain untouched in storage for compatibility.
	 */
	private function sn_manual_destination_card_display($invoice): string
	{
		$row = is_object($invoice) ? get_object_vars($invoice) : (is_array($invoice) ? $invoice : []);
		$last_four = preg_replace('/\\D+/', '', SN_Helpers::to_english_nums((string) (($row['manual_card_to'] ?? '') ?: ($row['deposit_card_to_last4'] ?? ''))));
		$last_four = is_string($last_four) && strlen($last_four) === 4 ? $last_four : '';
		if ($last_four !== '') { return $last_four; }
		foreach ([$row['manual_card_to_number'] ?? '', $row['payment_card_number'] ?? ''] as $candidate) {
			$number = $this->sn_normalize_payment_card_number($candidate);
			$number_digits = preg_replace('/\\D+/', '', $number);
			if ($number !== '' && is_string($number_digits)) { return substr($number_digits, -4); }
		}
		return '';
	}

	private function sn_sales_deputy_card_settings(): array
	{
		$raw = get_option('sn_sales_deputy_cards', []);
		if (! is_array($raw)) { return []; }
		$out = [];
		foreach ($raw as $user_id => $row) {
			$user_id = absint($user_id);
			$row = is_array($row) ? $row : [];
			$number = $this->sn_normalize_payment_card_number($row['card_number'] ?? '');
			if ($user_id < 1 || $number === '') { continue; }
			$out[$user_id] = [
				'card_number' => $number,
				'card_owner' => sanitize_text_field((string) ($row['card_owner'] ?? '')),
			];
		}
		return $out;
	}

	private function sn_sales_manager_card_settings(): array
	{
		$raw = get_option('sn_sales_manager_cards', []);
		if (! is_array($raw)) { return []; }
		$out = [];
		foreach ($raw as $user_id => $row) {
			$user_id = absint($user_id);
			$row = is_array($row) ? $row : [];
			$number = $this->sn_normalize_payment_card_number($row['card_number'] ?? '');
			if ($user_id < 1 || $number === '') { continue; }
			$out[$user_id] = [
				'card_number' => $number,
				'card_owner' => sanitize_text_field((string) ($row['card_owner'] ?? '')),
			];
		}
		return $out;
	}

	private function sn_card_to_card_enabled(): bool
	{
		return (string) get_option('sn_card_to_card_enabled', '1') === '1';
	}

	private function sn_resolve_sales_manager_card_for_seller(int $seller_id): array
	{
		$fallback_number = trim((string) get_option('sn_card_number', ''));
		$fallback_owner = trim((string) get_option('sn_card_owner', ''));
		$result = [
			'number' => $fallback_number,
			'owner' => $fallback_owner,
			'sales_manager_user_id' => 0,
			'deputy_user_id' => 0,
			'source' => 'global',
		];
		if ($seller_id < 1) { return $result; }
		$chain_map = $this->sn_admin_invoice_hr_chain_map([$seller_id]);
		$manager_id = absint($chain_map[$seller_id]['sales_manager_id'] ?? 0);
		$manager_cards = $this->sn_sales_manager_card_settings();
		if ($manager_id > 0 && ! empty($manager_cards[$manager_id]['card_number'])) {
			return [
				'number' => (string) $manager_cards[$manager_id]['card_number'],
				'owner' => (string) ($manager_cards[$manager_id]['card_owner'] ?? ''),
				'sales_manager_user_id' => $manager_id,
				'deputy_user_id' => 0,
				'source' => 'sales_manager',
			];
		}
		if ($manager_id > 0) { return $result; }

		// Compatibility for installations that already configured deputy cards.
		// Read them only for truly legacy chains that do not have a sales manager.
		$deputy_id = absint($chain_map[$seller_id]['deputy_id'] ?? 0);
		if ($deputy_id < 1) { return $result; }
		$cards = $this->sn_sales_deputy_card_settings();
		if (empty($cards[$deputy_id]['card_number'])) { return $result; }
		return [
			'number' => (string) $cards[$deputy_id]['card_number'],
			'owner' => (string) ($cards[$deputy_id]['card_owner'] ?? ''),
			'sales_manager_user_id' => 0,
			'deputy_user_id' => $deputy_id,
			'source' => 'legacy_sales_deputy_fallback',
		];
	}

	private function sn_resolve_invoice_card($invoice): array
	{
		$row = is_object($invoice) ? get_object_vars($invoice) : (is_array($invoice) ? $invoice : []);
		$snapshot_number = $this->sn_normalize_payment_card_number($row['payment_card_number'] ?? '');
		if ($snapshot_number !== '') {
			return [
				'number' => $snapshot_number,
				'owner' => sanitize_text_field((string) ($row['payment_card_owner'] ?? '')),
				'sales_manager_user_id' => absint($row['payment_card_sales_manager_user_id'] ?? 0),
				'deputy_user_id' => absint($row['payment_card_deputy_user_id'] ?? 0),
				'source' => 'invoice_snapshot',
			];
		}
		$seller_id = $this->sn_invoice_effective_seller_id_for_admin($row);
		return $this->sn_resolve_sales_manager_card_for_seller($seller_id);
	}

	private function sn_admin_invoice_group_stats(array $filters): array
	{
		global $wpdb;
		[$where, $args] = $this->build_invoices_where($filters);
		$sql = "SELECT * FROM {$wpdb->prefix}sn_invoices WHERE {$where} ORDER BY id DESC LIMIT 5000";
		$rows = $args ? $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) : $wpdb->get_results($sql, ARRAY_A);
		$groups = []; $seller_ids = [];
		foreach ((array) $rows as $r) { $seller_id = $this->sn_invoice_effective_seller_id_for_admin((array) $r); $seller_ids[] = $seller_id; if (! isset($groups[$seller_id])) { $groups[$seller_id] = ['seller_id'=>$seller_id,'invoice_count'=>0,'paid_count'=>0,'revenue'=>0.0]; } $groups[$seller_id]['invoice_count']++; if ($this->sn_invoice_is_paid_for_admin((array) $r)) { $groups[$seller_id]['paid_count']++; $groups[$seller_id]['revenue'] += $this->sn_invoice_amount_from_row((array) $r); } }
		$chain_map = $this->sn_admin_invoice_hr_chain_map($seller_ids);
		foreach ($groups as $seller_id => &$g) { $g['chain'] = $chain_map[$seller_id] ?? ['seller_name' => $seller_id ? $this->sn_user_label((int) $seller_id) : '—']; }
		unset($g); usort($groups, static fn($a, $b) => ((float) $b['revenue'] <=> (float) $a['revenue']) ?: ((int) $b['invoice_count'] <=> (int) $a['invoice_count']));
		return array_slice($groups, 0, 50);
	}

	private function sn_admin_money_filter_value($value): ?float
	{
		$value = trim((string) $value);
		if ($value === '') { return null; }
		$value = str_replace(['٬', ',', '،', ' '], '', $value);
		$value = preg_replace('/[^0-9.\-]/', '', $value);
		if ($value === '' || ! is_numeric($value)) { return null; }
		return (float) $value;
	}

	private function sn_admin_invoice_status_filter_condition(string $status, string $alias = 'i'): array
	{
		$prefix = $alias !== '' ? rtrim($alias, '.') . '.' : '';
		if ($status === 'needs_review') {
			return ["({$prefix}status IN ('receipt_uploaded','pending_financial_approval') OR {$prefix}payment_status IN ('receipt_uploaded','pending_financial_approval') OR {$prefix}invoice_status IN ('receipt_uploaded','pending_financial_approval'))", []];
		}
		if ($status === 'paid') {
			return ["({$prefix}status IN ('paid','approved','completed') OR {$prefix}payment_status IN ('paid','approved','completed') OR {$prefix}invoice_status IN ('paid','approved','completed'))", []];
		}
		if ($status === 'pre_invoice') {
			return ["({$prefix}status IN ('pre_invoice','pending','pending_payment','partial_paid') OR {$prefix}payment_status IN ('pre_invoice','pending','pending_payment','partial_paid') OR {$prefix}invoice_status IN ('pre_invoice','pending','pending_payment','partial_paid'))", []];
		}
		if ($status === 'cancelled') {
			return ["({$prefix}status IN ('cancelled','payment_archived') OR {$prefix}payment_status IN ('cancelled','payment_archived') OR {$prefix}invoice_status IN ('cancelled','payment_archived'))", []];
		}
		if ($status !== '' && $status !== 'all') {
			return ["({$prefix}status=%s OR {$prefix}payment_status=%s OR {$prefix}invoice_status=%s)", [$status, $status, $status]];
		}
		return ['1=1', []];
	}

	private function sn_admin_hierarchy_filter_options(): array
	{
		// Build options inside this helper. In 1.0.138 these variables were
		// accidentally expected from the caller scope, which caused fatal errors
		// on sn-invoices and sn-customer-profiles when rendering the checkdrop UI.
		$sales_managers = $this->sn_admin_invoice_user_options(['sales_manager'], ['sn_sales_manager']);
		$senior_supervisors = $this->sn_admin_invoice_user_options(['senior_supervisor'], []);
		$supervisors = $this->sn_admin_invoice_user_options(['supervisor'], ['sn_supervisor']);
		$sellers = $this->sn_admin_invoice_user_options(['seller'], ['sn_seller']);

		$all_ids = [];
		foreach ([$sales_managers, $senior_supervisors, $supervisors, $sellers] as $group) {
			foreach ((array) $group as $opt) { $all_ids[] = (int) ($opt->ID ?? 0); }
		}
		$chains = $this->sn_admin_invoice_hr_chain_map($all_ids);
		return [
			'sales_manager' => [$sales_managers, $chains],
			'senior_supervisor' => [$senior_supervisors, $chains],
			'supervisor' => [$supervisors, $chains],
			'seller' => [$sellers, $chains],
		];
	}

	private function sn_admin_render_checkdrop_assets(): void
	{
		static $printed = false;
		if ($printed) { return; }
		$printed = true;
		?>
		<style>
			.sn-checkdrop{position:relative;min-width:210px}.sn-checkdrop-toggle{width:100%;min-height:38px;border:1px solid #cbd5e1;border-radius:12px;background:#fff;text-align:right;padding:8px 12px;cursor:pointer}.sn-checkdrop-toggle strong{display:block;font-size:12px;color:#0f172a}.sn-checkdrop-toggle span{font-size:12px;color:#64748b}.sn-checkdrop-menu{display:none;position:absolute;z-index:10000;right:0;top:calc(100% + 6px);width:280px;max-height:330px;overflow:auto;background:#fff;border:1px solid #cbd5e1;border-radius:14px;box-shadow:0 18px 40px rgba(15,23,42,.16);padding:10px}.sn-checkdrop.is-open .sn-checkdrop-menu{display:block}.sn-checkdrop-search{width:100%;margin-bottom:8px;border-radius:10px}.sn-checkdrop-item{display:flex;gap:8px;align-items:center;padding:7px 6px;border-radius:10px;font-size:13px;cursor:pointer}.sn-checkdrop-item:hover{background:#f1f5f9}.sn-checkdrop-item.is-hidden{display:none}.sn-filter-actions{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.sn-admin-filterbar.sn-hierarchy-form{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.sn-admin-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.sn-admin-tabs a{padding:9px 16px;border-radius:12px;background:#f1f5f9;text-decoration:none;font-weight:700;color:#334155}.sn-admin-tabs a.is-active{background:#2563eb;color:#fff}.sn-inline-note{color:#64748b;font-size:12px;margin-top:4px}
		</style>
		<script>
			(function(){
				if(window.snCheckdropReady){return;} window.snCheckdropReady=true;
				function selected(role){return Array.prototype.slice.call(document.querySelectorAll('.sn-checkdrop[data-role="'+role+'"] input[type="checkbox"]:checked')).map(function(i){return i.value;});}
				function anyMatch(csv, values){if(!values.length){return true;} if(!csv){return false;} var parts=String(csv).split(',').filter(Boolean); return values.some(function(v){return parts.indexOf(String(v))>-1;});}
				function refreshSummary(box){var checked=box.querySelectorAll('input[type="checkbox"]:checked'); var span=box.querySelector('.sn-checkdrop-summary'); var label=box.getAttribute('data-empty') || 'انتخاب نشده'; if(!span){return;} if(!checked.length){span.textContent=label;} else if(checked.length===1){span.textContent=checked[0].getAttribute('data-caption') || checked[0].parentNode.textContent.trim();} else {span.textContent=checked.length+' مورد انتخاب شده';}}
				function cascade(){var sm=selected('sales_manager'), ss=selected('senior_supervisor'), sp=selected('supervisor'); document.querySelectorAll('.sn-checkdrop-item').forEach(function(row){var role=row.closest('.sn-checkdrop').getAttribute('data-role'); var ok=true; if(role==='senior_supervisor'){ok=anyMatch(row.getAttribute('data-sales-manager'),sm);} if(role==='supervisor'){ok=anyMatch(row.getAttribute('data-sales-manager'),sm)&&anyMatch(row.getAttribute('data-senior-supervisor'),ss);} if(role==='seller'){ok=anyMatch(row.getAttribute('data-sales-manager'),sm)&&anyMatch(row.getAttribute('data-senior-supervisor'),ss)&&anyMatch(row.getAttribute('data-supervisor'),sp);} row.classList.toggle('is-hidden',!ok); var cb=row.querySelector('input[type="checkbox"]'); if(cb && !ok){cb.checked=false;} }); document.querySelectorAll('.sn-checkdrop').forEach(refreshSummary);}
				document.addEventListener('click',function(e){var toggle=e.target.closest('.sn-checkdrop-toggle'); if(toggle){e.preventDefault(); var box=toggle.closest('.sn-checkdrop'); document.querySelectorAll('.sn-checkdrop.is-open').forEach(function(other){if(other!==box){other.classList.remove('is-open');}}); box.classList.toggle('is-open'); return;} if(!e.target.closest('.sn-checkdrop')){document.querySelectorAll('.sn-checkdrop.is-open').forEach(function(b){b.classList.remove('is-open');});}});
				document.addEventListener('input',function(e){if(e.target.classList.contains('sn-checkdrop-search')){var q=e.target.value.trim().toLowerCase(); e.target.closest('.sn-checkdrop-menu').querySelectorAll('.sn-checkdrop-item').forEach(function(row){var text=row.textContent.toLowerCase(); row.style.display = (!q || text.indexOf(q)>-1) ? '' : 'none';});}});
				document.addEventListener('change',function(e){if(e.target.matches('.sn-checkdrop input[type="checkbox"]')){cascade();}});
				document.addEventListener('DOMContentLoaded',cascade); setTimeout(cascade,50);
			})();
		</script>
		<?php
	}

	private function sn_admin_render_checkdrop(string $role, string $name, string $label, ?array $options, array $selected, array $chain_map): void
	{
		$options = is_array($options) ? $options : [];
		$selected = array_values(array_unique(array_filter(array_map('intval', $selected))));
		$this->sn_admin_render_checkdrop_assets();
		?>
		<div class="sn-checkdrop" data-role="<?php echo esc_attr($role); ?>" data-empty="همه <?php echo esc_attr($label); ?>">
			<button type="button" class="sn-checkdrop-toggle"><strong><?php echo esc_html($label); ?></strong><span class="sn-checkdrop-summary">همه <?php echo esc_html($label); ?></span></button>
			<div class="sn-checkdrop-menu">
				<input type="search" class="sn-checkdrop-search" placeholder="جستجو در <?php echo esc_attr($label); ?>">
				<?php foreach ($options as $opt) :
					$oid = (int) ($opt->ID ?? 0); if ($oid < 1) { continue; }
					$caption = trim((string) ($opt->display_name ?? '')) ?: ('#' . $oid);
					$chain = $chain_map[$oid] ?? [];
					$sm = (string) ($chain['sales_manager_id'] ?? ($role === 'sales_manager' ? $oid : ''));
					$sen = (string) ($chain['senior_supervisor_id'] ?? ($role === 'senior_supervisor' ? $oid : ''));
					$sup = (string) ($chain['supervisor_id'] ?? ($role === 'supervisor' ? $oid : ''));
				?>
					<label class="sn-checkdrop-item" data-sales-manager="<?php echo esc_attr($sm); ?>" data-senior-supervisor="<?php echo esc_attr($sen); ?>" data-supervisor="<?php echo esc_attr($sup); ?>"><input type="checkbox" name="<?php echo esc_attr($name); ?>[]" value="<?php echo esc_attr((string) $oid); ?>" data-caption="<?php echo esc_attr($caption . ' #' . $oid); ?>" <?php checked(in_array($oid, $selected, true)); ?>> <span><?php echo esc_html($caption . ' #' . $oid); ?></span></label>
				<?php endforeach; ?>
			</div>
		</div>
		<?php
	}

	private function sn_admin_render_hierarchy_checkdrops(array $filters): void
	{
		$options = $this->sn_admin_hierarchy_filter_options();
		[$sales_managers, $chain_map] = $options['sales_manager'];
		[$senior_supervisors, $chain_map] = $options['senior_supervisor'];
		[$supervisors, $chain_map] = $options['supervisor'];
		[$sellers, $chain_map] = $options['seller'];
		$this->sn_admin_render_checkdrop('sales_manager', 'sn_sales_manager_ids', 'مدیر فروش', $sales_managers, (array) ($filters['sales_manager_ids'] ?? []), $chain_map);
		$this->sn_admin_render_checkdrop('senior_supervisor', 'sn_senior_supervisor_ids', 'سرپرست ارشد', $senior_supervisors, (array) ($filters['senior_supervisor_ids'] ?? []), $chain_map);
		$this->sn_admin_render_checkdrop('supervisor', 'sn_supervisor_ids', 'سرپرست', $supervisors, (array) ($filters['supervisor_ids'] ?? []), $chain_map);
		$this->sn_admin_render_checkdrop('seller', 'sn_seller_ids', 'فروشنده', $sellers, (array) ($filters['seller_ids'] ?? []), $chain_map);
	}

	private function sn_customer_profile_filters(): array
	{
		$view = sanitize_key(wp_unslash($_GET['sn_view'] ?? 'detail'));
		if (! in_array($view, ['detail','aggregate'], true)) { $view = 'detail'; }
		$q = sanitize_text_field(wp_unslash($_GET['sn_q'] ?? ($_GET['sn_search'] ?? '')));
		return [
			'view' => $view,
			'status' => sanitize_text_field(wp_unslash($_GET['sn_status'] ?? 'all')),
			'search' => $q,
			'sales_manager_ids' => $this->sn_admin_request_id_list('sn_sales_manager_ids', 'sn_sales_manager_id'),
			'senior_supervisor_ids' => $this->sn_admin_request_id_list('sn_senior_supervisor_ids', 'sn_senior_supervisor_id'),
			'supervisor_ids' => $this->sn_admin_request_id_list('sn_supervisor_ids', 'sn_supervisor_id'),
			'seller_ids' => $this->sn_admin_request_id_list('sn_seller_ids', 'sn_seller_id'),
			'date_from' => sanitize_text_field(wp_unslash($_GET['sn_date_from'] ?? '')),
			'date_to' => sanitize_text_field(wp_unslash($_GET['sn_date_to'] ?? '')),
			'amount_min' => sanitize_text_field(wp_unslash($_GET['sn_amount_min'] ?? '')),
			'amount_max' => sanitize_text_field(wp_unslash($_GET['sn_amount_max'] ?? '')),
		];
	}

	private function sn_customer_profile_invoice_where(array $filters): array
	{
		global $wpdb;
		$where = ['1=1']; $args = [];
		[$status_where, $status_args] = $this->sn_admin_invoice_status_filter_condition((string) ($filters['status'] ?? 'all'), 'i');
		if ($status_where !== '1=1') { $where[] = $status_where; $args = array_merge($args, $status_args); }
		$q = (string) ($filters['search'] ?? '');
		if ($q !== '') { $like = '%' . $wpdb->esc_like($q) . '%'; $where[] = '(i.customer_phone LIKE %s OR i.customer_name LIKE %s OR i.invoice_code LIKE %s OR u.display_name LIKE %s OR u.user_login LIKE %s OR i.city LIKE %s OR i.province LIKE %s)'; $args = array_merge($args, [$like, $like, $like, $like, $like, $like, $like]); }
		$has_hierarchy_filter = ! empty($filters['sales_manager_ids']) || ! empty($filters['senior_supervisor_ids']) || ! empty($filters['supervisor_ids']) || ! empty($filters['seller_ids']);
		if ($has_hierarchy_filter) {
			$seller_ids = $this->sn_admin_invoice_selected_scope_seller_ids($filters);
			if (! $seller_ids) { $where[] = '0=1'; }
			else { [$owner_where, $owner_args] = $this->sn_admin_invoice_owner_where_for_user_ids($seller_ids, 'i'); $where[] = $owner_where; $args = array_merge($args, $owner_args); }
		}
		$date_from = SN_Helpers::jalali_to_gregorian_date((string) ($filters['date_from'] ?? ''));
		$date_to = SN_Helpers::jalali_to_gregorian_date((string) ($filters['date_to'] ?? ''));
		if ($date_from) { $where[] = 'DATE(i.created_at) >= %s'; $args[] = $date_from; }
		if ($date_to) { $where[] = 'DATE(i.created_at) <= %s'; $args[] = $date_to; }
		if (($filters['view'] ?? 'detail') !== 'aggregate') {
			$amount_expr = $this->sn_admin_invoice_amount_expr('i');
			$min = $this->sn_admin_money_filter_value($filters['amount_min'] ?? '');
			$max = $this->sn_admin_money_filter_value($filters['amount_max'] ?? '');
			if ($min !== null) { $where[] = "{$amount_expr} >= %f"; $args[] = $min; }
			if ($max !== null) { $where[] = "{$amount_expr} <= %f"; $args[] = $max; }
		}
		return [implode(' AND ', $where), $args];
	}

	private function sn_customer_profile_fetch_invoice_rows(array $filters, int $limit = 1000): array
	{
		global $wpdb;
		[$where, $args] = $this->sn_customer_profile_invoice_where($filters);
		$limit = max(50, min(20000, absint($limit)));
		$sql = "SELECT i.* FROM {$wpdb->prefix}sn_invoices i LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id WHERE {$where} ORDER BY i.customer_phone ASC, i.created_at DESC, i.id DESC LIMIT %d";
		$args[] = $limit;
		return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
	}

	private function sn_customer_profile_aggregate_rows(array $rows, array $chain_map, array $filters = []): array
	{
		$groups = [];
		foreach ((array) $rows as $r) {
			$phone = preg_replace('/\D+/', '', (string) ($r['customer_phone'] ?? ''));
			$key = $phone !== '' ? $phone : ('invoice-' . (string) ($r['id'] ?? uniqid('', true)));
			if (! isset($groups[$key])) {
				$groups[$key] = ['customer_phone' => (string) ($r['customer_phone'] ?? ''), 'customer_name' => (string) ($r['customer_name'] ?? ''), 'invoice_count' => 0, 'total_amount' => 0.0, 'paid_count' => 0, 'paid_amount' => 0.0, 'latest_invoice_code' => '', 'products' => [], 'statuses' => [], 'pay_methods' => [], 'sellers' => [], 'supervisors' => [], 'senior_supervisors' => [], 'sales_managers' => [], 'deputies' => [], 'first_date' => '', 'last_date' => ''];
			}
			$g =& $groups[$key];
			$amount = $this->sn_invoice_amount_from_row((array) $r);
			$g['invoice_count']++;
			$g['total_amount'] += $amount;
			if ($this->sn_invoice_is_paid_for_admin((array) $r)) { $g['paid_count']++; $g['paid_amount'] += $amount; }
			if ($g['customer_name'] === '' && ! empty($r['customer_name'])) { $g['customer_name'] = (string) $r['customer_name']; }
			if ($g['latest_invoice_code'] === '' && ! empty($r['invoice_code'])) { $g['latest_invoice_code'] = (string) $r['invoice_code']; }
			$product = $this->sn_invoice_items_label((int) ($r['id'] ?? 0), (int) ($r['product_id'] ?? 0)); if ($product !== '') { $g['products'][$product] = $product; }
			$status = $this->sn_invoice_status_label_for_admin((array) $r); if ($status !== '') { $g['statuses'][$status] = $status; }
			$pm = $this->sn_invoice_pay_method_label((string) ($r['pay_method'] ?? '')); if ($pm !== '' && $pm !== '—') { $g['pay_methods'][$pm] = $pm; }
			$seller_id = $this->sn_invoice_effective_seller_id_for_admin((array) $r); $chain = $chain_map[$seller_id] ?? [];
			foreach ([['sellers','seller_name'],['supervisors','supervisor_name'],['senior_supervisors','senior_supervisor_name'],['sales_managers','sales_manager_name'],['deputies','deputy_name']] as $pair) { $name = (string) ($chain[$pair[1]] ?? ''); if ($name !== '') { $g[$pair[0]][$name] = $name; } }
			$date = (string) ($r['created_at'] ?? ''); if ($date !== '') { if ($g['last_date'] === '' || $date > $g['last_date']) { $g['last_date'] = $date; } if ($g['first_date'] === '' || $date < $g['first_date']) { $g['first_date'] = $date; } }
			unset($g);
		}
		$min = $this->sn_admin_money_filter_value($filters['amount_min'] ?? '');
		$max = $this->sn_admin_money_filter_value($filters['amount_max'] ?? '');
		$out = array_values($groups);
		$out = array_values(array_filter($out, static function($row) use ($min, $max) { $total = (float) ($row['total_amount'] ?? 0); if ($min !== null && $total < $min) { return false; } if ($max !== null && $total > $max) { return false; } return true; }));
		usort($out, static fn($a, $b) => ((float) ($b['total_amount'] ?? 0) <=> (float) ($a['total_amount'] ?? 0)) ?: ((int) ($b['invoice_count'] ?? 0) <=> (int) ($a['invoice_count'] ?? 0)));
		return $out;
	}

	/**
	 * Destructive reset tool. It deliberately preserves WordPress pages/products,
	 * every wp_option setting and the plugin's structural configuration tables.
	 */
	public function ajax_full_data_reset(): void
	{
		if (! current_user_can('manage_options') || ! check_ajax_referer('sn_full_data_reset', 'nonce', false)) {
			wp_send_json_error(['message' => 'دسترسی غیرمجاز است.'], 403);
		}
		$confirmation = sanitize_text_field(wp_unslash($_POST['confirmation'] ?? ''));
		if ($confirmation !== 'حذف کامل داده‌ها' || (string) ($_POST['confirmed'] ?? '') !== '1') {
			wp_send_json_error(['message' => 'عبارت تایید یا تیک پذیرش عملیات کامل نیست.'], 400);
		}
		$actor_id = get_current_user_id();
		if ($actor_id < 1) { wp_send_json_error(['message' => 'مدیر جاری معتبر نیست.'], 403); }
		if (function_exists('wp_raise_memory_limit')) { wp_raise_memory_limit('admin'); }
		if (function_exists('set_time_limit')) { @set_time_limit(0); }
		require_once ABSPATH . 'wp-admin/includes/user.php';

		// Keep all administrators and reassign every authored post/page to the
		// current administrator before deleting other users.
		$deleted_users = 0; $skipped_users = 0; $user_errors = [];
		foreach (get_users(['fields' => 'ids', 'number' => -1]) as $candidate_id) {
			$candidate_id = (int) $candidate_id;
			if ($candidate_id < 1 || $candidate_id === $actor_id || user_can($candidate_id, 'manage_options')) { $skipped_users++; continue; }
			$result = wp_delete_user($candidate_id, $actor_id);
			if ($result) { $deleted_users++; } else { $user_errors[] = $candidate_id; }
		}

		global $wpdb;
		$preserve_suffixes = [
			'sn_hr_positions','sn_hr_levels','sn_hr_position_role_mappings','sn_hr_departments','sn_hr_units','sn_hr_teams',
			'sn_mis_distribution_rules','sn_distribution_chains','sn_distribution_chain_steps','sn_commission_rules',
			'sn_project_subscriptions','sn_project_subscription_contents','sn_project_manager_products','sn_project_manager_sales_routes',
			'sn_project_operations_manager_products','sn_project_operations_sales_routes','sn_project_operations_supervisor_sales_routes',
			'sn_project_card_upgrade_rules','sn_project_commission_rules','sn_project_api_configs',
		];
		$preserve = array_flip(array_map(static fn($suffix) => $wpdb->prefix . $suffix, $preserve_suffixes));
		$like = $wpdb->esc_like($wpdb->prefix . 'sn_') . '%';
		$tables = (array) $wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s', $like));
		$cleared_tables = []; $cleared_rows = 0; $table_errors = [];
		foreach ($tables as $table) {
			$table = (string) $table;
			if (isset($preserve[$table])) { continue; }
			if (! preg_match('/^' . preg_quote($wpdb->prefix, '/') . 'sn_[A-Za-z0-9_]+$/', $table)) { continue; }
			$count = (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$table}`");
			// TRUNCATE keeps large resets bounded; restricted database accounts fall
			// back to DELETE without expanding the reset scope.
			$cleared = $wpdb->query("TRUNCATE TABLE `{$table}`");
			if (false === $cleared) {
				$cleared = $wpdb->query("DELETE FROM `{$table}`");
				if (false !== $cleared) { $wpdb->query("ALTER TABLE `{$table}` AUTO_INCREMENT=1"); }
			}
			if (false === $cleared) { $table_errors[] = $table; continue; }
			$cleared_rows += $count; $cleared_tables[] = $table;
		}
		// Runtime caches/rate limits are data, not settings. Persistent sn_* options
		// are intentionally untouched.
		$wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '\\_transient\\_sn\\_%' OR option_name LIKE '\\_transient\\_timeout\\_sn\\_%' OR option_name LIKE '\\_site\\_transient\\_sn\\_%' OR option_name LIKE '\\_site\\_transient\\_timeout\\_sn\\_%'");
		wp_cache_flush();
		$report = [
			'deleted_users' => $deleted_users,
			'preserved_admins' => $skipped_users,
			'cleared_tables' => count($cleared_tables),
			'cleared_rows' => $cleared_rows,
			'user_errors' => $user_errors,
			'table_errors' => $table_errors,
			'completed_at' => current_time('mysql'),
		];
		update_option('sn_last_full_data_reset_report', $report, false);
		if ($user_errors || $table_errors) {
			wp_send_json_error(['message' => 'ریست انجام شد، اما چند مورد خطا داشت. گزارش در تنظیمات ثبت شد.', 'report' => $report], 500);
		}
		wp_send_json_success(['message' => sprintf('%s کاربر و %s ردیف داده پاک شد. صفحات، محصولات و تنظیمات حفظ شدند.', number_format_i18n($deleted_users), number_format_i18n($cleared_rows)), 'report' => $report]);
	}

	public function ajax_save_project_settings(): void
	{
		if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
			SN_Helpers::send_json(false, 'دسترسی نامعتبر است؛ صفحه را تازه‌سازی کنید و دوباره وارد شوید.'); return;
		}
		if (! class_exists('SN_Projects')) { SN_Helpers::send_json(false, 'بخش پروژه‌ها در دسترس نیست.'); return; }
		// A single JSON field avoids PHP max_input_vars truncating large settings forms.
		$payload = json_decode(wp_unslash((string) ($_POST['payload'] ?? '')), true);
		if (! is_array($payload) || empty($payload['sn_projects_settings_present']) || ! isset($payload['sn_projects']) || ! is_array($payload['sn_projects']) || empty($payload['sn_operations_supervisor_routes_present'])) {
			SN_Helpers::send_json(false, 'اطلاعات تنظیمات پروژه ناقص دریافت شد؛ هیچ تغییری ذخیره نشد.'); return;
		}
		$request = array_intersect_key($payload, array_flip(['sn_projects_settings_present','sn_projects','sn_operations_supervisor_routes_present','sn_operations_customer_inactivity_days']));
		$result = SN_Projects::instance()->save_settings_from_request(wp_slash($request));
		if (is_wp_error($result)) { SN_Helpers::send_json(false, $result->get_error_message()); return; }
		SN_Helpers::send_json(true, 'تنظیمات پروژه‌ها با موفقیت ذخیره شد. مقصد ' . number_format_i18n((int) ($result['rerouted_operations'] ?? 0)) . ' پرونده دست‌نخورده به‌روز شد.');
	}

	public function ajax_save_settings(): void
	{
		if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
			SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
			return;
		}
		if (class_exists('SN_Dot_Flow')) {
			$dot_saved = SN_Dot_Flow::instance()->save_settings_from_request($_POST);
			if (is_wp_error($dot_saved)) {
				SN_Helpers::send_json(false, $dot_saved->get_error_message());
				return;
			}
			$dot_marketing_saved = SN_Dot_Flow::instance()->save_marketing_settings_from_request($_POST);
			if (is_wp_error($dot_marketing_saved)) {
				SN_Helpers::send_json(false, $dot_marketing_saved->get_error_message());
				return;
			}
		}
		if (class_exists('SN_Projects')) {
			$projects_saved = SN_Projects::instance()->save_settings_from_request($_POST);
			if (is_wp_error($projects_saved)) {
				SN_Helpers::send_json(false, $projects_saved->get_error_message());
				return;
			}
		}

		if ( class_exists( 'SN_Purpose_Commission' ) ) {
			$commission_saved = SN_Purpose_Commission::instance()->save_settings_from_request( $_POST );
			if ( is_wp_error( $commission_saved ) ) { SN_Helpers::send_json( false, $commission_saved->get_error_message() ); return; }
		}

		// فیلدهای ثابت
		$fields = [
			'sn_payment_gateway',
			'sn_zarinpal_merchant',
			'sn_zarinpal_sandbox',
			'sn_zibal_merchant',
			'sn_zibal_test_mode',
			'sn_asan_config_id',
			'sn_asan_username',
			'sn_asan_password',
			'sn_asan_key',
			'sn_asan_iv',
			'sn_asan_reconcile',
			'sn_customer_portal_invite_sms_enabled',
			'sn_kavenegar_template_customer_otp',
			'sn_kavenegar_template_invoice',
			'sn_kavenegar_template_online_payment',
			'sn_kavenegar_template_card_payment',
			'sn_kavenegar_template_payment_reward',
			'sn_faraz_pattern_customer_otp',
			'sn_faraz_pattern_customer_otp_variable',
			'sn_faraz_pattern_invoice',
			'sn_faraz_pattern_online_payment',
			'sn_faraz_pattern_card_payment',
			'sn_faraz_pattern_payment_reward',
			'sn_payment_reward_sms_enabled',
			'sn_payment_reward_sms_template',
			'sn_payment_reward_form_text',
			'sn_wheel_company_name',
			'sn_wheel_free_product_id',
			'sn_coupon_allow_on_sale',
			'sn_lottery_text_template',
			'sn_payment_reward_text',
			'sn_recontact_popup_text',
			'sn_invoice_info_show_product_info',
			'sn_invoice_info_show_short_desc',
			'sn_invoice_info_show_price',
			'sn_invoice_info_show_lottery',
			'sn_invoice_info_show_wheel',
			'sn_invoice_info_show_coupon',
			'sn_invoice_info_show_image',
			'sn_invoice_info_show_gallery',
			'sn_meli_username',
			'sn_meli_password',
			'sn_meli_body_id_invoice',
			'sn_sms_invoice_template',
			'sn_sms_invoice_bodyid',
			'sn_card_number',
			'sn_card_owner',
			'sn_card_to_card_enabled',
			'sn_partial_payment_presets',
			'sn_invoice_max_products',
			'sn_seller_commission_type',
			'sn_seller_commission_value',
			'sn_supervisor_commission_type',
			'sn_supervisor_commission_value',
			'sn_wallet_auto_credit',
			'sn_invoice_page_id',
			'sn_seller_panel_page_id',
			'sn_supervisor_panel_page_id',
			'sn_auth_page_id',
			'sn_supervisor_auth_page_id',
			'sn_after_sales_panel_page_id',
			'sn_financial_auth_page_id',
			'sn_financial_panel_page_id',
			'sn_sales_manager_auth_page_id',
			'sn_sales_manager_panel_page_id',
			'sn_dot_customer_page_id',
			'sn_dot_converter_panel_page_id',
			'sn_shipping_panel_page_id',
			'sn_operations_sales_manager_panel_page_id',
			'sn_operations_sales_supervisor_panel_page_id',
			'sn_operations_sales_expert_panel_page_id',
			'sn_operations_executive_manager_panel_page_id',
			'sn_operations_execution_expert_panel_page_id',
		];
		foreach ($fields as $field) {
			if (isset($_POST[$field])) {
				if (in_array($field, ['sn_sms_invoice_template','sn_payment_reward_text','sn_payment_reward_form_text','sn_payment_reward_sms_template','sn_lottery_text_template','sn_recontact_popup_text'], true)) {
					update_option($field, sanitize_textarea_field(wp_unslash($_POST[$field])));
				} else {
					update_option($field, sanitize_text_field(wp_unslash($_POST[$field])));
				}
			}
		}

		// Zibal reporting API token is a secret: never echo it back into the settings form.
		// Empty submissions preserve the existing token; the explicit clear checkbox removes it.
		if (! empty($_POST['sn_zibal_report_api_token_clear'])) {
			delete_option('sn_zibal_report_api_token');
		} elseif (isset($_POST['sn_zibal_report_api_token'])) {
			$zibal_report_token = trim((string) wp_unslash($_POST['sn_zibal_report_api_token']));
			$zibal_report_token = (string) preg_replace('/[\x00-\x1F\x7F]/', '', $zibal_report_token);
			if ($zibal_report_token !== '') {
				// Bearer tokens may legitimately contain punctuation (for example dots, tildes or percent signs).
				// Strip only control characters instead of sanitize_text_field(), which can alter opaque credentials.
				update_option('sn_zibal_report_api_token', $zibal_report_token, false);
			}
		}

		// 1.0.149: normalize the product-row limit. Zero is the explicit unlimited mode.
		if (isset($_POST['sn_invoice_max_products'])) {
			$raw_max_products = SN_Helpers::to_english_nums(sanitize_text_field(wp_unslash($_POST['sn_invoice_max_products'])));
			update_option('sn_invoice_max_products', (string) max(0, (int) $raw_max_products));
		}

		// Checkbox fields: preserve absent values. A checkbox is changed only when that checkbox actually exists in the submitted form.
		// Checked boxes submit their own value; unchecked boxes submit only the __present marker added by admin.js.
		// This prevents partial/admin-tab saves and plugin update flows from resetting unrelated settings.
		$checkbox_fields = ['sn_zarinpal_sandbox','sn_zibal_test_mode','sn_asan_reconcile','sn_wallet_auto_credit','sn_coupon_allow_on_sale','sn_payment_reward_sms_enabled','sn_customer_portal_invite_sms_enabled','sn_invoice_info_show_product_info','sn_invoice_info_show_short_desc','sn_invoice_info_show_price','sn_invoice_info_show_lottery','sn_invoice_info_show_coupon','sn_invoice_info_show_image','sn_invoice_info_show_gallery','sn_card_to_card_enabled'];
		foreach ($checkbox_fields as $checkbox_field) {
			$marker = $checkbox_field . '__present';
			if (! isset($_POST[$checkbox_field]) && ! isset($_POST[$marker])) {
				continue;
			}
			update_option($checkbox_field, isset($_POST[$checkbox_field]) ? '1' : '0', false);
		}

		if (isset($_POST['sn_sales_deputy_cards']) && is_array($_POST['sn_sales_deputy_cards'])) {
			$raw_cards = wp_unslash($_POST['sn_sales_deputy_cards']);
			$cards = [];
			foreach ($raw_cards as $deputy_id => $row) {
				$deputy_id = absint($deputy_id);
				$row = is_array($row) ? $row : [];
				$raw_number = trim((string) ($row['card_number'] ?? ''));
				$number = $this->sn_normalize_payment_card_number($raw_number);
				if ($deputy_id < 1 || $raw_number === '') { continue; }
				if ($number === '') {
					SN_Helpers::send_json(false, 'شماره کارت معاون فروش ' . $this->sn_user_label($deputy_id) . ' باید دقیقاً ۱۶ رقم باشد.');
					return;
				}
				$cards[$deputy_id] = [
					'card_number' => $number,
					'card_owner' => sanitize_text_field((string) ($row['card_owner'] ?? '')),
				];
			}
			update_option('sn_sales_deputy_cards', $cards, false);
		}

		if (isset($_POST['sn_sales_manager_cards']) && is_array($_POST['sn_sales_manager_cards'])) {
			$raw_cards = wp_unslash($_POST['sn_sales_manager_cards']);
			$cards = [];
			foreach ($raw_cards as $manager_id => $row) {
				$manager_id = absint($manager_id);
				$row = is_array($row) ? $row : [];
				$raw_number = trim((string) ($row['card_number'] ?? ''));
				$number = $this->sn_normalize_payment_card_number($raw_number);
				if ($manager_id < 1 || $raw_number === '') { continue; }
				if ($number === '') {
					SN_Helpers::send_json(false, 'شماره کارت مدیر فروش ' . $this->sn_user_label($manager_id) . ' باید دقیقاً ۱۶ رقم باشد.');
					return;
				}
				$cards[$manager_id] = [
					'card_number' => $number,
					'card_owner' => sanitize_text_field((string) ($row['card_owner'] ?? '')),
				];
			}
			update_option('sn_sales_manager_cards', $cards, false);
		}

		// تنظیمات یکجای گردونه/قرعه‌کشی محصولات از صفحه تنظیمات؛ additive و هماهنگ با product meta ووکامرس.
		if (isset($_POST['sn_product_wheel']) && is_array($_POST['sn_product_wheel'])) {
			$wheel_products = wp_unslash($_POST['sn_product_wheel']);
			foreach ($wheel_products as $pid => $row) {
				$pid = absint($pid);
				if (! $pid || get_post_type($pid) !== 'product') { continue; }
				$row = is_array($row) ? $row : [];
				update_post_meta($pid, '_sn_lottery_chance_count', max(0, absint($row['lottery_chance_count'] ?? 0)));
				update_post_meta($pid, '_sn_has_lucky_wheel', ! empty($row['has_lucky_wheel']) ? '1' : '0');
				update_post_meta($pid, '_sn_payment_reward_enabled', ! empty($row['payment_reward_enabled']) ? '1' : '0');
				update_post_meta($pid, '_sn_has_discount_coupon', ! empty($row['has_discount_coupon']) ? '1' : '0');
				update_post_meta($pid, '_sn_wheel_id', sanitize_key($row['wheel_id'] ?? ''));
				update_post_meta($pid, '_sn_short_description', wp_kses_post($row['short_description'] ?? ''));
			}
		}


		// تنظیمات چند گردونه: هر گردونه چند گزینه با درصد شانس دارد و هر محصول به یکی از گردونه‌ها وصل می‌شود.
		if (isset($_POST['sn_lucky_wheels']) && is_array($_POST['sn_lucky_wheels'])) {
			$raw_wheels = wp_unslash($_POST['sn_lucky_wheels']);
			$wheels = [];
			foreach ($raw_wheels as $wheel_key => $wheel_row) {
				$wheel_row = is_array($wheel_row) ? $wheel_row : [];
				$title = sanitize_text_field($wheel_row['title'] ?? '');
				if ($title === '') { continue; }
				$id = sanitize_key($wheel_row['id'] ?? $wheel_key);
				if ($id === '' || $id === 'new') { $id = 'wheel_' . substr(md5($title . microtime(true) . wp_rand()), 0, 8); }
				$segments = [];
				if (! empty($wheel_row['segments']) && is_array($wheel_row['segments'])) {
					foreach ($wheel_row['segments'] as $seg) {
						$seg = is_array($seg) ? $seg : [];
						$label = sanitize_text_field($seg['label'] ?? '');
						$type = sanitize_key($seg['type'] ?? 'discount_coupon');
						$chance = max(0, min(100, (float) str_replace(',', '.', (string)($seg['chance'] ?? 0))));
						if ($label === '' || $chance <= 0) { continue; }
						$segments[] = [
							'label' => $label,
							'type' => in_array($type, ['discount_coupon','free_product','empty_reward','text'], true) ? $type : 'discount_coupon',
							'chance' => $chance,
							'value' => sanitize_text_field($seg['value'] ?? ''),
							'product_id' => absint($seg['product_id'] ?? 0),
						];
					}
				}
				if (!$segments) { continue; }
				$wheels[$id] = [
					'id' => $id,
					'title' => $title,
					'description' => sanitize_textarea_field($wheel_row['description'] ?? ''),
					'segments' => $segments,
				];
			}
			update_option('sn_lucky_wheels', $wheels, false);
		}

		$sms_saved = SN_SMS::save_provider_settings_from_request( $_POST );
		if ( is_wp_error( $sms_saved ) ) { SN_Helpers::send_json( false, $sms_saved->get_error_message() ); return; }

		SN_Helpers::send_json(true, 'تنظیمات ذخیره شد');
	}

	public function ajax_repair_pages(): void
	{
		if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
			SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
			return;
		}
		if (! class_exists('SN_Activator') || ! method_exists('SN_Activator', 'create_required_pages')) {
			SN_Helpers::send_json(false, 'ماژول ساخت صفحات در دسترس نیست');
			return;
		}
		$result = SN_Activator::create_required_pages();
		update_option('sn_pages_repair_version', SN_VERSION);
		$duplicate_count = 0;
		foreach ($result as $item) {
			$duplicate_count += isset($item['duplicates']) && is_array($item['duplicates']) ? count($item['duplicates']) : 0;
		}
		$message = $duplicate_count > 0
			? 'صفحات سیستم بررسی و اصلاح شدند. ' . $duplicate_count . ' صفحه مشابه/تکراری گزارش شد و حذف نشد.'
			: 'صفحات سیستم بررسی و اصلاح شدند و duplicate فعالی پیدا نشد.';
		SN_Helpers::send_json(true, $message, ['pages' => $result, 'duplicates' => get_option('sn_page_duplicate_report', [])]);
	}

	// =========================================================
	// AJAX - SELLER
	// =========================================================

	public function ajax_create_invoice(): void
	{
		// پاک کردن هر output قبلی که ممکنه از jwt یا پلاگین دیگه‌ای باشه
		if (ob_get_level()) {
			ob_clean();
		}

		if (! check_ajax_referer('sn_public', 'nonce', false)) {
			error_log('SN create_invoice: nonce verification failed');
			wp_send_json_error(['message' => 'خطای امنیتی — صفحه را رفرش کنید'], 403);
			return;
		}
		$result = $this->sn_create_invoice_core($_POST);
		$payload = array_merge(['message' => (string) ($result['message'] ?? '')], (array) ($result['data'] ?? []));
		if (! empty($result['success'])) {
			wp_send_json_success($payload);
		}
		$status = (int) ($result['status'] ?? 0);
		if ($status >= 500) {
			error_log('SN create_invoice failed: ' . (string) ($result['message'] ?? 'unknown_error'));
			wp_send_json_error($payload, $status);
		}
		if (in_array($status, [401, 403], true)) {
			wp_send_json_error($payload, $status);
		}
		// Validation/business errors are valid AJAX responses. Returning them as
		// HTTP 200 keeps jQuery in its JSON branch so the seller sees the real
		// Persian reason instead of a generic "400 Bad Request" network error.
		wp_send_json_error($payload);
	}

	/**
	 * Verify and repair only the tables/columns required by invoice creation.
	 * Full runtime migrations can be marked complete on older installations even
	 * when a single dbDelta statement was rejected by the database host. Keeping
	 * this focused guard in the submit path makes full and staged invoices usable
	 * without requiring a deactivate/activate cycle.
	 */
	private function sn_ensure_invoice_creation_schema(): array
	{
		global $wpdb;
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
		$charset = $wpdb->get_charset_collate();
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$item_table = $wpdb->prefix . 'sn_invoice_items';
		$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';

		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $invoice_table)) !== $invoice_table) {
			return ['success' => false, 'message' => 'جدول فاکتورها در دیتابیس موجود نیست؛ افزونه را یک‌بار غیرفعال و فعال کنید.'];
		}

		$invoice_columns = (array) $wpdb->get_col("SHOW COLUMNS FROM {$invoice_table}", 0);
		$invoice_definitions = [
			'catalog_discounts_snapshot' => 'LONGTEXT DEFAULT NULL',
			'catalog_manager_user_id' => 'BIGINT UNSIGNED DEFAULT NULL',
			'original_total' => 'DECIMAL(18,2) DEFAULT NULL',
			'discount_amount' => 'DECIMAL(18,2) DEFAULT NULL',
			'discount_total' => 'DECIMAL(18,2) DEFAULT NULL',
			'customer_phone_secondary' => 'VARCHAR(20) DEFAULT NULL',
			'access_token' => 'VARCHAR(96) DEFAULT NULL',
			'short_code' => 'VARCHAR(32) DEFAULT NULL',
			'invoice_status' => 'VARCHAR(60) DEFAULT NULL',
			'payment_status' => 'VARCHAR(60) DEFAULT NULL',
			'payment_card_number' => 'VARCHAR(32) DEFAULT NULL',
			'payment_card_owner' => 'VARCHAR(191) DEFAULT NULL',
			'payment_card_sales_manager_user_id' => 'BIGINT UNSIGNED DEFAULT NULL',
			'payment_card_deputy_user_id' => 'BIGINT UNSIGNED DEFAULT NULL',
			'final_total' => 'DECIMAL(18,2) DEFAULT NULL',
			'payment_plan' => "VARCHAR(20) NOT NULL DEFAULT 'full'",
			'payment_total_amount' => 'DECIMAL(18,2) DEFAULT NULL',
			'current_due_amount' => 'DECIMAL(18,2) DEFAULT NULL',
			'paid_total_amount' => 'DECIMAL(18,2) NOT NULL DEFAULT 0',
			'remaining_amount' => 'DECIMAL(18,2) DEFAULT NULL',
			'current_payment_stage' => 'INT UNSIGNED NOT NULL DEFAULT 1',
			'payment_workflow_status' => "VARCHAR(60) NOT NULL DEFAULT 'awaiting_payment'",
			'current_stage_issued_by_user_id' => 'BIGINT UNSIGNED DEFAULT NULL',
			'payment_completed_at' => 'DATETIME DEFAULT NULL',
			'customer_address' => 'TEXT DEFAULT NULL',
			'customer_postal_code' => 'VARCHAR(20) DEFAULT NULL',
			'referral_item_id' => 'BIGINT UNSIGNED DEFAULT NULL',
		];
		$repair_errors = [];
		foreach ($invoice_definitions as $column => $definition) {
			if (! in_array($column, $invoice_columns, true)) {
				if (false === $wpdb->query("ALTER TABLE {$invoice_table} ADD COLUMN {$column} {$definition}")) {
					$repair_errors[] = $invoice_table . '.' . $column;
				} else {
					$invoice_columns[] = $column;
				}
			}
		}

		$item_required = ['invoice_id', 'product_id', 'product_name', 'qty', 'unit_price', 'total_price', 'created_at'];
		$stage_required = ['invoice_id', 'stage_no', 'stage_type', 'requested_amount', 'status', 'issued_by_user_id', 'note', 'created_at', 'updated_at'];
		$table_needs_repair = static function (string $table, array $columns) use ($wpdb): bool {
			if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) { return true; }
			$existing = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
			return (bool) array_diff($columns, $existing);
		};

		if ($table_needs_repair($item_table, $item_required)) {
			dbDelta("CREATE TABLE {$item_table} (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			invoice_id BIGINT UNSIGNED NOT NULL,
			product_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
			product_name VARCHAR(255) NOT NULL,
			qty INT UNSIGNED NOT NULL DEFAULT 1,
			unit_price DECIMAL(18,2) NOT NULL DEFAULT 0,
			total_price DECIMAL(18,2) NOT NULL DEFAULT 0,
			is_free TINYINT(1) NOT NULL DEFAULT 0,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY invoice_id (invoice_id),
			KEY product_id (product_id)
		) {$charset};");
		}
		if ($table_needs_repair($stage_table, $stage_required)) {
			dbDelta("CREATE TABLE {$stage_table} (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			invoice_id BIGINT UNSIGNED NOT NULL,
			stage_no INT UNSIGNED NOT NULL DEFAULT 1,
			stage_type VARCHAR(30) NOT NULL DEFAULT 'full',
			requested_amount DECIMAL(18,2) NOT NULL DEFAULT 0,
			status VARCHAR(60) NOT NULL DEFAULT 'pending',
			pay_method VARCHAR(30) DEFAULT NULL,
			payment_source VARCHAR(60) DEFAULT NULL,
			payment_ref_id VARCHAR(191) DEFAULT NULL,
			receipt_urls LONGTEXT DEFAULT NULL,
			issued_by_user_id BIGINT UNSIGNED DEFAULT NULL,
			approved_by_user_id BIGINT UNSIGNED DEFAULT NULL,
			approved_at DATETIME DEFAULT NULL,
			paid_at DATETIME DEFAULT NULL,
			note TEXT DEFAULT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			UNIQUE KEY invoice_stage (invoice_id, stage_no),
			KEY invoice_id (invoice_id),
			KEY status (status)
		) {$charset};");
		}

		$required = [
			$invoice_table => ['invoice_code', 'access_token', 'seller_id', 'customer_name', 'customer_phone', 'product_id', 'product_price', 'payment_plan', 'payment_total_amount', 'current_due_amount', 'paid_total_amount', 'remaining_amount', 'current_payment_stage', 'payment_workflow_status', 'status', 'created_at'],
			$item_table => $item_required,
			$stage_table => $stage_required,
		];
		foreach ($required as $table => $columns) {
			if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
				$repair_errors[] = $table;
				continue;
			}
			$existing = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
			foreach ($columns as $column) {
				if (! in_array($column, $existing, true)) { $repair_errors[] = $table . '.' . $column; }
			}
		}
		if ($repair_errors) {
			return ['success' => false, 'message' => 'ساختار دیتابیس صدور فاکتور کامل نشد: ' . implode('، ', array_unique($repair_errors))];
		}
		return ['success' => true];
	}

	/**
	 * Create the fixed-product source invoice used by the public Dot marketing form.
	 * This is a trusted internal entry point: product, seller and supervisor are
	 * resolved server-side by SN_Dot_Flow and no seller/session data is accepted
	 * from the visitor. It deliberately does not send the ordinary invoice SMS.
	 */
	public function create_dot_marketing_source_invoice(array $customer, int $product_id, int $seller_id, int $supervisor_id, bool $subscription_form = false): array
	{
		$this->maybe_create_tables();
		$schema = $this->sn_ensure_invoice_creation_schema();
		if (empty($schema['success'])) {
			return ['success' => false, 'message' => (string) ($schema['message'] ?? 'ساختار دیتابیس صدور فاکتور آماده نیست.'), 'status' => 500];
		}
		if (! class_exists('SN_Dot_Flow')) {
			return ['success' => false, 'message' => 'ماژول دات فلو در دسترس نیست.', 'status' => 500];
		}
		$name = sanitize_text_field((string) ($customer['customer_name'] ?? ''));
		$phone = SN_Helpers::normalize_mobile(sanitize_text_field((string) ($customer['customer_phone'] ?? '')));
		$province = sanitize_text_field((string) ($customer['province'] ?? ''));
		$city = sanitize_text_field((string) ($customer['city'] ?? ''));
		$form_id = sanitize_key( (string) ( $customer['marketing_form_id'] ?? 'default' ) );
		if ($name === '' || ! SN_Helpers::is_valid_mobile($phone) || $province === '' || $city === '') {
			return ['success' => false, 'message' => 'نام، شماره موبایل، استان و شهر را کامل وارد کنید.', 'status' => 400];
		}
		$seller = get_user_by('id', $seller_id);
		$valid_seller = $subscription_form
			? (string) get_user_meta( $seller_id, '_sn_subscription_form_seller', true ) === '1' && (int) get_user_meta( $seller_id, '_sn_subscription_form_supervisor', true ) === $supervisor_id
			: (string) get_user_meta( $seller_id, '_sn_dot_marketing_seller', true ) === '1' && (int) get_user_meta( $seller_id, '_sn_dot_marketing_supervisor', true ) === $supervisor_id;
		if (! $seller || ! $valid_seller) {
			return ['success' => false, 'message' => 'فروشنده سیستمی مارکتینگ معتبر نیست.', 'status' => 403];
		}
		if (! function_exists('wc_get_product')) {
			return ['success' => false, 'message' => 'ووکامرس فعال نیست.', 'status' => 500];
		}
		$product = wc_get_product($product_id);
		if (! $product || get_post_status($product_id) !== 'publish' || (string) get_post_meta($product_id, '_sn_enabled', true) !== '1') {
			return ['success' => false, 'message' => 'محصول ثابت مارکتینگ دات فلو معتبر یا فعال نیست.', 'status' => 400];
		}
		if (class_exists('SN_Projects') && SN_Projects::instance()->is_content_product($product_id)) {
			return ['success' => false, 'message' => 'این محصول نمی‌تواند به‌عنوان محصول ورودی مارکتینگ دات فلو استفاده شود.', 'status' => 403];
		}
		if ( $subscription_form && ( ! class_exists( 'SN_Projects' ) || ! SN_Projects::instance()->is_subscription_product( $product_id ) || (int) get_post_meta( $product_id, '_sn_subscription_form_supervisor', true ) !== $supervisor_id ) ) {
			return ['success' => false, 'message' => 'محصول اشتراک یا سرپرست این فرم معتبر نیست.', 'status' => 403];
		}
		$total = (float) $product->get_price();
		if ($total <= 0) {
			return ['success' => false, 'message' => 'مبلغ محصول ثابت باید بیشتر از صفر باشد تا پرداخت درگاهی انجام شود.', 'status' => 400];
		}
		$marketing_config = $subscription_form ? [] : SN_Dot_Flow::instance()->marketing_config_for_form( $form_id );
		$dot_context = $subscription_form ? [] : SN_Dot_Flow::instance()->prepare_marketing_invoice_context($product_id, $seller_id, $supervisor_id, $marketing_config);
		if (is_wp_error($dot_context)) {
			return ['success' => false, 'message' => $dot_context->get_error_message(), 'status' => 403];
		}

		global $wpdb;
		try {
			$code = $this->sn_generate_invoice_code();
		} catch (RuntimeException $e) {
			return ['success' => false, 'message' => 'تولید کد فاکتور ممکن نشد.', 'status' => 500];
		}
		$access_token = SN_Helpers::generate_unique_access_token();
		$now = current_time('mysql');
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$item_table = $wpdb->prefix . 'sn_invoice_items';
		$invoice_data = $this->sn_filter_existing_columns_fresh($invoice_table, [
			'invoice_code' => $code,
			'access_token' => $access_token,
			'seller_id' => $seller_id,
			'lead_id' => absint( $customer['lead_id'] ?? 0 ) ?: null,
			'customer_name' => $name,
			'customer_phone' => $phone,
			'province' => $province,
			'city' => $city,
			'national_id' => sanitize_text_field( (string) ( $customer['national_id'] ?? '' ) ),
			'product_id' => $product_id,
			'product_price' => $total,
			'final_total' => $total,
			'payment_plan' => 'full',
			'payment_total_amount' => $total,
			'current_due_amount' => $total,
			'paid_total_amount' => 0,
			'remaining_amount' => $total,
			'current_payment_stage' => 1,
			'payment_workflow_status' => 'awaiting_payment',
			'current_stage_issued_by_user_id' => $seller_id,
			'payment_card_number' => '',
			'payment_card_owner' => '',
			'payment_card_sales_manager_user_id' => null,
			'payment_card_deputy_user_id' => null,
			'status' => 'pre_invoice',
			'created_at' => $now,
			'updated_at' => $now,
			'issued_by_user_id' => $seller_id,
			'original_seller_id' => $seller_id,
		]);

		$wpdb->query('START TRANSACTION');
		if (! $wpdb->insert($invoice_table, $invoice_data)) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'ذخیره فاکتور مارکتینگ انجام نشد: ' . ($wpdb->last_error ?: 'خطای دیتابیس'), 'status' => 500];
		}
		$invoice_id = (int) $wpdb->insert_id;
		if (! $this->sn_create_invoice_payment_stage($invoice_id, 1, 'full', $total, $seller_id, 'پرداخت کامل ورودی مارکتینگ دات فلو')) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'مرحله پرداخت مارکتینگ ایجاد نشد: ' . ($wpdb->last_error ?: 'خطای دیتابیس'), 'status' => 500];
		}
		$item = [
			'invoice_id' => $invoice_id,
			'product_id' => $product_id,
			'product_name' => (string) $product->get_name(),
			'product_type' => $subscription_form ? 'subscription' : 'assessment',
			'qty' => 1,
			'unit_price' => $total,
			'total_price' => $total,
			'is_free' => 0,
			'created_at' => $now,
		];
		if (! $wpdb->insert($item_table, $item)) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'قلم فاکتور مارکتینگ ثبت نشد: ' . ($wpdb->last_error ?: 'خطای دیتابیس'), 'status' => 500];
		}
		if (!$subscription_form && ! SN_Dot_Flow::instance()->register_source_invoice_in_transaction($invoice_id, $dot_context)) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'اتصال فاکتور مارکتینگ به دات فلو انجام نشد: ' . ($wpdb->last_error ?: 'خطای دیتابیس'), 'status' => 500];
		}
		$wpdb->query('COMMIT');

		$customer_wp_id = $this->get_or_create_customer_account($phone, $name);
		if ($customer_wp_id) {
			$wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, ['customer_wp_id' => $customer_wp_id]), ['id' => $invoice_id]);
			$this->sn_sync_customer_profile_from_invoice($customer_wp_id, (object) [
				'id' => $invoice_id,
				'invoice_code' => $code,
				'customer_name' => $name,
				'customer_phone' => $phone,
				'province' => $province,
				'city' => $city,
			]);
		}
		$this->sn_log_activity($invoice_id, null, 'dot_marketing_invoice_created', 'ثبت مستقیم لندینگ مارکتینگ دات فلو', [
			'seller_id' => $seller_id,
			'supervisor_id' => $supervisor_id,
			'product_id' => $product_id,
			'amount' => $total,
			'invoice_sms_sent' => false,
		]);
		return ['success' => true, 'message' => 'فاکتور مارکتینگ ایجاد شد.', 'data' => [
			'invoice_id' => $invoice_id,
			'invoice_code' => $code,
			'access_token' => $access_token,
			'customer_phone' => $phone,
			'amount' => $total,
			'customer_wp_id' => $customer_wp_id,
		]];
	}

	private function sn_create_invoice_core(array $request, bool $allow_controlled_workflow_invoice = false): array
	{
		if (! is_user_logged_in()) {
			return ['success' => false, 'message' => 'لطفاً ابتدا وارد شوید', 'status' => 401];
		}

		$this->maybe_create_tables();
		$schema = $this->sn_ensure_invoice_creation_schema();
		if (empty($schema['success'])) {
			return ['success' => false, 'message' => (string) ($schema['message'] ?? 'ساختار دیتابیس صدور فاکتور آماده نیست.'), 'status' => 500];
		}
		$user = wp_get_current_user();
		$roles = (array) $user->roles;
		$is_admin = current_user_can('manage_options');
		$actor_position = $this->sn_hr_position_for_user((int) $user->ID);
		$is_seller = in_array('sn_seller', $roles, true) || $actor_position === 'seller';
		$is_converter = in_array('sn_converter', $roles, true) || $actor_position === 'converter';
		$is_supervisor = in_array('sn_supervisor', $roles, true) || in_array($actor_position, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy'], true);
		if (! $is_admin && ! $is_seller && ! $is_converter && ! $is_supervisor) {
			return ['success' => false, 'message' => 'دسترسی غیرمجاز — مجوز صدور فاکتور ندارید', 'status' => 403];
		}
		if (! $is_admin && ! $allow_controlled_workflow_invoice && ! $this->sn_user_can_create_manual_invoice((int) $user->ID)) {
			return ['success' => false, 'message' => 'دسترسی صدور پیش‌فاکتور از پرونده برای شما در پنل HR غیرفعال شده است', 'status' => 403];
		}
		$requested_lead_id = absint($request['lead_id'] ?? 0);
		if (! $allow_controlled_workflow_invoice && $requested_lead_id < 1 && ! $this->sn_seller_manual_invoice_enabled()) {
			return ['success' => false, 'message' => 'پیش‌فاکتور فقط از داخل پرونده یا شمارهٔ تخصیص‌یافته صادر می‌شود.', 'status' => 403];
		}
		$seller_assigned_only = $is_seller && ! $is_admin;

		// Converter manual invoices are owned by the converter account itself.
		// A validated controlled workflow must retain the original seller even on
		// legacy accounts that accidentally carry more than one sales role.
		$seller_id = $allow_controlled_workflow_invoice
			? absint($request['seller_id'] ?? 0)
			: (($is_seller || $is_converter) ? (int) $user->ID : absint($request['seller_id'] ?? 0));
		if (! $seller_id) {
			return ['success' => false, 'message' => 'فروشنده نامعتبر است'];
		}
		$seller_user = get_user_by('id', $seller_id);
		$seller_owner_position = $seller_user ? $this->sn_hr_position_for_user($seller_id) : '';
		$seller_owner_roles = $seller_user ? (array) $seller_user->roles : [];
		$seller_owner_valid = $seller_user && (
			in_array('sn_seller', $seller_owner_roles, true)
			|| $seller_owner_position === 'seller'
			|| (($is_converter || $is_admin) && (in_array('sn_converter', $seller_owner_roles, true) || $seller_owner_position === 'converter'))
		);
		if (! $seller_owner_valid) {
			return ['success' => false, 'message' => 'صادرکننده فاکتور معتبر نیست'];
		}
		if ($is_supervisor && ! $is_admin && ! $this->sn_user_can_issue_invoice_for_seller((int) $user->ID, $seller_id)) {
			return ['success' => false, 'message' => 'این فروشنده در محدوده HR شما نیست', 'status' => 403];
		}

		$name    = sanitize_text_field(wp_unslash($request['customer_name'] ?? ''));
		$phone   = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($request['customer_phone'] ?? '')));
		$phone_secondary = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($request['customer_phone_secondary'] ?? '')));
		if ($phone_secondary !== '' && ! SN_Helpers::is_valid_mobile($phone_secondary)) {
			return ['success'=>false,'message'=>'شماره دوم مشتری معتبر نیست.','status'=>400];
		}
		$prov    = sanitize_text_field(wp_unslash($request['province'] ?? ''));
		$city    = sanitize_text_field(wp_unslash($request['city'] ?? ''));
		// Keep the canonical names used by current panels while accepting the
		// legacy aliases used by older cached/front-end forms during upgrades.
		$customer_address = sanitize_textarea_field(wp_unslash($request['customer_address'] ?? $request['address'] ?? ''));
		$customer_postal_code = preg_replace('/\D+/', '', strtr((string) wp_unslash($request['customer_postal_code'] ?? $request['postal_code'] ?? ''), ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']));
		$prod_id = absint($request['product_id'] ?? 0);
		$product_ids_raw = $request['product_ids'] ?? [];
		$qtys_raw = $request['product_qtys'] ?? [];
		if (! is_array($product_ids_raw)) { $product_ids_raw = $product_ids_raw ? explode(',', (string) $product_ids_raw) : []; }
		if (! is_array($qtys_raw)) { $qtys_raw = []; }
		$product_ids = array_values(array_filter(array_map('absint', $product_ids_raw)));
		if (! $product_ids && $prod_id) { $product_ids = [$prod_id]; }
		if (class_exists('SN_Projects')) {
			$project_validation = SN_Projects::instance()->validate_invoice_products($product_ids, (int) $user->ID);
			if (is_wp_error($project_validation)) {
				return ['success' => false, 'message' => $project_validation->get_error_message(), 'status' => 403];
			}
		}
		if (!$allow_controlled_workflow_invoice && class_exists('SN_Dot_Flow') && array_intersect($product_ids, SN_Dot_Flow::instance()->marketing_form_product_ids())) {
			return ['success'=>false,'message'=>'محصول فرم دات‌فلو برای فروش مستقل در پنل فروشنده قابل انتخاب نیست؛ ثبت آن از فرم مربوطه انجام می‌شود.','status'=>403];
		}
		if (class_exists('SN_Seller_Flow')) {
			$product_type_validation = SN_Seller_Flow::instance()->validate_invoice_product_types($product_ids, $qtys_raw);
			if (is_wp_error($product_type_validation)) {
				return ['success' => false, 'message' => $product_type_validation->get_error_message(), 'status' => 400];
			}
			if (! $allow_controlled_workflow_invoice) {
				foreach ($product_ids as $selected_product_id) {
					if (! SN_Seller_Flow::instance()->standalone_sale_visible($selected_product_id)) {
						return ['success' => false, 'message' => 'فروش مستقل این محصول* در تنظیمات محصول غیرفعال است.', 'status' => 403];
					}
				}
			}
		}
		$max_products = $this->sn_invoice_max_products();
		if ($max_products > 0 && count($product_ids) > $max_products) {
			return ['success' => false, 'message' => sprintf('حداکثر %d محصول در هر پیش‌فاکتور قابل انتخاب است. این مقدار از تنظیمات قابل تغییر است.', $max_products), 'status' => 400];
		}
		$lead_id = $requested_lead_id;

		global $wpdb;
		$v4_item_id_for_invoice = $this->sn_distribution_item_id_from_virtual_lead($lead_id);
		if ($v4_item_id_for_invoice > 0) {
			$item = $this->sn_distribution_load_conversion_item($v4_item_id_for_invoice);
			if (! $item) {
				return ['success' => false, 'message' => 'شماره تحویل‌شده یافت نشد'];
			}
			$is_owner = (int) ($item->current_owner_user_id ?? 0) === (int) $seller_id || (int) ($item->current_owner_user_id ?? 0) === (int) $user->ID;
			if (! $is_owner && ! $is_admin) {
				return ['success' => false, 'message' => 'این شماره به فروشنده انتخاب‌شده تحویل نشده است', 'status' => 403];
			}
			if (class_exists('SN_Seller_Flow') && SN_Seller_Flow::instance()->is_archived('v4_distribution_item', $v4_item_id_for_invoice)) {
				return ['success' => false, 'message' => 'این شماره در بایگانی مدیر فروش قرار دارد و از پنل فروشنده قابل صدور پیش‌فاکتور نیست.', 'status' => 403];
			}
			$item_name = (string) ($item->customer_name ?? '');
			$item_phone = SN_Helpers::normalize_mobile((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? '')));
			$item_province = (string) ($item->province ?? '');
			$item_city = (string) ($item->city ?? '');
			if ((string) ($item->source_type ?? '') === 'paid_invoice_referral' && ! SN_Helpers::is_valid_mobile($item_phone)) {
				$source_invoice_id = absint(($item->ref_invoice_id ?? 0) ?: ($item->source_id ?? 0));
				$source_invoice = $source_invoice_id > 0 ? $wpdb->get_row($wpdb->prepare("SELECT customer_name,customer_phone,province,city FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $source_invoice_id)) : null;
				if ($source_invoice) {
					$item_name = $item_name ?: (string) ($source_invoice->customer_name ?? '');
					$item_phone = SN_Helpers::normalize_mobile((string) ($source_invoice->customer_phone ?? ''));
					$item_province = $item_province ?: (string) ($source_invoice->province ?? '');
					$item_city = $item_city ?: (string) ($source_invoice->city ?? '');
				}
			}
			if (empty($name)) { $name = $item_name; }
			if ($seller_assigned_only || empty($phone)) { $phone = $item_phone; }
			if (empty($prov)) { $prov = $item_province; }
			if (empty($city)) { $city = $item_city; }
			// مسیر V4 به صورت پیش‌فرض sn_leads نمی‌سازد؛ فاکتور بدون lead_id زنده ثبت می‌شود.
			$lead_id = 0;
		}

		if ($lead_id) {
			$lead = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_leads WHERE id=%d", $lead_id));
			if (! $lead) {
				return ['success' => false, 'message' => 'شماره یافت نشد'];
			}
			if ($is_seller && (int) $lead->seller_id !== (int) $user->ID) {
				return ['success' => false, 'message' => 'این شماره به شما تخصیص داده نشده است', 'status' => 403];
			}
			if ($is_supervisor && ! $is_admin && (int) $lead->supervisor_id !== (int) $user->ID && (int) get_user_meta((int) $lead->seller_id, 'sn_supervisor_id', true) !== (int) $user->ID) {
				return ['success' => false, 'message' => 'این شماره در دسترس شما نیست', 'status' => 403];
			}
			if (! $is_admin && $seller_id && (int) $lead->seller_id && (int) $lead->seller_id !== $seller_id) {
				return ['success' => false, 'message' => 'این شماره متعلق به فروشنده انتخاب‌شده نیست', 'status' => 403];
			}
			if (class_exists('SN_Seller_Flow') && SN_Seller_Flow::instance()->is_archived('legacy_lead', $lead_id)) {
				return ['success' => false, 'message' => 'این شماره در بایگانی مدیر فروش قرار دارد و از پنل فروشنده قابل صدور پیش‌فاکتور نیست.', 'status' => 403];
			}
			if ((int) $lead->seller_id) {
				$seller_id = (int) $lead->seller_id;
			}
			if (empty($name)) { $name = (string) ($lead->customer_name ?? ''); }
			if ($seller_assigned_only || empty($phone)) { $phone = SN_Helpers::normalize_mobile((string) $lead->phone); }
			if (empty($prov)) { $prov = (string) ($lead->province ?? ''); }
			if (empty($city)) { $city = (string) ($lead->city ?? ''); }
		}

		if (empty($name) || ! SN_Helpers::is_valid_mobile($phone) || ! $product_ids) {
			return ['success' => false, 'message' => 'اطلاعات ناقص است'];
		}
		if (! class_exists('WooCommerce')) {
			return ['success' => false, 'message' => 'ووکامرس فعال نیست'];
		}

		$items = [];
		$total = 0.0;
		foreach ($product_ids as $idx => $pid) {
			$product = wc_get_product($pid);
			if (! $product || get_post_status($pid) !== 'publish') {
				return ['success' => false, 'message' => 'محصول یافت نشد یا منتشر نشده است'];
			}
			if ((string) get_post_meta($pid, '_sn_enabled', true) !== '1') {
				return ['success' => false, 'message' => 'این محصول برای شبکه فروش فعال نیست', 'status' => 403];
			}
			$qty = isset($qtys_raw[$idx]) ? absint($qtys_raw[$idx]) : 1;
			if ($qty < 1) { $qty = 1; }
			$unit_price = (float) $product->get_price();
			$line_total = $unit_price * $qty;
			$total += $line_total;
			$product_type = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance()->product_type($pid) : '';
			$items[] = ['product_id' => $pid, 'product_name' => $product->get_name(), 'product_type' => $product_type ?: null, 'qty' => $qty, 'unit_price' => $unit_price, 'total_price' => $line_total, 'is_free' => 0];
		}
		$invoice_product_types = array_values(array_unique(array_filter(array_column($items, 'product_type'))));
		if (in_array('product', $invoice_product_types, true) && ($prov === '' || $city === '' || trim($customer_address) === '')) {
			return ['success' => false, 'message' => 'برای محصول عادی، استان، شهر و آدرس کامل مشتری اجباری است.', 'status' => 400];
		}
		if ($customer_postal_code !== '' && strlen($customer_postal_code) !== 10) {
			return ['success' => false, 'message' => 'کد پستی باید ۱۰ رقم باشد.', 'status' => 400];
		}

		$catalog_pricing = SN_Sales_Catalog::instance()->price_items($items, $request['catalog_discount_ids'] ?? [], (int) $user->ID, (int) $seller_id);
		if (is_wp_error($catalog_pricing)) { return ['success' => false, 'message' => $catalog_pricing->get_error_message(), 'status' => 403]; }
		$total = $catalog_pricing['final_total'];

		$payment_plan = sanitize_key((string) ($request['payment_plan'] ?? $request['payment_mode'] ?? 'full'));
		if (! in_array($payment_plan, ['full','partial'], true)) { $payment_plan = 'full'; }
		$initial_due = $total;
		if ($payment_plan === 'partial') {
			$initial_due = $this->sn_parse_money_value($request['prepayment_amount'] ?? $request['payment_amount'] ?? 0);
			if ($initial_due <= 0) { return ['success'=>false,'message'=>'مبلغ پیش‌پرداخت باید بیشتر از صفر باشد']; }
			if ($initial_due - $total > 0.5) { return ['success'=>false,'message'=>'مبلغ مرحله پرداخت نمی‌تواند از مبلغ کل فاکتور بیشتر باشد.']; }
			// A custom staged amount equal to the invoice total is a full first stage.
			// Normalize it instead of rejecting the seller's valid choice.
			if ( abs( $initial_due - $total ) <= 0.5 ) { $payment_plan = 'full'; $initial_due = $total; }
		}
		if ($payment_plan === 'partial' && class_exists('SN_Dot_Flow')) {
			foreach ($product_ids as $product_id) {
				if (SN_Dot_Flow::instance()->is_assessment_product((int) $product_id)) {
					return ['success'=>false,'message'=>'برای محصول اعتبارسنجی پیش‌پرداخت مرحله‌ای مجاز نیست. پرداخت کامل را انتخاب کنید.','status'=>400];
				}
			}
		}
		$dot_context = [];
		if (class_exists('SN_Dot_Flow')) {
			$is_assessment_invoice = in_array('assessment', $invoice_product_types, true);
			$current_decision_ui = (string) wp_unslash($request['dot_assessment_decision_ui'] ?? '') === '1';
			$dot_route_choice_present = array_key_exists('dot_conversion_route', $request);
			$dot_conversion_route = sanitize_key((string) wp_unslash($request['dot_conversion_route'] ?? 'supervisor_queue'));
			$dot_sms_choice_present = array_key_exists('dot_send_assessment_sms', $request);
			$dot_sms_choice_raw = strtolower(trim((string) wp_unslash($request['dot_send_assessment_sms'] ?? '1')));
			if ($is_assessment_invoice && $current_decision_ui) {
				if (! $dot_sms_choice_present || ! in_array($dot_sms_choice_raw, ['0','1'], true)) {
					return ['success'=>false, 'message'=>'ابتدا وضعیت «ارسال پیامک نتیجه اعتبارسنجی» را انتخاب کنید.', 'status'=>400];
				}
				if (! $dot_route_choice_present || ! in_array($dot_conversion_route, ['supervisor_queue', 'seller_self'], true)) {
					return ['success'=>false, 'message'=>'پس از انتخاب وضعیت پیامک، گزینه «ارسال برای سرپرست / تبدیل توسط خودم» را انتخاب کنید.', 'status'=>400];
				}
			}
			// Missing is a legacy form/client and intentionally preserves the old
			// behavior. Only the owning seller may suppress this customer SMS.
			$dot_send_assessment_sms = ! $dot_sms_choice_present || in_array($dot_sms_choice_raw, ['1','true','yes','on'], true);
			if (! in_array($dot_conversion_route, ['supervisor_queue', 'seller_self'], true)) {
				$dot_conversion_route = 'supervisor_queue';
			}
			if (! $is_assessment_invoice) {
				$dot_conversion_route = 'supervisor_queue';
				$dot_send_assessment_sms = true;
			} elseif ($dot_conversion_route === 'seller_self' && (! $is_seller || (int) $user->ID !== (int) $seller_id)) {
				return ['success'=>false, 'message'=>'گزینه «تبدیل توسط خودم» فقط برای فروشنده‌ای مجاز است که فاکتور اعتبارسنجی را برای مشتری خودش ثبت می‌کند.', 'status'=>403];
			}
			if (! $is_seller || (int) $user->ID !== (int) $seller_id) { $dot_send_assessment_sms = true; }
			$dot_context = SN_Dot_Flow::instance()->prepare_invoice_context($product_ids, $seller_id, $payment_plan, array_column($items, 'qty'), $dot_conversion_route, $dot_send_assessment_sms);
			if (is_wp_error($dot_context)) {
				return ['success'=>false, 'message'=>$dot_context->get_error_message(), 'status'=>403];
			}
		}

		try {
			$code = $this->sn_generate_invoice_code();
		} catch (RuntimeException $e) {
			return ['success' => false, 'message' => 'تولید کد شش‌رقمی فاکتور ممکن نشد. لطفاً وضعیت کدهای فاکتور را در یکپارچه‌سازی بررسی کنید.', 'status' => 500];
		}
		$access_token = SN_Helpers::generate_unique_access_token();
		$prod_id = (int) $items[0]['product_id'];
		$invoice_card = $this->sn_resolve_sales_manager_card_for_seller($seller_id);
		$invoice_data = $this->sn_filter_existing_columns_fresh($wpdb->prefix . 'sn_invoices', [
			'invoice_code'   => $code,
			'access_token'   => $access_token,
			'seller_id'      => $seller_id,
			'lead_id'        => $lead_id ?: null,
			'customer_name'  => $name,
			'customer_phone' => $phone,
			'customer_phone_secondary' => $phone_secondary ?: null,
			'province'       => $prov,
			'city'           => $city,
			'customer_address' => $customer_address ?: null,
			'customer_postal_code' => $customer_postal_code ?: null,
			'product_id'     => $prod_id,
			// Keep the legacy product_price field aligned with the payable total.
			// Gross value remains available in original_total and the catalog snapshot.
			'product_price'  => $total,
			'original_total' => $catalog_pricing['original_total'],
			'discount_amount' => $catalog_pricing['discount_total'],
			'discount_total' => $catalog_pricing['discount_total'],
			'catalog_discounts_snapshot' => wp_json_encode($catalog_pricing['snapshot']),
			'catalog_manager_user_id' => $catalog_pricing['manager_user_id'] ?: null,
			'final_total'    => $total,
			'payment_plan' => $payment_plan,
			'payment_total_amount' => $total,
			'current_due_amount' => $initial_due,
			'paid_total_amount' => 0,
			'remaining_amount' => $total,
			'current_payment_stage' => 1,
			'payment_workflow_status' => 'awaiting_payment',
			'current_stage_issued_by_user_id' => (int) $user->ID,
			'payment_card_number' => (string) ($invoice_card['number'] ?? ''),
			'payment_card_owner' => (string) ($invoice_card['owner'] ?? ''),
			'payment_card_sales_manager_user_id' => absint($invoice_card['sales_manager_user_id'] ?? 0) ?: null,
			'payment_card_deputy_user_id' => absint($invoice_card['deputy_user_id'] ?? 0) ?: null,
			'status'         => 'pre_invoice',
			'created_at'     => current_time('mysql'),
			'updated_at'     => current_time('mysql'),
			'issued_by_user_id' => (int) $user->ID,
			'original_seller_id' => $seller_id,
			'referral_item_id' => absint($request['sn_paid_referral_item_id'] ?? 0),
		]);
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$item_table = $wpdb->prefix . 'sn_invoice_items';
		$pre_invoice_lead_status = 'پیش‌فاکتور';
		$this->sn_ensure_pre_invoice_lead_status();
		if (! empty($v4_item_id_for_invoice)) {
			// Schema repairs may issue DDL and therefore must run before opening the
			// invoice transaction. The actual source update remains transactional.
			$this->sn_distribution_ensure_seller_inline_columns();
		}
		$wpdb->query('START TRANSACTION');

		// Lock the live source before any seller-flow state lock. The archive job
		// uses the same source -> shared-state order, so a concurrent archive or
		// reassignment cannot leave the invoice and source in different states.
		if ($lead_id) {
			$locked_source = $wpdb->get_row($wpdb->prepare(
				"SELECT id,seller_id FROM {$wpdb->prefix}sn_leads WHERE id=%d LIMIT 1 FOR UPDATE",
				$lead_id
			));
			if (! $locked_source) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ شماره منبع هنگام ثبت نهایی در دسترس نبود.','status'=>409];
			}
			if ((int) ($locked_source->seller_id ?? 0) > 0 && (int) $locked_source->seller_id !== (int) $seller_id) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'مالک شماره هنگام صدور پیش‌فاکتور تغییر کرده است؛ صفحه را تازه‌سازی کنید.','status'=>409];
			}
		}
		if (! empty($v4_item_id_for_invoice)) {
			$locked_source = $wpdb->get_row($wpdb->prepare(
				"SELECT id,current_owner_user_id FROM {$wpdb->prefix}sn_distribution_items WHERE id=%d LIMIT 1 FOR UPDATE",
				(int) $v4_item_id_for_invoice
			));
			if (! $locked_source) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ شماره توزیع‌شده هنگام ثبت نهایی در دسترس نبود.','status'=>409];
			}
			$locked_owner_id = (int) ($locked_source->current_owner_user_id ?? 0);
			if (! $is_admin && $locked_owner_id !== (int) $seller_id && $locked_owner_id !== (int) $user->ID) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'مالک شماره توزیع‌شده هنگام صدور پیش‌فاکتور تغییر کرده است؛ صفحه را تازه‌سازی کنید.','status'=>409];
			}
		}
		$inserted = $wpdb->insert($invoice_table, $invoice_data);
		if (! $inserted) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'ذخیره فاکتور انجام نشد: ' . ($wpdb->last_error ?: 'خطای نامشخص'), 'status' => 500];
		}
		$invoice_id = (int) $wpdb->insert_id;
		$stored_access_token = (string) $wpdb->get_var($wpdb->prepare("SELECT access_token FROM {$invoice_table} WHERE id=%d", $invoice_id));
		if ($stored_access_token === '' && in_array('access_token', $this->sn_table_columns($invoice_table), true)) {
			$access_token = SN_Helpers::generate_unique_access_token();
			$token_updated = $wpdb->update($invoice_table, ['access_token' => $access_token], ['id' => $invoice_id]);
			if ($token_updated === false) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ ذخیره توکن لینک عمومی با خطا مواجه شد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
			}
		} elseif ($stored_access_token !== '') {
			$access_token = $stored_access_token;
		}
		$invoice_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $invoice_id));
		if (! $invoice_row || empty($invoice_row->access_token)) {
			$wpdb->query('ROLLBACK');
			return ['success' => false, 'message' => 'فاکتور ایجاد نشد؛ توکن لینک عمومی قابل ذخیره نبود.', 'status' => 500];
		}
		$access_token = (string) $invoice_row->access_token;
		if (! $this->sn_create_invoice_payment_stage($invoice_id, 1, $payment_plan, $initial_due, (int) $user->ID, $payment_plan === 'partial' ? 'پیش‌پرداخت اولیه' : 'پرداخت کامل')) {
			$wpdb->query('ROLLBACK');
			return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ ثبت مرحله پرداخت اولیه با خطا مواجه شد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
		}
		foreach ($items as $it) {
			$item_data = $this->sn_filter_existing_columns_fresh($item_table, $it + ['invoice_id' => $invoice_id, 'created_at' => current_time('mysql')]);
			$item_inserted = $wpdb->insert($item_table, $item_data);
			if (! $item_inserted) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ ثبت اقلام فاکتور با خطا مواجه شد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
			}
		}
		if ($dot_context && class_exists('SN_Dot_Flow') && ! SN_Dot_Flow::instance()->register_source_invoice_in_transaction($invoice_id, $dot_context)) {
			$wpdb->query('ROLLBACK');
			return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ اتصال امن آن به فلو اعتبارسنجی با خطا مواجه شد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
		}
		if ($lead_id) {
			$lead_status_updated = $wpdb->update($wpdb->prefix . 'sn_leads', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_leads', [
				'status' => 'invoiced',
				'lead_status' => $pre_invoice_lead_status,
				'updated_at' => current_time('mysql'),
			]), ['id' => $lead_id]);
			if ($lead_status_updated === false) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ وضعیت شماره منبع ذخیره نشد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
			}
		}
		if (! empty($v4_item_id_for_invoice)) {
			$item_table_for_invoice_status = $wpdb->prefix . 'sn_distribution_items';
			$v4_status_updated = $wpdb->update($item_table_for_invoice_status, $this->sn_distribution_filter_existing_columns_fresh($item_table_for_invoice_status, [
				'seller_contact_status' => $pre_invoice_lead_status,
				'seller_updated_by' => (int) $user->ID,
				'seller_updated_at' => current_time('mysql'),
				'updated_at' => current_time('mysql'),
				'follow_invoice_id' => $invoice_id,
			]), ['id' => (int) $v4_item_id_for_invoice]);
			if ($v4_status_updated === false) {
				$wpdb->query('ROLLBACK');
				return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ وضعیت شماره توزیع‌شده ذخیره نشد: '.($wpdb->last_error ?: 'خطای دیتابیس'),'status'=>500];
			}
		}
		if (class_exists('SN_Seller_Flow')) {
			$flow_source_kind = ! empty($v4_item_id_for_invoice) ? 'v4_distribution_item' : 'legacy_lead';
			$flow_source_id = ! empty($v4_item_id_for_invoice) ? (int) $v4_item_id_for_invoice : (int) $lead_id;
			if ($flow_source_id > 0) {
				$flow_result = SN_Seller_Flow::instance()->apply_activity([
					'source_kind' => $flow_source_kind,
					'source_id' => $flow_source_id,
					'seller_user_id' => $seller_id,
					'actor_user_id' => (int) $user->ID,
					'status_label' => 'پیش‌فاکتور',
					'status_changed' => true,
					'invoice_id' => $invoice_id,
					'changed_field' => 'invoice_created',
				]);
				if (is_wp_error($flow_result)) {
					$wpdb->query('ROLLBACK');
					return ['success'=>false,'message'=>'فاکتور ایجاد نشد؛ ثبت یکپارچه وضعیت مرحله فروشنده ناموفق بود: '.$flow_result->get_error_message(),'status'=>500];
				}
			}
		}
		$wpdb->query('COMMIT');
		$invoice_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $invoice_id));

		if ($is_converter && (int) $user->ID === (int) $seller_id) {
			$invoice_actor_action = 'invoice_created_by_converter';
			$invoice_actor_message = 'صدور پیش‌فاکتور دستی توسط تبدیل‌کننده';
		} else {
			$invoice_actor_action = ((int) $user->ID === (int) $seller_id) ? 'invoice_created' : 'invoice_created_by_supervisor_for_seller';
			$invoice_actor_message = ((int) $user->ID === (int) $seller_id) ? 'صدور پیش‌فاکتور توسط فروشنده' : 'صدور پیش‌فاکتور توسط سرپرست برای فروشنده';
		}
		$this->sn_log_activity($invoice_id, $lead_id ?: null, $invoice_actor_action, $invoice_actor_message, ['seller_id' => $seller_id, 'issued_by_user_id' => (int) $user->ID, 'product_ids' => $product_ids, 'amount' => $total, 'payment_plan'=>$payment_plan, 'current_due_amount'=>$initial_due, 'dot_conversion_route'=>(string) ($dot_context['conversion_route'] ?? ''), 'dot_send_assessment_sms'=>isset($dot_context['send_assessment_sms']) ? (int) $dot_context['send_assessment_sms'] : null, 'referral_item_id' => absint($request['sn_paid_referral_item_id'] ?? 0)]);

		$customer_wp_id = $this->get_or_create_customer_account($phone, $name);
		if ($customer_wp_id) {
			$wpdb->update($wpdb->prefix . 'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_invoices', ['customer_wp_id' => $customer_wp_id]), ['id' => $invoice_id]);
			$this->sn_sync_customer_profile_from_invoice($customer_wp_id, (object) [
				'id' => $invoice_id, 'invoice_code' => $code, 'customer_name' => $name, 'customer_phone' => $phone, 'province' => $prov, 'city' => $city
			]);
		}

		// The invoice is already committed; an SMS failure must not look like a failed creation.
		$sms_sent = false;
		$sms_error = '';
		try {
			$invoice_url = $this->sn_invoice_public_url($invoice_row);
			$amount = number_format($initial_due, 0, '', ',');
			$card_number = $this->sn_card_to_card_enabled() ? (string) ($this->sn_resolve_invoice_card($invoice_row)['number'] ?? '') : '';
			$sms = new SN_SMS();
			$sms_sent = $sms->send_invoice_link($phone, $code, $invoice_url, $name, $amount, $card_number);
			$sms_error = $sms->get_last_error();
		} catch (Throwable $error) {
			$sms_error = 'خطا در اجرای ارسال پیامک؛ جزئیات در گزارش خطای سرور ثبت شد.';
			error_log('SN invoice created #' . $invoice_id . ', SMS failed: ' . $error->getMessage());
		}
		$message = 'پیش‌فاکتور با موفقیت صادر شد.';

		return ['success' => true, 'message' => $message, 'data' => [
			'sms_sent' => $sms_sent,
			'sms_status' => $sms_sent ? 'sent' : 'failed',
			'sms_message' => $sms_sent ? 'درخواست پیامک توسط سرویس پذیرفته شد.' : ('پیش‌فاکتور صادر شد. ' . ($sms_error ?: 'ارسال پیامک تأیید نشد؛ تنظیمات سرویس پیامک را بررسی کنید.')),
			'invoice_id' => $invoice_id,
			'invoice_code' => $code,
			'code' => $code,
			'customer_wp_id' => $customer_wp_id,
			'payment_plan' => $payment_plan,
			'payment_total_amount' => $total,
			'current_due_amount' => $initial_due,
			'remaining_amount' => $total,
			'dot_conversion_route' => (string) ($dot_context['conversion_route'] ?? ''),
			'dot_conversion_route_label' => ! empty($dot_context) ? ((string) ($dot_context['conversion_route'] ?? '') === 'seller_self' ? 'تبدیل توسط خودم' : 'ارسال برای سرپرست') : '',
			'dot_send_assessment_sms' => isset($dot_context['send_assessment_sms']) ? (int) $dot_context['send_assessment_sms'] : null,
			'dot_send_assessment_sms_label' => ! empty($dot_context) ? (! empty($dot_context['send_assessment_sms']) ? 'ارسال پیامک نتیجه اعتبارسنجی' : 'عدم ارسال پیامک نتیجه اعتبارسنجی؛ ورود مستقیم به تبدیل') : '',
		]];
	}

	/**
	 * Fallback: صدور فاکتور از طریق form POST (برای وقتی AJAX مشکل داره)
	 */
	public function handle_create_invoice_post(): void
	{
		if (! is_user_logged_in()) {
			$auth = (int) get_option('sn_auth_page_id');
			wp_redirect($auth ? get_permalink($auth) : home_url());
			exit;
		}
		if (! wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['nonce'] ?? '')), 'sn_public')) {
			wp_safe_redirect(add_query_arg('sn_err_inv', rawurlencode('خطای امنیتی — صفحه را رفرش کنید'), wp_get_referer() ?: home_url()));
			exit;
		}
		$result = $this->sn_create_invoice_core($_POST);
		$data = array_merge(['success' => false, 'message' => 'خطا'], $result, (array) ($result['data'] ?? []));
		$panel = (int) get_option('sn_seller_panel_page_id');
		$back  = $panel ? get_permalink($panel) : home_url();
		if ($data && $data['success']) {
			wp_safe_redirect(add_query_arg('sn_ok', rawurlencode((string) $data['invoice_code']), $back));
		} else {
			$msg = $data['message'] ?? 'خطا';
			wp_safe_redirect(add_query_arg('sn_err_inv', rawurlencode($msg), $back));
		}
		exit;
	}

	/**
	 * پیدا کردن یا ساخت حساب کاربری مشتری بر اساس شماره موبایل.
	 * با پلاگین Digits سازگار است — username = شماره موبایل.
	 */
	private function get_or_create_customer_account(string $phone, string $name): int
	{
		$phone = SN_Helpers::normalize_mobile($phone);
		// اول چک کن آیا کاربری با این شماره وجود دارد؛ برای پرسنل HR نباید پروفایل مشتری ساخته/آپدیت شود.
		$existing = get_user_by('login', $phone);
		if (! $existing instanceof WP_User && method_exists($this, 'sn_find_user_by_lookup')) {
			$lookup_user = $this->sn_find_user_by_lookup($phone);
			if ($lookup_user instanceof WP_User) { $existing = $lookup_user; }
		}
		if ($existing) {
			if ($this->sn_hr_is_internal_user_id((int) $existing->ID)) {
				return 0;
			}
			// اگه نقش customer نداره، اضافه کن
			if (! in_array('customer', (array) $existing->roles, true)) {
				$existing->add_role('customer');
			}
			return $existing->ID;
		}

		// ساخت کاربر جدید — رمز تصادفی (Digits بعدا میتونه reset کنه)
		$password = wp_generate_password(12, false);
		$email    = $phone . '@sn-customer.local'; // placeholder — Digits با phone_number کار میکنه

		$user_id = wp_insert_user([
			'user_login'   => $phone,
			'user_pass'    => $password,
			'user_email'   => $email,
			'display_name' => $name,
			'first_name'   => $name,
			'role'         => 'customer',
		]);

		if (is_wp_error($user_id)) {
			return 0;
		}

		// ست کردن متای phone_number برای سازگاری با Digits
		update_user_meta($user_id, 'digits_phone',        $phone);
		update_user_meta($user_id, 'digits_phone_no',     $phone);
		update_user_meta($user_id, 'billing_phone',       $phone);
		update_user_meta($user_id, 'billing_first_name',  $name);

		return $user_id;
	}


	private function sn_sync_customer_profile_from_invoice(int $customer_id, $invoice): void
	{
		if (! $customer_id || ! $invoice) { return; }
		$customer_user = get_user_by('id', $customer_id);
		if ($customer_user && $this->sn_hr_is_internal_user_id((int) $customer_id)) {
			return;
		}
		$name = sanitize_text_field((string) ($invoice->customer_name ?? ''));
		$phone = SN_Helpers::normalize_mobile((string) ($invoice->customer_phone ?? ''));
		$province = sanitize_text_field((string) ($invoice->province ?? ''));
		$city = sanitize_text_field((string) ($invoice->city ?? ''));
		if ($name !== '') {
			wp_update_user(['ID' => $customer_id, 'display_name' => $name, 'first_name' => $name]);
			update_user_meta($customer_id, 'billing_first_name', $name);
		}
		if ($phone !== '') {
			update_user_meta($customer_id, 'digits_phone', $phone);
			update_user_meta($customer_id, 'digits_phone_no', $phone);
			update_user_meta($customer_id, 'billing_phone', $phone);
			update_user_meta($customer_id, 'sn_customer_phone', $phone);
		}
		if ($province !== '') {
			update_user_meta($customer_id, 'billing_state', $province);
			update_user_meta($customer_id, 'sn_customer_province', $province);
		}
		if ($city !== '') {
			update_user_meta($customer_id, 'billing_city', $city);
			update_user_meta($customer_id, 'sn_customer_city', $city);
		}
		update_user_meta($customer_id, 'sn_last_invoice_code', sanitize_text_field((string) ($invoice->invoice_code ?? '')));
		update_user_meta($customer_id, 'sn_last_invoice_id', (int) ($invoice->id ?? 0));
	}

	private function sn_create_wc_order_for_invoice(int $invoice_id, $invoice): int
	{
		if (! function_exists('wc_create_order') || ! $invoice_id || ! $invoice) { return 0; }
		global $wpdb;
		$fresh = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
		if ($fresh) { $invoice = $fresh; }
		if (! empty($invoice->wc_order_id) && get_post((int) $invoice->wc_order_id)) {
			$order_id = (int) $invoice->wc_order_id;
			// A Finance reopen keeps the existing Woo order on hold.  When Finance
			// approves the invoice again, reactivate that same order instead of
			// creating a duplicate order or leaving it on hold forever.
			if (function_exists('wc_get_order')) {
				$existing_order = wc_get_order($order_id);
				if ($existing_order && (string) $existing_order->get_meta('_sn_finance_reopened', true) === '1') {
					$existing_order->payment_complete();
					$existing_order->update_status('completed', 'تایید مجدد مالی فاکتور شبکه فروش');
					$existing_order->delete_meta_data('_sn_finance_reopened');
					$existing_order->delete_meta_data('_sn_finance_reopen_reason');
					$existing_order->save();
				}
			}
			return $order_id;
		}
		$customer_id = (int) ($invoice->customer_wp_id ?? 0);
		if (! $customer_id) {
			$customer_id = $this->get_or_create_customer_account((string) ($invoice->customer_phone ?? ''), (string) ($invoice->customer_name ?? ''));
			if ($customer_id) { $wpdb->update($wpdb->prefix . 'sn_invoices', ['customer_wp_id' => $customer_id], ['id' => $invoice_id]); }
		}
		$order = wc_create_order(['customer_id' => $customer_id ?: 0, 'created_via' => 'sales_network']);
		if (is_wp_error($order) || ! $order) { return 0; }
		$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d ORDER BY id ASC", $invoice_id));
		foreach ($items as $item) {
			$product = function_exists('wc_get_product') ? wc_get_product((int) $item->product_id) : null;
			$qty = max(1, (int) ($item->qty ?? 1));
			if ($product) {
				$order->add_product($product, $qty, [
					'subtotal' => (float) ($item->is_free ? 0 : $item->total_price),
					'total' => (float) ($item->is_free ? 0 : $item->total_price),
				]);
			} else {
				$wc_item = new WC_Order_Item_Product();
				$wc_item->set_name((string) ($item->product_name ?: 'محصول شبکه فروش'));
				$wc_item->set_quantity($qty);
				$wc_item->set_subtotal((float) ($item->is_free ? 0 : $item->total_price));
				$wc_item->set_total((float) ($item->is_free ? 0 : $item->total_price));
				$order->add_item($wc_item);
			}
		}
		$discount_total = (float) ($invoice->discount_total ?? 0);
		if ($discount_total > 0) {
			$fee = new WC_Order_Item_Fee();
			$fee->set_name('تخفیف شبکه فروش');
			$fee->set_amount(-1 * $discount_total);
			$fee->set_total(-1 * $discount_total);
			$order->add_item($fee);
		}
		$order->set_billing_first_name((string) ($invoice->customer_name ?? ''));
		$order->set_billing_phone((string) ($invoice->customer_phone ?? ''));
		$order->set_billing_city((string) ($invoice->city ?? ''));
		$order->update_meta_data('_sn_invoice_id', $invoice_id);
		$order->update_meta_data('_sn_invoice_code', (string) ($invoice->invoice_code ?? ''));
		$order->update_meta_data('_sn_payment_source', (string) ($invoice->payment_source ?? $invoice->pay_method ?? ''));
		$order->update_meta_data('_sn_receipt_urls', SN_Helpers::receipt_urls($invoice));
		$order->update_meta_data('_sn_receipt_file', (string) ($invoice->receipt_file ?? $invoice->receipt_url ?? ''));
		$order->update_meta_data('_sn_manual_paid_at_jalali', (string) ($invoice->manual_paid_at_jalali ?? $invoice->deposit_jalali_datetime ?? ''));
		$order->calculate_totals(false);
		$final = (float) ($invoice->final_total ?? $invoice->product_price ?? 0);
		if ($final >= 0) { $order->set_total($final); }
		$order->payment_complete();
		$order->update_status('completed', 'ثبت خودکار از شبکه فروش پس از تایید پرداخت');
		$order->save();
		$order_id = (int) $order->get_id();
		$wpdb->update($wpdb->prefix . 'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_invoices', ['wc_order_id' => $order_id]), ['id' => $invoice_id]);
		$this->sn_log_activity($invoice_id, (int) ($invoice->lead_id ?? 0), 'wc_order_created', 'سفارش ووکامرس از فاکتور شبکه فروش ساخته شد', ['order_id' => $order_id]);
		return $order_id;
	}

	/** Bounded, opt-in timing data for CRM-44; never includes query text or customer data. */
	private function sn_crm_profile_snapshot(float $started, int $queries_started, array $marks, int $query_log_start = 0): array
	{
		global $wpdb;
		$profile = ['total_ms'=>round((microtime(true)-$started)*1000,1),'queries'=>max(0,(int)$wpdb->num_queries-$queries_started),'phases_ms'=>$marks];
		if (defined('SAVEQUERIES') && SAVEQUERIES && ! empty($wpdb->queries)) {
			$slow = [];
			foreach (array_slice((array)$wpdb->queries, $query_log_start) as $query) {
				$duration = (float)($query[1]??0);
				if ($duration < 0.02) { continue; }
				preg_match('/\\b(?:FROM|JOIN|UPDATE|INTO)\\s+`?([a-zA-Z0-9_]+)/i',(string)($query[0]??''),$match);
				$slow[] = ['ms'=>round($duration*1000,1),'table'=>(string)($match[1]??'unknown')];
			}
			usort($slow,static fn($a,$b)=>$b['ms']<=>$a['ms']);
			$profile['slow_queries'] = array_slice($slow,0,5);
		}
		return $profile;
	}

	public function ajax_seller_leads(): void
	{
		if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
			SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
			return;
		}
		$user = wp_get_current_user();
		global $wpdb;
		$crm_profile = current_user_can('manage_options') && ! empty($_POST['sn_profile']);
		$crm_started = microtime(true);
		$crm_queries_started = (int)$wpdb->num_queries;
		$crm_query_log_start = count((array)$wpdb->queries);
		$crm_marks = [];
		$crm_last_mark = $crm_started;
		$crm_mark = static function(string $name) use (&$crm_marks,&$crm_last_mark): void { $now=microtime(true);$crm_marks[$name]=round(($now-$crm_last_mark)*1000,1);$crm_last_mark=$now; };
		$seller_id = (int) $user->ID;

		$page = max(1, absint($_POST['page'] ?? 1));
		$per_page = absint($_POST['per_page'] ?? 50);
		if (! in_array($per_page, [20, 50, 100], true)) {
			$per_page = 50;
		}
		$active_filter = sanitize_text_field(wp_unslash($_POST['filter'] ?? 'no-status'));
		if ($active_filter === '') {
			$active_filter = 'no-status';
		}
		// Standard seller-stage tabs use canonical slugs, never display labels.
		// Accept old Persian-label requests for backward compatibility, but normalize
		// them before filtering so legacy/MIS rows and flow-state rows behave alike.
		$flow_filter = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance() : null;
		$canonical_stage_filter = $flow_filter ? $flow_filter->status_slug($active_filter) : '';
		if ($canonical_stage_filter !== '') {
			$active_filter = $canonical_stage_filter;
		}
		$search = trim(sanitize_text_field(wp_unslash($_POST['search'] ?? '')));
		$search_norm = preg_replace('/\D+/', '', strtr($search, ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']));

		$scope_decision = null;
		$scope_error = '';
		if (class_exists('SN_Scope_Service')) {
			try {
				$scope_service = new SN_Scope_Service();
				$scope_decision = $scope_service->seller_scope_decision('seller_leads', (int) $user->ID);
				$legacy_count = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE seller_id=%d", (int) $user->ID));
				$scope_service->record_enforcement_decision('seller_leads', (int) $user->ID, $scope_decision, [
					'legacy_count' => $legacy_count,
					'scope_count' => $legacy_count,
				]);
			} catch (Throwable $e) {
				$scope_error = $e->getMessage();
				$scope_decision = ['enforced' => false, 'reason' => 'scope_exception_fallback'];
			}
		}
		$lead_query_debug = $scope_error !== '' ? ['scope_exception' => $scope_error] : [];
		$leads_table = $wpdb->prefix . 'sn_leads';
		$lead_order_parts_alias = ["MAX(CASE WHEN i.status='recontact_requested' THEN i.recontact_requested_at ELSE NULL END)"];
		$lead_order_parts_plain = [];
		if ($this->sn_table_has_column($leads_table, 'assigned_at')) {
			$lead_order_parts_alias[] = 'l.assigned_at';
			$lead_order_parts_plain[] = 'assigned_at';
		}
		foreach (['created_at', 'imported_at', 'updated_at'] as $sn_lead_date_col) {
			if ($this->sn_table_has_column($leads_table, $sn_lead_date_col)) {
				$lead_order_parts_alias[] = 'l.' . $sn_lead_date_col;
				$lead_order_parts_plain[] = $sn_lead_date_col;
				break;
			}
		}
		$lead_order_sql = 'COALESCE(' . implode(', ', $lead_order_parts_alias) . ') DESC, l.id DESC';
		$lead_fallback_order_sql = $lead_order_parts_plain ? ('COALESCE(' . implode(', ', $lead_order_parts_plain) . ') DESC, id DESC') : 'id DESC';

		// برای صفحه‌بندی Ajax دیگر لازم نیست کل لیست به DOM فرستاده شود. این سقف فقط window داده‌ای سمت سرور است
		// تا ترکیب legacy و V4 بعد از sort/filter قابل صفحه‌بندی باشد، بدون اینکه جدول HTML سنگین شود.
		$fetch_window = min(5000, max(600, ($page * $per_page) + 300));
		try {
			$leads = $wpdb->get_results($wpdb->prepare(
				"SELECT l.*,
					MAX(CASE WHEN i.status='recontact_requested' THEN 1 ELSE 0 END) AS has_recontact,
					MAX(CASE WHEN i.status='recontact_requested' THEN i.recontact_requested_at ELSE NULL END) AS recontact_requested_at,
					MAX(CASE WHEN i.status='recontact_requested' THEN i.recontact_note ELSE NULL END) AS recontact_note,
					MAX(CASE WHEN i.status='recontact_requested' THEN i.invoice_code ELSE NULL END) AS recontact_invoice_code
				FROM {$wpdb->prefix}sn_leads l
				LEFT JOIN {$wpdb->prefix}sn_invoices i ON i.lead_id=l.id AND i.seller_id=l.seller_id
				WHERE l.seller_id=%d
				GROUP BY l.id
				ORDER BY {$lead_order_sql}
				LIMIT %d",
				$seller_id,
				$fetch_window
			), ARRAY_A) ?: [];
			if ($wpdb->last_error) { $lead_query_debug['legacy_join_warning'] = (string) $wpdb->last_error; }
		} catch (Throwable $e) {
			$lead_query_debug['legacy_join_exception'] = $e->getMessage();
			$leads = [];
		}
		if (! $leads && ! empty($lead_query_debug)) {
			$leads = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_leads WHERE seller_id=%d ORDER BY {$lead_fallback_order_sql} LIMIT %d", $seller_id, $fetch_window), ARRAY_A) ?: [];
		}
		foreach ($leads as &$lead) {
			$lead['has_recontact'] = ! empty($lead['has_recontact']);
			$lead['source_kind'] = 'legacy_lead';
			$is_extra = ((string) ($lead['source_tag'] ?? '') === 'approved_extra_number_request') || ! empty($lead['extra_number_request_id']);
			$lead['is_extra_number_request'] = $is_extra;
			if ($is_extra) {
				$lead['lead_badge_label'] = 'شماره درخواستی تایید‌شده';
				$lead['lead_badge_class'] = 'sn-extra-approved-badge';
			}
		}
		unset($lead);
		if ($crm_profile) { $crm_mark('legacy_leads'); }

		$v4_items = [];
		try {
			$v4_items = $this->sn_distribution_seller_delivered_items($seller_id, min(5000, max(600, ($page * $per_page) + 300)));
		} catch (Throwable $e) {
			$lead_query_debug['v4_items_exception'] = $e->getMessage();
			$v4_items = [];
		}
		foreach ($v4_items as $item) {
			if (! empty($item->live_lead_id)) {
				continue;
			}
			$phone = (string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? ''));
			if ($phone === '') {
				continue;
			}
			$probability = '';
			if (! empty($item->seller_sale_probability_label)) {
				$probability = (string) $item->seller_sale_probability_label;
			} elseif (isset($item->seller_sale_probability) && (int) $item->seller_sale_probability > 0) {
				$probability = (string) (int) $item->seller_sale_probability . '٪';
			}
			$leads[] = [
				'id' => $this->sn_distribution_virtual_lead_id((int) $item->id),
				'distribution_item_id' => (int) $item->id,
				'source_kind' => 'v4_distribution_item',
				'phone' => $phone,
				'customer_name' => (string) ($item->customer_name ?? ''),
				'province' => (string) ($item->province ?? ''),
				'city' => (string) ($item->city ?? ''),
				'sales_prediction' => $probability,
				'note' => (string) ($item->seller_notes ?? ''),
				'lead_status' => (string) ($item->seller_contact_status ?? ''),
				'status' => (string) ($item->status ?? 'delivered_to_seller'),
				'import_code' => (string) ($item->batch_code ?? ''),
				'assigned_at' => (string) (($item->seller_updated_at ?? '') ?: (($item->updated_at ?? '') ?: ($item->created_at ?? current_time('mysql')))),
				'has_recontact' => false,
				'is_v4_distribution' => true,
				'lead_badge_label' => 'داده MIS تحویل‌شده',
				'lead_badge_class' => 'sn-mis-delivered-badge',
			];
		}
		if ($crm_profile) { $crm_mark('v4_distribution'); }
		if (class_exists('SN_Seller_Flow')) {
			$leads = SN_Seller_Flow::instance()->enrich_and_filter_leads($leads, $seller_id);
		}
		if ($crm_profile) { $crm_mark('seller_flow'); }

		usort($leads, static function ($a, $b) {
			return strcmp((string) ($b['assigned_at'] ?? ''), (string) ($a['assigned_at'] ?? ''));
		});

		$total_all = count($leads);
		$no_status_total = 0;
		$recontact_total = 0;
		$extra_total = 0;
		// A lead is "without status" only while neither the canonical seller-flow
		// status nor the legacy/display status has been set. Extra-number requests
		// keep their own independent tab and must leave this bucket after an action.
		$lead_has_no_status = static function (array $lead): bool {
			return trim((string) ($lead['seller_flow_status'] ?? '')) === ''
				&& trim((string) ($lead['lead_status'] ?? '')) === '';
		};
		foreach ($leads as $lead) {
			if ($lead_has_no_status($lead)) { $no_status_total++; }
			if (! empty($lead['has_recontact'])) { $recontact_total++; }
			if (! empty($lead['is_extra_number_request'])) { $extra_total++; }
		}

		$filtered = array_values(array_filter($leads, static function ($lead) use ($active_filter, $search, $search_norm, $lead_has_no_status) {
			$status = (string) ($lead['lead_status'] ?? '');
			$flow_status = sanitize_key((string) ($lead['seller_flow_status'] ?? ''));
			$matches_filter = true;
			if ($active_filter === 'all') {
				$matches_filter = true;
			} elseif ($active_filter === 'no-status') {
				$matches_filter = $lead_has_no_status($lead);
			} elseif ($active_filter === 'recontact') {
				$matches_filter = ! empty($lead['has_recontact']);
			} elseif ($active_filter === 'extra-number') {
				$matches_filter = ! empty($lead['is_extra_number_request']);
			} elseif (in_array($active_filter, ['no_answer', 'callback', 'not_purchased', 'pre_invoice'], true)) {
				$matches_filter = $flow_status === $active_filter;
			} else {
				// Compatibility fallback for non-stage custom filters.
				$matches_filter = $status === $active_filter;
			}
			if (! $matches_filter) { return false; }
			if ($search === '') { return true; }
			$haystack = implode(' ', [
				(string) ($lead['phone'] ?? ''),
				(string) ($lead['customer_name'] ?? ''),
				(string) ($lead['province'] ?? ''),
				(string) ($lead['city'] ?? ''),
				(string) ($lead['import_code'] ?? ''),
				(string) ($lead['note'] ?? ''),
				(string) ($lead['lead_status'] ?? ''),
			]);
			$text_match = function_exists('mb_stripos') ? (mb_stripos($haystack, $search, 0, 'UTF-8') !== false) : (stripos($haystack, $search) !== false);
			if ($text_match) { return true; }
			if ($search_norm !== '') {
				$phone_norm = preg_replace('/\D+/', '', (string) ($lead['phone'] ?? ''));
				return strpos($phone_norm, $search_norm) !== false;
			}
			return false;
		}));

		$total_filtered = count($filtered);
		$total_pages = max(1, (int) ceil($total_filtered / $per_page));
		if ($page > $total_pages) { $page = $total_pages; }
		$offset = ($page - 1) * $per_page;
		$page_leads = array_slice($filtered, $offset, $per_page);
		if ($crm_profile) { $crm_mark('filter_sort_page'); }

		SN_Helpers::send_json(true, '', [
			'leads' => $page_leads,
			'pagination' => [
				'page' => $page,
				'per_page' => $per_page,
				'total' => $total_filtered,
				'total_all' => $total_all,
				'total_pages' => $total_pages,
				'current_count' => count($page_leads),
				'filter' => $active_filter,
				'search' => $search,
				'no_status_total' => $no_status_total,
				'status_done_total' => max(0, $total_all - $no_status_total),
				'recontact_total' => $recontact_total,
				'extra_total' => $extra_total,
			],
			'v4_distribution_count' => count($v4_items),
			'debug' => current_user_can('manage_options') ? $lead_query_debug : [],
			'profile' => $crm_profile ? $this->sn_crm_profile_snapshot($crm_started,$crm_queries_started,$crm_marks,$crm_query_log_start) : null,
		]);
	}

	// =========================================================
	// AJAX - SUPERVISOR
	// =========================================================

	public function ajax_supervisor_data(): void
	{
		$crm_started = microtime(true);
		if (! is_user_logged_in()) {
			SN_Helpers::send_json(false, 'وارد نشده‌اید');
			return;
		}
		$user = wp_get_current_user();
		$viewer_position = class_exists('SN_Scope_Service') ? (new SN_Scope_Service())->get_viewer_position_slug((int) $user->ID) : '';
		if (! in_array('sn_supervisor', (array) $user->roles, true) && ! current_user_can('manage_options') && $viewer_position !== 'supervisor') {
			SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
			return;
		}
		$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
		if (! $valid) {
			SN_Helpers::send_json(false, 'نانس نامعتبر');
			return;
		}

		global $wpdb;
		$crm_profile = current_user_can('manage_options') && ! empty($_POST['sn_profile']);
		$crm_queries_started = (int)$wpdb->num_queries;
		$crm_query_log_start = count((array)$wpdb->queries);
		$crm_marks = [];
		$crm_last_mark = $crm_started;
		$crm_mark = static function(string $name) use (&$crm_marks,&$crm_last_mark): void { $now=microtime(true);$crm_marks[$name]=round(($now-$crm_last_mark)*1000,1);$crm_last_mark=$now; };
		$supervisor_id = current_user_can('manage_options') ? absint($_POST['supervisor_id'] ?? 0) : (int) $user->ID;
		if (! $supervisor_id) {
			$supervisor_id = (int) $user->ID;
		}

		// دریافت فروشنده‌ها به صورت مقاوم: HR assignment منبع اصلی V4 است.
		// کاربران واردشده از HR ممکن است فقط Subscriber باشند و نقش sn_seller نداشته باشند؛
		// بنابراین پنل سرپرست نباید فروشنده را فقط با WP role یا user_meta قدیمی فیلتر کند.
		$hr_direct_seller_ids = array_values(array_unique(array_filter(array_map('absint', array_column($this->sn_get_direct_children((int) $supervisor_id, 'seller'), 'user_id')))));
		$seller_ids = [];
		if (current_user_can('manage_options') && empty($_POST['supervisor_id'])) {
			$wp_role_seller_ids = get_users([
				'role__in' => ['sn_seller'],
				'fields'   => 'ids',
				'number'   => 1000,
			]);
			$hr_seller_ids = array_map('absint', array_column($this->sn_hr_all_users_by_position('seller'), 'user_id'));
			$seller_ids = array_values(array_unique(array_filter(array_map('absint', array_merge((array) $wp_role_seller_ids, (array) $hr_seller_ids)))));
		} else {
			$meta_seller_ids = get_users([
				'role__in'     => ['sn_seller'],
				'fields'       => 'ids',
				'number'       => 1000,
				'meta_key'     => 'sn_supervisor_id',
				'meta_value'   => (string) $supervisor_id,
				'meta_compare' => '=',
			]);
			$lead_seller_ids = $wpdb->get_col($wpdb->prepare("SELECT DISTINCT seller_id FROM {$wpdb->prefix}sn_leads WHERE supervisor_id=%d AND seller_id IS NOT NULL AND seller_id > 0", $supervisor_id));
			$seller_ids = array_values(array_unique(array_filter(array_map('absint', array_merge((array) $meta_seller_ids, (array) $lead_seller_ids, (array) $hr_direct_seller_ids)))));
		}
		$legacy_seller_ids = array_values(array_unique(array_map('absint', (array) $seller_ids)));
		$seller_scope_decision = $this->sn_supervisor_scope_decision('supervisor_sellers', (int) $user->ID);
		$lead_scope_decision = $this->sn_supervisor_scope_decision('supervisor_leads', (int) $user->ID);
		$use_hr_supervisor_scope = ! current_user_can('manage_options') && $viewer_position === 'supervisor';
		if ($use_hr_supervisor_scope) {
			// در پنل خود سرپرست، فروشنده‌های مستقیم HR همیشه باید دیده شوند، حتی اگر scope mode خاموش/audit_only باشد.
			$seller_ids = $hr_direct_seller_ids;
		} elseif (! current_user_can('manage_options') && ! empty($seller_scope_decision['enforced'])) {
			$seller_ids = array_values(array_unique(array_map('absint', (array) ($seller_scope_decision['visible_user_ids'] ?? []))));
		}
		$this->sn_record_scope_decision('supervisor_sellers', (int) $user->ID, $seller_scope_decision, [
			'legacy_seller_ids' => $legacy_seller_ids,
			'hr_direct_seller_ids' => $hr_direct_seller_ids,
			'scope_seller_ids' => $seller_ids,
		]);
		$sellers = [];
		foreach ($seller_ids as $sid) {
			$seller = get_user_by('id', $sid);
			if ($seller instanceof WP_User && (in_array('sn_seller', (array) $seller->roles, true) || $this->sn_user_has_hr_position((int) $sid, 'seller'))) {
				$sellers[] = $seller;
			}
		}
		usort($sellers, static function ($a, $b) {
			return strnatcasecmp($a->display_name ?: $a->user_login, $b->display_name ?: $b->user_login);
		});

		$date_from = sanitize_text_field(wp_unslash($_POST['date_from'] ?? ''));
		$date_to   = sanitize_text_field(wp_unslash($_POST['date_to'] ?? ''));
		$time_from = sanitize_text_field(wp_unslash($_POST['time_from'] ?? ''));
		$time_to   = sanitize_text_field(wp_unslash($_POST['time_to'] ?? ''));
		$filter_seller_id = absint($_POST['seller_id'] ?? 0);
		$filter_lead_status = sanitize_text_field(wp_unslash($_POST['lead_status'] ?? ''));
		$filter_import_code = sanitize_text_field(wp_unslash($_POST['import_code'] ?? ''));
		$filter_assignment = sanitize_text_field(wp_unslash($_POST['assignment'] ?? ''));
		$date_from_g_for_sellers = SN_Helpers::jalali_to_gregorian_date($date_from);
		$date_to_g_for_sellers = SN_Helpers::jalali_to_gregorian_date($date_to);

		// Performance: seller stats are built with bulk GROUP BY queries instead of 4+ queries per seller.
		$v4_seller_distribution_total = 0;
		$seller_id_list = array_values(array_unique(array_filter(array_map(static fn($s) => (int) $s->ID, $sellers))));

		$sn_supervisor_data_cache_key = 'sn_sup_data_' . md5(wp_json_encode([
			'v' => SN_VERSION,
			'user' => (int) $user->ID,
			'supervisor' => (int) $supervisor_id,
			'sellers' => $seller_id_list,
			'date_from' => $date_from,
			'date_to' => $date_to,
			'time_from' => $time_from,
			'time_to' => $time_to,
			'filter_seller_id' => $filter_seller_id,
			'filter_lead_status' => $filter_lead_status,
			'filter_import_code' => $filter_import_code,
			'filter_assignment' => $filter_assignment,
		]));
		if (empty($_POST['force_refresh'])) {
			$sn_supervisor_data_cached = get_transient($sn_supervisor_data_cache_key);
			if (is_array($sn_supervisor_data_cached)) {
				$sn_supervisor_data_cached['cache_hit'] = true;
				if ($crm_profile) { $crm_mark('scope_and_cache'); $sn_supervisor_data_cached['profile']=$this->sn_crm_profile_snapshot($crm_started,$crm_queries_started,$crm_marks,$crm_query_log_start); }
				SN_Helpers::send_json(true, '', $sn_supervisor_data_cached);
				return;
			}
		}
		if ($crm_profile) { $crm_mark('scope_and_cache'); }

		$lead_count_map = [];
		$distribution_count_map = [];
		$invoice_count_map = [];
		$paid_count_map = [];
		$revenue_map = [];
		if ($seller_id_list) {
			$ph = implode(',', array_fill(0, count($seller_id_list), '%d'));
			$lead_where_bulk = ["seller_id IN ({$ph})"];
			$lead_args_bulk = array_values($seller_id_list);
			if ($date_from_g_for_sellers) { $lead_where_bulk[] = 'assigned_at >= %s'; $lead_args_bulk[] = $date_from_g_for_sellers . ' 00:00:00'; }
			if ($date_to_g_for_sellers) { $lead_where_bulk[] = 'assigned_at <= %s'; $lead_args_bulk[] = $date_to_g_for_sellers . ' 23:59:59'; }
			if (preg_match('/^\d{2}:\d{2}$/', $time_from)) { $lead_where_bulk[] = 'TIME(assigned_at) >= %s'; $lead_args_bulk[] = $time_from . ':00'; }
			if (preg_match('/^\d{2}:\d{2}$/', $time_to)) { $lead_where_bulk[] = 'TIME(assigned_at) <= %s'; $lead_args_bulk[] = $time_to . ':59'; }
			if ($filter_lead_status !== '') { $lead_where_bulk[] = 'lead_status = %s'; $lead_args_bulk[] = $filter_lead_status; }
			if ($filter_import_code !== '') { $lead_where_bulk[] = 'import_code = %s'; $lead_args_bulk[] = $filter_import_code; }
			if ($filter_assignment === 'unassigned') { $lead_where_bulk[] = '1=0'; }
			$lead_rows_bulk = $wpdb->get_results($wpdb->prepare("SELECT seller_id, COUNT(*) c FROM {$wpdb->prefix}sn_leads WHERE " . implode(' AND ', $lead_where_bulk) . " GROUP BY seller_id", ...$lead_args_bulk), ARRAY_A) ?: [];
			foreach ($lead_rows_bulk as $row) { $lead_count_map[(int) $row['seller_id']] = (int) $row['c']; }

			$invoice_rows_bulk = $wpdb->get_results($wpdb->prepare(
				"SELECT seller_id,
					COUNT(*) invoice_count,
					SUM(CASE WHEN status IN ('paid','approved') THEN 1 ELSE 0 END) paid_count,
					COALESCE(SUM(CASE WHEN status IN ('paid','approved') THEN COALESCE(NULLIF(final_total,0), NULLIF(product_price,0), NULLIF(paid_amount,0), 0) ELSE 0 END),0) revenue
				 FROM {$wpdb->prefix}sn_invoices
				 WHERE seller_id IN ({$ph})
				 GROUP BY seller_id",
				...$seller_id_list
			), ARRAY_A) ?: [];
			foreach ($invoice_rows_bulk as $row) {
				$sid = (int) $row['seller_id'];
				$invoice_count_map[$sid] = (int) $row['invoice_count'];
				$paid_count_map[$sid] = (int) $row['paid_count'];
				$revenue_map[$sid] = (float) $row['revenue'];
			}

			if ($this->sn_mis_table_exists('sn_distribution_items')) {
				// Performance: avoid fetching every distribution row into PHP. Count by resolved seller in SQL.
				$dist_rows_bulk = $wpdb->get_results($wpdb->prepare(
					"SELECT COALESCE(NULLIF(final_seller_user_id,0), current_owner_user_id) seller_id, COUNT(*) c
					 FROM {$wpdb->prefix}sn_distribution_items
					 WHERE COALESCE(NULLIF(final_seller_user_id,0), current_owner_user_id) IN ({$ph})
					   AND status='delivered_to_seller'
					   AND (live_lead_id IS NULL OR live_lead_id=0)
					 GROUP BY COALESCE(NULLIF(final_seller_user_id,0), current_owner_user_id)",
					...$seller_id_list
				), ARRAY_A) ?: [];
				foreach ($dist_rows_bulk as $row) {
					$sid = (int) ($row['seller_id'] ?? 0);
					if ($sid > 0) { $distribution_count_map[$sid] = (int) ($row['c'] ?? 0); }
				}
			}
		}
		$sellers_data = [];
		if ($crm_profile) { $crm_mark('bulk_counts'); }
		foreach ($sellers as $s) {
			$sid = (int) $s->ID;
			$lead_count = (int) ($lead_count_map[$sid] ?? 0);
			$v4_distribution_count = (int) ($distribution_count_map[$sid] ?? 0);
			$v4_seller_distribution_total += $v4_distribution_count;
			$active_meta = get_user_meta($sid, 'sn_is_active', true);
			$sellers_data[] = [
				'id' => $sid,
				'name' => $s->display_name,
				'phone' => $s->user_login,
				'lead_count' => $lead_count + $v4_distribution_count,
				'legacy_lead_count' => $lead_count,
				'distribution_item_count' => $v4_distribution_count,
				'invoice_count' => (int) ($invoice_count_map[$sid] ?? 0),
				'paid_count' => (int) ($paid_count_map[$sid] ?? 0),
				'revenue' => (float) ($revenue_map[$sid] ?? 0),
				'is_active' => ($active_meta !== '0'),
			];
		}
		$supervisor_leads_enforced = $use_hr_supervisor_scope || (! current_user_can('manage_options') && ! empty($lead_scope_decision['enforced']));
		$pool = $supervisor_leads_enforced ? 0 : (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE supervisor_id=%d AND seller_id IS NULL AND status='supervisor_pool'",
			$supervisor_id
		));

		if ($supervisor_leads_enforced) {
			if ($seller_ids) {
				$where = ['seller_id IN (' . implode(',', array_fill(0, count($seller_ids), '%d')) . ')'];
				$args = array_values(array_map('intval', $seller_ids));
			} else {
				$where = ['1=0'];
				$args = [];
			}
		} else {
			$where = ['supervisor_id=%d'];
			$args = [$supervisor_id];
		}
		$base_where = $where;
		$base_args = $args;
		$date_from_g = SN_Helpers::jalali_to_gregorian_date($date_from);
		$date_to_g = SN_Helpers::jalali_to_gregorian_date($date_to);
		if ($date_from_g) {
			$where[] = 'DATE(assigned_at) >= %s';
			$args[] = $date_from_g;
		}
		if ($date_to_g) {
			$where[] = 'DATE(assigned_at) <= %s';
			$args[] = $date_to_g;
		}
		if (preg_match('/^\d{2}:\d{2}$/', $time_from)) {
			$where[] = 'TIME(assigned_at) >= %s';
			$args[] = $time_from . ':00';
		}
		if (preg_match('/^\d{2}:\d{2}$/', $time_to)) {
			$where[] = 'TIME(assigned_at) <= %s';
			$args[] = $time_to . ':59';
		}
		if ($filter_seller_id) {
			$where[] = 'seller_id = %d';
			$args[] = $filter_seller_id;
		}
		if ($filter_lead_status !== '') {
			$where[] = 'lead_status = %s';
			$args[] = $filter_lead_status;
		}
		if ($filter_import_code !== '') {
			$where[] = 'import_code = %s';
			$args[] = $filter_import_code;
		}
		if ($filter_assignment === 'assigned') {
			$where[] = 'seller_id IS NOT NULL';
		} elseif ($filter_assignment === 'unassigned') {
			$where[] = 'seller_id IS NULL';
		}
		$range_sql = " WHERE " . implode(' AND ', $where);
		$range_count = (int) ( $args ? $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$range_sql}", ...$args)) : $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$range_sql}") );
		$base_sql = " WHERE " . implode(' AND ', $base_where);
		$total_count = (int) ( $base_args ? $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql}", ...$base_args)) : $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql}") );
		$assigned_count = (int) ( $base_args ? $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql} AND seller_id IS NOT NULL", ...$base_args)) : $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql} AND seller_id IS NOT NULL") );
		$invoiced_count = (int) ( $base_args ? $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql} AND status='invoiced'", ...$base_args)) : $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads {$base_sql} AND status='invoiced'") );
		if ($supervisor_leads_enforced) {
			$paid_count = (int) ( $seller_ids ? $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices WHERE seller_id IN (" . implode(',', array_fill(0, count($seller_ids), '%d')) . ") AND status IN ('paid','approved')", ...array_values(array_map('intval', $seller_ids)))) : 0 );
		} else {
			$paid_count = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices i INNER JOIN {$wpdb->prefix}sn_leads l ON l.id=i.lead_id WHERE l.supervisor_id=%d AND i.status IN ('paid','approved')", $supervisor_id));
		}
		$this->sn_record_scope_decision('supervisor_leads', (int) $user->ID, $lead_scope_decision, [
			'legacy_seller_ids' => $legacy_seller_ids,
			'scope_seller_ids' => $seller_ids,
		]);
		$lead_statuses = $wpdb->get_col("SELECT label FROM {$wpdb->prefix}sn_lead_statuses WHERE is_active=1 ORDER BY sort_order ASC, id ASC");

		// Performance: the previous summary loaded up to 300 full distribution rows and resolved next recipients per row.
		// For the dashboard KPI a fast SQL count is enough; detailed eligibility is checked only during actual transfer.
		$distribution_owned_count = $this->sn_distribution_fast_owned_count_for_actor((int) $supervisor_id);
		$distribution_transferable = $distribution_owned_count;
		$distribution_transferred_out = $this->sn_distribution_transferred_out_count((int) $supervisor_id);
		$active_seller_count = count(array_filter($sellers_data, static fn($seller_row) => ! empty($seller_row['is_active'])));
		$approved_revenue_total = array_reduce($sellers_data, static fn($sum, $seller_row) => $sum + (float) ($seller_row['revenue'] ?? 0), 0.0);

		$sn_supervisor_data_payload = [
			'sellers' => $sellers_data,
			'unassigned' => $pool,
			'supervisor_id' => $supervisor_id,
			'scope_debug' => [
				'viewer_user_id' => (int) $user->ID,
				'viewer_position' => (string) $viewer_position,
				'supervisor_id' => (int) $supervisor_id,
				'hr_direct_seller_ids' => array_values(array_map('intval', $hr_direct_seller_ids)),
				'legacy_seller_ids' => array_values(array_map('intval', $legacy_seller_ids)),
				'final_seller_ids' => array_values(array_map('intval', $seller_ids)),
				'scope_reason' => (string) ($seller_scope_decision['reason'] ?? ''),
			],
			'summary' => [
				'total' => $total_count + (int) $v4_seller_distribution_total,
				'total_leads' => $total_count + (int) $v4_seller_distribution_total,
				'assigned' => $assigned_count + (int) $v4_seller_distribution_total,
				'unassigned' => $pool,
				'range_assigned' => $range_count,
				'invoiced' => $invoiced_count,
				'invoices' => $invoiced_count,
				'paid' => $paid_count,
				'sales' => $approved_revenue_total,
				'revenue' => $approved_revenue_total,
				'hr_sellers_total' => count($sellers_data),
				'hr_sellers_active' => $active_seller_count,
				'v4_owned_items' => (int) $distribution_owned_count,
				'v4_transferable_items' => $distribution_transferable,
				'v4_transferred_out' => $distribution_transferred_out,
				'v4_delivered_to_sellers' => (int) $v4_seller_distribution_total,
			],
			'lead_statuses' => $lead_statuses ?: [],
			'cache_hit' => false,
		];
		set_transient($sn_supervisor_data_cache_key, $sn_supervisor_data_payload, 20);
		if ($crm_profile) { $crm_mark('aggregation_and_render'); $sn_supervisor_data_payload['profile']=$this->sn_crm_profile_snapshot($crm_started,$crm_queries_started,$crm_marks,$crm_query_log_start); }
		SN_Helpers::send_json(true, '', $sn_supervisor_data_payload);
	}

	// =========================================================
	// AJAX - INVOICE PAGE (PUBLIC)
	// =========================================================

	private function sn_invoice_ajax_nonce_context(): string
	{
		$nonce = sanitize_text_field(wp_unslash($_POST['nonce'] ?? ($_POST['security'] ?? '')));
		if ($nonce === '') {
			return '';
		}
		if (is_user_logged_in() && wp_verify_nonce($nonce, 'sn_admin')) {
			return 'admin';
		}
		if (wp_verify_nonce($nonce, 'sn_public')) {
			return 'public';
		}
		return '';
	}

	private function sn_current_user_is_invoice_info_admin(): bool
	{
		$user_id = (int) get_current_user_id();
		return $user_id > 0 && (user_can($user_id, 'manage_options') || (function_exists('is_super_admin') && is_super_admin($user_id)));
	}

	private function sn_invoice_info_fail(string $message, string $error_code, string $debug_reason, string $nonce_checked, bool $has_invoice_code, bool $has_access_token, array $debug = []): void
	{
		$payload = [
			'success' => false,
			'message' => $message,
			'code' => $error_code,
			'error_code' => $error_code,
		];
		if (current_user_can('manage_options')) {
			$payload += [
				'debug_reason' => $debug_reason,
				'nonce_checked' => $nonce_checked,
				'is_logged_in' => is_user_logged_in(),
				'has_invoice_code' => $has_invoice_code,
				'has_access_token' => $has_access_token,
			];
			if ($debug) {
				$payload['debug'] = $debug;
			}
		}
		wp_send_json($payload);
	}

	public function ajax_invoice_info(): void
	{
		$code    = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
		$token   = $this->sn_public_access_token();
		$has_code = $code !== '';
		$has_token = $token !== '';
		$nonce_context = $this->sn_invoice_ajax_nonce_context();
		$nonce_checked = $nonce_context !== '' ? $nonce_context : 'invalid';
		$invoice = null;
		$invoice_info_access_version = '';
		$public_customer_access = false;

		if (is_user_logged_in() && $has_code && ! $has_token && in_array($nonce_context, ['admin', 'public'], true) && $this->sn_current_user_is_invoice_info_admin()) {
			$invoice = SN_Helpers::get_invoice_by_code($code);
			$invoice_info_access_version = 'admin-bypass-20260531';
			if (! $invoice) {
				$this->sn_invoice_info_fail('فاکتور یافت نشد.', 'invoice_not_found', 'admin_bypass_invoice_code_not_found', $nonce_checked, $has_code, $has_token, [
					'debug_branch' => 'admin_bypass_not_found',
					'current_user_id' => (int) get_current_user_id(),
					'is_logged_in' => is_user_logged_in(),
					'user_can_manage_options' => user_can((int) get_current_user_id(), 'manage_options') ? 'yes' : 'no',
					'invoice_code' => $code,
					'invoice_id' => 0,
					'invoice_seller_id' => 0,
					'permission_branch' => 'admin_bypass',
					'reason' => 'invoice_not_found',
				]);
				return;
			}
		} elseif (is_user_logged_in() && $has_code && ! $has_token && in_array($nonce_context, ['admin', 'public'], true)) {
			$internal_invoice = SN_Helpers::get_invoice_by_code($code);
			$internal_access = $internal_invoice ? $this->sn_internal_invoice_info_access($internal_invoice, 0, $code) : ['allowed' => false, 'reason' => 'invoice_not_found', 'invoice_code' => $code, 'debug_branch' => 'internal_not_found'];
			if ($internal_invoice && ! empty($internal_access['allowed'])) {
				$invoice = $internal_invoice;
			} elseif ($internal_invoice) {
				$this->sn_invoice_info_fail('دسترسی به این فاکتور مجاز نیست.', 'forbidden_invoice', (string) ($internal_access['reason'] ?? 'internal_permission_or_scope_rejected'), $nonce_checked, $has_code, $has_token, $internal_access);
				return;
			} else {
				$this->sn_invoice_info_fail('فاکتور یافت نشد.', 'invoice_not_found', 'internal_invoice_code_not_found', $nonce_checked, $has_code, $has_token);
				return;
			}
		} else {
			if ($nonce_context !== 'public') {
				$this->sn_invoice_info_fail('نانس نامعتبر', 'invalid_nonce', 'public_route_requires_sn_public_nonce', $nonce_checked, $has_code, $has_token);
				return;
			}
			if (! $has_token) {
				$this->sn_invoice_info_fail('لینک فاکتور معتبر نیست یا منقضی شده است. لطفاً لینک جدید دریافت کنید.', 'missing_access_token', 'public_route_requires_access_token', $nonce_checked, $has_code, $has_token);
				return;
			}
			$access = $this->sn_validate_public_invoice_access($code, $token, 'view');
			if (empty($access['success'])) {
				$this->sn_invoice_info_fail((string) $access['message'], 'public_invoice_access_denied', 'public_token_validation_failed', $nonce_checked, $has_code, $has_token);
				return;
			}
			$invoice = $access['invoice'];
			$public_customer_access = true;
		}
		$card_to_card_enabled = $this->sn_card_to_card_enabled();
		$invoice_card = $this->sn_resolve_invoice_card($invoice);
		$card_number = $card_to_card_enabled ? (string) ($invoice_card['number'] ?? '') : '';
		$card_owner  = $card_to_card_enabled ? (string) ($invoice_card['owner'] ?? '') : '';
		global $wpdb;
		$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d ORDER BY id ASC", (int) $invoice->id), ARRAY_A);
		if (! $items) {
			$items = [[
				'product_id' => (int) $invoice->product_id,
				'product_name' => get_the_title($invoice->product_id),
				'qty' => 1,
				'unit_price' => (float) $invoice->product_price,
				'total_price' => (float) $invoice->product_price,
				'is_free' => 0,
			]];
		}
		$items_out = [];
		$sn_wheels_for_invoice = get_option('sn_lucky_wheels', []);
		if (! is_array($sn_wheels_for_invoice)) { $sn_wheels_for_invoice = []; }
		foreach ($items as $it) {
			$pid = (int) ($it['product_id'] ?? 0);
			$product_type = sanitize_key((string) ($it['product_type'] ?? ''));
			if ($product_type === '' && $pid && class_exists('SN_Seller_Flow')) {
				$product_type = SN_Seller_Flow::instance()->product_type($pid);
			}
			$product = $pid && function_exists('wc_get_product') ? wc_get_product($pid) : null;
			$regular = $product ? (float) $product->get_regular_price() : (float) ($it['unit_price'] ?? 0);
			$sale = $product ? (float) $product->get_price() : (float) ($it['unit_price'] ?? 0);
			$short_description = (string) get_post_meta($pid, '_sn_short_description', true);
			if ($short_description === '' && $product && method_exists($product, 'get_short_description')) {
				$short_description = (string) $product->get_short_description();
			}
			if ($short_description === '' && $pid) {
				$short_description = (string) get_post_field('post_excerpt', $pid);
			}
			$image_url = '';
			$gallery_urls = [];
			if ($product) {
				$image_id = method_exists($product, 'get_image_id') ? (int) $product->get_image_id() : 0;
				if ($image_id) { $image_url = (string) wp_get_attachment_image_url($image_id, 'medium'); }
				$gallery_ids = method_exists($product, 'get_gallery_image_ids') ? (array) $product->get_gallery_image_ids() : [];
				foreach ($gallery_ids as $gid) {
					$gurl = wp_get_attachment_image_url((int) $gid, 'thumbnail');
					if ($gurl) { $gallery_urls[] = (string) $gurl; }
				}
			}
			$items_out[] = [
				'product_id' => $pid,
				'product_type' => $product_type ?: 'product',
				'product_name' => (string) ($it['product_name'] ?? get_the_title($pid)),
				'qty' => (int) ($it['qty'] ?? 1),
				'unit_price' => (float) ($it['unit_price'] ?? $sale),
				'total_price' => (float) ($it['total_price'] ?? 0),
				'is_free' => ! empty($it['is_free']),
				'short_description' => wp_kses_post($short_description),
				'image_url' => esc_url_raw($image_url),
				'gallery_urls' => array_map('esc_url_raw', $gallery_urls),
				'regular_price' => $regular,
				'sale_price' => $sale,
				'has_sale' => $regular > $sale && $sale > 0,
				'lottery_chance_count' => (int) get_post_meta($pid, '_sn_lottery_chance_count', true),
				'has_lucky_wheel' => get_post_meta($pid, '_sn_has_lucky_wheel', true) === '1',
				'payment_reward_enabled' => $this->sn_payment_rewards_enabled() && get_post_meta($pid, '_sn_payment_reward_enabled', true) === '1',
				'has_discount_coupon' => get_post_meta($pid, '_sn_has_discount_coupon', true) === '1',
				'wheel_id' => (string) get_post_meta($pid, '_sn_wheel_id', true),
				'wheel_title' => (function($wid, $wheels){ if ($wid && isset($wheels[$wid])) { return (string)($wheels[$wid]['title'] ?? ''); } $first = is_array($wheels) ? reset($wheels) : null; return is_array($first) ? (string)($first['title'] ?? '') : ''; })((string) get_post_meta($pid, '_sn_wheel_id', true), $sn_wheels_for_invoice),
				'wheel_description' => (function($wid, $wheels){ if ($wid && isset($wheels[$wid])) { return (string)($wheels[$wid]['description'] ?? ''); } $first = is_array($wheels) ? reset($wheels) : null; return is_array($first) ? (string)($first['description'] ?? '') : ''; })((string) get_post_meta($pid, '_sn_wheel_id', true), $sn_wheels_for_invoice),
				'wheel_segments' => (function($wid, $wheels){ if ($wid && isset($wheels[$wid]) && !empty($wheels[$wid]['segments'])) { return array_values((array)$wheels[$wid]['segments']); } $first = is_array($wheels) ? reset($wheels) : null; return (is_array($first) && !empty($first['segments'])) ? array_values((array)$first['segments']) : []; })((string) get_post_meta($pid, '_sn_wheel_id', true), $sn_wheels_for_invoice),
			];
		}
		$duplicate_subscription_ids = [];
		$current_subscription_ids = array_values(array_filter(array_unique(array_map('intval', array_column(array_filter($items_out, static function ($item) {
			return sanitize_key((string) ($item['product_type'] ?? '')) === 'subscription';
		}), 'product_id')))));
		if ($current_subscription_ids && class_exists('SN_Customer_Portal')) {
			$previous_subscription_ids = SN_Customer_Portal::instance()->purchased_subscription_product_ids(
				(string) ($invoice->customer_phone ?? ''),
				absint($invoice->customer_wp_id ?? 0),
				(int) $invoice->id
			);
			$duplicate_subscription_ids = array_values(array_intersect($current_subscription_ids, $previous_subscription_ids));
		}
		$duplicate_subscription_warning = $duplicate_subscription_ids
			? 'مشتری گرامی، شما قبلا این اشتراک را خریداری کرده اید و در حال خرید دوباره همین نوع اشتراک می باشید'
			: '';
		$original_total = 0.0;
		foreach ($items_out as $io) {
			$original_unit = (! empty($io['has_sale']) && (float) $io['regular_price'] > 0) ? (float) $io['regular_price'] : (float) $io['unit_price'];
			$original_total += ! empty($io['is_free']) ? 0 : ($original_unit * max(1, (int) $io['qty']));
		}
		if (SN_Sales_Catalog::invoice_snapshot($invoice) && isset($invoice->original_total)) { $original_total = (float) $invoice->original_total; }
		$final_total = (float) (($invoice->final_total ?? 0) ?: ($invoice->product_price ?? 0));
		$payment_totals = $this->sn_invoice_payment_totals($invoice);
		$payment_gate = $this->sn_invoice_customer_payment_gate($invoice, 'view');
        $invoice_transactions = SN_Payment_Transactions::rows($invoice);
		if ($public_customer_access && empty($payment_gate['allowed'])) {
			// Do not disclose destination card data to a customer when no active payment is payable.
			$card_number = '';
			$card_owner = '';
		}
		$payment_stages = [];
		$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $stage_table)) === $stage_table) {
			$payment_stages = $wpdb->get_results($wpdb->prepare("SELECT stage_no,stage_type,requested_amount,status,pay_method,payment_source,approved_at,paid_at,created_at FROM {$stage_table} WHERE invoice_id=%d ORDER BY stage_no ASC", (int)$invoice->id), ARRAY_A) ?: [];
			$stage_type_labels = ['full'=>'پرداخت کامل','partial'=>'پیش‌پرداخت','remaining'=>'تکمیل مانده'];
			foreach ($payment_stages as &$payment_stage) {
				$stage_date = (string)($payment_stage['approved_at'] ?: ($payment_stage['paid_at'] ?: $payment_stage['created_at']));
				$payment_stage['status_label'] = SN_Helpers::status_label((string)$payment_stage['status']);
				$payment_stage['stage_type_label'] = $stage_type_labels[(string)$payment_stage['stage_type']] ?? 'پرداخت مرحله‌ای';
				$payment_stage['display_date_jalali'] = SN_Helpers::gregorian_to_jalali_date($stage_date);
			}
			unset($payment_stage);
		}
		$dot_payment_context = class_exists('SN_Dot_Flow') ? SN_Dot_Flow::instance()->invoice_conversion_payment_context((int) $invoice->id) : [];
		$response_payment_plan = (string) $payment_totals['plan'];
		$response_payment_total = (float) $payment_totals['total'];
		$response_paid_total = (float) $payment_totals['paid'];
		$response_remaining = (float) $payment_totals['remaining'];
		$response_stage_no = (int) $payment_totals['stage_no'];
		$response_is_fully_paid = ! empty($payment_gate['fully_paid']);
		if (! empty($dot_payment_context['is_dot_conversion_payment'])) {
			$response_payment_plan = (string) ($dot_payment_context['payment_plan'] ?? $response_payment_plan);
			$response_payment_total = (float) ($dot_payment_context['payment_total_amount'] ?? $response_payment_total);
			$response_paid_total = (float) ($dot_payment_context['paid_total_amount'] ?? $response_paid_total);
			$response_remaining = (float) ($dot_payment_context['remaining_amount'] ?? $response_remaining);
			$response_stage_no = (int) ($dot_payment_context['current_payment_stage'] ?? $response_stage_no);
			$response_is_fully_paid = ! empty($dot_payment_context['is_completed']);
			$payment_stages = is_array($dot_payment_context['payment_stages'] ?? null) ? $dot_payment_context['payment_stages'] : $payment_stages;
		}
		$response_is_staged_payment = $response_payment_plan === 'partial';
		$response_payment_block_reason = (string) ($payment_gate['message'] ?? '');
		if (! $response_is_staged_payment && strpos($response_payment_block_reason, 'مرحله پرداخت') !== false) {
			$response_payment_block_reason = 'پرداخت این فاکتور در حال حاضر فعال نیست.';
		}
		$discount_total = max(0, $original_total - $final_total);
		if (isset($invoice->discount_amount)) { $discount_total = max($discount_total, (float) $invoice->discount_amount); }
		if (isset($invoice->coupon_discount_amount)) { $discount_total = max($discount_total, (float) $invoice->coupon_discount_amount + (float)($invoice->discount_amount ?? 0)); }
		$wheel_used = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoice_wheel WHERE invoice_id=%d", (int) $invoice->id));
		$payment_reward_claim = null;
		$payment_reward_table = $wpdb->prefix . 'sn_payment_reward_claims';
		if ($this->sn_payment_rewards_enabled() && $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $payment_reward_table)) === $payment_reward_table) {
			$payment_reward_claim = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$payment_reward_table} WHERE invoice_id=%d ORDER BY id DESC LIMIT 1", (int) $invoice->id), ARRAY_A);
		}

		SN_Helpers::send_json(true, '', [
			'invoice_info_access_version' => $invoice_info_access_version,
			'invoice' => [
				'catalog_discounts' => SN_Sales_Catalog::invoice_snapshot($invoice),
				'id'             => $invoice->id,
				'code'           => $invoice->invoice_code,
				'customer_name'  => $invoice->customer_name,
				'customer_phone' => $invoice->customer_phone,
				'customer_phone_secondary' => (string)($invoice->customer_phone_secondary ?? ''),
				'province'       => $invoice->province,
				'city'           => $invoice->city,
				'product_id'     => $invoice->product_id,
				'product_name'   => get_the_title($invoice->product_id),
				'product_price'  => (float) $invoice->product_price,
				'price_fmt'      => SN_Helpers::format_price((float) $invoice->product_price),
				'final_price_fmt'=> SN_Helpers::format_price($final_total),
				'original_total'  => $original_total,
				'discount_total'  => $discount_total,
				'final_total'     => $final_total,
				'payment_plan' => $response_payment_plan,
				'payment_total_amount' => $response_payment_total,
				'current_due_amount' => $payment_totals['due'],
				'paid_total_amount' => $response_paid_total,
				'remaining_amount' => $response_remaining,
				'current_payment_stage' => $response_stage_no,
				'is_staged_payment' => $response_is_staged_payment,
					'payment_workflow_status' => $payment_totals['workflow_status'],
					'payment_allowed' => ! empty($payment_gate['allowed']),
					'payment_block_reason' => $response_payment_block_reason,
					'is_fully_paid' => $response_is_fully_paid,
				'is_dot_conversion_payment' => ! empty($dot_payment_context['is_dot_conversion_payment']),
				'dot_case_id' => (int) ($dot_payment_context['case_id'] ?? 0),
				'dot_option_title' => (string) ($dot_payment_context['option_title'] ?? ''),
				'dot_payment_type' => (string) ($dot_payment_context['payment_type'] ?? ''),
				'dot_payment_type_label' => (string) ($dot_payment_context['payment_type_label'] ?? ''),
				'payment_stages' => $response_is_staged_payment ? $payment_stages : [],
				'coupon_code'    => isset($invoice->coupon_code) ? (string) $invoice->coupon_code : '',
				'coupon_discount_amount' => isset($invoice->coupon_discount_amount) ? (float) $invoice->coupon_discount_amount : 0,
				'status'         => $invoice->status,
				'status_label'   => SN_Helpers::status_label((string) $invoice->status),
				'issued_at_jalali' => SN_Helpers::gregorian_to_jalali_date((string)($invoice->created_at ?? '')),
				'receipt_url'     => isset($invoice->receipt_url) ? $invoice->receipt_url : '',
                'receipt_urls' => SN_Helpers::receipt_urls($invoice),
                'transactions' => $invoice_transactions,
                'transaction_summary' => SN_Payment_Transactions::summary($invoice_transactions,(int)$payment_totals['stage_no'],(float)$payment_totals['due']),
				'manual_paid_at_jalali' => isset($invoice->manual_paid_at_jalali) ? $invoice->manual_paid_at_jalali : '',
				'items'          => $items_out,
				'duplicate_subscription_purchase' => ! empty($duplicate_subscription_ids),
				'duplicate_subscription_product_ids' => $duplicate_subscription_ids,
				'duplicate_subscription_warning' => $duplicate_subscription_warning,
				'discount_amount'=> isset($invoice->discount_amount) ? (float) $invoice->discount_amount : 0,
				'wheel_reward_summary' => isset($invoice->wheel_reward_summary) ? (string) $invoice->wheel_reward_summary : '',
				'wheel_used'     => $wheel_used > 0,
				'payment_reward_claim_submitted' => ! empty($payment_reward_claim),
				'payment_reward_claim_phone' => ! empty($payment_reward_claim['reward_phone']) ? (string) $payment_reward_claim['reward_phone'] : '',
				'payment_reward_claim_sms_status' => ! empty($payment_reward_claim['sms_status']) ? (string) $payment_reward_claim['sms_status'] : '',
				'is_paid'        => ! empty($dot_payment_context['is_dot_conversion_payment']) ? $response_is_fully_paid : ($payment_totals['remaining'] <= 0 && in_array((string) $invoice->status, ['paid','approved'], true)),
			],
			'card'    => ['number' => $card_number, 'owner' => $card_owner],
			'settings' => [
				'card_to_card_enabled' => $card_to_card_enabled ? '1' : '0',
				'wheel_company_name' => get_option('sn_wheel_company_name', ''),
				'lottery_text_template' => get_option('sn_lottery_text_template', 'با پرداخت این فاکتور {count} شانس برای شرکت در قرعه‌کشی {company} دریافت می‌کنید.'),
				'payment_reward_text' => get_option('sn_payment_reward_text', 'اگر این محصول را از درگاه پرداخت آنلاین تهیه کنید، بعد از پرداخت جایزه یا گردونه شانس برای شما فعال می‌شود.'),
				'payment_reward_form_text' => get_option('sn_payment_reward_form_text', 'شماره موبایل فردی را وارد کنید که می‌خواهید جایزه برای او ثبت و پیامک شود. شماره نباید همان شماره خریدار فاکتور باشد.'),
				'recontact_popup_text' => get_option('sn_recontact_popup_text', 'اگر پیش از پرداخت فاکتور از کارشناس خود سوالی دارید، دکمه ارتباط مجدد با کارشناس را بزنید.'),
				'info_show_product_info' => get_option('sn_invoice_info_show_product_info', '1'),
				'info_show_short_desc' => get_option('sn_invoice_info_show_short_desc', '1'),
				'info_show_price' => get_option('sn_invoice_info_show_price', '1'),
				'info_show_lottery' => get_option('sn_invoice_info_show_lottery', '1'),
				'info_show_wheel' => get_option('sn_invoice_info_show_wheel', '1'),
				'info_show_coupon' => get_option('sn_invoice_info_show_coupon', '1'),
				'info_show_image' => get_option('sn_invoice_info_show_image', '1'),
				'info_show_gallery' => get_option('sn_invoice_info_show_gallery', '1'),
			],
		]);
	}


	private function sn_parse_money_value($value): float
	{
		$value = (string) $value;
		$value = strtr($value, ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);
		$value = preg_replace('/[^0-9.]/', '', $value);
		return max(0, (float) $value);
	}

	private function sn_partial_payment_presets(): array
	{
		$raw = (string) get_option('sn_partial_payment_presets', '1000000,2000000,3000000,5000000');
		$parts = preg_split('/[,،;\n\r]+/u', $raw) ?: [];
		$out = [];
		foreach ($parts as $part) {
			$amount = $this->sn_parse_money_value($part);
			if ($amount > 0) { $out[(string) (int) round($amount)] = $amount; }
		}
		$out = array_values($out);
		sort($out, SORT_NUMERIC);
		return $out ?: [1000000, 2000000, 3000000, 5000000];
	}


	private function sn_invoice_max_products(): int
	{
		$raw = get_option('sn_invoice_max_products', '2');
		$limit = is_numeric($raw) ? (int) $raw : 2;
		return max(0, $limit);
	}

	private function sn_seller_manual_invoice_enabled(): bool
	{
		$user_id = get_current_user_id();
		return $user_id > 0 && $this->sn_effective_manual_invoice_access_mode($user_id) === 'allow';
	}

	/** An explicit personal setting wins; otherwise inherit the team's supervisor setting. */
	private function sn_effective_manual_invoice_access_mode(int $user_id): string
	{
		$mode = $this->sn_manual_invoice_access_mode($user_id);
		if ($mode !== 'inherit' || $user_id < 1) { return $mode; }
		$supervisor_id = $this->sn_team_invoice_supervisor_for_user($user_id);
		if ($supervisor_id > 0 && $supervisor_id !== $user_id) {
			return $this->sn_manual_invoice_access_mode($supervisor_id);
		}
		return 'inherit';
	}

	private function sn_manual_invoice_access_mode(int $user_id): string
	{
		if ($user_id < 1) { return 'inherit'; }
		$mode = sanitize_key((string) get_user_meta($user_id, 'sn_manual_invoice_access', true));
		return in_array($mode, ['allow','deny'], true) ? $mode : 'inherit';
	}

	private function sn_extra_number_request_access_mode(int $user_id): string
	{
		if ($user_id < 1) { return 'inherit'; }
		$mode = sanitize_key((string) get_user_meta($user_id, 'sn_extra_number_request_access', true));
		return in_array($mode, ['allow','deny'], true) ? $mode : 'inherit';
	}

	private function sn_user_can_request_extra_number(int $user_id): bool
	{
		if ($user_id < 1) { return false; }
		if (user_can($user_id, 'manage_options')) { return true; }
		$mode = $this->sn_extra_number_request_access_mode($user_id);
		if ($mode === 'allow') { return true; }
		if ($mode === 'deny') { return false; }
		$user = get_user_by('id', $user_id);
		if (! $user) { return false; }
		return in_array('sn_seller', (array) $user->roles, true) || $this->sn_hr_position_for_user($user_id) === 'seller';
	}

	private function sn_team_invoice_source_mode(int $supervisor_user_id): string
	{
		if ($supervisor_user_id < 1) { return 'manual'; }
		$mode = sanitize_key((string) get_user_meta($supervisor_user_id, 'sn_team_invoice_source_mode', true));
		return in_array($mode, ['manual','mis_only'], true) ? $mode : 'manual';
	}

	/** Resolve the nearest sales/Operations supervisor that governs invoice source. */
	private function sn_team_invoice_supervisor_for_user(int $user_id): int
	{
		if ($user_id < 1) { return 0; }
		$supervisor_positions = ['supervisor','senior_supervisor','operations_sales_supervisor'];
		if (in_array($this->sn_hr_position_for_user($user_id), $supervisor_positions, true)) { return $user_id; }
		$user = get_user_by('id', $user_id);
		if ($user && array_intersect((array) $user->roles, ['sn_supervisor','sn_senior_supervisor','sn_operations_sales_supervisor'])) { return $user_id; }
		if (! class_exists('SN_Hierarchy_Service')) { return 0; }
		$hierarchy = new SN_Hierarchy_Service();
		$current = $user_id; $seen = [];
		for ($depth = 0; $depth < 20; $depth++) {
			if (isset($seen[$current])) { break; }
			$seen[$current] = true;
			$parent = (int) $hierarchy->get_current_parent_user_id($current);
			if ($parent < 1 || $parent === $current) { break; }
			$parent_user = get_user_by('id', $parent);
			if (in_array($this->sn_hr_position_for_user($parent), $supervisor_positions, true)
				|| ($parent_user && array_intersect((array) $parent_user->roles, ['sn_supervisor','sn_senior_supervisor','sn_operations_sales_supervisor']))) { return $parent; }
			$current = $parent;
		}
		// Legacy seller accounts have only this relation; never override an existing HR chain.
		if ($current === $user_id && ! $hierarchy->get_current_parent_user_id($user_id)) {
			$legacy_id = absint(get_user_meta($user_id, 'sn_supervisor_id', true));
			$legacy_user = $legacy_id > 0 ? get_user_by('id', $legacy_id) : false;
			if ($legacy_user && $legacy_id !== $user_id && (in_array($this->sn_hr_position_for_user($legacy_id), $supervisor_positions, true)
				|| array_intersect((array) $legacy_user->roles, ['sn_supervisor','sn_senior_supervisor','sn_operations_sales_supervisor']))) { return $legacy_id; }
		}
		return 0;
	}

	private function sn_team_invoice_source_mode_for_user(int $user_id): string
	{
		$supervisor_id = $this->sn_team_invoice_supervisor_for_user($user_id);
		return $supervisor_id > 0 ? $this->sn_team_invoice_source_mode($supervisor_id) : 'manual';
	}

	private function sn_user_can_create_manual_invoice(int $user_id): bool
	{
		if ($user_id < 1) { return false; }
		if (user_can($user_id, 'manage_options')) { return true; }
		$mode = $this->sn_effective_manual_invoice_access_mode($user_id);
		if ($mode === 'allow') { return true; }
		if ($mode === 'deny') { return false; }
		$user = get_user_by('id', $user_id);
		if (! $user) { return false; }
		$position = $this->sn_hr_position_for_user($user_id);
		$roles = (array) $user->roles;
		return in_array('sn_seller', $roles, true)
			|| in_array('sn_supervisor', $roles, true)
			|| in_array('sn_converter', $roles, true)
			|| in_array($position, ['seller','converter','supervisor','senior_supervisor','sales_manager','sales_deputy'], true);
	}

	private function sn_invoice_payment_totals($invoice): array
	{
		$inv = is_object($invoice) ? $invoice : (object) $invoice;
		$catalog_snapshot = trim((string) ($inv->catalog_discounts_snapshot ?? ''));
		$catalog_discount = max(0, (float) (($inv->discount_total ?? 0) ?: ($inv->discount_amount ?? 0)));
		$catalog_final = max(0, (float) ($inv->final_total ?? 0));
		// Catalog-discount invoices must always charge the snapshotted net total.
		// This also repairs v2.0.142 rows at read time if payment_total_amount or
		// product_price still contains the pre-discount gross amount.
		if ($catalog_snapshot !== '' && $catalog_discount > 0 && $catalog_final > 0) {
			$total = $catalog_final;
		} else {
			$total = max(0, (float) (($inv->payment_total_amount ?? 0) ?: (($inv->final_total ?? 0) ?: ($inv->product_price ?? 0))));
		}
		$status = (string) ($inv->status ?? '');
		$workflow = (string) ($inv->payment_workflow_status ?? '');
		$paid = max(0, (float) ($inv->paid_total_amount ?? 0));
		$has_stored_remaining = property_exists($inv, 'remaining_amount') && $inv->remaining_amount !== null && $inv->remaining_amount !== '';
		$stored_remaining = $has_stored_remaining ? max(0, (float) $inv->remaining_amount) : null;

		if ($paid <= 0 && in_array($status, ['paid','approved'], true) && $workflow !== 'awaiting_assignment') {
			$paid = $total;
		} elseif ($paid <= 0 && $has_stored_remaining && $stored_remaining < $total - 0.5 && in_array($status, ['partial_paid','receipt_uploaded','pending_financial_approval','rejected'], true)) {
			// Compatibility for older staged invoices that persisted remaining_amount
			// but did not reliably persist paid_total_amount.
			$paid = max(0, $total - $stored_remaining);
		}
		$paid = min($total, $paid);

		// The three displayed monetary values must always satisfy:
		// total = approved paid + remaining.  Older/stale remaining_amount values
		// must not leak into Finance or customer staged-payment summaries.
		$calculated_remaining = max(0, $total - $paid);
		$remaining = $has_stored_remaining ? $stored_remaining : $calculated_remaining;
		if (abs($remaining - $calculated_remaining) > 0.5) {
			$remaining = $calculated_remaining;
		}

		if (property_exists($inv, 'current_due_amount') && $inv->current_due_amount !== null && $inv->current_due_amount !== '') {
			$due = max(0, (float) $inv->current_due_amount);
		} else {
			$due = in_array($status, ['paid','approved','cancelled','payment_archived'], true) ? 0 : ($remaining > 0 ? $remaining : $total);
		}
		$due = min($remaining, $due);
		return [
			'plan' => in_array((string) ($inv->payment_plan ?? ''), ['full','partial'], true) ? (string) $inv->payment_plan : 'full',
			'total' => $total,
			'paid' => $paid,
			'remaining' => $remaining,
			'due' => $due,
			'stage_no' => max(1, (int) ($inv->current_payment_stage ?? 1)),
			'workflow_status' => $workflow !== '' ? $workflow : (in_array($status, ['paid','approved'], true) ? 'completed' : 'awaiting_payment'),
		];
	}

	private function sn_invoice_customer_payment_gate($invoice, string $route = 'view'): array
	{
		$inv = is_object($invoice) ? $invoice : (object) $invoice;
		$totals = $this->sn_invoice_payment_totals($inv);
		$status = sanitize_key((string) ($inv->status ?? ''));
		$workflow = sanitize_key((string) ($totals['workflow_status'] ?? ''));
		$fully_paid = (float) $totals['remaining'] <= 0.5 || $workflow === 'completed';

		if (! empty($inv->id) && class_exists('SN_Dot_Flow') && SN_Dot_Flow::instance()->is_gifted_assessment_invoice((int) $inv->id)) {
			return ['allowed'=>false, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>'هزینه اعتبارسنجی این فاکتور از طرف شرکت هدیه شده است و دیگر نباید پرداخت شود. لینک انتخاب برای مشتری پیامک شده است.'];
		}

		if ($fully_paid) {
			return ['allowed'=>false, 'fully_paid'=>true, 'totals'=>$totals, 'message'=>'این فاکتور به‌طور کامل تسویه شده است و پرداخت دیگری برای آن پذیرفته نمی‌شود.'];
		}
		if ((float) $totals['total'] <= 0.5) {
			return ['allowed'=>false, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>'این فاکتور مبلغ قابل پرداختی ندارد.'];
		}
		if (in_array($status, ['cancelled','payment_archived'], true) || $workflow === 'archived') {
			return ['allowed'=>false, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>'این فاکتور بایگانی یا لغو شده و قابل پرداخت نیست.'];
		}
		if ((float) $totals['due'] <= 0.5 || $workflow === 'awaiting_assignment') {
			return ['allowed'=>false, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>'مرحله پرداخت جدیدی برای این فاکتور صادر نشده است.'];
		}

		$allowed_statuses = ['pending','pre_invoice','pending_payment','rejected','recontact_requested'];
		if (in_array($route, ['view','card','manual','upload'], true)) {
			// Preserve the existing receipt-replacement flow while finance is reviewing a submitted payment.
			$allowed_statuses = array_merge($allowed_statuses, ['receipt_uploaded','pending_financial_approval','card_submitted']);
		}
		if (! in_array($status, $allowed_statuses, true)) {
			return ['allowed'=>false, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>'این فاکتور در وضعیت قابل پرداخت نیست.'];
		}
		return ['allowed'=>true, 'fully_paid'=>false, 'totals'=>$totals, 'message'=>''];
	}

	/**
	 * Synchronize staged-payment totals after a discount changes the invoice total.
	 * Discounts are intentionally blocked after the first approved payment so paid history is immutable.
	 */
	private function sn_sync_unpaid_invoice_payment_total(int $invoice_id, float $new_total): array
	{
		global $wpdb;
		$new_total = max(0, $new_total);
		if ($invoice_id < 1 || $new_total <= 0) { return ['success'=>false,'message'=>'مبلغ نهایی فاکتور نامعتبر است']; }
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $invoice_id));
		if (! $invoice) { return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
		$totals = $this->sn_invoice_payment_totals($invoice);
		if ($totals['paid'] > 0.5) { return ['success'=>false,'message'=>'بعد از تایید اولین پرداخت، مبلغ یا تخفیف فاکتور قابل تغییر نیست']; }
		$stage_no = max(1, (int) $totals['stage_no']);
		$old_due = $totals['due'] > 0 ? $totals['due'] : $new_total;
		$new_due = min($new_total, $old_due);
		if ($new_due <= 0) { $new_due = $new_total; }
		$fields = [
			'payment_total_amount'=>$new_total,
			'paid_total_amount'=>0,
			'remaining_amount'=>$new_total,
			'current_due_amount'=>$new_due,
			'payment_workflow_status'=>'awaiting_payment',
			'updated_at'=>current_time('mysql'),
		];
		$ok = false !== $wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, $fields), ['id'=>$invoice_id]);
		if (! $ok) { return ['success'=>false,'message'=>'همگام‌سازی مبلغ پرداخت انجام نشد']; }
		$stage = $this->sn_current_invoice_payment_stage($invoice_id, $stage_no);
		if ($stage && ! in_array((string)$stage->status, ['paid','approved'], true)) {
			$stage_type = $new_due >= $new_total ? 'full' : (string)($stage->stage_type ?? 'partial');
			$wpdb->update($wpdb->prefix.'sn_invoice_payment_stages', [
				'requested_amount'=>$new_due,
				'stage_type'=>$stage_type,
				'updated_at'=>current_time('mysql'),
			], ['id'=>(int)$stage->id]);
		}
		return ['success'=>true,'total'=>$new_total,'due'=>$new_due,'stage_no'=>$stage_no];
	}

	private function sn_create_invoice_payment_stage(int $invoice_id, int $stage_no, string $stage_type, float $amount, int $issued_by, string $note = ''): bool
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_invoice_payment_stages';
		if ($invoice_id < 1 || $stage_no < 1 || $amount <= 0 || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) { return false; }
		$existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE invoice_id=%d AND stage_no=%d", $invoice_id, $stage_no));
		if ($existing && in_array((string) $existing->status, ['paid','approved'], true)) { return false; }
		$data = [
			'invoice_id' => $invoice_id,
			'stage_no' => $stage_no,
			'stage_type' => in_array($stage_type, ['full','partial','remaining'], true) ? $stage_type : 'partial',
			'requested_amount' => $amount,
			'status' => 'pending',
			'issued_by_user_id' => $issued_by ?: null,
			'note' => sanitize_textarea_field($note),
			'updated_at' => current_time('mysql'),
		];
		if ($existing) {
			return false !== $wpdb->update($table, $data, ['id' => (int) $existing->id]);
		}
		$data['created_at'] = current_time('mysql');
		return (bool) $wpdb->insert($table, $data);
	}

	private function sn_current_invoice_payment_stage(int $invoice_id, int $stage_no = 0): ?object
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_invoice_payment_stages';
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) { return null; }
		if ($stage_no > 0) { return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE invoice_id=%d AND stage_no=%d", $invoice_id, $stage_no)); }
		return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE invoice_id=%d ORDER BY stage_no DESC LIMIT 1", $invoice_id));
	}

	private function sn_create_or_reset_payment_action_item(int $invoice_id, object $invoice): int
	{
		global $wpdb;
		$this->sn_distribution_ensure_schema();
		if (! $this->sn_distribution_tables_ready()) { return 0; }
		$this->sn_distribution_ensure_seller_inline_columns();
		$table = $wpdb->prefix . 'sn_distribution_items';
		$seller_id = (int) (($invoice->original_seller_id ?? 0) ?: ($invoice->seller_id ?? 0));
		if ($seller_id < 1) { return 0; }
		$owner_position = $this->sn_hr_position_for_user($seller_id);
		if (! in_array($owner_position, ['seller','converter','supervisor','senior_supervisor','sales_manager','sales_deputy'], true)) { $owner_position = 'seller'; }
		$existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE source_type='paid_invoice_referral' AND source_id=%d AND workflow_kind='invoice_payment_completion' ORDER BY id DESC LIMIT 1", $invoice_id));
		$phone = SN_Helpers::normalize_mobile((string) ($invoice->customer_phone ?? ''));
		$data = $this->sn_distribution_filter_existing_columns_fresh($table, [
			'source_type' => 'paid_invoice_referral',
			'source_id' => $invoice_id,
			'current_owner_user_id' => $seller_id,
			'current_owner_position' => $owner_position,
			'current_step_order' => 999,
			'final_seller_user_id' => $seller_id,
			'live_lead_id' => null,
			'status' => 'needs_payment_assignment',
			'seller_customer_name' => sanitize_text_field((string) ($invoice->customer_name ?? '')),
			'seller_province' => sanitize_text_field((string) ($invoice->province ?? '')),
			'seller_city' => sanitize_text_field((string) ($invoice->city ?? '')),
			'customer_phone' => $phone,
			'normalized_phone' => $phone,
			'ref_invoice_id' => $invoice_id,
			'ref_product_id' => (int) ($invoice->product_id ?? 0),
			'referral_original_seller_id' => $seller_id,
			'referral_target_scope' => 'payment_completion',
			'referral_note' => 'صدور مرحله بعد پرداخت فاکتور مرحله‌ای',
			'workflow_kind' => 'invoice_payment_completion',
			'workflow_assigned_by_user_id' => null,
			'updated_at' => current_time('mysql'),
		]);
		if ($existing) {
			$ok = false !== $wpdb->update($table, $data, ['id' => (int) $existing->id]);
			$item_id = $ok ? (int) $existing->id : 0;
		} else {
			$data['created_at'] = current_time('mysql');
			$ok = (bool) $wpdb->insert($table, $data);
			$item_id = $ok ? (int) $wpdb->insert_id : 0;
		}
		if ($item_id) {
			$this->sn_distribution_log($item_id, 'invoice_payment_action_created', get_current_user_id() ?: 0, 0, $seller_id, 'invoice', $owner_position, 999, 'ایجاد نیاز به اقدام برای مرحله بعد پرداخت فاکتور', ['invoice_id'=>$invoice_id,'original_seller_id'=>$seller_id,'owner_position'=>$owner_position]);
		}
		return $item_id;
	}

	private function sn_close_payment_action_item(int $invoice_id, string $status = 'payment_completed', int $actor_id = 0, string $note = ''): void
	{
		global $wpdb;
		if (! $this->sn_distribution_tables_ready()) { return; }
		$this->sn_distribution_ensure_seller_inline_columns();
		$table = $wpdb->prefix . 'sn_distribution_items';
		$item = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE source_type='paid_invoice_referral' AND source_id=%d AND workflow_kind='invoice_payment_completion' ORDER BY id DESC LIMIT 1", $invoice_id));
		if (! $item) { return; }
		$wpdb->update($table, $this->sn_filter_existing_columns($table, ['status'=>$status,'seller_notes'=>$note,'updated_at'=>current_time('mysql')]), ['id'=>(int)$item->id]);
		$this->sn_distribution_log((int)$item->id, $status, $actor_id, (int)($item->current_owner_user_id ?? 0), (int)($item->current_owner_user_id ?? 0), (string)($item->current_owner_position ?? ''), (string)($item->current_owner_position ?? ''), 999, $note, ['invoice_id'=>$invoice_id]);
	}

	private function sn_finalize_current_payment_stage(int $invoice_id, string $pay_method, string $payment_source, string $payment_ref_id = '', int $approved_by = 0, string $final_status = 'paid', int $stage_no_override = 0): array
	{
		$this->maybe_create_tables();
		global $wpdb;
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
		$wpdb->query('START TRANSACTION');
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $invoice_id));
		if (! $invoice) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
		$totals = $this->sn_invoice_payment_totals($invoice);
		$is_archived = $totals['workflow_status'] === 'archived' || in_array((string)$invoice->status, ['cancelled','payment_archived'], true);
		$revived_from_archive = $is_archived && $pay_method === 'online' && $stage_no_override > 0;
		if ($is_archived && ! $revived_from_archive) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'این فاکتور بایگانی یا لغو شده است']; }
		$current_stage_no = max(1, (int) $totals['stage_no']);
		$stage_no = $stage_no_override > 0 ? $stage_no_override : $current_stage_no;
		$stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $invoice_id, $stage_no));
		if ($stage_no_override > 0 && $stage_no !== $current_stage_no && (! $stage || ! in_array((string)$stage->status, ['paid','approved'], true))) {
			$wpdb->query('ROLLBACK');
			return ['success'=>false,'message'=>'بازگشت درگاه مربوط به یک مرحله قدیمی یا نامعتبر است'];
		}
		if (! $stage) {
			if ($stage_no_override > 0) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مرحله پرداخت درخواستی یافت نشد']; }
			$due_fallback = $totals['due'] > 0 ? $totals['due'] : ($totals['remaining'] > 0 ? $totals['remaining'] : $totals['total']);
			if (! $this->sn_create_invoice_payment_stage($invoice_id, $stage_no, $stage_no === 1 ? $totals['plan'] : 'partial', $due_fallback, (int)($invoice->current_stage_issued_by_user_id ?? $invoice->issued_by_user_id ?? $invoice->seller_id ?? 0), 'ساخت خودکار مرحله برای سازگاری')) {
				$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مرحله پرداخت قابل بازیابی نیست'];
			}
			$stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $invoice_id, $stage_no));
		}
		if ($stage && in_array((string)$stage->status, ['paid','approved'], true)) {
			if (false === $wpdb->query('COMMIT')) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت نهایی تأیید پرداخت انجام نشد']; }
			$fresh = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $invoice_id));
			$fresh_totals = $fresh ? $this->sn_invoice_payment_totals($fresh) : $totals;
			$operations_owned_payment = class_exists('SN_Operations_Flow') && SN_Operations_Flow::instance()->is_upgrade_invoice($invoice_id);
			if ($fresh && $fresh_totals['remaining'] > 0 && $fresh_totals['due'] <= 0 && $fresh_totals['workflow_status'] === 'awaiting_assignment' && ! $operations_owned_payment) {
				$action_exists = false;
				if ($this->sn_distribution_tables_ready()) {
					$action_exists = (bool) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}sn_distribution_items WHERE source_type='paid_invoice_referral' AND source_id=%d AND workflow_kind='invoice_payment_completion' ORDER BY id DESC LIMIT 1", $invoice_id));
				}
				if (! $action_exists) { $this->sn_create_or_reset_payment_action_item($invoice_id, $fresh); }
			} elseif ($fresh && $fresh_totals['remaining'] <= 0) {
				$this->sn_close_payment_action_item($invoice_id, 'payment_completed', $approved_by ?: get_current_user_id(), 'واریزی کامل شده است');
			}
			return ['success'=>true,'already'=>true,'completed'=>$fresh_totals['remaining'] <= 0,'remaining'=>$fresh_totals['remaining'],'paid'=>$fresh_totals['paid'],'total'=>$fresh_totals['total'],'status'=>(string)($fresh->status ?? ($fresh_totals['remaining'] <= 0 ? 'paid' : 'partial_paid'))];
		}
		$due = max(0, (float) ($stage->requested_amount ?? $totals['due']));
        if ($pay_method === 'card' || $pay_method === 'admin') {
            $pending_transactions = SN_Payment_Transactions::pending_rows($invoice_id,$stage_no);
            $transaction_summary = SN_Payment_Transactions::summary($pending_transactions,$stage_no,$due);
            if ($transaction_summary['independent'] && !$transaction_summary['ready']) {
                $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مجموع تراکنش‌های در انتظار بررسی باید با مبلغ این مرحله برابر باشد؛ هنوز مبلغ کامل ثبت نشده یا مغایرت وجود دارد'];
            }
        }

		if ($due <= 0 || $totals['total'] <= 0) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ مرحله پرداخت نامعتبر است']; }
		if ($due - $totals['remaining'] > 0.5) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ این مرحله از مانده واقعی فاکتور بیشتر است؛ ابتدا مبلغ مرحله را اصلاح کنید']; }
		$new_paid = min($totals['total'], max(0, $totals['paid']) + $due);
		$new_remaining = max(0, $totals['total'] - $new_paid);
		$completed = $new_remaining < 0.5;
		$stage_status = $approved_by > 0 || $pay_method === 'card' || $final_status === 'approved' ? 'approved' : 'paid';
		$stage_ok = false !== $wpdb->update($stage_table, [
			'status'=>$stage_status,
			'pay_method'=>sanitize_key($pay_method),
			'payment_source'=>sanitize_key($payment_source),
			'payment_ref_id'=>sanitize_text_field($payment_ref_id),
			'approved_by_user_id'=>$approved_by ?: null,
			'approved_at'=>($approved_by || $final_status === 'approved') ? current_time('mysql') : null,
			'paid_at'=>current_time('mysql'),
			'updated_at'=>current_time('mysql'),
		], ['id'=>(int)$stage->id]);
		if (! $stage_ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت مرحله پرداخت انجام نشد: '.($wpdb->last_error ?: 'خطای دیتابیس')]; }
		if ($pay_method === 'card') {
			$payment_update = $this->sn_filter_existing_columns($wpdb->prefix . 'sn_payments', [
				'status' => 'approved',
				'pay_method' => 'card',
				'updated_at' => current_time('mysql'),
			]);
			if ($payment_update) {
				$payment_rows_ok = $wpdb->query($wpdb->prepare(
					"UPDATE {$wpdb->prefix}sn_payments SET " . implode(', ', array_map(static function($col){ return "`{$col}`=%s"; }, array_keys($payment_update))) . " WHERE invoice_id=%d AND payment_stage_no=%d AND status='pending' AND (authority IS NULL OR authority='')",
					...array_merge(array_values($payment_update), [$invoice_id, $stage_no])
				));
                if ($payment_rows_ok === false) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت تأیید تراکنش‌ها انجام نشد؛ دوباره تلاش کنید']; }
			}
		}
		$invoice_data = [
			'payment_total_amount'=>$totals['total'],
			'paid_total_amount'=>$new_paid,
			'remaining_amount'=>$new_remaining,
			'current_due_amount'=>0,
			'pay_method'=>sanitize_key($pay_method),
			'payment_source'=>sanitize_key($payment_source),
			'updated_at'=>current_time('mysql'),
		];
		if ($revived_from_archive) {
			$invoice_data['payment_archived_at'] = null;
			$invoice_data['payment_archived_by'] = null;
			$invoice_data['payment_archive_reason'] = null;
		}
		if ($approved_by || $final_status === 'approved') {
			$invoice_data['approved_by']=$approved_by ?: null;
			$invoice_data['approved_at']=current_time('mysql');
			$invoice_data['financial_reviewed_by']=$approved_by ?: null;
			$invoice_data['financial_reviewed_at']=current_time('mysql');
		}
		if ($completed) {
			$resolved_final_status = in_array($final_status, ['paid','approved'], true) ? $final_status : ($approved_by ? 'approved' : 'paid');
			$invoice_data += [
				'status'=>$resolved_final_status,
				'invoice_status'=>$resolved_final_status,
				'payment_status'=>$resolved_final_status,
				'payment_workflow_status'=>'completed',
				'payment_completed_at'=>current_time('mysql'),
				'paid_at'=>current_time('mysql'),
			];
		} else {
			$invoice_data += [
				'status'=>'partial_paid',
				'invoice_status'=>'partial_paid',
				'payment_status'=>'partial_paid',
				'payment_workflow_status'=>'awaiting_assignment',
			];
		}
		$ok = false !== $wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, $invoice_data), ['id'=>$invoice_id]);
		if (! $ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت نتیجه پرداخت انجام نشد: '.($wpdb->last_error ?: 'خطای دیتابیس')]; }
        if (false === $wpdb->query('COMMIT')) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت نهایی تأیید پرداخت انجام نشد']; }
		$fresh = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $invoice_id));
		$this->sn_log_activity($invoice_id, (int)($invoice->lead_id ?? 0), $completed ? 'invoice_payment_completed' : 'invoice_partial_payment_approved', $completed ? 'واریزی فاکتور تکمیل شد' : 'پیش‌پرداخت تایید شد و فاکتور برای تکمیل واریزی ارجاع شد', ['stage_no'=>$stage_no,'stage_amount'=>$due,'paid_total'=>$new_paid,'remaining_amount'=>$new_remaining,'pay_method'=>$pay_method,'payment_source'=>$payment_source,'approved_by'=>$approved_by,'revived_from_archive'=>$revived_from_archive]);
		if ($fresh) {
			do_action('sn_invoice_payment_stage_approved', $invoice_id, $fresh, [
				'stage_no'=>$stage_no,
				'stage_amount'=>$due,
				'paid_total'=>$new_paid,
				'remaining_amount'=>$new_remaining,
				'completed'=>$completed,
				'pay_method'=>$pay_method,
				'payment_source'=>$payment_source,
				'approved_by'=>$approved_by,
			]);
		}
		if ($completed) {
			$this->sn_close_payment_action_item($invoice_id, 'payment_completed', $approved_by ?: get_current_user_id(), 'واریزی کامل شد');
			if ($fresh) { do_action('sn_invoice_paid', $invoice_id, $fresh); }
		} elseif ($fresh) {
			$operations_owned_payment = class_exists('SN_Operations_Flow') && SN_Operations_Flow::instance()->is_upgrade_invoice($invoice_id);
			if (! $operations_owned_payment) {
				$action_item_id = $this->sn_create_or_reset_payment_action_item($invoice_id, $fresh);
				if ($action_item_id < 1) {
					error_log(sprintf('SN staged payment: action item creation failed for invoice #%d after approved stage #%d', $invoice_id, $stage_no));
				}
			}
		}
		return ['success'=>true,'completed'=>$completed,'stage_no'=>$stage_no,'stage_amount'=>$due,'paid'=>$new_paid,'remaining'=>$new_remaining,'total'=>$totals['total'],'status'=>$completed ? (string)($fresh->status ?? $final_status) : 'partial_paid'];
	}

	private function sn_send_invoice_stage_sms(int $invoice_id, string $destination_phone = ''): bool
	{
		$this->sn_invoice_sms_last_error = '';
		global $wpdb;
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
		if (! $invoice) { return false; }
		$totals = $this->sn_invoice_payment_totals($invoice);
		$url = $this->sn_invoice_public_url($invoice);
		$card = $this->sn_resolve_invoice_card($invoice);
		$sms_amount = (float) ($totals['due'] ?? 0);
		if ($sms_amount <= 0.5) { $sms_amount = (float) ($totals['remaining'] ?? 0); }
		if ($sms_amount <= 0.5) { $sms_amount = (float) ($totals['total'] ?? 0); }
		$sms = new SN_SMS();
		$sent = (bool) $sms->send_invoice_link($destination_phone !== '' ? $destination_phone : (string)$invoice->customer_phone, (string)$invoice->invoice_code, $url, (string)$invoice->customer_name, number_format($sms_amount, 0, '', ','), $this->sn_card_to_card_enabled() ? (string)($card['number'] ?? '') : '');
		$this->sn_invoice_sms_last_error = $sms->get_last_error();
		return $sent;
	}

	private function sn_can_resend_invoice_sms($invoice): bool
	{
		if (! $invoice || ! is_user_logged_in()) { return false; }
		if (current_user_can('manage_options') || $this->sn_can_view_finance()) { return true; }
		$user = wp_get_current_user();
		$user_id = (int) $user->ID;
		$roles = (array) $user->roles;
		$position = $this->sn_hr_position_for_user($user_id);
		$invoice_id = (int) ($invoice->id ?? 0);
		if ($invoice_id < 1) { return false; }

		$is_manager = current_user_can('sn_view_sales_reports')
			|| (bool) array_intersect($roles, ['sn_supervisor', 'sn_senior_supervisor', 'sn_sales_manager'])
			|| in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy'], true);
		if ($is_manager) {
			if (class_exists('SN_Scope_Service') && (new SN_Scope_Service())->can_view_invoice($user_id, $invoice_id)) { return true; }
			return $this->sn_supervisor_can_access_invoice($invoice_id, $user_id);
		}

		$is_converter = in_array('sn_converter', $roles, true) || $position === 'converter';
		if ($is_converter && $this->sn_converter_can_access_invoice($invoice, $user_id)) { return true; }

		$is_seller = in_array('sn_seller', $roles, true) || $position === 'seller';
		if (! $is_seller || (int) ($invoice->seller_id ?? 0) !== $user_id) { return false; }
		if (! $this->sn_invoice_is_conversion_payment($invoice_id)) { return true; }
		return (int) ($invoice->issued_by_user_id ?? 0) === $user_id || $this->sn_user_owns_conversion_invoice($invoice_id, $user_id);
	}

	public function ajax_resend_invoice_sms(): void
	{
		try {
			$this->sn_resend_invoice_sms_request();
		} catch (Throwable $error) {
			error_log('SN invoice SMS request failed: ' . $error->getMessage() . ' at ' . $error->getFile() . ':' . $error->getLine());
			SN_Helpers::send_json(false, 'خطا در پردازش ارسال پیامک؛ جزئیات در گزارش خطای سرور ثبت شد.');
		}
	}

	private function sn_resend_invoice_sms_request(): void
	{
		if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
			SN_Helpers::send_json(false, 'نشست شما معتبر نیست؛ صفحه را تازه کنید و دوباره وارد شوید.');
			return;
		}
		$invoice_id = absint($_POST['invoice_id'] ?? 0);
		if ($invoice_id < 1) {
			SN_Helpers::send_json(false, 'فاکتور نامعتبر است');
			return;
		}
		global $wpdb;
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
		if (! $invoice) {
			SN_Helpers::send_json(false, 'فاکتور یافت نشد');
			return;
		}
		if (! $this->sn_can_resend_invoice_sms($invoice)) {
			SN_Helpers::send_json(false, 'به این فاکتور دسترسی ندارید');
			return;
		}
		$requested_phone = is_scalar($_POST['destination_phone'] ?? '') ? sanitize_text_field(wp_unslash((string)$_POST['destination_phone'])) : '';
		$phone = SN_Helpers::normalize_mobile($requested_phone !== '' ? $requested_phone : (string) ($invoice->customer_phone ?? ''));
		if (! SN_Helpers::is_valid_mobile($phone)) {
			SN_Helpers::send_json(false, 'شماره موبایل مشتری معتبر نیست');
			return;
		}
		$actor_id = get_current_user_id();
		$lock_key = 'sn_resend_invoice_sms_' . $actor_id . '_' . $invoice_id;
		if (get_transient($lock_key)) {
			SN_Helpers::send_json(false, 'پیامک همین فاکتور به‌تازگی ارسال شده است؛ کمی صبر کنید');
			return;
		}
		set_transient($lock_key, 1, 20);
		try {
			$sent = $this->sn_send_invoice_stage_sms($invoice_id, $phone);
		} catch (Throwable $error) {
			$sent = false;
			error_log('SN invoice SMS resend failed for invoice #' . $invoice_id . ': ' . $error->getMessage());
		}
		if (! $sent) {
			delete_transient($lock_key);
			try { $this->sn_log_activity($invoice_id, (int) ($invoice->lead_id ?? 0), 'invoice_sms_resend_failed', 'ارسال مجدد پیامک فاکتور ناموفق بود', ['actor_id' => $actor_id]); }
			catch (Throwable $error) { error_log('SN SMS activity log failed: ' . $error->getMessage()); }
			SN_Helpers::send_json(false, $this->sn_invoice_sms_last_error ?: 'ارسال پیامک ناموفق بود؛ تنظیمات سرویس پیامک را بررسی کنید');
			return;
		}
		try { $this->sn_log_activity($invoice_id, (int) ($invoice->lead_id ?? 0), 'invoice_sms_resent', 'پیامک لینک فاکتور مجدداً برای مشتری ارسال شد', ['actor_id' => $actor_id, 'destination' => $phone === SN_Helpers::normalize_mobile((string)$invoice->customer_phone) ? 'primary' : 'other']); }
		catch (Throwable $error) { error_log('SN SMS activity log failed: ' . $error->getMessage()); }
		SN_Helpers::send_json(true, 'پیامک فاکتور مجدداً ارسال شد', ['invoice_id' => $invoice_id]);
	}

	public function ajax_copy_invoice_payment_link(): void
	{
		if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
		global $wpdb;
		$id = absint($_POST['invoice_id'] ?? 0);
		$invoice = $id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $id)) : null;
		if (! $invoice || ! $this->sn_can_resend_invoice_sms($invoice)) { SN_Helpers::send_json(false, 'فاکتور در محدوده شما نیست'); return; }
		// Return only the short bearer URL; never expose access_token in staff panels.
		$url = $this->sn_invoice_short_public_url($invoice);
		if ($url === '') { SN_Helpers::send_json(false, 'لینک کوتاه این فاکتور ساخته نشد'); return; }
		$this->sn_log_activity($id, (int)($invoice->lead_id ?? 0), 'invoice_payment_link_copied', 'لینک پرداخت توسط کاربر مجاز دریافت شد');
		SN_Helpers::send_json(true, 'لینک آمادهٔ کپی است', ['url' => $url]);
	}

	/** The current owner of the invitation to pay, not a customer or a finance approver. */
	private function sn_invoice_last_payment_sender($invoice): int
	{
		global $wpdb;
		$actions = ['invoice_created','invoice_created_by_supervisor_for_seller','invoice_created_by_converter','invoice_sms_resent','seller_payment_submitted','supervisor_payment_submitted','converter_payment_submitted','seller_resend_to_financial','invoice_payment_stage_issued'];
		$placeholders = implode(',', array_fill(0, count($actions), '%s'));
		$actor = (int) $wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$wpdb->prefix}sn_activity_logs WHERE invoice_id=%d AND user_id>0 AND action IN ({$placeholders}) ORDER BY id DESC LIMIT 1", (int)$invoice->id, ...$actions));
		return $actor ?: (int)($invoice->current_stage_issued_by_user_id ?: $invoice->issued_by_user_id ?: $invoice->seller_id);
	}

	/** Rechecked under an invoice lock before every financial edit. */
	private function sn_invoice_pre_payment_edit_block($invoice, $stage): string
	{
		global $wpdb;
		$id = (int) $invoice->id;
		if ($this->sn_invoice_is_conversion_payment($id)) { return 'فاکتورهای پرداخت تبدیل از داخل پروندهٔ تبدیل مدیریت می‌شوند.'; }
		$link_table = $wpdb->prefix . 'sn_dot_invoice_links';
		if ($this->sn_table_exists_quiet($link_table) && $wpdb->get_var($wpdb->prepare("SELECT id FROM {$link_table} WHERE invoice_id=%d LIMIT 1", $id))) { return 'فاکتور متصل به فرایند اعتبارسنجی از این مسیر قابل ویرایش نیست.'; }
		if (in_array((string)$invoice->status, ['paid','approved','partial_paid','payment_archived','cancelled'], true)
			|| (float)($invoice->paid_total_amount ?? 0)>0.5 || !empty($invoice->paid_at) || !empty($invoice->approved_at)
			|| !empty($invoice->wc_order_id) || !empty($invoice->receipt_url) || !empty($invoice->receipt_file)
			|| (float)($invoice->manual_amount ?? 0)>0.5) { return 'پس از ثبت پرداخت، فیش یا تحویل محصول، ویرایش مالی عادی مجاز نیست.'; }
		if (SN_Sales_Catalog::invoice_snapshot($invoice) || (float)($invoice->discount_total ?? 0)>0.5 || (float)($invoice->discount_amount ?? 0)>0.5 || !empty($invoice->wheel_reward_summary) || !empty($invoice->coupon_code) || (float)($invoice->coupon_discount_amount ?? 0)>0.5) { return 'برای فاکتور دارای تخفیف یا کوپن، ویرایش مبلغ باید با محاسبهٔ مجدد تخفیف انجام شود.'; }
		if (!empty($invoice->manual_paid_at) || (float)($invoice->deposit_amount ?? 0)>0.5 || !empty($invoice->deposit_jalali_datetime) || !empty($invoice->financial_reviewed_at)
			|| in_array((string)($invoice->payment_workflow_status ?? ''), ['pending_financial_approval','approved','completed'], true)) { return 'اطلاعات پرداخت یا بررسی مالی برای این پیش‌فاکتور ثبت شده است.'; }
		if (!$stage || (int)$stage->stage_no!==1 || (string)$stage->status!=='pending' || !empty($stage->paid_at) || !empty($stage->approved_at)
			|| (int)($invoice->current_payment_stage ?? 1)!==1) { return 'مرحلهٔ اول پرداخت دیگر قابل ویرایش نیست.'; }
		$payments = $wpdb->prefix . 'sn_payments';
		if ($this->sn_table_exists_quiet($payments) && $wpdb->get_var($wpdb->prepare("SELECT id FROM {$payments} WHERE invoice_id=%d AND status NOT IN ('failed','cancelled','rejected') LIMIT 1", $id))) { return 'درخواست پرداخت یا بررسی مالی برای این فاکتور ثبت شده است.'; }
		$memberships = $wpdb->prefix . 'sn_project_memberships';
		if ($this->sn_table_exists_quiet($memberships) && $wpdb->get_var($wpdb->prepare("SELECT id FROM {$memberships} WHERE source_invoice_id=%d LIMIT 1", $id))) { return 'محصول این فاکتور وارد فرایند تحویل شده است.'; }
		return '';
	}

	public function ajax_invoice_pre_payment_edit(): void
	{
		if (!is_user_logged_in() || !check_ajax_referer('sn_public','nonce',false)) { SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
		global $wpdb;
		$id=absint($_POST['invoice_id']??0); $actor=get_current_user_id();
		$invoice_table=$wpdb->prefix.'sn_invoices'; $stage_table=$wpdb->prefix.'sn_invoice_payment_stages'; $item_table=$wpdb->prefix.'sn_invoice_items';
		$mode=sanitize_key(wp_unslash($_POST['edit_mode']??'read'));
		if ($mode==='save') { $wpdb->query('START TRANSACTION'); }
		$invoice=$id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d".($mode==='save'?' FOR UPDATE':''),$id)) : null;
		if (!$invoice) { if($mode==='save')$wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'فاکتور یافت نشد'); return; }
		$is_seller=(int)$invoice->seller_id===$actor && !$this->sn_invoice_is_conversion_payment($id);
		$is_sender=$this->sn_invoice_last_payment_sender($invoice)===$actor && $this->sn_can_resend_invoice_sms($invoice);
		if (!$is_seller && !$is_sender) { if($mode==='save')$wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'ویرایش فقط برای فروشندهٔ مالک یا آخرین فرستندهٔ لینک/پروندهٔ مالی مجاز است'); return; }
		$stage=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d ORDER BY stage_no ASC LIMIT 1".($mode==='save'?' FOR UPDATE':''),$id));
		$blocked=$this->sn_invoice_pre_payment_edit_block($invoice,$stage);
		if ($blocked!=='') { if($mode==='save')$wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,$blocked); return; }
		$items=$wpdb->get_results($wpdb->prepare("SELECT id,product_id,qty FROM {$item_table} WHERE invoice_id=%d ORDER BY id ASC".($mode==='save'?' FOR UPDATE':''),$id),ARRAY_A)?:[];
		if (!$items) { if($mode==='save')$wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'اقلام فاکتور موجود نیست'); return; }
		if ($mode!=='save') {
			SN_Helpers::send_json(true,'اطلاعات قابل ویرایش',['invoice_id'=>$id,'payment_plan'=>(string)$invoice->payment_plan,'current_due_amount'=>(float)$invoice->current_due_amount,'customer_phone_secondary'=>(string)($invoice->customer_phone_secondary??''),'items'=>$items,'can_edit_products'=>$is_seller]);return;
		}
		$plan=sanitize_key(wp_unslash($_POST['payment_plan']??''));
		if (!in_array($plan,['full','partial'],true)) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'نوع پرداخت نامعتبر است'); return; }
		// Changing a full invoice to stages belongs exclusively to the last staff sender.
		if ((string)$invoice->payment_plan==='full' && $plan==='partial' && !$is_sender) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'فقط آخرین فرستندهٔ پرداخت/تأیید مالی می‌تواند پرداخت کامل را مرحله‌ای کند'); return; }
		$phone_secondary_raw=is_scalar($_POST['customer_phone_secondary']??'')?(string)$_POST['customer_phone_secondary']:'';
		$phone_secondary=SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($phone_secondary_raw)));
		if ($phone_secondary!=='' && !SN_Helpers::is_valid_mobile($phone_secondary)) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'شماره دوم معتبر نیست'); return; }
		$product_ids=array_values(array_map('absint',is_array($_POST['product_ids']??null)?$_POST['product_ids']:[]));
		$quantities=array_values(array_map('absint',is_array($_POST['product_qtys']??null)?$_POST['product_qtys']:[]));
		if (!$is_seller) { $product_ids=array_map('intval',array_column($items,'product_id'));$quantities=array_map('intval',array_column($items,'qty')); }
		if (count($product_ids)!==count($items) || count($quantities)!==count($items)) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'تعداد اقلام فاکتور تغییر کرده است'); return; }
		if ($is_seller && class_exists('SN_Projects')) { $valid=SN_Projects::instance()->validate_invoice_products($product_ids,$actor); if(is_wp_error($valid)){ $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,$valid->get_error_message());return; } }
		if (class_exists('SN_Seller_Flow')) { $valid=SN_Seller_Flow::instance()->validate_invoice_product_types($product_ids,$quantities); if(is_wp_error($valid)){ $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,$valid->get_error_message());return; } }
		$catalog_valid=SN_Sales_Catalog::instance()->validate_products($product_ids,$actor,(int)$invoice->seller_id);
		if(is_wp_error($catalog_valid)){ $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,$catalog_valid->get_error_message());return; }
		$total=0.0;$updated=[];
		foreach($items as $index=>$item){
			$pid=$product_ids[$index];$qty=$quantities[$index];$product=$pid>0 && function_exists('wc_get_product')?wc_get_product($pid):null;
			if(!$product || get_post_status($pid)!=='publish' || (string)get_post_meta($pid,'_sn_enabled',true)!=='1' || $qty<1){$wpdb->query('ROLLBACK');SN_Helpers::send_json(false,'محصول یا تعداد مجاز نیست');return;}
			if ($plan==='partial' && class_exists('SN_Dot_Flow') && SN_Dot_Flow::instance()->is_assessment_product($pid)) { $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,'اعتبارسنجی باید پرداخت کامل باشد');return; }
			$price=(float)$product->get_price();$line=$price*$qty;$total+=$line;
			$type=class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance()->product_type($pid) : '';
			if ($type==='product' && (trim((string)($invoice->province??''))==='' || trim((string)($invoice->city??''))==='' || trim((string)($invoice->customer_address??''))==='')) { $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,'برای محصول عادی، استان، شهر و آدرس کامل مشتری لازم است');return; }
			$updated[]=['id'=>(int)$item['id'],'product_id'=>$pid,'product_name'=>$product->get_name(),'product_type'=>$type?:null,'qty'=>$qty,'unit_price'=>$price,'total_price'=>$line];
		}
		$due=$plan==='partial'?$this->sn_parse_money_value(is_scalar($_POST['prepayment_amount']??0)?$_POST['prepayment_amount']:0):$total;
		if($total<=0.5 || $due<=0.5 || ($plan==='partial' && $due >= $total-0.5)){ $wpdb->query('ROLLBACK');SN_Helpers::send_json(false,'مبلغ مرحله باید بیشتر از صفر و کمتر از مبلغ کل باشد');return; }
		$invoice_update=$this->sn_filter_existing_columns($invoice_table,['product_id'=>$product_ids[0],'product_price'=>$total,'original_total'=>$total,'final_total'=>$total,'payment_plan'=>$plan,'payment_total_amount'=>$total,'current_due_amount'=>$due,'remaining_amount'=>$total,'customer_phone_secondary'=>$phone_secondary?:null,'updated_at'=>current_time('mysql')]);
		$ok=$wpdb->update($invoice_table,$invoice_update,['id'=>$id])!==false;
		foreach($updated as $item){$item_id=$item['id'];unset($item['id']);$ok=$ok && $wpdb->update($item_table,$item,['id'=>$item_id])!==false;}
		$ok=$ok && $wpdb->update($stage_table,['stage_type'=>$plan,'requested_amount'=>$due,'updated_at'=>current_time('mysql')],['id'=>(int)$stage->id])!==false;
		if(!$ok){$wpdb->query('ROLLBACK');SN_Helpers::send_json(false,'ذخیرهٔ ویرایش انجام نشد');return;}
		$wpdb->query('COMMIT');
		$this->sn_log_activity($id,(int)($invoice->lead_id??0),'invoice_pre_payment_edited','ویرایش پیش‌فاکتور پیش از نخستین پرداخت',['actor_id'=>$actor,'payment_plan'=>$plan,'total'=>$total,'current_due'=>$due,'product_ids'=>$product_ids]);
		SN_Helpers::send_json(true,'پیش‌فاکتور به‌روزرسانی شد',['invoice_id'=>$id,'total'=>$total,'due'=>$due]);
	}

	/**
	 * Issue another payment stage on an invoice owned by the current seller/converter.
	 * This is intentionally independent from Dot conversion-payment invoices: it is
	 * used for normal/manual invoices that already have one or more approved stages.
	 */
	private function sn_issue_owned_invoice_payment_stage(int $invoice_id, int $actor_id, string $mode, float $requested_amount = 0, string $note = ''): array
	{
		$this->maybe_create_tables();
		global $wpdb;
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
		$mode = in_array($mode, ['partial','remaining'], true) ? $mode : 'partial';
		if ($invoice_id < 1 || $actor_id < 1) { return ['success'=>false,'message'=>'فاکتور یا کاربر معتبر نیست']; }

		$wpdb->query('START TRANSACTION');
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $invoice_id));
		if (! $invoice) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
		if (! current_user_can('manage_options') && (int)($invoice->seller_id ?? 0) !== $actor_id) {
			$wpdb->query('ROLLBACK');
			return ['success'=>false,'message'=>'این فاکتور متعلق به حساب شما نیست'];
		}
		$totals = $this->sn_invoice_payment_totals($invoice);
		$remaining = (float)$totals['remaining'];
		if ($remaining <= 0.5 || $totals['workflow_status'] === 'completed') {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'این فاکتور قبلاً به طور کامل تسویه شده است'];
		}
		if ($totals['workflow_status'] !== 'awaiting_assignment' || (float)$totals['due'] > 0.5) {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مرحله جاری هنوز تعیین تکلیف نشده یا مرحله بعد قبلاً صادر شده است'];
		}

		$amount = $mode === 'remaining' ? $remaining : max(0, $requested_amount);
		if ($mode === 'partial' && ($amount <= 0.5 || $amount - $remaining > 0.5)) {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ مرحله جدید باید بیشتر از صفر و حداکثر برابر مانده فاکتور باشد'];
		}
		if ($amount <= 0.5 || $amount - $remaining > 0.5) {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ مرحله جدید با مانده فاکتور سازگار نیست'];
		}
		if ( abs($amount - $remaining) <= 0.5 ) { $mode = 'remaining'; $amount = $remaining; }

		$next_stage = max(1, (int)$totals['stage_no']) + 1;
		$stage_type = $mode === 'remaining' ? 'remaining' : 'partial';
		if (! $this->sn_create_invoice_payment_stage($invoice_id, $next_stage, $stage_type, $amount, $actor_id, $note ?: ($mode === 'remaining' ? 'تسویه کامل مانده' : 'پرداخت مرحله‌ای جدید'))) {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>$wpdb->last_error ?: 'مرحله پرداخت جدید ایجاد نشد'];
		}

		$reset = [
			'current_due_amount'=>$amount,
			'current_payment_stage'=>$next_stage,
			'payment_workflow_status'=>'awaiting_payment',
			'current_stage_issued_by_user_id'=>$actor_id,
			'status'=>'pre_invoice',
			'invoice_status'=>'pre_invoice',
			'payment_status'=>'pending_payment',
			'receipt_url'=>null, 'receipt_urls'=>null, 'receipt_file'=>null, 'receipt_source'=>null,
			'manual_transfer_type'=>null,'manual_account_last6'=>null,'manual_tracking_last6'=>null,'manual_account_owner'=>null,'manual_card_from'=>null, 'manual_card_to'=>null, 'manual_card_to_number'=>null, 'manual_amount'=>null,
			'manual_paid_at'=>null, 'manual_paid_at_jalali'=>null,
			'rejected_by'=>null, 'rejected_at'=>null, 'rejected_reason'=>null,
			'updated_at'=>current_time('mysql'),
		];
		$invoice_updated = $wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, $reset), ['id'=>$invoice_id]);
		if ($invoice_updated === false) {
			$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>$wpdb->last_error ?: 'وضعیت مرحله جدید روی فاکتور ذخیره نشد'];
		}

		// Keep the shared staged-payment action item in sync so another panel cannot
		// issue a duplicate stage while this one is open.
		if ($this->sn_distribution_tables_ready()) {
			$action_table = $wpdb->prefix . 'sn_distribution_items';
			$action_item = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$action_table} WHERE source_type='paid_invoice_referral' AND source_id=%d AND workflow_kind='invoice_payment_completion' ORDER BY id DESC LIMIT 1 FOR UPDATE", $invoice_id));
			if ($action_item) {
				$position = $this->sn_hr_position_for_user($actor_id);
				if ($position === '') { $position = 'converter'; }
				$action_ok = $wpdb->update($action_table, $this->sn_distribution_filter_existing_columns_fresh($action_table, [
					'current_owner_user_id'=>$actor_id,
					'current_owner_position'=>$position,
					'status'=>'payment_stage_issued',
					'referral_issued_by_user_id'=>$actor_id,
					'updated_at'=>current_time('mysql'),
				]), ['id'=>(int)$action_item->id]);
				if ($action_ok === false) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'وضعیت اقدام مرحله‌ای همگام نشد']; }
			}
		}

		$wpdb->query('COMMIT');
		$sms_sent = $this->sn_send_invoice_stage_sms($invoice_id);
		$this->sn_log_activity($invoice_id, (int)($invoice->lead_id ?? 0), 'invoice_payment_stage_issued', 'مرحله جدید پرداخت روی همان فاکتور صادر شد', [
			'stage_no'=>$next_stage, 'amount'=>$amount, 'stage_type'=>$stage_type, 'issued_by_user_id'=>$actor_id, 'sms_sent'=>$sms_sent,
		]);
		return [
			'success'=>true, 'message'=>$sms_sent ? 'مرحله جدید صادر و لینک پرداخت برای مشتری پیامک شد.' : 'مرحله جدید صادر شد؛ ارسال پیامک ناموفق بود.',
			'invoice_id'=>$invoice_id, 'stage_no'=>$next_stage, 'amount'=>$amount, 'remaining_before'=>$remaining, 'sms_sent'=>$sms_sent,
		];
	}

	public function ajax_converter_issue_payment_stage(): void
	{
		if (! check_ajax_referer('sn_public', 'nonce', false)) { wp_send_json(['success'=>false,'message'=>'درخواست امنیتی نامعتبر است'], 403); }
		if (! is_user_logged_in()) { wp_send_json(['success'=>false,'message'=>'ابتدا وارد حساب کاربری شوید'], 401); }
		$user = wp_get_current_user();
		$user_id = (int)$user->ID;
		$position = $this->sn_hr_position_for_user($user_id);
		$is_converter = in_array('sn_converter', (array)$user->roles, true) || $position === 'converter';
		if (! current_user_can('manage_options') && ! $is_converter) { wp_send_json(['success'=>false,'message'=>'این عملیات فقط برای تبدیل‌کننده مجاز است'], 403); }
		$invoice_id = absint($_POST['invoice_id'] ?? 0);
		$mode = sanitize_key((string)wp_unslash($_POST['stage_mode'] ?? 'partial'));
		$amount = $mode === 'remaining' ? 0 : $this->sn_parse_money_value($_POST['amount'] ?? 0);
		$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
		$result = $this->sn_issue_owned_invoice_payment_stage($invoice_id, $user_id, $mode, $amount, $note);
		$status = ! empty($result['success']) ? 200 : 400;
		wp_send_json($result, $status);
	}

	public function ajax_pay_online(): void
	{
		if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
		$this->maybe_create_tables();
		$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
		$access = $this->sn_invoice_access_for_payment_action($code, 'pay_online');
		if (empty($access['internal']) && empty($access['internal_denied']) && ! $this->sn_rate_limit_public_or_json('invoice_pay_online', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
		if (empty($access['success']) && empty($access['internal']) && empty($access['internal_denied'])) { $access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'pay_online'); }
		if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
		$invoice = $access['invoice'];
		if (! $invoice) { SN_Helpers::send_json(false, 'فاکتور یافت نشد'); return; }
		$online_totals = $this->sn_invoice_payment_totals($invoice);
        $online_pending = SN_Payment_Transactions::summary(SN_Payment_Transactions::pending_rows((int)$invoice->id,(int)$online_totals['stage_no']),(int)$online_totals['stage_no'],(float)$online_totals['due']);
        if ($online_pending['pending_amount'] > 0) { SN_Helpers::send_json(false,'تراکنش واریزی در انتظار بررسی دارید؛ ابتدا نتیجه بررسی مالی مشخص شود'); return; }
        $payment_gate = $this->sn_invoice_customer_payment_gate($invoice, 'online');
		if (empty($payment_gate['allowed'])) { SN_Helpers::send_json(false, (string) $payment_gate['message']); return; }
		$totals = (array) $payment_gate['totals'];
		$amount = (float) $totals['due'];
		$active_stage = $this->sn_current_invoice_payment_stage((int)$invoice->id, (int)$totals['stage_no']);
		// Repair stale v2.0.142 payment-stage amounts at the last possible point
		// before creating a gateway request. The invoice net total/due is
		// authoritative for catalog-discount invoices.
		$catalog_snapshot = trim((string)($invoice->catalog_discounts_snapshot ?? ''));
		$catalog_discount = max(0, (float)(($invoice->discount_total ?? 0) ?: ($invoice->discount_amount ?? 0)));
		if ($active_stage && $catalog_snapshot !== '' && $catalog_discount > 0
			&& ! in_array((string)($active_stage->status ?? ''), ['paid','approved'], true)
			&& abs((float)($active_stage->requested_amount ?? 0) - $amount) > 0.5) {
			$stage_type = $amount >= (float)$totals['remaining'] - 0.5 ? 'full' : (string)($active_stage->stage_type ?? 'partial');
			$stage_updated = $wpdb->update($wpdb->prefix.'sn_invoice_payment_stages', [
				'requested_amount'=>$amount,
				'stage_type'=>$stage_type,
				'updated_at'=>current_time('mysql'),
			], ['id'=>(int)$active_stage->id]);
			if ($stage_updated === false) { SN_Helpers::send_json(false, 'همگام‌سازی مبلغ مرحله پرداخت انجام نشد'); return; }
			$active_stage = $this->sn_current_invoice_payment_stage((int)$invoice->id, (int)$totals['stage_no']);
		}
		if (! $active_stage) {
			if (! $this->sn_create_invoice_payment_stage((int)$invoice->id, (int)$totals['stage_no'], (int)$totals['stage_no'] === 1 ? (string)$totals['plan'] : 'partial', $amount, (int)($invoice->current_stage_issued_by_user_id ?? $invoice->seller_id ?? 0), 'ساخت مرحله سازگاری برای فاکتور قدیمی')) {
				SN_Helpers::send_json(false, 'مرحله پرداخت فاکتور قابل ایجاد نیست'); return;
			}
		}
		$gw = new SN_Invoice();
		$page_id = (int) get_option('sn_invoice_page_id');
		$gateway = $gw->active_gateway();
		$callback_url = add_query_arg(['sn_callback'=>'1','sn_gateway'=>$gateway,'invoice_id'=>$invoice->id,'sn_stage'=>(int)$totals['stage_no'],'orderId'=>$invoice->invoice_code], $page_id ? get_permalink($page_id) : home_url());
		$result = $gw->request_payment((int)$invoice->id, $amount, 'پرداخت مرحله '.(int)$totals['stage_no'].' فاکتور '.$invoice->invoice_code, (string)$invoice->customer_phone, $callback_url, (string)$invoice->invoice_code, (int)$totals['stage_no']);
		if (isset($result['error'])) { SN_Helpers::send_json(false, $result['error']); return; }
		SN_Helpers::send_json(true, '', ['redirect'=>$result['url'],'amount'=>$amount,'stage_no'=>(int)$totals['stage_no']]);
	}

    public function ajax_invoice_transactions(): void
    {
        if (!check_ajax_referer('sn_public','nonce',false)) { SN_Helpers::send_json(false,'نانس نامعتبر'); return; }
        $code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
        if ($code === '' && is_user_logged_in()) {
            global $wpdb;
            $candidate = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", absint($_POST['invoice_id'] ?? 0)));
            if (!$candidate || !$this->sn_can_perform_internal_invoice_payment_action($candidate,'manual_payment')) { SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
            $code = (string)$candidate->invoice_code;
        }
        $access = $this->sn_invoice_access_for_payment_action($code,'manual_payment');
        if (empty($access['success']) && empty($access['internal_denied'])) { $access = $this->sn_validate_public_invoice_access($code,$this->sn_public_access_token(),'view'); }
        if (empty($access['success']) || empty($access['invoice'])) { SN_Helpers::send_json(false,'دسترسی به تراکنش‌های این فاکتور مجاز نیست'); return; }
        $invoice = $access['invoice']; $totals = $this->sn_invoice_payment_totals($invoice);
        $rows = SN_Payment_Transactions::rows($invoice);
        SN_Helpers::send_json(true,'',['transactions'=>$rows,'transaction_summary'=>SN_Payment_Transactions::summary($rows,(int)$totals['stage_no'],(float)$totals['due'])]);
    }

	public function ajax_upload_receipt(): void
	{
		if (! check_ajax_referer('sn_public', 'nonce', false)) {
			SN_Helpers::send_json(false, 'نانس نامعتبر');
			return;
		}
		if (! $this->sn_card_to_card_enabled()) { SN_Helpers::send_json(false, 'پرداخت کارت‌به‌کارت غیرفعال است'); return; }
		$code    = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
		$access = $this->sn_invoice_access_for_payment_action($code, 'upload_receipt');
		if (empty($access['internal']) && empty($access['internal_denied']) && ! $this->sn_rate_limit_public_or_json('invoice_upload_receipt', $code, 5, 15 * MINUTE_IN_SECONDS)) { return; }
		if (empty($access['success']) && empty($access['internal']) && empty($access['internal_denied'])) {
			$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'upload_receipt');
		}
		if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
		$invoice = $access['invoice'];
		if (! $invoice) { SN_Helpers::send_json(false, 'فاکتور یافت نشد'); return; }
		$payment_gate = $this->sn_invoice_customer_payment_gate($invoice, 'upload');
		if (empty($payment_gate['allowed'])) { SN_Helpers::send_json(false, (string) $payment_gate['message']); return; }
		$invoice_card = $this->sn_resolve_invoice_card($invoice);
		$invoice_card_digits = preg_replace('/\D+/', '', SN_Helpers::to_english_nums((string)($invoice_card['number'] ?? '')));
		if (empty($access['internal']) && strlen((string)$invoice_card_digits) !== 16) { SN_Helpers::send_json(false, 'شماره کارت مقصد معتبر برای این فاکتور ثبت نشده است'); return; }

		if (empty($_FILES['receipt'])) {
			SN_Helpers::send_json(false, 'فایل آپلود نشد');
			return;
		}

		$upload = SN_Helpers::upload_receipt($_FILES['receipt']); // phpcs:ignore
		if (empty($upload['success']) || empty($upload['url'])) {
			SN_Helpers::send_json(false, (string) ($upload['message'] ?? 'خطا در آپلود فایل'));
			return;
		}
		$url = (string) $upload['url'];

		$source = !empty($access['internal']) ? $this->sn_internal_payment_source_for_current_user() : 'customer_upload';
        $save = $this->sn_save_invoice_manual_payment((int) $invoice->id, $source, ['receipt_url' => $url, 'receipt_urls' => $upload['urls']]);
		if (empty($save['success'])) {
			SN_Helpers::send_json(false, (string)($save['message'] ?? 'ذخیره فیش در دیتابیس انجام نشد'));
			return;
		}
		SN_Helpers::send_json(true, 'فیش با موفقیت ثبت شد و در وضعیت نیاز به بررسی فیش قرار گرفت', [
			'invoice_id' => (int) $invoice->id,
			'status' => 'pending_financial_approval',
			'status_label' => 'نیاز به بررسی فیش',
			'receipt_url' => $url, 'payment_id'=>(int)($save['payment_id'] ?? 0), 'available_amount'=>(float)($save['available_amount'] ?? 0),
		]);
	}


