	// =========================================================
	// ZARINPAL CALLBACK
	// =========================================================

	public function handle_zarinpal_callback(): void
	{
		if (empty($_GET['sn_callback']) || empty($_GET['invoice_id'])) { return; }
		$this->maybe_create_tables();
			$invoice_id = absint($_GET['invoice_id']);
			$gateway = sanitize_key(wp_unslash($_GET['sn_gateway'] ?? ''));
			if ($gateway === '') { $gateway = ! empty($_GET['trackId']) ? 'zibal' : 'zarinpal'; }
			$gateway_is_valid = in_array($gateway, ['zarinpal','zibal','asanpardakht'], true);
			global $wpdb;
		$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
		if (! $invoice) { wp_die('فاکتور یافت نشد'); }
		$invoice_page = get_permalink((int)get_option('sn_invoice_page_id')) ?: home_url();
		$marketing_return_url = '';
		if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(), 'marketing_gateway_return_url')) {
			$marketing_return_url = (string) SN_Dot_Flow::instance()->marketing_gateway_return_url($invoice_id);
		}
			$is_dot_marketing_callback = $marketing_return_url !== '';
			if ($is_dot_marketing_callback) { $invoice_page = $marketing_return_url; }
			$is_operations_upgrade = ! $is_dot_marketing_callback && class_exists('SN_Operations_Flow') && SN_Operations_Flow::instance()->is_upgrade_invoice($invoice_id);
			if ($is_operations_upgrade) {
				$operations_return_url = SN_Operations_Flow::instance()->customer_return_url($invoice_id);
				if ($operations_return_url !== '') { $invoice_page = $operations_return_url; }
			}
			$base_redirect = ($is_dot_marketing_callback || $is_operations_upgrade) ? [] : ['invoice'=>$invoice->invoice_code,'access_token'=>(string)($invoice->access_token ?? '')];
			$mark_marketing_gateway_result = static function(string $result, string $reason = '') use ($is_dot_marketing_callback, $invoice_id): void {
				if ($is_dot_marketing_callback && class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(), 'mark_marketing_gateway_result')) {
					SN_Dot_Flow::instance()->mark_marketing_gateway_result($invoice_id, $result, $reason);
				}
			};
			$fail_and_redirect = static function(string $reason, string $gateway_name = '', bool $cancelled = false) use ($mark_marketing_gateway_result, $base_redirect, $invoice_page): void {
				$mark_marketing_gateway_result($cancelled ? 'gateway_cancelled' : 'gateway_failed', $reason);
				$args = array_merge($base_redirect, ['pay_result'=>'failed']);
				if ($reason !== '') { $args['reason'] = $reason; }
				if ($gateway_name !== '') { $args['gateway'] = $gateway_name; }
				wp_safe_redirect(add_query_arg($args, $invoice_page));
				exit;
			};
			if (class_exists('SN_Dot_Flow') && SN_Dot_Flow::instance()->is_gifted_assessment_invoice($invoice_id)) {
				$fail_and_redirect('validation_gifted', $gateway, true);
			}
			if (! $gateway_is_valid) { $fail_and_redirect('invalid_gateway', $gateway); }
			$totals = $this->sn_invoice_payment_totals($invoice);
		$callback_stage_no = max(1, absint($_GET['sn_stage'] ?? $totals['stage_no']));
		$known_authority = '';
		if ($gateway === 'zibal' && ! empty($_GET['trackId'])) { $known_authority = 'zibal:' . sanitize_text_field(wp_unslash($_GET['trackId'])); }
		elseif ($gateway === 'zarinpal' && ! empty($_GET['Authority'])) { $known_authority = sanitize_text_field(wp_unslash($_GET['Authority'])); }
		$payment_request = $known_authority !== '' ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_payments WHERE authority=%s ORDER BY id DESC LIMIT 1", $known_authority)) : null;
		if ($known_authority !== '' && ! $payment_request) {
			$fail_and_redirect('payment_request_not_found', $gateway);
		}
			if ($payment_request) {
				if ((int)$payment_request->invoice_id !== $invoice_id) { $fail_and_redirect('payment_invoice_mismatch', $gateway); }
				$stored_gateway = sanitize_key((string)($payment_request->payment_source ?? ''));
				if ($stored_gateway !== '' && $stored_gateway !== $gateway) { $fail_and_redirect('payment_gateway_mismatch', $gateway); }
				if (! empty($payment_request->payment_stage_no)) { $callback_stage_no = max(1, (int)$payment_request->payment_stage_no); }
			}
		$stage = $this->sn_current_invoice_payment_stage($invoice_id, $callback_stage_no);
		if (! $stage && $callback_stage_no === (int)$totals['stage_no'] && $totals['due'] > 0) {
			$this->sn_create_invoice_payment_stage($invoice_id, $callback_stage_no, $callback_stage_no === 1 ? (string)$totals['plan'] : 'partial', (float)$totals['due'], (int)($invoice->current_stage_issued_by_user_id ?? $invoice->seller_id ?? 0), 'ساخت مرحله سازگاری هنگام بازگشت درگاه');
			$stage = $this->sn_current_invoice_payment_stage($invoice_id, $callback_stage_no);
		}
		if (! $stage) { $fail_and_redirect('stage_not_found', $gateway); }
		$expected_amount = (float) ($stage->requested_amount ?? 0);
		if ($payment_request && abs((float)$payment_request->amount - $expected_amount) > 0.5) { $fail_and_redirect('payment_amount_mismatch', $gateway); }
		if ($expected_amount <= 0 && $totals['workflow_status'] === 'completed') { wp_safe_redirect(add_query_arg(array_merge($base_redirect,['pay_result'=>'success']),$invoice_page)); exit; }
		if ($expected_amount <= 0) { $fail_and_redirect('no_active_stage', $gateway); }
		$gw = new SN_Invoice();
		$finalize_and_redirect = function(string $source, string $ref_id = '', string $authority = '') use ($invoice_id, $callback_stage_no, $invoice_page, $base_redirect, $wpdb, $fail_and_redirect) {
			// A verified gateway callback is authoritative: all gateway payments are
			// financially approved automatically. Manual receipts remain reviewable.
			$result = $this->sn_finalize_current_payment_stage($invoice_id, 'online', $source, $ref_id, 0, 'approved', $callback_stage_no);
			if (empty($result['success'])) {
				if ($authority !== '') { $wpdb->update($wpdb->prefix.'sn_payments', $this->sn_filter_existing_columns($wpdb->prefix.'sn_payments', ['status'=>'reconcile_error','updated_at'=>current_time('mysql')]), ['authority'=>$authority]); }
				$fail_and_redirect('stage_finalize', $source);
			}
			if ($authority !== '') {
				$wpdb->update($wpdb->prefix.'sn_payments', $this->sn_filter_existing_columns($wpdb->prefix.'sn_payments', ['status'=>'approved','ref_id'=>$ref_id,'pay_method'=>'online','payment_source'=>$source,'updated_at'=>current_time('mysql')]), ['authority'=>$authority]);
			}
			if (! is_user_logged_in() && (! class_exists('SN_Dot_Flow') || ! SN_Dot_Flow::instance()->is_dot_invoice_id($invoice_id))) {
				$customer_id = (int)$wpdb->get_var($wpdb->prepare("SELECT customer_wp_id FROM {$wpdb->prefix}sn_invoices WHERE id=%d",$invoice_id));
				if ($customer_id) { wp_set_auth_cookie($customer_id, false); }
			}
			wp_safe_redirect(add_query_arg(array_merge($base_redirect,['pay_result'=>!empty($result['completed'])?'success':'partial_success','ref_id'=>$ref_id,'gateway'=>$source]),$invoice_page)); exit;
		};
		if ($gateway === 'asanpardakht') {
			$returning_params = isset($_POST['ReturningParams']) ? trim((string)wp_unslash($_POST['ReturningParams'])) : '';
			if ($returning_params === '') { $fail_and_redirect('asanpardakht_cancelled', 'asanpardakht', true); }
			$verified = $gw->asanpardakht_verify($invoice_id, $expected_amount, $returning_params);
			if (! empty($verified['success'])) {
				$ref_id=(string)($verified['ref_id'] ?? ''); $authority=(string)($verified['authority'] ?? '');
					if ($authority === '') { $fail_and_redirect('payment_request_not_found', 'asanpardakht'); }
					$asan_request=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_payments WHERE authority=%s ORDER BY id DESC LIMIT 1",$authority));
					if (! $asan_request || (int)$asan_request->invoice_id!==$invoice_id || sanitize_key((string)($asan_request->payment_source ?? ''))!=='asanpardakht' || (!empty($asan_request->payment_stage_no) && (int)$asan_request->payment_stage_no!==$callback_stage_no) || abs((float)$asan_request->amount-$expected_amount)>0.5) { $fail_and_redirect('payment_stage_mismatch', 'asanpardakht'); }
				$finalize_and_redirect('asanpardakht',$ref_id,$authority);
			}
			error_log('SN AsanPardakht callback failed: '.wp_json_encode($verified,JSON_UNESCAPED_UNICODE));
			$fail_and_redirect('asanpardakht_verify_failed', 'asanpardakht');
		}
		if ($gateway === 'zibal') {
			$track_id=sanitize_text_field(wp_unslash($_GET['trackId'] ?? '')); $success=sanitize_text_field(wp_unslash($_GET['success'] ?? '0'));
			if ($track_id==='' || $success!=='1') { if ($known_authority !== '') { $wpdb->update($wpdb->prefix.'sn_payments', $this->sn_filter_existing_columns($wpdb->prefix.'sn_payments', ['status'=>'cancelled','updated_at'=>current_time('mysql')]), ['authority'=>$known_authority]); } $fail_and_redirect('zibal_cancelled', 'zibal', true); }
			$verified=$gw->zibal_verify($track_id,$expected_amount);
			if (! empty($verified['success'])) { $ref_id=(string)($verified['ref_id'] ?? $track_id); $finalize_and_redirect('zibal',$ref_id,'zibal:'.$track_id); }
			$fail_and_redirect('zibal_verify_failed', 'zibal');
		}
		if (empty($_GET['Authority']) || empty($_GET['Status'])) {
			if ($is_dot_marketing_callback) { $fail_and_redirect('zarinpal_callback_missing', 'zarinpal', true); }
			return;
		}
		$authority=sanitize_text_field(wp_unslash($_GET['Authority'])); $status=sanitize_text_field(wp_unslash($_GET['Status']));
		if ($status!=='OK') { $wpdb->update($wpdb->prefix.'sn_payments', $this->sn_filter_existing_columns($wpdb->prefix.'sn_payments', ['status'=>'cancelled','updated_at'=>current_time('mysql')]), ['authority'=>$authority]); $fail_and_redirect('zarinpal_cancelled', 'zarinpal', true); }
		$verified=$gw->zarinpal_verify($authority,$expected_amount);
		if (! empty($verified['success'])) { $ref_id=(string)($verified['ref_id'] ?? ''); $finalize_and_redirect('zarinpal',$ref_id,$authority); }
		$fail_and_redirect('zarinpal_verify_failed', 'zarinpal');
	}

