		(function(){
			var wrap=document.currentScript&&document.currentScript.previousElementSibling;
			var btn=wrap?wrap.querySelector('.sn-password-toggle'):document.querySelector('.sn-unified-login .sn-password-toggle');
			if(!btn){return;}
			btn.addEventListener('click',function(){
				var id=this.getAttribute('aria-controls');
				var input=id?document.getElementById(id):null;
				if(!input){return;}
				var show=input.type==='password';
				input.type=show?'text':'password';
				this.setAttribute('aria-pressed',show?'true':'false');
				this.setAttribute('aria-label',show?'مخفی کردن رمز عبور':'نمایش رمز عبور');
				this.title=show?'مخفی کردن رمز عبور':'نمایش رمز عبور';
				this.textContent=show?'🙈':'👁';
			});
		})();
