	public function render_my_panel(): string
	{
		if (! is_user_logged_in()) {
			return $this->render_unified_panel_login();
		}
		if (current_user_can('sn_view_campaign_reports') && ! current_user_can('manage_options') && class_exists('SN_Campaign_Tracking')) {
			return SN_Campaign_Tracking::instance()->render_partner_portal();
		}
		if (! class_exists('SN_HR_Service')) {
			return '<div class="sn-panel" dir="rtl"><div class="sn-notice sn-error">سرویس منابع انسانی در دسترس نیست.</div></div>';
		}
		$resolved = (new SN_HR_Service())->resolve_panel_for_user(get_current_user_id());
		if (current_user_can('manage_options') && in_array((string) ($resolved['panel_key'] ?? ''), ['unknown_panel', 'admin_dashboard'], true)) {
			return $this->render_admin_front_dashboard();
		}
		$shortcode = sanitize_key((string) ($resolved['shortcode'] ?? ''));
		$route_type = (string) ($resolved['route_type'] ?? 'placeholder');
		if ($shortcode && $shortcode !== 'sn_my_panel' && $route_type !== 'placeholder' && shortcode_exists($shortcode)) {
			$this->sn_enqueue_public_panel_assets($shortcode);
			return $this->sn_render_my_panel_entry_card($resolved, $shortcode) . $this->sn_dashboard_reporting_content();
		}
		return $this->sn_render_my_panel_entry_card($resolved, '') . $this->sn_dashboard_reporting_content();
	}

	public function render_admin_front_dashboard(): string
	{
		if (! is_user_logged_in() || ! current_user_can('manage_options')) {
			return $this->render_unified_panel_login();
		}
		wp_enqueue_style('sn-admin', SN_PLUGIN_URL . 'assets/css/admin.css', [], SN_VERSION);
		wp_enqueue_style('sn-public', SN_PLUGIN_URL . 'assets/css/public.css', [], SN_VERSION);
		ob_start();
		?>
		<div class="sn-panel sn-no-sidebar sn-portal sn-my-panel-entry sn-admin-front-dashboard" dir="rtl">
			<div class="sn-portal-entry-card">
				<div>
					<h2>داشبورد مدیریت شبکه فروش</h2>
					<p class="sn-muted">سلام <?php echo esc_html($this->sn_user_label(get_current_user_id())); ?>، شما به عنوان مدیر سیستم شناسایی شدید.</p>
					<div class="sn-portal-entry-detected"><span>پنل شناسایی‌شده</span><strong>داشبورد مدیریت شبکه فروش</strong></div>
				</div>
				<div class="sn-portal-entry-actions">
					<a class="sn-btn sn-btn-primary" href="<?php echo esc_url(admin_url('admin.php?page=sn-dashboard')); ?>">ورود به مدیریت کامل CRM</a>
					<?php if (get_option('sn_my_password_page_id')) : ?><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url(get_permalink((int) get_option('sn_my_password_page_id'))); ?>">رمز من</a><?php endif; ?>
					<div class="sn-portal-entry-links">
						<a href="<?php echo esc_url(admin_url('admin.php?page=sn-sellers')); ?>">فروشندگان</a>
						<a href="<?php echo esc_url(admin_url('admin.php?page=sn-settings')); ?>">تنظیمات</a>
					</div>
				</div>
			</div>
			<?php echo $this->sn_dashboard_reporting_content(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Escaped in reporting renderer. ?>
		</div>
		<?php
		return ob_get_clean();
	}

	private function sn_render_my_panel_entry_card(array $resolved, string $shortcode): string
	{
		$user = wp_get_current_user();
		$panel_label = (string) ($resolved['panel_label'] ?? 'پنل من');
		$panel_url = $this->sn_resolved_panel_portal_url($resolved);
		$button_label = $panel_url !== '' ? 'ورود به ' . $panel_label : 'پنل اختصاصی در دسترس نیست';
		$extra_links = [];
		if (current_user_can('manage_options')) {
			foreach (['customer' => 'پروفایل مشتری'] as $key => $label) {
				if ($this->sn_portal_can_access_nav_item($key)) {
					$url = $this->sn_portal_page_url($key);
					if ($url !== '' && $url !== $panel_url) {
						$extra_links[] = ['label' => $label, 'url' => $url];
					}
				}
			}
		}
		ob_start();
		?>
		<div class="sn-panel sn-no-sidebar sn-portal sn-my-panel-entry" dir="rtl">
			<div class="sn-portal-entry-card">
				<div>
					<h2>داشبورد من</h2>
					<p class="sn-muted">سلام <?php echo esc_html($this->sn_user_label((int) $user->ID)); ?>، مسیر پنل شما شناسایی شد.</p>
					<div class="sn-portal-entry-detected">
						<span>پنل شناسایی‌شده</span>
						<strong><?php echo esc_html($panel_label); ?></strong>
					</div>
				</div>
				<div class="sn-portal-entry-actions">
					<?php if ($panel_url !== '') : ?>
						<a class="sn-btn sn-btn-primary" href="<?php echo esc_url($panel_url); ?>"><?php echo esc_html($button_label); ?></a>
					<?php else : ?>
						<div class="sn-notice sn-info">پنل اختصاصی این سمت هنوز ساخته نشده است.</div>
					<?php endif; ?>
					<?php if (get_option('sn_my_password_page_id')) : ?><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url(get_permalink((int) get_option('sn_my_password_page_id'))); ?>">رمز من</a><?php endif; ?>
					<?php if ($extra_links) : ?>
						<div class="sn-portal-entry-links">
							<?php foreach ($extra_links as $link) : ?>
								<a href="<?php echo esc_url((string) $link['url']); ?>"><?php echo esc_html((string) $link['label']); ?></a>
							<?php endforeach; ?>
						</div>
					<?php endif; ?>
				</div>
			</div>
			<?php if ($panel_url === '') : ?>
				<div class="sn-card"><p class="sn-muted">اگر مسیر پنل اشتباه است، سمت HR کاربر را در پنل منابع انسانی یا ابزارهای یکپارچه‌سازی بررسی کنید.</p></div>
			<?php endif; ?>
			<?php if (current_user_can('manage_options')) : ?>
				<details class="sn-card sn-advanced">
					<summary>جزئیات فنی مسیر پنل</summary>
					<table class="sn-table">
						<tbody>
							<tr><th>کاربر</th><td><?php echo esc_html($this->sn_user_label(get_current_user_id())); ?></td></tr>
							<tr><th>نقش‌های وردپرس</th><td><?php echo esc_html(implode(', ', (array) ($resolved['wp_roles'] ?? []))); ?></td></tr>
							<tr><th>legacy_role</th><td><code><?php echo esc_html((string) ($resolved['legacy_role'] ?? '')); ?></code></td></tr>
							<tr><th>سمت HR</th><td><code><?php echo esc_html((string) ($resolved['position_slug'] ?? '')); ?></code></td></tr>
							<tr><th>سطح HR</th><td><code><?php echo esc_html((string) ($resolved['level_slug'] ?? '')); ?></code></td></tr>
							<tr><th>panel_key</th><td><code><?php echo esc_html((string) ($resolved['panel_key'] ?? '')); ?></code></td></tr>
							<tr><th>shortcode</th><td><code><?php echo esc_html($shortcode); ?></code></td></tr>
