	private function sn_resolved_panel_portal_url(array $resolved): string
	{
		$panel_key = (string) ($resolved['panel_key'] ?? '');
		if ($panel_key === 'admin_dashboard') {
			return admin_url('admin.php?page=sn-dashboard');
		}
		$map = [
			'seller_panel' => 'seller',
			'supervisor_panel' => 'supervisor',
			'converter_panel' => 'converter',
			'senior_supervisor_panel' => 'senior_supervisor',
			'sales_manager_panel' => 'sales_manager',
			'sales_deputy_panel' => 'sales_deputy',
			'finance_panel' => 'finance',
			'invoice_review_panel' => 'invoice_review',
			'hr_panel' => 'hr',
			'mis_panel' => 'mis',
			'after_sales_panel' => 'after_sales',
			'project_manager_panel' => 'operations_sales_manager',
			'project_expert_panel' => 'operations_sales_expert',
			'shipping_panel' => 'shipping',
			'operations_sales_manager_panel' => 'operations_sales_manager',
			'operations_sales_supervisor_panel' => 'operations_sales_supervisor',
			'operations_sales_expert_panel' => 'operations_sales_expert',
			'operations_executive_manager_panel' => 'operations_executive_manager',
			'operations_execution_expert_panel' => 'operations_execution_expert',
		];
		$portal_key = $map[$panel_key] ?? '';
		if ($portal_key !== '') {
			$url = $this->sn_portal_page_url($portal_key);
			if ($url !== '') {
				return $url;
			}
		}
		return '';
	}

