	private function sn_portal_page_ids(): array
	{
		$ids = get_option('sn_portal_page_ids', []);
		$ids = is_array($ids) ? array_map('absint', $ids) : [];
		foreach ($this->sn_portal_page_registry() as $key => $page) {
			if (empty($ids[$key]) && ! empty($page['option'])) {
				$legacy_id = (int) get_option((string) $page['option'], 0);
				if ($legacy_id > 0) {
					$ids[$key] = $legacy_id;
				}
			}
		}
		return $ids;
	}

	private function sn_shortcode_bracketed(string $shortcode): string
	{
		$shortcode = trim($shortcode);
		if ($shortcode === '') { return ''; }
		if ($shortcode[0] === '[') { return $shortcode; }
		return '[' . sanitize_key($shortcode) . ']';
	}

	private function sn_elementor_shortcode_data(string $shortcode): string
	{
		$shortcode = $this->sn_shortcode_bracketed($shortcode);
		$data = [[
			'id' => substr(md5('sn_section_' . $shortcode), 0, 8),
			'elType' => 'section',
			'isInner' => false,
			'settings' => [
				'layout' => 'full_width',
				'content_width' => 'full',
				'stretch_section' => 'section-stretched',
			],
			'elements' => [[
				'id' => substr(md5('sn_column_' . $shortcode), 0, 8),
				'elType' => 'column',
				'isInner' => false,
				'settings' => ['_column_size' => 100, '_inline_size' => null],
				'elements' => [[
					'id' => substr(md5('sn_shortcode_' . $shortcode), 0, 8),
					'elType' => 'widget',
					'widgetType' => 'shortcode',
					'settings' => ['shortcode' => $shortcode],
					'elements' => [],
				]],
			]],
		]];
		return wp_json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?: '[]';
	}

	private function sn_elementor_data_is_simple_shortcode($raw): bool
	{
		if (! is_string($raw) || trim($raw) === '') { return true; }
		$decoded = json_decode($raw, true);
		if (! is_array($decoded)) { return false; }
		$widgets = 0;
		$walk = static function ($nodes) use (&$walk, &$widgets): void {
			foreach ((array) $nodes as $node) {
				if (! is_array($node)) { continue; }
				if (($node['elType'] ?? '') === 'widget') { $widgets++; }
				if (! empty($node['elements'])) { $walk($node['elements']); }
			}
		};
		$walk($decoded);
		return $widgets <= 1 && strpos($raw, '"widgetType":"shortcode"') !== false;
	}

	private function sn_apply_crm_page_layout_defaults(int $page_id, string $shortcode): void
	{
		if ($page_id < 1) { return; }
		$shortcode = $this->sn_shortcode_bracketed($shortcode);
		if ($shortcode === '') { return; }
		update_post_meta($page_id, '_wp_page_template', 'elementor_canvas');
		update_post_meta($page_id, '_sn_system_page', '1');
		$settings = get_post_meta($page_id, '_elementor_page_settings', true);
		$settings = is_array($settings) ? $settings : [];
		$settings['page_layout'] = 'elementor_canvas';
		$settings['template'] = 'elementor_canvas';
		update_post_meta($page_id, '_elementor_page_settings', $settings);
		if (! metadata_exists('post', $page_id, '_elementor_edit_mode')) {
			update_post_meta($page_id, '_elementor_edit_mode', 'builder');
		}
		update_post_meta($page_id, '_elementor_template_type', 'wp-page');
		$existing_data = (string) get_post_meta($page_id, '_elementor_data', true);
		if ($this->sn_elementor_data_is_simple_shortcode($existing_data)) {
			update_post_meta($page_id, '_elementor_data', $this->sn_elementor_shortcode_data($shortcode));
		}
	}

	public function sn_apply_crm_page_layout_defaults_once(): void
	{
		if (! is_admin() || wp_doing_ajax() || $this->sn_defer_heavy_admin_runtime()) { return; }
		$layout_version = '2026-06-25-v1';
		if ((string) get_option('sn_elementor_canvas_defaults_version', '') === $layout_version) { return; }
		$shortcodes = [];
		foreach ($this->sn_portal_page_registry() as $page) {
			$shortcodes[(string) ($page['slug'] ?? '')] = $this->sn_shortcode_bracketed((string) ($page['shortcode'] ?? ''));
		}
		if (class_exists('SN_Activator') && method_exists('SN_Activator', 'required_pages')) {
			foreach (SN_Activator::required_pages() as $page) {
				$shortcodes[(string) ($page['slug'] ?? '')] = $this->sn_shortcode_bracketed((string) ($page['shortcode'] ?? ''));
			}
		}
		foreach ($shortcodes as $slug => $shortcode) {
			if ($slug === '' || $shortcode === '') { continue; }
			$page = get_page_by_path($slug, OBJECT, 'page');
			if ($page instanceof WP_Post && has_shortcode((string) $page->post_content, trim($shortcode, '[]'))) {
				$this->sn_apply_crm_page_layout_defaults((int) $page->ID, $shortcode);
			}
		}
		update_option('sn_elementor_canvas_defaults_version', $layout_version, false);
	}

	private function sn_portal_page_url(string $key, array $args = []): string
	{
		$registry = $this->sn_portal_page_registry();
		if (! isset($registry[$key])) {
			return '';
		}
		$ids = $this->sn_portal_page_ids();
		$page_id = (int) ($ids[$key] ?? 0);
		$url = $page_id > 0 ? (string) get_permalink($page_id) : '';
		if ($url === '') {
			$page = get_page_by_path((string) $registry[$key]['slug'], OBJECT, 'page');
			$url = $page instanceof WP_Post ? (string) get_permalink((int) $page->ID) : '';
		}
		if ($url === '') {
			return '';
		}
		$safe_args = [];
		foreach ($args as $arg_key => $value) {
			$arg_key = sanitize_key((string) $arg_key);
			if ($arg_key === '' || in_array($arg_key, ['access_token', 'token', 'public_invoice_url', 'invoice_url'], true)) {
				continue;
			}
			$safe_args[$arg_key] = is_scalar($value) ? sanitize_text_field((string) $value) : '';
		}
		return $safe_args ? add_query_arg($safe_args, $url) : $url;
	}

	private function sn_portal_page_setup_report(bool $apply = false, bool $store = false): array
	{
		$registry = $this->sn_portal_page_registry();
		$page_ids = $this->sn_portal_page_ids();
		$report = [
			'mode' => $apply ? 'apply' : 'dry_run',
			'created' => 0,
			'existing' => 0,
			'conflicts' => 0,
			'missing_shortcode' => 0,
			'items' => [],
			'updated_at' => current_time('mysql'),
		];

		foreach ($registry as $key => $page) {
			$shortcode = sanitize_key((string) ($page['shortcode'] ?? ''));
			$item = [
				'key' => $key,
				'title' => (string) $page['title'],
				'slug' => (string) $page['slug'],
				'shortcode' => $shortcode,
				'page_id' => 0,
				'url' => '',
				'status' => 'unknown',
				'message' => '',
			];
			if (! $shortcode || ! shortcode_exists($shortcode)) {
				$item['status'] = 'missing_shortcode';
				$item['message'] = 'shortcode_not_registered';
				$report['missing_shortcode']++;
				$report['items'][] = $item;
				continue;
			}

			$page_post = null;
			$stored_id = (int) ($page_ids[$key] ?? 0);
			if ($stored_id > 0) {
				$maybe = get_post($stored_id);
				if ($maybe instanceof WP_Post && $maybe->post_type === 'page' && $maybe->post_status !== 'trash') {
					$page_post = $maybe;
				}
			}
			if (! $page_post) {
				$maybe = get_page_by_path((string) $page['slug'], OBJECT, 'page');
				if ($maybe instanceof WP_Post) {
					$page_post = $maybe;
				}
			}

			$content_has_shortcode = $page_post instanceof WP_Post && has_shortcode((string) $page_post->post_content, $shortcode);
			if ($page_post instanceof WP_Post) {
				$item['page_id'] = (int) $page_post->ID;
				$item['url'] = (string) get_permalink($page_post->ID);
				if ($content_has_shortcode) {
					if ($apply || $store) {
						$this->sn_apply_crm_page_layout_defaults((int) $page_post->ID, '[' . $shortcode . ']');
					}
					$item['status'] = 'exists';
					$item['message'] = 'page_already_contains_shortcode';
					$page_ids[$key] = (int) $page_post->ID;
					$report['existing']++;
				} else {
					$item['status'] = 'conflict';
					$item['message'] = 'slug_exists_without_expected_shortcode';
					$report['conflicts']++;
				}
				$report['items'][] = $item;
				continue;
			}

			$item['status'] = $apply ? 'create_pending' : 'would_create';
			if ($apply) {
				// v1.0.66: panel pages should not receive a global portal navbar by default.
				// Users are routed to their own panel after unified login; extra cross-panel nav was confusing.
				$content = "[{$shortcode}]";
				$new_id = wp_insert_post([
					'post_type' => 'page',
					'post_status' => 'publish',
					'post_title' => (string) $page['title'],
					'post_name' => (string) $page['slug'],
					'post_content' => $content,
				], true);
				if (is_wp_error($new_id)) {
					$item['status'] = 'error';
					$item['message'] = $new_id->get_error_message();
				} else {
					$item['status'] = 'created';
					$item['page_id'] = (int) $new_id;
					$item['url'] = (string) get_permalink((int) $new_id);
					$this->sn_apply_crm_page_layout_defaults((int) $new_id, '[' . $shortcode . ']');
					$page_ids[$key] = (int) $new_id;
					$report['created']++;
				}
			}
			$report['items'][] = $item;
		}

		if ($apply || $store) {
			update_option('sn_portal_page_ids', $page_ids, false);
			update_option('sn_portal_page_setup_report', $report, false);
		}
		return $report;
	}

	public function handle_portal_page_setup(): void
	{
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_portal_page_setup');
		$mode = sanitize_key(wp_unslash($_POST['mode'] ?? 'dry_run'));
		if ($mode === 'apply' && trim((string) wp_unslash($_POST['confirm'] ?? '')) !== 'APPLY') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'portal_page_setup_confirm_missing'], admin_url('admin.php')));
			exit;
		}
		$apply = $mode === 'apply';
		$report = $this->sn_portal_page_setup_report($apply, true);
		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'portal_page_setup_done',
			'portal_mode' => $apply ? 'apply' : ($mode === 'refresh' ? 'refresh' : 'dry_run'),
			'portal_created' => (int) ($report['created'] ?? 0),
			'portal_conflicts' => (int) ($report['conflicts'] ?? 0),
		], admin_url('admin.php')));
		exit;
	}

	public function render_portal_nav($atts = []): string
	{
		// v1.0.66: The unified login already redirects each user to the correct panel.
		// Showing a global CRM portal navbar above every role panel is confusing and may expose links
		// the operator did not intend to present. Keep the shortcode inert by default so existing
		// pages that still contain [sn_portal_nav] stop rendering that top bar.
		$atts = shortcode_atts(['show' => '0'], is_array($atts) ? $atts : [], 'sn_portal_nav');
		$enabled = (string) get_option('sn_portal_nav_enabled', '0') === '1' || (string) ($atts['show'] ?? '0') === '1';
		if (! $enabled || ! is_user_logged_in()) {
			return '';
		}
		$items = $this->sn_portal_nav_items();
		if (! $items) {
			return '';
		}
		$current_page_id = get_queried_object_id();
		ob_start();
		?>
		<nav class="sn-portal-nav" dir="rtl" aria-label="ناوبری پورتال CRM">
			<div class="sn-portal-nav-title">پورتال CRM</div>
			<div class="sn-portal-nav-list">
				<?php foreach ($items as $item) : ?>
					<?php $active = ! empty($item['page_id']) && (int) $item['page_id'] === (int) $current_page_id; ?>
					<?php if (! empty($item['url'])) : ?>
						<a class="<?php echo $active ? 'is-active' : ''; ?>" href="<?php echo esc_url((string) $item['url']); ?>"><?php echo esc_html((string) $item['label']); ?></a>
					<?php else : ?>
						<span class="is-disabled"><?php echo esc_html((string) $item['label']); ?></span>
					<?php endif; ?>
				<?php endforeach; ?>
			</div>
		</nav>
		<?php
		return ob_get_clean();
	}

	private function sn_portal_nav_items(): array
	{
		$registry = $this->sn_portal_page_registry();
		$ids = $this->sn_portal_page_ids();
		$nav_keys = ['crm_dashboard', 'seller', 'supervisor', 'converter', 'senior_supervisor', 'sales_manager', 'sales_deputy', 'finance', 'hr', 'mis', 'after_sales', 'shipping', 'operations_sales_manager', 'operations_sales_supervisor', 'operations_sales_expert', 'operations_executive_manager', 'operations_execution_expert', 'reports', 'customer'];
		$items = [];
		foreach ($nav_keys as $key) {
			if (! isset($registry[$key]) || ! $this->sn_portal_can_access_nav_item($key)) {
				continue;
			}
			$url = $this->sn_portal_page_url($key);
			$items[] = [
				'key' => $key,
				'label' => (string) ($registry[$key]['nav_label'] ?? $registry[$key]['title']),
				'url' => $url,
				'page_id' => (int) ($ids[$key] ?? 0),
			];
		}
		return $items;
	}

	private function sn_portal_can_access_nav_item(string $key): bool
	{
		if (current_user_can('manage_options')) {
			return true;
		}
		$user_id = get_current_user_id();
		if ($key === 'crm_dashboard') {
			return $user_id > 0;
		}
		if ($key === 'seller') {
			return $this->sn_user_has_hr_position($user_id, 'seller') || in_array('sn_seller', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'supervisor') {
			return $this->sn_user_has_hr_position($user_id, ['supervisor', 'senior_supervisor']) || in_array('sn_supervisor', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'converter') {
			return $this->sn_user_has_hr_position($user_id, ['converter', 'supervisor', 'senior_supervisor'])
				|| in_array('sn_converter', (array) wp_get_current_user()->roles, true)
				|| in_array('sn_supervisor', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'senior_supervisor') {
			return $this->sn_user_has_hr_position($user_id, 'senior_supervisor')
				|| in_array('sn_senior_supervisor', (array) wp_get_current_user()->roles, true)
				|| in_array('sas_senior_supervisor', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'sales_manager') {
			return $this->sn_user_has_hr_position($user_id, 'sales_manager') || current_user_can('sn_view_sales_reports');
		}
		if ($key === 'sales_deputy') {
			return $this->sn_user_has_hr_position($user_id, 'sales_deputy') || in_array('sn_sales_deputy', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'invoice_review') { return SN_Invoice_Review::allowed(); }
		if ($key === 'finance') {
			return $this->sn_can_view_finance();
		}
		if ($key === 'hr') {
			return $this->sn_can_manage_hr_panel();
		}
		if ($key === 'mis') {
			return $this->sn_can_access_mis_panel();
		}
		if ($key === 'after_sales') {
			return $this->sn_can_access_after_sales_panel();
		}
		if ($key === 'project_manager') {
			return $this->sn_user_has_hr_position($user_id, 'project_manager') || in_array('sn_project_manager', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'project_expert') {
			return $this->sn_user_has_hr_position($user_id, 'project_expert') || in_array('sn_project_expert', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'shipping') {
			return $this->sn_user_has_hr_position($user_id, 'shipping_expert') || in_array('sn_shipping_expert', (array) wp_get_current_user()->roles, true);
		}
		if ($key === 'operations_sales_manager') {
			return $this->sn_user_has_hr_position($user_id, 'operations_sales_manager') || current_user_can('sn_manage_operations_sales');
		}
		if ($key === 'operations_sales_supervisor') {
			return $this->sn_user_has_hr_position($user_id, 'operations_sales_supervisor') || current_user_can('sn_supervise_operations_sales');
		}
		if ($key === 'operations_sales_expert') {
			return $this->sn_user_has_hr_position($user_id, 'operations_sales_expert') || current_user_can('sn_work_operations_sales');
		}
		if ($key === 'operations_executive_manager') {
			return $this->sn_user_has_hr_position($user_id, 'operations_executive_manager') || current_user_can('sn_manage_operations_execution');
		}
		if ($key === 'operations_execution_expert') {
			return $this->sn_user_has_hr_position($user_id, 'operations_execution_expert') || current_user_can('sn_work_operations_execution');
		}
		if ($key === 'reports') {
			return false; // The reporting center is embedded in /crm-dashboard/.
		}
		if ($key === 'customer') {
			return $this->sn_can_view_customer_profiles();
		}
		return false;
	}

	private function sn_wrap_portal_output(string $content, array $resolved = []): string
	{
		$nav = $this->render_portal_nav();
		$context = $this->sn_render_portal_route_context($resolved);
		return '<div class="sn-portal-shell" dir="rtl">' . $nav . $context . $content . '</div>';
	}

	private function sn_render_portal_route_context(array $resolved): string
	{
		if (! is_user_logged_in()) {
			return '';
		}
		$position = (string) ($resolved['position_slug'] ?? '');
		$panel = (string) ($resolved['panel_label'] ?? $resolved['panel_key'] ?? '');
		$route_type = (string) ($resolved['route_type'] ?? '');
		$chips = [];
		if ($position !== '') {
			$chips[] = 'سمت: ' . $position;
		}
		if ($panel !== '') {
			$chips[] = 'مسیر: ' . $panel;
		}
		if ($route_type !== '') {
			$chips[] = 'نوع مسیر: ' . $route_type;
		}
		if (! $chips) {
			return '';
		}
		return '<div class="sn-portal-route-context">' . implode('', array_map(static function ($chip) {
			return '<span>' . esc_html($chip) . '</span>';
		}, $chips)) . '</div>';
	}

