				<h2>ورود به پنل</h2>
				<p>برای ورود به پنل، ابتدا وارد حساب کاربری شوید.</p>
			</div>
			<div class="sn-auth-card">
				<?php if ($err) : ?><div class="sn-auth-error"><?php echo esc_html($errors[$err] ?? 'خطا رخ داد.'); ?></div><?php endif; ?>
				<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
					<input type="hidden" name="action" value="sn_my_panel_login">
					<input type="hidden" name="redirect" value="<?php echo esc_attr($redirect); ?>">
					<div class="sn-field"><label>شماره موبایل / نام کاربری / ایمیل</label><input type="text" name="phone" required autocomplete="username"><small class="sn-muted">برای ورود می‌توانید شماره موبایل ثبت‌شده خود را وارد کنید.</small></div>
					<div class="sn-field"><label>رمز عبور</label><input type="password" name="password" required autocomplete="current-password"></div>
					<button type="submit" class="sn-auth-submit">ورود به پنل</button>
				</form>
				<div class="sn-auth-footer">سامانه فروش — <?php echo esc_html(get_bloginfo('name')); ?></div>
			</div>
		</div>
		<?php
		return ob_get_clean();
	}

	private function sn_current_url(): string
	{
		$scheme = is_ssl() ? 'https://' : 'http://';
		$host = sanitize_text_field(wp_unslash($_SERVER['HTTP_HOST'] ?? ''));
		$uri = sanitize_text_field(wp_unslash($_SERVER['REQUEST_URI'] ?? '/'));
		$url = $host ? $scheme . $host . $uri : home_url('/');
		return remove_query_arg('sn_err', $url);
	}

	private function sn_hr_panel_return_url(array $args = []): string
	{
		$referer = wp_get_referer();
		if ($referer) {
			$safe_referer = wp_validate_redirect($referer, '');
			if ($safe_referer !== '') {
				return add_query_arg($args, remove_query_arg(['sn_msg'], $safe_referer));
			}
		}
		$hr_url = $this->sn_portal_page_url('hr');
		if ($hr_url !== '') {
			return add_query_arg($args, $hr_url);
		}
		if (current_user_can('manage_options')) {
			return add_query_arg(array_merge(['page' => 'sn-integration'], $args), admin_url('admin.php'));
		}
		return add_query_arg($args, home_url('/'));
	}

	private function sn_enqueue_public_panel_assets(string $shortcode): void
	{
		$asset_map = [
			'sn_seller_panel' => 'seller',
			'sn_supervisor_panel' => 'supervisor',
			'sn_senior_supervisor_panel' => 'supervisor',
			'sn_sales_manager_panel' => 'manager',
			'sn_financial_panel' => 'manager',
			'sn_hr_panel' => 'hr',
			'sn_mis_panel' => 'manager',
			'sn_sales_deputy_panel' => 'manager',
			'sn_dot_converter_panel' => 'converter',
			'sn_dot_customer_flow' => 'dot',
		];
		$script_map = [
			'seller' => 'public-seller.js',
			'supervisor' => 'public-supervisor.js',
			'manager' => 'public-manager.js',
			'hr' => 'public-manager.js',
			'dot' => 'public-dot.js',
			'converter' => 'public-converter.js',
		];
		$asset_key = $asset_map[$shortcode] ?? '';
		if ($asset_key === '') {
			return;
		}
		wp_enqueue_style('sn-public', SN_PLUGIN_URL . 'assets/css/public.css', [], SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/css/public.css') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/css/public.css') : '0'));
		wp_enqueue_style('sn-public-performance', SN_PLUGIN_URL . 'assets/css/public-performance.css', ['sn-public'], SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/css/public-performance.css') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/css/public-performance.css') : '0'));
		if (in_array($asset_key, ['dot','converter','seller','supervisor'], true)) {
			wp_enqueue_style('sn-dot-flow', SN_PLUGIN_URL . 'assets/css/dot-flow.css', ['sn-public'], SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/css/dot-flow.css') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/css/dot-flow.css') : '0'));
		}
		$script_file = $script_map[$asset_key] ?? 'public-manager.js';
		$public_js_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/js/public.js') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/js/public.js') : '0');
		$panel_js_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/js/' . $script_file) ? (string) filemtime(SN_PLUGIN_DIR . 'assets/js/' . $script_file) : '0');
		$shell_js_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/js/public-shell.js') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/js/public-shell.js') : '0');
		wp_enqueue_script('sn-public-shell', SN_PLUGIN_URL . 'assets/js/public-shell.js', [], $shell_js_version, true);
		$handle = 'sn-public-' . $asset_key;
		$deps = ['jquery', 'sn-public-shell', 'sn-payment-transactions'];
        wp_enqueue_script('sn-payment-transactions', SN_PLUGIN_URL . 'assets/js/payment-transactions.js', ['jquery','sn-public-shell'], SN_VERSION, true);
		// HR needs public.js for the generic tab engine and workforce interaction helpers;
		// manager/supervisor stay standalone to avoid duplicate heavy Ajax handlers.
		if (in_array($asset_key, ['seller', 'hr', 'converter'], true)) {
			wp_enqueue_script('sn-public-base', SN_PLUGIN_URL . 'assets/js/public.js', ['jquery', 'sn-public-shell'], $public_js_version, true);
			$deps[] = 'sn-public-base';
		}
		if (in_array($asset_key, ['converter', 'seller'], true)) {
			$dot_shared_version = SN_VERSION . '-' . (file_exists(SN_PLUGIN_DIR . 'assets/js/public-dot.js') ? (string) filemtime(SN_PLUGIN_DIR . 'assets/js/public-dot.js') : '0');
			wp_enqueue_script('sn-public-dot-shared', SN_PLUGIN_URL . 'assets/js/public-dot.js', ['jquery','sn-public-shell'], $dot_shared_version, true);
			$deps[] = 'sn-public-dot-shared';
		}
		wp_enqueue_script($handle, SN_PLUGIN_URL . 'assets/js/' . $script_file, $deps, $panel_js_version, true);
		SN_Sales_Catalog::instance()->staff_assets();
		$sn_public_data = [
			'ajaxurl' => admin_url('admin-ajax.php'),
			'nonce' => wp_create_nonce('sn_public'),
			'admin_nonce' => (current_user_can('manage_options') || current_user_can('sn_manage_supervisor_leads')) ? wp_create_nonce('sn_admin') : '',
			'current_user' => get_current_user_id(),
			'asset_key' => $asset_key,
			'invoice_token' => '',
		];
		if (wp_script_is('sn-public-base', 'enqueued')) {
			wp_localize_script('sn-public-base', 'snAjax', $sn_public_data);
			wp_localize_script('sn-public-base', 'snData', $sn_public_data);
		}
		if (wp_script_is('sn-public-dot-shared', 'enqueued')) {
			wp_localize_script('sn-public-dot-shared', 'snAjax', $sn_public_data);
			wp_localize_script('sn-public-dot-shared', 'snData', $sn_public_data);
			wp_localize_script('sn-public-dot-shared', 'snDot', $sn_public_data);
		}
		wp_localize_script($handle, 'snAjax', $sn_public_data);
		wp_localize_script($handle, 'snData', $sn_public_data);
		if ($asset_key === 'dot') { wp_localize_script($handle, 'snDot', $sn_public_data); }
	}

