	private function sn_get_user_panel_url(int $user_id): string
	{
		// 1.0.125: fast front-login resolver. Avoid SN_HR_Service full resolver on every login/admin redirect.
		$user_id = absint($user_id);
		if ($user_id < 1) { return ''; }
		$position = $this->sn_fast_hr_position_for_user($user_id);
		$portal_key_map = [
			'seller' => 'seller',
			'supervisor' => 'supervisor',
			'converter' => 'converter',
			'senior_supervisor' => 'senior_supervisor',
			'sales_manager' => 'sales_manager',
			'sales_deputy' => 'sales_deputy',
			'finance' => 'finance',
			'invoice_reviewer' => 'invoice_review',
			'hr' => 'hr',
			'mis' => 'mis',
			'after_sales' => 'after_sales',
			'project_manager' => 'operations_sales_manager',
			'project_expert' => 'operations_sales_expert',
			'shipping_expert' => 'shipping',
			'operations_sales_manager' => 'operations_sales_manager',
			'operations_sales_supervisor' => 'operations_sales_supervisor',
			'operations_sales_expert' => 'operations_sales_expert',
			'operations_executive_manager' => 'operations_executive_manager',
			'operations_execution_expert' => 'operations_execution_expert',
		];
		$portal_key = $portal_key_map[$position] ?? '';
		if ($portal_key !== '') {
			$portal_url = $this->sn_portal_page_url($portal_key);
			if ($portal_url !== '') { return $portal_url; }
		}
		$role_option_map = [
			'sn_seller' => 'sn_seller_panel_page_id',
			'sn_supervisor' => 'sn_supervisor_panel_page_id',
			'sn_senior_supervisor' => 'sn_senior_supervisor_panel_page_id',
			'sas_senior_supervisor' => 'sn_senior_supervisor_panel_page_id',
			'sn_converter' => 'sn_dot_converter_panel_page_id',
			'sn_sales_manager' => 'sn_sales_manager_panel_page_id',
			'sn_sales_deputy' => 'sn_sales_deputy_panel_page_id',
			'sn_after_sales' => 'sn_after_sales_panel_page_id',
			'sn_financial' => 'sn_financial_panel_page_id',
			'sn_financial_approval' => 'sn_financial_panel_page_id',
			'sn_finance' => 'sn_financial_panel_page_id',
			'sn_invoice_reviewer' => 'sn_invoice_review_panel_page_id',
			'sn_hr' => 'sn_hr_panel_page_id',
			'sn_mis' => 'sn_mis_panel_page_id',
			'sn_project_manager' => 'sn_operations_sales_manager_panel_page_id',
			'sn_project_expert' => 'sn_operations_sales_expert_panel_page_id',
			'sn_shipping_expert' => 'sn_shipping_panel_page_id',
			'sn_operations_sales_manager' => 'sn_operations_sales_manager_panel_page_id',
			'sn_operations_sales_supervisor' => 'sn_operations_sales_supervisor_panel_page_id',
			'sn_operations_sales_expert' => 'sn_operations_sales_expert_panel_page_id',
			'sn_operations_executive_manager' => 'sn_operations_executive_manager_panel_page_id',
			'sn_operations_execution_expert' => 'sn_operations_execution_expert_panel_page_id',
		];
		$user = get_user_by('id', $user_id);
		$roles = $user instanceof WP_User ? (array) $user->roles : [];
		foreach ($role_option_map as $role => $option) {
			if (in_array($role, $roles, true)) {
				$page_id = (int) get_option($option, 0);
				$url = $page_id ? (string) get_permalink($page_id) : '';
				if ($url !== '') { return $url; }
			}
		}
		return '';
	}

	private function sn_clean_ui_tab_id($value): string
	{
		if (! is_scalar($value)) {
			return '';
		}
		$value = (string) $value;
		$value = rawurldecode($value);
		$value = preg_replace('/^#/', '', $value);
		$value = preg_replace('/[^A-Za-z0-9_-]/', '', $value);
		return is_string($value) ? $value : '';
	}

	private function sn_requested_ui_active_tab(): string
	{
		$post_tab = isset($_POST['sn_ui_active_tab']) ? $this->sn_clean_ui_tab_id(wp_unslash($_POST['sn_ui_active_tab'])) : '';
		if ($post_tab !== '') {
			return $post_tab;
		}
		$get_tab = isset($_GET['sn_ui_active_tab']) ? $this->sn_clean_ui_tab_id(wp_unslash($_GET['sn_ui_active_tab'])) : '';
		if ($get_tab !== '') {
			return $get_tab;
		}
		$legacy_mis_tab = isset($_GET['sn_mis_tab']) ? $this->sn_clean_ui_tab_id(wp_unslash($_GET['sn_mis_tab'])) : '';
		return $legacy_mis_tab;
	}

	private function sn_effective_panel_tab(string $default, array $tabs): string
	{
		$default = $this->sn_clean_ui_tab_id($default);
		$requested = $this->sn_requested_ui_active_tab();
		if ($requested !== '' && array_key_exists($requested, $tabs)) {
			return $requested;
		}
		return $default;
	}

	public function sn_preserve_ui_active_tab_on_redirect($location, $status = 302): string
	{
		$tab = isset($_POST['sn_ui_active_tab']) ? $this->sn_clean_ui_tab_id(wp_unslash($_POST['sn_ui_active_tab'])) : '';
		if ($tab === '' || ! is_string($location) || $location === '') {
			return is_string($location) ? $location : '';
		}
		[$base] = array_pad(explode('#', $location, 2), 1, '');
		$base = remove_query_arg('sn_ui_active_tab', $base);
		$base = add_query_arg('sn_ui_active_tab', $tab, $base);
		return $base . '#' . $tab;
	}

	private function sn_internal_panel_url(string $option_name, array $args = []): string
	{
		$page_id = (int) get_option($option_name, 0);
		$url = $page_id ? (string) get_permalink($page_id) : '';
		if ($url === '') {
			return '';
		}
		$safe_args = [];
		foreach ($args as $key => $value) {
			$key = sanitize_key((string) $key);
			if ($key === '' || in_array($key, ['access_token', 'token', 'public_invoice_url', 'invoice_url'], true)) {
				continue;
			}
			$safe_args[$key] = is_scalar($value) ? sanitize_text_field((string) $value) : '';
		}
		return $safe_args ? add_query_arg($safe_args, $url) : $url;
	}

	private function sn_safe_current_context_url(array $args = []): string
	{
		$url = remove_query_arg(['access_token', 'token', 'public_invoice_url', 'invoice_url']);
		$safe_args = [];
		foreach ($args as $key => $value) {
			$key = sanitize_key((string) $key);
			if ($key === '' || in_array($key, ['access_token', 'token', 'public_invoice_url', 'invoice_url'], true)) {
				continue;
			}
			$safe_args[$key] = is_scalar($value) ? sanitize_text_field((string) $value) : '';
		}
		return $safe_args ? add_query_arg($safe_args, $url) : $url;
	}

	private function sn_after_sales_context_url(string $invoice_code): string
	{
		$invoice_code = sanitize_text_field($invoice_code);
		return $invoice_code !== '' ? $this->sn_internal_panel_url('sn_after_sales_panel_page_id', ['as_invoice_code' => $invoice_code]) : '';
	}

	private function sn_admin_invoice_context_url(string $invoice_code): string
	{
		if (! current_user_can('manage_options')) {
			return '';
		}
		$invoice_code = sanitize_text_field($invoice_code);
		return $invoice_code !== '' ? add_query_arg(['page' => 'sn-invoices', 'sn_search' => $invoice_code], admin_url('admin.php')) : '';
	}

	private function sn_panel_route_badge(int $user_id): string
	{
		if (! class_exists('SN_HR_Service') || $user_id <= 0) {
			return '—';
		}
		$resolved = (new SN_HR_Service())->resolve_panel_for_user($user_id);
		$label = (string) ($resolved['panel_label'] ?? ($resolved['panel_key'] ?? '—'));
		$key = (string) ($resolved['panel_key'] ?? '');
		return '<span class="sn-badge sn-route-badge" title="' . esc_attr($key) . '">' . esc_html($label) . '</span>';
	}

	private function sn_render_panel_tabs(array $tabs, string $active = ''): void
	{
		$tabs = array_filter($tabs, static fn($label) => (string) $label !== '');
		if (! $tabs) {
			return;
		}
		if ($active === '' || ! array_key_exists($active, $tabs)) {
			$active = (string) array_key_first($tabs);
		}
		$active = $this->sn_effective_panel_tab($active, $tabs);
		echo '<div class="sn-panel-toolbar"><div class="sn-tabs sn-tab-nav" data-sn-tabs>';
		foreach ($tabs as $id => $label) {
			$id = sanitize_key((string) $id);
			$classes = 'sn-tab-button' . ($id === $active ? ' sn-tab-button-active' : '');
			echo '<button type="button" class="' . esc_attr($classes) . '" data-sn-tab-target="' . esc_attr($id) . '" aria-controls="' . esc_attr($id) . '" aria-selected="' . esc_attr($id === $active ? 'true' : 'false') . '">' . esc_html((string) $label) . '</button>';
		}
		echo '</div></div>';
	}

	private function sn_tab_panel_class(string $id, string $active): string
	{
		$requested = $this->sn_requested_ui_active_tab();
		if ($requested !== '' && $requested === $id) {
			$active = $requested;
		}
		return 'sn-tab-panel' . ($id === $active ? ' sn-tab-panel-active' : '');
	}

	public function render_sales_deputy_panel(): string
	{
		if (! is_user_logged_in()) {
			return $this->render_unified_panel_login();
		}
		if (! current_user_can('manage_options') && $this->sn_fast_hr_position_for_user(get_current_user_id()) !== 'sales_deputy') {
			return '<div class="sn-panel" dir="rtl"><div class="sn-notice sn-error">دسترسی به پنل معاون فروش مجاز نیست.</div></div>';
		}
		if (! class_exists('SN_Scope_Service') || ! class_exists('SN_Hierarchy_Service') || ! class_exists('SN_HR_Service')) {
			return '<div class="sn-panel" dir="rtl"><div class="sn-notice sn-error">سرویس منابع انسانی در دسترس نیست.</div></div>';
