	private function sn_sales_deputy_filters(): array
	{
		return [
			'date_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['sn_sd_date_from'] ?? ''))),
			'date_to' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['sn_sd_date_to'] ?? ''))),
			'sales_manager_id' => absint($_GET['sn_sd_sales_manager'] ?? 0),
			'senior_supervisor_id' => absint($_GET['sn_sd_senior_supervisor'] ?? 0),
			'invoice_status' => sanitize_key(wp_unslash($_GET['sn_sd_invoice_status'] ?? '')),
		];
	}

	private function sn_sales_deputy_filtered_seller_ids(array $visible_seller_ids, array $filters): array
	{
		$ids = array_values(array_unique(array_map('intval', $visible_seller_ids)));
		foreach (['sales_manager_id', 'senior_supervisor_id'] as $filter_key) {
			$user_id = (int) ($filters[$filter_key] ?? 0);
			if (! $user_id) {
				continue;
			}
			$scope_ids = $this->sn_sales_deputy_seller_ids_under_user($user_id);
			$ids = array_values(array_intersect($ids, $scope_ids));
		}
		return $ids;
	}

	private function sn_sales_deputy_seller_ids_under_user(int $user_id): array
	{
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$profile = $hr->get_profile_by_user_id($user_id);
		if (! $profile) {
			return [];
		}
		return $this->sn_sales_deputy_seller_ids_for_profiles($hierarchy->get_descendant_profile_ids((int) $profile->id, 10));
	}

	private function sn_sales_deputy_profiles_by_position(string $position_slug, array $visible_profile_ids): array
	{
		global $wpdb;
		$visible_profile_ids = array_values(array_unique(array_map('intval', $visible_profile_ids)));
		if (! $visible_profile_ids) {
			return [];
		}
		$ph = implode(',', array_fill(0, count($visible_profile_ids), '%d'));
		return $wpdb->get_results($wpdb->prepare(
			"SELECT p.*, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			WHERE p.id IN ({$ph}) AND pos.slug=%s
			ORDER BY u.display_name ASC, p.user_id ASC",
			...array_merge($visible_profile_ids, [$position_slug])
		));
	}

	private function sn_sales_deputy_seller_ids_for_profiles(array $profile_ids): array
	{
		global $wpdb;
		$profile_ids = array_values(array_unique(array_map('intval', $profile_ids)));
		if (! $profile_ids) {
			return [];
		}
		$ph = implode(',', array_fill(0, count($profile_ids), '%d'));
		return array_map('intval', $wpdb->get_col($wpdb->prepare(
			"SELECT p.user_id
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE p.id IN ({$ph}) AND pos.slug='seller'",
			...$profile_ids
		)));
	}

	private function sn_sales_deputy_summary(array $seller_ids, array $filters): array
	{
		$status_counts = $this->sn_sales_deputy_seller_status_counts($seller_ids);
		return [
			'کل فروشنده‌های قابل مشاهده' => number_format_i18n(count($seller_ids)),
			'فروشنده فعال' => number_format_i18n($status_counts['active']),
			'فروشنده غیرفعال' => number_format_i18n($status_counts['inactive']),
			'کل لیدها' => number_format_i18n($this->sn_sales_deputy_count_leads($seller_ids, $filters)),
			'کل فاکتورها' => number_format_i18n($this->sn_sales_deputy_count_invoices($seller_ids, $filters)),
			'پیش‌فاکتور' => number_format_i18n($this->sn_sales_deputy_count_invoices($seller_ids, $filters, 'pre_invoice')),
			'فاکتور paid/approved' => number_format_i18n($this->sn_sales_deputy_count_invoices($seller_ids, $filters, 'paid')),
			'فاکتور rejected/returned' => number_format_i18n($this->sn_sales_deputy_count_invoices($seller_ids, $filters, 'rejected')),
			'مبلغ کل فاکتورها' => SN_Helpers::format_price($this->sn_sales_deputy_sum_invoices($seller_ids, $filters)),
			'مبلغ پرداخت‌شده' => SN_Helpers::format_price($this->sn_sales_deputy_sum_payments($seller_ids, $filters)),
		];
	}

	private function sn_sales_deputy_seller_status_counts(array $seller_ids): array
	{
		$active = 0;
		$inactive = 0;
		foreach (array_values(array_unique(array_map('intval', $seller_ids))) as $seller_id) {
			get_user_meta($seller_id, 'sn_is_active', true) === '0' ? $inactive++ : $active++;
		}
		return ['active' => $active, 'inactive' => $inactive];
	}

	private function sn_sales_deputy_invoice_where(array $seller_ids, array $filters, string $alias = 'i'): array
	{
		$seller_ids = array_values(array_unique(array_map('intval', $seller_ids)));
		if (! $seller_ids) {
			return ['0=1', []];
		}
		$ph = implode(',', array_fill(0, count($seller_ids), '%d'));
		$where = ["{$alias}.seller_id IN ({$ph})"];
		$args = $seller_ids;
		if (! empty($filters['date_from'])) {
			$where[] = "{$alias}.created_at >= %s";
			$args[] = $filters['date_from'] . ' 00:00:00';
		}
		if (! empty($filters['date_to'])) {
			$where[] = "{$alias}.created_at <= %s";
			$args[] = $filters['date_to'] . ' 23:59:59';
		}
		if (! empty($filters['invoice_status'])) {
			$where[] = "({$alias}.status=%s OR {$alias}.invoice_status=%s OR {$alias}.payment_status=%s)";
			$args[] = $filters['invoice_status'];
			$args[] = $filters['invoice_status'];
			$args[] = $filters['invoice_status'];
		}
		return [implode(' AND ', $where), $args];
	}

	private function sn_sales_deputy_lead_where(array $seller_ids, array $filters, string $alias = 'l'): array
	{
		global $wpdb;
		$seller_ids = array_values(array_unique(array_map('intval', $seller_ids)));
		if (! $seller_ids) {
			return ['0=1', []];
		}
		$ph = implode(',', array_fill(0, count($seller_ids), '%d'));
		$where = ["{$alias}.seller_id IN ({$ph})"];
		$args = $seller_ids;
		$cols = $this->sn_table_columns($wpdb->prefix . 'sn_leads');
		$date_col = in_array('created_at', $cols, true) ? 'created_at' : (in_array('assigned_at', $cols, true) ? 'assigned_at' : '');
		if ($date_col && ! empty($filters['date_from'])) {
			$where[] = "{$alias}.{$date_col} >= %s";
			$args[] = $filters['date_from'] . ' 00:00:00';
		}
		if ($date_col && ! empty($filters['date_to'])) {
			$where[] = "{$alias}.{$date_col} <= %s";
			$args[] = $filters['date_to'] . ' 23:59:59';
		}
		return [implode(' AND ', $where), $args];
	}

	private function sn_sales_deputy_count_leads(array $seller_ids, array $filters): int
	{
		global $wpdb;
		[$where, $args] = $this->sn_sales_deputy_lead_where($seller_ids, $filters, 'l');
		$sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads l WHERE {$where}";
		return (int) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_sales_deputy_count_invoices(array $seller_ids, array $filters, string $bucket = ''): int
	{
		global $wpdb;
		[$where, $args] = $this->sn_sales_deputy_invoice_where($seller_ids, $filters, 'i');
		if ($bucket === 'paid') {
			$where .= " AND (i.status IN ('paid','approved') OR i.invoice_status IN ('paid','approved') OR i.payment_status IN ('paid','approved'))";
		} elseif ($bucket === 'rejected') {
			$where .= " AND (i.status IN ('rejected','returned','return') OR i.invoice_status IN ('rejected','returned','return') OR i.payment_status IN ('rejected','returned','return'))";
		} elseif ($bucket === 'pre_invoice') {
			$where .= " AND (i.status IN ('pending','draft','unpaid') OR COALESCE(i.status,'')='')";
		}
		$sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}";
		return (int) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_sales_deputy_sum_invoices(array $seller_ids, array $filters): float
	{
		global $wpdb;
		[$where, $args] = $this->sn_sales_deputy_invoice_where($seller_ids, $filters, 'i');
		$sql = "SELECT COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}";
		return (float) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_sales_deputy_sum_payments(array $seller_ids, array $filters): float
	{
		global $wpdb;
		[$where, $args] = $this->sn_sales_deputy_invoice_where($seller_ids, $filters, 'i');
		$where .= " AND p.status IN ('paid','approved','verified','success')";
		$sql = "SELECT COALESCE(SUM(p.amount),0) FROM {$wpdb->prefix}sn_payments p INNER JOIN {$wpdb->prefix}sn_invoices i ON i.id=p.invoice_id WHERE {$where}";
		return (float) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_sales_deputy_hierarchy_overview(array $manager_profiles, array $visible_seller_ids, array $filters): array
	{
		$rows = [];
		$hierarchy = new SN_Hierarchy_Service();
		foreach ($manager_profiles as $manager) {
			$descendants = $hierarchy->get_descendant_profile_ids((int) $manager->id, 10);
			$seller_ids = array_values(array_intersect($visible_seller_ids, $this->sn_sales_deputy_seller_ids_for_profiles($descendants)));
			$seller_ids = $this->sn_sales_deputy_filtered_seller_ids($seller_ids, $filters);
			$child_profiles = $hierarchy->get_direct_children_profile_ids((int) $manager->id);
			$direct_sellers = count(array_intersect($visible_seller_ids, $this->sn_sales_deputy_seller_ids_for_profiles($child_profiles)));
			$senior_summaries = [];
			foreach ($child_profiles as $child_profile_id) {
				$position = $this->sn_sales_deputy_position_for_profile((int) $child_profile_id);
				if ($position !== 'senior_supervisor') {
					continue;
				}
				$user_id = $this->sn_sales_deputy_user_for_profile((int) $child_profile_id);
				$senior_seller_ids = array_values(array_intersect($visible_seller_ids, $this->sn_sales_deputy_seller_ids_for_profiles($hierarchy->get_descendant_profile_ids((int) $child_profile_id, 10))));
				$senior_summaries[] = $this->sn_user_label($user_id) . ': ' . count($senior_seller_ids);
			}
			$rows[] = [
				'manager_label' => $this->sn_user_label((int) $manager->user_id),
				'senior_summary' => $senior_summaries ? implode(' | ', $senior_summaries) : '—',
				'direct_sellers' => $direct_sellers,
				'total_sellers' => count($seller_ids),
			];
		}
		return $rows;
	}

	private function sn_sales_deputy_performance_rows(array $profiles, array $visible_seller_ids, array $filters, string $position_slug): array
	{
		$rows = [];
		$hierarchy = new SN_Hierarchy_Service();
		foreach ($profiles as $profile) {
			if ($position_slug === 'seller') {
				$seller_ids = in_array((int) $profile->user_id, $visible_seller_ids, true) ? [(int) $profile->user_id] : [];
			} else {
				$seller_ids = array_values(array_intersect($visible_seller_ids, $this->sn_sales_deputy_seller_ids_for_profiles($hierarchy->get_descendant_profile_ids((int) $profile->id, 10))));
			}
			$seller_ids = $this->sn_sales_deputy_filtered_seller_ids($seller_ids, $filters);
			$status_counts = $this->sn_sales_deputy_seller_status_counts($seller_ids);
			$parent_label = '';
			if (in_array($position_slug, ['senior_supervisor', 'supervisor', 'seller'], true)) {
				$parent_user_id = $hierarchy->get_current_parent_user_id((int) $profile->user_id);
				$parent_label = $parent_user_id ? $this->sn_user_label($parent_user_id) : '—';
			}
			$rows[] = [
				'label' => $this->sn_user_label((int) $profile->user_id),
				'parent_label' => $parent_label,
				'sellers' => count($seller_ids),
				'active_sellers' => $status_counts['active'],
				'leads' => $this->sn_sales_deputy_count_leads($seller_ids, $filters),
				'invoices' => $this->sn_sales_deputy_count_invoices($seller_ids, $filters),
				'paid_invoices' => $this->sn_sales_deputy_count_invoices($seller_ids, $filters, 'paid'),
				'rejected_invoices' => $this->sn_sales_deputy_count_invoices($seller_ids, $filters, 'rejected'),
				'total_amount' => $this->sn_sales_deputy_sum_invoices($seller_ids, $filters),
				'paid_amount' => $this->sn_sales_deputy_sum_payments($seller_ids, $filters),
			];
		}
		return $rows;
	}

	private function sn_sales_deputy_render_performance_table(array $rows, string $first_col, string $parent_col): void
	{
		?>
		<table class="sn-table">
			<thead><tr><th><?php echo esc_html($first_col); ?></th><?php if ($parent_col) : ?><th><?php echo esc_html($parent_col); ?></th><?php endif; ?><th>فروشنده</th><th>فعال</th><th>لید</th><th>فاکتور</th><th>paid/approved</th><th>rejected/returned</th><th>مبلغ کل</th><th>مبلغ پرداخت‌شده</th></tr></thead>
			<tbody>
				<?php if (! $rows) : ?><tr><td colspan="<?php echo $parent_col ? 10 : 9; ?>">داده‌ای برای نمایش وجود ندارد.</td></tr><?php endif; ?>
				<?php foreach ($rows as $row) : ?>
					<tr>
						<td><?php echo esc_html((string) $row['label']); ?></td>
						<?php if ($parent_col) : ?><td><?php echo esc_html((string) $row['parent_label']); ?></td><?php endif; ?>
						<td><?php echo esc_html((string) (int) $row['sellers']); ?></td>
						<td><?php echo esc_html((string) (int) $row['active_sellers']); ?></td>
						<td><?php echo esc_html(number_format_i18n((int) $row['leads'])); ?></td>
						<td><?php echo esc_html(number_format_i18n((int) $row['invoices'])); ?></td>
						<td><?php echo esc_html(number_format_i18n((int) $row['paid_invoices'])); ?></td>
						<td><?php echo esc_html(number_format_i18n((int) $row['rejected_invoices'])); ?></td>
						<td><?php echo esc_html(SN_Helpers::format_price((float) $row['total_amount'])); ?></td>
						<td><?php echo esc_html(SN_Helpers::format_price((float) $row['paid_amount'])); ?></td>
					</tr>
				<?php endforeach; ?>
			</tbody>
		</table>
		<?php
	}

	private function sn_sales_deputy_recent_invoices(array $seller_ids, array $filters): array
	{
		global $wpdb;
		[$where, $args] = $this->sn_sales_deputy_invoice_where($seller_ids, $filters, 'i');
		$sql = "SELECT i.invoice_code, i.status, i.invoice_status, i.payment_status, COALESCE(i.final_total,i.product_price,0) amount, i.created_at, COALESCE(u.display_name, CONCAT('#', i.seller_id)) seller_name
			FROM {$wpdb->prefix}sn_invoices i
			LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id
			WHERE {$where}
			ORDER BY i.created_at DESC, i.id DESC
			LIMIT 20";
		return $wpdb->get_results($args ? $wpdb->prepare($sql, ...$args) : $sql, ARRAY_A) ?: [];
	}

	private function sn_sales_deputy_position_for_profile(int $profile_id): string
	{
		global $wpdb;
		return (string) $wpdb->get_var($wpdb->prepare(
			"SELECT pos.slug FROM {$wpdb->prefix}sn_hr_profiles p INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id WHERE p.id=%d",
			$profile_id
		));
	}

	private function sn_sales_deputy_user_for_profile(int $profile_id): int
	{
		global $wpdb;
		return (int) $wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$wpdb->prefix}sn_hr_profiles WHERE id=%d", $profile_id));
	}

	private function sn_user_label(int $user_id): string
	{
		$user_id = absint($user_id);
		if ($user_id < 1) { return '#0'; }
		if (isset($this->sn_user_label_cache[$user_id])) {
			return (string) $this->sn_user_label_cache[$user_id];
		}
		$label = $this->sn_hr_display_name_for_user($user_id);
		if ($label === '') {
			$user = get_user_by('id', $user_id);
			$label = $user instanceof WP_User ? trim((string) $user->display_name) : '';
		}
		$this->sn_user_label_cache[$user_id] = ($label !== '' ? $label : ('#' . $user_id)) . ' #' . $user_id;
		return (string) $this->sn_user_label_cache[$user_id];
	}

	/**
	 * نام نمایشی پرسنل فقط باید از پروفایل HR خوانده شود.
	 * customer/invoice flow ممکن است wp_users.display_name را تغییر دهد؛ پنل‌های داخلی نباید از آن آلوده شوند.
	 */
	private function sn_hr_display_name_for_user(int $user_id): string
	{
		global $wpdb;
		$user_id = absint($user_id);
		if ($user_id < 1) { return ''; }
		$table = $wpdb->prefix . 'sn_hr_profiles';
		if (! $this->sn_table_exists_quiet($table)) { return ''; }
		$this->sn_ensure_hr_display_name_column();
		$cols = $this->sn_table_columns($table);
		if (in_array('hr_display_name', $cols, true)) {
			$name = (string) $wpdb->get_var($wpdb->prepare("SELECT hr_display_name FROM {$table} WHERE user_id=%d AND is_active=1 ORDER BY id DESC LIMIT 1", $user_id));
			if (trim($name) !== '') { return trim($name); }
		}
		return '';
	}

	private function sn_hr_is_internal_user_id(int $user_id): bool
	{
		global $wpdb;
		$user_id = absint($user_id);
		if ($user_id < 1) { return false; }
		$user = get_user_by('id', $user_id);
		if ($user instanceof WP_User) {
			$internal_roles = ['administrator','sn_seller','sn_supervisor','sn_converter','sn_sales_manager','sn_senior_supervisor','sn_sales_deputy','sn_mis','sn_hr','sn_financial','sn_financial_approval','sn_finance','sn_after_sales','sn_project_manager','sn_project_expert','sn_shipping_expert','sn_operations_sales_manager','sn_operations_sales_supervisor','sn_operations_sales_expert','sn_operations_executive_manager','sn_operations_execution_expert'];
			if (array_intersect($internal_roles, (array) $user->roles) || user_can($user, 'manage_options')) { return true; }
		}
		$table = $wpdb->prefix . 'sn_hr_profiles';
		return $this->sn_table_exists_quiet($table) && (bool) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE user_id=%d AND is_active=1 LIMIT 1", $user_id));
	}

	private function sn_ensure_hr_display_name_column(): void
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_profiles';
		if (! $this->sn_table_exists_quiet($table)) { return; }
		$cols = $this->sn_table_columns($table);
		if (! in_array('hr_display_name', $cols, true)) {
			$wpdb->query("ALTER TABLE {$table} ADD COLUMN hr_display_name VARCHAR(191) DEFAULT NULL AFTER user_id");
		}
	}

	private function sn_hr_user_rows_by_profile_ids(array $profile_ids, string $position_filter = ''): array
	{
		global $wpdb;
		$profile_ids = array_values(array_unique(array_filter(array_map('intval', $profile_ids))));
		if (! $profile_ids) {
			return [];
		}
		$key = md5(implode(',', $profile_ids) . '|' . sanitize_key($position_filter));
		if (isset($this->sn_distribution_user_rows_cache[$key])) {
			return (array) $this->sn_distribution_user_rows_cache[$key];
		}
		$placeholders = implode(',', array_fill(0, count($profile_ids), '%d'));
		$args = $profile_ids;
		$where = "p.id IN ({$placeholders})";
		if ($position_filter !== '') {
			$where .= ' AND pos.slug=%s';
			$args[] = sanitize_key($position_filter);
		}
		$this->sn_distribution_user_rows_cache[$key] = $wpdb->get_results($wpdb->prepare(
			"SELECT p.id profile_id, p.user_id, p.is_active, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE {$where}
			ORDER BY pos.sort_order ASC, u.display_name ASC, p.user_id ASC",
			...$args
		), ARRAY_A) ?: [];
		return (array) $this->sn_distribution_user_rows_cache[$key];
	}

	private function sn_hr_profile_ids_for_user(int $user_id): array
	{
		global $wpdb;
		$user_id = absint($user_id);
		if ($user_id < 1) {
			return [];
		}
		if (isset($this->sn_distribution_profile_ids_cache[$user_id])) {
			return (array) $this->sn_distribution_profile_ids_cache[$user_id];
		}
		$this->sn_distribution_profile_ids_cache[$user_id] = array_values(array_unique(array_map('intval', $wpdb->get_col($wpdb->prepare(
			"SELECT id FROM {$wpdb->prefix}sn_hr_profiles WHERE user_id=%d ORDER BY is_active DESC, id DESC",
			$user_id
		)) ?: [])));
		return (array) $this->sn_distribution_profile_ids_cache[$user_id];
	}

	private function sn_hr_direct_child_profile_ids_for_parent_profile_ids(array $parent_profile_ids): array
	{
		global $wpdb;
		$parent_profile_ids = array_values(array_unique(array_filter(array_map('intval', $parent_profile_ids))));
		if (! $parent_profile_ids) {
			return [];
		}
		$key = implode(',', $parent_profile_ids);
		if (isset($this->sn_distribution_direct_child_profile_ids_cache[$key])) {
			return (array) $this->sn_distribution_direct_child_profile_ids_cache[$key];
		}
		$placeholders = implode(',', array_fill(0, count($parent_profile_ids), '%d'));
		$this->sn_distribution_direct_child_profile_ids_cache[$key] = array_values(array_unique(array_map('intval', $wpdb->get_col($wpdb->prepare(
			"SELECT child_profile_id FROM {$wpdb->prefix}sn_hr_assignments WHERE parent_profile_id IN ({$placeholders}) AND is_current=1 AND (relationship_type='reports_to' OR relationship_type='' OR relationship_type IS NULL) ORDER BY id ASC",
			...$parent_profile_ids
		)) ?: [])));
		return (array) $this->sn_distribution_direct_child_profile_ids_cache[$key];
	}

	private function sn_hr_descendant_profile_ids_for_user(int $manager_user_id, int $max_depth = 20): array
	{
		global $wpdb;
		$manager_user_id = absint($manager_user_id);
		$max_depth = max(1, absint($max_depth));
		$key = $manager_user_id . ':' . $max_depth;
		if (isset($this->sn_distribution_descendant_ids_cache[$key])) {
			return (array) $this->sn_distribution_descendant_ids_cache[$key];
		}
		$frontier = $this->sn_hr_profile_ids_for_user($manager_user_id);
		if (! $frontier || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_assignments')) {
			$this->sn_distribution_descendant_ids_cache[$key] = [];
			return [];
		}
		// Build the graph once per request. Distribution screens can call this hundreds of times.
		static $children_by_parent_cache = null;
		if ($children_by_parent_cache === null) {
			$edges = $wpdb->get_results("SELECT parent_profile_id, child_profile_id FROM {$wpdb->prefix}sn_hr_assignments WHERE is_current=1 AND (relationship_type='reports_to' OR relationship_type='' OR relationship_type IS NULL) ORDER BY id ASC", ARRAY_A) ?: [];
			$children_by_parent_cache = [];
			foreach ($edges as $edge) {
				$parent_id = (int) ($edge['parent_profile_id'] ?? 0);
				$child_id = (int) ($edge['child_profile_id'] ?? 0);
				if ($parent_id < 1 || $child_id < 1) { continue; }
				$children_by_parent_cache[$parent_id][] = $child_id;
			}
		}
		$seen = [];
		$frontier = array_values(array_unique(array_filter(array_map('intval', $frontier))));
		for ($depth = 0; $depth < $max_depth; $depth++) {
			$next = [];
			foreach ($frontier as $profile_id) {
				foreach (($children_by_parent_cache[$profile_id] ?? []) as $child_profile_id) {
					if (isset($seen[$child_profile_id])) { continue; }
					$seen[$child_profile_id] = true;
					$next[] = $child_profile_id;
				}
			}
			if (! $next) { break; }
			$frontier = array_values(array_unique($next));
		}
		$this->sn_distribution_descendant_ids_cache[$key] = array_values(array_map('intval', array_keys($seen)));
		return (array) $this->sn_distribution_descendant_ids_cache[$key];
	}

	private function sn_get_direct_children(int $manager_user_id, string $position_filter = ''): array
	{
		if ($manager_user_id <= 0) {
			return [];
		}
		$key = absint($manager_user_id) . ':' . sanitize_key($position_filter);
		if (isset($this->sn_distribution_direct_children_cache[$key])) {
			return (array) $this->sn_distribution_direct_children_cache[$key];
		}
		$parent_profile_ids = $this->sn_hr_profile_ids_for_user($manager_user_id);
		$child_profile_ids = $this->sn_hr_direct_child_profile_ids_for_parent_profile_ids($parent_profile_ids);
		$this->sn_distribution_direct_children_cache[$key] = $this->sn_hr_user_rows_by_profile_ids($child_profile_ids, $position_filter);
		return (array) $this->sn_distribution_direct_children_cache[$key];
	}

	private function sn_hr_assignment_rows_for_profile_ids(array $profile_ids): array
	{
		global $wpdb;
		$profile_ids = array_values(array_unique(array_filter(array_map('intval', $profile_ids))));
		if (! $profile_ids) {
			return [];
		}
		$placeholders = implode(',', array_fill(0, count($profile_ids), '%d'));
		return $wpdb->get_results($wpdb->prepare(
			"SELECT a.id assignment_id, a.child_profile_id, a.parent_profile_id, a.relationship_type, a.is_current,
				child.user_id child_user_id, child_pos.slug child_position,
				parent.user_id parent_user_id, parent_pos.slug parent_position
			FROM {$wpdb->prefix}sn_hr_assignments a
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles child ON child.id=a.child_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions child_pos ON child_pos.id=child.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions parent_pos ON parent_pos.id=parent.position_id
			WHERE a.is_current=1 AND a.relationship_type='reports_to'
				AND (a.child_profile_id IN ({$placeholders}) OR a.parent_profile_id IN ({$placeholders}))
			ORDER BY a.parent_profile_id ASC, a.child_profile_id ASC
			LIMIT 300",
			...array_merge($profile_ids, $profile_ids)
		), ARRAY_A) ?: [];
	}

	private function sn_get_descendant_users(int $manager_user_id, string $position_filter = ''): array
	{
		if ($manager_user_id <= 0) {
			return [];
		}
		$key = absint($manager_user_id) . ':' . sanitize_key($position_filter);
		if (isset($this->sn_distribution_descendant_users_cache[$key])) {
			return (array) $this->sn_distribution_descendant_users_cache[$key];
		}
		$descendant_profile_ids = $this->sn_hr_descendant_profile_ids_for_user($manager_user_id, 20);
		$this->sn_distribution_descendant_users_cache[$key] = $this->sn_hr_user_rows_by_profile_ids($descendant_profile_ids, $position_filter);
		return (array) $this->sn_distribution_descendant_users_cache[$key];
	}

	private function sn_sales_manager_panel_hr_diagnostics(int $manager_user_id): array
	{
		$profile_ids = $this->sn_hr_profile_ids_for_user($manager_user_id);
		$direct_supervisor_rows = $this->sn_get_direct_children($manager_user_id, 'supervisor');
		$direct_senior_rows = $this->sn_get_direct_children($manager_user_id, 'senior_supervisor');
		$direct_seller_rows = $this->sn_get_direct_children($manager_user_id, 'seller');
		$descendant_seller_rows = $this->sn_get_descendant_users($manager_user_id, 'seller');
		$direct_child_profile_ids = $this->sn_hr_direct_child_profile_ids_for_parent_profile_ids($profile_ids);
		return [
			'user_id' => $manager_user_id,
			'user_label' => $this->sn_user_label($manager_user_id),
			'hr_position' => $this->sn_hr_position_for_user($manager_user_id),
			'profile_ids' => $profile_ids,
			'direct_child_profile_ids' => $direct_child_profile_ids,
			'direct_senior_count' => count($direct_senior_rows),
			'direct_supervisor_count' => count($direct_supervisor_rows),
			'direct_seller_count' => count($direct_seller_rows),
			'descendant_seller_count' => count($descendant_seller_rows),
			'direct_supervisors' => array_values(array_map(fn($row) => $this->sn_user_label((int) ($row['user_id'] ?? 0)), $direct_supervisor_rows)),
			'descendant_sellers_sample' => array_values(array_slice(array_map(fn($row) => $this->sn_user_label((int) ($row['user_id'] ?? 0)), $descendant_seller_rows), 0, 20)),
		];
	}

	private function sn_hr_all_users_by_position(string $position_slug): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare(
			"SELECT p.id profile_id, p.user_id, p.is_active, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE pos.slug=%s
			ORDER BY u.display_name ASC, p.user_id ASC",
			sanitize_key($position_slug)
		), ARRAY_A) ?: [];
	}

	private function sn_get_seller_ids_in_hr_scope(int $actor_user_id): array
	{
		$actor_user_id = absint($actor_user_id);
		if ($actor_user_id <= 0) {
			return [];
		}
		if (current_user_can('manage_options') || is_super_admin($actor_user_id)) {
			$ids = array_map('intval', array_column($this->sn_hr_all_users_by_position('seller'), 'user_id'));
			$legacy = array_map('intval', get_users(['role' => 'sn_seller', 'fields' => 'ID', 'number' => 2000]));
			return array_values(array_unique(array_filter(array_merge($ids, $legacy))));
		}
		$position = $this->sn_hr_position_for_user($actor_user_id);
		if ($position === 'seller') {
			return [$actor_user_id];
		}
		$descendant = array_map('intval', array_column($this->sn_get_descendant_users($actor_user_id, 'seller'), 'user_id'));
		$direct = array_map('intval', array_column($this->sn_get_direct_children($actor_user_id, 'seller'), 'user_id'));
		return array_values(array_unique(array_filter(array_merge($descendant, $direct))));
	}

	private function sn_get_hierarchy_scope_summary(int $actor_user_id): array
	{
		$direct = $this->sn_get_direct_children($actor_user_id);
		$descendants = $this->sn_get_descendant_users($actor_user_id);
		$by_direct_position = [];
		$by_descendant_position = [];
		foreach ($direct as $row) {
			$key = (string) ($row['position_slug'] ?? 'unknown');
			$by_direct_position[$key] = ($by_direct_position[$key] ?? 0) + 1;
		}
		foreach ($descendants as $row) {
			$key = (string) ($row['position_slug'] ?? 'unknown');
			$by_descendant_position[$key] = ($by_descendant_position[$key] ?? 0) + 1;
		}
		$seller_ids = array_values(array_unique(array_map('intval', array_column(array_filter($descendants, static fn($row) => ($row['position_slug'] ?? '') === 'seller'), 'user_id'))));
		return [
			'actor_user_id' => $actor_user_id,
			'actor_position' => $this->sn_hr_position_for_user($actor_user_id),
			'direct_children_count' => count($direct),
			'descendant_user_count' => count($descendants),
			'descendant_seller_count' => count($seller_ids),
			'descendant_seller_ids' => $seller_ids,
			'direct_by_position' => $by_direct_position,
			'descendant_by_position' => $by_descendant_position,
		];
	}

	private function sn_can_manage_hr_panel(): bool
	{
		if (current_user_can('manage_options')) {
			return true;
		}
		if (! is_user_logged_in()) {
			return false;
		}
		$user_id = get_current_user_id();
		$user = wp_get_current_user();
		$roles = array_map('sanitize_key', (array) ($user->roles ?? []));
		if (in_array('sn_hr', $roles, true)) {
			return true;
		}
		// Fast direct HR check for admin-post/admin-ajax handlers.  Relying only on
		// SN_Scope_Service made manual HR actions fail in some role-based panel loads.
		if ($this->sn_hr_position_for_user($user_id) === 'hr') {
			return true;
		}
		return class_exists('SN_Scope_Service') && (new SN_Scope_Service())->get_viewer_position_slug($user_id) === 'hr';
	}

	private function sn_hr_legacy_role_for_position(string $position_slug): string
	{
		$position_slug = sanitize_key($position_slug);
		$map = [
			'seller' => 'sn_seller',
			'supervisor' => 'sn_supervisor',
			'converter' => 'sn_converter',
			'senior_supervisor' => 'sn_senior_supervisor',
			'sales_manager' => 'sn_sales_manager',
			'sales_deputy' => 'sn_sales_deputy',
			'hr' => 'sn_hr',
			'finance' => 'sn_financial',
			'invoice_reviewer' => 'sn_invoice_reviewer',
			'after_sales' => 'sn_after_sales',
			'mis' => 'sn_mis',
			'shipping_expert' => 'sn_shipping_expert',
			'operations_sales_manager' => 'sn_operations_sales_manager',
			'operations_sales_supervisor' => 'sn_operations_sales_supervisor',
			'operations_sales_expert' => 'sn_operations_sales_expert',
			'operations_executive_manager' => 'sn_operations_executive_manager',
			'operations_execution_expert' => 'sn_operations_execution_expert',
		];
		return $map[$position_slug] ?? $position_slug;
	}

	private function sn_hr_apply_user_access_for_position(int $user_id, string $position_slug): void
	{
		$user = get_user_by('id', $user_id);
		if (! $user instanceof WP_User) {
			return;
		}
		$role = $this->sn_hr_legacy_role_for_position($position_slug);
		if ($role === '') {
			return;
		}
		$role_caps = ['read' => true];
		if ($role === 'sn_invoice_reviewer') { $role_caps['sn_review_invoices'] = true; }
		if ($role === 'sn_converter') { $role_caps['sn_manage_dot_conversion'] = true; }
		if ($role === 'sn_after_sales') { $role_caps['sn_view_customer_profiles'] = true; }
		if ($role === 'sn_sales_manager') {
			$role_caps['sn_view_sales_reports'] = true;
			$role_caps['sn_manage_supervisor_leads'] = true;
			$role_caps['sn_export_sales_reports'] = true;
		}
		if ($role === 'sn_shipping_expert') { $role_caps['sn_manage_shipping'] = true; }
		if ($role === 'sn_operations_sales_manager') { $role_caps['sn_manage_operations_sales'] = true; }
		if ($role === 'sn_operations_sales_supervisor') { $role_caps['sn_supervise_operations_sales'] = true; }
		if ($role === 'sn_operations_sales_expert') { $role_caps['sn_work_operations_sales'] = true; }
		if ($role === 'sn_operations_executive_manager') { $role_caps['sn_manage_operations_execution'] = true; }
		if ($role === 'sn_operations_execution_expert') { $role_caps['sn_work_operations_execution'] = true; }
		if (! get_role($role)) {
			add_role($role, $this->sn_hr_persian_label($position_slug) ?: $role, $role_caps);
		}
		if (! get_role($role)) {
			return;
		}
		// HR positions are mutually exclusive inside this plugin. Remove only the
		// plugin-managed operational roles so an old position cannot keep exposing
		// a previous panel after an HR transfer. Unrelated WordPress roles/caps and
		// all historical HR records remain untouched.
		$previous_roles = (array) $user->roles;
		$managed_roles = [
			'sn_seller', 'sn_supervisor', 'sn_senior_supervisor', 'sn_sales_manager',
			'sn_sales_deputy', 'sn_converter', 'sn_financial', 'sn_financial_approval',
			'sn_finance', 'sn_invoice_reviewer', 'sn_hr', 'sn_mis', 'sn_after_sales', 'sn_shipping_expert', 'sn_operations_sales_manager',
			'sn_operations_sales_supervisor', 'sn_operations_sales_expert', 'sn_operations_executive_manager',
			'sn_operations_execution_expert',
		];
		foreach ($managed_roles as $managed_role) {
			if ($managed_role !== $role && in_array($managed_role, (array) $user->roles, true)) {
				$user->remove_role($managed_role);
			}
		}
		if (! in_array($role, (array) $user->roles, true)) {
			$user->add_role($role);
		}
		$finance_caps = ['sn_view_finance', 'sn_approve_payment', 'sn_reject_payment'];
		$is_finance_position = $position_slug === 'finance';
		$was_finance_role = (bool) array_intersect($previous_roles, ['sn_financial', 'sn_financial_approval', 'sn_finance']);
		if ($is_finance_position) {
			foreach ($finance_caps as $finance_cap) { $user->add_cap($finance_cap); }
		} elseif ($was_finance_role) {
			foreach ($finance_caps as $finance_cap) { $user->remove_cap($finance_cap); }
		}
		update_user_meta($user_id, 'sn_hr_position', sanitize_key($position_slug));
		update_user_meta($user_id, 'sn_position', sanitize_key($position_slug));
		clean_user_cache($user_id);
		unset($this->sn_hr_position_for_user_cache[$user_id], $this->sn_hr_position_for_user_cache['fast:' . $user_id]);
	}

	private function sn_login_credential_phone_for_user(int $user_id): string
	{
		global $wpdb;
		$candidates = [
			(string) get_user_meta($user_id, 'billing_phone', true),
			(string) get_user_meta($user_id, 'digits_phone', true),
			(string) get_user_meta($user_id, 'digits_phone_no', true),
			(string) get_user_meta($user_id, 'mobile', true),
			(string) get_user_meta($user_id, 'phone', true),
			(string) get_user_meta($user_id, 'sn_phone', true),
		];
		$profile = $wpdb->get_row($wpdb->prepare("SELECT work_phone, emergency_phone FROM {$wpdb->prefix}sn_hr_profiles WHERE user_id=%d LIMIT 1", $user_id), ARRAY_A);
		if ($profile) {
			$candidates[] = (string) ($profile['work_phone'] ?? '');
			$candidates[] = (string) ($profile['emergency_phone'] ?? '');
		}
		$user = get_user_by('id', $user_id);
		if ($user instanceof WP_User) {
			$candidates[] = (string) $user->user_login;
		}
		foreach ($candidates as $candidate) {
			$phone = SN_Helpers::normalize_mobile($candidate);
			if (SN_Helpers::is_valid_mobile($phone)) {
				return $phone;
			}
		}
		return '';
	}

	private function sn_login_credentials_sms_audit(int $limit = 30): array
	{
		$rows = get_option('sn_login_credentials_sms_audit', []);
		return array_slice(is_array($rows) ? $rows : [], 0, max(1, $limit));
	}

	private function sn_store_login_credentials_sms_report(array $report): void
	{
		update_option('sn_login_credentials_sms_report', $report, false);
		$audit = $this->sn_login_credentials_sms_audit(100);
		array_unshift($audit, [
			'time' => current_time('mysql'),
			'actor_user_id' => get_current_user_id(),
			'sent' => (int) ($report['sent'] ?? 0),
			'failed' => (int) ($report['failed'] ?? 0),
			'skipped' => (int) ($report['skipped'] ?? 0),
			'users' => array_map(static function ($row) {
				return [
					'user_id' => (int) ($row['user_id'] ?? 0),
					'phone_masked' => (string) ($row['phone_masked'] ?? ''),
					'status' => (string) ($row['status'] ?? ''),
					'message' => (string) ($row['message'] ?? ''),
				];
			}, array_slice((array) ($report['rows'] ?? []), 0, 50)),
		]);
		update_option('sn_login_credentials_sms_audit', array_slice($audit, 0, 100), false);
	}

