	private function sn_hr_panel_log_profile(int $profile_id, int $user_id, string $action, $old_value, $new_value, array $context = []): void
	{
		global $wpdb;
		$wpdb->insert($wpdb->prefix . 'sn_hr_profile_logs', [
			'profile_id' => $profile_id ?: null,
			'user_id' => $user_id ?: null,
			'actor_user_id' => get_current_user_id() ?: null,
			'action' => sanitize_key($action),
			'old_value' => $old_value === null ? null : wp_json_encode($old_value, JSON_UNESCAPED_UNICODE),
			'new_value' => $new_value === null ? null : wp_json_encode($new_value, JSON_UNESCAPED_UNICODE),
			'context' => $context ? wp_json_encode($context, JSON_UNESCAPED_UNICODE) : null,
			'created_at' => current_time('mysql'),
		]);
	}

	private function sn_hr_structure_table(string $type): string
	{
		global $wpdb;
		$map = [
			'departments' => $wpdb->prefix . 'sn_hr_departments',
			'units' => $wpdb->prefix . 'sn_hr_units',
			'teams' => $wpdb->prefix . 'sn_hr_teams',
		];
		return $map[$type] ?? '';
	}

	private function sn_hr_structure_rows(string $type): array
	{
		global $wpdb;
		$table = $this->sn_hr_structure_table($type);
		if ($table === '' || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
			return [];
		}
		$order = 'sort_order ASC, id ASC';
		return $wpdb->get_results("SELECT * FROM {$table} ORDER BY {$order}") ?: [];
	}

