	private function sn_hr_render_structure_section(string $type, string $title, array $rows, array $parents): void
	{
		$parent_field = $type === 'units' ? 'department_id' : ($type === 'teams' ? 'unit_id' : '');
		echo '<div class="sn-hr-subsection"><h4>' . esc_html($title) . '</h4><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>شناسه</th><th>والد</th><th>کد سیستمی</th><th>عنوان</th><th>توضیح</th><th>فعال</th><th>ترتیب</th><th>عملیات</th></tr></thead><tbody>';
		foreach ($rows as $row) {
			echo '<tr><form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><td>' . esc_html((string) (int) $row->id) . '<input type="hidden" name="structure_id" value="' . esc_attr((string) (int) $row->id) . '"></td><td>';
			$this->sn_hr_render_parent_select($parent_field, $parents, (int) ($parent_field ? ($row->{$parent_field} ?? 0) : 0));
			echo '</td><td><span class="sn-hr-badge">' . esc_html((string) $row->slug) . '</span></td><td><input type="text" name="label" value="' . esc_attr((string) $row->label) . '"></td><td><input type="text" name="description" value="' . esc_attr((string) ($row->description ?? '')) . '"></td><td><label class="sn-hr-check"><input type="checkbox" name="is_active" value="1" ' . checked((int) $row->is_active, 1, false) . '> فعال</label></td><td><input type="number" name="sort_order" value="' . esc_attr((string) (int) $row->sort_order) . '"></td><td><input type="hidden" name="action" value="sn_hr_save_structure"><input type="hidden" name="structure_type" value="' . esc_attr($type) . '">';
			wp_nonce_field('sn_hr_save_structure');
			echo '<button class="sn-btn">ذخیره</button></td></form></tr>';
		}
		echo '<tr><form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><td>جدید</td><td>';
		$this->sn_hr_render_parent_select($parent_field, $parents, 0);
		echo '</td><td><input type="text" name="slug" placeholder="کد سیستمی"></td><td><input type="text" name="label" placeholder="عنوان"></td><td><input type="text" name="description" placeholder="توضیح"></td><td><label class="sn-hr-check"><input type="checkbox" name="is_active" value="1" checked> فعال</label></td><td><input type="number" name="sort_order" value="0"></td><td><input type="hidden" name="action" value="sn_hr_save_structure"><input type="hidden" name="structure_type" value="' . esc_attr($type) . '">';
		wp_nonce_field('sn_hr_save_structure');
		echo '<button class="sn-btn">افزودن</button></td></form></tr></tbody></table></div></div>';
	}

	private function sn_hr_render_parent_select(string $field, array $parents, int $selected): void
	{
		if ($field === '') {
			echo '—';
			return;
		}
		echo '<select name="' . esc_attr($field) . '"><option value="0">—</option>';
		foreach ($parents as $parent) {
			echo '<option value="' . esc_attr((string) (int) $parent->id) . '" ' . selected($selected, (int) $parent->id, false) . '>' . esc_html((string) $parent->label . ' (' . (string) $parent->slug . ')') . '</option>';
		}
		echo '</select>';
	}

	private function sn_hr_mask_salary($row): string
	{
		if (! current_user_can('manage_options') && ! $this->sn_can_manage_hr_panel()) {
			return '***';
		}
		$amount = isset($row->base_salary) ? (int) $row->base_salary : 0;
		return $amount > 0 ? number_format_i18n($amount) . ' ' . esc_html((string) ($row->salary_currency ?? 'IRT')) : '—';
	}

	private function sn_hr_safe_log_value($value): string
	{
		if ($value === null || $value === '') {
			return '—';
		}
		$decoded = json_decode((string) $value, true);
		if (json_last_error() === JSON_ERROR_NONE) {
			return $this->sn_after_sales_format_safe_log_data($this->sn_hr_sanitize_log_data($decoded));
		}
		return $this->sn_after_sales_mask_sensitive_text((string) $value);
	}

	private function sn_hr_format_log_value($value): string
	{
		if ($value === null || $value === '') {
			return '—';
		}
		$decoded = json_decode((string) $value, true);
		if (json_last_error() !== JSON_ERROR_NONE || ! is_array($decoded)) {
			return $this->sn_after_sales_mask_sensitive_text((string) $value);
		}
		$safe = $this->sn_hr_sanitize_log_data($decoded);
		$lines = [];
		foreach ($safe as $key => $item) {
			$label = $this->sn_hr_persian_label((string) $key);
			if (is_array($item)) {
				$item = wp_json_encode($item, JSON_UNESCAPED_UNICODE);
			}
			$lines[] = $label . ': ' . (string) $item;
		}
		return $lines ? implode("\n", $lines) : '—';
	}

	private function sn_hr_sanitize_log_data($data)
	{
		if (is_array($data)) {
			$out = [];
			foreach ($data as $key => $value) {
				$key_string = is_string($key) ? $key : (string) $key;
				$key_lc = strtolower($key_string);
				if (strpos($key_lc, 'token') !== false || strpos($key_lc, 'password') !== false || strpos($key_lc, 'url') !== false || strpos($key_lc, 'hash') !== false) {
					$out[$key_string] = '[hidden]';
				} elseif (strpos($key_lc, 'phone') !== false || strpos($key_lc, 'mobile') !== false || strpos($key_lc, 'national_id') !== false) {
					$out[$key_string] = $this->sn_mask_phone((string) $value);
				} else {
					$out[$key_string] = $this->sn_hr_sanitize_log_data($value);
				}
			}
			return $out;
		}
		return is_scalar($data) ? $this->sn_after_sales_mask_sensitive_text((string) $data) : '';
	}

	private function sn_hr_panel_profile_selector_rows(int $limit = 500): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare(
			"SELECT p.user_id, p.employee_code, p.is_active, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, u.user_email, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			ORDER BY u.display_name ASC, p.user_id ASC
			LIMIT %d",
			max(1, min(1000, $limit))
		)) ?: [];
	}

	private function sn_hr_panel_manager_selector_rows(int $exclude_user_id = 0, int $limit = 500): array
	{
		global $wpdb;
		$args = [];
		// Include the Operations sales chain in the generic HR manager picker.
		// These positions are created by the Operations module, but this selector
		// is rendered by the core HR panel and previously omitted them entirely.
		$manager_positions = ['sales_deputy','sales_manager','senior_supervisor','supervisor','operations_sales_manager','operations_sales_supervisor','operations_sales_expert','operations_executive_manager','hr','finance','mis','after_sales'];
		$position_placeholders = implode(',', array_fill(0, count($manager_positions), '%s'));
		$where = ['COALESCE(p.is_active,1)=1', "pos.slug IN ({$position_placeholders})"];
		array_push($args, ...$manager_positions);
		if ($exclude_user_id) {
			$where[] = 'p.user_id<>%d';
			$args[] = $exclude_user_id;
		}
		$args[] = max(1, min(1000, $limit));
		$sql = "SELECT p.user_id, p.employee_code, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, u.user_email, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE " . implode(' AND ', $where) . "
			ORDER BY FIELD(pos.slug,'sales_deputy','sales_manager','senior_supervisor','supervisor','operations_sales_manager','operations_sales_supervisor','operations_sales_expert','operations_executive_manager','hr','finance','mis','after_sales','seller'), u.display_name ASC, p.user_id ASC
			LIMIT %d";
		return $wpdb->get_results($wpdb->prepare($sql, ...$args)) ?: [];
	}

	private function sn_hr_panel_user_option_label($row): string
	{
		$parts = [
			trim((string) ($row->display_name ?? '')) ?: (string) ($row->user_login ?? ''),
			'@' . (string) ($row->user_login ?? ''),
			'#' . (int) ($row->user_id ?? 0),
		];
		if (! empty($row->position_label) || ! empty($row->position_slug)) {
			$parts[] = trim((string) ($row->position_label ?? '') . ' / ' . (string) ($row->position_slug ?? ''), ' /');
		}
		if (! empty($row->employee_code)) {
			$parts[] = 'کد: ' . (string) $row->employee_code;
		}
		return implode(' - ', array_filter($parts));
	}

	private function sn_hr_allowed_parent_positions(string $child_position_slug): array
	{
		$map = [
			'seller' => ['supervisor', 'senior_supervisor', 'sales_manager'],
			'converter' => ['supervisor'],
			'supervisor' => ['senior_supervisor', 'sales_manager'],
			'senior_supervisor' => ['sales_manager', 'sales_deputy'],
			'sales_manager' => ['sales_deputy'],
			'operations_sales_supervisor' => ['operations_sales_manager'],
			'operations_sales_expert' => ['operations_sales_supervisor'],
			'operations_execution_expert' => ['operations_executive_manager'],
		];
		return $map[$child_position_slug] ?? [];
	}

	private function sn_hr_manager_candidates_for_position(string $child_position_slug, int $exclude_user_id = 0): array
	{
		global $wpdb;
		$allowed = $this->sn_hr_allowed_parent_positions($child_position_slug);
		if (! $allowed) {
			return [];
		}
		$cache_key = sanitize_key($child_position_slug);
		if (isset($this->sn_hr_manager_candidates_cache[$cache_key])) {
			$rows = $this->sn_hr_manager_candidates_cache[$cache_key];
			return $exclude_user_id > 0
				? array_values(array_filter($rows, static fn($row) => (int) ($row->user_id ?? 0) !== $exclude_user_id))
				: $rows;
		}
		$args = $allowed;
		$where = ['COALESCE(p.is_active,1)=1', "pos.slug IN (" . implode(',', array_fill(0, count($allowed), '%s')) . ")"];
		$rows = $wpdb->get_results($wpdb->prepare(
			"SELECT p.id profile_id, p.user_id, p.employee_code, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, u.user_email, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE " . implode(' AND ', $where) . "
			ORDER BY FIELD(pos.slug,'sales_deputy','sales_manager','senior_supervisor','supervisor','operations_sales_manager','operations_sales_supervisor','operations_sales_expert'), u.display_name ASC, p.user_id ASC
			LIMIT 500",
			...$args
		)) ?: [];
		$this->sn_hr_manager_candidates_cache[$cache_key] = $rows;
		return $exclude_user_id > 0
			? array_values(array_filter($rows, static fn($row) => (int) ($row->user_id ?? 0) !== $exclude_user_id))
			: $rows;
	}

	private function sn_hr_manager_allowed_for_child(string $child_position_slug, string $manager_position_slug): bool
	{
		return $manager_position_slug !== '' && in_array($manager_position_slug, $this->sn_hr_allowed_parent_positions($child_position_slug), true);
	}

	private function sn_hr_workforce_audit_cards(): array
	{
		global $wpdb;
		$p = $wpdb->prefix . 'sn_hr_profiles';
		$a = $wpdb->prefix . 'sn_hr_assignments';
		$pos = $wpdb->prefix . 'sn_hr_positions';
		$hist = $wpdb->prefix . 'sn_hr_compensation_history';
		$has_hist = $this->sn_table_exists_quiet($hist);
		$count_for = static function($sql, ...$args) use ($wpdb): int {
			return (int) ($args ? $wpdb->get_var($wpdb->prepare($sql, ...$args)) : $wpdb->get_var($sql));
		};
		$seller_join = "FROM {$p} child INNER JOIN {$pos} cpos ON cpos.id=child.position_id LEFT JOIN {$a} rel ON rel.child_profile_id=child.id AND rel.is_current=1 AND rel.relationship_type='reports_to' LEFT JOIN {$p} parent ON parent.id=rel.parent_profile_id LEFT JOIN {$pos} ppos ON ppos.id=parent.position_id";
		$overlap = 0;
		if ($has_hist) {
			$overlap = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$hist} h1 INNER JOIN {$hist} h2 ON h1.user_id=h2.user_id AND h1.id<h2.id AND h1.is_active=1 AND h2.is_active=1 AND h1.effective_from <= COALESCE(h2.effective_to,'9999-12-31') AND h2.effective_from <= COALESCE(h1.effective_to,'9999-12-31')");
		}
		return [
			['label' => 'فروشنده‌های بدون مدیر', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='seller' AND rel.id IS NULL"), 'filter' => ['sn_hr_position' => 'seller', 'sn_hr_assignment' => 'none']],
			['label' => 'فروشنده‌های زیر سرپرست ارشد', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='seller' AND ppos.slug='senior_supervisor'"), 'filter' => ['sn_hr_position' => 'seller']],
			['label' => 'فروشنده‌های زیر سرپرست', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='seller' AND ppos.slug='supervisor'"), 'filter' => ['sn_hr_position' => 'seller']],
			['label' => 'فروشنده‌های مستقیم زیر مدیر فروش', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='seller' AND ppos.slug='sales_manager'"), 'filter' => ['sn_hr_position' => 'seller']],
			['label' => 'سرپرست ارشد بدون مدیر فروش', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='senior_supervisor' AND (rel.id IS NULL OR ppos.slug<>'sales_manager')"), 'filter' => ['sn_hr_position' => 'senior_supervisor']],
			['label' => 'مدیر فروش بدون معاون فروش', 'count' => $count_for("SELECT COUNT(*) {$seller_join} WHERE cpos.slug='sales_manager' AND (rel.id IS NULL OR ppos.slug<>'sales_deputy')"), 'filter' => ['sn_hr_position' => 'sales_manager']],
			['label' => 'نیروهای بدون سطح', 'count' => $count_for("SELECT COUNT(*) FROM {$p} WHERE level_id IS NULL OR level_id=0"), 'filter' => ['sn_hr_level' => '']],
			['label' => 'نیروهای بدون تاریخچه حقوق و پورسانت', 'count' => $has_hist ? $count_for("SELECT COUNT(*) FROM {$p} prof LEFT JOIN {$hist} h ON h.profile_id=prof.id AND h.is_active=1 WHERE h.id IS NULL") : 0, 'filter' => ['sn_hr_missing_comp_history' => '1']],
			['label' => 'نیروهای دارای بازه حقوقی هم‌پوشان', 'count' => $overlap, 'filter' => []],
		];
	}

	private function sn_hr_workforce_rows(array $filters, int $limit = 148, int $offset = 0): array
	{
		$cache_key = md5(wp_json_encode([$filters, max(1, min(500, $limit)), max(0, $offset)]));
		if (isset($this->sn_hr_workforce_rows_cache[$cache_key])) {
			$this->sn_hr_workforce_page_report = $this->sn_hr_workforce_reports_cache[$cache_key] ?? [];
			return $this->sn_hr_workforce_rows_cache[$cache_key];
		}
		global $wpdb;
		$where = ['1=1'];
		$args = [];
		$total_profiles = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_profiles");
		$comp_table = $wpdb->prefix . 'sn_hr_compensation_profiles';
		$rules_table = $wpdb->prefix . 'sn_commission_rules';
		$hist_table = $wpdb->prefix . 'sn_hr_compensation_history';
		$has_comp = $this->sn_table_exists_quiet($comp_table);
		$has_rules = $this->sn_table_exists_quiet($rules_table);
		$has_hist = $this->sn_table_exists_quiet($hist_table);
		$comp_select = $has_comp ? 'cp.base_salary comp_base_salary, cp.salary_currency comp_salary_currency, cp.commission_enabled, cp.default_commission_rule_id, cp.commission_override_mode, cp.effective_from comp_effective_from' : "NULL comp_base_salary, NULL comp_salary_currency, 1 commission_enabled, 0 default_commission_rule_id, 'inherit' commission_override_mode, NULL comp_effective_from";
		$rule_select = $has_rules ? 'cr.title rule_title, cr.rule_code' : 'NULL rule_title, NULL rule_code';
		$hist_select = $has_hist ? 'ch.id current_history_id, ch.effective_from history_effective_from' : 'NULL current_history_id, NULL history_effective_from';
		$comp_join = $has_comp ? "LEFT JOIN {$comp_table} cp ON cp.id=(SELECT cp_latest.id FROM {$comp_table} cp_latest WHERE cp_latest.profile_id=p.id AND cp_latest.is_active=1 ORDER BY cp_latest.id DESC LIMIT 1)" : '';
		$rule_join = ($has_comp && $has_rules) ? "LEFT JOIN {$rules_table} cr ON cr.id=cp.default_commission_rule_id" : '';
		$hist_join = $has_hist ? "LEFT JOIN {$hist_table} ch ON ch.id=(SELECT ch_latest.id FROM {$hist_table} ch_latest WHERE ch_latest.profile_id=p.id AND ch_latest.is_active=1 AND ch_latest.effective_from <= CURDATE() AND (ch_latest.effective_to IS NULL OR ch_latest.effective_to >= CURDATE()) ORDER BY ch_latest.effective_from DESC, ch_latest.id DESC LIMIT 1)" : '';
		if ($filters['q'] !== '') {
			if (ctype_digit($filters['q'])) {
				$where[] = '(p.user_id=%d OR u.user_login LIKE %s)';
				$args[] = (int) $filters['q'];
				$args[] = '%' . $wpdb->esc_like($filters['q']) . '%';
			} else {
				$like = '%' . $wpdb->esc_like($filters['q']) . '%';
				$where[] = '(u.user_login LIKE %s OR u.user_email LIKE %s OR u.display_name LIKE %s OR p.hr_display_name LIKE %s OR p.employee_code LIKE %s OR p.work_phone LIKE %s OR p.emergency_phone LIKE %s)';
				array_push($args, $like, $like, $like, $like, $like, $like, $like);
			}
		}
		if ($filters['position'] !== '') { $where[] = 'pos.slug=%s'; $args[] = $filters['position']; }
		if ($filters['level'] !== '') { $where[] = 'lvl.slug=%s'; $args[] = $filters['level']; }
		if (! empty($filters['missing_level'])) { $where[] = '(p.level_id IS NULL OR p.level_id=0)'; }
		if ($filters['active'] !== '') { $where[] = 'p.is_active=%d'; $args[] = (int) $filters['active']; }
		if ($filters['employment_status'] !== '') { $where[] = 'p.employment_status=%s'; $args[] = $filters['employment_status']; }
		if (! empty($filters['manager_user_id'])) { $where[] = 'parent.user_id=%d'; $args[] = (int) $filters['manager_user_id']; }
		if ($filters['assignment'] === 'none' || ! empty($filters['missing_manager'])) { $where[] = 'a.id IS NULL'; }
		if ($filters['assignment'] === 'has') { $where[] = 'a.id IS NOT NULL'; }
		if (! empty($filters['missing_comp_history']) && $has_hist) { $where[] = 'ch.id IS NULL'; }
		foreach (['department_id','unit_id','team_id'] as $field) {
			if (! empty($filters[$field])) { $where[] = "p.{$field}=%d"; $args[] = (int) $filters[$field]; }
		}
		if (! empty($filters['legacy_role'])) { $where[] = 'p.legacy_role=%s'; $args[] = $filters['legacy_role']; }
		if (! empty($filters['user_ids'])) {
			$ids = array_values(array_unique(array_filter(array_map('absint', (array) $filters['user_ids']))));
			$where[] = $ids ? 'p.user_id IN (' . implode(',', $ids) . ')' : '1=0';
		}
		$count_args = $args;
		$args[] = max(1, min(500, $limit));
		$args[] = max(0, $offset);
		$from_sql = "FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=p.level_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.id=(SELECT a_latest.id FROM {$wpdb->prefix}sn_hr_assignments a_latest WHERE a_latest.child_profile_id=p.id AND a_latest.is_current=1 AND a_latest.relationship_type='reports_to' ORDER BY a_latest.id DESC LIMIT 1)
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions parentpos ON parentpos.id=parent.position_id
			{$comp_join}
			{$rule_join}
			{$hist_join}
			WHERE " . implode(' AND ', $where);
		$count_from = str_replace([$comp_join, $rule_join], '', $from_sql);
		if (empty($filters['missing_comp_history'])) { $count_from = str_replace($hist_join, '', $count_from); }
		$count_sql = "SELECT COUNT(*) " . $count_from;
		$filtered_total = count($where) === 1 ? $total_profiles : (int) $wpdb->get_var($count_args ? $wpdb->prepare($count_sql, ...$count_args) : $count_sql);
		$sql = $wpdb->prepare(
			"SELECT p.id, p.user_id, p.position_id, p.level_id, p.employee_code, p.employment_status, p.employment_type, p.base_salary, p.salary_currency, p.work_phone, p.emergency_phone, p.hire_date, p.is_active,
				COALESCE(NULLIF(p.hr_display_name,''), u.display_name) display_name, p.legacy_role, u.user_login, u.user_email,
				pos.slug position_slug, pos.label position_label, lvl.slug level_slug, lvl.label level_label,
				parent.user_id manager_user_id, parentpos.slug manager_position_slug, parentpos.label manager_position_label,
				{$comp_select},
				{$rule_select},
				{$hist_select}
			{$from_sql}
			ORDER BY pos.sort_order ASC, u.display_name ASC, p.user_id ASC
			LIMIT %d OFFSET %d",
			...$args
		);
		$wpdb->last_error = '';
		$rows = $wpdb->get_results($sql) ?: [];
		$report = [
			'complex_count' => count($rows),
			'total_profiles' => $total_profiles,
			'filtered_total' => $filtered_total,
			'offset' => max(0, $offset),
			'last_error' => (string) $wpdb->last_error,
			'filters_active' => $this->sn_hr_workforce_filters_active($filters),
			'used_fallback' => false,
			'first_complex_user_ids' => array_slice(array_map(static fn($row) => (int) ($row->user_id ?? 0), $rows), 0, 10),
			'updated_at' => current_time('mysql'),
		];
		if (! $this->sn_hr_workforce_filters_active($filters) && ($wpdb->last_error !== '' || (empty($rows) && $offset === 0 && $total_profiles > 0))) {
			$fallback = $this->sn_hr_workforce_fallback_rows($filters, $limit, $offset);
			if ($fallback) {
				$rows = $fallback;
				$report['used_fallback'] = true;
				$report['fallback_count'] = count($fallback);
				$report['first_fallback_user_ids'] = array_slice(array_map(static fn($row) => (int) ($row->user_id ?? 0), $fallback), 0, 10);
			}
		}

		$workforce_user_ids = array_values(array_unique(array_filter(array_map(static fn($row) => (int) ($row->user_id ?? 0), $rows))));
		if ($workforce_user_ids) { update_meta_cache('user', $workforce_user_ids); }
			foreach ($rows as $row) {
				$mode = sanitize_key((string) get_user_meta((int) ($row->user_id ?? 0), 'sn_manual_invoice_access', true));
				$row->manual_invoice_access = in_array($mode, ['allow','deny'], true) ? $mode : 'inherit';
				$extra_number_mode = sanitize_key((string) get_user_meta((int) ($row->user_id ?? 0), 'sn_extra_number_request_access', true));
				$row->extra_number_request_access = in_array($extra_number_mode, ['allow','deny'], true) ? $extra_number_mode : 'inherit';
				$row->team_invoice_source_mode = $this->sn_team_invoice_source_mode((int) ($row->user_id ?? 0));
			}
		$this->sn_hr_workforce_page_report = $report;
		$this->sn_hr_workforce_reports_cache[$cache_key] = $report;
		if ($report['last_error'] !== '' || $report['used_fallback']) { update_option('sn_hr_workforce_query_report', $report, false); }
		$this->sn_hr_workforce_rows_cache[$cache_key] = $rows;
		return $rows;
	}

	private function sn_hr_workforce_fallback_rows(array $filters, int $limit = 500, int $offset = 0): array
	{
		global $wpdb;
		$where = ['1=1'];
		$args = [];
		if (! empty($filters['q'])) {
			if (ctype_digit((string) $filters['q'])) {
				$where[] = '(p.user_id=%d OR u.user_login LIKE %s)';
				$args[] = (int) $filters['q'];
				$args[] = '%' . $wpdb->esc_like((string) $filters['q']) . '%';
			} else {
				$like = '%' . $wpdb->esc_like((string) $filters['q']) . '%';
				$where[] = '(u.user_login LIKE %s OR u.user_email LIKE %s OR u.display_name LIKE %s OR p.employee_code LIKE %s OR p.work_phone LIKE %s OR p.emergency_phone LIKE %s)';
				array_push($args, $like, $like, $like, $like, $like, $like);
			}
		}
		if (! empty($filters['position'])) { $where[] = 'pos.slug=%s'; $args[] = (string) $filters['position']; }
		if (! empty($filters['level'])) { $where[] = 'lvl.slug=%s'; $args[] = (string) $filters['level']; }
		if (! empty($filters['missing_level'])) { $where[] = '(p.level_id IS NULL OR p.level_id=0)'; }
		if (isset($filters['active']) && $filters['active'] !== '') { $where[] = 'p.is_active=%d'; $args[] = (int) $filters['active']; }
		if (! empty($filters['employment_status'])) { $where[] = 'p.employment_status=%s'; $args[] = (string) $filters['employment_status']; }
		if (! empty($filters['manager_user_id'])) { $where[] = 'parent.user_id=%d'; $args[] = (int) $filters['manager_user_id']; }
		if (($filters['assignment'] ?? '') === 'none' || ! empty($filters['missing_manager'])) { $where[] = 'a.id IS NULL'; }
		if (($filters['assignment'] ?? '') === 'has') { $where[] = 'a.id IS NOT NULL'; }
		$args[] = max(1, min(500, $limit));
		$args[] = max(0, $offset);
		return $wpdb->get_results($wpdb->prepare(
			"SELECT p.id, p.user_id, p.position_id, p.level_id, p.employee_code, p.employment_status, p.employment_type, p.base_salary, p.salary_currency, p.work_phone, p.emergency_phone, p.hire_date, p.is_active,
				u.display_name, u.user_login, u.user_email,
				pos.slug position_slug, pos.label position_label, lvl.slug level_slug, lvl.label level_label,
				parent.user_id manager_user_id, parentpos.slug manager_position_slug, parentpos.label manager_position_label,
				NULL comp_base_salary, NULL comp_salary_currency, 1 commission_enabled, 0 default_commission_rule_id, 'inherit' commission_override_mode, NULL comp_effective_from,
				NULL rule_title, NULL rule_code, NULL current_history_id, NULL history_effective_from
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=p.level_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.id=(SELECT a_latest.id FROM {$wpdb->prefix}sn_hr_assignments a_latest WHERE a_latest.child_profile_id=p.id AND a_latest.is_current=1 AND a_latest.relationship_type='reports_to' ORDER BY a_latest.id DESC LIMIT 1)
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions parentpos ON parentpos.id=parent.position_id
			WHERE " . implode(' AND ', $where) . "
			ORDER BY p.id DESC
			LIMIT %d OFFSET %d",
			...$args
		)) ?: [];
	}

	private function sn_hr_workforce_filters_active(array $filters): bool
	{
		foreach (['q','position','level','active','employment_status','assignment','legacy_role','missing_manager','missing_level','missing_comp_history'] as $key) {
			if (! empty($filters[$key]) || (isset($filters[$key]) && $filters[$key] === '0')) {
				return true;
			}
		}
		foreach (['department_id','unit_id','team_id','manager_user_id'] as $key) {
			if (! empty($filters[$key])) {
				return true;
			}
		}
		return false;
	}

	private function sn_hr_workforce_visibility_diagnostics(array $filters, int $visible_count): array
	{
		global $wpdb;
		$p = $wpdb->prefix . 'sn_hr_profiles';
		$a = $wpdb->prefix . 'sn_hr_assignments';
		$hist = $wpdb->prefix . 'sn_hr_compensation_history';
		$total = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$p}");
		$without_manager = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$p} prof LEFT JOIN {$a} rel ON rel.child_profile_id=prof.id AND rel.is_current=1 AND rel.relationship_type='reports_to' WHERE rel.id IS NULL");
		$without_level = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$p} WHERE level_id IS NULL OR level_id=0");
		$without_history = $this->sn_table_exists_quiet($hist)
			? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$p} prof LEFT JOIN {$hist} h ON h.profile_id=prof.id AND h.is_active=1 WHERE h.id IS NULL")
			: $total;
		$hidden = max(0, $total - $visible_count);
		return [
			'warning' => ! empty($this->sn_hr_workforce_page_report['last_error']),
			'cards' => [
				['label' => 'کل پروفایل‌های HR', 'count' => $total],
				['label' => 'نمایش داده‌شده در جدول', 'count' => $visible_count],
				['label' => 'در صفحات دیگر یا خارج از فیلتر', 'count' => $hidden],
				['label' => 'بدون مدیر', 'count' => $without_manager],
				['label' => 'بدون سطح', 'count' => $without_level],
				['label' => 'بدون تاریخچه حقوق/پورسانت', 'count' => $without_history],
			],
		];
	}

	private function sn_hr_latest_profile_visibility_rows(array $filters, int $limit = 10): array
	{
		global $wpdb;
		$hist = $wpdb->prefix . 'sn_hr_compensation_history';
		$has_hist = $this->sn_table_exists_quiet($hist);
		$hist_select = $has_hist ? 'h.id history_id' : 'NULL history_id';
		$hist_join = $has_hist ? "LEFT JOIN {$hist} h ON h.profile_id=p.id AND h.is_active=1" : '';
		$visible_ids = [];
		foreach ($this->sn_hr_workforce_rows($filters, 500) as $row) {
			$visible_ids[(int) $row->user_id] = true;
		}
		$rows = $wpdb->get_results($wpdb->prepare(
			"SELECT p.id profile_id, p.user_id, p.level_id, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.label position_label, pos.slug position_slug, rel.id assignment_id, {$hist_select}
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments rel ON rel.child_profile_id=p.id AND rel.is_current=1 AND rel.relationship_type='reports_to'
			{$hist_join}
			ORDER BY p.id DESC LIMIT %d",
			max(1, min(50, $limit))
		)) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$visible = ! empty($visible_ids[(int) $row->user_id]);
			$reasons = [];
			if (! $visible && $this->sn_hr_workforce_filters_active($filters)) { $reasons[] = 'فیلتر فعال است'; }
			if (! $visible && ! $this->sn_hr_workforce_filters_active($filters)) { $reasons[] = 'محدودیت تعداد/خطای اتصال جدول'; }
			$out[] = [
				'user_id' => (int) $row->user_id,
				'name' => trim((string) ($row->display_name ?: $row->user_login)),
				'position' => (string) ($row->position_label ?: $row->position_slug ?: 'بدون سمت'),
				'has_manager' => ! empty($row->assignment_id),
				'has_level' => ! empty($row->level_id),
				'has_compensation_history' => ! empty($row->history_id),
				'visible_in_workforce_table' => $visible,
				'reason' => $visible ? '—' : implode('، ', $reasons),
			];
		}
		return $out;
	}

	private function sn_hr_normalize_lookup_rows(array $rows, string $type = 'lookup'): array
	{
		$normalized = [];
		foreach ($rows as $row) {
			if (is_array($row)) {
				$row = (object) $row;
			}
			if (! is_object($row)) {
				continue;
			}
			$legacy_key = $type === 'position' ? 'position_key' : ($type === 'level' ? 'level_key' : '');
			$slug = (string) ($row->slug ?? '');
			if ($slug === '' && $legacy_key !== '') {
				$slug = (string) ($row->{$legacy_key} ?? '');
			}
			if ($slug === '') {
				$slug = (string) ($row->key ?? $row->code ?? '');
			}
			if ($slug === '' && ! empty($row->id)) {
				$slug = $type . '_' . (int) $row->id;
			}
			$label = (string) ($row->label ?? '');
			if ($label === '') {
				$label = (string) ($row->title ?? $row->name ?? '');
			}
			if ($label === '' && $legacy_key !== '') {
				$label = (string) ($row->{$legacy_key} ?? '');
			}
			if ($label === '') {
				$label = $slug !== '' ? $slug : '—';
			}
			$row->id = (int) ($row->id ?? 0);
			$row->slug = $slug;
			$row->label = $label;
			$row->description = (string) ($row->description ?? '');
			$row->sort_order = (int) ($row->sort_order ?? 0);
			$row->is_active = (int) ($row->is_active ?? 1);
			$row->is_system = (int) ($row->is_system ?? 0);
			if ($type === 'position') {
				$row->panel_key = (string) ($row->panel_key ?? $slug);
			}
			$normalized[] = $row;
		}
		return $normalized;
	}

	private function sn_hr_select_options(array $rows, $selected, string $value_key = 'id', string $label_key = 'label', string $empty_label = 'انتخاب نشده'): void
	{
		echo '<option value="0">' . esc_html($empty_label) . '</option>';
		foreach ($rows as $row) {
			if (is_array($row)) { $row = (object) $row; }
			if (! is_object($row)) { continue; }
			$value = (string) ($row->{$value_key} ?? '');
			$label = (string) ($row->{$label_key} ?? $value);
			echo '<option value="' . esc_attr($value) . '" ' . selected((string) $selected, $value, false) . '>' . esc_html($label !== '' ? $label : $value) . '</option>';
		}
	}

	private function sn_hr_render_manager_select(string $name, string $child_position_slug, int $child_user_id, int $selected_user_id, string $empty_label = 'بدون مدیر مستقیم'): void
	{
		$candidates = $this->sn_hr_manager_candidates_for_position($child_position_slug, $child_user_id);
		echo '<select name="' . esc_attr($name) . '" class="sn-hr-manager-select">';
		echo '<option value="0">' . esc_html($empty_label) . '</option>';
		foreach ($candidates as $candidate) {
			$label = trim((string) $candidate->display_name) . ' - ' . (string) ($candidate->position_label ?: $candidate->position_slug) . ' #' . (int) $candidate->user_id;
			echo '<option value="' . esc_attr((string) (int) $candidate->user_id) . '" ' . selected($selected_user_id, (int) $candidate->user_id, false) . '>' . esc_html($label) . '</option>';
		}
		echo '</select>';
	}

	private function sn_hr_render_hierarchy_manager_select(string $name, int $selected_user_id = 0, string $empty_label = 'انتخاب مدیر جدید'): void
	{
		global $wpdb;
		// Keep the generic picker useful for manual HR creation as well as the
		// inline workforce editor. Operations roles must be selectable here or a
		// new operations supervisor/expert cannot be attached to its chain.
		$allowed = ['sales_deputy','sales_manager','senior_supervisor','supervisor','operations_sales_manager','operations_sales_supervisor','operations_executive_manager'];
		$placeholders = implode(',', array_fill(0, count($allowed), '%s'));
		$rows = $wpdb->get_results($wpdb->prepare(
			"SELECT p.user_id, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, pos.slug position_slug, pos.label position_label
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->users} u ON u.ID=p.user_id
			INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE COALESCE(p.is_active,1)=1 AND pos.slug IN ({$placeholders})
			ORDER BY pos.sort_order ASC, u.display_name ASC",
			...$allowed
		)) ?: [];
		echo '<select name="' . esc_attr($name) . '" class="sn-hr-manager-select">';
		echo '<option value="0">' . esc_html($empty_label) . '</option>';
		foreach ($rows as $row) {
			$label = trim((string) $row->display_name) . ' - ' . (string) ($row->position_label ?: $row->position_slug) . ' #' . (int) $row->user_id;
			echo '<option value="' . esc_attr((string) (int) $row->user_id) . '" ' . selected($selected_user_id, (int) $row->user_id, false) . '>' . esc_html($label) . '</option>';
		}
		echo '</select>';
	}

	private function sn_hr_render_workforce_pagination(int $page, int $pages, int $total): void
	{
		?><nav class="sn-hr-pagination sn-actions" aria-label="صفحات نیروها">
			<span><?php echo esc_html(sprintf('صفحه %s از %s — %s نیرو', number_format_i18n($page), number_format_i18n($pages), number_format_i18n($total))); ?></span>
			<?php if ($page > 1) : ?><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url(add_query_arg(['sn_hr_page' => $page - 1, 'sn_hr_tab' => 'hr-workforce'])); ?>">صفحه قبل</a><?php endif; ?>
			<?php if ($page < $pages) : ?><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url(add_query_arg(['sn_hr_page' => $page + 1, 'sn_hr_tab' => 'hr-workforce'])); ?>">صفحه بعد</a><?php endif; ?>
		</nav><?php
	}

	private function sn_hr_render_workforce_management_section(array $filters, array $positions, array $levels, array $departments, array $units, array $teams, array $rules): void
