	private function sn_hr_change_request_ensure_table(): bool
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_change_requests';
		if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") === $table) {
			return true;
		}
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
		$charset = $wpdb->get_charset_collate();
		dbDelta("CREATE TABLE {$table} (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			request_type VARCHAR(60) NOT NULL,
			subject_user_id BIGINT UNSIGNED NOT NULL,
			subject_profile_id BIGINT UNSIGNED DEFAULT NULL,
			current_parent_profile_id BIGINT UNSIGNED DEFAULT NULL,
			target_parent_profile_id BIGINT UNSIGNED DEFAULT NULL,
			target_parent_user_id BIGINT UNSIGNED DEFAULT NULL,
			requested_by_user_id BIGINT UNSIGNED NOT NULL,
			current_reviewer_user_id BIGINT UNSIGNED DEFAULT NULL,
			status VARCHAR(60) NOT NULL DEFAULT 'pending_review',
			reason TEXT DEFAULT NULL,
			reviewer_notes TEXT DEFAULT NULL,
			approval_path LONGTEXT DEFAULT NULL,
			applied_at DATETIME DEFAULT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY request_type (request_type),
			KEY subject_user_id (subject_user_id),
			KEY requested_by_user_id (requested_by_user_id),
			KEY current_reviewer_user_id (current_reviewer_user_id),
			KEY status (status),
			KEY created_at (created_at)
		) {$charset};");
		return $wpdb->get_var("SHOW TABLES LIKE '{$table}'") === $table;
	}

	private function sn_hr_change_request_type_label(string $type): string
	{
		$labels = [
			'transfer_seller' => 'جابجایی فروشنده',
			'terminate_seller' => 'قطع همکاری فروشنده',
		];
		return $labels[$type] ?? $type;
	}

	private function sn_hr_change_request_status_label(string $status): string
	{
		$labels = [
			'pending_review' => 'در انتظار تایید سلسله‌مراتبی',
			'pending_hr' => 'در انتظار منابع انسانی',
			'approved' => 'تایید و اعمال شده',
			'rejected' => 'رد شده',
			'cancelled' => 'لغو شده',
			'failed' => 'خطا در اعمال',
		];
		return $labels[$status] ?? $status;
	}

	private function sn_hr_change_request_profile_by_user(int $user_id)
	{
		if ($user_id < 1 || ! class_exists('SN_HR_Service')) { return null; }
		return (new SN_HR_Service())->get_profile_by_user_id($user_id);
	}

	private function sn_hr_change_request_current_parent_profile_id(int $user_id): int
	{
		if ($user_id < 1 || ! class_exists('SN_Hierarchy_Service') || ! class_exists('SN_HR_Service')) { return 0; }
		$profile = (new SN_HR_Service())->get_profile_by_user_id($user_id);
		return $profile ? (int) (new SN_Hierarchy_Service())->get_current_parent_profile_id((int) $profile->id) : 0;
	}

	private function sn_hr_change_request_next_reviewer_user_id(int $actor_user_id): int
	{
		if ($actor_user_id < 1 || ! class_exists('SN_Hierarchy_Service')) { return 0; }
		$position = $this->sn_hr_position_for_user($actor_user_id);
		if (in_array($position, ['hr'], true) || current_user_can('manage_options')) { return 0; }
		$parent_user_id = (int) (new SN_Hierarchy_Service())->get_current_parent_user_id($actor_user_id);
		if ($parent_user_id > 0 && $parent_user_id !== $actor_user_id) {
			return $parent_user_id;
		}
		return 0;
	}

	private function sn_hr_change_request_can_create(int $actor_user_id): bool
	{
		if ($actor_user_id < 1) { return false; }
		if (current_user_can('manage_options')) { return true; }
		return $this->sn_user_has_hr_position($actor_user_id, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy', 'hr']);
	}

	private function sn_hr_change_request_is_hr_reviewer(int $actor_user_id): bool
	{
		return current_user_can('manage_options') || $this->sn_user_has_hr_position($actor_user_id, 'hr');
	}

	private function sn_hr_change_request_subject_options(int $actor_user_id): array
	{
		if ($actor_user_id < 1) { return []; }
		if ($this->sn_hr_change_request_is_hr_reviewer($actor_user_id)) {
			return $this->sn_hr_all_users_by_position('seller');
		}
		return $this->sn_get_descendant_users($actor_user_id, 'seller');
	}

	private function sn_hr_change_request_target_supervisors(int $actor_user_id): array
	{
		$rows = $this->sn_hr_all_users_by_position('supervisor');
		return array_values(array_filter($rows, static fn($row) => ! empty($row['is_active']) && (int) ($row['user_id'] ?? 0) > 0));
	}

	private function sn_hr_change_request_actor_can_touch_subject(int $actor_user_id, int $subject_user_id): bool
	{
		if ($this->sn_hr_change_request_is_hr_reviewer($actor_user_id)) { return true; }
		$allowed = array_values(array_unique(array_map('intval', array_column($this->sn_hr_change_request_subject_options($actor_user_id), 'user_id'))));
		return in_array($subject_user_id, $allowed, true);
	}

	private function sn_hr_change_request_return_url(string $msg, string $err = ''): string
	{
		$url = wp_get_referer() ?: home_url('/');
		$args = ['sn_msg' => $msg];
		if ($err !== '') { $args['sn_err'] = $err; }
		return add_query_arg($args, remove_query_arg(['sn_msg', 'sn_err'], $url));
	}

	private function sn_hr_change_request_append_path($approval_path, array $event): string
	{
		$path = [];
		if (is_string($approval_path) && $approval_path !== '') {
			$decoded = json_decode($approval_path, true);
			if (is_array($decoded)) { $path = $decoded; }
		}
		$event['at'] = current_time('mysql');
		$path[] = $event;
		return (string) wp_json_encode($path, JSON_UNESCAPED_UNICODE);
	}

	public function handle_hr_change_request_create(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_change_request_create');
		if (! $this->sn_hr_change_request_ensure_table()) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'table_missing')); exit; }
		global $wpdb;
		$actor_id = get_current_user_id();
		if (! $this->sn_hr_change_request_can_create($actor_id)) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'permission')); exit; }
		$request_type = sanitize_key(wp_unslash($_POST['request_type'] ?? ''));
		$subject_user_id = absint($_POST['subject_user_id'] ?? 0);
		$target_parent_user_id = absint($_POST['target_parent_user_id'] ?? 0);
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		if (! in_array($request_type, ['transfer_seller', 'terminate_seller'], true) || $subject_user_id < 1 || $reason === '') {
			wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'invalid_data')); exit;
		}
		if ($this->sn_hr_position_for_user($subject_user_id) !== 'seller' || ! $this->sn_hr_change_request_actor_can_touch_subject($actor_id, $subject_user_id)) {
			wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'subject_scope')); exit;
		}
		$subject_profile = $this->sn_hr_change_request_profile_by_user($subject_user_id);
		if (! $subject_profile) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'subject_profile')); exit; }
		$target_profile_id = 0;
		if ($request_type === 'transfer_seller') {
			if ($target_parent_user_id < 1 || $this->sn_hr_position_for_user($target_parent_user_id) !== 'supervisor') {
				wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'target_supervisor')); exit;
			}
			$target_profile = $this->sn_hr_change_request_profile_by_user($target_parent_user_id);
			if (! $target_profile) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'target_profile')); exit; }
			$target_profile_id = (int) $target_profile->id;
		}
		$table = $wpdb->prefix . 'sn_hr_change_requests';
		$duplicate = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE subject_user_id=%d AND request_type=%s AND status IN ('pending_review','pending_hr') ORDER BY id DESC LIMIT 1", $subject_user_id, $request_type));
		if ($duplicate) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'duplicate')); exit; }
		$reviewer_user_id = $this->sn_hr_change_request_next_reviewer_user_id($actor_id);
		$status = $reviewer_user_id > 0 ? 'pending_review' : 'pending_hr';
		$approval_path = $this->sn_hr_change_request_append_path('', [
			'action' => 'created',
			'actor_user_id' => $actor_id,
			'next_reviewer_user_id' => $reviewer_user_id,
			'status' => $status,
		]);
		$wpdb->insert($table, [
			'request_type' => $request_type,
			'subject_user_id' => $subject_user_id,
			'subject_profile_id' => (int) $subject_profile->id,
			'current_parent_profile_id' => $this->sn_hr_change_request_current_parent_profile_id($subject_user_id) ?: null,
			'target_parent_profile_id' => $target_profile_id ?: null,
			'target_parent_user_id' => $target_parent_user_id ?: null,
			'requested_by_user_id' => $actor_id,
			'current_reviewer_user_id' => $reviewer_user_id ?: null,
			'status' => $status,
			'reason' => $reason,
			'approval_path' => $approval_path,
		], ['%s','%d','%d','%d','%d','%d','%d','%d','%s','%s','%s']);
		$request_id = (int) $wpdb->insert_id;
		$this->sn_hr_panel_log_profile((int) $subject_profile->id, $subject_user_id, 'hr_change_request_created', null, ['request_id' => $request_id, 'type' => $request_type, 'target_parent_user_id' => $target_parent_user_id], ['actor_user_id' => $actor_id, 'reason' => $reason]);
		wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_created'));
		exit;
	}

	private function sn_hr_change_request_can_review($row, int $actor_user_id): bool
	{
		if (! $row || $actor_user_id < 1) { return false; }
		$status = (string) ($row->status ?? '');
		if (! in_array($status, ['pending_review', 'pending_hr'], true)) { return false; }
		if ($this->sn_hr_change_request_is_hr_reviewer($actor_user_id)) { return true; }
		return $status === 'pending_review' && (int) ($row->current_reviewer_user_id ?? 0) === $actor_user_id;
	}

	private function sn_hr_change_request_apply($row, int $actor_user_id): array
	{
		if (! $row) { return ['success' => false, 'message' => 'request_missing']; }
		$subject_user_id = (int) $row->subject_user_id;
		$subject_profile_id = (int) $row->subject_profile_id;
		if ($subject_user_id < 1 || $subject_profile_id < 1) { return ['success' => false, 'message' => 'subject_missing']; }
		global $wpdb;
		if ((string) $row->request_type === 'transfer_seller') {
			$target_profile_id = (int) $row->target_parent_profile_id;
			if ($target_profile_id < 1 || ! class_exists('SN_Hierarchy_Service')) { return ['success' => false, 'message' => 'target_missing']; }
			$result = (new SN_Hierarchy_Service())->assign_parent($subject_profile_id, $target_profile_id, $actor_user_id, 'hr_change_request', (string) ($row->reason ?? ''));
			if (empty($result['success'])) { return ['success' => false, 'message' => (string) ($result['message'] ?? 'assign_failed')]; }
			$this->sn_hr_panel_log_profile($subject_profile_id, $subject_user_id, 'hr_change_request_transfer_applied', ['old_parent_profile_id' => (int) $row->current_parent_profile_id], ['new_parent_profile_id' => $target_profile_id], ['actor_user_id' => $actor_user_id, 'request_id' => (int) $row->id]);
			return ['success' => true, 'message' => 'transfer_applied'];
		}
		if ((string) $row->request_type === 'terminate_seller') {
			$profile_table = $wpdb->prefix . 'sn_hr_profiles';
			$old = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$profile_table} WHERE id=%d", $subject_profile_id), ARRAY_A);
			$data = [
				'is_active' => 0,
				'employment_status' => 'terminated',
				'termination_date' => SN_Helpers::tehran_today_gregorian(),
				'updated_at' => current_time('mysql'),
			];
			$wpdb->update($profile_table, $data, ['id' => $subject_profile_id], ['%d','%s','%s','%s'], ['%d']);
			update_user_meta($subject_user_id, 'sn_is_active', '0');
			$new = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$profile_table} WHERE id=%d", $subject_profile_id), ARRAY_A);
			$this->sn_hr_panel_log_profile($subject_profile_id, $subject_user_id, 'hr_change_request_termination_applied', $old ?: null, $new ?: $data, ['actor_user_id' => $actor_user_id, 'request_id' => (int) $row->id]);
			return ['success' => true, 'message' => 'termination_applied'];
		}
		return ['success' => false, 'message' => 'unknown_request_type'];
	}

	public function handle_hr_change_request_review(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_change_request_review');
		if (! $this->sn_hr_change_request_ensure_table()) { wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'table_missing')); exit; }
		global $wpdb;
		$actor_id = get_current_user_id();
		$request_id = absint($_POST['request_id'] ?? 0);
		$decision = sanitize_key(wp_unslash($_POST['decision'] ?? ''));
		$notes = sanitize_textarea_field(wp_unslash($_POST['reviewer_notes'] ?? ''));
		$table = $wpdb->prefix . 'sn_hr_change_requests';
		$row = $request_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $request_id)) : null;
		if (! $row || ! $this->sn_hr_change_request_can_review($row, $actor_id) || ! in_array($decision, ['approve', 'reject'], true)) {
			wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', 'review_permission')); exit;
		}
		if ($decision === 'reject') {
			$path = $this->sn_hr_change_request_append_path($row->approval_path, ['action' => 'rejected', 'actor_user_id' => $actor_id, 'notes' => $notes]);
			$wpdb->update($table, ['status' => 'rejected', 'current_reviewer_user_id' => null, 'reviewer_notes' => $notes, 'approval_path' => $path, 'updated_at' => current_time('mysql')], ['id' => $request_id], ['%s','%d','%s','%s','%s'], ['%d']);
			wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_rejected')); exit;
		}
		$is_final = $this->sn_hr_change_request_is_hr_reviewer($actor_id) || (string) $row->status === 'pending_hr';
		if ($is_final) {
			$apply = $this->sn_hr_change_request_apply($row, $actor_id);
			if (empty($apply['success'])) {
				$path = $this->sn_hr_change_request_append_path($row->approval_path, ['action' => 'apply_failed', 'actor_user_id' => $actor_id, 'message' => (string) ($apply['message'] ?? '')]);
				$wpdb->update($table, ['status' => 'failed', 'reviewer_notes' => $notes, 'approval_path' => $path, 'updated_at' => current_time('mysql')], ['id' => $request_id], ['%s','%s','%s','%s'], ['%d']);
				wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_error', (string) ($apply['message'] ?? 'apply_failed'))); exit;
			}
			$path = $this->sn_hr_change_request_append_path($row->approval_path, ['action' => 'approved_final', 'actor_user_id' => $actor_id, 'notes' => $notes]);
			$wpdb->update($table, ['status' => 'approved', 'current_reviewer_user_id' => null, 'reviewer_notes' => $notes, 'approval_path' => $path, 'applied_at' => current_time('mysql'), 'updated_at' => current_time('mysql')], ['id' => $request_id], ['%s','%d','%s','%s','%s','%s'], ['%d']);
			wp_safe_redirect($this->sn_hr_change_request_return_url('hr_change_request_approved')); exit;
		}
		$next_reviewer = $this->sn_hr_change_request_next_reviewer_user_id($actor_id);
		$status = $next_reviewer > 0 ? 'pending_review' : 'pending_hr';
		$path = $this->sn_hr_change_request_append_path($row->approval_path, ['action' => 'approved_step', 'actor_user_id' => $actor_id, 'next_reviewer_user_id' => $next_reviewer, 'status' => $status, 'notes' => $notes]);
		$wpdb->update($table, ['status' => $status, 'current_reviewer_user_id' => $next_reviewer ?: null, 'reviewer_notes' => $notes, 'approval_path' => $path, 'updated_at' => current_time('mysql')], ['id' => $request_id], ['%s','%d','%s','%s','%s'], ['%d']);
		wp_safe_redirect($this->sn_hr_change_request_return_url($status === 'pending_hr' ? 'hr_change_request_sent_to_hr' : 'hr_change_request_step_approved'));
		exit;
	}

	private function sn_hr_change_request_rows_for_actor(int $actor_user_id, int $limit = 80): array
	{
		if (! $this->sn_hr_change_request_ensure_table()) { return []; }
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_change_requests';
		$limit = max(10, min(300, $limit));
		if ($this->sn_hr_change_request_is_hr_reviewer($actor_user_id)) {
			return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} ORDER BY FIELD(status,'pending_hr','pending_review','failed','approved','rejected'), id DESC LIMIT %d", $limit)) ?: [];
		}
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE requested_by_user_id=%d OR current_reviewer_user_id=%d ORDER BY FIELD(status,'pending_review','pending_hr','failed','approved','rejected'), id DESC LIMIT %d", $actor_user_id, $actor_user_id, $limit)) ?: [];
	}

	private function sn_hr_change_request_render_section(int $actor_user_id, string $context = ''): void
	{
