	private function sn_hr_panel_summary(): array
	{
		global $wpdb;
		$profiles = $wpdb->prefix . 'sn_hr_profiles';
		$assignments = $wpdb->prefix . 'sn_hr_assignments';
		$summary = [
			'کل پروفایل‌ها' => number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles}")),
			'فعال' => number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} WHERE is_active=1 AND (employment_status IS NULL OR employment_status NOT IN ('inactive','suspended','resigned','terminated'))")),
			'غیرفعال' => number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} WHERE is_active=0 OR employment_status IN ('inactive','suspended','resigned','terminated')")),
		];
		foreach ([
			'seller' => 'فروشنده‌ها',
			'converter' => 'تبدیل‌کننده‌ها',
			'senior_supervisor' => 'سرپرست ارشد',
			'sales_manager' => 'مدیر فروش',
			'sales_deputy' => 'معاون فروش',
			'hr' => 'منابع انسانی',
			'mis' => 'MIS',
			'after_sales' => 'خدمات پس از فروش',
			'operations_sales_manager' => 'مدیران فروش عملیات',
			'operations_sales_supervisor' => 'سرپرستان فروش عملیات',
			'operations_sales_expert' => 'کارشناسان فروش عملیات',
		] as $slug => $label) {
			$summary[$label] = number_format_i18n((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$profiles} hp INNER JOIN {$wpdb->prefix}sn_hr_positions p ON p.id=hp.position_id WHERE p.slug=%s", $slug)));
		}
		$summary['بدون مدیر مستقیم'] = number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} p LEFT JOIN {$assignments} a ON a.child_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to' WHERE a.id IS NULL"));
		$summary['بدون کد پرسنلی'] = number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} WHERE employee_code IS NULL OR employee_code=''"));
		$summary['بدون ساختار واحدی'] = number_format_i18n((int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} WHERE department_id IS NULL OR department_id=0 OR unit_id IS NULL OR unit_id=0 OR team_id IS NULL OR team_id=0"));
		return $summary;
	}

