	private function sn_runtime_add_column_if_missing(string $table, string $column, string $definition): bool
	{
		global $wpdb;
		if (! $this->sn_table_exists_quiet($table)) { return false; }
		if ($this->sn_table_has_column($table, $column)) { return false; }
		$result = $wpdb->query("ALTER TABLE {$table} ADD COLUMN {$definition}");
		if ($result !== false) { $this->sn_runtime_column_exists_cache[$table . '|' . $column] = true; }
		return $result !== false;
	}

	public function sn_ensure_hr_profile_schema_runtime(): void
	{
		if ($this->sn_defer_heavy_admin_runtime()) { return; }
		$schema_version = '2026-10-07-hr-performance-v1';
		if (get_option('sn_hr_profile_runtime_version', '') === $schema_version) { return; }
		global $wpdb;
		$profiles = $wpdb->prefix . 'sn_hr_profiles';
		if (! $this->sn_table_exists_quiet($profiles)) { return; }
		$changed = false;
		$ready = true;
		foreach ([
			'hr_display_name' => 'hr_display_name VARCHAR(255) NULL AFTER user_id',
			'position_id' => 'position_id BIGINT UNSIGNED DEFAULT NULL AFTER user_id',
			'level_id' => 'level_id BIGINT UNSIGNED DEFAULT NULL AFTER position_id',
			'employee_code' => 'employee_code VARCHAR(100) NULL AFTER level_id',
			'employment_status' => "employment_status VARCHAR(50) NOT NULL DEFAULT 'active' AFTER employee_code",
			'employment_type' => 'employment_type VARCHAR(50) NULL AFTER employment_status',
			'hire_date' => 'hire_date DATE NULL AFTER employment_type',
			'termination_date' => 'termination_date DATE NULL AFTER hire_date',
			'base_salary' => 'base_salary BIGINT UNSIGNED NULL AFTER termination_date',
			'salary_currency' => "salary_currency VARCHAR(20) NOT NULL DEFAULT 'IRT' AFTER base_salary",
			'national_id' => 'national_id VARCHAR(50) NULL AFTER salary_currency',
			'work_phone' => 'work_phone VARCHAR(50) NULL AFTER national_id',
			'emergency_phone' => 'emergency_phone VARCHAR(50) NULL AFTER work_phone',
			'department_id' => 'department_id BIGINT UNSIGNED NULL AFTER emergency_phone',
			'unit_id' => 'unit_id BIGINT UNSIGNED NULL AFTER department_id',
			'team_id' => 'team_id BIGINT UNSIGNED NULL AFTER unit_id',
			'contract_status' => 'contract_status VARCHAR(50) NULL AFTER team_id',
			'training_status' => 'training_status VARCHAR(50) NULL AFTER contract_status',
			'legacy_role' => 'legacy_role VARCHAR(120) NULL AFTER training_status',
			'legacy_source' => 'legacy_source VARCHAR(120) NULL AFTER legacy_role',
			'is_active' => 'is_active TINYINT(1) NOT NULL DEFAULT 1 AFTER legacy_source',
			'notes' => 'notes TEXT NULL AFTER is_active',
			'created_at' => 'created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP AFTER notes',
			'updated_at' => 'updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP AFTER created_at',
		] as $column => $definition) {
			$changed = $this->sn_runtime_add_column_if_missing($profiles, $column, $definition) || $changed;
			$ready = $this->sn_table_has_column($profiles, $column) && $ready;
		}
		foreach ([
			'position_id' => ['position_id'],
			'level_id' => ['level_id'],
			'employee_code' => ['employee_code'],
			'employment_status' => ['employment_status'],
			'is_active' => ['is_active'],
		] as $index => $columns) {
			$this->sn_add_index_if_possible($profiles, $index, $columns);
			$ready = $this->sn_index_exists($profiles, $index) && $ready;
		}
		foreach ([
			'sn_hr_assignments' => ['sn_hr_child_current_idx', ['child_profile_id','is_current','relationship_type','id']],
			'sn_hr_compensation_profiles' => ['sn_hr_comp_current_idx', ['profile_id','is_active','id']],
			'sn_hr_compensation_history' => ['sn_hr_history_current_idx', ['profile_id','is_active','effective_from','id']],
		] as $suffix => [$index, $columns]) {
			$table = $wpdb->prefix . $suffix;
			$this->sn_add_index_if_possible($table, $index, $columns);
			$ready = $this->sn_index_exists($table, $index) && $ready;
		}
		$backfill = $this->sn_hr_backfill_profiles_from_latest_import_report();
		if ($changed || $backfill['updated_profiles'] > 0) {
			update_option('sn_hr_profile_schema_repair_report', [
				'changed_schema' => $changed,
				'backfill' => $backfill,
				'updated_at' => current_time('mysql'),
			], false);
		}
		if ($ready) { update_option('sn_hr_profile_runtime_version', $schema_version, false); }
	}

	private function sn_hr_lookup_id_by_slug_or_label(string $table_suffix, string $slug, string $label = ''): int
	{
		global $wpdb;
		$table = $wpdb->prefix . $table_suffix;
		if (! $this->sn_table_exists_quiet($table)) { return 0; }
		$slug = sanitize_key($slug);
		$label = trim($label);
		if ($slug !== '') {
			$id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE slug=%s LIMIT 1", $slug));
			if ($id > 0) { return $id; }
		}
		if ($label !== '') {
			$id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE label=%s LIMIT 1", $label));
			if ($id > 0) { return $id; }
		}
		return 0;
	}

	private function sn_hr_backfill_profiles_from_latest_import_report(): array
	{
		global $wpdb;
		$profiles = $wpdb->prefix . 'sn_hr_profiles';
		if (! $this->sn_table_exists_quiet($profiles) || ! $this->sn_table_has_column($profiles, 'position_id')) {
			return ['updated_profiles' => 0, 'scanned' => 0, 'source' => 'schema_missing'];
		}
		$report = get_option('sn_hr_csv_dry_run_report', []);
		if (! is_array($report) || empty($report['preview']) || ! is_array($report['preview'])) {
			return ['updated_profiles' => 0, 'scanned' => 0, 'source' => 'no_import_report'];
		}
		$updated = 0;
		$scanned = 0;
		foreach ($report['preview'] as $row) {
			$row = is_array($row) ? $row : [];
			$user_id = absint($row['user_id'] ?? 0);
			if ($user_id < 1 && ! empty($row['user']) && preg_match('/#(\d+)/u', (string) $row['user'], $m)) {
				$user_id = absint($m[1]);
			}
			if ($user_id < 1) { continue; }
			$scanned++;
			$position_slug = sanitize_key((string) ($row['position'] ?? ''));
			$level_slug = sanitize_key((string) ($row['level'] ?? ''));
			$position_id = $this->sn_hr_lookup_id_by_slug_or_label('sn_hr_positions', $position_slug, (string) ($row['position_label'] ?? ''));
			$level_id = $this->sn_hr_lookup_id_by_slug_or_label('sn_hr_levels', $level_slug, (string) ($row['level_label'] ?? ''));
			$data = ['updated_at' => current_time('mysql')];
			if ($position_id > 0) { $data['position_id'] = $position_id; }
			if ($level_id > 0 && $this->sn_table_has_column($profiles, 'level_id')) { $data['level_id'] = $level_id; }
			if ($position_slug !== '' && $this->sn_table_has_column($profiles, 'legacy_role')) { $data['legacy_role'] = $position_slug; }
			if ($this->sn_table_has_column($profiles, 'legacy_source')) { $data['legacy_source'] = 'hr_people_import_report_backfill'; }
			if (count($data) < 2) { continue; }
			$where_sql = $position_id > 0 ? "user_id=%d AND (position_id IS NULL OR position_id=0)" : "user_id=%d";
			$prepare_args = array_values(array_map('strval', $data));
			$prepare_args[] = $user_id;
			$result = $wpdb->query($wpdb->prepare("UPDATE {$profiles} SET " . implode(', ', array_map(static function($key) { return $key . '=%s'; }, array_keys($data))) . " WHERE {$where_sql}", ...$prepare_args));
			if ($result && $result > 0) { $updated += (int) $result; }
		}
		return ['updated_profiles' => $updated, 'scanned' => $scanned, 'source' => 'sn_hr_csv_dry_run_report'];
	}

	private function sn_table_exists_quiet(string $table): bool
	{
		global $wpdb;
		if (array_key_exists($table, $this->sn_runtime_table_exists_cache)) {
			return (bool) $this->sn_runtime_table_exists_cache[$table];
		}
		$exists = (string) $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
		$this->sn_runtime_table_exists_cache[$table] = $exists;
		return $exists;
	}

	private function sn_next_numeric_invoice_code_preview(): string
	{
		// کد فاکتور دیگر ترتیبی نیست. این مقدار فقط برای نمایش تشخیصی یک نمونه تصادفی امن است.
		return (string) wp_rand(20000000, 99999999);
	}

	private function sn_generate_invoice_code(): string
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_invoices';
		for ($i = 0; $i < 500; $i++) {
			$code = (string) wp_rand(20000000, 99999999);
			$exists = $this->sn_table_exists_quiet($table) ? (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE invoice_code=%s", $code)) : 0;
			if ($exists < 1) {
				return $code;
			}
		}
		throw new RuntimeException('invoice_code_random_pool_exhausted');
	}

	private function sn_invoice_code_diagnostics(): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_invoices';
		if (! $this->sn_table_exists_quiet($table)) {
			return ['table_exists' => false, 'next_numeric_code' => '', 'numeric_six_digit_count' => 0, 'legacy_format_count' => 0, 'duplicate_code_groups' => 0];
		}
		return [
			'table_exists' => true,
			'next_numeric_code' => $this->sn_next_numeric_invoice_code_preview(),
			'random_code_mode' => '8_digit_non_sequential',
			'numeric_six_digit_count' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE invoice_code REGEXP '^[0-9]{6}$'"),
			'legacy_format_count' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE invoice_code IS NOT NULL AND invoice_code <> '' AND invoice_code NOT REGEXP '^[0-9]{6}$'"),
			'duplicate_code_groups' => (int) $wpdb->get_var("SELECT COUNT(*) FROM (SELECT invoice_code FROM {$table} WHERE invoice_code IS NOT NULL AND invoice_code <> '' GROUP BY invoice_code HAVING COUNT(*) > 1) d"),
		];
	}

	private function sn_hr_compensation_rows(int $limit = 100): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_profiles';
		if (! $this->sn_table_exists_quiet($table)) {
			return [];
		}
		return $wpdb->get_results($wpdb->prepare(
			"SELECT hp.id profile_id, hp.user_id, hp.employment_status, hp.employment_type, hp.base_salary profile_base_salary, hp.salary_currency profile_salary_currency, hp.is_active profile_active,
				u.display_name, u.user_login, pos.label position_label, pos.slug position_slug, lvl.label level_label, lvl.slug level_slug,
				cp.base_salary, cp.salary_currency, cp.commission_enabled, cp.default_commission_rule_id, cp.commission_override_mode, cp.effective_from, cp.effective_to, cp.notes, cp.is_active compensation_active,
				cr.rule_code, cr.title rule_title
			FROM {$wpdb->prefix}sn_hr_profiles hp
			LEFT JOIN {$wpdb->users} u ON u.ID=hp.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=hp.level_id
			LEFT JOIN {$table} cp ON cp.profile_id=hp.id AND cp.is_active=1
			LEFT JOIN {$wpdb->prefix}sn_commission_rules cr ON cr.id=cp.default_commission_rule_id
			ORDER BY pos.sort_order ASC, hp.user_id ASC
			LIMIT %d",
			max(1, min(300, $limit))
		)) ?: [];
	}

	private function sn_hr_compensation_rule_usage_rows(): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_profiles';
		if (! $this->sn_table_exists_quiet($table) || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_commission_rules')) {
			return [];
		}
		return $wpdb->get_results("SELECT cr.title label, cr.rule_code slug, COUNT(cp.id) count
			FROM {$wpdb->prefix}sn_commission_rules cr
			LEFT JOIN {$table} cp ON cp.default_commission_rule_id=cr.id AND cp.is_active=1
			GROUP BY cr.id, cr.title, cr.rule_code
			ORDER BY count ASC, cr.id ASC", ARRAY_A) ?: [];
	}

	private function sn_hr_compensation_for_profile(int $profile_id)
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_profiles';
		if (! $profile_id || ! $this->sn_table_exists_quiet($table)) {
			return null;
		}
		return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE profile_id=%d AND is_active=1 ORDER BY id DESC LIMIT 1", $profile_id));
	}

	private function sn_hr_compensation_history_for_user_at(int $user_id, string $date): ?array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_history';
		if ($user_id < 1 || ! preg_match('/^\d{4}-\d{2}-\d{2}$/', $date) || ! $this->sn_table_exists_quiet($table)) {
			return null;
		}
		$row = $wpdb->get_row($wpdb->prepare(
			"SELECT * FROM {$table}
			WHERE user_id=%d AND is_active=1 AND effective_from <= %s
			  AND (effective_to IS NULL OR effective_to >= %s)
			ORDER BY effective_from DESC, id DESC LIMIT 1",
			$user_id,
			$date,
			$date
		), ARRAY_A);
		return $row ?: null;
	}

	private function sn_hr_compensation_history_rows(int $limit = 80): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_history';
		if (! $this->sn_table_exists_quiet($table)) {
			return [];
		}
		return $wpdb->get_results($wpdb->prepare(
			"SELECT ch.*, u.display_name, u.user_login, cr.title rule_title, cr.rule_code
			FROM {$table} ch
			LEFT JOIN {$wpdb->users} u ON u.ID=ch.user_id
			LEFT JOIN {$wpdb->prefix}sn_commission_rules cr ON cr.id=ch.commission_rule_id
			ORDER BY ch.effective_from DESC, ch.id DESC
			LIMIT %d",
			max(1, min(200, $limit))
		), ARRAY_A) ?: [];
	}

	private function sn_commission_calculation_date(array $invoice): string
	{
		foreach (['payment_approved_at', 'approved_at', 'paid_at', 'paid_date', 'payment_date', 'created_at'] as $key) {
			$value = trim((string) ($invoice[$key] ?? ''));
			if ($value !== '' && preg_match('/^\d{4}-\d{2}-\d{2}/', $value)) {
				try {
					return (new DateTimeImmutable($value, wp_timezone()))->setTimezone(SN_Helpers::tehran_timezone())->format('Y-m-d');
				} catch (Throwable $e) {
					return substr($value, 0, 10);
				}
			}
		}
		return (new DateTimeImmutable('now', SN_Helpers::tehran_timezone()))->format('Y-m-d');
	}

	private function sn_hr_compensation_update(int $profile_id, int $user_id, array $data, string $reason): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_profiles';
		if (! $profile_id || ! $user_id || ! $this->sn_table_exists_quiet($table)) {
			return ['changed' => false, 'old' => null, 'new' => null, 'error' => 'compensation_profile_table_missing_or_invalid_identity'];
		}
		$existing = $this->sn_hr_compensation_for_profile($profile_id);
		$old = $existing ? (array) $existing : null;
		$payload = [
			'profile_id' => $profile_id,
			'user_id' => $user_id,
			'updated_at' => current_time('mysql'),
		];
		foreach (['base_salary','salary_currency','commission_enabled','default_commission_rule_id','commission_override_mode','effective_from','effective_to','notes','is_active'] as $field) {
			if (array_key_exists($field, $data)) {
				$payload[$field] = $data[$field];
			}
		}
		if ($existing) {
			$changed = false;
			foreach ($payload as $key => $value) {
				if (in_array($key, ['profile_id','user_id','updated_at'], true)) {
					continue;
				}
				if ((string) ($existing->{$key} ?? '') !== (string) $value) {
					$changed = true;
					break;
				}
			}
			if ($changed) {
				$updated = $wpdb->update($table, $this->sn_filter_existing_columns($table, $payload), ['id' => (int) $existing->id]);
				if ($updated === false) {
					return ['changed' => false, 'old' => $old, 'new' => $old, 'error' => 'compensation_profile_update_failed'];
				}
				$new = (array) $this->sn_hr_compensation_for_profile($profile_id);
				$this->sn_hr_panel_log_profile($profile_id, $user_id, 'hr_compensation_profile_updated', $old, $new, ['reason' => $reason]);
				return ['changed' => true, 'old' => $old, 'new' => $new];
			}
			return ['changed' => false, 'old' => $old, 'new' => $old];
		}
		$payload['created_at'] = current_time('mysql');
		if (! array_key_exists('commission_enabled', $payload)) {
			$payload['commission_enabled'] = 1;
		}
		if (! array_key_exists('commission_override_mode', $payload) || $payload['commission_override_mode'] === '') {
			$payload['commission_override_mode'] = 'inherit';
		}
		if (! array_key_exists('salary_currency', $payload) || $payload['salary_currency'] === '') {
			$payload['salary_currency'] = 'IRT';
		}
		$inserted = $wpdb->insert($table, $this->sn_filter_existing_columns($table, $payload));
		if ($inserted === false || ! $wpdb->insert_id) {
			return ['changed' => false, 'old' => null, 'new' => null, 'error' => 'compensation_profile_insert_failed'];
		}
		$new = (array) $this->sn_hr_compensation_for_profile($profile_id);
		$this->sn_hr_panel_log_profile($profile_id, $user_id, 'hr_compensation_profile_created', null, $new, ['reason' => $reason]);
		return ['changed' => true, 'old' => null, 'new' => $new];
	}

