	private function sn_hr_panel_counts_by(string $type): array
	{
		global $wpdb;
		if ($type === 'level') {
			return $wpdb->get_results("SELECT COALESCE(l.label,'بدون سطح') label, COALESCE(l.slug,'none') slug, COUNT(*) count FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->prefix}sn_hr_levels l ON l.id=p.level_id GROUP BY slug,label ORDER BY count DESC", ARRAY_A) ?: [];
		}
		return $wpdb->get_results("SELECT COALESCE(pos.label,'بدون سمت') label, COALESCE(pos.slug,'none') slug, COUNT(*) count FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id GROUP BY slug,label ORDER BY count DESC", ARRAY_A) ?: [];
	}

	private function sn_hr_panel_render_count_table(array $rows): void
	{
		echo '<div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>عنوان</th><th>کد</th><th>تعداد</th></tr></thead><tbody>';
		foreach ($rows as $row) {
			echo '<tr><td>' . esc_html((string) ($row['label'] ?? '')) . '</td><td><span class="sn-hr-badge">' . esc_html((string) ($row['slug'] ?? '')) . '</span></td><td>' . esc_html(number_format_i18n((int) ($row['count'] ?? 0))) . '</td></tr>';
		}
		echo '</tbody></table></div>';
	}

	private function sn_hr_commission_rule_value($rule, string $key, $default = '')
	{
		if (is_array($rule)) {
			return $rule[$key] ?? $default;
		}
		if (is_object($rule)) {
			return $rule->{$key} ?? $default;
		}
		return $default;
	}

	private function sn_hr_commission_rule_label($rule): string
	{
		$id = (int) $this->sn_hr_commission_rule_value($rule, 'id', 0);
		$title = trim((string) $this->sn_hr_commission_rule_value($rule, 'title', ''));
		$code = trim((string) $this->sn_hr_commission_rule_value($rule, 'rule_code', ''));
		$label = $title !== '' ? $title : ($code !== '' ? $code : 'قانون #' . $id);
		if ((int) $this->sn_hr_commission_rule_value($rule, 'is_active', 1) !== 1) {
			$label .= ' - غیرفعال';
		}
		return $label;
	}

	private function sn_hr_render_commission_rule_options(array $rules, int $selected_id = 0, string $empty_label = 'بدون طرح پورسانت'): void
	{
		echo '<option value="0"' . selected($selected_id, 0, false) . '>' . esc_html($empty_label) . '</option>';
		if (! $rules) {
			echo '<option value="0" disabled>قانون پورسانتی ثبت نشده است</option>';
			return;
		}
		foreach ($rules as $rule) {
			$id = (int) $this->sn_hr_commission_rule_value($rule, 'id', 0);
			if ($id < 1) {
				continue;
			}
			echo '<option value="' . esc_attr((string) $id) . '"' . selected($selected_id, $id, false) . '>' . esc_html($this->sn_hr_commission_rule_label($rule)) . '</option>';
		}
	}

	private function sn_hr_panel_profile_filters(): array
	{
		return [
			'q' => sanitize_text_field(SN_Helpers::to_english_nums(wp_unslash($_GET['sn_hr_q'] ?? ''))),
			'position' => sanitize_key(wp_unslash($_GET['sn_hr_position'] ?? '')),
			'level' => sanitize_key(wp_unslash($_GET['sn_hr_level'] ?? '')),
			'active' => in_array((string) ($_GET['sn_hr_active'] ?? ''), ['0', '1'], true) ? (string) $_GET['sn_hr_active'] : '',
			'assignment' => in_array((string) ($_GET['sn_hr_assignment'] ?? ''), ['has', 'none'], true) ? (string) $_GET['sn_hr_assignment'] : '',
			'legacy_role' => sanitize_key(wp_unslash($_GET['sn_hr_legacy_role'] ?? '')),
			'employment_status' => sanitize_key(wp_unslash($_GET['sn_hr_employment_status'] ?? '')),
			'department_id' => absint($_GET['sn_hr_department'] ?? 0),
			'unit_id' => absint($_GET['sn_hr_unit'] ?? 0),
			'team_id' => absint($_GET['sn_hr_team'] ?? 0),
			'manager_user_id' => absint($_GET['sn_hr_manager'] ?? 0),
			'missing_manager' => ! empty($_GET['sn_hr_missing_manager']) ? '1' : '',
			'missing_level' => ! empty($_GET['sn_hr_missing_level']) ? '1' : '',
			'missing_comp_history' => ! empty($_GET['sn_hr_missing_comp_history']) ? '1' : '',
		];
	}

	private function sn_hr_panel_profile_rows(array $filters, int $limit = 100): array
	{
		global $wpdb;
		$where = ['1=1'];
		$args = [];
		if ($filters['q'] !== '') {
			if (ctype_digit($filters['q'])) {
				$where[] = 'p.user_id=%d';
				$args[] = (int) $filters['q'];
			} else {
				$like = '%' . $wpdb->esc_like($filters['q']) . '%';
				$where[] = '(u.user_login LIKE %s OR u.user_email LIKE %s OR u.display_name LIKE %s OR p.employee_code LIKE %s)';
				array_push($args, $like, $like, $like, $like);
			}
		}
		if ($filters['position'] !== '') { $where[] = 'pos.slug=%s'; $args[] = $filters['position']; }
		if ($filters['level'] !== '') { $where[] = 'lvl.slug=%s'; $args[] = $filters['level']; }
		if ($filters['active'] !== '') { $where[] = 'p.is_active=%d'; $args[] = (int) $filters['active']; }
		if ($filters['legacy_role'] !== '') { $where[] = 'p.legacy_role=%s'; $args[] = $filters['legacy_role']; }
		if ($filters['employment_status'] !== '') { $where[] = 'p.employment_status=%s'; $args[] = $filters['employment_status']; }
		if ($filters['department_id']) { $where[] = 'p.department_id=%d'; $args[] = $filters['department_id']; }
		if ($filters['unit_id']) { $where[] = 'p.unit_id=%d'; $args[] = $filters['unit_id']; }
		if ($filters['team_id']) { $where[] = 'p.team_id=%d'; $args[] = $filters['team_id']; }
		if ($filters['assignment'] === 'has') { $where[] = 'a.id IS NOT NULL'; }
		if ($filters['assignment'] === 'none') { $where[] = 'a.id IS NULL'; }
		$sql = "SELECT p.*, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug position_slug, pos.label position_label, lvl.slug level_slug, lvl.label level_label, parent.user_id manager_user_id, d.label department_label, un.label unit_label, t.label team_label,
			(SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_assignments ca WHERE ca.parent_profile_id=p.id AND ca.is_current=1 AND ca.relationship_type='reports_to') direct_children_count
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=p.level_id
			LEFT JOIN {$wpdb->prefix}sn_hr_departments d ON d.id=p.department_id
			LEFT JOIN {$wpdb->prefix}sn_hr_units un ON un.id=p.unit_id
			LEFT JOIN {$wpdb->prefix}sn_hr_teams t ON t.id=p.team_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to'
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			WHERE " . implode(' AND ', $where) . " ORDER BY p.updated_at DESC, p.user_id ASC LIMIT %d";
		$args[] = max(1, min(300, $limit));
		return $wpdb->get_results($wpdb->prepare($sql, ...$args)) ?: [];
	}

