	private function sn_hr_hierarchy_option_label(array $row): string
	{
		$user_id = (int) ($row['user_id'] ?? 0);
		$status = ! empty($row['is_active']) ? 'فعال' : 'غیرفعال';
		return $this->sn_user_label($user_id) . ' / ' . (string) ($row['position_label'] ?? $row['position_slug'] ?? '') . ' / ' . $status;
	}

	private function sn_hr_hierarchy_audit_summary(): array
	{
		global $wpdb;
		$sql = "SELECT child.user_id child_user_id, child_pos.slug child_position, child.is_active child_active,
				parent.user_id parent_user_id, parent_pos.slug parent_position, parent.is_active parent_active
			FROM {$wpdb->prefix}sn_hr_profiles child
			LEFT JOIN {$wpdb->prefix}sn_hr_positions child_pos ON child_pos.id=child.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=child.id AND a.relationship_type='reports_to' AND a.is_current=1
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions parent_pos ON parent_pos.id=parent.position_id";
		$rows = $wpdb->get_results($sql, ARRAY_A) ?: [];
		$out = [
			'فروشنده بدون مدیر' => 0,
			'فروشنده زیر سرپرست ارشد' => 0,
			'فروشنده زیر سرپرست' => 0,
			'فروشنده مستقیم زیر مدیر فروش' => 0,
			'سرپرست ارشد بدون مدیر فروش' => 0,
			'مدیر فروش بدون معاون فروش' => 0,
			'سرپرست فروش عملیات بدون مدیر معتبر' => 0,
			'کارشناس فروش عملیات بدون سرپرست معتبر' => 0,
			'کارشناس اجرایی عملیات بدون مدیر معتبر' => 0,
			'مدیر مستقیم با سمت نامعتبر' => 0,
			'نیروهای سطح بالا' => 0,
		];
		$valid_parents = [
			'seller' => ['supervisor', 'senior_supervisor', 'sales_manager'],
			'converter' => ['supervisor'],
			'supervisor' => ['senior_supervisor'],
			'senior_supervisor' => ['sales_manager'],
			'sales_manager' => ['sales_deputy'],
			'operations_sales_supervisor' => ['operations_sales_manager'],
			'operations_sales_expert' => ['operations_sales_supervisor'],
			'operations_execution_expert' => ['operations_executive_manager'],
		];
		foreach ($rows as $row) {
			$child = (string) ($row['child_position'] ?? '');
			$parent = (string) ($row['parent_position'] ?? '');
			if ($parent === '') {
				$out['نیروهای سطح بالا']++;
			}
			if ($child === 'seller') {
				if ($parent === '') { $out['فروشنده بدون مدیر']++; }
				if ($parent === 'senior_supervisor') { $out['فروشنده زیر سرپرست ارشد']++; }
				if ($parent === 'supervisor') { $out['فروشنده زیر سرپرست']++; }
				if ($parent === 'sales_manager') { $out['فروشنده مستقیم زیر مدیر فروش']++; }
			}
			if ($child === 'senior_supervisor' && $parent !== 'sales_manager') {
				$out['سرپرست ارشد بدون مدیر فروش']++;
			}
			if ($child === 'sales_manager' && $parent !== 'sales_deputy') {
				$out['مدیر فروش بدون معاون فروش']++;
			}
			if ($child === 'operations_sales_supervisor' && $parent !== 'operations_sales_manager') {
				$out['سرپرست فروش عملیات بدون مدیر معتبر']++;
			}
			if ($child === 'operations_sales_expert' && $parent !== 'operations_sales_supervisor') {
				$out['کارشناس فروش عملیات بدون سرپرست معتبر']++;
			}
			if ($child === 'operations_execution_expert' && $parent !== 'operations_executive_manager') {
				$out['کارشناس اجرایی عملیات بدون مدیر معتبر']++;
			}
			if (isset($valid_parents[$child]) && $parent !== '' && ! in_array($parent, $valid_parents[$child], true)) {
				$out['مدیر مستقیم با سمت نامعتبر']++;
			}
		}
		return $out;
	}

	public function handle_hr_bulk_assign_hierarchy(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_bulk_assign_hierarchy');
		$type = sanitize_key(wp_unslash($_POST['assignment_type'] ?? ''));
		$configs = [
			'sellers' => ['child' => 'seller', 'parents' => ['supervisor', 'senior_supervisor', 'sales_manager']],
			'converters' => ['child' => 'converter', 'parents' => ['supervisor']],
			'supervisors' => ['child' => 'supervisor', 'parents' => ['senior_supervisor']],
			'senior_supervisors' => ['child' => 'senior_supervisor', 'parents' => ['sales_manager']],
			'sales_managers' => ['child' => 'sales_manager', 'parents' => ['sales_deputy']],
			'operations_sales_supervisors' => ['child' => 'operations_sales_supervisor', 'parents' => ['operations_sales_manager']],
			'operations_sales_experts' => ['child' => 'operations_sales_expert', 'parents' => ['operations_sales_supervisor']],
			'operations_execution_experts' => ['child' => 'operations_execution_expert', 'parents' => ['operations_executive_manager']],
		];
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		$overwrite = ! empty($_POST['overwrite_existing']);
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$selected_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['selected_user_ids'] ?? [])))));
		$target_user_id = absint($_POST['target_manager_user_id'] ?? 0);
		$report = ['action' => 'hr_bulk_assign_hierarchy', 'mode' => $run_mode, 'type' => $type, 'requested' => count($selected_ids), 'eligible' => 0, 'assigned' => 0, 'skipped' => 0, 'errors' => [], 'rows' => [], 'updated_at' => current_time('mysql')];
		if (! isset($configs[$type])) { $report['errors'][] = 'invalid_assignment_type'; }
		if (! $target_user_id) { $report['errors'][] = 'target_manager_required'; }
		if ($run_mode === 'apply' && $confirm !== 'APPLY') { $report['errors'][] = 'confirmation_required'; }
		if (! class_exists('SN_HR_Service') || ! class_exists('SN_Hierarchy_Service')) { $report['errors'][] = 'hr_service_missing'; }
		$hr = class_exists('SN_HR_Service') ? new SN_HR_Service() : null;
		$hierarchy = class_exists('SN_Hierarchy_Service') ? new SN_Hierarchy_Service() : null;
		$target_profile = ($hr && $target_user_id) ? $hr->get_profile_by_user_id($target_user_id) : null;
		$target_position = $target_user_id ? $this->sn_hr_position_for_user($target_user_id) : '';
		if (isset($configs[$type]) && (! $target_profile || ! in_array($target_position, $configs[$type]['parents'], true))) {
			$report['errors'][] = 'target_manager_position_invalid';
		}
		foreach ($selected_ids as $child_user_id) {
			$row = ['child_user_id' => $child_user_id, 'child_label' => $this->sn_user_label($child_user_id), 'status' => 'skipped', 'reason' => ''];
			$child_profile = $hr ? $hr->get_profile_by_user_id($child_user_id) : null;
			$child_position = $this->sn_hr_position_for_user($child_user_id);
			if (! empty($report['errors'])) {
				$row['reason'] = 'preflight_error';
			} elseif (! $child_profile || ! $target_profile || ! $hierarchy) {
				$row['reason'] = 'profile_missing';
			} elseif ($child_position !== $configs[$type]['child']) {
				$row['reason'] = 'child_position_invalid';
			} else {
				$current_parent = $hierarchy->get_current_parent_profile_id((int) $child_profile->id);
				if ($current_parent && ! $overwrite && $current_parent !== (int) $target_profile->id) {
					$row['reason'] = 'has_existing_manager';
				} else {
					$report['eligible']++;
					$row['status'] = 'eligible';
					$row['reason'] = 'ready';
					if ($run_mode === 'apply') {
						$result = $hierarchy->assign_parent((int) $child_profile->id, (int) $target_profile->id, get_current_user_id(), 'hr_bulk_assignment', $reason ?: 'manual hierarchy assignment');
						if (! empty($result['success'])) {
							$report['assigned']++;
							$row['status'] = ! empty($result['skipped']) ? 'unchanged' : 'assigned';
							$row['reason'] = (string) ($result['message'] ?? 'assigned');
						} else {
							$row['status'] = 'error';
							$row['reason'] = (string) ($result['message'] ?? 'assign_failed');
						}
					}
				}
			}
			if (in_array($row['status'], ['skipped', 'error'], true)) { $report['skipped']++; }
			$report['rows'][] = $row;
		}
		update_option('sn_hr_bulk_assignment_report', $report, false);
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => 'hr_bulk_assignment_done']));
		exit;
	}

	public function handle_hierarchy_consistency_check(): void
	{
		if (! current_user_can('manage_options')) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hierarchy_consistency_check');
		$report = $this->sn_hierarchy_consistency_report();
		update_option('sn_hierarchy_consistency_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: admin_url('admin.php?page=sn-integration'));
		exit;
	}

	private function sn_hierarchy_consistency_report(): array
	{
		$report = ['checked_at' => current_time('mysql'), 'warnings' => [], 'senior_supervisors' => [], 'sales_managers' => [], 'sales_deputy' => [], 'audit' => $this->sn_hr_hierarchy_audit_summary()];
		$supervisor_count = count($this->sn_hr_all_users_by_position('supervisor'));
		if ($supervisor_count === 0) {
			$report['warnings'][] = 'supervisor_layer_empty_current_transitional_structure_allowed';
		}
		$sales_manager_count = count($this->sn_hr_all_users_by_position('sales_manager'));
		if ($sales_manager_count !== 1) {
			$report['warnings'][] = 'sales_manager_count_' . $sales_manager_count;
		}
		foreach ($this->sn_hr_all_users_by_position('senior_supervisor') as $row) {
			$user_id = (int) $row['user_id'];
			$direct_sellers = array_map('intval', array_column($this->sn_get_direct_children($user_id, 'seller'), 'user_id'));
			$direct_supervisors = array_map('intval', array_column($this->sn_get_direct_children($user_id, 'supervisor'), 'user_id'));
			$scope_sellers = array_map('intval', array_column($this->sn_get_descendant_users($user_id, 'seller'), 'user_id'));
			$expected_count = count(array_unique(array_merge($direct_sellers, $this->sn_hierarchy_sellers_under_users($direct_supervisors))));
			$report['senior_supervisors'][] = [
				'user_id' => $user_id,
				'label' => $this->sn_user_label($user_id),
				'direct_seller_count' => count($direct_sellers),
				'direct_supervisor_count' => count($direct_supervisors),
				'performance_seller_count' => count($scope_sellers),
				'mismatch' => $expected_count !== count($scope_sellers),
			];
		}
		foreach ($this->sn_hr_all_users_by_position('sales_manager') as $row) {
			$user_id = (int) $row['user_id'];
			$summary = $this->sn_get_hierarchy_scope_summary($user_id);
			$report['sales_managers'][] = ['user_id' => $user_id, 'label' => $this->sn_user_label($user_id), 'descendant_users' => (int) $summary['descendant_user_count'], 'descendant_sellers' => (int) $summary['descendant_seller_count']];
		}
		foreach ($this->sn_hr_all_users_by_position('sales_deputy') as $row) {
			$user_id = (int) $row['user_id'];
			$summary = $this->sn_get_hierarchy_scope_summary($user_id);
			$report['sales_deputy'][] = ['user_id' => $user_id, 'label' => $this->sn_user_label($user_id), 'descendant_users' => (int) $summary['descendant_user_count'], 'descendant_sellers' => (int) $summary['descendant_seller_count']];
		}
		return $report;
	}

	private function sn_hierarchy_sellers_under_users(array $user_ids): array
	{
		$sellers = [];
		foreach (array_values(array_unique(array_map('intval', $user_ids))) as $user_id) {
			$sellers = array_merge($sellers, array_map('intval', array_column($this->sn_get_descendant_users($user_id, 'seller'), 'user_id')));
		}
		return array_values(array_unique($sellers));
	}

	public function handle_distribution_current_structure_preset(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_distribution_current_structure_preset');
		$this->sn_distribution_ensure_schema();
		$this->sn_distribution_ensure_seller_inline_columns();
		global $wpdb;
		$this->sn_ensure_hr_profile_schema_runtime();
		$mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		$now = current_time('mysql');
		$report = ['action' => 'distribution_current_structure_preset', 'mode' => $mode, 'chain_code' => 'current_manager_senior_seller', 'steps' => [['sales_manager', 'senior_supervisor'], ['senior_supervisor', 'seller']], 'saved' => false, 'errors' => [], 'updated_at' => $now];
		if ($mode === 'apply') {
			if ($confirm !== 'APPLY') {
				$report['errors'][] = 'confirmation_required';
			} else {
				$chains = $wpdb->prefix . 'sn_distribution_chains';
				$steps = $wpdb->prefix . 'sn_distribution_chain_steps';
				$wpdb->update($chains, ['is_default' => 0], ['is_default' => 1]);
				$chain_id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$chains} WHERE chain_code=%s", 'current_manager_senior_seller'));
				$data = $this->sn_filter_existing_columns($chains, [
					'chain_code' => 'current_manager_senior_seller',
					'title' => 'ساختار فعلی: مدیر فروش → سرپرست ارشد → فروشنده',
					'description' => 'Preset امن برای ساختار فعلی بدون لایه supervisor.',
					'is_active' => 1,
					'is_default' => 1,
					'updated_at' => $now,
				]);
				if ($chain_id) {
					$wpdb->update($chains, $data, ['id' => $chain_id]);
				} else {
					$data['created_at'] = $now;
					$wpdb->insert($chains, $data);
					$chain_id = (int) $wpdb->insert_id;
				}
				if ($chain_id) {
					$wpdb->update($steps, ['is_active' => 0, 'updated_at' => $now], ['chain_id' => $chain_id]);
					$order = 10;
					foreach ($report['steps'] as $step_pair) {
						$wpdb->insert($steps, $this->sn_filter_existing_columns($steps, [
							'chain_id' => $chain_id,
							'step_order' => $order,
							'from_position_slug' => $step_pair[0],
							'to_position_slug' => $step_pair[1],
							'allow_skip_if_missing' => 1,
							'is_final_delivery_step' => $step_pair[1] === 'seller' ? 1 : 0,
							'creates_live_lead' => 0,
							'is_active' => 1,
							'created_at' => $now,
							'updated_at' => $now,
						]));
						$order += 10;
					}
					$report['saved'] = true;
					$report['chain_id'] = $chain_id;
				} else {
					$report['errors'][] = 'chain_save_failed';
				}
			}
		}
		update_option('sn_distribution_current_structure_preset_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: $this->sn_hr_panel_return_url());
		exit;
	}

	private function sn_hr_panel_top_level_profiles(int $limit): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare("SELECT p.*, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug position_slug FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to' WHERE a.id IS NULL ORDER BY pos.sort_order ASC, p.user_id ASC LIMIT %d", $limit)) ?: [];
	}

	private function sn_hr_panel_assignments(int $limit): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare("SELECT a.*, child.user_id child_user_id, parent.user_id parent_user_id, cp.slug child_position, pp.slug parent_position FROM {$wpdb->prefix}sn_hr_assignments a INNER JOIN {$wpdb->prefix}sn_hr_profiles child ON child.id=a.child_profile_id LEFT JOIN {$wpdb->prefix}sn_hr_positions cp ON cp.id=child.position_id LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id LEFT JOIN {$wpdb->prefix}sn_hr_positions pp ON pp.id=parent.position_id WHERE a.is_current=1 ORDER BY a.created_at DESC, a.id DESC LIMIT %d", $limit)) ?: [];
	}

	private function sn_hr_panel_logs(int $limit): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_hr_profile_logs ORDER BY created_at DESC, id DESC LIMIT %d", $limit)) ?: [];
	}

	private function sn_hr_panel_missing_profile_users(int $limit): array
	{
		$roles = ['sn_seller','sn_supervisor','sn_senior_supervisor','sn_converter','sn_sales_manager','sn_sales_deputy','sn_financial','sn_financial_approval','sn_finance','sn_invoice_reviewer','sn_hr','sn_mis','sn_after_sales','sn_shipping_expert','sn_operations_sales_manager','sn_operations_sales_supervisor','sn_operations_sales_expert','sn_operations_executive_manager','sn_operations_execution_expert','sas_employee','sas_supervisor','sas_senior_supervisor','sas_sales_manager'];
		$users = get_users(['role__in' => $roles, 'number' => max(1, min(1000, $limit)), 'orderby' => 'ID', 'order' => 'ASC']);
		$hr = class_exists('SN_HR_Service') ? new SN_HR_Service() : null;
		return array_values(array_filter($users, static function($user) use ($hr) {
			return $user instanceof WP_User && $hr && ! $hr->get_profile_by_user_id((int) $user->ID);
		}));
	}

	private function sn_hr_panel_render_simple_profiles(array $rows): void
	{
		echo '<div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>نیرو</th><th>نام کاربری</th><th>سمت</th><th>وضعیت</th></tr></thead><tbody>';
		foreach ($rows as $r) {
			echo '<tr><td>' . esc_html($this->sn_user_label((int) $r->user_id)) . '</td><td><code>' . esc_html((string) $r->user_login) . '</code></td><td><span class="sn-hr-badge">' . esc_html((string) $r->position_slug) . '</span></td><td>' . ((int) $r->is_active ? 'فعال' : 'غیرفعال') . '</td></tr>';
		}
		echo '</tbody></table></div>';
	}

	private function sn_can_access_mis_panel(): bool
	{
		if (current_user_can('manage_options')) { return true; }
		if (! is_user_logged_in()) { return false; }
		return $this->sn_fast_hr_position_for_user(get_current_user_id()) === 'mis';
	}

	public function render_mis_panel(): string
	{
		if (! is_user_logged_in()) { return $this->render_unified_panel_login(); }
		if (! $this->sn_can_access_mis_panel()) {
			return '<div class="sn-panel" dir="rtl"><div class="sn-notice sn-error">دسترسی به پنل MIS مجاز نیست.</div></div>';
		}
		global $wpdb;
		$selected_batch_id = absint($_GET['sn_mis_batch_id'] ?? 0);
		$mis_active_tab = $this->sn_requested_ui_active_tab();
		if ($mis_active_tab === '') { $mis_active_tab = 'mis-overview'; }
		$mis_schema_status = [];
		$mis_schema_ready = $this->sn_mis_core_tables_ready_fast();
		$mis_schema_diagnostics_needed = ! $mis_schema_ready || in_array($mis_active_tab, ['mis-import','mis-logs'], true);
		if (class_exists('SN_Migration_Service') && $mis_schema_diagnostics_needed) {
			$service = new SN_Migration_Service();
			if (! $service->mis_tables_complete()) {
				$service->repair_mis_schema();
			}
			$mis_schema_status = $service->mis_schema_status();
			$mis_schema_ready = $service->mis_tables_complete();
		}
		$mis_need_preview = $mis_active_tab === 'mis-preview';
		$mis_need_logs = $mis_active_tab === 'mis-logs';
		$mis_need_distribution = in_array($mis_active_tab, ['mis-distribution','mis-live'], true);
		$mis_need_pool_rows = $mis_active_tab === 'mis-pool';
		$summary = $this->sn_mis_summary();
		$mis_ops = $mis_schema_ready ? $this->sn_mis_operator_pipeline_counts() : [];
		$batches = $mis_schema_ready ? $this->sn_mis_batches(20) : [];
		$batch_ux_stats = $mis_schema_ready ? $this->sn_mis_batch_operational_stats(20) : [];
		$preview = ($mis_need_preview && $mis_schema_ready && $selected_batch_id) ? $this->sn_mis_batch_preview($selected_batch_id, 100) : [];
		$conversion = ($mis_need_preview && $mis_schema_ready && $selected_batch_id) ? $this->sn_mis_conversion_summary($selected_batch_id) : ['imported_rows' => 0, 'matching_leads' => 0, 'matching_invoices' => 0, 'matching_paid_invoices' => 0, 'conversion_percentage' => 0];
		$mis_case_report_filters = [
			'manager_id' => absint($_GET['sn_mis_report_manager_id'] ?? 0),
			'senior_id' => absint($_GET['sn_mis_report_senior_id'] ?? 0),
			'supervisor_id' => absint($_GET['sn_mis_report_supervisor_id'] ?? 0),
			'seller_id' => absint($_GET['sn_mis_report_seller_id'] ?? 0),
			'status' => sanitize_key(wp_unslash($_GET['sn_mis_report_status'] ?? '')),
		];
		$mis_case_report_all_rows = ($mis_need_preview && $mis_schema_ready && $selected_batch_id) ? $this->sn_mis_case_report_rows($selected_batch_id, 1200) : [];
		$mis_case_report_rows = $this->sn_mis_case_report_apply_filters($mis_case_report_all_rows, $mis_case_report_filters);
		$mis_case_report_options = $this->sn_mis_case_report_filter_options($mis_case_report_all_rows);
		$mis_case_report_summary = $this->sn_mis_case_report_summary($mis_case_report_rows);
		$logs = ($mis_need_logs && $mis_schema_ready) ? $this->sn_mis_logs(100) : [];
		$report = get_option('sn_mis_last_report', []);
		$return_assign_report = get_option('sn_mis_return_assignments_report', []);
		if (! is_array($return_assign_report)) { $return_assign_report = []; }
		$delete_batch_report = get_option('sn_mis_delete_batch_report', []);
		if (! is_array($delete_batch_report)) { $delete_batch_report = []; }
		$repair_report = get_option('sn_mis_schema_repair_report', []);
		$pool_report = get_option('sn_mis_lead_pool_report', []);
		$managers = $this->sn_mis_sales_managers();
		$pool_summary = $mis_schema_ready ? $this->sn_mis_lead_pool_summary() : [];
		$pool_filters = [
			'batch_id' => absint($_GET['sn_pool_batch_id'] ?? 0),
			'manager_id' => absint($_GET['sn_pool_manager_id'] ?? 0),
			'status' => sanitize_key(wp_unslash($_GET['sn_pool_status'] ?? '')),
		];
		$pool_rows = ($mis_need_pool_rows && $mis_schema_ready) ? $this->sn_mis_lead_pool_rows($pool_filters, 100) : [];
		$distribution_report = get_option('sn_mis_distribution_plan_report', []);
		$distribution_rules = ($mis_need_distribution && $mis_schema_ready) ? $this->sn_mis_distribution_rules(50) : [];
		$distribution_plans = ($mis_need_distribution && $mis_schema_ready) ? $this->sn_mis_distribution_plans(20) : [];
		$selected_plan_id = absint($_GET['sn_mis_plan_id'] ?? 0);
		$selected_plan_items = ($mis_need_distribution && $mis_schema_ready && $selected_plan_id) ? $this->sn_mis_distribution_plan_items($selected_plan_id, 100) : [];
		$lead_creation_report = get_option('sn_mis_lead_creation_report', []);
		$plan_manager_id = absint($_GET['sn_plan_manager_id'] ?? ($managers[0]->user_id ?? 0));
		$plan_sellers = ($mis_need_distribution && $plan_manager_id) ? $this->sn_mis_sellers_under_manager($plan_manager_id) : [];
		$plan_selected_seller_ids = array_values(array_filter(array_map('intval', (array) ($distribution_report['selected_seller_ids'] ?? []))));
		$launch_checks = ($mis_active_tab === 'mis-overview') ? $this->sn_mis_launch_self_check() : [];
		$is_global_admin = current_user_can('manage_options');
		$is_mis_operator = $this->sn_fast_hr_position_for_user(get_current_user_id()) === 'mis';
		$can_use_mis_advanced_tools = $is_global_admin || $is_mis_operator;
		ob_start();
		?>
		<div id="sn-mis-panel" class="sn-panel sn-portal sn-mis-panel" dir="rtl">
			<div class="sn-panel-header"><h2>پنل MIS</h2><?php echo $this->sn_panel_user_actions_markup(); ?></div>
			<?php
			$mis_tabs = [
				'mis-overview' => 'کار امروز',
				'mis-import' => 'آپلود فایل',
				'mis-batches-list' => 'تخصیص / برگشت',
				'mis-pool' => 'تحویل به فروش',
				'mis-preview' => 'گزارش شماره‌ها',
				'mis-batches' => 'پرونده‌ها',
			];
			if ($can_use_mis_advanced_tools) {
				$mis_tabs['mis-quick'] = 'ابزار سریع';
				$mis_tabs['mis-distribution'] = 'برنامه پخش';
				$mis_tabs['mis-live'] = 'ساخت لید';
				$mis_tabs['mis-logs'] = 'لاگ و عیب‌یابی';
			}
			$this->sn_render_panel_tabs($mis_tabs, 'mis-overview');
			?>
			<section id="mis-overview" class="<?php echo esc_attr($this->sn_tab_panel_class('mis-overview', 'mis-overview')); ?>" data-sn-tab-panel="mis-overview">
			<?php
			$mis_ops = is_array($mis_ops) ? $mis_ops : [];
			$op = static function (string $key) use ($mis_ops): int { return (int) ($mis_ops[$key] ?? 0); };
			$mis_clean_query_keys = ['sn_ui_active_tab','sn_mis_batch_id','sn_pool_batch_id','sn_pool_manager_id','sn_pool_status','sn_mis_report_manager_id','sn_mis_report_senior_id','sn_mis_report_supervisor_id','sn_mis_report_seller_id','sn_mis_report_status'];
			$mis_tab_url = static function (string $tab, array $args = []) use ($mis_clean_query_keys): string {
				return add_query_arg(array_merge(['sn_ui_active_tab' => $tab], $args), remove_query_arg($mis_clean_query_keys)) . '#' . $tab;
			};
			$mis_batch_state = static function (array $stats, object $batch): array {
				$total = (int) ($stats['total_rows'] ?? $batch->total_rows ?? 0);
				$valid = (int) ($stats['valid_rows'] ?? $batch->valid_rows ?? 0);
				$invalid = (int) ($stats['invalid_rows'] ?? $batch->invalid_rows ?? 0);
				$duplicates = (int) ($stats['duplicate_rows'] ?? $batch->duplicate_rows ?? 0);
				$unassigned = (int) ($stats['unassigned_valid'] ?? 0);
				$assigned = (int) ($stats['assigned_to_manager'] ?? 0);
				$eligible_pool = (int) ($stats['eligible_to_pool'] ?? 0);
				$pool_ready = (int) ($stats['pool_ready'] ?? 0);
				$distributed = (int) ($stats['distribution_total'] ?? 0);
				$returnable = (int) ($stats['returnable_with_distribution'] ?? 0);
				if ($total < 1) { return ['label' => 'منتظر آپلود فایل', 'class' => 'sn-status-warning', 'tab' => 'mis-import', 'button' => 'آپلود فایل']; }
				if ($valid < 1 && ($invalid > 0 || $duplicates > 0)) { return ['label' => 'فایل قابل استفاده نیست', 'class' => 'sn-status-rejected', 'tab' => 'mis-import', 'button' => 'اصلاح و آپلود مجدد']; }
				if ($invalid > 0) { return ['label' => 'فایل نیازمند بررسی', 'class' => 'sn-status-warning', 'tab' => 'mis-preview', 'button' => 'دیدن خطاها']; }
				if ($unassigned > 0) { return ['label' => 'آماده تخصیص به مدیر فروش', 'class' => 'sn-status-approved', 'tab' => 'mis-batches-list', 'button' => 'تخصیص بده']; }
				if ($eligible_pool > 0) { return ['label' => 'تخصیص انجام شده؛ آماده تحویل', 'class' => 'sn-status-approved', 'tab' => 'mis-pool', 'button' => 'تحویل به فروش']; }
				if ($pool_ready > 0) { return ['label' => 'در صف آماده فروش', 'class' => 'sn-status', 'tab' => 'mis-pool', 'button' => 'مشاهده صف']; }
				if ($distributed > 0) { return ['label' => $returnable > 0 ? 'دست فروش؛ بخشی قابل برگشت' : 'دست فروش / در حال پیگیری', 'class' => $returnable > 0 ? 'sn-status-warning' : 'sn-status', 'tab' => $returnable > 0 ? 'mis-batches-list' : 'mis-preview', 'button' => $returnable > 0 ? 'برگشت یا گزارش' : 'گزارش بگیر']; }
				if ($assigned > 0) { return ['label' => 'تخصیص‌داده‌شده؛ اقدام بعدی تحویل', 'class' => 'sn-status-approved', 'tab' => 'mis-pool', 'button' => 'آماده‌سازی تحویل']; }
				return ['label' => 'بدون اقدام فوری', 'class' => 'sn-status', 'tab' => 'mis-preview', 'button' => 'گزارش'];
			};
			$focus_batch = null;
			$focus_state = null;
			$state_priority = ['آماده تخصیص به مدیر فروش' => 10, 'تخصیص انجام شده؛ آماده تحویل' => 9, 'فایل نیازمند بررسی' => 8, 'منتظر آپلود فایل' => 7, 'فایل قابل استفاده نیست' => 6, 'دست فروش؛ بخشی قابل برگشت' => 5, 'در صف آماده فروش' => 4, 'دست فروش / در حال پیگیری' => 3, 'تخصیص‌داده‌شده؛ اقدام بعدی تحویل' => 2, 'بدون اقدام فوری' => 1];
			$focus_score = -1;
			foreach ($batches as $candidate_batch) {
				$candidate_state = $mis_batch_state((array) ($batch_ux_stats[(int) $candidate_batch->id] ?? []), $candidate_batch);
				$candidate_score = (int) ($state_priority[$candidate_state['label']] ?? 0);
				if ($candidate_score > $focus_score) {
					$focus_batch = $candidate_batch;
					$focus_state = $candidate_state;
					$focus_score = $candidate_score;
				}
			}
			$import_quality = $op('total_rows') < 1 ? 'هنوز فایلی وارد نشده' : ($op('valid_rows') > 0 && $op('invalid_rows') === 0 && $op('duplicate_rows') === 0 ? 'فایل سالم و قابل استفاده' : 'فایل نیازمند بررسی');
			$today_sentence = 'هنوز پرونده‌ای برای کار MIS ساخته نشده است.';
			$primary_action_title = 'شروع کار';
			$primary_action_body = 'اول یک پرونده بسازید، بعد فایل شماره‌ها را داخل همان پرونده آپلود کنید.';
			$primary_action_button = 'ساخت پرونده';
			$primary_action_url = $mis_tab_url('mis-batches');
			if ($focus_batch && is_array($focus_state)) {
				$focus_stats = (array) ($batch_ux_stats[(int) $focus_batch->id] ?? []);
				$today_sentence = 'پرونده «' . (string) $focus_batch->title . '» الان در وضعیت «' . (string) $focus_state['label'] . '» است.';
				$primary_action_title = (string) $focus_state['label'];
				$primary_action_body = 'روی همین پرونده کار کنید؛ لازم نیست بین گزارش‌های فنی دنبال مرحله بعد بگردید.';
				$primary_action_button = (string) $focus_state['button'];
				$primary_action_url = $mis_tab_url((string) $focus_state['tab'], ['sn_mis_batch_id' => (int) $focus_batch->id, 'sn_pool_batch_id' => (int) $focus_batch->id]);
				if ((int) ($focus_stats['unassigned_valid'] ?? 0) > 0) {
					$primary_action_body = number_format_i18n((int) $focus_stats['unassigned_valid']) . ' شماره سالم بدون مدیر فروش دارد. مرحله درست: تخصیص به مدیر فروش.';
				} elseif ((int) ($focus_stats['eligible_to_pool'] ?? 0) > 0) {
					$primary_action_body = number_format_i18n((int) $focus_stats['eligible_to_pool']) . ' شماره به مدیر فروش وصل شده و آماده تحویل به فروش است.';
				} elseif ((int) ($focus_stats['returnable_with_distribution'] ?? 0) > 0) {
					$primary_action_body = number_format_i18n((int) $focus_stats['returnable_with_distribution']) . ' شماره هنوز لید/فاکتور نشده و قابل برگشت به MIS است.';
				}
			}
			?>
			<div class="sn-card sn-mis-workbench">
				<div class="sn-mis-workbench-hero">
					<div>
						<span class="sn-badge sn-status-approved">میز کار MIS</span>
						<h3>الان باید چه کار کنم؟</h3>
						<p><?php echo esc_html($today_sentence); ?></p>
					</div>
					<div class="sn-mis-primary-action-card">
						<strong><?php echo esc_html($primary_action_title); ?></strong>
						<span><?php echo esc_html($primary_action_body); ?></span>
						<a class="sn-btn sn-btn-primary" href="<?php echo esc_url($primary_action_url); ?>"><?php echo esc_html($primary_action_button); ?></a>
					</div>
				</div>
				<div class="sn-mis-plain-funnel" aria-label="مسیر ساده دیتا">
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('valid_rows'))); ?></strong><span>شماره سالم</span><small>از فایل‌های آپلودشده</small></div>
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('unassigned_valid'))); ?></strong><span>منتظر تخصیص</span><small>باید مدیر فروش بگیرد</small></div>
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('assigned_to_manager'))); ?></strong><span>دست مدیر فروش</span><small>مالک اولیه مشخص شده</small></div>
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('eligible_to_pool') + $op('pool_ready'))); ?></strong><span>آماده تحویل</span><small>قابل ورود به فروش</small></div>
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('distribution_total'))); ?></strong><span>دست تیم فروش</span><small>در زنجیره فروش</small></div>
					<div><strong><?php echo esc_html($this->sn_mis_format_count($op('returnable_with_distribution'))); ?></strong><span>قابل برگشت</span><small>هنوز قفل فروش/فاکتور نشده</small></div>
				</div>
			</div>

			<div class="sn-card sn-mis-simple-board">
				<div class="sn-section-title-row"><h3>پرونده‌ها با زبان عملیاتی</h3><span class="sn-muted">برای هر پرونده فقط یک وضعیت و یک دکمه اصلی نمایش داده می‌شود.</span></div>
				<div class="sn-table-wrap"><table class="sn-table sn-mis-operator-table">
					<thead><tr><th>پرونده</th><th>وضعیت الان</th><th>شماره سالم</th><th>منتظر تخصیص</th><th>دست مدیر</th><th>آماده تحویل</th><th>دست فروش</th><th>قابل برگشت</th><th>کار بعدی</th></tr></thead>
					<tbody>
					<?php if (! $batches) : ?><tr><td colspan="9"><div class="sn-empty-state">هیچ پرونده‌ای وجود ندارد. کار را از دکمه «ساخت پرونده» شروع کنید.</div></td></tr><?php endif; ?>
					<?php foreach (array_slice($batches, 0, 12) as $b) : $b_stats = (array) ($batch_ux_stats[(int) $b->id] ?? []); $b_state = $mis_batch_state($b_stats, $b); $b_action_url = $mis_tab_url((string) $b_state['tab'], ['sn_mis_batch_id' => (int) $b->id, 'sn_pool_batch_id' => (int) $b->id]); ?>
						<tr>
							<td><code><?php echo esc_html((string) $b->batch_code); ?></code><br><strong><?php echo esc_html((string) $b->title); ?></strong></td>
							<td><span class="sn-badge <?php echo esc_attr((string) $b_state['class']); ?>"><?php echo esc_html((string) $b_state['label']); ?></span></td>
							<td><?php echo esc_html($this->sn_mis_format_count($b_stats['valid_rows'] ?? $b->valid_rows)); ?></td>
							<td><?php echo esc_html($this->sn_mis_format_count($b_stats['unassigned_valid'] ?? 0)); ?></td>
							<td><?php echo esc_html($this->sn_mis_format_count($b_stats['assigned_to_manager'] ?? 0)); ?></td>
							<td><?php echo esc_html($this->sn_mis_format_count(((int) ($b_stats['eligible_to_pool'] ?? 0)) + ((int) ($b_stats['pool_ready'] ?? 0)))); ?></td>
							<td><?php echo esc_html($this->sn_mis_format_count($b_stats['distribution_total'] ?? 0)); ?></td>
							<td><?php echo esc_html($this->sn_mis_format_count($b_stats['returnable_with_distribution'] ?? 0)); ?></td>
							<td><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url($b_action_url); ?>"><?php echo esc_html((string) $b_state['button']); ?></a></td>
						</tr>
					<?php endforeach; ?>
					</tbody>
				</table></div>
				<?php if (count($batches) > 12) : ?><p class="sn-note">برای جلوگیری از شلوغی، فقط ۱۲ پرونده اول نمایش داده شد. لیست کامل در تب «پرونده‌ها» است.</p><?php endif; ?>
			</div>

			<div class="sn-card sn-mis-operator-help">
				<h3>ترجمه وضعیت‌ها</h3>
				<div class="sn-mis-guide-grid">
					<div><strong>منتظر تخصیص</strong><span>شماره سالم است، ولی هنوز به هیچ مدیر فروشی وصل نشده. کار درست: تخصیص به مدیر فروش.</span></div>
					<div><strong>دست مدیر فروش</strong><span>مالک مدیر فروش مشخص شده، اما هنوز به فروشنده/زنجیره فروش تحویل نشده.</span></div>
					<div><strong>آماده تحویل</strong><span>شماره آماده ورود به فروش است. کار درست: آماده‌سازی/تحویل به فروش.</span></div>
					<div><strong>قابل برگشت</strong><span>شماره هنوز لید یا فاکتور نشده؛ برگشت یعنی مالک فعلی حذف می‌شود و دوباره به «منتظر تخصیص» برمی‌گردد.</span></div>
				</div>
			</div>

			<details class="sn-card sn-mis-secondary-details"><summary><strong>جزئیات بیشتر / آخرین آپلود</strong></summary>
			<div class="sn-mis-top-summary">
				<div class="sn-dashboard-grid sn-mis-dashboard-grid"><?php foreach ($summary as $label => $value) : ?><div class="sn-card sn-mis-stat-card"><strong><?php echo esc_html((string) $value); ?></strong><span><?php echo esc_html((string) $label); ?></span></div><?php endforeach; ?></div>
				<div class="sn-card sn-mis-last-import-card">
					<h3>آخرین ورود فایل</h3>
					<?php if ($report && is_array($report)) : ?>
						<p class="sn-readable-summary"><?php echo esc_html($this->sn_mis_report_summary($report)); ?></p>
						<div class="sn-mis-result-badges">
							<span class="sn-badge">کل: <?php echo esc_html((string) (int) ($report['rows_seen'] ?? $report['total_rows'] ?? 0)); ?></span>
							<span class="sn-badge sn-status-approved">معتبر: <?php echo esc_html((string) (int) ($report['valid'] ?? $report['valid_rows'] ?? 0)); ?></span>
							<span class="sn-badge sn-status-warning">تکراری: <?php echo esc_html((string) (int) ($report['duplicate'] ?? 0)); ?></span>
							<span class="sn-badge sn-status-rejected">نامعتبر: <?php echo esc_html((string) (int) ($report['invalid'] ?? $report['invalid_rows'] ?? 0)); ?></span>
						</div>
						<?php if (! empty($report['operator_message'])) : ?><div class="sn-alert"><?php echo esc_html((string) $report['operator_message']); ?></div><?php endif; ?>
					<?php else : ?>
						<p class="sn-note">هنوز گزارشی از ورود فایل ثبت نشده است.</p>
					<?php endif; ?>
				</div>
			</div>

			<div class="sn-card sn-mis-operator-guide sn-mis-guide-compact">
				<h3>راهنمای کوتاه مسیر MIS</h3>
				<div class="sn-mis-guide-grid">
					<div><strong>۱. پرونده</strong><span>برای هر فایل یک پرونده بسازید؛ تخصیص‌ها در حال حاضر بر اساس پرونده انجام می‌شوند.</span></div>
					<div><strong>۲. ورود فایل</strong><span>فایل Excel/CSV وارد می‌شود و نتیجه معتبر، تکراری و نامعتبر واضح نمایش داده می‌شود.</span></div>
					<div><strong>۳. اختصاص مدیر</strong><span>ردیف‌های معتبر به مدیر فروش وصل می‌شوند تا مالک اولیه دیتا مشخص باشد.</span></div>
					<div><strong>۴. آماده‌سازی و تحویل</strong><span>داده آماده وارد صف توزیع می‌شود و بعد به زنجیره فروش تحویل داده می‌شود.</span></div>
