			<?php if ($can_use_mis_advanced_tools) : ?>
			<div class="sn-card sn-section sn-mis-launch-check">
				<h3 class="sn-section-title">تست و عیب‌یابی مدیرکل</h3>
				<div class="sn-table-wrap sn-hr-change-table"><table class="sn-table"><thead><tr><th>مرحله</th><th>وضعیت</th><th>عدد/خلاصه</th><th>اقدام بعدی</th></tr></thead><tbody>
				<?php foreach ($launch_checks as $check) : ?><tr><td><?php echo esc_html((string) $check['label']); ?></td><td><span class="sn-badge <?php echo ! empty($check['ok']) ? 'sn-status-approved' : 'sn-status'; ?>"><?php echo ! empty($check['ok']) ? 'PASS' : 'نیازمند اقدام'; ?></span></td><td><?php echo esc_html((string) $check['count']); ?></td><td><?php echo esc_html((string) $check['next']); ?></td></tr><?php endforeach; ?>
