			<details class="sn-card"><summary><strong>وضعیت جدول‌های MIS</strong></summary>
				<table class="sn-table"><thead><tr><th>جدول</th><th>وجود دارد؟</th><th>تعداد ردیف</th><th>وضعیت آخرین بازسازی</th><th>آخرین خطا</th></tr></thead><tbody>
				<?php foreach ($mis_schema_status as $table => $info) : $last_error = $this->sn_mis_last_table_error($table, is_array($repair_report) ? $repair_report : []); ?><tr><td><code><?php echo esc_html($table); ?></code></td><td><?php echo ! empty($info['exists']) ? 'بله' : 'خیر'; ?></td><td><?php echo esc_html((string) (int) ($info['rows'] ?? 0)); ?></td><td><?php echo empty($last_error) ? 'سالم' : 'خطا'; ?></td><td><?php echo esc_html($last_error ?: '—'); ?></td></tr><?php endforeach; ?>
