	private function sn_current_user_can_senior_supervisor_panel(): bool
	{
		if (! is_user_logged_in()) {
			return false;
		}
		$user_id = get_current_user_id();
		return current_user_can('manage_options') || $this->sn_fast_hr_position_for_user($user_id) === 'senior_supervisor';
	}

	private function sn_senior_supervisor_lazy_placeholder(string $tab, string $title, string $message): void
	{
		?>
		<div class="sn-card sn-senior-lazy-placeholder" data-sn-senior-placeholder="<?php echo esc_attr($tab); ?>">
			<h3><?php echo esc_html($title); ?></h3>
			<p class="sn-note"><?php echo esc_html($message); ?></p>
			<div class="sn-loading">در حال آماده‌سازی...</div>
		</div>
		<?php
	}

	public function ajax_senior_supervisor_lazy_tab(): void
	{
		$started = microtime(true);
		try {
			if (function_exists('set_time_limit')) { @set_time_limit(25); }
			if (! check_ajax_referer('sn_public', 'nonce', false)) {
				wp_send_json_error(['message' => 'اعتبار نشست منقضی شده است؛ صفحه را تازه‌سازی کنید.'], 403);
			}
			if (! $this->sn_current_user_can_senior_supervisor_panel()) {
				wp_send_json_error(['message' => 'دسترسی غیرمجاز'], 403);
			}
			$tab = sanitize_key(wp_unslash($_POST['tab'] ?? ''));
			$user_id = get_current_user_id();
			ob_start();
			switch ($tab) {
				case 'ss-overview':
					$this->sn_render_senior_supervisor_overview_tab($user_id);
					break;
				case 'ss-team':
					$this->sn_render_senior_supervisor_team_tab($user_id);
					break;
				case 'ss-distribution':
					echo '<div id="sn-tab-assign">';
					$this->sn_render_supervisor_progressive_assign_tab($user_id);
					echo '</div>';
					break;
				case 'ss-sellers':
					$this->sn_render_senior_supervisor_sellers_tab($user_id);
					break;
				case 'ss-invoices':
					$this->sn_render_supervisor_progressive_invoice_tab($user_id);
					break;
				case 'ss-payment-actions':
					$this->sn_render_paid_referral_action_section($user_id, 'senior_supervisor');
					break;
				case 'ss-repeat-actions':
					if (class_exists('SN_Dot_Flow')) { SN_Dot_Flow::instance()->render_supervisor_ready_tab($user_id, true); }
					break;
				case 'ss-converter-stats':
					if (class_exists('SN_Dot_Flow')) { SN_Dot_Flow::instance()->render_supervisor_converters_tab($user_id); }
					break;
				case 'ss-my-conversions':
					if (class_exists('SN_Dot_Flow')) { echo SN_Dot_Flow::instance()->render_converter_panel('supervisor'); }
					break;
				case 'ss-hr-requests':
					$this->sn_hr_change_request_render_section($user_id, 'senior_supervisor');
					break;
				case 'ss-leads':
					$this->sn_render_senior_supervisor_leads_tab($user_id);
					break;
				default:
					wp_send_json_error(['message' => 'تب نامعتبر است'], 400);
			}
			$html = ob_get_clean();
			wp_send_json_success([
				'html' => $html,
				'elapsed_ms' => (int) round((microtime(true) - $started) * 1000),
			]);
		} catch (Throwable $e) {
			while (ob_get_level() > 0) { @ob_end_clean(); }
			error_log('SN ajax_senior_supervisor_lazy_tab failed: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
			wp_send_json_error(['message' => 'خطای داخلی در بارگذاری این بخش رخ داد. جزئیات در لاگ سرور ثبت شد.'], 500);
		}
	}

