	private function sn_senior_supervisor_user_map(array $user_ids): array
	{
		global $wpdb;
		$user_ids = array_values(array_unique(array_filter(array_map('intval', $user_ids))));
		if (! $user_ids) { return []; }
		$out = [];
		foreach (array_chunk($user_ids, 500) as $chunk) {
			$ph = implode(',', array_fill(0, count($chunk), '%d'));
			$rows = $wpdb->get_results($wpdb->prepare("SELECT ID, display_name, user_login FROM {$wpdb->users} WHERE ID IN ({$ph})", ...$chunk), ARRAY_A) ?: [];
			foreach ($rows as $row) {
				$id = (int) ($row['ID'] ?? 0);
				if ($id < 1) { continue; }
				$label = trim((string) ($row['display_name'] ?? ''));
				if ($label === '') { $label = trim((string) ($row['user_login'] ?? '')); }
				$out[$id] = $label !== '' ? $label : '#' . $id;
			}
		}
		return $out;
	}

	private function sn_senior_supervisor_active_map(array $user_ids): array
	{
		global $wpdb;
		$user_ids = array_values(array_unique(array_filter(array_map('intval', $user_ids))));
		$out = array_fill_keys($user_ids, true);
		foreach (array_chunk($user_ids, 500) as $chunk) {
			if (! $chunk) { continue; }
			$ph = implode(',', array_fill(0, count($chunk), '%d'));
			$rows = $wpdb->get_results($wpdb->prepare("SELECT user_id, meta_value FROM {$wpdb->usermeta} WHERE meta_key='sn_is_active' AND user_id IN ({$ph})", ...$chunk), ARRAY_A) ?: [];
			foreach ($rows as $row) { $out[(int) $row['user_id']] = (string) $row['meta_value'] !== '0'; }
		}
		return $out;
	}

