	private function sn_render_senior_supervisor_team_tab(int $viewer_id): void
	{
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$profile = $hr->get_profile_by_user_id($viewer_id);
		$visible = $this->sn_get_seller_ids_in_hr_scope($viewer_id);
		$direct_profiles = $profile ? $hierarchy->get_direct_children_profile_ids((int) $profile->id) : [];
		$direct_sellers = array_values(array_intersect($visible, array_map('intval', array_column($this->sn_get_direct_children($viewer_id, 'seller'), 'user_id'))));
		$supervisors = $this->sn_senior_supervisor_direct_supervisors($direct_profiles);
		$indirect = array_values(array_diff($visible, $direct_sellers));
		$labels = $this->sn_senior_supervisor_user_map(array_merge($visible, array_column($supervisors, 'user_id')));
		$active = $this->sn_senior_supervisor_active_map($visible);
