	private function sn_senior_supervisor_filters(): array
	{
		$source = wp_unslash($_REQUEST);
		return [
			'date_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field($source['sn_ss_date_from'] ?? '')),
			'date_to' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field($source['sn_ss_date_to'] ?? '')),
			'seller_id' => absint($source['sn_ss_seller'] ?? 0),
			'invoice_status' => sanitize_key($source['sn_ss_invoice_status'] ?? ''),
			'lead_status' => sanitize_text_field($source['sn_ss_lead_status'] ?? ''),
			'invoice_code' => sanitize_text_field($source['sn_ss_invoice_code'] ?? ''),
		];
	}

	private function sn_senior_supervisor_filtered_seller_ids(array $visible_seller_ids, array $filters): array
	{
		$ids = array_values(array_unique(array_map('intval', $visible_seller_ids)));
		$seller_id = (int) ($filters['seller_id'] ?? 0);
		if ($seller_id && in_array($seller_id, $ids, true)) {
			return [$seller_id];
		}
		if ($seller_id) {
			return [];
		}
		return $ids;
	}

	private function sn_senior_supervisor_direct_supervisors(array $direct_child_profiles): array
	{
		global $wpdb;
		$profile_ids = array_values(array_unique(array_filter(array_map('intval', $direct_child_profiles))));
		if (! $profile_ids) { return []; }
		$rows = [];
		foreach (array_chunk($profile_ids, 500) as $chunk) {
			$ph = implode(',', array_fill(0, count($chunk), '%d'));
			$rows = array_merge($rows, $wpdb->get_results($wpdb->prepare(
				"SELECT p.id profile_id, p.user_id FROM {$wpdb->prefix}sn_hr_profiles p INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id WHERE p.id IN ({$ph}) AND pos.slug='supervisor'",
				...$chunk
			), ARRAY_A) ?: []);
		}
		$out = [];
		foreach ($rows as $row) {
			$user_id = (int) ($row['user_id'] ?? 0);
			if ($user_id < 1) { continue; }
			$descendant_profiles = $this->sn_hr_descendant_profile_ids_for_user($user_id, 20);
			$seller_ids = $this->sn_sales_deputy_seller_ids_for_profiles($descendant_profiles);
			$out[] = ['user_id' => $user_id, 'seller_count' => count(array_unique(array_map('intval', $seller_ids)))];
		}
		return $out;
	}

	private function sn_senior_supervisor_seller_rows(array $seller_ids, array $filters): array
	{
		global $wpdb;
		$seller_ids = array_values(array_unique(array_filter(array_map('intval', $seller_ids))));
		if (! $seller_ids) { return []; }
		$labels = $this->sn_senior_supervisor_user_map($seller_ids);
		$active_map = $this->sn_senior_supervisor_active_map($seller_ids);
		$lead_map = [];
		[$lead_where, $lead_args] = $this->sn_senior_supervisor_lead_where($seller_ids, $filters, 'l');
		$lead_sql = "SELECT l.seller_id, COUNT(*) total FROM {$wpdb->prefix}sn_leads l WHERE {$lead_where} GROUP BY l.seller_id";
		foreach (($wpdb->get_results($lead_args ? $wpdb->prepare($lead_sql, ...$lead_args) : $lead_sql, ARRAY_A) ?: []) as $row) {
			$lead_map[(int) $row['seller_id']] = (int) $row['total'];
		}

		$invoice_map = [];
		[$invoice_where, $invoice_args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		$invoice_sql = "SELECT i.seller_id,
			COUNT(*) invoices,
			SUM(CASE WHEN (i.status IN ('pending','draft','unpaid') OR COALESCE(i.status,'')='') THEN 1 ELSE 0 END) pre_invoices,
			SUM(CASE WHEN (i.status IN ('paid','approved') OR i.invoice_status IN ('paid','approved') OR i.payment_status IN ('paid','approved')) THEN 1 ELSE 0 END) paid_invoices,
			SUM(CASE WHEN (i.status IN ('rejected','returned','return') OR i.invoice_status IN ('rejected','returned','return') OR i.payment_status IN ('rejected','returned','return')) THEN 1 ELSE 0 END) rejected_invoices,
			COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) total_amount,
			MAX(i.created_at) latest_invoice_date
			FROM {$wpdb->prefix}sn_invoices i WHERE {$invoice_where} GROUP BY i.seller_id";
		foreach (($wpdb->get_results($invoice_args ? $wpdb->prepare($invoice_sql, ...$invoice_args) : $invoice_sql, ARRAY_A) ?: []) as $row) {
			$invoice_map[(int) $row['seller_id']] = $row;
		}

		$payment_map = [];
		$payment_where = $invoice_where . " AND p.status IN ('paid','approved','verified','success')";
		$payment_sql = "SELECT i.seller_id, COALESCE(SUM(p.amount),0) paid_amount FROM {$wpdb->prefix}sn_payments p INNER JOIN {$wpdb->prefix}sn_invoices i ON i.id=p.invoice_id WHERE {$payment_where} GROUP BY i.seller_id";
		foreach (($wpdb->get_results($invoice_args ? $wpdb->prepare($payment_sql, ...$invoice_args) : $payment_sql, ARRAY_A) ?: []) as $row) {
			$payment_map[(int) $row['seller_id']] = (float) $row['paid_amount'];
		}

		$rows = [];
		foreach ($seller_ids as $seller_id) {
			$inv = $invoice_map[$seller_id] ?? [];
			$rows[] = [
				'seller_id' => $seller_id,
				'label' => $labels[$seller_id] ?? ('#' . $seller_id),
				'status' => ! empty($active_map[$seller_id]) ? 'فعال' : 'غیرفعال',
				'leads' => (int) ($lead_map[$seller_id] ?? 0),
				'invoices' => (int) ($inv['invoices'] ?? 0),
				'pre_invoices' => (int) ($inv['pre_invoices'] ?? 0),
				'paid_invoices' => (int) ($inv['paid_invoices'] ?? 0),
				'rejected_invoices' => (int) ($inv['rejected_invoices'] ?? 0),
				'total_amount' => (float) ($inv['total_amount'] ?? 0),
				'paid_amount' => (float) ($payment_map[$seller_id] ?? 0),
				'latest_invoice_date' => (string) ($inv['latest_invoice_date'] ?? ''),
			];
		}
		return $rows;
	}

	private function sn_senior_supervisor_summary(array $seller_ids, array $filters): array
	{
		global $wpdb;
		$seller_ids = array_values(array_unique(array_filter(array_map('intval', $seller_ids))));
		$status_counts = $this->sn_sales_deputy_seller_status_counts($seller_ids);
		$lead_count = $this->sn_senior_supervisor_count_leads($seller_ids, $filters);
		[$where, $args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		$sql = "SELECT COUNT(*) total,
			SUM(CASE WHEN (i.status IN ('pending','draft','unpaid') OR COALESCE(i.status,'')='') THEN 1 ELSE 0 END) pre_count,
			SUM(CASE WHEN (i.status IN ('paid','approved') OR i.invoice_status IN ('paid','approved') OR i.payment_status IN ('paid','approved')) THEN 1 ELSE 0 END) paid_count,
			SUM(CASE WHEN (i.status IN ('rejected','returned','return') OR i.invoice_status IN ('rejected','returned','return') OR i.payment_status IN ('rejected','returned','return')) THEN 1 ELSE 0 END) rejected_count,
			COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) total_amount
			FROM {$wpdb->prefix}sn_invoices i WHERE {$where}";
		$invoice = $wpdb->get_row($args ? $wpdb->prepare($sql, ...$args) : $sql, ARRAY_A) ?: [];
		$paid_amount = $this->sn_senior_supervisor_sum_payments($seller_ids, $filters);
		return [
			'کل فروشنده‌های قابل مشاهده' => number_format_i18n(count($seller_ids)),
			'فروشنده فعال' => number_format_i18n($status_counts['active']),
			'فروشنده غیرفعال' => number_format_i18n($status_counts['inactive']),
			'کل لیدها' => number_format_i18n($lead_count),
			'کل فاکتورها' => number_format_i18n((int) ($invoice['total'] ?? 0)),
			'پیش‌فاکتور' => number_format_i18n((int) ($invoice['pre_count'] ?? 0)),
			'فاکتور paid/approved' => number_format_i18n((int) ($invoice['paid_count'] ?? 0)),
			'فاکتور rejected/returned' => number_format_i18n((int) ($invoice['rejected_count'] ?? 0)),
			'مبلغ کل فاکتورها' => SN_Helpers::format_price((float) ($invoice['total_amount'] ?? 0)),
			'مبلغ پرداخت‌شده' => SN_Helpers::format_price($paid_amount),
		];
	}

	private function sn_senior_supervisor_invoice_where(array $seller_ids, array $filters, string $alias = 'i'): array
	{
		[$where, $args] = $this->sn_sales_deputy_invoice_where($seller_ids, $filters, $alias);
		if (! empty($filters['invoice_code'])) {
			$where .= " AND {$alias}.invoice_code LIKE %s";
			$args[] = '%' . $GLOBALS['wpdb']->esc_like((string) $filters['invoice_code']) . '%';
		}
		return [$where, $args];
	}

	private function sn_senior_supervisor_recent_invoices(array $seller_ids, array $filters): array
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		$sql = "SELECT i.invoice_code, i.status, i.invoice_status, i.payment_status, COALESCE(i.final_total,i.product_price,0) amount, i.created_at, COALESCE(u.display_name, CONCAT('#', i.seller_id)) seller_name
			FROM {$wpdb->prefix}sn_invoices i
			LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id
			WHERE {$where}
			ORDER BY i.created_at DESC, i.id DESC
			LIMIT 20";
		return $wpdb->get_results($args ? $wpdb->prepare($sql, ...$args) : $sql, ARRAY_A) ?: [];
	}

	private function sn_senior_supervisor_count_invoices(array $seller_ids, array $filters, string $bucket = ''): int
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		if ($bucket === 'paid') {
			$where .= " AND (i.status IN ('paid','approved') OR i.invoice_status IN ('paid','approved') OR i.payment_status IN ('paid','approved'))";
		} elseif ($bucket === 'rejected') {
			$where .= " AND (i.status IN ('rejected','returned','return') OR i.invoice_status IN ('rejected','returned','return') OR i.payment_status IN ('rejected','returned','return'))";
		} elseif ($bucket === 'pre_invoice') {
			$where .= " AND (i.status IN ('pending','draft','unpaid') OR COALESCE(i.status,'')='')";
		}
		$sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}";
		return (int) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_senior_supervisor_sum_invoices(array $seller_ids, array $filters): float
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		$sql = "SELECT COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}";
		return (float) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_senior_supervisor_sum_payments(array $seller_ids, array $filters): float
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_invoice_where($seller_ids, $filters, 'i');
		$where .= " AND p.status IN ('paid','approved','verified','success')";
		$sql = "SELECT COALESCE(SUM(p.amount),0) FROM {$wpdb->prefix}sn_payments p INNER JOIN {$wpdb->prefix}sn_invoices i ON i.id=p.invoice_id WHERE {$where}";
		return (float) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_senior_supervisor_lead_where(array $seller_ids, array $filters, string $alias = 'l'): array
	{
		[$where, $args] = $this->sn_sales_deputy_lead_where($seller_ids, $filters, $alias);
		if (! empty($filters['lead_status'])) {
			$where .= " AND ({$alias}.lead_status=%s OR {$alias}.status=%s)";
			$args[] = (string) $filters['lead_status'];
			$args[] = (string) $filters['lead_status'];
		}
		return [$where, $args];
	}

	private function sn_senior_supervisor_count_leads(array $seller_ids, array $filters): int
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_lead_where($seller_ids, $filters, 'l');
		$sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads l WHERE {$where}";
		return (int) $wpdb->get_var($args ? $wpdb->prepare($sql, ...$args) : $sql);
	}

	private function sn_senior_supervisor_lead_status_summary(array $seller_ids, array $filters): array
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_lead_where($seller_ids, $filters, 'l');
		$sql = "SELECT COALESCE(NULLIF(l.lead_status,''), l.status, 'unknown') status_label, COUNT(*) count FROM {$wpdb->prefix}sn_leads l WHERE {$where} GROUP BY status_label ORDER BY count DESC LIMIT 20";
		return $wpdb->get_results($args ? $wpdb->prepare($sql, ...$args) : $sql, ARRAY_A) ?: [];
	}

	private function sn_senior_supervisor_recent_leads(array $seller_ids, array $filters): array
	{
		global $wpdb;
		[$where, $args] = $this->sn_senior_supervisor_lead_where($seller_ids, $filters, 'l');
		$lead_cols = $this->sn_table_columns($wpdb->prefix . 'sn_leads');
		$customer_select = in_array('customer_name', $lead_cols, true) ? 'l.customer_name' : "'' AS customer_name";
		$updated_select = in_array('updated_at', $lead_cols, true) ? 'l.updated_at' : (in_array('assigned_at', $lead_cols, true) ? 'l.assigned_at AS updated_at' : 'NULL AS updated_at');
		$sql = "SELECT l.id, l.phone, {$customer_select}, l.status, l.lead_status, {$updated_select}, COALESCE(u.display_name, CONCAT('#', l.seller_id)) seller_name
			FROM {$wpdb->prefix}sn_leads l
			LEFT JOIN {$wpdb->users} u ON u.ID=l.seller_id
			WHERE {$where}
			ORDER BY updated_at DESC, l.id DESC
			LIMIT 20";
		return $wpdb->get_results($args ? $wpdb->prepare($sql, ...$args) : $sql, ARRAY_A) ?: [];
	}

