	private function sn_sales_manager_scope_seller_ids(int $manager_user_id): array
	{
		if (current_user_can('manage_options') || is_super_admin($manager_user_id)) {
			$ids = array_map('intval', array_column($this->sn_hr_all_users_by_position('seller'), 'user_id'));
			$legacy = array_map('intval', get_users(['role' => 'sn_seller', 'fields' => 'ID']));
			return array_values(array_unique(array_filter(array_merge($ids, $legacy))));
		}
		$ids = array_map('intval', array_column($this->sn_get_descendant_users($manager_user_id, 'seller'), 'user_id'));
		$direct = array_map('intval', array_column($this->sn_get_direct_children($manager_user_id, 'seller'), 'user_id'));
		return array_values(array_unique(array_filter(array_merge($ids, $direct))));
	}

	private function sn_sales_manager_scope_user_ids(int $manager_user_id): array
	{
		if (current_user_can('manage_options') || is_super_admin($manager_user_id)) {
			$ids = [];
			foreach (['sales_manager', 'senior_supervisor', 'supervisor', 'seller'] as $position) {
				$ids = array_merge($ids, array_map('intval', array_column($this->sn_hr_all_users_by_position($position), 'user_id')));
			}
			return array_values(array_unique(array_filter($ids)));
		}
		$ids = [$manager_user_id];
		foreach (['senior_supervisor', 'supervisor', 'seller'] as $position) {
			$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_descendant_users($manager_user_id, $position), 'user_id')));
			$ids = array_merge($ids, array_map('intval', array_column($this->sn_get_direct_children($manager_user_id, $position), 'user_id')));
		}
		return array_values(array_unique(array_filter($ids)));
	}

	private function sn_sales_manager_invoice_rows(int $manager_user_id, int $limit = 80): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_invoices';
		if (! $this->sn_table_exists_quiet($table)) {
			return [];
		}
		$limit = max(1, min(300, $limit));
		$columns = $this->sn_table_columns($table);
		$seller_ids = $this->sn_sales_manager_scope_seller_ids($manager_user_id);
		$where = ['1=1'];
		$args = [];
		$owner_fields = array_values(array_intersect(['seller_id', 'original_seller_id', 'commission_seller_id', 'seller_user_id', 'sales_user_id', 'lead_seller_id', 'assigned_seller_id'], $columns));
		if (! current_user_can('manage_options')) {
			if (! $seller_ids || ! $owner_fields) {
				return [];
			}
			$field_parts = [];
			foreach ($owner_fields as $field) {
				$field_parts[] = "i.{$field} IN (" . implode(',', array_fill(0, count($seller_ids), '%d')) . ')';
				$args = array_merge($args, $seller_ids);
			}
			$where[] = '(' . implode(' OR ', $field_parts) . ')';
		}
		$select = ['i.*'];
		$seller_name_field = in_array('seller_id', $columns, true) ? "COALESCE(NULLIF(hp.hr_display_name,''), u.display_name) seller_name" : "'' seller_name";
		$select[] = $seller_name_field;
		$join = in_array('seller_id', $columns, true) ? " LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id LEFT JOIN {$wpdb->prefix}sn_hr_profiles hp ON hp.user_id=i.seller_id AND hp.is_active=1" : '';
		$sql = 'SELECT ' . implode(', ', $select) . " FROM {$table} i{$join} WHERE " . implode(' AND ', $where) . ' ORDER BY i.id DESC LIMIT %d';
		$args[] = $limit;
		return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
	}

	private function sn_sales_manager_render_invoice_table(array $rows): void
	{
		echo '<div class="sn-card"><h3>فاکتورهای محدوده مدیر فروش</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>کد فاکتور</th><th>فروشنده</th><th>مشتری</th><th>مبلغ</th><th>روش پرداخت</th><th>وضعیت</th><th>تاریخ</th></tr></thead><tbody>';
		if (! $rows) {
			echo '<tr><td colspan="7"><div class="sn-empty-state">فاکتوری در محدوده این مدیر فروش پیدا نشد.</div></td></tr>';
		}
		foreach ($rows as $row) {
			$amount = (float) ($row['final_total'] ?? $row['product_price'] ?? $row['paid_amount'] ?? 0);
			$payment_status = (string) ($row['payment_status'] ?? '');
			$invoice_status = (string) ($row['invoice_status'] ?? '');
			$status = $payment_status !== '' ? $payment_status : ($invoice_status !== '' ? $invoice_status : (string) ($row['status'] ?? ''));
			$date = (string) ($row['approved_at'] ?? $row['paid_at'] ?? $row['created_at'] ?? '');
			echo '<tr>';
			echo '<td><code>' . esc_html((string) ($row['invoice_code'] ?? ('#' . (int) ($row['id'] ?? 0)))) . '</code></td>';
			echo '<td>' . esc_html((string) ($row['seller_name'] ?? ($row['seller_id'] ?? '—'))) . '</td>';
			echo '<td>' . esc_html(trim((string) ($row['customer_name'] ?? '') . ' ' . (string) ($row['customer_phone'] ?? ''))) . '</td>';
			echo '<td>' . esc_html(SN_Helpers::format_price($amount)) . '</td>';
			echo '<td>' . esc_html(SN_Helpers::pay_method_label((string) ($row['pay_method'] ?? ''))) . '</td>';
			echo '<td><span class="sn-status">' . esc_html(SN_Helpers::status_label($status)) . '</span></td>';
			echo '<td>' . esc_html($date !== '' ? SN_Helpers::gregorian_to_jalali_date($date) : '—') . '</td>';
			echo '</tr>';
		}
		echo '</tbody></table></div></div>';
	}

	private function sn_sales_manager_v4_report_rows(int $manager_user_id, array $filters, int $limit = 100): array
	{
		global $wpdb;
		if (! $this->sn_distribution_tables_ready()) {
			return [];
		}
		$item_table = $wpdb->prefix . 'sn_distribution_items';
		$limit = max(1, min(2000, $limit));
		$scope_user_ids = $this->sn_sales_manager_scope_user_ids($manager_user_id);
		$where = ['1=1'];
		$args = [];
		if (! current_user_can('manage_options')) {
			if (! $scope_user_ids) {
				return [];
			}
			$where[] = '(di.current_owner_user_id IN (' . implode(',', array_fill(0, count($scope_user_ids), '%d')) . ') OR di.final_seller_user_id IN (' . implode(',', array_fill(0, count($scope_user_ids), '%d')) . '))';
			$args = array_merge($args, $scope_user_ids, $scope_user_ids);
		}
		$excluded = ['archived','cancelled','duplicate','error'];
		$where[] = "(di.status IS NULL OR di.status='' OR di.status NOT IN (" . implode(',', array_fill(0, count($excluded), '%s')) . '))';
		$args = array_merge($args, $excluded);
		if (! empty($filters['search'])) {
			$like = '%' . $wpdb->esc_like((string) $filters['search']) . '%';
			$where[] = '(COALESCE(p.normalized_phone,r.normalized_phone) LIKE %s OR COALESCE(p.customer_phone,r.customer_phone) LIKE %s OR COALESCE(p.customer_name,r.customer_name) LIKE %s OR COALESCE(p.city,r.city) LIKE %s OR COALESCE(p.province,r.province) LIKE %s OR b.batch_code LIKE %s)';
			$args = array_merge($args, [$like, $like, $like, $like, $like, $like]);
		}
		if (! empty($filters['import_code'])) {
			$where[] = 'b.batch_code = %s';
			$args[] = (string) $filters['import_code'];
		}
		if (! empty($filters['status']) && (string) $filters['status'] !== 'all') {
			$st = sanitize_key((string) $filters['status']);
			if ($st === 'unassigned') { $where[] = "di.current_owner_position IN ('sales_manager','senior_supervisor','supervisor') AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)"; }
			elseif ($st === 'supervisor_pool') { $where[] = "di.current_owner_position IN ('senior_supervisor','supervisor') AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)"; }
			elseif ($st === 'assigned') { $where[] = "(di.final_seller_user_id IS NOT NULL AND di.final_seller_user_id>0)"; }
			elseif ($st === 'invoiced') { $where[] = "((di.live_lead_id IS NOT NULL AND di.live_lead_id>0) OR di.status IN ('invoiced','seller_invoice_created','live_lead_created'))"; }
		}
		if (! empty($filters['assignment']) && (string) $filters['assignment'] !== 'all') {
			$as = sanitize_key((string) $filters['assignment']);
			if ($as === 'unassigned') { $where[] = "di.current_owner_position='sales_manager' AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)"; }
			elseif ($as === 'supervisor_pool') { $where[] = "di.current_owner_position IN ('senior_supervisor','supervisor') AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)"; }
			elseif ($as === 'assigned') { $where[] = "(di.final_seller_user_id IS NOT NULL AND di.final_seller_user_id>0)"; }
		}
		if (! empty($filters['supervisor_id'])) {
			$where[] = 'di.current_owner_user_id=%d';
			$args[] = (int) $filters['supervisor_id'];
		}
		if (! empty($filters['seller_id'])) {
			$where[] = '(di.current_owner_user_id=%d OR di.final_seller_user_id=%d)';
			$args[] = (int) $filters['seller_id'];
			$args[] = (int) $filters['seller_id'];
		}
		$sql = "SELECT di.*, COALESCE(p.customer_name,r.customer_name) customer_name, COALESCE(p.customer_phone,r.customer_phone) customer_phone, COALESCE(p.normalized_phone,r.normalized_phone) normalized_phone, COALESCE(p.province,r.province) province, COALESCE(p.city,r.city) city, b.batch_code
			FROM {$item_table} di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)
			WHERE " . implode(' AND ', $where) . ' ORDER BY di.updated_at DESC, di.id DESC LIMIT %d';
		$args[] = $limit;
		$rows = $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
		$items = [];
		foreach ($rows as $row) {
			$owner_id = (int) ($row['current_owner_user_id'] ?? 0);
			$seller_id = (int) ($row['final_seller_user_id'] ?: ($row['current_owner_position'] === 'seller' ? $owner_id : 0));
			$items[] = [
				'id' => 'v4-' . (int) ($row['id'] ?? 0),
				'phone' => (string) ($row['normalized_phone'] ?: $row['customer_phone'] ?: ''),
				'province' => (string) ($row['province'] ?? ''),
				'city' => (string) ($row['city'] ?? ''),
				'status' => (string) ($row['status'] ?? ''),
				'status_label' => 'V4: ' . $this->sn_portal_status_label((string) ($row['status'] ?? '')),
				'lead_status' => '',
				'import_code' => (string) ($row['batch_code'] ?? ''),
				'supervisor_name' => $owner_id ? $this->sn_user_label($owner_id) : '—',
				'seller_name' => $seller_id ? $this->sn_user_label($seller_id) : '—',
				'imported_at' => (string) ($row['created_at'] ?? ''),
				'assigned_at' => (string) ($row['updated_at'] ?? ''),
			];
		}
		return $items;
	}


	/**
	 * 1.0.126: ultra-fast sales-manager gate for panel entry.
	 * Avoid the full HR/Scope resolver during the first page request.
	 */
	private function sn_current_user_can_sales_manager_panel(): bool
	{
		if (! is_user_logged_in()) { return false; }
		$user = wp_get_current_user();
		$user_id = (int) ($user->ID ?? 0);
		if ($user_id < 1) { return false; }
		if (current_user_can('manage_options') || current_user_can('sn_view_sales_reports')) { return true; }
		$roles = (array) ($user->roles ?? []);
		if (in_array('sn_sales_manager', $roles, true)) { return true; }
		return $this->sn_fast_hr_position_for_user($user_id) === 'sales_manager';
	}

