	private function sn_render_sales_manager_fast_overview(int $manager_user_id): void
	{
		global $wpdb;
		$manager_user_id = absint($manager_user_id);
		$owned = 0;
		$transferred = 0;
		if ($manager_user_id > 0 && $this->sn_distribution_tables_ready()) {
			$owned = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d AND (live_lead_id IS NULL OR live_lead_id=0) AND (status IS NULL OR status='' OR status NOT IN ('archived','cancelled','converted','lead_created','live_lead_created','duplicate','error','returned_to_mis'))",
				$manager_user_id
			));
			$transferred = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE assigned_by_user_id=%d AND current_owner_user_id<>%d",
				$manager_user_id,
				$manager_user_id
			));
		}
		?>
		<div class="sn-card sn-section">
			<h3 class="sn-section-title">نمای کلی سریع مدیر فروش</h3>
			<p class="sn-note">برای جلوگیری از 504، ورود پنل فقط آمار سبک را نمایش می‌دهد. گزارش‌های سنگین از تب‌های جدا و با Ajax لود می‌شوند.</p>
			<div class="sn-kpi-grid">
				<div class="sn-kpi-card"><small>شماره‌های فعلی نزد مدیر</small><strong><?php echo esc_html(number_format_i18n($owned)); ?></strong></div>
				<div class="sn-kpi-card"><small>تخصیص‌داده‌شده توسط مدیر</small><strong><?php echo esc_html(number_format_i18n($transferred)); ?></strong></div>
				<div class="sn-kpi-card"><small>کاربر</small><strong>#<?php echo esc_html((string) $manager_user_id); ?></strong><em><?php echo esc_html($this->sn_user_label($manager_user_id)); ?></em></div>
			</div>
		</div>
		<?php
	}

