	public function ajax_sales_manager_lazy_tab(): void
	{
		$started = microtime(true);
		try {
			check_ajax_referer('sn_public', 'nonce');
			if (! $this->sn_current_user_can_sales_manager_panel()) {
				wp_send_json_error(['message' => 'دسترسی غیرمجاز'], 403);
			}
			$tab = sanitize_key(wp_unslash($_POST['tab'] ?? ''));
			$user_id = get_current_user_id();
			ob_start();
			switch ($tab) {
				case 'manager-overview':
					$this->sn_render_sales_manager_fast_overview($user_id);
					break;
				case 'manager-distribution':
					// 1.0.127: permanent progressive allocation view; full workflow, bounded table, no manual load button.
					$this->sn_render_supervisor_progressive_assign_tab($user_id);
					break;
				case 'manager-report':
					$this->sn_render_sales_manager_report_shell_fast($user_id);
					break;
				case 'manager-invoices':
					// 1.0.127: only shell; rows are loaded through the bounded invoice endpoint.
					$this->sn_render_supervisor_progressive_invoice_tab($user_id);
					break;
				case 'manager-customer-actions':
					$this->sn_render_staff_customer_actions_section();
					break;
				case 'manager-archives':
					if (! class_exists('SN_Seller_Flow')) {
						echo '<div class="sn-notice sn-error">ماژول بایگانی مرحله فروشنده در دسترس نیست.</div>';
						break;
					}
					SN_Seller_Flow::instance()->render_manager_archives($user_id, current_user_can('manage_options'));
					break;
				case 'manager-extra-number-requests':
					$this->sn_render_manager_extra_number_requests($user_id);
					break;
				case 'manager-hr-requests':
					$this->sn_hr_change_request_render_section($user_id, 'sales_manager');
					break;
				default:
					wp_send_json_error(['message' => 'تب نامعتبر است'], 400);
			}
			$html = ob_get_clean();
			wp_send_json_success(['html' => $html, 'elapsed_ms' => (int) round((microtime(true) - $started) * 1000)]);
		} catch (Throwable $e) {
			while (ob_get_level() > 0) { @ob_end_clean(); }
			error_log('SN ajax_sales_manager_lazy_tab failed: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
			wp_send_json_error(['message' => 'خطای داخلی در بارگذاری این بخش رخ داد. جزئیات در لاگ سرور ثبت شد.'], 500);
		}
	}

	public function render_sales_manager_panel(): string
	{
		if (! is_user_logged_in()) {
			$auth_id = (int) get_option('sn_sales_manager_auth_page_id', 0);
			$url = $auth_id ? get_permalink($auth_id) : wp_login_url();
			return '<script>window.location.href=' . json_encode($url) . ';</script><div class="sn-notice">در حال انتقال به صفحه ورود...</div>';
		}
		$current_user_id = get_current_user_id();
		if (! $this->sn_current_user_can_sales_manager_panel()) {
			$user = wp_get_current_user();
			$position = $this->sn_fast_hr_position_for_user((int) $user->ID);
			$roles = array_filter(array_map('sanitize_key', (array) $user->roles));
			return '<div class="sn-notice sn-error" dir="rtl"><strong>دسترسی غیرمجاز.</strong><div class="sn-muted" style="margin-top:6px">شناسه کاربر: #' . esc_html((string) $user->ID) . ' | سمت HR: ' . esc_html($position !== '' ? $position : 'نامشخص') . ' | نقش‌های وردپرس: ' . esc_html($roles ? implode(', ', $roles) : 'ندارد') . ' | مقدار مورد انتظار: sales_manager</div></div>';
		}
		ob_start();
		?>
		<div class="sn-panel sn-portal" id="sn-sales-manager-panel" dir="rtl" data-sn-manager-lazy="1">
			<div class="sn-panel-header"><div><h2>پنل مدیر فروش</h2><div class="sn-muted">کاربر فعلی: <?php echo esc_html($this->sn_user_label($current_user_id)); ?> | سمت سریع: <?php echo esc_html($this->sn_hr_persian_label($this->sn_fast_hr_position_for_user($current_user_id))); ?> | User ID: #<?php echo esc_html((string) $current_user_id); ?></div></div><a class="sn-btn sn-btn-secondary" href="#sn-reports-panel">گزارش جامع</a><?php echo $this->sn_panel_user_actions_markup(); ?></div>
			<?php $this->sn_render_panel_tabs([
				'manager-overview' => 'نمای کلی',
				'manager-distribution' => 'تخصیص شماره',
				'manager-report' => 'گزارش سرنخ‌ها',
				'manager-invoices' => 'فاکتورها',
				'manager-customer-actions' => 'رفتار مشتریان',
				'manager-archives' => 'بایگانی‌ها',
				'manager-extra-number-requests' => 'درخواست شماره',
				'manager-hr-requests' => 'درخواست HR',
				'manager-wallet' => 'کیف پول',
			], 'manager-overview'); ?>
			<section id="manager-overview" class="<?php echo esc_attr($this->sn_tab_panel_class('manager-overview', 'manager-overview')); ?> sn-manager-lazy-tab" data-sn-tab-panel="manager-overview"><?php $this->sn_sales_manager_lazy_placeholder('manager-overview', 'نمای کلی سریع', 'برای لود آمار سبک مدیر فروش کلیک کن.'); ?></section>
			<section id="manager-distribution" class="<?php echo esc_attr($this->sn_tab_panel_class('manager-distribution', 'manager-overview')); ?> sn-manager-lazy-tab" data-sn-tab-panel="manager-distribution"><?php $this->sn_sales_manager_lazy_placeholder('manager-distribution', 'تخصیص شماره', 'فرم و جدول تخصیص فقط هنگام نیاز بارگذاری می‌شود.'); ?></section>
			<section id="manager-report" class="<?php echo esc_attr($this->sn_tab_panel_class('manager-report', 'manager-overview')); ?> sn-manager-lazy-tab" data-sn-tab-panel="manager-report"><?php $this->sn_sales_manager_lazy_placeholder('manager-report', 'گزارش سرنخ‌ها', 'گزارش با فیلتر و محدودیت ردیف لود می‌شود.'); ?></section>
			<section id="manager-invoices" class="<?php echo esc_attr($this->sn_tab_panel_class('manager-invoices', 'manager-overview')); ?> sn-manager-lazy-tab" data-sn-tab-panel="manager-invoices"><?php $this->sn_sales_manager_lazy_placeholder('manager-invoices', 'فاکتورها', 'گزارش فاکتورها جدا از ورود پنل لود می‌شود.'); ?></section>
			<section id="manager-customer-actions" class="<?php echo esc_attr($this->sn_tab_panel_class('manager-customer-actions', 'manager-overview')); ?> sn-manager-lazy-tab" data-sn-tab-panel="manager-customer-actions"><?php $this->sn_sales_manager_lazy_placeholder('manager-customer-actions', 'رفتار مشتریان', 'رفتار مشتری در فاکتورهای زیرمجموعه هنگام باز کردن تب بارگذاری می‌شود.'); ?></section>
