	// --- پنل فروشنده ---

			private function sn_invoice_items_label(int $invoice_id, int $fallback_product_id = 0): string
			{
				global $wpdb;
				$items = $wpdb->get_results($wpdb->prepare("SELECT product_name, qty FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d ORDER BY id ASC", $invoice_id), ARRAY_A);
				if (!$items) { return $fallback_product_id ? (string) get_the_title($fallback_product_id) : '—'; }
				$parts = [];
				foreach ($items as $it) { $parts[] = trim((string)$it['product_name']) . ((int)$it['qty'] > 1 ? ' × ' . (int)$it['qty'] : ''); }
				return implode('، ', $parts);
			}

	public function render_seller_panel(): string
	{
		if (! is_user_logged_in()) {
			// در shortcode نمیشه header ارسال کرد — با JS redirect کن
			$auth_page_id  = (int) get_option('sn_auth_page_id', 0);
			$panel_page_id = (int) get_option('sn_seller_panel_page_id', 0);
			$current_url   = get_permalink($panel_page_id) ?: home_url($_SERVER['REQUEST_URI'] ?? '/');
			if ($auth_page_id) {
				$login_url = add_query_arg('redirect_to', urlencode($current_url), get_permalink($auth_page_id));
				return '<script>window.location.href=' . json_encode($login_url) . ';</script>'
					. '<div class="sn-notice">در حال انتقال به صفحه ورود...</div>';
			}
			return '<div class="sn-notice sn-error">صفحه ورود فروشنده تنظیم نشده — از پنل ادمین → تنظیمات، ID صفحه ورود را وارد کنید.</div>';
		}
		$user = wp_get_current_user();
		if (! in_array('sn_seller', (array) $user->roles, true) && $this->sn_hr_position_for_user((int) $user->ID) !== 'seller') {
			$position = $this->sn_hr_position_for_user((int) $user->ID);
			$roles = array_filter(array_map('sanitize_key', (array) $user->roles));
			return '<div class="sn-panel" dir="rtl"><div class="sn-notice sn-error"><strong>دسترسی غیرمجاز — این صفحه فقط برای فروشندگان است.</strong><div class="sn-muted" style="margin-top:6px">شناسه کاربر: #' . esc_html((string) $user->ID) . ' | سمت HR: ' . esc_html($position !== '' ? $position : 'نامشخص') . ' | نقش‌های وردپرس: ' . esc_html($roles ? implode(', ', $roles) : 'ندارد') . ' | مقدار مورد انتظار: seller</div></div></div>';
		}

		$products = SN_Helpers::get_sn_products();
		if (class_exists('SN_Dot_Flow')) {
			$products = SN_Dot_Flow::instance()->filter_products_for_user($products, (int) $user->ID);
		}
		if (class_exists('SN_Projects')) {
			$products = SN_Projects::instance()->filter_sellable_products($products, (int) $user->ID);
		}
		$product_groups = [];
		if (class_exists('SN_Seller_Flow')) {
			$products = SN_Seller_Flow::instance()->decorate_products($products);
			foreach (SN_Seller_Flow::product_types() as $type_key => $type_label) {
				$product_groups[$type_key] = ['label' => $type_label, 'products' => []];
			}
			foreach ($products as $product_row) {
				$type_key = (string) ($product_row['sales_product_type'] ?? 'product');
				if (! isset($product_groups[$type_key])) { $type_key = 'product'; }
				$product_groups[$type_key]['products'][] = $product_row;
			}
		}
		$provinces = SN_Helpers::get_provinces();
		$payment_presets = $this->sn_partial_payment_presets();
		$max_invoice_products = $this->sn_invoice_max_products();
			$can_issue_invoice = $this->sn_user_can_create_manual_invoice((int) $user->ID);
			$can_request_extra_number = $this->sn_user_can_request_extra_number((int) $user->ID);
			$manual_invoice_enabled = $this->sn_seller_manual_invoice_enabled();
			$team_invoice_source_mode = $this->sn_team_invoice_source_mode_for_user((int) $user->ID);
			$show_manual_invoice_tab = $can_issue_invoice && $manual_invoice_enabled;

		ob_start();
	?>
			<div class="sn-panel sn-portal" dir="rtl" id="sn-seller-panel" data-sn-max-products="<?php echo esc_attr((string) $max_invoice_products); ?>" data-sn-can-issue-invoice="<?php echo $can_issue_invoice ? '1' : '0'; ?>" data-sn-can-request-extra-number="<?php echo $can_request_extra_number ? '1' : '0'; ?>" data-sn-manual-invoice-enabled="<?php echo $manual_invoice_enabled ? '1' : '0'; ?>" data-sn-team-invoice-source="<?php echo esc_attr($team_invoice_source_mode); ?>">
			<div class="sn-panel-header">
				<h2>پنل فروشنده — <?php echo esc_html($this->sn_user_label((int) $user->ID)); ?></h2>
				<?php echo $this->sn_panel_user_actions_markup(); ?>
