	private function sn_render_seller_commission_preview(int $seller_id): string
	{
		global $wpdb;
		if ($seller_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) {
			return '<div class="sn-card"><h3>پورسانت من</h3><p class="sn-muted">داده‌ای برای نمایش وجود ندارد.</p></div>';
		}
		$this->sn_ensure_commission_tables();
		$paid_condition = $this->sn_commission_paid_approved_invoice_condition('i');
		$rows = $wpdb->get_results($wpdb->prepare("SELECT i.* FROM {$wpdb->prefix}sn_invoices i WHERE i.seller_id=%d AND {$paid_condition} ORDER BY i.id DESC LIMIT 30", $seller_id), ARRAY_A) ?: [];
		$payment_options = $this->sn_commission_payment_method_options();
		$employment_type_options = $this->sn_commission_employment_type_options();
		ob_start(); ?>
		<div class="sn-card sn-section sn-seller-commission-preview">
			<h3>پورسانت من</h3>
			<p class="sn-note">این بخش فقط پیش‌نمایش خواندنی است؛ هیچ مبلغی به کیف پول ارسال نمی‌شود. قوانین بر اساس نوع همکاری HR در تاریخ تایید مالی و روش پرداخت مشتری match می‌شوند.</p>
			<div class="sn-table-wrap sn-hr-change-table"><table class="sn-table"><thead><tr><th>فاکتور</th><th>مبلغ</th><th>روش پرداخت</th><th>نوع همکاری</th><th>قانون</th><th>پورسانت</th><th>وضعیت</th></tr></thead><tbody>
			<?php if (! $rows) : ?><tr><td colspan="7">هنوز فاکتور تاییدشده‌ای برای پیش‌نمایش پورسانت وجود ندارد.</td></tr><?php endif; ?>
			<?php foreach ($rows as $invoice) :
				$context = $this->sn_resolve_invoice_commission_context((int) ($invoice['id'] ?? 0), $invoice);
				$match = $this->sn_find_matching_commission_rule($context);
				$rule = $match['matched_rule'] ?? null;
				$rules = $this->sn_commission_apply_hr_override_to_rules($context, (array) ($match['matched_rules'] ?? []));
				$rule = $rules[0] ?? null;
				$amount = (float) ($context['invoice_total'] ?? 0);
				$component_result = $this->sn_commission_calculate_rule_components($rules, $amount);
				$commission = (float) ($component_result['total'] ?? 0);
				$diagnostics = array_filter(array_merge((array) ($context['diagnostics'] ?? []), (array) ($match['diagnostics'] ?? [])));
			?>
				<tr>
					<td><?php echo esc_html((string) ($context['invoice_code'] ?: ('#' . (int) $context['invoice_id']))); ?><br><small>#<?php echo esc_html((string) (int) $context['invoice_id']); ?><?php if ((int) ($context['issued_by_user_id'] ?? 0) && (int) $context['issued_by_user_id'] !== $seller_id) : ?> | صادرکننده: #<?php echo esc_html((string) (int) $context['issued_by_user_id']); ?><?php endif; ?></small></td>
					<td><?php echo esc_html(SN_Helpers::format_price($amount)); ?></td>
					<td><?php echo esc_html($this->sn_commission_option_label($payment_options, (string) ($context['payment_method_normalized'] ?? 'unknown'))); ?></td>
					<td><?php echo esc_html($this->sn_commission_option_label($employment_type_options, (string) ($context['seller_employment_type'] ?? ''))); ?><br><small><?php echo ! empty($context['compensation_history_id']) ? 'HR history #' . esc_html((string) (int) $context['compensation_history_id']) : 'بدون تاریخچه HR'; ?></small></td>
					<td><?php echo $rule ? esc_html((string) ($rule['title'] ?? ('#' . (int) $rule['id']))) . '<br><small>#' . esc_html((string) (int) $rule['id']) . '</small>' : '<span class="sn-muted">قانون پورسانت منطبق پیدا نشد.</span>'; ?></td>
					<td><?php echo esc_html(SN_Helpers::format_price($commission)); ?></td>
					<td><span class="sn-badge"><?php echo $rule ? 'پیش‌نمایش' : 'بدون قانون'; ?></span><?php if ($diagnostics) : ?><br><small><?php echo esc_html(implode('، ', array_unique($diagnostics))); ?></small><?php endif; ?></td>
				</tr>
			<?php endforeach; ?>
			</tbody></table></div>
		</div>
		<?php return ob_get_clean();
	}

	private function sn_distribution_virtual_lead_offset(): int
	{
		return 900000000;
	}

	private function sn_distribution_virtual_lead_id(int $item_id): int
	{
		return $this->sn_distribution_virtual_lead_offset() + max(0, $item_id);
	}

	private function sn_distribution_item_id_from_virtual_lead($lead_id): int
	{
		$lead_id = absint($lead_id);
		$offset = $this->sn_distribution_virtual_lead_offset();
		return $lead_id > $offset ? $lead_id - $offset : 0;
	}

	private function sn_distribution_seller_delivered_items(int $seller_id, int $limit = 100): array
	{
		global $wpdb;
		if ($seller_id < 1 || ! $this->sn_distribution_tables_ready()) {
			return [];
		}
		// این لیست منبع اصلی نمایش شماره‌های فروشنده است. محدودیت خیلی کوچک باعث می‌شد
		// شماره‌هایی که فروشنده روی آن‌ها وضعیت/یادداشت ثبت کرده بعد از چند روز از پنل دیده نشوند،
		// درحالی‌که حذف نشده بودند و فقط از سقف نمایش بیرون افتاده بودند.
		$limit = max(1, min(5000, $limit));
		$allowed_statuses = [
			'assigned_to_role',
			'delivered_to_role',
			'distributed_forward',
			'delivered_to_seller',
			'ready_for_lead_conversion',
			'duplicate_lead_detected',
			'conversion_failed',
			'live_lead_created',
			'',
		];
		$status_placeholders = implode(',', array_fill(0, count($allowed_statuses), '%s'));
		$owner_where = 'di.current_owner_user_id=%d';
		$status_where = "(di.status IS NULL OR di.status IN ({$status_placeholders}))";
		$latest_items = $wpdb->get_results($wpdb->prepare(
			"SELECT di.*
			FROM {$wpdb->prefix}sn_distribution_items di
			WHERE {$owner_where}
				AND {$status_where}
			ORDER BY COALESCE(di.updated_at, di.created_at) DESC, di.id DESC
			LIMIT %d",
			...array_merge([$seller_id], $allowed_statuses, [$limit])
		)) ?: [];

		// retention pool: هر شماره‌ای که فروشنده روی آن کاری کرده، باید حتی اگر از لیست آخرین شماره‌ها
		// بیرون افتاد، همچنان در پنل قابل مشاهده بماند. این روی مالکیت/تخصیص اثر ندارد؛ فقط نمایش را کامل می‌کند.
		$retention_limit = min(5000, max($limit, 250));
		$retained_items = $wpdb->get_results($wpdb->prepare(
			"SELECT di.*
			FROM {$wpdb->prefix}sn_distribution_items di
			WHERE {$owner_where}
				AND {$status_where}
				AND (
					NULLIF(di.seller_contact_status,'') IS NOT NULL
					OR NULLIF(di.seller_notes,'') IS NOT NULL
					OR NULLIF(di.seller_customer_name,'') IS NOT NULL
					OR di.seller_next_followup_at IS NOT NULL
					OR di.seller_updated_at IS NOT NULL
					OR di.live_lead_id IS NOT NULL
				)
			ORDER BY COALESCE(di.seller_updated_at, di.updated_at, di.created_at) DESC, di.id DESC
			LIMIT %d",
			...array_merge([$seller_id], $allowed_statuses, [$retention_limit])
		)) ?: [];

		$item_map = [];
		foreach (array_merge($latest_items, $retained_items) as $item) {
			$item_id = (int) ($item->id ?? 0);
			if ($item_id > 0) {
				$item_map[$item_id] = $item;
			}
		}
		$items = array_values($item_map);
		usort($items, static function ($a, $b) {
			$ad = (string) (($a->seller_updated_at ?? '') ?: (($a->updated_at ?? '') ?: ($a->created_at ?? '')));
			$bd = (string) (($b->seller_updated_at ?? '') ?: (($b->updated_at ?? '') ?: ($b->created_at ?? '')));
			return strcmp($bd, $ad) ?: ((int) ($b->id ?? 0) <=> (int) ($a->id ?? 0));
		});
		if (! $items) {
			return [];
		}

		$fetch_by_ids = function (string $table, array $ids) use ($wpdb): array {
			$ids = array_values(array_unique(array_filter(array_map('absint', $ids))));
			if (! $ids) { return []; }
			$placeholders = implode(',', array_fill(0, count($ids), '%d'));
			$rows = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE id IN ({$placeholders})", ...$ids)) ?: [];
			$map = [];
			foreach ($rows as $row) { $map[(int) ($row->id ?? 0)] = $row; }
			return $map;
		};

		$pool_table = $wpdb->prefix . 'sn_mis_lead_pool';
		$row_table = $wpdb->prefix . 'sn_mis_data_rows';
		$batch_table = $wpdb->prefix . 'sn_mis_import_batches';
		$pool_ready = $this->sn_table_exists_quiet($pool_table);
		$rows_ready = $this->sn_table_exists_quiet($row_table);
		$batches_ready = $this->sn_table_exists_quiet($batch_table);

		$pool_ids = [];
		$row_ids = [];
		$batch_ids = [];
		foreach ($items as $item) {
			$item->customer_name = (string) ($item->seller_customer_name ?? '');
			$item->customer_phone = '';
			$item->normalized_phone = '';
			$item->city = (string) ($item->seller_city ?? '');
			$item->province = (string) ($item->seller_province ?? '');
			$item->batch_code = '';
			$item->campaign_code = '';
			$item->data_category = '';
			$source_type = (string) ($item->source_type ?? '');
			$source_id = (int) ($item->source_id ?? 0);
			$pool_id = (int) ($item->pool_item_id ?? 0);
			if ($pool_id > 0 || ($source_type === 'mis_pool' && $source_id > 0)) {
				$pool_ids[] = $pool_id > 0 ? $pool_id : $source_id;
			}
			if ($source_type === 'mis_data_row' && $source_id > 0) { $row_ids[] = $source_id; }
			if (! empty($item->batch_id)) { $batch_ids[] = (int) $item->batch_id; }
		}

		$pools = $pool_ready ? $fetch_by_ids($pool_table, $pool_ids) : [];
		foreach ($pools as $pool) {
			if (! empty($pool->source_row_id)) { $row_ids[] = (int) $pool->source_row_id; }
			if (! empty($pool->batch_id)) { $batch_ids[] = (int) $pool->batch_id; }
		}
		$rows = $rows_ready ? $fetch_by_ids($row_table, $row_ids) : [];
		foreach ($rows as $row) {
			if (! empty($row->batch_id)) { $batch_ids[] = (int) $row->batch_id; }
		}
		$batches = $batches_ready ? $fetch_by_ids($batch_table, $batch_ids) : [];

		foreach ($items as $item) {
			$source_type = (string) ($item->source_type ?? '');
			$source_id = (int) ($item->source_id ?? 0);
			$pool_id = (int) ($item->pool_item_id ?? 0);
			$batch_id = (int) ($item->batch_id ?? 0);
			$pool = null;
			if ($pool_id > 0 && isset($pools[$pool_id])) { $pool = $pools[$pool_id]; }
			elseif ($source_type === 'mis_pool' && $source_id > 0 && isset($pools[$source_id])) { $pool = $pools[$source_id]; }

			$row = null;
			if ($source_type === 'mis_data_row' && $source_id > 0 && isset($rows[$source_id])) { $row = $rows[$source_id]; }
			elseif ($pool && ! empty($pool->source_row_id) && isset($rows[(int) $pool->source_row_id])) { $row = $rows[(int) $pool->source_row_id]; }

			if ($row) {
				$item->customer_name = (string) ($item->customer_name ?: ($row->customer_name ?? ''));
				$item->customer_phone = (string) ($row->customer_phone ?? '');
				$item->normalized_phone = (string) ($row->normalized_phone ?? '');
				$item->city = (string) ($item->city ?: ($row->city ?? ''));
				$item->province = (string) ($item->province ?: ($row->province ?? ''));
				if (! $batch_id && ! empty($row->batch_id)) { $batch_id = (int) $row->batch_id; }
			}
			if ($pool) {
				$item->customer_name = (string) ($item->customer_name ?: ($pool->customer_name ?? ''));
				$item->customer_phone = (string) ($item->customer_phone ?: ($pool->customer_phone ?? ''));
				$item->normalized_phone = (string) ($item->normalized_phone ?: ($pool->normalized_phone ?? ''));
				$item->city = (string) ($item->city ?: ($pool->city ?? ''));
				$item->province = (string) ($item->province ?: ($pool->province ?? ''));
				if (! $batch_id && ! empty($pool->batch_id)) { $batch_id = (int) $pool->batch_id; }
			}
			if ($batch_id > 0 && isset($batches[$batch_id])) {
				$batch = $batches[$batch_id];
				$item->batch_code = (string) ($batch->batch_code ?? '');
				$item->campaign_code = (string) ($batch->campaign_code ?? '');
				$item->data_category = (string) ($batch->data_category ?? '');
			}
			foreach (['normalized_phone', 'customer_phone', 'phone', 'mobile'] as $phone_key) {
				if (! empty($item->{$phone_key})) {
					$item->normalized_phone = (string) $item->{$phone_key};
					break;
				}
			}
			$this->sn_distribution_guard_seller_state_for_view($seller_id, $item);
		}
		return $items;
	}
	private function sn_distribution_seller_debug(int $seller_id, array $items): array
	{
		global $wpdb;
		$debug = [
			'current_user_id' => $seller_id,
			'hr_position' => $this->sn_hr_position_for_user($seller_id),
			'query_source' => 'sn_distribution_items.current_owner_user_id only',
			'owned_distribution_item_count' => count($items),
			'live_lead_count' => 0,
			'source_status_summary' => [],
			'sample_distribution_item_ids' => [],
			'query_args' => [
				'current_owner_user_id' => $seller_id,
				'final_seller_user_id' => 'ignored_for_seller_panel_visibility',
				'statuses' => ['assigned_to_role', 'delivered_to_role', 'distributed_forward', 'delivered_to_seller', 'ready_for_lead_conversion', 'duplicate_lead_detected', 'conversion_failed'],
				'live_lead_required' => false,
			],
			'reason_no_rows_rendered' => '',
		];
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
			$debug['live_lead_count'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE seller_id=%d", $seller_id));
		}
		if ($this->sn_distribution_tables_ready()) {
			$rows = $wpdb->get_results($wpdb->prepare("SELECT COALESCE(source_type,'') source_type, COALESCE(status,'') status, COUNT(*) c FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d GROUP BY source_type,status ORDER BY c DESC", $seller_id)) ?: [];
			foreach ($rows as $row) {
				$key = (string) $row->source_type . ' / ' . (string) $row->status;
				$debug['source_status_summary'][$key] = (int) $row->c;
			}
			$debug['owned_distribution_item_count_db'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d", $seller_id));
		}
		foreach (array_slice($items, 0, 10) as $item) {
			$debug['sample_distribution_item_ids'][] = [
				'id' => (int) ($item->id ?? 0),
				'current_owner_user_id' => (int) ($item->current_owner_user_id ?? 0),
				'current_owner_position' => (string) ($item->current_owner_position ?? ''),
				'final_seller_user_id' => (int) ($item->final_seller_user_id ?? 0),
				'source_type' => (string) ($item->source_type ?? ''),
				'status' => (string) ($item->status ?? ''),
				'live_lead_id' => (int) ($item->live_lead_id ?? 0),
				'phone_masked' => $this->sn_mask_phone((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? ''))),
			];
		}
		if (! $items) {
			$debug['reason_no_rows_rendered'] = ! empty($debug['owned_distribution_item_count_db']) ? 'status_filter_excluded_or_render_bug' : 'no_owned_distribution_items';
		}
		return $debug;
	}

	private function sn_distribution_seller_item_counts(int $seller_id, array $items): array
	{
		global $wpdb;
		$live = 0;
		$today = 0;
		$paid = 0;
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
			$live = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE seller_id=%d", $seller_id));
		}
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) {
			$paid = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices WHERE seller_id=%d AND status='paid'", $seller_id));
		}
		foreach ($items as $item) {
			$follow = (string) ($item->seller_next_followup_at ?? '');
			$follow_timestamp = SN_Helpers::site_mysql_timestamp($follow, 0);
			if ($follow_timestamp > 0 && SN_Helpers::tehran_format('Y-m-d', $follow_timestamp) === SN_Helpers::tehran_today_gregorian()) {
				$today++;
			}
		}
		return [
			'v4_delivered' => count($items),
			'live_leads' => $live,
			'today_followups' => $today,
			'paid_sales' => $paid,
		];
	}

	private function sn_distribution_render_seller_delivered_section(int $seller_id): void
	{
		$this->sn_distribution_ensure_schema();
		$items = $this->sn_distribution_seller_delivered_items($seller_id, 100);
		$report = get_option('sn_distribution_conversion_report', []);
		$edit_report = get_option('sn_distribution_seller_item_update_report', []);
		$counts = $this->sn_distribution_seller_item_counts($seller_id, $items);
		$debug = $this->sn_distribution_seller_debug($seller_id, $items);
		$contact_statuses = [
			'' => '—',
			'new' => 'جدید',
			'no_answer' => 'پاسخ نداد',
			'called' => 'تماس گرفته شد',
			'interested' => 'علاقه‌مند',
