	public function handle_distribution_update_seller_item(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_distribution_update_seller_item');
		$this->sn_distribution_ensure_schema();
		$this->sn_distribution_ensure_seller_inline_columns();
		global $wpdb;
		$actor_id = get_current_user_id();
		$item_id = absint($_POST['item_id'] ?? 0);
		$item_table = $wpdb->prefix . 'sn_distribution_items';
		$item = $item_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$item_table} WHERE id=%d", $item_id)) : null;
		$report = ['action' => 'distribution_update_seller_item', 'item_id' => $item_id, 'actor_user_id' => $actor_id, 'saved' => false, 'errors' => [], 'updated_at' => current_time('mysql')];
		if (! $item) {
			$report['errors'][] = 'item_not_found';
		} elseif (! current_user_can('manage_options') && ! ($this->sn_hr_position_for_user($actor_id) === 'seller' && (int) ($item->current_owner_user_id ?? 0) === $actor_id && (string) ($item->current_owner_position ?? '') === 'seller')) {
			$report['errors'][] = 'forbidden_not_current_seller_owner';
			$report['current_owner_user_id'] = (int) ($item->current_owner_user_id ?? 0);
			$report['final_seller_user_id'] = (int) ($item->final_seller_user_id ?? 0);
		}
		if (empty($report['errors'])) {
			$contact_status = sanitize_key(wp_unslash($_POST['contact_status'] ?? ''));
			$next_date = sanitize_text_field(wp_unslash($_POST['next_followup_date'] ?? ''));
			$next_time = sanitize_text_field(wp_unslash($_POST['next_followup_time'] ?? ''));
			$next = null;
			if ($next_date !== '' || $next_time !== '' || $contact_status === 'followup') {
				if ($next_date === '' || $next_time === '') {
					$report['errors'][] = 'followup_date_and_tehran_time_required';
				} else {
					$normalized_followup = SN_Helpers::normalize_jalali_tehran_datetime($next_date, $next_time, true);
					if (is_wp_error($normalized_followup)) {
						$report['errors'][] = $normalized_followup->get_error_message();
					} else {
						$next = (string) $normalized_followup['mysql'];
					}
				}
			}
		}
		if (empty($report['errors'])) {
			$data = [
				'seller_customer_name' => sanitize_text_field(wp_unslash($_POST['customer_name'] ?? '')),
				'seller_province' => sanitize_text_field(wp_unslash($_POST['province'] ?? '')),
				'seller_city' => sanitize_text_field(wp_unslash($_POST['city'] ?? '')),
				'seller_contact_status' => $contact_status,
				'seller_sale_probability' => min(100, max(0, absint($_POST['sale_probability'] ?? 0))),
				'seller_next_followup_at' => $next,
				'seller_notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
				'seller_updated_by' => $actor_id,
				'seller_updated_at' => current_time('mysql'),
				'updated_at' => current_time('mysql'),
			];
			$filtered = $this->sn_distribution_filter_existing_columns_fresh($item_table, $data);
			$ok = $wpdb->update($item_table, $filtered, ['id' => $item_id]) !== false;
			$report['saved'] = $ok;
			if (! $ok) {
				$report['errors'][] = sanitize_text_field($wpdb->last_error ?: 'update_failed');
			} else {
				$this->sn_distribution_log($item_id, 'seller_item_updated', $actor_id, (int) ($item->current_owner_user_id ?? 0), (int) ($item->current_owner_user_id ?? 0), (string) ($item->current_owner_position ?? ''), (string) ($item->current_owner_position ?? ''), (int) ($item->current_step_order ?? 0), (string) ($data['seller_notes'] ?? ''), ['fields' => array_keys($filtered)]);
			}
		}
		update_option('sn_distribution_seller_item_update_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	// --- پنل سرپرست ---

	private function sn_distribution_fast_owned_count_for_actor(int $actor_id): int
	{
		global $wpdb;
		if ($actor_id < 1 || ! $this->sn_distribution_tables_ready()) { return 0; }
		$excluded = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error', 'returned_to_mis'];
		$ph = implode(',', array_fill(0, count($excluded), '%s'));
		return (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items di
			 WHERE di.current_owner_user_id=%d
			   AND COALESCE(di.source_type,'') <> 'paid_invoice_referral'
			   AND (di.live_lead_id IS NULL OR di.live_lead_id=0)
			   AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)
			   AND (di.status IS NULL OR di.status='' OR di.status NOT IN ({$ph}))",
			...array_merge([$actor_id], $excluded)
		));
	}

	private function sn_distribution_fast_case_options_for_actor(int $actor_id, int $limit = 40): array
	{
		global $wpdb;
		if ($actor_id < 1 || ! $this->sn_distribution_tables_ready()) { return []; }
		$excluded = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error', 'returned_to_mis'];
		$ph = implode(',', array_fill(0, count($excluded), '%s'));
		$limit = max(1, min(100, $limit));
		$rows = $wpdb->get_results($wpdb->prepare(
			"SELECT COALESCE(di.batch_id,0) batch_id, COUNT(*) total,
			        MAX(b.batch_code) batch_code, MAX(b.title) batch_title,
			        MAX(b.campaign_code) campaign_code, MAX(b.data_category) data_category, MAX(b.source_label) source_label
			 FROM {$wpdb->prefix}sn_distribution_items di
			 LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id=di.batch_id
			 WHERE di.current_owner_user_id=%d
			   AND COALESCE(di.source_type,'') <> 'paid_invoice_referral'
			   AND (di.live_lead_id IS NULL OR di.live_lead_id=0)
			   AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)
			   AND (di.status IS NULL OR di.status='' OR di.status NOT IN ({$ph}))
			 GROUP BY COALESCE(di.batch_id,0)
			 ORDER BY total DESC, batch_id DESC LIMIT %d",
			...array_merge([$actor_id], $excluded, [$limit])
		), ARRAY_A) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$batch_id = (int) ($row['batch_id'] ?? 0);
			$key = $batch_id > 0 ? 'batch:' . $batch_id : '';
			$label_parts = [];
			foreach (['batch_code','batch_title','campaign_code'] as $k) {
				$v = trim((string) ($row[$k] ?? ''));
				if ($v !== '') { $label_parts[] = $v; }
			}
			$out[] = [
				'key' => $key,
				'label' => $label_parts ? implode(' / ', array_unique($label_parts)) : 'بدون پرونده مشخص',
				'total' => (int) ($row['total'] ?? 0),
			];
		}
		return $out;
	}

