	/**
	 * 1.0.125: ultra-fast supervisor gate for front panel entry.
	 * Do not instantiate SN_Scope_Service here; on large HR trees it can build hierarchy/scope
	 * structures during the very first page request and cause gateway 504 before any PHP fatal log.
	 */
	private function sn_current_user_can_supervisor_panel(): bool
	{
		if (! is_user_logged_in()) { return false; }
		$user = wp_get_current_user();
		$user_id = (int) ($user->ID ?? 0);
		if ($user_id < 1) { return false; }
		$roles = (array) ($user->roles ?? []);
		if (in_array('sn_supervisor', $roles, true) || in_array('sn_senior_supervisor', $roles, true) || current_user_can('manage_options')) {
			return true;
		}
		return in_array($this->sn_fast_hr_position_for_user($user_id), ['supervisor', 'senior_supervisor'], true);
	}

	private function sn_fast_hr_position_for_user(int $user_id): string
	{
		$user_id = absint($user_id);
		if ($user_id < 1) { return ''; }
		$cache_key = 'fast:' . $user_id;
		if (isset($this->sn_hr_position_for_user_cache[$cache_key])) {
			return (string) $this->sn_hr_position_for_user_cache[$cache_key];
		}
		$position = '';
		global $wpdb;
		$profiles = $wpdb->prefix . 'sn_hr_profiles';
		$positions = $wpdb->prefix . 'sn_hr_positions';
		if ($this->sn_table_exists_quiet($profiles) && $this->sn_table_exists_quiet($positions)) {
			$position = (string) $wpdb->get_var($wpdb->prepare(
				"SELECT pos.slug
				 FROM {$profiles} p
				 INNER JOIN {$positions} pos ON pos.id=p.position_id
				 WHERE p.user_id=%d AND p.is_active=1
				 ORDER BY p.id DESC
				 LIMIT 1",
				$user_id
			));
		}
		if ($position === '') {
			$user = get_user_by('id', $user_id);
			$roles = $user instanceof WP_User ? (array) $user->roles : [];
			if (in_array('sn_hr', $roles, true)) { $position = 'hr'; }
			elseif (in_array('sn_mis', $roles, true)) { $position = 'mis'; }
			elseif (in_array('sn_sales_deputy', $roles, true)) { $position = 'sales_deputy'; }
			elseif (in_array('sn_sales_manager', $roles, true) || in_array('sas_sales_manager', $roles, true)) { $position = 'sales_manager'; }
			elseif (in_array('sn_senior_supervisor', $roles, true) || in_array('sas_senior_supervisor', $roles, true)) { $position = 'senior_supervisor'; }
			elseif (in_array('sn_supervisor', $roles, true) || in_array('sas_supervisor', $roles, true)) { $position = 'supervisor'; }
			elseif (in_array('sn_converter', $roles, true)) { $position = 'converter'; }
			elseif (in_array('sn_financial', $roles, true) || in_array('sn_financial_approval', $roles, true) || in_array('sn_finance', $roles, true)) { $position = 'finance'; }
			elseif (in_array('sn_invoice_reviewer', $roles, true)) { $position = 'invoice_reviewer'; }
			elseif (in_array('sn_after_sales', $roles, true)) { $position = 'after_sales'; }
			elseif (in_array('sn_project_manager', $roles, true)) { $position = 'operations_sales_manager'; }
			elseif (in_array('sn_project_expert', $roles, true)) { $position = 'operations_sales_expert'; }
			elseif (in_array('sn_shipping_expert', $roles, true)) { $position = 'shipping_expert'; }
			elseif (in_array('sn_operations_sales_manager', $roles, true)) { $position = 'operations_sales_manager'; }
			elseif (in_array('sn_operations_sales_supervisor', $roles, true)) { $position = 'operations_sales_supervisor'; }
			elseif (in_array('sn_operations_sales_expert', $roles, true)) { $position = 'operations_sales_expert'; }
			elseif (in_array('sn_operations_executive_manager', $roles, true)) { $position = 'operations_executive_manager'; }
			elseif (in_array('sn_operations_execution_expert', $roles, true)) { $position = 'operations_execution_expert'; }
			elseif (in_array('sn_seller', $roles, true) || in_array('sas_employee', $roles, true)) { $position = 'seller'; }
		}
		$this->sn_hr_position_for_user_cache[$cache_key] = sanitize_key($position);
		return (string) $this->sn_hr_position_for_user_cache[$cache_key];
	}

	private function sn_supervisor_case_filter_from_raw(string $raw): array
	{
		$raw = sanitize_text_field(wp_unslash($raw));
		$out = ['raw' => $raw, 'type' => '', 'value' => '', 'batch_id' => 0];
		if ($raw === '') { return $out; }
		[$type, $value] = array_pad(explode(':', $raw, 2), 2, '');
		$type = sanitize_key($type);
		$value = sanitize_text_field($value);
		if ($type === 'batch') {
			$out['type'] = 'batch';
			$out['batch_id'] = absint($value);
			$out['value'] = (string) $out['batch_id'];
			return $out;
		}
		if (in_array($type, ['campaign', 'category', 'source'], true) && $value !== '') {
			$out['type'] = $type;
			$out['value'] = $value;
			return $out;
		}
		return ['raw' => '', 'type' => '', 'value' => '', 'batch_id' => 0];
	}

