	public function ajax_supervisor_distribution_items(): void
	{
		check_ajax_referer('sn_public', 'nonce');
		if (! $this->sn_current_user_can_supervisor_panel() && ! $this->sn_current_user_can_sales_manager_panel()) {
			wp_send_json_error(['message' => 'دسترسی غیرمجاز'], 403);
		}
		global $wpdb;
		$actor_id = get_current_user_id();
		$limit = max(10, min(100, absint($_POST['limit'] ?? 50)));
		$page = max(1, absint($_POST['page'] ?? 1));
		$offset = ($page - 1) * $limit;
		$filter = $this->sn_supervisor_case_filter_from_raw((string) ($_POST['case_filter'] ?? ''));
		if (! $this->sn_distribution_tables_ready()) {
			wp_send_json_success(['html' => '<div class="sn-notice sn-warning">جدول پخش آماده نیست.</div>', 'has_more' => false]);
		}
		$excluded = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error', 'returned_to_mis'];
		$ph = implode(',', array_fill(0, count($excluded), '%s'));
		$where = [
			'di.current_owner_user_id=%d',
			"COALESCE(di.source_type,'') <> 'paid_invoice_referral'",
			'(di.live_lead_id IS NULL OR di.live_lead_id=0)',
			'(di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)',
			"(di.status IS NULL OR di.status='' OR di.status NOT IN ({$ph}))",
		];
		$args = array_merge([$actor_id], $excluded);
		$type = (string) ($filter['type'] ?? '');
		if ($type === 'batch') {
			$where[] = '(di.batch_id=%d OR p.batch_id=%d OR r.batch_id=%d)';
			$args[] = (int) ($filter['batch_id'] ?? 0);
			$args[] = (int) ($filter['batch_id'] ?? 0);
			$args[] = (int) ($filter['batch_id'] ?? 0);
		} elseif ($type === 'campaign') {
			$where[] = 'b.campaign_code=%s';
			$args[] = (string) ($filter['value'] ?? '');
		} elseif ($type === 'category') {
			$where[] = 'b.data_category=%s';
			$args[] = (string) ($filter['value'] ?? '');
		} elseif ($type === 'source') {
			$where[] = 'di.source_type=%s';
			$args[] = (string) ($filter['value'] ?? '');
		}
		$args[] = $limit + 1;
		$args[] = $offset;
		$sql = "SELECT di.id, di.batch_id, di.status, di.current_owner_user_id, di.current_owner_position, di.updated_at,
			COALESCE(NULLIF(p.customer_name,''), NULLIF(r.customer_name,''), '') AS customer_name,
			COALESCE(NULLIF(di.customer_phone,''), NULLIF(p.customer_phone,''), NULLIF(r.customer_phone,''), '') AS customer_phone,
			COALESCE(NULLIF(di.normalized_phone,''), NULLIF(p.normalized_phone,''), NULLIF(r.normalized_phone,''), '') AS normalized_phone,
			COALESCE(NULLIF(p.city,''), NULLIF(r.city,''), '') AS city,
			COALESCE(NULLIF(p.province,''), NULLIF(r.province,''), '') AS province,
			b.batch_code, b.title batch_title, b.campaign_code, b.data_category, b.source_label
			FROM {$wpdb->prefix}sn_distribution_items di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)
			WHERE " . implode(' AND ', $where) . "
			ORDER BY di.updated_at DESC, di.id DESC LIMIT %d OFFSET %d";
		$rows = $wpdb->get_results($wpdb->prepare($sql, ...$args)) ?: [];
		$has_more = count($rows) > $limit;
		if ($has_more) { array_pop($rows); }
		ob_start();
		if ($page === 1) : ?>
			<div class="sn-table-wrap"><table class="sn-table sn-distribution-owned-table"><thead><tr><th>انتخاب</th><th>آیتم</th><th>پرونده / کد دیتا</th><th>مشتری</th><th>شماره</th><th>موقعیت</th><th>مالک فعلی</th><th>وضعیت</th></tr></thead><tbody>
		<?php endif; ?>
		<?php if (! $rows && $page === 1) : ?><tr><td colspan="8"><div class="sn-empty-state">شماره‌ای با این فیلتر پیدا نشد.</div></td></tr><?php endif; ?>
		<?php foreach ($rows as $item) : $case_value = (int) ($item->batch_id ?? 0) > 0 ? 'batch:' . (int) $item->batch_id : ''; $phone = (string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? '')); ?>
			<tr data-case-filter="<?php echo esc_attr($case_value); ?>">
				<td><input type="checkbox" name="distribution_item_ids[]" value="<?php echo esc_attr((string) (int) $item->id); ?>" disabled></td>
				<td>#<?php echo esc_html((string) (int) $item->id); ?></td>
				<td><strong><?php echo esc_html((string) (($item->batch_title ?? '') ?: ($item->batch_code ?? 'بدون پرونده'))); ?></strong><br><small><?php echo esc_html((string) ($item->campaign_code ?? '')); ?></small></td>
				<td><?php echo esc_html((string) ($item->customer_name ?? '—')); ?></td>
				<td><code><?php echo esc_html($this->sn_mask_phone($phone)); ?></code></td>
				<td><?php echo esc_html(trim((string) (($item->province ?? '') . ' / ' . ($item->city ?? '')), ' /') ?: '—'); ?></td>
				<td><?php echo esc_html($this->sn_user_label((int) ($item->current_owner_user_id ?? 0))); ?></td>
				<td><?php echo esc_html($this->sn_distribution_status_label((string) ($item->status ?? ''))); ?></td>
			</tr>
		<?php endforeach; ?>
		<?php if ($page === 1) : ?></tbody></table></div><?php endif; ?>
		<?php $html = ob_get_clean();
		wp_send_json_success(['html' => $html, 'has_more' => $has_more, 'page' => $page]);
	}

	public function ajax_supervisor_lazy_tab(): void
	{
		$started = microtime(true);
		try {
			check_ajax_referer('sn_public', 'nonce');
			if (! $this->sn_current_user_can_supervisor_panel()) {
				wp_send_json_error(['message' => 'دسترسی غیرمجاز'], 403);
			}
			$tab = sanitize_key(wp_unslash($_POST['tab'] ?? ''));
			$user_id = get_current_user_id();
			ob_start();
			switch ($tab) {
				case 'assign':
					$this->sn_render_supervisor_progressive_assign_tab($user_id);
					break;
				case 'distribution-logs':
					$this->sn_render_supervisor_fast_distribution_logs($user_id);
					break;
				case 'invoices':
					$this->sn_render_supervisor_progressive_invoice_tab($user_id);
					break;
				case 'needs-action':
					if (class_exists('SN_Dot_Flow')) { SN_Dot_Flow::instance()->render_supervisor_ready_tab($user_id); }
					break;
				case 'repeat-actions':
					$this->sn_render_paid_referral_action_section($user_id, 'supervisor');
					break;
				case 'subscriptions':
					if (class_exists('SN_Product_Flow')) { SN_Product_Flow::instance()->render_supervisor_subscriptions($user_id); }
					break;
				case 'hr-requests':
					$this->sn_hr_change_request_render_section($user_id, 'supervisor');
					break;
				case 'wallet':
					if ( class_exists('SN_Purpose_Commission') ) { echo SN_Purpose_Commission::render_dual_wallet_cards($user_id, 25); }
					else { echo $this->render_wallet_box_for_user($user_id, 'supervisor'); }
					break;
				case 'conversion-ready':
					if (class_exists('SN_Dot_Flow')) { SN_Dot_Flow::instance()->render_supervisor_ready_tab($user_id); }
					break;
				case 'converter-stats':
					if (class_exists('SN_Dot_Flow')) { SN_Dot_Flow::instance()->render_supervisor_converters_tab($user_id); }
					break;
				case 'my-conversions':
					if (class_exists('SN_Dot_Flow')) { echo SN_Dot_Flow::instance()->render_converter_panel('supervisor'); }
					break;
				default:
					wp_send_json_error(['message' => 'تب نامعتبر است'], 400);
			}
			$html = ob_get_clean();
			wp_send_json_success(['html' => $html, 'elapsed_ms' => (int) round((microtime(true) - $started) * 1000)]);
		} catch (Throwable $e) {
			while (ob_get_level() > 0) { @ob_end_clean(); }
			error_log('SN ajax_supervisor_lazy_tab failed: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
			wp_send_json_error(['message' => 'خطای داخلی در بارگذاری این بخش رخ داد. جزئیات در لاگ سرور ثبت شد.'], 500);
		}
	}

