	// =========================================================
	// ADMIN OPERATIONAL REPORT HELPERS
	// =========================================================

	private function sn_admin_invoice_paid_condition(string $alias = 'i'): string
	{
		global $wpdb;
		$alias = preg_replace('/[^a-zA-Z0-9_]/', '', $alias) ?: 'i';
		$cols = $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices') ? $this->sn_table_columns($wpdb->prefix . 'sn_invoices') : [];
		$parts = [];
		foreach (['status','invoice_status','payment_status'] as $column) {
			if (in_array($column, $cols, true)) { $parts[] = "{$alias}.{$column} IN ('paid','approved')"; }
		}
		return $parts ? '(' . implode(' OR ', $parts) . ')' : '1=0';
	}

	private function sn_admin_invoice_amount_expr(string $alias = 'i'): string
	{
		global $wpdb;
		$alias = preg_replace('/[^a-zA-Z0-9_]/', '', $alias) ?: 'i';
		$cols = $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices') ? $this->sn_table_columns($wpdb->prefix . 'sn_invoices') : [];
		$candidates = [];
		foreach (['final_total','product_price','paid_amount','deposit_amount','manual_amount','original_total'] as $column) {
			if (in_array($column, $cols, true)) { $candidates[] = "NULLIF({$alias}.{$column},0)"; }
		}
		return $candidates ? 'COALESCE(' . implode(', ', $candidates) . ', 0)' : '0';
	}

	private function sn_admin_distribution_active_condition(string $alias = 'di'): string
	{
		$alias = preg_replace('/[^a-zA-Z0-9_]/', '', $alias) ?: 'di';
		return "({$alias}.status IS NULL OR {$alias}.status='' OR {$alias}.status NOT IN ('archived','cancelled','converted','lead_created','live_lead_created','duplicate','error','returned_to_mis'))";
	}

	private function sn_admin_ids_sql(array $ids): string
	{
		$ids = array_values(array_unique(array_filter(array_map('absint', $ids))));
		return $ids ? implode(',', $ids) : '0';
	}

	private function sn_admin_group_count_by_user(string $table, string $column, array $user_ids, string $extra_where = ''): array
	{
		global $wpdb;
		$full = strpos($table, $wpdb->prefix) === 0 ? $table : $wpdb->prefix . ltrim($table, '_');
		if (! $user_ids || ! $this->sn_table_exists_quiet($full) || ! $this->sn_table_has_column($full, $column)) { return []; }
		$ids_sql = $this->sn_admin_ids_sql($user_ids);
		$where = "{$column} IN ({$ids_sql})" . ($extra_where ? " AND ({$extra_where})" : '');
		$rows = $wpdb->get_results("SELECT {$column} user_id, COUNT(*) c FROM {$full} WHERE {$where} GROUP BY {$column}", ARRAY_A) ?: [];
		$out = [];
		foreach ($rows as $row) { $out[(int) ($row['user_id'] ?? 0)] = (int) ($row['c'] ?? 0); }
		return $out;
	}

	private function sn_admin_wallet_map(array $user_ids): array
	{
		global $wpdb;
		$user_ids = array_values(array_unique(array_filter(array_map('absint', $user_ids))));
		if (! $user_ids || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_wallets')) { return []; }
		$ids_sql = $this->sn_admin_ids_sql($user_ids);
		$rows = $wpdb->get_results("SELECT user_id, wallet_type, balance, total_credit, total_debit, updated_at FROM {$wpdb->prefix}sn_wallets WHERE user_id IN ({$ids_sql})", ARRAY_A) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$out[(int) $row['user_id']][(string) $row['wallet_type']] = $row;
		}
		return $out;
	}

	private function sn_admin_invoice_metrics_by_seller(array $seller_ids): array
	{
		global $wpdb;
		$seller_ids = array_values(array_unique(array_filter(array_map('absint', $seller_ids))));
		if (! $seller_ids || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) { return []; }
		$ids_sql = $this->sn_admin_ids_sql($seller_ids);
		$paid = $this->sn_admin_invoice_paid_condition('i');
		$amount = $this->sn_admin_invoice_amount_expr('i');
		$rows = $wpdb->get_results("SELECT i.seller_id user_id, COUNT(*) invoice_count, SUM(CASE WHEN {$paid} THEN 1 ELSE 0 END) paid_count, COALESCE(SUM(CASE WHEN {$paid} THEN {$amount} ELSE 0 END),0) paid_revenue FROM {$wpdb->prefix}sn_invoices i WHERE i.seller_id IN ({$ids_sql}) GROUP BY i.seller_id", ARRAY_A) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$out[(int) $row['user_id']] = [
				'invoice_count' => (int) ($row['invoice_count'] ?? 0),
				'paid_count' => (int) ($row['paid_count'] ?? 0),
				'paid_revenue' => (float) ($row['paid_revenue'] ?? 0),
			];
		}
		return $out;
	}

	private function sn_admin_hr_people_by_positions(array $position_slugs, int $limit = 800): array
	{
		global $wpdb;
		$position_slugs = array_values(array_unique(array_filter(array_map('sanitize_key', $position_slugs))));
		if (! $position_slugs || ! $this->sn_mis_table_exists('sn_hr_profiles') || ! $this->sn_mis_table_exists('sn_hr_positions')) { return []; }
		$this->sn_ensure_hr_display_name_column();
		$profile_cols = $this->sn_table_columns($wpdb->prefix . 'sn_hr_profiles');
		$expr = static function (string $column, string $fallback = "''") use ($profile_cols): string {
			return in_array($column, $profile_cols, true) ? 'p.' . $column : $fallback;
		};
		$parent_name_expr = in_array('hr_display_name', $profile_cols, true) ? "COALESCE(NULLIF(parent.hr_display_name,''), pu.display_name, '')" : "COALESCE(pu.display_name, '')";
		$display_expr = in_array('hr_display_name', $profile_cols, true) ? "COALESCE(NULLIF(p.hr_display_name,''), u.display_name, CONCAT('#', p.user_id))" : "COALESCE(u.display_name, CONCAT('#', p.user_id))";
		$placeholders = implode(',', array_fill(0, count($position_slugs), '%s'));
		$limit = max(1, min(2000, absint($limit)));
		$sql = "SELECT p.id profile_id, p.user_id, p.is_active,
			{$expr('employment_status', "'active'")} AS employment_status,
			{$expr('employment_type')} AS employment_type,
			{$expr('work_phone')} AS work_phone,
			{$expr('employee_code')} AS employee_code,
			{$display_expr} AS display_name,
			u.user_login, u.user_email,
			pos.slug position_slug, pos.label position_label,
			parent.id parent_profile_id, parent.user_id parent_user_id,
			parent_pos.slug parent_position_slug, parent_pos.label parent_position_label,
			{$parent_name_expr} AS parent_name
		FROM {$wpdb->prefix}sn_hr_profiles p
		LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
		LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
		LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.is_current=1 AND (a.relationship_type='reports_to' OR a.relationship_type='' OR a.relationship_type IS NULL)
		LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
		LEFT JOIN {$wpdb->prefix}sn_hr_positions parent_pos ON parent_pos.id=parent.position_id
		LEFT JOIN {$wpdb->users} pu ON pu.ID=parent.user_id
		WHERE pos.slug IN ({$placeholders})
		ORDER BY pos.sort_order ASC, p.is_active DESC, display_name ASC, p.user_id ASC
		LIMIT %d";
		return $wpdb->get_results($wpdb->prepare($sql, ...array_merge($position_slugs, [$limit])), ARRAY_A) ?: [];
	}

	private function sn_admin_status_counts(string $table, string $column): array
	{
		global $wpdb;
		$full = strpos($table, $wpdb->prefix) === 0 ? $table : $wpdb->prefix . ltrim($table, '_');
		if (! $this->sn_table_exists_quiet($full) || ! $this->sn_table_has_column($full, $column)) { return []; }
		$rows = $wpdb->get_results("SELECT COALESCE(NULLIF({$column},''),'none') k, COUNT(*) c FROM {$full} GROUP BY k ORDER BY c DESC", ARRAY_A) ?: [];
		$out = [];
		foreach ($rows as $row) { $out[(string) ($row['k'] ?? 'none')] = (int) ($row['c'] ?? 0); }
		return $out;
	}

	private function sn_admin_status_count_value(array $counts, array $keys): int
	{
		$total = 0;
		foreach ($keys as $key) { $total += (int) ($counts[$key] ?? 0); }
		return $total;
	}


