	public function render_admin_page(): void
	{
		if (! current_user_can('manage_options') && current_user_can('sn_view_wallet_commission')) {
			$this->render_admin_wallets();
			return;
		}
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		global $wpdb;
		$paid = $this->sn_admin_invoice_paid_condition('i');
		$amount = $this->sn_admin_invoice_amount_expr('i');
		$active_dist = $this->sn_admin_distribution_active_condition('di');
		$hr_counts = [];
		if ($this->sn_mis_table_exists('sn_hr_profiles') && $this->sn_mis_table_exists('sn_hr_positions')) {
			$hr_rows = $wpdb->get_results("SELECT pos.slug, pos.label, COUNT(*) c FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id WHERE p.is_active=1 GROUP BY pos.slug,pos.label ORDER BY pos.sort_order ASC", ARRAY_A) ?: [];
			foreach ($hr_rows as $row) { $hr_counts[(string) ($row['slug'] ?: 'none')] = ['label' => (string) ($row['label'] ?: 'بدون سمت'), 'count' => (int) $row['c']]; }
		}
		$mis_rows_total = $this->sn_safe_table_count('sn_mis_data_rows');
		$dist_total = $this->sn_safe_table_count('sn_distribution_items');
		$active_distribution = $this->sn_mis_table_exists('sn_distribution_items') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items di WHERE {$active_dist}") : 0;
		$final_to_seller = $this->sn_mis_table_exists('sn_distribution_items') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE final_seller_user_id IS NOT NULL AND final_seller_user_id > 0") : 0;
		$live_leads = $this->sn_mis_table_exists('sn_leads') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads") : 0;
		$invoice_total = $this->sn_mis_table_exists('sn_invoices') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices") : 0;
		$paid_invoice_count = $this->sn_mis_table_exists('sn_invoices') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices i WHERE {$paid}") : 0;
		$paid_revenue = $this->sn_mis_table_exists('sn_invoices') ? (float) $wpdb->get_var("SELECT COALESCE(SUM({$amount}),0) FROM {$wpdb->prefix}sn_invoices i WHERE {$paid}") : 0.0;
		$wallet_balance = $this->sn_mis_table_exists('sn_wallets') ? (float) $wpdb->get_var("SELECT COALESCE(SUM(balance),0) FROM {$wpdb->prefix}sn_wallets") : 0.0;
		$dist_status_counts = $this->sn_admin_status_counts('sn_distribution_items', 'status');
		$mis_status_counts = $this->sn_admin_status_counts('sn_mis_data_rows', 'row_status');
	?>
