	public function render_admin_leads(): void
	{
		global $wpdb;
		$filters = $this->get_lead_filters();
		[$where, $args] = $this->build_leads_where($filters);
		$page    = max(1, absint($_GET['paged'] ?? 1));
		$per     = 50;
		$offset  = ($page - 1) * $per;
		$count_sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE {$where}";
		$total = (int) ($args ? $wpdb->get_var($wpdb->prepare($count_sql, ...$args)) : $wpdb->get_var($count_sql));
		$pages = max(1, (int) ceil($total / $per));
		$list_sql = "SELECT * FROM {$wpdb->prefix}sn_leads WHERE {$where} ORDER BY id DESC LIMIT %d OFFSET %d";
		$list_args = array_merge($args, [$per, $offset]);
		$leads = $wpdb->get_results($wpdb->prepare($list_sql, ...$list_args), ARRAY_A);
		$all_total = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads");
		$raw = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE status='unassigned' AND seller_id IS NULL AND supervisor_id IS NULL");
		$pool = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE status='supervisor_pool'");
		$assigned = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE seller_id IS NOT NULL");
		$invoiced = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE status='invoiced'");
		$conv = $all_total ? round(($invoiced / $all_total) * 100, 1) : 0;
		$sellers = $this->sn_admin_invoice_user_options(['seller'], ['sn_seller']);
		$supervisors = $this->sn_admin_invoice_user_options(['supervisor', 'senior_supervisor'], ['sn_supervisor']);
		$lead_statuses = $wpdb->get_results("SELECT label FROM {$wpdb->prefix}sn_lead_statuses WHERE is_active=1 ORDER BY sort_order ASC, id ASC", ARRAY_A);
		$export_url = wp_nonce_url(add_query_arg(array_merge($_GET, ['sn_export' => 'leads']), admin_url('admin.php')), 'sn_export_leads');
		$status_labels = ['unassigned' => 'لیست خام / بدون تخصیص', 'supervisor_pool' => 'داخل پنل سرپرست', 'assigned' => 'تخصیص‌یافته به فروشنده', 'invoiced' => 'پیش‌فاکتور صادرشده'];
	?>
		<div class="wrap sn-admin" dir="rtl">
			<h1>مدیریت شماره‌ها</h1>
			<div style="display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px;margin:14px 0">
				<div class="sn-card"><strong><?php echo number_format_i18n($all_total); ?></strong><br><span>کل شماره‌ها</span></div>
				<div class="sn-card"><strong><?php echo number_format_i18n($raw); ?></strong><br><span>لیست خام</span></div>
				<div class="sn-card"><strong><?php echo number_format_i18n($pool); ?></strong><br><span>داخل پنل سرپرست</span></div>
				<div class="sn-card"><strong><?php echo number_format_i18n($assigned); ?></strong><br><span>تخصیص به فروشنده</span></div>
				<div class="sn-card"><strong><?php echo esc_html($conv); ?>٪</strong><br><span>نرخ تبدیل به فاکتور</span></div>
			</div>
			<div class="sn-card" style="margin-bottom:20px">
				<h3>آپلود فایل CSV</h3>
				<p>فایل CSV با ستون شماره موبایل آپلود کنید. اگر ستون <code>code</code> یا <code>import_code</code> داشته باشد، کد هر ردیف ذخیره می‌شود.</p>
				<input type="text" id="sn-import-code" class="regular-text" placeholder="کد کلی فایل، مثلاً ORD-1403-02" style="margin-left:8px">
				<input type="file" id="sn-import-file" accept=".csv">
				<button type="button" id="sn-do-import" class="button button-primary" style="margin-right:8px">آپلود و وارد کردن</button>
				<span id="sn-import-result"></span>
			</div>
			<form method="get" class="sn-card" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin-bottom:14px">
				<input type="hidden" name="page" value="sn-leads">
				<label>جستجو<br><input type="search" name="sn_search" value="<?php echo esc_attr($filters['search']); ?>" placeholder="شماره، شهر، یادداشت، کد"></label>
				<label>کد واردات<br><input type="text" name="sn_import_code" value="<?php echo esc_attr($filters['import_code']); ?>" placeholder="کد فایل/شماره"></label>
				<label>وضعیت سیستمی<br><select name="sn_status">
						<option value="all">همه</option><?php foreach ($status_labels as $k => $v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($filters['status'], $k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?>
					</select></label>
				<label>وضعیت تماس<br><select name="sn_lead_status">
						<option value="">همه</option><?php foreach ($lead_statuses as $st): ?><option value="<?php echo esc_attr($st['label']); ?>" <?php selected($filters['lead_status'], $st['label']); ?>><?php echo esc_html($st['label']); ?></option><?php endforeach; ?>
					</select></label>
				<label>سرپرست<br><select name="sn_supervisor_id">
						<option value="0">همه</option><?php foreach ($supervisors as $sup): ?><option value="<?php echo esc_attr($sup->ID); ?>" <?php selected($filters['supervisor_id'], $sup->ID); ?>><?php echo esc_html($sup->display_name); ?></option><?php endforeach; ?>
					</select></label>
				<label>فروشنده<br><select name="sn_seller_id">
						<option value="0">همه</option><?php foreach ($sellers as $seller): ?><option value="<?php echo esc_attr($seller->ID); ?>" <?php selected($filters['seller_id'], $seller->ID); ?>><?php echo esc_html($seller->display_name); ?></option><?php endforeach; ?>
					</select></label>
				<label>از تاریخ تخصیص<br><input type="text" class="sn-jalali-date" name="sn_date_from" value="<?php echo esc_attr($filters['date_from']); ?>" placeholder="1403/02/18"></label>
				<label>تا تاریخ تخصیص<br><input type="text" class="sn-jalali-date" name="sn_date_to" value="<?php echo esc_attr($filters['date_to']); ?>" placeholder="1403/02/18"></label>
				<label>از ساعت تهران<br><input type="time" name="sn_time_from" value="<?php echo esc_attr($filters['time_from']); ?>"></label>
				<label>تا ساعت تهران<br><input type="time" name="sn_time_to" value="<?php echo esc_attr($filters['time_to']); ?>"></label>
				<button class="button button-primary">فیلتر</button>
				<a class="button" href="<?php echo esc_url(admin_url('admin.php?page=sn-leads')); ?>">پاک کردن</a>
				<a class="button button-secondary" href="<?php echo esc_url($export_url); ?>">خروجی اکسل</a>
			</form>
			<p><strong><?php echo number_format_i18n($total); ?></strong> شماره مطابق فیلتر فعلی پیدا شد.</p>
			<table class="wp-list-table widefat fixed striped">
				<thead>
					<tr>
						<th>#</th>
						<th>شماره</th>
						<th>کد</th>
						<th>استان/شهر</th>
						<th>وضعیت سیستمی</th>
						<th>وضعیت تماس</th>
						<th>سرپرست</th>
						<th>فروشنده</th>
						<th>تاریخ ورود</th>
						<th>تاریخ تخصیص</th>
					</tr>
				</thead>
				<tbody>
					<?php foreach ($leads as $l) : $seller = $l['seller_id'] ? get_user_by('id', $l['seller_id']) : null;
						$supervisor = ! empty($l['supervisor_id']) ? get_user_by('id', $l['supervisor_id']) : null; ?>
						<tr>
							<td><?php echo (int) $l['id']; ?></td>
							<td><?php echo esc_html($l['phone']); ?></td>
							<td><?php echo esc_html($l['import_code'] ?: '—'); ?></td>
							<td><?php echo esc_html(trim(($l['province'] ?: '') . ' / ' . ($l['city'] ?: ''), ' /') ?: '—'); ?></td>
							<td><span class="sn-status sn-status-<?php echo esc_attr($l['status']); ?>"><?php echo esc_html($status_labels[$l['status']] ?? $l['status']); ?></span></td>
							<td><?php echo esc_html($l['lead_status'] ?: '—'); ?></td>
							<td><?php echo $supervisor ? esc_html($supervisor->display_name) : '—'; ?></td>
							<td><?php echo $seller ? esc_html($seller->display_name) : '—'; ?></td>
							<td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date($l['imported_at'])); ?></td>
							<td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date($l['assigned_at'] ?: '')); ?></td>
						</tr>
					<?php endforeach; ?>
				</tbody>
			</table>
			<?php if ($pages > 1) : ?><div class="tablenav bottom">
					<div class="tablenav-pages"><?php echo paginate_links(['total' => $pages, 'current' => $page, 'add_args' => array_filter($_GET)]); ?></div>
				</div><?php endif; ?>
		</div>
	<?php
	}

	public function render_admin_sellers(): void
	{
		global $wpdb;
		$sellers = $this->sn_admin_hr_people_by_positions(['seller'], 1200);
		if (empty($sellers)) {
			foreach (get_users(['role__in' => ['sn_seller'], 'number' => 1200]) as $u) {
				$sellers[] = ['profile_id' => 0, 'user_id' => (int) $u->ID, 'display_name' => $u->display_name, 'user_login' => $u->user_login, 'position_label' => 'فروشنده', 'position_slug' => 'seller', 'is_active' => 1, 'employment_status' => 'active', 'parent_name' => '', 'parent_user_id' => 0, 'parent_position_label' => ''];
			}
		}
		$user_ids = array_values(array_unique(array_filter(array_map('intval', array_column($sellers, 'user_id')))));
		$legacy_leads = $this->sn_admin_group_count_by_user('sn_leads', 'seller_id', $user_ids);
		$active_dist = $this->sn_admin_distribution_active_condition('di');
		$owned_distribution = $this->sn_admin_group_count_by_user('sn_distribution_items', 'current_owner_user_id', $user_ids, str_replace('di.', '', $active_dist));
		$final_distribution = $this->sn_admin_group_count_by_user('sn_distribution_items', 'final_seller_user_id', $user_ids);
		$invoice_metrics = $this->sn_admin_invoice_metrics_by_seller($user_ids);
		$wallets = $this->sn_admin_wallet_map($user_ids);
		$total_sellers = count($sellers);
		$active_sellers = count(array_filter($sellers, static fn($r) => (int) ($r['is_active'] ?? 0) === 1 && ! in_array((string) ($r['employment_status'] ?? ''), ['inactive','suspended','resigned','terminated'], true)));
		$with_parent = count(array_filter($sellers, static fn($r) => ! empty($r['parent_user_id'])));
		$paid_revenue_total = array_sum(array_map(static fn($m) => (float) ($m['paid_revenue'] ?? 0), $invoice_metrics));
		$export_url = wp_nonce_url(add_query_arg(['page' => 'sn-sellers', 'sn_export' => 'sellers'], admin_url('admin.php')), 'sn_export_sellers');
	?>
		<div class="wrap sn-admin sn-admin-modern" dir="rtl">
			<h1>فروشندگان</h1>
			<div class="notice notice-info inline"><p>این صفحه از پروفایل HR و موتور Distribution نسخه فعلی خوانده می‌شود. ستون «لید زنده» فقط داده‌های تبدیل‌شده/قدیمی جدول شماره‌هاست و معیار اصلی تخصیص، آیتم‌های پخش است.</p></div>
			<div class="sn-stats-grid sn-admin-kpi-grid">
				<div class="sn-stat"><span><?php echo number_format_i18n($total_sellers); ?></span><label>کل فروشنده‌های HR</label></div>
				<div class="sn-stat sn-stat-success"><span><?php echo number_format_i18n($active_sellers); ?></span><label>فعال</label></div>
				<div class="sn-stat"><span><?php echo number_format_i18n($with_parent); ?></span><label>دارای بالادستی HR</label></div>
				<div class="sn-stat sn-stat-primary"><span><?php echo esc_html(SN_Helpers::format_price((float) $paid_revenue_total)); ?></span><label>فروش تاییدشده فروشنده‌ها</label></div>
			</div>
			<p><a class="button" href="<?php echo esc_url($export_url); ?>">خروجی اکسل</a></p>
			<table class="wp-list-table widefat fixed striped sn-admin-report-table">
				<thead><tr><th>فروشنده</th><th>بالادستی HR</th><th>وضعیت HR</th><th>در پنل فروشنده</th><th>تحویل نهایی</th><th>لید زنده</th><th>فاکتور</th><th>تایید/پرداخت</th><th>فروش تاییدشده</th><th>کیف پول</th></tr></thead>
				<tbody>
				<?php foreach ($sellers as $s) :
					$uid = (int) ($s['user_id'] ?? 0);
					$im = $invoice_metrics[$uid] ?? ['invoice_count' => 0, 'paid_count' => 0, 'paid_revenue' => 0];
					$wallet = $wallets[$uid]['seller'] ?? [];
					$is_active = (int) ($s['is_active'] ?? 0) === 1 && ! in_array((string) ($s['employment_status'] ?? ''), ['inactive','suspended','resigned','terminated'], true);
				?>
					<tr>
						<td><strong><?php echo esc_html((string) ($s['display_name'] ?? '')); ?></strong><br><small><?php echo esc_html((string) ($s['user_login'] ?? '')); ?> #<?php echo (int) $uid; ?></small></td>
						<td><?php echo ! empty($s['parent_user_id']) ? esc_html(trim(($s['parent_name'] ?: ('#' . $s['parent_user_id'])) . ' - ' . ($s['parent_position_label'] ?: ''))) : '<span class="sn-muted">بدون بالادستی</span>'; ?></td>
						<td><?php echo $is_active ? '<span class="sn-badge sn-status-approved">فعال</span>' : '<span class="sn-badge sn-status-rejected">غیرفعال</span>'; ?><br><small><?php echo esc_html((string) ($s['employment_status'] ?: '—')); ?></small></td>
						<td><?php echo number_format_i18n((int) ($owned_distribution[$uid] ?? 0)); ?></td>
						<td><?php echo number_format_i18n((int) ($final_distribution[$uid] ?? 0)); ?></td>
						<td><?php echo number_format_i18n((int) ($legacy_leads[$uid] ?? 0)); ?></td>
						<td><?php echo number_format_i18n((int) ($im['invoice_count'] ?? 0)); ?></td>
						<td><?php echo number_format_i18n((int) ($im['paid_count'] ?? 0)); ?></td>
						<td><?php echo esc_html(SN_Helpers::format_price((float) ($im['paid_revenue'] ?? 0))); ?></td>
						<td><?php echo esc_html(SN_Helpers::format_price((float) ($wallet['balance'] ?? 0))); ?></td>
					</tr>
				<?php endforeach; ?>
				<?php if (empty($sellers)) : ?><tr><td colspan="10">فروشنده‌ای در HR ثبت نشده است.</td></tr><?php endif; ?>
				</tbody>
			</table>
		</div>
	<?php
	}


	public function render_admin_supervisors(): void
	{
		global $wpdb;
		$leaders = $this->sn_admin_hr_people_by_positions(['sales_manager','senior_supervisor','supervisor'], 800);
		if (empty($leaders)) {
			foreach (get_users(['role__in' => ['sn_supervisor'], 'number' => 800]) as $u) {
				$leaders[] = ['profile_id' => 0, 'user_id' => (int) $u->ID, 'display_name' => $u->display_name, 'user_login' => $u->user_login, 'position_label' => 'سرپرست', 'position_slug' => 'supervisor', 'is_active' => 1, 'employment_status' => 'active', 'parent_name' => '', 'parent_user_id' => 0, 'parent_position_label' => ''];
			}
		}
		$user_ids = array_values(array_unique(array_filter(array_map('intval', array_column($leaders, 'user_id')))));
		$active_dist = $this->sn_admin_distribution_active_condition('di');
		$owned_distribution = $this->sn_admin_group_count_by_user('sn_distribution_items', 'current_owner_user_id', $user_ids, str_replace('di.', '', $active_dist));
		$legacy_pool = $this->sn_admin_group_count_by_user('sn_leads', 'supervisor_id', $user_ids);
		$wallets = $this->sn_admin_wallet_map($user_ids);
		$total = count($leaders);
		$active = count(array_filter($leaders, static fn($r) => (int) ($r['is_active'] ?? 0) === 1 && ! in_array((string) ($r['employment_status'] ?? ''), ['inactive','suspended','resigned','terminated'], true)));
		$by_position = [];
		foreach ($leaders as $r) { $by_position[(string) ($r['position_slug'] ?? 'none')] = ($by_position[(string) ($r['position_slug'] ?? 'none')] ?? 0) + 1; }
	?>
		<div class="wrap sn-admin sn-admin-modern" dir="rtl">
			<h1>مدیرها و سرپرست‌ها</h1>
			<div class="notice notice-info inline"><p>این بخش دیگر فقط role قدیمی وردپرس را معیار نمی‌گیرد؛ ساختار واقعی از HR reports_to خوانده می‌شود: مدیر فروش ← سرپرست ارشد ← سرپرست ← فروشنده.</p></div>
			<div class="sn-stats-grid sn-admin-kpi-grid">
				<div class="sn-stat"><span><?php echo number_format_i18n($total); ?></span><label>کل مدیر/سرپرست‌ها</label></div>
				<div class="sn-stat sn-stat-success"><span><?php echo number_format_i18n($active); ?></span><label>فعال</label></div>
				<div class="sn-stat"><span><?php echo number_format_i18n((int) ($by_position['sales_manager'] ?? 0)); ?></span><label>مدیر فروش</label></div>
				<div class="sn-stat"><span><?php echo number_format_i18n((int) ($by_position['senior_supervisor'] ?? 0)); ?></span><label>سرپرست ارشد</label></div>
				<div class="sn-stat"><span><?php echo number_format_i18n((int) ($by_position['supervisor'] ?? 0)); ?></span><label>سرپرست</label></div>
			</div>
