	private function sn_finance_cap_labels(): array
	{
		return [
			'sn_view_finance' => 'مشاهده مالی',
			'sn_approve_payment' => 'تأیید پرداخت',
			'sn_reject_payment' => 'رد پرداخت',
			'sn_view_wallet_commission' => 'مشاهده کیف پول و پورسانت',
		];
	}

	private function sn_get_finance_users(): array
	{
		$users = [];
		$queries = [
			['role__in' => ['sn_financial', 'sn_financial_approval', 'sn_finance']],
			['capability__in' => array_keys($this->sn_finance_cap_labels())],
		];
		foreach ($queries as $args) {
			$args['fields'] = 'all';
			foreach (get_users($args) as $user) {
				if ($user instanceof WP_User) {
					$users[(int) $user->ID] = $user;
				}
			}
		}
		ksort($users);
		return array_values($users);
	}

	private function sn_find_user_for_finance(string $lookup): ?WP_User
	{
		$lookup = trim($lookup);
		if ($lookup === '') { return null; }
		if (ctype_digit($lookup)) {
			$user = get_user_by('id', (int) $lookup);
			if ($user instanceof WP_User) { return $user; }
		}
		if (is_email($lookup)) {
			$user = get_user_by('email', $lookup);
			if ($user instanceof WP_User) { return $user; }
		}
		$user = get_user_by('login', $lookup);
		return $user instanceof WP_User ? $user : null;
	}

	private function sn_apply_finance_user_caps(WP_User $user, array $selected_caps): void
	{
		if (! get_role('sn_financial')) {
			add_role('sn_financial', 'تایید مالی', ['read' => true]);
		}
		if (! in_array('sn_financial', (array) $user->roles, true)) {
			$user->add_role('sn_financial');
		}
		$legacy_map = [
			'sn_view_finance' => 'sn_view_payments',
			'sn_approve_payment' => 'sn_approve_payments',
			'sn_reject_payment' => 'sn_reject_payments',
			'sn_view_wallet_commission' => '',
		];
		foreach (array_keys($this->sn_finance_cap_labels()) as $cap) {
			if (in_array($cap, $selected_caps, true)) {
				$user->add_cap($cap);
			} else {
				$user->remove_cap($cap);
				if (! empty($legacy_map[$cap])) {
					$user->remove_cap($legacy_map[$cap]);
				}
			}
		}
	}

	public function handle_save_finance_user(): void
	{
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_save_finance_user');
		$user_id = absint($_POST['user_id'] ?? 0);
		$user = $user_id ? get_user_by('id', $user_id) : $this->sn_find_user_for_finance(sanitize_text_field(wp_unslash($_POST['user_lookup'] ?? '')));
		if (! $user instanceof WP_User) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-finance-users', 'sn_msg' => 'user_not_found'], admin_url('admin.php')));
			exit;
		}
		$raw_caps = isset($_POST['finance_caps']) && is_array($_POST['finance_caps']) ? array_map('sanitize_key', wp_unslash($_POST['finance_caps'])) : [];
		$selected_caps = array_values(array_intersect($raw_caps, array_keys($this->sn_finance_cap_labels())));
		$this->sn_apply_finance_user_caps($user, $selected_caps);
		$msg = (! in_array('sn_view_finance', $selected_caps, true) && array_intersect($selected_caps, ['sn_approve_payment', 'sn_reject_payment'])) ? 'saved_without_view' : 'saved';
		wp_safe_redirect(add_query_arg(['page' => 'sn-finance-users', 'sn_msg' => $msg], admin_url('admin.php')));
		exit;
	}

