	private function sn_hr_tables_status(): array
	{
		global $wpdb;
		$tables = [
			'sn_hr_positions',
			'sn_hr_levels',
			'sn_hr_profiles',
			'sn_hr_position_role_mappings',
			'sn_hr_profile_logs',
			'sn_hr_assignments',
			'sn_hr_assignment_history',
		];
		$status = [];
		foreach ($tables as $table) {
			$full = $wpdb->prefix . $table;
			$status[$table] = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $full)) === $full;
		}
		return $status;
	}

	private function sn_hr_count(string $table): int
	{
		global $wpdb;
		$full = $wpdb->prefix . $table;
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $full)) !== $full) {
			return 0;
		}
		return (int) $wpdb->get_var("SELECT COUNT(*) FROM {$full}");
	}

	public function handle_save_hr_role_mappings(): void
	{
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_save_hr_role_mappings');
		if (class_exists('SN_Migration_Service')) {
			(new SN_Migration_Service())->migrate_if_needed();
		}
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_position_role_mappings';
		$roles = isset($_POST['legacy_role']) && is_array($_POST['legacy_role']) ? array_map('sanitize_key', wp_unslash($_POST['legacy_role'])) : [];
		$positions = isset($_POST['position_id']) && is_array($_POST['position_id']) ? array_map('absint', wp_unslash($_POST['position_id'])) : [];
		$levels = isset($_POST['default_level_id']) && is_array($_POST['default_level_id']) ? array_map('absint', wp_unslash($_POST['default_level_id'])) : [];
		$active = isset($_POST['is_active']) && is_array($_POST['is_active']) ? array_map('sanitize_key', wp_unslash($_POST['is_active'])) : [];
		foreach ($roles as $idx => $role) {
			if ($role === '') { continue; }
			$data = [
				'legacy_role' => $role,
				'position_id' => (int) ($positions[$idx] ?? 0),
				'default_level_id' => ! empty($levels[$idx]) ? (int) $levels[$idx] : null,
				'is_active' => in_array($role, $active, true) ? 1 : 0,
			];
			if ($data['position_id'] < 1) { continue; }
			$existing = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE legacy_role=%s", $role));
			if ($existing) {
				$wpdb->update($table, $data, ['id' => (int) $existing]);
			} else {
				$wpdb->insert($table, $this->sn_filter_existing_columns($table, $data));
			}
		}
		wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'mapping_saved'], admin_url('admin.php')));
		exit;
	}

