	private function sn_find_hr_profile_by_lookup(string $lookup)
	{
		$lookup = trim($lookup);
		if ($lookup === '') { return null; }
		$user = $this->sn_find_user_by_lookup($lookup);
		if (! $user instanceof WP_User || ! class_exists('SN_HR_Service')) { return null; }
		return (new SN_HR_Service())->get_or_create_profile_for_user((int) $user->ID);
	}

	private function sn_find_user_by_lookup(string $lookup)
	{
		$lookup = trim($lookup);
		if ($lookup === '') { return null; }
		$user = null;
		if (ctype_digit($lookup)) {
			$user = get_user_by('id', (int) $lookup);
		}
		if (! $user && is_email($lookup)) {
			$user = get_user_by('email', $lookup);
		}
		if (! $user) {
			$user = get_user_by('login', $lookup);
		}
		if (! $user && class_exists('SN_Helpers')) {
			$mobile = SN_Helpers::normalize_mobile($lookup);
			if ($mobile !== '') {
				foreach ([$mobile, 'user_' . $mobile] as $login_candidate) {
					$user = get_user_by('login', $login_candidate);
					if ($user instanceof WP_User) {
						break;
					}
				}
				if (! $user) {
					global $wpdb;
					$meta_keys = ['phone', 'mobile', 'user_phone', 'billing_phone', 'sn_phone'];
					$placeholders = implode(',', array_fill(0, count($meta_keys), '%s'));
					$args = array_merge($meta_keys, [$mobile, $lookup]);
					$user_id = (int) $wpdb->get_var($wpdb->prepare(
						"SELECT user_id FROM {$wpdb->usermeta} WHERE meta_key IN ({$placeholders}) AND meta_value IN (%s,%s) ORDER BY user_id ASC LIMIT 1",
						...$args
					));
					if ($user_id > 0) {
						$user = get_user_by('id', $user_id);
					}
				}
			}
		}
		return $user instanceof WP_User ? $user : null;
	}

	public function handle_assign_hr_parent(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_assign_hr_parent');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		$child = $this->sn_find_hr_profile_by_lookup(sanitize_text_field(wp_unslash($_POST['child_lookup'] ?? '')));
		$parent = $this->sn_find_hr_profile_by_lookup(sanitize_text_field(wp_unslash($_POST['parent_lookup'] ?? '')));
		if (! $child || ! $parent || ! class_exists('SN_Hierarchy_Service')) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'hierarchy_error'], admin_url('admin.php')));
			exit;
		}
		$result = (new SN_Hierarchy_Service())->assign_parent((int) $child->id, (int) $parent->id, get_current_user_id(), 'manual', sanitize_text_field(wp_unslash($_POST['reason'] ?? '')));
		wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => ! empty($result['success']) ? 'hierarchy_saved' : 'hierarchy_error'], admin_url('admin.php')));
		exit;
	}

