	public function handle_bulk_hr_hierarchy_repair(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_bulk_hr_hierarchy_repair');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		if (! class_exists('SN_Hierarchy_Service')) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'hierarchy_error'], admin_url('admin.php')));
			exit;
		}
		$repair_type = sanitize_key(wp_unslash($_POST['repair_type'] ?? ''));
		$mode = sanitize_key(wp_unslash($_POST['repair_mode'] ?? 'dry_run'));
		$dry_run = $mode !== 'apply';
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		if (! $dry_run && $confirm !== 'APPLY') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'bulk_hierarchy_confirm_missing'], admin_url('admin.php')));
			exit;
		}
		$parent = $this->sn_find_hr_profile_by_lookup(sanitize_text_field(wp_unslash($_POST['parent_lookup'] ?? '')));
		if (! $parent) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'hierarchy_error'], admin_url('admin.php')));
			exit;
		}
		$only_without_parent = ! empty($_POST['only_without_parent']);
		if ($repair_type === 'sales_managers_to_deputy') {
			$child_position = 'sales_manager';
		} else {
			$child_position = $repair_type === 'unassigned_sellers' ? 'seller' : 'supervisor';
		}
		if ($repair_type === 'unassigned_sellers') {
			$only_without_parent = true;
		}
		$hierarchy = new SN_Hierarchy_Service();
		$report = $hierarchy->bulk_assign_position_to_parent((int) $parent->user_id, $child_position, $only_without_parent, $dry_run, get_current_user_id());
		$report['repair_type'] = $repair_type;
		update_option('sn_hr_bulk_hierarchy_repair_report', $report, false);
		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'bulk_hierarchy_repair_done',
			'bulk_mode' => $dry_run ? 'dry_run' : 'apply',
			'bulk_assigned' => (int) ($report['assigned'] ?? 0),
			'bulk_eligible' => (int) ($report['eligible'] ?? 0),
			'bulk_errors' => (int) ($report['errors'] ?? 0),
		], admin_url('admin.php')));
		exit;
	}

	public function handle_restore_seller_hierarchy_from_leads(): void
	{
		if (! current_user_can('manage_options')) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_restore_seller_hierarchy_from_leads');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		if (! class_exists('SN_Hierarchy_Service')) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'legacy_lead_hierarchy_error'], admin_url('admin.php')));
			exit;
		}

		$mode = sanitize_key(wp_unslash($_POST['restore_mode'] ?? 'dry_run'));
		$dry_run = $mode !== 'apply';
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		if (! $dry_run && $confirm !== 'APPLY') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'legacy_lead_hierarchy_confirm_missing'], admin_url('admin.php')));
			exit;
		}

		$conflict_strategy = sanitize_key(wp_unslash($_POST['conflict_strategy'] ?? 'keep_existing'));
		if (! in_array($conflict_strategy, ['keep_existing', 'report_conflict', 'overwrite'], true)) {
			$conflict_strategy = 'keep_existing';
		}
		$override_confirm = sanitize_text_field(wp_unslash($_POST['confirm_override'] ?? ''));
		$report = $this->sn_restore_seller_hierarchy_from_leads_report([
			'dry_run' => $dry_run,
			'only_unassigned_sellers' => ! empty($_POST['only_unassigned_sellers']),
			'supervisor_filter' => absint($_POST['supervisor_filter'] ?? 0),
			'seller_filter' => absint($_POST['seller_filter'] ?? 0),
			'conflict_strategy' => $conflict_strategy,
			'allow_override' => $conflict_strategy === 'overwrite' && $override_confirm === 'OVERRIDE',
			'reason' => sanitize_text_field(wp_unslash($_POST['reason'] ?? '')),
		]);
		update_option('sn_hr_legacy_lead_hierarchy_restore_report', $report, false);

		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'legacy_lead_hierarchy_done',
			'legacy_mode' => $dry_run ? 'dry_run' : 'apply',
			'legacy_eligible' => (int) ($report['eligible_assignments'] ?? 0),
			'legacy_assigned' => (int) ($report['assigned'] ?? 0),
			'legacy_errors' => (int) ($report['errors'] ?? 0),
		], admin_url('admin.php')));
		exit;
	}

	private function sn_restore_seller_hierarchy_from_leads_report(array $args): array
	{
		global $wpdb;
		$dry_run = ! empty($args['dry_run']);
		$only_unassigned = ! empty($args['only_unassigned_sellers']);
		$supervisor_filter = absint($args['supervisor_filter'] ?? 0);
		$seller_filter = absint($args['seller_filter'] ?? 0);
		$conflict_strategy = sanitize_key((string) ($args['conflict_strategy'] ?? 'keep_existing'));
		$allow_override = ! empty($args['allow_override']);
		$reason = sanitize_text_field((string) ($args['reason'] ?? ''));
		$reason = $reason ?: 'Restore seller hierarchy from legacy lead supervisor_id';
		$report = [
			'tool' => 'restore_seller_hierarchy_from_leads',
			'mode' => $dry_run ? 'dry_run' : 'apply',
			'only_unassigned_sellers' => $only_unassigned,
			'supervisor_filter' => $supervisor_filter,
			'seller_filter' => $seller_filter,
			'conflict_strategy' => $conflict_strategy,
			'override_enabled' => $allow_override,
			'sellers_scanned' => 0,
			'sellers_with_legacy_supervisor' => 0,
			'eligible_assignments' => 0,
			'assigned' => 0,
			'already_assigned_skipped' => 0,
			'no_legacy_supervisor_skipped' => 0,
			'missing_supervisor_profile_skipped' => 0,
			'invalid_supervisor_position_skipped' => 0,
			'conflict_count' => 0,
			'cycle_rejected' => 0,
			'self_manager_skipped' => 0,
			'errors' => 0,
			'affected_sample' => [],
			'summary_by_manager' => [],
			'sales_manager_warning' => $this->sn_restore_sales_manager_warning_rows(),
			'updated_at' => current_time('mysql'),
		];

		$leads_table = $wpdb->prefix . 'sn_leads';
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $leads_table)) !== $leads_table) {
			$report['errors']++;
			$report['message'] = 'sn_leads_missing';
			return $report;
		}
		$lead_cols = $this->sn_table_columns($leads_table);
		if (! in_array('seller_id', $lead_cols, true) || ! in_array('supervisor_id', $lead_cols, true)) {
			$report['errors']++;
			$report['message'] = 'required_lead_columns_missing';
			$report['lead_columns_checked'] = ['seller_id' => in_array('seller_id', $lead_cols, true), 'supervisor_id' => in_array('supervisor_id', $lead_cols, true)];
			return $report;
		}

		$seller_where = ["pos.slug='seller'"];
		$seller_params = [];
		if ($seller_filter) {
			$seller_where[] = 'p.user_id=%d';
			$seller_params[] = $seller_filter;
		}
		$seller_sql = "SELECT p.id profile_id, p.user_id, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, a.parent_profile_id current_parent_profile_id, parent.user_id current_manager_user_id, COALESCE(NULLIF(parent.hr_display_name,''), pu.display_name) current_manager_display_name
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.relationship_type='reports_to' AND a.is_current=1
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->users} pu ON pu.ID=parent.user_id
			WHERE " . implode(' AND ', $seller_where) . "
			ORDER BY p.user_id ASC";
		$sellers = $wpdb->get_results($seller_params ? $wpdb->prepare($seller_sql, ...$seller_params) : $seller_sql) ?: [];
		$hierarchy = new SN_Hierarchy_Service();

		foreach ($sellers as $seller) {
			$report['sellers_scanned']++;
			$seller_user_id = (int) $seller->user_id;
			$suggestion = $this->sn_restore_legacy_supervisor_suggestion($seller_user_id, $supervisor_filter, $lead_cols);
			if (empty($suggestion)) {
				$report['no_legacy_supervisor_skipped']++;
				continue;
			}
			$report['sellers_with_legacy_supervisor']++;
			$manager_user_id = (int) ($suggestion['supervisor_id'] ?? 0);
			if ($manager_user_id === $seller_user_id) {
				$report['self_manager_skipped']++;
				$this->sn_restore_append_sample($report, $seller, null, $suggestion, 'self_manager');
				continue;
			}
			$manager = $wpdb->get_row($wpdb->prepare(
				"SELECT p.id profile_id, p.user_id, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug position_slug, pos.label position_label
				FROM {$wpdb->prefix}sn_hr_profiles p
				INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
				LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
				WHERE p.user_id=%d",
				$manager_user_id
			));
			if (! $manager) {
				$report['missing_supervisor_profile_skipped']++;
				$this->sn_restore_append_sample($report, $seller, null, $suggestion, 'supervisor_profile_missing');
				continue;
			}
			if (! in_array((string) $manager->position_slug, ['senior_supervisor', 'supervisor', 'sales_manager'], true)) {
				$report['invalid_supervisor_position_skipped']++;
				$this->sn_restore_append_sample($report, $seller, $manager, $suggestion, 'manager_position_not_allowed');
				continue;
			}
			$current_parent = (int) ($seller->current_parent_profile_id ?? 0);
			if ($current_parent) {
				if ($current_parent === (int) $manager->profile_id) {
					$report['already_assigned_skipped']++;
					$this->sn_restore_append_sample($report, $seller, $manager, $suggestion, 'already_assigned_to_suggested_manager');
					continue;
				}
				if ($only_unassigned || in_array($conflict_strategy, ['keep_existing', 'report_conflict'], true) || ($conflict_strategy === 'overwrite' && ! $allow_override)) {
					$report['conflict_count']++;
					$this->sn_restore_append_sample($report, $seller, $manager, $suggestion, 'conflict_existing_manager');
					continue;
				}
			}
			if ($hierarchy->would_create_cycle((int) $seller->profile_id, (int) $manager->profile_id)) {
				$report['cycle_rejected']++;
				$this->sn_restore_append_sample($report, $seller, $manager, $suggestion, 'cycle_rejected');
				continue;
			}
			$report['eligible_assignments']++;
			$manager_key = (string) (int) $manager->user_id;
			if (! isset($report['summary_by_manager'][$manager_key])) {
				$report['summary_by_manager'][$manager_key] = [
					'manager_user_id' => (int) $manager->user_id,
					'manager_label' => $this->sn_user_label((int) $manager->user_id),
					'manager_position' => (string) $manager->position_slug,
					'eligible_sellers' => 0,
					'assigned' => 0,
				];
			}
			$report['summary_by_manager'][$manager_key]['eligible_sellers']++;
			$this->sn_restore_append_sample($report, $seller, $manager, $suggestion, $dry_run ? 'would_assign' : 'eligible');
			if ($dry_run) {
				continue;
			}
			$result = $hierarchy->assign_parent((int) $seller->profile_id, (int) $manager->profile_id, get_current_user_id(), 'legacy_lead_supervisor_id', $reason);
			if (empty($result['success'])) {
				if (($result['message'] ?? '') === 'cycle_not_allowed') {
					$report['cycle_rejected']++;
				} else {
					$report['errors']++;
				}
				continue;
			}
			if (! empty($result['skipped'])) {
				$report['already_assigned_skipped']++;
				continue;
			}
			$report['assigned']++;
			$report['summary_by_manager'][$manager_key]['assigned']++;
		}

		$report['summary_by_manager'] = array_values($report['summary_by_manager']);
		return $report;
	}

	private function sn_restore_legacy_supervisor_suggestion(int $seller_user_id, int $supervisor_filter, array $lead_cols): array
	{
		global $wpdb;
		$date_cols = array_values(array_intersect(['assigned_at', 'updated_at', 'imported_at', 'created_at'], $lead_cols));
		if (count($date_cols) === 1) {
			$date_expr = 'MAX(COALESCE(l.' . $date_cols[0] . ", '1970-01-01 00:00:00'))";
		} elseif (count($date_cols) > 1) {
			$date_expr = 'MAX(GREATEST(' . implode(',', array_map(static function($col) { return 'COALESCE(l.' . $col . ", '1970-01-01 00:00:00')"; }, $date_cols)) . '))';
		} else {
			$date_expr = "MAX('1970-01-01 00:00:00')";
		}
		$where = ['l.seller_id=%d', 'l.supervisor_id IS NOT NULL', 'l.supervisor_id > 0'];
		$params = [$seller_user_id];
		if ($supervisor_filter) {
			$where[] = 'l.supervisor_id=%d';
			$params[] = $supervisor_filter;
		}
		$total_sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads l WHERE l.seller_id=%d AND l.supervisor_id IS NOT NULL AND l.supervisor_id > 0";
		$total = (int) $wpdb->get_var($wpdb->prepare($total_sql, $seller_user_id));
		$sql = "SELECT l.supervisor_id, COUNT(*) lead_count, {$date_expr} latest_lead_date, MAX(l.id) latest_lead_id
			FROM {$wpdb->prefix}sn_leads l
			WHERE " . implode(' AND ', $where) . "
			GROUP BY l.supervisor_id
			ORDER BY lead_count DESC, latest_lead_date DESC, latest_lead_id DESC
			LIMIT 1";
		$row = $wpdb->get_row($wpdb->prepare($sql, ...$params), ARRAY_A);
		if (! $row) {
			return [];
		}
		return [
			'supervisor_id' => (int) $row['supervisor_id'],
			'lead_count' => (int) $row['lead_count'],
			'total_lead_count' => $total,
			'latest_lead_date' => (string) ($row['latest_lead_date'] ?? ''),
			'latest_lead_id' => (int) ($row['latest_lead_id'] ?? 0),
		];
	}

	private function sn_restore_append_sample(array &$report, $seller, $manager, array $suggestion, string $reason): void
	{
		if (count($report['affected_sample']) >= 100) {
			return;
		}
		$report['affected_sample'][] = [
			'seller_user_id' => (int) ($seller->user_id ?? 0),
			'seller_label' => $this->sn_user_label((int) ($seller->user_id ?? 0)),
			'current_manager_user_id' => (int) ($seller->current_manager_user_id ?? 0),
			'current_manager_label' => ! empty($seller->current_manager_user_id) ? $this->sn_user_label((int) $seller->current_manager_user_id) : '',
			'suggested_manager_user_id' => (int) ($suggestion['supervisor_id'] ?? 0),
			'suggested_manager_label' => $manager ? $this->sn_user_label((int) $manager->user_id) : ('#' . (int) ($suggestion['supervisor_id'] ?? 0)),
			'manager_position' => $manager ? (string) $manager->position_slug : '',
			'lead_count_for_manager' => (int) ($suggestion['lead_count'] ?? 0),
			'total_legacy_lead_count' => (int) ($suggestion['total_lead_count'] ?? 0),
			'latest_lead_date' => (string) ($suggestion['latest_lead_date'] ?? ''),
			'reason' => $reason,
		];
	}

	private function sn_restore_sales_manager_warning_rows(): array
	{
		global $wpdb;
		return $wpdb->get_results("SELECT p.user_id, u.display_name, u.user_login,
			(SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_assignments a WHERE a.parent_profile_id=p.id AND a.relationship_type='reports_to' AND a.is_current=1) direct_children_count
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			WHERE pos.slug='sales_manager'
			ORDER BY p.user_id ASC", ARRAY_A) ?: [];
	}

