	public function handle_assign_sales_deputy_position(): void
	{
		if (! current_user_can('manage_options')) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_assign_sales_deputy_position');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		if (! class_exists('SN_HR_Service')) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'target_transition_error'], admin_url('admin.php')));
			exit;
		}
		$user = $this->sn_find_user_by_lookup(sanitize_text_field(wp_unslash($_POST['user_lookup'] ?? '')));
		if (! $user instanceof WP_User) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'target_transition_error'], admin_url('admin.php')));
			exit;
		}
		$mode = sanitize_key(wp_unslash($_POST['transition_mode'] ?? 'dry_run'));
		$dry_run = $mode !== 'apply';
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		if (! $dry_run && $confirm !== 'APPLY') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'target_transition_confirm_missing'], admin_url('admin.php')));
			exit;
		}
		$report = (new SN_HR_Service())->assign_sales_deputy_position((int) $user->ID, $dry_run, get_current_user_id());
		if (! $dry_run && ! empty($report['changed']) && empty($report['errors'])) {
			$this->sn_hr_apply_user_access_for_position((int) $user->ID, 'sales_deputy');
		}
		update_option('sn_hr_target_transition_report', array_merge($report, ['tool' => 'assign_sales_deputy_position']), false);
		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'target_transition_done',
			'target_mode' => $dry_run ? 'dry_run' : 'apply',
			'target_changed' => ! empty($report['changed']) ? 1 : 0,
			'target_eligible' => 1,
			'target_errors' => (int) ($report['errors'] ?? 0),
		], admin_url('admin.php')));
		exit;
	}

	public function handle_manual_hr_position_correction(): void
	{
		if (! current_user_can('manage_options')) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_manual_hr_position_correction');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		if (! class_exists('SN_HR_Service') || ! class_exists('SN_Hierarchy_Service')) {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'manual_hr_correction_error'], admin_url('admin.php')));
			exit;
		}
		$mode = sanitize_key(wp_unslash($_POST['correction_mode'] ?? 'dry_run'));
		$dry_run = $mode !== 'apply';
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		if (! $dry_run && $confirm !== 'APPLY') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'manual_hr_correction_confirm_missing'], admin_url('admin.php')));
			exit;
		}
		$user = $this->sn_find_user_by_lookup(sanitize_text_field(wp_unslash($_POST['user_lookup'] ?? '')));
		$target_position_slug = sanitize_key(wp_unslash($_POST['target_position_slug'] ?? ''));
		$manager_lookup = sanitize_text_field(wp_unslash($_POST['manager_lookup'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$create_missing = ! empty($_POST['create_missing_profile']);
		if (! $user instanceof WP_User || $target_position_slug === '') {
			wp_safe_redirect(add_query_arg(['page' => 'sn-integration', 'sn_msg' => 'manual_hr_correction_error'], admin_url('admin.php')));
			exit;
		}
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$old_manager_user_id = $hierarchy->get_current_parent_user_id((int) $user->ID);
		$new_manager = $manager_lookup !== '' ? $this->sn_find_user_by_lookup($manager_lookup) : null;
		$report = $hr->manual_position_correction((int) $user->ID, $target_position_slug, $create_missing, $dry_run, get_current_user_id(), $reason);
		if (! $dry_run && empty($report['errors']) && (! empty($report['changed_position']) || ! empty($report['created_profile']))) {
			$this->sn_hr_apply_user_access_for_position((int) $user->ID, $target_position_slug);
		}
		$report['tool'] = 'manual_hr_position_correction';
		$report['old_manager_user_id'] = $old_manager_user_id;
		$report['old_manager_label'] = $old_manager_user_id ? $this->sn_user_label($old_manager_user_id) : '';
		$report['new_manager_user_id'] = $new_manager instanceof WP_User ? (int) $new_manager->ID : 0;
		$report['new_manager_label'] = $new_manager instanceof WP_User ? $this->sn_user_label((int) $new_manager->ID) : '';
		$report['would_change_manager'] = $new_manager instanceof WP_User && (int) $new_manager->ID !== $old_manager_user_id;
		$report['changed_manager'] = false;
		$report['manager_errors'] = 0;
		$report['reason'] = $reason;

		if ($manager_lookup !== '' && ! $new_manager instanceof WP_User) {
			$report['manager_errors']++;
			$report['warnings'][] = 'new_manager_not_found';
		} elseif ($new_manager instanceof WP_User && empty($report['errors'])) {
			if ($dry_run) {
				$parent_profile = $hr->get_profile_by_user_id((int) $new_manager->ID);
				if (! $parent_profile) {
					$report['manager_errors']++;
					$report['warnings'][] = 'new_manager_profile_missing';
				}
			} else {
			$child_profile = $hr->get_profile_by_user_id((int) $user->ID);
			$parent_profile = $hr->get_profile_by_user_id((int) $new_manager->ID);
			if (! $child_profile || ! $parent_profile) {
				$report['manager_errors']++;
				$report['warnings'][] = 'manager_or_child_profile_missing';
			} elseif ((int) $new_manager->ID !== $old_manager_user_id) {
				$result = $hierarchy->assign_parent((int) $child_profile->id, (int) $parent_profile->id, get_current_user_id(), 'manual_hr_position_correction', $reason ?: 'manual HR position correction');
				$report['assignment_result'] = $result;
				if (! empty($result['success'])) {
					$report['changed_manager'] = empty($result['skipped']);
				} else {
					$report['manager_errors']++;
					$report['warnings'][] = (string) ($result['message'] ?? 'assignment_failed');
				}
			}
			}
		}
		update_option('sn_hr_manual_position_correction_report', $report, false);
		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'manual_hr_correction_done',
			'manual_mode' => $dry_run ? 'dry_run' : 'apply',
			'manual_changed_position' => ! empty($report['changed_position']) ? 1 : 0,
			'manual_changed_manager' => ! empty($report['changed_manager']) ? 1 : 0,
			'manual_errors' => (int) ($report['errors'] ?? 0) + (int) ($report['manager_errors'] ?? 0),
		], admin_url('admin.php')));
		exit;
	}


	private function sn_hr_lookup_ajax_response(string $message, array $extra = []): void
	{
		if (function_exists('wp_doing_ajax') && wp_doing_ajax()) {
			$success = strpos($message, 'failed') === false && strpos($message, 'error') === false;
			if ($success) {
				wp_send_json_success(array_merge(['message' => $message], $extra));
			}
			wp_send_json_error(array_merge(['message' => $message], $extra));
		}
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => $message]));
		exit;
	}

	public function handle_hr_save_position(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_save_position');
		global $wpdb;
		$id = absint($_POST['position_id'] ?? 0);
		$slug = sanitize_key(wp_unslash($_POST['slug'] ?? ''));
		$label = sanitize_text_field(wp_unslash($_POST['label'] ?? ''));
		$description = sanitize_textarea_field(wp_unslash($_POST['description'] ?? ''));
		$is_active = ! empty($_POST['is_active']) ? 1 : 0;
		$status_action = sanitize_key(wp_unslash($_POST['position_status_action'] ?? 'save'));
		$table = $wpdb->prefix . 'sn_hr_positions';
		if ($id && $status_action === 'delete') {
			$deleted = $this->sn_hr_delete_lookup_row('position', $id);
			$this->sn_hr_lookup_ajax_response($deleted ? 'hr_position_deleted' : 'hr_position_delete_failed', ['type' => 'position', 'id' => $id, 'deleted' => (bool) $deleted]);
		}
		$result = false;
		if ($id) {
			$result = $wpdb->update($table, $this->sn_filter_existing_columns($table, [
				'label' => $label,
				'description' => $description,
				'is_active' => $is_active,
				'updated_at' => current_time('mysql'),
			]), ['id' => $id]);
		} elseif ($slug !== '' && $label !== '') {
			$existing = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE slug=%s", $slug));
			if ($existing) {
				$result = $wpdb->update($table, $this->sn_filter_existing_columns($table, [
					'label' => $label,
					'description' => $description,
					'is_active' => $is_active,
					'updated_at' => current_time('mysql'),
				]), ['id' => $existing]);
				$id = $existing;
			} else {
				$result = $wpdb->insert($table, $this->sn_filter_existing_columns($table, [
					'slug' => $slug,
					'label' => $label,
					'description' => $description,
					'is_active' => $is_active,
					'is_system' => 0,
					'created_at' => current_time('mysql'),
					'updated_at' => current_time('mysql'),
				]));
				$id = $result !== false ? (int) $wpdb->insert_id : 0;
			}
		}
		$row = $id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $id), ARRAY_A) : null;
		$message = ($result !== false && $id > 0) ? 'hr_position_saved' : 'hr_position_update_failed';
		$this->sn_hr_lookup_ajax_response($message, ['type' => 'position', 'id' => $id, 'row' => $row ?: [], 'db_error' => (string) $wpdb->last_error]);
	}

	public function handle_hr_save_level(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز برای تغییر وضعیت سطح'); }
		check_admin_referer('sn_hr_save_level');
		global $wpdb;
		$id = absint($_POST['level_id'] ?? 0);
		$slug = sanitize_key(wp_unslash($_POST['slug'] ?? ''));
		$label = sanitize_text_field(wp_unslash($_POST['label'] ?? ''));
		$description = sanitize_textarea_field(wp_unslash($_POST['description'] ?? ''));
		$status_action = sanitize_key(wp_unslash($_POST['level_status_action'] ?? 'save'));
		$posted_is_active = wp_unslash($_POST['is_active'] ?? '');
		if (is_array($posted_is_active)) { $posted_is_active = end($posted_is_active); }
		if ($status_action === 'activate') {
			$is_active = 1;
		} elseif ($status_action === 'deactivate') {
			$is_active = 0;
		} else {
			$is_active = (string) $posted_is_active === '1' ? 1 : 0;
		}
		$table = $wpdb->prefix . 'sn_hr_levels';
		if ($id && $status_action === 'delete') {
			$deleted = $this->sn_hr_delete_lookup_row('level', $id);
			update_option('sn_hr_last_level_action_report', ['time' => current_time('mysql'), 'actor_user_id' => get_current_user_id(), 'level_id' => $id, 'level_status_action' => 'delete', 'verified' => $deleted, 'message' => $deleted ? 'hr_level_deleted' : 'hr_level_delete_failed'], false);
			$this->sn_hr_lookup_ajax_response($deleted ? 'hr_level_deleted' : 'hr_level_delete_failed', ['type' => 'level', 'id' => $id, 'deleted' => (bool) $deleted]);
		}
		$columns = $this->sn_table_columns($table);
		$active_column = in_array('is_active', $columns, true) ? 'is_active' : (in_array('active', $columns, true) ? 'active' : '');
		if ($active_column === '') {
			$this->sn_hr_lookup_ajax_response('hr_level_update_failed', ['type' => 'level', 'id' => $id, 'db_error' => 'active_column_missing']);
		}
		$result = false;
		if ($id) {
			$data = in_array($status_action, ['activate', 'deactivate'], true)
				? [$active_column => $is_active, 'updated_at' => current_time('mysql')]
				: ['label' => $label, 'description' => $description, $active_column => $is_active, 'updated_at' => current_time('mysql')];
			$result = $wpdb->update($table, $this->sn_filter_existing_columns($table, $data), ['id' => $id]);
		} elseif ($slug !== '' && $label !== '') {
			$existing = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE slug=%s", $slug));
			if ($existing) {
				$result = $wpdb->update($table, $this->sn_filter_existing_columns($table, ['label' => $label, 'description' => $description, $active_column => $is_active, 'updated_at' => current_time('mysql')]), ['id' => $existing]);
				$id = $existing;
			} else {
				$result = $wpdb->insert($table, $this->sn_filter_existing_columns($table, ['slug' => $slug, 'label' => $label, 'description' => $description, $active_column => $is_active, 'is_system' => 0, 'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')]));
				$id = $result !== false ? (int) $wpdb->insert_id : 0;
			}
		}
		$row = $id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $id), ARRAY_A) : null;
		$saved = $result !== false && $id > 0;
		if ($saved && $status_action === 'activate') { $message = 'hr_level_activated'; }
		elseif ($saved && $status_action === 'deactivate') { $message = 'hr_level_deactivated'; }
		elseif ($saved) { $message = 'hr_level_saved'; }
		else { $message = 'hr_level_update_failed'; }
		update_option('sn_hr_last_level_action_report', ['time' => current_time('mysql'), 'actor_user_id' => get_current_user_id(), 'level_id' => $id, 'level_status_action' => $status_action, 'verified' => $saved, 'message' => $message, 'db_error' => (string) $wpdb->last_error], false);
		$this->sn_hr_lookup_ajax_response($message, ['type' => 'level', 'id' => $id, 'row' => $row ?: [], 'db_error' => (string) $wpdb->last_error]);
	}

	public function sn_hr_purge_builtin_lookup_rows_once(): void
	{
		if ($this->sn_defer_heavy_admin_runtime()) { return; }
		$version = '2026-10-08-hr-invoice-review-v1';
		if (get_option('sn_hr_builtin_lookup_version', '') === $version) { return; }
		$this->sn_hr_ensure_builtin_lookup_rows();
		$report = get_option('sn_hr_builtin_lookup_repair_report', []);
		if (empty($report['errors'])) { update_option('sn_hr_builtin_lookup_version', $version, false); }
	}

