	private function sn_hr_ensure_builtin_lookup_rows(): void
	{
		global $wpdb;
		$positions = $wpdb->prefix . 'sn_hr_positions';
		$levels = $wpdb->prefix . 'sn_hr_levels';
		$report = ['time' => current_time('mysql'), 'positions_upserted' => 0, 'levels_upserted' => 0, 'system_positions_removed' => 0, 'system_levels_removed' => 0, 'errors' => []];
		if ($this->sn_table_exists_quiet($positions)) {
			foreach ($this->sn_hr_builtin_positions() as $slug => $row) {
				$existing = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$positions} WHERE slug=%s", $slug));
				if ($existing) {
					// Preserve administrator edits on updates: label, sort order, active state and panel key are not overwritten.
					continue;
				}
				$data = $this->sn_filter_existing_columns($positions, ['slug' => $slug, 'label' => $row['label'], 'panel_key' => $row['panel_key'], 'sort_order' => $row['sort_order'], 'is_active' => 1, 'is_system' => 1, 'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')]);
				$wpdb->insert($positions, $data);
				if ($wpdb->last_error) { $report['errors'][] = $wpdb->last_error; } else { $report['positions_upserted']++; }
			}
		}
		if ($this->sn_table_exists_quiet($levels)) {
			foreach ($this->sn_hr_builtin_levels() as $slug => $row) {
				$existing = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$levels} WHERE slug=%s", $slug));
				if ($existing) {
					// Preserve administrator edits on updates: label, sort order and active state are not overwritten.
					continue;
				}
				$data = $this->sn_filter_existing_columns($levels, ['slug' => $slug, 'label' => $row['label'], 'sort_order' => $row['sort_order'], 'is_active' => 1, 'is_system' => 1, 'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql')]);
				$wpdb->insert($levels, $data);
				if ($wpdb->last_error) { $report['errors'][] = $wpdb->last_error; } else { $report['levels_upserted']++; }
			}
		}
		update_option('sn_hr_builtin_lookup_repair_report', $report, false);
	}

	private function sn_hr_delete_lookup_row(string $type, int $id): bool
	{
		if ($id < 1) { return false; }
		global $wpdb;
		$is_position = $type === 'position';
		$table = $wpdb->prefix . ($is_position ? 'sn_hr_positions' : 'sn_hr_levels');
		if (! $this->sn_table_exists_quiet($table)) { return false; }
		$row_exists = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE id=%d", $id));
		if (! $row_exists) { return false; }
		$profiles = $wpdb->prefix . 'sn_hr_profiles';
		if ($this->sn_table_exists_quiet($profiles)) {
			$column = $is_position ? 'position_id' : 'level_id';
			if ($this->sn_table_has_column($profiles, $column)) {
				$wpdb->update($profiles, [$column => null, 'updated_at' => current_time('mysql')], [$column => $id]);
			}
		}
		$map = $wpdb->prefix . 'sn_hr_position_role_mappings';
		if ($this->sn_table_exists_quiet($map)) {
			if ($is_position && $this->sn_table_has_column($map, 'position_id')) {
				$wpdb->delete($map, ['position_id' => $id]);
			} elseif (! $is_position && $this->sn_table_has_column($map, 'default_level_id')) {
				$wpdb->update($map, ['default_level_id' => null, 'updated_at' => current_time('mysql')], ['default_level_id' => $id]);
			}
		}
		$result = $wpdb->delete($table, ['id' => $id]);
		return $result !== false && ! $wpdb->last_error;
	}

	private function sn_hr_profile_metadata_update($profile, array $metadata): array
	{
		$data = [];
		foreach (['employee_code','employment_status','employment_type','salary_currency','national_id','work_phone','emergency_phone','notes'] as $field) {
			if (isset($metadata[$field]) && $metadata[$field] !== '') {
				$data[$field] = $metadata[$field];
			}
		}
		foreach (['hire_date','termination_date'] as $field) {
			if (! empty($metadata[$field]) && preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) $metadata[$field])) {
				$data[$field] = $metadata[$field];
			}
		}
		if ($metadata['base_salary'] !== null) {
			$data['base_salary'] = (int) $metadata['base_salary'];
			if (empty($data['salary_currency'])) {
				$data['salary_currency'] = 'IRT';
			}
		}
		foreach (['department_id','unit_id','team_id'] as $field) {
			if (isset($metadata[$field]) && (int) $metadata[$field] >= 0) {
				$data[$field] = (int) $metadata[$field] ?: null;
			}
		}
		return $data;
	}

	public function handle_hr_save_structure(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_save_structure');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		global $wpdb;
		$type = sanitize_key(wp_unslash($_POST['structure_type'] ?? ''));
		$table = $this->sn_hr_structure_table($type);
		if ($table === '') {
			wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => 'hr_structure_error']));
			exit;
		}
		$id = absint($_POST['structure_id'] ?? 0);
		$old = $id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $id), ARRAY_A) : null;
		$data = [
			'label' => sanitize_text_field(wp_unslash($_POST['label'] ?? '')),
			'description' => sanitize_textarea_field(wp_unslash($_POST['description'] ?? '')),
			'is_active' => ! empty($_POST['is_active']) ? 1 : 0,
			'sort_order' => intval($_POST['sort_order'] ?? 0),
			'updated_at' => current_time('mysql'),
		];
		if ($type === 'units') { $data['department_id'] = absint($_POST['department_id'] ?? 0) ?: null; }
		if ($type === 'teams') { $data['unit_id'] = absint($_POST['unit_id'] ?? 0) ?: null; }
		if ($id) {
			$wpdb->update($table, $this->sn_filter_existing_columns($table, $data), ['id' => $id]);
			$this->sn_hr_panel_log_profile(0, 0, 'hr_structure_updated', $old, array_merge(['type' => $type, 'id' => $id], $data), []);
		} else {
			$slug = sanitize_key(wp_unslash($_POST['slug'] ?? ''));
			if ($slug !== '' && $data['label'] !== '') {
				$data['slug'] = $slug;
				$data['created_at'] = current_time('mysql');
				$wpdb->insert($table, $this->sn_filter_existing_columns($table, $data));
				$this->sn_hr_panel_log_profile(0, 0, 'hr_structure_created', null, array_merge(['type' => $type, 'id' => (int) $wpdb->insert_id], $data), []);
			}
		}
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => 'hr_structure_saved']));
		exit;
	}

	private function sn_read_tabular_upload(array $file, array $allowed_mimes = []): array
	{
		$name = sanitize_file_name((string) ($file['name'] ?? ''));
		$tmp = (string) ($file['tmp_name'] ?? '');
		$ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
		$out = [
			'headers' => [],
			'rows' => [],
			'errors' => [],
			'file_name' => $name,
			'ext' => $ext,
			'debug' => [
				'original_filename' => $name,
				'mime_type' => sanitize_text_field((string) ($file['type'] ?? '')),
				'extension' => $ext,
				'tmp_name_exists' => $tmp !== '' && file_exists($tmp),
				'file_size' => isset($file['size']) ? (int) $file['size'] : 0,
			],
		];
		$upload_error = isset($file['error']) ? (int) $file['error'] : UPLOAD_ERR_OK;
		if ($upload_error !== UPLOAD_ERR_OK) {
			$out['errors'][] = 'upload_error_' . $upload_error;
			return $out;
		}
		if ($tmp === '' || ! is_uploaded_file($tmp)) {
			$out['errors'][] = 'upload_missing';
			return $out;
		}
		if ((int) ($file['size'] ?? 0) > 5 * 1024 * 1024) {
			$out['errors'][] = 'file_too_large_max_5mb';
			return $out;
		}
		if ($ext === 'xls') {
			$out['errors'][] = 'xls_not_supported_save_as_csv_or_xlsx';
			return $out;
		}
		if (! in_array($ext, ['csv', 'xlsx'], true)) {
			$out['errors'][] = 'invalid_file_type';
			return $out;
		}
		if ($allowed_mimes && ! array_key_exists($ext, $allowed_mimes)) {
			$out['errors'][] = 'file_type_not_allowed';
			return $out;
		}
		if ($ext === 'csv') {
			if (! is_readable($tmp)) {
				$out['errors'][] = 'cannot_read_file';
				return $out;
			}
			$content = file_get_contents($tmp);
			if (! is_string($content) || $content === '') {
				$out['errors'][] = 'file_empty';
				return $out;
			}
			$parsed = $this->sn_parse_csv_content($content);
			$out['headers'] = $parsed['headers'];
			$out['rows'] = $parsed['rows'];
			$out['errors'] = array_merge($out['errors'], $parsed['errors']);
			$out['debug'] = array_merge($out['debug'], $parsed['debug']);
			return $out;
		}
		if (! class_exists('ZipArchive')) {
			$out['errors'][] = 'خواندن XLSX روی این سرور فعال نیست. فایل را CSV UTF-8 ذخیره و بارگذاری کنید.';
			return $out;
		}
		$zip = new ZipArchive();
		if ($zip->open($tmp) !== true) {
			$out['errors'][] = 'xlsx_open_failed';
			return $out;
		}
		$shared_stat = $zip->statName('xl/sharedStrings.xml');
		if (is_array($shared_stat) && (int) ($shared_stat['size'] ?? 0) > 20 * 1024 * 1024) {
			$zip->close();
			$out['errors'][] = 'xlsx_shared_strings_too_large';
			return $out;
		}
		$sheet_stat = $zip->statName('xl/worksheets/sheet1.xml');
		if (is_array($sheet_stat) && (int) ($sheet_stat['size'] ?? 0) > 30 * 1024 * 1024) {
			$zip->close();
			$out['errors'][] = 'xlsx_sheet_too_large';
			return $out;
		}
		$shared = [];
		$shared_xml = $zip->getFromName('xl/sharedStrings.xml');
		if (is_string($shared_xml) && strlen($shared_xml) > 20 * 1024 * 1024) {
			$zip->close();
			$out['errors'][] = 'xlsx_shared_strings_too_large';
			return $out;
		}
		if (is_string($shared_xml) && $shared_xml !== '') {
			if (preg_match_all('/<(?:[A-Za-z0-9_]+:)?si\b[^>]*>(.*?)<\/(?:[A-Za-z0-9_]+:)?si>/s', $shared_xml, $items)) {
				foreach ($items[1] as $si) {
					preg_match_all('/<(?:[A-Za-z0-9_]+:)?t\b[^>]*>(.*?)<\/(?:[A-Za-z0-9_]+:)?t>/s', $si, $texts);
					$shared[] = html_entity_decode(strip_tags(implode('', $texts[1] ?? [])), ENT_QUOTES | ENT_XML1, 'UTF-8');
				}
			}
		}
		$sheet_xml = $zip->getFromName('xl/worksheets/sheet1.xml');
		$zip->close();
		if (! is_string($sheet_xml) || $sheet_xml === '') {
			$out['errors'][] = 'xlsx_first_sheet_missing';
			return $out;
		}
		if (strlen($sheet_xml) > 30 * 1024 * 1024) {
			$out['errors'][] = 'xlsx_sheet_too_large';
			return $out;
		}
		$matrix = [];
		if (preg_match_all('/<(?:[A-Za-z0-9_]+:)?row\b[^>]*>(.*?)<\/(?:[A-Za-z0-9_]+:)?row>/s', $sheet_xml, $rows)) {
			foreach ($rows[1] as $row_xml) {
				$row = [];
				if (preg_match_all('/<(?:[A-Za-z0-9_]+:)?c\b([^>]*)>(.*?)<\/(?:[A-Za-z0-9_]+:)?c>/s', $row_xml, $cells, PREG_SET_ORDER)) {
					foreach ($cells as $cell) {
						$attrs = (string) $cell[1];
						$body = (string) $cell[2];
						$ref = preg_match('/\br="([A-Z]+)\d+"/', $attrs, $m) ? $m[1] : '';
						$idx = $ref !== '' ? $this->sn_excel_column_index($ref) : count($row);
						if ($idx > 511) {
							$out['errors'][] = 'xlsx_column_limit_exceeded_max_512';
							return $out;
						}
						$type = preg_match('/\bt="([^"]+)"/', $attrs, $m) ? $m[1] : '';
						$value = '';
						if (preg_match('/<(?:[A-Za-z0-9_]+:)?v>(.*?)<\/(?:[A-Za-z0-9_]+:)?v>/s', $body, $m)) {
							$value = html_entity_decode($m[1], ENT_QUOTES | ENT_XML1, 'UTF-8');
							if ($type === 's') { $value = $shared[(int) $value] ?? ''; }
						} elseif (preg_match('/<(?:[A-Za-z0-9_]+:)?t\b[^>]*>(.*?)<\/(?:[A-Za-z0-9_]+:)?t>/s', $body, $m)) {
							$value = html_entity_decode($m[1], ENT_QUOTES | ENT_XML1, 'UTF-8');
						}
						$row[$idx] = trim((string) $value);
					}
				}
				if ($row) {
					ksort($row);
					$max_index = max(array_keys($row));
					$dense_row = [];
					for ($i = 0; $i <= $max_index; $i++) {
						$dense_row[] = isset($row[$i]) ? (string) $row[$i] : '';
					}
					$matrix[] = $dense_row;
				}
			}
		}
		if (! $matrix) { $out['errors'][] = 'xlsx_no_rows'; return $out; }
		$header_row = array_shift($matrix);
		$out['headers'] = array_map([$this, 'sn_clean_tabular_header'], $header_row);
		$out['debug']['header_raw_row'] = implode("	", array_map(static fn($h) => (string) $h, $header_row));
		$out['debug']['header_parsed_cells'] = $out['headers'];
		$out['debug']['normalized_header_cells'] = array_map([$this, 'sn_norm_header_key'], $out['headers']);
		if (! $this->sn_tabular_has_non_empty_cells($out['headers'])) {
			$out['errors'][] = 'header_blank';
			return $out;
		}
		if (count($matrix) > 10000) {
			$out['errors'][] = 'row_limit_exceeded_max_10000';
			return $out;
		}
		foreach ($matrix as $row) {
			if (! $this->sn_tabular_has_non_empty_cells($row)) { continue; }
			$out['rows'][] = $this->sn_row_to_assoc($out['headers'], $row);
		}
		return $out;
	}

	private function sn_parse_csv_content(string $content): array
	{
		$debug = $this->sn_csv_parser_debug($content);
		$out = ['headers' => [], 'rows' => [], 'errors' => [], 'debug' => $debug];
		$preview_lines = preg_split('/\r\n|\n|\r/', substr($content, 0, 65536));
		if (! is_array($preview_lines)) {
			$out['errors'][] = 'csv_preview_failed';
			return $out;
		}
		$header_line = '';
		foreach ($preview_lines as $line) {
			$clean = $this->sn_clean_tabular_cell((string) $line);
			if ($clean !== '') {
				$header_line = (string) $line;
				break;
			}
		}
		if ($header_line === '') {
			$out['errors'][] = 'header_missing';
			return $out;
		}
		$delimiter = $this->sn_detect_csv_delimiter($header_line);
		$stream = fopen('php://temp', 'w+b');
		if ($stream === false) {
			$out['errors'][] = 'csv_stream_failed';
			return $out;
		}
		fwrite($stream, $content);
		rewind($stream);
		$headers = [];
		while (($candidate = fgetcsv($stream, 0, $delimiter, '"', '\\')) !== false) {
			$candidate = array_map([$this, 'sn_clean_tabular_header'], (array) $candidate);
			if ($this->sn_tabular_has_non_empty_cells($candidate)) {
				$headers = $candidate;
				break;
			}
		}
		$out['debug']['delimiter_selected'] = $delimiter === "	" ? 'tab' : $delimiter;
		$out['debug']['header_raw_row'] = $this->sn_mask_debug_line($header_line);
		$out['debug']['header_parsed_cells'] = $headers;
		$out['debug']['normalized_header_cells'] = array_map([$this, 'sn_norm_header_key'], $headers);
		if (! $this->sn_tabular_has_non_empty_cells($headers)) {
			$out['errors'][] = 'header_blank';
			fclose($stream);
			return $out;
		}
		$out['headers'] = $headers;
		while (($row = fgetcsv($stream, 0, $delimiter, '"', '\\')) !== false) {
			$row = array_map([$this, 'sn_clean_tabular_cell'], (array) $row);
			if (! $this->sn_tabular_has_non_empty_cells($row)) {
				continue;
			}
			$out['rows'][] = $this->sn_row_to_assoc($headers, $row);
			if (count($out['rows']) > 10000) {
				$out['errors'][] = 'row_limit_exceeded_max_10000';
				$out['rows'] = [];
				break;
			}
		}
		fclose($stream);
		return $out;
	}

	private function sn_csv_parser_debug(string $content): array
	{
		$preview = substr($content, 0, 200);
		$lines = preg_split('/\r\n|\n|\r/', substr($content, 0, 2048));
		$raw_lines = [];
		if (is_array($lines)) {
			foreach (array_slice($lines, 0, 5) as $line) {
				$raw_lines[] = $this->sn_mask_debug_line((string) $line);
			}
		}
		return [
			'first_200_raw_bytes_hex' => bin2hex($preview),
			'first_5_raw_lines' => $raw_lines,
			'delimiter_selected' => '',
			'header_raw_row' => '',
			'header_parsed_cells' => [],
			'normalized_header_cells' => [],
		];
	}

	private function sn_detect_csv_delimiter(string $line): string
	{
		$candidates = [',', ';', "	", '|'];
		$best = ',';
		$best_score = 0;
		foreach ($candidates as $delimiter) {
			$cells = str_getcsv($line, $delimiter, '"', '\\');
			$non_empty = 0;
			foreach ((array) $cells as $cell) {
				if ($this->sn_clean_tabular_cell((string) $cell) !== '') {
					$non_empty++;
				}
			}
			$score = max(count((array) $cells), $non_empty);
			if ($score > $best_score) {
				$best_score = $score;
				$best = $delimiter;
			}
		}
		return $best;
	}

	private function sn_parse_csv_line(string $line, string $delimiter, bool $is_header = false): array
	{
		$cells = str_getcsv($line, $delimiter, '"', '\\');
		$out = [];
		foreach ((array) $cells as $cell) {
			$out[] = $is_header ? $this->sn_clean_tabular_header((string) $cell) : $this->sn_clean_tabular_cell((string) $cell);
		}
		return $out;
	}

	private function sn_tabular_has_non_empty_cells(array $cells): bool
	{
		foreach ($cells as $cell) {
			if ($this->sn_clean_tabular_cell((string) $cell) !== '') {
				return true;
			}
		}
		return false;
	}

	private function sn_clean_tabular_header($value): string
	{
		$value = $this->sn_clean_tabular_cell((string) $value);
		$value = preg_replace('/\s+/u', ' ', $value);
		return trim((string) $value);
	}

	private function sn_clean_tabular_cell($value): string
	{
		$value = is_scalar($value) ? (string) $value : '';
		$value = str_replace(["\xEF\xBB\xBF", "\xC2\xA0", '﻿', '‌', '‍', 'ي', 'ك'], ['', ' ', '', '', '', 'ی', 'ک'], $value);
		$value = preg_replace('/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}]/u', '', $value);
		return trim((string) $value);
	}

	private function sn_mask_debug_line(string $line): string
	{
		$line = $this->sn_clean_tabular_cell($line);
		$english = SN_Helpers::to_english_nums($line);
		return preg_replace_callback('/(?:\+?98|0098|0)?9\d{9}/', function ($m) {
			return $this->sn_mask_phone((string) $m[0]);
		}, $english) ?: $english;
	}

	private function sn_excel_column_index(string $letters): int
	{
		$letters = strtoupper($letters);
		$num = 0;
		for ($i = 0, $len = strlen($letters); $i < $len; $i++) {
			$num = $num * 26 + (ord($letters[$i]) - 64);
		}
		return max(0, $num - 1);
	}

	private function sn_row_to_assoc(array $headers, array $row): array
	{
		$out = [];
		foreach ($headers as $i => $header) {
			$key = $this->sn_clean_tabular_header((string) $header);
			if ($key === '') { $key = 'col_' . $i; }
			$out[$key] = sanitize_text_field((string) ($row[$i] ?? ''));
		}
		return $out;
	}

