	private function sn_normalize_row_keys(array $row): array
	{
		$out = [];
		foreach ($row as $key => $value) {
			$out[$this->sn_norm_header_key((string) $key)] = is_scalar($value) ? trim((string) $value) : '';
		}
		return $out;
	}

	private function sn_mis_detect_phone_columns(array $headers, array $row = []): array
	{
		$primary_aliases = ['phone', 'mobile'];
		$secondary_aliases = ['phone_2'];
		$detected = [
			'headers' => [],
			'primary' => '',
			'primary_label' => '',
			'secondary' => '',
			'secondary_label' => '',
		];
		foreach ($headers as $header) {
			$label = trim((string) $header);
			if ($label === '') { continue; }
			$key = $this->sn_norm_header_key($label);
			$detected['headers'][] = sanitize_text_field($label);
			if ($detected['primary'] === '' && in_array($key, $primary_aliases, true)) {
				$detected['primary'] = $key;
				$detected['primary_label'] = sanitize_text_field($label);
			}
			if ($detected['secondary'] === '' && in_array($key, $secondary_aliases, true)) {
				$detected['secondary'] = $key;
				$detected['secondary_label'] = sanitize_text_field($label);
			}
		}
		foreach ($primary_aliases as $key) {
			if ($detected['primary'] === '' && array_key_exists($key, $row)) {
				$detected['primary'] = $key;
				$detected['primary_label'] = $key;
			}
		}
		if ($detected['secondary'] === '' && array_key_exists('phone_2', $row)) {
			$detected['secondary'] = 'phone_2';
			$detected['secondary_label'] = 'phone_2';
		}
		return $detected;
	}

	private function sn_mis_pick_phone(array $row, array $detected): array
	{
		$candidates = [];
		if (! empty($detected['primary'])) {
			$candidates[] = ['key' => (string) $detected['primary'], 'label' => (string) ($detected['primary_label'] ?: $detected['primary'])];
		}
		if (! empty($detected['secondary'])) {
			$candidates[] = ['key' => (string) $detected['secondary'], 'label' => (string) ($detected['secondary_label'] ?: $detected['secondary'])];
		}
		if (! $candidates) {
			return [
				'raw' => '',
				'normalized' => '',
				'reason' => 'no_phone_column',
				'source_column' => '',
			];
		}
		$first = null;
		foreach ($candidates as $candidate) {
			$raw = sanitize_text_field((string) ($row[$candidate['key']] ?? ''));
			$normalized = $this->sn_normalize_iran_mobile($raw);
			$current = [
				'raw' => $raw,
				'normalized' => $normalized['normalized'],
				'reason' => $normalized['reason'],
				'source_column' => sanitize_text_field((string) $candidate['label']),
			];
			if ($first === null) { $first = $current; }
			if ($current['reason'] === '') { return $current; }
		}
		return $first ?: [
			'raw' => '',
			'normalized' => '',
			'reason' => 'empty_phone',
			'source_column' => '',
		];
	}

	private function sn_normalize_iran_mobile($value): array
	{
		$raw = is_scalar($value) ? trim((string) $value) : '';
		if ($raw === '') {
			return ['normalized' => '', 'reason' => 'empty_phone'];
		}
		$phone = SN_Helpers::to_english_nums($raw);
		$phone = trim(str_replace(["\xEF\xBB\xBF", "\xC2\xA0"], ['', ' '], $phone));
		if (preg_match('/^[+-]?\d+(?:\.\d+)?[eE][+-]?\d+$/', $phone)) {
			$phone = sprintf('%.0f', (float) $phone);
		}
		$compact = preg_replace('/[\s\-\_\(\)\.\/\\\\]+/u', '', $phone);
		$compact = ltrim((string) $compact, '+');
		if ($compact === '') {
			return ['normalized' => '', 'reason' => 'empty_phone'];
		}
		if (preg_match('/[^0-9]/', $compact)) {
			$digits = preg_replace('/\D+/', '', $compact);
			return ['normalized' => (string) $digits, 'reason' => 'non_numeric_after_normalization'];
		}
		$digits = $compact;
		if (strpos($digits, '0098') === 0) {
			$digits = '98' . substr($digits, 4);
		}
		if (strpos($digits, '98') === 0 && strlen($digits) === 12) {
			$digits = '0' . substr($digits, 2);
		} elseif (strlen($digits) === 10 && strpos($digits, '9') === 0) {
			$digits = '0' . $digits;
		}
		if (strlen($digits) < 10) {
			return ['normalized' => $digits, 'reason' => 'too_short'];
		}
		if (strlen($digits) > 11) {
			return ['normalized' => $digits, 'reason' => 'too_long'];
		}
		if (strlen($digits) !== 11 || strpos($digits, '09') !== 0) {
			return ['normalized' => $digits, 'reason' => 'not_mobile_prefix'];
		}
		return ['normalized' => $digits, 'reason' => ''];
	}

	private function sn_normalize_hr_people_row(array $row): array
	{
		$r = $this->sn_normalize_row_keys($row);
		$is_roundtrip_export = (string) ($r['export_schema'] ?? '') === 'sn_hr_users_v1';
		if ($is_roundtrip_export) {
			foreach ($r as $field => $value) {
				if (is_string($value) && preg_match('/^\'\s*[=+\-@]/u', $value)) {
					$r[$field] = substr($value, 1);
				}
			}
		}
		$provided_fields = array_keys($r);
		$first_name = sanitize_text_field((string) ($r['first_name'] ?? ''));
		$last_name = sanitize_text_field((string) ($r['last_name'] ?? ''));
		$full_name = sanitize_text_field((string) ($r['full_name'] ?? ''));
		$r['display_name'] = sanitize_text_field((string) ($r['display_name'] ?? $r['name'] ?? $full_name));
		if ($r['display_name'] === '') {
			$r['display_name'] = trim($first_name . ' ' . $last_name);
		}
		$r['first_name'] = $first_name;
		$r['last_name'] = $last_name;
		$r['mobile'] = sanitize_text_field((string) ($r['mobile'] ?? $r['phone'] ?? ''));
		$r['email'] = sanitize_email((string) ($r['email'] ?? ''));
		$r['user_login'] = sanitize_user((string) ($r['user_login'] ?? ''));
		$r['user_lookup'] = sanitize_text_field((string) ($r['user_lookup'] ?? ($r['user_login'] ?: ($r['email'] ?: $r['mobile']))));
		$r['position_raw'] = sanitize_text_field((string) ($r['position'] ?? ''));
		$r['level_raw'] = sanitize_text_field((string) ($r['level'] ?? ''));
		$r['position'] = $this->sn_slug_from_label($r['position_raw']);
		$r['level'] = $this->sn_slug_from_label($r['level_raw']);

		$manager_mobile_raw = sanitize_text_field((string) ($r['manager_mobile'] ?? ''));
		$manager_lookup_raw = sanitize_text_field((string) ($r['manager_lookup'] ?? ''));
		$manager_name_raw = sanitize_text_field((string) ($r['manager_name'] ?? ''));
		$manager_mobile = '';
		if ($manager_mobile_raw !== '' && class_exists('SN_Helpers')) {
			$normalized_manager_mobile = SN_Helpers::normalize_mobile($manager_mobile_raw);
			if (SN_Helpers::is_valid_mobile($normalized_manager_mobile)) {
				$manager_mobile = $normalized_manager_mobile;
			}
		}
		if ($manager_mobile === '' && $manager_lookup_raw !== '' && class_exists('SN_Helpers')) {
			$normalized_manager_lookup = SN_Helpers::normalize_mobile($manager_lookup_raw);
			if (SN_Helpers::is_valid_mobile($normalized_manager_lookup)) {
				$manager_mobile = $normalized_manager_lookup;
			}
		}
		$r['manager_mobile'] = $manager_mobile ?: $manager_mobile_raw;
		$r['manager_name'] = $manager_name_raw;
		$r['manager_lookup_raw'] = $manager_lookup_raw;
		$r['manager_lookup'] = $manager_mobile ?: ($manager_lookup_raw ?: $manager_name_raw);

		$r['employment_status'] = $this->sn_slug_from_label((string) ($r['employment_status'] ?? 'active'));
		$r['employment_type'] = $this->sn_slug_from_label((string) ($r['employment_type'] ?? ''));
		$r['is_active'] = isset($r['is_active']) && $r['is_active'] !== '' ? ($this->sn_truthy_persian((string) $r['is_active']) ? 1 : 0) : 1;
		foreach (['hire_date', 'termination_date', 'effective_from'] as $date_key) {
			if (isset($r[$date_key]) && trim((string) $r[$date_key]) !== '') {
				$raw_date = sanitize_text_field((string) $r[$date_key]);
				$normalized_date = class_exists('SN_Helpers') ? SN_Helpers::jalali_to_gregorian_date($raw_date) : $raw_date;
				$r[$date_key] = $normalized_date !== '' ? $normalized_date : $raw_date;
			}
		}
		$r['salary_currency'] = in_array(strtoupper((string) ($r['salary_currency'] ?? 'IRT')), ['IRT', 'IRR'], true) ? strtoupper((string) ($r['salary_currency'] ?? 'IRT')) : 'IRT';
		$r['commission_override_mode'] = sanitize_key((string) ($r['commission_override_mode'] ?? ''));
		$r['_provided_fields'] = $provided_fields;
		return $r;
	}

	private function sn_hr_import_has_explicit_compensation(array $data, array $provided_fields): bool
	{
		$provided_fields = array_map('sanitize_key', $provided_fields);
		foreach (['base_salary', 'commission_enabled', 'commission_rule_id', 'commission_rule_code', 'commission_override_mode', 'effective_from'] as $field) {
			if (in_array($field, $provided_fields, true) && (string) ($data[$field] ?? '') !== '') {
				return true;
			}
		}
		return false;
	}

	private function sn_hr_import_profile_payload(array $data, array $provided_fields, string $employee_code, string $normalized_mobile, $position, $level, array $structure_ids): array
	{
		$provided_fields = array_map('sanitize_key', $provided_fields);
		$was_provided = static fn(string $field): bool => in_array($field, $provided_fields, true);
		$payload = [
			'legacy_source' => 'hr_people_import',
			'updated_at' => current_time('mysql'),
		];
		if (! empty($data['display_name'])) { $payload['hr_display_name'] = sanitize_text_field((string) $data['display_name']); }
		if ($was_provided('employee_code')) { $payload['employee_code'] = $employee_code !== '' ? $employee_code : null; }
		if ($was_provided('employment_status')) { $payload['employment_status'] = sanitize_key((string) ($data['employment_status'] ?: 'active')); }
		if ($was_provided('employment_type')) { $payload['employment_type'] = sanitize_key((string) ($data['employment_type'] ?? '')); }
		if ($was_provided('is_active')) { $payload['is_active'] = (int) ($data['is_active'] ?? 1); }
		if ($was_provided('salary_currency') || $was_provided('base_salary')) { $payload['salary_currency'] = (string) ($data['salary_currency'] ?? 'IRT'); }
		if ($position) { $payload['position_id'] = (int) $position->id; }
		if ($level) { $payload['level_id'] = (int) $level->id; }
		if ($was_provided('work_phone')) {
			$payload['work_phone'] = sanitize_text_field((string) ($data['work_phone'] ?? '')) ?: null;
		} elseif (($was_provided('mobile') || $was_provided('phone')) && $normalized_mobile !== '') {
			$payload['work_phone'] = $normalized_mobile;
		}
		foreach (['national_id', 'emergency_phone'] as $optional_text_field) {
			if ($was_provided($optional_text_field)) { $payload[$optional_text_field] = sanitize_text_field((string) ($data[$optional_text_field] ?? '')) ?: null; }
		}
		foreach (['hire_date', 'termination_date'] as $optional_date_field) {
			if ($was_provided($optional_date_field)) { $payload[$optional_date_field] = (string) ($data[$optional_date_field] ?? '') ?: null; }
		}
		if ($was_provided('notes')) { $payload['notes'] = sanitize_textarea_field((string) ($data['notes'] ?? '')); }
		if ($was_provided('base_salary') && (string) ($data['base_salary'] ?? '') !== '') {
			$payload['base_salary'] = max(0, (int) preg_replace('/\D+/', '', (string) $data['base_salary']));
		}
		foreach ($structure_ids as $structure_column => $structure_id) { $payload[$structure_column] = (int) $structure_id; }
		return $payload;
	}

	private function sn_hr_import_compensation_payload($profile, array $profile_data, array $data, array $provided_fields, string $position_slug, string $level_slug): array
	{
		$provided_fields = array_map('sanitize_key', $provided_fields);
		$was_provided = static fn(string $field): bool => in_array($field, $provided_fields, true);
		$current = $this->sn_hr_compensation_for_profile((int) ($profile->id ?? 0));

		$base_salary = $current->base_salary ?? ($profile_data['base_salary'] ?? ($profile->base_salary ?? null));
		if ($was_provided('base_salary') && (string) ($data['base_salary'] ?? '') !== '') {
			$base_salary = max(0, (int) preg_replace('/\D+/', '', (string) $data['base_salary']));
		}
		$salary_currency = (string) ($current->salary_currency ?? ($profile_data['salary_currency'] ?? ($profile->salary_currency ?? 'IRT')));
		if ($was_provided('salary_currency')) {
			$salary_currency = (string) ($data['salary_currency'] ?? 'IRT');
		}
		if (! in_array($salary_currency, ['IRT', 'IRR'], true)) { $salary_currency = 'IRT'; }

		$commission_enabled = isset($current->commission_enabled) ? (int) $current->commission_enabled : 1;
		if ($was_provided('commission_enabled') && (string) ($data['commission_enabled'] ?? '') !== '') {
			$commission_enabled = $this->sn_truthy_persian((string) $data['commission_enabled']) ? 1 : 0;
		}
		$commission_rule_id = (int) ($current->default_commission_rule_id ?? 0) ?: null;
		if ($was_provided('commission_rule_id') || $was_provided('commission_rule_code')) {
			$commission_rule_id = absint($data['commission_rule_id'] ?? 0) ?: null;
		}
		$override_mode = $this->sn_commission_normalize_override_mode((string) ($current->commission_override_mode ?? 'inherit'));
		if ($was_provided('commission_override_mode') && (string) ($data['commission_override_mode'] ?? '') !== '') {
			$override_mode = $this->sn_commission_normalize_override_mode((string) $data['commission_override_mode']);
		}
		$effective_from = (string) ($current->effective_from ?? '');
		if ($was_provided('effective_from') && (string) ($data['effective_from'] ?? '') !== '') {
			$effective_from = sanitize_text_field((string) $data['effective_from']);
		}
		if ($effective_from === '') { $effective_from = SN_Helpers::tehran_today_gregorian(); }

		$notes = (string) ($current->notes ?? '');
		if ($was_provided('notes')) { $notes = sanitize_textarea_field((string) ($data['notes'] ?? '')); }
		$profile_position_id = (int) ($profile_data['position_id'] ?? ($profile->position_id ?? 0));
		$profile_level_id = (int) ($profile_data['level_id'] ?? ($profile->level_id ?? 0));

		return [
			'base_salary' => $base_salary,
			'salary_currency' => $salary_currency,
			'commission_enabled' => $commission_enabled,
			'commission_rule_id' => $commission_rule_id,
			'commission_override_mode' => $override_mode,
			'effective_from' => $effective_from,
			'effective_to' => null,
			'employment_status' => (string) ($profile_data['employment_status'] ?? ($profile->employment_status ?? 'active')),
			'employment_type' => (string) ($profile_data['employment_type'] ?? ($profile->employment_type ?? '')),
			'position_slug_snapshot' => $position_slug ?: $this->sn_hr_position_slug_by_id($profile_position_id),
			'level_slug_snapshot' => $level_slug ?: $this->sn_hr_level_slug_by_id($profile_level_id),
			'notes' => $notes,
		];
	}


	private function sn_hr_lookup_keys_for_value(string $value): array
	{
		$value = trim(str_replace(['ي', 'ك'], ['ی', 'ک'], $value));
		if ($value === '') { return []; }
		if (class_exists('SN_Helpers')) { $value = SN_Helpers::to_english_nums($value); }
		$value = sanitize_text_field($value);
		$keys = [];
		if (class_exists('SN_Helpers')) {
			$mobile = SN_Helpers::normalize_mobile($value);
			if (SN_Helpers::is_valid_mobile($mobile)) { $keys[] = 'mobile:' . $mobile; }
		} else {
			$digits = preg_replace('/\D+/', '', $value);
			if (is_string($digits) && preg_match('/^09\d{9}$/', $digits)) { $keys[] = 'mobile:' . $digits; }
		}
		if (is_email($value)) { $keys[] = 'email:' . strtolower(sanitize_email($value)); }
		$login = sanitize_user($value, true);
		if ($login !== '' && ! preg_match('/\s/u', $value)) { $keys[] = 'login:' . strtolower($login); }
		$name = $this->sn_hr_canonical_person_key($value);
		if ($name !== '' && ! preg_match('/^\d+$/', $name)) { $keys[] = 'name:' . $name; }
		return array_values(array_unique($keys));
	}

	private function sn_hr_user_lookup_cache_key(string $lookup): string
	{
		$lookup = trim(class_exists('SN_Helpers') ? SN_Helpers::to_english_nums($lookup) : $lookup);
		return function_exists('mb_strtolower') ? mb_strtolower($lookup, 'UTF-8') : strtolower($lookup);
	}

	private function sn_hr_preload_user_lookup_cache(array $prepared_rows): array
	{
		global $wpdb;
		$raw_values = [];
		foreach ($prepared_rows as $item) {
			$data = (array) ($item['data'] ?? []);
			foreach (['user_lookup', 'user_login', 'email', 'mobile', 'manager_lookup'] as $field) {
				$value = sanitize_text_field((string) ($data[$field] ?? ''));
				if ($value !== '') { $raw_values[$this->sn_hr_user_lookup_cache_key($value)] = $value; }
			}
		}
		if (! $raw_values) { return []; }

		$ids = [];
		$emails = [];
		$logins = [];
		$meta_values = [];
		foreach ($raw_values as $value) {
			if (ctype_digit($value)) { $ids[] = (int) $value; }
			if (is_email($value)) { $emails[] = sanitize_email($value); }
			$login = sanitize_user($value);
			if ($login !== '') { $logins[] = $login; }
			if (class_exists('SN_Helpers')) {
				$mobile = SN_Helpers::normalize_mobile($value);
				if (SN_Helpers::is_valid_mobile($mobile)) {
					$logins[] = $mobile;
					$logins[] = 'user_' . $mobile;
					$meta_values[] = $mobile;
					$meta_values[] = $value;
				}
			}
		}
		$ids = array_values(array_unique(array_filter(array_map('absint', $ids))));
		$emails = array_values(array_unique(array_filter($emails)));
		$logins = array_values(array_unique(array_filter($logins)));
		$meta_values = array_values(array_unique(array_filter($meta_values)));
		$user_rows = [];
		foreach (array_chunk($ids, 500) as $chunk) {
			$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
			foreach ((array) $wpdb->get_results($wpdb->prepare("SELECT ID,user_login,user_email FROM {$wpdb->users} WHERE ID IN ({$placeholders})", ...$chunk), ARRAY_A) as $row) { $user_rows[(int) $row['ID']] = $row; }
		}
		foreach ([['user_login', $logins], ['user_email', $emails]] as [$column, $values]) {
			foreach (array_chunk($values, 500) as $chunk) {
				$placeholders = implode(',', array_fill(0, count($chunk), '%s'));
				foreach ((array) $wpdb->get_results($wpdb->prepare("SELECT ID,user_login,user_email FROM {$wpdb->users} WHERE {$column} IN ({$placeholders})", ...$chunk), ARRAY_A) as $row) { $user_rows[(int) $row['ID']] = $row; }
			}
		}
		$meta_rows = [];
		$meta_keys = ['phone', 'mobile', 'user_phone', 'billing_phone', 'sn_phone'];
		foreach (array_chunk($meta_values, 400) as $chunk) {
			$key_placeholders = implode(',', array_fill(0, count($meta_keys), '%s'));
			$value_placeholders = implode(',', array_fill(0, count($chunk), '%s'));
			$args = array_merge($meta_keys, $chunk);
			$rows = $wpdb->get_results($wpdb->prepare(
				"SELECT user_id,meta_value FROM {$wpdb->usermeta} WHERE meta_key IN ({$key_placeholders}) AND meta_value IN ({$value_placeholders}) ORDER BY user_id ASC",
				...$args
			), ARRAY_A) ?: [];
			foreach ($rows as $row) {
				$meta_rows[] = $row;
			}
		}
		$meta_user_ids = array_values(array_unique(array_filter(array_map(static fn($row) => absint($row['user_id'] ?? 0), $meta_rows))));
		$missing_meta_user_ids = array_values(array_diff($meta_user_ids, array_map('intval', array_keys($user_rows))));
		foreach (array_chunk($missing_meta_user_ids, 500) as $chunk) {
			$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
			foreach ((array) $wpdb->get_results($wpdb->prepare("SELECT ID,user_login,user_email FROM {$wpdb->users} WHERE ID IN ({$placeholders})", ...$chunk), ARRAY_A) as $row) { $user_rows[(int) $row['ID']] = $row; }
		}
		$user_ids = array_keys($user_rows);
		if ($user_ids && function_exists('cache_users')) { cache_users($user_ids); }
		$users_by_id = [];
		$users_by_login = [];
		$users_by_email = [];
		foreach ($user_rows as $user_id => $row) {
			$user = get_user_by('id', (int) $user_id);
			if (! $user instanceof WP_User) { continue; }
			$users_by_id[(int) $user_id] = $user;
			$users_by_login[strtolower((string) ($row['user_login'] ?? ''))] = $user;
			$users_by_email[strtolower((string) ($row['user_email'] ?? ''))] = $user;
		}
		$users_by_mobile = [];
		foreach ($meta_rows as $row) {
			$user = $users_by_id[(int) ($row['user_id'] ?? 0)] ?? null;
			if (! $user instanceof WP_User) { continue; }
			$value = (string) ($row['meta_value'] ?? '');
			$users_by_mobile[$this->sn_hr_user_lookup_cache_key($value)] ??= $user;
			if (class_exists('SN_Helpers')) {
				$mobile = SN_Helpers::normalize_mobile($value);
				if (SN_Helpers::is_valid_mobile($mobile)) { $users_by_mobile[$this->sn_hr_user_lookup_cache_key($mobile)] ??= $user; }
			}
		}

		$cache = [];
		foreach ($raw_values as $cache_key => $value) {
			$user = ctype_digit($value) ? ($users_by_id[(int) $value] ?? null) : null;
			if (! $user && is_email($value)) { $user = $users_by_email[strtolower(sanitize_email($value))] ?? null; }
			if (! $user) { $user = $users_by_login[strtolower(sanitize_user($value))] ?? null; }
			if (! $user && class_exists('SN_Helpers')) {
				$mobile = SN_Helpers::normalize_mobile($value);
				if (SN_Helpers::is_valid_mobile($mobile)) {
					$user = $users_by_login[strtolower($mobile)] ?? ($users_by_login[strtolower('user_' . $mobile)] ?? ($users_by_mobile[$this->sn_hr_user_lookup_cache_key($mobile)] ?? null));
				}
			}
			$cache[$cache_key] = $user instanceof WP_User ? $user : null;
		}
		return $cache;
	}

	private function sn_hr_find_user_by_lookup_cached(string $lookup, array &$cache)
	{
		$key = $this->sn_hr_user_lookup_cache_key($lookup);
		if ($key === '') { return null; }
		if (! array_key_exists($key, $cache)) { $cache[$key] = $this->sn_find_user_by_lookup($lookup); }
		return $cache[$key] instanceof WP_User ? $cache[$key] : null;
	}

	private function sn_hr_person_lookup_keys_for_row(array $data): array
	{
		$keys = [];
		foreach (['mobile', 'user_lookup', 'email', 'user_login'] as $field) {
			$value = sanitize_text_field((string) ($data[$field] ?? ''));
			if ($value !== '') { $keys = array_merge($keys, $this->sn_hr_lookup_keys_for_value($value)); }
		}
		$name = $this->sn_hr_canonical_person_key((string) ($data['display_name'] ?? ''));
		if ($name !== '') { $keys[] = 'name:' . $name; }
		return array_values(array_unique($keys));
	}

	private function sn_hr_canonical_person_key(string $value): string
	{
		$value = trim(str_replace(['ي', 'ك'], ['ی', 'ک'], $value));
		if ($value === '') { return ''; }
		if (class_exists('SN_Helpers')) { $value = SN_Helpers::to_english_nums($value); }
		$value = preg_replace('/[\x{200c}\x{200f}\x{202a}-\x{202e}]+/u', ' ', $value);
		$value = preg_replace('/\s+/u', ' ', (string) $value);
		$value = trim((string) $value);
		return function_exists('mb_strtolower') ? mb_strtolower($value, 'UTF-8') : strtolower($value);
	}

	private function sn_hr_file_lookup_indexes(string $lookup, array $file_lookup_index): array
	{
		$matches = [];
		foreach ($this->sn_hr_lookup_keys_for_value($lookup) as $key) {
			if (! empty($file_lookup_index[$key]) && is_array($file_lookup_index[$key])) {
				$matches = array_merge($matches, array_map('intval', $file_lookup_index[$key]));
			}
		}
		$matches = array_values(array_unique($matches));
		sort($matches);
		return $matches;
	}

	private function sn_slug_from_label(string $value): string
	{
		$value = trim(str_replace(['ي', 'ك'], ['ی', 'ک'], $value));
		$map = [
			'فروشنده' => 'seller',
			'تبدیل کننده' => 'converter',
			'تبدیل‌کننده' => 'converter',
			'سرپرست ارشد' => 'senior_supervisor',
			'سرپرست' => 'supervisor',
			'مدیر فروش' => 'sales_manager',
			'معاون فروش' => 'sales_deputy',
			'مالی' => 'finance',
			'منابع انسانی' => 'hr',
			'MIS' => 'mis',
			'ام آی اس' => 'mis',
			'خدمات پس از فروش' => 'after_sales',
			'مدیر فروش عملیات' => 'operations_sales_manager',
			'سرپرست فروش عملیات' => 'operations_sales_supervisor',
			'کارشناس فروش عملیات' => 'operations_sales_expert',
			'مدیر اجرایی عملیات' => 'operations_executive_manager',
			'کارشناس اجرایی عملیات' => 'operations_execution_expert',
			// Old import labels are accepted as migration aliases only.
			'مدیر پروژه' => 'operations_sales_manager',
			'کارشناس پروژه' => 'operations_sales_expert',
			'فعال' => 'active',
			'غیرفعال' => 'inactive',
			'تمام وقت' => 'full_time',
			'تمام‌وقت' => 'full_time',
			'پاره وقت' => 'part_time',
			'پاره‌وقت' => 'part_time',
			'قراردادی' => 'contractor',
			'کارآموز' => 'intern',
		];
		return $map[$value] ?? sanitize_key($value);
	}

	private function sn_truthy_persian(string $value): bool
	{
		$value = trim(strtolower(str_replace(['ي', 'ك'], ['ی', 'ک'], $value)));
		return in_array($value, ['1', 'yes', 'true', 'on', 'y', 'بله', 'بلی', 'آری', 'فعال', 'دارد'], true);
	}

	private function sn_is_valid_iso_date(string $value): bool
	{
		if (! preg_match('/^(\d{4})-(\d{2})-(\d{2})$/', $value, $matches)) { return false; }
		return checkdate((int) $matches[2], (int) $matches[3], (int) $matches[1]);
	}

	private function sn_find_hr_lookup_row(string $table_suffix, string $slug, string $raw_label)
	{
		global $wpdb;
		$table = $wpdb->prefix . $table_suffix;
		$slug = sanitize_key($slug);
		$raw_label = sanitize_text_field(trim(str_replace(['ي', 'ك'], ['ی', 'ک'], $raw_label)));
		if ($slug === '' && $raw_label === '') {
			return null;
		}
		if ($slug !== '' && $raw_label !== '') {
			return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE slug=%s OR label=%s ORDER BY id ASC LIMIT 1", $slug, $raw_label));
		}
		if ($slug !== '') {
			return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE slug=%s ORDER BY id ASC LIMIT 1", $slug));
		}
		return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE label=%s ORDER BY id ASC LIMIT 1", $raw_label));
	}

	public function handle_hr_csv_dry_run(): void
	{
		$this->handle_hr_people_import();
	}

	public function handle_hr_people_import(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		$posted_nonce = sanitize_text_field(wp_unslash($_POST['_wpnonce'] ?? ''));
		$has_people_import_nonce = $posted_nonce !== '' && (bool) wp_verify_nonce($posted_nonce, 'sn_hr_people_import');
		$nonce_action = $has_people_import_nonce ? 'sn_hr_people_import' : 'sn_hr_csv_dry_run';
		check_admin_referer($nonce_action);
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		if (! in_array($run_mode, ['dry_run', 'apply'], true)) { $run_mode = 'dry_run'; }
		// The legacy nonce was issued for preview-only forms. It must never authorize Apply.
		if (! $has_people_import_nonce) { $run_mode = 'dry_run'; }
		$import_mode = sanitize_key(wp_unslash($_POST['import_mode'] ?? ($_POST['template_type'] ?? 'advanced_people')));
		$simple_mode = $import_mode === 'simple_people';
		$apply = $run_mode === 'apply';
		$allow_create_user = ! empty($_POST['allow_create_wp_user']);
		$send_notification = ! empty($_POST['send_user_notification']);
		$report = [
			'action' => $apply ? 'hr_people_import_apply' : 'hr_people_import_dry_run',
			'mode' => $apply ? 'apply' : 'dry_run',
			'import_mode' => $simple_mode ? 'simple_people' : ($import_mode === 'roundtrip_people' ? 'roundtrip_people' : 'advanced_people'),
			'total_rows' => 0,
			'valid' => 0,
			'invalid' => 0,
			'created_users' => 0,
			'matched_users' => 0,
			'profiles_created' => 0,
			'profiles_updated' => 0,
			'assignments_changed' => 0,
			'assignments_skipped' => 0,
			'compensation_updated' => 0,
			'duplicate_employee_code' => 0,
			'duplicate_person' => 0,
			'identity_conflict' => 0,
			'invalid_mobile' => 0,
			'name_missing' => 0,
			'user_not_found' => 0,
			'position_not_found' => 0,
			'level_not_found' => 0,
			'manager_not_found' => 0,
			'manager_resolved' => 0,
			'manager_in_file' => 0,
			'manager_ambiguous' => 0,
			'would_assign' => 0,
			'preview' => [],
			'errors' => [],
			'warnings' => [],
		];
		if ($apply && strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''))) !== 'APPLY') {
			$report['errors'][] = 'apply_confirmation_missing';
			update_option('sn_hr_csv_dry_run_report', $report, false);
			$redirect = wp_get_referer() ?: home_url('/');
			wp_safe_redirect(add_query_arg('sn_transfer_msg', 'apply_confirmation_missing', $redirect));
			exit;
		}
		if (empty($_FILES['hr_csv']['tmp_name']) || ! is_uploaded_file($_FILES['hr_csv']['tmp_name'])) {
			$report['errors'][] = 'file_missing';
			update_option('sn_hr_csv_dry_run_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		$file = $_FILES['hr_csv']; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized
		$rows = $this->sn_read_tabular_upload($file, ['csv' => 'text/csv', 'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
		if (! empty($rows['errors'])) {
			$report['errors'] = array_merge($report['errors'], (array) $rows['errors']);
			update_option('sn_hr_csv_dry_run_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		if (empty($rows['rows'])) {
			$report['errors'][] = 'file_empty';
			update_option('sn_hr_csv_dry_run_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}

		global $wpdb;
		$this->sn_ensure_hr_profile_schema_runtime();
		$position_cache = [];
		$level_cache = [];
		$structure_cache = ['department' => [], 'unit' => [], 'team' => []];
		$commission_rule_cache = [];
		$hr = class_exists('SN_HR_Service') ? new SN_HR_Service() : null;
		$hierarchy = class_exists('SN_Hierarchy_Service') ? new SN_Hierarchy_Service() : null;
		if (! $hr || (! $simple_mode && ! $hierarchy)) {
			$report['errors'][] = 'hr_import_service_missing';
			update_option('sn_hr_csv_dry_run_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		$seen_codes = [];
		$prepared_rows = [];
		$file_lookup_index = [];
		foreach (array_slice((array) $rows['rows'], 0, 10000) as $row_no => $raw_row) {
			$data = $this->sn_normalize_hr_people_row((array) $raw_row);
			$normalized_mobile = class_exists('SN_Helpers') ? SN_Helpers::normalize_mobile((string) ($data['mobile'] ?? '')) : sanitize_text_field((string) ($data['mobile'] ?? ''));
			$prepared_index = count($prepared_rows);
			$prepared_rows[] = [
				'row' => $row_no + 2,
				'data' => $data,
				'normalized_mobile' => $normalized_mobile,
				'user_id' => 0,
				'profile_id' => 0,
				'valid' => false,
				'manager_lookup' => sanitize_text_field((string) ($data['manager_lookup'] ?? '')),
			];
			foreach ($this->sn_hr_person_lookup_keys_for_row($data) as $key) {
				if (! isset($file_lookup_index[$key])) { $file_lookup_index[$key] = []; }
				$file_lookup_index[$key][] = $prepared_index;
			}
		}

		$user_lookup_cache = $this->sn_hr_preload_user_lookup_cache($prepared_rows);
		$existing_code_owners = [];
		$import_employee_codes = array_values(array_unique(array_filter(array_map(
			static fn($item) => sanitize_text_field((string) (($item['data']['employee_code'] ?? ''))),
			$prepared_rows
		))));
		foreach (array_chunk($import_employee_codes, 500) as $code_chunk) {
			$placeholders = implode(',', array_fill(0, count($code_chunk), '%s'));
			$code_rows = $wpdb->get_results($wpdb->prepare(
				"SELECT employee_code,user_id FROM {$wpdb->prefix}sn_hr_profiles WHERE employee_code IN ({$placeholders})",
				...$code_chunk
			), ARRAY_A) ?: [];
			foreach ($code_rows as $code_row) { $existing_code_owners[(string) $code_row['employee_code']] = (int) $code_row['user_id']; }
		}
		$resolved_user_id_by_key = [];
		$assignment_queue = [];
		$seen_person_keys = [];
		foreach ($prepared_rows as $item_index => $item) {
			$report['total_rows']++;
			$data = (array) $item['data'];
			$employee_code = (string) ($data['employee_code'] ?? '');
			$user_lookup = (string) ($data['user_lookup'] ?? '');
			$matched_identity_users = [];
			foreach (array_values(array_unique(array_filter([
				$user_lookup,
				(string) ($data['user_login'] ?? ''),
				(string) ($data['email'] ?? ''),
				(string) ($data['mobile'] ?? ''),
			]))) as $identity_lookup) {
				$identity_user = $this->sn_hr_find_user_by_lookup_cached((string) $identity_lookup, $user_lookup_cache);
				if ($identity_user instanceof WP_User) { $matched_identity_users[(int) $identity_user->ID] = $identity_user; }
			}
			$identity_conflict = count($matched_identity_users) > 1;
			$user = count($matched_identity_users) === 1 ? reset($matched_identity_users) : null;
			$position_slug = sanitize_key((string) ($data['position'] ?? ''));
			$level_slug = sanitize_key((string) ($data['level'] ?? ''));
			$position_raw = (string) ($data['position_raw'] ?? '');
			$level_raw = (string) ($data['level_raw'] ?? '');
			$manager_lookup = sanitize_text_field((string) ($data['manager_lookup'] ?? ''));
			$manager = (! $simple_mode && $manager_lookup !== '') ? $this->sn_hr_find_user_by_lookup_cached($manager_lookup, $user_lookup_cache) : null;
			$manager_file_matches = (! $simple_mode && $manager_lookup !== '') ? $this->sn_hr_file_lookup_indexes($manager_lookup, $file_lookup_index) : [];
			$manager_in_file = ! $manager instanceof WP_User && count($manager_file_matches) === 1;
			$manager_ambiguous = ! $manager instanceof WP_User && count($manager_file_matches) > 1;
			$manager_status = 'none';
			if ($simple_mode && $manager_lookup !== '') {
				$manager_status = 'simple_ignored';
			} elseif (! $simple_mode && $manager_lookup !== '') {
				if ($manager instanceof WP_User) { $manager_status = 'resolved'; }
				elseif ($manager_in_file) { $manager_status = 'in_file'; }
				elseif ($manager_ambiguous) { $manager_status = 'ambiguous'; }
				else { $manager_status = 'not_found'; }
			}
			$normalized_mobile = (string) ($item['normalized_mobile'] ?? '');
			$reasons = [];
			if ($identity_conflict) { $report['identity_conflict']++; $reasons[] = 'identity_fields_match_different_users'; }
			if ($simple_mode && $data['display_name'] === '') {
				$report['name_missing']++;
				$reasons[] = 'نام وارد نشده است';
			}
			if ($simple_mode && (! class_exists('SN_Helpers') || ! SN_Helpers::is_valid_mobile($normalized_mobile))) {
				$report['invalid_mobile']++;
				$reasons[] = 'موبایل معتبر نیست';
			}
			if ($employee_code !== '' && isset($seen_codes[$employee_code])) { $report['duplicate_employee_code']++; $reasons[] = 'duplicate_employee_code'; }
			if ($employee_code !== '') { $seen_codes[$employee_code] = true; }
			if ($employee_code !== '') {
				$employee_code_user_id = (int) ($existing_code_owners[$employee_code] ?? 0);
				if ($employee_code_user_id > 0 && (! $user instanceof WP_User || $employee_code_user_id !== (int) $user->ID)) {
					$report['duplicate_employee_code']++;
					$reasons[] = 'duplicate_employee_code_existing_profile';
				}
			}
			$identity_keys = array_values(array_filter(
				$this->sn_hr_person_lookup_keys_for_row($data),
				static fn($key) => strpos((string) $key, 'name:') !== 0
			));
			$duplicate_identity = false;
			foreach ($identity_keys as $identity_key) {
				if (isset($seen_person_keys[$identity_key])) { $duplicate_identity = true; }
			}
			if ($duplicate_identity) {
				$report['duplicate_person']++;
				$reasons[] = 'duplicate_person_in_file';
			}
			foreach ($identity_keys as $identity_key) { $seen_person_keys[$identity_key] = true; }
			if ($user instanceof WP_User) {
				$report['matched_users']++;
			}
			$position = null;
			if ($position_slug !== '' || $position_raw !== '') {
				$position_cache_key = $position_slug . '|' . $position_raw;
				if (! isset($position_cache[$position_cache_key])) {
					$position_cache[$position_cache_key] = $this->sn_find_hr_lookup_row('sn_hr_positions', $position_slug, $position_raw);
				}
				$position = $position_cache[$position_cache_key];
				if (! $position) { $report['position_not_found']++; $reasons[] = 'position_not_found'; }
			} elseif ($simple_mode) {
				$report['position_not_found']++;
				$reasons[] = 'سمت شناسایی نشد';
			}
			$level = null;
			if (! $simple_mode && ($level_slug !== '' || $level_raw !== '')) {
				$level_cache_key = $level_slug . '|' . $level_raw;
				if (! isset($level_cache[$level_cache_key])) {
					$level_cache[$level_cache_key] = $this->sn_find_hr_lookup_row('sn_hr_levels', $level_slug, $level_raw);
				}
				$level = $level_cache[$level_cache_key];
				if (! $level) { $report['level_not_found']++; $reasons[] = 'level_not_found'; }
			}
			$structure_ids = [];
			if (! $simple_mode) {
				foreach (['department' => 'sn_hr_departments', 'unit' => 'sn_hr_units', 'team' => 'sn_hr_teams'] as $structure_key => $table_suffix) {
					$structure_raw = sanitize_text_field((string) ($data[$structure_key] ?? ''));
					if ($structure_raw === '') { continue; }
					$structure_slug = sanitize_key($structure_raw);
					$cache_key = $structure_slug . '|' . $structure_raw;
					if (! array_key_exists($cache_key, $structure_cache[$structure_key])) {
						$structure_cache[$structure_key][$cache_key] = $this->sn_find_hr_lookup_row($table_suffix, $structure_slug, $structure_raw);
					}
					$structure_row = $structure_cache[$structure_key][$cache_key];
					if (! $structure_row) {
						$reasons[] = $structure_key . '_not_found';
					} else {
						$structure_ids[$structure_key . '_id'] = (int) $structure_row->id;
					}
				}
				foreach (['hire_date', 'termination_date', 'effective_from'] as $date_key) {
					$date_value = (string) ($data[$date_key] ?? '');
					if ($date_value !== '' && ! $this->sn_is_valid_iso_date($date_value)) { $reasons[] = $date_key . '_invalid'; }
				}
			}
			if (! $simple_mode && $manager_lookup !== '') {
				if ($manager instanceof WP_User) { $report['manager_resolved']++; }
				elseif ($manager_in_file) { $report['manager_in_file']++; }
				elseif ($manager_ambiguous) { $report['manager_ambiguous']++; $reasons[] = 'manager_ambiguous'; }
				else { $report['manager_not_found']++; $reasons[] = 'manager_not_found'; }
				$manager_position_slug = $manager instanceof WP_User ? $this->sn_hr_position_for_user((int) $manager->ID) : '';
				if (count($manager_file_matches) === 1) {
					$manager_file_row = (array) ($prepared_rows[(int) $manager_file_matches[0]]['data'] ?? []);
					$manager_file_position = sanitize_key((string) ($manager_file_row['position'] ?? ''));
					if ($manager_file_position !== '') { $manager_position_slug = $manager_file_position; }
				}
				$child_position_for_manager = $position_slug !== '' ? $position_slug : ($user instanceof WP_User ? $this->sn_hr_position_for_user((int) $user->ID) : '');
				if (($manager instanceof WP_User || $manager_in_file) && ! $this->sn_hr_manager_allowed_for_child($child_position_for_manager, $manager_position_slug)) {
					$reasons[] = 'manager_position_not_allowed';
				}
			}
			if ($user instanceof WP_User && $manager instanceof WP_User && (int) $user->ID === (int) $manager->ID) {
				$reasons[] = 'manager_self_reference';
			}
			if ($manager_in_file && in_array($item_index, $manager_file_matches, true)) {
				$reasons[] = 'manager_self_reference';
			}
			$commission_rule_code = sanitize_key((string) ($data['commission_rule_code'] ?? ''));
			if (! $simple_mode && $commission_rule_code !== '') {
				$rule_code_cache_key = 'code:' . $commission_rule_code;
				if (! array_key_exists($rule_code_cache_key, $commission_rule_cache)) {
					$commission_rule_cache[$rule_code_cache_key] = (int) $wpdb->get_var($wpdb->prepare(
						"SELECT id FROM {$wpdb->prefix}sn_commission_rules WHERE rule_code=%s AND is_active=1 LIMIT 1",
						$commission_rule_code
					));
				}
				if (! $commission_rule_cache[$rule_code_cache_key]) {
					$reasons[] = 'commission_rule_code_not_found';
				} else {
					$data['commission_rule_id'] = (int) $commission_rule_cache[$rule_code_cache_key];
					$commission_rule_cache[(int) $data['commission_rule_id']] = (int) $data['commission_rule_id'];
				}
			}
			$commission_rule_id = absint($data['commission_rule_id'] ?? 0);
			if (! $simple_mode && $commission_rule_id > 0) {
				if (! array_key_exists($commission_rule_id, $commission_rule_cache)) {
					$commission_rule_cache[$commission_rule_id] = (int) $wpdb->get_var($wpdb->prepare(
						"SELECT id FROM {$wpdb->prefix}sn_commission_rules WHERE id=%d AND is_active=1 LIMIT 1",
						$commission_rule_id
					));
				}
				if (! $commission_rule_cache[$commission_rule_id]) { $reasons[] = 'commission_rule_not_found'; }
			}
			$provided_fields = array_map('sanitize_key', (array) ($data['_provided_fields'] ?? []));
			$profile_fields = $simple_mode ? array_values(array_diff($provided_fields, ['base_salary', 'salary_currency'])) : $provided_fields;
			$has_explicit_compensation = ! $simple_mode && $this->sn_hr_import_has_explicit_compensation($data, $provided_fields);
			if ($has_explicit_compensation && (! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_compensation_history') || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_compensation_profiles'))) {
				$reasons[] = 'compensation_tables_missing';
			}
			if (empty($reasons) && $has_explicit_compensation && $user instanceof WP_User) {
				$preview_profile = $hr->get_profile_by_user_id((int) $user->ID);
				if ($preview_profile) {
					$preview_profile_data = $this->sn_hr_import_profile_payload($data, $profile_fields, $employee_code, $normalized_mobile, $position, $level, $structure_ids);
					$preview_compensation = $this->sn_hr_import_compensation_payload($preview_profile, $preview_profile_data, $data, $provided_fields, $position_slug, $level_slug);
					$compensation_preflight = $this->sn_hr_apply_compensation_history_update((int) $preview_profile->id, (int) $user->ID, $preview_compensation, true, 'hr_people_import_preflight');
					foreach ((array) ($compensation_preflight['errors'] ?? []) as $comp_error) {
						$reason = 'compensation_' . sanitize_key((string) $comp_error);
						$reasons[] = $reason;
						$report['warnings'][] = $reason . '_row_' . (int) $item['row'];
					}
				}
			}
			if (! $user instanceof WP_User && ! $allow_create_user) {
				$report['user_not_found']++;
				$reasons[] = 'user_not_found';
			}
			$is_valid = empty($reasons);
			$is_valid ? $report['valid']++ : $report['invalid']++;
			$created_user_this_row = false;
			if ($is_valid && $apply && ! ($user instanceof WP_User) && $allow_create_user) {
				$email_local_parts = explode('@', (string) $data['email']);
				$email_local = (string) ($email_local_parts[0] ?? '');
				$login_base = $data['user_login'] ?: ($normalized_mobile ?: $email_local);
				$login = sanitize_user((string) $login_base);
				if ($login === '') {
					$report['invalid']++;
					$report['valid'] = max(0, (int) $report['valid'] - 1);
					$reasons[] = 'user_login_missing';
					$is_valid = false;
				} else {
					if (username_exists($login)) {
						$base = sanitize_user($normalized_mobile !== '' ? 'user_' . $normalized_mobile : $login . '_import');
						$login = $base;
						$suffix = 1;
						while (username_exists($login)) { $login = $base . '_' . ++$suffix; }
					}
					$email = sanitize_email((string) ($data['email'] ?? ''));
					if ($email === '') {
						$email_base = sanitize_user($login, true) ?: ('sn_import_' . (int) $item['row']);
						$email = $email_base . '@sn.local';
						$email_suffix = 1;
						while (email_exists($email)) { $email = $email_base . '_' . ++$email_suffix . '@sn.local'; }
					}
					if (email_exists($email)) {
						$report['invalid']++;
						$report['valid'] = max(0, (int) $report['valid'] - 1);
						$reasons[] = 'user_email_already_exists';
						$is_valid = false;
					} else {
						$user_id = wp_create_user($login, wp_generate_password(16, true, true), $email);
						if (is_wp_error($user_id)) {
							$report['invalid']++;
							$report['valid'] = max(0, (int) $report['valid'] - 1);
							$reasons[] = 'user_create_failed_' . $user_id->get_error_code();
							$is_valid = false;
						} else {
							$user = get_user_by('id', (int) $user_id);
							if ($user instanceof WP_User) {
								$created_user_this_row = true;
								$report['created_users']++;
							} else {
								$report['invalid']++;
								$report['valid'] = max(0, (int) $report['valid'] - 1);
								$reasons[] = 'created_user_reload_failed';
								$is_valid = false;
							}
						}
					}
				}
			}
			if ($is_valid && $apply && $user instanceof WP_User) {
				$wp_user_update = ['ID' => (int) $user->ID];
				if (! empty($data['display_name'])) { $wp_user_update['display_name'] = sanitize_text_field((string) $data['display_name']); }
				if (! empty($data['first_name'])) { $wp_user_update['first_name'] = sanitize_text_field((string) $data['first_name']); }
				if (! empty($data['last_name'])) { $wp_user_update['last_name'] = sanitize_text_field((string) $data['last_name']); }
				$import_email = sanitize_email((string) ($data['email'] ?? ''));
				$email_owner = $import_email !== '' ? email_exists($import_email) : false;
				if ($import_email !== '' && (! $email_owner || (int) $email_owner === (int) $user->ID)) {
					$wp_user_update['user_email'] = $import_email;
				} elseif ($import_email !== '' && $email_owner) {
					$reasons[] = 'user_email_already_exists';
					$report['valid'] = max(0, (int) $report['valid'] - 1);
					$report['invalid']++;
					$is_valid = false;
				}
				$user_update_result = $is_valid && count($wp_user_update) > 1 ? wp_update_user($wp_user_update) : (int) $user->ID;
				if (is_wp_error($user_update_result)) {
					$reasons[] = 'user_update_failed_' . $user_update_result->get_error_code();
					$report['valid'] = max(0, (int) $report['valid'] - 1);
					$report['invalid']++;
					$is_valid = false;
				}
				if ($is_valid && $normalized_mobile !== '' && class_exists('SN_Helpers') && SN_Helpers::is_valid_mobile($normalized_mobile)) {
					foreach (['mobile', 'phone', 'billing_phone', 'digits_phone', 'digits_phone_no', 'sn_phone'] as $phone_meta_key) {
						update_user_meta((int) $user->ID, $phone_meta_key, $normalized_mobile);
					}
				}
			}
			if ($is_valid && $apply && $user instanceof WP_User && $hr) {
				$old_profile = $hr->get_profile_by_user_id((int) $user->ID);
				$profile = $hr->get_or_create_profile_for_user((int) $user->ID);
				if ($profile) {
					$profile_data = $this->sn_hr_import_profile_payload($data, $profile_fields, $employee_code, $normalized_mobile, $position, $level, $structure_ids);
					$compensation_payload = $has_explicit_compensation ? $this->sn_hr_import_compensation_payload($profile, $profile_data, $data, $provided_fields, $position_slug, $level_slug) : [];
					if ($has_explicit_compensation && ! $old_profile) {
						$compensation_preflight = $this->sn_hr_apply_compensation_history_update((int) $profile->id, (int) $user->ID, $compensation_payload, true, 'hr_people_import_preflight');
						foreach ((array) ($compensation_preflight['errors'] ?? []) as $comp_error) {
							$reason = 'compensation_' . sanitize_key((string) $comp_error);
							$reasons[] = $reason;
							$report['warnings'][] = $reason . '_row_' . (int) $item['row'];
						}
						if (! empty($compensation_preflight['errors'])) {
							$report['valid'] = max(0, (int) $report['valid'] - 1);
							$report['invalid']++;
							$is_valid = false;
						}
					}
					$profile_update = $is_valid ? $wpdb->update($wpdb->prefix . 'sn_hr_profiles', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_hr_profiles', $profile_data), ['id' => (int) $profile->id]) : false;
					if ($profile_update === false) {
						if ($is_valid) {
							$report['warnings'][] = 'profile_update_failed_row_' . (int) $item['row'];
							$report['valid'] = max(0, (int) $report['valid'] - 1);
							$report['invalid']++;
							$reasons[] = 'profile_update_failed';
							$is_valid = false;
						}
					} else {
						$prepared_rows[$item_index]['profile_id'] = (int) $profile->id;
						$old_profile ? $report['profiles_updated']++ : $report['profiles_created']++;
						$this->sn_hr_panel_log_profile((int) $profile->id, (int) $user->ID, 'hr_people_import_profile_saved', null, $profile_data, ['source' => 'crm_people_import']);
					}
					if ($profile_update !== false && $has_explicit_compensation) {
						$comp_result = $this->sn_hr_apply_compensation_history_update((int) $profile->id, (int) $user->ID, $compensation_payload, false, 'hr_people_import');
						if (! empty($comp_result['changed'])) { $report['compensation_updated']++; }
						foreach ((array) ($comp_result['errors'] ?? []) as $comp_error) { $report['warnings'][] = 'compensation_' . sanitize_key((string) $comp_error) . '_row_' . (int) $item['row']; }
						if (! empty($comp_result['errors'])) {
							$report['valid'] = max(0, (int) $report['valid'] - 1);
							$report['invalid']++;
							$reasons[] = 'compensation_update_failed';
							$is_valid = false;
						}
					}
				} else {
					$report['warnings'][] = 'profile_create_failed_row_' . (int) $item['row'];
					$report['valid'] = max(0, (int) $report['valid'] - 1);
					$report['invalid']++;
					$reasons[] = 'profile_create_failed';
					$is_valid = false;
				}
			}
			if ($created_user_this_row && ! $is_valid) {
				$report['warnings'][] = 'partial_user_created_row_' . (int) $item['row'];
			}
			if ($created_user_this_row && $is_valid && $send_notification && $user instanceof WP_User && ! empty($prepared_rows[$item_index]['profile_id'])) {
				wp_new_user_notification((int) $user->ID, null, 'user');
			}
			if ($is_valid && $user instanceof WP_User) {
				$prepared_rows[$item_index]['user_id'] = (int) $user->ID;
				foreach ($this->sn_hr_person_lookup_keys_for_row($data) as $key) {
					if (count((array) ($file_lookup_index[$key] ?? [])) === 1) { $resolved_user_id_by_key[$key] = (int) $user->ID; }
				}
			}
			$would_assign = ! $simple_mode && $is_valid && $manager_lookup !== '' && ($manager instanceof WP_User || $manager_in_file);
			if ($would_assign) { $report['would_assign']++; }
			$prepared_rows[$item_index]['valid'] = $is_valid;
			$prepared_rows[$item_index]['manager_lookup'] = $manager_lookup;
			$prepared_rows[$item_index]['manager_user_id'] = $manager instanceof WP_User ? (int) $manager->ID : 0;
			$prepared_rows[$item_index]['manager_file_matches'] = $manager_file_matches;
			if ($is_valid && ! $simple_mode && $manager_lookup !== '') {
				$assignment_queue[] = [
					'row' => (int) $item['row'],
					'item_index' => $item_index,
					'child_user_id' => $user instanceof WP_User ? (int) $user->ID : 0,
					'manager_lookup' => $manager_lookup,
					'manager_user_id' => $manager instanceof WP_User ? (int) $manager->ID : 0,
				];
			}
			if (count($report['preview']) < 50) {
				$report['preview'][] = [
					'row' => (int) $item['row'],
					'employee_code' => $employee_code,
					'user' => $user instanceof WP_User ? $this->sn_user_label((int) $user->ID) : $user_lookup,
					'position' => $position_slug,
					'manager' => $manager instanceof WP_User ? $this->sn_user_label((int) $manager->ID) : $manager_lookup,
					'manager_lookup' => $manager_lookup,
					'manager_name' => sanitize_text_field((string) ($data['manager_name'] ?? '')),
					'manager_mobile' => sanitize_text_field((string) ($data['manager_mobile'] ?? '')),
					'manager_status' => $manager_status,
					'manager_resolved' => $manager instanceof WP_User ? $this->sn_user_label((int) $manager->ID) : '',
					'manager_in_file' => $manager_in_file,
					'would_assign' => $would_assign,
					'valid' => $is_valid,
					'reasons' => $reasons,
				];
			}
		}

		if ($apply && ! $simple_mode && $hr && $hierarchy && $assignment_queue) {
			foreach ($assignment_queue as $assignment) {
				$child_user_id = (int) ($assignment['child_user_id'] ?? 0);
				if (! $child_user_id && isset($prepared_rows[(int) $assignment['item_index']]['user_id'])) {
					$child_user_id = (int) $prepared_rows[(int) $assignment['item_index']]['user_id'];
				}
				$manager_user_id = (int) ($assignment['manager_user_id'] ?? 0);
				if (! $manager_user_id) {
					$candidate_ids = [];
					foreach ($this->sn_hr_lookup_keys_for_value((string) $assignment['manager_lookup']) as $key) {
						if (! empty($resolved_user_id_by_key[$key])) { $candidate_ids[] = (int) $resolved_user_id_by_key[$key]; }
					}
					$candidate_ids = array_values(array_unique(array_filter($candidate_ids)));
					if (count($candidate_ids) === 1) { $manager_user_id = (int) $candidate_ids[0]; }
				}
				if (! $child_user_id || ! $manager_user_id || $child_user_id === $manager_user_id) {
					$report['assignments_skipped']++;
					$report['warnings'][] = 'assignment_skipped_row_' . (int) ($assignment['row'] ?? 0);
					continue;
				}
				$child_profile = $hr->get_profile_by_user_id($child_user_id);
				$manager_profile = $hr->get_profile_by_user_id($manager_user_id);
				if (! $child_profile || ! $manager_profile) {
					$report['assignments_skipped']++;
					$report['warnings'][] = 'assignment_profile_missing_row_' . (int) ($assignment['row'] ?? 0);
					continue;
				}
				$assigned = $hierarchy->assign_parent((int) $child_profile->id, (int) $manager_profile->id, get_current_user_id(), 'hr_people_import', 'ورود گروهی نیروها');
				if (! empty($assigned['success']) && empty($assigned['skipped'])) {
					$report['assignments_changed']++;
				} else {
					$report['assignments_skipped']++;
					$report['warnings'][] = 'assignment_' . sanitize_key((string) ($assigned['message'] ?? 'skipped')) . '_row_' . (int) ($assignment['row'] ?? 0);
				}
			}
		}

		$report['warning_count'] = count((array) $report['warnings']);
		if ($report['warning_count'] > 500) {
			$report['warnings'] = array_slice((array) $report['warnings'], 0, 500);
			$report['warnings'][] = 'warnings_truncated_after_500';
		}
		$report['updated_at'] = current_time('mysql');
		update_option('sn_hr_csv_dry_run_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	/** Manual creation is insert-only; never reuse or overwrite an existing account. */
	private function sn_hr_manual_mobile_exists(string $mobile): bool
	{
		global $wpdb;
		$variants = $this->sn_login_identifier_variants($mobile);
		// Normalize stored legacy digits/separators as well as the submitted value.
		$expression = static function (string $column): string {
			foreach (['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹','٠','١','٢','٣','٤','٥','٦','٧','٨','٩'] as $i => $digit) {
				$column = "REPLACE({$column}, '{$digit}', '" . ($i % 10) . "')";
			}
			foreach ([' ', '-', '(', ')', '.', '+'] as $separator) {
				$column = "REPLACE({$column}, '{$separator}', '')";
			}
			return $column;
		};
		$variants = array_values(array_unique(array_map(static function ($value) { return str_replace('+', '', $value); }, $variants)));
		$login_variants = array_merge($variants, array_map(static function ($value) { return 'user_' . $value; }, $variants));
		$placeholders = implode(',', array_fill(0, count($variants), '%s'));
		$login_placeholders = implode(',', array_fill(0, count($login_variants), '%s'));
		if ($wpdb->get_var($wpdb->prepare("SELECT ID FROM {$wpdb->users} WHERE " . $expression('user_login') . " IN ($login_placeholders) LIMIT 1", ...$login_variants))) { return true; }
		$keys = ['mobile','phone','user_phone','billing_phone','sn_phone','digits_phone','digits_phone_no','sn_customer_phone'];
		$key_placeholders = implode(',', array_fill(0, count($keys), '%s'));
		if ($wpdb->get_var($wpdb->prepare("SELECT m.user_id FROM {$wpdb->usermeta} m INNER JOIN {$wpdb->users} u ON u.ID=m.user_id WHERE m.meta_key IN ($key_placeholders) AND " . $expression('m.meta_value') . " IN ($placeholders) LIMIT 1", ...array_merge($keys, $variants)))) { return true; }
		$table = $wpdb->prefix . 'sn_hr_profiles';
		// Emergency contacts may legitimately be shared; only work_phone identifies the person.
		return $this->sn_table_exists_quiet($table) && (bool) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE " . $expression('work_phone') . " IN ($placeholders) LIMIT 1", ...$variants));
	}

	public function handle_hr_simple_add_person(): void
	{
		if (! $this->sn_can_manage_hr_panel()) {
			if (wp_doing_ajax()) { wp_send_json(['success' => false, 'message' => 'دسترسی غیرمجاز برای افزودن نیرو']); }
			wp_die('دسترسی غیرمجاز');
		}
		if (! check_admin_referer('sn_hr_simple_add_person', '_wpnonce', false)) {
			if (wp_doing_ajax()) { wp_send_json(['success' => false, 'message' => 'نشست منقضی شده است؛ صفحه منابع انسانی را رفرش کنید.']); }
			wp_die('نشست منقضی شده است');
		}
		global $wpdb;
		$this->sn_ensure_hr_profile_schema_runtime();
		$first_name = sanitize_text_field(wp_unslash($_POST['first_name'] ?? ''));
		$last_name = sanitize_text_field(wp_unslash($_POST['last_name'] ?? ''));
		$display_name = trim($first_name . ' ' . $last_name);
		$mobile = class_exists('SN_Helpers') ? SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($_POST['mobile'] ?? ''))) : sanitize_text_field(wp_unslash($_POST['mobile'] ?? ''));
		if (strpos($mobile, '0098') === 0) { $mobile = '0' . substr($mobile, 4); }
		if (preg_match('/^9[0-9]{9}$/', $mobile)) { $mobile = '0' . $mobile; }
		$position_raw = sanitize_text_field(wp_unslash($_POST['position'] ?? ''));
		$position_slug = $this->sn_slug_from_label($position_raw);
		$notes = sanitize_textarea_field(wp_unslash($_POST['notes'] ?? ''));
		$level_id = absint($_POST['level_id'] ?? 0);
		$manager_user_id = absint($_POST['manager_user_id'] ?? 0);
		$allow_create = ! empty($_POST['allow_create_wp_user']);
		$report = [
			'action' => 'hr_simple_add_person',
			'version' => SN_VERSION,
			'valid' => 0,
			'invalid' => 0,
			'created_users' => 0,
			'matched_users' => 0,
			'profiles_created' => 0,
			'profiles_updated' => 0,
			'errors' => [],
			'warnings' => [],
			'updated_at' => current_time('mysql'),
		];
		if ($display_name === '') { $report['errors'][] = 'نام وارد نشده است'; }
		if (! class_exists('SN_Helpers') || ! SN_Helpers::is_valid_mobile($mobile)) { $report['errors'][] = 'موبایل معتبر نیست'; }
		$position = $this->sn_find_hr_lookup_row('sn_hr_positions', $position_slug, $position_raw);
		if (! $position) { $report['errors'][] = 'سمت شناسایی نشد'; }
		// Validate a supplied manager against the selected HR position. The
		// generic manual-add picker contains all organizational leaders, so the
		// server must enforce the allowed chain (including Operations roles).
		if ($position && $manager_user_id && class_exists('SN_HR_Service')) {
			$manager_profile = (new SN_HR_Service())->get_profile_by_user_id($manager_user_id);
			$manager_position = $manager_profile ? $this->sn_hr_position_slug_by_id((int) $manager_profile->position_id) : '';
			$allowed_parent_positions = $this->sn_hr_allowed_parent_positions((string) $position->slug);
			if (! $manager_profile || ($allowed_parent_positions && ! $this->sn_hr_manager_allowed_for_child((string) $position->slug, $manager_position))) {
				$report['errors'][] = 'نیروی بالادستی با سمت انتخاب‌شده سازگار نیست';
			}
		}
		$level = $level_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_hr_levels WHERE id=%d", $level_id)) : null;
		if ($level_id && ! $level) { $report['errors'][] = 'سطح شناسایی نشد'; }
		$user = null;
		if (SN_Helpers::is_valid_mobile($mobile) && $this->sn_hr_manual_mobile_exists($mobile)) {
			$report['errors'][] = 'این شماره موبایل قبلاً ثبت شده است؛ ثبت کاربر جدید با شماره تکراری امکان‌پذیر نیست.';
		} elseif (! $allow_create) {
			$report['errors'][] = 'کاربر پیدا نشد و گزینه ساخت کاربر جدید فعال نیست';
		}
		if (empty($report['errors']) && ! ($user instanceof WP_User)) {
			// A username collision must fail, never create a suffixed duplicate.
			$login = sanitize_user($mobile);
			$email_base = sanitize_user($login, true) ?: ('sn_user_' . time());
			$email = $email_base . '@sn.local';
			$email_suffix = 1;
			while (email_exists($email)) {
				$email_suffix++;
				$email = $email_base . '_' . $email_suffix . '@sn.local';
			}
			$user_id = wp_create_user($login, wp_generate_password(16, true, true), $email);
			if (is_wp_error($user_id)) {
				$report['errors'][] = 'خطا در ساخت کاربر: ' . $user_id->get_error_code();
				$report['wp_error_message'] = $user_id->get_error_message();
			} else {
				$user = get_user_by('id', (int) $user_id);
				if ($user instanceof WP_User) {
					wp_update_user(['ID' => (int) $user->ID, 'display_name' => $display_name, 'first_name' => $first_name, 'last_name' => $last_name]);
					update_user_meta((int) $user->ID, 'mobile', $mobile);
					update_user_meta((int) $user->ID, 'phone', $mobile);
					update_user_meta((int) $user->ID, 'billing_phone', $mobile);
					update_user_meta((int) $user->ID, 'digits_phone', $mobile);
					update_user_meta((int) $user->ID, 'digits_phone_no', $mobile);
					update_user_meta((int) $user->ID, 'sn_phone', $mobile);
					$report['created_users'] = 1;
				}
			}
		}
		if (empty($report['errors']) && $user instanceof WP_User) {
			$update_user = ['ID' => (int) $user->ID];
			if ($display_name !== '') { $update_user['display_name'] = $display_name; }
			if ($first_name !== '') { $update_user['first_name'] = $first_name; }
			if ($last_name !== '') { $update_user['last_name'] = $last_name; }
			wp_update_user($update_user);
			foreach (['mobile', 'phone', 'billing_phone', 'digits_phone', 'digits_phone_no', 'sn_phone'] as $meta_key) {
				update_user_meta((int) $user->ID, $meta_key, $mobile);
			}
			$user = get_user_by('id', (int) $user->ID);
		}
		if (empty($report['errors']) && $user instanceof WP_User && class_exists('SN_HR_Service')) {
			$hr = new SN_HR_Service();
			$old_profile = $hr->get_profile_by_user_id((int) $user->ID);
			$profile = $hr->get_or_create_profile_for_user((int) $user->ID);
			if ($profile) {
				$data = $this->sn_filter_existing_columns($wpdb->prefix . 'sn_hr_profiles', [
					'hr_display_name' => $display_name,
					'position_id' => (int) $position->id,
					'level_id' => $level_id ?: null,
					'legacy_role' => $this->sn_hr_legacy_role_for_position($position_slug) ?: $position_slug,
					'legacy_source' => 'hr_simple_add',
					'employment_status' => 'active',
					'is_active' => 1,
					'work_phone' => $mobile,
					'notes' => $notes,
					'updated_at' => current_time('mysql'),
				]);
				$updated = $wpdb->update($wpdb->prefix . 'sn_hr_profiles', $data, ['id' => (int) $profile->id]);
				if ($updated === false) {
					$report['errors'][] = 'خطا در ذخیره پروفایل منابع انسانی';
					$report['db_error'] = (string) $wpdb->last_error;
				} else {
					$this->sn_hr_apply_user_access_for_position((int) $user->ID, $position_slug);
					$old_profile ? $report['profiles_updated']++ : $report['profiles_created']++;
				}
				if ($manager_user_id && class_exists('SN_Hierarchy_Service')) {
					$parent_profile = $hr->get_profile_by_user_id($manager_user_id);
					if ($parent_profile) {
						$result = (new SN_Hierarchy_Service())->assign_parent((int) $profile->id, (int) $parent_profile->id, get_current_user_id(), 'hr_simple_add', $notes ?: 'manual add parent');
						if (! empty($result['success'])) { $report['assignments_changed'] = 1; } else { $report['warnings'][] = (string) ($result['message'] ?? 'manager_assign_failed'); }
					} else { $report['warnings'][] = 'manager_profile_missing'; }
				}
				$report['valid'] = 1;
				$this->sn_hr_panel_log_profile((int) $profile->id, (int) $user->ID, 'hr_simple_person_saved', null, $data, ['source' => 'manual_simple_add']);
			} else {
				$report['errors'][] = 'profile_create_failed';
			}
		}
		if (! empty($report['errors'])) {
			$report['invalid'] = 1;
		}
		update_option('sn_hr_csv_dry_run_report', $report, false);
		if (! empty($report['errors'])) {
			error_log('SN HR manual add failed | ' . wp_json_encode($report, JSON_UNESCAPED_UNICODE));
		}
		$redirect = ($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_simple_person_saved' : 'hr_simple_person_error'])) . '#hr-manual-add';
		if (wp_doing_ajax()) {
			wp_send_json([
				'success' => empty($report['errors']),
				'message' => empty($report['errors']) ? 'نیرو اضافه شد و دسترسی پنل ثبت شد.' : implode('، ', array_map('strval', $report['errors'])),
				'user_id' => ($user instanceof WP_User) ? (int) $user->ID : 0,
				'redirect' => $redirect,
				'report' => $report,
			]);
		}
		wp_safe_redirect($redirect);
		exit;
	}

	public function handle_hr_profile_action(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_profile_action');
		$redirect_base = $this->sn_hr_panel_return_url();
		if (! class_exists('SN_HR_Service') || ! class_exists('SN_Hierarchy_Service')) {
			wp_safe_redirect(add_query_arg(['sn_msg' => 'hr_profile_action_error'], $redirect_base));
			exit;
		}
		$mode = sanitize_key(wp_unslash($_POST['hr_action_mode'] ?? 'dry_run'));
		$dry_run = $mode !== 'apply';
		$selected_user_id = absint($_POST['user_lookup_select'] ?? 0);
		$user = $selected_user_id ? get_user_by('id', $selected_user_id) : $this->sn_find_user_by_lookup(sanitize_text_field(wp_unslash($_POST['user_lookup'] ?? '')));
		if (! $user instanceof WP_User) {
			update_option('sn_hr_panel_action_report', [
				'tool' => 'hr_panel_profile_action',
				'mode' => sanitize_key(wp_unslash($_POST['hr_action_mode'] ?? 'dry_run')),
				'errors' => 1,
				'warnings' => ['کاربر یا مدیر مستقیم معتبر نیست', 'user_not_found'],
				'updated_at' => current_time('mysql'),
			], false);
			wp_safe_redirect(add_query_arg(['sn_msg' => 'hr_profile_action_error'], $redirect_base));
			exit;
		}
		global $wpdb;
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$profile = $hr->get_profile_by_user_id((int) $user->ID);
		$create_missing = ! empty($_POST['create_missing_profile']);
		$target_position_id = absint($_POST['target_position_id'] ?? 0);
		$target_level_raw = sanitize_text_field(wp_unslash($_POST['target_level_id'] ?? '-1'));
		$change_level = $target_level_raw !== '-1';
		$target_level_id = $change_level ? absint($target_level_raw) : ($profile ? (int) $profile->level_id : 0);
		$manager_user_id = absint($_POST['manager_user_id'] ?? 0);
		$manager_lookup = sanitize_text_field(wp_unslash($_POST['manager_lookup'] ?? ''));
		$end_assignment = ! empty($_POST['end_assignment']);
		$set_active = ! empty($_POST['is_active']) ? 1 : 0;
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$metadata = [
			'employee_code' => sanitize_text_field(wp_unslash($_POST['employee_code'] ?? '')),
			'employment_status' => sanitize_key(wp_unslash($_POST['employment_status'] ?? '')),
			'employment_type' => sanitize_key(wp_unslash($_POST['employment_type'] ?? '')),
				'manual_invoice_access' => isset($_POST['manual_invoice_access']) ? sanitize_key(wp_unslash($_POST['manual_invoice_access'])) : null,
				'extra_number_request_access' => isset($_POST['extra_number_request_access']) ? sanitize_key(wp_unslash($_POST['extra_number_request_access'])) : null,
				'team_invoice_source_mode' => isset($_POST['team_invoice_source_mode']) ? sanitize_key(wp_unslash($_POST['team_invoice_source_mode'])) : null,
			'national_id' => sanitize_text_field(wp_unslash($_POST['national_id'] ?? '')),
			'work_phone' => sanitize_text_field(wp_unslash($_POST['work_phone'] ?? '')),
			'emergency_phone' => sanitize_text_field(wp_unslash($_POST['emergency_phone'] ?? '')),
			'hire_date' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['hire_date'] ?? ''))),
			'termination_date' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['termination_date'] ?? ''))),
			'base_salary' => isset($_POST['base_salary']) && $_POST['base_salary'] !== '' ? absint($_POST['base_salary']) : null,
			'salary_currency' => in_array((string) ($_POST['salary_currency'] ?? ''), ['IRT', 'IRR'], true) ? (string) $_POST['salary_currency'] : '',
			'department_id' => intval($_POST['department_id'] ?? -1),
			'unit_id' => intval($_POST['unit_id'] ?? -1),
			'team_id' => intval($_POST['team_id'] ?? -1),
			'notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
		];
		$commission_enabled_mode = sanitize_text_field(wp_unslash($_POST['commission_enabled_mode'] ?? ''));
		$commission_override_mode_mode = sanitize_key(wp_unslash($_POST['commission_override_mode_mode'] ?? ''));
		$default_commission_rule_raw = sanitize_text_field(wp_unslash($_POST['default_commission_rule_id'] ?? '-1'));
		$comp_effective_from = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['comp_effective_from'] ?? '')));
		$comp_effective_to = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['comp_effective_to'] ?? '')));
		$comp_notes = sanitize_textarea_field(wp_unslash($_POST['comp_notes'] ?? ''));
		$old_manager = $hierarchy->get_current_parent_user_id((int) $user->ID);
		$report = [
			'tool' => 'hr_panel_profile_action',
			'mode' => $dry_run ? 'dry_run' : 'apply',
			'user_id' => (int) $user->ID,
			'display_name' => (string) $user->display_name,
			'had_profile' => (bool) $profile,
			'old_position' => $profile ? $this->sn_hr_position_slug_by_id((int) $profile->position_id) : '',
			'old_level' => $profile ? $this->sn_hr_level_slug_by_id((int) $profile->level_id) : '',
			'old_manager' => $old_manager,
			'old_manager_label' => $old_manager ? $this->sn_user_label((int) $old_manager) : '—',
			'would_create_profile' => ! $profile && $create_missing,
			'would_change_position' => $profile && $target_position_id && (int) $profile->position_id !== $target_position_id,
			'would_change_level' => $profile && $change_level && (int) $profile->level_id !== $target_level_id,
			'would_change_active' => $profile && $set_active !== null && (int) $profile->is_active !== $set_active,
			'would_change_metadata' => false,
			'would_change_manager' => false,
			'changed_position' => false,
			'changed_level' => false,
			'changed_active' => false,
			'changed_metadata' => false,
			'changed_compensation' => false,
			'changed_manager' => false,
			'errors' => 0,
			'warnings' => [],
			'reason' => $reason,
			'updated_at' => current_time('mysql'),
		];
		$new_manager = $manager_user_id ? get_user_by('id', $manager_user_id) : ($manager_lookup !== '' ? $this->sn_find_user_by_lookup($manager_lookup) : null);
		if ($new_manager instanceof WP_User) {
			$report['new_manager'] = (int) $new_manager->ID;
			$report['new_manager_label'] = $this->sn_user_label((int) $new_manager->ID);
			$report['old_manager_label'] = $old_manager ? $this->sn_user_label((int) $old_manager) : '—';
			$report['would_change_manager'] = (int) $new_manager->ID !== $old_manager;
			if ((int) $new_manager->ID === (int) $user->ID) {
				$report['errors']++;
				$report['warnings'][] = 'self_manager_not_allowed';
				$report['warnings'][] = 'کاربر نمی‌تواند مدیر مستقیم خودش باشد';
			}
			// A manually typed manager must still respect the HR chain. This was
			// previously checked only by the bulk UI, allowing the regular profile
			// editor to save invalid relationships and omit Operations leaders.
			$child_position_slug = $target_position_id
				? $this->sn_hr_position_slug_by_id($target_position_id)
				: ($profile ? $this->sn_hr_position_slug_by_id((int) $profile->position_id) : '');
			$parent_profile = class_exists('SN_HR_Service') ? (new SN_HR_Service())->get_profile_by_user_id((int) $new_manager->ID) : null;
			$parent_position_slug = $parent_profile ? $this->sn_hr_position_slug_by_id((int) $parent_profile->position_id) : '';
			if ($child_position_slug !== '' && $this->sn_hr_allowed_parent_positions($child_position_slug) && ! $this->sn_hr_manager_allowed_for_child($child_position_slug, $parent_position_slug)) {
				$report['errors']++;
				$report['warnings'][] = 'نیروی بالادستی با سمت این نیرو سازگار نیست';
			}
		} elseif ($manager_user_id || $manager_lookup !== '') {
			$report['errors']++;
			$report['warnings'][] = 'manager_not_found';
			$report['warnings'][] = 'کاربر یا مدیر مستقیم معتبر نیست';
		}
		if (! $profile && ! $create_missing) {
			$report['errors']++;
			$report['warnings'][] = 'profile_missing';
		}
		if ($profile) {
			foreach ($this->sn_hr_profile_metadata_update($profile, $metadata) as $k => $v) {
				$current = $profile->{$k} ?? null;
				if ((string) $current !== (string) $v) {
					$report['would_change_metadata'] = true;
					break;
				}
			}
		}
		if (! $dry_run && empty($report['errors'])) {
			if (! $profile) {
				$profile = $hr->get_or_create_profile_for_user((int) $user->ID);
			}
			if ($profile && ($target_position_id || $change_level)) {
				$position_id = $target_position_id ?: (int) $profile->position_id;
				$updated = $hr->update_profile_position_level((int) $user->ID, $position_id, $target_level_id, get_current_user_id());
				$report['changed_position'] = $updated && (int) $profile->position_id !== $position_id;
				$report['changed_level'] = $updated && $change_level && (int) $profile->level_id !== $target_level_id;
				$profile = $hr->get_profile_by_user_id((int) $user->ID);
				if ($report['changed_position'] && $profile) {
					$this->sn_hr_apply_user_access_for_position((int) $user->ID, $this->sn_hr_position_slug_by_id((int) $profile->position_id));
				}
			}
			if ($profile && $set_active !== null && (int) $profile->is_active !== $set_active) {
				$old = ['is_active' => (int) $profile->is_active];
				$wpdb->update($wpdb->prefix . 'sn_hr_profiles', ['is_active' => $set_active, 'updated_at' => current_time('mysql')], ['id' => (int) $profile->id]);
				$this->sn_hr_panel_log_profile((int) $profile->id, (int) $user->ID, 'hr_panel_profile_activation_updated', $old, ['is_active' => $set_active], ['reason' => $reason]);
				$report['changed_active'] = true;
			}
			if ($profile) {
				$meta_update = $this->sn_hr_profile_metadata_update($profile, $metadata);
				if (! empty($meta_update)) {
					$old_meta = [];
					foreach ($meta_update as $k => $v) { $old_meta[$k] = $profile->{$k} ?? null; }
					$meta_update['updated_at'] = current_time('mysql');
					$wpdb->update($wpdb->prefix . 'sn_hr_profiles', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_hr_profiles', $meta_update), ['id' => (int) $profile->id]);
					$this->sn_hr_panel_log_profile((int) $profile->id, (int) $user->ID, 'hr_panel_profile_metadata_updated', $old_meta, $meta_update, ['reason' => $reason]);
					$report['changed_metadata'] = true;
				}
			}
			$profile = $hr->get_profile_by_user_id((int) $user->ID);
			if ($profile) {
				$comp_payload = [];
				if ($metadata['base_salary'] !== null) { $comp_payload['base_salary'] = (int) $metadata['base_salary']; }
				if ($metadata['salary_currency'] !== '') { $comp_payload['salary_currency'] = $metadata['salary_currency']; }
				if ($commission_override_mode_mode !== '') {
					$mode = $this->sn_commission_normalize_override_mode($commission_override_mode_mode);
					$comp_payload['commission_override_mode'] = $mode;
					$comp_payload['commission_enabled'] = $mode === 'disabled' ? 0 : 1;
				}
				if (in_array($commission_enabled_mode, ['0', '1'], true) && $commission_override_mode_mode === '') { $comp_payload['commission_enabled'] = (int) $commission_enabled_mode; }
				if ($default_commission_rule_raw !== '-1') { $comp_payload['default_commission_rule_id'] = absint($default_commission_rule_raw) ?: null; }
				if ($comp_effective_from !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $comp_effective_from)) { $comp_payload['effective_from'] = $comp_effective_from; }
				if ($comp_effective_to !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $comp_effective_to)) { $comp_payload['effective_to'] = $comp_effective_to; }
				if ($comp_notes !== '') { $comp_payload['notes'] = $comp_notes; }
				if ($comp_payload) {
					$comp_payload['is_active'] = 1;
					$comp_result = $this->sn_hr_compensation_update((int) $profile->id, (int) $user->ID, $comp_payload, $reason ?: 'HR compensation readiness update');
					$report['changed_compensation'] = ! empty($comp_result['changed']);
				}
			}
			$profile = $hr->get_profile_by_user_id((int) $user->ID);
			if ($profile && $end_assignment) {
				$report['changed_manager'] = $hierarchy->end_current_assignment((int) $profile->id, get_current_user_id(), $reason ?: 'HR panel end assignment');
			} elseif ($profile && $new_manager instanceof WP_User && (int) $new_manager->ID !== $old_manager) {
				$parent = $hr->get_profile_by_user_id((int) $new_manager->ID);
				if ($parent) {
					$result = $hierarchy->assign_parent((int) $profile->id, (int) $parent->id, get_current_user_id(), 'hr_panel', $reason ?: 'HR panel manager assignment');
					$report['assignment_result'] = $result;
					$report['changed_manager'] = ! empty($result['success']) && empty($result['skipped']);
					if (empty($result['success'])) {
						$report['errors']++;
						$message = (string) ($result['message'] ?? 'assignment_failed');
						$report['warnings'][] = $message;
						if ($message === 'cycle_not_allowed') { $report['warnings'][] = 'این تغییر باعث چرخه در سلسله‌مراتب می‌شود و مسدود شد'; }
						if ($message === 'self_parent_not_allowed') { $report['warnings'][] = 'کاربر نمی‌تواند مدیر مستقیم خودش باشد'; }
					}
				} else {
					$report['errors']++;
					$report['warnings'][] = 'manager_profile_missing';
				}
			}
		}
		update_option('sn_hr_panel_action_report', $report, false);
		if (wp_doing_ajax()) {
			wp_send_json(['success' => empty($report['errors']), 'message' => empty($report['errors']) ? 'پروفایل ذخیره شد.' : 'ذخیره پروفایل با خطا همراه بود.', 'report' => $report]);
		}
		wp_safe_redirect(add_query_arg([
			'sn_msg' => empty($report['errors']) ? 'hr_profile_action_done' : 'hr_profile_action_error',
			'hr_action_mode' => $dry_run ? 'dry_run' : 'apply',
			'hr_action_errors' => (int) ($report['errors'] ?? 0),
		], $redirect_base));
		exit;
	}

	public function handle_hr_inline_profile_update(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_inline_profile_update');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		$user_id = absint($_POST['user_id'] ?? 0);
		$report = $this->sn_hr_apply_workforce_update($user_id, $this->sn_hr_workforce_payload_from_post(), false, 'hr_inline_profile_update');
		update_option('sn_hr_inline_update_report', $report, false);
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_profile_action_done' : 'hr_profile_action_error']) . '#hr-workforce');
		exit;
	}


	private function sn_hr_workforce_payload_from_row_post(array $row, bool $include_compensation = false): array
	{
		$payload = [
			'display_name' => sanitize_text_field(wp_unslash($row['display_name'] ?? '')),
			'first_name' => sanitize_text_field(wp_unslash($row['first_name'] ?? '')),
			'last_name' => sanitize_text_field(wp_unslash($row['last_name'] ?? '')),
			'position_id' => absint($row['position_id'] ?? 0),
			'level_id' => absint($row['level_id'] ?? 0),
			'manager_user_id' => array_key_exists('manager_user_id', $row) ? absint($row['manager_user_id'] ?? 0) : null,
			'employment_status' => sanitize_key(wp_unslash($row['employment_status'] ?? '')),
			'employment_type' => sanitize_key(wp_unslash($row['employment_type'] ?? '')),
				'manual_invoice_access' => array_key_exists('manual_invoice_access', $row) ? sanitize_key(wp_unslash($row['manual_invoice_access'])) : null,
				'extra_number_request_access' => array_key_exists('extra_number_request_access', $row) ? sanitize_key(wp_unslash($row['extra_number_request_access'])) : null,
				'team_invoice_source_mode' => array_key_exists('team_invoice_source_mode', $row) ? sanitize_key(wp_unslash($row['team_invoice_source_mode'])) : null,
			'is_active' => array_key_exists('is_active', $row) ? absint($row['is_active']) : null,
			'reason' => sanitize_textarea_field(wp_unslash($_POST['reason'] ?? 'bulk_inline_hr_workforce_update')),
		];
		if ($payload['manager_user_id'] === null) { unset($payload['manager_user_id']); }
		if ($include_compensation) {
			$payload['fixed_salary_enabled'] = ! empty($row['fixed_salary_enabled']);
			$payload['base_salary'] = ($row['base_salary'] ?? '') === '' ? null : absint($row['base_salary']);
			if (isset($row['commission_override_mode']) && $row['commission_override_mode'] !== '') {
				$payload['commission_override_mode'] = $this->sn_commission_normalize_override_mode((string) $row['commission_override_mode']);
				$payload['commission_enabled'] = $payload['commission_override_mode'] === 'disabled' ? 0 : 1;
			} elseif (isset($row['commission_enabled']) && $row['commission_enabled'] !== '') {
				$payload['commission_enabled'] = absint($row['commission_enabled']);
			}
			if (array_key_exists('default_commission_rule_id', $row)) {
				$payload['default_commission_rule_id'] = absint($row['default_commission_rule_id'] ?? 0);
			}
			$payload['effective_from'] = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($row['effective_from'] ?? '')));
		}
		return $payload;
	}

	private function sn_hr_workforce_filters_from_post(): array
	{
		return [
			'q' => sanitize_text_field(wp_unslash($_POST['sn_hr_q'] ?? '')),
			'position' => sanitize_key(wp_unslash($_POST['sn_hr_position'] ?? '')),
			'level' => sanitize_key(wp_unslash($_POST['sn_hr_level'] ?? '')),
			'active' => in_array((string) ($_POST['sn_hr_active'] ?? ''), ['0', '1'], true) ? (string) $_POST['sn_hr_active'] : '',
			'assignment' => in_array((string) ($_POST['sn_hr_assignment'] ?? ''), ['has', 'none'], true) ? (string) $_POST['sn_hr_assignment'] : '',
			'legacy_role' => sanitize_key(wp_unslash($_POST['sn_hr_legacy_role'] ?? '')),
			'employment_status' => sanitize_key(wp_unslash($_POST['sn_hr_employment_status'] ?? '')),
			'department_id' => absint($_POST['sn_hr_department'] ?? 0),
			'unit_id' => absint($_POST['sn_hr_unit'] ?? 0),
			'team_id' => absint($_POST['sn_hr_team'] ?? 0),
			'manager_user_id' => absint($_POST['sn_hr_manager'] ?? 0),
			'missing_manager' => ! empty($_POST['sn_hr_missing_manager']) ? '1' : '',
			'missing_level' => ! empty($_POST['sn_hr_missing_level']) ? '1' : '',
			'missing_comp_history' => ! empty($_POST['sn_hr_missing_comp_history']) ? '1' : '',
		];
	}

	private function sn_hr_user_ids_for_posted_filter_scope(): array
	{
		$filters = $this->sn_hr_workforce_filters_from_post();
		$rows = $this->sn_hr_workforce_rows($filters, 500);
		return array_values(array_unique(array_filter(array_map(static fn($row) => (int) ($row->user_id ?? 0), $rows))));
	}

	private function sn_hr_workforce_rows_from_post(): array
	{
		if (isset($_POST['rows_json']) && is_string($_POST['rows_json'])) {
			$rows = json_decode(wp_unslash($_POST['rows_json']), true);
			return is_array($rows) ? wp_slash($rows) : [];
		}
		return is_array($_POST['rows'] ?? null) ? (array) $_POST['rows'] : [];
	}

	public function handle_hr_bulk_inline_profile_update(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_bulk_inline_profile_update');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		$rows = $this->sn_hr_workforce_rows_from_post();
		$selected_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['user_ids'] ?? [])))));
		$visible_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['visible_user_ids'] ?? [])))));
		$scope = sanitize_key(wp_unslash($_POST['save_scope'] ?? 'selected'));
		$target_ids = $scope === 'visible' ? $visible_ids : $selected_ids;
		$mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'apply'));
		$dry_run = false;
		$include_compensation = ! empty($_POST['save_compensation_fields']);
		$report = [
			'action' => 'hr_bulk_inline_profile_update',
			'mode' => $dry_run ? 'dry_run' : 'apply',
			'scope' => $scope,
			'include_compensation' => $include_compensation,
			'selected_count' => count($target_ids),
			'changed_count' => 0,
			'errors' => [],
			'items' => [],
			'message' => '',
			'updated_at' => current_time('mysql'),
		];
		if (! $target_ids) { $report['errors'][] = 'no_users_selected_or_visible'; }
		foreach ($target_ids as $uid) {
			if (! isset($rows[$uid]) || ! is_array($rows[$uid])) { $report['errors'][] = '#' . $uid . ':row_payload_missing'; }
		}
		if (empty($report['errors'])) {
			foreach ($target_ids as $uid) {
				$row = $rows[$uid] ?? $rows[(string) $uid] ?? null;
				if (! is_array($row)) {
					$report['errors'][] = '#' . $uid . ':row_payload_missing';
					continue;
				}
				$payload = $this->sn_hr_workforce_payload_from_row_post($row, $include_compensation);
				$item = $this->sn_hr_apply_workforce_update($uid, $payload, $dry_run, 'hr_bulk_inline_save');
				$report['items'][] = [
					'user_id' => $uid,
					'errors' => $item['errors'] ?? [],
					'messages' => $item['messages'] ?? [],
					'changed' => ! empty($item['changed']),
				];
				if (! empty($item['changed'])) { $report['changed_count']++; }
				foreach ((array) ($item['errors'] ?? []) as $error) { $report['errors'][] = '#' . $uid . ':' . $error; }
			}
		}
		$report['message'] = empty($report['errors']) ? ($dry_run ? 'Dry-run ذخیره انجام شد؛ داده‌ای ذخیره نشد.' : 'ذخیره ردیف انجام شد.') : 'ذخیره کامل نشد.';
		update_option('sn_hr_bulk_inline_update_report', $report, false);
		if (wp_doing_ajax()) { wp_send_json(['success' => empty($report['errors']), 'message' => (string) $report['message'], 'report' => $report]); }
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_bulk_inline_done' : 'hr_profile_action_error']) . '#hr-workforce');
		exit;
	}

	public function handle_hr_bulk_workforce_action(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_bulk_workforce_action');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		$user_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['user_ids'] ?? [])))));
		$bulk_scope = sanitize_key(wp_unslash($_POST['bulk_scope'] ?? 'selected'));
		if ($bulk_scope === 'filtered') {
			$user_ids = $this->sn_hr_user_ids_for_posted_filter_scope();
		}
		$mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'apply'));
		$dry_run = false;
		$bulk_action = sanitize_key(wp_unslash($_POST['bulk_action'] ?? ''));
		$payload = $this->sn_hr_workforce_payload_from_post();
		$payload['bulk_action'] = $bulk_action;
		$payload['overwrite_manager'] = ! empty($_POST['overwrite_manager']);
		$payload['overwrite_compensation'] = ! empty($_POST['overwrite_compensation']);
		$report = [
			'action' => 'hr_bulk_workforce_action',
			'mode' => $dry_run ? 'dry_run' : 'apply',
			'bulk_action' => $bulk_action,
			'bulk_scope' => $bulk_scope,
			'filter_scope' => $bulk_scope === 'filtered' ? $this->sn_hr_workforce_filters_from_post() : [],
			'selected_count' => count($user_ids),
			'changed_count' => 0,
			'errors' => [],
			'items' => [],
			'message' => '',
			'updated_at' => current_time('mysql'),
		];
		if (! $user_ids) {
			$report['errors'][] = 'no_users_selected';
		}
		if (! in_array($bulk_action, ['manager','position','level','employment','compensation'], true)) {
			$report['errors'][] = 'invalid_bulk_action';
		}
		if ($bulk_action === 'manager' && empty($payload['manager_user_id'])) {
			$report['errors'][] = 'manager_required';
		}
		if (empty($report['errors'])) {
			foreach ($user_ids as $uid) {
				$item_payload = $payload;
				if ($bulk_action !== 'manager') { unset($item_payload['manager_user_id']); }
				if ($bulk_action !== 'position') { unset($item_payload['position_id']); }
				if ($bulk_action !== 'level') { unset($item_payload['level_id']); }
				if ($bulk_action !== 'employment') { unset($item_payload['employment_status'], $item_payload['employment_type']); }
				if ($bulk_action !== 'compensation') { unset($item_payload['fixed_salary_enabled'], $item_payload['base_salary'], $item_payload['commission_enabled'], $item_payload['commission_override_mode'], $item_payload['default_commission_rule_id'], $item_payload['effective_from']); }
				$item = $this->sn_hr_apply_workforce_update($uid, $item_payload, $dry_run, 'hr_bulk_' . $bulk_action);
				$report['items'][] = [
					'user_id' => $uid,
					'errors' => $item['errors'] ?? [],
					'messages' => $item['messages'] ?? [],
					'changed' => ! empty($item['changed']),
				];
				if (! empty($item['changed'])) { $report['changed_count']++; }
				foreach ((array) ($item['errors'] ?? []) as $error) { $report['errors'][] = '#' . $uid . ':' . $error; }
			}
		}
		$report['message'] = empty($report['errors']) ? ($dry_run ? 'Dry-run انجام شد؛ داده‌ای ذخیره نشد.' : 'تغییرات گروهی ذخیره شد.') : 'عملیات گروهی کامل نشد.';
		update_option('sn_hr_bulk_workforce_report', $report, false);
		if (wp_doing_ajax()) { wp_send_json(['success' => empty($report['errors']), 'message' => (string) $report['message'], 'report' => $report]); }
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_bulk_assignment_done' : 'hr_profile_action_error']) . '#hr-bulk');
		exit;
	}


	private function sn_hr_supervisor_replacement_options(): array
	{
		global $wpdb;
		if (! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles')) { return []; }
		return $wpdb->get_results("SELECT p.id AS profile_id, p.user_id, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug AS position_slug, pos.label AS position_label,
			(SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_assignments a WHERE a.parent_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to') AS direct_children_count
			FROM {$wpdb->prefix}sn_hr_profiles p
			INNER JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id
			WHERE p.is_active=1 AND pos.slug IN ('supervisor','senior_supervisor','sales_manager')
			ORDER BY FIELD(pos.slug,'sales_manager','senior_supervisor','supervisor'), u.display_name ASC") ?: [];
	}

	public function handle_hr_replace_supervisor(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_hr_replace_supervisor');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate_if_needed(); }
		global $wpdb;
		$old_user_id = absint($_POST['old_supervisor_user_id'] ?? 0);
		$new_user_id = absint($_POST['new_supervisor_user_id'] ?? 0);
		$mode = sanitize_key(wp_unslash($_POST['mode'] ?? 'dry_run'));
		$apply = $mode === 'apply';
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$scope = sanitize_key(wp_unslash($_POST['replacement_scope'] ?? 'direct_children'));
		$deactivate_old = ! empty($_POST['deactivate_old_supervisor']);
		$actor_id = get_current_user_id();
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$old_profile = $old_user_id ? $hr->get_profile_by_user_id($old_user_id) : null;
		$new_profile = $new_user_id ? $hr->get_profile_by_user_id($new_user_id) : null;
		$report = [
			'action' => 'hr_replace_supervisor',
			'mode' => $apply ? 'apply' : 'dry_run',
			'old_supervisor_user_id' => $old_user_id,
			'old_supervisor_label' => $old_user_id ? $this->sn_user_label($old_user_id) : '',
			'new_supervisor_user_id' => $new_user_id,
			'new_supervisor_label' => $new_user_id ? $this->sn_user_label($new_user_id) : '',
			'scope' => $scope,
			'reason' => $reason,
			'candidates' => 0,
			'changed' => 0,
			'skipped' => 0,
			'errors' => [],
			'rows' => [],
			'deactivated_old_supervisor' => false,
			'updated_at' => current_time('mysql'),
		];
		if (! $old_profile || ! $new_profile) { $report['errors'][] = 'old_or_new_profile_missing'; }
		if ($old_user_id && $old_user_id === $new_user_id) { $report['errors'][] = 'same_supervisor_not_allowed'; }
		if ($apply && $confirm !== 'APPLY') { $report['errors'][] = 'confirm_apply_required'; }
		if (empty($report['errors'])) {
			$child_rows = $wpdb->get_results($wpdb->prepare("SELECT child.*, COALESCE(NULLIF(child.hr_display_name,''), u.display_name) AS display_name, u.user_login, pos.slug AS position_slug, pos.label AS position_label
				FROM {$wpdb->prefix}sn_hr_assignments a
				INNER JOIN {$wpdb->prefix}sn_hr_profiles child ON child.id=a.child_profile_id
				INNER JOIN {$wpdb->users} u ON u.ID=child.user_id
				LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=child.position_id
				WHERE a.parent_profile_id=%d AND a.is_current=1 AND a.relationship_type='reports_to'
				ORDER BY FIELD(pos.slug,'senior_supervisor','supervisor','seller'), u.display_name ASC", (int) $old_profile->id)) ?: [];
			if ($scope === 'sellers_only') {
				$child_rows = array_values(array_filter($child_rows, static fn($row) => (string) ($row->position_slug ?? '') === 'seller'));
			}
			$report['candidates'] = count($child_rows);
			foreach ($child_rows as $child) {
				$row = [
					'user_id' => (int) $child->user_id,
					'label' => $this->sn_user_label((int) $child->user_id),
					'position' => (string) ($child->position_slug ?? ''),
					'old_parent_profile_id' => (int) $old_profile->id,
					'new_parent_profile_id' => (int) $new_profile->id,
					'would_change' => true,
					'changed' => false,
				];
				if ($apply) {
					$result = $hierarchy->assign_parent((int) $child->id, (int) $new_profile->id, $actor_id, 'hr_supervisor_replacement', $reason ?: 'جابه‌جایی سرپرست');
					$row['assignment_result'] = $result;
					if (! empty($result['success']) && empty($result['skipped'])) {
						$row['changed'] = true;
						$report['changed']++;
						$this->sn_hr_panel_log_profile((int) $child->id, (int) $child->user_id, 'hr_supervisor_replacement_child_reassigned', [
							'old_supervisor_user_id' => $old_user_id,
							'old_supervisor_label' => $this->sn_user_label($old_user_id),
						], [
							'new_supervisor_user_id' => $new_user_id,
							'new_supervisor_label' => $this->sn_user_label($new_user_id),
						], ['reason' => $reason, 'source' => 'hr_supervisor_replacement']);
					} elseif (! empty($result['skipped'])) {
						$report['skipped']++;
					} else {
						$report['errors'][] = 'child_' . (int) $child->user_id . ':' . (string) ($result['message'] ?? 'assignment_failed');
					}
				}
				$report['rows'][] = $row;
			}
			if ($apply && $deactivate_old && $old_profile) {
				$old_state = ['is_active' => (int) $old_profile->is_active, 'employment_status' => (string) ($old_profile->employment_status ?? '')];
				$wpdb->update($wpdb->prefix . 'sn_hr_profiles', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_hr_profiles', [
					'is_active' => 0,
					'employment_status' => 'inactive',
					'updated_at' => current_time('mysql'),
				]), ['id' => (int) $old_profile->id]);
				$report['deactivated_old_supervisor'] = true;
				$this->sn_hr_panel_log_profile((int) $old_profile->id, $old_user_id, 'hr_supervisor_replacement_old_supervisor_deactivated', $old_state, ['is_active' => 0, 'employment_status' => 'inactive'], ['reason' => $reason, 'new_supervisor_user_id' => $new_user_id]);
			}
			if ($apply) {
				$this->sn_hr_panel_log_profile((int) ($new_profile->id ?? 0), $new_user_id, 'hr_supervisor_replacement_applied', ['old_supervisor_user_id' => $old_user_id, 'old_supervisor_label' => $this->sn_user_label($old_user_id)], ['new_supervisor_user_id' => $new_user_id, 'moved_count' => (int) $report['changed']], ['reason' => $reason]);
			}
		}
		update_option('sn_hr_replace_supervisor_report', $report, false);
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_replace_supervisor_done' : 'hr_replace_supervisor_error']) . '#hr-bulk');
		exit;
	}

	public function handle_hr_send_login_credentials_sms(): void
	{
		if (! $this->sn_can_manage_hr_panel()) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_hr_send_login_credentials_sms');
		$user_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['user_ids'] ?? [])))));
		$confirm = strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? '')));
		$reset_password = ! empty($_POST['reset_password']);
		$template = sanitize_textarea_field(wp_unslash($_POST['sms_template'] ?? ''));
		if ($template === '') {
			$template = "نام کاربری: {username}\nرمز عبور موقت: {password}\nورود: {login_url}";
		}
		$report = [
			'action' => 'hr_login_credentials_sms',
			'selected_count' => count($user_ids),
			'sent' => 0,
			'failed' => 0,
			'skipped' => 0,
			'rows' => [],
			'errors' => [],
			'updated_at' => current_time('mysql'),
		];
		if ($confirm !== 'APPLY') {
			$report['errors'][] = 'confirm_apply_required';
		}
		if (! $reset_password) {
			$report['errors'][] = 'reset_password_required_existing_password_not_readable';
		}
		if (! $user_ids) {
			$report['errors'][] = 'no_users_selected';
		}
		if (! class_exists('SN_SMS')) {
			$report['errors'][] = 'sms_service_missing';
		}
		if (empty($report['errors'])) {
			$sms = new SN_SMS();
			foreach ($user_ids as $uid) {
				$user = get_user_by('id', $uid);
				$phone = $this->sn_login_credential_phone_for_user($uid);
				$row = [
					'user_id' => $uid,
					'phone_masked' => $phone ? $this->sn_mask_phone($phone) : '',
					'status' => 'skipped',
					'message' => '',
				];
				if (! $user instanceof WP_User) {
					$row['message'] = 'user_not_found';
					$report['skipped']++;
					$report['rows'][] = $row;
					continue;
				}
				if (! SN_Helpers::is_valid_mobile($phone)) {
					$row['message'] = 'valid_mobile_not_found';
					$report['skipped']++;
					$report['rows'][] = $row;
					continue;
				}
				$password = wp_generate_password(12, false, false);
				wp_set_password($password, $uid);
				$message = str_replace(
					['{display_name}', '{username}', '{password}', '{login_url}'],
					[(string) $user->display_name, (string) $user->user_login, $password, home_url('/crm-dashboard/')],
					$template
				);
				$sent = $sms->send($phone, $message);
				$row['status'] = $sent ? 'sent' : 'failed';
				$row['message'] = $sent ? 'sms_sent_password_not_logged' : 'رمز تغییر کرد ولی پیامک ارسال نشد';
				if ($sent) { $report['sent']++; } else { $report['failed']++; }
				$this->sn_hr_panel_log_profile(0, $uid, 'login_credentials_sms_sent', null, [
					'phone_masked' => $row['phone_masked'],
					'sms_status' => $row['status'],
					'password_reset' => true,
				], ['source' => 'hr_login_credentials_sms', 'password_logged' => false]);
				$report['rows'][] = $row;
				unset($password, $message);
			}
		}
		$this->sn_store_login_credentials_sms_report($report);
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => empty($report['errors']) ? 'hr_login_sms_done' : 'hr_profile_action_error']) . '#hr-bulk');
		exit;
	}

	public function handle_hr_set_user_password(): void
	{
		$is_ajax = wp_doing_ajax();
		if (! $this->sn_can_manage_hr_panel()) {
			if ($is_ajax) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); }
			wp_die('دسترسی غیرمجاز');
		}
		if ($is_ajax) {
			if (! check_ajax_referer('sn_hr_set_user_password', '_wpnonce', false)) {
				SN_Helpers::send_json(false, 'اعتبار فرم منقضی شده است؛ صفحه را تازه‌سازی کنید.');
			}
		} else {
			check_admin_referer('sn_hr_set_user_password');
		}

		$user_id = absint($_POST['user_id'] ?? 0);
		$generate = ! empty($_POST['generate_random']);
		$send_sms = ! empty($_POST['send_sms']);
		$new_password = (string) wp_unslash($_POST['new_password'] ?? '');
		$repeat = (string) wp_unslash($_POST['new_password_repeat'] ?? '');
		$user = $user_id ? get_user_by('id', $user_id) : null;
		$report = [
			'action' => 'hr_set_user_password',
			'user_id' => $user_id,
			'actor_user_id' => get_current_user_id(),
			'password_reset' => false,
			'sms_sent' => false,
			'phone_masked' => '',
			'errors' => [],
			'updated_at' => current_time('mysql'),
		];

		try {
			if (! $user instanceof WP_User) {
				$report['errors'][] = 'کاربر پیدا نشد.';
			}
			if ($generate) {
				$new_password = wp_generate_password(12, false, false);
				$repeat = $new_password;
			}
			$password_length = function_exists('mb_strlen') ? mb_strlen($new_password, 'UTF-8') : strlen($new_password);
			if ($new_password === '' || $password_length < 8) {
				$report['errors'][] = 'رمز باید حداقل ۸ کاراکتر باشد.';
			}
			if (! hash_equals($new_password, $repeat)) {
				$report['errors'][] = 'تکرار رمز با رمز جدید یکسان نیست.';
			}

			$sms_status = 'not_requested';
			if (empty($report['errors']) && $user instanceof WP_User) {
				wp_set_password($new_password, $user_id);
				clean_user_cache($user_id);
				$updated_user = get_user_by('id', $user_id);
				if (! $updated_user instanceof WP_User || ! wp_check_password($new_password, (string) $updated_user->user_pass, $user_id)) {
					throw new RuntimeException('password_write_verification_failed');
				}
				$report['password_reset'] = true;
				$phone = $this->sn_login_credential_phone_for_user($user_id);
				$report['phone_masked'] = $phone ? $this->sn_mask_phone($phone) : '';
				if ($send_sms) {
					if (! class_exists('SN_SMS')) {
						$sms_status = 'sms_service_missing';
						$report['errors'][] = 'رمز تغییر کرد، اما سرویس پیامک در دسترس نیست.';
					} elseif (! SN_Helpers::is_valid_mobile($phone)) {
						$sms_status = 'valid_mobile_not_found';
						$report['errors'][] = 'رمز تغییر کرد، اما شماره موبایل معتبر برای پیامک پیدا نشد.';
					} else {
						$message = sprintf(
							"سلام %s، اطلاعات ورود شما به پورتال CRM:\nشماره ورود: %s\nرمز عبور موقت: %s\nآدرس ورود: %s\nلطفاً پس از ورود رمز خود را تغییر دهید.",
							(string) ($user->display_name ?: $user->user_login),
							$phone,
							$new_password,
							home_url('/crm-dashboard/')
						);
						$sms = new SN_SMS();
						$sent = (bool) $sms->send($phone, $message);
						$report['sms_sent'] = $sent;
						$sms_status = $sent ? 'sent' : 'password_changed_sms_failed';
						if (! $sent) { $report['errors'][] = 'رمز تغییر کرد، اما پیامک ارسال نشد.'; }
						unset($message);
					}
				}
				try {
					$this->sn_hr_panel_log_profile(0, $user_id, 'hr_password_reset', null, [
						'password_reset' => true,
						'sms_sent' => ! empty($report['sms_sent']),
						'phone_masked' => $report['phone_masked'],
						'sms_status' => $sms_status,
					], ['source' => 'hr_set_user_password', 'password_logged' => false]);
				} catch (Throwable $log_error) {
					error_log('SN HR password audit log failed for user ' . $user_id . ': ' . $log_error->getMessage());
				}
			}
		} catch (Throwable $e) {
			error_log('SN handle_hr_set_user_password failed for user ' . $user_id . ': ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine());
			if (! $report['password_reset']) {
				$report['errors'][] = 'ذخیره رمز در وردپرس انجام نشد. کد خطا: password_write_failed';
			}
		}

		unset($new_password, $repeat);
		update_option('sn_hr_set_user_password_report', $report, false);
		$success = ! empty($report['password_reset']);
		$message = $success
			? (empty($report['errors']) ? 'رمز با موفقیت ثبت شد.' : implode(' ', array_map('strval', (array) $report['errors'])))
			: (empty($report['errors']) ? 'ثبت رمز انجام نشد.' : implode(' ', array_map('strval', (array) $report['errors'])));
		if ($is_ajax) {
			SN_Helpers::send_json($success, $message, ['report' => $report]);
		}
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => $success ? 'hr_password_reset_done' : 'hr_profile_action_error']) . '#hr-workforce');
		exit;
	}


	public function handle_hr_bulk_set_password(): void
	{
		$is_ajax = wp_doing_ajax();
		if (! $this->sn_can_manage_hr_panel()) {
			if ($is_ajax) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); }
			wp_die('دسترسی غیرمجاز');
		}
		if ($is_ajax) {
			if (! check_ajax_referer('sn_hr_bulk_set_password', '_wpnonce', false)) {
				SN_Helpers::send_json(false, 'اعتبار فرم منقضی شده است؛ صفحه را تازه‌سازی کنید.');
			}
		} else {
			check_admin_referer('sn_hr_bulk_set_password');
		}

		global $wpdb;
		$scope = sanitize_key(wp_unslash($_POST['password_scope'] ?? 'selected'));
		$confirm = strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? '')));
		$new_password = (string) wp_unslash($_POST['new_password'] ?? '');
		$repeat = (string) wp_unslash($_POST['new_password_repeat'] ?? '');
		$selected_ids = array_values(array_unique(array_filter(array_map('absint', (array) ($_POST['user_ids'] ?? [])))));
		$current_user_id = get_current_user_id();
		$report = [
			'action' => 'hr_bulk_set_password',
			'scope' => $scope,
			'actor_user_id' => $current_user_id,
			'selected_count' => count($selected_ids),
			'target_count' => 0,
			'changed' => 0,
			'skipped' => 0,
			'errors' => [],
			'rows' => [],
			'password_logged' => false,
			'updated_at' => current_time('mysql'),
		];

		if ($confirm !== 'APPLY') { $report['errors'][] = 'تأیید APPLY انجام نشده است.'; }
		if (! in_array($scope, ['selected', 'all_active_hr', 'all_hr'], true)) { $report['errors'][] = 'محدوده تغییر رمز نامعتبر است.'; }
		$password_length = function_exists('mb_strlen') ? mb_strlen($new_password, 'UTF-8') : strlen($new_password);
		if ($new_password === '' || $password_length < 8) { $report['errors'][] = 'رمز باید حداقل ۸ کاراکتر باشد.'; }
		if (! hash_equals($new_password, $repeat)) { $report['errors'][] = 'تکرار رمز با رمز جدید یکسان نیست.'; }

		$user_ids = [];
		$profile_table = $wpdb->prefix . 'sn_hr_profiles';
		if (empty($report['errors'])) {
			if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $profile_table)) !== $profile_table) {
				$report['errors'][] = 'جدول منابع انسانی در دسترس نیست.';
			} elseif ($scope === 'selected') {
				if (! $selected_ids) {
					$report['errors'][] = 'هیچ نیرویی انتخاب نشده است.';
				} else {
					foreach (array_chunk($selected_ids, 500) as $chunk) {
						$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
						$user_ids = array_merge($user_ids, array_map('intval', $wpdb->get_col($wpdb->prepare("SELECT DISTINCT user_id FROM {$profile_table} WHERE user_id IN ({$placeholders}) ORDER BY user_id ASC", ...$chunk)) ?: []));
					}
				}
			} elseif ($scope === 'all_active_hr') {
				$user_ids = array_map('intval', $wpdb->get_col("SELECT DISTINCT user_id FROM {$profile_table} WHERE user_id > 0 AND is_active=1 ORDER BY user_id ASC") ?: []);
			} else {
				$user_ids = array_map('intval', $wpdb->get_col("SELECT DISTINCT user_id FROM {$profile_table} WHERE user_id > 0 ORDER BY user_id ASC") ?: []);
			}
			$user_ids = array_values(array_unique(array_filter($user_ids, static fn($uid) => (int) $uid > 0)));
			$report['target_count'] = count($user_ids);
			if (! $user_ids && empty($report['errors'])) { $report['errors'][] = 'کاربری برای تغییر رمز پیدا نشد.'; }
		}

		if (empty($report['errors'])) {
			foreach ($user_ids as $uid) {
				$user = get_user_by('id', $uid);
				$row = [
					'user_id' => $uid,
					'username' => $user instanceof WP_User ? (string) $user->user_login : '',
					'display_name' => $user instanceof WP_User ? (string) $user->display_name : '',
					'status' => 'skipped',
					'message' => '',
				];
				if (! $user instanceof WP_User) {
					$row['message'] = 'کاربر پیدا نشد.';
					$report['skipped']++;
					$report['rows'][] = $row;
					continue;
				}
				if ($uid === $current_user_id) {
					$row['message'] = 'حساب کاربر اجراکننده برای جلوگیری از خروج ناخواسته تغییر نکرد.';
					$report['skipped']++;
					$report['rows'][] = $row;
					continue;
				}
				try {
					wp_set_password($new_password, $uid);
					clean_user_cache($uid);
					$updated_user = get_user_by('id', $uid);
					if (! $updated_user instanceof WP_User || ! wp_check_password($new_password, (string) $updated_user->user_pass, $uid)) {
						throw new RuntimeException('password_write_verification_failed');
					}
					$row['status'] = 'changed';
					$row['message'] = 'رمز تغییر کرد.';
					$report['changed']++;
					try {
						$this->sn_hr_panel_log_profile(0, $uid, 'hr_bulk_password_reset', null, [
							'password_reset' => true,
							'sms_sent' => false,
							'scope' => $scope,
							'actor_user_id' => $current_user_id,
						], ['source' => 'hr_bulk_set_password', 'password_logged' => false]);
					} catch (Throwable $log_error) {
						error_log('SN HR bulk password audit log failed for user ' . $uid . ': ' . $log_error->getMessage());
					}
				} catch (Throwable $e) {
					$row['status'] = 'failed';
					$row['message'] = 'ذخیره رمز انجام نشد.';
					$report['skipped']++;
					error_log('SN bulk password update failed for user ' . $uid . ': ' . $e->getMessage());
				}
				$report['rows'][] = $row;
			}
		}

		unset($new_password, $repeat);
		update_option('sn_hr_bulk_set_password_report', $report, false);
		$success = empty($report['errors']) && $report['changed'] > 0;
		$message = $success
			? sprintf('رمز %s نیرو ثبت شد؛ %s مورد تغییر نکرد.', number_format_i18n($report['changed']), number_format_i18n($report['skipped']))
			: (empty($report['errors']) ? 'هیچ رمزی تغییر نکرد.' : implode(' ', array_map('strval', (array) $report['errors'])));
		if ($is_ajax) { SN_Helpers::send_json($success, $message, ['report' => $report]); }
		wp_safe_redirect($this->sn_hr_panel_return_url(['sn_msg' => $success ? 'hr_bulk_password_done' : 'hr_profile_action_error']) . '#hr-workforce');
		exit;
	}

	private function sn_hr_workforce_payload_from_post(): array
	{
		return [
			'position_id' => absint($_POST['position_id'] ?? 0),
			'level_id' => absint($_POST['level_id'] ?? 0),
			'manager_user_id' => absint($_POST['manager_user_id'] ?? 0),
			'employment_status' => sanitize_key(wp_unslash($_POST['employment_status'] ?? '')),
				'employment_type' => sanitize_key(wp_unslash($_POST['employment_type'] ?? '')),
				'manual_invoice_access' => isset($_POST['manual_invoice_access']) ? sanitize_key(wp_unslash($_POST['manual_invoice_access'])) : null,
				'extra_number_request_access' => isset($_POST['extra_number_request_access']) ? sanitize_key(wp_unslash($_POST['extra_number_request_access'])) : null,
				'team_invoice_source_mode' => isset($_POST['team_invoice_source_mode']) ? sanitize_key(wp_unslash($_POST['team_invoice_source_mode'])) : null,
			'is_active' => isset($_POST['is_active']) ? absint($_POST['is_active']) : null,
			'fixed_salary_enabled' => ! empty($_POST['fixed_salary_enabled']),
			'base_salary' => ($_POST['base_salary'] ?? '') === '' ? null : absint($_POST['base_salary']),
			'commission_override_mode' => isset($_POST['commission_override_mode']) && $_POST['commission_override_mode'] !== '' ? $this->sn_commission_normalize_override_mode((string) $_POST['commission_override_mode']) : '',
			'commission_enabled' => isset($_POST['commission_enabled']) && $_POST['commission_enabled'] !== '' ? absint($_POST['commission_enabled']) : null,
			'default_commission_rule_id' => isset($_POST['default_commission_rule_id']) && (string) $_POST['default_commission_rule_id'] !== '-1' ? absint($_POST['default_commission_rule_id'] ?? 0) : null,
			'effective_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['effective_from'] ?? ''))),
			'reason' => sanitize_textarea_field(wp_unslash($_POST['reason'] ?? '')),
			'overwrite_manager' => ! empty($_POST['overwrite_manager']),
			'overwrite_compensation' => ! empty($_POST['overwrite_compensation']),
		];
	}

	private function sn_hr_apply_workforce_update(int $user_id, array $payload, bool $dry_run, string $source): array
	{
		global $wpdb;
		$report = ['user_id' => $user_id, 'mode' => $dry_run ? 'dry_run' : 'apply', 'source' => $source, 'changed' => false, 'errors' => [], 'messages' => []];
		if (! $user_id || ! class_exists('SN_HR_Service') || ! class_exists('SN_Hierarchy_Service')) {
			$report['errors'][] = 'invalid_user_or_service';
			return $report;
		}
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$profile = $hr->get_profile_by_user_id($user_id);
		if (! $profile) {
			$report['errors'][] = 'profile_missing';
			return $report;
		}
		$profiles_table = $wpdb->prefix . 'sn_hr_profiles';
		$this->sn_ensure_hr_display_name_column();
		$display_name = trim((string) ($payload['display_name'] ?? ''));
		$first_name = trim((string) ($payload['first_name'] ?? ''));
		$last_name = trim((string) ($payload['last_name'] ?? ''));
		if ($display_name === '' && trim($first_name . ' ' . $last_name) !== '') {
			$display_name = trim($first_name . ' ' . $last_name);
		}
		if ($display_name !== '' && (! isset($profile->hr_display_name) || (string) $profile->hr_display_name !== $display_name)) {
			$report['messages'][] = 'نام نمایشی HR تغییر می‌کند';
			if (! $dry_run) {
				$wpdb->update($profiles_table, $this->sn_filter_existing_columns($profiles_table, [
					'hr_display_name' => $display_name,
					'updated_at' => current_time('mysql'),
				]), ['id' => (int) $profile->id]);
				$this->sn_hr_panel_log_profile((int) $profile->id, $user_id, 'hr_display_name_updated', ['hr_display_name' => (string) ($profile->hr_display_name ?? '')], ['hr_display_name' => $display_name], ['source' => $source]);
				$report['changed'] = true;
				$profile = $hr->get_profile_by_user_id($user_id);
			}
		}
		if ($report['errors']) { return $report; }
		$old_position_slug = $this->sn_hr_position_slug_by_id((int) $profile->position_id);
		$new_position_id = ! empty($payload['position_id']) ? (int) $payload['position_id'] : (int) $profile->position_id;
		$new_level_id = ! empty($payload['level_id']) ? (int) $payload['level_id'] : (int) $profile->level_id;
		$new_position_slug = $this->sn_hr_position_slug_by_id($new_position_id);
		if ($new_position_id && $new_position_slug === '') { $report['errors'][] = 'position_not_found'; }
		if (! empty($payload['level_id']) && $this->sn_hr_level_slug_by_id($new_level_id) === '') { $report['errors'][] = 'level_not_found'; }
		$current_manager_user_id = $hierarchy->get_current_parent_user_id($user_id);
		$has_manager_update = array_key_exists('manager_user_id', $payload);
		$manager_user_id = $has_manager_update ? (int) ($payload['manager_user_id'] ?? 0) : $current_manager_user_id;
		if ($has_manager_update && $manager_user_id > 0) {
			$manager_profile = $hr->get_profile_by_user_id($manager_user_id);
			if ($manager_user_id === $user_id) {
				$report['errors'][] = 'self_manager_not_allowed';
			} elseif (! $manager_profile) {
				$report['errors'][] = 'manager_profile_missing';
			} else {
				$manager_position_slug = $this->sn_hr_position_slug_by_id((int) $manager_profile->position_id);
				if ((int) $manager_profile->is_active !== 1) { $report['errors'][] = 'manager_inactive'; }
				if (! $this->sn_hr_manager_allowed_for_child($new_position_slug, $manager_position_slug)) { $report['errors'][] = 'manager_position_not_allowed'; }
			}
		}
		$has_fixed_salary_toggle = array_key_exists('fixed_salary_enabled', $payload);
		$has_base_salary = array_key_exists('base_salary', $payload) && $payload['base_salary'] !== null;
		$has_commission_enabled = array_key_exists('commission_enabled', $payload) && $payload['commission_enabled'] !== null;
		$has_commission_override_mode = array_key_exists('commission_override_mode', $payload) && (string) $payload['commission_override_mode'] !== '';
		$has_default_rule = array_key_exists('default_commission_rule_id', $payload) && $payload['default_commission_rule_id'] !== null;
		$comp_touched = $has_fixed_salary_toggle || $has_base_salary || $has_commission_enabled || $has_commission_override_mode || $has_default_rule;
		if ($comp_touched && ! preg_match('/^\d{4}-\d{2}-\d{2}$/', (string) ($payload['effective_from'] ?? ''))) {
			$report['errors'][] = 'effective_from_required';
		}
		if ($report['errors']) { return $report; }

		if ($new_position_id !== (int) $profile->position_id || $new_level_id !== (int) $profile->level_id) {
			$report['messages'][] = 'سمت/سطح تغییر می‌کند';
			if (! $dry_run) {
				$ok = $hr->update_profile_position_level($user_id, $new_position_id, $new_level_id, get_current_user_id());
				if ($ok) {
					$report['changed'] = true;
					if ($new_position_slug !== $old_position_slug) {
						$this->sn_hr_apply_user_access_for_position($user_id, $new_position_slug);
					}
				} else { $report['errors'][] = 'position_level_update_failed'; }
				$profile = $hr->get_profile_by_user_id($user_id);
			}
		}
		$meta = [];
		foreach (['employment_status','employment_type'] as $field) {
			if (isset($payload[$field]) && $payload[$field] !== '' && (string) ($profile->{$field} ?? '') !== (string) $payload[$field]) { $meta[$field] = $payload[$field]; }
		}
		if (array_key_exists('is_active', $payload) && $payload['is_active'] !== null && (int) $payload['is_active'] !== (int) $profile->is_active) { $meta['is_active'] = (int) $payload['is_active']; }
		if ($meta) {
			$report['messages'][] = 'اطلاعات همکاری تغییر می‌کند';
			if (! $dry_run) {
				$old_meta = [];
				foreach ($meta as $k => $v) { $old_meta[$k] = $profile->{$k} ?? null; }
				$meta['updated_at'] = current_time('mysql');
				$wpdb->update($profiles_table, $this->sn_filter_existing_columns($profiles_table, $meta), ['id' => (int) $profile->id]);
				$this->sn_hr_panel_log_profile((int) $profile->id, $user_id, 'hr_workforce_inline_profile_updated', $old_meta, $meta, ['source' => $source, 'reason' => $payload['reason'] ?? '']);
				$report['changed'] = true;
				$profile = $hr->get_profile_by_user_id($user_id);
			}
		}
		if ($has_manager_update && $manager_user_id !== $current_manager_user_id) {
			if ($source === 'hr_bulk_manager' && $current_manager_user_id && empty($payload['overwrite_manager'])) {
				$report['messages'][] = 'مدیر فعلی حفظ شد؛ گزینه جایگزینی فعال نبود';
				return $report;
			}
			$report['messages'][] = 'نیروی بالادستی تغییر می‌کند';
			if (! $dry_run) {
				if ($manager_user_id > 0) {
					$parent = $hr->get_profile_by_user_id($manager_user_id);
					$result = $parent ? $hierarchy->assign_parent((int) $profile->id, (int) $parent->id, get_current_user_id(), $source, (string) ($payload['reason'] ?? '')) : ['success' => false, 'message' => 'manager_profile_missing'];
					if (! empty($result['success'])) { $report['changed'] = true; } else { $report['errors'][] = (string) ($result['message'] ?? 'assignment_failed'); }
				} else {
					$ended = $hierarchy->end_current_assignment((int) $profile->id, get_current_user_id(), (string) ($payload['reason'] ?? ''));
					if ($ended) { $report['changed'] = true; }
				}
			}
		}

			if (array_key_exists('manual_invoice_access', $payload) && $payload['manual_invoice_access'] !== null) {
			$new_access = sanitize_key((string) $payload['manual_invoice_access']);
			if (! in_array($new_access, ['inherit','allow','deny'], true)) { $new_access = 'inherit'; }
			$old_access = $this->sn_manual_invoice_access_mode($user_id);
			if ($new_access !== $old_access) {
				$report['messages'][] = 'دسترسی صدور دستی پیش‌فاکتور تغییر می‌کند';
				if (! $dry_run) {
					if ($new_access === 'inherit') { delete_user_meta($user_id, 'sn_manual_invoice_access'); }
					else { update_user_meta($user_id, 'sn_manual_invoice_access', $new_access); }
					if ($this->sn_manual_invoice_access_mode($user_id) !== $new_access) {
						$report['errors'][] = 'ذخیره مجوز صدور دستی پیش‌فاکتور انجام نشد.';
					} else {
						$this->sn_hr_panel_log_profile((int) $profile->id, $user_id, 'manual_invoice_access_updated', ['mode'=>$old_access], ['mode'=>$new_access], ['source'=>$source]);
						$report['changed'] = true;
					}
					}
				}
			}
			if (array_key_exists('extra_number_request_access', $payload) && $payload['extra_number_request_access'] !== null) {
				$new_extra_access = sanitize_key((string) $payload['extra_number_request_access']);
				if (! in_array($new_extra_access, ['inherit','allow','deny'], true)) { $new_extra_access = 'inherit'; }
				$old_extra_access = $this->sn_extra_number_request_access_mode($user_id);
				if ($new_extra_access !== $old_extra_access) {
					$report['messages'][] = 'دسترسی درخواست شماره تغییر می‌کند';
					if (! $dry_run) {
						if ($new_extra_access === 'inherit') { delete_user_meta($user_id, 'sn_extra_number_request_access'); }
						else { update_user_meta($user_id, 'sn_extra_number_request_access', $new_extra_access); }
						$this->sn_hr_panel_log_profile((int) $profile->id, $user_id, 'extra_number_request_access_updated', ['mode'=>$old_extra_access], ['mode'=>$new_extra_access], ['source'=>$source]);
						$report['changed'] = true;
					}
				}
			}
			if (array_key_exists('team_invoice_source_mode', $payload) && $payload['team_invoice_source_mode'] !== null) {
				$new_source_mode = sanitize_key((string) $payload['team_invoice_source_mode']);
				if (! in_array($new_source_mode, ['manual','mis_only'], true)) { $new_source_mode = 'manual'; }
				$supervisor_positions = ['supervisor','senior_supervisor','operations_sales_supervisor'];
				if (in_array($new_position_slug ?: $old_position_slug, $supervisor_positions, true)) {
					$old_source_mode = $this->sn_team_invoice_source_mode($user_id);
					if ($new_source_mode !== $old_source_mode) {
						$report['messages'][] = 'سیاست منبع صدور پیش‌فاکتور تیم تغییر می‌کند';
						if (! $dry_run) {
							update_user_meta($user_id, 'sn_team_invoice_source_mode', $new_source_mode);
							$this->sn_hr_panel_log_profile((int) $profile->id, $user_id, 'team_invoice_source_mode_updated', ['mode'=>$old_source_mode], ['mode'=>$new_source_mode], ['source'=>$source]);
							$report['changed'] = true;
						}
					}
				}
			}
			if ($comp_touched) {
			$current_comp = $this->sn_hr_compensation_for_profile((int) $profile->id);
			$commission_override_mode = $has_commission_override_mode ? $this->sn_commission_normalize_override_mode((string) $payload['commission_override_mode']) : $this->sn_commission_normalize_override_mode((string) ($current_comp->commission_override_mode ?? 'inherit'));
			$commission_enabled = $commission_override_mode === 'disabled' ? 0 : ($has_commission_enabled ? (int) $payload['commission_enabled'] : 1);
			$default_rule_id = $has_default_rule ? ((int) $payload['default_commission_rule_id'] ?: null) : ((int) ($current_comp->default_commission_rule_id ?? 0) ?: null);
			if ($commission_override_mode !== 'manual_rule') { $default_rule_id = null; }
			$employment_status = (string) (($payload['employment_status'] ?? '') ?: ($profile->employment_status ?? 'active'));
			$employment_type = (string) (($payload['employment_type'] ?? '') ?: ($profile->employment_type ?? ''));
			$comp = $this->sn_hr_apply_compensation_history_update((int) $profile->id, $user_id, [
				'base_salary' => ! empty($payload['fixed_salary_enabled']) ? (int) ($payload['base_salary'] ?? 0) : null,
				'salary_currency' => 'IRT',
				'commission_enabled' => $commission_enabled,
				'commission_rule_id' => $default_rule_id,
				'commission_override_mode' => $commission_override_mode,
				'effective_from' => (string) ($payload['effective_from'] ?? ''),
				'employment_status' => $employment_status,
				'employment_type' => $employment_type,
				'position_slug_snapshot' => $new_position_slug ?: $old_position_slug,
				'level_slug_snapshot' => $this->sn_hr_level_slug_by_id($new_level_id),
				'notes' => (string) ($payload['reason'] ?? ''),
			], $dry_run, $source);
			$report['messages'] = array_merge($report['messages'], (array) ($comp['messages'] ?? []));
			$report['errors'] = array_merge($report['errors'], (array) ($comp['errors'] ?? []));
			if (! empty($comp['changed'])) { $report['changed'] = true; }
		}
		return $report;
	}

	private function sn_hr_apply_compensation_history_update(int $profile_id, int $user_id, array $data, bool $dry_run, string $source): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_history';
		$report = ['changed' => false, 'errors' => [], 'messages' => []];
		if (! $this->sn_table_exists_quiet($table)) { $report['errors'][] = 'compensation_history_table_missing'; return $report; }
		$effective_from = (string) ($data['effective_from'] ?? '');
		if (! preg_match('/^\d{4}-\d{2}-\d{2}$/', $effective_from)) { $report['errors'][] = 'effective_from_invalid'; return $report; }
		$same = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE user_id=%d AND is_active=1 AND effective_from=%s ORDER BY id DESC LIMIT 1", $user_id, $effective_from), ARRAY_A);
		$payload = [
			'profile_id' => $profile_id,
			'user_id' => $user_id,
			'base_salary' => $data['base_salary'],
			'salary_currency' => $data['salary_currency'] ?: 'IRT',
			'commission_enabled' => (int) ($data['commission_enabled'] ?? 1),
			'commission_rule_id' => $data['commission_rule_id'] ?: null,
			'commission_override_mode' => $this->sn_commission_normalize_override_mode((string) ($data['commission_override_mode'] ?? 'inherit')),
			'effective_from' => $effective_from,
			'effective_to' => null,
			'employment_status' => $data['employment_status'] ?: 'active',
			'employment_type' => $data['employment_type'] ?: null,
			'position_slug_snapshot' => $data['position_slug_snapshot'] ?: null,
			'level_slug_snapshot' => $data['level_slug_snapshot'] ?: null,
			'notes' => $data['notes'] ?: null,
			'is_active' => 1,
			'updated_by' => get_current_user_id() ?: null,
			'updated_at' => current_time('mysql'),
			'change_reason' => $source,
		];
		if ($same) {
			if (! empty($same['locked_after_payroll'])) { $report['errors'][] = 'locked_history_row'; return $report; }
			$report['messages'][] = 'بازه هم‌تاریخ بروزرسانی می‌شود';
			if (! $dry_run) {
				$history_updated = $wpdb->update($table, $this->sn_filter_existing_columns($table, $payload), ['id' => (int) $same['id']]);
				if ($history_updated === false) { $report['errors'][] = 'history_update_failed'; return $report; }
				$profile_result = $this->sn_hr_compensation_update($profile_id, $user_id, [
					'base_salary' => $payload['base_salary'],
					'salary_currency' => $payload['salary_currency'],
					'commission_enabled' => $payload['commission_enabled'],
					'default_commission_rule_id' => $payload['commission_rule_id'],
					'commission_override_mode' => $payload['commission_override_mode'],
					'effective_from' => $payload['effective_from'],
					'effective_to' => null,
					'notes' => $payload['notes'],
					'is_active' => 1,
				], $source);
				if (! empty($profile_result['error'])) { $report['errors'][] = (string) $profile_result['error']; return $report; }
				$this->sn_hr_panel_log_profile($profile_id, $user_id, 'hr_compensation_history_updated', $same, $payload, ['source' => $source]);
				$report['changed'] = true;
			}
			return $report;
		}
		$open = $wpdb->get_row($wpdb->prepare(
			"SELECT * FROM {$table} WHERE user_id=%d AND is_active=1 AND effective_from < %s AND (effective_to IS NULL OR effective_to >= %s) ORDER BY effective_from DESC, id DESC LIMIT 1",
			$user_id,
			$effective_from,
			$effective_from
		), ARRAY_A);
		$overlap_count = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$table} WHERE user_id=%d AND is_active=1 AND effective_from <= %s AND (effective_to IS NULL OR effective_to >= %s)",
			$user_id,
			'9999-12-31',
			$effective_from
		));
		if ($overlap_count > ($open ? 1 : 0)) { $report['errors'][] = 'overlapping_history_period'; return $report; }
		$report['messages'][] = 'بازه جدید تاریخچه حقوق/پورسانت ساخته می‌شود';
		if (! $dry_run) {
			if ($open) {
				if (! empty($open['locked_after_payroll'])) { $report['errors'][] = 'locked_history_row'; return $report; }
				$closed = $wpdb->update($table, ['effective_to' => (new DateTimeImmutable($effective_from, new DateTimeZone('UTC')))->modify('-1 day')->format('Y-m-d'), 'updated_by' => get_current_user_id() ?: null, 'updated_at' => current_time('mysql'), 'change_reason' => $source], ['id' => (int) $open['id']]);
				if ($closed === false) { $report['errors'][] = 'history_close_failed'; return $report; }
			}
			$payload['created_by'] = get_current_user_id() ?: null;
			$payload['created_at'] = current_time('mysql');
			$history_inserted = $wpdb->insert($table, $this->sn_filter_existing_columns($table, $payload));
			if ($history_inserted === false || ! $wpdb->insert_id) { $report['errors'][] = 'history_insert_failed'; return $report; }
			$profile_result = $this->sn_hr_compensation_update($profile_id, $user_id, [
				'base_salary' => $payload['base_salary'],
				'salary_currency' => $payload['salary_currency'],
				'commission_enabled' => $payload['commission_enabled'],
				'default_commission_rule_id' => $payload['commission_rule_id'],
				'commission_override_mode' => $payload['commission_override_mode'],
				'effective_from' => $payload['effective_from'],
				'effective_to' => null,
				'notes' => $payload['notes'],
				'is_active' => 1,
			], $source);
			if (! empty($profile_result['error'])) { $report['errors'][] = (string) $profile_result['error']; return $report; }
			$this->sn_hr_panel_log_profile($profile_id, $user_id, 'hr_compensation_history_created', $open, $payload, ['source' => $source]);
			$report['changed'] = true;
		}
		return $report;
	}

	public function handle_hr_compensation_timeline_action(): void
	{
		if (! $this->sn_can_manage_hr_panel()) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_hr_compensation_timeline_action');
		if (class_exists('SN_Migration_Service')) {
			(new SN_Migration_Service())->migrate_if_needed();
		}
		$redirect_base = $this->sn_hr_panel_return_url();
		global $wpdb;
		$table = $wpdb->prefix . 'sn_hr_compensation_history';
		$report = ['status' => 'error', 'message' => 'ثبت بازه انجام نشد.', 'errors' => [], 'updated_at' => current_time('mysql')];
		if (! class_exists('SN_HR_Service') || ! $this->sn_table_exists_quiet($table)) {
			$report['errors'][] = 'table_or_service_missing';
			update_option('sn_hr_compensation_timeline_report', $report, false);
			wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_error', $redirect_base) . '#hr-compensation');
			exit;
		}
		$confirm = strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? '')));
		$user_id = absint($_POST['user_id'] ?? 0);
		$effective_from = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['effective_from'] ?? '')));
		$effective_to = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['effective_to'] ?? '')));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$profile = (new SN_HR_Service())->get_profile_by_user_id($user_id);
		if ($confirm !== 'APPLY') { $report['errors'][] = 'confirm_apply_required'; }
		if (! $profile) { $report['errors'][] = 'profile_missing'; }
		if (! preg_match('/^\d{4}-\d{2}-\d{2}$/', $effective_from)) { $report['errors'][] = 'effective_from_invalid'; }
		if ($effective_to !== '' && ! preg_match('/^\d{4}-\d{2}-\d{2}$/', $effective_to)) { $report['errors'][] = 'effective_to_invalid'; }
		if ($effective_to !== '' && $effective_from !== '' && $effective_to < $effective_from) { $report['errors'][] = 'effective_to_before_from'; }
		if ($reason === '') { $report['errors'][] = 'reason_required'; }
		if (! empty($report['errors'])) {
			update_option('sn_hr_compensation_timeline_report', $report, false);
			wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_error', $redirect_base) . '#hr-compensation');
			exit;
		}

		$profile_id = (int) $profile->id;
		$open_rows = $wpdb->get_results($wpdb->prepare(
			"SELECT * FROM {$table} WHERE user_id=%d AND is_active=1 AND effective_from < %s AND (effective_to IS NULL OR effective_to >= %s) ORDER BY effective_from DESC, id DESC",
			$user_id,
			$effective_from,
			$effective_from
		), ARRAY_A) ?: [];
		$closed_previous = 0;
		if (count($open_rows) > 1) {
			$report['errors'][] = 'multiple_overlapping_history_rows';
			update_option('sn_hr_compensation_timeline_report', $report, false);
			wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_error', $redirect_base) . '#hr-compensation');
			exit;
		}
		if ($open_rows) {
			$previous_end = (new DateTimeImmutable($effective_from, new DateTimeZone('UTC')))->modify('-1 day')->format('Y-m-d');
			$wpdb->update($table, ['effective_to' => $previous_end, 'updated_by' => get_current_user_id() ?: null, 'updated_at' => current_time('mysql'), 'change_reason' => trim($reason . "\nAuto-closed by new compensation period")], ['id' => (int) $open_rows[0]['id']]);
			$closed_previous = 1;
		}
		$overlap_sql = "SELECT COUNT(*) FROM {$table} WHERE user_id=%d AND is_active=1 AND effective_from <= %s AND (effective_to IS NULL OR effective_to >= %s)";
		$overlap_to = $effective_to !== '' ? $effective_to : '9999-12-31';
		$remaining_overlap = (int) $wpdb->get_var($wpdb->prepare($overlap_sql, $user_id, $overlap_to, $effective_from));
		if ($remaining_overlap > 0) {
			$report['errors'][] = 'overlapping_history_period';
			update_option('sn_hr_compensation_timeline_report', $report, false);
			wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_error', $redirect_base) . '#hr-compensation');
			exit;
		}
		$commission_override_mode = $this->sn_commission_normalize_override_mode(sanitize_text_field(wp_unslash($_POST['commission_override_mode'] ?? 'inherit')));
		$commission_rule_id = absint($_POST['commission_rule_id'] ?? 0) ?: null;
		if ($commission_override_mode !== 'manual_rule') { $commission_rule_id = null; }
		$payload = [
			'profile_id' => $profile_id,
			'user_id' => $user_id,
			'base_salary' => ($_POST['base_salary'] ?? '') === '' ? null : absint($_POST['base_salary']),
			'salary_currency' => in_array((string) ($_POST['salary_currency'] ?? ''), ['IRT', 'IRR'], true) ? (string) $_POST['salary_currency'] : 'IRT',
			'commission_enabled' => $commission_override_mode === 'disabled' ? 0 : 1,
			'commission_rule_id' => $commission_rule_id,
			'commission_override_mode' => $commission_override_mode,
			'effective_from' => $effective_from,
			'effective_to' => $effective_to !== '' ? $effective_to : null,
			'employment_type' => sanitize_key(wp_unslash($_POST['employment_type'] ?? '')) ?: ($profile->employment_type ?? null),
			'employment_status' => sanitize_key(wp_unslash($_POST['employment_status'] ?? '')) ?: ($profile->employment_status ?? 'active'),
			'position_slug_snapshot' => $this->sn_hr_position_slug_by_id((int) $profile->position_id),
			'level_slug_snapshot' => $this->sn_hr_level_slug_by_id((int) $profile->level_id),
			'notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
			'is_active' => 1,
			'locked_after_payroll' => 0,
			'created_by' => get_current_user_id() ?: null,
			'updated_by' => get_current_user_id() ?: null,
			'change_reason' => $reason,
			'created_at' => current_time('mysql'),
			'updated_at' => current_time('mysql'),
		];
		$inserted = $wpdb->insert($table, $this->sn_filter_existing_columns($table, $payload));
		if (! $inserted) {
			$report['errors'][] = sanitize_text_field((string) $wpdb->last_error);
			update_option('sn_hr_compensation_timeline_report', $report, false);
			wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_error', $redirect_base) . '#hr-compensation');
			exit;
		}
		if ($effective_to === '' || $effective_to >= SN_Helpers::tehran_today_gregorian()) {
			$this->sn_hr_compensation_update($profile_id, $user_id, [
				'base_salary' => $payload['base_salary'],
				'salary_currency' => $payload['salary_currency'],
				'commission_enabled' => $payload['commission_enabled'],
				'default_commission_rule_id' => $payload['commission_rule_id'],
				'commission_override_mode' => $payload['commission_override_mode'],
				'effective_from' => $payload['effective_from'],
				'effective_to' => $payload['effective_to'],
				'notes' => $payload['notes'],
				'is_active' => 1,
			], $reason ?: 'HR compensation timeline current profile sync');
		}
		$this->sn_hr_panel_log_profile($profile_id, $user_id, 'hr_compensation_history_created', $open_rows ? $open_rows[0] : null, $payload, ['reason' => $reason, 'closed_previous' => $closed_previous]);
		update_option('sn_hr_compensation_timeline_report', [
			'status' => 'ok',
			'message' => 'بازه تاریخی حقوق و پورسانت ثبت شد.',
			'user_id' => $user_id,
			'history_id' => (int) $wpdb->insert_id,
			'closed_previous' => $closed_previous,
			'updated_at' => current_time('mysql'),
		], false);
		wp_safe_redirect(add_query_arg('sn_msg', 'hr_compensation_timeline_saved', $redirect_base) . '#hr-compensation');
		exit;
	}

	public function handle_after_sales_create_case(): void
	{
		if (! $this->sn_can_access_after_sales_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_after_sales_create_case');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate(); }
		if (! $this->sn_after_sales_tables_ready()) { $this->sn_after_sales_redirect(); }
		global $wpdb;
		$case_table = $wpdb->prefix . 'sn_after_sales_cases';
		$invoice_code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
		$lead_id = absint($_POST['lead_id'] ?? 0);
		$customer_name = sanitize_text_field(wp_unslash($_POST['customer_name'] ?? ''));
		$customer_phone = sanitize_text_field(wp_unslash($_POST['customer_phone'] ?? ''));
		$seller_user_id = absint($_POST['seller_user_id'] ?? 0);
		$assigned_user_id = absint($_POST['assigned_after_sales_user_id'] ?? 0);
		$case_type = sanitize_key(wp_unslash($_POST['case_type'] ?? 'other'));
		$priority = sanitize_key(wp_unslash($_POST['priority'] ?? 'normal'));
		$due_at_raw = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['due_at'] ?? '')));
		$notes = sanitize_textarea_field(wp_unslash($_POST['notes'] ?? ''));
		$invoice_id = 0;

		if ($invoice_code !== '') {
			$invoice_table = $wpdb->prefix . 'sn_invoices';
			if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $invoice_table)) === $invoice_table) {
				$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE invoice_code=%s LIMIT 1", $invoice_code), ARRAY_A);
				if ($invoice) {
					$invoice_id = (int) ($invoice['id'] ?? 0);
					$lead_id = $lead_id ?: (int) ($invoice['lead_id'] ?? 0);
					$customer_name = $customer_name !== '' ? $customer_name : (string) ($invoice['customer_name'] ?? '');
					$customer_phone = $customer_phone !== '' ? $customer_phone : (string) ($invoice['customer_phone'] ?? '');
					$seller_user_id = $seller_user_id ?: (int) ($invoice['seller_id'] ?? 0);
				}
			}
		}
		if ($lead_id && ($customer_phone === '' || $customer_name === '' || ! $seller_user_id)) {
			$lead_table = $wpdb->prefix . 'sn_leads';
			if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $lead_table)) === $lead_table) {
				$lead = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$lead_table} WHERE id=%d LIMIT 1", $lead_id), ARRAY_A);
				if ($lead) {
					$customer_phone = $customer_phone !== '' ? $customer_phone : (string) ($lead['phone'] ?? '');
					$customer_name = $customer_name !== '' ? $customer_name : (string) ($lead['customer_name'] ?? '');
					$seller_user_id = $seller_user_id ?: (int) ($lead['seller_id'] ?? 0);
				}
			}
		}
		if ($customer_phone === '' && $invoice_code === '' && ! $lead_id) {
			update_option('sn_after_sales_action_report', ['action' => 'case_create', 'success' => false, 'message' => 'customer_or_invoice_required', 'updated_at' => current_time('mysql')], false);
			$this->sn_after_sales_redirect();
		}
		$now = current_time('mysql');
		$data = $this->sn_filter_existing_columns($case_table, [
			'case_code' => $this->sn_after_sales_generate_case_code(),
			'invoice_id' => $invoice_id ?: null,
			'invoice_code' => $invoice_code ?: null,
			'lead_id' => $lead_id ?: null,
			'customer_name' => $customer_name ?: null,
			'customer_phone' => $customer_phone ?: null,
			'normalized_phone' => $customer_phone !== '' ? SN_Helpers::normalize_mobile($customer_phone) : null,
			'seller_user_id' => $seller_user_id ?: null,
			'assigned_after_sales_user_id' => $assigned_user_id ?: (get_current_user_id() ?: null),
			'case_type' => array_key_exists($case_type, $this->sn_after_sales_case_types()) ? $case_type : 'other',
			'case_status' => 'open',
			'priority' => array_key_exists($priority, $this->sn_after_sales_priorities()) ? $priority : 'normal',
			'source' => $invoice_id ? 'invoice' : 'manual',
			'opened_at' => $now,
			'due_at' => preg_match('/^\d{4}-\d{2}-\d{2}$/', $due_at_raw) ? $due_at_raw . ' 23:59:59' : null,
			'created_by' => get_current_user_id() ?: null,
			'created_at' => $now,
			'updated_at' => $now,
			'notes' => $notes ?: null,
		]);
		$ok = (bool) $wpdb->insert($case_table, $data);
		$case_id = $ok ? (int) $wpdb->insert_id : 0;
		if ($case_id) {
			$this->sn_after_sales_log($case_id, 'case_created', null, $data, $notes);
		}
		update_option('sn_after_sales_action_report', ['action' => 'case_create', 'success' => $ok, 'case_id' => $case_id, 'case_code' => $data['case_code'] ?? '', 'mysql_error' => $ok ? '' : sanitize_text_field($wpdb->last_error), 'updated_at' => $now], false);
		$this->sn_after_sales_redirect();
	}

	public function handle_after_sales_update_case(): void
	{
		if (! $this->sn_can_access_after_sales_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_after_sales_update_case');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->migrate(); }
		if (! $this->sn_after_sales_tables_ready()) { $this->sn_after_sales_redirect(); }
		global $wpdb;
		$table = $wpdb->prefix . 'sn_after_sales_cases';
		$case_id = absint($_POST['case_id'] ?? 0);
		$old = $case_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d LIMIT 1", $case_id), ARRAY_A) : null;
		if (! $old) {
			update_option('sn_after_sales_action_report', ['action' => 'case_update', 'success' => false, 'message' => 'case_not_found', 'updated_at' => current_time('mysql')], false);
			$this->sn_after_sales_redirect();
		}
		$status = sanitize_key(wp_unslash($_POST['case_status'] ?? $old['case_status']));
		$priority = sanitize_key(wp_unslash($_POST['priority'] ?? $old['priority']));
		$assigned_user_id = absint($_POST['assigned_after_sales_user_id'] ?? 0);
		$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
		$statuses = $this->sn_after_sales_statuses();
		$priorities = $this->sn_after_sales_priorities();
		$status = array_key_exists($status, $statuses) ? $status : (string) $old['case_status'];
		$priority = array_key_exists($priority, $priorities) ? $priority : (string) $old['priority'];
		$now = current_time('mysql');
		$data = [
			'case_status' => $status,
			'priority' => $priority,
			'assigned_after_sales_user_id' => $assigned_user_id ?: null,
			'updated_at' => $now,
		];
		if (in_array($status, ['resolved', 'closed'], true) && empty($old['resolved_at'])) {
			$data['resolved_at'] = $now;
		}
		if (! in_array($status, ['resolved', 'closed'], true)) {
			$data['resolved_at'] = null;
		}
		$data = $this->sn_filter_existing_columns($table, $data);
		$ok = false !== $wpdb->update($table, $data, ['id' => $case_id]);
		if ($ok) {
			$this->sn_after_sales_log($case_id, 'case_updated', [
				'case_status' => $old['case_status'] ?? '',
				'priority' => $old['priority'] ?? '',
				'assigned_after_sales_user_id' => (int) ($old['assigned_after_sales_user_id'] ?? 0),
			], $data, $note);
			if ($note !== '') {
				$this->sn_after_sales_log($case_id, 'note_added', null, null, $note);
			}
		}
		update_option('sn_after_sales_action_report', ['action' => 'case_update', 'success' => $ok, 'case_id' => $case_id, 'mysql_error' => $ok ? '' : sanitize_text_field($wpdb->last_error), 'updated_at' => $now], false);
		$this->sn_after_sales_redirect();
	}

	private function sn_mis_batch_delete_audit(int $batch_id): array
	{
		global $wpdb;
		$report = [
			'batch_id' => $batch_id,
			'rows' => 0,
			'pool_rows' => 0,
			'distribution_items' => 0,
			'distribution_item_logs' => 0,
			'plans' => 0,
			'plan_items' => 0,
			'locked_items' => 0,
			'locked_plan_items' => 0,
			'locked_reason' => [],
		];
		if ($batch_id < 1) { return $report; }
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$item_logs = $wpdb->prefix . 'sn_distribution_item_logs';
		$plans = $wpdb->prefix . 'sn_mis_distribution_plans';
		$plan_items = $wpdb->prefix . 'sn_mis_distribution_plan_items';
		if ($this->sn_table_exists_quiet($rows)) {
			$report['rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows} WHERE batch_id=%d", $batch_id));
		}
		if ($this->sn_table_exists_quiet($pool)) {
			$report['pool_rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$pool} WHERE batch_id=%d", $batch_id));
		}
		$dist_where = "(di.batch_id=%d";
		$dist_args = [$batch_id];
		if ($this->sn_table_exists_quiet($rows)) {
			$dist_where .= " OR (di.source_type='mis_data_row' AND di.source_id IN (SELECT id FROM {$rows} WHERE batch_id=%d))";
			$dist_args[] = $batch_id;
		}
		if ($this->sn_table_exists_quiet($pool)) {
			$dist_where .= " OR di.pool_item_id IN (SELECT id FROM {$pool} WHERE batch_id=%d) OR (di.source_type='mis_pool' AND di.source_id IN (SELECT id FROM {$pool} WHERE batch_id=%d))";
			$dist_args[] = $batch_id;
			$dist_args[] = $batch_id;
		}
		$dist_where .= ')';
		$report['distribution_where_sql'] = $dist_where;
		if ($this->sn_table_exists_quiet($items)) {
			$report['distribution_items'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$items} di WHERE {$dist_where}", ...$dist_args));
			$locked_statuses = ['converted','lead_created','live_lead_created','invoiced','invoice_created','paid','approved'];
			$placeholders = implode(',', array_fill(0, count($locked_statuses), '%s'));
			$locked_args = array_merge($dist_args, $locked_statuses, $locked_statuses);
			$invoice_guard = $this->sn_table_has_column($items, 'follow_invoice_id') ? ' OR COALESCE(di.follow_invoice_id,0)>0' : '';
			$invoices = $wpdb->prefix . 'sn_invoices';
			if ($this->sn_table_exists_quiet($invoices)) {
				$invoice_guard .= " OR EXISTS (SELECT 1 FROM {$invoices} inv WHERE inv.lead_id=900000000+di.id)";
			}
			$report['locked_items'] = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT COUNT(*) FROM {$items} di WHERE {$dist_where} AND (COALESCE(di.live_lead_id,0)>0{$invoice_guard} OR COALESCE(di.conversion_status,'') IN ({$placeholders}) OR COALESCE(di.status,'') IN ({$placeholders}))",
				...$locked_args
			));
			if ($this->sn_table_exists_quiet($item_logs)) {
				$report['distribution_item_logs'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$item_logs} l INNER JOIN {$items} di ON di.id=l.item_id WHERE {$dist_where}", ...$dist_args));
			}
		}
		if ($this->sn_table_exists_quiet($plans)) {
			$report['plans'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$plans} WHERE batch_id=%d", $batch_id));
		}
		if ($this->sn_table_exists_quiet($plan_items)) {
			$where = [];
			$args = [];
			if ($this->sn_table_exists_quiet($plans)) { $where[] = "pi.plan_id IN (SELECT id FROM {$plans} WHERE batch_id=%d)"; $args[] = $batch_id; }
			if ($this->sn_table_exists_quiet($rows)) { $where[] = "pi.source_row_id IN (SELECT id FROM {$rows} WHERE batch_id=%d)"; $args[] = $batch_id; }
			if ($this->sn_table_exists_quiet($pool)) { $where[] = "pi.pool_id IN (SELECT id FROM {$pool} WHERE batch_id=%d)"; $args[] = $batch_id; }
			if ($where) {
				$where_sql = '(' . implode(' OR ', $where) . ')';
				$report['plan_items'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$plan_items} pi WHERE {$where_sql}", ...$args));
				$report['locked_plan_items'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$plan_items} pi WHERE {$where_sql} AND COALESCE(pi.created_lead_id,0)>0", ...$args));
			}
		}
		if ((int) $report['locked_items'] > 0) { $report['locked_reason'][] = 'آیتم پخش به لید/پیش‌فاکتور/فاکتور وصل است یا وضعیت قفل‌شده دارد.'; }
		if ((int) $report['locked_plan_items'] > 0) { $report['locked_reason'][] = 'برنامه توزیع برای بعضی ردیف‌ها لید ساخته است.'; }
		return $report;
	}

	public function handle_mis_delete_batch_data(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_delete_batch_data');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$mode = sanitize_key(wp_unslash($_POST['delete_mode'] ?? 'file_only'));
		$confirm = strtoupper(trim(sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''))));
		$now = current_time('mysql');
		$report = ['action' => 'mis_delete_batch_data', 'batch_id' => $batch_id, 'mode' => $mode, 'success' => false, 'message' => '', 'errors' => [], 'deleted' => [], 'updated_at' => $now];
		if ($batch_id < 1) { $report['message'] = 'پرونده انتخاب نشده است.'; update_option('sn_mis_delete_batch_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$expected = $mode === 'full_batch' ? 'DELETE_BATCH' : 'DELETE_FILE';
		if ($confirm !== $expected) { $report['message'] = 'کلمه تأیید درست نیست. برای حذف فایل DELETE_FILE و برای حذف کامل پرونده DELETE_BATCH بنویس.'; update_option('sn_mis_delete_batch_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$batches = $wpdb->prefix . 'sn_mis_import_batches';
		if (! $this->sn_table_exists_quiet($batches)) { $report['message'] = 'جدول پرونده‌های MIS وجود ندارد.'; update_option('sn_mis_delete_batch_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$batch = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$batches} WHERE id=%d", $batch_id), ARRAY_A);
		if (! $batch) { $report['message'] = 'پرونده پیدا نشد.'; update_option('sn_mis_delete_batch_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$audit = $this->sn_mis_batch_delete_audit($batch_id);
		$report['audit_before'] = $audit;
		if ((int) ($audit['locked_items'] ?? 0) > 0 || (int) ($audit['locked_plan_items'] ?? 0) > 0) {
			$report['message'] = 'حذف متوقف شد؛ این پرونده ردیف قفل‌شده دارد. اول گزارش را بررسی کن. لید/فاکتور حذف نمی‌شود.';
			update_option('sn_mis_delete_batch_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$item_logs = $wpdb->prefix . 'sn_distribution_item_logs';
		$plans = $wpdb->prefix . 'sn_mis_distribution_plans';
		$plan_items = $wpdb->prefix . 'sn_mis_distribution_plan_items';
		try {
			foreach ([$rows, $pool, $items, $item_logs, $plans, $plan_items] as $required_table) {
				if (! $this->sn_table_exists_quiet($required_table)) { throw new RuntimeException('جدول موردنیاز حذف پرونده موجود نیست: ' . $required_table); }
			}
			if (false === $wpdb->query('START TRANSACTION')) { throw new RuntimeException('شروع تراکنش حذف پرونده ممکن نشد.'); }
			$locked_batch = $wpdb->get_row($wpdb->prepare("SELECT id FROM {$batches} WHERE id=%d FOR UPDATE", $batch_id));
			if (! $locked_batch) { throw new RuntimeException('پرونده پیش از حذف تغییر کرده است؛ صفحه را تازه کنید.'); }
			$run_delete = static function(string $sql, array $args = []) use ($wpdb): int {
				$result = $wpdb->query($args ? $wpdb->prepare($sql, ...$args) : $sql);
				if (false === $result) { throw new RuntimeException('خطای دیتابیس هنگام حذف: ' . ($wpdb->last_error ?: 'نامشخص')); }
				return (int) $result;
			};
			$delete_row = static function(string $table, array $where) use ($wpdb): int {
				$result = $wpdb->delete($table, $where);
				if (false === $result) { throw new RuntimeException('خطای دیتابیس هنگام حذف از ' . $table . ': ' . ($wpdb->last_error ?: 'نامشخص')); }
				return (int) $result;
			};
			$dist_where = "(di.batch_id=%d";
			$dist_args = [$batch_id];
			if ($this->sn_table_exists_quiet($rows)) { $dist_where .= " OR (di.source_type='mis_data_row' AND di.source_id IN (SELECT id FROM {$rows} WHERE batch_id=%d))"; $dist_args[] = $batch_id; }
			if ($this->sn_table_exists_quiet($pool)) { $dist_where .= " OR di.pool_item_id IN (SELECT id FROM {$pool} WHERE batch_id=%d) OR (di.source_type='mis_pool' AND di.source_id IN (SELECT id FROM {$pool} WHERE batch_id=%d))"; $dist_args[] = $batch_id; $dist_args[] = $batch_id; }
			$dist_where .= ')';
			$wpdb->get_col($wpdb->prepare("SELECT di.id FROM {$items} di WHERE {$dist_where} FOR UPDATE", ...$dist_args));
			if ($wpdb->last_error) { throw new RuntimeException('قفل‌کردن آیتم‌های پخش داده ممکن نشد: ' . $wpdb->last_error); }
			$report['audit_before'] = $this->sn_mis_batch_delete_audit($batch_id);
			if ((int) ($report['audit_before']['locked_items'] ?? 0) > 0 || (int) ($report['audit_before']['locked_plan_items'] ?? 0) > 0) {
				throw new RuntimeException('پرونده هم‌زمان به لید یا فاکتور متصل شده است؛ حذف متوقف شد.');
			}
			if ($this->sn_table_exists_quiet($items) && $this->sn_table_exists_quiet($item_logs)) {
				$report['deleted']['distribution_item_logs'] = $run_delete("DELETE l FROM {$item_logs} l INNER JOIN {$items} di ON di.id=l.item_id WHERE {$dist_where}", $dist_args);
			}
			if ($this->sn_table_exists_quiet($items)) {
				$report['deleted']['distribution_items'] = $run_delete("DELETE di FROM {$items} di WHERE {$dist_where}", $dist_args);
			}
			if ($this->sn_table_exists_quiet($plan_items)) {
				$where = [];
				$args = [];
				if ($this->sn_table_exists_quiet($plans)) { $where[] = "pi.plan_id IN (SELECT id FROM {$plans} WHERE batch_id=%d)"; $args[] = $batch_id; }
				if ($this->sn_table_exists_quiet($rows)) { $where[] = "pi.source_row_id IN (SELECT id FROM {$rows} WHERE batch_id=%d)"; $args[] = $batch_id; }
				if ($this->sn_table_exists_quiet($pool)) { $where[] = "pi.pool_id IN (SELECT id FROM {$pool} WHERE batch_id=%d)"; $args[] = $batch_id; }
				if ($where) { $report['deleted']['plan_items'] = $run_delete("DELETE pi FROM {$plan_items} pi WHERE (" . implode(' OR ', $where) . ")", $args); }
			}
			if ($this->sn_table_exists_quiet($plans)) { $report['deleted']['plans'] = $delete_row($plans, ['batch_id' => $batch_id]); }
			if ($this->sn_table_exists_quiet($pool)) { $report['deleted']['pool_rows'] = $delete_row($pool, ['batch_id' => $batch_id]); }
			if ($this->sn_table_exists_quiet($rows)) { $report['deleted']['data_rows'] = $delete_row($rows, ['batch_id' => $batch_id]); }
			// Phone numbers are shared across files; removing other batches by phone would erase unrelated work.
			if ($mode === 'full_batch') {
				$report['deleted']['batch'] = $delete_row($batches, ['id' => $batch_id]);
				if ($report['deleted']['batch'] !== 1) { throw new RuntimeException('پرونده از دیتابیس حذف نشد.'); }
			} else {
				$reset = [
					'import_file_name' => null,
					'import_status' => 'draft',
					'assigned_manager_user_id' => null,
					'total_rows' => 0,
					'valid_rows' => 0,
					'duplicate_rows' => 0,
					'invalid_rows' => 0,
					'updated_at' => $now,
				];
				$reset_result = $wpdb->update($batches, $this->sn_filter_existing_columns($batches, $reset), ['id' => $batch_id]);
				if (false === $reset_result) { throw new RuntimeException('ریست پرونده انجام نشد: ' . ($wpdb->last_error ?: 'خطای دیتابیس')); }
				$report['deleted']['batch_reset'] = (int) $reset_result;
			}
			$report['audit_after'] = $this->sn_mis_batch_delete_audit($batch_id);
			foreach (['rows', 'pool_rows', 'distribution_items', 'distribution_item_logs', 'plans', 'plan_items'] as $key) {
				if ((int) ($report['audit_after'][$key] ?? 0) > 0) { throw new RuntimeException('ردیف‌های پرونده به‌طور کامل حذف نشدند: ' . $key); }
			}
			if (false === $wpdb->query('COMMIT')) { throw new RuntimeException('ثبت نهایی حذف در دیتابیس انجام نشد.'); }
			$report['success'] = true;
			$report['message'] = $mode === 'full_batch' ? 'پرونده MIS و فایل/ردیف‌های امن آن حذف شد.' : 'فایل آپلودشده، ردیف‌ها و آیتم‌های امن این پرونده حذف شد؛ خود پرونده برای آپلود مجدد باقی ماند.';
			$this->sn_mis_log($batch_id, $mode === 'full_batch' ? 'mis_batch_deleted' : 'mis_batch_file_deleted', $batch, $report, 'delete/reset MIS uploaded data');
			update_option('sn_mis_last_report', $report, false);
		} catch (Throwable $e) {
			$db_error = sanitize_text_field((string) $wpdb->last_error);
			$wpdb->query('ROLLBACK');
			$report['message'] = 'حذف کامل نشد: ' . $e->getMessage();
			$report['errors'][] = $e->getMessage();
			$report['deleted'] = [];
			$report['mysql_error'] = $db_error;
		}
		if (! isset($report['mysql_error'])) { $report['mysql_error'] = sanitize_text_field((string) $wpdb->last_error); }
		$report['audit_after'] = $this->sn_mis_batch_delete_audit($batch_id);
		update_option('sn_mis_delete_batch_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_ui_active_tab' => 'mis-batches'], wp_get_referer() ?: home_url('/')) . '#mis-batches');
		exit;
	}


	public function handle_mis_cleanup_deleted_traces(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_cleanup_deleted_traces');
		global $wpdb;
		$confirm = strtoupper(trim(sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''))));
		$report = ['action' => 'mis_cleanup_deleted_traces', 'success' => false, 'message' => '', 'deleted' => [], 'updated_at' => current_time('mysql')];
		if ($confirm !== 'CLEAN_MIS') {
			$report['message'] = 'برای پاکسازی ردپا باید CLEAN_MIS بنویسی.';
			update_option('sn_mis_delete_batch_report', $report, false);
			wp_safe_redirect(add_query_arg(['sn_ui_active_tab' => 'mis-batches'], wp_get_referer() ?: home_url('/')) . '#mis-batches');
			exit;
		}
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$batches = $wpdb->prefix . 'sn_mis_import_batches';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$item_logs = $wpdb->prefix . 'sn_distribution_item_logs';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$plans = $wpdb->prefix . 'sn_mis_distribution_plans';
		$plan_items = $wpdb->prefix . 'sn_mis_distribution_plan_items';
		$locked = ['converted','lead_created','live_lead_created','invoiced','invoice_created','paid','approved'];
		$wpdb->query('START TRANSACTION');
		try {
			if ($this->sn_table_exists_quiet($items)) {
				$where = "COALESCE(di.live_lead_id,0)=0 AND COALESCE(di.status,'') IN ('returned_to_mis','duplicate','archived','cancelled','conversion_failed')";
				if ($this->sn_table_exists_quiet($item_logs)) {
					$deleted = $wpdb->query("DELETE l FROM {$item_logs} l INNER JOIN {$items} di ON di.id=l.item_id WHERE {$where}");
					$report['deleted']['distribution_item_logs'] = max(0, (int) $deleted);
				}
				$deleted = $wpdb->query("DELETE di FROM {$items} di WHERE {$where}");
				$report['deleted']['distribution_items_stale'] = max(0, (int) $deleted);
			}
			if ($this->sn_table_exists_quiet($plan_items) && $this->sn_table_exists_quiet($plans)) {
				$deleted = $wpdb->query("DELETE pi FROM {$plan_items} pi LEFT JOIN {$plans} p ON p.id=pi.plan_id WHERE p.id IS NULL OR COALESCE(pi.created_lead_id,0)=0");
				$report['deleted']['plan_items_stale'] = max(0, (int) $deleted);
			}
			if ($this->sn_table_exists_quiet($pool)) {
				$join = $this->sn_table_exists_quiet($batches) ? " LEFT JOIN {$batches} b ON b.id=p.batch_id" : "";
				$where = $this->sn_table_exists_quiet($batches) ? "b.id IS NULL OR COALESCE(b.import_status,'') IN ('draft','deleted','file_deleted','reset_deleted')" : "1=0";
				$deleted = $wpdb->query("DELETE p FROM {$pool} p {$join} WHERE {$where}");
				$report['deleted']['pool_orphan_or_reset'] = max(0, (int) $deleted);
			}
			if ($this->sn_table_exists_quiet($rows)) {
				$join = $this->sn_table_exists_quiet($batches) ? " LEFT JOIN {$batches} b ON b.id=r.batch_id" : "";
				$where = $this->sn_table_exists_quiet($batches) ? "r.row_status<>'valid' OR b.id IS NULL OR COALESCE(b.import_status,'') IN ('draft','deleted','file_deleted','reset_deleted')" : "r.row_status<>'valid'";
				$affected = $wpdb->get_col("SELECT DISTINCT r.batch_id FROM {$rows} r {$join} WHERE {$where}") ?: [];
				$deleted = $wpdb->query("DELETE r FROM {$rows} r {$join} WHERE {$where}");
				$report['deleted']['data_rows_stale_duplicate_or_reset'] = max(0, (int) $deleted);
				foreach ((array) $affected as $bid) { if ((int) $bid > 0) { $this->sn_mis_recount_batch_rows((int) $bid); } }
			}
			$wpdb->query('COMMIT');
			$report['success'] = true;
			$report['message'] = 'پاکسازی اضطراری ردپاهای حذف‌شده/تکراری MIS انجام شد.';
		} catch (Throwable $e) {
			$wpdb->query('ROLLBACK');
			$report['message'] = 'پاکسازی کامل نشد: ' . $e->getMessage();
			$report['error'] = $e->getMessage();
		}
		$report['mysql_error'] = sanitize_text_field((string) $wpdb->last_error);
		update_option('sn_mis_delete_batch_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_ui_active_tab' => 'mis-batches'], wp_get_referer() ?: home_url('/')) . '#mis-batches');
		exit;
	}

	public function handle_mis_create_batch(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_create_batch');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_import_batches')) { wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$code = $this->sn_mis_generate_batch_code();
		$data = [
			'batch_code' => $code,
			'title' => sanitize_text_field(wp_unslash($_POST['title'] ?? '')),
			'source_type' => sanitize_key(wp_unslash($_POST['source_type'] ?? '')),
			'source_label' => sanitize_text_field(wp_unslash($_POST['source_label'] ?? '')),
			'campaign_code' => sanitize_key(wp_unslash($_POST['campaign_code'] ?? '')),
			'data_category' => sanitize_key(wp_unslash($_POST['data_category'] ?? '')),
			'import_status' => 'draft',
			'created_by' => get_current_user_id(),
			'notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
		];
		$wpdb->insert($wpdb->prefix . 'sn_mis_import_batches', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_import_batches', $data));
		$batch_id = (int) $wpdb->insert_id;
		$this->sn_mis_log($batch_id, 'batch_created', null, $data, 'create draft batch');
		update_option('sn_mis_last_report', ['action' => 'batch_created', 'batch_id' => $batch_id, 'batch_code' => $code, 'updated_at' => current_time('mysql')], false);
		wp_safe_redirect(add_query_arg(['sn_msg' => 'mis_batch_created'], wp_get_referer() ?: home_url('/')));
		exit;
	}

	public function handle_repair_mis_schema(): void
	{
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_repair_mis_schema');
		if (class_exists('SN_Migration_Service')) {
			$service = new SN_Migration_Service();
			$service->repair_mis_schema();
			$service->migrate();
		}
		$this->sn_mis_clear_performance_cache();
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	public function handle_distribution_save_chain(): void
	{
		if (! $this->sn_can_manage_hr_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_distribution_save_chain');
		$this->sn_distribution_ensure_schema();
		global $wpdb;
		$now = current_time('mysql');
		$mode = sanitize_key(wp_unslash($_POST['distribution_save_mode'] ?? 'chain'));
		$report = ['action' => 'distribution_save_chain', 'mode' => $mode, 'saved' => false, 'errors' => [], 'updated_at' => $now];

		if ($mode === 'step') {
			$chain_id = absint($_POST['chain_id'] ?? 0);
			$step_id = absint($_POST['step_id'] ?? 0);
			$from = sanitize_key(wp_unslash($_POST['from_position_slug'] ?? ''));
			$to = sanitize_key(wp_unslash($_POST['to_position_slug'] ?? ''));
			$data = $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_chain_steps', [
				'chain_id' => $chain_id,
				'step_order' => max(1, absint($_POST['step_order'] ?? 10)),
				'from_position_slug' => $from,
				'to_position_slug' => $to,
				'allow_skip_if_missing' => ! empty($_POST['allow_skip_if_missing']) ? 1 : 0,
				'is_final_delivery_step' => ! empty($_POST['is_final_delivery_step']) ? 1 : 0,
				'creates_live_lead' => ! empty($_POST['creates_live_lead']) ? 1 : 0,
				'is_active' => ! empty($_POST['is_active']) ? 1 : 0,
				'updated_at' => $now,
			]);
			if (! $chain_id || $from === '' || $to === '') {
				$report['errors'][] = 'chain_or_position_missing';
			} elseif ($step_id) {
				$report['saved'] = $wpdb->update($wpdb->prefix . 'sn_distribution_chain_steps', $data, ['id' => $step_id]) !== false;
				$report['step_id'] = $step_id;
			} else {
				$data['created_at'] = $now;
				$report['saved'] = (bool) $wpdb->insert($wpdb->prefix . 'sn_distribution_chain_steps', $data);
				$report['step_id'] = (int) $wpdb->insert_id;
			}
		} else {
			$chain_id = absint($_POST['chain_id'] ?? 0);
			$chain_code = sanitize_key(wp_unslash($_POST['chain_code'] ?? ''));
			$data = $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_chains', [
				'chain_code' => $chain_code ?: 'custom_chain_' . SN_Helpers::tehran_format('YmdHis'),
				'title' => sanitize_text_field(wp_unslash($_POST['title'] ?? '')),
				'description' => sanitize_textarea_field(wp_unslash($_POST['description'] ?? '')),
				'is_active' => ! empty($_POST['is_active']) ? 1 : 0,
				'is_default' => ! empty($_POST['is_default']) ? 1 : 0,
				'updated_at' => $now,
			]);
			if (! empty($data['is_default'])) {
				$wpdb->update($wpdb->prefix . 'sn_distribution_chains', ['is_default' => 0], ['is_default' => 1]);
			}
			if ($chain_id) {
				$report['saved'] = $wpdb->update($wpdb->prefix . 'sn_distribution_chains', $data, ['id' => $chain_id]) !== false;
				$report['chain_id'] = $chain_id;
			} else {
				$data['created_at'] = $now;
				$report['saved'] = (bool) $wpdb->insert($wpdb->prefix . 'sn_distribution_chains', $data);
				$report['chain_id'] = (int) $wpdb->insert_id;
			}
		}
		if (! $report['saved'] && $wpdb->last_error) {
			$report['errors'][] = sanitize_text_field($wpdb->last_error);
		}
		update_option('sn_distribution_chain_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	public function handle_distribution_deliver_pool(): void
	{
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_distribution_deliver_pool');
		$this->sn_distribution_ensure_schema();
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$report = $run_mode === 'apply'
			? ['batch_id' => $batch_id, 'manager_user_id' => $manager_id, 'eligible' => 0, 'already_delivered' => 0, 'preview' => [], 'errors' => [], 'updated_at' => current_time('mysql'), 'preflight_report_skipped' => true]
			: $this->sn_distribution_delivery_report($batch_id, $manager_id, 20);
		$report['action'] = 'distribution_delivery_' . ($run_mode === 'apply' ? 'apply' : 'dry_run');
		$report['created'] = 0;
		$report['duplicate_blocked'] = (int) ($report['duplicate_blocked'] ?? 0);
		$report['duplicate_blocked_samples'] = (array) ($report['duplicate_blocked_samples'] ?? []);
		$report['errors'] = (array) ($report['errors'] ?? []);
		if ($run_mode === 'apply') {
			if ($confirm !== 'APPLY') {
				$report['errors'][] = 'confirmation_required';
			} elseif (! $this->sn_distribution_tables_ready()) {
				$report['errors'][] = 'distribution_tables_missing';
			} else {
				$wpdb->query('START TRANSACTION');
				$delivery_candidates = $this->sn_distribution_delivery_candidates($batch_id, $manager_id, 500);
				foreach ($delivery_candidates as $row) {
					$row->source_type = 'mis_pool';
					$row->source_id = (int) ($row->id ?? 0);
					$row->pool_item_id = (int) ($row->id ?? 0);
					$row->resolved_pool_id = (int) ($row->id ?? 0);
					$row->resolved_source_row_id = (int) ($row->source_row_id ?? 0);
				}
				$delivery_duplicate_guards = $this->sn_mis_duplicate_hard_guard_bulk($delivery_candidates);
				foreach ($delivery_candidates as $row) {
					$pool_id = (int) $row->id;
					$phone_for_guard = SN_Helpers::normalize_mobile((string) ($row->normalized_phone ?: $row->customer_phone));
					$guard = $delivery_duplicate_guards[$pool_id] ?? $this->sn_mis_duplicate_hard_guard($phone_for_guard, (int) ($row->source_row_id ?? 0), $pool_id, 0);
					if (! empty($guard['duplicate'])) {
						$report['duplicate_blocked']++;
						if (count($report['duplicate_blocked_samples']) < 20) {
							$report['duplicate_blocked_samples'][] = [
								'pool_id' => $pool_id,
								'phone' => $this->sn_mask_phone($phone_for_guard),
								'source' => (string) ($guard['source'] ?? ''),
								'message' => (string) ($guard['message'] ?? ''),
							];
						}
						continue;
					}
					$owner_id = (int) $row->assigned_manager_user_id;
					$owner_position = $this->sn_hr_position_for_user($owner_id) ?: 'sales_manager';
					$inserted = $wpdb->insert($wpdb->prefix . 'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_items', [
						'source_type' => 'mis_pool',
						'source_id' => $pool_id,
						'batch_id' => (int) $row->batch_id,
						'pool_item_id' => $pool_id,
						'current_owner_user_id' => $owner_id,
						'current_owner_position' => $owner_position,
						'current_step_order' => 0,
						'final_seller_user_id' => null,
						'live_lead_id' => null,
						'customer_phone' => (string) ($row->customer_phone ?? ''),
						'normalized_phone' => $phone_for_guard,
						'status' => 'assigned_to_role',
						'created_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
					]));
					if ($inserted) {
						$item_id = (int) $wpdb->insert_id;
						$report['created']++;
						$this->sn_distribution_log($item_id, 'item_created_from_mis_pool', get_current_user_id(), 0, $owner_id, '', $owner_position, 0, $reason, ['pool_id' => $pool_id, 'batch_id' => (int) $row->batch_id]);
					} elseif ($wpdb->last_error) {
						$report['errors'][] = sanitize_text_field($wpdb->last_error);
					}
				}
				$wpdb->query('COMMIT');
				$report = array_merge($report, $this->sn_distribution_delivery_report($batch_id, $manager_id, 20));
				$report['action'] = 'distribution_delivery_apply';
			}
		}
		update_option('sn_distribution_delivery_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	public function handle_distribution_transfer_items(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		$nonce_value = sanitize_text_field(wp_unslash($_POST['_wpnonce'] ?? ($_POST['nonce'] ?? '')));
		$form_nonce_status = $nonce_value !== '' && (bool) wp_verify_nonce($nonce_value, 'sn_distribution_transfer_items');
		if (! $form_nonce_status) {
			if (wp_doing_ajax()) {
				SN_Helpers::send_json(false, 'درخواست نامعتبر است. صفحه را رفرش کنید و دوباره تلاش کنید.', ['errors' => ['nonce_invalid']]);
				return;
			}
			check_admin_referer('sn_distribution_transfer_items');
		}
		$this->sn_distribution_ensure_schema();
		global $wpdb;
		$actor_id = get_current_user_id();
		$sanitize_raw_list = static function ($values): array {
			return array_map(static function ($value): string {
				if (is_array($value)) {
					return '[array]';
				}
				return sanitize_text_field(wp_unslash((string) $value));
			}, (array) $values);
		};
		$raw_distribution_item_ids = (array) ($_POST['distribution_item_ids'] ?? []);
		$raw_legacy_item_ids = (array) ($_POST['item_ids'] ?? []);
		$posted_item_ids = array_merge(
			$raw_distribution_item_ids,
			$raw_legacy_item_ids
		);
		$item_ids = array_values(array_filter(array_unique(array_map('absint', $posted_item_ids))));
		$to_user_id = absint($_POST['recipient_user_id'] ?? ($_POST['to_user_id'] ?? 0));
		$selected_recipient_ids = array_values(array_filter(array_unique(array_map('absint', (array) ($_POST['recipient_user_ids'] ?? [])))));
		$recipient_scope = sanitize_key((string) ($_POST['distribution_recipient_scope'] ?? ''));
		$target_position_filter = sanitize_key((string) ($_POST['distribution_target_position'] ?? ''));
		$bulk_mode = sanitize_key((string) ($_POST['distribution_bulk_mode'] ?? 'selected'));
		$allocation_count = max(0, absint($_POST['allocation_count'] ?? 0));
		$per_seller_count = max(0, absint($_POST['per_seller_count'] ?? 0));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
		$case_filter = $this->sn_distribution_transfer_filter_from_request();
		$recipient_map = [];
		$requested_recipient_counts = [];
		$posted_field = ! empty($_POST['distribution_item_ids']) ? 'distribution_item_ids' : (! empty($_POST['item_ids']) ? 'item_ids_legacy' : 'none');
		$auto_skipped_duplicate_items = [];
		$auto_skipped_duplicate_count = 0;
		$auto_target_total = 0;
		$auto_candidate_scan_limit = 2500;
		$record_auto_duplicate_skip = function($candidate, array $guard) use (&$auto_skipped_duplicate_items, &$auto_skipped_duplicate_count, $actor_id): void {
			$auto_skipped_duplicate_count++;
			// Performance critical: auto-allocation can scan thousands of candidates.
			// Do not UPDATE+INSERT-log every skipped duplicate here; the final selected rows
			// are still guarded before transfer. Keep only lightweight samples for operators.
			if (count($auto_skipped_duplicate_items) >= 20) { return; }
			$item_id = (int) ($candidate->id ?? 0);
			$item_phone = $this->sn_distribution_item_phone($candidate);
			$auto_skipped_duplicate_items[] = [
				'item_id' => $item_id,
				'phone' => $this->sn_mask_phone($item_phone),
				'source' => (string) ($guard['source'] ?? ''),
				'message' => (string) ($guard['message'] ?? ''),
				'existing_owner' => (string) ($guard['existing_owner_label'] ?? ''),
				'existing_seller' => (string) ($guard['existing_seller_label'] ?? ''),
			];
		};
		$is_auto_duplicate_candidate = function($candidate) use (&$record_auto_duplicate_skip): bool {
			$item_phone = $this->sn_distribution_item_phone($candidate);
			$source_type = (string) ($candidate->source_type ?? '');
			$exclude_row_id = $source_type === 'mis_data_row' ? (int) ($candidate->source_id ?? 0) : (int) ($candidate->resolved_source_row_id ?? 0);
			$exclude_pool_id = $source_type === 'mis_pool' ? (int) ($candidate->source_id ?? 0) : (int) (($candidate->resolved_pool_id ?? 0) ?: ($candidate->pool_item_id ?? 0));
			$guard = $this->sn_mis_duplicate_hard_guard($item_phone, $exclude_row_id, $exclude_pool_id, (int) ($candidate->id ?? 0));
			if (! empty($guard['duplicate'])) {
				$record_auto_duplicate_skip($candidate, $guard);
				return true;
			}
			return false;
		};

		if (in_array($bulk_mode, ['assign_n_to_recipient', 'round_robin_active_sellers'], true)) {
			// In automatic allocation modes, ignore any checked rows that may still be visible in the table.
			// Otherwise old selected item IDs can be mixed with generated recipient_map and block the transfer.
			$item_ids = [];
		}
		if ($bulk_mode === 'assign_n_to_recipient' && $to_user_id > 0 && $allocation_count > 0) {
			$posted_field = 'bulk_assign_n';
			$auto_target_total = $allocation_count;
			$auto_candidate_scan_limit = $this->sn_distribution_auto_candidate_scan_limit($auto_target_total);
			$auto_candidates = $this->sn_distribution_bulk_candidate_items($actor_id, $auto_candidate_scan_limit, $case_filter);
			$auto_duplicate_guards = $this->sn_mis_duplicate_hard_guard_bulk($auto_candidates);
			foreach ($auto_candidates as $candidate) {
				$allowed = $this->sn_distribution_next_recipients($actor_id, $candidate);
				if (! isset($allowed[$to_user_id])) {
					continue;
				}
				$guard = $auto_duplicate_guards[(int) ($candidate->id ?? 0)] ?? null;
				if (is_array($guard) && ! empty($guard['duplicate'])) {
					$record_auto_duplicate_skip($candidate, $guard);
					continue;
				}
				$item_id = (int) $candidate->id;
				$item_ids[] = $item_id;
				$recipient_map[$item_id] = $to_user_id;
				if (count($item_ids) >= $allocation_count) {
					break;
				}
			}
		} elseif ($bulk_mode === 'round_robin_active_sellers') {
			$use_selected_recipients = $recipient_scope === 'selected' || ! empty($selected_recipient_ids);
			$posted_field = $use_selected_recipients ? 'bulk_round_robin_selected_recipients' : 'bulk_round_robin';
			$primary_position = $this->sn_distribution_primary_recipient_position_for_actor($actor_id);
			$default_recipients = $this->sn_distribution_default_recipient_options_for_actor($actor_id);
			if ($target_position_filter !== '') {
				$default_recipients = array_filter($default_recipients, static fn($recipient) => sanitize_key((string) ($recipient['position'] ?? '')) === $target_position_filter);
			}
			if ($use_selected_recipients) {
				// وقتی کاربر گیرنده‌ها را دستی انتخاب می‌کند، باید همه سطح‌های مجاز HR
				// قابل تخصیص باشند، نه فقط لایه پیش‌فرض بعدی.
				$selected_lookup = array_flip($selected_recipient_ids);
				$bulk_recipients = $selected_recipient_ids ? array_filter($default_recipients, static fn($recipient, $rid) => isset($selected_lookup[(int) $rid]), ARRAY_FILTER_USE_BOTH) : [];
			} else {
				$bulk_recipients = array_filter($default_recipients, static fn($recipient) => ($recipient['position'] ?? '') === $primary_position);
				if (! $bulk_recipients && $default_recipients) {
					$bulk_recipients = $default_recipients;
				}
			}
			$recipient_ids = array_values(array_map('intval', array_keys($bulk_recipients)));
			$target_total = $per_seller_count > 0 ? $per_seller_count * max(1, count($recipient_ids)) : $allocation_count;
			$target_total = $target_total > 0 ? $target_total : 0;
			$auto_target_total = $target_total;
			if ($recipient_ids && $target_total > 0) {
				$recipient_quotas = [];
				if ($per_seller_count > 0) {
					foreach ($recipient_ids as $recipient_id) {
						$recipient_quotas[$recipient_id] = $per_seller_count;
						$requested_recipient_counts[$recipient_id] = $per_seller_count;
					}
				}
				$recipient_index = 0;
				$auto_candidate_scan_limit = $this->sn_distribution_auto_candidate_scan_limit($target_total);
				$auto_candidates = $this->sn_distribution_bulk_candidate_items($actor_id, $auto_candidate_scan_limit, $case_filter);
				$auto_duplicate_guards = $this->sn_mis_duplicate_hard_guard_bulk($auto_candidates);
				foreach ($auto_candidates as $candidate) {
					$allowed = $this->sn_distribution_next_recipients($actor_id, $candidate);
					$matched_recipient = 0;
					$matched_attempt = 0;
					for ($attempt = 0; $attempt < count($recipient_ids); $attempt++) {
						$rid = $recipient_ids[($recipient_index + $attempt) % count($recipient_ids)];
						$has_remaining_quota = ! $recipient_quotas || (int) ($recipient_quotas[$rid] ?? 0) > 0;
						if ($has_remaining_quota && isset($allowed[$rid])) {
							$matched_recipient = $rid;
							$matched_attempt = $attempt;
							break;
						}
					}
					if (! $matched_recipient) {
						continue;
					}
					$guard = $auto_duplicate_guards[(int) ($candidate->id ?? 0)] ?? null;
					if (is_array($guard) && ! empty($guard['duplicate'])) {
						$record_auto_duplicate_skip($candidate, $guard);
						continue;
					}
					$recipient_index = ($recipient_index + $matched_attempt + 1) % count($recipient_ids);
					$item_id = (int) $candidate->id;
					$item_ids[] = $item_id;
					$recipient_map[$item_id] = $matched_recipient;
					if ($recipient_quotas) {
						$recipient_quotas[$matched_recipient] = max(0, (int) $recipient_quotas[$matched_recipient] - 1);
					}
					if (count($item_ids) >= $target_total) {
						break;
					}
					if ($recipient_quotas && array_sum($recipient_quotas) < 1) { break; }
				}
			}
		}
		$item_ids = array_values(array_filter(array_unique(array_map('absint', $item_ids))));
		if ($bulk_mode === 'selected' && $selected_recipient_ids && $item_ids) {
			if ($target_position_filter !== '') {
				$allowed_default = $this->sn_distribution_default_recipient_options_for_actor($actor_id);
				$selected_recipient_ids = array_values(array_filter($selected_recipient_ids, function($rid) use ($allowed_default, $target_position_filter) {
					return isset($allowed_default[(int) $rid]) && sanitize_key((string) ($allowed_default[(int) $rid]['position'] ?? '')) === $target_position_filter;
				}));
			}
			$posted_field = 'selected_items_selected_recipients';
			$to_user_id = 0;
			$recipient_index = 0;
			$selected_item_map = $this->sn_distribution_items_by_ids($item_ids);
			foreach ($item_ids as $item_id) {
				$item = $selected_item_map[(int) $item_id] ?? null;
				if (! $item) {
					continue;
				}
				$allowed = $this->sn_distribution_next_recipients($actor_id, $item);
				$matched_recipient = 0;
				for ($attempt = 0; $attempt < count($selected_recipient_ids); $attempt++) {
					$rid = $selected_recipient_ids[($recipient_index + $attempt) % count($selected_recipient_ids)];
					if (isset($allowed[$rid])) {
						$matched_recipient = $rid;
						$recipient_index = ($recipient_index + $attempt + 1) % count($selected_recipient_ids);
						break;
					}
				}
				if ($matched_recipient) {
					$recipient_map[(int) $item_id] = $matched_recipient;
				}
			}
		}
		$report = [
			'action' => 'distribution_transfer_items',
			'requested_items' => count($item_ids),
			'posted_field' => $posted_field,
			'bulk_mode' => $bulk_mode,
			'recipient_scope' => $recipient_scope,
			'allocation_count' => $allocation_count,
			'per_seller_count' => $per_seller_count,
			'case_filter' => $case_filter,
			'selected_recipient_ids' => $selected_recipient_ids,
			'target_position_filter' => $target_position_filter,
			'actor_user_id' => $actor_id,
			'recipient_user_id' => $to_user_id,
			'recipient_map' => $recipient_map,
			'requested_recipient_counts' => $requested_recipient_counts,
			'recipient_counts' => [],
			'recipient_shortfalls' => [],
			'recipient_labels' => [],
			'form_nonce_status' => $form_nonce_status ? 'valid' : 'invalid_or_missing',
			'raw_post_keys' => array_map('sanitize_key', array_keys($_POST)),
			'distribution_item_ids_raw' => $sanitize_raw_list($raw_distribution_item_ids),
			'item_ids_raw' => $sanitize_raw_list($raw_legacy_item_ids),
			'selected_item_ids_after_sanitize' => $item_ids,
			'auto_target_total' => $auto_target_total,
			'auto_candidate_scan_limit' => $auto_candidate_scan_limit,
			'auto_skipped_duplicate_candidates' => $auto_skipped_duplicate_count,
			'auto_skipped_duplicate_items' => $auto_skipped_duplicate_items,
			'transferred' => 0,
			'errors' => [],
			'duplicate_blocked' => 0,
			'duplicate_blocked_items' => [],
			'skipped_already_delivered_items' => [],
			'skipped_paid_referral_items' => [],
			'skipped_supervisor_action_items' => [],
			'updated_at' => current_time('mysql'),
		];
		if (! $item_ids) {
			$report['errors'][] = 'no_items_selected';
			$report['operator_message'] = in_array($bulk_mode, ['assign_n_to_recipient', 'round_robin_active_sellers'], true) && $auto_skipped_duplicate_count > 0
				? 'همه کاندیدهای قابل بررسی تکراری، تبدیل‌شده یا قبلاً وارد زنجیره فروش بودند؛ هیچ شماره سالمی برای تخصیص پیدا نشد.'
				: 'هیچ آیتمی انتخاب نشده است. حداقل یک ردیف را از ستون انتخاب تیک بزنید.';
			if ($report['posted_field'] === 'none' && current_user_can('manage_options')) {
				$report['admin_debug_message'] = 'هیچ فیلد item_id در POST دریافت نشد؛ checkboxها داخل فرم نیستند یا name آن‌ها اشتباه است.';
			}
		}
		// Operational distribution transfers are nonce- and ownership-protected.
		// The old manual APPLY text gate was removed from front-office panels because
		// supervisors/managers did not understand it and it blocked normal allocation.
		$report['confirm_policy'] = 'not_required_for_operational_distribution_transfer';
		if (! $to_user_id && $bulk_mode !== 'round_robin_active_sellers' && empty($recipient_map)) {
			$report['errors'][] = 'recipient_required';
		}
		if ($bulk_mode === 'selected' && $selected_recipient_ids && empty($recipient_map)) {
			$report['errors'][] = 'no_selected_recipients_in_scope';
		}
		if ($bulk_mode === 'round_robin_active_sellers' && empty($recipient_map)) {
			$report['errors'][] = 'no_active_recipients';
		}
		$fatal_validation_errors = ! empty($report['errors']);
		$transfer_item_map = $this->sn_distribution_items_by_ids($item_ids);
		$bulk_duplicate_guards = ! $fatal_validation_errors && $transfer_item_map ? $this->sn_mis_duplicate_hard_guard_bulk($transfer_item_map) : [];
		if (! $fatal_validation_errors && $item_ids) {
			$wpdb->query('START TRANSACTION');
		}
		foreach ($item_ids as $item_id) {
			$item = $transfer_item_map[(int) $item_id] ?? null;
			if (! $item) {
				$report['errors'][] = 'item_not_found_' . $item_id;
				continue;
			}
			if ($fatal_validation_errors) {
				continue;
			}
			if (! $this->sn_distribution_actor_can_transfer($actor_id, $item)) {
				$report['errors'][] = 'not_owner_' . $item_id;
				continue;
			}
			$item_status_for_transfer = (string) ($item->status ?? '');
			if ((int) ($item->final_seller_user_id ?? 0) > 0 || (int) ($item->live_lead_id ?? 0) > 0 || in_array($item_status_for_transfer, ['delivered_to_seller', 'live_lead_created', 'lead_created', 'converted'], true)) {
				$report['skipped_already_delivered_items'][] = [
					'item_id' => $item_id,
					'phone' => $this->sn_mask_phone($this->sn_distribution_item_phone($item)),
					'status' => $item_status_for_transfer,
					'final_seller' => (int) ($item->final_seller_user_id ?? 0) > 0 ? $this->sn_user_label((int) $item->final_seller_user_id) : '',
				];
				continue;
			}
			$source_type = (string) ($item->source_type ?? '');
			if ($source_type === 'paid_invoice_referral') {
				$report['skipped_paid_referral_items'][] = [
					'item_id' => $item_id,
					'phone' => $this->sn_mask_phone($this->sn_distribution_item_phone($item)),
					'status' => $item_status_for_transfer,
					'message' => 'این آیتم از فاکتور پرداخت‌شده ساخته شده و در صف آماده‌های تبدیل رسیدگی می‌شود، نه تخصیص عادی.',
				];
				continue;
			}
			if ($this->sn_distribution_is_paid_referral_supervisor_hold($item)) {
				$report['skipped_supervisor_action_items'][] = $item_id;
				continue;
			}
			$item_phone = $this->sn_distribution_item_phone($item);
			$exclude_row_id = $source_type === 'mis_data_row' ? (int) ($item->source_id ?? 0) : (int) ($item->resolved_source_row_id ?? 0);
			$exclude_pool_id = $source_type === 'mis_pool' ? (int) ($item->source_id ?? 0) : (int) (($item->resolved_pool_id ?? 0) ?: ($item->pool_item_id ?? 0));
			$guard = $bulk_duplicate_guards[$item_id] ?? $this->sn_mis_duplicate_hard_guard($item_phone, $exclude_row_id, $exclude_pool_id, $item_id);
			if (! empty($guard['duplicate'])) {
				$report['duplicate_blocked']++;
				$report['duplicate_blocked_items'][] = [
					'item_id' => $item_id,
					'phone' => $this->sn_mask_phone($item_phone),
					'source' => (string) ($guard['source'] ?? ''),
					'message' => (string) ($guard['message'] ?? ''),
					'existing_owner' => (string) ($guard['existing_owner_label'] ?? ''),
					'existing_seller' => (string) ($guard['existing_seller_label'] ?? ''),
				];
				$this->sn_distribution_mark_duplicate_blocked_item($item, $actor_id, $guard, 'manual_duplicate_blocked_before_transfer');
				continue;
			}
			$item_to_user_id = absint($recipient_map[$item_id] ?? $to_user_id);
			$allowed = $this->sn_distribution_next_recipients($actor_id, $item);
			$recipient = $allowed[$item_to_user_id] ?? null;
			if (! $recipient) {
				$report['errors'][] = 'recipient_out_of_scope_' . $item_to_user_id;
				continue;
			}
			$to_position = (string) ($recipient['position'] ?? $this->sn_hr_position_for_user($item_to_user_id));
			$status = ! empty($recipient['is_final']) ? 'delivered_to_seller' : 'distributed_forward';
			$data = array_merge($this->sn_distribution_seller_state_reset_data(), [
				'current_owner_user_id' => $item_to_user_id,
				'current_owner_position' => $to_position,
				'current_step_order' => (int) ($recipient['step_order'] ?? 0),
				'status' => $status,
				'updated_at' => current_time('mysql'),
			]);
			if (! empty($recipient['is_final'])) {
				$data['final_seller_user_id'] = $item_to_user_id;
			}
			$ok = $wpdb->update($wpdb->prefix . 'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_items', $data), ['id' => $item_id]) !== false;
			if ($ok) {
				$report['transferred']++;
				$report['recipient_counts'][$item_to_user_id] = (int) ($report['recipient_counts'][$item_to_user_id] ?? 0) + 1;
				$report['recipient_labels'][$item_to_user_id] = $this->sn_user_label($item_to_user_id);
				$this->sn_distribution_log($item_id, $status, $actor_id, (int) $item->current_owner_user_id, $item_to_user_id, (string) $item->current_owner_position, $to_position, (int) ($recipient['step_order'] ?? 0), $note, ['live_lead_created' => false, 'reason' => 'standard_hierarchy_delivery_only']);
			} else {
				$report['errors'][] = 'update_failed_' . $item_id;
			}
		}
		if (! $fatal_validation_errors && $item_ids) {
			$wpdb->query('COMMIT');
		}
		if (! empty($report['duplicate_blocked_items']) && (int) ($report['transferred'] ?? 0) < 1 && empty($report['errors'])) {
			$report['operator_message'] = 'شماره انتخاب‌شده قبلاً در MIS، زنجیره پخش یا سرنخ‌های فروش وجود دارد و دوباره قابل تخصیص نیست.';
		}
		if (! empty($report['skipped_already_delivered_items']) && (int) ($report['transferred'] ?? 0) < 1 && empty($report['errors']) && empty($report['operator_message'])) {
			$report['operator_message'] = 'شماره انتخاب‌شده قبلاً به فروشنده/لید نهایی رسیده و از تخصیص عملیاتی حذف شد.';
		}
		if (! empty($report['skipped_supervisor_action_items']) && (int) ($report['transferred'] ?? 0) < 1 && empty($report['errors']) && empty($report['operator_message'])) {
			$report['operator_message'] = 'این ردیف‌ها مربوط به جریان تبدیل هستند و از بخش تخصیص عادی قابل ارسال نیستند. سرپرست یا سرپرست ارشد باید آن‌ها را از تب «آماده‌های تبدیل» به خودش یا تبدیل‌کننده تخصیص دهد.';
		}
		if (! empty($report['skipped_paid_referral_items']) && (int) ($report['transferred'] ?? 0) < 1 && empty($report['errors']) && empty($report['operator_message'])) {
			$report['operator_message'] = 'این آیتم‌ها منبعشان «ارجاع فاکتور پرداخت‌شده» است و از MIS آپلود نشده‌اند. از تب «آماده‌های تبدیل» استفاده کنید؛ در تخصیص عادی وارد نمی‌شوند.';
		}
		foreach ((array) ($report['requested_recipient_counts'] ?? []) as $rid => $requested_count) {
			$actual_count = (int) ($report['recipient_counts'][$rid] ?? 0);
			if ($actual_count < (int) $requested_count) {
				$report['recipient_shortfalls'][$rid] = (int) $requested_count - $actual_count;
			}
		}
		update_option('sn_distribution_transfer_report', $report, false);
		if (wp_doing_ajax()) {
			$summary_parts = [];
			foreach ((array) ($report['recipient_counts'] ?? []) as $rid => $count) {
				$label = (string) (($report['recipient_labels'][$rid] ?? '') ?: $this->sn_user_label((int) $rid));
				$summary_parts[] = $label . ': ' . number_format_i18n((int) $count);
			}
			$skipped_supervisor_action_count = count((array) ($report['skipped_supervisor_action_items'] ?? []));
			$skipped_paid_referral_count = count((array) ($report['skipped_paid_referral_items'] ?? []));
			$skipped_already_delivered_count = count((array) ($report['skipped_already_delivered_items'] ?? []));
			$auto_skipped_duplicate_message_count = (int) ($report['auto_skipped_duplicate_candidates'] ?? 0);
			$manual_duplicate_message_count = (int) ($report['duplicate_blocked'] ?? 0);
			$shortfall_count = array_sum(array_map('intval', (array) ($report['recipient_shortfalls'] ?? [])));
			$success = empty($report['errors']) && (int) ($report['transferred'] ?? 0) > 0;
			$message = $success
				? number_format_i18n((int) $report['transferred']) . ' شماره سالم تخصیص داده شد.' . ($shortfall_count ? ' برای بعضی گیرنده‌ها ' . number_format_i18n($shortfall_count) . ' شماره سالم/مجاز کمتر از مقدار درخواستی موجود بود؛ به هیچ فردی بیشتر از تعداد انتخاب‌شده داده نشد.' : '') . ($auto_skipped_duplicate_message_count ? ' ' . number_format_i18n($auto_skipped_duplicate_message_count) . ' شماره تکراری/تبدیل‌شده قبل از تخصیص رد شد و وارد لیست گیرنده‌ها نشد.' : '') . ($manual_duplicate_message_count ? ' ' . number_format_i18n($manual_duplicate_message_count) . ' شماره انتخاب‌شده به‌دلیل تکراری/تبدیل‌شده بودن تخصیص نگرفت.' : '') . ($skipped_already_delivered_count ? ' ' . number_format_i18n($skipped_already_delivered_count) . ' شماره قبلاً به فروشنده/لید نهایی رسیده بود و تخصیص نگرفت.' : '') . ($skipped_supervisor_action_count ? ' ' . number_format_i18n($skipped_supervisor_action_count) . ' آیتم نیاز به اقدام مجدد در تخصیص عادی رد شد.' : '') . ($skipped_paid_referral_count ? ' ' . number_format_i18n($skipped_paid_referral_count) . ' آیتم ارجاع فاکتور پرداخت‌شده از تخصیص عادی رد شد.' : '')
				: (string) (($report['operator_message'] ?? '') ?: 'تخصیص انجام نشد. انتخاب‌ها و تعداد را بررسی کنید.');
			SN_Helpers::send_json($success, $message, ['report' => $report]);
			return;
		}
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}


	private function sn_distribution_returnable_items_for_actor(int $actor_id, int $limit = 500, array $case_filter = []): array
	{
		global $wpdb;
		if ($actor_id < 1 || ! $this->sn_distribution_tables_ready()) { return []; }
		$limit = max(1, min(5000, $limit));
		$excluded_statuses = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error', 'returned_to_mis'];
		$status_placeholders = implode(',', array_fill(0, count($excluded_statuses), '%s'));
		$select_sql = "SELECT DISTINCT di.*, COALESCE(p.customer_name,r.customer_name) customer_name, COALESCE(p.customer_phone,r.customer_phone) customer_phone, COALESCE(p.normalized_phone,r.normalized_phone) normalized_phone, COALESCE(p.city,r.city) city, COALESCE(p.province,r.province) province, b.batch_code, b.title batch_title, b.source_type batch_source_type, b.source_label, b.campaign_code, b.data_category,
			COALESCE(p.source_row_id, CASE WHEN di.source_type='mis_data_row' THEN di.source_id ELSE 0 END) AS resolved_source_row_id,
			COALESCE(p.id, di.pool_item_id, CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE 0 END) AS resolved_pool_id
			FROM {$wpdb->prefix}sn_distribution_items di
			INNER JOIN {$wpdb->prefix}sn_distribution_item_logs l ON l.item_id=di.id AND l.actor_user_id=%d AND l.action IN ('distributed_forward','delivered_to_seller')
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)
			WHERE (di.current_owner_user_id IS NULL OR di.current_owner_user_id<>%d)
				AND (di.live_lead_id IS NULL OR di.live_lead_id=0)
				AND (di.status IS NULL OR di.status='' OR di.status NOT IN ({$status_placeholders}))
			ORDER BY di.updated_at DESC, di.id DESC LIMIT %d";
		$args = array_merge([$actor_id, $actor_id], $excluded_statuses, [$limit]);
		$rows = $wpdb->get_results($wpdb->prepare($select_sql, ...$args)) ?: [];
		if ($case_filter) {
			$rows = array_values(array_filter($rows, fn($item) => $this->sn_distribution_item_matches_transfer_filter($item, $case_filter)));
		}
		return $rows;
	}

	public function handle_distribution_return_items(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		$nonce_value = sanitize_text_field(wp_unslash($_POST['_wpnonce'] ?? ($_POST['nonce'] ?? '')));
		$form_nonce_status = $nonce_value !== '' && (bool) wp_verify_nonce($nonce_value, 'sn_distribution_return_items');
		if (! $form_nonce_status) {
			if (wp_doing_ajax()) { SN_Helpers::send_json(false, 'درخواست نامعتبر است. صفحه را رفرش کنید و دوباره تلاش کنید.', ['errors' => ['nonce_invalid']]); return; }
			check_admin_referer('sn_distribution_return_items');
		}
		$this->sn_distribution_ensure_schema();
		global $wpdb;
		$actor_id = get_current_user_id();
		$actor_position = sanitize_key((string) $this->sn_hr_position_for_user($actor_id));
		if (! current_user_can('manage_options') && ! in_array($actor_position, ['sales_deputy','sales_manager','senior_supervisor','supervisor'], true)) {
			if (wp_doing_ajax()) { SN_Helpers::send_json(false, 'این عملیات فقط برای مدیران/سرپرستان مجاز است.'); return; }
			wp_die('دسترسی غیرمجاز');
		}
		if ($actor_position === '') { $actor_position = 'sales_manager'; }
		$case_filter = $this->sn_distribution_transfer_filter_from_request();
		$return_count = max(0, min(500, absint($_POST['return_count'] ?? 0)));
		$selected_ids = array_values(array_filter(array_unique(array_map('absint', (array) ($_POST['distribution_item_ids'] ?? [])))));
		$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? 'برگشت تخصیص به پنل مالک'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$report = [
			'action' => 'distribution_return_items',
			'actor_user_id' => $actor_id,
			'actor_position' => $actor_position,
			'requested_items' => 0,
			'returned' => 0,
			'skipped' => 0,
			'errors' => [],
			'case_filter' => $case_filter,
			'updated_at' => current_time('mysql'),
		];
		if ($confirm !== 'RETURN') { $report['errors'][] = 'confirmation_required'; }
		$candidates = $this->sn_distribution_returnable_items_for_actor($actor_id, 2500, $case_filter);
		$candidate_map = [];
		foreach ($candidates as $candidate) { $candidate_map[(int) $candidate->id] = $candidate; }
		if ($selected_ids) {
			$item_ids = array_values(array_intersect($selected_ids, array_keys($candidate_map)));
		} else {
			$item_ids = array_slice(array_keys($candidate_map), 0, $return_count > 0 ? $return_count : 0);
		}
		$report['requested_items'] = count($item_ids);
		if (! $item_ids) { $report['errors'][] = 'no_returnable_items_selected'; }
		$chain = $this->sn_distribution_active_chain();
		$step_map = $this->sn_distribution_step_order_map((array) ($chain['steps'] ?? []));
		$actor_step = (int) ($step_map[$actor_position] ?? 0);
		if (empty($report['errors'])) {
			foreach ($item_ids as $item_id) {
				$item = $candidate_map[(int) $item_id] ?? null;
				if (! $item) { $report['skipped']++; continue; }
				$from_user_id = (int) ($item->current_owner_user_id ?? 0);
				$from_position = (string) ($item->current_owner_position ?? '');
				$data = array_merge($this->sn_distribution_seller_state_reset_data(), [
					'current_owner_user_id' => $actor_id,
					'current_owner_position' => $actor_position,
					'current_step_order' => $actor_step,
					'final_seller_user_id' => null,
					'status' => $actor_position === 'sales_manager' ? 'returned_to_manager' : 'returned_to_owner',
					'updated_at' => current_time('mysql'),
				]);
				$ok = $wpdb->update($wpdb->prefix . 'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_items', $data), ['id' => (int) $item_id]) !== false;
				if ($ok) {
					$report['returned']++;
					$this->sn_distribution_log((int) $item_id, (string) $data['status'], $actor_id, $from_user_id, $actor_id, $from_position, $actor_position, $actor_step, $note, [
						'reason' => 'manual_return_to_owner_panel',
						'previous_status' => (string) ($item->status ?? ''),
						'previous_final_seller_user_id' => (int) ($item->final_seller_user_id ?? 0),
					]);
				} else {
					$report['errors'][] = 'update_failed_' . (int) $item_id;
				}
			}
		}
		update_option('sn_distribution_return_report', $report, false);
		if (wp_doing_ajax()) {
			$success = empty($report['errors']) && (int) $report['returned'] > 0;
			$message = $success ? number_format_i18n((int) $report['returned']) . ' شماره به پنل شما برگشت.' : 'برگشت انجام نشد. تعداد/پرونده را بررسی کنید.';
			SN_Helpers::send_json($success, $message, ['report' => $report]);
			return;
		}
		wp_safe_redirect(add_query_arg('sn_ui_active_tab', 'manager-distribution', wp_get_referer() ?: home_url('/')) . '#manager-distribution');
		exit;
	}

	public function handle_distribution_convert_items(): void
	{
		if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_distribution_convert_items');
		$this->sn_distribution_ensure_schema();
		$actor_id = get_current_user_id();
		$item_ids = array_values(array_filter(array_unique(array_map('absint', (array) ($_POST['item_ids'] ?? [])))));
		$single_item_id = absint($_POST['item_id'] ?? 0);
		if ($single_item_id > 0 && ! in_array($single_item_id, $item_ids, true)) {
			$item_ids[] = $single_item_id;
		}
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$requires_confirm = count($item_ids) > 1;
		$report = [
			'action' => 'distribution_convert_items_to_live_leads',
			'requested_items' => count($item_ids),
			'created' => 0,
			'already_created' => 0,
			'duplicates' => 0,
			'errors' => [],
			'items' => [],
			'updated_at' => current_time('mysql'),
		];
		if (! $item_ids) {
			$report['errors'][] = 'item_required';
		}
		if ($requires_confirm && $confirm !== 'APPLY') {
			$report['errors'][] = 'confirmation_required_for_bulk';
		}
		if (empty($report['errors'])) {
			foreach ($item_ids as $item_id) {
				$result = $this->sn_distribution_convert_item_to_lead($item_id, $actor_id, $reason);
				$report['items'][] = $result;
				$status = (string) ($result['status'] ?? '');
				if ($status === 'created') {
					$report['created']++;
				} elseif ($status === 'already_created') {
					$report['already_created']++;
				} elseif ($status === 'duplicate') {
					$report['duplicates']++;
				} elseif (! empty($result['error'])) {
					$report['errors'][] = 'item_' . $item_id . '_' . (string) $result['error'];
				}
			}
		}
		update_option('sn_distribution_conversion_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	private function sn_distribution_can_convert_item(object $item, int $actor_id): bool
	{
		if (current_user_can('manage_options') || is_super_admin($actor_id)) {
			return true;
		}
		if ($this->sn_hr_position_for_user($actor_id) !== 'seller') {
			return false;
		}
		$final_seller_id = (int) ($item->final_seller_user_id ?? 0);
		$current_owner_id = (int) ($item->current_owner_user_id ?? 0);
		$current_position = (string) ($item->current_owner_position ?? '');
		return $final_seller_id === $actor_id || ($current_owner_id === $actor_id && $current_position === 'seller');
	}

	private function sn_distribution_load_conversion_item(int $item_id): ?object
	{
		global $wpdb;
		if ($item_id < 1 || ! $this->sn_distribution_tables_ready()) {
			return null;
		}
		return $wpdb->get_row($wpdb->prepare(
			"SELECT di.*,
				COALESCE(NULLIF(di.seller_customer_name,''),p.customer_name,r.customer_name) customer_name,
				COALESCE(p.customer_phone,r.customer_phone) customer_phone,
				COALESCE(p.normalized_phone,r.normalized_phone) normalized_phone,
				COALESCE(NULLIF(di.seller_city,''),p.city,r.city) city,
				COALESCE(NULLIF(di.seller_province,''),p.province,r.province) province,
				p.source_meta, b.batch_code, b.campaign_code, b.data_category
			FROM {$wpdb->prefix}sn_distribution_items di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)
			WHERE di.id=%d",
			$item_id
		));
	}

	private function sn_distribution_find_existing_lead(string $phone): ?object
	{
		global $wpdb;
		$phone = SN_Helpers::normalize_mobile($phone);
		if ($phone === '') {
			return null;
		}
		$digits = preg_replace('/\D+/', '', $phone);
		$variants = array_values(array_unique(array_filter([$phone, $digits, ltrim($digits, '0'), preg_replace('/^98/', '0', $digits)])));
		$placeholders = implode(',', array_fill(0, count($variants), '%s'));
		return $wpdb->get_row($wpdb->prepare("SELECT id, seller_id, phone FROM {$wpdb->prefix}sn_leads WHERE phone IN ({$placeholders}) ORDER BY id ASC LIMIT 1", ...$variants));
	}

	private function sn_distribution_convert_item_to_lead(int $item_id, int $actor_id, string $reason = ''): array
	{
		global $wpdb;
		$item = $this->sn_distribution_load_conversion_item($item_id);
		$now = current_time('mysql');
		if (! $item) {
			return ['item_id' => $item_id, 'status' => 'error', 'error' => 'item_not_found'];
		}
		if (! $this->sn_distribution_can_convert_item($item, $actor_id)) {
			return ['item_id' => $item_id, 'status' => 'error', 'error' => 'forbidden'];
		}
		$item_status = (string) ($item->status ?? '');
		$current_owner_id = (int) ($item->current_owner_user_id ?? 0);
		$current_position = (string) ($item->current_owner_position ?? '');
		$allowed_conversion_statuses = ['delivered_to_seller', 'ready_for_lead_conversion'];
		if ($current_owner_id === $actor_id && $current_position === 'seller') {
			$allowed_conversion_statuses[] = 'distributed_forward';
			$allowed_conversion_statuses[] = 'assigned_to_role';
			$allowed_conversion_statuses[] = 'delivered_to_role';
		}
		if (! in_array($item_status, $allowed_conversion_statuses, true)) {
			return ['item_id' => $item_id, 'status' => 'error', 'error' => 'item_not_delivered_to_seller'];
		}
		$seller_id = (int) ($item->final_seller_user_id ?: $item->current_owner_user_id);
		if ($seller_id < 1 || $this->sn_hr_position_for_user($seller_id) !== 'seller') {
			return ['item_id' => $item_id, 'status' => 'error', 'error' => 'final_seller_required'];
		}
		if (! empty($item->live_lead_id)) {
			return ['item_id' => $item_id, 'status' => 'already_created', 'lead_id' => (int) $item->live_lead_id];
		}
		$phone = SN_Helpers::normalize_mobile((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? '')));
		if ($phone === '') {
			$this->sn_distribution_mark_conversion_result($item, 'conversion_failed', 0, $actor_id, 'missing_phone', $now);
			return ['item_id' => $item_id, 'status' => 'error', 'error' => 'missing_phone'];
		}
		$existing = $this->sn_distribution_find_existing_lead($phone);
		if ($existing) {
			$lead_id = (int) $existing->id;
			$can_link = (int) ($existing->seller_id ?? 0) === $seller_id;
			$this->sn_distribution_mark_conversion_result($item, 'duplicate_lead_detected', $can_link ? $lead_id : 0, $actor_id, 'duplicate_phone_in_sn_leads', $now);
			return ['item_id' => $item_id, 'status' => 'duplicate', 'lead_id' => $can_link ? $lead_id : 0, 'error' => 'duplicate_phone_in_sn_leads'];
		}
		$lead_table = $wpdb->prefix . 'sn_leads';
		$note_parts = [
			'MIS hierarchy delivered item conversion',
			'distribution_item_id=' . $item_id,
			'pool_item_id=' . (int) ($item->pool_item_id ?? 0),
			'batch_id=' . (int) ($item->batch_id ?? 0),
			'batch_code=' . (string) ($item->batch_code ?? ''),
			'campaign=' . (string) ($item->campaign_code ?? ''),
			'category=' . (string) ($item->data_category ?? ''),
		];
		if ($reason !== '') {
			$note_parts[] = 'reason=' . $reason;
		}
		$data = [
			'phone' => $phone,
			'customer_name' => sanitize_text_field((string) ($item->customer_name ?? '')),
			'import_code' => (string) ($item->batch_code ?? '') !== '' ? sanitize_text_field((string) $item->batch_code) : 'MIS-' . (int) ($item->batch_id ?? 0),
			'province' => sanitize_text_field((string) ($item->province ?? '')),
			'city' => sanitize_text_field((string) ($item->city ?? '')),
			'status' => 'assigned',
			'lead_status' => 'assigned',
			'note' => implode(' | ', $note_parts),
			'seller_id' => $seller_id,
			'supervisor_id' => (int) get_user_meta($seller_id, 'sn_supervisor_id', true) ?: null,
			'imported_at' => $now,
			'assigned_at' => $now,
			'updated_at' => $now,
		];
		$data = array_intersect_key($data, array_flip($this->sn_table_columns($lead_table)));
		$inserted = $wpdb->insert($lead_table, $data);
		if (! $inserted) {
			$error = sanitize_text_field($wpdb->last_error ?: 'lead_insert_failed');
			$this->sn_distribution_mark_conversion_result($item, 'conversion_failed', 0, $actor_id, $error, $now);
			return ['item_id' => $item_id, 'status' => 'error', 'error' => $error];
		}
		$lead_id = (int) $wpdb->insert_id;
		if ( class_exists( 'SN_Campaign_Tracking' ) ) { SN_Campaign_Tracking::capture_lead( $lead_id, $phone ); }
		$this->sn_distribution_mark_conversion_result($item, 'live_lead_created', $lead_id, $actor_id, '', $now);
		$this->sn_log_status_history($lead_id, null, 'assigned', 'ساخت سرنخ از آیتم تحویل‌شده پخش داده #' . $item_id);
		return ['item_id' => $item_id, 'status' => 'created', 'lead_id' => $lead_id];
	}

	private function sn_distribution_mark_conversion_result(object $item, string $status, int $lead_id, int $actor_id, string $error, string $now): void
	{
		global $wpdb;
		$item_table = $wpdb->prefix . 'sn_distribution_items';
		$item_id = (int) $item->id;
		$data = [
			'status' => $status,
			'live_lead_id' => $lead_id > 0 ? $lead_id : null,
			'converted_by' => $actor_id,
			'converted_at' => $now,
			'conversion_status' => $status,
			'conversion_error' => $error !== '' ? substr($error, 0, 500) : null,
			'conversion_attempts' => max(0, (int) ($item->conversion_attempts ?? 0)) + 1,
			'updated_at' => $now,
		];
		$wpdb->update($item_table, $this->sn_filter_existing_columns($item_table, $data), ['id' => $item_id]);
		$this->sn_distribution_log($item_id, $status, $actor_id, (int) ($item->current_owner_user_id ?? 0), (int) ($item->final_seller_user_id ?? 0), (string) ($item->current_owner_position ?? ''), 'seller', (int) ($item->current_step_order ?? 0), $error, [
			'live_lead_id' => $lead_id,
			'conversion_status' => $status,
			'standard_hierarchy_completed_before_conversion' => true,
		]);
	}


	private function sn_mis_duplicate_trace_for_phone(string $normalized, int $current_batch_id = 0, int $exclude_row_id = 0): array
	{
		global $wpdb;
		$normalized = trim($normalized);
		$trace = [
			'phone_masked' => $this->sn_mask_phone($normalized),
			'source' => '',
			'existing_row_id' => 0,
			'existing_batch_id' => 0,
			'existing_batch_code' => '',
			'existing_batch_title' => '',
			'existing_batch_status' => '',
			'existing_row_status' => '',
			'distribution_item_id' => 0,
			'distribution_status' => '',
			'current_owner_user_id' => 0,
			'current_owner_label' => '',
			'current_owner_position' => '',
			'final_seller_user_id' => 0,
			'final_seller_label' => '',
			'live_lead_id' => 0,
			'lead_id' => 0,
			'lead_seller_user_id' => 0,
			'lead_seller_label' => '',
			'lead_status' => '',
		];
		if ($normalized === '') {
			return $trace;
		}

		$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
		if ($this->sn_table_exists_quiet($rows_table)) {
			$where = 'normalized_phone=%s';
			$args = [$normalized];
			if ($exclude_row_id > 0) {
				$where .= ' AND id<>%d';
				$args[] = $exclude_row_id;
			}
			$batch_table = $wpdb->prefix . 'sn_mis_import_batches';
			$join = $this->sn_table_exists_quiet($batch_table) ? " LEFT JOIN {$batch_table} b ON b.id=r.batch_id" : '';
			$select = $this->sn_table_exists_quiet($batch_table)
				? 'r.*, b.batch_code existing_batch_code, b.title existing_batch_title, b.import_status existing_batch_status'
				: 'r.*';
			$active_batch_sql = $this->sn_table_exists_quiet($batch_table) ? " AND b.id IS NOT NULL AND COALESCE(b.import_status,'') NOT IN ('draft','deleted','file_deleted','reset_deleted')" : '';
			$sql = "SELECT {$select} FROM {$rows_table} r {$join} WHERE {$where} AND r.row_status='valid'{$active_batch_sql} ORDER BY r.id ASC LIMIT 1";
			$row = $wpdb->get_row($wpdb->prepare($sql, ...$args));
			if ($row) {
				$trace['source'] = 'mis_data_rows';
				$trace['existing_row_id'] = (int) ($row->id ?? 0);
				$trace['existing_batch_id'] = (int) ($row->batch_id ?? 0);
				$trace['existing_batch_code'] = (string) ($row->existing_batch_code ?? '');
				$trace['existing_batch_title'] = (string) ($row->existing_batch_title ?? '');
				$trace['existing_batch_status'] = (string) ($row->existing_batch_status ?? '');
				$trace['existing_row_status'] = (string) ($row->row_status ?? '');
				$dist = $this->sn_mis_distribution_trace_for_data_row_id((int) ($row->id ?? 0));
				$trace = array_merge($trace, $dist);
				return $trace;
			}
		}

		$leads_table = $wpdb->prefix . 'sn_leads';
		if ($this->sn_table_exists_quiet($leads_table)) {
			$lead = $wpdb->get_row($wpdb->prepare("SELECT id, seller_id, status, lead_status FROM {$leads_table} WHERE phone=%s ORDER BY id ASC LIMIT 1", $normalized));
			if ($lead) {
				$trace['source'] = 'sn_leads';
				$trace['lead_id'] = (int) ($lead->id ?? 0);
				$trace['lead_seller_user_id'] = (int) ($lead->seller_id ?? 0);
				$trace['lead_seller_label'] = $trace['lead_seller_user_id'] ? $this->sn_user_label($trace['lead_seller_user_id']) : '';
				$trace['lead_status'] = (string) (($lead->lead_status ?? '') ?: ($lead->status ?? ''));
			}
		}
		return $trace;
	}

	private function sn_mis_duplicate_trace_for_row($row): array
	{
		if (! is_object($row)) {
			return [];
		}
		$normalized = (string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''));
		return $this->sn_mis_duplicate_trace_for_phone($normalized, (int) ($row->batch_id ?? 0), (int) ($row->id ?? 0));
	}

	private function sn_mis_existing_row_for_phone_in_batch(string $normalized, int $batch_id, int $exclude_row_id = 0): ?object
	{
		global $wpdb;
		$normalized = SN_Helpers::normalize_mobile($normalized);
		if ($normalized === '' || $batch_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			return null;
		}
		$where = 'batch_id=%d AND normalized_phone=%s';
		$args = [$batch_id, $normalized];
		if ($exclude_row_id > 0) {
			$where .= ' AND id<>%d';
			$args[] = $exclude_row_id;
		}
		$sql = "SELECT * FROM {$wpdb->prefix}sn_mis_data_rows WHERE {$where} ORDER BY CASE WHEN row_status='valid' THEN 0 WHEN row_status='duplicate' THEN 1 ELSE 2 END, id ASC LIMIT 1";
		$row = $wpdb->get_row($wpdb->prepare($sql, ...$args));
		return $row ?: null;
	}

	private function sn_mis_recount_batch_rows(int $batch_id): array
	{
		global $wpdb;
		$out = ['total' => 0, 'valid' => 0, 'duplicate' => 0, 'invalid' => 0];
		if ($batch_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			return $out;
		}
		$rows = $wpdb->get_results($wpdb->prepare("SELECT row_status, COUNT(*) c FROM {$wpdb->prefix}sn_mis_data_rows WHERE batch_id=%d GROUP BY row_status", $batch_id)) ?: [];
		foreach ($rows as $row) {
			$status = (string) ($row->row_status ?? '');
			$count = (int) ($row->c ?? 0);
			$out['total'] += $count;
			if ($status === 'valid') {
				$out['valid'] += $count;
			} elseif ($status === 'duplicate') {
				$out['duplicate'] += $count;
			} else {
				$out['invalid'] += $count;
			}
		}
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_import_batches')) {
			$wpdb->update($wpdb->prefix . 'sn_mis_import_batches', [
				'total_rows' => $out['total'],
				'valid_rows' => $out['valid'],
				'duplicate_rows' => $out['duplicate'],
				'invalid_rows' => $out['invalid'],
				'updated_at' => current_time('mysql'),
			], ['id' => $batch_id]);
		}
		return $out;
	}

	private function sn_mis_cleanup_same_batch_duplicate_rows(int $batch_id): int
	{
		global $wpdb;
		if ($batch_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			return 0;
		}
		$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
		$items_table = $wpdb->prefix . 'sn_distribution_items';
		$items_join = $this->sn_table_exists_quiet($items_table) ? "LEFT JOIN {$items_table} di ON di.source_type='mis_data_row' AND di.source_id=d.id" : '';
		$items_where = $this->sn_table_exists_quiet($items_table) ? 'AND di.id IS NULL' : '';
		$sql = "DELETE d FROM {$rows_table} d
			INNER JOIN {$rows_table} k ON k.batch_id=d.batch_id AND k.normalized_phone=d.normalized_phone AND k.id<d.id
			{$items_join}
			WHERE d.batch_id=%d
			AND COALESCE(d.normalized_phone,'')<>''
			AND d.row_status='duplicate'
			AND COALESCE(d.duplicate_reason,'') IN ('duplicate_in_mis','duplicate_in_file','duplicate_in_same_batch','same_batch_reimport')
			{$items_where}";
		$deleted = $wpdb->query($wpdb->prepare($sql, $batch_id));
		if ($deleted === false) {
			return 0;
		}
		if ((int) $deleted > 0) {
			$this->sn_mis_recount_batch_rows($batch_id);
		}
		return (int) $deleted;
	}


	private function sn_mis_collect_batch_phone_scope(int $batch_id): array
	{
		global $wpdb;
		$phones = [];
		if ($batch_id < 1) { return []; }
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$add = static function($value) use (&$phones): void {
			$phone = SN_Helpers::normalize_mobile((string) $value);
			if ($phone !== '') { $phones[$phone] = true; }
		};
		if ($this->sn_table_exists_quiet($rows)) {
			foreach ((array) $wpdb->get_col($wpdb->prepare("SELECT COALESCE(NULLIF(normalized_phone,''), customer_phone) FROM {$rows} WHERE batch_id=%d", $batch_id)) as $phone) { $add($phone); }
		}
		if ($this->sn_table_exists_quiet($pool)) {
			foreach ((array) $wpdb->get_col($wpdb->prepare("SELECT COALESCE(NULLIF(normalized_phone,''), customer_phone) FROM {$pool} WHERE batch_id=%d", $batch_id)) as $phone) { $add($phone); }
		}
		if ($this->sn_table_exists_quiet($items)) {
			$phone_expr = "COALESCE(NULLIF(di.normalized_phone,''), NULLIF(di.customer_phone,''), NULLIF(r.normalized_phone,''), NULLIF(r.customer_phone,''), NULLIF(p.normalized_phone,''), NULLIF(p.customer_phone,''))";
			$join_rows = $this->sn_table_exists_quiet($rows) ? " LEFT JOIN {$rows} r ON (di.source_type='mis_data_row' AND r.id=di.source_id)" : " LEFT JOIN (SELECT 0 id, '' normalized_phone, '' customer_phone, 0 batch_id) r ON 1=0";
			$join_pool = $this->sn_table_exists_quiet($pool) ? " LEFT JOIN {$pool} p ON ((di.source_type='mis_pool' AND p.id=di.source_id) OR p.id=di.pool_item_id)" : " LEFT JOIN (SELECT 0 id, '' normalized_phone, '' customer_phone, 0 batch_id) p ON 1=0";
			$where = ["di.batch_id=%d"];
			$args = [$batch_id];
			if ($this->sn_table_exists_quiet($rows)) { $where[] = "r.batch_id=%d"; $args[] = $batch_id; }
			if ($this->sn_table_exists_quiet($pool)) { $where[] = "p.batch_id=%d"; $args[] = $batch_id; }
			$sql = "SELECT {$phone_expr} phone FROM {$items} di {$join_rows} {$join_pool} WHERE (" . implode(' OR ', $where) . ")";
			foreach ((array) $wpdb->get_col($wpdb->prepare($sql, ...$args)) as $phone) { $add($phone); }
		}
		return array_values(array_keys($phones));
	}

	private function sn_mis_purge_unlocked_phone_traces(array $phones, int $batch_id = 0): array
	{
		global $wpdb;
		$phones = array_values(array_unique(array_filter(array_map(static fn($p) => SN_Helpers::normalize_mobile((string) $p), $phones))));
		$report = ['phones' => count($phones), 'distribution_item_logs' => 0, 'distribution_items' => 0, 'pool_rows' => 0, 'data_rows' => 0, 'affected_batches' => []];
		if (! $phones || $batch_id < 1) { return $report; }
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$item_logs = $wpdb->prefix . 'sn_distribution_item_logs';
		$locked_statuses = ['converted','lead_created','live_lead_created','invoiced','invoice_created','paid','approved'];
		foreach (array_chunk($phones, 600) as $chunk) {
			$ph = implode(',', array_fill(0, count($chunk), '%s'));
			if ($this->sn_table_exists_quiet($items)) {
				$rows_join = $this->sn_table_exists_quiet($rows) ? " LEFT JOIN {$rows} r ON di.source_type='mis_data_row' AND r.id=di.source_id" : "";
				$pool_join = $this->sn_table_exists_quiet($pool) ? " LEFT JOIN {$pool} p ON ((di.source_type='mis_pool' AND p.id=di.source_id) OR p.id=di.pool_item_id)" : "";
				$phone_parts = ["NULLIF(di.normalized_phone,'')", "NULLIF(di.customer_phone,'')"];
				if ($this->sn_table_exists_quiet($rows)) { $phone_parts[] = "NULLIF(r.normalized_phone,'')"; $phone_parts[] = "NULLIF(r.customer_phone,'')"; }
				if ($this->sn_table_exists_quiet($pool)) { $phone_parts[] = "NULLIF(p.normalized_phone,'')"; $phone_parts[] = "NULLIF(p.customer_phone,'')"; }
				$phone_expr = 'COALESCE(' . implode(', ', $phone_parts) . ')';
				$where = "{$phone_expr} IN ({$ph}) AND COALESCE(di.live_lead_id,0)=0";
				$args = $chunk;
				if ($this->sn_table_has_column($items, 'conversion_status')) {
					$where .= " AND COALESCE(di.conversion_status,'') NOT IN (" . implode(',', array_fill(0, count($locked_statuses), '%s')) . ")";
					$args = array_merge($args, $locked_statuses);
				}
				$where .= " AND COALESCE(di.status,'') NOT IN (" . implode(',', array_fill(0, count($locked_statuses), '%s')) . ")";
				$args = array_merge($args, $locked_statuses);
				$scope = ['di.batch_id=%d'];
				$scope_args = [$batch_id];
				if ($this->sn_table_exists_quiet($rows)) { $scope[] = "r.batch_id=%d"; $scope_args[] = $batch_id; }
				if ($this->sn_table_exists_quiet($pool)) { $scope[] = "p.batch_id=%d"; $scope_args[] = $batch_id; }
				$where .= ' AND (' . implode(' OR ', $scope) . ')';
				$args = array_merge($args, $scope_args);
				if ($this->sn_table_exists_quiet($item_logs)) {
					$deleted = $wpdb->query($wpdb->prepare("DELETE l FROM {$item_logs} l INNER JOIN {$items} di ON di.id=l.item_id {$rows_join} {$pool_join} WHERE {$where}", ...$args));
					$report['distribution_item_logs'] += max(0, (int) $deleted);
				}
				$deleted = $wpdb->query($wpdb->prepare("DELETE di FROM {$items} di {$rows_join} {$pool_join} WHERE {$where}", ...$args));
				$report['distribution_items'] += max(0, (int) $deleted);
			}
			if ($this->sn_table_exists_quiet($pool)) {
				$args = array_merge($chunk, [$batch_id]);
				$where = "COALESCE(NULLIF(normalized_phone,''), customer_phone) IN ({$ph}) AND batch_id=%d";
				$deleted = $wpdb->query($wpdb->prepare("DELETE FROM {$pool} WHERE {$where}", ...$args));
				$report['pool_rows'] += max(0, (int) $deleted);
			}
			if ($this->sn_table_exists_quiet($rows)) {
				$args = array_merge($chunk, [$batch_id]);
				$where = "COALESCE(NULLIF(r.normalized_phone,''), r.customer_phone) IN ({$ph}) AND r.batch_id=%d";
				$affected = $wpdb->get_col($wpdb->prepare("SELECT DISTINCT r.batch_id FROM {$rows} r WHERE {$where}", ...$args));
				foreach ((array) $affected as $bid) { if ((int) $bid > 0) { $report['affected_batches'][(int) $bid] = true; } }
				$deleted = $wpdb->query($wpdb->prepare("DELETE r FROM {$rows} r WHERE {$where}", ...$args));
				$report['data_rows'] += max(0, (int) $deleted);
			}
		}
		foreach (array_keys((array) $report['affected_batches']) as $affected_batch_id) { $this->sn_mis_recount_batch_rows((int) $affected_batch_id); }
		$report['affected_batches'] = array_map('intval', array_keys((array) $report['affected_batches']));
		return $report;
	}


	private function sn_distribution_item_phone(object $item): string
	{
		global $wpdb;
		$phone = SN_Helpers::normalize_mobile((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? '') ?: ($item->phone ?? '') ?: ($item->mobile ?? '')));
		if ($phone !== '') {
			return $phone;
		}
		$source_type = (string) ($item->source_type ?? '');
		$source_id = (int) ($item->source_id ?? 0);
		if ($source_type === 'mis_data_row' && $source_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			$row_phone = (string) $wpdb->get_var($wpdb->prepare("SELECT COALESCE(NULLIF(normalized_phone,''), customer_phone) FROM {$wpdb->prefix}sn_mis_data_rows WHERE id=%d LIMIT 1", $source_id));
			$phone = SN_Helpers::normalize_mobile($row_phone);
			if ($phone !== '') { return $phone; }
		}
		$pool_id = $source_type === 'mis_pool' ? $source_id : (int) ($item->pool_item_id ?? 0);
		if ($pool_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_lead_pool')) {
			$pool_phone = (string) $wpdb->get_var($wpdb->prepare("SELECT COALESCE(NULLIF(normalized_phone,''), customer_phone) FROM {$wpdb->prefix}sn_mis_lead_pool WHERE id=%d LIMIT 1", $pool_id));
			$phone = SN_Helpers::normalize_mobile($pool_phone);
			if ($phone !== '') { return $phone; }
		}
		return '';
	}


	private function sn_distribution_mark_duplicate_blocked_item(object $item, int $actor_id, array $guard, string $reason = ''): void
	{
		global $wpdb;
		if (! $this->sn_distribution_tables_ready()) { return; }
		$item_id = (int) ($item->id ?? 0);
		if ($item_id < 1) { return; }
		$current_status = (string) ($item->status ?? '');
		if (in_array($current_status, ['duplicate', 'archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created'], true)) { return; }
		$now = current_time('mysql');
		$message = (string) (($guard['message'] ?? '') ?: 'duplicate_blocked_before_transfer');
		$source = (string) ($guard['source'] ?? '');
		$error = trim(($source !== '' ? $source . ': ' : '') . $message);
		$existing_lead_id = (int) ($guard['existing_lead_id'] ?? 0);
		$data = [
			'status' => 'duplicate',
			'live_lead_id' => $existing_lead_id > 0 ? $existing_lead_id : null,
			'conversion_status' => 'duplicate_blocked_before_transfer',
			'conversion_error' => $error !== '' ? substr($error, 0, 500) : null,
			'updated_at' => $now,
		];
		$wpdb->update($wpdb->prefix . 'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_items', $data), ['id' => $item_id]);
		$this->sn_distribution_log($item_id, 'duplicate_blocked_before_transfer', $actor_id, (int) ($item->current_owner_user_id ?? 0), 0, (string) ($item->current_owner_position ?? ''), '', (int) ($item->current_step_order ?? 0), $reason ?: $error, [
			'guard_source' => $source,
			'guard_message' => $message,
			'existing_row_id' => (int) ($guard['existing_row_id'] ?? 0),
			'existing_item_id' => (int) ($guard['existing_item_id'] ?? 0),
			'existing_lead_id' => $existing_lead_id,
		]);
	}


	private function sn_mis_duplicate_hard_guard_bulk(array $items): array
	{
		global $wpdb;
		$base_guard = function (string $phone): array {
			return [
				'duplicate' => false,
				'source' => '',
				'message' => '',
				'phone_masked' => $this->sn_mask_phone($phone),
				'existing_row_id' => 0,
				'existing_batch_id' => 0,
				'existing_item_id' => 0,
				'existing_lead_id' => 0,
				'existing_owner_label' => '',
				'existing_seller_label' => '',
			];
		};
		$checks = [];
		$phones = [];
		foreach ($items as $key => $item) {
			if (! is_object($item)) { continue; }
			$item_id = (int) ($item->id ?? $key);
			if ($item_id < 1) { continue; }
			$phone = SN_Helpers::normalize_mobile((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? '') ?: ($item->phone ?? '') ?: ($item->mobile ?? '')));
			if ($phone === '') {
				$phone = $this->sn_distribution_item_phone($item);
			}
			$source_type = (string) ($item->source_type ?? '');
			$exclude_row_id = $source_type === 'mis_data_row' ? (int) ($item->source_id ?? 0) : (int) ($item->resolved_source_row_id ?? 0);
			$exclude_pool_id = $source_type === 'mis_pool' ? (int) ($item->source_id ?? 0) : (int) (($item->resolved_pool_id ?? 0) ?: ($item->pool_item_id ?? 0));
			$checks[$item_id] = [
				'phone' => $phone,
				'source_batch_id' => (int) ($item->source_batch_id ?? $item->batch_id ?? 0),
				'exclude_row_id' => $exclude_row_id,
				'exclude_pool_id' => $exclude_pool_id,
				'exclude_item_id' => (int) (($item->source_type ?? '') === 'mis_pool' && ! isset($item->current_owner_user_id) ? 0 : $item_id),
				'guard' => $base_guard($phone),
			];
			if ($phone !== '') { $phones[$phone] = true; }
		}
		if (! $checks || ! $phones) {
			return array_map(static fn($check) => $check['guard'], $checks);
		}
		$phone_list = array_values(array_keys($phones));
		$chunks = array_chunk($phone_list, 800);

		$lead_by_phone = [];
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
			foreach ($chunks as $chunk) {
				$placeholders = implode(',', array_fill(0, count($chunk), '%s'));
				$rows = $wpdb->get_results($wpdb->prepare("SELECT id, phone, seller_id, status, lead_status FROM {$wpdb->prefix}sn_leads WHERE phone IN ({$placeholders}) ORDER BY id ASC", ...$chunk)) ?: [];
				foreach ($rows as $row) {
					$p = SN_Helpers::normalize_mobile((string) ($row->phone ?? ''));
					if ($p !== '' && ! isset($lead_by_phone[$p])) { $lead_by_phone[$p] = $row; }
				}
			}
		}

		$mis_rows_by_phone = [];
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			foreach ($chunks as $chunk) {
				$placeholders = implode(',', array_fill(0, count($chunk), '%s'));
				$batch_table = $wpdb->prefix . 'sn_mis_import_batches';
				$join_batch = $this->sn_table_exists_quiet($batch_table) ? " INNER JOIN {$batch_table} b ON b.id=r.batch_id AND COALESCE(b.import_status,'') NOT IN ('draft','deleted','file_deleted','reset_deleted')" : '';
				$rows = $wpdb->get_results($wpdb->prepare("SELECT r.id, r.batch_id, r.normalized_phone, r.row_status FROM {$wpdb->prefix}sn_mis_data_rows r {$join_batch} WHERE r.normalized_phone IN ({$placeholders}) AND r.row_status='valid' ORDER BY r.id ASC", ...$chunk)) ?: [];
				foreach ($rows as $row) {
					$p = SN_Helpers::normalize_mobile((string) ($row->normalized_phone ?? ''));
					if ($p !== '') { $mis_rows_by_phone[$p][] = $row; }
				}
			}
		}

		$dist_items_by_phone = [];
		if ($this->sn_distribution_tables_ready()) {
			foreach ($chunks as $chunk) {
				$placeholders = implode(',', array_fill(0, count($chunk), '%s'));
				$args = array_merge($chunk, $chunk);
				$rows = $wpdb->get_results($wpdb->prepare(
					"SELECT id, source_type, source_id, pool_item_id, normalized_phone, customer_phone, current_owner_user_id, final_seller_user_id, status
					 FROM {$wpdb->prefix}sn_distribution_items
					 WHERE (normalized_phone IN ({$placeholders}) OR customer_phone IN ({$placeholders}))
					 AND COALESCE(status,'') NOT IN ('archived','cancelled','referral_cancelled','conversion_failed','returned_to_mis')
					 ORDER BY id ASC",
					...$args
				)) ?: [];
				foreach ($rows as $row) {
					$p1 = SN_Helpers::normalize_mobile((string) ($row->normalized_phone ?? ''));
					$p2 = SN_Helpers::normalize_mobile((string) ($row->customer_phone ?? ''));
					foreach (array_unique(array_filter([$p1, $p2])) as $p) { $dist_items_by_phone[$p][] = $row; }
				}
			}
		}

		foreach ($checks as $item_id => &$check) {
			$phone = (string) ($check['phone'] ?? '');
			if ($phone === '') { continue; }
			if (isset($lead_by_phone[$phone])) {
				$lead = $lead_by_phone[$phone];
				$seller_id = (int) ($lead->seller_id ?? 0);
				$check['guard']['duplicate'] = true;
				$check['guard']['source'] = 'sn_leads';
				$check['guard']['existing_lead_id'] = (int) ($lead->id ?? 0);
				$check['guard']['existing_seller_label'] = $seller_id ? $this->sn_user_label($seller_id) : '';
				$check['guard']['message'] = 'این شماره قبلاً به عنوان سرنخ فروش ثبت شده است.';
				continue;
			}
			foreach ((array) ($mis_rows_by_phone[$phone] ?? []) as $row) {
				if ((int) ($row->id ?? 0) === (int) ($check['exclude_row_id'] ?? 0)) { continue; }
				if ((int) ($check['source_batch_id'] ?? 0) > 0 && (int) ($row->batch_id ?? 0) === (int) ($check['source_batch_id'] ?? 0)) { continue; }
				$check['guard']['duplicate'] = true;
				$check['guard']['source'] = 'sn_mis_data_rows';
				$check['guard']['existing_row_id'] = (int) ($row->id ?? 0);
				$check['guard']['existing_batch_id'] = (int) ($row->batch_id ?? 0);
				$check['guard']['message'] = 'این شماره قبلاً در پرونده‌های MIS به عنوان ردیف معتبر ثبت شده است.';
				break;
			}
			if (! empty($check['guard']['duplicate'])) { continue; }
			foreach ((array) ($dist_items_by_phone[$phone] ?? []) as $other) {
				$other_id = (int) ($other->id ?? 0);
				if ($other_id < 1 || $other_id === (int) ($check['exclude_item_id'] ?? 0)) { continue; }
				$other_source_type = (string) ($other->source_type ?? '');
				$other_source_id = (int) ($other->source_id ?? 0);
				$other_pool_id = (int) ($other->pool_item_id ?? 0);
				if ($other_source_type === 'mis_data_row' && $other_source_id > 0 && $other_source_id === (int) ($check['exclude_row_id'] ?? 0)) { continue; }
				if ((int) ($check['exclude_pool_id'] ?? 0) > 0 && (($other_source_type === 'mis_pool' && $other_source_id === (int) $check['exclude_pool_id']) || $other_pool_id === (int) $check['exclude_pool_id'])) { continue; }
				$owner_id = (int) ($other->current_owner_user_id ?? 0);
				$seller_id = (int) ($other->final_seller_user_id ?? 0);
				$check['guard']['duplicate'] = true;
				$check['guard']['source'] = 'sn_distribution_items';
				$check['guard']['existing_item_id'] = $other_id;
				$check['guard']['existing_owner_label'] = $owner_id ? $this->sn_user_label($owner_id) : '';
				$check['guard']['existing_seller_label'] = $seller_id ? $this->sn_user_label($seller_id) : '';
				$check['guard']['message'] = 'این شماره قبلاً وارد زنجیره پخش داده شده است.';
				break;
			}
		}
		unset($check);
		$out = [];
		foreach ($checks as $item_id => $check) { $out[(int) $item_id] = $check['guard']; }
		return $out;
	}

	private function sn_mis_duplicate_hard_guard(string $phone, int $exclude_row_id = 0, int $exclude_pool_id = 0, int $exclude_item_id = 0): array
	{
		global $wpdb;
		$phone = SN_Helpers::normalize_mobile($phone);
		$out = [
			'duplicate' => false,
			'source' => '',
			'message' => '',
			'phone_masked' => $this->sn_mask_phone($phone),
			'existing_row_id' => 0,
			'existing_batch_id' => 0,
			'existing_item_id' => 0,
			'existing_lead_id' => 0,
			'existing_owner_label' => '',
			'existing_seller_label' => '',
		];
		if ($phone === '') {
			return $out;
		}

		// Resolve the original MIS source for distribution items before duplicate checks.
		// Automatic candidate selection receives hydrated rows with pool/source context,
		// but the final transfer loop reloads items from sn_distribution_items only. If
		// we do not re-resolve source_row_id here, the item's own MIS row is falsely
		// detected as a duplicate and the transfer becomes 0 even for healthy data.
		if ($exclude_item_id > 0 && ($exclude_row_id < 1 || $exclude_pool_id < 1) && $this->sn_distribution_tables_ready()) {
			$pool_join = $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_lead_pool')
				? "LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)"
				: '';
			$item_context = $wpdb->get_row($wpdb->prepare(
				"SELECT di.source_type, di.source_id, di.pool_item_id" . ($pool_join ? ", p.id AS resolved_pool_id, p.source_row_id AS resolved_source_row_id" : ", 0 AS resolved_pool_id, 0 AS resolved_source_row_id") . "
				 FROM {$wpdb->prefix}sn_distribution_items di {$pool_join}
				 WHERE di.id=%d LIMIT 1",
				$exclude_item_id
			));
			if ($item_context) {
				$ctx_source_type = (string) ($item_context->source_type ?? '');
				$ctx_source_id = (int) ($item_context->source_id ?? 0);
				$ctx_pool_id = (int) (($item_context->resolved_pool_id ?? 0) ?: ($item_context->pool_item_id ?? 0));
				$ctx_source_row_id = (int) ($item_context->resolved_source_row_id ?? 0);
				if ($exclude_pool_id < 1 && $ctx_pool_id > 0) {
					$exclude_pool_id = $ctx_pool_id;
				}
				if ($exclude_row_id < 1 && $ctx_source_type === 'mis_data_row' && $ctx_source_id > 0) {
					$exclude_row_id = $ctx_source_id;
				}
				if ($exclude_row_id < 1 && $ctx_source_row_id > 0) {
					$exclude_row_id = $ctx_source_row_id;
				}
			}
		}

		// When the source item comes from sn_mis_lead_pool, the same phone necessarily
		// exists in sn_mis_data_rows as its original source row. Treating that source
		// row as a duplicate blocks legitimate operational transfers. Resolve the
		// linked MIS row and exclude it from the hard duplicate guard.
		if ($exclude_row_id < 1 && $exclude_pool_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_lead_pool')) {
			$linked_row_id = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT source_row_id FROM {$wpdb->prefix}sn_mis_lead_pool WHERE id=%d LIMIT 1",
				$exclude_pool_id
			));
			if ($linked_row_id > 0) {
				$exclude_row_id = $linked_row_id;
			}
		}

		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
			$lead = $wpdb->get_row($wpdb->prepare("SELECT id, seller_id, status, lead_status FROM {$wpdb->prefix}sn_leads WHERE phone=%s ORDER BY id ASC LIMIT 1", $phone));
			if ($lead) {
				$out['duplicate'] = true;
				$out['source'] = 'sn_leads';
				$out['existing_lead_id'] = (int) ($lead->id ?? 0);
				$seller_id = (int) ($lead->seller_id ?? 0);
				$out['existing_seller_label'] = $seller_id ? $this->sn_user_label($seller_id) : '';
				$out['message'] = 'این شماره قبلاً به عنوان سرنخ فروش ثبت شده است.';
				return $out;
			}
		}

		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
			$batch_table = $wpdb->prefix . 'sn_mis_import_batches';
			$join_batch = $this->sn_table_exists_quiet($batch_table) ? " INNER JOIN {$batch_table} b ON b.id=r.batch_id AND COALESCE(b.import_status,'') NOT IN ('draft','deleted','file_deleted','reset_deleted')" : '';
			$row = $wpdb->get_row($wpdb->prepare(
				"SELECT r.id, r.batch_id, r.row_status FROM {$wpdb->prefix}sn_mis_data_rows r {$join_batch} WHERE r.normalized_phone=%s AND r.row_status='valid' AND r.id<>%d ORDER BY r.id ASC LIMIT 1",
				$phone,
				$exclude_row_id
			));
			if ($row) {
				$out['duplicate'] = true;
				$out['source'] = 'sn_mis_data_rows';
				$out['existing_row_id'] = (int) ($row->id ?? 0);
				$out['existing_batch_id'] = (int) ($row->batch_id ?? 0);
				$out['message'] = 'این شماره قبلاً در پرونده‌های MIS به عنوان ردیف معتبر ثبت شده است.';
				$dist = $this->sn_mis_distribution_trace_for_data_row_id((int) ($row->id ?? 0));
				if (! empty($dist['current_owner_label'])) { $out['existing_owner_label'] = (string) $dist['current_owner_label']; }
				if (! empty($dist['final_seller_label'])) { $out['existing_seller_label'] = (string) $dist['final_seller_label']; }
				return $out;
			}
		}

		if ($this->sn_distribution_tables_ready()) {
			$items_table = $wpdb->prefix . 'sn_distribution_items';
			$phone_expr_parts = ["NULLIF(di.normalized_phone,'')", "NULLIF(di.customer_phone,'')"];
			$rows_join = '';
			if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows')) {
				$rows_join = "LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON di.source_type='mis_data_row' AND r.id=di.source_id";
				$phone_expr_parts[] = "NULLIF(r.normalized_phone,'')";
				$phone_expr_parts[] = "NULLIF(r.customer_phone,'')";
			}
			$pool_join = '';
			if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_lead_pool')) {
				$pool_join = "LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON (di.source_type='mis_pool' AND p.id=di.source_id) OR p.id=di.pool_item_id";
				$phone_expr_parts[] = "NULLIF(p.normalized_phone,'')";
				$phone_expr_parts[] = "NULLIF(p.customer_phone,'')";
			}
			$phone_expr = 'COALESCE(' . implode(', ', $phone_expr_parts) . ')';
			$item = $wpdb->get_row($wpdb->prepare(
				"SELECT di.* FROM {$items_table} di {$rows_join} {$pool_join}
				 WHERE {$phone_expr}=%s
				 AND di.id<>%d
				 AND NOT (di.source_type='mis_data_row' AND di.source_id=%d)
				 AND NOT (di.source_type='mis_pool' AND di.source_id=%d)
				 AND COALESCE(di.status,'') NOT IN ('archived','cancelled','referral_cancelled','conversion_failed','returned_to_mis')
				 ORDER BY di.id ASC LIMIT 1",
				$phone,
				$exclude_item_id,
				$exclude_row_id,
				$exclude_pool_id
			));
			if ($item) {
				$out['duplicate'] = true;
				$out['source'] = 'sn_distribution_items';
				$out['existing_item_id'] = (int) ($item->id ?? 0);
				$owner_id = (int) ($item->current_owner_user_id ?? 0);
				$seller_id = (int) ($item->final_seller_user_id ?? 0);
				$out['existing_owner_label'] = $owner_id ? $this->sn_user_label($owner_id) : '';
				$out['existing_seller_label'] = $seller_id ? $this->sn_user_label($seller_id) : '';
				$out['message'] = 'این شماره قبلاً وارد زنجیره پخش داده شده است.';
				return $out;
			}
		}
		return $out;
	}

	private function sn_mis_distribution_trace_for_data_row_id(int $row_id): array
	{
		global $wpdb;
		$out = [
			'distribution_item_id' => 0,
			'distribution_status' => '',
			'current_owner_user_id' => 0,
			'current_owner_label' => '',
			'current_owner_position' => '',
			'final_seller_user_id' => 0,
			'final_seller_label' => '',
			'live_lead_id' => 0,
		];
		if ($row_id < 1 || ! $this->sn_distribution_tables_ready()) {
			return $out;
		}
		$items_table = $wpdb->prefix . 'sn_distribution_items';
		$pool_table = $wpdb->prefix . 'sn_mis_lead_pool';
		if ($this->sn_table_exists_quiet($pool_table)) {
			$item = $wpdb->get_row($wpdb->prepare(
				"SELECT di.*
				 FROM {$items_table} di
				 LEFT JOIN {$pool_table} p ON (di.source_type='mis_pool' AND p.id=di.source_id) OR p.id=di.pool_item_id
				 WHERE (di.source_type='mis_data_row' AND di.source_id=%d) OR p.source_row_id=%d
				 ORDER BY di.id ASC LIMIT 1",
				$row_id,
				$row_id
			));
		} else {
			$item = $wpdb->get_row($wpdb->prepare(
				"SELECT di.* FROM {$items_table} di WHERE di.source_type='mis_data_row' AND di.source_id=%d ORDER BY di.id ASC LIMIT 1",
				$row_id
			));
		}
		if (! $item) {
			return $out;
		}
		$out['distribution_item_id'] = (int) ($item->id ?? 0);
		$out['distribution_status'] = (string) ($item->status ?? '');
		$out['current_owner_user_id'] = (int) ($item->current_owner_user_id ?? 0);
		$out['current_owner_label'] = $out['current_owner_user_id'] ? $this->sn_user_label($out['current_owner_user_id']) : '';
		$out['current_owner_position'] = (string) ($item->current_owner_position ?? '');
		$out['final_seller_user_id'] = (int) ($item->final_seller_user_id ?? 0);
		$out['final_seller_label'] = $out['final_seller_user_id'] ? $this->sn_user_label($out['final_seller_user_id']) : '';
		$out['live_lead_id'] = (int) ($item->live_lead_id ?? 0);
		return $out;
	}

	private function sn_mis_trace_label(array $trace): string
	{
		$source = (string) ($trace['source'] ?? '');
		if ($source === 'same_file') {
			return 'تکراری داخل همین فایل' . (! empty($trace['first_row_number']) ? '؛ ردیف اول: ' . (int) $trace['first_row_number'] : '');
		}
		if ($source === 'sn_leads') {
			$parts = ['لید زنده #' . (int) ($trace['lead_id'] ?? 0)];
			if (! empty($trace['lead_seller_label'])) { $parts[] = 'فروشنده: ' . (string) $trace['lead_seller_label']; }
			if (! empty($trace['lead_status'])) { $parts[] = 'وضعیت: ' . $this->sn_portal_status_label((string) $trace['lead_status']); }
			return implode(' | ', array_filter($parts));
		}
		if ($source === 'mis_data_rows') {
			$parts = [];
			$batch = trim((string) ($trace['existing_batch_code'] ?? '')) ?: ('#' . (int) ($trace['existing_batch_id'] ?? 0));
			$parts[] = 'MIS ' . $batch . ' / ردیف #' . (int) ($trace['existing_row_id'] ?? 0);
			if (! empty($trace['existing_batch_title'])) { $parts[] = (string) $trace['existing_batch_title']; }
			if (! empty($trace['distribution_item_id'])) { $parts[] = 'آیتم پخش #' . (int) $trace['distribution_item_id']; }
			if (! empty($trace['current_owner_label'])) { $parts[] = 'مالک فعلی: ' . (string) $trace['current_owner_label']; }
			if (! empty($trace['final_seller_label'])) { $parts[] = 'فروشنده نهایی: ' . (string) $trace['final_seller_label']; }
			if (! empty($trace['distribution_status'])) { $parts[] = 'وضعیت پخش: ' . $this->sn_portal_status_label((string) $trace['distribution_status']); }
			elseif (! empty($trace['existing_row_status'])) { $parts[] = 'وضعیت ردیف: ' . $this->sn_portal_status_label((string) $trace['existing_row_status']); }
			return implode(' | ', array_filter($parts));
		}
		return 'محل تکرار قابل تشخیص نیست.';
	}

	private function sn_mis_assignment_traces_for_batch(int $batch_id, int $limit = 30): array
	{
		global $wpdb;
		if ($batch_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_data_rows') || ! $this->sn_distribution_tables_ready()) {
			return [];
		}
		$limit = max(1, min(100, $limit));
		$rows = $wpdb->get_results($wpdb->prepare(
			"SELECT r.id row_id, r.row_number, r.normalized_phone, r.customer_phone, r.customer_name, b.batch_code,
				di.id item_id, di.status distribution_status, di.current_owner_user_id, di.current_owner_position, di.final_seller_user_id, di.live_lead_id, di.updated_at
			 FROM {$wpdb->prefix}sn_mis_data_rows r
			 LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id=r.batch_id
			 INNER JOIN {$wpdb->prefix}sn_distribution_items di ON di.source_type='mis_data_row' AND di.source_id=r.id
			 WHERE r.batch_id=%d AND r.row_status='valid'
			 ORDER BY di.updated_at DESC, di.id DESC LIMIT %d",
			$batch_id,
			$limit
		)) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$owner_id = (int) ($row->current_owner_user_id ?? 0);
			$seller_id = (int) ($row->final_seller_user_id ?? 0);
			$out[] = [
				'row_id' => (int) ($row->row_id ?? 0),
				'row_number' => (int) ($row->row_number ?? 0),
				'item_id' => (int) ($row->item_id ?? 0),
				'phone' => $this->sn_mask_phone((string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''))),
				'customer_name' => (string) ($row->customer_name ?? ''),
				'batch_code' => (string) ($row->batch_code ?? ''),
				'distribution_status' => (string) ($row->distribution_status ?? ''),
				'current_owner_user_id' => $owner_id,
				'current_owner_label' => $owner_id ? $this->sn_user_label($owner_id) : '',
				'current_owner_position' => (string) ($row->current_owner_position ?? ''),
				'final_seller_user_id' => $seller_id,
				'final_seller_label' => $seller_id ? $this->sn_user_label($seller_id) : '',
				'live_lead_id' => (int) ($row->live_lead_id ?? 0),
				'updated_at' => (string) ($row->updated_at ?? ''),
			];
		}
		return $out;
	}


	public function handle_mis_import_csv(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_import_csv');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		if (! $this->sn_mis_table_exists('sn_mis_import_batches') || ! $this->sn_mis_table_exists('sn_mis_data_rows')) {
			update_option('sn_mis_last_report', ['action' => 'csv_import', 'batch_id' => $batch_id, 'rows_seen' => 0, 'rows_imported' => 0, 'valid' => 0, 'duplicate' => 0, 'invalid' => 0, 'warnings' => ['mis_tables_missing'], 'updated_at' => current_time('mysql')], false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		$batch = $batch_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_import_batches WHERE id=%d", $batch_id)) : null;
		$report = [
			'action' => 'csv_import',
			'batch_id' => $batch_id,
			'rows_seen' => 0,
			'rows_imported' => 0,
			'valid' => 0,
			'duplicate' => 0,
			'invalid' => 0,
			'duplicate_in_file' => 0,
			'duplicate_existing_rows' => 0,
			'duplicate_same_batch' => 0,
			'skipped_same_batch_reimport' => 0,
			'cleanup_same_batch_duplicates_deleted' => 0,
			'duplicate_in_leads' => 0,
			'detected_headers' => [],
			'normalized_headers' => [],
			'detected_phone_columns' => [],
			'invalid_reasons' => [],
			'invalid_samples' => [],
			'duplicate_samples' => [],
			'operator_message' => '',
			'upload_key' => 'mis_csv',
			'parser_debug' => [],
			'warnings' => [],
			'updated_at' => current_time('mysql'),
		];
		if (! $batch || empty($_FILES['mis_csv']['tmp_name'])) {
			$report['warnings'][] = 'batch_or_file_missing';
			update_option('sn_mis_last_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		$report['cleanup_same_batch_duplicates_deleted'] = $this->sn_mis_cleanup_same_batch_duplicate_rows($batch_id);
		$file = $_FILES['mis_csv']; // phpcs:ignore
		$report['uploaded_file'] = [
			'name' => sanitize_file_name((string) ($file['name'] ?? '')),
			'mime_type' => sanitize_text_field((string) ($file['type'] ?? '')),
			'size' => (int) ($file['size'] ?? 0),
		];
		if ((int) ($file['size'] ?? 0) > 5 * 1024 * 1024) { $report['warnings'][] = 'file_too_large'; update_option('sn_mis_last_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$parsed = $this->sn_read_tabular_upload($file, ['csv' => 'text/csv', 'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
		if (current_user_can('manage_options')) {
			$report['parser_debug'] = (array) ($parsed['debug'] ?? []);
		} else {
			$debug = (array) ($parsed['debug'] ?? []);
			$report['parser_debug'] = [
				'original_filename' => sanitize_file_name((string) ($debug['original_filename'] ?? $report['uploaded_file']['name'])),
				'mime_type' => sanitize_text_field((string) ($debug['mime_type'] ?? $report['uploaded_file']['mime_type'])),
				'extension' => sanitize_key((string) ($debug['extension'] ?? '')),
				'file_size' => (int) ($debug['file_size'] ?? 0),
				'delimiter_selected' => sanitize_text_field((string) ($debug['delimiter_selected'] ?? '')),
				'header_parsed_cells' => array_map('sanitize_text_field', (array) ($debug['header_parsed_cells'] ?? [])),
				'normalized_header_cells' => array_map('sanitize_text_field', (array) ($debug['normalized_header_cells'] ?? [])),
			];
		}
		if (! empty($parsed['errors'])) {
			$report['warnings'] = array_merge($report['warnings'], (array) $parsed['errors']);
			if (in_array('header_blank', (array) $parsed['errors'], true) || in_array('header_missing', (array) $parsed['errors'], true)) {
				$report['operator_message'] = 'ردیف عنوان ستون خوانده نشد. فایل را به صورت CSV UTF-8 ذخیره کنید و مطمئن شوید ردیف اول شامل عنوان ستون مثل «شماره اول» است.';
			}
			update_option('sn_mis_last_report', $report, false);
			wp_safe_redirect(wp_get_referer() ?: home_url('/'));
			exit;
		}
		if (empty($parsed['rows'])) { $report['warnings'][] = 'file_empty'; update_option('sn_mis_last_report', $report, false); wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$headers = (array) ($parsed['headers'] ?? []);
		$first_row = (array) reset($parsed['rows']);
		$first_normalized = $this->sn_normalize_row_keys($first_row);
		$phone_columns = $this->sn_mis_detect_phone_columns($headers ?: array_keys($first_row), $first_normalized);
		$report['detected_headers'] = $phone_columns['headers'];
		$report['normalized_headers'] = array_map([$this, 'sn_norm_header_key'], $headers ?: array_keys($first_row));
		$report['detected_phone_columns'] = [
			'primary' => $phone_columns['primary_label'],
			'secondary' => $phone_columns['secondary_label'],
		];
		if ($phone_columns['primary'] === '' && $phone_columns['secondary'] === '') {
			$report['warnings'][] = 'ستون شماره موبایل پیدا نشد';
			$report['operator_message'] = 'ستون شماره پیدا نشد. عنوان ستون باید یکی از این‌ها باشد: شماره اول، موبایل، شماره موبایل، شماره تماس.';
		}
		$preupload_phones = [];
		foreach ((array) $parsed['rows'] as $pre_raw_row) {
			$pre_row = $this->sn_normalize_row_keys((array) $pre_raw_row);
			$pre_cols = $this->sn_mis_detect_phone_columns(array_keys((array) $pre_raw_row), $pre_row);
			if ($pre_cols['primary'] === '' && $phone_columns['primary'] !== '') { $pre_cols = $phone_columns; }
			$pre_phone = $this->sn_mis_pick_phone($pre_row, $pre_cols);
			if (! empty($pre_phone['normalized'])) { $preupload_phones[$pre_phone['normalized']] = true; }
		}
		if ($preupload_phones) {
			$linked = $this->sn_mis_batch_delete_audit($batch_id);
			if ((int) ($linked['distribution_items'] ?? 0) === 0 && (int) ($linked['plan_items'] ?? 0) === 0) {
				$report['preupload_stale_purge'] = $this->sn_mis_purge_unlocked_phone_traces(array_keys($preupload_phones), $batch_id);
			} else {
				$report['warnings'][] = 'ردپای فایل قبلی پاک نشد؛ این پرونده به آیتم پخش یا برنامه توزیع وصل است.';
			}
		}
		$seen = [];
		$max_rows = 5000;
		foreach ((array) $parsed['rows'] as $raw_row) {
			$report['rows_seen']++;
			if ($report['rows_seen'] > $max_rows) { $report['warnings'][] = 'safe_row_limit_reached'; break; }
			$row = $this->sn_normalize_row_keys((array) $raw_row);
			$row_phone_columns = $this->sn_mis_detect_phone_columns(array_keys((array) $raw_row), $row);
			if ($row_phone_columns['primary'] === '' && $phone_columns['primary'] !== '') {
				$row_phone_columns = $phone_columns;
			}
			$phone_info = $this->sn_mis_pick_phone($row, $row_phone_columns);
			$phone_raw = $phone_info['raw'];
			$normalized = $phone_info['normalized'];
			$phone_reason = $phone_info['reason'];
			$status = 'valid'; $dup_reason = ''; $duplicate_trace = [];
			if ($phone_reason !== '') {
				$status = 'invalid';
				$dup_reason = $phone_reason;
			} elseif (isset($seen[$normalized])) {
				$status = 'duplicate';
				$dup_reason = 'duplicate_in_file';
				$duplicate_trace = [
					'source' => 'same_file',
					'phone_masked' => $this->sn_mask_phone($normalized),
					'first_row_number' => (int) $seen[$normalized],
				];
			} else {
				$existing_same_batch_row = $this->sn_mis_existing_row_for_phone_in_batch($normalized, $batch_id);
				if ($existing_same_batch_row) {
					$duplicate_trace = $this->sn_mis_duplicate_trace_for_phone($normalized, $batch_id, (int) ($existing_same_batch_row->id ?? 0));
					$duplicate_trace['source'] = 'same_batch_reimport';
					$duplicate_trace['existing_row_id'] = (int) ($existing_same_batch_row->id ?? 0);
					$duplicate_trace['existing_batch_id'] = $batch_id;
					$duplicate_trace['existing_row_status'] = (string) ($existing_same_batch_row->row_status ?? '');
					$status = 'duplicate';
					$dup_reason = 'duplicate_in_same_batch';
				} else {
					$duplicate_trace = $this->sn_mis_duplicate_trace_for_phone($normalized, $batch_id, 0);
					if (! empty($duplicate_trace['existing_row_id'])) {
						$status = 'duplicate';
						$dup_reason = 'duplicate_in_mis';
					} elseif (! empty($duplicate_trace['lead_id'])) {
						$status = 'duplicate';
						$dup_reason = 'duplicate_in_leads';
					}
				}
			}
			if ($normalized !== '' && $phone_reason === '' && ! isset($seen[$normalized])) {
				$seen[$normalized] = (int) $report['rows_seen'];
			}
			if ($status === 'invalid') {
				$report['invalid_reasons'][$dup_reason] = (int) ($report['invalid_reasons'][$dup_reason] ?? 0) + 1;
				if (count($report['invalid_samples']) < 10) {
					$report['invalid_samples'][] = [
						'row_number' => $report['rows_seen'],
						'raw_value' => $phone_raw,
						'normalized_value' => $normalized,
						'reason' => $dup_reason,
						'source_column' => $phone_info['source_column'],
					];
				}
			} elseif ($status === 'duplicate') {
				if ($dup_reason === 'duplicate_in_file') { $report['duplicate_in_file']++; }
				if ($dup_reason === 'duplicate_in_same_batch') { $report['duplicate_same_batch']++; }
				if ($dup_reason === 'duplicate_in_mis') { $report['duplicate_existing_rows']++; }
				if ($dup_reason === 'duplicate_in_leads') { $report['duplicate_in_leads']++; }
				if (count($report['duplicate_samples']) < 20) {
					$report['duplicate_samples'][] = [
						'row_number' => $report['rows_seen'],
						'raw_value' => $phone_raw,
						'normalized_value' => $normalized,
						'reason' => $dup_reason,
						'source_column' => $phone_info['source_column'],
						'trace' => $duplicate_trace,
						'trace_label' => $this->sn_mis_trace_label((array) $duplicate_trace),
					];
				}
			}
			if ($status === 'duplicate' && in_array($dup_reason, ['duplicate_in_file', 'duplicate_in_same_batch'], true)) {
				$report['duplicate']++;
				$report['skipped_same_batch_reimport']++;
				continue;
			}
			$payload = [
				'raw_columns' => count((array) $raw_row),
				'row_number' => $report['rows_seen'],
				'raw_phone' => $phone_raw,
				'normalized_phone' => $normalized,
				'phone_source_column' => $phone_info['source_column'],
				'phone_invalid_reason' => $dup_reason,
				'duplicate_trace' => $duplicate_trace,
				'detected_phone_columns' => $report['detected_phone_columns'],
				'phone_2' => sanitize_text_field((string) ($row['phone_2'] ?? '')),
				'address' => sanitize_textarea_field((string) ($row['address'] ?? '')),
				'notes' => sanitize_textarea_field((string) ($row['notes'] ?? '')),
			];
			$inserted = $wpdb->insert($wpdb->prefix . 'sn_mis_data_rows', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_data_rows', [
				'batch_id' => $batch_id, 'row_number' => $report['rows_seen'],
				'customer_name' => sanitize_text_field((string) ($row['name'] ?? $row['display_name'] ?? '')),
				'customer_phone' => $phone_raw, 'normalized_phone' => $normalized,
				'city' => sanitize_text_field((string) ($row['city'] ?? '')),
				'province' => sanitize_text_field((string) ($row['province'] ?? '')),
				'source_meta' => wp_json_encode($payload, JSON_UNESCAPED_UNICODE),
				'row_status' => $status, 'duplicate_reason' => $dup_reason ?: null,
			]));
			if ($inserted === false) {
				$report['warnings'][] = 'row_insert_failed_' . $report['rows_seen'];
				if ($wpdb->last_error) {
					$report['warnings'][] = 'db_error_' . substr(sanitize_text_field($wpdb->last_error), 0, 120);
				}
				continue;
			}
			$report['rows_imported']++;
			$report[$status === 'duplicate' ? 'duplicate' : $status]++;
		}
		$batch_counts = $this->sn_mis_recount_batch_rows($batch_id);
		$wpdb->update($wpdb->prefix . 'sn_mis_import_batches', [
			'import_file_name' => sanitize_file_name((string) $file['name']),
			'import_status' => 'imported',
			'total_rows' => (int) ($batch_counts['total'] ?? 0),
			'valid_rows' => (int) ($batch_counts['valid'] ?? 0),
			'duplicate_rows' => (int) ($batch_counts['duplicate'] ?? 0),
			'invalid_rows' => (int) ($batch_counts['invalid'] ?? 0),
			'updated_at' => current_time('mysql'),
		], ['id' => $batch_id]);
		$this->sn_mis_log($batch_id, 'csv_imported', null, $report, 'import into MIS staging only');
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	public function handle_mis_assign_batch(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_assign_batch');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_import_batches') || ! $this->sn_mis_table_exists('sn_mis_data_rows')) { wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		if (! $batch_id || ! $manager_id || $this->sn_hr_position_for_user($manager_id) !== 'sales_manager') { wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$before = ['unassigned_valid' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_data_rows WHERE batch_id=%d AND row_status='valid' AND assigned_manager_user_id IS NULL", $batch_id))];
		$wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}sn_mis_data_rows SET assigned_manager_user_id=%d, assigned_at=%s WHERE batch_id=%d AND row_status='valid' AND assigned_manager_user_id IS NULL", $manager_id, current_time('mysql'), $batch_id));
		$assigned = (int) $wpdb->rows_affected;
		$wpdb->update($wpdb->prefix . 'sn_mis_import_batches', ['assigned_manager_user_id' => $manager_id, 'import_status' => 'assigned_to_manager', 'updated_at' => current_time('mysql')], ['id' => $batch_id]);
		$report = ['action' => 'assign_batch_to_sales_manager', 'batch_id' => $batch_id, 'manager_user_id' => $manager_id, 'assigned_rows' => $assigned, 'updated_at' => current_time('mysql')];
		$this->sn_mis_log($batch_id, 'assigned_to_manager', $before, $report, $reason);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}



	private function sn_distribution_item_has_invoice_lock(int $item_id): bool
	{
		global $wpdb;
		$item_id = absint($item_id);
		if ($item_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) {
			return false;
		}
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		$cols = $this->sn_table_columns($invoice_table);
		if (! in_array('lead_id', $cols, true)) {
			return false;
		}
		$virtual_lead_id = $this->sn_distribution_virtual_lead_id($item_id);
		$count = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$invoice_table} WHERE lead_id=%d AND COALESCE(status,'') NOT IN ('cancelled','rejected','deleted')",
			$virtual_lead_id
		));
		return $count > 0;
	}

	public function handle_mis_return_assignments(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_return_assignments');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); (new SN_Migration_Service())->migrate(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		$include_distribution = ! empty($_POST['include_distribution']);
		$limit = max(1, min(2000, absint($_POST['limit'] ?? 500)));
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? 'برگشت تخصیص MIS'));
		$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
		$pool_table = $wpdb->prefix . 'sn_mis_lead_pool';
		$items_table = $wpdb->prefix . 'sn_distribution_items';
		$report = [
			'action' => $run_mode === 'apply' ? 'mis_return_assignments_apply' : 'mis_return_assignments_dry_run',
			'batch_id' => $batch_id,
			'manager_user_id' => $manager_id,
			'include_distribution' => $include_distribution,
			'limit' => $limit,
			'eligible_rows' => 0,
			'returned_rows' => 0,
			'returned_pool_rows' => 0,
			'returned_distribution_items' => 0,
			'recovered_orphan_distribution_items' => 0,
			'hard_batch_distribution_items' => 0,
			'blocked_converted' => 0,
			'blocked_invoice' => 0,
			'skipped_has_distribution' => 0,
			'preview' => [],
			'errors' => [],
			'updated_at' => current_time('mysql'),
		];
		if (! $batch_id) { $report['errors'][] = 'batch_required'; }
		if ($run_mode === 'apply' && $confirm !== 'RETURN') { $report['errors'][] = 'confirmation_required'; }
		if (! $this->sn_mis_table_exists('sn_mis_data_rows')) { $report['errors'][] = 'mis_rows_table_missing'; }
		if ($include_distribution && ! $this->sn_distribution_tables_ready()) { $report['errors'][] = 'distribution_tables_missing'; }
		$eligible = [];
		if (empty($report['errors'])) {
			$where = ['r.batch_id=%d', 'r.row_status=%s', 'r.assigned_manager_user_id IS NOT NULL', 'r.assigned_manager_user_id>0'];
			$args = [$batch_id, 'valid'];
			if ($manager_id > 0) { $where[] = 'r.assigned_manager_user_id=%d'; $args[] = $manager_id; }
			$args[] = $limit;
			$rows = $wpdb->get_results($wpdb->prepare("SELECT r.* FROM {$rows_table} r WHERE " . implode(' AND ', $where) . " ORDER BY r.id ASC LIMIT %d", ...$args)) ?: [];
			foreach ($rows as $row) {
				$row_id = (int) $row->id;
				$pool_ids = $this->sn_mis_table_exists('sn_mis_lead_pool') ? array_map('intval', (array) $wpdb->get_col($wpdb->prepare("SELECT id FROM {$pool_table} WHERE source_row_id=%d", $row_id))) : [];
				$item_args = [$row_id];
				$item_sql = "SELECT * FROM {$items_table} WHERE (source_type='mis_data_row' AND source_id=%d";
				if ($pool_ids) {
					$item_sql .= ' OR pool_item_id IN (' . implode(',', array_fill(0, count($pool_ids), '%d')) . ') OR (source_type=\'mis_pool\' AND source_id IN (' . implode(',', array_fill(0, count($pool_ids), '%d')) . '))';
					$item_args = array_merge($item_args, $pool_ids, $pool_ids);
				} else {
					$item_sql .= ')';
				}
				$items = $this->sn_distribution_tables_ready() ? ($wpdb->get_results($wpdb->prepare($item_sql, ...$item_args)) ?: []) : [];
				$has_distribution = ! empty($items) || ! empty($pool_ids);
				$converted = false;
				$invoice_locked = false;
				foreach ($items as $item) {
					$status = sanitize_key((string) ($item->status ?? ''));
					$item_id_for_lock = (int) ($item->id ?? 0);
					if ((int) ($item->live_lead_id ?? 0) > 0 || in_array($status, ['converted','lead_created','live_lead_created'], true)) {
						$converted = true;
						break;
					}
					if ($item_id_for_lock > 0 && $this->sn_distribution_item_has_invoice_lock($item_id_for_lock)) {
						$invoice_locked = true;
						break;
					}
				}
				if ($converted) { $report['blocked_converted']++; continue; }
				if ($invoice_locked) { $report['blocked_invoice']++; continue; }
				if ($has_distribution && ! $include_distribution) { $report['skipped_has_distribution']++; continue; }
				$eligible[] = ['row' => $row, 'pool_ids' => $pool_ids, 'items' => $items];
				if (count($report['preview']) < 25) {
					$report['preview'][] = [
						'row_id' => $row_id,
						'name' => (string) ($row->customer_name ?? ''),
						'phone' => $this->sn_mask_phone((string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''))),
						'manager' => $this->sn_user_label((int) ($row->assigned_manager_user_id ?? 0)),
						'pool_count' => count($pool_ids),
						'distribution_item_count' => count($items),
					];
				}
			}

			// Backward-compatible recovery: older MIS quick assignment created distribution items
			// without syncing sn_mis_data_rows.assigned_manager_user_id. In that state the
			// normal return query sees eligible_rows=0 while the manager still owns the
			// numbers. When include_distribution is explicitly checked, recover those
			// safe orphaned distribution items too. Only live/converted/invoiced items
			// stay locked; seller statuses are snapshotted in logs and reset on return.
			if ($include_distribution && $this->sn_distribution_tables_ready()) {
				$seen_row_ids = [];
				foreach ($eligible as $entry) {
					if (! empty($entry['row']->id)) { $seen_row_ids[(int) $entry['row']->id] = true; }
				}
				$remaining_limit = max(0, $limit - count($eligible));
				if ($remaining_limit > 0) {
					$orphan_where = [
						'r.batch_id=%d',
						"r.row_status='valid'",
						"di.source_type='mis_data_row'",
						'(di.live_lead_id IS NULL OR di.live_lead_id=0)',
						"COALESCE(di.status,'') NOT IN ('converted','lead_created','live_lead_created','cancelled','archived','referral_cancelled','returned_to_mis')",
					];
					$orphan_args = [$batch_id];
					if ($manager_id > 0) {
						$orphan_where[] = 'di.current_owner_user_id=%d';
						$orphan_args[] = $manager_id;
					} else {
						// "All managers in this case" must recover every active distribution item in the batch,
						// even if an earlier broken return/sync left owner fields inconsistent.
						$orphan_where[] = '1=1';
					}
					if ($seen_row_ids) {
						$orphan_where[] = 'r.id NOT IN (' . implode(',', array_fill(0, count($seen_row_ids), '%d')) . ')';
						$orphan_args = array_merge($orphan_args, array_keys($seen_row_ids));
					}
					$orphan_args[] = $remaining_limit;
					$orphan_rows = $wpdb->get_results($wpdb->prepare(
						"SELECT r.*, di.id AS orphan_distribution_item_id, di.current_owner_user_id AS orphan_owner_user_id, di.current_owner_position AS orphan_owner_position, di.status AS orphan_distribution_status
						 FROM {$rows_table} r
						 INNER JOIN {$items_table} di ON di.source_type='mis_data_row' AND di.source_id=r.id
						 WHERE " . implode(' AND ', $orphan_where) . "
						 ORDER BY r.id ASC LIMIT %d",
						...$orphan_args
					)) ?: [];
					foreach ($orphan_rows as $row) {
						$orphan_item_id = (int) ($row->orphan_distribution_item_id ?? 0);
						if ($orphan_item_id > 0 && $this->sn_distribution_item_has_invoice_lock($orphan_item_id)) {
							$report['blocked_invoice']++;
							continue;
						}
						$item = (object) [
							'id' => $orphan_item_id,
							'current_owner_user_id' => (int) ($row->orphan_owner_user_id ?? 0),
							'current_owner_position' => (string) ($row->orphan_owner_position ?? ''),
							'status' => (string) ($row->orphan_distribution_status ?? ''),
						];
						$eligible[] = ['row' => $row, 'pool_ids' => [], 'items' => [$item], 'recovered_orphan' => true];
						$report['recovered_orphan_distribution_items']++;
						if (count($report['preview']) < 25) {
							$report['preview'][] = [
								'row_id' => (int) ($row->id ?? 0),
								'name' => (string) ($row->customer_name ?? ''),
								'phone' => $this->sn_mask_phone((string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''))),
								'manager' => $this->sn_user_label((int) ($row->orphan_owner_user_id ?? 0)),
								'pool_count' => 0,
								'distribution_item_count' => 1,
								'recovered_orphan' => true,
							];
						}
					}
				}
			}

			// Final hard fallback for real-world recovery cases:
			// Some historical/bulk paths left items visible in the sales-manager panel while the
			// MIS row assignment columns or source-row join context were not enough for the
			// conservative return selector. When the operator explicitly checks
			// include_distribution, scan distribution_items by batch_id itself and return every
			// safe, non-converted, non-invoiced item from the selected MIS batch.
			if ($include_distribution && $this->sn_distribution_tables_ready()) {
				$seen_item_ids = [];
				$seen_row_ids_for_hard = [];
				foreach ($eligible as $entry) {
					if (! empty($entry['row']->id)) { $seen_row_ids_for_hard[(int) $entry['row']->id] = true; }
					foreach ((array) ($entry['items'] ?? []) as $seen_item) {
						if (! empty($seen_item->id)) { $seen_item_ids[(int) $seen_item->id] = true; }
					}
				}
				$hard_remaining_limit = max(0, $limit - count($eligible));
				if ($hard_remaining_limit > 0) {
					$hard_where = [
						'(COALESCE(di.batch_id, r.batch_id)= %d OR r.batch_id=%d)',
						'r.id IS NOT NULL',
						"r.row_status='valid'",
						'(di.live_lead_id IS NULL OR di.live_lead_id=0)',
						"COALESCE(di.status,'') NOT IN ('converted','lead_created','live_lead_created','cancelled','archived','referral_cancelled')",
					];
					$hard_args = [$batch_id, $batch_id];
					if ($manager_id > 0) {
						$hard_where[] = '(di.current_owner_user_id=%d OR r.assigned_manager_user_id=%d)';
						$hard_args[] = $manager_id;
						$hard_args[] = $manager_id;
					}
					if ($seen_item_ids) {
						$hard_where[] = 'di.id NOT IN (' . implode(',', array_fill(0, count($seen_item_ids), '%d')) . ')';
						$hard_args = array_merge($hard_args, array_keys($seen_item_ids));
					}
					$hard_args[] = $hard_remaining_limit;
					$hard_rows = $wpdb->get_results($wpdb->prepare(
						"SELECT r.*, di.id AS hard_distribution_item_id, di.current_owner_user_id AS hard_owner_user_id, di.current_owner_position AS hard_owner_position, di.final_seller_user_id AS hard_final_seller_user_id, di.status AS hard_distribution_status, di.seller_contact_status AS hard_seller_contact_status, di.seller_customer_name AS hard_seller_customer_name
						 FROM {$items_table} di
						 LEFT JOIN {$pool_table} p ON (di.pool_item_id=p.id OR (di.source_type='mis_pool' AND di.source_id=p.id))
						 LEFT JOIN {$rows_table} r ON ((di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id))
						 WHERE " . implode(' AND ', $hard_where) . "
						 ORDER BY di.id ASC LIMIT %d",
						...$hard_args
					)) ?: [];
					foreach ($hard_rows as $row) {
						$hard_item_id = (int) ($row->hard_distribution_item_id ?? 0);
						if ($hard_item_id < 1 || isset($seen_item_ids[$hard_item_id])) { continue; }
						if ($this->sn_distribution_item_has_invoice_lock($hard_item_id)) {
							$report['blocked_invoice']++;
							continue;
						}
						$item = (object) [
							'id' => $hard_item_id,
							'current_owner_user_id' => (int) ($row->hard_owner_user_id ?? 0),
							'current_owner_position' => (string) ($row->hard_owner_position ?? ''),
							'final_seller_user_id' => (int) ($row->hard_final_seller_user_id ?? 0),
							'status' => (string) ($row->hard_distribution_status ?? ''),
							'seller_contact_status' => (string) ($row->hard_seller_contact_status ?? ''),
							'seller_customer_name' => (string) ($row->hard_seller_customer_name ?? ''),
						];
						$eligible[] = ['row' => $row, 'pool_ids' => [], 'items' => [$item], 'hard_batch_distribution_recovery' => true];
						$seen_item_ids[$hard_item_id] = true;
						$seen_row_ids_for_hard[(int) ($row->id ?? 0)] = true;
						$report['recovered_orphan_distribution_items']++;
						$report['hard_batch_distribution_items'] = (int) ($report['hard_batch_distribution_items'] ?? 0) + 1;
						if (count($report['preview']) < 25) {
							$report['preview'][] = [
								'row_id' => (int) ($row->id ?? 0),
								'item_id' => $hard_item_id,
								'name' => (string) ($row->customer_name ?? ''),
								'phone' => $this->sn_mask_phone((string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''))),
								'manager' => $this->sn_user_label((int) ($row->hard_owner_user_id ?? 0)),
								'pool_count' => 0,
								'distribution_item_count' => 1,
								'hard_batch_distribution_recovery' => true,
							];
						}
					}
				}
			}
			$report['eligible_rows'] = count($eligible);
		}
		if (empty($report['errors']) && $run_mode === 'apply') {
			foreach ($eligible as $entry) {
				$row = $entry['row'];
				$row_id = (int) $row->id;
				foreach ((array) $entry['items'] as $item) {
					$item_id = (int) ($item->id ?? 0);
					if ($item_id < 1) { continue; }
					$previous_snapshot = [
						'current_owner_user_id' => (int) ($item->current_owner_user_id ?? 0),
						'current_owner_position' => (string) ($item->current_owner_position ?? ''),
						'final_seller_user_id' => (int) ($item->final_seller_user_id ?? 0),
						'status' => (string) ($item->status ?? ''),
						'seller_contact_status' => (string) ($item->seller_contact_status ?? ''),
						'seller_customer_name' => (string) ($item->seller_customer_name ?? ''),
					];
					$this->sn_distribution_log($item_id, 'returned_to_mis', get_current_user_id(), (int) ($item->current_owner_user_id ?? 0), 0, (string) ($item->current_owner_position ?? ''), 'mis', 0, $reason, ['reason' => 'mis_return_assignment', 'row_id' => $row_id, 'previous' => $previous_snapshot]);
					$reset_data = [
						'current_owner_user_id' => null,
						'current_owner_position' => 'mis',
						'current_step_order' => 0,
						'final_seller_user_id' => null,
						'seller_customer_name' => null,
						'seller_province' => null,
						'seller_city' => null,
						'seller_contact_status' => null,
						'seller_sale_probability' => 0,
						'seller_next_followup_at' => null,
						'seller_notes' => null,
						'seller_updated_by' => null,
						'seller_updated_at' => null,
						'status' => 'returned_to_mis',
						'updated_at' => current_time('mysql'),
					];
					$wpdb->update($items_table, $this->sn_filter_existing_columns($items_table, $reset_data), ['id' => $item_id]);
					$report['returned_distribution_items']++;
				}
				foreach ((array) $entry['pool_ids'] as $pool_id) {
					$wpdb->delete($pool_table, ['id' => (int) $pool_id]);
					$report['returned_pool_rows']++;
				}
				$wpdb->update($rows_table, ['assigned_manager_user_id' => null, 'assigned_at' => null, 'updated_at' => current_time('mysql')], ['id' => $row_id]);
				$report['returned_rows']++;
			}
			$remaining_assigned = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows_table} WHERE batch_id=%d AND assigned_manager_user_id IS NOT NULL AND assigned_manager_user_id>0", $batch_id));
			if ($this->sn_mis_table_exists('sn_mis_import_batches')) {
				$batch_update = ['updated_at' => current_time('mysql')];
				if ($remaining_assigned < 1) { $batch_update['assigned_manager_user_id'] = null; $batch_update['import_status'] = 'imported'; }
				$wpdb->update($wpdb->prefix . 'sn_mis_import_batches', $batch_update, ['id' => $batch_id]);
			}
			$this->sn_mis_log($batch_id, 'mis_assignments_returned', ['manager_user_id' => $manager_id, 'include_distribution' => $include_distribution], $report, $reason);
		}
		update_option('sn_mis_return_assignments_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_mis_batch_id' => $batch_id, 'sn_ui_active_tab' => 'mis-batches-list', 'sn_mis_return_report' => '1'], wp_get_referer() ?: home_url('/')) . '#mis-batches-list');
		exit;
	}

	public function handle_mis_quick_assign_data(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_quick_assign_data');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); (new SN_Migration_Service())->migrate(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$target_user_id = absint($_POST['target_user_id'] ?? 0);
		$limit = max(1, min(500, absint($_POST['limit'] ?? 100)));
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? 'تخصیص سریع توسط MIS'));
		$target_position = $this->sn_hr_position_for_user($target_user_id);
		$report = [
			'action' => $run_mode === 'apply' ? 'mis_quick_assign_apply' : 'mis_quick_assign_dry_run',
			'handler_reached' => true,
			'request_method' => sanitize_text_field((string) ($_SERVER['REQUEST_METHOD'] ?? '')),
			'batch_id' => $batch_id,
			'target_user_id' => $target_user_id,
			'target_label' => $target_user_id ? $this->sn_user_label($target_user_id) : '',
			'target_position' => $target_position,
			'limit' => $limit,
			'total_rows' => 0,
			'valid_rows' => 0,
			'invalid_rows' => 0,
			'status_values' => [],
			'sample_row_ids' => [],
			'eligible' => 0,
			'eligible_total' => 0,
			'candidate_scanned' => 0,
			'duplicate_same_batch_candidates' => 0,
			'duplicate_same_batch_samples' => [],
			'created_distribution_items' => 0,
			'reactivated_returned_items' => 0,
			'skipped' => 0,
			'already_delivered' => 0,
			'already_delivered_total' => 0,
			'duplicate_rows' => 0,
			'duplicate_blocked' => 0,
			'duplicate_blocked_samples' => [],
			'cleanup_same_batch_duplicates_deleted' => 0,
			'assignment_traces' => [],
			'zero_reason' => '',
			'operator_message' => '',
			'invalid_reasons' => [],
			'detected_phone_columns' => [],
			'errors' => [],
			'insert_errors' => [],
			'preview' => [],
			'query_mode' => 'eligible_rows_only',
			'updated_at' => current_time('mysql'),
		];
		if (! $batch_id) { $report['errors'][] = 'batch_required'; }
		if (! $target_user_id || ! in_array($target_position, ['sales_deputy','sales_manager','senior_supervisor','supervisor','seller'], true)) { $report['errors'][] = 'target_position_invalid'; }
		if ($run_mode === 'apply' && $confirm !== 'APPLY') { $report['errors'][] = 'confirmation_required'; }
		if (! $this->sn_mis_table_exists('sn_mis_data_rows') || ! $this->sn_distribution_tables_ready()) { $report['errors'][] = 'mis_or_distribution_tables_missing'; }
		$rows = [];
		if (empty($report['errors'])) {
			$report['cleanup_same_batch_duplicates_deleted'] = $this->sn_mis_cleanup_same_batch_duplicate_rows($batch_id);
			$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
			$items_table = $wpdb->prefix . 'sn_distribution_items';
			$report['total_rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows_table} WHERE batch_id=%d", $batch_id));
			$report['valid_rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows_table} WHERE batch_id=%d AND row_status='valid'", $batch_id));
			$status_rows = $wpdb->get_results($wpdb->prepare("SELECT row_status, COUNT(*) c FROM {$rows_table} WHERE batch_id=%d GROUP BY row_status", $batch_id)) ?: [];
			foreach ($status_rows as $status_row) {
				$report['status_values'][(string) $status_row->row_status] = (int) $status_row->c;
			}
			$report['duplicate_rows'] = (int) ($report['status_values']['duplicate'] ?? 0);
			$report['invalid_rows'] = max(0, (int) $report['total_rows'] - (int) $report['valid_rows'] - (int) $report['duplicate_rows']);
			$invalid_reason_rows = $wpdb->get_results($wpdb->prepare("SELECT COALESCE(duplicate_reason,'unknown') reason, COUNT(*) c FROM {$rows_table} WHERE batch_id=%d AND row_status='invalid' GROUP BY duplicate_reason ORDER BY c DESC", $batch_id)) ?: [];
			foreach ($invalid_reason_rows as $reason_row) {
				$report['invalid_reasons'][(string) $reason_row->reason] = (int) $reason_row->c;
			}
			$latest_import = $this->sn_mis_latest_batch_import_report($batch_id);
			$report['detected_phone_columns'] = is_array($latest_import['detected_phone_columns'] ?? null) ? $latest_import['detected_phone_columns'] : [];
			$active_item_condition = "COALESCE(di.status,'') NOT IN ('returned_to_mis','archived','cancelled','referral_cancelled')";
			$report['already_delivered_total'] = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT COUNT(*)
				 FROM {$rows_table} r
				 INNER JOIN {$items_table} di ON di.source_type='mis_data_row' AND di.source_id=r.id AND {$active_item_condition}
				 WHERE r.batch_id=%d AND r.row_status='valid'",
				$batch_id
			));
			$report['eligible_total'] = (int) $wpdb->get_var($wpdb->prepare(
				"SELECT COUNT(*)
				 FROM {$rows_table} r
				 WHERE r.batch_id=%d AND r.row_status='valid'
				 AND NOT EXISTS (SELECT 1 FROM {$items_table} di WHERE di.source_type='mis_data_row' AND di.source_id=r.id AND {$active_item_condition})",
				$batch_id
			));
			$candidate_limit = min(1000, max($limit, $limit * 4));
			$rows = $wpdb->get_results($wpdb->prepare(
				"SELECT r.*, rt.id AS returned_distribution_item_id
				 FROM {$rows_table} r
				 LEFT JOIN {$items_table} rt ON rt.source_type='mis_data_row' AND rt.source_id=r.id AND COALESCE(rt.status,'')='returned_to_mis'
				 WHERE r.batch_id=%d AND r.row_status='valid'
				 AND NOT EXISTS (SELECT 1 FROM {$items_table} di WHERE di.source_type='mis_data_row' AND di.source_id=r.id AND {$active_item_condition})
				 ORDER BY r.id ASC LIMIT %d",
				$batch_id,
				$candidate_limit
			)) ?: [];
			$report['candidate_scanned'] = count($rows);
			$unique_rows = [];
			$seen_batch_phones = [];
			foreach ($rows as $row) {
				$phone_key = SN_Helpers::normalize_mobile((string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? '')));
				if ($phone_key !== '' && isset($seen_batch_phones[$phone_key])) {
					$report['duplicate_same_batch_candidates']++;
					if (count($report['duplicate_same_batch_samples']) < 20) {
						$report['duplicate_same_batch_samples'][] = [
							'row_id' => (int) ($row->id ?? 0),
							'phone' => $this->sn_mask_phone($phone_key),
							'kept_row_id' => (int) $seen_batch_phones[$phone_key],
						];
					}
					continue;
				}
				if ($phone_key !== '') { $seen_batch_phones[$phone_key] = (int) ($row->id ?? 0); }
				$unique_rows[] = $row;
			}
			$rows = $unique_rows;
			$guarded_rows = [];
			foreach ($rows as $row) {
				// Hydrate source context so the bulk duplicate guard excludes the row itself and same-batch siblings.
				$row->source_type = 'mis_data_row';
				$row->source_id = (int) ($row->id ?? 0);
				$row->source_batch_id = (int) ($row->batch_id ?? $batch_id);
			}
			$bulk_guards = $this->sn_mis_duplicate_hard_guard_bulk($rows);
			foreach ($rows as $row) {
				$phone_for_guard = SN_Helpers::normalize_mobile((string) ($row->normalized_phone ?: $row->customer_phone));
				$guard = (array) ($bulk_guards[(int) $row->id] ?? []);
				if (! empty($guard['duplicate'])) {
					$report['duplicate_blocked']++;
					if (count($report['duplicate_blocked_samples']) < 20) {
						$report['duplicate_blocked_samples'][] = [
							'row_id' => (int) $row->id,
							'phone' => $this->sn_mask_phone($phone_for_guard),
							'source' => (string) ($guard['source'] ?? ''),
							'message' => (string) ($guard['message'] ?? ''),
							'existing_owner' => (string) ($guard['existing_owner_label'] ?? ''),
							'existing_seller' => (string) ($guard['existing_seller_label'] ?? ''),
						];
					}
					continue;
				}
				$guarded_rows[] = $row;
				if (count($guarded_rows) >= $limit) { break; }
			}
			$rows = $guarded_rows;
			$report['eligible'] = count($rows);
			foreach ($rows as $row) {
				$report['sample_row_ids'][] = (int) $row->id;
				if (count($report['preview']) < 20) {
					$report['preview'][] = [
						'row_id' => (int) $row->id,
						'name' => (string) $row->customer_name,
						'phone' => $this->sn_mask_phone((string) ($row->normalized_phone ?: $row->customer_phone)),
						'target' => $this->sn_user_label($target_user_id),
						'target_position' => $target_position,
					];
				}
			}
		}
		if (empty($report['errors']) && (int) $report['eligible'] === 0) {
			if ((int) $report['valid_rows'] === 0 && (int) ($report['duplicate_rows'] ?? 0) > 0) {
				$report['zero_reason'] = 'all_rows_duplicate';
			} else {
				$report['zero_reason'] = (int) $report['valid_rows'] === 0 ? 'no_valid_rows' : (((int) $report['eligible_total'] === 0 && (int) $report['already_delivered_total'] >= (int) $report['valid_rows']) ? 'all_already_assigned' : 'unknown');
			}
			if ($report['zero_reason'] === 'all_rows_duplicate') {
				$report['operator_message'] = 'همه شماره‌های این پرونده تکراری هستند و قبلاً در MIS یا لیدهای فروش ثبت شده‌اند. از بخش پیش‌نمایش پرونده، ستون «ردیابی تکراری/تحویل» را ببینید.';
			} elseif ($report['zero_reason'] === 'no_valid_rows') {
				$report['operator_message'] = 'هیچ شماره معتبری برای تخصیص وجود ندارد. ابتدا گزارش ورود فایل را بررسی کنید.';
			} elseif ($report['zero_reason'] === 'all_already_assigned') {
				$report['operator_message'] = 'همه ردیف‌های معتبر این پرونده قبلاً وارد آیتم‌های پخش شده‌اند. ردیابی مالک/فروشنده فعلی در همین گزارش آمده است.';
				$report['assignment_traces'] = $this->sn_mis_assignment_traces_for_batch($batch_id, 30);
			} else {
				$report['operator_message'] = 'ردیف واجد شرایط برای این اجرای تخصیص سریع پیدا نشد. گزارش فنی را بررسی کنید.';
			}
		}
		if (empty($report['errors']) && $run_mode === 'apply') {
			$items_table = $wpdb->prefix . 'sn_distribution_items';
			$wpdb->query('START TRANSACTION');
			foreach ($rows as $row) {
				$phone_for_guard = SN_Helpers::normalize_mobile((string) ($row->normalized_phone ?: $row->customer_phone));
				$status = $target_position === 'seller' ? 'delivered_to_seller' : 'assigned_to_role';
				$returned_item_id = (int) ($row->returned_distribution_item_id ?? 0);
				$item_data = [
					'source_type' => 'mis_data_row',
					'source_id' => (int) $row->id,
					'batch_id' => (int) $row->batch_id,
					'pool_item_id' => null,
					'current_owner_user_id' => $target_user_id,
					'current_owner_position' => $target_position,
					'current_step_order' => $target_position === 'seller' ? 999 : 0,
					'final_seller_user_id' => $target_position === 'seller' ? $target_user_id : null,
					'live_lead_id' => null,
					'customer_phone' => (string) ($row->customer_phone ?? ''),
					'normalized_phone' => $phone_for_guard,
					'seller_customer_name' => null,
					'seller_province' => null,
					'seller_city' => null,
					'seller_contact_status' => null,
					'seller_sale_probability' => 0,
					'seller_next_followup_at' => null,
					'seller_notes' => null,
					'seller_updated_by' => null,
					'seller_updated_at' => null,
					'status' => $status,
					'updated_at' => current_time('mysql'),
				];
				$item_id = 0;
				$write_ok = false;
				if ($returned_item_id > 0) {
					$write_ok = $wpdb->update($items_table, $this->sn_filter_existing_columns($items_table, $item_data), ['id' => $returned_item_id]) !== false;
					$item_id = $returned_item_id;
					if ($write_ok) { $report['reactivated_returned_items']++; }
				} else {
					$item_data['created_at'] = current_time('mysql');
					$write_ok = (bool) $wpdb->insert($items_table, $this->sn_filter_existing_columns($items_table, $item_data));
					$item_id = $write_ok ? (int) $wpdb->insert_id : 0;
				}
				if ($write_ok && $item_id > 0) {
					$report['created_distribution_items']++;
					$this->sn_distribution_log($item_id, $target_position === 'seller' ? 'mis_direct_delivery_to_seller' : 'mis_quick_assignment_to_role', get_current_user_id(), 0, $target_user_id, 'mis', $target_position, $target_position === 'seller' ? 999 : 0, $reason, ['source_row_id' => (int) $row->id, 'source_type' => 'mis_data_row', 'live_lead_created' => false, 'reactivated_returned_item' => $returned_item_id > 0]);
					if ($target_position === 'sales_manager') {
						$wpdb->update($rows_table, ['assigned_manager_user_id' => $target_user_id, 'assigned_at' => current_time('mysql'), 'updated_at' => current_time('mysql')], ['id' => (int) $row->id]);
					}
				} else {
					$report['skipped']++;
					$report['insert_errors'][] = $wpdb->last_error ? sanitize_text_field($wpdb->last_error) : 'distribution_item_write_failed_without_db_error';
				}
			}
			if ($target_position === 'sales_manager' && (int) ($report['created_distribution_items'] ?? 0) > 0 && $this->sn_mis_table_exists('sn_mis_import_batches')) {
				$wpdb->update($wpdb->prefix . 'sn_mis_import_batches', ['assigned_manager_user_id' => $target_user_id, 'import_status' => 'assigned', 'updated_at' => current_time('mysql')], ['id' => $batch_id]);
			}
			$wpdb->query('COMMIT');
		}
		if ($run_mode === 'apply' || $run_mode === 'dry_run' || ! empty($report['errors'])) {
			$this->sn_mis_log($batch_id, $run_mode === 'apply' ? 'mis_quick_assignment' : ($run_mode === 'dry_run' ? 'mis_quick_assignment_preview' : 'mis_quick_assignment_error'), null, $report, $reason);
		}
		update_option('sn_mis_quick_assign_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		$redirect_to = esc_url_raw(wp_unslash($_POST['redirect_to'] ?? ''));
		$redirect_to = $redirect_to !== '' ? $redirect_to : (wp_get_referer() ?: home_url('/'));
		$redirect_to = remove_query_arg(['sn_mis_quick_report','sn_mis_tab','sn_mis_batch_id'], $redirect_to);
		wp_safe_redirect(add_query_arg(['sn_mis_batch_id' => $batch_id, 'sn_mis_tab' => 'mis-quick', 'sn_mis_quick_report' => 1, 'sn_mis_quick_mode' => $run_mode], $redirect_to) . '#mis-quick');
		exit;
	}

	public function handle_mis_prepare_lead_pool(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_prepare_lead_pool');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$report = $run_mode === 'apply'
			? ['batch_id' => $batch_id, 'manager_user_id' => $manager_id, 'eligible' => 0, 'already_in_pool' => 0, 'invalid' => 0, 'duplicate' => 0, 'no_manager' => 0, 'candidates' => [], 'preflight_report_skipped' => true]
			: $this->sn_mis_lead_pool_prepare_report($batch_id, $manager_id, 20);
		$report['action'] = 'lead_pool_prepare_' . ($run_mode === 'apply' ? 'apply' : 'dry_run');
		$report['updated_at'] = current_time('mysql');
		$report['created'] = 0;
		$report['errors'] = [];
		if ($manager_id > 0 && $this->sn_hr_position_for_user($manager_id) !== 'sales_manager') {
			$report['errors'][] = 'manager_must_have_sales_manager_position';
			$run_mode = 'dry_run';
		}
		if ($run_mode === 'apply') {
			if ($confirm !== 'APPLY') {
				$report['errors'][] = 'confirmation_required';
			} elseif (! $this->sn_mis_table_exists('sn_mis_lead_pool')) {
				$report['errors'][] = 'lead_pool_table_missing';
			} else {
				$rows = $this->sn_mis_lead_pool_candidate_rows($batch_id, $manager_id, 500);
				$wpdb->query('START TRANSACTION');
				foreach ($rows as $row) {
					$inserted = $wpdb->insert($wpdb->prefix . 'sn_mis_lead_pool', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_lead_pool', [
						'source_row_id' => (int) $row->id,
						'batch_id' => (int) $row->batch_id,
						'assigned_manager_user_id' => (int) $row->assigned_manager_user_id,
						'assigned_seller_user_id' => null,
						'pool_status' => 'ready',
						'normalized_phone' => (string) ($row->normalized_phone ?? ''),
						'customer_phone' => (string) ($row->customer_phone ?? ''),
						'customer_name' => (string) ($row->customer_name ?? ''),
						'city' => (string) ($row->city ?? ''),
						'province' => (string) ($row->province ?? ''),
						'source_meta' => (string) ($row->source_meta ?? ''),
						'created_by' => get_current_user_id() ?: null,
						'created_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
						'notes' => $reason,
					]));
					if ($inserted) {
						$report['created']++;
					} elseif ($wpdb->last_error) {
						$report['errors'][] = sanitize_text_field($wpdb->last_error);
					}
				}
				$wpdb->query('COMMIT');
				$report = array_merge($report, $this->sn_mis_lead_pool_prepare_report($batch_id, $manager_id, 20));
				$report['action'] = 'lead_pool_prepare_apply';
				$report['created'] = (int) ($report['created'] ?? 0);
				$report['updated_at'] = current_time('mysql');
			}
		}
		$this->sn_mis_log($batch_id, 'lead_pool_prepared', null, $report, $reason);
		update_option('sn_mis_lead_pool_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_mis_batch_id' => $batch_id], wp_get_referer() ?: home_url('/')));
		exit;
	}

	public function handle_mis_create_distribution_rule(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_create_distribution_rule');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_distribution_rules')) { wp_safe_redirect(wp_get_referer() ?: home_url('/')); exit; }
		$rule_type = sanitize_key(wp_unslash($_POST['rule_type'] ?? 'equal_split'));
		if (! in_array($rule_type, ['equal_split', 'manual_selection'], true)) {
			$rule_type = 'equal_split';
		}
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		if ($manager_id > 0 && $this->sn_hr_position_for_user($manager_id) !== 'sales_manager') {
			$manager_id = 0;
		}
		$data = $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_rules', [
			'rule_name' => sanitize_text_field(wp_unslash($_POST['rule_name'] ?? '')),
			'rule_type' => $rule_type,
			'manager_user_id' => $manager_id ?: null,
			'status' => 'draft',
			'config' => wp_json_encode(['notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? ''))], JSON_UNESCAPED_UNICODE),
			'created_by' => get_current_user_id() ?: null,
			'created_at' => current_time('mysql'),
			'updated_at' => current_time('mysql'),
			'notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
		]);
		$wpdb->insert($wpdb->prefix . 'sn_mis_distribution_rules', $data);
		$rule_id = (int) $wpdb->insert_id;
		$report = ['action' => 'distribution_rule_created', 'rule_id' => $rule_id, 'rule_type' => $rule_type, 'manager_user_id' => $manager_id, 'updated_at' => current_time('mysql')];
		$this->sn_mis_log(0, 'distribution_rule_created', null, $report, (string) ($data['notes'] ?? ''));
		update_option('sn_mis_distribution_plan_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(wp_get_referer() ?: home_url('/'));
		exit;
	}

	public function handle_mis_create_distribution_plan(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_create_distribution_plan');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		$batch_id = absint($_POST['batch_id'] ?? 0);
		$manager_id = absint($_POST['manager_user_id'] ?? 0);
		$rule_id = absint($_POST['rule_id'] ?? 0);
		$raw_seller_ids = $_POST['seller_ids'] ?? ($_POST['seller_user_ids'] ?? []);
		$seller_ids = array_map('absint', (array) $raw_seller_ids);
		$seller_ids = array_values(array_filter(array_unique($seller_ids)));
		$run_mode = sanitize_key(wp_unslash($_POST['run_mode'] ?? 'dry_run'));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$report = $this->sn_mis_distribution_plan_report($batch_id, $manager_id, $rule_id, $seller_ids, 20);
		$report['action'] = 'distribution_plan_' . ($run_mode === 'apply' ? 'apply' : 'dry_run');
		$report['created_plan_id'] = 0;
		$report['created_items'] = 0;
		$report['updated_at'] = current_time('mysql');
		$report['errors'] = (array) ($report['errors'] ?? []);
		if ($run_mode === 'apply') {
			if ($confirm !== 'APPLY') {
				$report['errors'][] = 'confirmation_required';
			} elseif (! empty($report['errors'])) {
				// Keep dry-run errors visible; do not write partial plans.
			} elseif (! $this->sn_mis_table_exists('sn_mis_distribution_plans') || ! $this->sn_mis_table_exists('sn_mis_distribution_plan_items')) {
				$report['errors'][] = 'distribution_tables_missing';
			} else {
				$plan_code = $this->sn_mis_generate_plan_code();
				$wpdb->insert($wpdb->prefix . 'sn_mis_distribution_plans', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_plans', [
					'plan_code' => $plan_code,
					'rule_id' => $rule_id ?: null,
					'batch_id' => $batch_id ?: null,
					'manager_user_id' => $manager_id,
					'plan_status' => 'draft',
					'total_pool_rows' => (int) ($report['total_pool_rows'] ?? 0),
					'planned_rows' => (int) ($report['planned_rows'] ?? 0),
					'skipped_rows' => (int) ($report['skipped_rows'] ?? 0),
					'created_by' => get_current_user_id() ?: null,
					'created_at' => current_time('mysql'),
					'updated_at' => current_time('mysql'),
					'notes' => $reason,
				]));
				$plan_id = (int) $wpdb->insert_id;
				$report['created_plan_id'] = $plan_id;
				foreach ((array) ($report['preview_items_all'] ?? []) as $item) {
					$inserted = $wpdb->insert($wpdb->prefix . 'sn_mis_distribution_plan_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_plan_items', [
						'plan_id' => $plan_id,
						'pool_id' => (int) $item['pool_id'],
						'source_row_id' => (int) $item['source_row_id'],
						'manager_user_id' => $manager_id,
						'planned_seller_user_id' => ! empty($item['seller_id']) ? (int) $item['seller_id'] : null,
						'item_status' => (string) $item['status'],
						'skip_reason' => (string) $item['skip_reason'],
						'created_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
					]));
					if ($inserted) {
						$report['created_items']++;
					}
				}
				$report['plan_code'] = $plan_code;
				$report['action'] = 'distribution_plan_created';
				$this->sn_mis_log($batch_id, 'distribution_plan_created', null, $report, $reason);
			}
		}
		unset($report['preview_items_all']);
		update_option('sn_mis_distribution_plan_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_mis_batch_id' => $batch_id], wp_get_referer() ?: home_url('/')));
		exit;
	}

	public function handle_mis_approve_distribution_plan(): void
	{
		$this->sn_mis_clear_performance_cache();
		if (! $this->sn_can_access_mis_panel()) { wp_die('دسترسی غیرمجاز'); }
		check_admin_referer('sn_mis_approve_distribution_plan');
		if (class_exists('SN_Migration_Service')) { (new SN_Migration_Service())->repair_mis_schema(); }
		global $wpdb;
		$plan_id = absint($_POST['plan_id'] ?? 0);
		$confirm = sanitize_text_field(wp_unslash($_POST['confirm'] ?? ''));
		$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
		$plan = $plan_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_distribution_plans WHERE id=%d", $plan_id)) : null;
		$report = ['action' => 'distribution_plan_approve', 'plan_id' => $plan_id, 'approved' => false, 'errors' => [], 'updated_at' => current_time('mysql')];
		if (! $plan) {
			$report['errors'][] = 'plan_not_found';
		} elseif ($confirm !== 'APPROVE') {
			$report['errors'][] = 'confirmation_required';
		} elseif (! in_array((string) $plan->plan_status, ['draft', 'dry_run'], true)) {
			$report['errors'][] = 'plan_status_not_approvable';
		} else {
			$wpdb->update($wpdb->prefix . 'sn_mis_distribution_plans', ['plan_status' => 'approved', 'updated_at' => current_time('mysql')], ['id' => $plan_id]);
			$report['approved'] = true;
			$report['plan_code'] = (string) $plan->plan_code;
			$this->sn_mis_log((int) ($plan->batch_id ?? 0), 'distribution_plan_approved', ['status' => (string) $plan->plan_status], $report, $reason);
		}
		update_option('sn_mis_lead_creation_report', $report, false);
		update_option('sn_mis_last_report', $report, false);
		wp_safe_redirect(add_query_arg(['sn_mis_plan_id' => $plan_id], wp_get_referer() ?: home_url('/')));
		exit;
	}

