	private function sn_mis_generate_batch_code(): string
	{
		global $wpdb;
		do {
			$code = 'MIS-' . SN_Helpers::tehran_format('Ymd') . '-' . strtoupper(wp_generate_password(4, false, false));
		} while ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_import_batches WHERE batch_code=%s", $code)) > 0);
		return $code;
	}

	private function sn_mis_log(int $batch_id, string $action, $old, $new, string $reason = ''): void
	{
		global $wpdb;
		$wpdb->insert($wpdb->prefix . 'sn_mis_distribution_logs', [
			'batch_id' => $batch_id ?: null,
			'actor_user_id' => get_current_user_id() ?: null,
			'action' => sanitize_key($action),
			'old_value' => $old === null ? null : wp_json_encode($old, JSON_UNESCAPED_UNICODE),
			'new_value' => $new === null ? null : wp_json_encode($new, JSON_UNESCAPED_UNICODE),
			'reason' => $reason ?: null,
			'created_at' => current_time('mysql'),
		]);
	}

	private function sn_mis_csv_header_map(array $headers): array
	{
		$map = [];
		foreach ($headers as $i => $header) {
			$key = strtolower(trim((string) $header));
			if (in_array($key, ['phone', 'mobile', 'customer_phone', 'tel'], true)) { $map['phone'] = $i; }
			if (in_array($key, ['name', 'customer_name', 'fullname', 'full_name'], true)) { $map['name'] = $i; }
			if ($key === 'city') { $map['city'] = $i; }
			if ($key === 'province') { $map['province'] = $i; }
			if (in_array($key, ['notes', 'note', 'source_meta'], true)) { $map['notes'] = $i; }
		}
		return $map;
	}

	private function sn_mis_table_exists(string $table): bool
	{
		global $wpdb;
		$full = strpos($table, $wpdb->prefix) === 0 ? $table : $wpdb->prefix . ltrim($table, '_');
		return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $full)) === $full;
	}

	private function sn_safe_table_count(string $table): int
	{
		global $wpdb;
		$full = strpos($table, $wpdb->prefix) === 0 ? $table : $wpdb->prefix . ltrim($table, '_');
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $full)) !== $full) {
			return 0;
		}
		return (int) $wpdb->get_var("SELECT COUNT(*) FROM {$full}");
	}

	private function sn_distribution_ensure_schema(): void
	{
		if (class_exists('SN_Migration_Service')) {
			(new SN_Migration_Service())->migrate();
		}
		// وضعیت تماس فروشنده باید به مالک فعلی آیتم تعلق داشته باشد.
		// بعد از برگشت/تخصیص مجدد، وضعیت فروشنده قبلی نباید روی مالک جدید دیده شود.
		$this->sn_distribution_ensure_seller_inline_columns();
		$this->sn_distribution_cleanup_stale_seller_state_once();
	}

	private function sn_distribution_seller_state_reset_data(): array
	{
		return [
			'seller_customer_name' => null,
			'seller_province' => null,
			'seller_city' => null,
			'seller_contact_status' => null,
			'seller_sale_probability' => 0,
			'seller_sale_probability_label' => null,
			'seller_next_followup_at' => null,
			'seller_notes' => null,
			'seller_updated_by' => null,
			'seller_updated_at' => null,
		];
	}

	private function sn_distribution_seller_status_reset_data(): array
	{
		return [
			'seller_contact_status' => null,
			'seller_sale_probability' => 0,
			'seller_sale_probability_label' => null,
			'seller_next_followup_at' => null,
			'seller_notes' => null,
			'seller_updated_by' => null,
			'seller_updated_at' => null,
		];
	}


	public function sn_distribution_cleanup_stale_seller_state_runtime(): void
	{
		// سبک و idempotent: فقط وضعیت تماس مانده از فروشنده قبلی را پاک می‌کند؛ مالکیت/لید/فاکتور را تغییر نمی‌دهد.
		$this->sn_distribution_cleanup_stale_seller_state_once();
	}

	private function sn_distribution_cleanup_stale_seller_state_once(): void
	{
		global $wpdb;
		$version_key = '1.0.134-force-stale-status-repair';
		if ((string) get_option('sn_stale_seller_state_cleanup_version', '') === $version_key) {
			return;
		}
		$table = $wpdb->prefix . 'sn_distribution_items';
		if (! $this->sn_mis_table_exists('sn_distribution_items')) {
			return;
		}
		$cols = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
		$required = ['seller_contact_status', 'seller_notes', 'seller_next_followup_at', 'seller_updated_by', 'seller_updated_at', 'current_owner_user_id', 'current_owner_position'];
		foreach ($required as $col) {
			if (! in_array($col, $cols, true)) {
				return;
			}
		}
		$has_state_sql = "(
			NULLIF(seller_contact_status,'') IS NOT NULL
			OR NULLIF(seller_notes,'') IS NOT NULL
			OR seller_next_followup_at IS NOT NULL
			OR seller_updated_at IS NOT NULL
		)";
		$stale_owner_sql = "(
			COALESCE(current_owner_position,'') <> 'seller'
			OR COALESCE(current_owner_user_id,0)=0
			OR COALESCE(seller_updated_by,0)=0
			OR COALESCE(seller_updated_by,0)<>COALESCE(current_owner_user_id,0)
		)";
		$where = "{$has_state_sql} AND {$stale_owner_sql}";
		$before = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE {$where}");
		$samples = $wpdb->get_results("
			SELECT current_owner_user_id, seller_updated_by, seller_contact_status, COUNT(*) total
			FROM {$table}
			WHERE {$where}
			GROUP BY current_owner_user_id, seller_updated_by, seller_contact_status
			ORDER BY total DESC
			LIMIT 20
		", ARRAY_A) ?: [];
		$set_parts = [];
		foreach ($this->sn_distribution_seller_status_reset_data() as $column => $value) {
			if (! in_array($column, $cols, true)) { continue; }
			$set_parts[] = $value === null ? "{$column}=NULL" : $wpdb->prepare("{$column}=%d", (int) $value);
		}
		if (! $set_parts) {
			update_option('sn_stale_seller_state_cleanup_version', $version_key, false);
			return;
		}
		// پاکسازی فقط state تماس فروشنده است؛ مالکیت، final_seller، live_lead و فاکتور تغییر نمی‌کند.
		// این نسخه عمداً live_lead_id/source_type را فیلتر نمی‌کند، چون status قدیمی نباید همراه مالک جدید دیده شود.
		$updated = $wpdb->query("UPDATE {$table} SET " . implode(', ', $set_parts) . " WHERE {$where}");
		$after = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE {$where}");
		update_option('sn_stale_seller_state_cleanup_version', $version_key, false);
		update_option('sn_stale_seller_state_cleanup_report', [
			'version' => $version_key,
			'stale_rows_before' => $before,
			'cleaned_rows' => is_numeric($updated) ? (int) $updated : 0,
			'stale_rows_after' => $after,
			'samples_before' => $samples,
			'last_error' => (string) $wpdb->last_error,
			'updated_at' => current_time('mysql'),
		], false);
	}

	private function sn_distribution_seller_state_is_current_for_view(int $seller_id, object $item): bool
	{
		if ($seller_id < 1 || (int) ($item->current_owner_user_id ?? 0) !== $seller_id || (string) ($item->current_owner_position ?? '') !== 'seller') {
			return false;
		}
		$updated_by = (int) ($item->seller_updated_by ?? 0);
		if ($updated_by > 0 && $updated_by !== $seller_id) {
			return false;
		}
		$seller_updated_at = (string) ($item->seller_updated_at ?? '');
		$item_updated_at = (string) ($item->updated_at ?? '');
		if ($seller_updated_at !== '' && $item_updated_at !== '') {
			$su = SN_Helpers::site_mysql_timestamp($seller_updated_at, 0);
			$iu = SN_Helpers::site_mysql_timestamp($item_updated_at, 0);
			if ($su && $iu && $su < $iu) {
				return false;
			}
		}
		return true;
	}

	private function sn_distribution_guard_seller_state_for_view(int $seller_id, object $item): void
	{
		$has_state = trim((string) ($item->seller_contact_status ?? '')) !== ''
			|| trim((string) ($item->seller_notes ?? '')) !== ''
			|| trim((string) ($item->seller_customer_name ?? '')) !== ''
			|| ! empty($item->seller_next_followup_at)
			|| ! empty($item->seller_updated_at);
		if (! $has_state || $this->sn_distribution_seller_state_is_current_for_view($seller_id, $item)) {
			return;
		}
		foreach ($this->sn_distribution_seller_state_reset_data() as $key => $value) {
			$item->{$key} = $value;
		}
	}

	private function sn_distribution_ensure_seller_inline_columns(): void
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_distribution_items';
		if (! $this->sn_mis_table_exists('sn_distribution_items')) {
			return;
		}
		$definitions = [
			'seller_customer_name' => 'VARCHAR(255) NULL',
			'seller_province' => 'VARCHAR(100) NULL',
			'seller_city' => 'VARCHAR(100) NULL',
			'seller_contact_status' => 'VARCHAR(60) NULL',
			'seller_sale_probability' => 'TINYINT UNSIGNED NOT NULL DEFAULT 0',
			'seller_sale_probability_label' => 'VARCHAR(40) NULL',
			'seller_next_followup_at' => 'DATETIME NULL',
			'seller_notes' => 'TEXT NULL',
			'seller_updated_by' => 'BIGINT UNSIGNED NULL',
			'seller_updated_at' => 'DATETIME NULL',
			'customer_phone' => 'VARCHAR(32) NULL',
			'normalized_phone' => 'VARCHAR(32) NULL',
			'ref_invoice_id' => 'BIGINT UNSIGNED NULL',
			'ref_product_id' => 'BIGINT UNSIGNED NULL',
			'follow_invoice_id' => 'BIGINT UNSIGNED NULL',
			'referral_original_seller_id' => 'BIGINT UNSIGNED NULL',
			'referral_issued_by_user_id' => 'BIGINT UNSIGNED NULL',
			'referral_target_scope' => 'VARCHAR(60) NULL',
			'referral_note' => 'TEXT NULL',
			'workflow_kind' => 'VARCHAR(60) NULL',
			'workflow_assigned_by_user_id' => 'BIGINT UNSIGNED NULL',
		];
		$existing = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
		foreach ($definitions as $column => $definition) {
			if (! in_array($column, $existing, true)) {
				$wpdb->query("ALTER TABLE {$table} ADD COLUMN {$column} {$definition}");
				$existing[] = $column;
			}
		}
	}

	private function sn_distribution_filter_existing_columns_fresh(string $table, array $data): array
	{
		global $wpdb;
		$cols = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
		return array_intersect_key($data, array_flip($cols));
	}

	private function sn_distribution_tables_ready(): bool
	{
		if ($this->sn_distribution_tables_ready_cache !== null) {
			return (bool) $this->sn_distribution_tables_ready_cache;
		}
		$ready = $this->sn_mis_table_exists('sn_distribution_chains')
			&& $this->sn_mis_table_exists('sn_distribution_chain_steps')
			&& $this->sn_mis_table_exists('sn_distribution_items')
			&& $this->sn_mis_table_exists('sn_distribution_item_logs');
		if ($ready) {
			$this->sn_distribution_tables_ready_cache = true;
		}
		return $ready;
	}

	private function sn_distribution_active_chain(): array
	{
		global $wpdb;
		if ($this->sn_distribution_active_chain_cache !== null) {
			return (array) $this->sn_distribution_active_chain_cache;
		}
		if (! $this->sn_distribution_tables_ready()) {
			$this->sn_distribution_active_chain_cache = ['chain' => null, 'steps' => []];
			return $this->sn_distribution_active_chain_cache;
		}
		$chain = $wpdb->get_row("SELECT * FROM {$wpdb->prefix}sn_distribution_chains WHERE is_active=1 ORDER BY is_default DESC, id ASC LIMIT 1");
		$steps = $chain ? ($wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_distribution_chain_steps WHERE chain_id=%d AND is_active=1 ORDER BY step_order ASC, id ASC", (int) $chain->id)) ?: []) : [];
		$this->sn_distribution_active_chain_cache = ['chain' => $chain, 'steps' => $steps];
		return $this->sn_distribution_active_chain_cache;
	}

	private function sn_distribution_positions(): array
	{
		global $wpdb;
		if ($this->sn_mis_table_exists('sn_hr_positions')) {
			$rows = $wpdb->get_results("SELECT slug,label FROM {$wpdb->prefix}sn_hr_positions WHERE is_active=1 ORDER BY sort_order ASC,id ASC") ?: [];
			$out = [];
			foreach ($this->sn_hr_normalize_lookup_rows($rows, 'position') as $row) { $out[(string) $row->slug] = (string) ($row->label ?: $row->slug); }
			if ($out) { return $out; }
		}
		return ['sales_deputy' => 'معاون فروش','sales_manager' => 'مدیر فروش','senior_supervisor' => 'سرپرست ارشد','supervisor' => 'سرپرست','converter' => 'تبدیل‌کننده','seller' => 'فروشنده','finance' => 'مالی',
			'invoice_reviewer' => 'بررسی فاکتور','hr' => 'منابع انسانی','mis' => 'MIS','after_sales' => 'خدمات پس از فروش'];
	}

	private function sn_distribution_position_label(string $slug): string
	{
		$positions = $this->sn_distribution_positions();
		return $positions[$slug] ?? $this->sn_hr_persian_label($slug);
	}

	private function sn_distribution_delivery_candidates(int $batch_id = 0, int $manager_id = 0, int $limit = 500): array
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_lead_pool') || ! $this->sn_distribution_tables_ready()) { return []; }
		$where = ["p.pool_status='ready'", 'p.assigned_manager_user_id > 0'];
		$args = [];
		if ($batch_id) { $where[] = 'p.batch_id=%d'; $args[] = $batch_id; }
		if ($manager_id) { $where[] = 'p.assigned_manager_user_id=%d'; $args[] = $manager_id; }
		$where[] = "NOT EXISTS (SELECT 1 FROM {$wpdb->prefix}sn_distribution_items di WHERE di.source_type='mis_pool' AND di.source_id=p.id)";
		$sql = "SELECT p.* FROM {$wpdb->prefix}sn_mis_lead_pool p WHERE " . implode(' AND ', $where) . ' ORDER BY p.id ASC LIMIT %d';
		$args[] = $limit;
		return $wpdb->get_results($wpdb->prepare($sql, ...$args)) ?: [];
	}

	private function sn_distribution_delivery_report(int $batch_id = 0, int $manager_id = 0, int $preview_limit = 20): array
	{
		global $wpdb;
		$report = ['batch_id' => $batch_id, 'manager_user_id' => $manager_id, 'eligible' => 0, 'already_delivered' => 0, 'preview' => [], 'errors' => [], 'updated_at' => current_time('mysql')];
		if (! $this->sn_mis_table_exists('sn_mis_lead_pool') || ! $this->sn_distribution_tables_ready()) {
			$report['errors'][] = 'distribution_or_pool_table_missing';
			return $report;
		}
		$where = ["pool_status='ready'", 'assigned_manager_user_id > 0'];
		$args = [];
		if ($batch_id) { $where[] = 'batch_id=%d'; $args[] = $batch_id; }
		if ($manager_id) { $where[] = 'assigned_manager_user_id=%d'; $args[] = $manager_id; }
		$where_sql = implode(' AND ', $where);
		$eligible_sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_lead_pool p WHERE {$where_sql} AND NOT EXISTS (SELECT 1 FROM {$wpdb->prefix}sn_distribution_items di WHERE di.source_type='mis_pool' AND di.source_id=p.id)";
		$delivered_sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_lead_pool p WHERE {$where_sql} AND EXISTS (SELECT 1 FROM {$wpdb->prefix}sn_distribution_items di WHERE di.source_type='mis_pool' AND di.source_id=p.id)";
		$report['eligible'] = (int) $wpdb->get_var($args ? $wpdb->prepare($eligible_sql, ...$args) : $eligible_sql);
		$report['already_delivered'] = (int) $wpdb->get_var($args ? $wpdb->prepare($delivered_sql, ...$args) : $delivered_sql);
		foreach ($this->sn_distribution_delivery_candidates($batch_id, $manager_id, $preview_limit) as $row) {
			$report['preview'][] = ['pool_id' => (int) $row->id, 'batch_id' => (int) $row->batch_id, 'manager_user_id' => (int) $row->assigned_manager_user_id, 'customer_name' => (string) $row->customer_name, 'phone_masked' => $this->sn_mask_phone((string) ($row->normalized_phone ?: $row->customer_phone))];
		}
		return $report;
	}

	private function sn_distribution_actor_can_transfer(int $actor_id, object $item): bool
	{
		if (current_user_can('manage_options')) { return true; }
		return (int) ($item->current_owner_user_id ?? 0) === $actor_id;
	}

	private function sn_distribution_user_is_active(int $user_id, int $row_is_active = 1): bool
	{
		$user_id = absint($user_id);
		if ($user_id < 1 || $row_is_active !== 1) {
			return false;
		}
		if (! array_key_exists($user_id, $this->sn_distribution_user_active_cache)) {
			$this->sn_distribution_user_active_cache[$user_id] = get_user_meta($user_id, 'sn_is_active', true) !== '0';
		}
		return (bool) $this->sn_distribution_user_active_cache[$user_id];
	}

	private function sn_distribution_descendant_users_by_position(int $actor_user_id, string $position_slug): array
	{
		$actor_user_id = absint($actor_user_id);
		$position_slug = sanitize_key($position_slug);
		if ($actor_user_id < 1 || $position_slug === '') {
			return [];
		}
		$key = $actor_user_id . ':' . $position_slug;
		if (isset($this->sn_distribution_descendant_users_cache['ids:' . $key])) {
			return (array) $this->sn_distribution_descendant_users_cache['ids:' . $key];
		}
		$rows = $this->sn_get_descendant_users($actor_user_id, $position_slug);
		$out = [];
		foreach ($rows as $row) {
			$user_id = absint($row['user_id'] ?? 0);
			if ($user_id > 0 && $this->sn_distribution_user_is_active($user_id, (int) ($row['is_active'] ?? 0))) {
				$out[] = $user_id;
			}
		}
		$this->sn_distribution_descendant_users_cache['ids:' . $key] = array_values(array_unique(array_map('intval', $out)));
		return (array) $this->sn_distribution_descendant_users_cache['ids:' . $key];
	}

	private function sn_distribution_is_paid_referral_supervisor_hold(object $item): bool
	{
		$source_type = (string) ($item->source_type ?? '');
		$scope = sanitize_key((string) ($item->referral_target_scope ?? ''));
		$owner_position = sanitize_key((string) ($item->current_owner_position ?? ''));
		$status = sanitize_key((string) ($item->status ?? ''));
		return $source_type === 'paid_invoice_referral'
			&& in_array($scope, ['supervisor', 'senior_supervisor'], true)
			&& in_array($owner_position, ['supervisor', 'senior_supervisor'], true)
			&& empty($item->follow_invoice_id)
			&& ! in_array($status, ['referral_invoice_created', 'referral_cancelled', 'cancelled'], true);
	}

	private function sn_distribution_next_recipients(int $actor_user_id, object $item): array
	{
		if ($this->sn_distribution_is_paid_referral_supervisor_hold($item)) {
			return [];
		}
		$current_position = (string) ($item->current_owner_position ?: $this->sn_hr_position_for_user($actor_user_id));
		$current_step = (int) ($item->current_step_order ?? 0);
		$cache_key = absint($actor_user_id) . '|' . sanitize_key($current_position) . '|' . $current_step;
		if (isset($this->sn_distribution_next_recipients_cache[$cache_key])) {
			return (array) $this->sn_distribution_next_recipients_cache[$cache_key];
		}
		$chain = $this->sn_distribution_active_chain();
		$steps = (array) ($chain['steps'] ?? []);
		if (! $steps) {
			$this->sn_distribution_next_recipients_cache[$cache_key] = [];
			return [];
		}
		$out = [];
		foreach ($steps as $step) {
			if ((int) $step->step_order <= $current_step) { continue; }
			if ((string) $step->from_position_slug !== $current_position) { continue; }
			$ids = $this->sn_distribution_descendant_users_by_position($actor_user_id, (string) $step->to_position_slug);
			foreach ($ids as $id) {
				$out[$id] = ['user_id' => $id, 'position' => (string) $step->to_position_slug, 'step_order' => (int) $step->step_order, 'is_final' => (bool) (int) $step->is_final_delivery_step, 'creates_live_lead' => (bool) (int) $step->creates_live_lead];
			}
			if ($ids || empty($step->allow_skip_if_missing)) { break; }
			$current_position = (string) $step->to_position_slug;
			$current_step = (int) $step->step_order;
		}
		$scope_positions = $this->sn_distribution_recipient_positions_for_actor($actor_user_id);
		if ($scope_positions) {
			foreach ($this->sn_distribution_scope_recipients_for_actor($actor_user_id, $scope_positions, $steps) as $id => $recipient) {
				$out[(int) $id] = $out[(int) $id] ?? $recipient;
			}
		}
		if (! $out && $current_position === 'sales_deputy') {
			foreach ($this->sn_distribution_direct_hr_recipients_for_actor($actor_user_id, 'sales_manager', max(10, $current_step + 10)) as $id => $recipient) {
				$recipient['is_final'] = false;
				$recipient['creates_live_lead'] = false;
				$out[(int) $id] = $recipient;
			}
		}
		$this->sn_distribution_next_recipients_cache[$cache_key] = $out;
		return $out;
	}


	private function sn_distribution_sales_manager_scope_recipients(int $actor_user_id, array $steps = []): array
	{
		$actor_user_id = absint($actor_user_id);
		if ($actor_user_id < 1) {
			return [];
		}
		$step_order_by_position = ['senior_supervisor' => 10, 'supervisor' => 20, 'seller' => 30];
		foreach ($steps as $step) {
			$to_position = sanitize_key((string) ($step->to_position_slug ?? ''));
			if (isset($step_order_by_position[$to_position])) {
				$step_order_by_position[$to_position] = (int) ($step->step_order ?? $step_order_by_position[$to_position]);
			}
		}
		$out = [];
		foreach (['senior_supervisor', 'supervisor', 'seller'] as $position) {
			foreach ($this->sn_get_descendant_users($actor_user_id, $position) as $row) {
				$user_id = absint($row['user_id'] ?? 0);
				$is_active = (int) ($row['is_active'] ?? 0) === 1 && get_user_meta($user_id, 'sn_is_active', true) !== '0';
				if ($user_id < 1 || ! $is_active) {
					continue;
				}
				$out[$user_id] = [
					'user_id' => $user_id,
					'position' => $position,
					'step_order' => $step_order_by_position[$position] ?? 0,
					'is_final' => $position === 'seller',
					'creates_live_lead' => false,
					'source' => 'hr_sales_manager_descendant_scope',
				];
			}
		}
		return $out;
	}


	private function sn_distribution_recipient_positions_for_actor(int $actor_user_id): array
	{
		$actor_position = $this->sn_hr_position_for_user($actor_user_id);
		if ($actor_position === 'sales_deputy') {
			return ['sales_manager', 'senior_supervisor', 'supervisor', 'seller'];
		}
		if ($actor_position === 'sales_manager') {
			return ['senior_supervisor', 'supervisor', 'seller'];
		}
		if ($actor_position === 'senior_supervisor') {
			return ['supervisor', 'seller'];
		}
		if ($actor_position === 'supervisor') {
			return ['seller'];
		}
		return [];
	}

	private function sn_distribution_step_order_map(array $steps = []): array
	{
		$map = ['sales_manager' => 5, 'senior_supervisor' => 10, 'supervisor' => 20, 'seller' => 30];
		foreach ($steps as $step) {
			$to_position = sanitize_key((string) ($step->to_position_slug ?? ''));
			if ($to_position !== '') {
				$map[$to_position] = (int) ($step->step_order ?? ($map[$to_position] ?? 0));
			}
		}
		return $map;
	}

	private function sn_distribution_scope_recipients_for_actor(int $actor_user_id, array $positions, array $steps = []): array
	{
		$actor_user_id = absint($actor_user_id);
		if ($actor_user_id < 1) {
			return [];
		}
		$positions = array_values(array_unique(array_filter(array_map('sanitize_key', $positions))));
		if (! $positions) {
			return [];
		}
		$step_order_by_position = $this->sn_distribution_step_order_map($steps);
		$cache_key = $actor_user_id . '|' . implode(',', $positions) . '|' . md5(wp_json_encode($step_order_by_position));
		if (isset($this->sn_distribution_scope_recipients_cache[$cache_key])) {
			return (array) $this->sn_distribution_scope_recipients_cache[$cache_key];
		}
		$out = [];
		foreach ($positions as $position) {
			foreach ($this->sn_get_descendant_users($actor_user_id, $position) as $row) {
				$user_id = absint($row['user_id'] ?? 0);
				if ($user_id < 1 || ! $this->sn_distribution_user_is_active($user_id, (int) ($row['is_active'] ?? 0))) {
					continue;
				}
				$out[$user_id] = [
					'user_id' => $user_id,
					'position' => $position,
					'step_order' => $step_order_by_position[$position] ?? 0,
					'is_final' => $position === 'seller',
					'creates_live_lead' => false,
					'source' => 'hr_descendant_scope_all_allowed_levels',
				];
			}
		}
		$this->sn_distribution_scope_recipients_cache[$cache_key] = $out;
		return $out;
	}


	private function sn_distribution_direct_hr_recipients_for_actor(int $actor_user_id, string $position_slug = '', int $step_order = 0): array
	{
		$actor_user_id = absint($actor_user_id);
		$position_slug = sanitize_key($position_slug);
		$step_order = (int) $step_order;
		if ($actor_user_id < 1) {
			return [];
		}
		$cache_key = $actor_user_id . '|' . $position_slug . '|' . $step_order;
		if (isset($this->sn_distribution_direct_hr_recipients_cache[$cache_key])) {
			return (array) $this->sn_distribution_direct_hr_recipients_cache[$cache_key];
		}
		$actor_position = $this->sn_hr_position_for_user($actor_user_id);
		$rows = [];
		if ($position_slug !== '') {
			$rows = $this->sn_get_direct_children($actor_user_id, $position_slug);
		} elseif ($actor_position === 'supervisor') {
			$rows = $this->sn_get_direct_children($actor_user_id, 'seller');
		} elseif ($actor_position === 'senior_supervisor') {
			$rows = array_merge($this->sn_get_direct_children($actor_user_id, 'supervisor'), $this->sn_get_direct_children($actor_user_id, 'seller'));
		} elseif ($actor_position === 'sales_manager') {
			$rows = array_merge($this->sn_get_descendant_users($actor_user_id, 'senior_supervisor'), $this->sn_get_descendant_users($actor_user_id, 'supervisor'), $this->sn_get_descendant_users($actor_user_id, 'seller'));
		} elseif ($actor_position === 'sales_deputy') {
			$rows = $this->sn_get_direct_children($actor_user_id, 'sales_manager');
		} else {
			$rows = $this->sn_get_direct_children($actor_user_id, 'seller');
		}

		$out = [];
		foreach ($rows as $row) {
			$user_id = absint($row['user_id'] ?? 0);
			$position = sanitize_key((string) ($row['position_slug'] ?? $position_slug));
			if ($user_id < 1 || ! $position || ! $this->sn_distribution_user_is_active($user_id, (int) ($row['is_active'] ?? 0))) {
				continue;
			}
			$out[$user_id] = [
				'user_id' => $user_id,
				'position' => $position,
				'step_order' => $step_order,
				'is_final' => $position === 'seller',
				'creates_live_lead' => false,
				'source' => 'hr_direct_assignment',
			];
		}
		$this->sn_distribution_direct_hr_recipients_cache[$cache_key] = $out;
		return $out;
	}


	private function sn_distribution_primary_recipient_position_for_actor(int $actor_user_id): string
	{
		$actor_position = $this->sn_hr_position_for_user($actor_user_id);
		if ($actor_position === 'sales_deputy') {
			return 'sales_manager';
		}
		if ($actor_position === 'sales_manager') {
			return 'senior_supervisor';
		}
		if ($actor_position === 'senior_supervisor') {
			return 'supervisor';
		}
		return 'seller';
	}

	private function sn_distribution_primary_recipient_label_for_actor(int $actor_user_id): string
	{
		return $this->sn_distribution_position_label($this->sn_distribution_primary_recipient_position_for_actor($actor_user_id));
	}

	private function sn_distribution_default_recipient_options_for_actor(int $actor_user_id): array
	{
		$actor_user_id = absint($actor_user_id);
		if ($actor_user_id < 1) { return []; }
		if (isset($this->sn_distribution_default_recipients_cache[$actor_user_id])) {
			return (array) $this->sn_distribution_default_recipients_cache[$actor_user_id];
		}
		$actor_position = $this->sn_hr_position_for_user($actor_user_id);
		$chain = $this->sn_distribution_active_chain();
		$scope_positions = $this->sn_distribution_recipient_positions_for_actor($actor_user_id);
		if ($scope_positions) {
			$this->sn_distribution_default_recipients_cache[$actor_user_id] = $this->sn_distribution_scope_recipients_for_actor($actor_user_id, $scope_positions, (array) ($chain['steps'] ?? []));
			return (array) $this->sn_distribution_default_recipients_cache[$actor_user_id];
		}
		$steps = (array) ($chain['steps'] ?? []);
		foreach ($steps as $step) {
			if ((string) $step->from_position_slug !== $actor_position) {
				continue;
			}
			$options = $this->sn_distribution_direct_hr_recipients_for_actor($actor_user_id, (string) $step->to_position_slug, (int) $step->step_order);
			foreach ($options as &$option) {
				$option['is_final'] = (bool) (int) $step->is_final_delivery_step || $option['position'] === 'seller';
				$option['creates_live_lead'] = (bool) (int) $step->creates_live_lead;
			}
			unset($option);
			if ($options || empty($step->allow_skip_if_missing)) {
				$this->sn_distribution_default_recipients_cache[$actor_user_id] = $options;
				return $options;
			}
		}
		$this->sn_distribution_default_recipients_cache[$actor_user_id] = $this->sn_distribution_direct_hr_recipients_for_actor($actor_user_id);
		return (array) $this->sn_distribution_default_recipients_cache[$actor_user_id];
	}


	private function sn_distribution_recipient_options_for_actor(int $actor_user_id, array $items = []): array
	{
		$options = [];
		foreach ($items as $item) {
			foreach ($this->sn_distribution_next_recipients($actor_user_id, $item) as $rid => $recipient) {
				$options[(int) $rid] = $recipient;
			}
		}
		foreach ($this->sn_distribution_default_recipient_options_for_actor($actor_user_id) as $rid => $recipient) {
			$options[(int) $rid] = $options[(int) $rid] ?? $recipient;
		}
		ksort($options);
		return $options;
	}


	private function sn_distribution_transfer_filter_from_request(): array
	{
		$raw = sanitize_text_field(wp_unslash($_POST['distribution_case_filter'] ?? ''));
		$out = ['raw' => $raw, 'type' => '', 'value' => '', 'batch_id' => 0];
		if ($raw === '') {
			return $out;
		}
		[$type, $value] = array_pad(explode(':', $raw, 2), 2, '');
		$type = sanitize_key($type);
		$value = sanitize_text_field($value);
		if ($type === 'batch') {
			$out['type'] = 'batch';
			$out['batch_id'] = absint($value);
			$out['value'] = (string) $out['batch_id'];
			return $out;
		}
		if (in_array($type, ['campaign', 'category', 'source'], true) && $value !== '') {
			$out['type'] = $type;
			$out['value'] = $value;
			return $out;
		}
		return ['raw' => '', 'type' => '', 'value' => '', 'batch_id' => 0];
	}

	private function sn_distribution_item_matches_transfer_filter(object $item, array $filter): bool
	{
		$type = (string) ($filter['type'] ?? '');
		if ($type === '') {
			return true;
		}
		if ($type === 'batch') {
			return (int) ($item->batch_id ?? 0) === (int) ($filter['batch_id'] ?? 0);
		}
		if ($type === 'campaign') {
			return (string) ($item->campaign_code ?? '') === (string) ($filter['value'] ?? '');
		}
		if ($type === 'category') {
			return (string) ($item->data_category ?? '') === (string) ($filter['value'] ?? '');
		}
		if ($type === 'source') {
			return (string) ($item->source_type ?? '') === (string) ($filter['value'] ?? '');
		}
		return true;
	}

	private function sn_distribution_case_filter_value(object $item): string
	{
		$batch_id = (int) ($item->batch_id ?? 0);
		return $batch_id > 0 ? 'batch:' . $batch_id : '';
	}

	private function sn_distribution_case_label(object $item): string
	{
		$code = trim((string) ($item->batch_code ?? ''));
		$title = trim((string) ($item->batch_title ?? ''));
		$campaign = trim((string) ($item->campaign_code ?? ''));
		$parts = [];
		if ($code !== '') { $parts[] = $code; }
		if ($title !== '') { $parts[] = $title; }
		if ($campaign !== '') { $parts[] = 'کمپین: ' . $campaign; }
		return $parts ? implode(' / ', $parts) : 'بدون پرونده مشخص';
	}

	private function sn_distribution_case_groups_for_items(array $items, int $actor_id = 0): array
	{
		$groups = [];
		foreach ($items as $item) {
			$key = $this->sn_distribution_case_filter_value($item) ?: 'none';
			if (! isset($groups[$key])) {
				$groups[$key] = [
					'key' => $key,
					'batch_id' => (int) ($item->batch_id ?? 0),
					'batch_code' => (string) ($item->batch_code ?? ''),
					'batch_title' => (string) ($item->batch_title ?? ''),
					'source_type' => (string) ($item->source_type ?? ''),
					'source_label' => (string) ($item->source_label ?? ''),
					'campaign_code' => (string) ($item->campaign_code ?? ''),
					'data_category' => (string) ($item->data_category ?? ''),
					'label' => $this->sn_distribution_case_label($item),
					'total' => 0,
					'transferable' => 0,
				];
			}
			$groups[$key]['total']++;
			$status = (string) ($item->status ?? '');
			if (! in_array($status, ['delivered_to_seller', 'live_lead_created', 'cancelled'], true) && ($actor_id < 1 || $this->sn_distribution_next_recipients($actor_id, $item))) {
				$groups[$key]['transferable']++;
			}
		}
		uasort($groups, static function ($a, $b) {
			return ($b['total'] <=> $a['total']) ?: strcmp((string) $a['label'], (string) $b['label']);
		});
		return $groups;
	}

	private function sn_distribution_auto_candidate_scan_limit(int $target_total): int
	{
		$target_total = absint($target_total);
		if ($target_total < 1) { return 300; }
		return max(300, min(5000, ($target_total * 8) + 100));
	}

	private function sn_distribution_bulk_candidate_items(int $actor_user_id, int $limit = 300, array $case_filter = []): array
	{
		global $wpdb;
		if (! $this->sn_distribution_tables_ready()) { return []; }
		$actor_user_id = absint($actor_user_id);
		$limit = max(1, min(5000, $limit));
		$excluded_statuses = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error'];
		$status_placeholders = implode(',', array_fill(0, count($excluded_statuses), '%s'));
		$where = [
			'di.current_owner_user_id=%d',
			"COALESCE(di.source_type,'') <> 'paid_invoice_referral'",
			'(di.live_lead_id IS NULL OR di.live_lead_id=0)',
			'(di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)',
			"(di.status IS NULL OR di.status='' OR di.status NOT IN ({$status_placeholders}))",
		];
		$args = array_merge([$actor_user_id], $excluded_statuses);
		$type = (string) ($case_filter['type'] ?? '');
		if ($type === 'batch') {
			$where[] = 'di.batch_id=%d';
			$args[] = (int) ($case_filter['batch_id'] ?? 0);
		} elseif ($type === 'source') {
			$where[] = 'di.source_type=%s';
			$args[] = (string) ($case_filter['value'] ?? '');
		} elseif ($type === 'campaign') {
			$where[] = 'b.campaign_code=%s';
			$args[] = (string) ($case_filter['value'] ?? '');
		} elseif ($type === 'category') {
			$where[] = 'b.data_category=%s';
			$args[] = (string) ($case_filter['value'] ?? '');
		}
		$args[] = $limit;
		$sql = "SELECT di.*,
			COALESCE(NULLIF(di.normalized_phone,''), NULLIF(p.normalized_phone,''), NULLIF(di.customer_phone,''), p.customer_phone) AS normalized_phone,
			COALESCE(NULLIF(di.customer_phone,''), p.customer_phone) AS customer_phone,
			COALESCE(p.source_row_id, CASE WHEN di.source_type='mis_data_row' THEN di.source_id ELSE 0 END) AS resolved_source_row_id,
			COALESCE(p.id, di.pool_item_id, CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE 0 END) AS resolved_pool_id,
			b.batch_code, b.title batch_title, b.source_type batch_source_type, b.source_label, b.campaign_code, b.data_category
			FROM {$wpdb->prefix}sn_distribution_items di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), p.batch_id)
			WHERE " . implode(' AND ', $where) . "
			ORDER BY di.updated_at DESC, di.id DESC LIMIT %d";
		return $wpdb->get_results($wpdb->prepare($sql, ...$args)) ?: [];
	}


	private function sn_distribution_items_for_actor(int $actor_id, int $limit = 100): array
	{
		global $wpdb;
		if (! $this->sn_distribution_tables_ready()) { return []; }
		$limit = max(1, min(5000, $limit));
		$select_sql = "SELECT di.*, COALESCE(p.customer_name,r.customer_name) customer_name, COALESCE(p.customer_phone,r.customer_phone) customer_phone, COALESCE(p.normalized_phone,r.normalized_phone) normalized_phone, COALESCE(p.city,r.city) city, COALESCE(p.province,r.province) province, b.batch_code, b.title batch_title, b.source_type batch_source_type, b.source_label, b.campaign_code, b.data_category,
			COALESCE(p.source_row_id, CASE WHEN di.source_type='mis_data_row' THEN di.source_id ELSE 0 END) AS resolved_source_row_id,
			COALESCE(p.id, di.pool_item_id, CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE 0 END) AS resolved_pool_id
			FROM {$wpdb->prefix}sn_distribution_items di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)";
		$excluded_statuses = ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error'];
		$status_placeholders = implode(',', array_fill(0, count($excluded_statuses), '%s'));
		if (current_user_can('manage_options')) {
			return $wpdb->get_results($wpdb->prepare(
				"{$select_sql}
				WHERE COALESCE(di.source_type,'') <> 'paid_invoice_referral'
					AND (di.live_lead_id IS NULL OR di.live_lead_id=0)
					AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)
					AND (di.status IS NULL OR di.status='' OR di.status NOT IN ({$status_placeholders}))
				ORDER BY di.updated_at DESC, di.id DESC LIMIT %d",
				...array_merge($excluded_statuses, [$limit])
			)) ?: [];
		}
		return $wpdb->get_results($wpdb->prepare(
			"{$select_sql}
			WHERE di.current_owner_user_id=%d
				AND COALESCE(di.source_type,'') <> 'paid_invoice_referral'
				AND (di.live_lead_id IS NULL OR di.live_lead_id=0)
				AND (di.final_seller_user_id IS NULL OR di.final_seller_user_id=0)
				AND (di.status IS NULL OR di.status='' OR di.status NOT IN ({$status_placeholders}))
			ORDER BY di.updated_at DESC, di.id DESC LIMIT %d",
			...array_merge([$actor_id], $excluded_statuses, [$limit])
		)) ?: [];
	}


	private function sn_distribution_items_by_ids(array $item_ids): array
	{
		global $wpdb;
		$item_ids = array_values(array_unique(array_filter(array_map('absint', $item_ids))));
		if (! $item_ids || ! $this->sn_distribution_tables_ready()) { return []; }
		$item_ids = array_slice($item_ids, 0, 5000);
		$placeholders = implode(',', array_fill(0, count($item_ids), '%d'));
		$select_sql = "SELECT di.*, COALESCE(p.customer_name,r.customer_name) customer_name, COALESCE(p.customer_phone,r.customer_phone) customer_phone, COALESCE(p.normalized_phone,r.normalized_phone) normalized_phone, COALESCE(p.city,r.city) city, COALESCE(p.province,r.province) province, b.batch_code, b.title batch_title, b.source_type batch_source_type, b.source_label, b.campaign_code, b.data_category,
			COALESCE(p.source_row_id, CASE WHEN di.source_type='mis_data_row' THEN di.source_id ELSE 0 END) AS resolved_source_row_id,
			COALESCE(p.id, di.pool_item_id, CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE 0 END) AS resolved_pool_id
			FROM {$wpdb->prefix}sn_distribution_items di
			LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id = COALESCE(NULLIF(di.pool_item_id,0), CASE WHEN di.source_type='mis_pool' THEN di.source_id ELSE NULL END)
			LEFT JOIN {$wpdb->prefix}sn_mis_data_rows r ON (di.source_type='mis_data_row' AND r.id=di.source_id) OR (p.source_row_id IS NOT NULL AND r.id=p.source_row_id)
			LEFT JOIN {$wpdb->prefix}sn_mis_import_batches b ON b.id = COALESCE(NULLIF(di.batch_id,0), r.batch_id, p.batch_id)
			WHERE di.id IN ({$placeholders})";
		$rows = $wpdb->get_results($wpdb->prepare($select_sql, ...$item_ids)) ?: [];
		$out = [];
		foreach ($rows as $row) {
			$out[(int) $row->id] = $row;
		}
		return $out;
	}


	private function sn_distribution_transferred_out_count(int $actor_id): int
	{
		global $wpdb;
		if ($actor_id < 1 || ! $this->sn_mis_table_exists('sn_distribution_item_logs')) {
			return 0;
		}
		return (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_item_logs WHERE actor_user_id=%d AND action IN ('distributed_forward','delivered_to_seller')",
			$actor_id
		));
	}


	private function sn_distribution_total_received_count(int $actor_id): int
	{
		global $wpdb;
		$actor_id = absint($actor_id);
		if ($actor_id < 1 || ! $this->sn_distribution_tables_ready()) { return 0; }
		$item_table = $wpdb->prefix . 'sn_distribution_items';
		$log_table = $wpdb->prefix . 'sn_distribution_item_logs';
		return (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(DISTINCT x.item_id) FROM (
				SELECT id AS item_id FROM {$item_table} WHERE current_owner_user_id=%d OR final_seller_user_id=%d
				UNION ALL
				SELECT item_id FROM {$log_table} WHERE to_user_id=%d OR actor_user_id=%d
			) x",
			$actor_id, $actor_id, $actor_id, $actor_id
		));
	}

	private function sn_distribution_actor_debug(int $actor_id, array $items): array
	{
		global $wpdb;
		$debug = [
			'current_user_id' => $actor_id,
			'hr_profile_id' => 0,
			'hr_position' => $this->sn_hr_position_for_user($actor_id),
			'expected_panel_key' => ($this->sn_hr_position_for_user($actor_id) ?: 'unknown') . '_panel',
			'can_access_sales_manager_panel' => current_user_can('manage_options') || current_user_can('sn_view_sales_reports') || $this->sn_user_has_hr_position($actor_id, 'sales_manager'),
			'can_access_distribution_role_section' => current_user_can('manage_options') || $this->sn_user_has_hr_position($actor_id, ['sales_deputy', 'sales_manager', 'senior_supervisor', 'supervisor', 'seller']),
			'owner_filter_user_id' => $actor_id,
			'owned_items_count' => count($items),
			'helper_name' => 'sn_distribution_items_for_actor',
			'query_source' => 'sn_distribution_items.current_owner_user_id',
			'status_policy' => 'include assigned_to_role/delivered_to_role/distributed_forward; exclude archived/converted/error/cancelled and live_lead_id>0',
			'items_sample' => [],
		];
		if (class_exists('SN_HR_Service')) {
			$profile = (new SN_HR_Service())->get_profile_by_user_id($actor_id);
			$debug['hr_profile_id'] = $profile ? (int) $profile->id : 0;
		}
		foreach (array_slice($items, 0, 10) as $item) {
			$debug['items_sample'][] = [
				'id' => (int) ($item->id ?? 0),
				'current_owner_user_id' => (int) ($item->current_owner_user_id ?? 0),
				'current_owner_position' => (string) ($item->current_owner_position ?? ''),
				'status' => (string) ($item->status ?? ''),
				'source_type' => (string) ($item->source_type ?? ''),
				'batch_id' => (int) ($item->batch_id ?? 0),
				'phone_masked' => $this->sn_mask_phone((string) (($item->normalized_phone ?? '') ?: ($item->customer_phone ?? ''))),
			];
		}
		if (current_user_can('manage_options') && $this->sn_distribution_tables_ready()) {
			$debug['all_distribution_items_count'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items");
			$debug['owned_items_count_db'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d", $actor_id));
			$debug['status_counts_for_owner'] = [];
			$status_rows = $wpdb->get_results($wpdb->prepare("SELECT COALESCE(status,'') status, COUNT(*) c FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d GROUP BY status ORDER BY c DESC", $actor_id)) ?: [];
			foreach ($status_rows as $row) {
				$debug['status_counts_for_owner'][(string) $row->status] = (int) $row->c;
			}
			$debug['source_counts_for_owner'] = [];
			$source_rows = $wpdb->get_results($wpdb->prepare("SELECT COALESCE(source_type,'') source_type, COUNT(*) c FROM {$wpdb->prefix}sn_distribution_items WHERE current_owner_user_id=%d GROUP BY source_type ORDER BY c DESC", $actor_id)) ?: [];
			foreach ($source_rows as $row) {
				$debug['source_counts_for_owner'][(string) $row->source_type] = (int) $row->c;
			}
			$debug['query_args'] = [
				'current_owner_user_id' => $actor_id,
				'excluded_statuses' => ['archived', 'cancelled', 'converted', 'lead_created', 'live_lead_created', 'duplicate', 'error'],
				'live_lead_id' => 'NULL or 0',
			];
			if (! $items) {
				$debug['reason'] = $debug['owned_items_count_db'] < 1 ? 'no_owned_items' : 'status_or_live_lead_filter_excluded';
			}
		}
		return $debug;
	}

	private function sn_distribution_item_logs(int $item_id, int $limit = 20): array
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_distribution_item_logs')) { return []; }
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_distribution_item_logs WHERE item_id=%d ORDER BY id DESC LIMIT %d", $item_id, $limit)) ?: [];
	}

	private function sn_distribution_log(int $item_id, string $action, int $actor_id, int $from_user_id, int $to_user_id, string $from_position, string $to_position, int $step_order, string $note = '', array $payload = []): void
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_distribution_item_logs')) { return; }
		$wpdb->insert($wpdb->prefix . 'sn_distribution_item_logs', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_item_logs', [
			'item_id' => $item_id,
			'action' => $action,
			'actor_user_id' => $actor_id ?: null,
			'from_user_id' => $from_user_id ?: null,
			'to_user_id' => $to_user_id ?: null,
			'from_position' => $from_position,
			'to_position' => $to_position,
			'step_order' => $step_order,
			'note' => $note,
			'payload_json' => wp_json_encode($this->sn_mask_sensitive_array($payload), JSON_UNESCAPED_UNICODE),
			'created_at' => current_time('mysql'),
		]));
	}

	private function sn_mask_sensitive_array(array $data): array
	{
		$out = [];
		foreach ($data as $key => $value) {
			$key_string = (string) $key;
			if (is_array($value)) {
				$out[$key] = $this->sn_mask_sensitive_array($value);
				continue;
			}
			if (preg_match('/phone|mobile|token|password|url|access/i', $key_string)) {
				$out[$key] = $this->sn_after_sales_mask_sensitive_text((string) $value);
				continue;
			}
			$out[$key] = $value;
		}
		return $out;
	}

