	private function sn_distribution_render_role_section(int $actor_id, array $args = []): void
	{
		$this->sn_distribution_ensure_schema();
		$item_limit = max(50, min(2500, absint($args['item_limit'] ?? 2500)));
		$row_log_limit = max(0, min(10, absint($args['row_log_limit'] ?? 10)));
		$items = $this->sn_distribution_items_for_actor($actor_id, $item_limit);
		$case_groups = $this->sn_distribution_case_groups_for_items($items, $actor_id);
		$returnable_items = $this->sn_distribution_returnable_items_for_actor($actor_id, $item_limit);
		$return_case_groups = $this->sn_distribution_case_groups_for_items($returnable_items, $actor_id);
		$returnable_count = count($returnable_items);
		$return_report = get_option('sn_distribution_return_report', []);
		if (! is_array($return_report)) { $return_report = []; }
		if ($return_report && ! current_user_can('manage_options') && (int) ($return_report['actor_user_id'] ?? 0) !== $actor_id) { $return_report = []; }
		$report = get_option('sn_distribution_transfer_report', []);
		if (! is_array($report)) {
			$report = [];
		}
		if ($report && ! current_user_can('manage_options') && (int) ($report['actor_user_id'] ?? 0) !== $actor_id) {
			$report = [];
		}
		$mode = sanitize_key((string) ($args['mode'] ?? 'standalone'));
		$title = (string) ($args['title'] ?? 'پخش داده در زنجیره فروش');
		$subtitle = (string) ($args['subtitle'] ?? 'فقط آیتم‌هایی که مالک فعلی آن‌ها شما هستید قابل پخش هستند. گیرنده‌ها از زنجیره فعال و زیرمجموعه HR شما محاسبه می‌شوند.');
		$empty_message = (string) ($args['empty_message'] ?? 'فعلاً آیتم پخشی برای شما وجود ندارد.');
		$show_inline_note = ! empty($args['show_inline_note']);
		$show_report = ! empty($args['show_report']);
		$show_debug = ! empty($args['show_debug']);
		$is_embedded = $mode === 'embedded';
		$recipient_options = $this->sn_distribution_recipient_options_for_actor($actor_id, $items);
		$owned_count = count($items);
		$transferable_count = 0;
		foreach ($items as $item) {
			$status = (string) ($item->status ?? '');
			if (! in_array($status, ['delivered_to_seller', 'live_lead_created', 'cancelled'], true) && $this->sn_distribution_next_recipients($actor_id, $item)) {
				$transferable_count++;
			}
		}
		$transferred_out = $this->sn_distribution_transferred_out_count($actor_id);
		$total_received_ever = $this->sn_distribution_total_received_count($actor_id);
		$primary_recipient_position = $this->sn_distribution_primary_recipient_position_for_actor($actor_id);
		$primary_recipient_label = $this->sn_distribution_primary_recipient_label_for_actor($actor_id);
		$primary_recipients = $recipient_options;
		$primary_recipient_label = 'گیرنده مجاز';
		$recipient_positions = [];
		foreach ($primary_recipients as $recipient) {
			$pos = sanitize_key((string) ($recipient['position'] ?? ''));
			if ($pos !== '') { $recipient_positions[$pos] = $this->sn_distribution_position_label($pos); }
		}
		uksort($recipient_positions, function($a, $b) {
			$order = ['sales_manager'=>5, 'senior_supervisor'=>10, 'supervisor'=>20, 'seller'=>30];
			return ($order[$a] ?? 999) <=> ($order[$b] ?? 999);
		});
		$active_sellers = count(array_filter($recipient_options, static fn($recipient) => ($recipient['position'] ?? '') === 'seller'));
		$active_primary_recipients = count($primary_recipients);
		$debug = $this->sn_distribution_actor_debug($actor_id, $items);
		$debug['hr_direct_seller_ids'] = array_values(array_map('intval', array_keys(array_filter($this->sn_distribution_direct_hr_recipients_for_actor($actor_id, 'seller'), static fn($recipient) => ($recipient['position'] ?? '') === 'seller'))));
		$debug['allowed_recipient_ids'] = array_values(array_map('intval', array_keys($recipient_options)));
		$debug['primary_recipient_position'] = $primary_recipient_position;
		$debug['primary_recipient_ids'] = array_values(array_map('intval', array_keys($primary_recipients)));
		$debug['owned_distribution_item_count'] = $owned_count;
		$debug['case_groups_count'] = count($case_groups);
		$debug['transferable_item_count'] = $transferable_count;
		$debug['reason_dropdown_empty'] = $recipient_options ? '' : ($active_sellers < 1 ? 'no_hr_sellers' : 'render_bug');
		$wrapper_class = $is_embedded
			? 'sn-card sn-supervisor-v4-distribution sn-distribution-role sn-distribution-role-embedded sn-distribution-allocation-ux'
			: 'sn-card sn-section sn-distribution-role sn-distribution-allocation-ux';
		$controls_disabled = $owned_count < 1 || $transferable_count < 1 || ! $recipient_options;
		$no_owned_with_sellers = $active_primary_recipients > 0 && $owned_count < 1;
		$owned_without_sellers = $active_primary_recipients < 1 && $owned_count > 0;
		?>
		<div class="<?php echo esc_attr($wrapper_class); ?>">
			<div class="sn-distribution-head">
				<div>
					<h3 class="sn-section-title"><?php echo esc_html($title); ?></h3>
					<?php if ($subtitle !== '') : ?><p class="sn-note"><?php echo esc_html($subtitle); ?></p><?php endif; ?>
				</div>
				<span class="sn-badge"><?php echo esc_html(number_format_i18n($owned_count)); ?></span>
			</div>
			<div class="sn-grid sn-distribution-kpis sn-distribution-card-kpis">
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($total_received_ever)); ?></strong><span>کل دیتای دریافتی از ابتدا</span></div>
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($owned_count)); ?></strong><span>مانده فعلی در پنل</span></div>
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($transferable_count)); ?></strong><span>آماده تخصیص</span></div>
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($active_primary_recipients)); ?></strong><span>گیرنده‌های مجاز زیرمجموعه</span></div>
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($transferred_out)); ?></strong><span>تخصیص‌داده‌شده توسط شما</span></div>
				<div class="sn-distribution-kpi-card"><strong><?php echo esc_html(number_format_i18n($returnable_count)); ?></strong><span>قابل برگشت به پنل من</span></div>
			</div>
			<?php if ($case_groups) : ?>
				<div class="sn-distribution-case-summary">
					<div class="sn-distribution-case-summary-head">
						<strong>پرونده‌های دیتای تحویل‌شده به شما</strong>
						<span class="sn-muted">برای تخصیص درست، اول پرونده/کد دیتا را تشخیص بده، بعد همان پرونده را بین نیروها پخش کن.</span>
					</div>
					<div class="sn-distribution-case-grid">
						<?php foreach ($case_groups as $group) : ?>
							<div class="sn-distribution-case-card" data-case-filter="<?php echo esc_attr((string) $group['key']); ?>">
								<div class="sn-case-card-top"><strong><?php echo esc_html((string) ($group['batch_title'] ?: $group['batch_code'] ?: 'بدون عنوان')); ?></strong><span><?php echo esc_html(number_format_i18n((int) $group['transferable'])); ?> قابل تخصیص</span></div>
								<div class="sn-case-card-meta">
									<?php if (! empty($group['batch_code'])) : ?><span>کد: <?php echo esc_html((string) $group['batch_code']); ?></span><?php endif; ?>
									<?php if (! empty($group['campaign_code'])) : ?><span>کمپین: <?php echo esc_html((string) $group['campaign_code']); ?></span><?php endif; ?>
									<?php if (! empty($group['data_category'])) : ?><span>دسته: <?php echo esc_html((string) $group['data_category']); ?></span><?php endif; ?>
									<?php if (! empty($group['source_label']) || ! empty($group['source_type'])) : ?><span>منبع: <?php echo esc_html(trim((string) ($group['source_label'] ?: $group['source_type']))); ?></span><?php endif; ?>
								</div>
								<small>کل در اختیار شما: <?php echo esc_html(number_format_i18n((int) $group['total'])); ?></small>
							</div>
						<?php endforeach; ?>
					</div>
				</div>
			<?php endif; ?>
