	private function sn_mis_last_table_error(string $table, array $repair_report): string
	{
		global $wpdb;
		$full = strpos($table, $wpdb->prefix) === 0 ? $table : $wpdb->prefix . ltrim($table, '_');
		foreach ((array) ($repair_report['table_errors'] ?? []) as $error) {
			if (($error['table'] ?? '') === $full) {
				return (string) ($error['message'] ?? '');
			}
		}
		return '';
	}

	private function sn_mis_perf_cache_key(string $key): string
	{
		return 'sn_mis_perf_' . sanitize_key($key) . '_v135';
	}

	private function sn_mis_perf_cache_get(string $key): ?array
	{
		$value = get_transient($this->sn_mis_perf_cache_key($key));
		return is_array($value) ? $value : null;
	}

	private function sn_mis_perf_cache_set(string $key, array $value, int $ttl = 30): array
	{
		set_transient($this->sn_mis_perf_cache_key($key), $value, max(5, min(300, $ttl)));
		return $value;
	}

	private function sn_mis_clear_performance_cache(): void
	{
		foreach (['summary','operator_pipeline','batch_operational_20','batch_operational_50','lead_pool_summary','launch_self_check','sales_managers'] as $key) {
			delete_transient($this->sn_mis_perf_cache_key($key));
		}
	}

	private function sn_mis_core_tables_ready_fast(): bool
	{
		global $wpdb;
		foreach (['sn_mis_import_batches','sn_mis_data_rows'] as $table) {
			$full = $wpdb->prefix . $table;
			if (! $this->sn_table_exists_quiet($full)) { return false; }
		}
		return true;
	}

	private function sn_mis_summary(): array
	{
		$cached = $this->sn_mis_perf_cache_get('summary');
		if ($cached !== null) { return $cached; }
		global $wpdb;
		$b = $wpdb->prefix . 'sn_mis_import_batches';
		$r = $wpdb->prefix . 'sn_mis_data_rows';
		$empty = [
			'کل پرونده‌ها' => '0',
			'کل ردیف‌های واردشده' => '0',
			'ردیف معتبر' => '0',
			'ردیف تکراری' => '0',
			'ردیف نامعتبر' => '0',
			'ردیف معتبر بدون مدیر' => '0',
			'اختصاص‌یافته به مدیر فروش' => '0',
			'کمپین‌ها' => '0',
			'دسته‌ها' => '0',
			'آخرین ورود فایل' => '',
		];
		if (! $this->sn_mis_table_exists($b) || ! $this->sn_mis_table_exists($r)) {
			return $empty;
		}
		$batch = $wpdb->get_row("SELECT COUNT(*) batches,
			COALESCE(SUM(total_rows),0) total_rows,
			COALESCE(SUM(valid_rows),0) valid_rows,
			COALESCE(SUM(duplicate_rows),0) duplicate_rows,
			COALESCE(SUM(invalid_rows),0) invalid_rows,
			COUNT(DISTINCT NULLIF(campaign_code,'')) campaigns,
			COUNT(DISTINCT NULLIF(data_category,'')) categories,
			MAX(created_at) last_batch_created
			FROM {$b}", ARRAY_A);
		$total_rows = (int) ($batch['total_rows'] ?? 0);
		$valid_rows = (int) ($batch['valid_rows'] ?? 0);
		$duplicate_rows = (int) ($batch['duplicate_rows'] ?? 0);
		$invalid_rows = (int) ($batch['invalid_rows'] ?? 0);
		if ($total_rows < 1 && (int) ($batch['batches'] ?? 0) > 0) {
			// Fallback for old batches whose aggregate columns were not maintained yet.
			$row_counts = $wpdb->get_row("SELECT COUNT(*) total_rows,
				SUM(CASE WHEN row_status='valid' THEN 1 ELSE 0 END) valid_rows,
				SUM(CASE WHEN row_status='duplicate' THEN 1 ELSE 0 END) duplicate_rows,
				SUM(CASE WHEN row_status='invalid' THEN 1 ELSE 0 END) invalid_rows
				FROM {$r}", ARRAY_A);
			$total_rows = (int) ($row_counts['total_rows'] ?? 0);
			$valid_rows = (int) ($row_counts['valid_rows'] ?? 0);
			$duplicate_rows = (int) ($row_counts['duplicate_rows'] ?? 0);
			$invalid_rows = (int) ($row_counts['invalid_rows'] ?? 0);
		}
		$assigned_rows = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$r} WHERE row_status='valid' AND assigned_manager_user_id IS NOT NULL AND assigned_manager_user_id > 0");
		$unassigned_valid_rows = max(0, $valid_rows - $assigned_rows);
		$out = [
			'کل پرونده‌ها' => number_format_i18n((int) ($batch['batches'] ?? 0)),
			'کل ردیف‌های واردشده' => number_format_i18n($total_rows),
			'ردیف معتبر' => number_format_i18n($valid_rows),
			'ردیف تکراری' => number_format_i18n($duplicate_rows),
			'ردیف نامعتبر' => number_format_i18n($invalid_rows),
			'ردیف معتبر بدون مدیر' => number_format_i18n($unassigned_valid_rows),
			'اختصاص‌یافته به مدیر فروش' => number_format_i18n($assigned_rows),
			'کمپین‌ها' => number_format_i18n((int) ($batch['campaigns'] ?? 0)),
			'دسته‌ها' => number_format_i18n((int) ($batch['categories'] ?? 0)),
			'آخرین ورود فایل' => (string) ($batch['last_batch_created'] ?: $wpdb->get_var("SELECT MAX(created_at) FROM {$r}")),
		];
		return $this->sn_mis_perf_cache_set('summary', $out, 20);
	}

	private function sn_mis_operator_pipeline_counts(): array
	{
		$cached = $this->sn_mis_perf_cache_get('operator_pipeline');
		if ($cached !== null) { return $cached; }
		global $wpdb;
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$batches = $wpdb->prefix . 'sn_mis_import_batches';
		$out = [
			'batches' => 0,
			'total_rows' => 0,
			'valid_rows' => 0,
			'duplicate_rows' => 0,
			'invalid_rows' => 0,
			'unassigned_valid' => 0,
			'assigned_to_manager' => 0,
			'eligible_to_pool' => 0,
			'pool_total' => 0,
			'pool_ready' => 0,
			'distribution_total' => 0,
			'delivered_to_seller' => 0,
			'converted_rows' => 0,
			'returnable_direct' => 0,
			'returnable_with_distribution' => 0,
			'locked_rows' => 0,
		];
		if ($this->sn_mis_table_exists($batches)) {
			$batch = $wpdb->get_row("SELECT COUNT(*) batches,
				COALESCE(SUM(total_rows),0) total_rows,
				COALESCE(SUM(valid_rows),0) valid_rows,
				COALESCE(SUM(duplicate_rows),0) duplicate_rows,
				COALESCE(SUM(invalid_rows),0) invalid_rows
				FROM {$batches}", ARRAY_A);
			foreach (['batches','total_rows','valid_rows','duplicate_rows','invalid_rows'] as $key) {
				$out[$key] = (int) ($batch[$key] ?? 0);
			}
		}
		if (! $this->sn_mis_table_exists($rows)) { return $out; }
		// One indexed pass over rows for live assignment counters; avoids multiple COUNT(*) requests.
		$row_counts = $wpdb->get_row("SELECT
			SUM(CASE WHEN row_status='valid' AND (assigned_manager_user_id IS NULL OR assigned_manager_user_id=0) THEN 1 ELSE 0 END) unassigned_valid,
			SUM(CASE WHEN row_status='valid' AND assigned_manager_user_id IS NOT NULL AND assigned_manager_user_id>0 THEN 1 ELSE 0 END) assigned_to_manager
			FROM {$rows}", ARRAY_A);
		$out['unassigned_valid'] = (int) ($row_counts['unassigned_valid'] ?? max(0, $out['valid_rows'] - $out['assigned_to_manager']));
		$out['assigned_to_manager'] = (int) ($row_counts['assigned_to_manager'] ?? 0);
		if ($out['total_rows'] < 1) {
			$row_total_counts = $wpdb->get_row("SELECT COUNT(*) total_rows,
				SUM(CASE WHEN row_status='valid' THEN 1 ELSE 0 END) valid_rows,
				SUM(CASE WHEN row_status='duplicate' THEN 1 ELSE 0 END) duplicate_rows,
				SUM(CASE WHEN row_status='invalid' THEN 1 ELSE 0 END) invalid_rows
				FROM {$rows}", ARRAY_A);
			foreach (['total_rows','valid_rows','duplicate_rows','invalid_rows'] as $key) { $out[$key] = (int) ($row_total_counts[$key] ?? 0); }
		}
		if ($this->sn_mis_table_exists($pool)) {
			$pool_counts = $wpdb->get_row("SELECT COUNT(*) pool_total,
				SUM(CASE WHEN pool_status='ready' THEN 1 ELSE 0 END) pool_ready,
				COUNT(DISTINCT source_row_id) already_pooled
				FROM {$pool}", ARRAY_A);
			$out['pool_total'] = (int) ($pool_counts['pool_total'] ?? 0);
			$out['pool_ready'] = (int) ($pool_counts['pool_ready'] ?? 0);
			$out['eligible_to_pool'] = max(0, (int) $out['assigned_to_manager'] - (int) ($pool_counts['already_pooled'] ?? 0));
		} else {
			$out['eligible_to_pool'] = (int) $out['assigned_to_manager'];
		}
		if ($this->sn_distribution_tables_ready()) {
			$item_counts = $wpdb->get_row("SELECT COUNT(*) distribution_total,
				SUM(CASE WHEN status='delivered_to_seller' THEN 1 ELSE 0 END) delivered_to_seller,
				SUM(CASE WHEN (live_lead_id IS NOT NULL AND live_lead_id>0) OR status IN ('converted','lead_created','live_lead_created') THEN 1 ELSE 0 END) converted_rows,
				SUM(CASE WHEN COALESCE(live_lead_id,0)=0 AND COALESCE(status,'') NOT IN ('converted','lead_created','live_lead_created','archived','cancelled','referral_cancelled','returned_to_mis') THEN 1 ELSE 0 END) returnable_with_distribution
				FROM {$items}", ARRAY_A);
			foreach (['distribution_total','delivered_to_seller','converted_rows','returnable_with_distribution'] as $key) {
				$out[$key] = (int) ($item_counts[$key] ?? 0);
			}
		}
		$out['locked_rows'] = (int) $out['converted_rows'];
		$out['returnable_direct'] = (int) $out['eligible_to_pool'];
		return $this->sn_mis_perf_cache_set('operator_pipeline', $out, 20);
	}

	private function sn_mis_batch_operational_stats(int $limit = 50): array
	{
		$limit = max(1, min(50, $limit));
		$cache_key = $limit <= 20 ? 'batch_operational_20' : 'batch_operational_50';
		$cached = $this->sn_mis_perf_cache_get($cache_key);
		if ($cached !== null) { return $cached; }
		global $wpdb;
		$batches = $wpdb->prefix . 'sn_mis_import_batches';
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$items = $wpdb->prefix . 'sn_distribution_items';
		$out = [];
		if ($this->sn_mis_table_exists($batches)) {
			$base_rows = $wpdb->get_results($wpdb->prepare("SELECT id AS batch_id,
				COALESCE(total_rows,0) total_rows,
				COALESCE(valid_rows,0) valid_rows,
				COALESCE(duplicate_rows,0) duplicate_rows,
				COALESCE(invalid_rows,0) invalid_rows
				FROM {$batches} ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
		} elseif ($this->sn_mis_table_exists($rows)) {
			$base_rows = $wpdb->get_results($wpdb->prepare("SELECT batch_id,
				COUNT(*) total_rows,
				SUM(CASE WHEN row_status='valid' THEN 1 ELSE 0 END) valid_rows,
				SUM(CASE WHEN row_status='duplicate' THEN 1 ELSE 0 END) duplicate_rows,
				SUM(CASE WHEN row_status='invalid' THEN 1 ELSE 0 END) invalid_rows
				FROM {$rows} GROUP BY batch_id ORDER BY batch_id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
		} else {
			return [];
		}
		foreach ($base_rows as $row) {
			$batch_id = (int) ($row['batch_id'] ?? 0);
			if ($batch_id < 1) { continue; }
			$out[$batch_id] = [
				'total_rows' => (int) ($row['total_rows'] ?? 0),
				'valid_rows' => (int) ($row['valid_rows'] ?? 0),
				'duplicate_rows' => (int) ($row['duplicate_rows'] ?? 0),
				'invalid_rows' => (int) ($row['invalid_rows'] ?? 0),
				'unassigned_valid' => 0,
				'assigned_to_manager' => 0,
				'eligible_to_pool' => 0,
				'pool_total' => 0,
				'pool_ready' => 0,
				'distribution_total' => 0,
				'delivered_to_seller' => 0,
				'converted_rows' => 0,
				'returnable_direct' => 0,
				'returnable_with_distribution' => 0,
				'duplicate_valid_same_batch' => 0,
			];
		}
		if (! $out || ! $this->sn_mis_table_exists($rows)) {
			return $this->sn_mis_perf_cache_set($cache_key, $out, 20);
		}
		$batch_ids = array_keys($out);
		$in = implode(',', array_map('intval', $batch_ids));
		foreach (($wpdb->get_results("SELECT batch_id,
			SUM(CASE WHEN row_status='valid' AND (assigned_manager_user_id IS NULL OR assigned_manager_user_id=0) THEN 1 ELSE 0 END) unassigned_valid,
			SUM(CASE WHEN row_status='valid' AND assigned_manager_user_id IS NOT NULL AND assigned_manager_user_id>0 THEN 1 ELSE 0 END) assigned_to_manager
			FROM {$rows} WHERE batch_id IN ({$in}) GROUP BY batch_id", ARRAY_A) ?: []) as $row) {
			$batch_id = (int) ($row['batch_id'] ?? 0);
			if (isset($out[$batch_id])) {
				$out[$batch_id]['unassigned_valid'] = (int) ($row['unassigned_valid'] ?? 0);
				$out[$batch_id]['assigned_to_manager'] = (int) ($row['assigned_to_manager'] ?? 0);
			}
		}
		if ($this->sn_mis_table_exists($pool)) {
			foreach (($wpdb->get_results("SELECT batch_id, COUNT(*) pool_total, SUM(CASE WHEN pool_status='ready' THEN 1 ELSE 0 END) pool_ready, COUNT(DISTINCT source_row_id) already_pooled FROM {$pool} WHERE batch_id IN ({$in}) GROUP BY batch_id", ARRAY_A) ?: []) as $row) {
				$batch_id = (int) ($row['batch_id'] ?? 0);
				if (! isset($out[$batch_id])) { continue; }
				$out[$batch_id]['pool_total'] = (int) ($row['pool_total'] ?? 0);
				$out[$batch_id]['pool_ready'] = (int) ($row['pool_ready'] ?? 0);
				$out[$batch_id]['eligible_to_pool'] = max(0, (int) ($out[$batch_id]['assigned_to_manager'] ?? 0) - (int) ($row['already_pooled'] ?? 0));
			}
		} else {
			foreach ($out as $batch_id => $row) { $out[$batch_id]['eligible_to_pool'] = (int) ($row['assigned_to_manager'] ?? 0); }
		}
		if ($this->sn_distribution_tables_ready()) {
			foreach (($wpdb->get_results("SELECT batch_id, COUNT(*) distribution_total,
				SUM(CASE WHEN status='delivered_to_seller' THEN 1 ELSE 0 END) delivered_to_seller,
				SUM(CASE WHEN (live_lead_id IS NOT NULL AND live_lead_id>0) OR status IN ('converted','lead_created','live_lead_created') THEN 1 ELSE 0 END) converted_rows,
				SUM(CASE WHEN COALESCE(live_lead_id,0)=0 AND COALESCE(status,'') NOT IN ('converted','lead_created','live_lead_created','archived','cancelled','referral_cancelled','returned_to_mis') THEN 1 ELSE 0 END) returnable_with_distribution
				FROM {$items} WHERE batch_id IN ({$in}) GROUP BY batch_id", ARRAY_A) ?: []) as $row) {
				$batch_id = (int) ($row['batch_id'] ?? 0);
				if (! isset($out[$batch_id])) { continue; }
				$out[$batch_id]['distribution_total'] = (int) ($row['distribution_total'] ?? 0);
				$out[$batch_id]['delivered_to_seller'] = (int) ($row['delivered_to_seller'] ?? 0);
				$out[$batch_id]['converted_rows'] = (int) ($row['converted_rows'] ?? 0);
				$out[$batch_id]['returnable_with_distribution'] = (int) ($row['returnable_with_distribution'] ?? 0);
			}
		}
		if ($this->sn_distribution_tables_ready()) {
			$active_item_condition = "COALESCE(di.status,'') NOT IN ('returned_to_mis','archived','cancelled','referral_cancelled')";
			foreach (($wpdb->get_results("SELECT r.batch_id,
				SUM(CASE WHEN r.row_status='valid' AND (r.assigned_manager_user_id IS NULL OR r.assigned_manager_user_id=0) AND di.id IS NULL THEN 1 ELSE 0 END) unassigned_valid,
				SUM(CASE WHEN r.row_status='valid' AND r.assigned_manager_user_id IS NOT NULL AND r.assigned_manager_user_id>0 AND di.id IS NULL THEN 1 ELSE 0 END) assigned_to_manager
				FROM {$rows} r
				LEFT JOIN {$items} di ON di.source_type='mis_data_row' AND di.source_id=r.id AND {$active_item_condition}
				WHERE r.batch_id IN ({$in}) GROUP BY r.batch_id", ARRAY_A) ?: []) as $row) {
				$batch_id = (int) ($row['batch_id'] ?? 0);
				if (! isset($out[$batch_id])) { continue; }
				$out[$batch_id]['unassigned_valid'] = (int) ($row['unassigned_valid'] ?? 0);
				$out[$batch_id]['assigned_to_manager'] = (int) ($row['assigned_to_manager'] ?? 0);
			}
		}
		foreach (($wpdb->get_results("SELECT batch_id, SUM(cnt - 1) duplicate_valid_same_batch FROM (
			SELECT batch_id, normalized_phone, COUNT(*) cnt
			FROM {$rows}
			WHERE batch_id IN ({$in}) AND row_status='valid' AND COALESCE(normalized_phone,'')<>''
			GROUP BY batch_id, normalized_phone HAVING COUNT(*)>1
		) x GROUP BY batch_id", ARRAY_A) ?: []) as $row) {
			$batch_id = (int) ($row['batch_id'] ?? 0);
			if (isset($out[$batch_id])) { $out[$batch_id]['duplicate_valid_same_batch'] = (int) ($row['duplicate_valid_same_batch'] ?? 0); }
		}
		foreach ($out as $batch_id => $row) {
			$out[$batch_id]['returnable_direct'] = (int) ($row['eligible_to_pool'] ?? 0);
		}
		return $this->sn_mis_perf_cache_set($cache_key, $out, 20);
	}

	private function sn_mis_ux_health_label(array $stats): string
	{
		$total = (int) ($stats['total_rows'] ?? 0);
		$valid = (int) ($stats['valid_rows'] ?? 0);
		$invalid = (int) ($stats['invalid_rows'] ?? 0);
		$duplicate = (int) ($stats['duplicate_rows'] ?? 0);
		$assigned = (int) ($stats['assigned_to_manager'] ?? 0);
		$pool = (int) ($stats['pool_total'] ?? 0);
		$dist = (int) ($stats['distribution_total'] ?? 0);
		if ($total < 1) { return 'خالی / هنوز فایل ندارد'; }
		if ($valid < 1) { return 'غیرقابل تخصیص؛ شماره معتبر ندارد'; }
		if ($invalid > 0 || $duplicate > 0) { return 'فایل وارد شده ولی نیاز به بررسی دارد'; }
		if ((int) ($stats['duplicate_valid_same_batch'] ?? 0) > 0) { return 'فایل سالم است اما شماره تکراری داخلی دارد'; }
		if ($dist > 0) { return 'تحویل به زنجیره فروش شده'; }
		if ($pool > 0) { return 'آماده تحویل به زنجیره فروش'; }
		if ($assigned > 0) { return 'اختصاص به مدیر فروش انجام شده'; }
		return 'آماده اختصاص به مدیر فروش';
	}

	private function sn_mis_format_count($value): string
	{
		return number_format_i18n((int) $value);
	}

	private function sn_mis_launch_self_check(): array
	{
		$cached = $this->sn_mis_perf_cache_get('launch_self_check');
		if ($cached !== null) { return $cached; }
		global $wpdb;
		$checks = [];
		$profile_counts = ['sales_manager' => 0, 'seller' => 0, 'senior_supervisor' => 0, 'finance' => 0];
		if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles') && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_positions')) {
			foreach (($wpdb->get_results("SELECT p.slug, COUNT(*) c FROM {$wpdb->prefix}sn_hr_profiles hp INNER JOIN {$wpdb->prefix}sn_hr_positions p ON p.id=hp.position_id WHERE hp.is_active=1 AND p.slug IN ('sales_manager','seller','senior_supervisor','finance') GROUP BY p.slug", ARRAY_A) ?: []) as $row) {
				$profile_counts[(string) ($row['slug'] ?? '')] = (int) ($row['c'] ?? 0);
			}
		}
		$sales_managers = (int) $profile_counts['sales_manager'];
		$sellers = (int) $profile_counts['seller'];
		$senior_supervisors = (int) $profile_counts['senior_supervisor'];
		$finance_users = (int) $profile_counts['finance'];
		$mis_rows_ready = $this->sn_mis_table_exists('sn_mis_data_rows');
		$pool_ready = $this->sn_mis_table_exists('sn_mis_lead_pool');
		$distribution_ready = $this->sn_distribution_tables_ready();
		$ops = $this->sn_mis_operator_pipeline_counts();
		$valid_rows = (int) ($ops['valid_rows'] ?? 0);
		$manager_assigned = (int) ($ops['assigned_to_manager'] ?? 0);
		$pool_rows = (int) ($ops['pool_total'] ?? 0);
		$distribution_items = (int) ($ops['distribution_total'] ?? 0);
		$delivered_items = (int) ($ops['delivered_to_seller'] ?? 0);
		$converted_items = (int) ($ops['converted_rows'] ?? 0);
		$invoices = $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices") : 0;
		$checks[] = ['label' => 'ساختار HR فروش', 'ok' => $sales_managers > 0 && $sellers > 0, 'count' => "مدیر فروش {$sales_managers} / فروشنده {$sellers} / سرپرست ارشد {$senior_supervisors}", 'next' => $sales_managers > 0 && $sellers > 0 ? 'آماده ورود داده' : 'در HR ابتدا مدیر فروش و فروشنده‌ها را بسازید و وصل کنید.'];
		$checks[] = ['label' => 'جدول‌های MIS', 'ok' => $mis_rows_ready && $pool_ready && $distribution_ready, 'count' => ($mis_rows_ready && $pool_ready && $distribution_ready) ? 'آماده' : 'ناقص', 'next' => 'اگر ناقص است، بازسازی جدول‌های MIS را اجرا کنید.'];
		$checks[] = ['label' => 'ردیف معتبر واردشده', 'ok' => $valid_rows > 0, 'count' => $valid_rows, 'next' => $valid_rows > 0 ? 'اختصاص به مدیر فروش را بررسی کنید.' : 'یک فایل Excel/CSV وارد کنید.'];
		$checks[] = ['label' => 'ردیف اختصاص‌یافته به مدیر فروش', 'ok' => $manager_assigned > 0, 'count' => $manager_assigned, 'next' => $manager_assigned > 0 ? 'صف آماده توزیع را بسازید.' : 'از بخش اختصاص مدیر، ردیف‌های معتبر را به مدیر فروش وصل کنید.'];
		$checks[] = ['label' => 'صف آماده توزیع', 'ok' => $pool_rows > 0, 'count' => $pool_rows, 'next' => $pool_rows > 0 ? 'تحویل به زنجیره یا برنامه پخش را انجام دهید.' : 'از ردیف‌های اختصاص‌یافته Lead Pool بسازید.'];
		$checks[] = ['label' => 'آیتم‌های پخش', 'ok' => $distribution_items > 0, 'count' => $distribution_items, 'next' => $distribution_items > 0 ? 'مالک فعلی باید به زیرمجموعه منتقل کند.' : 'داده را به زنجیره پخش تحویل دهید.'];
		$checks[] = ['label' => 'تحویل به فروشنده', 'ok' => $delivered_items > 0, 'count' => $delivered_items, 'next' => $delivered_items > 0 ? 'فروشنده می‌تواند action کنترل‌شده ساخت سرنخ را اجرا کند.' : 'داده هنوز به فروشنده نهایی نرسیده است.'];
		$checks[] = ['label' => 'تبدیل کنترل‌شده به لید', 'ok' => $converted_items > 0, 'count' => $converted_items, 'next' => $converted_items > 0 ? 'فروشنده می‌تواند فروش و پیش‌فاکتور را ادامه دهد.' : 'هنوز لید زنده‌ای از مسیر کنترل‌شده ساخته نشده است.'];
		$checks[] = ['label' => 'آمادگی مالی', 'ok' => $finance_users > 0, 'count' => "کاربر مالی {$finance_users} / فاکتور {$invoices}", 'next' => $finance_users > 0 ? 'مالی می‌تواند صف پرداخت/پورسانت را بررسی کند.' : 'برای لانچ حداقل یک کاربر finance تعریف کنید.'];
		return $this->sn_mis_perf_cache_set('launch_self_check', $checks, 30);
	}

	private function sn_mis_lead_pool_summary(): array
	{
		$cached = $this->sn_mis_perf_cache_get('lead_pool_summary');
		if ($cached !== null) { return $cached; }
		global $wpdb;
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$empty = [
			'کل صف آماده' => '0',
			'آماده پخش' => '0',
			'مدیرهای دارای صف' => '0',
			'قبلاً وارد صف شده' => '0',
			'قابل ورود از داده‌های اختصاص‌یافته' => '0',
			'مسدود به دلیل تکراری بودن' => '0',
		];
		if (! $this->sn_mis_table_exists($pool) || ! $this->sn_mis_table_exists($rows)) {
			return $empty;
		}
		$pool_counts = $wpdb->get_row("SELECT COUNT(*) pool_total,
			SUM(CASE WHEN pool_status='ready' THEN 1 ELSE 0 END) pool_ready,
			COUNT(DISTINCT assigned_manager_user_id) managers,
			COUNT(DISTINCT source_row_id) source_rows
			FROM {$pool}", ARRAY_A);
		$assigned = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$rows} WHERE row_status='valid' AND assigned_manager_user_id IS NOT NULL AND assigned_manager_user_id > 0");
		$duplicates = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$rows} WHERE row_status='duplicate'");
		$out = [
			'کل صف آماده' => number_format_i18n((int) ($pool_counts['pool_total'] ?? 0)),
			'آماده پخش' => number_format_i18n((int) ($pool_counts['pool_ready'] ?? 0)),
			'مدیرهای دارای صف' => number_format_i18n((int) ($pool_counts['managers'] ?? 0)),
			'قبلاً وارد صف شده' => number_format_i18n((int) ($pool_counts['source_rows'] ?? 0)),
			'قابل ورود از داده‌های اختصاص‌یافته' => number_format_i18n(max(0, $assigned - (int) ($pool_counts['source_rows'] ?? 0))),
			'مسدود به دلیل تکراری بودن' => number_format_i18n($duplicates),
		];
		return $this->sn_mis_perf_cache_set('lead_pool_summary', $out, 20);
	}

	private function sn_mis_lead_pool_candidate_rows(int $batch_id, int $manager_id = 0, int $limit = 20): array
	{
		global $wpdb;
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		if (! $this->sn_mis_table_exists($pool) || ! $this->sn_mis_table_exists($rows) || ! $batch_id) {
			return [];
		}
		$where = "r.batch_id=%d AND r.row_status='valid' AND r.assigned_manager_user_id IS NOT NULL AND r.assigned_manager_user_id > 0 AND p.id IS NULL";
		$args = [$batch_id];
		if ($manager_id > 0) {
			$where .= ' AND r.assigned_manager_user_id=%d';
			$args[] = $manager_id;
		}
		$args[] = max(1, min(500, $limit));
		return $wpdb->get_results($wpdb->prepare("SELECT r.* FROM {$rows} r LEFT JOIN {$pool} p ON p.source_row_id=r.id WHERE {$where} ORDER BY r.id ASC LIMIT %d", ...$args)) ?: [];
	}

	private function sn_mis_pool_id_for_row(object $row, int $target_user_id = 0, bool $create = false, string $notes = ''): int
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_lead_pool')) { return 0; }
		$row_id = (int) ($row->id ?? 0);
		if ($row_id < 1) { return 0; }
		$existing = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}sn_mis_lead_pool WHERE source_row_id=%d ORDER BY id ASC LIMIT 1", $row_id));
		if ($existing || ! $create) { return $existing; }
		$manager_id = (int) ($row->assigned_manager_user_id ?? 0);
		$target_position = $target_user_id ? $this->sn_hr_position_for_user($target_user_id) : '';
		if ($manager_id < 1) {
			if ($target_position === 'sales_manager') {
				$manager_id = $target_user_id;
			} elseif ($target_user_id > 0) {
				$manager_id = $this->sn_hr_ancestor_user_by_position($target_user_id, 'sales_manager');
			}
		}
		if ($manager_id < 1 && $target_position === 'sales_deputy') {
			$managers = $this->sn_get_descendant_users($target_user_id, 'sales_manager');
			$manager_id = (int) ($managers[0]['user_id'] ?? 0);
		}
		$wpdb->insert($wpdb->prefix . 'sn_mis_lead_pool', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_lead_pool', [
			'source_row_id' => $row_id,
			'batch_id' => (int) ($row->batch_id ?? 0),
			'assigned_manager_user_id' => $manager_id,
			'assigned_seller_user_id' => $target_position === 'seller' ? $target_user_id : null,
			'pool_status' => 'ready',
			'normalized_phone' => (string) ($row->normalized_phone ?? ''),
			'customer_phone' => (string) ($row->customer_phone ?? ''),
			'customer_name' => (string) ($row->customer_name ?? ''),
			'city' => (string) ($row->city ?? ''),
			'province' => (string) ($row->province ?? ''),
			'source_meta' => (string) ($row->source_meta ?? ''),
			'created_by' => get_current_user_id() ?: null,
			'created_at' => current_time('mysql'),
			'updated_at' => current_time('mysql'),
			'notes' => $notes,
		]));
		return (int) $wpdb->insert_id;
	}

	private function sn_hr_ancestor_user_by_position(int $child_user_id, string $position_slug): int
	{
		if ($child_user_id < 1 || ! class_exists('SN_HR_Service') || ! class_exists('SN_Hierarchy_Service')) { return 0; }
		global $wpdb;
		$hr = new SN_HR_Service();
		$hierarchy = new SN_Hierarchy_Service();
		$profile = $hr->get_profile_by_user_id($child_user_id);
		if (! $profile) { return 0; }
		foreach ($hierarchy->get_ancestor_profile_ids((int) $profile->id, 20) as $ancestor_profile_id) {
			$user_id = (int) $wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$wpdb->prefix}sn_hr_profiles WHERE id=%d", (int) $ancestor_profile_id));
			if ($user_id > 0 && $this->sn_hr_position_for_user($user_id) === $position_slug) {
				return $user_id;
			}
		}
		return 0;
	}

	private function sn_mis_lead_pool_prepare_report(int $batch_id, int $manager_id = 0, int $preview_limit = 20): array
	{
		global $wpdb;
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$rows = $wpdb->prefix . 'sn_mis_data_rows';
		$report = [
			'batch_id' => $batch_id,
			'manager_user_id' => $manager_id,
			'eligible' => 0,
			'already_in_pool' => 0,
			'invalid' => 0,
			'duplicate' => 0,
			'no_manager' => 0,
			'candidates' => [],
		];
		if (! $batch_id || ! $this->sn_mis_table_exists($pool) || ! $this->sn_mis_table_exists($rows)) {
			$report['errors'] = ['mis_tables_missing'];
			return $report;
		}
		$manager_sql = '';
		$args = [$batch_id];
		if ($manager_id > 0) {
			$manager_sql = ' AND assigned_manager_user_id=%d';
			$args[] = $manager_id;
		}
		$report['invalid'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows} WHERE batch_id=%d AND row_status NOT IN ('valid','duplicate')" . $manager_sql, ...$args));
		$report['duplicate'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows} WHERE batch_id=%d AND row_status='duplicate'" . $manager_sql, ...$args));
		$report['no_manager'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$rows} WHERE batch_id=%d AND row_status='valid' AND (assigned_manager_user_id IS NULL OR assigned_manager_user_id=0)", $batch_id));
		$report['already_in_pool'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*)
			FROM {$rows} r
			INNER JOIN {$pool} p ON p.source_row_id=r.id
			WHERE r.batch_id=%d" . ($manager_id > 0 ? ' AND r.assigned_manager_user_id=%d' : ''), ...$args));
		$report['eligible'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*)
			FROM {$rows} r
			LEFT JOIN {$pool} p ON p.source_row_id=r.id
			WHERE r.batch_id=%d AND r.row_status='valid' AND r.assigned_manager_user_id IS NOT NULL AND r.assigned_manager_user_id > 0 AND p.id IS NULL" . ($manager_id > 0 ? ' AND r.assigned_manager_user_id=%d' : ''), ...$args));
		foreach ($this->sn_mis_lead_pool_candidate_rows($batch_id, $manager_id, $preview_limit) as $row) {
			$report['candidates'][] = [
				'source_row_id' => (int) $row->id,
				'name' => (string) ($row->customer_name ?? ''),
				'phone' => $this->sn_mask_phone((string) ($row->normalized_phone ?: $row->customer_phone)),
				'manager' => $this->sn_user_label((int) $row->assigned_manager_user_id),
			];
		}
		return $report;
	}

	private function sn_mis_lead_pool_rows(array $filters, int $limit): array
	{
		global $wpdb;
		$pool = $wpdb->prefix . 'sn_mis_lead_pool';
		$batches = $wpdb->prefix . 'sn_mis_import_batches';
		if (! $this->sn_mis_table_exists($pool)) {
			return [];
		}
		$where = '1=1';
		$args = [];
		if (! empty($filters['batch_id'])) {
			$where .= ' AND p.batch_id=%d';
			$args[] = (int) $filters['batch_id'];
		}
		if (! empty($filters['manager_id'])) {
			$where .= ' AND p.assigned_manager_user_id=%d';
			$args[] = (int) $filters['manager_id'];
		}
		if (! empty($filters['status'])) {
			$where .= ' AND p.pool_status=%s';
			$args[] = (string) $filters['status'];
		}
		$args[] = max(1, min(200, $limit));
		return $wpdb->get_results($wpdb->prepare("SELECT p.*, b.batch_code FROM {$pool} p LEFT JOIN {$batches} b ON b.id=p.batch_id WHERE {$where} ORDER BY p.id DESC LIMIT %d", ...$args)) ?: [];
	}

