	private function sn_mis_distribution_plan_items(int $plan_id, int $limit): array
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_distribution_plan_items') || ! $this->sn_mis_table_exists('sn_mis_lead_pool')) {
			return [];
		}
		return $wpdb->get_results($wpdb->prepare("SELECT i.*, p.customer_phone, p.normalized_phone FROM {$wpdb->prefix}sn_mis_distribution_plan_items i LEFT JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id=i.pool_id WHERE i.plan_id=%d ORDER BY i.id ASC LIMIT %d", $plan_id, $limit)) ?: [];
