	private function sn_mis_live_lead_creation_report(int $plan_id, int $preview_limit = 20): array
	{
		global $wpdb;
		$report = [
			'plan_id' => $plan_id,
			'plan_code' => '',
			'batch_id' => 0,
			'total_items' => 0,
			'eligible_to_create' => 0,
			'already_created' => 0,
			'duplicate_in_leads' => 0,
			'missing_seller' => 0,
			'blocked' => 0,
			'preview_rows' => [],
			'eligible_items_all' => [],
			'errors' => [],
		];
		if (! $plan_id || ! $this->sn_mis_table_exists('sn_mis_distribution_plans') || ! $this->sn_mis_table_exists('sn_mis_distribution_plan_items') || ! $this->sn_mis_table_exists('sn_mis_lead_pool')) {
			$report['errors'][] = 'mis_distribution_tables_missing';
			return $report;
		}
		$plan = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_distribution_plans WHERE id=%d", $plan_id));
		if (! $plan) {
			$report['errors'][] = 'plan_not_found';
			return $report;
		}
		$report['plan_code'] = (string) $plan->plan_code;
		$report['batch_id'] = (int) ($plan->batch_id ?? 0);
		if ((string) $plan->plan_status !== 'approved') {
			$report['errors'][] = 'plan_must_be_approved';
			return $report;
		}
		$items = $wpdb->get_results($wpdb->prepare("SELECT i.*, p.customer_name, p.customer_phone, p.normalized_phone, p.city, p.province, p.source_meta, p.batch_id
			FROM {$wpdb->prefix}sn_mis_distribution_plan_items i
			INNER JOIN {$wpdb->prefix}sn_mis_lead_pool p ON p.id=i.pool_id
			WHERE i.plan_id=%d AND i.item_status='planned'
			ORDER BY i.id ASC", $plan_id)) ?: [];
		$report['total_items'] = count($items);
		foreach ($items as $item) {
			$item_id = (int) $item->id;
			$seller_id = (int) ($item->planned_seller_user_id ?? 0);
			$phone = SN_Helpers::normalize_mobile((string) ($item->normalized_phone ?: $item->customer_phone));
			$row = [
				'item_id' => $item_id,
				'pool_id' => (int) $item->pool_id,
				'source_row_id' => (int) $item->source_row_id,
				'seller_id' => $seller_id,
				'seller' => $seller_id ? $this->sn_user_label($seller_id) : '',
				'phone' => $this->sn_mask_phone($phone),
				'status' => 'eligible',
				'reason' => '',
			];
			if ((int) ($item->created_lead_id ?? 0) > 0) {
				$report['already_created']++;
				$row['status'] = 'already_created';
				$row['reason'] = 'created_lead_id=' . (int) $item->created_lead_id;
			} elseif (! $seller_id) {
				$report['missing_seller']++;
				$row['status'] = 'blocked';
				$row['reason'] = 'missing_seller';
			} elseif ($phone === '' || $this->sn_mis_phone_exists_in_leads($phone)) {
				$report['duplicate_in_leads']++;
				$row['status'] = 'blocked';
				$row['reason'] = $phone === '' ? 'missing_phone' : 'duplicate_in_leads';
			} else {
				$report['eligible_to_create']++;
				$report['eligible_items_all'][] = [
					'item_id' => $item_id,
					'plan_id' => $plan_id,
					'pool_id' => (int) $item->pool_id,
					'source_row_id' => (int) $item->source_row_id,
					'batch_id' => (int) ($item->batch_id ?? $plan->batch_id ?? 0),
					'manager_user_id' => (int) $item->manager_user_id,
					'seller_id' => $seller_id,
					'phone' => $phone,
					'customer_name' => (string) ($item->customer_name ?? ''),
					'city' => (string) ($item->city ?? ''),
					'province' => (string) ($item->province ?? ''),
					'source_meta' => (string) ($item->source_meta ?? ''),
					'plan_code' => (string) $plan->plan_code,
				];
			}
			if (count($report['preview_rows']) < $preview_limit) {
				$report['preview_rows'][] = $row;
			}
		}
		$report['blocked'] = $report['duplicate_in_leads'] + $report['missing_seller'];
		return $report;
	}

	private function sn_mis_phone_exists_in_leads(string $phone): bool
	{
		global $wpdb;
		$phone = SN_Helpers::normalize_mobile($phone);
		if ($phone === '') {
			return false;
		}
		$digits = preg_replace('/\D+/', '', $phone);
		$variants = array_values(array_unique(array_filter([$phone, $digits, ltrim($digits, '0'), preg_replace('/^98/', '0', $digits)])));
		$placeholders = implode(',', array_fill(0, count($variants), '%s'));
		return (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE phone IN ({$placeholders})", ...$variants)) > 0;
	}

	private function sn_mis_insert_live_lead_from_item(object $item, string $reason = ''): int
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_leads';
		$item_id = (int) $item->item_id;
		$phone = SN_Helpers::normalize_mobile((string) $item->phone);
		if ($item_id < 1 || $phone === '' || $this->sn_mis_phone_exists_in_leads($phone)) {
			$wpdb->update($wpdb->prefix . 'sn_mis_distribution_plan_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_plan_items', [
				'lead_creation_status' => 'skipped',
				'lead_creation_error' => 'duplicate_or_invalid_phone',
				'updated_at' => current_time('mysql'),
			]), ['id' => $item_id]);
			return 0;
		}
		$cols = $this->sn_table_columns($table);
		$note_parts = [
			'MIS controlled lead creation',
			'plan=' . (string) ($item->plan_code ?? ''),
			'plan_id=' . (int) ($item->plan_id ?? 0),
			'pool_id=' . (int) ($item->pool_id ?? 0),
			'source_row_id=' . (int) ($item->source_row_id ?? 0),
		];
		if ($reason !== '') {
			$note_parts[] = 'reason=' . $reason;
		}
		$data = [
			'phone' => $phone,
			'customer_name' => sanitize_text_field((string) ($item->customer_name ?? '')),
			'import_code' => 'MIS-' . (int) ($item->batch_id ?? 0),
			'province' => sanitize_text_field((string) ($item->province ?? '')),
			'city' => sanitize_text_field((string) ($item->city ?? '')),
			'status' => 'assigned',
			'lead_status' => 'assigned',
			'note' => implode(' | ', $note_parts),
			'seller_id' => (int) ($item->seller_id ?? 0),
			'supervisor_id' => (int) get_user_meta((int) ($item->seller_id ?? 0), 'sn_supervisor_id', true) ?: null,
			'imported_at' => current_time('mysql'),
			'assigned_at' => current_time('mysql'),
			'updated_at' => current_time('mysql'),
		];
		$data = array_intersect_key($data, array_flip($cols));
		$inserted = $wpdb->insert($table, $this->sn_filter_existing_columns($table, $data));
		if (! $inserted) {
			$wpdb->update($wpdb->prefix . 'sn_mis_distribution_plan_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_plan_items', [
				'lead_creation_status' => 'error',
				'lead_creation_error' => sanitize_text_field($wpdb->last_error ?: 'insert_failed'),
				'updated_at' => current_time('mysql'),
			]), ['id' => $item_id]);
			return 0;
		}
		$lead_id = (int) $wpdb->insert_id;
		if ( class_exists( 'SN_Campaign_Tracking' ) ) { SN_Campaign_Tracking::capture_lead( $lead_id, $phone ); }
		$wpdb->update($wpdb->prefix . 'sn_mis_distribution_plan_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_mis_distribution_plan_items', [
			'created_lead_id' => $lead_id,
			'lead_created_at' => current_time('mysql'),
			'lead_creation_status' => 'created',
			'lead_creation_error' => null,
			'updated_at' => current_time('mysql'),
		]), ['id' => $item_id]);
		return $lead_id;
	}

	private function sn_mis_distribution_eligible_pool_rows(int $batch_id, int $manager_id, int $limit = 1000): array
	{
		global $wpdb;
		if (! $this->sn_mis_table_exists('sn_mis_lead_pool') || ! $manager_id) {
			return [];
		}
		$where = "pool_status='ready' AND assigned_manager_user_id=%d AND (assigned_seller_user_id IS NULL OR assigned_seller_user_id=0)";
		$args = [$manager_id];
		if ($batch_id > 0) {
			$where .= ' AND batch_id=%d';
			$args[] = $batch_id;
		}
		$args[] = max(1, min(1000, $limit));
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_lead_pool WHERE {$where} ORDER BY id ASC LIMIT %d", ...$args)) ?: [];
	}

	private function sn_mis_distribution_plan_report(int $batch_id, int $manager_id, int $rule_id, array $seller_ids, int $preview_limit = 20): array
	{
		global $wpdb;
		$report = [
			'batch_id' => $batch_id,
			'manager_user_id' => $manager_id,
			'rule_id' => $rule_id,
			'total_pool_rows' => 0,
			'eligible_rows' => 0,
			'planned_rows' => 0,
			'skipped_rows' => 0,
			'rows_per_seller' => [],
			'preview_items' => [],
			'preview_items_all' => [],
			'selected_seller_ids' => array_values(array_filter(array_map('intval', $seller_ids))),
			'blocked_seller_ids' => [],
			'active_plan_pool_rows' => 0,
			'warnings' => [],
			'errors' => [],
		];
		if (! $this->sn_mis_table_exists('sn_mis_lead_pool') || ! $this->sn_mis_table_exists('sn_mis_distribution_rules')) {
			$report['errors'][] = 'distribution_tables_missing';
			return $report;
		}
		if (! $manager_id || $this->sn_hr_position_for_user($manager_id) !== 'sales_manager') {
			$report['errors'][] = 'manager_must_have_sales_manager_position';
			return $report;
		}
		$rule = $rule_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_distribution_rules WHERE id=%d AND status='draft'", $rule_id)) : null;
		if (! $rule) {
			$report['errors'][] = 'draft_rule_required';
			return $report;
		}
		if (! empty($rule->manager_user_id) && (int) $rule->manager_user_id !== $manager_id) {
			$report['errors'][] = 'rule_manager_mismatch';
			return $report;
		}
		$allowed_sellers = $this->sn_mis_sellers_under_manager($manager_id);
		$requested_seller_ids = array_values(array_filter(array_map('intval', $seller_ids)));
		$seller_ids = array_values(array_intersect($seller_ids, $allowed_sellers));
		$blocked_seller_ids = array_values(array_diff($requested_seller_ids, $seller_ids));
		$report['selected_seller_ids'] = $seller_ids;
		$report['blocked_seller_ids'] = $blocked_seller_ids;
		$report['allowed_seller_count'] = count($allowed_sellers);
		if ($blocked_seller_ids) {
			$report['warnings'][] = 'some_selected_sellers_outside_manager_scope';
		}
		if (! $seller_ids) {
			$report['errors'][] = 'seller_selection_required';
			return $report;
		}
		$pool_table = $wpdb->prefix . 'sn_mis_lead_pool';
		$where = "pool_status='ready' AND assigned_manager_user_id=%d AND (assigned_seller_user_id IS NULL OR assigned_seller_user_id=0)";
		$args = [$manager_id];
		if ($batch_id > 0) {
			$where .= ' AND batch_id=%d';
			$args[] = $batch_id;
		}
		$report['total_pool_rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$pool_table} WHERE {$where}", ...$args));
		$rows = $this->sn_mis_distribution_eligible_pool_rows($batch_id, $manager_id, 1000);
		$report['eligible_rows'] = count($rows);
		if ($this->sn_mis_table_exists('sn_mis_distribution_plan_items')) {
			$active_statuses = ['draft', 'dry_run', 'approved'];
			$placeholders = implode(',', array_fill(0, count($active_statuses), '%s'));
			$active_args = array_merge($active_statuses, [$manager_id]);
			$active_batch_sql = '';
			if ($batch_id > 0) {
				$active_batch_sql = ' AND p.batch_id=%d';
				$active_args[] = $batch_id;
			}
			$report['active_plan_pool_rows'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT i.pool_id) FROM {$wpdb->prefix}sn_mis_distribution_plan_items i INNER JOIN {$wpdb->prefix}sn_mis_distribution_plans p ON p.id=i.plan_id WHERE p.plan_status IN ({$placeholders}) AND i.manager_user_id=%d{$active_batch_sql}", ...$active_args));
			if ($report['active_plan_pool_rows'] > 0) {
				$report['warnings'][] = 'pool_rows_already_exist_in_active_plan';
			}
		}
		$rule_type = (string) $rule->rule_type;
		$i = 0;
		foreach ($rows as $row) {
			$seller_id = $rule_type === 'manual_selection' ? (int) $seller_ids[0] : (int) $seller_ids[$i % count($seller_ids)];
			$item = [
				'pool_id' => (int) $row->id,
				'source_row_id' => (int) $row->source_row_id,
				'seller_id' => $seller_id,
				'seller' => $this->sn_user_label($seller_id),
				'phone' => $this->sn_mask_phone((string) ($row->normalized_phone ?: $row->customer_phone)),
				'status' => 'planned',
				'skip_reason' => '',
			];
			$report['preview_items_all'][] = $item;
			if (count($report['preview_items']) < $preview_limit) {
				$report['preview_items'][] = $item;
			}
			$report['rows_per_seller'][$seller_id] = (int) ($report['rows_per_seller'][$seller_id] ?? 0) + 1;
			$i++;
		}
		$report['planned_rows'] = count($report['preview_items_all']);
		$report['skipped_rows'] = max(0, $report['total_pool_rows'] - $report['planned_rows']);
		return $report;
	}

	private function sn_mis_sellers_under_manager(int $manager_id): array
	{
		if (! $manager_id || ! class_exists('SN_Scope_Service')) {
			return [];
		}
		$sellers = (new SN_Scope_Service())->scope_visible_seller_ids($manager_id);
		return array_values(array_filter(array_map('intval', (array) $sellers)));
	}

	private function sn_mis_generate_plan_code(): string
	{
		global $wpdb;
		do {
			$code = 'MDP-' . SN_Helpers::tehran_format('Ymd') . '-' . strtoupper(wp_generate_password(4, false, false));
		} while ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_distribution_plans WHERE plan_code=%s", $code)) > 0);
		return $code;
	}

	private function sn_mis_batches(int $limit): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_import_batches ORDER BY id DESC LIMIT %d", $limit)) ?: [];
	}

	private function sn_mis_batch_preview(int $batch_id, int $limit): array
	{
		global $wpdb;
		$table = $wpdb->prefix . 'sn_mis_data_rows';
		$order_by = in_array('row_number', $this->sn_table_columns($table), true) ? '`row_number` ASC, id ASC' : 'id ASC';
		$rows = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE batch_id=%d ORDER BY {$order_by} LIMIT %d", $batch_id, $limit)) ?: [];
		foreach ($rows as $row) {
			$row->sn_duplicate_trace = [];
			$row->sn_distribution_trace = $this->sn_mis_distribution_trace_for_data_row_id((int) ($row->id ?? 0));
			if ((string) ($row->row_status ?? '') === 'duplicate') {
				$trace = [];
				$meta = $this->sn_mis_decode_payload($row->source_meta ?? '');
				if (! empty($meta['duplicate_trace']) && is_array($meta['duplicate_trace'])) {
					$trace = $meta['duplicate_trace'];
				} else {
					$trace = $this->sn_mis_duplicate_trace_for_row($row);
				}
				$row->sn_duplicate_trace = $trace;
			}
		}
		return $rows;
	}

	private function sn_mis_case_report_rows(int $batch_id, int $limit = 3000): array
	{
		global $wpdb;
		if ($batch_id < 1 || ! $this->sn_mis_table_exists('sn_mis_data_rows')) { return []; }
		$limit = max(1, min(5000, $limit));
		$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
		$pool_table = $wpdb->prefix . 'sn_mis_lead_pool';
		$items_table = $wpdb->prefix . 'sn_distribution_items';
		$batches_table = $wpdb->prefix . 'sn_mis_import_batches';
		$has_pool = $this->sn_mis_table_exists('sn_mis_lead_pool');
		$has_items = $this->sn_mis_table_exists('sn_distribution_items');
		$has_batches = $this->sn_mis_table_exists('sn_mis_import_batches');
		$order_by = in_array('row_number', $this->sn_table_columns($rows_table), true) ? 'r.`row_number` ASC, r.id ASC' : 'r.id ASC';
		$select = "SELECT r.*";
		$join = '';
		if ($has_pool) {
			$select .= ', p.id pool_id, p.assigned_manager_user_id pool_manager_user_id, p.pool_status';
			$join .= " LEFT JOIN {$pool_table} p ON p.source_row_id=r.id";
		} else {
			$select .= ', NULL pool_id, NULL pool_manager_user_id, NULL pool_status';
		}
		if ($has_items) {
			$select .= ', di.id distribution_item_id, di.status distribution_status, di.current_owner_user_id, di.current_owner_position, di.final_seller_user_id, di.seller_contact_status, di.seller_customer_name, di.seller_updated_at';
			if ($has_pool) {
				$join .= " LEFT JOIN {$items_table} di ON (di.source_type='mis_data_row' AND di.source_id=r.id) OR (di.source_type='mis_pool' AND di.source_id=p.id) OR di.pool_item_id=p.id";
			} else {
				$join .= " LEFT JOIN {$items_table} di ON (di.source_type='mis_data_row' AND di.source_id=r.id)";
			}
		} else {
			$select .= ', NULL distribution_item_id, NULL distribution_status, NULL current_owner_user_id, NULL current_owner_position, NULL final_seller_user_id, NULL seller_contact_status, NULL seller_customer_name, NULL seller_updated_at';
		}
		if ($has_batches) {
			$select .= ', b.batch_code, b.title batch_title, b.campaign_code, b.data_category, b.source_type batch_source_type, b.source_label batch_source_label';
			$join .= " LEFT JOIN {$batches_table} b ON b.id=r.batch_id";
		} else {
			$select .= ', NULL batch_code, NULL batch_title, NULL campaign_code, NULL data_category, NULL batch_source_type, NULL batch_source_label';
		}
		$sql = $wpdb->prepare("{$select} FROM {$rows_table} r {$join} WHERE r.batch_id=%d ORDER BY {$order_by} LIMIT %d", $batch_id, $limit);
		$db_rows = $wpdb->get_results($sql) ?: [];
		$item_ids = [];
		foreach ($db_rows as $row) {
			if (! empty($row->distribution_item_id)) { $item_ids[] = (int) $row->distribution_item_id; }
		}
		$logs_by_item = $this->sn_mis_distribution_latest_logs_by_position(array_values(array_unique($item_ids)));
		$out = [];
		foreach ($db_rows as $row) {
			$item_id = (int) ($row->distribution_item_id ?? 0);
			$logs = $logs_by_item[$item_id] ?? [];
			$manager_id = (int) ($row->assigned_manager_user_id ?? 0);
			if (! $manager_id) { $manager_id = (int) ($row->pool_manager_user_id ?? 0); }
			if (! $manager_id && ! empty($logs['sales_manager']['to_user_id'])) { $manager_id = (int) $logs['sales_manager']['to_user_id']; }
			if (! $manager_id && (string) ($row->current_owner_position ?? '') === 'sales_manager') { $manager_id = (int) ($row->current_owner_user_id ?? 0); }
			$senior_id = ! empty($logs['senior_supervisor']['to_user_id']) ? (int) $logs['senior_supervisor']['to_user_id'] : 0;
			if (! $senior_id && (string) ($row->current_owner_position ?? '') === 'senior_supervisor') { $senior_id = (int) ($row->current_owner_user_id ?? 0); }
			$supervisor_id = ! empty($logs['supervisor']['to_user_id']) ? (int) $logs['supervisor']['to_user_id'] : 0;
			if (! $supervisor_id && (string) ($row->current_owner_position ?? '') === 'supervisor') { $supervisor_id = (int) ($row->current_owner_user_id ?? 0); }
			$seller_id = (int) ($row->final_seller_user_id ?? 0);
			if (! $seller_id && ! empty($logs['seller']['to_user_id'])) { $seller_id = (int) $logs['seller']['to_user_id']; }
			if (! $seller_id && (string) ($row->current_owner_position ?? '') === 'seller') { $seller_id = (int) ($row->current_owner_user_id ?? 0); }
			$phone = (string) (($row->normalized_phone ?? '') ?: ($row->customer_phone ?? ''));
			$contact_status = (string) ($row->seller_contact_status ?? '');
			$distribution_status = (string) ($row->distribution_status ?? '');
			$row_status = (string) ($row->row_status ?? '');
			$combined_status = $contact_status !== '' ? 'contact:' . sanitize_key($contact_status) : ($distribution_status !== '' ? 'distribution:' . sanitize_key($distribution_status) : 'row:' . sanitize_key($row_status));
			$current_owner_id = (int) ($row->current_owner_user_id ?? 0);
			$current_pos = (string) ($row->current_owner_position ?? '');
			$trace = $this->sn_mis_distribution_trace_for_data_row_id((int) ($row->id ?? 0));
			$out[] = [
				'id' => (int) ($row->id ?? 0),
				'row_number' => (int) ($row->row_number ?? $row->id ?? 0),
				'customer_name' => (string) (($row->seller_customer_name ?? '') ?: ($row->customer_name ?? '')),
				'phone' => $phone,
				'city' => (string) ($row->city ?? ''),
				'province' => (string) ($row->province ?? ''),
				'row_status' => $row_status,
				'duplicate_reason' => (string) ($row->duplicate_reason ?? ''),
				'batch_code' => (string) ($row->batch_code ?? ''),
				'batch_title' => (string) ($row->batch_title ?? ''),
				'campaign_code' => (string) ($row->campaign_code ?? ''),
				'data_category' => (string) ($row->data_category ?? ''),
				'source_type' => (string) ($row->batch_source_type ?? ''),
				'source_label' => (string) ($row->batch_source_label ?? ''),
				'distribution_item_id' => $item_id,
				'distribution_status' => $distribution_status,
				'seller_contact_status' => $contact_status,
				'seller_contact_status_label' => $contact_status !== '' ? $this->sn_portal_status_label($contact_status) : '—',
				'combined_status_key' => $combined_status,
				'combined_status_label' => $this->sn_mis_combined_status_label($combined_status, $row_status, $distribution_status, $contact_status),
				'manager_id' => $manager_id,
				'manager_label' => $manager_id ? $this->sn_user_label($manager_id) : '—',
				'senior_id' => $senior_id,
				'senior_label' => $senior_id ? $this->sn_user_label($senior_id) : '—',
				'supervisor_id' => $supervisor_id,
				'supervisor_label' => $supervisor_id ? $this->sn_user_label($supervisor_id) : '—',
				'seller_id' => $seller_id,
				'seller_label' => $seller_id ? $this->sn_user_label($seller_id) : '—',
				'current_owner_id' => $current_owner_id,
				'current_owner_label' => $current_owner_id ? ($this->sn_user_label($current_owner_id) . ($current_pos ? ' / ' . $this->sn_distribution_position_label($current_pos) : '')) : '—',
				'trace_label' => $trace ? $this->sn_mis_trace_label($trace) : '',
			];
		}
		return $out;
	}

	private function sn_mis_distribution_latest_logs_by_position(array $item_ids): array
	{
		global $wpdb;
		$item_ids = array_values(array_filter(array_map('intval', $item_ids)));
		if (! $item_ids || ! $this->sn_mis_table_exists('sn_distribution_item_logs')) { return []; }
		$positions = ['sales_manager', 'senior_supervisor', 'supervisor', 'seller'];
		$item_placeholders = implode(',', array_fill(0, count($item_ids), '%d'));
		$pos_placeholders = implode(',', array_fill(0, count($positions), '%s'));
		$sql = "SELECT * FROM {$wpdb->prefix}sn_distribution_item_logs WHERE item_id IN ({$item_placeholders}) AND to_position IN ({$pos_placeholders}) ORDER BY id ASC";
		$logs = $wpdb->get_results($wpdb->prepare($sql, ...array_merge($item_ids, $positions))) ?: [];
		$out = [];
		foreach ($logs as $log) {
			$item_id = (int) ($log->item_id ?? 0);
			$pos = (string) ($log->to_position ?? '');
			if (! $item_id || $pos === '') { continue; }
			$out[$item_id][$pos] = [
				'id' => (int) ($log->id ?? 0),
				'to_user_id' => (int) ($log->to_user_id ?? 0),
				'action' => (string) ($log->action ?? ''),
				'created_at' => (string) ($log->created_at ?? ''),
			];
		}
		return $out;
	}

	private function sn_mis_case_report_apply_filters(array $rows, array $filters): array
	{
		return array_values(array_filter($rows, static function ($row) use ($filters) {
			if (! empty($filters['manager_id']) && (int) ($row['manager_id'] ?? 0) !== (int) $filters['manager_id']) { return false; }
			if (! empty($filters['senior_id']) && (int) ($row['senior_id'] ?? 0) !== (int) $filters['senior_id']) { return false; }
			if (! empty($filters['supervisor_id']) && (int) ($row['supervisor_id'] ?? 0) !== (int) $filters['supervisor_id']) { return false; }
			if (! empty($filters['seller_id']) && (int) ($row['seller_id'] ?? 0) !== (int) $filters['seller_id']) { return false; }
			if (! empty($filters['status']) && (string) ($row['combined_status_key'] ?? '') !== (string) $filters['status']) { return false; }
			return true;
		}));
	}

	private function sn_mis_case_report_filter_options(array $rows): array
	{
		$options = ['managers' => [], 'seniors' => [], 'supervisors' => [], 'sellers' => [], 'statuses' => []];
		foreach ($rows as $row) {
			if (! empty($row['manager_id'])) { $options['managers'][(int) $row['manager_id']] = (string) ($row['manager_label'] ?? $row['manager_id']); }
			if (! empty($row['senior_id'])) { $options['seniors'][(int) $row['senior_id']] = (string) ($row['senior_label'] ?? $row['senior_id']); }
			if (! empty($row['supervisor_id'])) { $options['supervisors'][(int) $row['supervisor_id']] = (string) ($row['supervisor_label'] ?? $row['supervisor_id']); }
			if (! empty($row['seller_id'])) { $options['sellers'][(int) $row['seller_id']] = (string) ($row['seller_label'] ?? $row['seller_id']); }
			$key = (string) ($row['combined_status_key'] ?? '');
			if ($key !== '') { $options['statuses'][$key] = (string) ($row['combined_status_label'] ?? $key); }
		}
		foreach ($options as $key => $vals) {
			asort($vals, SORT_NATURAL | SORT_FLAG_CASE);
			$options[$key] = $vals;
		}
		return $options;
	}

	private function sn_mis_case_report_summary(array $rows): array
	{
		$summary = ['total' => count($rows), 'valid' => 0, 'duplicates' => 0, 'invalid' => 0, 'distributed' => 0, 'delivered_to_seller' => 0, 'by_manager' => [], 'by_senior' => [], 'by_supervisor' => [], 'by_seller' => [], 'by_status' => []];
		foreach ($rows as $row) {
			$status = (string) ($row['row_status'] ?? '');
			if ($status === 'valid') { $summary['valid']++; }
			elseif ($status === 'duplicate') { $summary['duplicates']++; }
			elseif ($status !== '') { $summary['invalid']++; }
			if (! empty($row['distribution_item_id'])) { $summary['distributed']++; }
			if ((string) ($row['distribution_status'] ?? '') === 'delivered_to_seller' || ! empty($row['seller_id'])) { $summary['delivered_to_seller']++; }
			$this->sn_mis_case_report_summary_inc($summary['by_manager'], (string) ($row['manager_label'] ?? '—'));
			$this->sn_mis_case_report_summary_inc($summary['by_senior'], (string) ($row['senior_label'] ?? '—'));
			$this->sn_mis_case_report_summary_inc($summary['by_supervisor'], (string) ($row['supervisor_label'] ?? '—'));
			$this->sn_mis_case_report_summary_inc($summary['by_seller'], (string) ($row['seller_label'] ?? '—'));
			$this->sn_mis_case_report_summary_inc($summary['by_status'], (string) ($row['combined_status_label'] ?? '—'));
		}
		return $summary;
	}

	private function sn_mis_case_report_summary_inc(array &$bucket, string $label): void
	{
		$label = trim($label) !== '' ? $label : '—';
		$bucket[$label] = (int) ($bucket[$label] ?? 0) + 1;
	}

	private function sn_mis_case_report_breakdown_table(string $title, array $rows): void
	{
		arsort($rows, SORT_NUMERIC);
		echo '<div class="sn-card sn-mis-breakdown-card"><h4>' . esc_html($title) . '</h4><table class="sn-table"><thead><tr><th>مقدار</th><th>تعداد</th></tr></thead><tbody>';
		if (! $rows) { echo '<tr><td colspan="2">—</td></tr>'; }
		foreach (array_slice($rows, 0, 12, true) as $label => $count) {
			echo '<tr><td>' . esc_html((string) $label) . '</td><td>' . esc_html(number_format_i18n((int) $count)) . '</td></tr>';
		}
		echo '</tbody></table></div>';
	}

	private function sn_mis_row_status_label(string $status): string
	{
		$labels = ['valid' => 'معتبر', 'duplicate' => 'تکراری', 'invalid' => 'نامعتبر', 'assigned' => 'اختصاص‌یافته'];
		return $labels[$status] ?? $this->sn_portal_status_label($status ?: '—');
	}

	private function sn_distribution_status_label(string $status): string
	{
		$labels = [
			'ready_for_distribution' => 'آماده پخش',
			'assigned_to_role' => 'اختصاص‌یافته به نقش',
			'delivered_to_seller' => 'تحویل فروشنده',
			'ready_for_lead_conversion' => 'آماده تبدیل',
			'lead_created' => 'لید ساخته‌شده',
			'live_lead_created' => 'لید زنده ساخته‌شده',
			'returned_to_owner' => 'برگشت به مالک قبلی',
			'returned_to_manager' => 'برگشت به مدیر فروش',
			'returned_to_mis' => 'برگشت به MIS',
			'pending_supervisor_action' => 'در انتظار اقدام سرپرست',
				'needs_repeat_action' => 'نیاز به اقدام مجدد',
				'converted_to_dot_case' => 'منتقل‌شده به آماده‌های تبدیل',
				'referral_cancelled' => 'انصرافی',
		];
		return $status !== '' ? ($labels[$status] ?? $this->sn_portal_status_label($status)) : '—';
