	private function sn_mis_combined_status_label(string $key, string $row_status, string $distribution_status, string $contact_status): string
	{
		if ($contact_status !== '') { return 'فروشنده: ' . $this->sn_portal_status_label($contact_status); }
		if ($distribution_status !== '') { return 'پخش: ' . $this->sn_distribution_status_label($distribution_status); }
		if ($row_status !== '') { return 'اعتبار: ' . $this->sn_mis_row_status_label($row_status); }
		return $key ?: '—';
	}

	private function sn_mis_logs(int $limit): array
	{
		global $wpdb;
		return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_mis_distribution_logs ORDER BY id DESC LIMIT %d", $limit)) ?: [];
	}

	private function sn_mis_decode_payload($value): array
	{
		if (is_array($value)) {
			return $value;
		}
		$decoded = json_decode((string) $value, true);
		return is_array($decoded) ? $decoded : [];
	}

	private function sn_mis_action_label(string $action): string
	{
		$labels = [
			'batch_created' => 'ساخت پرونده ورود',
			'csv_imported' => 'ورود فایل اطلاعات',
			'assigned_to_manager' => 'اختصاص به مدیر فروش',
			'assign_batch_to_sales_manager' => 'اختصاص به مدیر فروش',
			'lead_pool_prepared' => 'آماده‌سازی صف توزیع',
			'lead_pool_prepare_dry_run' => 'پیش‌نمایش صف توزیع',
			'lead_pool_prepare_apply' => 'ثبت صف توزیع',
			'distribution_rule_created' => 'ساخت قانون پخش',
			'distribution_plan_created' => 'ساخت برنامه پخش',
			'distribution_plan_approved' => 'تأیید برنامه پخش',
			'live_leads_created_from_mis_plan' => 'ساخت کنترل‌شده لید',
			'mis_assignments_returned' => 'برگشت تخصیص‌های MIS',
			'batch_archived' => 'آرشیو پرونده',
		];
		return $labels[$action] ?? $action;
