	private function sn_mis_report_summary(array $data): string
	{
		$action = (string) ($data['action'] ?? '');
		if ($action === '') {
			return 'گزارش MIS ثبت شده است.';
		}
		return $this->sn_mis_summary_from_action($action, $data);
	}

	private function sn_mis_latest_batch_import_report(int $batch_id): array
	{
		if ($batch_id <= 0 || ! $this->sn_mis_table_exists('sn_mis_distribution_logs')) {
			return [];
		}
		global $wpdb;
		$row = $wpdb->get_var($wpdb->prepare(
			"SELECT new_value FROM {$wpdb->prefix}sn_mis_distribution_logs WHERE batch_id=%d AND action='csv_imported' ORDER BY id DESC LIMIT 1",
			$batch_id
		));
		$decoded = $this->sn_mis_decode_payload($row);
		return is_array($decoded) ? $decoded : [];
	}

	private function sn_mis_log_summary($log): string
	{
		$action = (string) ($log->action ?? '');
		$new = $this->sn_mis_decode_payload($log->new_value ?? '');
		return $this->sn_mis_summary_from_action($action, $new);
	}

	private function sn_mis_summary_from_action(string $action, array $data): string
	{
		$batch_code = (string) ($data['batch_code'] ?? '');
		$title = (string) ($data['title'] ?? '');
		if ($action === 'batch_created') {
			return 'پرونده ورود اطلاعات ساخته شد' . ($batch_code ? ': کد ' . $batch_code : '') . ($title ? '، عنوان ' . $title : '') . '، وضعیت پیش‌نویس. هنوز ردیفی وارد نشده است.';
		}
		if ($action === 'csv_imported' || $action === 'csv_import') {
			$summary = sprintf('فایل وارد جدول موقت MIS شد: کل %d، معتبر %d، تکراری %d، نامعتبر %d.', (int) ($data['rows_seen'] ?? 0), (int) ($data['valid'] ?? 0), (int) ($data['duplicate'] ?? 0), (int) ($data['invalid'] ?? 0));
			$columns = array_filter((array) ($data['detected_phone_columns'] ?? []));
			if ($columns) {
				$summary .= ' ستون شماره تشخیص‌داده‌شده: ' . implode('، ', array_map('strval', $columns)) . '.';
			}
			if (! empty($data['invalid_reasons']) && is_array($data['invalid_reasons'])) {
				$parts = [];
				foreach ($data['invalid_reasons'] as $reason => $count) {
					$parts[] = $this->sn_mis_invalid_reason_label((string) $reason) . ': ' . (int) $count;
				}
				$summary .= ' علت‌های نامعتبر: ' . implode('، ', $parts) . '.';
			}
			return $summary;
		}
		if (in_array($action, ['mis_quick_assign_dry_run', 'mis_quick_assign_apply'], true)) {
			if (($data['zero_reason'] ?? '') === 'no_valid_rows') {
				return 'هیچ شماره معتبری برای تخصیص وجود ندارد. ابتدا گزارش ورود فایل را بررسی کنید.';
			}
			return sprintf('تخصیص سریع MIS: کل %d، معتبر %d، واجد شرایط %d، آیتم ساخته‌شده %d.', (int) ($data['total_rows'] ?? 0), (int) ($data['valid_rows'] ?? 0), (int) ($data['eligible'] ?? 0), (int) ($data['created_distribution_items'] ?? 0));
		}
		if (in_array($action, ['assigned_to_manager', 'assign_batch_to_sales_manager'], true)) {
			$assigned = (int) ($data['assigned_rows'] ?? 0);
			$unassigned_valid = (int) ($data['unassigned_valid'] ?? 0);
			$manager = (int) ($data['manager_user_id'] ?? ($data['assigned_manager_user_id'] ?? 0));
			if ($assigned > 0) {
				return sprintf('%d ردیف معتبر به مدیر فروش #%d اختصاص داده شد.', $assigned, $manager);
			}
			if ($unassigned_valid === 0) {
				return 'ردیف معتبر بدون مدیر برای اختصاص وجود نداشت. ابتدا ورود فایل و وضعیت ردیف‌های معتبر را بررسی کنید.';
			}
			return 'اختصاص به مدیر فروش انجام نشد یا ردیف واجد شرایط پیدا نشد.';
		}
		if (in_array($action, ['lead_pool_prepared', 'lead_pool_prepare_dry_run', 'lead_pool_prepare_apply'], true)) {
			$eligible = (int) ($data['eligible'] ?? ($data['eligible_rows'] ?? 0));
			$created = (int) ($data['created'] ?? ($data['created_rows'] ?? 0));
			if ($eligible > 0 && strpos($action, 'dry_run') !== false) {
				return sprintf('%d ردیف واجد شرایط برای صف آماده توزیع پیدا شد.', $eligible);
			}
			if ($created > 0) {
				return sprintf('%d ردیف وارد صف آماده توزیع شد.', $created);
			}
			if ($eligible === 0) {
				return 'ردیف واجد شرایط برای صف آماده توزیع وجود ندارد. باید ردیف معتبر به مدیر فروش اختصاص داده شده باشد.';
			}
			return 'هیچ ردیف جدیدی در صف آماده توزیع ساخته نشد.';
		}
		if ($action === 'distribution_plan_created') {
			$planned = (int) ($data['planned_rows'] ?? 0);
			$skipped = (int) ($data['skipped_rows'] ?? 0);
			return sprintf('برنامه پخش ساخته شد: %d ردیف برنامه‌ریزی‌شده، %d ردیف رد/عبور.', $planned, $skipped);
		}
		if ($action === 'distribution_plan_approved') {
			return 'برنامه پخش تأیید شد. این تأیید به‌تنهایی لید زنده نمی‌سازد.';
		}
		if ($action === 'live_leads_created_from_mis_plan') {
			return sprintf('ساخت کنترل‌شده Lead: ساخته‌شده %d، تکراری %d، خطا %d.', (int) ($data['created'] ?? 0), (int) ($data['duplicate_in_leads'] ?? ($data['duplicate'] ?? 0)), (int) ($data['errors'] ?? 0));
		}
		return $this->sn_mis_action_label($action) . ' ثبت شد.';
	}

	private function sn_mis_invalid_reason_label(string $reason): string
	{
		$labels = [
			'empty_phone' => 'شماره خالی',
			'too_short' => 'شماره کوتاه',
			'too_long' => 'شماره طولانی',
			'not_mobile_prefix' => 'پیش‌شماره موبایل نیست',
			'no_phone_column' => 'ستون شماره پیدا نشد',
			'non_numeric_after_normalization' => 'حروف/کاراکتر غیرعددی',
			'invalid_phone' => 'شماره نامعتبر',
			'duplicate_in_file' => 'تکراری داخل همین فایل',
			'duplicate_in_same_batch' => 'تکراری داخل همین پرونده',
			'same_batch_reimport' => 'تکراری داخل همین پرونده',
			'duplicate_in_mis' => 'تکراری در پرونده‌های MIS',
			'duplicate_in_leads' => 'تکراری در لیدهای فروش',
			'unknown' => 'نامشخص',
		];
		return $labels[$reason] ?? $reason;
	}

	private function sn_mis_safe_json($value): string
	{
		$decoded = $this->sn_mis_decode_payload($value);
		if (! $decoded) {
			return (string) $value;
		}
		array_walk_recursive($decoded, function (&$item, $key): void {
			$key_lc = strtolower((string) $key);
			if (strpos($key_lc, 'phone') !== false || strpos($key_lc, 'mobile') !== false) {
				$item = $this->sn_mask_phone((string) $item);
			}
			if (strpos($key_lc, 'token') !== false || strpos($key_lc, 'password') !== false || strpos($key_lc, 'hash') !== false || strpos($key_lc, 'url') !== false) {
				$item = '[hidden]';
			}
		});
		$json = (string) wp_json_encode($decoded, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
		return (string) preg_replace_callback('/(09\d{2})\d{4}(\d{3})/', function ($m) {
			return $m[1] . '****' . $m[2];
		}, $json);
	}

	private function sn_mis_sales_managers(): array
	{
		$cached = $this->sn_mis_perf_cache_get('sales_managers');
		if ($cached !== null) {
			return array_map(static function($row) {
				return (object) ['user_id' => (int) ($row['user_id'] ?? 0)];
			}, $cached);
		}
		global $wpdb;
		$rows = $wpdb->get_results("SELECT p.user_id FROM {$wpdb->prefix}sn_hr_profiles p INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id WHERE pos.slug='sales_manager' AND p.is_active=1 ORDER BY p.user_id ASC") ?: [];
		$this->sn_mis_perf_cache_set('sales_managers', array_map(static fn($row) => ['user_id' => (int) ($row->user_id ?? 0)], $rows), 60);
		return $rows;
	}

	private function sn_hr_position_for_user(int $user_id): string
	{
		$user_id = absint($user_id);
		if ($user_id < 1) { return ''; }
		if (isset($this->sn_hr_position_for_user_cache[$user_id])) {
			return (string) $this->sn_hr_position_for_user_cache[$user_id];
		}
		$this->sn_hr_position_for_user_cache[$user_id] = class_exists('SN_Scope_Service')
			? (string) (new SN_Scope_Service())->get_viewer_position_slug($user_id)
			: '';
		return (string) $this->sn_hr_position_for_user_cache[$user_id];
	}

	private function sn_mask_phone(string $phone): string
	{
		$phone = preg_replace('/\D+/', '', $phone);
		if (strlen($phone) < 7) { return $phone; }
		return substr($phone, 0, 4) . '***' . substr($phone, -3);
	}

	private function sn_mis_render_report_table(string $field): void
	{
		global $wpdb;
		$allowed = ['campaign_code', 'data_category', 'source_type', 'assigned_manager_user_id'];
		if (! in_array($field, $allowed, true)) { return; }
		$table = $wpdb->prefix . 'sn_mis_import_batches';
		$labels = [
			'campaign_code' => 'کد کمپین',
			'data_category' => 'دسته دیتا',
			'source_type' => 'نوع منبع',
			'assigned_manager_user_id' => 'مدیر فروش اختصاص‌یافته',
		];
		$label = $labels[$field] ?? $field;
		$rows = $wpdb->get_results("SELECT COALESCE(CAST({$field} AS CHAR),'—') label, COUNT(*) batches, COALESCE(SUM(total_rows),0) rows_total, COALESCE(SUM(valid_rows),0) valid_total FROM {$table} GROUP BY {$field} ORDER BY batches DESC LIMIT 20", ARRAY_A) ?: [];
		echo '<div><h4>' . esc_html($label) . '</h4><table class="sn-table"><thead><tr><th>مقدار</th><th>بچ‌ها</th><th>ردیف‌ها</th><th>معتبر</th></tr></thead><tbody>';
		foreach ($rows as $row) {
			$value = $field === 'assigned_manager_user_id' && (int) $row['label'] ? $this->sn_user_label((int) $row['label']) : (string) $row['label'];
			echo '<tr><td>' . esc_html($value ?: '—') . '</td><td>' . esc_html((string) (int) $row['batches']) . '</td><td>' . esc_html((string) (int) $row['rows_total']) . '</td><td>' . esc_html((string) (int) $row['valid_total']) . '</td></tr>';
		}
		echo '</tbody></table></div>';
	}

	private function sn_mis_conversion_summary(int $batch_id): array
	{
		global $wpdb;
		$rows_table = $wpdb->prefix . 'sn_mis_data_rows';
		$leads_table = $wpdb->prefix . 'sn_leads';
		$invoices_table = $wpdb->prefix . 'sn_invoices';
		$imported_rows = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(*) FROM {$rows_table} WHERE batch_id=%d",
			$batch_id
		));
		$matching_leads = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(DISTINCT r.id)
			 FROM {$rows_table} r
			 INNER JOIN {$leads_table} l ON l.phone=r.normalized_phone
			 WHERE r.batch_id=%d AND r.normalized_phone<>''",
			$batch_id
		));
		$matching_invoices = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(DISTINCT i.id)
			 FROM {$rows_table} r
			 INNER JOIN {$leads_table} l ON l.phone=r.normalized_phone
			 INNER JOIN {$invoices_table} i ON i.lead_id=l.id
			 WHERE r.batch_id=%d AND r.normalized_phone<>''",
			$batch_id
		));
		$matching_paid = (int) $wpdb->get_var($wpdb->prepare(
			"SELECT COUNT(DISTINCT i.id)
			 FROM {$rows_table} r
			 INNER JOIN {$leads_table} l ON l.phone=r.normalized_phone
			 INNER JOIN {$invoices_table} i ON i.lead_id=l.id
			 WHERE r.batch_id=%d AND r.normalized_phone<>'' AND i.status IN ('paid','approved','completed')",
			$batch_id
		));
		$conversion = $imported_rows > 0 ? round(($matching_invoices / $imported_rows) * 100, 2) : 0;
		return [
			'imported_rows' => $imported_rows,
			'matching_leads' => $matching_leads,
			'matching_invoices' => $matching_invoices,
			'matching_paid_invoices' => $matching_paid,
			'conversion_percentage' => $conversion,
		];
	}

	public function handle_save_scope_enforcement_mode(): void
	{
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		check_admin_referer('sn_save_scope_enforcement_mode');
		$mode = sanitize_key(wp_unslash($_POST['sn_scope_enforcement_mode'] ?? 'off'));
		$allowed = ['off', 'audit_only', 'enforce_seller', 'enforce_seller_supervisor', 'enforce_sales_management'];
		if (! in_array($mode, $allowed, true)) {
			$mode = 'off';
		}
		update_option('sn_scope_enforcement_mode', $mode, false);
		wp_safe_redirect(add_query_arg([
			'page' => 'sn-integration',
			'sn_msg' => 'scope_enforcement_saved',
		], admin_url('admin.php')));
		exit;
	}

	public function render_admin_integration(): void
	{
		if (! current_user_can('manage_options')) {
			wp_die('دسترسی غیرمجاز');
		}
		if (class_exists('SN_Migration_Service')) {
			(new SN_Migration_Service())->migrate();
		}
		global $wpdb;
		$positions = $this->sn_hr_normalize_lookup_rows($wpdb->get_results("SELECT * FROM {$wpdb->prefix}sn_hr_positions WHERE slug NOT IN ('project_manager','project_expert') ORDER BY sort_order ASC, id ASC") ?: [], 'position');
		$levels = $this->sn_hr_normalize_lookup_rows($wpdb->get_results("SELECT * FROM {$wpdb->prefix}sn_hr_levels ORDER BY sort_order ASC, id ASC") ?: [], 'level');
		$mappings = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}sn_hr_position_role_mappings WHERE legacy_role NOT IN ('sn_project_manager','sn_project_expert') ORDER BY legacy_role ASC");
		$tables = $this->sn_hr_tables_status();
		$hr = class_exists('SN_HR_Service') ? new SN_HR_Service() : null;
		$legacy_count = $hr ? $hr->count_legacy_users() : 0;
		$report = get_option('sn_db_migration_report', []);
		$sync_report = get_option('sn_hr_last_sync_report', []);
		$hierarchy_report = get_option('sn_hr_last_hierarchy_sync_report', []);
		$current_assignments = $this->sn_hr_count('sn_hr_assignments');
		$current_assignments = $current_assignments ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_assignments WHERE is_current=1") : 0;
		$top_level_profiles = $this->sn_hr_count('sn_hr_profiles') ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_profiles p LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to' WHERE a.id IS NULL") : 0;
		$bulk_hierarchy_report = get_option('sn_hr_bulk_hierarchy_repair_report', []);
		$legacy_lead_hierarchy_restore_report = get_option('sn_hr_legacy_lead_hierarchy_restore_report', []);
		$bulk_hierarchy_counts = class_exists('SN_Hierarchy_Service') ? (new SN_Hierarchy_Service())->hierarchy_repair_audit_counts() : ['top_level_supervisors' => 0, 'unassigned_sellers' => 0, 'sales_managers' => 0, 'current_assignments' => $current_assignments];
		$target_transition_report = get_option('sn_hr_target_transition_report', []);
		$manual_hr_correction_report = get_option('sn_hr_manual_position_correction_report', []);
		$target_org_counts = class_exists('SN_HR_Service') ? (new SN_HR_Service())->target_organization_counts() : ['positions' => []];
		$target_hierarchy_summary = class_exists('SN_Hierarchy_Service') ? (new SN_Hierarchy_Service())->target_hierarchy_summary() : [];
		$hierarchy_consistency_report = get_option('sn_hierarchy_consistency_report', []);
		$scope_service = class_exists('SN_Scope_Service') ? new SN_Scope_Service() : null;
		$scope_enforcement_mode = $scope_service ? $scope_service->get_enforcement_mode() : (string) get_option('sn_scope_enforcement_mode', 'off');
		$scope_enforcement_log = get_option('sn_scope_enforcement_audit_log', []);
		if (! is_array($scope_enforcement_log)) { $scope_enforcement_log = []; }
		$tree_rows = $wpdb->get_results("SELECT child.user_id child_user_id, COALESCE(NULLIF(child.hr_display_name,''), cu.display_name) child_name, cp.slug child_position, parent.user_id parent_user_id, COALESCE(NULLIF(parent.hr_display_name,''), pu.display_name) parent_name, pp.slug parent_position, a.source
			FROM {$wpdb->prefix}sn_hr_assignments a
			INNER JOIN {$wpdb->prefix}sn_hr_profiles child ON child.id=a.child_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions cp ON cp.id=child.position_id
			LEFT JOIN {$wpdb->users} cu ON cu.ID=child.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions pp ON pp.id=parent.position_id
			LEFT JOIN {$wpdb->users} pu ON pu.ID=parent.user_id
			WHERE a.is_current=1
			ORDER BY pp.sort_order ASC, parent.user_id ASC, cp.sort_order ASC, child.user_id ASC
			LIMIT 200");
		$profile_rows = $wpdb->get_results("SELECT p.*, COALESCE(NULLIF(p.hr_display_name,''), u.display_name) AS display_name, u.user_login, hp.label position_label, hp.slug position_slug, hl.label level_label, hl.slug level_slug, parent.user_id manager_user_id, COALESCE(NULLIF(parent.hr_display_name,''), pu.display_name) manager_name,
				(SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_assignments c WHERE c.parent_profile_id=p.id AND c.is_current=1 AND c.relationship_type='reports_to') direct_children
			FROM {$wpdb->prefix}sn_hr_profiles p
			LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
			LEFT JOIN {$wpdb->prefix}sn_hr_positions hp ON hp.id=p.position_id
			LEFT JOIN {$wpdb->prefix}sn_hr_levels hl ON hl.id=p.level_id
			LEFT JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=p.id AND a.is_current=1 AND a.relationship_type='reports_to'
			LEFT JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
			LEFT JOIN {$wpdb->users} pu ON pu.ID=parent.user_id
			ORDER BY hp.sort_order ASC, p.user_id ASC
			LIMIT 300");
		$latest_invoice_debug = [];
		$invoice_token_report = get_option('sn_invoice_token_backfill_report', []);
		$invoice_token_counts = [
			'total' => 0,
			'with_token' => 0,
			'missing_token' => 0,
			'has_column' => false,
		];
		$invoice_table = $wpdb->prefix . 'sn_invoices';
		if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $invoice_table)) === $invoice_table) {
			$invoice_cols = $this->sn_table_columns($invoice_table);
			$invoice_token_counts['has_column'] = in_array('access_token', $invoice_cols, true);
			$invoice_token_counts['total'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoice_table}");
			if ($invoice_token_counts['has_column']) {
				$invoice_token_counts['with_token'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoice_table} WHERE access_token IS NOT NULL AND access_token<>''");
				$invoice_token_counts['missing_token'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoice_table} WHERE access_token IS NULL OR access_token=''");
			} else {
				$invoice_token_counts['missing_token'] = $invoice_token_counts['total'];
			}
			$token_select = $invoice_token_counts['has_column'] ? 'access_token' : "'' AS access_token";
			$latest_invoice_debug = $wpdb->get_results("SELECT id, invoice_code, {$token_select}, status, created_at, seller_id FROM {$invoice_table} ORDER BY id DESC LIMIT 10");
		}
		$invoice_code_diagnostics = $this->sn_invoice_code_diagnostics();
		$scope_audit_lookup = sanitize_text_field(wp_unslash($_GET['sn_scope_audit_user'] ?? ''));
		$scope_audit_report = get_option('sn_scope_last_audit_report', []);
		$panel_resolver_lookup = sanitize_text_field(wp_unslash($_GET['sn_panel_resolver_user'] ?? ''));
		$panel_resolver_report = [];
		$panel_readiness_map = $this->sn_panel_readiness_map();
		if ($panel_resolver_lookup !== '' && class_exists('SN_HR_Service') && isset($_GET['_wpnonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'sn_panel_resolver')) {
			$panel_user = $this->sn_find_user_by_lookup($panel_resolver_lookup);
			if ($panel_user instanceof WP_User) {
				$resolved_panel = (new SN_HR_Service())->resolve_panel_for_user((int) $panel_user->ID);
				$panel_resolver_report = [
					'user' => [
						'id' => (int) $panel_user->ID,
						'display_name' => (string) $panel_user->display_name,
						'user_login' => (string) $panel_user->user_login,
					],
					'resolved' => $resolved_panel,
					'panel_url' => $this->sn_get_user_panel_url((int) $panel_user->ID),
				];
			} else {
				$panel_resolver_report = ['error' => 'user_not_found', 'lookup' => $panel_resolver_lookup];
			}
		}
		if ($scope_audit_lookup !== '' && class_exists('SN_Scope_Service') && isset($_GET['_wpnonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'sn_scope_audit')) {
			$audit_user = null;
			if (ctype_digit($scope_audit_lookup)) {
				$audit_user = get_user_by('id', (int) $scope_audit_lookup);
			}
			if (! $audit_user && is_email($scope_audit_lookup)) {
				$audit_user = get_user_by('email', $scope_audit_lookup);
			}
			if (! $audit_user) {
				$audit_user = get_user_by('login', $scope_audit_lookup);
			}
			if ($audit_user instanceof WP_User) {
				$scope = new SN_Scope_Service();
				$explain = $scope->explain_scope((int) $audit_user->ID);
				$seller_compare = $scope->compare_visible_sellers((int) $audit_user->ID);
				$count_compare = $scope->compare_lead_invoice_counts((int) $audit_user->ID);
				$only_legacy_sellers = $scope->describe_seller_visibility_gap((int) $audit_user->ID, (array) ($seller_compare['only_in_legacy_ids'] ?? []), 100);
				$only_scope_sellers = $scope->describe_seller_visibility_gap((int) $audit_user->ID, (array) ($seller_compare['only_in_scope_ids'] ?? []), 100);
				$count_compare['leads']['difference_count'] = abs((int) $count_compare['leads']['legacy_count'] - (int) $count_compare['leads']['scope_count']);
				$count_compare['invoices']['difference_count'] = abs((int) $count_compare['invoices']['legacy_count'] - (int) $count_compare['invoices']['scope_count']);
				$scope_audit_report = [
					'user' => [
						'id' => (int) $audit_user->ID,
