			private function sn_invoice_review_status_label($invoice): string
			{
				$get = static function (string $key) use ($invoice) {
					if (is_array($invoice)) {
						return $invoice[$key] ?? '';
					}
					if (is_object($invoice)) {
						return $invoice->{$key} ?? '';
					}
					return '';
				};
				$stored_status = (string) ($get('status') ?: '');
				$effective_status = (string) ($get('payment_status') ?: ($get('invoice_status') ?: $stored_status));
				$is_review = in_array($effective_status, ['pending_financial_approval', 'receipt_uploaded'], true)
					|| in_array($stored_status, ['pending_financial_approval', 'receipt_uploaded'], true);
				if (! $is_review) {
					return SN_Helpers::status_label($stored_status ?: $effective_status);
				}
				$receipt = trim((string) ($get('receipt_url') ?: $get('receipt_file')));
				$manual = trim(implode(' ', array_filter([
					(string) ($get('manual_card_from') ?: $get('deposit_card_from_last4')),
					(string) $get('manual_card_to_number'),
					(string) ($get('manual_card_to') ?: $get('deposit_card_to_last4')),
					(string) ($get('manual_amount') ?: $get('deposit_amount')),
					(string) ($get('manual_paid_at_jalali') ?: $get('deposit_jalali_datetime')),
				])));
				if ($receipt !== '') {
					return 'نیاز به بررسی فیش';
				}
				if ($manual !== '') {
					return 'نیاز به بررسی اطلاعات واریزی';
				}
				if ((string) $get('pay_method') === 'online') {
					return 'پرداخت درگاهی؛ در انتظار تأیید مالی';
				}
				return 'در انتظار تکمیل اطلاعات پرداخت';
			}

			public function ajax_seller_invoices(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$user = wp_get_current_user(); global $wpdb;
				$tab = sanitize_key($_POST['tab'] ?? 'all');
				$q = sanitize_text_field(wp_unslash($_POST['q'] ?? ''));
				$page = max(1, absint($_POST['page'] ?? 1)); $limit = min(50, max(10, absint($_POST['limit'] ?? 30))); $offset = ($page-1)*$limit;
				$summary_only = ! empty($_POST['summary_only']);
				$context = $q !== '' ? 'seller_invoice_search' : 'seller_invoices';
				$scope_decision = null;
				if (class_exists('SN_Scope_Service')) {
					$scope_service = new SN_Scope_Service();
					$scope_decision = $scope_service->seller_scope_decision($context, (int) $user->ID);
					$legacy_count = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoices WHERE seller_id=%d", (int) $user->ID));
					$scope_service->record_enforcement_decision($context, (int) $user->ID, $scope_decision, [
						'legacy_count' => $legacy_count,
						'scope_count' => $legacy_count,
					]);
				}
				$seller_id = (! empty($scope_decision['enforced'])) ? (int) $user->ID : (int) $user->ID;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$dot_links_table = $wpdb->prefix . 'sn_dot_invoice_links';
				// Conversion-payment invoices are visible to the user who actually issued
				// them. This preserves the original seller relation for reporting while
				// preventing another converter's payment links from leaking to the seller.
				$seller_visibility_condition = $this->sn_table_exists_quiet($dot_links_table)
					? "(NOT EXISTS (SELECT 1 FROM {$dot_links_table} sn_dot_link WHERE sn_dot_link.invoice_id={$invoice_table}.id AND sn_dot_link.flow_kind='conversion_payment') OR ({$invoice_table}.issued_by_user_id=" . (int) $seller_id . " AND EXISTS (SELECT 1 FROM {$dot_links_table} sn_dot_self_link WHERE sn_dot_self_link.invoice_id={$invoice_table}.id AND sn_dot_self_link.flow_kind='conversion_payment')))"
					: '1=1';
				$pre_invoice_condition = "(status IN ('pre_invoice','pending','pending_payment','partial_paid','receipt_uploaded','pending_financial_approval') OR invoice_status IN ('pre_invoice','pending','pending_payment','partial_paid','receipt_uploaded','pending_financial_approval') OR payment_status IN ('pre_invoice','pending','pending_payment','partial_paid','receipt_uploaded','pending_financial_approval'))";
				$paid_condition = "(status IN ('paid','approved') OR invoice_status IN ('paid','approved') OR payment_status IN ('paid','approved'))";
				$rejected_condition = "(status='rejected' OR payment_status='rejected' OR invoice_status='rejected' OR financial_return_state IN ('returned_to_seller','resent_after_return'))";
				$recontact_condition = "(status='recontact_requested' OR invoice_status='recontact_requested')";
				$cancelled_condition = "(status IN ('cancelled','payment_archived') OR invoice_status IN ('cancelled','payment_archived') OR payment_status IN ('cancelled','payment_archived'))";
				$staged_condition = "(payment_plan='partial' OR current_payment_stage>1)";
				$staged_completed_condition = "{$staged_condition} AND status IN ('paid','approved') AND payment_workflow_status='completed' AND COALESCE(remaining_amount,0)<=0.5";
				$staged_incomplete_condition = "{$staged_condition} AND NOT (status IN ('paid','approved') AND payment_workflow_status='completed' AND COALESCE(remaining_amount,0)<=0.5)";
				$where = ['seller_id=%d', $seller_visibility_condition]; $args = [$seller_id];
				if ($q !== '') {
					$like = '%' . $wpdb->esc_like($q) . '%';
					$where[] = '(invoice_code LIKE %s OR customer_name LIKE %s OR customer_phone LIKE %s)';
					array_push($args, $like, $like, $like);
				}
				if ($tab === 'pre_invoice') { $where[] = $pre_invoice_condition; }
				elseif ($tab === 'paid') { $where[] = $paid_condition; }
				elseif ($tab === 'rejected') { $where[] = $rejected_condition; }
				elseif ($tab === 'recontact') { $where[] = $recontact_condition; }
				elseif ($tab === 'cancelled') { $where[] = $cancelled_condition; }
				elseif ($tab === 'staged_completed') { $where[] = $staged_completed_condition; }
				elseif ($tab === 'staged_incomplete') { $where[] = $staged_incomplete_condition; }
				$base_args = [$seller_id];
				$summary = [
					'all' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition}", ...$base_args)),
					'pre_invoice' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$pre_invoice_condition}", ...$base_args)),
					'paid' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$paid_condition}", ...$base_args)),
					'rejected' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$rejected_condition}", ...$base_args)),
					'recontact' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$recontact_condition}", ...$base_args)),
					'cancelled' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$cancelled_condition}", ...$base_args)),
					'staged_completed' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$staged_completed_condition}", ...$base_args)),
					'staged_incomplete' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$staged_incomplete_condition}", ...$base_args)),
				];
				$paid_amount = (float) $wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(product_price),0) FROM {$invoice_table} WHERE seller_id=%d AND {$seller_visibility_condition} AND {$paid_condition}", ...$base_args));
				if ($summary_only) {
					SN_Helpers::send_json(true, '', ['invoices'=>[], 'items'=>[], 'page'=>$page, 'limit'=>$limit, 'total'=>0, 'summary'=>$summary, 'paid_amount'=>$paid_amount, 'summary_only' => true]);
					return;
				}
				$sql_where = implode(' AND ', array_map(function($w){ return '(' . $w . ')'; }, $where));
				$total = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE {$sql_where}", ...$args));
				$rows = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE {$sql_where} ORDER BY id DESC LIMIT %d OFFSET %d", ...array_merge($args, [$limit, $offset])), ARRAY_A);
				$conversion_invoice_ids = [];
				if ($rows && $this->sn_table_exists_quiet($dot_links_table)) {
					$row_ids = array_values(array_filter(array_map('intval', array_column($rows, 'id'))));
					if ($row_ids) {
						$conversion_invoice_ids = array_map('intval', (array) $wpdb->get_col($wpdb->prepare(
							"SELECT DISTINCT invoice_id FROM {$dot_links_table} WHERE flow_kind='conversion_payment' AND invoice_id IN (" . implode(',', array_fill(0, count($row_ids), '%d')) . ')',
							...$row_ids
						)));
					}
				}
				$dot_results = [];
				if ($rows && class_exists('SN_Dot_Flow')) {
					$dot_results = SN_Dot_Flow::instance()->completed_results_for_seller_invoices(array_column($rows, 'id'), $seller_id);
				}
				$project_results = ($rows && class_exists('SN_Projects')) ? SN_Projects::instance()->project_summaries_for_invoices(array_column($rows, 'id'), (int) $user->ID) : [];
				foreach ($rows as &$row) {
					$row['product_name'] = $this->sn_invoice_items_label((int)$row['id'], (int)$row['product_id']);
					$row['amount_fmt'] = SN_Helpers::format_price((float)$row['product_price']);
					$row['payment_summary'] = $this->sn_invoice_payment_totals((object) $row);
					$row['status_label'] = $this->sn_invoice_review_status_label($row);
					$row['review_status_label'] = $row['status_label'];
					$row['has_access_token'] = ! empty($row['access_token']);
					$issued_by = (int) ($row['issued_by_user_id'] ?? 0);
					$row['issued_by_user_id'] = $issued_by;
					$row['issued_by_label'] = $issued_by > 0 ? $this->sn_user_label($issued_by) : '';
					$row['issued_by_position'] = $issued_by > 0 ? $this->sn_hr_position_for_user($issued_by) : '';
					$row['issued_by_is_self'] = $issued_by < 1 || $issued_by === (int) $user->ID;
					$row['is_conversion_payment'] = in_array((int) $row['id'], $conversion_invoice_ids, true);
					$row['can_submit_manual_payment'] = $this->sn_supervisor_can_upload_receipt_for_status($row);
					$row['can_upload_receipt'] = false;
					$row['dot_conversion_result'] = $dot_results[(int) $row['id']] ?? null;
					$row['project'] = $project_results[(int) $row['id']] ?? null;
					unset($row['access_token']);
				}
				SN_Helpers::send_json(true, '', ['invoices'=>$rows, 'items'=>$rows, 'page'=>$page, 'limit'=>$limit, 'total'=>$total, 'summary'=>$summary, 'paid_amount'=>$paid_amount]);
			}


			public function ajax_get_unassigned(): void
			{
				if (! is_user_logged_in()) {
					SN_Helpers::send_json(false, 'وارد نشده‌اید');
					return;
				}
				$user = wp_get_current_user();
				$position = $this->sn_fast_hr_position_for_user((int) $user->ID);
				$can_upload_for_scope = current_user_can('manage_options')
					|| in_array('sn_supervisor', (array) $user->roles, true)
					|| in_array('sn_senior_supervisor', (array) $user->roles, true)
					|| in_array('sn_sales_manager', (array) $user->roles, true)
					|| in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true);
				if (! $can_upload_for_scope) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
				if (! $valid) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				global $wpdb;
				$supervisor_id = current_user_can('manage_options') ? absint($_POST['supervisor_id'] ?? 0) : (int) $user->ID;
				if (! $supervisor_id) {
					$supervisor_id = (int) $user->ID;
				}
				$leads = $wpdb->get_results($wpdb->prepare(
					"SELECT id, phone, imported_at FROM {$wpdb->prefix}sn_leads WHERE supervisor_id=%d AND seller_id IS NULL AND status='supervisor_pool' ORDER BY id ASC LIMIT 300",
					$supervisor_id
				), ARRAY_A);
				SN_Helpers::send_json(true, '', ['leads' => $leads ?: []]);
			}

			public function ajax_confirm_card_payment(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin','nonce',false)) { SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
				$id=absint($_POST['invoice_id'] ?? 0); if (!$id) { SN_Helpers::send_json(false,'ID نامعتبر'); return; }
				$result=$this->sn_finalize_current_payment_stage($id,'card','admin_confirmation','',get_current_user_id(),'approved');
				if (empty($result['success'])) { SN_Helpers::send_json(false,(string)($result['message'] ?? 'تایید پرداخت انجام نشد')); return; }
				SN_Helpers::send_json(true,!empty($result['completed'])?'✅ واریزی کامل و فاکتور نهایی شد':'✅ پیش‌پرداخت تایید و برای اقدام بعدی ارجاع شد',['completed'=>!empty($result['completed']),'remaining_amount'=>(float)($result['remaining'] ?? 0)]);
			}

			// تغییر وضعیت دستی پیش‌فاکتور از ادمین
			public function ajax_admin_change_invoice_status(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$id     = absint($_POST['invoice_id'] ?? 0);
				$status = sanitize_text_field(wp_unslash($_POST['status'] ?? ''));
				$allowed = ['pre_invoice', 'pending', 'paid', 'cancelled'];
				if (! $id || ! in_array($status, $allowed, true)) {
					SN_Helpers::send_json(false, 'داده نامعتبر');
					return;
				}
				global $wpdb;
				if ($status === 'paid') {
					$result = $this->sn_finalize_current_payment_stage($id, 'admin', 'admin_status_change', '', get_current_user_id(), 'approved');
					if (empty($result['success'])) { SN_Helpers::send_json(false, (string)($result['message'] ?? 'تایید پرداخت انجام نشد')); return; }
					SN_Helpers::send_json(true, !empty($result['completed']) ? 'فاکتور به‌طور کامل تایید شد' : 'این مرحله تایید شد و مانده برای اقدام بعدی ثبت گردید', ['completed'=>!empty($result['completed']),'remaining_amount'=>(float)($result['remaining'] ?? 0)]);
					return;
				}
				$data = ['status' => $status];
				if ($status === 'paid') {
					$data['paid_at'] = current_time('mysql');
				}
				if ($status === 'pre_invoice' || $status === 'pending') {
					// ریست کردن فیش
					$data['receipt_url'] = null; $data['receipt_file'] = null; $data['receipt_urls'] = null;
					$data['pay_method']  = null;
					$data['paid_at']     = null;
				}
				$inv_row = $wpdb->get_row($wpdb->prepare(
					"SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d",
					$id
				));
				$wpdb->update($wpdb->prefix . 'sn_invoices', $data, ['id' => $id]);

				// اگه lead رو برگردوندیم، وضعیتش رو هم reset کن
				if (in_array($status, ['pre_invoice', 'cancelled'], true) && $inv_row && $inv_row->lead_id) {
					$new_lead_status = $status === 'cancelled' ? 'assigned' : 'assigned';
					$wpdb->update($wpdb->prefix . 'sn_leads', ['status' => $new_lead_status], ['id' => $inv_row->lead_id]);
				}

				$labels = [
					'pre_invoice' => 'پیش‌فاکتور',
					'paid'        => 'فاکتور تایید‌شده',
					'cancelled'   => 'لغوشده',
				];
				SN_Helpers::send_json(true, 'وضعیت به «' . ($labels[$status] ?? $status) . '» تغییر کرد');
			}

			public function ajax_reject_receipt(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$id = absint($_POST['invoice_id'] ?? 0);
				if (! $id) {
					SN_Helpers::send_json(false, 'ID نامعتبر');
					return;
				}
				global $wpdb;
				$wpdb->update($wpdb->prefix . 'sn_invoices', [
					'status'      => 'pre_invoice',
					'receipt_url' => null, 'receipt_urls'=>null, 'receipt_file'=>null,
					'pay_method'  => null,
				], ['id' => $id]);
				SN_Helpers::send_json(true, '❌ فیش رد شد — پیش‌فاکتور به حالت اولیه برگشت');
			}

			// =========================================================
			// TEST SMS — برای debug از ادمین
			// =========================================================

			public function ajax_test_sms(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$phone = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($_POST['phone'] ?? '')));
				if (! SN_Helpers::is_valid_mobile($phone)) {
					SN_Helpers::send_json(false, 'شماره موبایل نامعتبر');
					return;
				}

				$sms = new SN_SMS();
				$provider = $sms->get_provider();
				$sender = $sms->get_sender();
				$pattern = $sms->event_pattern('invoice');
				$test_type = sanitize_key((string) wp_unslash($_POST['test_type'] ?? 'invoice'));
				if ($test_type === 'otp') {
					$result = $sms->send_customer_portal_otp($phone, '123456');
					SN_Helpers::send_json($result, $result ? 'پیامک تست کد ورود توسط درگاه فعال پذیرفته شد.' : $sms->get_last_error(), ['provider'=>$provider, 'test_type'=>'otp']);
					return;
				}

				$result = $sms->send_invoice_link(
					$phone,
					'TEST-0000',
					home_url('/test-invoice/'),
					'مشتری تست',
					'100000',
					get_option('sn_card_number', '')
				);

				if ($result) {
					SN_Helpers::send_json(true, 'پیامک تست توسط درگاه فعال پذیرفته شد.', [
						'provider' => $provider,
						'sender'   => $sender,
						'pattern'  => $pattern,
					]);
				} else {
					SN_Helpers::send_json(false, $sms->get_last_error() ?: 'ارسال پیامک تست ناموفق بود.', [
						'provider' => $provider,
						'sender'   => $sender,
						'pattern'  => $pattern,
					]);
				}
			}


			public function ajax_preview_invoice_sms(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}

				$invoice_code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				$phone_override = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($_POST['phone'] ?? '')));
				if ($invoice_code === '') {
					SN_Helpers::send_json(false, 'کد فاکتور را وارد کنید');
					return;
				}

				$invoice = SN_Helpers::get_invoice_by_code($invoice_code);
				if (! $invoice) {
					SN_Helpers::send_json(false, 'فاکتور پیدا نشد');
					return;
				}

				$phone = $phone_override ?: SN_Helpers::normalize_mobile((string) ($invoice->customer_phone ?? ''));
				if (! SN_Helpers::is_valid_mobile($phone)) {
					SN_Helpers::send_json(false, 'شماره موبایل فاکتور یا شماره تست معتبر نیست');
					return;
				}

				$provider = (new SN_SMS())->get_provider();

				$invoice_url = $this->sn_invoice_public_url($invoice);
				$sms = new SN_SMS();
				$preview = method_exists($sms, 'build_invoice_link_preview')
					? $sms->build_invoice_link_preview(
						$phone,
						(string) ($invoice->invoice_code ?? $invoice_code),
						$invoice_url,
						(string) ($invoice->customer_name ?? ''),
						(string) ($invoice->final_total ?? $invoice->product_price ?? ''),
						(string) ($this->sn_resolve_invoice_card($invoice)['number'] ?? '')
					)
					: [
						'provider' => $provider,
						'phone' => $phone,
						'invoice_code' => (string) ($invoice->invoice_code ?? $invoice_code),
						'invoice_url' => $invoice_url,
					];

				update_option('sn_last_invoice_sms_debug', [
					'preview_only' => true,
					'created_at' => current_time('mysql'),
					'payload' => $preview,
				], false);

				SN_Helpers::send_json(true, 'پیش‌نمایش پیامک فاکتور ساخته شد؛ پیامک واقعی ارسال نشد.', [
					'plugin_version' => defined('SN_VERSION') ? SN_VERSION : 'unknown',
					'preview' => $preview,
				]);
			}

			// =========================================================
			// LEAD STATUS AJAX
			// =========================================================

			public function ajax_save_customer_info(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$this->maybe_create_tables();
				$user    = wp_get_current_user();
				$lead_id_raw = wp_unslash($_POST['lead_id'] ?? '');
				$lead_id = absint($lead_id_raw);
				if (! $lead_id) {
					SN_Helpers::send_json(false, 'شناسه نامعتبر');
					return;
				}

				global $wpdb;

				// شناسه‌های مجازی V4 داخل همان UI قدیمی فروشنده نمایش داده می‌شوند، اما ذخیره آن‌ها روی sn_distribution_items انجام می‌شود.
				// برای پایداری بیشتر، JS شناسه واقعی distribution_item_id را هم می‌فرستد؛ اگر نبود از lead_id مجازی استخراج می‌کنیم.
				$v4_item_id = absint($_POST['distribution_item_id'] ?? 0);
				if ($v4_item_id < 1) {
					$v4_item_id = $this->sn_distribution_item_id_from_virtual_lead($lead_id);
				}
				if ($v4_item_id > 0) {
					// اطمینان از وجود ستون‌های seller_*؛ در بعضی محیط‌ها جدول توزیع قبل از اضافه شدن این ستون‌ها ساخته شده است.
					$this->sn_distribution_ensure_schema();
					$this->sn_distribution_ensure_seller_inline_columns();
					$item_table = $wpdb->prefix . 'sn_distribution_items';
					$item = $this->sn_distribution_tables_ready() ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$item_table} WHERE id=%d", $v4_item_id)) : null;
					if (! $item) {
						SN_Helpers::send_json(false, 'شماره تحویل‌شده یافت نشد');
						return;
					}
					$is_owner = (int) ($item->current_owner_user_id ?? 0) === (int) $user->ID;
					if (! $is_owner && ! current_user_can('manage_options')) {
						SN_Helpers::send_json(false, 'این شماره دیگر مالکیت فعلی شما نیست و از پنل شما قابل تعیین وضعیت نیست.', [
							'distribution_item_id' => $v4_item_id,
							'current_owner_user_id' => (int) ($item->current_owner_user_id ?? 0),
							'final_seller_user_id' => (int) ($item->final_seller_user_id ?? 0),
						]);
						return;
					}
					$probability_raw = sanitize_text_field(wp_unslash($_POST['sales_prediction'] ?? ''));
					$probability_digits = preg_replace('/\D+/', '', strtr($probability_raw, ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9','٪'=>'']));
					$probability_num = $probability_digits !== '' ? absint($probability_digits) : 0;
					if ($probability_num < 1) {
						$probability_map = ['ضعیف' => 25, 'متوسط' => 50, 'بالا' => 75, 'زیاد' => 75, '۱۰۰٪' => 100, '100%' => 100, '100' => 100];
						$probability_num = (int) ($probability_map[$probability_raw] ?? 0);
					}
					$changed_field = sanitize_text_field(wp_unslash($_POST['changed_field'] ?? ''));
					$incoming_contact_status = sanitize_text_field(wp_unslash($_POST['lead_status'] ?? ''));
					$customer_name = sanitize_text_field(wp_unslash($_POST['customer_name'] ?? ''));
					$province = sanitize_text_field(wp_unslash($_POST['province'] ?? ''));
					$city = sanitize_text_field(wp_unslash($_POST['city'] ?? ''));
					$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
					$not_purchase_reason = sanitize_textarea_field(wp_unslash($_POST['not_purchase_reason'] ?? ''));
					$callback_at = sanitize_text_field(wp_unslash($_POST['callback_at'] ?? ''));
					$flow = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance() : null;
					$incoming_flow_slug = $flow ? $flow->status_slug($incoming_contact_status) : '';
					if ($incoming_flow_slug !== '') {
						// Persist one canonical display label. Older/cached clients may submit
						// a slug or a Persian spelling variant; tabs always operate on the slug.
						$incoming_contact_status = $flow->status_label($incoming_flow_slug);
					}
					$current_contact_status = (string) ($item->seller_contact_status ?? '');
					$flow_status_equal = $flow && $flow->status_slug($incoming_contact_status) !== '' && $flow->status_slug($incoming_contact_status) === $flow->status_slug($current_contact_status);
					$flow_status_changed = $changed_field === 'lead_status' || ($incoming_contact_status !== '' && ! $flow_status_equal && $incoming_contact_status !== $current_contact_status);
					$flow_reason_changed = $changed_field === 'not_purchase_reason';
					if ($flow && $flow->is_archived('v4_distribution_item', $v4_item_id)) {
						SN_Helpers::send_json(false, 'این شماره بایگانی شده و از پنل فروشنده قابل ویرایش نیست.');
						return;
					}
					if ($flow && $flow_status_changed) {
						$flow_validation = $flow->validate_status_change($incoming_contact_status, $not_purchase_reason);
						if (is_wp_error($flow_validation)) {
							SN_Helpers::send_json(false, $flow_validation->get_error_message());
							return;
						}
					}
					$raw_data = [
						'seller_customer_name' => $customer_name,
						'seller_province' => $province,
						'seller_city' => $city,
						'seller_sale_probability' => min(100, $probability_num),
						'seller_sale_probability_label' => $probability_raw,
						'seller_notes' => $note,
						'seller_updated_by' => (int) $user->ID,
						'seller_updated_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
					];
					// ذخیره نام/یادداشت/شهر نباید وابسته به تعیین وضعیت باشد و نباید وضعیت را ناخواسته خالی کند.
					if ($changed_field === 'lead_status' || $incoming_contact_status !== '') {
						$raw_data['seller_contact_status'] = $incoming_contact_status;
					}
					$data = $this->sn_distribution_filter_existing_columns_fresh($item_table, $raw_data);
					if (empty($data)) {
						SN_Helpers::send_json(false, 'ستون‌های ذخیره‌سازی فروشنده در جدول توزیع آماده نیستند', [
							'action' => 'seller_inline_v4_save',
							'distribution_item_id' => $v4_item_id,
							'actor_user_id' => (int) $user->ID,
							'error' => 'no_writable_seller_columns',
						]);
						return;
					}
					if ($flow) { $wpdb->query('START TRANSACTION'); }
					$updated = $wpdb->update($item_table, $data, ['id' => $v4_item_id]);
					$report = [
						'action' => 'seller_inline_v4_save',
						'lead_id' => $lead_id,
						'distribution_item_id' => $v4_item_id,
						'actor_user_id' => (int) $user->ID,
						'changed_field' => $changed_field,
						'saved' => $updated !== false,
						'contact_status' => (string) ($data['seller_contact_status'] ?? ''),
						'db_error' => $updated === false ? (string) $wpdb->last_error : '',
						'updated_at' => current_time('mysql'),
					];
					update_option('sn_distribution_seller_inline_save_report', $report, false);
					if ($updated === false) {
						if ($flow) { $wpdb->query('ROLLBACK'); }
						error_log('SN seller inline save failed for distribution item ' . $v4_item_id . ': ' . sanitize_text_field((string) $wpdb->last_error));
						SN_Helpers::send_json(false, 'خطا در ذخیره اطلاعات فروشنده؛ لطفاً دوباره تلاش کنید.');
						return;
					}
					$flow_state = [];
					if ($flow) {
						$flow_result = $flow->apply_activity([
							'source_kind' => 'v4_distribution_item',
							'source_id' => $v4_item_id,
							'seller_user_id' => (int) ($item->current_owner_user_id ?? $user->ID),
							'actor_user_id' => (int) $user->ID,
							'status_label' => $incoming_contact_status,
							'not_purchase_reason' => $not_purchase_reason,
							'callback_at' => $callback_at,
							'status_changed' => $flow_status_changed,
							'reason_changed' => $flow_reason_changed,
							'changed_field' => $changed_field,
						]);
						if (is_wp_error($flow_result)) {
							$wpdb->query('ROLLBACK');
							SN_Helpers::send_json(false, $flow_result->get_error_message());
							return;
						}
						$flow_state = $flow_result;
						$wpdb->query('COMMIT');
					}
					SN_Helpers::send_json(true, 'اطلاعات ذخیره شد', array_merge([
						'distribution_item_id' => $v4_item_id,
						'lead_id' => $this->sn_distribution_virtual_lead_id($v4_item_id),
						'changed_field' => $changed_field,
						'customer_name' => $customer_name,
						'province' => $province,
						'city' => $city,
						'sales_prediction' => $probability_raw,
						'note' => $note,
						'lead_status' => array_key_exists('seller_contact_status', $data) ? (string) $data['seller_contact_status'] : $incoming_contact_status,
						'not_purchase_reason' => $not_purchase_reason,
						'callback_at' => $callback_at,
					], $flow_state));
					return;
				}

				$legacy_lead = $wpdb->get_row($wpdb->prepare(
					"SELECT seller_id,lead_status FROM {$wpdb->prefix}sn_leads WHERE id=%d",
					$lead_id
				));
				if (! $legacy_lead) {
					SN_Helpers::send_json(false, 'شماره یافت نشد');
					return;
				}
				$owner = (int) ($legacy_lead->seller_id ?? 0);
				if ($owner !== (int) $user->ID && ! current_user_can('manage_options')) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}

				$changed_field = sanitize_text_field(wp_unslash($_POST['changed_field'] ?? ''));
				$incoming_lead_status = sanitize_text_field(wp_unslash($_POST['lead_status'] ?? ''));
				$not_purchase_reason = sanitize_textarea_field(wp_unslash($_POST['not_purchase_reason'] ?? ''));
				$callback_at = sanitize_text_field(wp_unslash($_POST['callback_at'] ?? ''));
				$flow = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance() : null;
				$incoming_flow_slug = $flow ? $flow->status_slug($incoming_lead_status) : '';
				if ($incoming_flow_slug !== '') {
					$incoming_lead_status = $flow->status_label($incoming_flow_slug);
				}
				$current_lead_status = (string) ($legacy_lead->lead_status ?? '');
				$flow_status_equal = $flow && $flow->status_slug($incoming_lead_status) !== '' && $flow->status_slug($incoming_lead_status) === $flow->status_slug($current_lead_status);
				$flow_status_changed = $changed_field === 'lead_status' || ($incoming_lead_status !== '' && ! $flow_status_equal && $incoming_lead_status !== $current_lead_status);
				$flow_reason_changed = $changed_field === 'not_purchase_reason';
				if ($flow && $flow->is_archived('legacy_lead', $lead_id)) {
					SN_Helpers::send_json(false, 'این شماره بایگانی شده و از پنل فروشنده قابل ویرایش نیست.');
					return;
				}
				if ($flow && $flow_status_changed) {
					$flow_validation = $flow->validate_status_change($incoming_lead_status, $not_purchase_reason);
					if (is_wp_error($flow_validation)) {
						SN_Helpers::send_json(false, $flow_validation->get_error_message());
						return;
					}
				}
				$data = [
					'customer_name'    => sanitize_text_field(wp_unslash($_POST['customer_name']    ?? '')),
					'province'         => sanitize_text_field(wp_unslash($_POST['province']         ?? '')),
					'city'             => sanitize_text_field(wp_unslash($_POST['city']             ?? '')),
					'sales_prediction' => sanitize_text_field(wp_unslash($_POST['sales_prediction'] ?? '')),
					'note'             => sanitize_textarea_field(wp_unslash($_POST['note']        ?? '')),
				];
				if ($changed_field === 'lead_status' || $incoming_lead_status !== '') {
					$data['lead_status'] = $incoming_lead_status;
				}

				if ($flow) { $wpdb->query('START TRANSACTION'); }
				$updated = $wpdb->update($wpdb->prefix . 'sn_leads', $data, ['id' => $lead_id]);
				if ($updated === false) {
					if ($flow) { $wpdb->query('ROLLBACK'); }
					error_log('SN customer info save failed for lead ' . $lead_id . ': ' . sanitize_text_field((string) $wpdb->last_error));
					SN_Helpers::send_json(false, 'خطا در ذخیره اطلاعات مشتری؛ لطفاً دوباره تلاش کنید.');
					return;
				}
				$flow_state = [];
				if ($flow) {
					$flow_result = $flow->apply_activity([
						'source_kind' => 'legacy_lead',
						'source_id' => $lead_id,
						'seller_user_id' => $owner,
						'actor_user_id' => (int) $user->ID,
						'status_label' => $incoming_lead_status,
						'not_purchase_reason' => $not_purchase_reason,
						'callback_at' => $callback_at,
						'status_changed' => $flow_status_changed,
						'reason_changed' => $flow_reason_changed,
						'changed_field' => $changed_field,
					]);
					if (is_wp_error($flow_result)) {
						$wpdb->query('ROLLBACK');
						SN_Helpers::send_json(false, $flow_result->get_error_message());
						return;
					}
					$flow_state = $flow_result;
					$wpdb->query('COMMIT');
				}
				if (! empty($data['lead_status']) && class_exists('SN_Campaign_Tracking')) { SN_Campaign_Tracking::mark_lead_status($lead_id, (string) $data['lead_status']); }
				SN_Helpers::send_json(true, 'اطلاعات ذخیره شد', array_merge($data + ['lead_id' => $lead_id, 'not_purchase_reason' => $not_purchase_reason, 'callback_at' => $callback_at], $flow_state));
			}

			public function ajax_update_lead_status(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				// اطمینان از وجود ستون lead_status
				$this->maybe_create_tables();
				$user   = wp_get_current_user();
				$lead_id = absint($_POST['lead_id'] ?? 0);
				$has_status = array_key_exists('lead_status', $_POST);
				$status  = $has_status ? sanitize_text_field(wp_unslash($_POST['lead_status'] ?? '')) : null;
				$note    = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
				$not_purchase_reason = sanitize_textarea_field(wp_unslash($_POST['not_purchase_reason'] ?? ''));
				$callback_at = sanitize_text_field(wp_unslash($_POST['callback_at'] ?? ''));

				if (! $lead_id) {
					SN_Helpers::send_json(false, 'شناسه نامعتبر');
					return;
				}

				global $wpdb;
				// فروشنده فقط lead های خودش رو میتونه آپدیت کنه
				$source_lead = $wpdb->get_row($wpdb->prepare(
					"SELECT seller_id,lead_status FROM {$wpdb->prefix}sn_leads WHERE id=%d",
					$lead_id
				));
				if (! $source_lead) {
					SN_Helpers::send_json(false, 'شماره یافت نشد');
					return;
				}
				$owner = (int) $source_lead->seller_id;
				if ((int) $owner !== (int) $user->ID && ! current_user_can('manage_options')) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$flow = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::instance() : null;
				if ($flow && $has_status && (string) $status !== '') {
					$status_slug = $flow->status_slug((string) $status);
					if ($status_slug !== '') { $status = $flow->status_label($status_slug); }
				}
				if ($flow && $flow->is_archived('legacy_lead', $lead_id)) {
					SN_Helpers::send_json(false, 'این شماره بایگانی شده و قابل ویرایش نیست.');
					return;
				}
				if ($flow && $has_status) {
					$flow_validation = $flow->validate_status_change((string) $status, $not_purchase_reason);
					if (is_wp_error($flow_validation)) {
						SN_Helpers::send_json(false, $flow_validation->get_error_message());
						return;
					}
				}

				// وضعیت را فقط وقتی عمداً ارسال شده ذخیره کن؛ این جلوی پاک‌شدن اتفاقی وضعیت‌ها را می‌گیرد.
				$data = ['note' => $note];
				if ($has_status) {
					// مقدار خالی فقط وقتی allow_clear=1 باشد وضعیت را پاک می‌کند.
					$allow_clear = ! empty($_POST['allow_clear']);
					if ($status !== '' || $allow_clear) {
						$data['lead_status'] = $status;
						// چهار وضعیت مرحله اول مسیر اختصاصی خودشان را دارند؛ مخصوصاً
						// «جواب نداده» نباید با تنظیم قدیمی فوراً از پنل فروشنده خارج شود.
						$is_stage_one_status = $flow && $flow->status_slug((string) $status) !== '';
						$route = ! $is_stage_one_status && $status !== '' ? $wpdb->get_row($wpdb->prepare("SELECT destination_panel, move_to_destination FROM {$wpdb->prefix}sn_lead_statuses WHERE label=%s AND is_active=1 LIMIT 1", $status), ARRAY_A) : null;
						if ($route && ! empty($route['move_to_destination']) && ! empty($route['destination_panel'])) {
							$data['destination_panel'] = sanitize_key((string) $route['destination_panel']);
							$data['destination_routed_at'] = current_time('mysql');
						} elseif ($allow_clear && $status === '') {
							$data['destination_panel'] = null;
							$data['destination_routed_at'] = null;
						}
					}
				}

				if ($flow) { $wpdb->query('START TRANSACTION'); }
				$result = $wpdb->update($wpdb->prefix . 'sn_leads', $data, ['id' => $lead_id]);
				if ($result === false) {
					if ($flow) { $wpdb->query('ROLLBACK'); }
					error_log('SN update_lead_status DB error: ' . sanitize_text_field((string) $wpdb->last_error));
					SN_Helpers::send_json(false, 'ذخیره وضعیت انجام نشد؛ لطفاً دوباره تلاش کنید.');
					return;
				}
				$flow_state = [];
				if ($flow) {
					$flow_result = $flow->apply_activity([
						'source_kind' => 'legacy_lead',
						'source_id' => $lead_id,
						'seller_user_id' => (int) $owner,
						'actor_user_id' => (int) $user->ID,
						'status_label' => (string) $status,
						'not_purchase_reason' => $not_purchase_reason,
						'callback_at' => $callback_at,
						'status_changed' => $has_status,
						'changed_field' => 'lead_status',
					]);
					if (is_wp_error($flow_result)) {
						$wpdb->query('ROLLBACK');
						SN_Helpers::send_json(false, $flow_result->get_error_message());
						return;
					}
					$flow_state = $flow_result;
					$wpdb->query('COMMIT');
				}
				if ($has_status && $status !== '' && class_exists('SN_Campaign_Tracking')) { SN_Campaign_Tracking::mark_lead_status($lead_id, (string) $status); }
				SN_Helpers::send_json(true, 'وضعیت بروزرسانی شد', $flow_state);
			}

			public function ajax_get_lead_statuses(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				if (class_exists('SN_Seller_Flow')) {
					SN_Helpers::send_json(true, '', ['statuses' => SN_Seller_Flow::instance()->statuses_for_ajax()]);
					return;
				}
				// اطمینان از وجود جدول، بدون اتکا به version guard عمومی
				global $wpdb;
				$table = $this->sn_ensure_lead_statuses_schema_runtime();
				$this->sn_ensure_pre_invoice_lead_status();
				$statuses = $wpdb->get_results(
					"SELECT id, label, color, sort_order, destination_panel, move_to_destination FROM {$table} WHERE is_active=1 ORDER BY sort_order ASC",
					ARRAY_A
				);
				SN_Helpers::send_json(true, '', ['statuses' => $statuses ?: []]);
			}


			private function sn_can_manage_status_settings(): bool
			{
				return current_user_can('manage_options') || $this->sn_can_manage_hr_panel();
			}

			private function sn_ensure_lead_statuses_schema_runtime(): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_lead_statuses';
				require_once ABSPATH . 'wp-admin/includes/upgrade.php';
				$charset = $wpdb->get_charset_collate();
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					dbDelta("CREATE TABLE {$table} (
						id INT UNSIGNED NOT NULL AUTO_INCREMENT,
						label VARCHAR(100) NOT NULL,
						color VARCHAR(20) NOT NULL DEFAULT '#6b7280',
						sort_order INT NOT NULL DEFAULT 0,
						is_active TINYINT(1) NOT NULL DEFAULT 1,
						destination_panel VARCHAR(50) DEFAULT NULL,
						move_to_destination TINYINT(1) NOT NULL DEFAULT 0,
						PRIMARY KEY (id)
					) {$charset};");
				}
				$cols = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				$alter_map = [
					'color' => "ALTER TABLE {$table} ADD COLUMN color VARCHAR(20) NOT NULL DEFAULT '#6b7280' AFTER label",
					'sort_order' => "ALTER TABLE {$table} ADD COLUMN sort_order INT NOT NULL DEFAULT 0 AFTER color",
					'is_active' => "ALTER TABLE {$table} ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1 AFTER sort_order",
					'destination_panel' => "ALTER TABLE {$table} ADD COLUMN destination_panel VARCHAR(50) DEFAULT NULL AFTER is_active",
					'move_to_destination' => "ALTER TABLE {$table} ADD COLUMN move_to_destination TINYINT(1) NOT NULL DEFAULT 0 AFTER destination_panel",
				];
				foreach ($alter_map as $col => $sql) {
					if (! in_array($col, $cols, true)) {
						$wpdb->query($sql);
					}
				}
				if ((int) $wpdb->get_var("SELECT COUNT(*) FROM {$table}") === 0) {
					$defaults = [
						['label' => 'جواب نداده', 'color' => '#f59e0b', 'sort_order' => 1],
						['label' => 'تماس مجدد', 'color' => '#3b82f6', 'sort_order' => 2],
						['label' => 'عدم خرید',   'color' => '#ef4444', 'sort_order' => 3],
						['label' => 'پیش‌فاکتور', 'color' => '#0ea5e9', 'sort_order' => 4],
					];
					foreach ($defaults as $row) {
						$wpdb->insert($table, $row);
					}
				}
				return $table;
			}

			public function ajax_save_statuses(): void
			{
				if (! $this->sn_can_manage_status_settings()) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز — امکان ویرایش وضعیت‌ها را ندارید');
					return;
				}
				$valid_nonce = check_ajax_referer('sn_admin', 'nonce', false) || check_ajax_referer('sn_public', 'nonce', false);
				if (! $valid_nonce) {
					SN_Helpers::send_json(false, 'خطای امنیتی — صفحه را رفرش کنید');
					return;
				}
				global $wpdb;
				$table = $this->sn_ensure_lead_statuses_schema_runtime();

				$raw_statuses = $_POST['statuses'] ?? [];
				if (! is_array($raw_statuses)) {
					SN_Helpers::send_json(false, 'داده وضعیت‌ها نامعتبر است');
					return;
				}

				$allowed_destinations = ['', 'after_sales', 'financial', 'supervisor'];
				$clean_rows = [];
				foreach ($raw_statuses as $i => $s) {
					if (! is_array($s)) { continue; }
					$label = sanitize_text_field(wp_unslash($s['label'] ?? ''));
					$label = trim(preg_replace('/\s+/u', ' ', $label));
					if ($label === '') { continue; }
					$destination = sanitize_key(wp_unslash($s['destination_panel'] ?? ''));
					if (! in_array($destination, $allowed_destinations, true)) {
						$destination = '';
					}
					$move = ! empty($s['move_to_destination']) && $destination !== '' ? 1 : 0;
					$clean_rows[] = [
						'id' => absint($s['id'] ?? 0),
						'label' => $label,
						'color' => sanitize_hex_color(wp_unslash($s['color'] ?? '#6b7280')) ?: '#6b7280',
						'sort_order' => count($clean_rows),
						'is_active' => 1,
						'destination_panel' => $destination !== '' ? $destination : null,
						'move_to_destination' => $move,
					];
				}

				if (empty($clean_rows)) {
					SN_Helpers::send_json(false, 'حداقل یک وضعیت باید باقی بماند');
					return;
				}

				$active_ids = [];
				$inserted = 0;
				$updated = 0;
				$errors = [];
				$wpdb->query('START TRANSACTION');
				foreach ($clean_rows as $row) {
					$id = (int) $row['id'];
					$data = $row;
					unset($data['id']);
					if ($id > 0) {
						$exists = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE id=%d", $id));
						if ($exists > 0) {
							$result = $wpdb->update($table, $data, ['id' => $id]);
							if ($result === false) {
								$errors[] = 'update_id_' . $id . ': ' . (string) $wpdb->last_error;
								continue;
							}
							$active_ids[] = $id;
							$updated++;
							continue;
						}
					}
					$result = $wpdb->insert($table, $data);
					if ($result === false) {
						$errors[] = 'insert_' . ($row['label'] ?? '') . ': ' . (string) $wpdb->last_error;
						continue;
					}
					$new_id = (int) $wpdb->insert_id;
					if ($new_id > 0) {
						$active_ids[] = $new_id;
						$inserted++;
					}
				}

				if (! empty($errors)) {
					$wpdb->query('ROLLBACK');
					error_log('SN save_statuses failed: ' . wp_json_encode($errors, JSON_UNESCAPED_UNICODE));
					SN_Helpers::send_json(false, 'ذخیره وضعیت‌ها انجام نشد؛ جزئیات فنی در لاگ وردپرس ثبت شد.');
					return;
				}

				if (! empty($active_ids)) {
					$ids_sql = implode(',', array_map('intval', $active_ids));
					$deactivated = $wpdb->query("UPDATE {$table} SET is_active=0 WHERE id NOT IN ({$ids_sql})");
					if ($deactivated === false) {
						$wpdb->query('ROLLBACK');
						error_log('SN status deactivation failed: ' . sanitize_text_field((string) $wpdb->last_error));
						SN_Helpers::send_json(false, 'ذخیره وضعیت‌ها انجام نشد؛ جزئیات فنی در لاگ وردپرس ثبت شد.');
						return;
					}
				}
				$wpdb->query('COMMIT');
				wp_cache_delete('sn_lead_statuses', 'options');
				SN_Helpers::send_json(true, "✅ وضعیت‌ها ذخیره شد. بروزرسانی: {$updated}، جدید: {$inserted}", [
					'updated' => $updated,
					'inserted' => $inserted,
					'active_ids' => $active_ids,
				]);
			}

