			/**
			 * اجرا بعد از پرداخت موفق فاکتور (آنلاین یا کارت)
			 * $invoice می‌تواند object یا array باشد
			 */

			private function sn_hr_parent_user_by_position(int $child_user_id, string $target_position = '', int $max_depth = 5): int
			{
				global $wpdb;
				$child_user_id = absint($child_user_id);
				$target_position = sanitize_key($target_position);
				if ($child_user_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles') || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_assignments')) {
					return 0;
				}
				$current_user_id = $child_user_id;
				$visited = [];
				for ($depth = 0; $depth < $max_depth; $depth++) {
					if ($current_user_id < 1 || in_array($current_user_id, $visited, true)) { break; }
					$visited[] = $current_user_id;
					$row = $wpdb->get_row($wpdb->prepare(
						"SELECT parent.user_id parent_user_id, parent_pos.slug parent_position
						 FROM {$wpdb->prefix}sn_hr_profiles child
						 INNER JOIN {$wpdb->prefix}sn_hr_assignments a ON a.child_profile_id=child.id AND a.is_current=1 AND a.relationship_type='reports_to'
						 INNER JOIN {$wpdb->prefix}sn_hr_profiles parent ON parent.id=a.parent_profile_id
						 LEFT JOIN {$wpdb->prefix}sn_hr_positions parent_pos ON parent_pos.id=parent.position_id
						 WHERE child.user_id=%d
						 ORDER BY a.id DESC LIMIT 1",
						$current_user_id
					));
					if (! $row || (int) ($row->parent_user_id ?? 0) < 1) { return 0; }
					$parent_user_id = (int) $row->parent_user_id;
					$parent_position = sanitize_key((string) ($row->parent_position ?? ''));
					if ($target_position === '' || $parent_position === $target_position) { return $parent_user_id; }
					$current_user_id = $parent_user_id;
				}
				return 0;
			}

			private function sn_enabled_products_for_referral_select(): array
			{
				if (! function_exists('wc_get_products')) { return []; }
				$products = wc_get_products(['status' => 'publish', 'limit' => 300, 'orderby' => 'title', 'order' => 'ASC']);
				$out = [];
				foreach ($products as $product) {
					if (! $product || ! method_exists($product, 'get_id')) { continue; }
					$pid = (int) $product->get_id();
					if ((string) get_post_meta($pid, '_sn_enabled', true) !== '1') { continue; }
					$out[] = ['id' => $pid, 'name' => $product->get_name(), 'price' => (float) $product->get_price()];
				}
				if (class_exists('SN_Dot_Flow')) { $out = SN_Dot_Flow::instance()->filter_products_for_user($out, (int) get_current_user_id()); }
				if (class_exists('SN_Projects')) { $out = SN_Projects::instance()->filter_sellable_products($out, (int) get_current_user_id()); }
				return $out;
			}

			private function sn_user_can_issue_invoice_for_seller(int $actor_id, int $seller_id): bool
			{
				if ($actor_id < 1 || $seller_id < 1) { return false; }
				if (current_user_can('manage_options') || $actor_id === $seller_id) { return true; }
				$actor_position = $this->sn_hr_position_for_user($actor_id);
				if (! in_array($actor_position, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy'], true)) { return false; }
				$descendants = $this->sn_get_descendant_users($actor_id, 'seller');
				$ids = array_map('intval', array_column($descendants, 'user_id'));
				if (in_array($seller_id, $ids, true)) { return true; }
				// fallback legacy supervisor relationship
				return (int) get_user_meta($seller_id, 'sn_supervisor_id', true) === $actor_id;
			}

			private function sn_paid_referral_parent_target(int $seller_id, string $target_scope): int
			{
				$target_scope = sanitize_key($target_scope);
				if ($target_scope === 'supervisor') { return $this->sn_hr_parent_user_by_position($seller_id, 'supervisor'); }
				if ($target_scope === 'senior_supervisor') { return $this->sn_hr_parent_user_by_position($seller_id, 'senior_supervisor'); }
				return $seller_id;
			}


			private function sn_payment_assignment_candidates(int $actor_id): array
			{
				$rows = $this->sn_get_descendant_users($actor_id, '');
				$out = [];
				foreach ($rows as $row) {
					$user_id = (int) ($row['user_id'] ?? 0);
					$position = sanitize_key((string) ($row['position_slug'] ?? $row['position'] ?? $this->sn_hr_position_for_user($user_id)));
					if ($user_id < 1 || ! in_array($position, ['seller','supervisor','senior_supervisor'], true)) { continue; }
					$out[$user_id] = ['user_id'=>$user_id,'position'=>$position,'label'=>$this->sn_user_label($user_id)];
				}
				return array_values($out);
			}

			private function sn_paid_referral_action_items_for_actor(int $actor_id, int $limit = 100): array
			{
				global $wpdb;
				if ($actor_id < 1 || ! $this->sn_distribution_tables_ready()) { return []; }
				$this->sn_distribution_ensure_seller_inline_columns();
				$limit=max(1,min(200,$limit));
				$statuses=['needs_repeat_action','pending_supervisor_action','referral_self_invoice_pending','assigned_to_role','paid_referral_routed','referral_cancelled','needs_payment_assignment','payment_assigned','payment_stage_issued'];
				$placeholders=implode(',',array_fill(0,count($statuses),'%s'));
				return $wpdb->get_results($wpdb->prepare(
					"SELECT di.*, i.invoice_code ref_invoice_code, i.customer_name ref_customer_name, i.customer_phone ref_customer_phone, i.province ref_province, i.city ref_city, i.seller_id ref_seller_id,
					 i.payment_plan ref_payment_plan, i.payment_total_amount ref_payment_total_amount, i.final_total ref_final_total, i.product_price ref_product_price,
					 i.customer_address ref_customer_address, i.customer_postal_code ref_customer_postal_code,
					 i.paid_total_amount ref_paid_total_amount, i.remaining_amount ref_remaining_amount, i.current_due_amount ref_current_due_amount,
					 i.current_payment_stage ref_current_payment_stage, i.payment_workflow_status ref_payment_workflow_status, i.status ref_invoice_status
					 FROM {$wpdb->prefix}sn_distribution_items di
					 LEFT JOIN {$wpdb->prefix}sn_invoices i ON i.id=di.ref_invoice_id
					 WHERE di.source_type='paid_invoice_referral'
					 AND (di.current_owner_user_id=%d OR (di.workflow_kind='invoice_payment_completion' AND (di.referral_original_seller_id=%d OR di.workflow_assigned_by_user_id=%d)))
					 AND (di.status IS NULL OR di.status IN ({$placeholders}))
						 AND NOT (di.workflow_kind='invoice_payment_completion' AND di.status='referral_cancelled')
					 ORDER BY di.updated_at DESC,di.id DESC LIMIT %d",
					...array_merge([$actor_id,$actor_id,$actor_id],$statuses,[$limit])
				)) ?: [];
			}

			private function sn_render_paid_referral_action_section(int $actor_id, string $context = 'seller'): void
			{
				$items=$this->sn_paid_referral_action_items_for_actor($actor_id,100);
