				$presets=$this->sn_partial_payment_presets();
				$report=get_option('sn_paid_referral_action_report',[]);
				$action_notice=get_transient('sn_paid_referral_action_notice_'.$actor_id);
				if(is_array($action_notice)){delete_transient('sn_paid_referral_action_notice_'.$actor_id);}else{$action_notice=[];}
				$assignment_candidates=$context==='seller'?[]:$this->sn_payment_assignment_candidates($actor_id);
				?>
