			private function sn_finish_paid_referral_action(array $report): void
            {
                $ok = empty($report['errors']) && (!empty($report['routed']) || !empty($report['created']));
                $actor = get_current_user_id();
                $notice = get_transient('sn_paid_referral_action_notice_' . $actor);
                $message = (string) ($report['message'] ?? '');
                if ($message === '' && ($report['action'] ?? '') === 'paid_referral_create_follow_invoice' && is_array($notice)) { $message = (string) ($notice['message'] ?? ''); }
                if ($message === '') { $message = $ok ? 'مسئول ادامه پرداخت با موفقیت ثبت شد.' : 'عملیات انجام نشد؛ وضعیت یا مسئول پرونده تغییر کرده است. صفحه را تازه کنید و دوباره بررسی کنید.'; }
                $position = $this->sn_hr_position_for_user($actor);
                $context = in_array($position, ['supervisor','senior_supervisor'], true) ? $position : 'seller';
                if (wp_doing_ajax()) {
                    $html = '';
                    if ($ok) { ob_start(); $this->sn_render_paid_referral_action_section($actor, $context); $html = ob_get_clean(); }
                    wp_send_json(['success'=>$ok, 'message'=>$message, 'html'=>$html]);
                }
                $page = (int) get_option('sn_' . ($context === 'senior_supervisor' ? 'senior_supervisor' : $context) . '_panel_page_id', 0);
                $back = wp_get_referer();
                if (!$back || preg_match('~/(?:admin-ajax|admin-post)\.php(?:[?#]|$)~', $back)) { $back = $page ? get_permalink($page) : home_url('/'); }
                set_transient('sn_paid_referral_action_notice_' . $actor, ['success'=>$ok,'message'=>$message], 5 * MINUTE_IN_SECONDS);
                wp_safe_redirect($back);
            }

            public function handle_paid_referral_route(): void
			{
				if(!is_user_logged_in()){wp_die('دسترسی غیرمجاز');} check_admin_referer('sn_paid_referral_route');
				$this->sn_distribution_ensure_schema(); $this->sn_distribution_ensure_seller_inline_columns(); global $wpdb;
				$actor_id=get_current_user_id(); $item_id=absint($_POST['referral_item_id']??0); $target_scope=sanitize_key(wp_unslash($_POST['target_scope']??'self'));
				$table=$wpdb->prefix.'sn_distribution_items'; $item=$item_id?$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d",$item_id)):null;
				$report=['action'=>'paid_referral_route','item_id'=>$item_id,'actor_user_id'=>$actor_id,'target_scope'=>$target_scope,'routed'=>false,'errors'=>[],'updated_at'=>current_time('mysql')];
				if(!$item||(string)($item->source_type??'')!=='paid_invoice_referral'){ $report['errors'][]='item_not_found'; update_option('sn_paid_referral_action_report',$report,false); $this->sn_finish_paid_referral_action($report); exit; }
				if((int)($item->current_owner_user_id??0)!==$actor_id&&!current_user_can('manage_options')){ $report['errors'][]='not_owner'; update_option('sn_paid_referral_action_report',$report,false); $this->sn_finish_paid_referral_action($report); exit; }
				$seller_id=(int)(($item->referral_original_seller_id??0)?:($item->final_seller_user_id??0));
				if($seller_id<1&&!empty($item->ref_invoice_id)){$seller_id=(int)$wpdb->get_var($wpdb->prepare("SELECT seller_id FROM {$wpdb->prefix}sn_invoices WHERE id=%d",(int)$item->ref_invoice_id));}
				$is_payment=(string)($item->workflow_kind??'')==='invoice_payment_completion';
				if($is_payment){
					if((string)($item->status??'')!=='needs_payment_assignment'){$report['errors'][]='payment_not_waiting_assignment';update_option('sn_paid_referral_action_report',$report,false);$this->sn_finish_paid_referral_action($report);exit;}
					if(!in_array($target_scope,['self','supervisor','user'],true)){$target_scope='self';}
					$target_user_id=0;
					if($target_scope==='self'){$target_user_id=$actor_id;}
					elseif($target_scope==='supervisor'){$target_user_id=$this->sn_hr_parent_user_by_position($seller_id,'supervisor');}
					else{
						$requested=absint($_POST['target_user_id']??0); $allowed=array_map('intval',array_column($this->sn_payment_assignment_candidates($actor_id),'user_id'));
						if(current_user_can('manage_options')||in_array($requested,$allowed,true)){$target_user_id=$requested;}
					}
					if($target_user_id<1){$report['errors'][]='invalid_target';update_option('sn_paid_referral_action_report',$report,false);$this->sn_finish_paid_referral_action($report);exit;}
					$target_position=$this->sn_hr_position_for_user($target_user_id)?:($target_user_id===$seller_id?'seller':'sales');
					// تحویل فروشنده به سرپرست هنوز «تخصیص نهایی مسئول مرحله» نیست؛ سرپرست باید خودش یا شخص دیگری را انتخاب کند.
					$next_status=$target_scope==='supervisor'?'needs_payment_assignment':'payment_assigned';
					$route_where=['id'=>$item_id,'status'=>'needs_payment_assignment'];if(!current_user_can('manage_options')){$route_where['current_owner_user_id']=$actor_id;}
					$route_updated=$wpdb->update($table,$this->sn_distribution_filter_existing_columns_fresh($table,['current_owner_user_id'=>$target_user_id,'current_owner_position'=>$target_position,'final_seller_user_id'=>$seller_id,'status'=>$next_status,'referral_target_scope'=>$target_scope,'referral_issued_by_user_id'=>$actor_id,'workflow_assigned_by_user_id'=>$actor_id,'updated_at'=>current_time('mysql')]),$route_where);
					$ok=is_int($route_updated)&&$route_updated>0;
					$report['target_user_id']=$target_user_id;$report['seller_id']=$seller_id;$report['next_status']=$next_status;$report['routed']=$ok;
					if($ok){$route_action=$next_status==='needs_payment_assignment'?'invoice_payment_sent_to_supervisor':'invoice_payment_assigned';$route_note=$next_status==='needs_payment_assignment'?'ارجاع به سرپرست برای تعیین مسئول تکمیل واریزی':'ارجاع مسئول تکمیل واریزی';$this->sn_distribution_log($item_id,$route_action,$actor_id,(int)$item->current_owner_user_id,$target_user_id,(string)$item->current_owner_position,$target_position,999,$route_note,['invoice_id'=>(int)($item->ref_invoice_id??0),'original_seller_id'=>$seller_id]);$this->sn_log_activity((int)($item->ref_invoice_id??0),null,$route_action,$route_note,['actor_user_id'=>$actor_id,'target_user_id'=>$target_user_id,'original_seller_id'=>$seller_id,'distribution_item_id'=>$item_id]);}
					update_option('sn_paid_referral_action_report',$report,false);$this->sn_finish_paid_referral_action($report);exit;
				}
				if(!in_array($target_scope,['self','supervisor','senior_supervisor'],true)){$target_scope='self';}
				$target_user_id=$target_scope==='self'?$seller_id:$this->sn_paid_referral_parent_target($seller_id,$target_scope); if($target_user_id<1){$target_user_id=$seller_id;}
				$target_position=$this->sn_hr_position_for_user($target_user_id)?:($target_user_id===$seller_id?'seller':'sales'); $is_supervisor_target=in_array($target_scope,['supervisor','senior_supervisor'],true);
				$ok=$wpdb->update($table,$this->sn_filter_existing_columns($table,['current_owner_user_id'=>$target_user_id,'current_owner_position'=>$target_position,'final_seller_user_id'=>$is_supervisor_target?null:$seller_id,'status'=>$is_supervisor_target?'pending_supervisor_action':'needs_repeat_action','referral_target_scope'=>$target_scope,'updated_at'=>current_time('mysql')]),['id'=>$item_id])!==false;
				$report['target_user_id']=$target_user_id;$report['seller_id']=$seller_id;$report['routed']=$ok;if($ok){$this->sn_distribution_log($item_id,'paid_referral_routed',$actor_id,(int)$item->current_owner_user_id,$target_user_id,(string)$item->current_owner_position,$target_position,999,'ارجاع به صف تبدیل',['target_scope'=>$target_scope,'seller_id'=>$seller_id]);if(in_array($target_position,['supervisor','senior_supervisor'],true)&&class_exists('SN_Dot_Flow')&&method_exists('SN_Dot_Flow','ensure_paid_referral_conversion_case')){$report['dot_case_id']=SN_Dot_Flow::instance()->ensure_paid_referral_conversion_case($item_id,$target_user_id);}}
				update_option('sn_paid_referral_action_report',$report,false);$this->sn_finish_paid_referral_action($report);exit;
			}

			public function handle_paid_referral_create_follow_invoice(): void
			{
				if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
				check_admin_referer('sn_paid_referral_create_follow_invoice');
				$this->maybe_create_tables();
				$this->sn_distribution_ensure_schema();
				$this->sn_distribution_ensure_seller_inline_columns();
				global $wpdb;

				$actor_id = get_current_user_id();
				$item_id = absint($_POST['referral_item_id'] ?? 0);
				$table = $wpdb->prefix . 'sn_distribution_items';
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$item = $item_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $item_id)) : null;
				$report = ['action'=>'paid_referral_create_follow_invoice','item_id'=>$item_id,'actor_user_id'=>$actor_id,'created'=>false,'errors'=>[],'updated_at'=>current_time('mysql')];
				$set_notice = static function (bool $success, string $message) use ($actor_id): void {
					set_transient('sn_paid_referral_action_notice_' . $actor_id, [
						'success' => $success,
						'message' => $message,
					], 5 * MINUTE_IN_SECONDS);
				};
				if (! $item || (string)($item->source_type ?? '') !== 'paid_invoice_referral') {
					$report['errors'][] = 'item_not_found';
					$report['message'] = 'این مورد دیگر در صف اقدام مجدد موجود نیست؛ لطفاً صفحه را تازه کنید.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}
				$can_manage = current_user_can('manage_options');
				if ((int)($item->current_owner_user_id ?? 0) !== $actor_id && ! $can_manage) {
					$report['errors'][] = 'not_owner';
					$report['message'] = 'این پرونده دیگر در اختیار شما نیست؛ لطفاً صفحه را تازه کنید.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				if ((string)($item->workflow_kind ?? '') === 'invoice_payment_completion') {
					$invoice_id = (int)($item->ref_invoice_id ?? 0);
					$mode = sanitize_key(wp_unslash($_POST['stage_mode'] ?? 'remaining'));
					$choice = sanitize_text_field(wp_unslash($_POST['prepayment_choice'] ?? ''));
					$custom_amount = $this->sn_parse_money_value($_POST['custom_amount'] ?? 0);
					$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));

					$wpdb->query('START TRANSACTION');
					// Lock order is always invoice -> workflow item, matching cancellation.
					$locked_invoice = $invoice_id > 0 ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $invoice_id)) : null;
					$locked_item = $item_id > 0 ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d FOR UPDATE", $item_id)) : null;
					if (! $locked_invoice || ! $locked_item) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = ! $locked_invoice ? 'invoice_not_found' : 'item_not_found_after_lock';
						$report['message'] = ! $locked_invoice ? 'فاکتور مرجع پیدا نشد.' : 'پرونده اقدام مجدد پیدا نشد.';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}
					if ((string)($locked_item->source_type ?? '') !== 'paid_invoice_referral'
						|| (string)($locked_item->workflow_kind ?? '') !== 'invoice_payment_completion'
						|| (int)($locked_item->ref_invoice_id ?? 0) !== $invoice_id
						|| (string)($locked_item->status ?? '') !== 'payment_assigned'
						|| ((int)($locked_item->current_owner_user_id ?? 0) !== $actor_id && ! $can_manage)) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = 'stale_or_unauthorized_assignment';
						$report['message'] = 'این ارجاع قبلاً تغییر کرده یا دیگر در اختیار شما نیست.';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}

					$totals = $this->sn_invoice_payment_totals($locked_invoice);
					$remaining = (float)$totals['remaining'];
					if ($totals['workflow_status'] !== 'awaiting_assignment' || (float)$totals['due'] > 0) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = 'invoice_not_ready_for_next_stage';
						$report['message'] = 'این فاکتور در وضعیت صدور مرحله بعد نیست.';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}

					$amount = $remaining;
					$stage_type = 'remaining';
					if ($mode === 'partial') {
						$amount = $choice === 'custom' ? $custom_amount : $this->sn_parse_money_value($choice);
						$stage_type = 'partial';
						if ($amount <= 0 || $amount - $remaining > 0.5) {
							$wpdb->query('ROLLBACK');
							$report['errors'][] = 'invalid_partial_amount';
							$report['message'] = 'مبلغ مرحله بعد باید بیشتر از صفر و حداکثر برابر مانده فاکتور باشد.';
							$set_notice(false, $report['message']);
							update_option('sn_paid_referral_action_report', $report, false);
							$this->sn_finish_paid_referral_action($report);
							exit;
						}
						if ( abs($amount - $remaining) <= 0.5 ) { $amount = $remaining; $stage_type = 'remaining'; }
					}
					if ($remaining <= 0 || $amount <= 0) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = 'no_remaining';
						$report['message'] = 'مانده‌ای برای صدور مرحله پرداخت وجود ندارد.';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}

					$next_stage = max(1, (int)$totals['stage_no']) + 1;
					if (! $this->sn_create_invoice_payment_stage($invoice_id, $next_stage, $stage_type, $amount, $actor_id, $note)) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = 'stage_create_failed';
						$report['message'] = $wpdb->last_error ?: 'مرحله پرداخت ایجاد نشد';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}
					$reset = [
						'current_due_amount'=>$amount,
						'current_payment_stage'=>$next_stage,
						'payment_workflow_status'=>'awaiting_payment',
						'current_stage_issued_by_user_id'=>$actor_id,
						'status'=>'pre_invoice',
						'invoice_status'=>'pre_invoice',
						'payment_status'=>'pending_payment',
						'receipt_url'=>null, 'receipt_urls'=>null,
						'receipt_file'=>null,
						'receipt_source'=>null,
						'manual_transfer_type'=>null,'manual_account_last6'=>null,'manual_tracking_last6'=>null,'manual_account_owner'=>null,'manual_card_from'=>null,
						'manual_card_to'=>null,
						'manual_card_to_number'=>null,
						'manual_amount'=>null,
						'manual_paid_at'=>null,
						'manual_paid_at_jalali'=>null,
						'rejected_by'=>null,
						'rejected_at'=>null,
						'rejected_reason'=>null,
						'updated_at'=>current_time('mysql'),
					];
					$invoice_updated = $wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, $reset), ['id'=>$invoice_id]);
					$item_updated = $wpdb->update($table, $this->sn_distribution_filter_existing_columns_fresh($table, [
						'status'=>'payment_stage_issued',
						'referral_issued_by_user_id'=>$actor_id,
						'updated_at'=>current_time('mysql'),
					]), ['id'=>$item_id, 'status'=>'payment_assigned']);
					if (! is_int($invoice_updated) || $invoice_updated < 1 || ! is_int($item_updated) || $item_updated < 1) {
						$wpdb->query('ROLLBACK');
						$report['errors'][] = 'stage_state_update_failed';
						$report['message'] = $wpdb->last_error ?: 'وضعیت مرحله پرداخت تغییر نکرد';
						$set_notice(false, $report['message']);
						update_option('sn_paid_referral_action_report', $report, false);
						$this->sn_finish_paid_referral_action($report);
						exit;
					}
					$wpdb->query('COMMIT');

					$sms_sent = $this->sn_send_invoice_stage_sms($invoice_id);
					$this->sn_distribution_log($item_id, 'invoice_payment_stage_issued', $actor_id, (int)$locked_item->current_owner_user_id, (int)$locked_item->current_owner_user_id, (string)$locked_item->current_owner_position, (string)$locked_item->current_owner_position, 999, 'صدور مرحله بعد پرداخت', [
						'invoice_id'=>$invoice_id,
						'stage_no'=>$next_stage,
						'amount'=>$amount,
						'stage_type'=>$stage_type,
						'original_seller_id'=>(int)($locked_item->referral_original_seller_id ?? 0),
					]);
					$this->sn_log_activity($invoice_id, null, 'invoice_payment_stage_issued', 'مرحله بعد پرداخت روی همان فاکتور صادر شد', [
						'stage_no'=>$next_stage,
						'amount'=>$amount,
						'stage_type'=>$stage_type,
						'issued_by_user_id'=>$actor_id,
						'original_seller_id'=>(int)($locked_item->referral_original_seller_id ?? 0),
						'sms_sent'=>$sms_sent,
					]);
					$report['created'] = true;
					$report += [
						'created'=>true,
						'invoice_id'=>$invoice_id,
						'invoice_code'=>(string)$locked_invoice->invoice_code,
						'stage_no'=>$next_stage,
						'amount'=>$amount,
						'sms_sent'=>$sms_sent,
					];
					$set_notice(true, $sms_sent
						? 'مرحله بعد پرداخت صادر و لینک آن برای مشتری پیامک شد.'
						: 'مرحله بعد پرداخت صادر شد، اما ارسال پیامک ناموفق بود؛ لینک را دستی برای مشتری ارسال کنید.');
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				$seller_id = (int)(($item->referral_original_seller_id ?? 0) ?: ($item->final_seller_user_id ?? 0));
				$ref_invoice = ! empty($item->ref_invoice_id)
					? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", (int)$item->ref_invoice_id))
					: null;
				if ($seller_id < 1 && $ref_invoice) { $seller_id = (int)($ref_invoice->seller_id ?? 0); }
				if (! $this->sn_user_can_issue_invoice_for_seller($actor_id, $seller_id)) {
					$report['errors'][] = 'seller_not_in_scope';
					$report['message'] = 'فروشنده اصلی این پرونده در محدوده سازمانی شما نیست.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				// Empty status is retained for old referral rows that predate the explicit state machine.
				$allowed_statuses = ['', 'needs_repeat_action', 'pending_supervisor_action', 'referral_self_invoice_pending', 'assigned_to_role', 'paid_referral_routed'];
				if (! in_array((string)($item->status ?? ''), $allowed_statuses, true) || (int)($item->follow_invoice_id ?? 0) > 0) {
					$report['errors'][] = 'repeat_action_already_processed';
					$report['message'] = 'این اقدام قبلاً انجام شده یا وضعیت پرونده تغییر کرده است.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				$name = sanitize_text_field(wp_unslash($_POST['customer_name'] ?? ''))
					?: (string)($item->seller_customer_name ?? '')
					?: (string)($ref_invoice->customer_name ?? '');
				$phone = SN_Helpers::normalize_mobile(
					sanitize_text_field(wp_unslash($_POST['customer_phone'] ?? ''))
						?: (string)($item->normalized_phone ?? '')
						?: (string)($ref_invoice->customer_phone ?? '')
				);
				$product_ids = $_POST['product_ids'] ?? [];
				if (! is_array($product_ids)) { $product_ids = [$product_ids]; }
				$product_ids = array_values(array_filter(array_map('absint', $product_ids)));
				if (! $product_ids && ! empty($item->ref_product_id)) { $product_ids = [(int)$item->ref_product_id]; }
				$qtys = $_POST['product_qtys'] ?? [];

				$request = [
					'seller_id' => $seller_id,
					'customer_name' => $name,
					'customer_phone' => $phone,
					'province' => sanitize_text_field(wp_unslash($_POST['province'] ?? '')) ?: (string)($item->seller_province ?? '') ?: (string)($ref_invoice->province ?? ''),
					'city' => sanitize_text_field(wp_unslash($_POST['city'] ?? '')) ?: (string)($item->seller_city ?? '') ?: (string)($ref_invoice->city ?? ''),
					'customer_address' => sanitize_textarea_field(wp_unslash($_POST['customer_address'] ?? '')) ?: (string)($ref_invoice->customer_address ?? ''),
					'customer_postal_code' => sanitize_text_field(wp_unslash($_POST['customer_postal_code'] ?? '')) ?: (string)($ref_invoice->customer_postal_code ?? ''),
					'product_ids' => $product_ids,
					'product_qtys' => is_array($qtys) ? $qtys : [],
					'product_id' => $product_ids[0] ?? 0,
					'lead_id' => $this->sn_distribution_virtual_lead_id($item_id),
					'sn_paid_referral_item_id' => $item_id,
					'payment_plan' => 'full',
				];

				// The permission bypass is an internal-only flag after ownership and HR scope checks above.
				// It cannot be enabled by a public request and does not change ordinary manual invoice permissions.
				$lock_key = 'sn_paid_referral_invoice_create_lock_' . $item_id;
				$lock_time = (int)get_option($lock_key, 0);
				if ($lock_time > 0 && $lock_time <= time() - 120) { delete_option($lock_key); }
				if ($lock_time > time() - 120 || ! add_option($lock_key, time(), '', false)) {
					$report['errors'][] = 'invoice_creation_in_progress';
					$report['message'] = 'صدور این فاکتور در حال انجام است؛ چند لحظه دیگر صفحه را تازه کنید.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				// Re-read after acquiring the atomic lock. This closes the small window
				// where a delayed second request had loaded the row before the first one
				// finished, then reached this point after the lock was released.
				$fresh_item = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $item_id));
				$fresh_status = (string)($fresh_item->status ?? '');
				$fresh_allowed = $fresh_item
					&& (string)($fresh_item->source_type ?? '') === 'paid_invoice_referral'
					&& (string)($fresh_item->workflow_kind ?? '') !== 'invoice_payment_completion'
					&& ((int)($fresh_item->current_owner_user_id ?? 0) === $actor_id || $can_manage)
					&& in_array($fresh_status, $allowed_statuses, true)
					&& (int)($fresh_item->follow_invoice_id ?? 0) < 1;
				if (! $fresh_allowed) {
					delete_option($lock_key);
					$report['errors'][] = 'repeat_action_changed_after_lock';
					$report['message'] = 'این اقدام قبلاً انجام شده یا وضعیت پرونده تغییر کرده است.';
					$set_notice(false, $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$this->sn_finish_paid_referral_action($report);
					exit;
				}
				$item = $fresh_item;

				// If a previous request created the invoice but its final queue-link update
				// was interrupted, repair that link instead of issuing a second invoice.
				$existing_invoice = $this->sn_table_has_column($invoice_table, 'referral_item_id')
					? $wpdb->get_row($wpdb->prepare("SELECT id,invoice_code FROM {$invoice_table} WHERE referral_item_id=%d ORDER BY id ASC LIMIT 1", $item_id))
					: null;
				if ($existing_invoice) {
					$link_where = ['id' => $item_id, 'status' => $item->status === null ? null : (string)$item->status];
					$link_updated = $wpdb->update($table, $this->sn_filter_existing_columns($table, [
						'follow_invoice_id' => (int)$existing_invoice->id,
						'referral_issued_by_user_id' => $actor_id,
						'status' => 'referral_invoice_created',
						'updated_at' => current_time('mysql'),
					]), $link_where);
					delete_option($lock_key);
					$report['result_success'] = is_int($link_updated) && $link_updated > 0;
					$report['created'] = true;
					$report['invoice_id'] = (int)$existing_invoice->id;
					$report['invoice_code'] = (string)$existing_invoice->invoice_code;
					$report['message'] = $report['result_success']
						? 'فاکتور قبلاً صادر شده بود و اتصال آن به صف اقدام با موفقیت بازیابی شد.'
						: 'فاکتور قبلاً صادر شده، اما اتصال آن به صف اقدام بازیابی نشد؛ کد فاکتور: ' . ($report['invoice_code'] ?: (string)$report['invoice_id']);
					if (! $report['result_success']) { $report['errors'][] = 'existing_referral_link_repair_failed'; }
					$set_notice($report['result_success'], $report['message']);
					update_option('sn_paid_referral_action_report', $report, false);
					$back = add_query_arg('sn_ok', rawurlencode((string)$report['invoice_code']), wp_get_referer() ?: home_url());
					$this->sn_finish_paid_referral_action($report);
					exit;
				}

				try {
					$result = $this->sn_create_invoice_core($request, true);
					$report['result_success'] = ! empty($result['success']);
					$report['message'] = (string)($result['message'] ?? '');
					if (! empty($result['success'])) {
						$new_id = (int)($result['data']['invoice_id'] ?? 0);
						$link_where = ['id' => $item_id, 'status' => $item->status === null ? null : (string)$item->status];
						$link_updated = $wpdb->update($table, $this->sn_filter_existing_columns($table, [
							'follow_invoice_id' => $new_id,
							'referral_issued_by_user_id' => $actor_id,
							'status' => 'referral_invoice_created',
							'updated_at' => current_time('mysql'),
						]), $link_where);
						$report['created'] = true;
						$report['invoice_id'] = $new_id;
						$report['invoice_code'] = (string)($result['data']['invoice_code'] ?? '');
						if (! is_int($link_updated) || $link_updated < 1) {
							$report['errors'][] = 'referral_link_update_failed';
							$report['message'] = 'فاکتور صادر شد، اما اتصال آن به صف اقدام مجدد ثبت نشد؛ کد فاکتور: ' . ($report['invoice_code'] ?: (string)$new_id);
							$set_notice(false, $report['message']);
						} else {
							$sms_sent = ! empty($result['data']['sms_sent']);
							$report['message'] = $sms_sent
								? 'فاکتور جدید با کد ' . $report['invoice_code'] . ' صادر و برای مشتری پیامک شد.'
								: 'فاکتور جدید با کد ' . $report['invoice_code'] . ' صادر شد، اما ارسال پیامک ناموفق بود.';
							$set_notice(true, $report['message']);
						}
					} else {
						$report['errors'][] = (string)($result['message'] ?? 'invoice_create_failed');
						$report['message'] = (string)($result['message'] ?? 'صدور فاکتور انجام نشد.');
						$set_notice(false, $report['message']);
					}
				} finally {
					delete_option($lock_key);
				}

				update_option('sn_paid_referral_action_report', $report, false);
				$back = wp_get_referer() ?: home_url();
				if (! empty($report['invoice_code'])) { $back = add_query_arg('sn_ok', rawurlencode((string)$report['invoice_code']), $back); }
				$this->sn_finish_paid_referral_action($report);
				exit;
			}

			private function sn_invoice_product_ids_for_referral(int $invoice_id, $invoice): array
			{
				global $wpdb;
				$ids = [];
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoice_items')) {
					$ids = array_map('intval', $wpdb->get_col($wpdb->prepare("SELECT product_id FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d ORDER BY id ASC", $invoice_id)) ?: []);
				}
				$fallback = (int) ($invoice->product_id ?? 0);
				if ($fallback > 0) { $ids[] = $fallback; }
				return array_values(array_unique(array_filter($ids)));
			}

			private function sn_create_paid_invoice_referral_item(int $invoice_id, $invoice): void
			{
				global $wpdb;
				$invoice_id = absint($invoice_id);
				$inv = is_object($invoice) ? $invoice : (object) $invoice;
				if ($invoice_id < 1 || ! $this->sn_distribution_tables_ready()) { return; }
				$this->sn_distribution_ensure_seller_inline_columns();
				$product_ids = $this->sn_invoice_product_ids_for_referral($invoice_id, $inv);
				$trigger_product_id = 0;
				$target_scope = 'self';
				$referral_mode = 'auto';
				$follow_product_id = 0;
				$note = '';
				foreach ($product_ids as $pid) {
					if ((string) get_post_meta($pid, '_sn_paid_referral_enabled', true) !== '1') { continue; }
					$trigger_product_id = (int) $pid;
					$referral_mode = sanitize_key((string) get_post_meta($pid, '_sn_paid_referral_mode', true)) ?: 'auto';
					if (! in_array($referral_mode, ['auto', 'manual'], true)) { $referral_mode = 'auto'; }
					$target_scope = sanitize_key((string) get_post_meta($pid, '_sn_paid_referral_target', true));
					if (! in_array($target_scope, ['self', 'supervisor', 'senior_supervisor'], true)) { $target_scope = 'self'; }
					$follow_product_id = (int) get_post_meta($pid, '_sn_paid_referral_product_id', true);
					$note = sanitize_textarea_field((string) get_post_meta($pid, '_sn_paid_referral_note', true));
					break;
				}
				if ($trigger_product_id < 1) { return; }
				if ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE source_type=%s AND source_id=%d AND COALESCE(workflow_kind,'')<>'invoice_payment_completion'", 'paid_invoice_referral', $invoice_id)) > 0) { return; }
				$seller_id = (int) ($inv->seller_id ?? 0);
				$target_user_id = $referral_mode === 'manual' ? $seller_id : $this->sn_paid_referral_parent_target($seller_id, $target_scope);
				if ($target_user_id < 1) { $target_user_id = $seller_id; }
				$target_position = $this->sn_hr_position_for_user($target_user_id);
				if ($target_position === '') { $target_position = $target_user_id === $seller_id ? 'seller' : 'sales'; }
				$is_seller_target = $target_position === 'seller';
				if ($referral_mode === 'manual') { $is_seller_target = false; }
				$is_supervisor_target = $referral_mode !== 'manual' && in_array($target_scope, ['supervisor', 'senior_supervisor'], true);
				$phone = SN_Helpers::normalize_mobile((string) ($inv->customer_phone ?? ''));
				$inserted = $wpdb->insert($wpdb->prefix . 'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_distribution_items', [
					'source_type' => 'paid_invoice_referral',
					'source_id' => $invoice_id,
					'batch_id' => null,
					'pool_item_id' => null,
					'current_owner_user_id' => $target_user_id,
					'current_owner_position' => $target_position,
					'current_step_order' => $is_seller_target ? 999 : 0,
					'final_seller_user_id' => $is_supervisor_target ? null : $seller_id,
					'live_lead_id' => null,
					'status' => $referral_mode === 'manual' ? 'needs_repeat_action' : ($is_supervisor_target ? 'pending_supervisor_action' : ($is_seller_target ? 'delivered_to_seller' : 'assigned_to_role')),
					'seller_customer_name' => sanitize_text_field((string) ($inv->customer_name ?? '')),
					'seller_province' => sanitize_text_field((string) ($inv->province ?? '')),
					'seller_city' => sanitize_text_field((string) ($inv->city ?? '')),
					'customer_phone' => $phone,
					'normalized_phone' => $phone,
					'ref_invoice_id' => $invoice_id,
					'ref_product_id' => $follow_product_id > 0 ? $follow_product_id : $trigger_product_id,
					'referral_original_seller_id' => $seller_id,
					'referral_target_scope' => $referral_mode === 'manual' ? 'seller_choice' : $target_scope,
					'referral_note' => $note,
					'created_at' => current_time('mysql'),
					'updated_at' => current_time('mysql'),
				]));
				if ($inserted) {
					$item_id = (int) $wpdb->insert_id;
					$this->sn_distribution_log($item_id, $referral_mode === 'manual' ? 'paid_invoice_repeat_action_created' : 'paid_invoice_referral_created', get_current_user_id() ?: 0, $seller_id, $target_user_id, 'invoice', $target_position, $is_seller_target ? 999 : 0, $note, ['invoice_id' => $invoice_id, 'trigger_product_id' => $trigger_product_id, 'follow_product_id' => $follow_product_id, 'target_scope' => $target_scope, 'referral_mode' => $referral_mode, 'live_lead_created' => false]);
					$this->sn_log_activity($invoice_id, (int) ($inv->lead_id ?? 0), $referral_mode === 'manual' ? 'paid_invoice_repeat_action_created' : 'paid_invoice_referral_created', $referral_mode === 'manual' ? 'نیاز به اقدام مجدد بعد از تایید مالی ساخته شد' : 'ارجاع بعد از تایید مالی محصول ساخته شد', ['distribution_item_id' => $item_id, 'target_user_id' => $target_user_id, 'target_scope' => $target_scope, 'trigger_product_id' => $trigger_product_id, 'referral_mode' => $referral_mode]);
					if ($is_supervisor_target && class_exists('SN_Dot_Flow') && method_exists('SN_Dot_Flow', 'ensure_paid_referral_conversion_case')) {
						SN_Dot_Flow::instance()->ensure_paid_referral_conversion_case($item_id, $target_user_id);
					}
				}
			}


			public function handle_invoice_payment_workflow_cancel(): void
			{
				if (! is_user_logged_in()) { wp_die('دسترسی غیرمجاز'); }
				check_admin_referer('sn_invoice_payment_workflow_cancel');
				$this->maybe_create_tables();
				$this->sn_distribution_ensure_seller_inline_columns();
				global $wpdb;

				$actor_id = get_current_user_id();
				$item_id = absint($_POST['referral_item_id'] ?? 0);
				$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				if ($reason === '') { wp_die('دلیل انصراف الزامی است'); }

				$table = $wpdb->prefix . 'sn_distribution_items';
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
				$item_hint = $item_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $item_id)) : null;
				if (! $item_hint || (string)($item_hint->workflow_kind ?? '') !== 'invoice_payment_completion') { wp_die('دسترسی غیرمجاز'); }
				$invoice_id = (int)($item_hint->ref_invoice_id ?? 0);
				$can_manage = current_user_can('manage_options');

				$wpdb->query('START TRANSACTION');
				// Lock invoice first so a concurrent gateway/finance approval cannot be archived after completion.
				$invoice = $invoice_id > 0 ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $invoice_id)) : null;
				$item = $item_id > 0 ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d FOR UPDATE", $item_id)) : null;
				if (! $invoice || ! $item) {
					$wpdb->query('ROLLBACK');
					wp_die(! $invoice ? 'فاکتور یافت نشد' : 'ارجاع یافت نشد');
				}
				$is_current_owner = (int)($item->current_owner_user_id ?? 0) === $actor_id;
				$is_original_seller = (int)($item->referral_original_seller_id ?? 0) === $actor_id;
				$is_latest_assigner = (int)($item->workflow_assigned_by_user_id ?? 0) === $actor_id;
				if ((string)($item->source_type ?? '') !== 'paid_invoice_referral'
					|| (string)($item->workflow_kind ?? '') !== 'invoice_payment_completion'
					|| (int)($item->ref_invoice_id ?? 0) !== $invoice_id
					|| (! $is_current_owner && ! $is_original_seller && ! $is_latest_assigner && ! $can_manage)
					|| in_array((string)($item->status ?? ''), ['payment_completed','referral_cancelled'], true)) {
					$wpdb->query('ROLLBACK');
					wp_die('این پرونده دیگر قابل بایگانی توسط شما نیست');
				}

				$totals = $this->sn_invoice_payment_totals($invoice);
				if ((float)$totals['remaining'] <= 0
					|| $totals['workflow_status'] === 'completed'
					|| in_array((string)$invoice->status, ['paid','approved'], true)) {
					$wpdb->query('ROLLBACK');
					wp_die('فاکتور تکمیل‌شده قابل بایگانی انصرافی نیست');
				}
				if ($totals['workflow_status'] === 'archived' || (string)$invoice->status === 'payment_archived') {
					$wpdb->query('ROLLBACK');
					wp_die('این فاکتور قبلاً بایگانی شده است');
				}
				$current_stage = $this->sn_current_invoice_payment_stage($invoice_id, max(1, (int)$totals['stage_no']));
				$invoice_payment_state = (string)(($invoice->payment_status ?? '') ?: ($invoice->invoice_status ?? '') ?: ($invoice->status ?? ''));
				if (($current_stage && (string)$current_stage->status === 'pending_financial_approval')
					|| in_array($invoice_payment_state, ['receipt_uploaded','pending_financial_approval'], true)) {
					$wpdb->query('ROLLBACK');
					wp_die('برای این مرحله فیش ثبت شده است؛ ابتدا واحد مالی باید آن را تأیید یا رد کند.');
				}

				$invoice_archived = $wpdb->update($invoice_table, $this->sn_filter_existing_columns($invoice_table, [
					'status'=>'payment_archived',
					'invoice_status'=>'payment_archived',
					'payment_status'=>'payment_archived',
					'payment_workflow_status'=>'archived',
					'current_due_amount'=>0,
					'payment_archived_at'=>current_time('mysql'),
					'payment_archived_by'=>$actor_id,
					'payment_archive_reason'=>$reason,
					'updated_at'=>current_time('mysql'),
				]), ['id'=>$invoice_id]);
				$item_archived = $wpdb->update($table, $this->sn_distribution_filter_existing_columns_fresh($table, [
					'status'=>'referral_cancelled',
					'seller_notes'=>$reason,
					'updated_at'=>current_time('mysql'),
				]), ['id'=>$item_id]);
				$stage_archived = true;
				if ($this->sn_table_exists_quiet($stage_table)) {
					$stage_result = $wpdb->query($wpdb->prepare(
						"UPDATE {$stage_table} SET status='cancelled', note=CONCAT(COALESCE(note,''), %s), updated_at=%s WHERE invoice_id=%d AND stage_no=%d AND status NOT IN ('paid','approved')",
						"\nبایگانی نهایی: " . $reason,
						current_time('mysql'),
						$invoice_id,
						max(1, (int)$totals['stage_no'])
					));
					$stage_archived = $stage_result !== false;
				}
				if ($invoice_archived === false || $item_archived === false || ! $stage_archived) {
					$wpdb->query('ROLLBACK');
					wp_die('بایگانی فاکتور انجام نشد: ' . esc_html($wpdb->last_error ?: 'خطای دیتابیس'));
				}
				$wpdb->query('COMMIT');

				$this->sn_distribution_log($item_id, 'invoice_payment_archived', $actor_id, (int)$item->current_owner_user_id, (int)$item->current_owner_user_id, (string)$item->current_owner_position, (string)$item->current_owner_position, 999, $reason, [
					'invoice_id'=>$invoice_id,
					'paid_total'=>$totals['paid'],
					'remaining_amount'=>$totals['remaining'],
					'original_seller_id'=>(int)($item->referral_original_seller_id ?? 0),
				]);
				$this->sn_log_activity($invoice_id, (int)($invoice->lead_id ?? 0), 'invoice_payment_archived', 'فاکتور مرحله‌ای با انصراف نهایی بایگانی شد', [
					'reason'=>$reason,
					'archived_by'=>$actor_id,
					'paid_total'=>$totals['paid'],
					'remaining_amount'=>$totals['remaining'],
					'original_seller_id'=>(int)($item->referral_original_seller_id ?? 0),
				]);
				wp_safe_redirect(wp_get_referer() ?: home_url());
				exit;
			}

			public function on_invoice_paid(int $invoice_id, $invoice): void
			{
				global $wpdb;
				if (class_exists('SN_Dot_Flow') && SN_Dot_Flow::instance()->should_bypass_core_paid_flow($invoice_id)) { return; }

				$inv = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
				if (! $inv) { $inv = is_object($invoice) ? $invoice : (object) $invoice; }
				$payment_totals = $this->sn_invoice_payment_totals($inv);
				if ($payment_totals['remaining'] > 0 || ! in_array((string)($inv->status ?? ''), ['paid','approved'], true)) { return; }

				// اگه customer_wp_id نداشت، سعی کن بسازیم
				$customer_wp_id = (int) ($inv->customer_wp_id ?? 0);
				if (! $customer_wp_id) {
					$customer_wp_id = $this->get_or_create_customer_account(
						$inv->customer_phone,
						$inv->customer_name
					);
					if ($customer_wp_id) {
						$wpdb->update(
							$wpdb->prefix . 'sn_invoices',
							['customer_wp_id' => $customer_wp_id],
							['id' => $invoice_id]
						);
					}
				}

				// تکمیل پروفایل مشتری و ثبت سفارش ووکامرس پس از پرداخت تایید شده
				if ($customer_wp_id) { $this->sn_sync_customer_profile_from_invoice($customer_wp_id, $inv); }
				$this->sn_create_wc_order_for_invoice($invoice_id, $inv);
				// An Operations upgrade is a payment for the existing card, not a new
				// sales lead. Keep order/commission/accounting hooks, but do not create
				// a second post-payment referral from the target Product* metadata.
				$is_operations_upgrade = class_exists('SN_Operations_Flow') && SN_Operations_Flow::instance()->is_upgrade_invoice($invoice_id);
				if (! $is_operations_upgrade) { $this->sn_create_paid_invoice_referral_item($invoice_id, $inv); }

				// ذخیره محصولات خریداری‌شده در user meta برای دسترسی سریع
				$this->sn_credit_wallet_for_invoice($invoice_id, $inv);
				$pm = (string)($inv->pay_method ?? '');
				$this->sn_maybe_send_payment_sms($inv, $pm === 'online' ? 'online' : 'card_to_card');

				if ($customer_wp_id && $inv->product_id) {
					$owned = get_user_meta($customer_wp_id, 'sn_owned_products', true);
					$owned = is_array($owned) ? $owned : [];
					if (! in_array((int) $inv->product_id, $owned, true)) {
						$owned[] = (int) $inv->product_id;
						update_user_meta($customer_wp_id, 'sn_owned_products', $owned);
					}
				}
			}

			/** Reverse only this plugin's posted seller/supervisor commission credits. */
			public function on_invoice_financial_rejected_commission(int $invoice_id, $invoice = null, string $reason = ''): void
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_wallet_transactions';
				if ($invoice_id < 1 || ! $this->sn_wallet_table_exists($table)) { return; }
				$credits = $wpdb->get_results($wpdb->prepare(
					"SELECT * FROM {$table} WHERE invoice_id=%d AND direction='credit' AND status='approved' AND type IN ('commission_engine','seller_commission','supervisor_commission') ORDER BY id ASC",
					$invoice_id
				), ARRAY_A) ?: [];
				foreach ($credits as $credit) {
					$credit_id = (int) ($credit['id'] ?? 0);
					$user_id = (int) ($credit['user_id'] ?? 0);
					$amount = (float) ($credit['amount'] ?? 0);
					if ($credit_id < 1 || $user_id < 1 || $amount <= 0) { continue; }
					$reversal_type = (string) $credit['type'] === 'supervisor_commission' ? 'supervisor_commission_reversal' : ((string) $credit['type'] === 'seller_commission' ? 'seller_commission_reversal' : 'commission_engine_reversal');
					$reversal_key = 'commission-reversal:' . $credit_id . ':' . $reversal_type;
					$already_reversed = in_array('idempotency_key', $this->sn_table_columns($table), true)
						? (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE idempotency_key=%s LIMIT 1", $reversal_key))
						: 0;
					$posted = $already_reversed > 0 || $this->sn_add_wallet_transaction(
						$user_id,
						(string) ($credit['wallet_type'] ?? 'seller'),
						$amount,
						'debit',
						$reversal_type,
						'برگشت پورسانت فاکتور لغو/ردشده #' . $invoice_id,
						$invoice_id,
						! empty($credit['lead_id']) ? (int) $credit['lead_id'] : null,
						['original_credit_transaction_id' => $credit_id, 'idempotency_key' => $reversal_key, 'reason' => sanitize_textarea_field($reason)]
					);
					if ($posted) {
						$archive = ['type' => (string) $credit['type'] . '_reversed'];
						if (in_array('idempotency_key', $this->sn_table_columns($table), true)) { $archive['idempotency_key'] = null; }
						$wpdb->update($table, $archive, ['id' => $credit_id]);
					}
				}
			}

			// =========================================================
			// ACTIVITY LOG / LEAD PROFILE / FINANCIAL APPROVAL
			// =========================================================

			private function sn_can_finance(): bool
			{
				return $this->sn_can_view_finance();
			}

			private function sn_user_has_hr_position(int $user_id, $position_slug): bool
			{
				$positions = array_filter(array_map('sanitize_key', (array) $position_slug));
				return $user_id > 0 && ! empty($positions) && in_array($this->sn_hr_position_for_user($user_id), $positions, true);
			}

			private function sn_can_view_finance(): bool
			{
				return current_user_can('manage_options')
					|| current_user_can('sn_view_finance')
					|| $this->sn_user_has_hr_position((int) get_current_user_id(), 'finance');
			}

			private function sn_can_view_wallet_commission(): bool
			{
				return current_user_can('manage_options') || current_user_can('sn_view_wallet_commission');
			}

			private function sn_can_approve_payment(): bool
			{
				return current_user_can('manage_options') || current_user_can('sn_approve_payment');
			}

			private function sn_can_reject_payment(): bool
			{
				return current_user_can('manage_options') || current_user_can('sn_reject_payment');
			}

			private function sn_finance_access_denied_notice(): string
			{
				if (! is_user_logged_in()) {
					return '<p class="sn-notice sn-error">دسترسی غیرمجاز.</p>';
				}
				$user = wp_get_current_user();
				$roles = array_filter(array_map('sanitize_key', (array) $user->roles));
				$position = $this->sn_hr_position_for_user((int) $user->ID);
				$html  = '<div class="sn-notice sn-error" dir="rtl">';
				$html .= '<strong>دسترسی غیرمجاز.</strong>';
				$html .= '<div class="sn-muted" style="margin-top:6px">';
				$html .= 'شناسه کاربر: #' . esc_html((string) $user->ID);
				$html .= ' | سمت HR: ' . esc_html($position !== '' ? $position : 'نامشخص');
				$html .= ' | نقش‌های وردپرس: ' . esc_html($roles ? implode(', ', $roles) : 'ندارد');
				$html .= ' | مقدار مورد انتظار: finance';
				$html .= '</div></div>';
				return $html;
			}

			private function sn_can_view_invoice_internally($invoice): bool
			{
				$access = $this->sn_internal_invoice_info_access($invoice);
				return ! empty($access['allowed']);
			}

			private function sn_internal_invoice_info_access($invoice, int $viewer_user_id = 0, string $invoice_code = ''): array
			{
				$viewer_user_id = $viewer_user_id > 0 ? $viewer_user_id : (int) get_current_user_id();
				$invoice_id = (int) ($invoice->id ?? 0);
				$seller_id = (int) ($invoice->seller_id ?? 0);
				$user_can_manage_options = $viewer_user_id > 0 && user_can($viewer_user_id, 'manage_options');
				$is_super_admin = $viewer_user_id > 0 && function_exists('is_super_admin') && is_super_admin($viewer_user_id);
				$base = [
					'allowed' => false,
					'current_user_id' => $viewer_user_id,
					'user_can_manage_options' => $user_can_manage_options ? 'yes' : 'no',
					'is_super_admin' => $is_super_admin ? 'yes' : 'no',
					'invoice_code' => $invoice_code !== '' ? $invoice_code : (string) ($invoice->invoice_code ?? ''),
					'invoice_id' => $invoice_id,
					'invoice_seller_id' => $seller_id,
					'debug_branch' => 'internal_invoice_info_permission',
					'permission_branch' => 'none',
					'reason' => 'not_checked',
				];
				if (! $invoice || ! is_user_logged_in() || $viewer_user_id <= 0) {
					$base['permission_branch'] = 'preflight';
					$base['reason'] = 'missing_invoice_or_logged_in_user';
					return $base;
				}
				if ($user_can_manage_options || $is_super_admin) {
					$base['allowed'] = true;
					$base['permission_branch'] = $user_can_manage_options ? 'manage_options' : 'super_admin';
					$base['reason'] = 'admin_read_only_invoice_info';
					return $base;
				}
				if ($this->sn_can_view_finance()) {
					$base['allowed'] = true;
					$base['permission_branch'] = 'finance';
					$base['reason'] = 'finance_read_permission';
					return $base;
				}
				$user = $viewer_user_id === (int) get_current_user_id() ? wp_get_current_user() : get_user_by('id', $viewer_user_id);
				if (! $user) {
					$base['permission_branch'] = 'preflight';
					$base['reason'] = 'viewer_user_not_found';
					return $base;
				}
				$roles = (array) $user->roles;
				if (in_array('sn_seller', $roles, true)) {
					$base['allowed'] = $seller_id === (int) $user->ID;
					$base['permission_branch'] = 'seller_owner';
					$base['reason'] = $base['allowed'] ? 'seller_own_invoice' : 'seller_not_invoice_owner';
					return $base;
				}
				if ($invoice_id > 0 && class_exists('SN_Scope_Service')) {
					$scope_service = new SN_Scope_Service();
					$position = $scope_service->get_viewer_position_slug((int) $user->ID);
					if (in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy'], true)) {
						$base['allowed'] = $scope_service->can_view_invoice((int) $user->ID, $invoice_id);
						$base['permission_branch'] = 'scope_' . $position;
						$base['reason'] = $base['allowed'] ? 'scope_invoice_allowed' : 'scope_invoice_denied';
						$base['viewer_position'] = $position;
						return $base;
					}
				}
				if (in_array('sn_supervisor', $roles, true)) {
					$base['allowed'] = $seller_id > 0 && (int) get_user_meta($seller_id, 'sn_supervisor_id', true) === (int) $user->ID;
					$base['permission_branch'] = 'legacy_supervisor';
					$base['reason'] = $base['allowed'] ? 'legacy_supervisor_seller_match' : 'legacy_supervisor_seller_mismatch';
					return $base;
				}
				if (in_array('sn_sales_manager', $roles, true)) {
					$base['allowed'] = true;
					$base['permission_branch'] = 'legacy_sales_manager';
					$base['reason'] = 'legacy_sales_manager';
					return $base;
				}
				$base['permission_branch'] = 'none';
				$base['reason'] = 'no_internal_invoice_read_permission';
				return $base;
			}

			private function sn_supervisor_scope_decision(string $context, int $viewer_user_id): array
			{
				return $this->sn_scope_decision($context, $viewer_user_id);
			}

			private function sn_scope_decision(string $context, int $viewer_user_id): array
			{
				if (! class_exists('SN_Scope_Service')) {
					return ['enforced' => false, 'would_enforce' => false, 'reason' => 'scope_service_missing', 'visible_user_ids' => []];
				}
				return (new SN_Scope_Service())->scope_enforcement_decision($context, $viewer_user_id);
			}

			private function sn_record_scope_decision(string $context, int $viewer_user_id, array $decision, $legacy_count = 0, int $scope_count = 0): void
			{
				if (! class_exists('SN_Scope_Service')) {
					return;
				}
				$scope_service = new SN_Scope_Service();
				if (is_array($legacy_count)) {
					$scope_seller_ids = null;
					if (! empty($decision['enforced']) && array_key_exists('scope_seller_ids', $legacy_count)) {
						$scope_seller_ids = (array) $legacy_count['scope_seller_ids'];
					}
					$counts = $scope_service->enforcement_count_summary(
						$viewer_user_id,
						(array) ($legacy_count['legacy_seller_ids'] ?? []),
						$scope_seller_ids
					);
				} else {
					$counts = [
						'legacy_visible_user_count' => (int) $legacy_count,
						'legacy_visible_seller_count' => (int) $legacy_count,
						'scope_visible_user_count' => (int) $scope_count,
						'scope_visible_seller_count' => (int) $scope_count,
					];
				}
				$scope_service->record_enforcement_decision($context, $viewer_user_id, $decision, $counts);
			}

			private function sn_can_perform_internal_invoice_payment_action($invoice, string $action = ''): bool
			{
				if (! $invoice || ! is_user_logged_in()) {
					return false;
				}
				if (current_user_can('manage_options') || $this->sn_can_view_finance()) {
					return true;
				}
				$user = wp_get_current_user();
				$roles = (array) $user->roles;
				$user_id = (int) $user->ID;
				// Use the canonical HR/scope position resolver here as well. Invoice lists
				// are scoped with SN_Scope_Service; using a different resolver for the
				// write action could make a visible invoice fail only at payment time.
				$position = $this->sn_hr_position_for_user($user_id);
				$invoice_id = (int) ($invoice->id ?? 0);
				if ($invoice_id < 1) {
					return false;
				}
				$is_manager = (bool) array_intersect($roles, ['sn_supervisor', 'sn_senior_supervisor', 'sn_sales_manager'])
					|| in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true);
				if ($is_manager) {
					if (class_exists('SN_Scope_Service') && in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true)) {
						$scope_allowed = (new SN_Scope_Service())->can_view_invoice($user_id, $invoice_id);
						if ($scope_allowed) { return true; }
					}
					return $this->sn_supervisor_can_access_invoice($invoice_id, $user_id);
				}
				$is_seller = in_array('sn_seller', $roles, true) || $position === 'seller';
				if ($is_seller) {
					// فروشنده برای فاکتور خودش اطلاعات و فیش را در همان درخواست دستی ثبت می‌کند.
					return $action === 'manual_payment'
						&& (int) ($invoice->seller_id ?? 0) === $user_id
						&& (! $this->sn_invoice_is_conversion_payment($invoice_id) || (int) ($invoice->issued_by_user_id ?? 0) === $user_id);
				}
				$is_converter = in_array('sn_converter', $roles, true) || $position === 'converter';
				if ($is_converter) {
					return $this->sn_converter_can_access_invoice($invoice, $user_id);
				}
				return false;
			}

			private function sn_invoice_is_conversion_payment(int $invoice_id): bool
			{
				if ($invoice_id < 1) { return false; }
				global $wpdb;
				$table = $wpdb->prefix . 'sn_dot_invoice_links';
				if (! $this->sn_table_exists_quiet($table)) { return false; }
				return (bool) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE invoice_id=%d AND flow_kind='conversion_payment' LIMIT 1", $invoice_id));
			}

			private function sn_user_owns_conversion_invoice(int $invoice_id, int $user_id): bool
			{
				if ($invoice_id < 1 || $user_id < 1) { return false; }
				global $wpdb;
				$links = $wpdb->prefix . 'sn_dot_invoice_links';
				$cases = $wpdb->prefix . 'sn_dot_cases';
				$invoices = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_table_exists_quiet($links) || ! $this->sn_table_exists_quiet($cases)) { return false; }
				return (bool) $wpdb->get_var($wpdb->prepare(
					"SELECT dl.id FROM {$links} dl INNER JOIN {$invoices} i ON i.id=dl.invoice_id LEFT JOIN {$cases} c ON c.id=dl.case_id WHERE dl.invoice_id=%d AND dl.flow_kind='conversion_payment' AND (c.converter_id=%d OR i.issued_by_user_id=%d) LIMIT 1",
					$invoice_id,
					$user_id,
					$user_id
				));
			}

			private function sn_converter_can_access_invoice($invoice, int $user_id): bool
			{
				$invoice_id = (int) ($invoice->id ?? 0);
				if ($invoice_id < 1 || $user_id < 1) { return false; }
				if ($this->sn_user_owns_conversion_invoice($invoice_id, $user_id)) { return true; }
				return ! $this->sn_invoice_is_conversion_payment($invoice_id)
					&& (int) ($invoice->seller_id ?? 0) === $user_id;
			}

			private function sn_internal_payment_source_for_current_user(): string
			{
				if (! is_user_logged_in()) { return 'customer_upload'; }
				$user = wp_get_current_user();
				$roles = (array) $user->roles;
				$position = $this->sn_hr_position_for_user((int) $user->ID);
				if ((bool) array_intersect($roles, ['sn_supervisor', 'sn_senior_supervisor', 'sn_sales_manager']) || in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true)) { return 'supervisor_manual'; }
				if (in_array('sn_converter', $roles, true) || $position === 'converter') { return 'converter_manual'; }
				if (in_array('sn_seller', $roles, true) || $position === 'seller') { return 'seller_manual'; }
				return 'supervisor_manual';
			}

			private function sn_invoice_access_for_payment_action(string $invoice_code, string $action): array
			{
				$invoice_code = sanitize_text_field($invoice_code);
				$public_token = $this->sn_public_access_token();
				if ($invoice_code !== '' && is_user_logged_in()) {
					$invoice = SN_Helpers::get_invoice_by_code($invoice_code);
					if ($invoice && $this->sn_can_perform_internal_invoice_payment_action($invoice, $action)) {
						return [
							'success' => true,
							'invoice' => $invoice,
							'internal' => true,
							'action' => $action,
						];
					}
					// Internal panels intentionally do not send the public invoice token.
					// Do not misclassify a denied internal write as an expired public link.
					// When a public token is actually present we still allow the normal
					// public-token fallback (e.g. staff opens a customer link while logged in).
					if ($public_token === '') {
						return [
							'success' => false,
							'message' => $invoice ? 'دسترسی شما برای ثبت پرداخت این فاکتور مجاز نیست.' : 'فاکتور یافت نشد.',
							'invoice' => $invoice ?: null,
							'internal' => false,
							'internal_denied' => true,
							'action' => $action,
						];
					}
				}
				return [
					'success' => false,
					'message' => 'لینک فاکتور معتبر نیست یا منقضی شده است. لطفاً لینک جدید دریافت کنید.',
					'internal' => false,
					'internal_denied' => false,
					'action' => $action,
				];
			}

			private function sn_invoice_public_url($invoice_or_code, string $access_token = ''): string
			{
				$short_url = $this->sn_invoice_short_public_url($invoice_or_code, $access_token);
				if ($short_url !== '') {
					return $short_url;
				}
				return $this->sn_invoice_public_long_url($invoice_or_code, $access_token);
			}

			private function sn_invoice_public_long_url($invoice_or_code, string $access_token = ''): string
			{
				$invoice = null;
				$code = '';
				if (is_array($invoice_or_code)) {
					$invoice = (object) $invoice_or_code;
					$code = (string) ($invoice->invoice_code ?? '');
					if ($access_token === '') {
						$access_token = (string) ($invoice->access_token ?? '');
					}
				} elseif (is_object($invoice_or_code)) {
					$invoice = $invoice_or_code;
					$code = (string) ($invoice->invoice_code ?? '');
					if ($access_token === '') {
						$access_token = (string) ($invoice->access_token ?? '');
					}
				} else {
					$code = (string) $invoice_or_code;
				}
				if ($code !== '' && $access_token === '') {
					if (! $invoice) {
						$invoice = SN_Helpers::get_invoice_by_code($code);
					}
					$access_token = $this->sn_ensure_invoice_access_token($invoice);
				}
				$page_id = (int) get_option('sn_invoice_page_id');
				$base = $page_id ? get_permalink($page_id) : home_url('/');
				return add_query_arg(array_filter([
					'invoice_code' => $code,
					'invoice' => $code,
					'access_token' => $access_token,
				]), $base ?: home_url('/'));
			}

			private function sn_invoice_short_public_url($invoice_or_code, string $access_token = ''): string
			{
				$invoice = null;
				$code = '';
				if (is_array($invoice_or_code)) {
					$invoice = (object) $invoice_or_code;
					$code = (string) ($invoice->invoice_code ?? '');
				} elseif (is_object($invoice_or_code)) {
					$invoice = $invoice_or_code;
					$code = (string) ($invoice->invoice_code ?? '');
				} else {
					$code = (string) $invoice_or_code;
				}
				if (! $invoice && $code !== '') {
					$invoice = SN_Helpers::get_invoice_by_code($code);
				}
				$short_code = $this->sn_ensure_invoice_short_code($invoice);
				if ($short_code === '') {
					return '';
				}
				return home_url('/i/' . rawurlencode($short_code) . '/');
			}

			private function sn_ensure_invoice_short_code($invoice): string
			{
				if (! $invoice) {
					return '';
				}
				$id = is_array($invoice) ? (int) ($invoice['id'] ?? 0) : (int) ($invoice->id ?? 0);
				$current = is_array($invoice) ? (string) ($invoice['short_code'] ?? '') : (string) ($invoice->short_code ?? '');
				if ($current !== '') {
					return $current;
				}
				if (! $id) {
					return '';
				}
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_ensure_invoice_short_code_column($table)) {
					return '';
				}
				$short_code = $this->sn_generate_unique_invoice_short_code();
				$updated = $wpdb->update($table, ['short_code' => $short_code], ['id' => $id]);
				if ($updated === false) {
					return '';
				}
				return (string) $wpdb->get_var($wpdb->prepare("SELECT short_code FROM {$table} WHERE id=%d", $id));
			}

			private function sn_ensure_invoice_short_code_column(string $table): bool
			{
				global $wpdb;
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					return false;
				}
				$cols = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				if (in_array('short_code', $cols, true)) {
					return true;
				}
				$ok = $wpdb->query("ALTER TABLE {$table} ADD COLUMN short_code VARCHAR(32) DEFAULT NULL AFTER access_token");
				return $ok !== false && in_array('short_code', $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0), true);
			}

			private function sn_generate_unique_invoice_short_code(int $length = 8): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				$alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
				$max = strlen($alphabet) - 1;
				for ($attempt = 0; $attempt < 20; $attempt++) {
					$code = '';
					for ($i = 0; $i < $length; $i++) {
						$code .= $alphabet[random_int(0, $max)];
					}
					$exists = (bool) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE short_code=%s LIMIT 1", $code));
					if (! $exists) {
						return $code;
					}
				}
				return wp_generate_password(max(12, $length), false, false);
			}

			private function sn_ensure_invoice_access_token($invoice): string
			{
				if (! $invoice) {
					return '';
				}
				$id = is_array($invoice) ? (int) ($invoice['id'] ?? 0) : (int) ($invoice->id ?? 0);
				$current = is_array($invoice) ? (string) ($invoice['access_token'] ?? '') : (string) ($invoice->access_token ?? '');
				if ($current !== '') {
					return $current;
				}
				if (! $id) {
					return '';
				}
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				if (! in_array('access_token', $this->sn_table_columns($table), true)) {
					return '';
				}
				$token = SN_Helpers::generate_unique_access_token();
				$updated = $wpdb->update($table, ['access_token' => $token], ['id' => $id]);
				if ($updated === false) {
					return '';
				}
				return (string) $wpdb->get_var($wpdb->prepare("SELECT access_token FROM {$table} WHERE id=%d", $id));
			}

			private function sn_public_access_token(): string
			{
				return sanitize_text_field(wp_unslash($_POST['access_token'] ?? ($_POST['token'] ?? ($_GET['access_token'] ?? ($_GET['token'] ?? '')))));
			}

			private function sn_validate_public_invoice_access(string $invoice_code, string $access_token, string $action = 'view'): array
			{
				$invoice = SN_Helpers::get_invoice_by_code($invoice_code);
				if (! $invoice || $access_token === '' || empty($invoice->access_token) || ! hash_equals((string) $invoice->access_token, $access_token)) {
					return ['success' => false, 'message' => 'لینک فاکتور معتبر نیست یا منقضی شده است. لطفاً لینک جدید دریافت کنید.', 'invoice' => null, 'status' => 403];
				}
				return ['success' => true, 'invoice' => $invoice];
			}

			private function sn_rate_limit_public_or_json(string $action, string $subject, int $limit, int $window): bool
			{
				$limited = SN_Helpers::rate_limit($action, $subject, $limit, $window);
				if (empty($limited['allowed'])) {
					if (function_exists('status_header')) { status_header(429); }
					SN_Helpers::send_json(false, (string) $limited['message'], ['retry_after' => (int) ($limited['retry_after'] ?? 0)]);
					return false;
				}
				return true;
			}

			private function sn_backfill_invoice_access_tokens(int $limit = 500): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				$report = [
					'has_table' => false,
					'has_column' => false,
					'total' => 0,
					'missing_before' => 0,
					'processed' => 0,
					'updated' => 0,
					'error' => 0,
					'remaining_missing' => 0,
					'limit' => max(1, min(1000, $limit)),
					'updated_at' => current_time('mysql'),
				];
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					update_option('sn_invoice_token_backfill_report', $report, false);
					return $report;
				}
				$report['has_table'] = true;
				$cols = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				if (! in_array('access_token', $cols, true)) {
					$wpdb->query("ALTER TABLE {$table} ADD COLUMN access_token VARCHAR(96) DEFAULT NULL AFTER invoice_code");
					$cols = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				}
				$report['has_column'] = in_array('access_token', $cols, true);
				$report['total'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table}");
				if (! $report['has_column']) {
					update_option('sn_invoice_token_backfill_report', $report, false);
					return $report;
				}
				$report['missing_before'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE access_token IS NULL OR access_token=''");
				$ids = $wpdb->get_col($wpdb->prepare("SELECT id FROM {$table} WHERE access_token IS NULL OR access_token='' ORDER BY id ASC LIMIT %d", $report['limit']));
				foreach ($ids as $id) {
					$report['processed']++;
					$updated = $wpdb->update($table, ['access_token' => SN_Helpers::generate_unique_access_token()], ['id' => (int) $id]);
					if ($updated === false) {
						$report['error']++;
					} else {
						$report['updated']++;
					}
				}
				$report['remaining_missing'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE access_token IS NULL OR access_token=''");
				update_option('sn_invoice_token_backfill_report', $report, false);
				return $report;
			}

			private function sn_hr_seller_is_in_viewer_scope(int $viewer_id, int $seller_id, bool $direct_only = false): bool
			{
				if ($viewer_id <= 0 || $seller_id <= 0) {
					return false;
				}
				$position = $this->sn_hr_position_for_user($viewer_id);
				if ($position === 'supervisor' || $direct_only) {
					$ids = array_map('intval', array_column($this->sn_get_direct_children($viewer_id, 'seller'), 'user_id'));
					return in_array($seller_id, $ids, true);
				}
				if (in_array($position, ['senior_supervisor', 'sales_manager', 'sales_deputy'], true)) {
					$ids = array_map('intval', array_column($this->sn_get_descendant_users($viewer_id, 'seller'), 'user_id'));
					return in_array($seller_id, $ids, true);
				}
				return false;
			}

			private function sn_can_manage_direct_seller_status(int $viewer_id, int $seller_id): bool
			{
				if ($viewer_id <= 0 || $seller_id <= 0) { return false; }
				if ((int) get_user_meta($seller_id, 'sn_supervisor_id', true) === $viewer_id) { return true; }
				return $this->sn_hr_seller_is_in_viewer_scope($viewer_id, $seller_id, true);
			}

			private function sn_can_view_seller_profile(int $viewer_id, int $seller_id): bool
			{
				if (! $viewer_id || ! $seller_id) { return false; }
				$viewer = get_user_by('id', $viewer_id);
				$seller = get_user_by('id', $seller_id);
				if (! $viewer || ! $seller) { return false; }
				if (user_can($viewer, 'manage_options')) { return true; }
				if ($viewer_id === $seller_id && $this->sn_hr_position_for_user($viewer_id) === 'seller') { return true; }
				if (in_array('sn_sales_manager', (array) $viewer->roles, true) || user_can($viewer, 'sn_view_sales_reports')) { return true; }
				$viewer_position = $this->sn_hr_position_for_user($viewer_id);
				if (in_array($viewer_position, ['supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy'], true)) {
					return $this->sn_hr_seller_is_in_viewer_scope($viewer_id, $seller_id, $viewer_position === 'supervisor');
				}
				if (in_array('sn_supervisor', (array) $viewer->roles, true)) {
					return (int) get_user_meta($seller_id, 'sn_supervisor_id', true) === $viewer_id;
				}
				if (in_array('sn_seller', (array) $viewer->roles, true)) {
					return $viewer_id === $seller_id;
				}
				return false;
			}

			private function sn_log_activity(?int $invoice_id, ?int $lead_id, string $action, string $description = '', array $context = []): void
			{
				global $wpdb;
				$old_value = $context['old_value'] ?? null;
				$new_value = $context['new_value'] ?? null;
				$table = $wpdb->prefix . 'sn_activity_logs';
				$data = [
					'invoice_id'  => $invoice_id ?: null,
					'lead_id'     => $lead_id ?: null,
					'user_id'     => get_current_user_id() ?: null,
					'action'      => sanitize_key($action),
					'old_value'   => is_null($old_value) ? null : wp_json_encode($old_value, JSON_UNESCAPED_UNICODE),
					'new_value'   => is_null($new_value) ? null : wp_json_encode($new_value, JSON_UNESCAPED_UNICODE),
					'description' => sanitize_textarea_field($description),
					'context'     => wp_json_encode($context, JSON_UNESCAPED_UNICODE),
					'ip_address'  => isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])) : null,
					'user_agent'  => isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field(wp_unslash($_SERVER['HTTP_USER_AGENT'])) : null,
					'created_at'  => current_time('mysql'),
				];
				$wpdb->insert($table, $this->sn_filter_existing_columns($table, $data));
				if ( $invoice_id && get_option( 'sn_report_state_baseline_at' ) && in_array( $action, [
					'customer_payment_submitted', 'seller_payment_submitted', 'supervisor_payment_submitted',
					'converter_payment_submitted', 'finance_stage_reconciled', 'financial_approval_reopened',
					'seller_resend_to_financial', 'payment_rejected', 'invoice_payment_completed',
					'invoice_partial_payment_approved', 'invoice_cancelled_by_finance',
				], true ) && ! $wpdb->last_error ) {
					$activity_id = (int) $wpdb->insert_id;
					$invoice = $wpdb->get_row( $wpdb->prepare( "SELECT seller_id,status FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id ) );
					if ( $invoice ) {
						$wpdb->insert( $wpdb->prefix . 'sn_report_invoice_state_events', [
							'invoice_id' => $invoice_id, 'seller_id' => (int) $invoice->seller_id,
							'state' => in_array( (string) $invoice->status, [ 'rejected', 'pending_financial_approval' ], true ) ? (string) $invoice->status : 'other',
							'actor_user_id' => get_current_user_id() ?: null, 'source_activity_id' => $activity_id,
							'created_at' => $data['created_at'],
						] );
					}
				}
			}

			private function sn_log_status_history(int $lead_id, $old_status, $new_status, string $note = ''): void
			{
				global $wpdb;
				$wpdb->insert($wpdb->prefix . 'sn_lead_status_history', [
					'lead_id'    => $lead_id,
					'user_id'    => get_current_user_id() ?: null,
					'old_status' => is_null($old_status) ? null : sanitize_text_field((string) $old_status),
					'new_status' => is_null($new_status) ? null : sanitize_text_field((string) $new_status),
					'note'       => sanitize_textarea_field($note),
					'created_at' => current_time('mysql'),
				]);
				$this->sn_log_activity(null, $lead_id, 'lead_status_history', 'ثبت تاریخچه تغییر وضعیت', ['old_status' => $old_status, 'new_status' => $new_status, 'note' => $note]);
			}

			private function sn_digits_only(string $value): string
			{
				$map = ['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9'];
				$value = strtr($value, $map);
				return preg_replace('/\D+/', '', $value) ?: '';
			}

			private function sn_find_wp_user_by_phone(string $phone): ?array
			{
				$digits = $this->sn_digits_only($phone);
				if ($digits === '') { return null; }
				$variants = array_values(array_unique([$phone, $digits, ltrim($digits, '0'), preg_replace('/^98/', '0', $digits)]));
				$meta_keys = ['billing_phone', 'phone', 'mobile', 'user_phone', 'sn_phone'];
				foreach ($variants as $v) {
					if ($v === '') { continue; }
					$users = get_users(['number' => 1, 'search' => $v, 'search_columns' => ['user_login', 'user_email']]);
					if (! empty($users)) { return $this->sn_wp_user_public_profile($users[0]); }
					foreach ($meta_keys as $key) {
						$users = get_users(['number' => 1, 'meta_key' => $key, 'meta_value' => $v]);
						if (! empty($users)) { return $this->sn_wp_user_public_profile($users[0]); }
					}
				}
				return null;
			}

			private function sn_wp_user_public_profile(WP_User $u): array
			{
				return [
					'ID' => (int)$u->ID,
					'user_login' => $u->user_login,
					'display_name' => $u->display_name,
					'user_email' => $u->user_email,
					'user_registered' => $u->user_registered,
					'billing_phone' => (string)get_user_meta($u->ID, 'billing_phone', true),
				];
			}

			public function ajax_lead_profile(): void
			{
				if (! is_user_logged_in()) {
					SN_Helpers::send_json(false, 'وارد نشده‌اید');
					return;
				}
				$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
				if (! $valid) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				$lead_id = absint($_POST['lead_id'] ?? 0);
				if (! $lead_id) {
					SN_Helpers::send_json(false, 'شناسه نامعتبر');
					return;
				}
				global $wpdb;
				$lead = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_leads WHERE id=%d", $lead_id), ARRAY_A);
				if (! $lead) {
					SN_Helpers::send_json(false, 'شماره یافت نشد');
					return;
				}
				$user = wp_get_current_user();
				if (! current_user_can('manage_options') && ! current_user_can('sn_view_customer_profiles')) {
					if (in_array('sn_supervisor', (array) $user->roles, true) && (int) $lead['supervisor_id'] !== (int) $user->ID) {
						SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
						return;
					}
					if (in_array('sn_seller', (array) $user->roles, true) && (int) $lead['seller_id'] !== (int) $user->ID) {
						SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
						return;
					}
				}
				$invoices = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE lead_id=%d ORDER BY id DESC", $lead_id), ARRAY_A);
				$status_history = $wpdb->get_results($wpdb->prepare("SELECT h.*, u.display_name FROM {$wpdb->prefix}sn_lead_status_history h LEFT JOIN {$wpdb->users} u ON u.ID=h.user_id WHERE h.lead_id=%d ORDER BY h.id DESC", $lead_id), ARRAY_A);
				$activity = $wpdb->get_results($wpdb->prepare("SELECT l.*, u.display_name FROM {$wpdb->prefix}sn_activity_logs l LEFT JOIN {$wpdb->users} u ON u.ID=l.user_id WHERE l.lead_id=%d ORDER BY l.id DESC LIMIT 300", $lead_id), ARRAY_A);
				$seller = ! empty($lead['seller_id']) ? get_user_by('id', (int) $lead['seller_id']) : null;
				$supervisor = ! empty($lead['supervisor_id']) ? get_user_by('id', (int) $lead['supervisor_id']) : null;
				$wp_customer = $this->sn_find_wp_user_by_phone((string)($lead['phone'] ?? ''));
				SN_Helpers::send_json(true, '', ['lead' => $lead, 'seller' => $seller ? $seller->display_name : '', 'supervisor' => $supervisor ? $supervisor->display_name : '', 'wp_user' => $wp_customer, 'invoices' => $invoices, 'status_history' => $status_history, 'activity' => $activity]);
			}

			public function ajax_supervisor_unassign_leads(): void
			{
				if (! is_user_logged_in()) {
					SN_Helpers::send_json(false, 'وارد نشده‌اید');
					return;
				}
				$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
				if (! $valid) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				$user = wp_get_current_user();
				$position = $this->sn_fast_hr_position_for_user((int) $user->ID);
				$can_upload_for_scope = current_user_can('manage_options')
					|| in_array('sn_supervisor', (array) $user->roles, true)
					|| in_array('sn_senior_supervisor', (array) $user->roles, true)
					|| in_array('sn_sales_manager', (array) $user->roles, true)
					|| in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true);
				if (! $can_upload_for_scope) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$seller_id = absint($_POST['seller_id'] ?? 0);
				$count = absint($_POST['count'] ?? 0);
				$date_from = sanitize_text_field(wp_unslash($_POST['date_from'] ?? ''));
				$date_to = sanitize_text_field(wp_unslash($_POST['date_to'] ?? ''));
				$time_from = sanitize_text_field(wp_unslash($_POST['time_from'] ?? ''));
				$time_to = sanitize_text_field(wp_unslash($_POST['time_to'] ?? ''));
				$lead_status = sanitize_text_field(wp_unslash($_POST['lead_status'] ?? ''));
				$import_code = sanitize_text_field(wp_unslash($_POST['import_code'] ?? ''));
				$supervisor_id = current_user_can('manage_options') ? absint($_POST['supervisor_id'] ?? 0) : (int) $user->ID;
				if (! $supervisor_id) {
					$supervisor_id = (int) $user->ID;
				}
				global $wpdb;
				$where = ['supervisor_id=%d', 'seller_id IS NOT NULL'];
				$args = [$supervisor_id];
				if ($seller_id) {
					$where[] = 'seller_id=%d';
					$args[] = $seller_id;
				}
				$date_from_g = SN_Helpers::jalali_to_gregorian_date($date_from);
				$date_to_g = SN_Helpers::jalali_to_gregorian_date($date_to);
				if ($date_from_g) {
					$where[] = 'DATE(assigned_at) >= %s';
					$args[] = $date_from_g;
				}
				if ($date_to_g) {
					$where[] = 'DATE(assigned_at) <= %s';
					$args[] = $date_to_g;
				}
				if ($time_from) {
					$where[] = 'TIME(assigned_at) >= %s';
					$args[] = $time_from . ':00';
				}
				if ($time_to) {
					$where[] = 'TIME(assigned_at) <= %s';
					$args[] = $time_to . ':59';
				}
				if ($lead_status !== '') {
					$where[] = 'lead_status=%s';
					$args[] = $lead_status;
				}
				if ($import_code !== '') {
					$where[] = 'import_code=%s';
					$args[] = $import_code;
				}
				$limit = $count > 0 ? ' LIMIT ' . $count : '';
				$sql = "SELECT id FROM {$wpdb->prefix}sn_leads WHERE " . implode(' AND ', $where) . " ORDER BY assigned_at DESC, id DESC" . $limit;
				$ids = array_map('intval', $wpdb->get_col($wpdb->prepare($sql, ...$args)));
				if (! $ids) {
					SN_Helpers::send_json(false, 'شماره‌ای مطابق فیلترها پیدا نشد');
					return;
				}
				$ph = implode(',', array_fill(0, count($ids), '%d'));
				$wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}sn_leads SET seller_id=NULL, status='supervisor_pool', assigned_at=NULL WHERE id IN ($ph)", ...$ids));
				$this->sn_log_activity(null, null, 'supervisor_unassign_bulk', 'جدا کردن گروهی لید از فروشنده توسط سرپرست', ['supervisor_id' => $supervisor_id, 'seller_id' => $seller_id, 'lead_status' => $lead_status, 'import_code' => $import_code, 'lead_ids' => $ids, 'count' => count($ids)]);
				foreach ($ids as $id) {
					$this->sn_log_activity(null, $id, 'lead_unassigned', 'لید از فروشنده جدا شد', ['supervisor_id' => $supervisor_id, 'seller_id' => $seller_id]);
				}
				SN_Helpers::send_json(true, count($ids) . ' شماره از فروشنده جدا شد', ['lead_ids' => $ids]);
			}

			private function sn_table_columns(string $table): array
			{
				global $wpdb;
				static $cache = [];
				if (! isset($cache[$table])) {
					$cache[$table] = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				}
				return (array) $cache[$table];
			}

			private function sn_filter_existing_columns_fresh(string $table, array $data): array
			{
				global $wpdb;
				$cols = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				return array_intersect_key($data, array_flip($cols));
			}

			private function sn_filter_existing_columns(string $table, array $data): array
			{
				$cols = $this->sn_table_columns($table);
				return array_intersect_key($data, array_flip($cols));
			}

			private function sn_ensure_payment_migrations(): void
			{
				// اجرای migration ایمن داخل AJAX هم لازم است؛ سایت‌های فعال‌شده قدیمی admin_init را همیشه اجرا نمی‌کنند.
				$this->maybe_create_tables();
			}

			private function sn_supervisor_can_access_invoice(int $invoice_id, int $supervisor_id): bool
			{
				if (current_user_can('manage_options')) {
					return true;
				}
				global $wpdb;
				$invoice = $wpdb->get_row($wpdb->prepare(
					"SELECT i.*, l.supervisor_id
					FROM {$wpdb->prefix}sn_invoices i
					LEFT JOIN {$wpdb->prefix}sn_leads l ON l.id=i.lead_id
					WHERE i.id=%d",
					$invoice_id
				), ARRAY_A);
				if (! $invoice) {
					return false;
				}
				if ((int) ($invoice['supervisor_id'] ?? 0) === $supervisor_id) {
					return true;
				}
				$seller_id = $this->sn_invoice_effective_seller_id_for_admin((array) $invoice);
				if ($seller_id > 0 && (int) get_user_meta($seller_id, 'sn_supervisor_id', true) === $supervisor_id) {
					return true;
				}
				$scope_seller_ids = array_map('intval', $this->sn_get_seller_ids_in_hr_scope($supervisor_id));
				if ($seller_id > 0 && in_array($seller_id, $scope_seller_ids, true)) {
					return true;
				}
				foreach (['issued_by_user_id', 'created_by', 'created_by_user_id'] as $actor_col) {
					if (! empty($invoice[$actor_col]) && (int) $invoice[$actor_col] === $supervisor_id) {
						return true;
					}
				}
				return false;
			}

			private function sn_save_invoice_manual_payment(int $invoice_id, string $source, array $extra = []): array
			{
				if (! $this->sn_card_to_card_enabled()) {
					return ['success'=>false,'message'=>'پرداخت کارت‌به‌کارت غیرفعال است'];
				}
				$this->sn_ensure_payment_migrations();
				global $wpdb;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
				$payments_table = $wpdb->prefix . 'sn_payments';
				$wpdb->query('START TRANSACTION');
				$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $invoice_id));
				if (! $invoice) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
				if ($source === 'customer_upload') {
					$payment_gate = $this->sn_invoice_customer_payment_gate($invoice, 'card');
					if (empty($payment_gate['allowed'])) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>(string)$payment_gate['message']]; }
					$totals = (array) $payment_gate['totals'];
				} else {
					$totals = $this->sn_invoice_payment_totals($invoice);
				}
				$due = (float)$totals['due'];
                $raw_amount = $extra['transaction_amount'] ?? ($_POST['amount'] ?? '');
                $amount = SN_Payment_Transactions::parse_amount(is_scalar($raw_amount) ? wp_unslash((string)$raw_amount) : '');
                $key = sanitize_text_field(is_scalar($_POST['submission_key'] ?? '') ? wp_unslash((string)($_POST['submission_key'] ?? '')) : '');
                if ($key !== '' && !preg_match('/^[a-zA-Z0-9_-]{16,64}$/', $key)) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'شناسه ثبت تراکنش معتبر نیست']; }
                if ($key !== '') {
                    $existing = $wpdb->get_row($wpdb->prepare("SELECT id,amount FROM {$payments_table} WHERE invoice_id=%d AND submission_key=%s LIMIT 1",$invoice_id,$key));
                    if ($existing) { $wpdb->query('ROLLBACK'); return ['success'=>true,'already'=>true,'payment_id'=>(int)$existing->id,'amount'=>(float)$existing->amount]; }
                }
                $pending_rows = SN_Payment_Transactions::pending_rows($invoice_id,(int)$totals['stage_no']);
                $pending_summary = SN_Payment_Transactions::summary($pending_rows,(int)$totals['stage_no'],$due);
                // Old clients omitted the amount for receipt-only uploads.
                if ($raw_amount === '' && $key === '') { $amount = (float)$pending_summary['available_amount']; }
                $amount_error = SN_Payment_Transactions::amount_error($amount,$due,(float)$pending_summary['pending_amount']);
                if ($amount_error !== '') { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>$amount_error]; }
                $proof = array_intersect_key($extra,array_flip(SN_Payment_Transactions::proof_fields()));
                $proof['entry_mode'] = !empty($extra['receipt_url']) ? 'receipt' : 'info';
                $proof['receipt_urls'] = SN_Helpers::receipt_urls($extra);
                $pending_urls = [];
                foreach ($pending_rows as $pending_row) {
                    $old_proof = json_decode((string)($pending_row['proof_data'] ?? ''),true);
                    $pending_urls = array_merge($pending_urls,SN_Helpers::receipt_urls(is_array($old_proof)?$old_proof:$invoice));
                }
                $all_urls = array_values(array_unique(array_merge($pending_urls,$proof['receipt_urls'])));
				if ($due <= 0 || $totals['remaining'] <= 0) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'برای این فاکتور مرحله پرداخت فعالی وجود ندارد']; }
				if ($due - $totals['remaining'] > 0.5) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ مرحله از مانده فاکتور بیشتر است']; }
				if (in_array((string)$invoice->status, ['paid','approved','cancelled','payment_archived'], true)) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'این فاکتور در وضعیت قابل ثبت واریزی نیست']; }
				$stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $invoice_id, (int)$totals['stage_no']));
				if (! $stage) {
					if (! $this->sn_create_invoice_payment_stage($invoice_id, (int)$totals['stage_no'], (int)$totals['stage_no']===1?(string)$totals['plan']:'partial', $due, (int)($invoice->current_stage_issued_by_user_id ?? $invoice->seller_id ?? 0), 'ساخت مرحله سازگاری برای ثبت کارت‌به‌کارت')) {
						$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مرحله پرداخت قابل ایجاد نیست'];
					}
					$stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $invoice_id, (int)$totals['stage_no']));
				}
				if (! $stage || in_array((string)$stage->status, ['paid','approved'], true)) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'این مرحله قبلاً پرداخت یا تایید شده است']; }
				$is_replacement = in_array((string)$stage->status, ['pending_financial_approval','receipt_uploaded'], true);
				$data = ['status'=>'pending_financial_approval','invoice_status'=>'pending_financial_approval','payment_status'=>'pending_financial_approval','payment_workflow_status'=>'awaiting_financial_approval','pay_method'=>'card','payment_source'=>$source,'receipt_source'=>$source,'manual_amount'=>$amount+(float)$pending_summary['pending_amount'],'deposit_amount'=>$amount+(float)$pending_summary['pending_amount'],'updated_at'=>current_time('mysql')];
				if (in_array((string)$invoice->status, ['rejected','financial_rejected'], true)) {
					$data['financial_return_state']='resent_after_return';
					$data['resend_to_financial_at']=current_time('mysql');
					$data['rejected_reason']=null; $data['financial_reject_reason']=null;
					$data['rejected_at']=null; $data['financial_rejected_at']=null;
					$data['rejected_by']=null; $data['financial_rejected_by']=null;
				}
				if ((string)($invoice->status ?? '') === 'recontact_requested' || (string)($invoice->invoice_status ?? '') === 'recontact_requested') { $data['repeat_action_status']='payment_submitted_after_recontact'; }
				foreach (['manual_transfer_type','manual_account_last6','manual_tracking_last6','manual_account_owner','receipt_url','manual_card_from','manual_card_to','manual_card_to_number','manual_paid_at','manual_paid_at_jalali'] as $k) { if (array_key_exists($k,$extra)) { $data[$k]=$extra[$k]; } }
                $data['receipt_urls'] = $all_urls ? wp_json_encode($all_urls) : null;
                $data['receipt_url'] = $all_urls[0] ?? null;
                $data['receipt_file'] = $data['receipt_url'];
				if (array_key_exists('manual_card_from',$data)) { $data['deposit_card_from_last4']=$data['manual_card_from']; }
				if (array_key_exists('manual_card_to_number',$data)) {
					$raw_to_number = trim((string) ($data['manual_card_to_number'] ?? ''));
					if ($raw_to_number === '') {
						$data['manual_card_to_number'] = null;
					} else {
						$normalized_to = $this->sn_normalize_payment_card_number($raw_to_number);
						if ($normalized_to === '') { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'شماره کامل کارت مقصد معتبر نیست']; }
						$data['manual_card_to_number'] = $normalized_to;
						$normalized_to_digits = preg_replace('/\\D+/', '', $normalized_to);
						$data['manual_card_to'] = is_string($normalized_to_digits) ? substr($normalized_to_digits, -4) : '';
					}
				}
				if (array_key_exists('manual_card_to',$data)) { $data['deposit_card_to_last4']=$data['manual_card_to']; }
				if (array_key_exists('manual_paid_at_jalali',$data)) { $data['deposit_jalali_datetime']=$data['manual_paid_at_jalali']; }
				$stored_data = $this->sn_filter_existing_columns_fresh($invoice_table, $data);
                if (!empty($data['manual_transfer_type']) && $data['manual_transfer_type'] !== 'card') {
                    foreach (['manual_transfer_type','manual_account_last6','manual_tracking_last6','manual_account_owner'] as $required_field) {
                        if (!array_key_exists($required_field, $stored_data)) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ستون‌های اطلاعات حواله آماده نیست؛ مدیر سایت به‌روزرسانی دیتابیس افزونه را بررسی کند.']; }
                    }
                }
                if (array_key_exists('receipt_urls', $data) && !array_key_exists('receipt_urls', $stored_data)) {
                    $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ستون فیش‌های چندتایی آماده نیست؛ به‌روزرسانی دیتابیس افزونه را بررسی کنید'];
                }
                $ok = false !== $wpdb->update($invoice_table,$stored_data,['id'=>$invoice_id]);
				if (! $ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ذخیره اطلاعات واریزی انجام نشد: '.($wpdb->last_error ?: 'خطای دیتابیس')]; }
				$stage_data = ['status'=>'pending_financial_approval','pay_method'=>'card','payment_source'=>sanitize_key($source),'updated_at'=>current_time('mysql')];
                if (array_key_exists('receipt_urls', $data)) { $stage_data['receipt_urls'] = $data['receipt_urls']; }
                $stage_ok = false !== $wpdb->update($stage_table,$stage_data,['id'=>(int)$stage->id]);
				if (! $stage_ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'وضعیت مرحله پرداخت ذخیره نشد']; }
				$uploaded_type = strpos($source, 'supervisor_') === 0 ? 'supervisor'
					: (strpos($source, 'seller_') === 0 ? 'seller'
					: (strpos($source, 'converter_') === 0 ? 'converter' : 'customer'));
                $payment_data = ['invoice_id'=>$invoice_id,'payment_stage_no'=>(int)$totals['stage_no'],'amount'=>$amount,'status'=>'pending','pay_method'=>'card','payment_source'=>$source,'uploaded_by_type'=>$uploaded_type,'uploaded_by_user_id'=>get_current_user_id()?:null,'proof_data'=>wp_json_encode($proof),'submission_key'=>$key ?: null,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')];
                $payment_ok = (bool)$wpdb->insert($payments_table,$payment_data);
                $payment_id = (int)$wpdb->insert_id;
				if (! $payment_ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت رکورد پرداخت انجام نشد: '.($wpdb->last_error ?: 'خطای دیتابیس')]; }
				if (false === $wpdb->query('COMMIT')) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'ثبت نهایی فیش‌ها انجام نشد']; }
                SN_Helpers::commit_receipt_uploads(SN_Helpers::receipt_urls($extra));
				$activity_action = $uploaded_type === 'supervisor' ? 'supervisor_payment_submitted' : ($uploaded_type === 'seller' ? 'seller_payment_submitted' : ($uploaded_type === 'converter' ? 'converter_payment_submitted' : 'customer_payment_submitted'));
				$this->sn_log_activity($invoice_id,(int)$invoice->lead_id,$activity_action,(!empty($extra['receipt_url']) && $is_replacement ? 'ثبت تراکنش جدید برای' : 'ثبت تراکنش').' مرحله '.(int)$totals['stage_no'].' و ارسال به تایید مالی',['source'=>$source,'uploaded_by_type'=>$uploaded_type,'stage_no'=>(int)$totals['stage_no'],'stage_amount'=>$due,'transaction_amount'=>$amount,'payment_id'=>$payment_id,'old_value'=>(string)$invoice->status,'new_value'=>'pending_financial_approval','replacement'=>$is_replacement,'receipt_urls'=>SN_Helpers::receipt_urls($extra),'transfer_details'=>array_intersect_key($data,array_flip(['manual_transfer_type','manual_account_last6','manual_tracking_last6','manual_account_owner']))]);
				return ['success'=>true,'payment_id'=>$payment_id,'stage_no'=>(int)$totals['stage_no'],'amount'=>$amount,'available_amount'=>max(0,$due-(float)$pending_summary['pending_amount']-$amount)];
			}

			/**
			 * Keep the supervisor receipt UI and endpoint on the same status contract.
			 * All persisted status columns are inspected so a stale non-final column
			 * cannot reopen a fully paid/cancelled invoice.
			 */
			private function sn_supervisor_can_upload_receipt_for_status($invoice): bool
			{
				if (! $this->sn_card_to_card_enabled()) { return false; }
				$get = static function(string $key) use ($invoice): string {
					$value = is_array($invoice) ? ($invoice[$key] ?? '') : ($invoice->{$key} ?? '');
					return sanitize_key((string) $value);
				};
				$statuses = array_values(array_unique(array_filter([
					$get('payment_status'),
					$get('invoice_status'),
					$get('status'),
				])));
				$terminal = [
					'paid', 'approved', 'financial_approved', 'gateway_paid', 'online_paid',
					'completed', 'success', 'cancelled', 'canceled', 'payment_archived',
				];
				if (array_intersect($statuses, $terminal)) {
					return false;
				}
				$allowed = [
					'pre_invoice', 'pending', 'pending_payment', 'awaiting_payment', 'partial_paid',
					'rejected', 'financial_rejected', 'payment_rejected', 'recontact_requested',
					'receipt_uploaded', 'pending_financial_approval', 'needs_finance_review',
				];
				return (bool) array_intersect($statuses, $allowed);
			}

			private function sn_validate_jalali_payment_datetime(string $value): array
			{
				$value = trim(SN_Helpers::to_english_nums($value));
				if (! preg_match('/^(\d{4})\/(\d{2})\/(\d{2})\s+(\d{2}):(\d{2})$/', $value, $m)) {
					return ['success'=>false,'message'=>'فرمت تاریخ و ساعت واریز معتبر نیست'];
				}
				$jalali = sprintf('%04d/%02d/%02d',(int)$m[1],(int)$m[2],(int)$m[3]);
				$tehran_time = sprintf('%02d:%02d',(int)$m[4],(int)$m[5]);
				$parsed = SN_Helpers::normalize_jalali_tehran_datetime($jalali,$tehran_time,false,true);
				if (is_wp_error($parsed)) { return ['success'=>false,'message'=>$parsed->get_error_message()]; }
				if ((int)$parsed['timestamp'] > time() + (15 * MINUTE_IN_SECONDS)) { return ['success'=>false,'message'=>'زمان واریز نمی‌تواند مربوط به آینده باشد']; }
				return ['success'=>true,'jalali'=>$jalali . ' ' . $tehran_time,'mysql'=>(string)$parsed['mysql']];
			}

			public function ajax_submit_manual_payment(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				if (! $this->sn_card_to_card_enabled()) { SN_Helpers::send_json(false, 'پرداخت کارت‌به‌کارت غیرفعال است'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				$access = $this->sn_invoice_access_for_payment_action($code, 'manual_payment');
				if (empty($access['internal']) && empty($access['internal_denied']) && ! $this->sn_rate_limit_public_or_json('invoice_manual_payment', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				if (empty($access['success']) && empty($access['internal']) && empty($access['internal_denied'])) {
					$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'manual_payment');
				}
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice) { SN_Helpers::send_json(false, 'فاکتور یافت نشد'); return; }
				if (! empty($access['internal'])) {
					$payment_gate = ['allowed' => true, 'totals' => $this->sn_invoice_payment_totals($invoice)];
				} else {
					$payment_gate = $this->sn_invoice_customer_payment_gate($invoice, 'manual');
					if (empty($payment_gate['allowed'])) { SN_Helpers::send_json(false, (string) $payment_gate['message']); return; }
				}
				$entry_mode = sanitize_key(wp_unslash($_POST['entry_mode'] ?? 'info'));
                if (!in_array($entry_mode, ['info','receipt'], true)) { SN_Helpers::send_json(false, 'روش ثبت معتبر نیست'); return; }
                if ($entry_mode === 'receipt') {
                    if (!SN_Helpers::has_receipt_upload($_FILES['receipt'] ?? [])) { SN_Helpers::send_json(false, 'فایل فیش را انتخاب کنید'); return; }
                    $upload = SN_Helpers::upload_receipt($_FILES['receipt']);
                    if (empty($upload['success']) || empty($upload['url'])) { SN_Helpers::send_json(false, (string)($upload['message'] ?? 'آپلود فیش انجام نشد')); return; }
                    $source = !empty($access['internal']) ? $this->sn_internal_payment_source_for_current_user() : 'customer_upload';
                    $fields = array_fill_keys(['manual_transfer_type','manual_account_last6','manual_tracking_last6','manual_account_owner','manual_card_from','manual_card_to','manual_card_to_number','manual_paid_at','manual_paid_at_jalali'], null);
                    $fields['receipt_url'] = (string)$upload['url'];
                    $fields['receipt_urls'] = $upload['urls'];
                    $save = $this->sn_save_invoice_manual_payment((int)$invoice->id, $source, $fields);
                    SN_Helpers::send_json(!empty($save['success']), !empty($save['success']) ? 'فیش برای بررسی مالی ثبت شد.' : (string)($save['message'] ?? 'ذخیره فیش انجام نشد'));
                    return;
                }
                $transfer_type = sanitize_key(wp_unslash($_POST['manual_transfer_type'] ?? 'card'));
                if (!in_array($transfer_type, ['card','paya','pol','account'], true)) { SN_Helpers::send_json(false, 'روش واریز معتبر نیست'); return; }
                $bank_fields = ['manual_transfer_type'=>$transfer_type,'manual_account_last6'=>null,'manual_tracking_last6'=>null,'manual_account_owner'=>null];
                if ($transfer_type !== 'card') {
                    $owner = sanitize_text_field(wp_unslash($_POST['manual_account_owner'] ?? ''));
                    if (!preg_match('/^.{1,191}$/us', $owner)) { SN_Helpers::send_json(false, 'نام صاحب حساب مبدأ را وارد کنید (حداکثر ۱۹۱ کاراکتر)'); return; }
                    $bank_fields['manual_account_owner'] = $owner;
                    foreach (['manual_account_last6','manual_tracking_last6'] as $key) {
                        $value = trim(SN_Helpers::to_english_nums(sanitize_text_field(wp_unslash($_POST[$key] ?? ''))));
                        if ($value !== '' && !preg_match('/^[0-9]{6}$/', $value)) { SN_Helpers::send_json(false, 'حساب و پیگیری، در صورت ورود، باید دقیقاً ۶ رقم باشند'); return; }
                        $bank_fields[$key] = $value === '' ? null : $value;
                    }
                }
                $from = preg_replace('/\D+/', '', SN_Helpers::to_english_nums(sanitize_text_field(wp_unslash($_POST['card_from'] ?? ''))));
				$invoice_card = $this->sn_resolve_invoice_card($invoice);
				$submitted_to = ! empty($access['internal']) ? sanitize_text_field(wp_unslash($_POST['card_to'] ?? '')) : (string) ($invoice_card['number'] ?? '');
				$destination = $this->sn_manual_destination_card_input($submitted_to, $invoice, ! empty($access['internal']));
				$to_number = (string) ($destination['number'] ?? '');
				$to = (string) ($destination['last4'] ?? '');
				$amount = $this->sn_parse_money_value(is_scalar($_POST['amount'] ?? '') ? wp_unslash((string)$_POST['amount']) : '');
				$submitted_amount = $this->sn_parse_money_value(is_scalar($_POST['amount'] ?? '') ? wp_unslash((string)$_POST['amount']) : '');
				if ($submitted_amount <= 0) { SN_Helpers::send_json(false, 'مبلغ این تراکنش را وارد کنید'); return; }
				$paid_at = sanitize_text_field(wp_unslash($_POST['paid_at'] ?? ''));
				$jy = sanitize_text_field(wp_unslash($_POST['paid_jy'] ?? ''));
				$jm = sanitize_text_field(wp_unslash($_POST['paid_jm'] ?? ''));
				$jd = sanitize_text_field(wp_unslash($_POST['paid_jd'] ?? ''));
				$hh = sanitize_text_field(wp_unslash($_POST['paid_hh'] ?? ''));
				$mi = sanitize_text_field(wp_unslash($_POST['paid_mi'] ?? ''));
				if ($jy !== '' && $jm !== '' && $jd !== '' && $hh !== '' && $mi !== '') {
					$paid_at = sprintf('%04d/%02d/%02d %02d:%02d', (int) $jy, (int) $jm, (int) $jd, (int) $hh, (int) $mi);
				}
				if ($paid_at === '') {
					SN_Helpers::send_json(false, 'تاریخ و ساعت واریز را انتخاب کنید');
					return;
				}
				$date_check = $this->sn_validate_jalali_payment_datetime($paid_at);
				if (empty($date_check['success'])) {
					SN_Helpers::send_json(false, (string)($date_check['message'] ?? 'تاریخ و ساعت واریز معتبر نیست'));
					return;
				}
				$paid_at = (string)$date_check['jalali'];
				if ($transfer_type === 'card' && ! preg_match('/^\d{4}$/', $from)) {
					SN_Helpers::send_json(false, '۴ رقم کارت مبدا باید عددی باشد');
					return;
				}
				if (empty($destination['valid']) || (! empty($access['internal']) && $to !== '' && ! preg_match('/^\d{4}$/', $to)) || (empty($access['internal']) && ! preg_match('/^\d{4}$/', $to))) {
					SN_Helpers::send_json(false, ! empty($access['internal']) ? '۴ رقم آخر کارت مقصد اختیاری است؛ در صورت ورود باید ۴ رقم باشد' : 'شماره کارت مقصد در تنظیمات پلاگین معتبر نیست');
					return;
				}
				if ($amount <= 0) {
					SN_Helpers::send_json(false, 'مبلغ فاکتور برای ثبت اطلاعات واریزی معتبر نیست');
					return;
				}
				$dt = (string)$date_check['mysql'];
				$source = ! empty($access['internal']) ? $this->sn_internal_payment_source_for_current_user() : 'customer_upload';
				$fields = $bank_fields + ['manual_card_from' => $transfer_type === 'card' ? $from : null, 'manual_card_to' => $to, 'manual_card_to_number' => $to_number !== '' ? $to_number : null, 'manual_amount' => (float) $amount, 'manual_paid_at' => $dt, 'manual_paid_at_jalali' => $paid_at];
                if (isset($_POST['entry_mode']) && $entry_mode === 'info') { $fields['receipt_url'] = null; }
				if (SN_Helpers::has_receipt_upload($_FILES['receipt'] ?? [])) {
					$upload = SN_Helpers::upload_receipt($_FILES['receipt']); // phpcs:ignore
					if (empty($upload['success']) || empty($upload['url'])) { SN_Helpers::send_json(false, (string)($upload['message'] ?? 'بارگذاری فیش انجام نشد')); return; }
					$fields['receipt_url'] = (string)$upload['url'];
                    $fields['receipt_urls'] = $upload['urls'];
				}
				$save = $this->sn_save_invoice_manual_payment((int) $invoice->id, $source, $fields);
				if (empty($save['success'])) {
					SN_Helpers::send_json(false, (string)($save['message'] ?? 'ذخیره اطلاعات واریزی در دیتابیس انجام نشد'));
					return;
				}
				SN_Helpers::send_json(true, 'اطلاعات واریز و فیش انتخاب‌شده برای بررسی مالی ثبت شد', ['status' => 'pending_financial_approval', 'status_label' => 'نیاز به بررسی اطلاعات واریزی']);
			}

			public function ajax_supervisor_upload_receipt(): void
			{
				if (! is_user_logged_in()) {
					SN_Helpers::send_json(false, 'وارد نشده‌اید');
					return;
				}
				if (! $this->sn_card_to_card_enabled()) { SN_Helpers::send_json(false, 'پرداخت کارت‌به‌کارت غیرفعال است'); return; }
				$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
				if (! $valid) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				$user = wp_get_current_user();
				$position = $this->sn_fast_hr_position_for_user((int) $user->ID);
				$is_seller_only = ($position === 'seller' || in_array('sn_seller', (array) $user->roles, true))
					&& ! in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true)
					&& ! array_intersect((array) $user->roles, ['sn_supervisor', 'sn_senior_supervisor', 'sn_sales_manager']);
				$is_converter = $position === 'converter' || in_array('sn_converter', (array) $user->roles, true);
				$can_upload_for_scope = ! $is_seller_only && (current_user_can('manage_options')
					|| in_array('sn_supervisor', (array) $user->roles, true)
					|| in_array('sn_senior_supervisor', (array) $user->roles, true)
					|| in_array('sn_sales_manager', (array) $user->roles, true)
					|| in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true)
					|| $is_converter);
				if (! $can_upload_for_scope) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$invoice_id = absint($_POST['invoice_id'] ?? 0);
				if (! $invoice_id) {
					SN_Helpers::send_json(false, 'شناسه فاکتور نامعتبر است');
					return;
				}
				global $wpdb;
				$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
				if (! $invoice) {
					SN_Helpers::send_json(false, 'فاکتور یافت نشد');
					return;
				}
				$can_access_invoice = current_user_can('manage_options');
				if (! $can_access_invoice && $is_converter) {
					$can_access_invoice = $this->sn_converter_can_access_invoice($invoice, (int) $user->ID);
				} elseif (! $can_access_invoice && class_exists('SN_Scope_Service') && in_array($position, ['supervisor', 'senior_supervisor', 'sales_manager'], true)) {
					$can_access_invoice = (new SN_Scope_Service())->can_view_invoice((int) $user->ID, $invoice_id);
					if (! $can_access_invoice) {
						$can_access_invoice = $this->sn_supervisor_can_access_invoice($invoice_id, (int) $user->ID);
					}
				} elseif (! $can_access_invoice) {
					$can_access_invoice = $this->sn_supervisor_can_access_invoice($invoice_id, (int) $user->ID);
				}
				if (! $can_access_invoice) {
					SN_Helpers::send_json(false, 'این فاکتور در محدوده دسترسی شما نیست');
					return;
				}
				if (! $this->sn_supervisor_can_upload_receipt_for_status($invoice)) {
					SN_Helpers::send_json(false, 'این فاکتور در وضعیت قابل ثبت فیش توسط سرپرست نیست');
					return;
				}
				$destination = $this->sn_manual_destination_card_input(sanitize_text_field(wp_unslash($_POST['card_to'] ?? '')), $invoice, true);
				if (empty($destination['valid'])) {
					SN_Helpers::send_json(false, '۴ رقم آخر کارت مقصد اختیاری است؛ در صورت ورود باید ۴ رقم باشد');
					return;
				}
				$manual_to_number = (string) ($destination['number'] ?? '');
				$manual_to_last4 = (string) ($destination['last4'] ?? '');
				if (empty($_FILES['receipt'])) {
					SN_Helpers::send_json(false, 'فایل فیش انتخاب نشده');
					return;
				}
				$upload = SN_Helpers::upload_receipt($_FILES['receipt']); // phpcs:ignore
				if (empty($upload['success']) || empty($upload['url'])) {
					SN_Helpers::send_json(false, (string) ($upload['message'] ?? 'خطا در آپلود فیش'));
					return;
				}
				$url = (string) $upload['url'];
				$source = $is_converter ? 'converter_upload' : 'supervisor_upload';
				$save = $this->sn_save_invoice_manual_payment($invoice_id, $source, [
					'receipt_url' => $url,
                    'receipt_urls' => $upload['urls'],
					'manual_card_to' => $manual_to_last4,
					'manual_card_to_number' => $manual_to_number !== '' ? $manual_to_number : null,
				]);
				if (empty($save['success'])) {
					SN_Helpers::send_json(false, (string)($save['message'] ?? 'ذخیره فیش در دیتابیس انجام نشد'));
					return;
				}
				SN_Helpers::send_json(true, 'فیش ثبت شد و برای بررسی مالی ارسال شد', ['status' => 'pending_financial_approval', 'status_label' => SN_Helpers::status_label('pending_financial_approval')]);
			}

			/** Reconcile a newly submitted payment after recontact/rejection before Finance acts. */
			private function sn_finance_reconcile_review_stage(int $invoice_id, $invoice, $stage, int $stage_no): array
			{
				if ($invoice_id < 1 || ! $invoice || ! $stage) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				$stage_status=sanitize_key((string)($stage->status ?? ''));
				if (in_array($stage_status,['pending_financial_approval','receipt_uploaded'],true)) { return ['ready'=>true,'reconciled'=>false,'stage'=>$stage]; }
				if (in_array($stage_status,['paid','approved','cancelled'],true)) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				global $wpdb;
				$payments_table=$wpdb->prefix.'sn_payments';
				if (! $this->sn_table_exists_quiet($payments_table)) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				$pending_payment=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$payments_table} WHERE invoice_id=%d AND payment_stage_no=%d AND status IN ('pending','verified') ORDER BY id DESC LIMIT 1",$invoice_id,$stage_no));
				if (! $pending_payment) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				$invoice_table=$wpdb->prefix.'sn_invoices'; $stage_table=$wpdb->prefix.'sn_invoice_payment_stages'; $now=current_time('mysql');
				$invoice_update=$this->sn_filter_existing_columns($invoice_table,['status'=>'pending_financial_approval','invoice_status'=>'pending_financial_approval','payment_status'=>'pending_financial_approval','payment_workflow_status'=>'awaiting_financial_approval','updated_at'=>$now]);
				if (false===$wpdb->update($invoice_table,$invoice_update,['id'=>$invoice_id])) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				$stage_update=['status'=>'pending_financial_approval','pay_method'=>(string)(($pending_payment->pay_method ?? '') ?: ($stage->pay_method ?? 'card')),'payment_source'=>(string)(($pending_payment->payment_source ?? '') ?: ($stage->payment_source ?? 'customer_upload')),'updated_at'=>$now];
				if (false===$wpdb->update($stage_table,$stage_update,['id'=>(int)$stage->id])) { return ['ready'=>false,'reconciled'=>false,'stage'=>$stage]; }
				$fresh=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE id=%d",(int)$stage->id));
				$this->sn_log_activity($invoice_id,(int)($invoice->lead_id ?? 0),'finance_stage_reconciled','هماهنگ‌سازی وضعیت مرحله پرداخت برای بررسی مالی',['old_stage_status'=>$stage_status,'new_stage_status'=>'pending_financial_approval','payment_id'=>(int)($pending_payment->id ?? 0),'previous_invoice_status'=>(string)($invoice->status ?? '')]);
				return ['ready'=>true,'reconciled'=>true,'stage'=>$fresh ?: $stage];
			}

			private function sn_financial_approve_invoice_internal(int $id, array $input = []): array
			{
				if ($id < 1) { return ['success'=>false,'message'=>'شناسه فاکتور نامعتبر است']; }
				global $wpdb;
				$inv=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d",$id));
				if (! $inv) { return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
				$totals=$this->sn_invoice_payment_totals($inv);
				$stage_no=(int)$totals['stage_no'];
				$stage=$this->sn_current_invoice_payment_stage($id,$stage_no);
				if ($totals['workflow_status']==='completed' && $totals['remaining']<=0) {
					return ['success'=>true,'message'=>'پرداخت قبلاً به طور کامل تایید شده است','data'=>['status'=>(string)$inv->status,'status_label'=>SN_Helpers::status_label((string)$inv->status),'completed'=>true,'remaining_amount'=>0]];
				}
				$reconcile=$this->sn_finance_reconcile_review_stage($id,$inv,$stage,$stage_no);
				if (!empty($reconcile['ready']) && !empty($reconcile['stage'])) { $stage=$reconcile['stage']; }
				if (! $stage || ! in_array((string)$stage->status,['pending_financial_approval','receipt_uploaded'],true)) {
					return ['success'=>false,'message'=>'مرحله فعال در صف تایید مالی نیست یا اطلاعات واریزی جدیدی برای بررسی ثبت نشده است'];
				}
				if (! in_array((string)($inv->payment_status ?? ''),['pending_financial_approval','receipt_uploaded'],true) || ! in_array((string)($inv->status ?? ''),['pending_financial_approval','receipt_uploaded'],true)) {
					$sync=$this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices',['status'=>'pending_financial_approval','invoice_status'=>'pending_financial_approval','payment_status'=>'pending_financial_approval','payment_workflow_status'=>'awaiting_financial_approval','updated_at'=>current_time('mysql')]);
					$wpdb->update($wpdb->prefix.'sn_invoices',$sync,['id'=>$id]);
				}
				$finance_edit_note=sanitize_textarea_field((string)($input['finance_edit_note'] ?? ''));
				$editable=[];
				foreach (['customer_name','customer_phone','manual_card_from','manual_card_to','manual_paid_at_jalali'] as $field) {
					if (isset($input[$field]) && trim((string)$input[$field])!=='') { $editable[$field]=sanitize_text_field((string)$input[$field]); }
				}
				$editable['manual_amount']=(float)$totals['due'];
				$editable['deposit_amount']=(float)$totals['due'];
				$editable['finance_edit_note']=$finance_edit_note;
				$approved_pay_method = ($stage && (string)($stage->pay_method ?? '') === 'online') || (string)($inv->pay_method ?? '') === 'online' ? 'online' : 'card';
				$result=$this->sn_finalize_current_payment_stage($id,$approved_pay_method,(string)(($inv->payment_source ?? '') ?: 'finance_approval'),(string)($stage->payment_ref_id ?? ''),(int)get_current_user_id(),'approved');
				if (empty($result['success'])) { return ['success'=>false,'message'=>(string)($result['message'] ?? 'تایید مرحله پرداخت انجام نشد')]; }
				if ($editable) { $wpdb->update($wpdb->prefix.'sn_invoices',$this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices',$editable),['id'=>$id]); }
				$reviewer=wp_get_current_user();
				$message=!empty($result['completed'])?'پرداخت کامل فاکتور توسط مالی تایید شد':'پیش‌پرداخت تایید شد و برای تکمیل واریزی به فروشنده اصلی ارجاع شد';
				return ['success'=>true,'message'=>$message,'data'=>[
					'status'=>(string)($result['status'] ?? 'partial_paid'),
					'status_label'=>SN_Helpers::status_label((string)($result['status'] ?? 'partial_paid')),
					'completed'=>!empty($result['completed']),
					'paid_total'=>(float)($result['paid'] ?? 0),
					'remaining_amount'=>(float)($result['remaining'] ?? 0),
					'finance_review_tag'=>'تایید شده توسط مالی',
					'reviewed_by'=>get_current_user_id(),
					'reviewed_by_name'=>(string)($reviewer->display_name ?: $reviewer->user_login),
					'reviewed_at'=>current_time('mysql'),
				]];
			}

			public function ajax_financial_approve_payment(): void
			{
				if (! $this->sn_can_approve_payment()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
				$valid=check_ajax_referer('sn_admin','nonce',false)||check_ajax_referer('sn_public','nonce',false);
				if (! $valid) { SN_Helpers::send_json(false,'نانس نامعتبر'); return; }
				$id=absint($_POST['invoice_id'] ?? 0);
				$input=[];
				foreach (['finance_edit_note','customer_name','customer_phone','manual_card_from','manual_card_to','manual_paid_at_jalali'] as $field) {
					if (isset($_POST[$field])) { $input[$field]=wp_unslash($_POST[$field]); }
				}
				$out=$this->sn_financial_approve_invoice_internal($id,$input);
				if (empty($out['success'])) { SN_Helpers::send_json(false,(string)($out['message'] ?? 'تایید انجام نشد')); return; }
				SN_Helpers::send_json(true,(string)$out['message'],(array)($out['data'] ?? []));
			}

			public function ajax_financial_bulk_approve(): void
			{
				if (! $this->sn_can_approve_payment()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
				$valid=check_ajax_referer('sn_admin','nonce',false)||check_ajax_referer('sn_public','nonce',false);
				if (! $valid) { SN_Helpers::send_json(false,'نانس نامعتبر'); return; }
				$raw=$_POST['invoice_ids'] ?? [];
				if (is_string($raw)) { $decoded=json_decode(wp_unslash($raw),true); if (is_array($decoded)) { $raw=$decoded; } }
				$ids=array_values(array_unique(array_filter(array_map('absint',(array)$raw))));
				if (! $ids) { SN_Helpers::send_json(false,'هیچ فاکتوری انتخاب نشده است'); return; }
				if (count($ids)>100) { $ids=array_slice($ids,0,100); }
				$approved=[]; $failed=[];
				foreach ($ids as $id) {
					$out=$this->sn_financial_approve_invoice_internal((int)$id,[]);
					if (!empty($out['success'])) { $approved[]=(int)$id; }
					else { $failed[]=['id'=>(int)$id,'message'=>(string)($out['message'] ?? 'خطا')]; }
				}
				$msg=sprintf('%s فاکتور تایید شد%s.', number_format_i18n(count($approved)), $failed ? ' و '.number_format_i18n(count($failed)).' مورد انجام نشد' : '');
				SN_Helpers::send_json((bool)$approved,$msg,['approved_ids'=>$approved,'failed'=>$failed,'approved_count'=>count($approved),'failed_count'=>count($failed)]);
			}

			public function ajax_financial_reject_payment(): void
			{
				if (! $this->sn_can_reject_payment()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$valid = check_ajax_referer('sn_admin', 'nonce', false) || check_ajax_referer('sn_public', 'nonce', false);
				if (! $valid) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$id = absint($_POST['invoice_id'] ?? 0);
				$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				if (! $id || $reason === '') { SN_Helpers::send_json(false, 'شناسه یا دلیل رد نامعتبر است'); return; }
				$this->sn_ensure_payment_migrations();
				global $wpdb;
				$invoice_table=$wpdb->prefix.'sn_invoices'; $stage_table=$wpdb->prefix.'sn_invoice_payment_stages'; $payments_table=$wpdb->prefix.'sn_payments';
				$wpdb->query('START TRANSACTION');
				$inv=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE",$id));
				if (! $inv) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'فاکتور یافت نشد'); return; }
				$totals=$this->sn_invoice_payment_totals($inv);
				if ($totals['remaining']<=0 || $totals['workflow_status']==='completed') { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'فاکتور تسویه‌شده قابل رد نیست'); return; }
				$stage_no=(int)$totals['stage_no'];
				$stage=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE",$id,$stage_no));
				$reconcile=$this->sn_finance_reconcile_review_stage($id,$inv,$stage,$stage_no);
				if (!empty($reconcile['ready']) && !empty($reconcile['stage'])) { $stage=$reconcile['stage']; }
				if (! $stage || ! in_array((string)$stage->status,['pending_financial_approval','receipt_uploaded'],true)) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'این مرحله در صف تایید مالی نیست یا اطلاعات واریزی جدیدی برای بررسی ثبت نشده است'); return; }
				$data=$this->sn_filter_existing_columns($invoice_table,[
					'status'=>'rejected','invoice_status'=>'rejected','payment_status'=>'rejected','rejected_by'=>get_current_user_id(),'rejected_at'=>current_time('mysql'),'rejected_reason'=>$reason,
					'financial_reviewed_by'=>get_current_user_id(),'financial_reviewed_at'=>current_time('mysql'),'financial_reject_reason'=>$reason,'financial_rejected_at'=>current_time('mysql'),'financial_rejected_by'=>get_current_user_id(),
					'financial_return_state'=>'returned_to_seller','returned_to_seller_at'=>current_time('mysql'),'updated_at'=>current_time('mysql'),
				]);
				if (false===$wpdb->update($invoice_table,$data,['id'=>$id])) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'ثبت رد مالی انجام نشد'); return; }
				if (false===$wpdb->update($stage_table,['status'=>'rejected','updated_at'=>current_time('mysql')],['id'=>(int)$stage->id])) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'وضعیت مرحله پرداخت ذخیره نشد'); return; }
				$payment_update=$this->sn_filter_existing_columns($payments_table,['status'=>'rejected','pay_method'=>'card','updated_at'=>current_time('mysql')]);
				if ($payment_update) {
					$set=[]; $args=[]; foreach($payment_update as $col=>$value){$set[]="`{$col}`=%s";$args[]=$value;} $args[]=$id; $args[]=(int)$totals['stage_no'];
					$wpdb->query($wpdb->prepare("UPDATE {$payments_table} SET ".implode(', ',$set)." WHERE invoice_id=%d AND payment_stage_no=%d AND status='pending' AND (authority IS NULL OR authority='')",...$args));
				}
				$wpdb->query('COMMIT');
				if (! empty($inv->wc_order_id) && function_exists('wc_get_order')) {
					$reopen_order = wc_get_order((int)$inv->wc_order_id);
					if ($reopen_order && (string)$reopen_order->get_meta('_sn_finance_reopened', true) === '1') {
						$reopen_order->update_status('cancelled', 'رد مالی پس از بازگشت فاکتور به بررسی: ' . $reason);
						$reopen_order->delete_meta_data('_sn_finance_reopened');
						$reopen_order->save();
					}
				}
				$this->sn_log_activity($id,(int)$inv->lead_id,'payment_rejected','پرداخت توسط واحد مالی رد شد',['reason'=>$reason,'rejected_by'=>get_current_user_id(),'old_value'=>(string)$inv->status,'new_value'=>'rejected','stage_no'=>(int)$totals['stage_no']]);
				do_action('sn_invoice_financial_rejected', $id, $inv, $reason);
				$reviewer=wp_get_current_user(); $reviewed_at=current_time('mysql');
				SN_Helpers::send_json(true,'پرداخت رد شد',['status'=>'rejected','status_label'=>SN_Helpers::status_label('rejected'),'reviewed_by'=>get_current_user_id(),'reviewed_by_name'=>(string)($reviewer->display_name ?: $reviewer->user_login),'reviewed_at'=>$reviewed_at,'rejected_reason'=>$reason,'financial_reject_reason'=>$reason,'financial_rejected_by'=>get_current_user_id(),'financial_rejected_by_name'=>(string)($reviewer->display_name ?: $reviewer->user_login),'financial_rejected_at'=>$reviewed_at]);
			}



			private function sn_financial_reopen_invoice_internal(int $id, string $reason = ''): array
			{
				$id = absint($id);
				$reason = sanitize_textarea_field($reason);
				if ($id < 1) { return ['success'=>false,'message'=>'شناسه فاکتور نامعتبر است']; }
				if ($reason === '') { return ['success'=>false,'message'=>'دلیل بازگشت به بررسی الزامی است']; }
				$this->sn_ensure_payment_migrations();
				global $wpdb;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
				$payments_table = $wpdb->prefix . 'sn_payments';

				if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(), 'financial_reopen_guard')) {
					$guard = (array) SN_Dot_Flow::instance()->financial_reopen_guard($id);
					if (isset($guard['allowed']) && ! $guard['allowed']) {
						return ['success'=>false,'message'=>(string)($guard['message'] ?? 'این فاکتور در وضعیت قابل بازگشت مستقیم نیست')];
					}
				}

				$wpdb->query('START TRANSACTION');
				$inv = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $id));
				if (! $inv) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'فاکتور یافت نشد']; }
				$status_blob = sanitize_key((string)($inv->status ?? '')) . ' ' . sanitize_key((string)($inv->payment_status ?? '')) . ' ' . sanitize_key((string)($inv->invoice_status ?? ''));
				if (strpos($status_blob, 'approved') === false) {
					$wpdb->query('ROLLBACK');
					return ['success'=>false,'message'=>'فقط فاکتور تاییدشده مالی قابل بازگشت به بررسی است'];
				}
				$stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND status='approved' ORDER BY stage_no DESC,id DESC LIMIT 1 FOR UPDATE", $id));
				if (! $stage) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مرحله تاییدشده مالی برای این فاکتور یافت نشد']; }
				$later_stage = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$stage_table} WHERE invoice_id=%d AND stage_no>%d", $id, (int)$stage->stage_no));
				if ($later_stage > 0) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'بعد از این مرحله، مرحله جدیدتری ساخته شده است و بازگشت مستقیم امن نیست']; }

				// Do not invalidate a downstream referral that has already materialized as a live lead.
				if ($this->sn_distribution_tables_ready()) {
					$live_ref = (int) $wpdb->get_var($wpdb->prepare(
						"SELECT COUNT(*) FROM {$wpdb->prefix}sn_distribution_items WHERE source_type='paid_invoice_referral' AND source_id=%d AND COALESCE(workflow_kind,'')<>'invoice_payment_completion' AND COALESCE(live_lead_id,0)>0",
						$id
					));
					if ($live_ref > 0) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'از این فاکتور قبلاً پرونده/ارجاع عملیاتی جدید ساخته شده است؛ برای جلوگیری از حذف اثر عملیاتی، بازگشت مستقیم مسدود است و باید از لغو/عودت استفاده شود']; }
				}

				$total = max(0, (float)(($inv->payment_total_amount ?? 0) ?: (($inv->final_total ?? 0) ?: ($inv->product_price ?? 0))));
				$stage_amount = max(0, (float)($stage->requested_amount ?? 0));
				if ($total <= 0.5 || $stage_amount <= 0.5) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'مبلغ مرحله یا مبلغ کل فاکتور معتبر نیست']; }
				$prior_paid = (float) $wpdb->get_var($wpdb->prepare(
					"SELECT COALESCE(SUM(requested_amount),0) FROM {$stage_table} WHERE invoice_id=%d AND id<>%d AND status IN ('paid','approved')",
					$id, (int)$stage->id
				));
				$prior_paid = min($total, max(0, $prior_paid));
				$new_remaining = max(0, $total - $prior_paid);
				$now = current_time('mysql');

				$stage_update = [
					'status'=>'pending_financial_approval',
					'approved_by_user_id'=>null,
					'approved_at'=>null,
					'paid_at'=>null,
					'updated_at'=>$now,
				];
				if (false === $wpdb->update($stage_table, $stage_update, ['id'=>(int)$stage->id])) {
					$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'برگرداندن مرحله پرداخت انجام نشد'];
				}

				$invoice_update = $this->sn_filter_existing_columns($invoice_table, [
					'status'=>'pending_financial_approval','invoice_status'=>'pending_financial_approval','payment_status'=>'pending_financial_approval',
					'payment_workflow_status'=>'awaiting_financial_approval','payment_total_amount'=>$total,'paid_total_amount'=>$prior_paid,
					'remaining_amount'=>$new_remaining,'current_due_amount'=>$stage_amount,'current_payment_stage'=>(int)$stage->stage_no,
					'approved_by'=>null,'approved_at'=>null,'financial_reviewed_by'=>null,'financial_reviewed_at'=>null,
					'payment_completed_at'=>null,'paid_at'=>null,'updated_at'=>$now,
				]);
				if (false === $wpdb->update($invoice_table, $invoice_update, ['id'=>$id])) {
					$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'وضعیت فاکتور به صف بررسی برنگشت'];
				}

				if ($this->sn_table_exists_quiet($payments_table)) {
					$back_status = sanitize_key((string)($stage->pay_method ?? $inv->pay_method ?? '')) === 'online' ? 'verified' : 'pending';
					$payment_update = $this->sn_filter_existing_columns($payments_table, ['status'=>$back_status,'updated_at'=>$now]);
					if ($payment_update) {
						$set=[]; $args=[];
						foreach ($payment_update as $col=>$value) { $set[]="`{$col}`=%s"; $args[]=$value; }
						$args[]=$id; $args[]=(int)$stage->stage_no;
						$sql="UPDATE {$payments_table} SET ".implode(', ',$set)." WHERE invoice_id=%d AND payment_stage_no=%d AND status IN ('paid','approved')";
						if (false === $wpdb->query($wpdb->prepare($sql, ...$args))) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'وضعیت تراکنش پرداخت به بررسی برنگشت']; }
					}
				}

				// Hide payment-completion action while Finance is reviewing the reverted stage.
				if ($this->sn_distribution_tables_ready()) {
					$dist_table = $wpdb->prefix . 'sn_distribution_items';
					$wpdb->query($wpdb->prepare(
						"UPDATE {$dist_table} SET status='awaiting_financial_review',seller_notes=%s,updated_at=%s WHERE source_type='paid_invoice_referral' AND source_id=%d AND workflow_kind='invoice_payment_completion'",
						'مرحله نهایی توسط مالی به حالت بررسی مجدد برگشت: ' . $reason, $now, $id
					));
					$wpdb->query($wpdb->prepare(
						"UPDATE {$dist_table} SET source_type='paid_invoice_referral_reopened',status='financial_reopened',seller_notes=CONCAT(COALESCE(seller_notes,''),%s),updated_at=%s WHERE source_type='paid_invoice_referral' AND source_id=%d AND COALESCE(workflow_kind,'')<>'invoice_payment_completion' AND COALESCE(live_lead_id,0)=0",
						"\nبازگشت تایید مالی: " . $reason, $now, $id
					));
				}

				// Compensate auto-posted commissions while preserving an auditable transaction trail.
				$wallet_table = $wpdb->prefix . 'sn_wallet_transactions';
				if ($this->sn_wallet_table_exists($wallet_table)) {
					$credits = $wpdb->get_results($wpdb->prepare(
						"SELECT * FROM {$wallet_table} WHERE invoice_id=%d AND direction='credit' AND status='approved' AND type IN ('commission_engine','seller_commission','supervisor_commission') FOR UPDATE",
						$id
					), ARRAY_A) ?: [];
					foreach ($credits as $credit) {
						$uid=(int)($credit['user_id'] ?? 0); $amount=(float)($credit['amount'] ?? 0); $wallet_type=(string)($credit['wallet_type'] ?? 'seller');
						if ($uid>0 && $amount>0) {
							$ok=$this->sn_add_wallet_transaction($uid,$wallet_type,$amount,'debit','finance_reopen_reversal','برگشت موقت پورسانت به دلیل بازگشت فاکتور به بررسی مالی',$id,!empty($inv->lead_id)?(int)$inv->lead_id:null,['reopened_credit_transaction_id'=>(int)$credit['id'],'reason'=>$reason]);
							if (! $ok) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'برگشت پورسانت ثبت‌شده انجام نشد؛ عملیات برای جلوگیری از اختلاف کیف پول متوقف شد']; }
							$new_type=(string)$credit['type']==='supervisor_commission'?'supervisor_commission_reopened':((string)$credit['type']==='seller_commission'?'seller_commission_reopened':'commission_engine_reopened');
							$credit_archive = ['type'=>$new_type];
							if (in_array('idempotency_key', $this->sn_table_columns($wallet_table), true)) { $credit_archive['idempotency_key'] = null; }
							if (false===$wpdb->update($wallet_table,$credit_archive,['id'=>(int)$credit['id']])) { $wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>'آرشیو تراکنش پورسانت انجام نشد']; }
						}
					}
				}

				if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(), 'financial_reopen_apply_in_transaction')) {
					$dot_result=(array) SN_Dot_Flow::instance()->financial_reopen_apply_in_transaction($id, $reason);
					if (isset($dot_result['success']) && ! $dot_result['success']) {
						$wpdb->query('ROLLBACK'); return ['success'=>false,'message'=>(string)($dot_result['message'] ?? 'هماهنگ‌سازی پرونده دات انجام نشد')];
					}
				}

				$wpdb->query('COMMIT');
				do_action('sn_invoice_financial_reopened', $id, $inv, $reason);

				// Downstream WordPress/WooCommerce effects are put on hold rather than deleted.
				$wc_order_id=(int)($inv->wc_order_id ?? 0);
				if ($wc_order_id>0 && function_exists('wc_get_order')) {
					$order=wc_get_order($wc_order_id);
					if ($order) {
						$order->update_meta_data('_sn_finance_reopened','1');
						$order->update_meta_data('_sn_finance_reopen_reason',$reason);
						$order->add_order_note('تایید مالی فاکتور شبکه فروش به حالت بررسی مجدد برگشت. علت: '.$reason);
						if (! in_array($order->get_status(), ['cancelled','refunded'], true)) { $order->update_status('on-hold','بازگشت فاکتور به بررسی مالی'); }
						$order->save();
					}
				}

				$customer_id=(int)($inv->customer_wp_id ?? 0);
				if ($customer_id>0) {
					$owned=get_user_meta($customer_id,'sn_owned_products',true); $owned=is_array($owned)?array_map('intval',$owned):[];
					$product_ids=$this->sn_invoice_product_ids($inv);
					foreach ($product_ids as $pid) {
						$other=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$invoice_table} WHERE id<>%d AND customer_wp_id=%d AND product_id=%d AND status IN ('paid','approved')",$id,$customer_id,$pid));
						if ($other<1) { $owned=array_values(array_diff($owned,[(int)$pid])); }
					}
					update_user_meta($customer_id,'sn_owned_products',array_values(array_unique($owned)));
				}

				$this->sn_log_activity($id,(int)($inv->lead_id ?? 0),'financial_approval_reopened','تایید مالی به حالت در انتظار بررسی برگشت',[
					'reason'=>$reason,'actor_user_id'=>get_current_user_id(),'stage_no'=>(int)$stage->stage_no,'stage_amount'=>$stage_amount,
					'prior_paid'=>$prior_paid,'remaining_amount'=>$new_remaining,'old_status'=>(string)($inv->status ?? ''),'new_status'=>'pending_financial_approval'
				]);
				return ['success'=>true,'message'=>'فاکتور به «در انتظار بررسی» برگشت. تایید قبلی از مرحله جاری برداشته شد.','data'=>[
					'status'=>'pending_financial_approval','status_label'=>SN_Helpers::status_label('pending_financial_approval'),'stage_no'=>(int)$stage->stage_no,
					'paid_total'=>$prior_paid,'remaining_amount'=>$new_remaining,
				]];
			}

			public function ajax_financial_reopen_invoice(): void
			{
				if (! $this->sn_can_approve_payment()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
				$valid=check_ajax_referer('sn_admin','nonce',false)||check_ajax_referer('sn_public','nonce',false);
				if (! $valid) { SN_Helpers::send_json(false,'نانس نامعتبر'); return; }
				$id=absint($_POST['invoice_id'] ?? 0);
				$reason=sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				$out=$this->sn_financial_reopen_invoice_internal($id,$reason);
				if (empty($out['success'])) { SN_Helpers::send_json(false,(string)($out['message'] ?? 'بازگشت به بررسی انجام نشد')); return; }
				SN_Helpers::send_json(true,(string)$out['message'],(array)($out['data'] ?? []));
			}

			public function ajax_financial_cancel_invoice(): void
			{
				if (! $this->sn_can_reject_payment()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false,'دسترسی غیرمجاز'); return; }
				$valid=check_ajax_referer('sn_admin','nonce',false)||check_ajax_referer('sn_public','nonce',false);
				if (! $valid) { SN_Helpers::send_json(false,'نانس نامعتبر'); return; }
				$id=absint($_POST['invoice_id'] ?? 0);
				$reason=sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				$refund_confirmed=!empty($_POST['refund_confirmed']);
				if ($id<1 || $reason==='') { SN_Helpers::send_json(false,'شناسه فاکتور و دلیل لغو الزامی است'); return; }
				if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(),'financial_cancellation_guard')) {
					$guard=(array) SN_Dot_Flow::instance()->financial_cancellation_guard($id);
					if (isset($guard['allowed']) && ! $guard['allowed']) { SN_Helpers::send_json(false,(string)($guard['message'] ?? 'این فاکتور در وضعیت قابل لغو مستقیم نیست')); return; }
				}
				$this->sn_ensure_payment_migrations();
				global $wpdb;
				$invoice_table=$wpdb->prefix.'sn_invoices';
				$stage_table=$wpdb->prefix.'sn_invoice_payment_stages';
				$payments_table=$wpdb->prefix.'sn_payments';
				$wpdb->query('START TRANSACTION');
				$inv=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE",$id));
				if (! $inv) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'فاکتور یافت نشد'); return; }
				if (in_array((string)($inv->status ?? ''),['cancelled','payment_archived'],true)) { $wpdb->query('COMMIT'); SN_Helpers::send_json(true,'این فاکتور قبلاً لغو شده است'); return; }
				$totals=$this->sn_invoice_payment_totals($inv);
				$paid=max(0,(float)($totals['paid'] ?? 0));
				if ($paid>0.5 && ! $refund_confirmed) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'برای فاکتوری که واریزی تاییدشده دارد، تایید انجام/پیگیری عودت وجه الزامی است'); return; }
				$now=current_time('mysql');
				$update=$this->sn_filter_existing_columns($invoice_table,[
					'status'=>'cancelled','invoice_status'=>'cancelled','payment_status'=>'cancelled','payment_workflow_status'=>'archived',
					'payment_archived_at'=>$now,'payment_archived_by'=>get_current_user_id(),'payment_archive_reason'=>$reason,
					'financial_return_state'=>$paid>0.5?'cancelled_by_finance_refund':'cancelled_by_finance','returned_to_seller_at'=>$now,
					'repeat_action_status'=>'cancelled_by_finance','repeat_action_cancel_reason'=>$reason,'updated_at'=>$now,
				]);
				if (false===$wpdb->update($invoice_table,$update,['id'=>$id])) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'ثبت لغو مالی انجام نشد'); return; }
				if ($this->sn_table_exists_quiet($stage_table)) {
					$wpdb->query($wpdb->prepare("UPDATE {$stage_table} SET status='cancelled', note=CONCAT(COALESCE(note,''), %s), updated_at=%s WHERE invoice_id=%d AND status NOT IN ('paid','approved','cancelled')", "\nلغو توسط مالی: ".$reason, $now, $id));
				}
				if ($this->sn_table_exists_quiet($payments_table)) {
					$wpdb->query($wpdb->prepare("UPDATE {$payments_table} SET status='cancelled', payment_source='finance_cancelled', updated_at=%s WHERE invoice_id=%d AND status IN ('pending','verified')",$now,$id));
				}
				if (!empty($inv->lead_id) && $this->sn_table_exists_quiet($wpdb->prefix.'sn_leads')) {
					$wpdb->update($wpdb->prefix.'sn_leads',['status'=>'assigned'],['id'=>(int)$inv->lead_id]);
				}
				$wpdb->query('COMMIT');
				if (! empty($inv->wc_order_id) && function_exists('wc_get_order')) {
					$reopened_order = wc_get_order((int)$inv->wc_order_id);
					if ($reopened_order && (string)$reopened_order->get_meta('_sn_finance_reopened', true) === '1') {
						$reopened_order->update_status('cancelled', 'لغو مالی پس از بازگشت فاکتور به بررسی: ' . $reason);
						$reopened_order->delete_meta_data('_sn_finance_reopened');
						$reopened_order->save();
					}
				}
				$this->sn_close_payment_action_item($id,'payment_cancelled_by_finance',get_current_user_id(),'لغو توسط واحد مالی: '.$reason);
				$this->sn_log_activity($id,(int)($inv->lead_id ?? 0),'invoice_cancelled_by_finance','فاکتور توسط واحد مالی لغو شد',['reason'=>$reason,'paid_total'=>$paid,'refund_confirmed'=>$refund_confirmed,'actor_user_id'=>get_current_user_id(),'wc_order_id'=>(int)($inv->wc_order_id ?? 0)]);
				$dot_handled=false;
				if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(),'on_financial_cancelled')) {
					$dot_handled=(bool) SN_Dot_Flow::instance()->on_financial_cancelled($id,$reason);
				}
				// The Dot handler owns its case balance, while this shared event also
				// reverses wallet/project commissions. Both paths are idempotent.
				do_action('sn_invoice_financial_rejected',$id,$inv,'لغو توسط مالی: '.$reason);
				SN_Helpers::send_json(true,$paid>0.5?'لغو مالی ثبت شد. عودت وجه به‌صورت عملیاتی خارج از این افزونه باید تکمیل/کنترل شود.':'فاکتور لغو شد و دیگر وارد صف تایید مالی نمی‌شود.',['status'=>'cancelled','status_label'=>SN_Helpers::status_label('cancelled'),'paid_total'=>$paid,'wc_order_id'=>(int)($inv->wc_order_id ?? 0)]);
			}

			public function handle_financial_login(): void
			{
				$login = sanitize_text_field(wp_unslash($_POST['phone'] ?? ''));
				$pass  = $this->sn_login_password_from_request();
				$auth_id = (int) get_option('sn_financial_auth_page_id', 0);
				$auth_url = $auth_id ? get_permalink($auth_id) : home_url();
				$limited = $this->sn_crm_login_rate_limit('financial', $login);
				if (empty($limited['allowed'])) {
					wp_safe_redirect(add_query_arg('sn_err', 'rate_limited', $auth_url));
					exit;
				}
				if ($login === '' || $pass === '') {
					wp_safe_redirect(add_query_arg('sn_err', 'empty', $auth_url));
					exit;
				}
				$lookup = $this->sn_find_user_for_crm_login($login, ['finance'], [], ['sn_view_finance','sn_view_wallet_commission']);
				if (($lookup['error'] ?? '') === 'duplicate_mobile') {
					wp_safe_redirect(add_query_arg('sn_err', 'duplicate_mobile', $auth_url));
					exit;
				}
				$user = $lookup['user'] ?? null;
				if (! $user instanceof WP_User || (! user_can($user, 'sn_view_finance') && ! user_can($user, 'sn_view_wallet_commission') && ! user_can($user, 'manage_options') && ! $this->sn_user_has_hr_position((int) $user->ID, 'finance'))) {
					wp_safe_redirect(add_query_arg('sn_err', 'notfound', $auth_url));
					exit;
				}
				if (! $this->sn_login_password_is_valid($user, $pass)) {
					wp_safe_redirect(add_query_arg('sn_err', 'wrongpass', $auth_url));
					exit;
				}
				wp_set_auth_cookie($user->ID, true);
				wp_set_current_user($user->ID);
				$panel_id = (int) get_option('sn_financial_panel_page_id', 0);
				wp_safe_redirect($panel_id ? get_permalink($panel_id) : admin_url('admin.php?page=sn-financial-approval'));
				exit;
			}

			public function render_financial_auth(): string
			{
				if (is_user_logged_in() && ($this->sn_can_finance() || $this->sn_can_view_wallet_commission())) {
					$panel_id = (int) get_option('sn_financial_panel_page_id', 0);
					$url = $panel_id ? get_permalink($panel_id) : admin_url('admin.php?page=sn-financial-approval');
					return '<script>window.location.href=' . wp_json_encode($url) . ';</script><p class="sn-notice sn-success">وارد شده‌اید — در حال انتقال...</p>';
				}
				$err = sanitize_text_field(wp_unslash($_GET['sn_err'] ?? ''));
				$errors = ['empty' => 'نام کاربری یا رمز عبور خالی است.', 'notfound' => 'کاربر تایید مالی یافت نشد یا دسترسی ندارد.', 'wrongpass' => 'رمز عبور اشتباه است.', 'duplicate_mobile' => 'این شماره موبایل برای چند کاربر ثبت شده است. با مدیر سیستم تماس بگیرید.'];
				ob_start(); ?>
		<div class="sn-auth-wrap" dir="rtl">
			<div class="sn-auth-logo">
				<h2>ورود تایید مالی</h2>
				<p>برای بررسی و تایید پرداخت‌ها وارد شوید.</p>
			</div>
			<div class="sn-auth-card"><?php if ($err) : ?><div class="sn-auth-error"><?php echo esc_html($errors[$err] ?? 'خطا رخ داد.'); ?></div><?php endif; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="sn_financial_login">
					<div class="sn-field"><label>شماره موبایل / نام کاربری / ایمیل</label><input type="text" name="phone" required autocomplete="username"><small class="sn-muted">برای ورود می‌توانید شماره موبایل ثبت‌شده خود را وارد کنید.</small></div>
					<div class="sn-field"><label>رمز عبور</label><input type="password" name="password" required autocomplete="current-password"></div><button type="submit" class="sn-auth-submit">ورود به پنل تایید مالی</button>
				</form>
			</div>
		</div>
	<?php return ob_get_clean();
			}

