			private function sn_zibal_export_selected_column_keys(): array
			{
				$columns = $this->sn_zibal_export_columns();
				$all_keys = array_keys($columns);
				$request = strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST' ? $_POST : $_GET;
				$submitted = ! empty($request['sn_gateway_export_columns_submitted']);
				if (! $submitted) { return $all_keys; }
				$raw = isset($request['sn_gateway_export_columns']) ? (array) wp_unslash($request['sn_gateway_export_columns']) : [];
				$wanted = [];
				foreach ($raw as $key) {
					$key = sanitize_key((string) $key);
					if (isset($columns[$key])) { $wanted[$key] = true; }
				}
				$selected = [];
				foreach ($all_keys as $key) {
					if (isset($wanted[$key])) { $selected[] = $key; }
				}
				return $selected;
			}


			/**
			 * Download the finance/Zibal reconciliation export.
			 *
			 * The primary join key is Zibal orderId -> sn_invoices.invoice_code.
			 * Monetary values from Zibal are kept in rial; CRM invoice totals are kept in toman.
			 */
			public function handle_financial_gateway_export(): void
			{
				if (! is_user_logged_in() || ! $this->sn_can_view_finance()) {
					wp_die('دسترسی به خروجی تراکنش‌های درگاهی مجاز نیست.', 'دسترسی غیرمجاز', ['response' => 403]);
				}
				check_admin_referer('sn_financial_gateway_export');

				$columns = $this->sn_zibal_export_columns();
				$selected_keys = $this->sn_zibal_export_selected_column_keys();
				if (! $selected_keys) {
					wp_die('حداقل یک ستون برای خروجی انتخاب کنید.', 'ستون خروجی انتخاب نشده', ['response' => 400]);
				}
				$source = sanitize_key((string) wp_unslash($_POST['sn_gateway_export_source'] ?? 'zibal'));
				if (! in_array($source, ['zibal', 'local'], true)) {
					wp_die('منبع خروجی نامعتبر است.', 'خطای خروجی', ['response' => 400]);
				}
				$all_keys = array_keys($columns);
				$index_by_key = array_flip($all_keys);

				$request_id = substr(str_replace('-', '', wp_generate_uuid4()), 0, 12);
				$started_at = microtime(true);
				$out = null;
				$this->sn_zibal_export_log($request_id, 'start', ['columns' => count($selected_keys)]);
				try {
					// Finish retrieval and validation before sending download headers. A failed
					// provider response must never masquerade as a successful local export.
					$report = $source === 'zibal' ? $this->sn_zibal_report_fetch_transactions() : [];
					if ($source === 'zibal') {
						$this->sn_zibal_export_log($request_id, 'remote_report', [
							'ok' => ! empty($report['ok']) ? 1 : 0,
							'rows' => count((array) ($report['transactions'] ?? [])),
							'raw_rows' => (int) ($report['raw_count'] ?? 0),
							'response_keys' => (string) ($report['response_keys'] ?? ''),
						]);
						if (empty($report['ok'])) {
							wp_die(esc_html((string) ($report['message'] ?? 'دریافت گزارش زیبال انجام نشد.')) . '<br>' . esc_html('کد پیگیری: ' . $request_id), 'گزارش زیبال آماده نشد', ['response' => 502, 'back_link' => true]);
						}
					}
					$local_transactions = $this->sn_zibal_local_successful_transactions();
					$transactions = $source === 'zibal'
						? $this->sn_zibal_merge_export_transactions((array) $report['transactions'], $local_transactions)
						: $local_transactions;
					$rows = $this->sn_zibal_build_finance_export_rows($transactions, $request_id);
					$this->sn_zibal_export_log($request_id, 'build_rows', ['source' => $source, 'rows' => count($rows)]);
					while (ob_get_level() > 0) { @ob_end_clean(); }
					$filename = 'sales-network-gateway-finance-' . $source . '-' . SN_Helpers::tehran_format('Y-m-d-His') . '.csv';
					header('Content-Type: text/csv; charset=UTF-8');
					header('Content-Disposition: attachment; filename=' . $filename);
					header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
					header('Pragma: no-cache');
					header('Expires: 0');
					header('X-Content-Type-Options: nosniff');
					header('X-SN-Export-Request-ID: ' . $request_id);
					$out = fopen('php://output', 'wb');
					if ($out === false) { throw new RuntimeException('zibal_export_output_unavailable'); }
					fwrite($out, "\xEF\xBB\xBF");
					$headers = [];
					foreach ($selected_keys as $key) { $headers[] = (string) ($columns[$key]['label'] ?? $key); }
					fputcsv($out, $headers, ',', '"', '\\');

					foreach ($rows as $row) {
						$csv_row = [];
						foreach ($selected_keys as $key) {
							$index = (int) ($index_by_key[$key] ?? -1);
							$value = ($index >= 0 && array_key_exists($index, $row)) ? $row[$index] : '';
							$value = $this->sn_zibal_export_safe_csv_cell($value);
							if (! empty($columns[$key]['excel_text']) && $value !== '' && $value !== null) {
								$text_value = trim((string) $value);
								// Only identifier-like data can be converted to an Excel text formula.
								// This prevents scientific notation / loss of leading zero without enabling arbitrary CSV formulas.
								if ($text_value !== '' && preg_match('/^[0-9*.+:\/ -]+$/', $text_value)) {
									$value = '="' . str_replace('"', '""', $text_value) . '"';
								}
							}
							$csv_row[] = $value;
						}
						fputcsv($out, $csv_row, ',', '"', '\\');
					}
					fclose($out);
					$this->sn_zibal_export_log($request_id, 'complete', [
						'rows' => count($rows),
						'columns' => count($selected_keys),
						'elapsed_ms' => (int) round((microtime(true) - $started_at) * 1000),
					]);
					exit;
				} catch (Throwable $error) {
					$this->sn_zibal_export_log($request_id, 'exception', [
						'type' => get_class($error),
						'message' => $error->getMessage(),
						'line' => $error->getLine(),
						'elapsed_ms' => (int) round((microtime(true) - $started_at) * 1000),
					]);
					if (is_resource($out)) {
						fputcsv($out, ['خطا در تکمیل خروجی؛ کد پیگیری ' . $request_id], ',', '"', '\\');
						fclose($out);
					}
					if (! headers_sent()) {
						wp_die('خروجی ساخته نشد. کد پیگیری: ' . esc_html($request_id), 'خطا در ساخت خروجی', ['response' => 500]);
					}
					exit;
				}
			}

			private function sn_zibal_export_log(string $request_id, string $stage, array $context = []): void
			{
				$safe_context = [];
				foreach ($context as $key => $value) {
					if (is_scalar($value) || $value === null) { $safe_context[sanitize_key((string) $key)] = $value; }
				}
				$safe_context['memory_mb'] = round(memory_get_usage(true) / 1048576, 1);
				error_log(sprintf(
					'Sales Network Zibal export [%s] stage=%s context=%s',
					preg_replace('/[^a-z0-9]/i', '', $request_id),
					sanitize_key($stage),
					wp_json_encode($safe_context, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
				));
			}

			private function sn_zibal_report_fetch_transactions(): array
			{
				$token = trim((string) get_option('sn_zibal_report_api_token', ''));
				if ($token === '') {
					return ['ok' => false, 'token_configured' => false, 'transactions' => [], 'message' => 'API Token گزارشات زیبال تنظیم نشده است.'];
				}

				$merchant_id = trim((string) get_option('sn_zibal_merchant', ''));
				if ($merchant_id === '') {
					return ['ok' => false, 'token_configured' => true, 'transactions' => [], 'message' => 'Merchant زیبال تنظیم نشده است.'];
				}

				$url = (string) apply_filters('sn_zibal_report_api_url', 'https://api.zibal.ir/v1/gateway/report/transaction');
				$request_body = apply_filters('sn_zibal_report_request_body', ['merchantId' => $merchant_id, 'verbose' => true]);
				$request_body = is_array($request_body) ? $request_body : ['merchantId' => $merchant_id, 'verbose' => true];
				$request_body['merchantId'] = $merchant_id;
				$timeout = max(3, min(12, (int) apply_filters('sn_zibal_report_timeout', 12)));
				$response = wp_remote_post($url, [
					'timeout' => $timeout,
					'redirection' => 1,
					'httpversion' => '1.1',
					'reject_unsafe_urls' => true,
					'limit_response_size' => 8 * MB_IN_BYTES,
					'headers' => [
						'Authorization' => 'Bearer ' . $token,
						'Content-Type' => 'application/json',
						'Accept' => 'application/json',
					],
					'body' => $request_body ? wp_json_encode($request_body) : '{}',
				]);
				if (is_wp_error($response)) {
					$message = 'ارتباط با Report API زیبال برقرار نشد: ' . $response->get_error_message();
					error_log('Sales Network: Zibal report export failed: ' . $message);
					return ['ok' => false, 'token_configured' => true, 'transactions' => [], 'message' => $message];
				}
				$http_code = (int) wp_remote_retrieve_response_code($response);
				$decoded = json_decode((string) wp_remote_retrieve_body($response), true);
				if ($http_code < 200 || $http_code >= 300 || ! is_array($decoded)) {
					$provider_message = is_array($decoded) ? sanitize_text_field((string) ($decoded['message'] ?? '')) : '';
					$message = $provider_message !== '' ? ('Report API زیبال: ' . $provider_message . ' (HTTP ' . $http_code . ').') : ('Report API زیبال پاسخ نامعتبر داد (HTTP ' . $http_code . ').');
					error_log('Sales Network: Zibal report export failed: ' . $message);
					return ['ok' => false, 'token_configured' => true, 'transactions' => [], 'message' => $message];
				}
				if (isset($decoded['result']) && ! in_array((int) $decoded['result'], [1, 100], true)) {
					$message = sanitize_text_field((string) ($decoded['message'] ?? 'زیبال درخواست گزارش را رد کرد.'));
					error_log('Sales Network: Zibal report export failed: ' . $message);
					return ['ok' => false, 'token_configured' => true, 'transactions' => [], 'message' => $message];
				}
				$raw_transactions = $this->sn_zibal_report_extract_transactions($decoded);
				$raw_count = count($raw_transactions);
				$diagnostics = [
					'raw_count' => $raw_count,
					'response_keys' => implode(',', array_map('sanitize_key', array_slice(array_keys($decoded), 0, 30))),
				];
				$transactions = [];
				foreach ($raw_transactions as $raw) {
					$normalized = $this->sn_zibal_normalize_report_transaction((array) $raw);
					if ($normalized && $this->sn_zibal_export_transaction_is_successful($normalized)) { $transactions[] = $normalized; }
				}
				return array_merge($diagnostics, ['ok' => true, 'token_configured' => true, 'transactions' => $transactions, 'message' => '']);
			}

			private function sn_zibal_report_extract_transactions(array $payload): array
			{
				$found = [];
				$walk = function ($node) use (&$walk, &$found): void {
					if (! is_array($node)) { return; }
					$track = $this->sn_zibal_report_find_scalar($node, ['trackId','track_id','transactionId','transaction_id'], false);
					$order = $this->sn_zibal_report_find_scalar($node, ['orderId','order_id','transactionOrderId','transaction_order_id'], false);
					$amount = $this->sn_zibal_report_find_scalar($node, ['amount'], false);
					if ($track !== '' && ($order !== '' || $amount !== '')) {
						$key = (string) $track;
						$found[$key] = $node;
						return;
					}
					foreach ($node as $child) {
						if (is_array($child)) { $walk($child); }
					}
				};
				$walk($payload);
				return array_values($found);
			}

			private function sn_zibal_report_normalize_key(string $key): string
			{
				return strtolower((string) preg_replace('/[^a-z0-9]/i', '', $key));
			}

			private function sn_zibal_report_find_scalar(array $node, array $aliases, bool $recursive = true): string
			{
				$wanted = [];
				foreach ($aliases as $alias) { $wanted[$this->sn_zibal_report_normalize_key((string) $alias)] = true; }
				foreach ($node as $key => $value) {
					if (! is_scalar($value) && $value !== null) { continue; }
					if (isset($wanted[$this->sn_zibal_report_normalize_key((string) $key)])) {
						return trim((string) $value);
					}
				}
				if ($recursive) {
					foreach ($node as $value) {
						if (! is_array($value)) { continue; }
						$match = $this->sn_zibal_report_find_scalar($value, $aliases, true);
						if ($match !== '') { return $match; }
					}
				}
				return '';
			}

			private function sn_zibal_normalize_report_transaction(array $raw): array
			{
				$track_id = $this->sn_zibal_report_find_scalar($raw, ['trackId','track_id','transactionId','transaction_id']);
				if ($track_id === '') { return []; }
				return [
					'trackId' => $track_id,
					'orderId' => $this->sn_zibal_report_find_scalar($raw, ['orderId','order_id','transactionOrderId','transaction_order_id']),
					'amount' => $this->sn_zibal_report_find_scalar($raw, ['amount','transactionAmount','paymentAmount']),
					'paidAt' => $this->sn_zibal_report_find_scalar($raw, ['paidAt','paid_at','paymentDate','payment_date','paidDateTime']),
					'refNumber' => $this->sn_zibal_report_find_scalar($raw, ['refNumber','ref_number','referenceNumber','reference_number','refId','ref_id']),
					'description' => $this->sn_zibal_report_find_scalar($raw, ['description','desc']),
					'mobile' => $this->sn_zibal_report_find_scalar($raw, ['mobile','payerMobile','payer_mobile']),
					'cardNumber' => $this->sn_zibal_report_find_scalar($raw, ['cardNumber','card_number','payerCardNumber','payer_card_number']),
					'gateway' => $this->sn_zibal_report_find_scalar($raw, ['gateway','gatewayName','gateway_name','psp','paymentGateway','payment_gateway','gatewayType','paymentProvider']),
					'terminalId' => $this->sn_zibal_report_find_scalar($raw, ['terminalId','terminalID','terminal_id','terminalNumber','terminal_number','terminalCode','terminal_code']),
					'payerIp' => $this->sn_zibal_report_find_scalar($raw, ['payerIp','payer_ip','cardHolderIP','card_holder_ip','paymentIp','payment_ip','ipAddress','ip_address','clientIp','client_ip','requestIp','request_ip']),
					'status' => $this->sn_zibal_report_find_scalar($raw, ['status','transactionStatus','transaction_status']),
					'_source' => 'zibal_report',
				];
			}

			private function sn_zibal_export_transaction_is_successful(array $transaction): bool
			{
				$status = trim(SN_Helpers::to_english_nums((string) ($transaction['status'] ?? '')));
				if ($status === '') {
					return ! empty($transaction['paidAt']) || ! empty($transaction['refNumber']);
				}
				if (in_array($status, ['1', '2', 'موفق - تاییدنشده', 'موفق - تایید نشده', 'پرداخت شده - تاییدنشده', 'پرداخت شده - تایید نشده'], true)) { return true; }
				$status_lc = strtolower($status);
				if (in_array($status_lc, ['success','successful','paid','verified','approved','done'], true)) { return true; }
				$negative_markers = ['ناموفق','تاییدنشده','تایید نشده','لغو','ریورس','استرداد','در انتظار','خطا'];
				foreach ($negative_markers as $marker) {
					if (strpos($status, $marker) !== false) { return false; }
				}
				return in_array($status, ['موفق','پرداخت شده - تاییدشده','پرداخت شده - تایید شده','تاییدشده','تایید شده'], true);
			}

			private function sn_zibal_local_successful_transactions(): array
			{
				global $wpdb;
				$payments = $wpdb->prefix . 'sn_payments';
				$invoices = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_table_exists_quiet($payments) || ! $this->sn_table_exists_quiet($invoices)) { return []; }
				$sql = "SELECT p.id AS payment_row_id,p.invoice_id,p.authority,p.ref_id,p.amount AS transaction_toman,p.status AS payment_row_status,p.created_at AS payment_created_at,p.updated_at AS payment_updated_at,i.*\n"
					. "FROM {$payments} p INNER JOIN {$invoices} i ON i.id=p.invoice_id\n"
					. "WHERE (p.payment_source='zibal' OR p.authority LIKE 'zibal:%')\n"
					. "AND p.status IN ('approved','paid','verified','success','completed') ORDER BY p.id DESC";
				$rows = $wpdb->get_results($sql, ARRAY_A) ?: [];
				$out = [];
				foreach ($rows as $row) {
					$authority = (string) ($row['authority'] ?? '');
					$track_id = '';
					if (preg_match('/^zibal:([0-9]+)$/i', $authority, $m)) { $track_id = (string) $m[1]; }
					if ($track_id === '') { continue; }
					$out[] = [
						'trackId' => $track_id,
						'orderId' => (string) ($row['invoice_code'] ?? ''),
						'amount' => (string) round(((float) ($row['transaction_toman'] ?? 0)) * 10),
						'paidAt' => (string) (($row['payment_updated_at'] ?? '') ?: ($row['payment_created_at'] ?? '') ?: ($row['paid_at'] ?? '')),
						'refNumber' => (string) ($row['ref_id'] ?? ''),
						'description' => '',
						'mobile' => '',
						'cardNumber' => '',
						'gateway' => '',
						'terminalId' => '',
						'payerIp' => '',
						'status' => '1',
						'_source' => 'local',
						'_invoice' => $row,
					];
				}
				return $out;
			}

			private function sn_zibal_merge_export_transactions(array $report_transactions, array $local_transactions): array
			{
				$local_by_track = [];
				foreach ($local_transactions as $transaction) {
					$key = trim((string) ($transaction['trackId'] ?? ''));
					if ($key !== '') { $local_by_track[$key] = $transaction; }
				}
				$map = [];
				foreach ($report_transactions as $transaction) {
					$key = trim((string) ($transaction['trackId'] ?? ''));
					if ($key === '') { continue; }
					// Provider rows and every provider field remain authoritative. Only
					// attach the CRM invoice for enrichment; never add local-only payments.
					$invoice = $local_by_track[$key]['_invoice'] ?? null;
					if (is_array($invoice)) { $transaction['_invoice'] = $invoice; }
					$map[$key] = $transaction;
				}
				$merged = array_values($map);
				usort($merged, function (array $a, array $b): int {
					return strcmp((string) ($b['paidAt'] ?? ''), (string) ($a['paidAt'] ?? ''));
				});
				return $merged;
			}

			private function sn_zibal_invoice_map_by_codes(array $codes): array
			{
				global $wpdb;
				$codes = array_values(array_unique(array_filter(array_map('strval', $codes), static function ($value): bool { return trim($value) !== ''; })));
				if (! $codes) { return []; }
				$table = $wpdb->prefix . 'sn_invoices';
				$out = [];
				foreach (array_chunk($codes, 400) as $chunk) {
					$placeholders = implode(',', array_fill(0, count($chunk), '%s'));
					$sql = $wpdb->prepare("SELECT * FROM {$table} WHERE invoice_code IN ({$placeholders})", ...$chunk);
					$rows = $wpdb->get_results($sql, ARRAY_A) ?: [];
					foreach ($rows as $row) { $out[(string) ($row['invoice_code'] ?? '')] = $row; }
				}
				return $out;
			}

			private function sn_zibal_invoice_items_labels_map(array $invoice_ids): array
			{
				global $wpdb;
				$invoice_ids = array_values(array_unique(array_filter(array_map('absint', $invoice_ids))));
				if (! $invoice_ids) { return []; }
				$table = $wpdb->prefix . 'sn_invoice_items';
				if (! $this->sn_table_exists_quiet($table)) { return []; }
				$parts = [];
				foreach (array_chunk($invoice_ids, 400) as $chunk) {
					$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
					$sql = $wpdb->prepare("SELECT invoice_id,product_name,qty FROM {$table} WHERE invoice_id IN ({$placeholders}) ORDER BY invoice_id ASC,id ASC", ...$chunk);
					$items = $wpdb->get_results($sql, ARRAY_A) ?: [];
					foreach ($items as $item) {
						$invoice_id = (int) ($item['invoice_id'] ?? 0);
						if ($invoice_id < 1) { continue; }
						$label = trim((string) ($item['product_name'] ?? ''));
						if ($label === '') { continue; }
						$qty = (int) ($item['qty'] ?? 1);
						$parts[$invoice_id][] = $label . ($qty > 1 ? ' × ' . $qty : '');
					}
				}
				$out = [];
				foreach ($parts as $invoice_id => $labels) { $out[(int) $invoice_id] = implode('، ', $labels); }
				return $out;
			}

			/**
			 * Resolve only the HR branches needed by the Zibal export.
			 *
			 * The shared admin helper intentionally supports broad reporting screens and
			 * loads the complete HR graph. Doing that during a synchronous CSV download
			 * can make LiteSpeed abort before response headers are sent. This export-only
			 * resolver keeps the same labels/roles while querying the requested sellers
			 * and their ancestors in bounded batches.
			 */
			private function sn_zibal_hr_chain_map(array $user_ids): array
			{
				global $wpdb;
				$user_ids = array_values(array_unique(array_filter(array_map('absint', $user_ids))));
				if (! $user_ids) { return []; }

				$map = [];
				foreach ($user_ids as $user_id) {
					$map[$user_id] = ['seller_id' => $user_id, 'seller_name' => '#' . $user_id];
				}
				// Preserve the existing no-HR-profile fallback without one query per seller.
				foreach (array_chunk($user_ids, 400) as $chunk) {
					$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
					$sql = $wpdb->prepare("SELECT ID,display_name FROM {$wpdb->users} WHERE ID IN ({$placeholders})", ...$chunk);
					foreach (($wpdb->get_results($sql, ARRAY_A) ?: []) as $user) {
						$user_id = (int) ($user['ID'] ?? 0);
						$name = trim((string) ($user['display_name'] ?? ''));
						if ($user_id > 0 && isset($map[$user_id])) {
							$map[$user_id]['seller_name'] = ($name !== '' ? $name : ('#' . $user_id)) . ' #' . $user_id;
						}
					}
				}

				$profiles_table = $wpdb->prefix . 'sn_hr_profiles';
				$assignments_table = $wpdb->prefix . 'sn_hr_assignments';
				$positions_table = $wpdb->prefix . 'sn_hr_positions';
				if (! $this->sn_table_exists_quiet($profiles_table)
					|| ! $this->sn_table_exists_quiet($assignments_table)
					|| ! $this->sn_table_exists_quiet($positions_table)) {
					return $map;
				}

				$profile_by_id = [];
				$profile_by_user = [];
				foreach (array_chunk($user_ids, 400) as $chunk) {
					$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
					$sql = $wpdb->prepare(
						"SELECT p.id,p.user_id,p.is_active,COALESCE(NULLIF(p.hr_display_name,''),u.display_name,CONCAT('#',p.user_id)) display_name,pos.slug position_slug
						FROM {$profiles_table} p
						LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
						LEFT JOIN {$positions_table} pos ON pos.id=p.position_id
						WHERE p.user_id IN ({$placeholders})
						ORDER BY p.is_active DESC,p.id DESC",
						...$chunk
					);
					foreach (($wpdb->get_results($sql, ARRAY_A) ?: []) as $profile) {
						$profile_id = (int) ($profile['id'] ?? 0);
						$user_id = (int) ($profile['user_id'] ?? 0);
						if ($profile_id < 1 || $user_id < 1) { continue; }
						$profile_by_id[$profile_id] = $profile;
						if (! isset($profile_by_user[$user_id])) { $profile_by_user[$user_id] = $profile; }
					}
				}

				$frontier = [];
				foreach ($user_ids as $user_id) {
					$profile = $profile_by_user[$user_id] ?? null;
					if (! is_array($profile)) { continue; }
					$map[$user_id]['seller_name'] = (string) ($profile['display_name'] ?? $map[$user_id]['seller_name']);
					$profile_id = (int) ($profile['id'] ?? 0);
					if ($profile_id > 0) { $frontier[$profile_id] = $profile_id; }
				}

				$parents = [];
				$expanded = [];
				for ($depth = 0; $depth < 12 && $frontier; $depth++) {
					$current_ids = array_values(array_diff(array_values($frontier), array_keys($expanded)));
					if (! $current_ids) { break; }
					foreach ($current_ids as $profile_id) { $expanded[$profile_id] = true; }
					$next_frontier = [];
					foreach (array_chunk($current_ids, 400) as $chunk) {
						$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
						$sql = $wpdb->prepare(
							"SELECT child_profile_id,parent_profile_id FROM {$assignments_table}
							WHERE is_current=1 AND (relationship_type='reports_to' OR relationship_type='' OR relationship_type IS NULL)
							AND child_profile_id IN ({$placeholders}) ORDER BY id DESC",
							...$chunk
						);
						foreach (($wpdb->get_results($sql, ARRAY_A) ?: []) as $edge) {
							$child_id = (int) ($edge['child_profile_id'] ?? 0);
							$parent_id = (int) ($edge['parent_profile_id'] ?? 0);
							if ($child_id < 1 || $parent_id < 1 || isset($parents[$child_id])) { continue; }
							$parents[$child_id] = $parent_id;
							$next_frontier[$parent_id] = $parent_id;
						}
					}

					$missing_parent_ids = array_values(array_diff(array_values($next_frontier), array_keys($profile_by_id)));
					foreach (array_chunk($missing_parent_ids, 400) as $chunk) {
						if (! $chunk) { continue; }
						$placeholders = implode(',', array_fill(0, count($chunk), '%d'));
						$sql = $wpdb->prepare(
							"SELECT p.id,p.user_id,p.is_active,COALESCE(NULLIF(p.hr_display_name,''),u.display_name,CONCAT('#',p.user_id)) display_name,pos.slug position_slug
							FROM {$profiles_table} p
							LEFT JOIN {$wpdb->users} u ON u.ID=p.user_id
							LEFT JOIN {$positions_table} pos ON pos.id=p.position_id
							WHERE p.id IN ({$placeholders})",
							...$chunk
						);
						foreach (($wpdb->get_results($sql, ARRAY_A) ?: []) as $profile) {
							$profile_id = (int) ($profile['id'] ?? 0);
							if ($profile_id > 0) { $profile_by_id[$profile_id] = $profile; }
						}
					}
					$frontier = [];
					foreach ($next_frontier as $profile_id) {
						if (isset($profile_by_id[$profile_id])) { $frontier[$profile_id] = $profile_id; }
					}
				}

				foreach ($user_ids as $user_id) {
					$profile = $profile_by_user[$user_id] ?? null;
					$current_profile_id = is_array($profile) ? (int) ($profile['id'] ?? 0) : 0;
					$seen = [];
					for ($depth = 0; $depth < 12 && $current_profile_id > 0 && isset($parents[$current_profile_id]); $depth++) {
						$parent_id = (int) $parents[$current_profile_id];
						if ($parent_id < 1 || isset($seen[$parent_id])) { break; }
						$seen[$parent_id] = true;
						$parent = $profile_by_id[$parent_id] ?? null;
						if (! is_array($parent)) { break; }
						$slug = (string) ($parent['position_slug'] ?? '');
						$name = (string) ($parent['display_name'] ?? '');
						$parent_user_id = (int) ($parent['user_id'] ?? 0);
						if ($slug === 'supervisor' && empty($map[$user_id]['supervisor_id'])) {
							$map[$user_id]['supervisor_id'] = $parent_user_id;
							$map[$user_id]['supervisor_name'] = $name;
						} elseif ($slug === 'senior_supervisor' && empty($map[$user_id]['senior_supervisor_id'])) {
							$map[$user_id]['senior_supervisor_id'] = $parent_user_id;
							$map[$user_id]['senior_supervisor_name'] = $name;
						} elseif ($slug === 'sales_manager' && empty($map[$user_id]['sales_manager_id'])) {
							$map[$user_id]['sales_manager_id'] = $parent_user_id;
							$map[$user_id]['sales_manager_name'] = $name;
						} elseif (in_array($slug, ['deputy_sales','sales_deputy','deputy'], true) && empty($map[$user_id]['deputy_id'])) {
							$map[$user_id]['deputy_id'] = $parent_user_id;
							$map[$user_id]['deputy_name'] = $name;
						}
						$current_profile_id = $parent_id;
					}
				}
				return $map;
			}

			private function sn_zibal_build_finance_export_rows(array $transactions, string $request_id = ''): array
			{
				$order_codes = [];
				$invoice_by_code = [];
				foreach ($transactions as $transaction) {
					if (! empty($transaction['_invoice']) && is_array($transaction['_invoice'])) {
						$invoice = $transaction['_invoice'];
						$code = (string) ($invoice['invoice_code'] ?? '');
						if ($code !== '') { $invoice_by_code[$code] = $invoice; }
					}
					$order_code = trim((string) ($transaction['orderId'] ?? ''));
					if ($order_code !== '' && ! isset($invoice_by_code[$order_code])) { $order_codes[] = $order_code; }
				}
				$invoice_by_code = array_replace($this->sn_zibal_invoice_map_by_codes($order_codes), $invoice_by_code);
				$seller_ids = [];
				$invoice_ids = [];
				foreach ($invoice_by_code as $invoice) {
					$seller_ids[] = $this->sn_invoice_effective_seller_id_for_admin((array) $invoice);
					if (! empty($invoice['id'])) { $invoice_ids[] = (int) $invoice['id']; }
				}
				$chain_started_at = microtime(true);
				try {
					$chain_map = $this->sn_zibal_hr_chain_map($seller_ids);
					if ($request_id !== '') {
						$this->sn_zibal_export_log($request_id, 'hr_chain', [
							'sellers' => count(array_unique(array_filter(array_map('absint', $seller_ids)))),
							'elapsed_ms' => (int) round((microtime(true) - $chain_started_at) * 1000),
						]);
					}
				} catch (Throwable $error) {
					// Hierarchy labels enrich the report; they must not make transaction data unavailable.
					$chain_map = [];
					if ($request_id !== '') {
						$this->sn_zibal_export_log($request_id, 'hr_chain_fallback', [
							'type' => get_class($error),
							'line' => $error->getLine(),
							'elapsed_ms' => (int) round((microtime(true) - $chain_started_at) * 1000),
						]);
					}
				}
				$product_labels = $this->sn_zibal_invoice_items_labels_map($invoice_ids);

				$rows = [];
				foreach ($transactions as $transaction) {
					$order_id = trim((string) ($transaction['orderId'] ?? ''));
					$invoice = $invoice_by_code[$order_id] ?? (is_array($transaction['_invoice'] ?? null) ? $transaction['_invoice'] : []);
					$seller_id = $invoice ? $this->sn_invoice_effective_seller_id_for_admin((array) $invoice) : 0;
					$chain = $chain_map[$seller_id] ?? [];
					$rows[] = [
						(string) ($transaction['trackId'] ?? ''),
						$order_id,
						$this->sn_zibal_export_numeric_value($transaction['amount'] ?? ''),
						$this->sn_zibal_export_paid_at((string) ($transaction['paidAt'] ?? ''), (string) ($transaction['_source'] ?? 'zibal_report')),
						(string) ($transaction['refNumber'] ?? ''),
						(string) ($transaction['description'] ?? ''),
						(string) ($transaction['mobile'] ?? ''),
						(string) ($transaction['cardNumber'] ?? ''),
						(string) ($transaction['gateway'] ?? ''),
						(string) ($transaction['terminalId'] ?? ''),
						(string) ($transaction['payerIp'] ?? ''),
						$this->sn_zibal_export_status_label((string) ($transaction['status'] ?? '')),
						(string) ($invoice['customer_name'] ?? ''),
						(string) ($invoice['customer_phone'] ?? ''),
						(string) ($invoice['province'] ?? ''),
						(string) ($invoice['city'] ?? ''),
						$invoice ? ($product_labels[(int) ($invoice['id'] ?? 0)] ?? ((int) ($invoice['product_id'] ?? 0) > 0 ? (string) get_the_title((int) $invoice['product_id']) : '—')) : '',
						$invoice ? $this->sn_invoice_amount_from_row((array) $invoice) : '',
						(string) ($chain['seller_name'] ?? ($seller_id ? $this->sn_user_label($seller_id) : '')),
						(string) ($chain['supervisor_name'] ?? ''),
						(string) ($chain['senior_supervisor_name'] ?? ''),
						$seller_id > 0 ? (string) $seller_id : '',
						! empty($chain['supervisor_id']) ? (string) (int) $chain['supervisor_id'] : '',
						! empty($chain['senior_supervisor_id']) ? (string) (int) $chain['senior_supervisor_id'] : '',
						(string) ($chain['sales_manager_name'] ?? ''),
						! empty($chain['sales_manager_id']) ? (string) (int) $chain['sales_manager_id'] : '',
						(string) ($chain['deputy_name'] ?? ''),
						! empty($chain['deputy_id']) ? (string) (int) $chain['deputy_id'] : '',
					];
				}
				return $rows;
			}

			private function sn_zibal_export_numeric_value($value)
			{
				if ($value === '' || $value === null) { return ''; }
				$normalized = str_replace([',', '٬', '،'], '', SN_Helpers::to_english_nums((string) $value));
				return is_numeric($normalized) ? (0 + $normalized) : (string) $value;
			}

            private function sn_zibal_export_paid_at(string $value, string $source = 'zibal_report'): string
            {
                $value = trim(SN_Helpers::to_english_nums($value));
                if ($value === '' || strpos($value, '0000-00-00') === 0) { return ''; }
                // A provider timestamp without an offset is UTC; legacy CRM timestamps
                // are WordPress-local. Explicit offsets always take precedence.
                $zone = $source === 'local'
                    ? (function_exists('wp_timezone') ? wp_timezone() : SN_Helpers::tehran_timezone())
                    : new DateTimeZone((string) apply_filters('sn_zibal_report_naive_timezone', 'UTC'));
                if (preg_match('/^((?:13|14)\d{2})[\/.-](\d{1,2})[\/.-](\d{1,2})(.*)$/', $value, $m)) {
                    $gregorian = SN_Helpers::jalali_to_gregorian_date($m[1].'/'.$m[2].'/'.$m[3]);
                    if ($gregorian === '') { return ''; }
                    $suffix = $m[4];
                    if (preg_match('/^-\d{1,2}:/', $suffix)) { $suffix = ' '.substr($suffix,1); }
                    $value = $gregorian.$suffix;
                }
                $epoch = (bool) preg_match('/^\d{10}(?:\d{3})?$/D', $value);
                $has_time = $epoch || (bool) preg_match('/\d{1,2}:\d{2}/', $value);
                try {
                    if ($epoch) {
                        $seconds = strlen($value) === 13 ? (int) floor((float)$value / 1000) : (int)$value;
                        $date = new DateTimeImmutable('@'.$seconds);
                    } else {
                        // Reject relative expressions and invalid calendar dates.
                        if (!preg_match('/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}(?:[ T].*)?$/D', $value)) { return ''; }
                        $date = new DateTimeImmutable($value, $zone);
                        $errors = DateTimeImmutable::getLastErrors();
                        if (is_array($errors) && ($errors['warning_count'] || $errors['error_count'])) { return ''; }
                    }
                    if ($has_time) { $date = $date->setTimezone(SN_Helpers::tehran_timezone()); }
                    // Pass an explicit offset so the shared converter cannot reinterpret it
                    // in the site's timezone a second time.
                    $jalali = SN_Helpers::gregorian_to_jalali_input_value($date->format('Y-m-d'));
                    return $jalali . ($has_time ? '-'.$date->format('H:i:s') : '');
                } catch (Throwable $error) { return ''; }
            }

			private function sn_zibal_export_status_label(string $status): string
			{
				$status = trim(SN_Helpers::to_english_nums($status));
				$labels = [
					'-2' => 'خطای داخلی', '-1' => 'در انتظار پرداخت', '1' => 'موفق',
					'2' => 'موفق - تاییدنشده', '3' => 'لغو شده توسط کاربر',
					'4' => 'شماره کارت نامعتبر', '5' => 'موجودی ناکافی', '6' => 'رمز اشتباه',
					'7' => 'تعداد درخواست بیش از حد مجاز', '8' => 'سقف تعداد پرداخت روزانه',
					'9' => 'سقف مبلغ پرداخت روزانه', '10' => 'صادرکننده کارت نامعتبر',
					'11' => 'خطای سوئیچ', '12' => 'کارت قابل دسترسی نیست',
					'15' => 'استرداد شده', '16' => 'در حال استرداد', '18' => 'ریورس شده',
					'21' => 'پذیرنده نامعتبر',
				];
				if (isset($labels[$status])) { return $labels[$status]; }
				if ($status === '') { return 'موفق'; }
				if (in_array(strtolower($status), ['success','successful','paid','verified','approved','done'], true)) { return 'موفق'; }
				return $status;
			}

			private function sn_zibal_export_safe_csv_cell($value)
			{
				if (! is_string($value)) { return $value; }
				$value = str_replace(["\r\n", "\r"], "\n", $value);
				if ($value !== '' && preg_match('/^[=+\-@]/', ltrim($value))) { return "'" . $value; }
				return $value;
			}

