					['پیش‌نمایش پورسانت', 'بررسی ایستا', 'پیش‌نمایش فقط ردیف بررسی می‌نویسد.'],
					['تایید پورسانت', 'بررسی ایستا', 'APPROVE/REJECT فقط فراداده و لاگ را تغییر می‌دهد.'],
					['کلید ارسال کیف پول', $this->sn_commission_posting_enabled() ? 'روشن' : 'خاموش', $this->sn_commission_posting_enabled() ? 'روشن؛ ارسال همچنان APPLY و اجرای تاییدشده لازم دارد.' : 'خاموش؛ ارسال اجرا نمی‌شود.'],
					['حقوق و پورسانت HR', 'نیازمند تست دستی', 'ویرایش حقوق/پورسانت HR باید با APPLY روی محیط تست بررسی شود.'],
