					<h3 class="sn-section-title">آمادگی بازبینی</h3>
					<p class="sn-muted">این بلوک query سنگین اجرا نمی‌کند؛ وضعیت‌های زیر راهنمای بازبینی بعد از تغییرات مالی هستند.</p>
					<div class="sn-table-wrap sn-hr-change-table"><table class="sn-table"><thead><tr><th>بخش</th><th>وضعیت</th><th>یادداشت</th></tr></thead><tbody>
					<?php foreach ($rows as $row) : ?><tr><td><?php echo esc_html($row[0]); ?></td><td><span class="sn-badge"><?php echo esc_html($row[1]); ?></span></td><td><?php echo esc_html($row[2]); ?></td></tr><?php endforeach; ?>
					<tr><td>Known issue</td><td><span class="sn-badge">documented</span></td><td>admin read-only /invoice/ lookup ممکن است برای بعضی invoice_codeها هنوز forbidden_invoice بدهد؛ خارج از این pass مگر اینکه Finance را بلاک کند.</td></tr>
					</tbody></table></div>
				</div>
				<?php return ob_get_clean();
			}

			private function sn_wallet_table_exists(string $table): bool
			{
				global $wpdb;
				return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
			}

			private function sn_wallet_readiness_stats(): array
			{
				global $wpdb;
				$this->ensure_wallet_tables();
				$wallets = $wpdb->prefix . 'sn_wallets';
				$tx = $wpdb->prefix . 'sn_wallet_transactions';
				$stats = [
					'wallet_count' => 0,
					'positive_balance' => 0,
					'negative_balance' => 0,
					'today_transactions' => 0,
					'pending_transactions' => 0,
					'pending_settlements' => 0,
					'latest_update' => '',
				];
				if (! $this->sn_wallet_table_exists($wallets) || ! $this->sn_wallet_table_exists($tx)) {
					return $stats;
				}
				$today = SN_Helpers::tehran_today_gregorian();
				$stats['wallet_count'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wallets}");
				$stats['positive_balance'] = (float) $wpdb->get_var("SELECT COALESCE(SUM(CASE WHEN balance > 0 THEN balance ELSE 0 END),0) FROM {$wallets}");
				$stats['negative_balance'] = (float) $wpdb->get_var("SELECT COALESCE(SUM(CASE WHEN balance < 0 THEN balance ELSE 0 END),0) FROM {$wallets}");
				$stats['today_transactions'] = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$tx} WHERE DATE(created_at)=%s", $today));
				$stats['pending_transactions'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx} WHERE status IN ('pending','review','needs_review','pending_review')");
				$stats['pending_settlements'] = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx} WHERE type IN ('settlement','withdraw','withdrawal') AND status IN ('pending','review','needs_review','pending_review')");
				$stats['latest_update'] = (string) $wpdb->get_var("SELECT MAX(latest_at) FROM (SELECT MAX(updated_at) latest_at FROM {$wallets} UNION ALL SELECT MAX(created_at) latest_at FROM {$tx}) x");
				return $stats;
			}

			private function sn_wallet_readiness_filters(): array
			{
				return [
					'seller_id' => absint($_GET['sn_wallet_seller'] ?? 0),
					'type' => sanitize_key(wp_unslash($_GET['sn_wallet_tx_type'] ?? '')),
					'status' => sanitize_key(wp_unslash($_GET['sn_wallet_tx_status'] ?? '')),
					'date_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['sn_wallet_date_from'] ?? ''))),
					'date_to' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['sn_wallet_date_to'] ?? ''))),
					'reference_type' => sanitize_key(wp_unslash($_GET['sn_wallet_ref_type'] ?? '')),
					'reference_id' => absint($_GET['sn_wallet_ref_id'] ?? 0),
				];
			}

			private function sn_wallet_readiness_ledger(array $filters, int $limit = 100): array
			{
				global $wpdb;
				$tx = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($tx)) {
					return [];
				}
				$where = ['1=1'];
				$args = [];
				if ($filters['seller_id'] > 0) {
					$where[] = 'wt.user_id=%d';
					$args[] = $filters['seller_id'];
				}
				if ($filters['type'] !== '') {
					$where[] = 'wt.type=%s';
					$args[] = $filters['type'];
				}
				if ($filters['status'] !== '') {
					$where[] = 'wt.status=%s';
					$args[] = $filters['status'];
				}
				if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['date_from'])) {
					$where[] = 'wt.created_at >= %s';
					$args[] = $filters['date_from'] . ' 00:00:00';
				}
				if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['date_to'])) {
					$where[] = 'wt.created_at <= %s';
					$args[] = $filters['date_to'] . ' 23:59:59';
				}
				if ($filters['reference_id'] > 0 && in_array($filters['reference_type'], ['invoice', 'lead'], true)) {
					$where[] = $filters['reference_type'] === 'invoice' ? 'wt.invoice_id=%d' : 'wt.lead_id=%d';
					$args[] = $filters['reference_id'];
				}
				$args[] = $limit;
				$sql = "SELECT wt.*, u.display_name, u.user_login FROM {$tx} wt LEFT JOIN {$wpdb->users} u ON u.ID=wt.user_id WHERE " . implode(' AND ', $where) . ' ORDER BY wt.created_at DESC, wt.id DESC LIMIT %d';
				return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
			}

			private function sn_wallet_readiness_checks(): array
			{
				global $wpdb;
				$wallets = $wpdb->prefix . 'sn_wallets';
				$tx = $wpdb->prefix . 'sn_wallet_transactions';
				$wallet_cols = $this->sn_table_columns($wallets);
				$tx_cols = $this->sn_table_columns($tx);
				$tx_count = $this->sn_wallet_table_exists($tx) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx}") : 0;
				$seller_missing_wallet = 0;
				if ($this->sn_wallet_table_exists($wallets) && $this->sn_wallet_table_exists($wpdb->prefix . 'sn_hr_profiles') && $this->sn_wallet_table_exists($wpdb->prefix . 'sn_hr_positions')) {
					$seller_missing_wallet = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_profiles hp INNER JOIN {$wpdb->prefix}sn_hr_positions p ON p.id=hp.position_id LEFT JOIN {$wallets} w ON w.user_id=hp.user_id AND w.wallet_type='seller' WHERE p.slug='seller' AND hp.is_active=1 AND w.id IS NULL");
				}
				$missing_before_after = 0;
				if ($tx_count > 0) {
					$has_before = in_array('balance_before', $tx_cols, true) || in_array('before_balance', $tx_cols, true);
					$has_after = in_array('balance_after', $tx_cols, true) || in_array('after_balance', $tx_cols, true);
					$missing_before_after = ($has_before && $has_after) ? 0 : $tx_count;
				}
				return [
					['label' => 'فروشنده‌های بدون رکورد کیف پول', 'count' => $seller_missing_wallet, 'note' => 'بر اساس HR position=seller و wallet_type=seller'],
					['label' => 'کیف پول‌های بدون کاربر معتبر', 'count' => $this->sn_wallet_table_exists($wallets) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wallets} w LEFT JOIN {$wpdb->users} u ON u.ID=w.user_id WHERE u.ID IS NULL") : 0, 'note' => 'فقط گزارش؛ تعمیر خودکار انجام نمی‌شود'],
					['label' => 'تراکنش‌های بدون کاربر معتبر', 'count' => $this->sn_wallet_table_exists($tx) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx} wt LEFT JOIN {$wpdb->users} u ON u.ID=wt.user_id WHERE u.ID IS NULL") : 0, 'note' => 'فقط گزارش'],
					['label' => 'تراکنش‌های بدون reference', 'count' => $this->sn_wallet_table_exists($tx) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx} WHERE (invoice_id IS NULL OR invoice_id=0) AND (lead_id IS NULL OR lead_id=0)") : 0, 'note' => 'ممکن است برای اصلاح دستی طبیعی باشد'],
					['label' => 'موجودی‌های منفی', 'count' => $this->sn_wallet_table_exists($wallets) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wallets} WHERE balance < 0") : 0, 'note' => 'نیازمند بررسی مالی'],
					['label' => 'تراکنش‌های فاقد balance قبل/بعد', 'count' => $missing_before_after, 'note' => $missing_before_after ? 'legacy missing: ستون‌های before/after در schema فعلی نیستند' : 'آماده'],
					['label' => 'تراکنش‌های legacy بدون status', 'count' => $this->sn_wallet_table_exists($tx) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tx} WHERE status IS NULL OR status=''") : 0, 'note' => 'برای موتور جدید باید status کامل شود'],
					['label' => 'reference تکراری قابل تشخیص', 'count' => $this->sn_wallet_table_exists($tx) ? (int) $wpdb->get_var("SELECT COUNT(*) FROM (SELECT invoice_id,user_id,wallet_type,type,COUNT(*) c FROM {$tx} WHERE invoice_id IS NOT NULL AND invoice_id > 0 GROUP BY invoice_id,user_id,wallet_type,type HAVING c > 1) d") : 0, 'note' => 'بر اساس invoice/user/wallet/type'],
				];
			}

			private function sn_wallet_settlement_readiness_rows(int $limit = 50): array
			{
				global $wpdb;
				$wallets = $wpdb->prefix . 'sn_wallets';
				$tx = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($wallets)) {
					return [];
				}
				$last_tx_select = $this->sn_wallet_table_exists($tx) ? "(SELECT MAX(created_at) FROM {$tx} wt WHERE wt.wallet_id=w.id)" : "NULL";
				$pending_select = $this->sn_wallet_table_exists($tx) ? "(SELECT COUNT(*) FROM {$tx} wt WHERE wt.wallet_id=w.id AND wt.type IN ('settlement','withdraw','withdrawal') AND wt.status IN ('pending','review','needs_review','pending_review'))" : "0";
				$posted_select = $this->sn_wallet_table_exists($tx) ? "(SELECT COALESCE(SUM(CASE WHEN wt.direction='credit' AND wt.type IN ('commission_engine','commission_engine_reopened','commission_engine_reversed','seller_commission','seller_commission_reopened','seller_commission_reversed','supervisor_commission','supervisor_commission_reopened','supervisor_commission_reversed','biavin_commission','biavin_commission_recredit','purpose_commission') THEN wt.amount WHEN wt.direction='debit' AND wt.type IN ('biavin_commission_reversal','commission_engine_reversal','seller_commission_reversal','supervisor_commission_reversal','finance_reopen_reversal','purpose_commission_reversal') THEN -wt.amount ELSE 0 END),0) FROM {$tx} wt WHERE wt.wallet_id=w.id AND wt.status='approved')" : "0";
				return $wpdb->get_results($wpdb->prepare("SELECT w.*, u.display_name, u.user_login, hp.employment_status, {$last_tx_select} last_transaction_at, {$pending_select} pending_settlements, {$posted_select} posted_commission_not_settled
					FROM {$wallets} w
					LEFT JOIN {$wpdb->users} u ON u.ID=w.user_id
					LEFT JOIN {$wpdb->prefix}sn_hr_profiles hp ON hp.user_id=w.user_id
					WHERE w.balance > 0
					ORDER BY w.balance DESC LIMIT %d", $limit), ARRAY_A) ?: [];
			}

			private function sn_wallet_adjustment_dry_run_report(): array
			{
				if ((string) ($_GET['sn_wallet_dry_run'] ?? '') !== '1') {
					return [];
				}
				global $wpdb;
				$user_id = absint($_GET['sn_wallet_adj_user'] ?? 0);
				$wallet_type = sanitize_key(wp_unslash($_GET['sn_wallet_adj_wallet_type'] ?? 'seller'));
				$direction = sanitize_key(wp_unslash($_GET['sn_wallet_adj_direction'] ?? 'credit'));
				$amount = (float) str_replace(',', '', sanitize_text_field(wp_unslash($_GET['sn_wallet_adj_amount'] ?? '0')));
				$reason = sanitize_text_field(wp_unslash($_GET['sn_wallet_adj_reason'] ?? ''));
				$wallet_type = in_array($wallet_type, ['seller', 'supervisor', 'biavin'], true) ? $wallet_type : 'seller';
				$direction = $direction === 'debit' ? 'debit' : 'credit';
				$report = [
					'valid' => false,
					'errors' => [],
					'user_id' => $user_id,
					'wallet_type' => $wallet_type,
					'direction' => $direction,
					'amount' => $amount,
					'reason' => $reason,
					'balance_before' => 0,
					'balance_after' => 0,
				];
				if (! $user_id || ! get_user_by('id', $user_id)) {
					$report['errors'][] = 'seller_not_found';
				}
				if ($amount <= 0) {
					$report['errors'][] = 'invalid_amount';
				}
				if ($reason === '') {
					$report['errors'][] = 'reason_required';
				}
				$wallet = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_wallets WHERE user_id=%d AND wallet_type=%s", $user_id, $wallet_type), ARRAY_A);
				$balance = (float) ($wallet['balance'] ?? 0);
				$report['balance_before'] = $balance;
				$report['balance_after'] = $direction === 'debit' ? $balance - $amount : $balance + $amount;
				$report['valid'] = empty($report['errors']);
				return $report;
			}

			private function sn_wallet_user_options(int $limit = 300): array
			{
				global $wpdb;
				return $wpdb->get_results($wpdb->prepare("SELECT DISTINCT w.user_id, u.display_name, u.user_login FROM {$wpdb->prefix}sn_wallets w LEFT JOIN {$wpdb->users} u ON u.ID=w.user_id ORDER BY u.display_name ASC, w.user_id ASC LIMIT %d", $limit), ARRAY_A) ?: [];
			}

