			private function sn_ensure_commission_tables(): bool
			{
				if (! class_exists('SN_Migration_Service')) {
					return false;
				}
				$service = new SN_Migration_Service();
				if (! $service->commission_tables_complete()) {
					$service->migrate();
				}
				$ready = $service->commission_tables_complete();
				if ($ready) {
					$this->sn_ensure_commission_rule_matching_schema();
				}
				return $ready;
			}

			private function sn_commission_table_columns_fresh(string $table): array
			{
				global $wpdb;
				return (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
			}

			private function sn_commission_add_column_if_missing(string $table, string $column, string $definition): void
			{
				$this->sn_runtime_add_column_if_missing($table, $column, $column . ' ' . $definition);
			}

			private function sn_ensure_commission_rule_matching_schema(): void
			{
				global $wpdb;
				$version = '2026-10-07-commission-matching-v1';
				if (get_option('sn_commission_matching_schema_version', '') === $version) { return; }
				$rules = $wpdb->prefix . 'sn_commission_rules';
				$items = $wpdb->prefix . 'sn_commission_dry_run_items';
				$invoices = $wpdb->prefix . 'sn_invoices';
				if ($this->sn_table_exists_quiet($rules)) {
					$this->sn_commission_add_column_if_missing($rules, 'employment_type', "VARCHAR(80) NOT NULL DEFAULT '' AFTER employment_status");
					$this->sn_commission_add_column_if_missing($rules, 'effective_from', 'DATE DEFAULT NULL AFTER max_invoice_amount');
					$this->sn_commission_add_column_if_missing($rules, 'effective_to', 'DATE DEFAULT NULL AFTER effective_from');
				}
				if ($this->sn_table_exists_quiet($items)) {
					$this->sn_commission_add_column_if_missing($items, 'employment_type', "VARCHAR(80) NOT NULL DEFAULT '' AFTER seller_level");
					$this->sn_commission_add_column_if_missing($items, 'issued_by_user_id', "BIGINT UNSIGNED DEFAULT NULL AFTER seller_user_id");
				}
				if ($this->sn_table_exists_quiet($invoices)) {
					$this->sn_commission_add_column_if_missing($invoices, 'issued_by_user_id', 'BIGINT UNSIGNED DEFAULT NULL');
					$this->sn_commission_add_column_if_missing($invoices, 'original_seller_id', 'BIGINT UNSIGNED DEFAULT NULL');
				}
				$ready = true;
				foreach ([$rules => ['employment_type','effective_from','effective_to'], $items => ['employment_type','issued_by_user_id'], $invoices => ['issued_by_user_id','original_seller_id']] as $table => $columns) {
					foreach ($columns as $column) { $ready = $this->sn_table_has_column($table, $column) && $ready; }
				}
				if ($ready) { update_option('sn_commission_matching_schema_version', $version, false); }
			}

			private function sn_commission_rule_code(): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_rules';
				do {
					$code = 'CR-' . SN_Helpers::tehran_format('Ymd') . '-' . strtoupper(wp_generate_password(5, false, false));
				} while ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE rule_code=%s", $code)) > 0);
				return $code;
			}

			private function sn_commission_run_code(): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_dry_runs';
				do {
					$code = 'CDR-' . SN_Helpers::tehran_format('Ymd') . '-' . strtoupper(wp_generate_password(5, false, false));
				} while ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE run_code=%s", $code)) > 0);
				return $code;
			}

			private function sn_commission_rules(bool $active_only = false): array
			{
				global $wpdb;
				if (! $this->sn_ensure_commission_tables()) {
					return [];
				}
				$table = $wpdb->prefix . 'sn_commission_rules';
				$where = $active_only ? 'WHERE is_active=1' : '';
				return $wpdb->get_results("SELECT * FROM {$table} {$where} ORDER BY is_active DESC, priority DESC, id ASC", ARRAY_A) ?: [];
			}

