			private function sn_commission_time_value($value, string $default): string
			{
				$value = trim((string) $value);
				if (preg_match('/^\d{1,2}:\d{2}$/', $value)) {
					$value .= ':00';
				}
				return preg_match('/^\d{2}:\d{2}:\d{2}$/', $value) ? $value : $default;
			}

