			private function sn_commission_active_rule_by_id(int $rule_id): ?array
			{
				if ($rule_id < 1) { return null; }
				foreach ($this->sn_commission_rules(true) as $rule) {
					if ((int) ($rule['id'] ?? 0) === $rule_id) { return $rule; }
				}
				return null;
			}

			private function sn_commission_apply_hr_override_to_rules(array &$context, array $auto_rules): array
			{
				$mode = $this->sn_commission_normalize_override_mode((string) ($context['commission_override_mode'] ?? 'inherit'));
				$manual_rule_id = (int) ($context['manual_commission_rule_id'] ?? 0);
				$context['commission_override_mode'] = $mode;
				if ($mode === 'disabled') {
					$context['diagnostics'][] = 'commission_disabled_by_manual_override';
					return [];
				}
				if ($mode === 'manual_rule') {
					$rule = $this->sn_commission_active_rule_by_id($manual_rule_id);
					if ($rule) {
						$context['diagnostics'][] = 'commission_manual_rule_override';
						return [$rule];
					}
					$context['diagnostics'][] = 'commission_manual_rule_missing_or_inactive';
					return [];
				}
				return $auto_rules;
			}

			private function sn_normalize_commission_employment_type(string $value): string
			{
				$value = trim($value);
				$map = [
					'آموزشی' => 'training',
					'اموزشی' => 'training',
					'training' => 'training',
					'train' => 'training',
					'probation' => 'training',
					'قراردادی' => 'contractor',
					'contractor' => 'contractor',
					'contract' => 'contractor',
					'پیمانکار' => 'contractor',
				];
				$key = sanitize_key($value);
				return $map[$value] ?? $map[$key] ?? $key;
			}

			private function sn_commission_option_label(array $options, string $value): string
			{
				$value = trim($value);
				if ($value === '') {
					return (string) ($options[''] ?? 'همه');
				}
				if (isset($options[$value])) {
					return (string) $options[$value];
				}
				if (strpos($value, ',') !== false) {
					$parts = array_filter(array_map('trim', explode(',', $value)));
					return implode(' / ', array_map(fn($part) => $this->sn_commission_option_label($options, $part), $parts));
				}
				return $value;
			}

			private function sn_commission_position_label(array $positions, string $slug): string
			{
				if ($slug === '') { return 'همه سمت‌ها'; }
				foreach ($positions as $pos) {
					if ((string) ($pos['slug'] ?? '') === $slug) {
						return (string) (($pos['label'] ?? '') ?: $slug);
					}
				}
				return $slug;
			}

			private function sn_commission_level_label(array $levels, string $slug): string
			{
				if ($slug === '') { return 'همه سطح‌ها'; }
				foreach ($levels as $level) {
					if ((string) ($level['slug'] ?? '') === $slug) {
						return (string) (($level['label'] ?? '') ?: $slug);
					}
				}
				return $slug;
			}

			private function sn_commission_diagnostics(array $rules, array $positions, array $levels, array $selected_run_summary): array
			{
				global $wpdb;
				$position_slugs = array_flip(array_filter(array_map(static fn($p) => (string) ($p['slug'] ?? ''), $positions)));
				$level_slugs = array_flip(array_filter(array_map(static fn($l) => (string) ($l['slug'] ?? ''), $levels)));
				$payment_options = $this->sn_commission_payment_method_options();
				$status_options = $this->sn_commission_statuses();
				$active_rules = array_values(array_filter($rules, static fn($r) => ! empty($r['is_active'])));
				$unknown_position = 0; $unknown_level = 0; $unknown_payment = 0; $unknown_status = 0;
				foreach ($active_rules as $rule) {
					$pos = (string) ($rule['applies_to_position'] ?? '');
					$lvl = (string) ($rule['applies_to_level'] ?? '');
					$pay = (string) ($rule['payment_method'] ?? '');
					$statuses = array_filter(array_map('trim', explode(',', (string) ($rule['invoice_status'] ?? ''))));
					if ($pos !== '' && ! isset($position_slugs[$pos])) { $unknown_position++; }
					if ($lvl !== '' && ! isset($level_slugs[$lvl])) { $unknown_level++; }
					if ($pay !== '' && ! isset($payment_options[$pay])) { $unknown_payment++; }
					foreach ($statuses as $status) { if (! isset($status_options[$status])) { $unknown_status++; break; } }
				}
				$items = $wpdb->prefix . 'sn_commission_dry_run_items';
				$zero_rules = 0;
				if ($this->sn_table_exists_quiet($items)) {
					foreach ($active_rules as $rule) {
						$used = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$items} WHERE matched_rule_id=%d OR notes LIKE %s LIMIT 1", (int) $rule['id'], '%"matched_rule_ids":%' . (int) $rule['id'] . '%'));
						if ($used === 0) { $zero_rules++; }
					}
				}
				$history_missing = (int) ($selected_run_summary['history_missing'] ?? 0);
				return [
					['label' => 'قوانین فعال', 'count' => count($active_rules), 'status' => count($active_rules) ? 'ok' : 'warning', 'hint' => count($active_rules) ? 'آماده بررسی' : 'حداقل یک قانون فعال لازم است.'],
					['label' => 'قانون با سمت ناشناخته', 'count' => $unknown_position, 'status' => $unknown_position ? 'warning' : 'ok', 'hint' => 'سمت باید از HR انتخاب شود.'],
					['label' => 'قانون با سطح ناشناخته', 'count' => $unknown_level, 'status' => $unknown_level ? 'warning' : 'ok', 'hint' => 'سطح باید از HR انتخاب شود.'],
					['label' => 'روش پرداخت ناشناخته', 'count' => $unknown_payment, 'status' => $unknown_payment ? 'warning' : 'ok', 'hint' => 'روش پرداخت را از dropdown انتخاب کنید.'],
					['label' => 'وضعیت فاکتور ناشناخته', 'count' => $unknown_status, 'status' => $unknown_status ? 'warning' : 'ok', 'hint' => 'وضعیت فاکتور باید از گزینه‌های شناخته‌شده باشد.'],
					['label' => 'قانون بدون match در dry-runها', 'count' => $zero_rules, 'status' => $zero_rules ? 'warning' : 'ok', 'hint' => 'اگر dry-run صفر است، سطح/سمت/وضعیت همکاری را در HR بررسی کنید.'],
					['label' => 'فاکتورهای بدون تاریخچه HR در run انتخاب‌شده', 'count' => $history_missing, 'status' => $history_missing ? 'warning' : 'ok', 'hint' => 'برای این فروشنده‌ها تاریخچه حقوق/پورسانت بسازید.'],
				];
			}

			private function sn_commission_invoice_amount_expr(): string
			{
				$cols = $this->sn_table_columns($GLOBALS['wpdb']->prefix . 'sn_invoices');
				if (in_array('final_total', $cols, true)) {
					return 'COALESCE(NULLIF(i.final_total,0), NULLIF(i.product_price,0), 0)';
				}
				return 'COALESCE(NULLIF(i.product_price,0), 0)';
			}

			private function sn_commission_readiness_stats(): array
			{
				global $wpdb;
				$this->sn_ensure_commission_tables();
				$amount_expr = $this->sn_commission_invoice_amount_expr();
				$rules = $wpdb->prefix . 'sn_commission_rules';
				$invoices = $wpdb->prefix . 'sn_invoices';
				$profiles = $wpdb->prefix . 'sn_hr_profiles';
				$positions = $wpdb->prefix . 'sn_hr_positions';
				$items = $wpdb->prefix . 'sn_commission_dry_run_items';
				$stats = [
					'active_rules' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$rules} WHERE is_active=1"),
					'eligible_invoices' => count($this->sn_commission_invoice_rows_for_wallet(null, 5000)),
					'active_sellers' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$profiles} hp INNER JOIN {$positions} p ON p.id=hp.position_id WHERE p.slug='seller' AND hp.is_active=1"),
					'invoices_without_seller' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoices} WHERE seller_id IS NULL OR seller_id=0"),
					'invoices_without_amount' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoices} i WHERE {$amount_expr} <= 0"),
					'latest_difference' => '—',
				];
				$diff = $wpdb->get_var("SELECT COALESCE(SUM(difference_amount),0) FROM {$items} WHERE difference_amount IS NOT NULL");
				$stats['latest_difference'] = $diff !== null ? SN_Helpers::format_price((float) $diff) : '—';
				return $stats;
			}

			private function sn_normalize_invoice_payment_method(array $invoice): string
			{
				$haystack = strtolower(trim(implode(' ', array_filter([
					(string) ($invoice['pay_method'] ?? ''),
					(string) ($invoice['payment_method'] ?? ''),
					(string) ($invoice['payment_source'] ?? ''),
					(string) ($invoice['receipt_source'] ?? ''),
					(string) ($invoice['gateway'] ?? ''),
					(string) ($invoice['authority'] ?? ''),
					(string) ($invoice['transaction_id'] ?? ''),
				]))));
				if ($haystack !== '' && preg_match('/zarin|gateway|online|portal|درگاه|آنلاین|انلاین/', $haystack)) {
					return 'online';
				}
				if ($haystack !== '' && preg_match('/card|receipt|manual|bank|deposit|upload|فیش|کارت|واریز/', $haystack)) {
					return 'card_to_card';
				}
				foreach (['receipt_url','receipt_file','deposit_amount','manual_amount','manual_card_from','manual_card_to','manual_card_to_number','deposit_card_from_last4','deposit_card_to_last4','manual_paid_at','deposit_jalali_datetime'] as $key) {
					if (! empty($invoice[$key])) { return 'card_to_card'; }
				}
				foreach (['wc_order_id','paid_at'] as $key) {
					if (! empty($invoice[$key]) && $haystack === '') { return 'online'; }
				}
				return 'unknown';
			}

			private function sn_invoice_amount_from_row(array $invoice): float
			{
				foreach (['final_total','paid_amount','deposit_amount','manual_amount','original_total','product_price','amount','total'] as $key) {
					if (isset($invoice[$key]) && (float) $invoice[$key] > 0) {
						return (float) $invoice[$key];
					}
				}
				return 0.0;
			}

			private function sn_resolve_invoice_commission_context(int $invoice_id, ?array $invoice_row = null): array
			{
				global $wpdb;
				$context = [
					'invoice_id' => $invoice_id,
					'invoice_code' => '',
					'seller_id' => 0,
					'issued_by_user_id' => 0,
					'finance_approved_at' => '',
					'calculation_date' => SN_Helpers::tehran_today_gregorian(),
					'issue_datetime' => '',
					'issue_date' => '',
					'issue_time' => '',
					'invoice_total' => 0.0,
					'paid_amount' => 0.0,
					'payment_method_normalized' => 'unknown',
					'invoice_status' => '',
					'seller_hr_position' => '',
					'seller_hr_level' => '',
					'seller_employment_status' => '',
					'seller_employment_type' => '',
					'compensation_history_id' => 0,
					'compensation_history' => null,
					'commission_enabled' => null,
					'commission_override_mode' => 'inherit',
					'manual_commission_rule_id' => 0,
					'diagnostics' => [],
					'source' => 'sn_invoices',
				];
				$table = $wpdb->prefix . 'sn_invoices';
				if (! $invoice_row) {
					$invoice_row = $this->sn_table_exists_quiet($table) ? (array) $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $invoice_id), ARRAY_A) : [];
				}
				if (! $invoice_row) {
					$context['diagnostics'][] = 'invoice_not_found';
					return $context;
				}
				$context['invoice_code'] = (string) ($invoice_row['invoice_code'] ?? '');
				$context['invoice_status'] = (string) ($invoice_row['status'] ?? ($invoice_row['invoice_status'] ?? ''));
				$issued_at = (string) (($invoice_row['created_at'] ?? '') ?: ($invoice_row['issued_at'] ?? '') ?: ($invoice_row['invoice_created_at'] ?? '') ?: ($invoice_row['updated_at'] ?? ''));
				try {
					$issued_date = $issued_at !== '' ? (new DateTimeImmutable($issued_at, wp_timezone()))->setTimezone(SN_Helpers::tehran_timezone()) : null;
				} catch (Throwable $e) {
					$issued_date = null;
				}
				if ($issued_date instanceof DateTimeImmutable) {
					$context['issue_datetime'] = $issued_date->format('Y-m-d H:i:s');
					$context['issue_date'] = $issued_date->format('Y-m-d');
					$context['issue_time'] = $issued_date->format('H:i:s');
				}
				$context['seller_id'] = $this->sn_commission_invoice_seller_id_from_row($invoice_row);
				$context['issued_by_user_id'] = (int) (($invoice_row['issued_by_user_id'] ?? 0) ?: ($invoice_row['created_by'] ?? 0) ?: $context['seller_id']);
				$context['finance_approved_at'] = (string) (($invoice_row['financial_reviewed_at'] ?? '') ?: ($invoice_row['approved_at'] ?? '') ?: ($invoice_row['payment_approved_at'] ?? ''));
				$context['invoice_total'] = $this->sn_invoice_amount_from_row($invoice_row);
				$context['paid_amount'] = (float) (($invoice_row['paid_amount'] ?? 0) ?: ($invoice_row['deposit_amount'] ?? 0) ?: ($invoice_row['manual_amount'] ?? 0) ?: $context['invoice_total']);
				$context['payment_method_normalized'] = $this->sn_normalize_invoice_payment_method($invoice_row);
				$context['calculation_date'] = $this->sn_commission_calculation_date(array_merge($invoice_row, ['payment_approved_at' => $context['finance_approved_at']]));
				if ($context['seller_id'] < 1) {
					$context['diagnostics'][] = 'missing_seller_id';
					return $context;
				}
				$profile = $wpdb->get_row($wpdb->prepare("SELECT hp.*, pos.slug position_slug, lvl.slug level_slug FROM {$wpdb->prefix}sn_hr_profiles hp LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=hp.level_id WHERE hp.user_id=%d ORDER BY hp.id DESC LIMIT 1", (int) $context['seller_id']), ARRAY_A);
				if ($profile) {
					$context['seller_hr_position'] = (string) ($profile['position_slug'] ?? '');
					$context['seller_hr_level'] = (string) ($profile['level_slug'] ?? '');
					$context['seller_employment_status'] = (string) ($profile['employment_status'] ?? '');
					$context['seller_employment_type'] = $this->sn_normalize_commission_employment_type((string) ($profile['employment_type'] ?? ''));
					$comp_table = $wpdb->prefix . 'sn_hr_compensation_profiles';
					if (! empty($profile['id']) && $this->sn_table_exists_quiet($comp_table)) {
						$comp_profile = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$comp_table} WHERE profile_id=%d AND is_active=1 ORDER BY id DESC LIMIT 1", (int) $profile['id']), ARRAY_A);
						if ($comp_profile) {
							$context['commission_override_mode'] = $this->sn_commission_normalize_override_mode((string) ($comp_profile['commission_override_mode'] ?? 'inherit'));
							$context['manual_commission_rule_id'] = (int) ($comp_profile['default_commission_rule_id'] ?? 0);
						}
					}
				}
				$history = $this->sn_hr_compensation_history_for_user_at((int) $context['seller_id'], (string) $context['calculation_date']);
				if ($history) {
					$context['compensation_history_id'] = (int) ($history['id'] ?? 0);
					$context['compensation_history'] = $history;
					$context['seller_hr_position'] = (string) (($history['position_slug_snapshot'] ?? '') ?: $context['seller_hr_position']);
					$context['seller_hr_level'] = (string) (($history['level_slug_snapshot'] ?? '') ?: $context['seller_hr_level']);
					$context['seller_employment_status'] = (string) (($history['employment_status'] ?? '') ?: $context['seller_employment_status']);
					$context['seller_employment_type'] = $this->sn_normalize_commission_employment_type((string) (($history['employment_type'] ?? '') ?: $context['seller_employment_type']));
					$context['commission_enabled'] = (int) ($history['commission_enabled'] ?? 0);
					$context['commission_override_mode'] = $this->sn_commission_normalize_override_mode((string) ($history['commission_override_mode'] ?? $context['commission_override_mode'] ?? 'inherit'));
					$context['manual_commission_rule_id'] = (int) ($history['commission_rule_id'] ?? $context['manual_commission_rule_id'] ?? 0);
				} else {
					$context['diagnostics'][] = 'no_compensation_history';
				}
				if ($context['payment_method_normalized'] === 'unknown') { $context['diagnostics'][] = 'no_payment_method'; }
				if ($this->sn_commission_is_missing_employment_type((string) ($context['seller_employment_type'] ?? '')) && empty($context['seller_hr_level'])) { $context['diagnostics'][] = 'no_employment_type'; }
				// A converter may issue a normal invoice from its seller-like workspace, but
				// converter-owned invoices must never be interpreted as seller commission sales.
				if ((string) ($context['seller_hr_position'] ?? '') === 'converter') {
					$context['diagnostics'][] = 'converter_owned_invoice_no_seller_commission';
					$context['commission_enabled'] = 0;
					$context['seller_id'] = 0;
				}
				return $context;
			}

			private function sn_rule_value_matches(string $rule_value, string $context_value): bool
			{
				$rule_value = trim($rule_value);
				if ($rule_value === '' || $rule_value === 'any' || $rule_value === 'all') { return true; }
				$allowed = array_filter(array_map('trim', explode(',', $rule_value)));
				return in_array($context_value, $allowed, true);
			}

			private function sn_commission_is_missing_employment_type(string $value): bool
			{
				$value = trim($value);
				return $value === '' || $value === 'unknown' || $value === 'نامشخص' || $value === '—' || $value === '-';
			}

			private function sn_commission_employment_type_level_matches(string $employment_type, string $level_slug): bool
			{
				$employment_type = $this->sn_normalize_commission_employment_type($employment_type);
				$level_slug = sanitize_key($level_slug);
				$map = [
					'training' => ['trainee', 'training', 'probation', 'آموزشی', 'amoozeshi'],
					'contractor' => ['standard', 'contract', 'contractor', 'قراردادی', 'gharardadi'],
				];
				return isset($map[$employment_type]) && in_array($level_slug, $map[$employment_type], true);
			}

			private function sn_commission_rule_employment_type_matches(array $rule, array $context): bool
			{
				$rule_value = trim((string) ($rule['employment_type'] ?? ''));
				$context_value = trim((string) ($context['seller_employment_type'] ?? ''));
				if ($this->sn_rule_value_matches($rule_value, $context_value)) {
					return true;
				}

				// Compatibility repair: older UI allowed selecting «آموزشی/قراردادی» both as level and as employment type.
				// In HR these are usually levels, while employment_type may be unknown. If the level already matches,
				// do not reject the rule only because employment_type is missing.
				$context_level = sanitize_key((string) ($context['seller_hr_level'] ?? ''));
				$rule_level = trim((string) ($rule['applies_to_level'] ?? ''));
				$rule_level_matches = $rule_level !== '' && $this->sn_rule_value_matches($rule_level, $context_level);
				if ($this->sn_commission_is_missing_employment_type($context_value) && $context_level !== '') {
					$allowed_types = array_filter(array_map('trim', explode(',', $rule_value)));
					foreach ($allowed_types as $type) {
						if (($rule_level_matches && $rule_level !== '') || $this->sn_commission_employment_type_level_matches($type, $context_level)) {
							return true;
						}
					}
				}
				return false;
			}

			private function sn_commission_effective_to_blocks_rule(array $rule, string $calc_date): bool
			{
				if (! $calc_date) { return false; }
				$effective_to = (string) ($rule['effective_to'] ?? '');
				if (! preg_match('/^\d{4}-\d{2}-\d{2}/', $effective_to)) { return false; }
				$to = substr($effective_to, 0, 10);
				$from = (string) ($rule['effective_from'] ?? '');
				// If UI accidentally stored end date equal to start date, treat it as open-ended instead of a one-day rule.
				if (preg_match('/^\d{4}-\d{2}-\d{2}/', $from) && substr($from, 0, 10) === $to) {
					return false;
				}
				return $to < $calc_date;
			}

			private function sn_find_matching_commission_rule(array $context): array
			{
				$rules = $this->sn_commission_rules(true);
				$candidates = [];
				$rejected = [];
				foreach ($rules as $rule) {
					$reasons = [];
					if (! $this->sn_rule_value_matches((string) ($rule['applies_to_position'] ?? ''), (string) ($context['seller_hr_position'] ?? ''))) { $reasons[] = 'position'; }
					if (! $this->sn_rule_value_matches((string) ($rule['applies_to_level'] ?? ''), (string) ($context['seller_hr_level'] ?? ''))) { $reasons[] = 'level'; }
					if (! $this->sn_rule_value_matches((string) ($rule['employment_status'] ?? ''), (string) ($context['seller_employment_status'] ?? ''))) { $reasons[] = 'employment_status'; }
					if (! $this->sn_commission_rule_employment_type_matches($rule, $context)) { $reasons[] = 'employment_type'; }
					if (! $this->sn_rule_value_matches((string) ($rule['payment_method'] ?? ''), (string) ($context['payment_method_normalized'] ?? 'unknown'))) { $reasons[] = 'payment_method'; }
					if (! $this->sn_rule_value_matches((string) ($rule['invoice_status'] ?? ''), (string) ($context['invoice_status'] ?? ''))) { $reasons[] = 'invoice_status'; }
					$amount = (float) ($context['invoice_total'] ?? 0);
					$min = $rule['min_invoice_amount'] === null || $rule['min_invoice_amount'] === '' ? null : (float) $rule['min_invoice_amount'];
					$max = $rule['max_invoice_amount'] === null || $rule['max_invoice_amount'] === '' ? null : (float) $rule['max_invoice_amount'];
					if ($min !== null && $amount < $min) { $reasons[] = 'min_amount'; }
					if ($max !== null && $max > 0 && $amount > $max) { $reasons[] = 'max_amount'; }
					$calc_date = (string) ($context['calculation_date'] ?? '');
					$effective_from = (string) ($rule['effective_from'] ?? '');
					$effective_to = (string) ($rule['effective_to'] ?? '');
					if ($calc_date && preg_match('/^\d{4}-\d{2}-\d{2}/', $effective_from) && substr($effective_from, 0, 10) > $calc_date) { $reasons[] = 'effective_from'; }
					if ($this->sn_commission_effective_to_blocks_rule($rule, $calc_date)) { $reasons[] = 'effective_to'; }
					if ($reasons) {
						$rejected[] = ['rule_id' => (int) ($rule['id'] ?? 0), 'reasons' => $reasons];
						continue;
					}
					$specificity = 0;
					foreach (['employment_type','payment_method','applies_to_level','applies_to_position','employment_status','invoice_status'] as $key) {
						if (trim((string) ($rule[$key] ?? '')) !== '') { $specificity++; }
					}
					$rule['_specificity'] = $specificity;
					$candidates[] = $rule;
				}
				usort($candidates, static function($a, $b) {
					foreach (['_specificity','priority'] as $key) {
						$cmp = ((int) ($b[$key] ?? 0)) <=> ((int) ($a[$key] ?? 0));
						if ($cmp !== 0) { return $cmp; }
					}
					$af = (string) ($a['effective_from'] ?? '');
					$bf = (string) ($b['effective_from'] ?? '');
					$cmp = strcmp($bf, $af);
					if ($cmp !== 0) { return $cmp; }
					return ((int) ($b['id'] ?? 0)) <=> ((int) ($a['id'] ?? 0));
				});
				$diagnostics = [];
				if (! $rules) { $diagnostics[] = 'no_active_rule'; }
				if (! $candidates && $rules) { $diagnostics[] = 'no_matching_rule'; }
				return [
					'matched_rule' => $candidates[0] ?? null,
					'matched_rules' => $candidates,
					'matched_rule_ids' => array_values(array_map(static fn($rule) => (int) ($rule['id'] ?? 0), $candidates)),
					'candidates' => $candidates,
					'rejected_rules' => $rejected,
					'diagnostics' => $diagnostics,
					'stack_mode' => 'cumulative_all_matching_rules',
				];
			}

			private function sn_commission_calculate_rule_components(array $rules, float $amount): array
			{
				$components = [];
				$total = 0.0;
				foreach ($rules as $rule) {
					$value = $this->sn_commission_calculate_from_rule($rule, $amount);
					if ($value <= 0) { continue; }
					$components[] = [
						'rule_id' => (int) ($rule['id'] ?? 0),
						'rule_title' => (string) ($rule['title'] ?? ('#' . (int) ($rule['id'] ?? 0))),
						'calculation_type' => $this->sn_commission_rule_calculation_type($rule),
						'rate_percent' => (float) ($rule['rate_percent'] ?? 0),
						'fixed_amount' => (float) ($rule['fixed_amount'] ?? 0),
						'daily_base_amount' => (float) ($rule['daily_base_amount'] ?? 0),
						'commission' => $value,
					];
					$total += $value;
				}
				return ['total' => round($total, 2), 'components' => $components];
			}

			private function sn_commission_daily_attendance_rule_ids(array $rules): array
			{
				$ids = [];
				foreach ($rules as $rule) {
					if ($this->sn_commission_rule_calculation_type($rule) === 'daily_attendance_plus_percent' && (float) ($rule['daily_base_amount'] ?? 0) > 0) {
						$ids[(int) ($rule['id'] ?? 0)] = true;
					}
				}
				return array_map('intval', array_keys($ids));
			}

			private function sn_commission_daily_attendance_context_key(array $context, array $rule): string
			{
				$seller_id = (int) ($context['seller_id'] ?? 0);
				$date = (string) (($context['issue_date'] ?? '') ?: ($context['calculation_date'] ?? ''));
				return $seller_id . '|' . $date . '|' . (int) ($rule['id'] ?? 0);
			}

			private function sn_commission_collect_daily_attendance_candidate(array &$daily_groups, array $context, array $rule): void
			{
				if ($this->sn_commission_rule_calculation_type($rule) !== 'daily_attendance_plus_percent') { return; }
				$seller_id = (int) ($context['seller_id'] ?? 0);
				$date = (string) (($context['issue_date'] ?? '') ?: ($context['calculation_date'] ?? ''));
				$time = (string) ($context['issue_time'] ?? '');
				if ($seller_id < 1 || $date === '' || $time === '') { return; }
				$key = $this->sn_commission_daily_attendance_context_key($context, $rule);
				if (! isset($daily_groups[$key])) {
					$daily_groups[$key] = [
						'seller_id' => $seller_id,
						'date' => $date,
						'rule' => $rule,
						'first_time' => $time,
						'last_time' => $time,
						'first_invoice_id' => (int) ($context['invoice_id'] ?? 0),
						'last_invoice_id' => (int) ($context['invoice_id'] ?? 0),
						'invoice_count' => 0,
						'seller_position' => (string) ($context['seller_hr_position'] ?? ''),
						'seller_level' => (string) ($context['seller_hr_level'] ?? ''),
						'employment_type' => (string) (($context['seller_employment_type'] ?? '') ?: 'unknown'),
						'compensation_history_id' => (int) ($context['compensation_history_id'] ?? 0),
						'compensation_effective_from' => ! empty($context['compensation_history']['effective_from']) ? (string) $context['compensation_history']['effective_from'] : null,
						'compensation_effective_to' => ! empty($context['compensation_history']['effective_to']) ? (string) $context['compensation_history']['effective_to'] : null,
					];
				}
				$daily_groups[$key]['invoice_count']++;
				if (strcmp($time, (string) $daily_groups[$key]['first_time']) < 0) {
					$daily_groups[$key]['first_time'] = $time;
					$daily_groups[$key]['first_invoice_id'] = (int) ($context['invoice_id'] ?? 0);
				}
				if (strcmp($time, (string) $daily_groups[$key]['last_time']) > 0) {
					$daily_groups[$key]['last_time'] = $time;
					$daily_groups[$key]['last_invoice_id'] = (int) ($context['invoice_id'] ?? 0);
				}
			}

			private function sn_commission_daily_attendance_group_qualifies(array $group): bool
			{
				$rule = (array) ($group['rule'] ?? []);
				$first_limit = $this->sn_commission_time_value($rule['attendance_first_before'] ?? '', '10:30:00');
				$last_limit = $this->sn_commission_time_value($rule['attendance_last_after'] ?? '', '15:00:00');
				$first = (string) ($group['first_time'] ?? '');
				$last = (string) ($group['last_time'] ?? '');
				return $first !== '' && $last !== '' && strcmp($first, $first_limit) <= 0 && strcmp($last, $last_limit) >= 0;
			}

			private function sn_commission_rule_matches_invoice(array $rule, array $invoice): bool
			{
				$context = [
					'seller_hr_position' => (string) ($invoice['seller_position'] ?? ''),
					'seller_hr_level' => (string) ($invoice['seller_level'] ?? ''),
					'seller_employment_status' => (string) ($invoice['employment_status'] ?? ''),
					'seller_employment_type' => $this->sn_normalize_commission_employment_type((string) ($invoice['employment_type'] ?? '')),
					'payment_method_normalized' => in_array((string) ($invoice['payment_method'] ?? ''), ['online','card_to_card','unknown'], true) ? (string) ($invoice['payment_method'] ?? '') : $this->sn_normalize_invoice_payment_method($invoice),
					'invoice_status' => (string) ($invoice['invoice_status'] ?? ''),
					'invoice_total' => (float) ($invoice['invoice_amount'] ?? 0),
					'calculation_date' => $this->sn_commission_calculation_date($invoice),
				];
				$result = $this->sn_find_matching_commission_rule($context);
				return in_array((int) ($rule['id'] ?? 0), array_map('intval', (array) ($result['matched_rule_ids'] ?? [])), true);
			}

			private function sn_commission_calculate_from_rule(array $rule, float $amount): float
			{
				$type = $this->sn_commission_rule_calculation_type($rule);
				$fixed = $type === 'daily_attendance_plus_percent' ? 0.0 : (float) ($rule['fixed_amount'] ?? 0);
				$percent = (float) ($rule['rate_percent'] ?? 0);
				return round(max(0, $fixed + (($amount * $percent) / 100)), 2);
			}

			private function sn_commission_legacy_for_invoice(int $invoice_id, int $seller_id): ?float
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($table)) {
					return null;
				}
				$value = $wpdb->get_var($wpdb->prepare("SELECT SUM(amount) FROM {$table} WHERE invoice_id=%d AND user_id=%d AND type='seller_commission'", $invoice_id, $seller_id));
				return $value === null ? null : (float) $value;
			}

			private function sn_commission_dry_run_items(int $run_id = 0, int $limit = 100): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_dry_run_items';
				if (! $this->sn_ensure_commission_tables()) {
					return [];
				}
				if ($run_id > 0) {
					return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} WHERE run_id=%d ORDER BY id DESC LIMIT %d", $run_id, $limit), ARRAY_A) ?: [];
				}
				return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
			}

			private function sn_latest_commission_dry_runs(int $limit = 10): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_dry_runs';
				if (! $this->sn_ensure_commission_tables()) {
					return [];
				}
				return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
			}

			private function sn_commission_run(int $run_id): array
			{
				global $wpdb;
				if (! $run_id || ! $this->sn_ensure_commission_tables()) {
					return [];
				}
				return (array) $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_commission_dry_runs WHERE id=%d", $run_id), ARRAY_A);
			}

			private function sn_commission_posting_enabled(): bool
			{
				// The purpose matrix is the single automatic commission source once enabled.
				// Keeping the legacy dry-run poster disabled prevents duplicate wallet credits.
				if ( class_exists('SN_Purpose_Commission') && SN_Purpose_Commission::is_matrix_engine_enabled() ) { return false; }
				return get_option('sn_enable_commission_wallet_posting', '0') === '1';
			}

			private function sn_commission_log(int $run_id, ?int $item_id, string $action, string $status, $old_value = null, $new_value = null, string $message = '', ?int $wallet_transaction_id = null): void
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_wallet_posting_logs';
				if (! $this->sn_wallet_table_exists($table)) {
					return;
				}
				$wpdb->insert($table, [
					'run_id' => $run_id,
					'item_id' => $item_id ?: null,
					'wallet_transaction_id' => $wallet_transaction_id ?: null,
					'actor_user_id' => get_current_user_id() ?: null,
					'action' => sanitize_key($action),
					'status' => sanitize_key($status),
					'old_value' => $old_value === null ? null : wp_json_encode($old_value, JSON_UNESCAPED_UNICODE),
					'new_value' => $new_value === null ? null : wp_json_encode($new_value, JSON_UNESCAPED_UNICODE),
					'message' => sanitize_textarea_field($message),
					'created_at' => current_time('mysql'),
				]);
			}

			private function sn_commission_run_posting_summary(int $run_id): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_dry_run_items';
				if (! $run_id || ! $this->sn_ensure_commission_tables()) {
					return ['eligible' => 0, 'posted' => 0, 'blocked' => 0, 'errors' => 0, 'amount' => 0];
				}
				return [
					'eligible' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE run_id=%d AND calculated_commission > 0 AND seller_user_id > 0 AND (wallet_transaction_id IS NULL OR wallet_transaction_id=0) AND COALESCE(posting_status,'pending') NOT IN ('posted','error')", $run_id)),
					'posted' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE run_id=%d AND wallet_transaction_id IS NOT NULL AND wallet_transaction_id > 0", $run_id)),
					'blocked' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE run_id=%d AND (calculated_commission <= 0 OR seller_user_id <= 0 OR item_status='no_rule')", $run_id)),
					'errors' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE run_id=%d AND posting_status='error'", $run_id)),
					'amount' => (float) $wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(calculated_commission),0) FROM {$table} WHERE run_id=%d AND calculated_commission > 0 AND seller_user_id > 0", $run_id)),
				];
			}

			private function sn_commission_latest_posting_logs(int $limit = 30): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_wallet_posting_logs';
				if (! $this->sn_wallet_table_exists($table)) {
					return [];
				}
				return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$table} ORDER BY created_at DESC, id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
			}

			private function sn_commission_find_wallet_transaction_id(int $item_id, int $seller_id, int $invoice_id): int
			{
				global $wpdb;
				$tx = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($tx)) {
					return 0;
				}
				$like = '%' . $wpdb->esc_like('"commission_dry_run_item_id":' . $item_id) . '%';
				$id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$tx} WHERE user_id=%d AND invoice_id=%d AND type='commission_engine' AND meta LIKE %s ORDER BY id DESC LIMIT 1", $seller_id, $invoice_id, $like));
				if ($id) {
					return $id;
				}
				return (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$tx} WHERE user_id=%d AND invoice_id=%d AND type='commission_engine' ORDER BY id DESC LIMIT 1", $seller_id, $invoice_id));
			}

			private function sn_render_commission_dry_run_section(): string
			{
