					<?php $posting_report = get_option('sn_commission_wallet_posting_report', []); if (! empty($posting_report)) : ?><div class="sn-alert sn-alert-info">آخرین ارسال به کیف پول: <?php echo esc_html((string) ($posting_report['message'] ?? $posting_report['status'] ?? '')); ?> | ارسال‌شده=<?php echo esc_html(number_format_i18n((int) ($posting_report['posted'] ?? 0))); ?></div><?php endif; ?>
