			public function handle_commission_save_rule(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_commission_save_rule');
				$this->sn_ensure_commission_tables();
				global $wpdb;
				$table = $wpdb->prefix . 'sn_commission_rules';
				$rule_id = absint($_POST['rule_id'] ?? 0);
				if ($rule_id > 0 && isset($_POST['toggle_active'])) {
					$active = (int) $_POST['toggle_active'] ? 1 : 0;
					$wpdb->update($table, ['is_active' => $active, 'updated_at' => current_time('mysql')], ['id' => $rule_id]);
					update_option('sn_commission_rule_report', ['status' => 'ok', 'message' => $active ? 'قانون فعال شد.' : 'قانون غیرفعال شد.', 'rule_id' => $rule_id], false);
					wp_safe_redirect(wp_get_referer() ?: home_url('/'));
					exit;
				}
				$title = sanitize_text_field(wp_unslash($_POST['title'] ?? ''));
				if ($title === '') {
					update_option('sn_commission_rule_report', ['status' => 'error', 'message' => 'عنوان قانون الزامی است.'], false);
					wp_safe_redirect(wp_get_referer() ?: home_url('/'));
					exit;
				}
				$data = [
					'rule_code' => $this->sn_commission_rule_code(),
					'title' => $title,
					'description' => sanitize_textarea_field(wp_unslash($_POST['description'] ?? '')),
					'applies_to_position' => sanitize_key(wp_unslash($_POST['applies_to_position'] ?? '')),
					'applies_to_level' => sanitize_key(wp_unslash($_POST['applies_to_level'] ?? '')),
					'payment_method' => sanitize_key(wp_unslash($_POST['payment_method'] ?? '')),
					'invoice_status' => sanitize_text_field(wp_unslash($_POST['invoice_status'] ?? '')),
					'employment_status' => sanitize_key(wp_unslash($_POST['employment_status'] ?? '')),
					'employment_type' => $this->sn_normalize_commission_employment_type(sanitize_text_field(wp_unslash($_POST['employment_type'] ?? ''))),
					'calculation_type' => $this->sn_commission_normalize_calculation_type(sanitize_text_field(wp_unslash($_POST['calculation_type'] ?? 'invoice_percent_fixed'))),
					'rate_percent' => max(0, (float) ($_POST['rate_percent'] ?? 0)),
					'fixed_amount' => max(0, (float) ($_POST['fixed_amount'] ?? 0)),
					'daily_base_amount' => ($_POST['daily_base_amount'] ?? '') === '' ? null : max(0, (float) $_POST['daily_base_amount']),
					'attendance_first_before' => $this->sn_commission_time_value(sanitize_text_field(wp_unslash($_POST['attendance_first_before'] ?? '10:30')), '10:30:00'),
					'attendance_last_after' => $this->sn_commission_time_value(sanitize_text_field(wp_unslash($_POST['attendance_last_after'] ?? '15:00')), '15:00:00'),
					'min_invoice_amount' => ($_POST['min_invoice_amount'] ?? '') === '' ? null : max(0, (float) $_POST['min_invoice_amount']),
					'max_invoice_amount' => ($_POST['max_invoice_amount'] ?? '') === '' ? null : max(0, (float) $_POST['max_invoice_amount']),
					'effective_from' => ($__sn_rule_effective_from = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['effective_from'] ?? '')))) !== '' ? $__sn_rule_effective_from : null,
					'effective_to' => ($__sn_rule_effective_to = SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_POST['effective_to'] ?? '')))) !== '' ? $__sn_rule_effective_to : null,
					'is_active' => ! empty($_POST['is_active']) ? 1 : 0,
					'priority' => (int) ($_POST['priority'] ?? 0),
					'created_at' => current_time('mysql'),
					'updated_at' => current_time('mysql'),
				];
				$wpdb->insert($table, $this->sn_filter_existing_columns($table, $data));
				update_option('sn_commission_rule_report', [
					'status' => $wpdb->insert_id ? 'ok' : 'error',
					'message' => $wpdb->insert_id ? 'قانون پورسانت ساخته شد.' : ('خطا در ساخت قانون: ' . sanitize_text_field((string) $wpdb->last_error)),
					'rule_id' => (int) $wpdb->insert_id,
				], false);
				wp_safe_redirect(wp_get_referer() ?: home_url('/'));
				exit;
			}

			public function handle_commission_run_dry_run(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_commission_run_dry_run');
				$this->sn_ensure_commission_tables();
				global $wpdb;
				$runs_table = $wpdb->prefix . 'sn_commission_dry_runs';
				$items_table = $wpdb->prefix . 'sn_commission_dry_run_items';
				$date_from = sanitize_text_field(wp_unslash($_POST['date_from'] ?? ''));
				$date_to = sanitize_text_field(wp_unslash($_POST['date_to'] ?? ''));
				$date_from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from) ? $date_from : '';
				$date_to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to) ? $date_to : '';
				$filter_position = sanitize_key(wp_unslash($_POST['position'] ?? ''));
				$filter_level = sanitize_key(wp_unslash($_POST['level'] ?? ''));
				$filter_payment = sanitize_key(wp_unslash($_POST['payment_method'] ?? ''));
				$filter_status = sanitize_text_field(wp_unslash($_POST['invoice_status'] ?? 'paid,approved'));
				$filter_seller = absint($_POST['seller_id'] ?? 0);
				$calculation_mode = sanitize_key(wp_unslash($_POST['calculation_mode'] ?? 'all_matching'));
				if (! in_array($calculation_mode, ['all_matching', 'best_match', 'selected_rule'], true)) {
					$calculation_mode = 'all_matching';
				}
				$selected_rule_id = absint($_POST['selected_rule_id'] ?? 0);
				$title = sanitize_text_field(wp_unslash($_POST['title'] ?? ''));
				$run_code = $this->sn_commission_run_code();
				$wpdb->insert($runs_table, [
					'run_code' => $run_code,
					'title' => $title ?: 'پیش‌نمایش پورسانت ' . current_time('mysql'),
					'date_from' => $date_from ?: null,
					'date_to' => $date_to ?: null,
					'status' => 'completed',
					'approval_status' => 'generated',
					'created_by' => get_current_user_id() ?: null,
					'summary_json' => '{}',
					'created_at' => current_time('mysql'),
				]);
				$run_id = (int) $wpdb->insert_id;
				if (! $run_id) {
					update_option('sn_commission_dry_run_report', ['status' => 'error', 'message' => sanitize_text_field((string) $wpdb->last_error)], false);
					wp_safe_redirect(wp_get_referer() ?: home_url('/'));
					exit;
				}

				$invoice_cols = $this->sn_table_columns($wpdb->prefix . 'sn_invoices');
				$where = ['1=1'];
				$args = [];
				if ($date_from !== '') { $where[] = 'i.created_at >= %s'; $args[] = $date_from . ' 00:00:00'; }
				if ($date_to !== '') { $where[] = 'i.created_at <= %s'; $args[] = $date_to . ' 23:59:59'; }
				if ($filter_seller > 0) { $where[] = 'i.seller_id=%d'; $args[] = $filter_seller; }
				if ($filter_status !== '') {
					$statuses = array_values(array_filter(array_map('sanitize_key', array_map('trim', explode(',', $filter_status)))));
					if ($statuses) {
						$where[] = 'i.status IN (' . implode(',', array_fill(0, count($statuses), '%s')) . ')';
						$args = array_merge($args, $statuses);
					}
				}
				$args[] = 1000;
				$sql = "SELECT i.* FROM {$wpdb->prefix}sn_invoices i WHERE " . implode(' AND ', $where) . " ORDER BY i.id ASC LIMIT %d";
				$invoices = $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
				$daily_attendance_groups = [];
				$summary = [
					'calculation_mode' => $calculation_mode,
					'selected_rule_id' => $selected_rule_id,
					'total_items' => 0,
					'matched' => 0,
					'no_rule' => 0,
					'without_seller' => 0,
					'without_amount' => 0,
					'history_used' => 0,
					'history_missing' => 0,
					'commission_disabled_by_history' => 0,
					'calculated_total' => 0,
					'legacy_total' => 0,
					'difference_total' => 0,
					'by_payment_method' => [],
					'by_employment_type' => [],
					'issued_by_other_user' => 0,
					'daily_attendance_candidates' => 0,
					'daily_attendance_qualified' => 0,
					'daily_attendance_total' => 0,
				];
				foreach ($invoices as $invoice_row) {
					$context = $this->sn_resolve_invoice_commission_context((int) ($invoice_row['id'] ?? 0), $invoice_row);
					if ($filter_payment !== '' && (string) ($context['payment_method_normalized'] ?? '') !== $filter_payment) { continue; }
					if ($filter_position !== '' && (string) ($context['seller_hr_position'] ?? '') !== $filter_position) { continue; }
					if ($filter_level !== '' && (string) ($context['seller_hr_level'] ?? '') !== $filter_level) { continue; }
					$matcher = $this->sn_find_matching_commission_rule($context);
					$all_matched_rules = (array) ($matcher['matched_rules'] ?? []);
					$matched_rules = $all_matched_rules;
					if ($calculation_mode === 'best_match') {
						$matched_rules = $all_matched_rules ? [$all_matched_rules[0]] : [];
					} elseif ($calculation_mode === 'selected_rule') {
						$matched_rules = [];
						if ($selected_rule_id > 0) {
							foreach ($all_matched_rules as $candidate_rule) {
								if ((int) ($candidate_rule['id'] ?? 0) === $selected_rule_id) {
									$matched_rules = [$candidate_rule];
									break;
								}
							}
						}
					}
					$matched_rule = $matched_rules[0] ?? null;
					$warning_code = '';
					if ($calculation_mode === 'selected_rule' && $selected_rule_id < 1) { $warning_code = 'selected_rule_required'; }
					if ($calculation_mode === 'selected_rule' && $selected_rule_id > 0 && ! $matched_rules && $all_matched_rules) { $warning_code = 'selected_rule_not_matching_invoice_context'; }
					$rule_source = $matched_rules ? ('commission_rules_' . $calculation_mode) : '';
					if (! empty($context['compensation_history_id'])) { $summary['history_used']++; } elseif ((int) ($context['seller_id'] ?? 0) > 0) { $summary['history_missing']++; $warning_code = 'no_compensation_history'; }
					$matched_rules = $this->sn_commission_apply_hr_override_to_rules($context, $matched_rules);
					$matched_rule = $matched_rules[0] ?? null;
					if (($context['commission_override_mode'] ?? 'inherit') === 'disabled') {
						$warning_code = 'commission_disabled_by_manual_override';
						$summary['commission_disabled_by_history']++;
					}
					foreach ($matched_rules as $daily_candidate_rule) {
						$this->sn_commission_collect_daily_attendance_candidate($daily_attendance_groups, $context, $daily_candidate_rule);
					}
					$amount = (float) ($context['invoice_total'] ?? 0);
					$component_result = $this->sn_commission_calculate_rule_components($matched_rules, $amount);
					$calculated = (float) ($component_result['total'] ?? 0);
					$seller_id = (int) ($context['seller_id'] ?? 0);
					$legacy = $seller_id > 0 ? $this->sn_commission_legacy_for_invoice((int) $context['invoice_id'], $seller_id) : null;
					$difference = $legacy === null ? null : $calculated - (float) $legacy;
					$item_status = $matched_rules ? 'matched' : 'no_rule';
					if (! $seller_id) { $item_status = 'missing_seller'; $summary['without_seller']++; }
					if ($amount <= 0) { $item_status = 'missing_amount'; $summary['without_amount']++; }
					if ($item_status === 'matched') { $summary['matched']++; } elseif ($item_status === 'no_rule') { $summary['no_rule']++; }
					$summary['total_items']++;
					$summary['calculated_total'] += $calculated;
					if ($legacy !== null) { $summary['legacy_total'] += (float) $legacy; }
					if ($difference !== null) { $summary['difference_total'] += $difference; }
					$pm = (string) ($context['payment_method_normalized'] ?? 'unknown');
					$et = (string) (($context['seller_employment_type'] ?? '') ?: 'unknown');
					$summary['by_payment_method'][$pm] = (int) ($summary['by_payment_method'][$pm] ?? 0) + 1;
					$summary['by_employment_type'][$et] = (int) ($summary['by_employment_type'][$et] ?? 0) + 1;
					if ((int) ($context['issued_by_user_id'] ?? 0) > 0 && (int) ($context['issued_by_user_id'] ?? 0) !== $seller_id) { $summary['issued_by_other_user']++; }
					$warning_note = $warning_code ?: ($matched_rules ? '' : (implode(',', array_merge((array) ($context['diagnostics'] ?? []), (array) ($matcher['diagnostics'] ?? []))) ?: 'no active matching rule'));
					$notes = [
						'mode' => 'dry_run_only',
						'calculation_date' => (string) ($context['calculation_date'] ?? ''),
						'compensation_history_id' => (int) ($context['compensation_history_id'] ?? 0),
						'payment_method_normalized' => $pm,
						'employment_type' => $et,
						'issued_by_user_id' => (int) ($context['issued_by_user_id'] ?? 0),
						'rule_source' => $rule_source,
						'warning_code' => $warning_note,
						'calculation_mode' => $calculation_mode,
						'selected_rule_id' => $selected_rule_id,
						'all_candidate_rule_ids' => array_values(array_map(static fn($rule) => (int) ($rule['id'] ?? 0), $all_matched_rules)),
						'stack_mode' => $calculation_mode,
						'matched_rule_ids' => array_values(array_map(static fn($rule) => (int) ($rule['id'] ?? 0), $matched_rules)),
						'commission_components' => (array) ($component_result['components'] ?? []),
						'rejected_rules' => array_slice((array) ($matcher['rejected_rules'] ?? []), 0, 12),
					];
					$wpdb->insert($items_table, $this->sn_filter_existing_columns($items_table, [
						'run_id' => $run_id,
						'invoice_id' => (int) $context['invoice_id'],
						'invoice_code' => (string) $context['invoice_code'],
						'seller_user_id' => $seller_id,
						'issued_by_user_id' => (int) ($context['issued_by_user_id'] ?? 0),
						'seller_position' => (string) ($context['seller_hr_position'] ?? ''),
						'seller_level' => (string) ($context['seller_hr_level'] ?? ''),
						'employment_type' => $et,
						'invoice_amount' => $amount,
						'payment_method' => $pm,
						'invoice_status' => (string) ($context['invoice_status'] ?? ''),
						'matched_rule_id' => $matched_rule ? (int) $matched_rule['id'] : null,
						'calculated_commission' => $calculated,
						'legacy_commission' => $legacy,
						'difference_amount' => $difference,
						'item_status' => $item_status,
						'notes' => wp_json_encode($notes, JSON_UNESCAPED_UNICODE),
						'posting_status' => 'pending',
						'compensation_history_id' => (int) ($context['compensation_history_id'] ?? 0) ?: null,
						'compensation_effective_from' => ! empty($context['compensation_history']['effective_from']) ? (string) $context['compensation_history']['effective_from'] : null,
						'compensation_effective_to' => ! empty($context['compensation_history']['effective_to']) ? (string) $context['compensation_history']['effective_to'] : null,
						'rule_source' => $rule_source,
						'warning_code' => $warning_code ?: null,
						'calculation_date' => (string) ($context['calculation_date'] ?? ''),
						'created_at' => current_time('mysql'),
					]));
				}


				foreach ($daily_attendance_groups as $group) {
					$summary['daily_attendance_candidates']++;
					$rule = (array) ($group['rule'] ?? []);
					$daily_amount = round(max(0, (float) ($rule['daily_base_amount'] ?? 0)), 2);
					if ($daily_amount <= 0 || ! $this->sn_commission_daily_attendance_group_qualifies($group)) {
						continue;
					}
					$summary['daily_attendance_qualified']++;
					$summary['daily_attendance_total'] += $daily_amount;
					$summary['calculated_total'] += $daily_amount;
					$summary['total_items']++;
					$summary['matched']++;
					$daily_notes = [
						'mode' => 'daily_attendance_bonus',
						'calculation_date' => (string) ($group['date'] ?? ''),
						'first_invoice_time' => (string) ($group['first_time'] ?? ''),
						'last_invoice_time' => (string) ($group['last_time'] ?? ''),
						'first_invoice_id' => (int) ($group['first_invoice_id'] ?? 0),
						'last_invoice_id' => (int) ($group['last_invoice_id'] ?? 0),
						'invoice_count' => (int) ($group['invoice_count'] ?? 0),
						'attendance_first_before' => $this->sn_commission_time_value($rule['attendance_first_before'] ?? '', '10:30:00'),
						'attendance_last_after' => $this->sn_commission_time_value($rule['attendance_last_after'] ?? '', '15:00:00'),
						'daily_base_amount' => (float) ($rule['daily_base_amount'] ?? 0),
						'matched_rule_ids' => [(int) ($rule['id'] ?? 0)],
						'commission_components' => [[
							'rule_id' => (int) ($rule['id'] ?? 0),
							'rule_title' => (string) ($rule['title'] ?? ('#' . (int) ($rule['id'] ?? 0))),
							'calculation_type' => 'daily_attendance_plus_percent',
							'rate_percent' => 0,
							'fixed_amount' => 0,
							'daily_base_amount' => (float) ($rule['daily_base_amount'] ?? 0),
							'commission' => $daily_amount,
						]],
					];
					$wpdb->insert($items_table, $this->sn_filter_existing_columns($items_table, [
						'run_id' => $run_id,
						'invoice_id' => (int) ($group['last_invoice_id'] ?? 0),
						'invoice_code' => 'DAILY-' . (string) ($group['date'] ?? '') . '-' . (int) ($group['seller_id'] ?? 0),
						'seller_user_id' => (int) ($group['seller_id'] ?? 0),
						'issued_by_user_id' => (int) ($group['seller_id'] ?? 0),
						'seller_position' => (string) ($group['seller_position'] ?? ''),
						'seller_level' => (string) ($group['seller_level'] ?? ''),
						'employment_type' => (string) ($group['employment_type'] ?? 'unknown'),
						'invoice_amount' => 0,
						'payment_method' => 'daily_attendance',
						'invoice_status' => 'daily_bonus',
						'matched_rule_id' => (int) ($rule['id'] ?? 0) ?: null,
						'calculated_commission' => $daily_amount,
						'legacy_commission' => null,
						'difference_amount' => null,
						'item_status' => 'daily_attendance_bonus',
						'notes' => wp_json_encode($daily_notes, JSON_UNESCAPED_UNICODE),
						'posting_status' => 'pending',
						'compensation_history_id' => ! empty($group['compensation_history_id']) ? (int) $group['compensation_history_id'] : null,
						'compensation_effective_from' => $group['compensation_effective_from'] ?? null,
						'compensation_effective_to' => $group['compensation_effective_to'] ?? null,
						'rule_source' => 'commission_rules_daily_attendance',
						'warning_code' => null,
						'calculation_date' => (string) ($group['date'] ?? ''),
						'created_at' => current_time('mysql'),
					]));
				}

				$wpdb->update($runs_table, ['summary_json' => wp_json_encode($summary, JSON_UNESCAPED_UNICODE)], ['id' => $run_id]);
				update_option('sn_commission_dry_run_report', array_merge(['status' => 'ok', 'run_id' => $run_id, 'run_code' => $run_code], $summary), false);
				wp_safe_redirect(add_query_arg('sn_commission_run_id', (string) $run_id, wp_get_referer() ?: home_url('/')) . '#sn-commission-preview');
				exit;
			}

			public function handle_commission_review_run(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_commission_review_run');
				$this->sn_ensure_commission_tables();
				global $wpdb;
				$run_id = absint($_POST['run_id'] ?? 0);
				$review_action = sanitize_key(wp_unslash($_POST['review_action'] ?? ''));
				$confirm = strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_word'] ?? '')));
				$note = sanitize_textarea_field(wp_unslash($_POST['approval_note'] ?? ''));
				$run = $this->sn_commission_run($run_id);
				$report = ['status' => 'error', 'run_id' => $run_id, 'message' => 'پیش‌نمایش یافت نشد.'];
				if ($run) {
					$current = (string) ($run['approval_status'] ?? 'generated');
					if ($review_action === 'approve' && $confirm === 'APPROVE' && ! in_array($current, ['approved'], true)) {
						$data = ['approval_status' => 'approved', 'approved_by' => get_current_user_id() ?: null, 'approved_at' => current_time('mysql'), 'approval_note' => $note, 'locked_at' => current_time('mysql')];
						$wpdb->update($wpdb->prefix . 'sn_commission_dry_runs', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_commission_dry_runs', $data), ['id' => $run_id]);
						$this->sn_commission_log($run_id, null, 'commission_run_approved', 'approved', ['approval_status' => $current], $data, $note);
						$report = ['status' => 'ok', 'run_id' => $run_id, 'message' => 'پیش‌نمایش تایید و قفل شد. کیف پول تغییری نکرد.'];
					} elseif ($review_action === 'reject' && $confirm === 'REJECT' && $current !== 'approved') {
						$data = ['approval_status' => 'rejected', 'rejected_by' => get_current_user_id() ?: null, 'rejected_at' => current_time('mysql'), 'approval_note' => $note, 'locked_at' => current_time('mysql')];
						$wpdb->update($wpdb->prefix . 'sn_commission_dry_runs', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_commission_dry_runs', $data), ['id' => $run_id]);
						$this->sn_commission_log($run_id, null, 'commission_run_rejected', 'rejected', ['approval_status' => $current], $data, $note);
						$report = ['status' => 'ok', 'run_id' => $run_id, 'message' => 'پیش‌نمایش رد شد و قابل ارسال به کیف پول نیست.'];
					} else {
						$report = ['status' => 'error', 'run_id' => $run_id, 'message' => 'کلمه تایید یا وضعیت پیش‌نمایش معتبر نیست.'];
					}
				}
				update_option('sn_commission_review_report', $report, false);
				wp_safe_redirect(add_query_arg('sn_commission_run_id', (string) $run_id, wp_get_referer() ?: home_url('/')) . '#sn-commission-preview');
				exit;
			}

			public function handle_commission_save_posting_flag(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_commission_save_posting_flag');
				update_option('sn_enable_commission_wallet_posting', ! empty($_POST['enable_posting']) ? '1' : '0', false);
				update_option('sn_commission_wallet_posting_report', ['status' => 'ok', 'message' => 'کلید فعال‌سازی ذخیره شد.', 'enabled' => ! empty($_POST['enable_posting'])], false);
				wp_safe_redirect((wp_get_referer() ?: home_url('/')) . '#sn-commission-preview');
				exit;
			}

			public function handle_commission_post_wallet(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_commission_post_wallet');
				$this->sn_ensure_commission_tables();
				global $wpdb;
				$run_id = absint($_POST['run_id'] ?? 0);
				$confirm = strtoupper(sanitize_text_field(wp_unslash($_POST['confirm_apply'] ?? '')));
				$note = sanitize_textarea_field(wp_unslash($_POST['posting_note'] ?? ''));
				$report = ['status' => 'error', 'run_id' => $run_id, 'posted' => 0, 'skipped' => 0, 'errors' => 0, 'message' => 'ارسال به کیف پول اجرا نشد.'];
				$run = $this->sn_commission_run($run_id);
				if (! $run) {
					$report['message'] = 'پیش‌نمایش یافت نشد.';
				} elseif (! $this->sn_commission_posting_enabled()) {
					$report['message'] = 'کلید فعال‌سازی ارسال به کیف پول غیرفعال است.';
				} elseif ($confirm !== 'APPLY') {
					$report['message'] = 'برای ارسال به کیف پول باید APPLY وارد شود.';
				} elseif ((string) ($run['approval_status'] ?? '') !== 'approved') {
					$report['message'] = 'فقط پیش‌نمایش تاییدشده قابل ارسال به کیف پول است.';
				} else {
					$items_table = $wpdb->prefix . 'sn_commission_dry_run_items';
					$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$items_table} WHERE run_id=%d ORDER BY id ASC LIMIT 2000", $run_id), ARRAY_A) ?: [];
					$posted = 0; $skipped = 0; $errors = 0;
					foreach ($items as $item) {
						$item_id = (int) $item['id'];
						$seller_id = (int) ($item['seller_user_id'] ?? 0);
						$invoice_id = (int) ($item['invoice_id'] ?? 0);
						$amount = (float) ($item['calculated_commission'] ?? 0);
						if (! $seller_id || $amount <= 0 || ! empty($item['wallet_transaction_id']) || in_array((string) ($item['posting_status'] ?? ''), ['posted'], true)) {
							$skipped++;
							continue;
						}
						$existing_tx = $this->sn_commission_find_wallet_transaction_id($item_id, $seller_id, $invoice_id);
						if ($existing_tx) {
							$wpdb->update($items_table, ['wallet_transaction_id' => $existing_tx, 'posted_at' => current_time('mysql'), 'posting_status' => 'posted', 'posting_error' => null], ['id' => $item_id]);
							$this->sn_commission_log($run_id, $item_id, 'commission_wallet_posting_idempotent_hit', 'posted', null, ['wallet_transaction_id' => $existing_tx], 'existing transaction linked', $existing_tx);
							$skipped++;
							continue;
						}
						$wallet_note_prefix = (string) ($item['item_status'] ?? '') === 'daily_attendance_bonus' ? 'حقوق روزانه مشروط موتور پورسانت برای ' : 'پورسانت تاییدشده موتور جدید برای فاکتور ';
						$ok = $this->sn_add_wallet_transaction($seller_id, 'seller', $amount, 'credit', 'commission_engine', $wallet_note_prefix . (string) ($item['invoice_code'] ?? $invoice_id), $invoice_id ?: null, null, [
							'commission_run_id' => $run_id,
							'commission_dry_run_item_id' => $item_id,
							'matched_rule_id' => (int) ($item['matched_rule_id'] ?? 0),
							'note' => $note,
						]);
						$tx_id = $ok ? $this->sn_commission_find_wallet_transaction_id($item_id, $seller_id, $invoice_id) : 0;
						if ($ok && $tx_id) {
							$wpdb->update($items_table, ['wallet_transaction_id' => $tx_id, 'posted_at' => current_time('mysql'), 'posting_status' => 'posted', 'posting_error' => null], ['id' => $item_id]);
							$this->sn_commission_log($run_id, $item_id, 'commission_wallet_posted', 'posted', null, ['wallet_transaction_id' => $tx_id, 'amount' => $amount], $note, $tx_id);
							$posted++;
						} else {
							$error = $wpdb->last_error ? sanitize_text_field((string) $wpdb->last_error) : 'wallet_transaction_not_created';
							$wpdb->update($items_table, ['posting_status' => 'error', 'posting_error' => $error], ['id' => $item_id]);
							$this->sn_commission_log($run_id, $item_id, 'commission_wallet_post_error', 'error', null, ['error' => $error], $error);
							$errors++;
						}
					}
					$report = ['status' => $errors ? 'partial' : 'ok', 'run_id' => $run_id, 'posted' => $posted, 'skipped' => $skipped, 'errors' => $errors, 'message' => $errors ? 'ارسال با خطا/هشدار تمام شد.' : 'ارسال کنترل‌شده انجام شد.'];
				}
				update_option('sn_commission_wallet_posting_report', $report, false);
				wp_safe_redirect(add_query_arg('sn_commission_run_id', (string) $run_id, wp_get_referer() ?: home_url('/')) . '#sn-commission-preview');
				exit;
			}



			private function render_financial_approval_table(bool $wrap = true): void
			{
				global $wpdb;
				$this->sn_ensure_payment_migrations();
				$review_statuses_sql = "'pending_financial_approval','receipt_uploaded'";
				$rows = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE status IN ({$review_statuses_sql}) OR payment_status IN ({$review_statuses_sql}) OR invoice_status IN ({$review_statuses_sql}) ORDER BY updated_at DESC, id DESC LIMIT 300");
				$can_approve = $this->sn_can_approve_payment();
				$can_reject = $this->sn_can_reject_payment();
				if ($wrap) {
					echo '<div class="wrap" dir="rtl"><h1>تایید مالی پرداخت‌ها</h1>';
				}
				echo '<table class="widefat striped sn-table"><thead><tr><th>کد</th><th>مشتری</th><th>مبلغ</th><th>نوع پرداخت / منبع</th><th>فیش / اطلاعات واریز</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>';
				if (! $rows) {
					echo '<tr><td colspan="7">پرداختی برای بررسی وجود ندارد.</td></tr>';
				}
				foreach ($rows as $r) {
					$jalali = isset($r->manual_paid_at_jalali) ? (string) $r->manual_paid_at_jalali : '';
					$receipt_url = ! empty($r->receipt_url) ? (string) $r->receipt_url : (string) ($r->receipt_file ?? '');
					$manual_from = (string) ($r->manual_card_from ?: ($r->deposit_card_from_last4 ?? ''));
					$manual_to = $this->sn_manual_destination_card_display($r);
					$manual_amount = (string) ($r->manual_amount ?: ($r->deposit_amount ?? ''));
					$manual_jalali = $jalali ?: (string) ($r->deposit_jalali_datetime ?? '');
					$info = $receipt_url
						? SN_Helpers::receipt_links($r) . ($manual_to !== '' ? '<br><small>کارت مقصد: <span dir="ltr">' . esc_html($manual_to) . '</span></small>' : '')
						: esc_html(trim($manual_from . ' → ' . $manual_to . ' / ' . $manual_amount . ' / ' . ($manual_jalali ?: SN_Helpers::gregorian_to_jalali_date((string) $r->manual_paid_at))));
					$source = SN_Helpers::payment_source_label((string) ($r->payment_source ?: ($r->receipt_source ?? '')));
					$effective_status = in_array((string) ($r->payment_status ?? ''), ['pending_financial_approval', 'receipt_uploaded'], true) ? (string) $r->payment_status : (in_array((string) ($r->invoice_status ?? ''), ['pending_financial_approval', 'receipt_uploaded'], true) ? (string) $r->invoice_status : (string) $r->status);
					$is_dot_marketing = (int) ($r->seller_id ?? 0) > 0 && (string) get_user_meta((int) $r->seller_id, '_sn_dot_marketing_seller', true) === '1';
					$invoice_code_html = '<strong>' . esc_html($r->invoice_code) . '</strong>' . ($is_dot_marketing ? '<br><span class="sn-fin-legacy-dot-tag">مارکتینگ دات فلو</span>' : '');
					echo '<tr><td>' . $invoice_code_html . '</td><td>' . esc_html($r->customer_name . ' - ' . $r->customer_phone) . '</td><td>' . esc_html(SN_Helpers::format_price((float) $r->product_price)) . '</td><td>' . esc_html(SN_Helpers::pay_method_label((string) $r->pay_method) . ' / ' . $source) . '</td><td>' . $info . '</td><td>' . esc_html(SN_Helpers::status_label($effective_status)) . '</td><td>';
					if (in_array($effective_status, ['pending_financial_approval', 'receipt_uploaded'], true)) {
						if ($can_approve) {
							echo '<button class="button button-primary sn-fin-approve" data-id="' . esc_attr($r->id) . '">تایید</button> ';
						}
						if ($can_reject) {
							echo '<button class="button sn-fin-reject" data-id="' . esc_attr($r->id) . '">رد</button>';
						}
					}
					echo '</td></tr>';
				}
				echo '</tbody></table>';
				if ($wrap) {
					echo '</div>';
				}
			}

			public function ajax_supervisor_invoices(): void
			{
				// 1.0.124: emergency-safe endpoint. The broad 1.0.123 invoice scope could build very heavy OR/EXISTS queries and trigger 504.
				// Keep the tab Ajax-based, but use bounded indexed queries and merge scope sources in PHP instead of one huge SQL condition.
				if (function_exists('set_time_limit')) { @set_time_limit(25); }
				if (! is_user_logged_in()) {
					SN_Helpers::send_json(false, 'وارد نشده‌اید');
					return;
				}
				$valid = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
				if (! $valid) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}

				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_table_exists_quiet($table)) {
					SN_Helpers::send_json(true, '', ['items' => [], 'has_more' => false, 'scope' => 'no_invoice_table']);
					return;
				}

				$user = wp_get_current_user();
				$actor_id = (int) $user->ID;
				$viewer_position = class_exists('SN_Scope_Service') ? (new SN_Scope_Service())->get_viewer_position_slug($actor_id) : $this->sn_hr_position_for_user($actor_id);
				$can_read_supervisor_invoice_context = in_array('sn_supervisor', (array) $user->roles, true)
					|| current_user_can('sn_view_sales_reports')
					|| current_user_can('manage_options')
					|| in_array($viewer_position, ['supervisor', 'senior_supervisor', 'sales_manager'], true);
				if (! $can_read_supervisor_invoice_context) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}

				$q = sanitize_text_field(wp_unslash($_POST['q'] ?? ''));
				$invoice_tab = sanitize_key(wp_unslash($_POST['tab'] ?? 'all'));
				$status_filter = sanitize_key(wp_unslash($_POST['status_filter'] ?? ''));
				if ($status_filter !== '' && $status_filter !== 'all') { $invoice_tab = $status_filter; }
				$date_from_raw = sanitize_text_field(wp_unslash($_POST['date_from'] ?? ''));
				$date_to_raw = sanitize_text_field(wp_unslash($_POST['date_to'] ?? ''));
				$date_from_g = $date_from_raw !== '' ? SN_Helpers::jalali_to_gregorian_date($date_from_raw) : '';
				$date_to_g = $date_to_raw !== '' ? SN_Helpers::jalali_to_gregorian_date($date_to_raw) : '';
				$limit = max(10, min(50, absint($_POST['limit'] ?? 50)));
				$cols = $this->sn_table_columns($table);
				$dot_links_table = $wpdb->prefix . 'sn_dot_invoice_links';
				$dot_cases_table = $wpdb->prefix . 'sn_dot_cases';
				$has_dot_cases = $this->sn_table_exists_quiet($dot_links_table) && $this->sn_table_exists_quiet($dot_cases_table);

				$cache_key = 'sn_sup_inv_scope_124_' . $actor_id . '_' . md5($viewer_position . '|' . implode(',', (array) $user->roles));
				$scope_cache = get_transient($cache_key);
				if (is_array($scope_cache)) {
					$seller_ids = array_map('intval', (array) ($scope_cache['seller_ids'] ?? []));
				} else {
					$seller_ids = [];
					if (! current_user_can('manage_options')) {
						// HR descendants/direct sellers. Cached because this can be recursive on larger hierarchies.
						$seller_ids = array_merge($seller_ids, array_map('intval', $this->sn_get_seller_ids_in_hr_scope($actor_id)));
						if ($viewer_position === 'sales_manager' || current_user_can('sn_view_sales_reports')) {
							$seller_ids = array_merge($seller_ids, array_map('intval', $this->sn_sales_manager_scope_seller_ids($actor_id)));
						}
						if (in_array('sn_supervisor', (array) $user->roles, true) || $viewer_position === 'supervisor') {
							$legacy_meta_sellers = get_users([
								'role' => 'sn_seller',
								'fields' => 'ID',
								'number' => 1000,
								'meta_key' => 'sn_supervisor_id',
								'meta_value' => $actor_id,
							]);
							$seller_ids = array_merge($seller_ids, array_map('intval', (array) $legacy_meta_sellers));
							if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
								$lead_seller_ids = $wpdb->get_col($wpdb->prepare("SELECT DISTINCT seller_id FROM {$wpdb->prefix}sn_leads WHERE supervisor_id=%d AND seller_id IS NOT NULL AND seller_id>0 LIMIT 1000", $actor_id));
								$seller_ids = array_merge($seller_ids, array_map('intval', (array) $lead_seller_ids));
							}
						}
					}
					$seller_ids = array_values(array_unique(array_filter(array_map('intval', $seller_ids))));
					if (count($seller_ids) > 1000) { $seller_ids = array_slice($seller_ids, 0, 1000); }
					set_transient($cache_key, ['seller_ids' => $seller_ids], 120);
				}

				$status_condition = static function(string $tab, array $cols, array &$args) use ($has_dot_cases): string {
					if (in_array($tab, ['staged_completed','staged_incomplete'], true)) {
						$staged = $has_dot_cases ? "((dl.id IS NOT NULL AND dl.payment_kind IN ('deposit','balance')) OR (dl.id IS NULL AND (i.payment_plan='partial' OR i.current_payment_stage>1)))" : "(i.payment_plan='partial' OR i.current_payment_stage>1)";
						$complete = $has_dot_cases ? "((dl.id IS NOT NULL AND COALESCE(c.selected_option_price,0)>0 AND COALESCE(c.paid_amount,0)>=c.selected_option_price-0.5) OR (dl.id IS NULL AND i.status IN ('paid','approved') AND i.payment_workflow_status='completed' AND COALESCE(i.remaining_amount,0)<=0.5))" : "(i.status IN ('paid','approved') AND i.payment_workflow_status='completed' AND COALESCE(i.remaining_amount,0)<=0.5)";
						return $staged . ' AND ' . ($tab === 'staged_completed' ? $complete : 'NOT ' . $complete);
					}
					$status_fields = array_values(array_intersect(['status', 'invoice_status', 'payment_status'], $cols));
					$make_status = static function(array $statuses, array $fields, array &$a): string {
						if (! $fields || ! $statuses) { return '1=1'; }
						$parts = [];
						foreach ($fields as $field) {
							$parts[] = "i.{$field} IN (" . implode(',', array_fill(0, count($statuses), '%s')) . ')';
							$a = array_merge($a, $statuses);
						}
						return '(' . implode(' OR ', $parts) . ')';
					};
					if ($tab === 'pre_invoice') { return $make_status(['pre_invoice', 'pending', 'pending_payment', 'partial_paid'], $status_fields, $args); }
					if ($tab === 'online_paid') {
						$parts = [$make_status(['paid', 'approved', 'financial_approved', 'gateway_paid', 'online_paid'], $status_fields, $args)];
						if (in_array('pay_method', $cols, true)) { $parts[] = "i.pay_method IN ('online','gateway')"; }
						if (in_array('payment_source', $cols, true)) { $parts[] = "i.payment_source IN ('gateway','online')"; }
						return '(' . implode(' OR ', $parts) . ')';
					}
					if ($tab === 'receipt_uploaded') {
						$parts = [$make_status(['receipt_uploaded', 'pending_financial_approval', 'needs_finance_review'], $status_fields, $args)];
						foreach (['receipt_url', 'receipt_file'] as $receipt_col) {
							if (in_array($receipt_col, $cols, true)) { $parts[] = "(i.{$receipt_col} IS NOT NULL AND i.{$receipt_col}<>'')"; }
						}
						return '(' . implode(' OR ', $parts) . ')';
					}
					if ($tab === 'needs_review') { return $make_status(['pending_financial_approval', 'receipt_uploaded', 'needs_finance_review'], $status_fields, $args); }
					if ($tab === 'rejected') { return $make_status(['rejected', 'financial_rejected'], $status_fields, $args); }
					return '1=1';
				};

				$run_query = function(array $scope_where, array $scope_args, int $take) use ($wpdb, $table, $cols, $q, $invoice_tab, $status_condition, $date_from_g, $date_to_g, $has_dot_cases, $dot_links_table, $dot_cases_table): array {
					$take = max(1, min(51, $take));
					$where = $scope_where;
					$args = $scope_args;
					if ($date_from_g !== '' && in_array('created_at', $cols, true)) {
						$where[] = 'i.created_at >= %s';
						$args[] = $date_from_g . ' 00:00:00';
					}
					if ($date_to_g !== '' && in_array('created_at', $cols, true)) {
						$where[] = 'i.created_at <= %s';
						$args[] = $date_to_g . ' 23:59:59';
					}
					if ($q !== '') {
						$like = '%' . $wpdb->esc_like($q) . '%';
						$search_parts = [];
						foreach (['invoice_code', 'customer_name', 'customer_phone'] as $search_col) {
							if (in_array($search_col, $cols, true)) { $search_parts[] = "i.{$search_col} LIKE %s"; $args[] = $like; }
						}
						if ($search_parts) { $where[] = '(' . implode(' OR ', $search_parts) . ')'; }
					}
					$where[] = $status_condition($invoice_tab, $cols, $args);
					if (in_array('created_at', $cols, true)) {
							$order = 'i.created_at DESC, i.id DESC';
						} elseif (in_array('approved_at', $cols, true)) {
							$order = 'i.approved_at DESC, i.id DESC';
						} elseif (in_array('paid_at', $cols, true)) {
							$order = 'i.paid_at DESC, i.id DESC';
						} elseif (in_array('updated_at', $cols, true)) {
							$order = 'i.updated_at DESC, i.id DESC';
						} else {
							$order = in_array('id', $cols, true) ? 'i.id DESC' : '1';
						}
					$hr_table = $wpdb->prefix . 'sn_hr_profiles';
					$join_hr = $wpdb->get_var("SHOW TABLES LIKE '{$hr_table}'") === $hr_table;
					$seller_expr = $join_hr ? "COALESCE(NULLIF(hp.hr_display_name,''), u.display_name, CONCAT('#', i.seller_id))" : "COALESCE(u.display_name, CONCAT('#', i.seller_id))";
					$join = "LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id";
					if ($join_hr) { $join .= " LEFT JOIN {$hr_table} hp ON hp.user_id=i.seller_id AND hp.is_active=1"; }
					if ($has_dot_cases && in_array($invoice_tab, ['staged_completed','staged_incomplete'], true)) {
						$join .= " LEFT JOIN {$dot_links_table} dl ON dl.invoice_id=i.id AND dl.flow_kind='conversion_payment' LEFT JOIN {$dot_cases_table} c ON c.id=dl.case_id";
					}
					$sql = "SELECT /* SN124_SUP_INV_FAST */ i.*, {$seller_expr} seller_name FROM {$table} i {$join} WHERE " . implode(' AND ', $where) . " ORDER BY {$order} LIMIT %d";
					$args[] = $take;
					return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
				};

				$rows_by_id = [];
				$append_rows = static function(array $rows) use (&$rows_by_id): void {
					foreach ($rows as $row) {
						$id = (int) ($row['id'] ?? 0);
						if ($id > 0 && ! isset($rows_by_id[$id])) { $rows_by_id[$id] = $row; }
					}
				};

				if (current_user_can('manage_options')) {
					$append_rows($run_query(['1=1'], [], $limit + 1));
				} else {
					if ($seller_ids && in_array('seller_id', $cols, true)) {
						$append_rows($run_query(['i.seller_id IN (' . implode(',', array_fill(0, count($seller_ids), '%d')) . ')'], $seller_ids, $limit + 1));
					}
					// Cheap fallback for invoices created directly by the supervisor/manager. Separate query avoids a huge OR condition.
					if (count($rows_by_id) < $limit + 1 && in_array('issued_by_user_id', $cols, true)) {
						$append_rows($run_query(['i.issued_by_user_id=%d'], [$actor_id], ($limit + 1) - count($rows_by_id)));
					}
					// Marketing Dot pre-invoices belong to a protected system seller. Add
					// their exact source-link scope so they appear immediately even while
					// the short seller-scope cache is still warm.
					if (count($rows_by_id) < $limit + 1 && class_exists('SN_Dot_Flow')) {
						$dot_invoice_ids = SN_Dot_Flow::instance()->source_invoice_ids_for_supervisor($actor_id, 250);
						if ($dot_invoice_ids) {
							$append_rows($run_query(['i.id IN (' . implode(',', array_fill(0, count($dot_invoice_ids), '%d')) . ')'], $dot_invoice_ids, ($limit + 1) - count($rows_by_id)));
						}
					}
					// Only when the user searches, include older/alternate seller columns. This keeps default tab load safe.
					if ($q !== '' && count($rows_by_id) < $limit + 1 && $seller_ids) {
						foreach (['original_seller_id', 'commission_seller_id', 'seller_user_id', 'sales_user_id', 'lead_seller_id', 'assigned_seller_id'] as $alt_col) {
							if (! in_array($alt_col, $cols, true) || count($rows_by_id) >= $limit + 1) { continue; }
							$append_rows($run_query(["i.{$alt_col} IN (" . implode(',', array_fill(0, count($seller_ids), '%d')) . ')'], $seller_ids, ($limit + 1) - count($rows_by_id)));
						}
					}
				}

				$rows = array_values($rows_by_id);
				usort($rows, static function($a, $b) {
						$date_cols = ['created_at', 'approved_at', 'paid_at', 'updated_at'];
						$ta = 0; $tb = 0;
						foreach ($date_cols as $dc) { if (! empty($a[$dc])) { $ta = SN_Helpers::site_mysql_timestamp((string) $a[$dc], 0); break; } }
						foreach ($date_cols as $dc) { if (! empty($b[$dc])) { $tb = SN_Helpers::site_mysql_timestamp((string) $b[$dc], 0); break; } }
						if ($ta !== $tb) { return $tb <=> $ta; }
						return (int) ($b['id'] ?? 0) <=> (int) ($a['id'] ?? 0);
					});
				$has_more = count($rows) > $limit;
				if ($has_more) { $rows = array_slice($rows, 0, $limit); }
				$gift_states = class_exists('SN_Dot_Flow')
					? SN_Dot_Flow::instance()->invoice_gift_states(array_column($rows, 'id'), $actor_id)
					: [];
				$project_results = class_exists('SN_Projects')
					? SN_Projects::instance()->project_summaries_for_invoices(array_column($rows, 'id'), $actor_id)
					: [];
				$dot_payment_cases = [];
				if ($rows && $has_dot_cases) {
					$invoice_ids = array_values(array_filter(array_map('intval', array_column($rows, 'id'))));
					if ($invoice_ids) {
						$case_rows = $wpdb->get_results($wpdb->prepare(
							"SELECT dl.invoice_id,c.selected_option_price,c.paid_amount FROM {$dot_links_table} dl INNER JOIN {$dot_cases_table} c ON c.id=dl.case_id WHERE dl.flow_kind='conversion_payment' AND dl.invoice_id IN (" . implode(',', array_fill(0, count($invoice_ids), '%d')) . ')',
							...$invoice_ids
						), ARRAY_A) ?: [];
						foreach ($case_rows as $case_row) { $dot_payment_cases[(int) $case_row['invoice_id']] = $case_row; }
					}
				}

				foreach ($rows as &$r) {
					$effective_status = (string) (($r['payment_status'] ?? '') ?: (($r['invoice_status'] ?? '') ?: ($r['status'] ?? '')));
					// Keep database values untouched and expose presentation-only dates.
					// Invoice rows are shared by the supervisor and sales-manager panels;
					// formatting them here guarantees Jalali dates and Tehran time in both.
					foreach (['created_at', 'approved_at', 'paid_at', 'updated_at', 'date'] as $date_field) {
						$r[$date_field . '_jalali'] = SN_Helpers::gregorian_to_jalali_date((string) ($r[$date_field] ?? ''));
					}
					$r['can_upload_receipt'] = $this->sn_supervisor_can_upload_receipt_for_status($r);
					$r['can_submit_manual_payment'] = $r['can_upload_receipt'];
					$r['status_label'] = SN_Helpers::status_label($effective_status);
					$r['pay_method_label'] = SN_Helpers::pay_method_label((string) ($r['pay_method'] ?? ''));
					$r['payment_source_label'] = SN_Helpers::payment_source_label((string) ($r['payment_source'] ?? ($r['receipt_source'] ?? '')));
					$r['amount_fmt'] = SN_Helpers::format_price((float) (($r['final_total'] ?? 0) ?: ($r['product_price'] ?? 0)));
					$r['payment_summary'] = $this->sn_invoice_payment_totals((object) $r);
					if (isset($dot_payment_cases[(int) $r['id']])) {
						$case_row = $dot_payment_cases[(int) $r['id']];
						$total = max((float) $case_row['selected_option_price'], (float) $r['payment_summary']['total']);
						$paid = min($total, max(0, (float) $case_row['paid_amount']));
						$r['payment_summary']['total'] = $total;
						$r['payment_summary']['paid'] = $paid;
						$r['payment_summary']['remaining'] = max(0, $total - $paid);
					}
					$r['has_access_token'] = ! empty($r['access_token']);
					$gift_state = (array) ($gift_states[(int) ($r['id'] ?? 0)] ?? []);
					$r['is_dot_assessment'] = ! empty($gift_state['is_dot_assessment']);
					$r['validation_gifted'] = ! empty($gift_state['validation_gifted']);
					$r['validation_gifted_at'] = (string) ($gift_state['validation_gifted_at'] ?? '');
					$r['validation_gift_sms_sent_at'] = (string) ($gift_state['validation_gift_sms_sent_at'] ?? '');
					$r['validation_gift_sms_delivered'] = ! empty($gift_state['sms_delivered']);
					$giftable_statuses = ['pre_invoice','pending','pending_payment','rejected','recontact_requested'];
					$r['can_gift_validation'] = ! empty($gift_state['can_manage_gift'])
						&& empty($gift_state['validation_gifted'])
						&& empty($gift_state['case_id'])
						&& in_array(sanitize_key($effective_status), $giftable_statuses, true)
						&& (float) ($r['paid_total_amount'] ?? 0) <= 0.5
						&& empty($r['paid_at'])
						&& empty($r['approved_at']);
					$r['can_resend_gift_validation'] = ! empty($gift_state['can_manage_gift'])
						&& ! empty($gift_state['validation_gifted'])
						&& empty($gift_state['sms_delivered']);
					$r['project'] = $project_results[(int) ($r['id'] ?? 0)] ?? null;
					unset($r['access_token']);
				}
				unset($r);

				SN_Helpers::send_json(true, '', [
					'items' => $rows,
					'has_more' => $has_more,
					'scope_seller_count' => count($seller_ids),
					'scope_mode' => 'safe_fast_124',
				]);
			}

			public function render_financial_approval_page(): void
			{
				if (! $this->sn_can_view_finance()) {
					wp_die('دسترسی غیرمجاز');
				}
				$this->render_financial_approval_table(true);
			}

			public function ensure_finance_role(): void
			{
				if ((string) get_option('sn_finance_roles_version', '') === SN_VERSION) { return; }
				if ($this->sn_defer_heavy_admin_runtime()) { return; }
				if (! get_role('sn_financial_approval')) {
					add_role('sn_financial_approval', 'تایید مالی', [
						'read' => true,
					]);
				}
				if (! get_role('sn_financial')) {
					add_role('sn_financial', 'تایید مالی', [
						'read' => true,
					]);
				}
				if (! get_role('sn_finance')) {
					add_role('sn_finance', 'مالی', ['read' => true]);
				}
				foreach (['sn_financial_approval', 'sn_financial', 'sn_finance'] as $role_key) {
					$role = get_role($role_key);
					if (! $role) {
						continue;
					}
					$role->add_cap('read');
					foreach (['sn_view_payments', 'sn_approve_payments', 'sn_reject_payments', 'sn_view_finance', 'sn_approve_payment', 'sn_reject_payment', 'sn_view_wallet_commission'] as $cap) {
						$role->remove_cap($cap);
					}
				}
				$this->sn_migrate_finance_user_caps();
				update_option('sn_finance_roles_version', SN_VERSION, false);
			}

			private function sn_migrate_finance_user_caps(): void
			{
				if (get_option('sn_finance_user_caps_migrated')) {
					return;
				}
				$users = get_users(['role__in' => ['sn_financial', 'sn_financial_approval', 'sn_finance'], 'fields' => 'all']);
				foreach ($users as $user) {
					if (! $user instanceof WP_User) {
						continue;
					}
					$user->add_cap('sn_view_finance');
					$user->add_cap('sn_approve_payment');
					$user->add_cap('sn_reject_payment');
				}
				update_option('sn_finance_user_caps_migrated', current_time('mysql'), false);
			}


			// =========================================================
			// HELPER
			// =========================================================

			private function is_supervisor(): bool
			{
				$user = wp_get_current_user();
				return is_user_logged_in() && in_array('sn_supervisor', (array) $user->roles, true);
			}

			public function ensure_after_sales_role(): void
			{
				if ((string) get_option('sn_after_sales_role_version', '') === SN_VERSION) { return; }
				if ($this->sn_defer_heavy_admin_runtime()) { return; }
				if (! get_role('sn_after_sales')) {
					add_role('sn_after_sales', 'خدمات پس از فروش', ['read' => true, 'sn_view_customer_profiles' => true]);
				}
				$role = get_role('sn_after_sales');
				if ($role) {
					$role->add_cap('read');
					$role->add_cap('sn_view_customer_profiles');
					foreach (['edit_posts', 'delete_posts', 'publish_posts', 'upload_files', 'edit_pages', 'delete_pages', 'manage_options', 'list_users', 'create_users', 'edit_users', 'delete_users'] as $cap) {
						$role->remove_cap($cap);
					}
				}
				update_option('sn_after_sales_role_version', SN_VERSION, false);
			}

			public function ensure_sales_manager_role(): void
			{
				if ((string) get_option('sn_sales_manager_role_version', '') === SN_VERSION) { return; }
				if ($this->sn_defer_heavy_admin_runtime()) { return; }
				if (! get_role('sn_sales_manager')) {
					add_role('sn_sales_manager', 'مدیر فروش', [
						'read' => true,
						'sn_view_sales_reports' => true,
						'sn_manage_supervisor_leads' => true,
						'sn_export_sales_reports' => true,
					]);
				}
				$role = get_role('sn_sales_manager');
				if ($role) {
					foreach (['read', 'sn_view_sales_reports', 'sn_manage_supervisor_leads', 'sn_export_sales_reports'] as $cap) {
						$role->add_cap($cap);
					}
					foreach (['edit_posts', 'delete_posts', 'publish_posts', 'upload_files', 'edit_pages', 'delete_pages', 'manage_options', 'list_users', 'create_users', 'edit_users', 'delete_users'] as $cap) {
						$role->remove_cap($cap);
					}
				}
				update_option('sn_sales_manager_role_version', SN_VERSION, false);
			}

			private function sn_is_sales_manager(): bool
			{
				$user = wp_get_current_user();
				return is_user_logged_in() && in_array('sn_sales_manager', (array) $user->roles, true);
			}

			private function sn_can_manage_supervisor_leads(): bool
			{
				return current_user_can('manage_options') || current_user_can('sn_manage_supervisor_leads');
			}

			private function sn_can_view_customer_profiles(): bool
			{
				if (current_user_can('manage_options') || current_user_can('sn_view_customer_profiles') || $this->sn_can_view_finance()) {
					return true;
				}
				return $this->sn_customer_visible_seller_ids() !== [];
			}

			private function sn_can_access_after_sales_panel(): bool
			{
				if (current_user_can('manage_options')) {
					return true;
				}
				if (! is_user_logged_in()) {
					return false;
				}
				$user = wp_get_current_user();
				if (in_array('sn_after_sales', (array) $user->roles, true) || current_user_can('sn_view_customer_profiles')) {
					return true;
				}
				return class_exists('SN_Scope_Service') && (new SN_Scope_Service())->get_viewer_position_slug(get_current_user_id()) === 'after_sales';
			}

			private function sn_after_sales_tables_ready(): bool
			{
				global $wpdb;
				return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->prefix . 'sn_after_sales_cases')) === $wpdb->prefix . 'sn_after_sales_cases'
					&& $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->prefix . 'sn_after_sales_case_logs')) === $wpdb->prefix . 'sn_after_sales_case_logs';
			}

