			private function sn_after_sales_log(int $case_id, string $action, $old_value = null, $new_value = null, string $note = ''): void
			{
				global $wpdb;
				if (! $this->sn_after_sales_tables_ready()) {
					return;
				}
				$wpdb->insert($wpdb->prefix . 'sn_after_sales_case_logs', [
					'case_id' => $case_id,
					'actor_user_id' => get_current_user_id() ?: null,
					'action' => sanitize_key($action),
					'old_value' => $old_value === null ? null : wp_json_encode($old_value, JSON_UNESCAPED_UNICODE),
					'new_value' => $new_value === null ? null : wp_json_encode($new_value, JSON_UNESCAPED_UNICODE),
					'note' => sanitize_textarea_field($note),
					'created_at' => current_time('mysql'),
				]);
			}

			private function sn_after_sales_generate_case_code(): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_after_sales_cases';
				do {
					$code = 'ASC-' . SN_Helpers::tehran_format('Ymd') . '-' . strtoupper(substr(wp_generate_password(6, false, false), 0, 6));
				} while ((int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE case_code=%s", $code)) > 0);
				return $code;
			}

			private function sn_after_sales_users(): array
			{
				global $wpdb;
				$ids = [];
				if ($this->sn_after_sales_tables_ready() && class_exists('SN_HR_Service')) {
					$ids = array_map('intval', (array) $wpdb->get_col("SELECT hp.user_id FROM {$wpdb->prefix}sn_hr_profiles hp INNER JOIN {$wpdb->prefix}sn_hr_positions p ON p.id=hp.position_id WHERE p.slug='after_sales' AND hp.is_active=1 ORDER BY hp.user_id ASC"));
				}
				foreach (get_users(['role' => 'sn_after_sales', 'fields' => 'ID']) as $id) {
					$ids[] = (int) $id;
				}
				$ids = array_values(array_unique(array_filter($ids)));
				return $ids;
			}

			private function sn_after_sales_summary(): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_after_sales_cases';
				if (! $this->sn_after_sales_tables_ready()) {
					return [];
				}
				$today = SN_Helpers::tehran_today_gregorian();
				return [
					'کل پرونده‌ها' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table}"),
					'باز' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE case_status='open'"),
					'در حال پیگیری' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE case_status='in_progress'"),
					'در انتظار مشتری' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE case_status='waiting_customer'"),
					'حل‌شده' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE case_status='resolved'"),
					'سررسید گذشته' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE due_at IS NOT NULL AND due_at < %s AND case_status NOT IN ('resolved','closed','archived')", $today . ' 00:00:00')),
					'سررسید امروز' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE due_at >= %s AND due_at <= %s", $today . ' 00:00:00', $today . ' 23:59:59')),
					'پرونده‌های من' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE assigned_after_sales_user_id=%d", get_current_user_id())),
					'فاکتورهای paid/approved اخیر' => $this->sn_after_sales_recent_paid_invoice_count(),
				];
			}

			private function sn_after_sales_recent_paid_invoice_count(): int
			{
				global $wpdb;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $invoice_table)) !== $invoice_table) {
					return 0;
				}
				return (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoice_table} WHERE status IN ('paid','approved') AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)");
			}

			private function sn_after_sales_filters(): array
			{
				return [
					'status' => sanitize_key(wp_unslash($_GET['as_status'] ?? '')),
					'priority' => sanitize_key(wp_unslash($_GET['as_priority'] ?? '')),
					'assigned_user' => absint($_GET['as_assigned_user'] ?? 0),
					'seller' => absint($_GET['as_seller'] ?? 0),
					'invoice_code' => sanitize_text_field(wp_unslash($_GET['as_invoice_code'] ?? '')),
					'phone' => sanitize_text_field(wp_unslash($_GET['as_phone'] ?? '')),
					'date_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['as_date_from'] ?? ''))),
					'date_to' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET['as_date_to'] ?? ''))),
				];
			}

			private function sn_after_sales_case_where(array $filters): array
			{
				global $wpdb;
				$where = ['1=1'];
				$args = [];
				if ($filters['status'] !== '') { $where[] = 'c.case_status=%s'; $args[] = $filters['status']; }
				if ($filters['priority'] !== '') { $where[] = 'c.priority=%s'; $args[] = $filters['priority']; }
				if ($filters['assigned_user']) { $where[] = 'c.assigned_after_sales_user_id=%d'; $args[] = $filters['assigned_user']; }
				if ($filters['seller']) { $where[] = 'c.seller_user_id=%d'; $args[] = $filters['seller']; }
				if ($filters['invoice_code'] !== '') { $where[] = 'c.invoice_code LIKE %s'; $args[] = '%' . $wpdb->esc_like($filters['invoice_code']) . '%'; }
				if ($filters['phone'] !== '') {
					$phone = SN_Helpers::normalize_mobile($filters['phone']);
					$where[] = '(c.normalized_phone LIKE %s OR c.customer_phone LIKE %s)';
					$args[] = '%' . $wpdb->esc_like($phone ?: $filters['phone']) . '%';
					$args[] = '%' . $wpdb->esc_like($filters['phone']) . '%';
				}
				if ($filters['date_from'] !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['date_from'])) { $where[] = 'c.created_at >= %s'; $args[] = $filters['date_from'] . ' 00:00:00'; }
				if ($filters['date_to'] !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $filters['date_to'])) { $where[] = 'c.created_at <= %s'; $args[] = $filters['date_to'] . ' 23:59:59'; }
				return [implode(' AND ', $where), $args];
			}

			private function sn_after_sales_case_rows(array $filters, int $limit = 100): array
			{
				global $wpdb;
				if (! $this->sn_after_sales_tables_ready()) {
					return [];
				}
				[$where, $args] = $this->sn_after_sales_case_where($filters);
				$sql = "SELECT c.*, seller.display_name seller_name, assigned.display_name assigned_name
					FROM {$wpdb->prefix}sn_after_sales_cases c
					LEFT JOIN {$wpdb->users} seller ON seller.ID=c.seller_user_id
					LEFT JOIN {$wpdb->users} assigned ON assigned.ID=c.assigned_after_sales_user_id
					WHERE {$where}
					ORDER BY c.updated_at DESC, c.id DESC
					LIMIT %d";
				$args[] = $limit;
				return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
			}

			private function sn_after_sales_logs(int $limit = 100): array
			{
				global $wpdb;
				if (! $this->sn_after_sales_tables_ready()) {
					return [];
				}
				return $wpdb->get_results($wpdb->prepare(
					"SELECT l.*, c.case_code, u.display_name actor_name FROM {$wpdb->prefix}sn_after_sales_case_logs l LEFT JOIN {$wpdb->prefix}sn_after_sales_cases c ON c.id=l.case_id LEFT JOIN {$wpdb->users} u ON u.ID=l.actor_user_id ORDER BY l.id DESC LIMIT %d",
					$limit
				), ARRAY_A) ?: [];
			}

			private function sn_after_sales_safe_log_value($value): string
			{
				if ($value === null || $value === '') {
					return '—';
				}
				$decoded = json_decode((string) $value, true);
				if (json_last_error() === JSON_ERROR_NONE) {
					return $this->sn_after_sales_format_safe_log_data($this->sn_after_sales_sanitize_log_data($decoded));
				}
				return $this->sn_after_sales_mask_sensitive_text((string) $value);
			}

			private function sn_after_sales_sanitize_log_data($data)
			{
				if (is_array($data)) {
					$safe = [];
					foreach ($data as $key => $value) {
						$key_string = is_string($key) ? $key : (string) $key;
						$key_lc = strtolower($key_string);
						if (strpos($key_lc, 'access_token') !== false || strpos($key_lc, 'token') !== false || strpos($key_lc, 'public_invoice_url') !== false || strpos($key_lc, 'invoice_url') !== false || strpos($key_lc, 'password') !== false || strpos($key_lc, 'hash') !== false) {
							$safe[$key_string] = '[hidden]';
							continue;
						}
						if (strpos($key_lc, 'phone') !== false || strpos($key_lc, 'mobile') !== false) {
							$safe[$key_string] = $this->sn_mask_phone((string) $value);
							continue;
						}
						$safe[$key_string] = $this->sn_after_sales_sanitize_log_data($value);
					}
					return $safe;
				}
				if (is_scalar($data)) {
					return $this->sn_after_sales_mask_sensitive_text((string) $data);
				}
				return '';
			}

			private function sn_after_sales_format_safe_log_data($data): string
			{
				if (! is_array($data)) {
					return (string) $data;
				}
				$parts = [];
				foreach ($data as $key => $value) {
					$label = is_string($key) ? $key : (string) $key;
					if (is_array($value)) {
						$value = $this->sn_after_sales_format_safe_log_data($value);
					}
					$parts[] = $label . ': ' . (string) $value;
				}
				return implode(' | ', array_slice($parts, 0, 30));
			}

			private function sn_after_sales_mask_sensitive_text(string $text): string
			{
				$text = preg_replace('/https?:\/\/[^\s"\']+/i', '[hidden-url]', $text);
				$text = preg_replace('/(access_token|token)=([^&\s"\']+)/i', '$1=[hidden]', (string) $text);
				return (string) preg_replace_callback('/(?<!\d)(?:\+?98|0)?9\d{9}(?!\d)/', function($matches) {
					return $this->sn_mask_phone((string) $matches[0]);
				}, (string) $text);
			}

			private function sn_after_sales_candidates(int $limit = 20): array
			{
				global $wpdb;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$case_table = $wpdb->prefix . 'sn_after_sales_cases';
				if (! $this->sn_after_sales_tables_ready() || $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $invoice_table)) !== $invoice_table) {
					return [];
				}
				return $wpdb->get_results($wpdb->prepare(
					"SELECT i.id, i.invoice_code, i.customer_name, i.customer_phone, i.seller_id, i.status, i.product_price, i.final_total, i.created_at
					FROM {$invoice_table} i
					LEFT JOIN {$case_table} c ON (c.invoice_id=i.id OR (c.invoice_code IS NOT NULL AND c.invoice_code=i.invoice_code))
					WHERE i.status IN ('paid','approved') AND c.id IS NULL
					ORDER BY i.id DESC LIMIT %d",
					$limit
				), ARRAY_A) ?: [];
			}

