			public function handle_export_report_csv(): void
			{
			if ( ! current_user_can( 'manage_options' ) ) { wp_die( 'خروجی قدیمی فقط برای مدیر مجاز است.', '', [ 'response' => 403 ] ); }
				if (! is_user_logged_in() || ! $this->sn_can_view_reports_panel()) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_export_report_csv');
				$type = sanitize_key(wp_unslash($_GET['report_type'] ?? ''));
				$allowed = ['successful_payments', 'leads', 'invoices', 'payments', 'wallet', 'commission', 'hr_profiles', 'after_sales', 'mis_summary'];
				if (! in_array($type, $allowed, true)) {
					wp_die('نوع خروجی نامعتبر است');
				}
				$filters = $this->sn_report_filters();
				$this->sn_csv_header('sales-network-' . $type . '-' . SN_Helpers::tehran_format('Y-m-d') . '.csv');
				$out = fopen('php://output', 'w');
				$rows = $this->sn_export_report_rows($type, $filters, 5000);
				$headers = $this->sn_export_report_headers($type);
				fputcsv($out, $headers);
				foreach ($rows as $row) {
					$line = [];
					foreach (array_keys($headers) as $key) {
						$line[] = $this->sn_csv_safe_cell((string) ($row[$key] ?? ''));
					}
					fputcsv($out, $line);
				}
				exit;
			}

