			private function sn_successful_payment_report_type_labels(): array
			{
				$labels = class_exists('SN_Seller_Flow') ? SN_Seller_Flow::product_types() : [];
				return is_array($labels) ? $labels : [];
			}

			private function sn_successful_payment_report_sql(array $filters): array
			{
				global $wpdb;
				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$payment_table = $wpdb->prefix . 'sn_payments';
				$item_table = $wpdb->prefix . 'sn_invoice_items';
				$items_ready = $this->sn_table_exists_quiet($item_table);
				$payments_ready = $this->sn_table_exists_quiet($payment_table);
				$success_values = "'paid','approved','verified','success','completed','financial_approved','gateway_paid','online_paid'";
				$invoice_success = "(i.status IN ({$success_values}) OR i.invoice_status IN ({$success_values}) OR i.payment_status IN ({$success_values}) OR i.payment_workflow_status='completed' OR i.payment_completed_at IS NOT NULL OR i.paid_at IS NOT NULL)";
				$product_names_sql = $items_ready
					? "COALESCE((SELECT GROUP_CONCAT(CONCAT(ii.product_name, CASE WHEN COALESCE(ii.qty,1)>1 THEN CONCAT(' × ',ii.qty) ELSE '' END) ORDER BY ii.id SEPARATOR '، ') FROM {$item_table} ii WHERE ii.invoice_id=i.id),'')"
					: "''";
				$product_types_sql = $items_ready
					? "COALESCE((SELECT GROUP_CONCAT(DISTINCT NULLIF(ii.product_type,'') ORDER BY ii.product_type SEPARATOR ',') FROM {$item_table} ii WHERE ii.invoice_id=i.id),'')"
					: "''";
				$append_filters = function(string $date_expr, bool $has_payment_alias) use ($filters, $items_ready, $item_table, $wpdb): array {
					[$scope_sql, $scope_args] = $this->sn_report_seller_sql('i.seller_id', $filters);
					$where = $scope_sql;
					$args = $scope_args;
					if (! empty($filters['date_from'])) { $where .= " AND {$date_expr} >= %s"; $args[] = $filters['date_from'] . ' 00:00:00'; }
					if (! empty($filters['date_to'])) { $where .= " AND {$date_expr} <= %s"; $args[] = $filters['date_to'] . ' 23:59:59'; }
					$pay_method = sanitize_key((string)($filters['pay_method'] ?? ''));
					if ($pay_method !== '') {
						$method_expr = $has_payment_alias ? "COALESCE(NULLIF(p.pay_method,''),i.pay_method)" : 'i.pay_method';
						$where .= " AND {$method_expr}=%s";
						$args[] = $pay_method;
					}
					$product_type = sanitize_key((string)($filters['product_type'] ?? ''));
					if ($product_type !== '' && $items_ready) {
						$where .= " AND EXISTS (SELECT 1 FROM {$item_table} fit WHERE fit.invoice_id=i.id AND fit.product_type=%s)";
						$args[] = $product_type;
					}
					$q = trim((string)($filters['q'] ?? ''));
					if ($q !== '') {
						$like = '%' . $wpdb->esc_like($q) . '%';
						$parts = ['i.invoice_code LIKE %s','i.customer_name LIKE %s','i.customer_phone LIKE %s'];
						$args = array_merge($args, [$like,$like,$like]);
						if ($items_ready) { $parts[] = "EXISTS (SELECT 1 FROM {$item_table} fiq WHERE fiq.invoice_id=i.id AND fiq.product_name LIKE %s)"; $args[] = $like; }
						$where .= ' AND (' . implode(' OR ', $parts) . ')';
					}
					return [$where, $args];
				};

				$selects = [];
				$args = [];
				if ($payments_ready) {
					$payment_date = 'COALESCE(p.updated_at,p.created_at,i.payment_completed_at,i.approved_at,i.paid_at,i.created_at)';
					[$where, $where_args] = $append_filters($payment_date, true);
					$selects[] = "SELECT p.id payment_id,p.payment_stage_no stage_no,i.id invoice_id,i.invoice_code,i.customer_name,i.customer_phone,i.product_id,i.seller_id,u.display_name seller_name,p.amount,p.status payment_status,COALESCE(NULLIF(p.pay_method,''),i.pay_method) pay_method,COALESCE(NULLIF(p.payment_source,''),i.payment_source) payment_source,{$payment_date} payment_at,{$product_names_sql} product_names,{$product_types_sql} product_types,'payment' row_source FROM {$payment_table} p INNER JOIN {$invoice_table} i ON i.id=p.invoice_id LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id WHERE p.status IN ({$success_values}) {$where}";
					$args = array_merge($args, $where_args);
				}
				$fallback_date = 'COALESCE(i.payment_completed_at,i.approved_at,i.paid_at,i.financial_reviewed_at,i.updated_at,i.created_at)';
				[$where, $where_args] = $append_filters($fallback_date, false);
				$not_exists = $payments_ready ? " AND NOT EXISTS (SELECT 1 FROM {$payment_table} px WHERE px.invoice_id=i.id AND px.status IN ({$success_values}))" : '';
				$selects[] = "SELECT 0 payment_id,COALESCE(i.current_payment_stage,1) stage_no,i.id invoice_id,i.invoice_code,i.customer_name,i.customer_phone,i.product_id,i.seller_id,u.display_name seller_name,COALESCE(NULLIF(i.paid_total_amount,0),NULLIF(i.payment_total_amount,0),NULLIF(i.final_total,0),i.product_price,0) amount,COALESCE(NULLIF(i.payment_status,''),NULLIF(i.invoice_status,''),i.status) payment_status,i.pay_method,i.payment_source,{$fallback_date} payment_at,{$product_names_sql} product_names,{$product_types_sql} product_types,'invoice_fallback' row_source FROM {$invoice_table} i LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id WHERE {$invoice_success}{$not_exists} {$where}";
				$args = array_merge($args, $where_args);
				return ['sql' => implode(' UNION ALL ', $selects), 'args' => $args];
			}

			private function sn_successful_payment_report_rows(array $filters, int $limit = 100, int $offset = 0): array
			{
				global $wpdb;
				$parts = $this->sn_successful_payment_report_sql($filters);
				$limit = max(1, min(5000, $limit));
				$offset = max(0, $offset);
				$sql = "SELECT * FROM ({$parts['sql']}) sn_success_payments ORDER BY payment_at DESC,invoice_id DESC,payment_id DESC LIMIT %d OFFSET %d";
				$args = array_merge($parts['args'], [$limit, $offset]);
				$rows = $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
				foreach ($rows as &$row) {
					if (trim((string)($row['product_names'] ?? '')) === '' && ! empty($row['product_id'])) {
						$row['product_names'] = (string)get_the_title((int)$row['product_id']);
					}
				}
				unset($row);
				return $rows;
			}

			private function sn_successful_payment_report_stats(array $filters): array
			{
				global $wpdb;
				$parts = $this->sn_successful_payment_report_sql($filters);
				$sql = "SELECT COUNT(*) payment_count,COALESCE(SUM(amount),0) total_amount,COUNT(DISTINCT NULLIF(customer_phone,'')) unique_customers,COUNT(DISTINCT invoice_id) invoice_count FROM ({$parts['sql']}) sn_success_payments";
				$row = $parts['args'] ? $wpdb->get_row($wpdb->prepare($sql, ...$parts['args']), ARRAY_A) : $wpdb->get_row($sql, ARRAY_A);
				return is_array($row) ? $row : ['payment_count'=>0,'total_amount'=>0,'unique_customers'=>0,'invoice_count'=>0];
			}

			private function sn_successful_payment_report_product_type_label(string $types): string
			{
				$labels = $this->sn_successful_payment_report_type_labels();
				$parts = array_values(array_unique(array_filter(array_map('sanitize_key', explode(',', $types)))));
				if (! $parts) { return 'بدون نوع ثبت‌شده'; }
				return implode('، ', array_map(static fn($type) => (string)($labels[$type] ?? $type), $parts));
			}

			private function sn_render_successful_payments_report(array $filters): void
			{
				$page = max(1, absint($_GET['sn_success_page'] ?? 1));
				$per_page = 100;
				$stats = $this->sn_successful_payment_report_stats($filters);
				$total = (int)($stats['payment_count'] ?? 0);
				$max_page = max(1, (int)ceil($total / $per_page));
				$page = min($page, $max_page);
				$rows = $this->sn_successful_payment_report_rows($filters, $per_page, ($page - 1) * $per_page);
				$type_labels = $this->sn_successful_payment_report_type_labels();
				$date_from_value = (string)($filters['date_from_raw'] ?? '');
				$date_to_value = (string)($filters['date_to_raw'] ?? '');
				$export_url = $this->sn_report_export_url('successful_payments', $filters);
				?>
				<div class="sn-card sn-section sn-successful-payments-report">
					<div class="sn-card-head"><div><h3>پرداخت‌های موفق</h3><p class="sn-note">تمام پرداخت‌های موفق ثبت‌شده در CRM، شامل پرداخت‌های مرحله‌ای و فاکتورهای موفق قدیمی/دستی که رکورد پرداخت جدا ندارند.</p></div><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url($export_url); ?>">خروجی CSV پرداخت‌های موفق</a></div>
					<form class="sn-filter-bar" method="get">
						<input type="hidden" name="sn_ui_active_tab" value="reports-successful-payments">
						<label>از تاریخ<br><input type="text" class="sn-jalali-date" name="date_from" value="<?php echo esc_attr($date_from_value); ?>" placeholder="1403/02/18"></label>
