			private function sn_reporting_context(): array
			{
				if ( ! is_user_logged_in() ) { return [ null, [] ]; }
				if ( current_user_can( 'manage_options' ) ) { return [ new SN_Report_Executive( $GLOBALS['wpdb'], null, null ), array_keys( SN_Report_Executive::definitions() ) ]; }
				$user_id = (int) get_current_user_id();
				$position = $this->sn_hr_position_for_user( $user_id );
				if ( $position === 'seller' ) { return [ new SN_Report_Executive( $GLOBALS['wpdb'], [ $user_id ], [ $user_id ] ), array_keys( SN_Report_Executive::definitions() ) ]; }
				if ( in_array( $position, [ 'supervisor', 'senior_supervisor', 'sales_manager', 'sales_deputy' ], true ) ) {
					$ids = class_exists( 'SN_Scope_Service' ) ? (new SN_Scope_Service())->scope_visible_seller_ids( $user_id ) : [];
					$recipients = array_merge( [ $user_id ], array_map( 'intval', array_column( $this->sn_get_descendant_users( $user_id ), 'user_id' ) ) );
					return [ new SN_Report_Executive( $GLOBALS['wpdb'], $ids, $recipients ), array_keys( SN_Report_Executive::definitions() ) ];
				}
				if ( $this->sn_can_view_finance() ) { return [ new SN_Report_Executive( $GLOBALS['wpdb'], null, null ), [ 'pre_invoices', 'sales', 'online_sales', 'card_sales', 'finance_pending', 'finance_rejected' ] ]; }
				return [ null, [] ];
			}

			/** Authorized people for the role dropdown. Only query one selected role. */
			private function sn_reporting_people( string $position ): array
			{
				$roles = [ 'seller' => [ 'sn_seller' ], 'supervisor' => [ 'sn_supervisor' ], 'senior_supervisor' => [ 'sn_senior_supervisor' ], 'sales_manager' => [ 'sn_sales_manager' ], 'sales_deputy' => [ 'sn_sales_deputy' ] ];
				if ( ! isset( $roles[$position] ) ) { return []; }
				$options = $this->sn_admin_invoice_user_options( [ $position ], $roles[$position] );
				$allowed = null;
				if ( ! current_user_can( 'manage_options' ) ) {
					$viewer = (int) get_current_user_id();
					$allowed = array_map( 'intval', array_column( $this->sn_get_descendant_users( $viewer ), 'user_id' ) );
					$allowed[] = $viewer;
				}
				$people = [];
				foreach ( $options as $person ) {
					$id = (int) $person->ID;
					if ( $allowed === null || in_array( $id, $allowed, true ) ) { $people[] = [ 'user_id' => $id, 'display_name' => (string)$person->display_name . ' #' . $id ]; }
				}
				return $people;
			}

			private function sn_reporting_selected_scope( SN_Report_Executive $service, array $input ): array
			{
				$raw = $input['sn_hierarchy_role'] ?? '';
				$role = sanitize_key( is_scalar( $raw ) ? wp_unslash( (string)$raw ) : '' );
				$people = $this->sn_reporting_people( $role );
				$id = absint( is_scalar( $input['sn_hierarchy_user'] ?? null ) ? $input['sn_hierarchy_user'] : 0 );
				if ( $id ) {
					$allowed = array_column( $people, 'user_id' );
					if ( ! in_array( $id, array_map( 'intval', $allowed ), true ) ) { return [ $service->under_person( [], [] ), $role, 0, $people ]; }
					$descendants = $role === 'seller' ? [] : $this->sn_get_descendant_users( $id );
					$recipients = array_values( array_unique( array_merge( [ $id ], array_map( 'intval', array_column( $descendants, 'user_id' ) ) ) ) );
					$sellers = $role === 'seller' ? [ $id ] : $this->sn_admin_invoice_seller_ids_for_role_users( [ $id ] );
					return [ $service->under_person( $sellers, $recipients ), $role, $id, $people ];
				}
				return [ $service, $role, 0, $people ];
			}

			private function sn_dashboard_reporting_content(): string
			{
				[ $service ] = $this->sn_reporting_context();
				return $service ? $this->sn_render_reporting_center( true ) : '';
			}

			private function sn_render_reporting_center( bool $dashboard = false ): string
			{
				if ( ! is_user_logged_in() ) { return $this->render_unified_panel_login(); }
				[ $service, $allowed ] = $this->sn_reporting_context();
				if ( ! $service ) { return '<div class="sn-portal" dir="rtl">دسترسی به گزارش‌ها مجاز نیست.</div>'; }
				$definitions = SN_Report_Executive::definitions();
				$raw_type = $_GET['sn_center_type'] ?? 'overview';
				$requested = sanitize_key( is_scalar( $raw_type ) ? wp_unslash( (string) $raw_type ) : 'overview' );
				$overview = $requested === 'overview';
				$type = $overview ? $allowed[0] : $requested;
				if ( ! in_array( $type, $allowed, true ) ) { $type = $allowed[0]; }
				$filters = SN_Report_Executive::filters( $_GET );
				$page = max( 1, absint( $_GET['sn_center_page'] ?? 1 ) );
				[ $service, $hierarchy_role, $hierarchy_user, $people ] = $this->sn_reporting_selected_scope( $service, $_GET );
				$report = $overview ? null : $service->query( $type, $filters, $page );
				if ( $report ) { $report['rows'] = $this->sn_reporting_enrich_rows( $type, $report['rows'] ); }
				$base = get_permalink() ?: ( $this->sn_portal_page_url( 'crm_dashboard' ) ?: home_url( '/crm-dashboard/' ) );
				$params = array_merge( $filters, [ 'sn_center_type' => $type, 'sn_center_mode' => $filters['mode'], 'sn_hierarchy_role' => $hierarchy_role, 'sn_hierarchy_user' => $hierarchy_user ] );
				$export = wp_nonce_url( add_query_arg( array_merge( $params, [ 'action' => 'sn_reporting_export' ] ), admin_url( 'admin-post.php' ) ), 'sn_reporting_export' );
				ob_start(); ?>
				<div id="sn-reports-panel" class="sn-portal sn-reports-panel" dir="rtl">
					<div class="sn-portal-header"><div><h2 class="sn-portal-title">مرکز گزارش‌گیری CRM</h2><p class="sn-portal-subtitle">داده‌های محدودهٔ دسترسی شما؛ انتخاب هر شاخص، ردیف‌های همان گزارش را در این صفحه نشان می‌دهد.</p></div></div>
					<?php if ( ! $overview ) : ?><nav class="sn-report-nav" aria-label="بخش‌های گزارش"><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url( add_query_arg( array_merge( $params, [ 'sn_center_type' => 'overview', 'sn_center_page' => 1 ] ), $base ) ); ?>">همهٔ گزارش‌ها</a><?php foreach ( $allowed as $key ) : ?><a class="sn-btn sn-btn-secondary <?php echo $key === $type ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array_merge( $params, [ 'sn_center_type' => $key, 'sn_center_page' => 1 ] ), $base ) ); ?>"><?php echo esc_html( $definitions[$key]['title'] ); ?></a><?php endforeach; ?></nav><?php endif; ?>
					<form method="get" class="sn-report-filters">
						<input type="hidden" name="sn_center_type" value="<?php echo esc_attr($overview ? 'overview' : $type); ?>">
						<label>نوع گزارش<select name="sn_center_mode"><option value="period" <?php selected($filters['mode'], 'period'); ?>>کل دوره یا بازهٔ زمانی</option><option value="asof" <?php selected($filters['mode'], 'asof'); ?>>وضعیت در لحظه</option></select></label>
						<?php foreach ( [ 'date_from' => 'از تاریخ', 'time_from' => 'از ساعت', 'date_to' => 'تا تاریخ', 'time_to' => 'تا ساعت', 'asof_date' => 'تاریخ لحظه', 'asof_time' => 'ساعت لحظه' ] as $key => $label ) : ?>
						<?php $is_date = in_array($key, ['date_from','date_to','asof_date'], true); $value = $is_date && $filters[$key] ? SN_Helpers::gregorian_to_jalali_input_value((string)$filters[$key]) : (string)$filters[$key]; ?>
						<label class="<?php echo esc_attr(str_starts_with($key, 'asof_') ? 'sn-asof-field' : 'sn-period-field'); ?>"><?php echo esc_html($label); ?><input name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>" <?php echo $is_date ? 'type="text" class="sn-jalali-date" placeholder="1405/07/01"' : 'type="time"'; ?>></label>
						<?php endforeach; ?>
						<?php if ( in_array( $type, [ 'invoices_register', 'customer_profiles', 'customer_invoice_details' ], true ) && ! $overview ) : ?><label>جستجوی مشتری یا فاکتور<input type="search" name="sn_report_search" value="<?php echo esc_attr($filters['report_search']); ?>" placeholder="نام، شماره یا کد"></label><label>وضعیت<select name="sn_report_status"><option value="">همه</option><?php foreach ( [ 'pre_invoice'=>'پیش‌فاکتور', 'pending_financial_approval'=>'انتظار مالی', 'paid'=>'پرداخت‌شده', 'approved'=>'تأییدشده', 'rejected'=>'ردشده', 'cancelled'=>'لغوشده' ] as $status => $label ) : ?><option value="<?php echo esc_attr($status); ?>" <?php selected($filters['report_status'],$status); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><?php endif; ?>
						<label>سمت<select name="sn_hierarchy_role" onchange="this.form.sn_hierarchy_user.value='';this.form.submit()"><option value="">همهٔ افراد مجاز</option><?php foreach ( [ 'sales_deputy'=>'معاون فروش', 'sales_manager'=>'مدیر فروش', 'senior_supervisor'=>'سرپرست ارشد', 'supervisor'=>'سرپرست', 'seller'=>'فروشنده' ] as $position => $name ) : ?><option value="<?php echo esc_attr($position); ?>" <?php selected($hierarchy_role,$position); ?>><?php echo esc_html($name); ?></option><?php endforeach; ?></select></label>
						<label>فرد و زیرمجموعه<select name="sn_hierarchy_user"><option value="">همهٔ افراد مجاز</option><?php foreach ($people as $person) : ?><option value="<?php echo esc_attr((int)$person['user_id']); ?>" <?php selected($hierarchy_user,(int)$person['user_id']); ?>><?php echo esc_html((string)$person['display_name']); ?></option><?php endforeach; ?></select></label>
