					<?php if (!$overview) : ?><p class="sn-note"><?php echo esc_html($report['note']); ?><?php if ($filters['mode'] === 'asof') : ?> برای وضعیت‌های مالی، تاریخچه فقط از زمان فعال‌سازی این نسخه معتبر است.<?php endif; ?></p>
					<?php if ($report['breakdown']) : ?><div class="sn-card sn-section"><h3 class="sn-section-title">تفکیک به تفکیک فرد</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>دریافت‌کننده / فروشنده</th><th>تعداد</th><th>مبلغ</th></tr></thead><tbody><?php foreach ($report['breakdown'] as $person) : ?><tr><td><?php echo esc_html((string)$person['person']); ?></td><td><?php echo esc_html(number_format_i18n((int)$person['total'])); ?></td><td><?php echo esc_html($report['amount'] === null ? '—' : SN_Helpers::format_price((float)$person['amount'])); ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
					<div class="sn-card sn-section"><h3 class="sn-section-title">ریز داده‌ها</h3><?php if ($report['available'] && current_user_can('sn_report_export')) : ?><a class="sn-btn sn-btn-secondary" href="<?php echo esc_url($export); ?>">خروجی CSV</a><?php endif; ?><div class="sn-table-wrap"><table class="sn-table"><thead><tr><?php foreach ($report['headers'] as $label) : ?><th><?php echo esc_html($label); ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($report['rows'] as $row) : ?><tr><?php foreach (array_keys($report['headers']) as $key) : ?><td><?php if ( $type === 'customer_profiles' && $key === 'customer_phone' ) : ?><a href="<?php echo esc_url(add_query_arg(array_merge($params, ['sn_center_type'=>'customer_invoice_details', 'sn_report_search'=>(string)($row['customer_phone'] ?? ''), 'sn_center_page'=>1]), $base)); ?>"><?php echo esc_html($this->sn_reporting_cell($key, (string)($row[$key] ?? ''))); ?></a><?php else : echo esc_html($this->sn_reporting_cell($key, (string)($row[$key] ?? ''))); endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
