			private function sn_reporting_enrich_rows( string $type, array $rows ): array
			{
				if ( ! in_array( $type, [ 'invoices_register', 'customer_profiles', 'customer_invoice_details' ], true ) || ! $rows ) { return $rows; }
				foreach ( $rows as &$item ) {
					if ( $type === 'customer_profiles' ) {
						$labels = [];
						foreach ( explode( '، ', (string)($item['product_ids'] ?? '') ) as $product_id ) {
							$id = absint( $product_id ); if ( ! $id ) { continue; }
							$labels[] = get_the_title( $id ) ?: '#' . $id;
						}
						$item['product_ids'] = implode( '، ', $labels );
					} else { $item['product_label'] = $this->sn_invoice_items_label( (int)($item['id'] ?? 0), (int)($item['product_id'] ?? 0) ); }
				}
				unset( $item );
				if ( $type === 'customer_invoice_details' ) { return $rows; }
				$ids = [];
				foreach ( $rows as $row ) {
					if ( $type === 'customer_profiles' ) { $ids = array_merge( $ids, array_map( 'intval', explode( ',', (string)($row['seller_ids'] ?? '') ) ) ); }
					else { $ids[] = (int)($row['seller_id'] ?? 0); }
				}
				$chains = $this->sn_admin_invoice_hr_chain_map( $ids );
				foreach ( $rows as &$row ) {
					$sellers = $type === 'customer_profiles' ? array_map( 'intval', explode( ',', (string)($row['seller_ids'] ?? '') ) ) : [ (int)($row['seller_id'] ?? 0) ];
					foreach ( [ 'supervisor_name', 'senior_supervisor_name', 'sales_manager_name', 'deputy_name' ] as $field ) {
						$names = [];
						foreach ( $sellers as $seller ) { $name = (string)($chains[$seller][$field] ?? ''); if ( $name !== '' ) { $names[$name] = $name; } }
						$row[$field] = implode( '، ', $names );
					}
				}
				unset( $row );
				return $rows;
			}

			private function sn_reporting_cell( string $key, string $value ): string
			{
				if ( in_array( $key, [ 'phone', 'customer_phone' ], true ) ) { return $this->sn_mask_phone( $value ); }
				if ( str_ends_with( $key, '_at' ) && $value !== '' ) { return SN_Helpers::gregorian_to_jalali_date( $value ); }
				return $value;
			}

			public function sn_reporting_export(): void
			{
				check_admin_referer( 'sn_reporting_export' );
				[ $service, $allowed ] = $this->sn_reporting_context();
				$raw_type = $_GET['sn_center_type'] ?? '';
				$type = sanitize_key( is_scalar( $raw_type ) ? wp_unslash( (string) $raw_type ) : '' );
				if ( ! $service || ! in_array( $type, $allowed, true ) || ! current_user_can( 'sn_report_export' ) ) { wp_die( 'دسترسی غیرمجاز', '', [ 'response' => 403 ] ); }
				[ $service ] = $this->sn_reporting_selected_scope( $service, $_GET );
				$filters = SN_Report_Executive::filters( $_GET );
				$first_page = $service->query( $type, $filters, 1, 500, false );
				if ( ! $first_page['available'] ) { wp_die( esc_html( $first_page['note'] ), '', [ 'response' => 400 ] ); }
				$this->sn_csv_header( 'crm-report-' . $type . '-' . SN_Helpers::tehran_format('Y-m-d') . '.csv' );
				$out = fopen( 'php://output', 'w' );
				$columns = SN_Report_Executive::definitions()[$type]['headers'];
				fputcsv( $out, array_values( $columns ) );
				for ( $page = 1; $page <= 20; $page++ ) {
					$report = $page === 1 ? $first_page : $service->query( $type, $filters, $page, 500, false );
					foreach ( $this->sn_reporting_enrich_rows( $type, $report['rows'] ) as $row ) {
						$line = [];
						foreach ( array_keys( $columns ) as $key ) { $line[] = $this->sn_csv_safe_cell( $this->sn_reporting_cell( $key, (string)($row[$key] ?? '') ) ); }
						fputcsv( $out, $line );
					}
					if ( $page * 500 >= $report['total'] ) { break; }
				}
				exit;
			}

