			private function sn_customer_visible_seller_ids(): ?array
			{
				$user_id = (int) get_current_user_id();
				if (current_user_can('manage_options') || $this->sn_can_view_finance()) {
					return null;
				}
				$position = $this->sn_hr_position_for_user($user_id);
				if (in_array($position, ['after_sales'], true) || current_user_can('sn_view_customer_profiles')) {
					return null;
				}
				if ($position === 'seller') {
					return [$user_id];
				}
				if (class_exists('SN_Scope_Service') && in_array($position, ['sales_deputy', 'sales_manager', 'senior_supervisor', 'supervisor'], true)) {
					return array_values(array_unique(array_map('intval', (new SN_Scope_Service())->scope_visible_seller_ids($user_id))));
				}
				return [];
			}

			private function sn_customer_scope_sql(string $column = 'seller_id'): array
			{
				$ids = $this->sn_customer_visible_seller_ids();
				if ($ids === null) {
					return ['', []];
				}
				$ids = array_values(array_filter(array_map('intval', $ids)));
				if (! $ids) {
					return [' AND 1=0', []];
				}
				return [' AND ' . $column . ' IN (' . implode(',', array_fill(0, count($ids), '%d')) . ')', $ids];
			}

			private function sn_build_customer_context(array $filters): array
			{
				global $wpdb;
				$identity = ['name' => '', 'phone' => '', 'location' => '', 'seller' => ''];
				$phone = '';
				$seed_invoice = null;
				$seed_lead = null;
				[$invoice_scope, $invoice_scope_args] = $this->sn_customer_scope_sql('seller_id');
				[$lead_scope, $lead_scope_args] = $this->sn_customer_scope_sql('seller_id');
				if ($filters['invoice_code'] !== '') {
					$sql = "SELECT id,invoice_code,customer_name,customer_phone,province,city,seller_id FROM {$wpdb->prefix}sn_invoices WHERE invoice_code=%s {$invoice_scope} LIMIT 1";
					$seed_invoice = $wpdb->get_row($wpdb->prepare($sql, ...array_merge([$filters['invoice_code']], $invoice_scope_args)), ARRAY_A);
				}
				if (! $seed_invoice && $filters['lead_id']) {
					$sql = "SELECT id,phone,province,city,seller_id FROM {$wpdb->prefix}sn_leads WHERE id=%d {$lead_scope} LIMIT 1";
					$seed_lead = $wpdb->get_row($wpdb->prepare($sql, ...array_merge([$filters['lead_id']], $lead_scope_args)), ARRAY_A);
				}
				if (! $seed_invoice && ! $seed_lead && $filters['q'] !== '') {
					$like = '%' . $wpdb->esc_like($filters['q']) . '%';
					$sql = "SELECT id,invoice_code,customer_name,customer_phone,province,city,seller_id FROM {$wpdb->prefix}sn_invoices WHERE (invoice_code LIKE %s OR customer_name LIKE %s OR customer_phone LIKE %s OR city LIKE %s) {$invoice_scope} ORDER BY id DESC LIMIT 1";
					$seed_invoice = $wpdb->get_row($wpdb->prepare($sql, ...array_merge([$like, $like, $like, $like], $invoice_scope_args)), ARRAY_A);
					if (! $seed_invoice) {
						$sql = "SELECT id,phone,province,city,seller_id FROM {$wpdb->prefix}sn_leads WHERE (phone LIKE %s OR city LIKE %s OR province LIKE %s OR note LIKE %s) {$lead_scope} ORDER BY id DESC LIMIT 1";
						$seed_lead = $wpdb->get_row($wpdb->prepare($sql, ...array_merge([$like, $like, $like, $like], $lead_scope_args)), ARRAY_A);
					}
				}
				if ($seed_invoice) {
					$phone = SN_Helpers::normalize_mobile((string) $seed_invoice['customer_phone']);
					$identity = [
						'name' => (string) $seed_invoice['customer_name'],
						'phone' => $phone ?: (string) $seed_invoice['customer_phone'],
						'location' => trim((string) ($seed_invoice['province'] ?? '') . ' / ' . (string) ($seed_invoice['city'] ?? ''), ' /'),
						'seller' => ! empty($seed_invoice['seller_id']) ? $this->sn_user_label((int) $seed_invoice['seller_id']) : '',
					];
				} elseif ($seed_lead) {
					$phone = SN_Helpers::normalize_mobile((string) $seed_lead['phone']);
					$identity = [
						'name' => '',
						'phone' => $phone ?: (string) $seed_lead['phone'],
						'location' => trim((string) ($seed_lead['province'] ?? '') . ' / ' . (string) ($seed_lead['city'] ?? ''), ' /'),
						'seller' => ! empty($seed_lead['seller_id']) ? $this->sn_user_label((int) $seed_lead['seller_id']) : '',
					];
				}
				if ($phone === '' && $filters['q'] !== '') {
					$phone = SN_Helpers::normalize_mobile($filters['q']);
				}
				if ($phone === '') {
					return ['found' => false, 'identity' => $identity, 'cards' => [], 'leads' => [], 'invoices' => [], 'payments' => [], 'cases' => [], 'activities' => []];
				}
				$phone_like = '%' . $wpdb->esc_like($phone) . '%';
				$leads_sql = "SELECT l.id,l.phone,l.province,l.city,l.status,l.lead_status,l.seller_id,l.updated_at,l.imported_at,u.display_name seller_name FROM {$wpdb->prefix}sn_leads l LEFT JOIN {$wpdb->users} u ON u.ID=l.seller_id WHERE l.phone LIKE %s {$lead_scope} ORDER BY l.id DESC LIMIT 100";
				$leads = $wpdb->get_results($wpdb->prepare($leads_sql, ...array_merge([$phone_like], $lead_scope_args)), ARRAY_A) ?: [];
				$invoices_sql = "SELECT id,invoice_code,customer_name,customer_phone,province,city,seller_id,status,pay_method,product_price,final_total,created_at,paid_at FROM {$wpdb->prefix}sn_invoices WHERE customer_phone LIKE %s {$invoice_scope} ORDER BY id DESC LIMIT 100";
				$invoices = $wpdb->get_results($wpdb->prepare($invoices_sql, ...array_merge([$phone_like], $invoice_scope_args)), ARRAY_A) ?: [];
				if ($identity['name'] === '' && ! empty($invoices[0]['customer_name'])) { $identity['name'] = (string) $invoices[0]['customer_name']; }
				if ($identity['seller'] === '' && ! empty($invoices[0]['seller_id'])) { $identity['seller'] = $this->sn_user_label((int) $invoices[0]['seller_id']); }
				$invoice_ids = array_values(array_filter(array_map('intval', wp_list_pluck($invoices, 'id'))));
				$payments = $this->sn_customer_payment_rows($invoice_ids);
				$cases = $this->sn_customer_after_sales_rows($phone, $invoice_ids, array_values(array_filter(array_map('intval', wp_list_pluck($leads, 'id')))));
				$activities = $this->sn_customer_activity_rows($invoice_ids);
				$paid_count = 0; $total_amount = 0.0; $paid_amount = 0.0;
				foreach ($invoices as $invoice) {
					$amount = (float) ($invoice['final_total'] ?: $invoice['product_price']);
					$total_amount += $amount;
					if (in_array((string) $invoice['status'], ['paid', 'approved'], true)) { $paid_count++; $paid_amount += $amount; }
				}
				return [
					'found' => true,
					'identity' => $identity,
					'cards' => [
						['label' => 'تعداد لید', 'value' => count($leads)],
						['label' => 'تعداد فاکتور', 'value' => count($invoices)],
						['label' => 'فاکتور paid/approved', 'value' => $paid_count],
						['label' => 'مبلغ کل فاکتورها', 'value' => SN_Helpers::format_price($total_amount)],
						['label' => 'مبلغ پرداخت/تأیید', 'value' => SN_Helpers::format_price($paid_amount)],
						['label' => 'پرونده خدمات', 'value' => count($cases)],
					],
					'leads' => $leads,
					'invoices' => $invoices,
					'payments' => $payments,
					'cases' => $cases,
					'activities' => $activities,
				];
			}

			private function sn_customer_payment_rows(array $invoice_ids): array
			{
				global $wpdb;
				if (! $invoice_ids || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_payments')) {
					return [];
				}
				$ph = implode(',', array_fill(0, count($invoice_ids), '%d'));
				return $wpdb->get_results($wpdb->prepare("SELECT invoice_id,amount,status,pay_method,ref_id,created_at FROM {$wpdb->prefix}sn_payments WHERE invoice_id IN ({$ph}) ORDER BY id DESC LIMIT 100", ...$invoice_ids), ARRAY_A) ?: [];
			}

			private function sn_customer_after_sales_rows(string $phone, array $invoice_ids, array $lead_ids): array
			{
				global $wpdb;
				if (! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_after_sales_cases')) {
					return [];
				}
				$where = ['(normalized_phone LIKE %s OR customer_phone LIKE %s)'];
				$args = ['%' . $wpdb->esc_like($phone) . '%', '%' . $wpdb->esc_like($phone) . '%'];
				if ($invoice_ids) { $where[] = 'invoice_id IN (' . implode(',', array_fill(0, count($invoice_ids), '%d')) . ')'; $args = array_merge($args, $invoice_ids); }
				if ($lead_ids) { $where[] = 'lead_id IN (' . implode(',', array_fill(0, count($lead_ids), '%d')) . ')'; $args = array_merge($args, $lead_ids); }
				return $wpdb->get_results($wpdb->prepare("SELECT case_code,invoice_code,lead_id,case_type,case_status,priority,due_at,updated_at FROM {$wpdb->prefix}sn_after_sales_cases WHERE " . implode(' OR ', $where) . " ORDER BY id DESC LIMIT 100", ...$args), ARRAY_A) ?: [];
			}

			private function sn_customer_activity_rows(array $invoice_ids): array
			{
				global $wpdb;
				if (! $invoice_ids || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_activity_logs')) {
					return [];
				}
				$ph = implode(',', array_fill(0, count($invoice_ids), '%d'));
				return $wpdb->get_results($wpdb->prepare("SELECT invoice_id,lead_id,action,description,created_at FROM {$wpdb->prefix}sn_activity_logs WHERE invoice_id IN ({$ph}) ORDER BY id DESC LIMIT 100", ...$invoice_ids), ARRAY_A) ?: [];
			}

