				<div class="sn-card sn-section"><h3 class="sn-section-title">فاکتورها</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>کد</th><th>مشتری</th><th>شماره</th><th>وضعیت</th><th>روش پرداخت</th><th>مبلغ</th><th>فروشنده</th><th>تاریخ</th></tr></thead><tbody><?php foreach ($context['invoices'] as $invoice) : ?><tr><td><?php echo $this->sn_customer_context_chip((string) $invoice['invoice_code'], ['sn_invoice_code' => (string) $invoice['invoice_code']]); ?></td><td><?php echo esc_html((string) $invoice['customer_name']); ?></td><td><?php echo esc_html($this->sn_mask_phone((string) $invoice['customer_phone'])); ?></td><td><span class="sn-status"><?php echo esc_html(SN_Helpers::status_label((string) $invoice['status'])); ?></span></td><td><?php echo esc_html(SN_Helpers::pay_method_label((string) $invoice['pay_method'])); ?></td><td><?php echo esc_html(SN_Helpers::format_price((float) ($invoice['final_total'] ?: $invoice['product_price']))); ?></td><td><?php echo ! empty($invoice['seller_id']) ? esc_html($this->sn_user_label((int) $invoice['seller_id'])) : '—'; ?></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) $invoice['created_at'])); ?></td></tr><?php endforeach; ?><?php if (empty($context['invoices'])) : ?><tr><td colspan="8">فاکتوری یافت نشد.</td></tr><?php endif; ?></tbody></table></div></div>
				<div class="sn-card sn-section"><h3 class="sn-section-title">پرداخت‌ها</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>فاکتور</th><th>مبلغ</th><th>وضعیت</th><th>روش</th><th>رسید/Ref</th><th>تاریخ</th></tr></thead><tbody><?php foreach ($context['payments'] as $payment) : ?><tr><td>#<?php echo esc_html((string) $payment['invoice_id']); ?></td><td><?php echo esc_html(SN_Helpers::format_price((float) $payment['amount'])); ?></td><td><span class="sn-status"><?php echo esc_html(SN_Helpers::status_label((string) $payment['status'])); ?></span></td><td><?php echo esc_html(SN_Helpers::pay_method_label((string) $payment['pay_method'])); ?></td><td><code><?php echo esc_html($this->sn_mask_sensitive_export_value((string) $payment['ref_id'])); ?></code></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) $payment['created_at'])); ?></td></tr><?php endforeach; ?><?php if (empty($context['payments'])) : ?><tr><td colspan="6">پرداختی یافت نشد.</td></tr><?php endif; ?></tbody></table></div></div>
				<div class="sn-card sn-section"><h3 class="sn-section-title">خدمات پس از فروش</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>پرونده</th><th>فاکتور</th><th>نوع</th><th>وضعیت</th><th>اولویت</th><th>سررسید</th><th>آخرین تغییر</th></tr></thead><tbody><?php foreach ($context['cases'] as $case) : ?><tr><td><code><?php echo esc_html((string) $case['case_code']); ?></code></td><td><code><?php echo esc_html((string) $case['invoice_code']); ?></code></td><td><?php echo esc_html((string) $case['case_type']); ?></td><td><span class="sn-status"><?php echo esc_html((string) $case['case_status']); ?></span></td><td><?php echo esc_html((string) $case['priority']); ?></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) $case['due_at'])); ?></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) $case['updated_at'])); ?></td></tr><?php endforeach; ?><?php if (empty($context['cases'])) : ?><tr><td colspan="7">پرونده‌ای یافت نشد.</td></tr><?php endif; ?></tbody></table></div></div>
				<div class="sn-card sn-section"><h3 class="sn-section-title">رفتار و رویدادها</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>فاکتور</th><th>لید</th><th>عملیات</th><th>شرح</th><th>زمان</th></tr></thead><tbody><?php foreach ($context['activities'] as $activity) : ?><tr><td>#<?php echo esc_html((string) $activity['invoice_id']); ?></td><td>#<?php echo esc_html((string) $activity['lead_id']); ?></td><td><?php echo esc_html((string) $activity['action']); ?></td><td><?php echo esc_html($this->sn_after_sales_mask_sensitive_text((string) $activity['description'])); ?></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) $activity['created_at'])); ?></td></tr><?php endforeach; ?><?php if (empty($context['activities'])) : ?><tr><td colspan="5">رویدادی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></div>
				<?php
			}

			private function sn_customer_context_chip(string $label, array $args): string
			{
				$url = $this->sn_portal_page_url('customer', array_merge(['sn_customer_q' => null], $args));
				if ($url === '') {
					$url = add_query_arg(array_merge(['sn_customer_q' => null], $args));
				}
				return '<a class="sn-customer-chip" href="' . esc_url($url) . '"><code>' . esc_html($label) . '</code></a>';
			}

			private function sn_report_filters(): array
			{
				$date_from_raw = sanitize_text_field(wp_unslash($_GET['date_from'] ?? ''));
				$date_to_raw = sanitize_text_field(wp_unslash($_GET['date_to'] ?? ''));
				$date_from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from_raw) ? $date_from_raw : SN_Helpers::jalali_to_gregorian_date($date_from_raw);
				$date_to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to_raw) ? $date_to_raw : SN_Helpers::jalali_to_gregorian_date($date_to_raw);
				return [
					'date_from' => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$date_from) ? (string)$date_from : '',
					'date_to' => preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$date_to) ? (string)$date_to : '',
					'date_from_raw' => $date_from_raw,
					'date_to_raw' => $date_to_raw,
					'seller_id' => absint($_GET['seller_id'] ?? 0),
					'status' => sanitize_key(wp_unslash($_GET['status'] ?? '')),
					'product_type' => sanitize_key(wp_unslash($_GET['product_type'] ?? '')),
					'pay_method' => sanitize_key(wp_unslash($_GET['pay_method'] ?? '')),
					'q' => sanitize_text_field(wp_unslash($_GET['q'] ?? '')),
				];
			}

			private function sn_report_date_sql(string $column, array $filters): array
			{
				$where = ''; $args = [];
				if ($filters['date_from'] !== '') { $where .= " AND {$column} >= %s"; $args[] = $filters['date_from'] . ' 00:00:00'; }
				if ($filters['date_to'] !== '') { $where .= " AND {$column} <= %s"; $args[] = $filters['date_to'] . ' 23:59:59'; }
				return [$where, $args];
			}

			private function sn_report_seller_sql(string $column, array $filters): array
			{
				[$scope_sql, $args] = $this->sn_customer_scope_sql($column);
				if ($filters['seller_id']) {
					$visible = $this->sn_customer_visible_seller_ids();
					if ($visible !== null && ! in_array((int) $filters['seller_id'], array_map('intval', $visible), true)) {
						return [' AND 1=0', []];
					}
					$scope_sql .= " AND {$column}=%d";
					$args[] = (int) $filters['seller_id'];
				}
				return [$scope_sql, $args];
			}

			private function sn_cross_module_report_summary(array $filters): array
			{
				global $wpdb;
				[$lead_seller_sql, $lead_seller_args] = $this->sn_report_seller_sql('seller_id', $filters);
				[$lead_date_sql, $lead_date_args] = $this->sn_report_date_sql('imported_at', $filters);
				[$invoice_seller_sql, $invoice_seller_args] = $this->sn_report_seller_sql('seller_id', $filters);
				[$invoice_date_sql, $invoice_date_args] = $this->sn_report_date_sql('created_at', $filters);
				$status_sql = $filters['status'] !== '' ? ' AND status=%s' : '';
				$status_args = $filters['status'] !== '' ? [$filters['status']] : [];
				$lead_args = array_merge($lead_seller_args, $lead_date_args);
				$lead_sql = "SELECT COUNT(*) FROM {$wpdb->prefix}sn_leads WHERE 1=1 {$lead_seller_sql} {$lead_date_sql}";
				$leads_count = (int) ($lead_args ? $wpdb->get_var($wpdb->prepare($lead_sql, ...$lead_args)) : $wpdb->get_var($lead_sql));
				$invoice_args = array_merge($invoice_seller_args, $invoice_date_args, $status_args);
				$invoice_sql = "SELECT COUNT(*) c, COALESCE(SUM(final_total),SUM(product_price),0) total, COALESCE(SUM(CASE WHEN status IN ('paid','approved') THEN COALESCE(final_total,product_price,0) ELSE 0 END),0) paid_total FROM {$wpdb->prefix}sn_invoices WHERE 1=1 {$invoice_seller_sql} {$invoice_date_sql} {$status_sql}";
				$invoice_stats = ($invoice_args ? $wpdb->get_row($wpdb->prepare($invoice_sql, ...$invoice_args), ARRAY_A) : $wpdb->get_row($invoice_sql, ARRAY_A)) ?: ['c' => 0, 'total' => 0, 'paid_total' => 0];
				$cards = [
					['label' => 'لیدها', 'value' => $leads_count],
					['label' => 'فاکتورها', 'value' => (int) $invoice_stats['c']],
					['label' => 'مبلغ فاکتورها', 'value' => SN_Helpers::format_price((float) $invoice_stats['total'])],
					['label' => 'پرداخت/تأیید شده', 'value' => SN_Helpers::format_price((float) $invoice_stats['paid_total'])],
				];
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_after_sales_cases')) {
					$cards[] = ['label' => 'پرونده خدمات', 'value' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_after_sales_cases")];
				}
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_import_batches')) {
					$cards[] = ['label' => 'پرونده‌های MIS', 'value' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_mis_import_batches")];
				}
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles')) {
					$cards[] = ['label' => 'پروفایل منابع انسانی', 'value' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}sn_hr_profiles")];
				}
				return ['cards' => $cards, 'sections' => $this->sn_cross_module_report_sections($filters)];
			}

			private function sn_cross_module_report_sections(array $filters): array
			{
				global $wpdb;
				$sections = [];
				[$seller_sql, $seller_args] = $this->sn_report_seller_sql('i.seller_id', $filters);
				[$date_sql, $date_args] = $this->sn_report_date_sql('i.created_at', $filters);
				$status_sql = $filters['status'] !== '' ? ' AND i.status=%s' : '';
				$status_args = $filters['status'] !== '' ? [$filters['status']] : [];
				$performance_args = array_merge($seller_args, $date_args, $status_args);
				$performance_sql = "SELECT i.seller_id,u.display_name,COUNT(*) invoices,COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) total,COALESCE(SUM(CASE WHEN i.status IN ('paid','approved') THEN COALESCE(i.final_total,i.product_price,0) ELSE 0 END),0) paid_total FROM {$wpdb->prefix}sn_invoices i LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id WHERE 1=1 {$seller_sql} {$date_sql} {$status_sql} GROUP BY i.seller_id,u.display_name ORDER BY total DESC LIMIT 20";
				$rows = ($performance_args ? $wpdb->get_results($wpdb->prepare($performance_sql, ...$performance_args), ARRAY_A) : $wpdb->get_results($performance_sql, ARRAY_A)) ?: [];
				$sections[] = ['title' => 'عملکرد فروشنده‌ها', 'headers' => ['فروشنده', 'فاکتور', 'مبلغ کل', 'مبلغ پرداخت/تأیید شده'], 'rows' => array_map(function($r) { return [esc_html($r['display_name'] ?: ('#' . (int) $r['seller_id'])), esc_html((string) $r['invoices']), esc_html(SN_Helpers::format_price((float) $r['total'])), esc_html(SN_Helpers::format_price((float) $r['paid_total']))]; }, $rows)];
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_after_sales_cases')) {
					$as = $wpdb->get_results("SELECT case_status,COUNT(*) c FROM {$wpdb->prefix}sn_after_sales_cases GROUP BY case_status ORDER BY c DESC LIMIT 20", ARRAY_A) ?: [];
					$sections[] = ['title' => 'خدمات پس از فروش', 'headers' => ['وضعیت', 'تعداد'], 'rows' => array_map(fn($r) => [esc_html((string) $r['case_status']), esc_html((string) $r['c'])], $as)];
				}
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_import_batches')) {
					$mis = $wpdb->get_results("SELECT import_status,COUNT(*) batches,COALESCE(SUM(total_rows),0) rows_total FROM {$wpdb->prefix}sn_mis_import_batches GROUP BY import_status ORDER BY batches DESC LIMIT 20", ARRAY_A) ?: [];
					$sections[] = ['title' => 'MIS', 'headers' => ['وضعیت پرونده', 'پرونده‌ها', 'ردیف‌ها'], 'rows' => array_map(fn($r) => [esc_html((string) $r['import_status']), esc_html((string) $r['batches']), esc_html((string) $r['rows_total'])], $mis)];
				}
				if ($this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles')) {
					$hr = $wpdb->get_results("SELECT COALESCE(pos.label,pos.slug,'بدون سمت') position_label,COUNT(*) c FROM {$wpdb->prefix}sn_hr_profiles hp LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id GROUP BY position_label ORDER BY c DESC", ARRAY_A) ?: [];
					$sections[] = ['title' => 'منابع انسانی', 'headers' => ['سمت', 'تعداد'], 'rows' => array_map(fn($r) => [esc_html((string) $r['position_label']), esc_html((string) $r['c'])], $hr)];
				}
				return $sections;
			}

			private function sn_report_export_url(string $type, array $filters): string
			{
				return wp_nonce_url(add_query_arg(array_merge(['action' => 'sn_export_report_csv', 'report_type' => $type], $filters), admin_url('admin-post.php')), 'sn_export_report_csv');
			}

