			private function sn_export_report_rows(string $type, array $filters, int $limit): array
			{
				global $wpdb;
				$limit = max(1, min(5000, $limit));
				if ($type === 'successful_payments') {
					$rows = $this->sn_successful_payment_report_rows($filters, $limit, 0);
					foreach ($rows as &$row) {
						$row['customer_phone'] = $this->sn_mask_phone((string)($row['customer_phone'] ?? ''));
						$row['product_types_label'] = $this->sn_successful_payment_report_product_type_label((string)($row['product_types'] ?? ''));
						$row['pay_method_label'] = $this->sn_invoice_pay_method_label((string)($row['pay_method'] ?? ''));
						$row['payment_at'] = SN_Helpers::gregorian_to_jalali_date((string)($row['payment_at'] ?? ''));
						$row['payment_status'] = SN_Helpers::status_label((string)($row['payment_status'] ?? 'paid'));
					}
					unset($row);
					return $rows;
				}
				if ($type === 'leads') {
					[$scope, $scope_args] = $this->sn_report_seller_sql('l.seller_id', $filters);
					[$date, $date_args] = $this->sn_report_date_sql('l.imported_at', $filters);
					$rows = $wpdb->get_results($wpdb->prepare("SELECT l.id,l.customer_name,l.national_id,l.marketing_form_id,l.phone,l.province,l.city,COALESCE(l.lead_status,l.status) status,u.display_name seller,l.imported_at created_at FROM {$wpdb->prefix}sn_leads l LEFT JOIN {$wpdb->users} u ON u.ID=l.seller_id WHERE 1=1 {$scope} {$date} ORDER BY l.id DESC LIMIT %d", ...array_merge($scope_args, $date_args, [$limit])), ARRAY_A) ?: [];
					foreach ($rows as &$row) { $row['phone'] = $this->sn_mask_phone((string) $row['phone']); }
					return $rows;
				}
				if ($type === 'invoices') {
					[$scope, $scope_args] = $this->sn_report_seller_sql('i.seller_id', $filters);
					[$date, $date_args] = $this->sn_report_date_sql('i.created_at', $filters);
					$status = $filters['status'] !== '' ? ' AND i.status=%s' : '';
					$status_args = $filters['status'] !== '' ? [$filters['status']] : [];
					$rows = $wpdb->get_results($wpdb->prepare("SELECT i.id,i.invoice_code,i.customer_name,i.customer_phone,i.status,COALESCE(i.final_total,i.product_price,0) amount,u.display_name seller,i.created_at FROM {$wpdb->prefix}sn_invoices i LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id WHERE 1=1 {$scope} {$date} {$status} ORDER BY i.id DESC LIMIT %d", ...array_merge($scope_args, $date_args, $status_args, [$limit])), ARRAY_A) ?: [];
					foreach ($rows as &$row) { $row['customer_phone'] = $this->sn_mask_phone((string) $row['customer_phone']); }
					return $rows;
				}
				if ($type === 'payments' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_payments')) {
					return $wpdb->get_results($wpdb->prepare("SELECT i.invoice_code,p.amount,p.status,p.pay_method,p.created_at FROM {$wpdb->prefix}sn_payments p LEFT JOIN {$wpdb->prefix}sn_invoices i ON i.id=p.invoice_id ORDER BY p.id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				if ($type === 'wallet' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_wallets')) {
					return $wpdb->get_results($wpdb->prepare("SELECT COALESCE(u.display_name,CONCAT('#',w.user_id)) user,w.wallet_type,w.balance,w.updated_at FROM {$wpdb->prefix}sn_wallets w LEFT JOIN {$wpdb->users} u ON u.ID=w.user_id ORDER BY w.updated_at DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				if ($type === 'commission' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_commission_rules')) {
					return $wpdb->get_results($wpdb->prepare("SELECT rule_name,position_slug,level_slug,is_active FROM {$wpdb->prefix}sn_commission_rules ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				if ($type === 'hr_profiles' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles')) {
					return $wpdb->get_results($wpdb->prepare("SELECT hp.user_id,COALESCE(NULLIF(hp.hr_display_name,''),u.display_name) AS display_name,pos.label position,lvl.label level,hp.employment_status FROM {$wpdb->prefix}sn_hr_profiles hp LEFT JOIN {$wpdb->users} u ON u.ID=hp.user_id LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id LEFT JOIN {$wpdb->prefix}sn_hr_levels lvl ON lvl.id=hp.level_id ORDER BY hp.id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				if ($type === 'after_sales' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_after_sales_cases')) {
					return $wpdb->get_results($wpdb->prepare("SELECT case_code,invoice_code,case_status,priority,updated_at FROM {$wpdb->prefix}sn_after_sales_cases ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				if ($type === 'mis_summary' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_mis_import_batches')) {
					return $wpdb->get_results($wpdb->prepare("SELECT batch_code,title,import_status,total_rows,valid_rows FROM {$wpdb->prefix}sn_mis_import_batches ORDER BY id DESC LIMIT %d", $limit), ARRAY_A) ?: [];
				}
				return [];
			}

			private function sn_csv_safe_cell(string $value): string
			{
				$value = $this->sn_mask_sensitive_export_value($value);
				return preg_match('/^[=+\-@]/', $value) ? "'" . $value : $value;
			}

			private function sn_mask_sensitive_export_value(string $value): string
			{
				$value = preg_replace('/https?:\/\/[^\s,"]+/i', '[hidden-url]', $value);
				$value = preg_replace('/(access_token|token|password|hash)=([^&\s,"]+)/i', '$1=[hidden]', (string) $value);
				return (string) $value;
			}

			public function render_admin_customer_profiles(): void
			{
				$filters = $this->sn_customer_profile_filters();
				$view = (string) ($filters['view'] ?? 'detail');
				$rows = $this->sn_customer_profile_fetch_invoice_rows($filters, $view === 'aggregate' ? 5000 : 500);
				$seller_ids = [];
				foreach ($rows as $r) { $seller_ids[] = $this->sn_invoice_effective_seller_id_for_admin((array) $r); }
				$chain_map = $this->sn_admin_invoice_hr_chain_map($seller_ids);
				$aggregate_rows = $view === 'aggregate' ? $this->sn_customer_profile_aggregate_rows($rows, $chain_map, $filters) : [];
				$visible_count = $view === 'aggregate' ? count($aggregate_rows) : count($rows);
				$paid_customers = [];
				$paid_revenue = 0.0;
				$invoice_total = 0.0;
				foreach ($rows as $r) { $amount = $this->sn_invoice_amount_from_row((array) $r); $invoice_total += $amount; if ($this->sn_invoice_is_paid_for_admin((array) $r)) { $paid_revenue += $amount; $paid_customers[preg_replace('/\D+/', '', (string) ($r['customer_phone'] ?? ''))] = true; } }
				$export_url = wp_nonce_url(add_query_arg(array_merge($_GET, ['sn_export' => 'customer_profiles', 'sn_view' => $view]), admin_url('admin.php')), 'sn_export_customer_profiles');
				$detail_url = add_query_arg(array_merge($_GET, ['page' => 'sn-customer-profiles', 'sn_view' => 'detail']), admin_url('admin.php'));
				$aggregate_url = add_query_arg(array_merge($_GET, ['page' => 'sn-customer-profiles', 'sn_view' => 'aggregate']), admin_url('admin.php'));
