			public function ensure_wallet_tables(): void
			{
				global $wpdb;
				$wallet_tx_table = $wpdb->prefix . 'sn_wallet_transactions';
				if ((string) get_option('sn_wallet_tables_version', '') === SN_VERSION) {
					$columns = $this->sn_wallet_table_exists($wallet_tx_table) ? (array) $wpdb->get_col("SHOW COLUMNS FROM {$wallet_tx_table}", 0) : [];
					if (in_array('idempotency_key', $columns, true)) { return; }
				}
				if ($this->sn_defer_heavy_admin_runtime()) { return; }
				require_once ABSPATH . 'wp-admin/includes/upgrade.php';
				$charset = $wpdb->get_charset_collate();
				dbDelta("CREATE TABLE {$wpdb->prefix}sn_wallets (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			user_id BIGINT UNSIGNED NOT NULL,
			wallet_type VARCHAR(30) NOT NULL DEFAULT 'seller',
			balance DECIMAL(18,2) NOT NULL DEFAULT 0,
			total_credit DECIMAL(18,2) NOT NULL DEFAULT 0,
			total_debit DECIMAL(18,2) NOT NULL DEFAULT 0,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			UNIQUE KEY user_wallet (user_id, wallet_type),
			KEY wallet_type (wallet_type)
		) {$charset};");
				dbDelta("CREATE TABLE {$wpdb->prefix}sn_wallet_transactions (
			id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
			wallet_id BIGINT UNSIGNED NOT NULL,
			user_id BIGINT UNSIGNED NOT NULL,
			wallet_type VARCHAR(30) NOT NULL DEFAULT 'seller',
			invoice_id BIGINT UNSIGNED DEFAULT NULL,
			lead_id BIGINT UNSIGNED DEFAULT NULL,
			amount DECIMAL(18,2) NOT NULL DEFAULT 0,
			direction VARCHAR(10) NOT NULL DEFAULT 'credit',
			type VARCHAR(60) NOT NULL DEFAULT 'commission',
			status VARCHAR(30) NOT NULL DEFAULT 'approved',
			description TEXT DEFAULT NULL,
			meta LONGTEXT DEFAULT NULL,
			idempotency_key VARCHAR(191) DEFAULT NULL,
			created_by BIGINT UNSIGNED DEFAULT NULL,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			PRIMARY KEY (id),
			KEY wallet_id (wallet_id),
			KEY user_id (user_id),
			KEY invoice_id (invoice_id),
			UNIQUE KEY idempotency_key (idempotency_key),
			KEY type (type),
			KEY created_at (created_at)
		) {$charset};");
				update_option('sn_wallet_tables_version', SN_VERSION, false);
			}

			private function sn_wallet_id(int $user_id, string $wallet_type = 'seller'): int
			{
				global $wpdb;
				$this->ensure_wallet_tables();
				$table = $wpdb->prefix . 'sn_wallets';
				$id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE user_id=%d AND wallet_type=%s", $user_id, $wallet_type));
				if ($id) {
					return $id;
				}
				$wpdb->insert($table, ['user_id' => $user_id, 'wallet_type' => $wallet_type, 'balance' => 0, 'total_credit' => 0, 'total_debit' => 0]);
				$created_id = (int) $wpdb->insert_id;
				return $created_id > 0 ? $created_id : (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE user_id=%d AND wallet_type=%s", $user_id, $wallet_type));
			}

			private function sn_add_wallet_transaction(int $user_id, string $wallet_type, float $amount, string $direction, string $type, string $description = '', ?int $invoice_id = null, ?int $lead_id = null, array $meta = []): bool
			{
				if ($user_id <= 0 || $amount <= 0) {
					return false;
				}
				global $wpdb;
				$wallet_id = $this->sn_wallet_id($user_id, $wallet_type);
				if ($wallet_id < 1) { return false; }
				$type = sanitize_key($type);
				$idempotency_key = null;
				if ($invoice_id && in_array($type, ['commission_engine', 'seller_commission', 'supervisor_commission'], true)) {
					$exists = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND wallet_type=%s AND type=%s LIMIT 1", $invoice_id, $user_id, $wallet_type, $type));
					if ($exists) {
						return false;
					}
					$idempotency_key = implode(':', ['invoice', $invoice_id, 'user', $user_id, 'wallet', sanitize_key($wallet_type), 'type', $type]);
				}
				if (! empty($meta['idempotency_key']) && in_array($type, ['commission_engine_reversal', 'seller_commission_reversal', 'supervisor_commission_reversal'], true)) {
					$idempotency_key = substr(sanitize_text_field((string) $meta['idempotency_key']), 0, 191);
				}
				$wpdb->insert($wpdb->prefix . 'sn_wallet_transactions', [
					'wallet_id' => $wallet_id,
					'user_id' => $user_id,
					'wallet_type' => $wallet_type,
					'invoice_id' => $invoice_id,
					'lead_id' => $lead_id,
					'amount' => $amount,
					'direction' => $direction === 'debit' ? 'debit' : 'credit',
					'type' => $type,
					'status' => 'approved',
					'description' => $description,
					'meta' => wp_json_encode($meta, JSON_UNESCAPED_UNICODE),
					'idempotency_key' => $idempotency_key,
					'created_by' => get_current_user_id() ?: null,
					'created_at' => current_time('mysql'),
				]);
				if ($wpdb->insert_id) {
					$transaction_id = (int) $wpdb->insert_id;
					$sign = $direction === 'debit' ? -1 : 1;
					$balance_updated = $wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}sn_wallets SET balance = balance + %f, total_credit = total_credit + %f, total_debit = total_debit + %f WHERE id=%d", $sign * $amount, $direction === 'debit' ? 0 : $amount, $direction === 'debit' ? $amount : 0, $wallet_id));
					if ($balance_updated === false || $balance_updated === 0) {
						$wpdb->delete($wpdb->prefix . 'sn_wallet_transactions', ['id' => $transaction_id]);
						return false;
					}
					$this->sn_log_activity($invoice_id, $lead_id, 'wallet_transaction', 'ثبت تراکنش کیف پول: ' . $description, ['user_id' => $user_id, 'wallet_type' => $wallet_type, 'amount' => $amount, 'direction' => $direction, 'type' => $type]);
					return true;
				}
				return false;
			}

			private function sn_commission_amount(float $base, string $role): float
			{
				$type = get_option("sn_{$role}_commission_type", 'percent');
				$value = (float) get_option("sn_{$role}_commission_value", 0);
				if ($value <= 0 || $base <= 0) {
					return 0;
				}
				return $type === 'fixed' ? $value : round(($base * $value) / 100, 2);
			}

			private function sn_commission_approved_status_values(): array
			{
				return [
					'paid','approved','completed','confirmed','payment_approved','finance_approved','financially_approved',
					'payment_confirmed','paid_confirmed','receipt_approved','receipt_confirmed','manual_approved',
					'finance_confirmed','finance_verified','verified','success','successful','settled',
					'تایید مالی','تأیید مالی','تایید شده','تأیید شده','پرداخت شده','موفق',
				];
			}


			private function sn_ensure_pre_invoice_lead_status(): void
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_lead_statuses';
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					return;
				}
				$label = 'پیش‌فاکتور';
				$exists = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE label=%s LIMIT 1", $label));
				if ($exists > 0) {
					return;
				}
				$wpdb->insert($table, [
					'label' => $label,
					'color' => '#0ea5e9',
					'sort_order' => 20,
					'is_active' => 1,
				]);
			}

			private function sn_commission_paid_approved_invoice_condition(string $alias = 'i'): string
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				$cols = $this->sn_table_columns($table);
				$prefix = $alias !== '' ? $alias . '.' : '';
				$quoted = array_map(static fn($v) => "'" . esc_sql((string) $v) . "'", $this->sn_commission_approved_status_values());
				$approved_values = implode(',', $quoted);
				$parts = [];
				foreach ([
					'status','payment_status','invoice_status','financial_status','finance_status','payment_approval_status','payment_review_status',
					'pay_status','payment_state','finance_review_status','finance_approval_status','receipt_status','manual_payment_status',
				] as $col) {
					if (in_array($col, $cols, true)) {
						$parts[] = "{$prefix}{$col} IN ({$approved_values})";
					}
				}
				foreach ([
					'financial_reviewed_at','finance_approved_at','payment_approved_at','approved_at','paid_at','payment_confirmed_at',
					'finance_confirmed_at','finance_verified_at','receipt_approved_at','manual_approved_at','confirmed_at',
				] as $date_col) {
					if (in_array($date_col, $cols, true)) {
						// In MySQL strict mode, comparing DATETIME columns with an empty string causes
						// "Incorrect DATETIME value: ''". Cast to CHAR so legacy empty/zero values
						// can be ignored without triggering DATE/DATETIME coercion.
						$parts[] = "({$prefix}{$date_col} IS NOT NULL AND CAST({$prefix}{$date_col} AS CHAR) NOT IN ('', '0000-00-00', '0000-00-00 00:00:00'))";
					}
				}
				return $parts ? '(' . implode(' OR ', $parts) . ')' : '1=0';
			}

			private function sn_commission_invoice_owner_column_candidates(): array
			{
				return ['seller_id','original_seller_id','commission_seller_id','seller_user_id','sales_user_id','lead_seller_id','assigned_seller_id'];
			}

			private function sn_commission_invoice_seller_id_from_row(array $invoice): int
			{
				foreach ($this->sn_commission_invoice_owner_column_candidates() as $col) {
					if (isset($invoice[$col]) && (int) $invoice[$col] > 0) {
						return (int) $invoice[$col];
					}
				}
				return 0;
			}

			private function sn_commission_invoice_is_approved_row(array $invoice): bool
			{
				// A finance approval can belong to one stage of an instalment invoice.
				// Never treat that intermediate approval as completion of the sale.
				$total = (float) (($invoice['payment_total_amount'] ?? 0) ?: ($invoice['final_total'] ?? 0) ?: ($invoice['product_price'] ?? 0));
				$paid_total = (float) ($invoice['paid_total_amount'] ?? 0);
				$remaining = isset($invoice['remaining_amount']) && $invoice['remaining_amount'] !== null && $invoice['remaining_amount'] !== ''
					? (float) $invoice['remaining_amount']
					: ($total > 0 && $paid_total > 0 ? max(0, $total - $paid_total) : 0);
				$workflow = sanitize_key((string) ($invoice['payment_workflow_status'] ?? ''));
				if ($remaining > 0.5 || in_array($workflow, ['partial_paid', 'awaiting_next_payment', 'payment_stage_issued'], true)) {
					return false;
				}
				if ($total > 0 && $paid_total > 0 && $paid_total + 0.5 < $total) {
					return false;
				}
				$rejected = ['rejected','cancelled','canceled','trash','failed','refunded','draft','pre_invoice','pending','در انتظار','رد شده','لغو شده'];
				foreach (['status','payment_status','invoice_status','financial_status','finance_status','payment_approval_status','payment_review_status','pay_status','payment_state','finance_review_status','finance_approval_status','receipt_status','manual_payment_status'] as $col) {
					$value = strtolower(trim((string) ($invoice[$col] ?? '')));
					if ($value === '') { continue; }
					foreach ($rejected as $bad) {
						if ($bad !== '' && str_contains($value, strtolower($bad))) { return false; }
					}
					if (in_array($value, array_map('strtolower', $this->sn_commission_approved_status_values()), true)) { return true; }
				}
				foreach (['financial_reviewed_at','finance_approved_at','payment_approved_at','approved_at','paid_at','payment_confirmed_at','finance_confirmed_at','finance_verified_at','receipt_approved_at','manual_approved_at','confirmed_at'] as $date_col) {
					if (! empty($invoice[$date_col]) && (string) $invoice[$date_col] !== '0000-00-00 00:00:00' && (string) $invoice[$date_col] !== '0000-00-00') { return true; }
				}
				return false;
			}

			private function sn_commission_invoice_rows_for_wallet(?int $seller_id = null, int $limit = 2000): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_table_exists_quiet($table)) { return []; }
				$rows = [];
				$seen = [];
				$cols = $this->sn_table_columns($table);
				$order_col = in_array('id', $cols, true) ? 'id' : (in_array('created_at', $cols, true) ? 'created_at' : '1');
				$owner_parts = [];
				$args = [];
				if ($seller_id !== null && $seller_id > 0) {
					foreach ($this->sn_commission_invoice_owner_column_candidates() as $col) {
						if (in_array($col, $cols, true)) { $owner_parts[] = "i.{$col}=%d"; $args[] = $seller_id; }
					}
				}
				$where = $owner_parts ? '(' . implode(' OR ', $owner_parts) . ')' : '1=1';
				$sql = "SELECT i.* FROM {$table} i WHERE {$where} ORDER BY i.{$order_col} DESC LIMIT %d";
				$args[] = max(1, min(5000, $limit));
				$candidates = $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
				// If the invoice uses an uncommon seller column, scan a bounded approved/recent set and filter through the commission context.
				if ($seller_id !== null && count($candidates) < 1) {
					$candidates = $wpdb->get_results("SELECT i.* FROM {$table} i ORDER BY i.{$order_col} DESC LIMIT 500", ARRAY_A) ?: [];
				}
				foreach ($candidates as $row) {
					$id = (int) ($row['id'] ?? 0);
					if (! $id || isset($seen[$id])) { continue; }
					$context_seller = $this->sn_commission_invoice_seller_id_from_row($row);
					if ($seller_id !== null && $context_seller !== $seller_id) { continue; }
					if (! $this->sn_commission_invoice_is_approved_row($row)) { continue; }
					$seen[$id] = true;
					$rows[] = $row;
					if (count($rows) >= $limit) { break; }
				}
				return $rows;
			}

			private function sn_wallet_finance_commission_preview_rows(int $seller_id, int $limit = 20): array
			{
				global $wpdb;
				if ($seller_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) {
					return [];
				}
				$rows = $this->sn_commission_invoice_rows_for_wallet($seller_id, max(1, min(50, $limit)));
				$preview = [];
				foreach ($rows as $invoice_row) {
					$payload = $this->sn_commission_engine_wallet_payload((int) ($invoice_row['id'] ?? 0), $invoice_row);
					$context = (array) ($payload['context'] ?? []);
					$amount = (float) ($payload['commission_amount'] ?? 0);
					$tx_id = $this->sn_wallet_existing_commission_transaction_id((int) ($context['invoice_id'] ?? 0), (int) ($context['seller_id'] ?? 0));
					$preview[] = [
						'invoice_id' => (int) ($context['invoice_id'] ?? 0),
						'invoice_code' => (string) (($context['invoice_code'] ?? '') ?: ('#' . (int) ($context['invoice_id'] ?? 0))),
						'base_amount' => (float) ($context['invoice_total'] ?? 0),
						'commission_amount' => $amount,
						'payment_method' => (string) ($context['payment_method_normalized'] ?? 'unknown'),
						'employment_type' => (string) ($context['seller_employment_type'] ?? ''),
						'matched_rule_ids' => (array) ($payload['matched_rule_ids'] ?? []),
						'components' => (array) ($payload['components'] ?? []),
						'diagnostics' => array_values(array_unique(array_filter((array) ($payload['diagnostics'] ?? [])))),
						'wallet_transaction_id' => $tx_id,
						'status' => $tx_id ? 'posted' : ($amount > 0 ? 'ready' : 'no_rule'),
					];
				}
				return $preview;
			}

			private function sn_commission_engine_wallet_payload(int $invoice_id, $invoice = null): array
			{
				$invoice_row = is_array($invoice) ? $invoice : (is_object($invoice) ? (array) $invoice : null);
				$context = $this->sn_resolve_invoice_commission_context($invoice_id, $invoice_row);
				$matcher = $this->sn_find_matching_commission_rule($context);
				$matched_rules = (array) ($matcher['matched_rules'] ?? []);
				$matched_rules = $this->sn_commission_apply_hr_override_to_rules($context, $matched_rules);
				$amount = (float) ($context['invoice_total'] ?? 0);
				$components = $this->sn_commission_calculate_rule_components($matched_rules, $amount);
				$diagnostics = array_values(array_unique(array_filter(array_merge((array) ($context['diagnostics'] ?? []), (array) ($matcher['diagnostics'] ?? [])))));
				return [
					'context' => $context,
					'matcher' => $matcher,
					'matched_rules' => $matched_rules,
					'matched_rule_ids' => array_values(array_map(static fn($rule) => (int) ($rule['id'] ?? 0), $matched_rules)),
					'commission_amount' => (float) ($components['total'] ?? 0),
					'components' => (array) ($components['components'] ?? []),
					'diagnostics' => $diagnostics,
				];
			}

			private function sn_wallet_existing_commission_transaction_id(int $invoice_id, int $seller_id): int
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($table) || ! $invoice_id || ! $seller_id) {
					return 0;
				}
				return (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table} WHERE invoice_id=%d AND user_id=%d AND wallet_type='seller' AND type IN ('commission_engine','seller_commission') LIMIT 1", $invoice_id, $seller_id));
			}

			private function sn_credit_wallet_for_invoice(int $invoice_id, $invoice, bool $force = false): void
			{
				if ( class_exists( 'SN_Purpose_Commission' ) && SN_Purpose_Commission::is_matrix_engine_enabled() ) {
					return;
				}
				if (! $force && get_option('sn_wallet_auto_credit', '1') !== '1') {
					return;
				}
				global $wpdb;
				$wallet_table = $wpdb->prefix . 'sn_wallet_transactions';
				if (! $this->sn_wallet_table_exists($wallet_table)) {
					return;
				}
				$inv = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id), ARRAY_A);
				if (! $inv) {
					$inv = is_array($invoice) ? $invoice : (is_object($invoice) ? (array) $invoice : []);
				}
				$payload = $this->sn_commission_engine_wallet_payload($invoice_id, $inv);
				$context = (array) ($payload['context'] ?? []);
				$seller_id = (int) ($context['seller_id'] ?? 0);
				$lead_id = (int) ($inv['lead_id'] ?? 0);
				if (! $seller_id && $lead_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
					$seller_id = (int) $wpdb->get_var($wpdb->prepare("SELECT seller_id FROM {$wpdb->prefix}sn_leads WHERE id=%d", $lead_id));
				}
				if (! $seller_id) {
					return;
				}

				$commission_amount = (float) ($payload['commission_amount'] ?? 0);
				$missing_seller = ! empty($payload['diagnostics']) && in_array('missing_seller_id', (array) $payload['diagnostics'], true);
				if ($commission_amount > 0 && ! $missing_seller && ! $this->sn_wallet_existing_commission_transaction_id($invoice_id, $seller_id)) {
					$this->sn_add_wallet_transaction($seller_id, 'seller', $commission_amount, 'credit', 'commission_engine', 'پورسانت بر اساس قوانین مالی برای فاکتور ' . (string) (($context['invoice_code'] ?? '') ?: $invoice_id), $invoice_id, $lead_id ?: null, [
						'base_amount' => (float) ($context['invoice_total'] ?? 0),
						'payment_method' => (string) ($context['payment_method_normalized'] ?? ''),
						'employment_type' => (string) ($context['seller_employment_type'] ?? ''),
						'compensation_history_id' => (int) ($context['compensation_history_id'] ?? 0),
						'calculation_date' => (string) ($context['calculation_date'] ?? ''),
						'issued_by_user_id' => (int) ($context['issued_by_user_id'] ?? 0),
						'matched_rule_ids' => (array) ($payload['matched_rule_ids'] ?? []),
						'commission_components' => (array) ($payload['components'] ?? []),
						'snapshot_version' => defined('SN_VERSION') ? SN_VERSION : '',
						'source' => $force ? 'wallet_recalculate_finance_rules' : 'invoice_auto_credit_finance_rules',
					]);
				}

				// Supervisor wallet is independent from seller commission posting. Existing seller wallet rows must not block supervisor commission.
				$supervisor_id = 0;
				if ($lead_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
					$supervisor_id = (int) $wpdb->get_var($wpdb->prepare("SELECT supervisor_id FROM {$wpdb->prefix}sn_leads WHERE id=%d", $lead_id));
				}
				if ($supervisor_id < 1) {
					$supervisor_id = (int) get_user_meta($seller_id, 'sn_supervisor_id', true);
				}
				if ($supervisor_id < 1 && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles') && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_assignments')) {
					$profile_ids = $this->sn_hr_profile_ids_for_user($seller_id);
					if ($profile_ids) {
						$ph = implode(',', array_fill(0, count($profile_ids), '%d'));
						$supervisor_id = (int) $wpdb->get_var($wpdb->prepare(
							"SELECT hp.user_id
							 FROM {$wpdb->prefix}sn_hr_assignments a
							 INNER JOIN {$wpdb->prefix}sn_hr_profiles hp ON hp.id=a.parent_profile_id AND hp.is_active=1
							 INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id
							 WHERE a.child_profile_id IN ({$ph}) AND a.is_current=1 AND pos.slug IN ('supervisor','senior_supervisor')
							 ORDER BY FIELD(pos.slug,'supervisor','senior_supervisor'), a.id DESC LIMIT 1",
							...$profile_ids
						));
					}
				}
				if ($supervisor_id > 0 && $supervisor_id !== $seller_id) {
					$existing_supervisor_tx = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$wallet_table} WHERE invoice_id=%d AND user_id=%d AND wallet_type='supervisor' AND type='supervisor_commission' LIMIT 1", $invoice_id, $supervisor_id));
					if (! $existing_supervisor_tx) {
						$supervisor_type = sanitize_key((string) get_option('sn_supervisor_commission_type', 'percent'));
						$supervisor_value = (float) get_option('sn_supervisor_commission_value', '0');
						$base_amount = (float) ($context['invoice_total'] ?? 0);
						$supervisor_amount = $supervisor_type === 'fixed' ? $supervisor_value : ($base_amount * $supervisor_value / 100);
						if ($supervisor_amount > 0) {
							$this->sn_add_wallet_transaction($supervisor_id, 'supervisor', $supervisor_amount, 'credit', 'supervisor_commission', 'پورسانت سرپرست برای فاکتور ' . (string) (($context['invoice_code'] ?? '') ?: $invoice_id), $invoice_id, $lead_id ?: null, [
								'base_amount' => $base_amount,
								'seller_id' => $seller_id,
								'commission_type' => $supervisor_type,
								'commission_value' => $supervisor_value,
								'supervisor_id_snapshot' => $supervisor_id,
								'snapshot_version' => defined('SN_VERSION') ? SN_VERSION : '',
								'source' => $force ? 'wallet_recalculate_supervisor_rules' : 'invoice_auto_credit_supervisor_rules',
							]);
						}
					}
				}
			}


			private function sn_wallet_autopost_recent_commissions_for_seller(int $seller_id, int $limit = 30): array
			{
				global $wpdb;
				$report = ['scanned' => 0, 'created' => 0, 'existing' => 0, 'ready_no_post' => 0, 'no_rule' => 0];
				if ($seller_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices')) {
					return $report;
				}
				$rows = $this->sn_commission_invoice_rows_for_wallet($seller_id, max(1, min(100, $limit)));
				foreach ($rows as $inv) {
					$report['scanned']++;
					$invoice_id = (int) ($inv['id'] ?? 0);
					if ($invoice_id < 1) { continue; }
					$payload = $this->sn_commission_engine_wallet_payload($invoice_id, $inv);
					$context = (array) ($payload['context'] ?? []);
					$resolved_seller = (int) ($context['seller_id'] ?? 0);
					$amount = (float) ($payload['commission_amount'] ?? 0);
					if ($resolved_seller !== $seller_id || $amount <= 0 || empty($payload['matched_rule_ids'])) {
						$report['no_rule']++;
						continue;
					}
					if ($this->sn_wallet_existing_commission_transaction_id($invoice_id, $seller_id)) {
						$report['existing']++;
						continue;
					}
					$before = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND wallet_type='seller' AND type='commission_engine'", $invoice_id, $seller_id));
					$this->sn_credit_wallet_for_invoice($invoice_id, $inv, true);
					$after = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND wallet_type='seller' AND type='commission_engine'", $invoice_id, $seller_id));
					if ($after > $before) {
						$report['created'] += ($after - $before);
					} else {
						$report['ready_no_post']++;
					}
				}
				return $report;
			}


			private function sn_wallet_summary(int $user_id, string $wallet_type): array
			{
				global $wpdb;
				$this->ensure_wallet_tables();
				$wallet_id = $this->sn_wallet_id($user_id, $wallet_type);
				$w = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_wallets WHERE id=%d", $wallet_id), ARRAY_A);
				$tx = $wpdb->get_results($wpdb->prepare("SELECT wt.*, i.pay_method AS invoice_pay_method, i.payment_source AS invoice_payment_source FROM {$wpdb->prefix}sn_wallet_transactions wt LEFT JOIN {$wpdb->prefix}sn_invoices i ON i.id=wt.invoice_id WHERE wt.wallet_id=%d ORDER BY wt.id DESC LIMIT 50", $wallet_id), ARRAY_A);
				return ['wallet' => $w ?: [], 'transactions' => $tx ?: []];
			}

			public function ajax_seller_wallet_box(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$user_id = get_current_user_id();
				$position = $this->sn_hr_position_for_user($user_id);
				if ($position !== 'seller' && ! in_array('sn_seller', (array) wp_get_current_user()->roles, true)) {
					SN_Helpers::send_json(false, 'این بخش فقط برای فروشنده است.');
					return;
				}
				$light = ! empty($_POST['light']) || ! empty($_POST['sn_wallet_light']);
				$html = '<div id="sn-seller-wallet-box" data-loaded="1">' . $this->render_wallet_box_for_user($user_id, 'seller', true) . '</div>';
				SN_Helpers::send_json(true, 'wallet_loaded', ['html' => $html]);
			}

			private function sn_wallet_autopost_recent_supervisor_commissions(int $supervisor_id, int $limit = 100): array
			{
				global $wpdb;
				$report = ['scanned' => 0, 'created' => 0, 'existing' => 0, 'no_scope' => 0, 'no_amount' => 0];
				$supervisor_id = absint($supervisor_id);
				if ($supervisor_id < 1 || (float) get_option('sn_supervisor_commission_value', '0') <= 0 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_invoices') || ! $this->sn_wallet_table_exists($wpdb->prefix . 'sn_wallet_transactions')) {
					return $report;
				}
				$seller_ids = $this->sn_scope_seller_ids_for_panel($supervisor_id, 'supervisor');
				if (! $seller_ids) {
					$report['no_scope'] = 1;
					return $report;
				}
				$limit = max(1, min(300, $limit));
				$ph = implode(',', array_fill(0, count($seller_ids), '%d'));
				$approved_condition = $this->sn_commission_paid_approved_invoice_condition('i');
				$args = array_merge(array_values(array_map('intval', $seller_ids)), [$limit]);
				$rows = $wpdb->get_results($wpdb->prepare(
					"SELECT i.* FROM {$wpdb->prefix}sn_invoices i
					 WHERE i.seller_id IN ({$ph}) AND {$approved_condition}
					 ORDER BY COALESCE(i.approved_at,i.financial_reviewed_at,i.paid_at,i.created_at) DESC, i.id DESC
					 LIMIT %d",
					...$args
				), ARRAY_A) ?: [];
				foreach ($rows as $inv) {
					$report['scanned']++;
					$invoice_id = (int) ($inv['id'] ?? 0);
					if ($invoice_id < 1) { continue; }
					$before = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND wallet_type='supervisor' AND type='supervisor_commission'", $invoice_id, $supervisor_id));
					$this->sn_credit_wallet_for_invoice($invoice_id, $inv, true);
					$after = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND wallet_type='supervisor' AND type='supervisor_commission'", $invoice_id, $supervisor_id));
					if ($after > $before) {
						$report['created'] += ($after - $before);
					} elseif ($before > 0) {
						$report['existing']++;
					} else {
						$report['no_amount']++;
					}
				}
				return $report;
			}


			public function render_wallet_box_for_user(int $user_id, string $wallet_type = 'seller', bool $include_finance_preview = true): string
			{
				if (! $user_id) {
					return '<div class="sn-card">کاربر نامعتبر است.</div>';
				}
				$autopost_report = [];
				if ($wallet_type === 'seller') {
					$autopost_report = $this->sn_wallet_autopost_recent_commissions_for_seller($user_id, 30);
				} elseif ($wallet_type === 'supervisor') {
					$autopost_report = $this->sn_wallet_autopost_recent_supervisor_commissions($user_id, 120);
				}
				$data = $this->sn_wallet_summary($user_id, $wallet_type);
				$w = $data['wallet'];
				// در پنل فروشنده، پیش‌نمایش محدود همیشه کمک می‌کند مشخص شود پرداخت تاییدشده قانون پورسانت دارد یا نه.
				$finance_preview_rows = ($wallet_type === 'seller') ? $this->sn_wallet_finance_commission_preview_rows($user_id, $include_finance_preview ? 20 : 8) : [];
				ob_start();
	?>
		<div class="sn-card sn-wallet-box" dir="rtl">
