			public function render_admin_wallets(): void
			{
				if (! current_user_can('manage_options') && ! current_user_can('sn_view_wallet_commission')) {
					wp_die('دسترسی غیرمجاز');
				}
				$can_manage_wallets = current_user_can('manage_options');
				$this->ensure_wallet_tables();
				global $wpdb;
				$role = sanitize_text_field($_GET['sn_wallet_role'] ?? '');
				$user_q = sanitize_text_field($_GET['sn_wallet_user'] ?? '');
				$where = '1=1';
				$args = [];
				if (in_array($role, ['seller', 'supervisor', 'biavin'], true)) {
					$where .= ' AND w.wallet_type=%s';
					$args[] = $role;
				}
				if ($user_q !== '') {
					$where .= ' AND (u.display_name LIKE %s OR u.user_login LIKE %s OR u.user_email LIKE %s OR hp.hr_display_name LIKE %s)';
					$like = '%' . $wpdb->esc_like($user_q) . '%';
					$args = array_merge($args, [$like, $like, $like, $like]);
				}
				$sql = "SELECT w.*, COALESCE(NULLIF(hp.hr_display_name,''), u.display_name, u.user_login) display_name, u.user_login, pos.label position_label, pos.slug position_slug
				FROM {$wpdb->prefix}sn_wallets w
				LEFT JOIN {$wpdb->users} u ON u.ID=w.user_id
				LEFT JOIN {$wpdb->prefix}sn_hr_profiles hp ON hp.user_id=w.user_id AND hp.is_active=1
				LEFT JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=hp.position_id
				WHERE {$where}
				ORDER BY w.updated_at DESC
				LIMIT 500";
				$wallets = $args ? $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) : $wpdb->get_results($sql, ARRAY_A);
				$summary_rows = $wpdb->get_results("SELECT wallet_type, COUNT(*) c, COALESCE(SUM(balance),0) balance, COALESCE(SUM(total_credit),0) credit, COALESCE(SUM(total_debit),0) debit FROM {$wpdb->prefix}sn_wallets GROUP BY wallet_type", ARRAY_A) ?: [];
				$summary = [];
				foreach ($summary_rows as $sr) { $summary[(string) $sr['wallet_type']] = $sr; }
				$report = get_option('sn_wallet_finance_recalculate_report', []);
				$nonce = wp_create_nonce('sn_admin');
	?>
