				<div class="sn-stat"><span><?php echo number_format_i18n((int) ($summary['supervisor']['c'] ?? 0)); ?></span><label>کیف پول سرپرستی</label></div>
				<div class="sn-stat sn-stat-primary"><span><?php echo esc_html(SN_Helpers::format_price((float) ($summary['supervisor']['balance'] ?? 0))); ?></span><label>مانده سرپرست‌ها</label></div>
				<div class="sn-stat"><span><?php echo number_format_i18n((int) ($summary['biavin']['c'] ?? 0)); ?></span><label>کیف پول بیاوین</label></div>
				<div class="sn-stat sn-stat-primary"><span><?php echo esc_html(SN_Helpers::format_price((float) ($summary['biavin']['balance'] ?? 0))); ?></span><label>مانده بیاوین</label></div>
