			public function ajax_wallet_manual_adjust(): void
			{
				if (! current_user_can('manage_options') || ! check_ajax_referer('sn_admin', 'nonce', false)) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				$user_id = absint($_POST['user_id'] ?? 0);
				$wallet_type = sanitize_key($_POST['wallet_type'] ?? 'seller');
				$wallet_type = in_array($wallet_type, ['seller', 'supervisor', 'biavin'], true) ? $wallet_type : 'seller';
				$amount = abs((float) ($_POST['amount'] ?? 0));
				$direction = sanitize_key($_POST['direction'] ?? 'debit');
				$desc = sanitize_text_field(wp_unslash($_POST['description'] ?? ''));
				if (! $user_id || $amount <= 0) {
					SN_Helpers::send_json(false, 'اطلاعات ناقص است');
					return;
				}
				$this->sn_add_wallet_transaction($user_id, $wallet_type, $amount, $direction === 'credit' ? 'credit' : 'debit', $direction === 'credit' ? 'manual_credit' : 'settlement', $desc ?: 'تراکنش دستی کیف پول', null, null, ['manual' => true]);
				SN_Helpers::send_json(true, 'تراکنش کیف پول ثبت شد');
			}

			public function ajax_wallet_recalculate(): void
			{
				$valid_nonce = check_ajax_referer('sn_admin', 'nonce', false) || check_ajax_referer('sn_public', 'nonce', false);
				if (! $valid_nonce || (! current_user_can('manage_options') && ! $this->sn_can_view_finance())) {
					SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
					return;
				}
				if (class_exists('SN_Purpose_Commission') && SN_Purpose_Commission::is_matrix_engine_enabled()) {
					SN_Purpose_Commission::instance()->queue_backfill();
					SN_Helpers::send_json(true, 'بازبینی فاکتورهای قدیمی در صف قرار گرفت. گزارش پیشرفت در صفحهٔ پورسانت نمایش داده می‌شود.');
					return;
				}
				global $wpdb;
				$rows = array_map(static fn($row) => (object) $row, $this->sn_commission_invoice_rows_for_wallet(null, 2000));
				$count = 0;
				$scanned = 0;
				$ready = 0;
				$no_rule = 0;
				$existing = 0;
				foreach ($rows as $inv) {
					$scanned++;
					$payload = $this->sn_commission_engine_wallet_payload((int) $inv->id, $inv);
					$seller_id = (int) (($payload['context']['seller_id'] ?? 0));
					$amount = (float) ($payload['commission_amount'] ?? 0);
					if (! $seller_id || $amount <= 0 || empty($payload['matched_rule_ids'])) {
						$no_rule++;
						continue;
					}
					if ($this->sn_wallet_existing_commission_transaction_id((int) $inv->id, $seller_id)) {
						$existing++;
						continue;
					}
					$ready++;
					$before = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND type='commission_engine'", (int)$inv->id, $seller_id));
					$this->sn_credit_wallet_for_invoice((int) $inv->id, $inv, true);
					$after = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_wallet_transactions WHERE invoice_id=%d AND user_id=%d AND type='commission_engine'", (int)$inv->id, $seller_id));
					if ($after > $before) {
						$count += ($after - $before);
					}
				}
				update_option('sn_wallet_finance_recalculate_report', [
					'scanned' => $scanned,
					'ready' => $ready,
					'created' => $count,
					'existing' => $existing,
					'no_rule_or_amount' => $no_rule,
					'updated_at' => current_time('mysql'),
				], false);
				SN_Helpers::send_json(true, sprintf('محاسبه مجدد انجام شد. بررسی‌شده: %d، آماده: %d، تراکنش جدید: %d، موجود از قبل: %d، بدون قانون/مبلغ: %d', $scanned, $ready, $count, $existing, $no_rule));
			}

