				];
			}

			private function sn_store_customer_action(string $code, string $action, string $label = '', string $extra_raw = ''): bool
			{
				$invoice = SN_Helpers::get_invoice_by_code($code);
				if (! $invoice) { return false; }
				$allowed = $this->sn_customer_action_labels();
				if (! isset($allowed[$action])) { $action = 'customer_action'; }
				$description = $allowed[$action] ?? ($label ?: 'اکشن مشتری در صفحه فاکتور');
				$extra = [];
				if (is_string($extra_raw) && $extra_raw !== '') {
					$decoded = json_decode($extra_raw, true);
					if (is_array($decoded)) { $extra = array_slice($decoded, 0, 12, true); }
				}
				$this->sn_log_activity((int)$invoice->id, (int)$invoice->lead_id, 'customer_' . sanitize_key($action), $description, array_merge($extra, [
					'invoice_code' => $code,
					'customer_phone' => (string)($invoice->customer_phone ?? ''),
					'label' => mb_substr($label, 0, 80),
				]));
				return true;
			}

			public function ajax_invoice_customer_action(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_customer_action', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'customer_action');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$action = sanitize_key(wp_unslash($_POST['event'] ?? 'customer_action'));
				$label = sanitize_text_field(wp_unslash($_POST['label'] ?? ''));
				$extra_raw = wp_unslash($_POST['extra'] ?? '');
				if ($code === '') { SN_Helpers::send_json(false, 'کد فاکتور نامعتبر است'); return; }
				$this->sn_store_customer_action($code, $action, $label, is_string($extra_raw) ? $extra_raw : '');
				SN_Helpers::send_json(true, 'ثبت شد');
			}

			public function ajax_invoice_customer_actions_batch(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_customer_actions_batch', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'customer_action_batch');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$raw = wp_unslash($_POST['events'] ?? '[]');
				$events = json_decode(is_string($raw) ? $raw : '[]', true);
				if ($code === '' || ! is_array($events)) { SN_Helpers::send_json(false, 'داده نامعتبر است'); return; }
				$count = 0;
				foreach (array_slice($events, 0, 10) as $e) {
					if (! is_array($e)) { continue; }
					$event = sanitize_key((string)($e['event'] ?? 'customer_action'));
					$label = sanitize_text_field((string)($e['label'] ?? ''));
					$extra = isset($e['extra']) && is_array($e['extra']) ? wp_json_encode(array_slice($e['extra'], 0, 12, true), JSON_UNESCAPED_UNICODE) : '';
					if ($this->sn_store_customer_action($code, $event, $label, $extra ?: '')) { $count++; }
				}
				SN_Helpers::send_json(true, 'ثبت شد', ['count' => $count]);
			}

			private function sn_customer_actions_scope_sql(int $user_id, array $invoice_cols): array
			{
				global $wpdb;
				if ($user_id < 1) { return ['allowed'=>false,'where'=>'1=0','params'=>[]]; }
				if (user_can($user_id, 'manage_options') || is_super_admin($user_id)) { return ['allowed'=>true,'where'=>'1=1','params'=>[]]; }
				$user = get_user_by('id', $user_id);
				$roles = $user instanceof WP_User ? (array) $user->roles : [];
				$position = $this->sn_fast_hr_position_for_user($user_id);
				if ($position === '') { $position = $this->sn_hr_position_for_user($user_id); }
				if ($position === '' && in_array('sn_seller', $roles, true)) { $position = 'seller'; }
				elseif ($position === '' && in_array('sn_converter', $roles, true)) { $position = 'converter'; }
				elseif ($position === '' && in_array('sn_supervisor', $roles, true)) { $position = 'supervisor'; }
				elseif ($position === '' && in_array('sn_senior_supervisor', $roles, true)) { $position = 'senior_supervisor'; }
				elseif ($position === '' && in_array('sn_sales_manager', $roles, true)) { $position = 'sales_manager'; }
				if (! in_array($position, ['seller','converter','supervisor','senior_supervisor','sales_manager'], true)) {
					return ['allowed'=>false,'where'=>'1=0','params'=>[]];
				}

				$owner_fields = array_values(array_intersect(['seller_id','original_seller_id','commission_seller_id'], $invoice_cols));
				if (! $owner_fields && in_array('seller_id', $invoice_cols, true)) { $owner_fields = ['seller_id']; }
				$parts = [];
				$params = [];
				if (in_array($position, ['seller','converter'], true)) {
					foreach ($owner_fields as $field) { $parts[] = "i.{$field}=%d"; $params[] = $user_id; }
					if (in_array('issued_by_user_id', $invoice_cols, true)) { $parts[] = 'i.issued_by_user_id=%d'; $params[] = $user_id; }
					if ($position === 'converter' && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_dot_cases')) {
						$parts[] = "EXISTS (SELECT 1 FROM {$wpdb->prefix}sn_dot_cases snca WHERE snca.source_invoice_id=i.id AND snca.converter_id=%d)";
						$params[] = $user_id;
					}
				} else {
					$seller_ids = array_values(array_unique(array_filter(array_map('absint', $position === 'sales_manager' ? $this->sn_sales_manager_scope_seller_ids($user_id) : $this->sn_get_seller_ids_in_hr_scope($user_id)))));
					if ($seller_ids) {
						$placeholders = implode(',', array_fill(0, count($seller_ids), '%d'));
						foreach ($owner_fields as $field) { $parts[] = "i.{$field} IN ({$placeholders})"; $params = array_merge($params, $seller_ids); }
					}
					if (in_array('issued_by_user_id', $invoice_cols, true)) { $parts[] = 'i.issued_by_user_id=%d'; $params[] = $user_id; }
					if (in_array($position, ['supervisor','senior_supervisor'], true) && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_dot_cases')) {
						$parts[] = "EXISTS (SELECT 1 FROM {$wpdb->prefix}sn_dot_cases snca WHERE snca.source_invoice_id=i.id AND (snca.supervisor_id=%d OR snca.converter_id=%d))";
						$params[] = $user_id; $params[] = $user_id;
					}
				}
				return ['allowed'=>true,'where'=>$parts ? '(' . implode(' OR ', $parts) . ')' : '1=0','params'=>$params];
			}

			public function ajax_seller_customer_actions(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$user = wp_get_current_user();
				$this->maybe_create_tables();
				global $wpdb;
				$page = max(1, absint($_POST['page'] ?? 1));
				$limit = min(30, max(10, absint($_POST['limit'] ?? 20)));
				$offset = ($page - 1) * $limit;
				$q = sanitize_text_field(wp_unslash($_POST['q'] ?? ''));
				$detail_invoice_id = absint($_POST['invoice_id'] ?? 0);

				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$invoice_cols = $this->sn_table_columns($invoice_table);
				$scope = $this->sn_customer_actions_scope_sql((int) $user->ID, $invoice_cols);
				if (empty($scope['allowed'])) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }

				if ($detail_invoice_id > 0) {
					if (! current_user_can('manage_options')) {
						$owned_sql = "SELECT COUNT(1) FROM {$invoice_table} i WHERE i.id=%d AND " . (string) $scope['where'];
						$owned_args = array_merge([$detail_invoice_id], (array) $scope['params']);
						$owned = (int) $wpdb->get_var($wpdb->prepare($owned_sql, ...$owned_args));
						if (! $owned) { SN_Helpers::send_json(false, 'مشاهده این فاکتور در محدوده دسترسی شما نیست'); return; }
					}
					$invoice_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d", $detail_invoice_id), ARRAY_A);
					$rows = $wpdb->get_results($wpdb->prepare(
						"SELECT a.id,a.invoice_id,a.lead_id,a.action,a.description,a.context,a.created_at,i.invoice_code,i.customer_name,i.customer_phone,l.phone
						 FROM {$wpdb->prefix}sn_activity_logs a
						 INNER JOIN {$invoice_table} i ON i.id=a.invoice_id
						 LEFT JOIN {$wpdb->prefix}sn_leads l ON l.id=a.lead_id
						 WHERE a.invoice_id=%d
						 ORDER BY a.id DESC LIMIT 300",
						$detail_invoice_id
					), ARRAY_A) ?: [];

					$synthetic = [];
					if ($invoice_row) {
						$created = (string) ($invoice_row['created_at'] ?? current_time('mysql'));
						$synthetic[] = [
							'id' => 0,
							'invoice_id' => $detail_invoice_id,
							'lead_id' => (int) ($invoice_row['lead_id'] ?? 0),
							'action' => 'invoice_created',
							'description' => 'پیش‌فاکتور صادر شد',
							'context' => '',
							'created_at' => $created,
							'invoice_code' => (string) ($invoice_row['invoice_code'] ?? ''),
							'customer_name' => (string) ($invoice_row['customer_name'] ?? ''),
							'customer_phone' => (string) ($invoice_row['customer_phone'] ?? ''),
							'phone' => '',
							'synthetic' => 1,
						];
						$status_values_lc = array_filter(array_map(static fn($v) => strtolower(trim((string) $v)), [
							$invoice_row['status'] ?? '',
							$invoice_row['payment_status'] ?? '',
							$invoice_row['invoice_status'] ?? '',
							$invoice_row['finance_status'] ?? '',
						]));
						$approved_values_lc = array_map('strtolower', $this->sn_commission_approved_status_values());
						$pending_values = ['receipt_uploaded','pending_financial_approval','card_submitted','payment_pending','pending'];
						$pending_like = (bool) array_intersect($status_values_lc, $pending_values);
						$paid_like = (bool) array_intersect($status_values_lc, $approved_values_lc);
						$payment_at = '';
						foreach (['paid_at','payment_confirmed_at','manual_paid_at','updated_at'] as $col) {
							if (! empty($invoice_row[$col]) && ! in_array((string) $invoice_row[$col], ['', '0000-00-00', '0000-00-00 00:00:00'], true)) { $payment_at = (string) $invoice_row[$col]; break; }
						}
						$approval_at = '';
						foreach (['financial_reviewed_at','approved_at','finance_approved_at','payment_approved_at','updated_at'] as $col) {
							if (! empty($invoice_row[$col]) && ! in_array((string) $invoice_row[$col], ['', '0000-00-00', '0000-00-00 00:00:00'], true)) { $approval_at = (string) $invoice_row[$col]; break; }
						}
						if ($pending_like) {
							$synthetic[] = [
								'id' => 0,
								'invoice_id' => $detail_invoice_id,
								'lead_id' => (int) ($invoice_row['lead_id'] ?? 0),
								'action' => 'payment_pending',
								'description' => 'پرداخت یا فیش در انتظار بررسی ثبت شد',
								'context' => '',
								'created_at' => $payment_at ?: $created,
								'invoice_code' => (string) ($invoice_row['invoice_code'] ?? ''),
								'customer_name' => (string) ($invoice_row['customer_name'] ?? ''),
								'customer_phone' => (string) ($invoice_row['customer_phone'] ?? ''),
								'phone' => '',
								'synthetic' => 1,
							];
						}
						if ($paid_like) {
							$synthetic[] = [
								'id' => 0,
								'invoice_id' => $detail_invoice_id,
								'lead_id' => (int) ($invoice_row['lead_id'] ?? 0),
								'action' => 'payment_approved',
								'description' => 'پرداخت / تایید مالی ثبت شد',
								'context' => '',
								'created_at' => $approval_at ?: ($payment_at ?: $created),
								'invoice_code' => (string) ($invoice_row['invoice_code'] ?? ''),
								'customer_name' => (string) ($invoice_row['customer_name'] ?? ''),
								'customer_phone' => (string) ($invoice_row['customer_phone'] ?? ''),
								'phone' => '',
								'synthetic' => 1,
							];
						}
					}
					$rows = array_merge($rows, $synthetic);
					usort($rows, static function($a, $b) {
						$at = SN_Helpers::site_mysql_timestamp((string) ($a['created_at'] ?? ''), 0);
						$bt = SN_Helpers::site_mysql_timestamp((string) ($b['created_at'] ?? ''), 0);
						if ($at === $bt) { return (int) ($b['id'] ?? 0) <=> (int) ($a['id'] ?? 0); }
						return $bt <=> $at;
					});
					foreach ($rows as &$r) {
						$r['created_at_jalali'] = SN_Helpers::gregorian_to_jalali_date($r['created_at'] ?? '');
					}
					SN_Helpers::send_json(true, '', ['items' => $rows ?: [], 'invoice_id' => $detail_invoice_id]);
					return;
				}

				$where = (string) $scope['where'];
				$params = (array) $scope['params'];
				if ($q !== '') {
					$like = '%' . $wpdb->esc_like($q) . '%';
					$where .= ' AND (i.customer_phone LIKE %s OR i.customer_name LIKE %s OR i.invoice_code LIKE %s)';
					array_push($params, $like, $like, $like);
				}
				$total = (int) $wpdb->get_var($params ? $wpdb->prepare("SELECT COUNT(1) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}", ...$params) : "SELECT COUNT(1) FROM {$wpdb->prefix}sn_invoices i WHERE {$where}");
				$params2 = array_merge($params, [$limit, $offset]);
				// 1.0.24 performance: avoid multiple correlated subqueries per invoice row.
				$finance_status_select = $this->sn_table_has_column($wpdb->prefix . 'sn_invoices', 'finance_status')
					? 'i.finance_status'
					: ($this->sn_table_has_column($wpdb->prefix . 'sn_invoices', 'financial_status') ? 'i.financial_status AS finance_status' : "'' AS finance_status");
				$sql = "SELECT i.id invoice_id,i.invoice_code,i.customer_name,i.customer_phone,i.status,i.payment_status,i.invoice_status,{$finance_status_select},
						la.description latest_action,
						la.action latest_action_key,
						la.created_at latest_at,
						COALESCE(ac.action_count,0) action_count
					FROM {$wpdb->prefix}sn_invoices i
					LEFT JOIN (
						SELECT invoice_id, MAX(id) latest_id, COUNT(1) action_count
						FROM {$wpdb->prefix}sn_activity_logs
						WHERE action LIKE 'customer_%%'
						GROUP BY invoice_id
					) ac ON ac.invoice_id=i.id
					LEFT JOIN {$wpdb->prefix}sn_activity_logs la ON la.id=ac.latest_id
					WHERE {$where}
					ORDER BY COALESCE(ac.latest_id,0) DESC, i.id DESC
					LIMIT %d OFFSET %d";
				$rows = $wpdb->get_results($wpdb->prepare($sql, ...$params2), ARRAY_A);
				$approved_values_lc = array_map('strtolower', $this->sn_commission_approved_status_values());
				foreach ($rows as &$r) {
					$r['latest_at_jalali'] = ! empty($r['latest_at']) ? SN_Helpers::gregorian_to_jalali_date($r['latest_at']) : '';
					if (empty($r['latest_action'])) {
						$status_values = array_filter(array_map(static fn($v) => strtolower(trim((string) $v)), [$r['status'] ?? '', $r['payment_status'] ?? '', $r['invoice_status'] ?? '', $r['finance_status'] ?? '']));
						$paid_like = (bool) array_intersect($status_values, $approved_values_lc);
						$pending_receipt = (bool) array_intersect($status_values, ['receipt_uploaded','pending_financial_approval','card_submitted']);
						$r['latest_action'] = $paid_like ? 'پرداخت / تایید مالی ثبت شده' : ($pending_receipt ? 'پرداخت یا فیش در انتظار بررسی' : 'پیش‌فاکتور صادر شده');
					}
					$r['customer_phone'] = $r['customer_phone'] ?: '';
					$r['customer_name'] = $r['customer_name'] ?: '—';
				}
				SN_Helpers::send_json(true, '', ['items' => $rows ?: [], 'total' => $total, 'page' => $page, 'limit' => $limit, 'has_more' => ($offset + $limit) < $total]);
			}

			public function ajax_invoice_recontact(): void
			{
				$public_nonce = check_ajax_referer('sn_public', 'nonce', false);
				$admin_nonce = check_ajax_referer('sn_admin', 'nonce', false);
				if (! $public_nonce && ! $admin_nonce) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				$invoice_id = absint($_POST['invoice_id'] ?? 0);
				$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
				global $wpdb;
				$invoice = null;
				if ($invoice_id > 0) {
					$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
					if ($invoice && $code === '') {
						$code = (string) ($invoice->invoice_code ?? '');
					}
				}
				if (! $invoice && $code !== '') {
					$invoice = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE invoice_code=%s", $code));
				}
				if (is_user_logged_in() && ! $invoice && ($code !== '' || $invoice_id > 0)) {
					SN_Helpers::send_json(false, 'فاکتور یافت نشد');
					return;
				}
				if (is_user_logged_in() && $invoice) {
					$internal_access = $this->sn_internal_invoice_info_access($invoice, get_current_user_id(), $code);
					if (! empty($internal_access['allowed'])) {
						if (in_array((string) $invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'این فاکتور قابل ارجاع مجدد نیست'); return; }
						$wpdb->update($wpdb->prefix . 'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_invoices', [
							'status' => 'recontact_requested',
							'invoice_status' => 'recontact_requested',
							'recontact_requested_at' => current_time('mysql'),
							'recontact_note' => $note,
							'updated_at' => current_time('mysql'),
						]), ['id' => (int) $invoice->id]);
						$this->sn_log_activity((int) $invoice->id, (int) $invoice->lead_id, 'invoice_recontact_requested', 'درخواست ارتباط مجدد با کارشناس توسط کاربر داخلی', ['note' => $note, 'internal_user_id' => get_current_user_id()]);
						SN_Helpers::send_json(true, 'فاکتور به کارشناس مربوطه ارجاع داده شد.', ['status' => 'recontact_requested', 'internal' => true]);
						return;
					}
					SN_Helpers::send_json(false, 'دسترسی داخلی به این فاکتور مجاز نیست');
					return;
				}
				if (! $public_nonce) { SN_Helpers::send_json(false, 'دسترسی عمومی به فاکتور نیازمند لینک معتبر است'); return; }
				if (! $this->sn_rate_limit_public_or_json('invoice_recontact', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'recontact');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice || in_array((string) $invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'این فاکتور قابل ارجاع مجدد نیست'); return; }
				$this->maybe_create_tables();
				$wpdb->update($wpdb->prefix . 'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix . 'sn_invoices', [
					'status' => 'recontact_requested',
					'invoice_status' => 'recontact_requested',
					'recontact_requested_at' => current_time('mysql'),
					'recontact_note' => $note,
					'updated_at' => current_time('mysql'),
				]), ['id' => (int) $invoice->id]);
				$this->sn_log_activity((int) $invoice->id, (int) $invoice->lead_id, 'invoice_recontact_requested', 'درخواست ارتباط مجدد با کارشناس توسط مشتری', ['note' => $note]);
				SN_Helpers::send_json(true, 'فاکتور شما به کارشناس مربوطه ارجاع داده شد. منتظر تماس کارشناس باشید.', ['status' => 'recontact_requested']);
			}

            public function ajax_seller_resend_financial(): void
            {
                $nonce_ok = check_ajax_referer('sn_public', 'nonce', false) || check_ajax_referer('sn_admin', 'nonce', false);
                if (! is_user_logged_in() || ! $nonce_ok) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
                $user = wp_get_current_user();
                $actor_position = $this->sn_hr_position_for_user((int) $user->ID);
                $is_seller = in_array('sn_seller', (array) $user->roles, true) || $actor_position === 'seller';
                $is_converter = in_array('sn_converter', (array) $user->roles, true) || $actor_position === 'converter';
                if (! $is_seller && ! $is_converter && ! current_user_can('manage_options')) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }

                $id = absint($_POST['invoice_id'] ?? 0);
                $note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
                if ($id < 1) { SN_Helpers::send_json(false, 'شناسه فاکتور نامعتبر است'); return; }

				$card_from = preg_replace('/\D+/', '', sanitize_text_field(wp_unslash($_POST['card_from'] ?? '')));
				$card_to_raw = sanitize_text_field(wp_unslash($_POST['card_to'] ?? ''));
				$amount_raw = str_replace(',', '', SN_Helpers::to_english_nums(sanitize_text_field(wp_unslash($_POST['amount'] ?? ''))));
				$paid_at = sanitize_text_field(wp_unslash($_POST['paid_at'] ?? ''));
				if ($paid_at !== '') {
					$payment_date = $this->sn_validate_jalali_payment_datetime($paid_at);
					if (empty($payment_date['success'])) { SN_Helpers::send_json(false, (string)($payment_date['message'] ?? 'تاریخ و ساعت واریز معتبر نیست')); return; }
					$paid_at = (string)$payment_date['jalali'];
				}
				if ($card_from !== '' && ! preg_match('/^\d{4}$/', $card_from)) { SN_Helpers::send_json(false, '۴ رقم کارت مبدا معتبر نیست'); return; }
				$card_to_input_digits = preg_replace('/[^0-9]+/', '', SN_Helpers::to_english_nums($card_to_raw));
				if ($card_to_raw !== '' && (! is_string($card_to_input_digits) || strlen($card_to_input_digits) !== 4)) { SN_Helpers::send_json(false, '۴ رقم آخر کارت مقصد معتبر نیست'); return; }
                $corrected_amount = null;
                if ($amount_raw !== '') {
                    if (! is_numeric($amount_raw) || (float) $amount_raw <= 0) { SN_Helpers::send_json(false, 'مبلغ اصلاحی معتبر نیست'); return; }
                    $corrected_amount = (float) $amount_raw;
                }

                $receipt_uploaded = false;
                $new_receipt_url = '';

                $this->sn_ensure_payment_migrations();
                global $wpdb;
                $invoice_table = $wpdb->prefix . 'sn_invoices';
                $stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
                $payments_table = $wpdb->prefix . 'sn_payments';
                $wpdb->query('START TRANSACTION');
                $inv = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$invoice_table} WHERE id=%d FOR UPDATE", $id));
                if (! $inv) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'فاکتور پیدا نشد'); return; }
				$destination_seed = $card_to_raw !== '' ? $card_to_raw : (string) (($inv->manual_card_to ?? '') ?: ($inv->deposit_card_to_last4 ?? '') ?: ($inv->manual_card_to_number ?? ''));
				$destination = $this->sn_manual_destination_card_input($destination_seed, $inv, true);
				if (empty($destination['valid'])) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, '۴ رقم آخر کارت مقصد اختیاری است؛ در صورت ورود باید ۴ رقم باشد'); return; }
				$card_to_number = (string) ($destination['number'] ?? '');
				$card_to = (string) ($destination['last4'] ?? '');
				if ($is_seller && ! $is_converter && $this->sn_invoice_is_conversion_payment($id) && (int) ($inv->issued_by_user_id ?? 0) !== (int) $user->ID) {
					$wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'این فاکتور تبدیل توسط شما صادر نشده است'); return;
				}

                $owner_allowed = current_user_can('manage_options');
                if (! $owner_allowed) {
                    foreach ($this->sn_invoice_owner_fields() as $owner_field) {
                        if (isset($inv->{$owner_field}) && (int) $inv->{$owner_field} === (int) $user->ID) { $owner_allowed = true; break; }
                    }
                }
                if (! $owner_allowed && ! empty($inv->lead_id) && $this->sn_table_exists_quiet($wpdb->prefix . 'sn_leads')) {
                    $lead_seller_id = (int) $wpdb->get_var($wpdb->prepare("SELECT seller_id FROM {$wpdb->prefix}sn_leads WHERE id=%d", (int) $inv->lead_id));
                    if ($lead_seller_id === (int) $user->ID) { $owner_allowed = true; }
                }
                if (! $owner_allowed) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'فاکتور متعلق به شما نیست'); return; }

                $returned = in_array((string) ($inv->status ?? ''), ['rejected','returned_to_seller','financial_rejected'], true)
                    || in_array((string) ($inv->invoice_status ?? ''), ['rejected','returned_to_seller','financial_rejected'], true)
                    || in_array((string) ($inv->payment_status ?? ''), ['rejected','returned_to_seller','financial_rejected'], true)
                    || in_array((string) ($inv->financial_return_state ?? ''), ['returned_to_seller','rejected'], true);
                if (! $returned) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'فقط فاکتور برگشت‌خورده از مالی قابل ارسال مجدد است'); return; }
                $independent_count = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$payments_table} WHERE invoice_id=%d AND payment_stage_no=%d AND proof_data IS NOT NULL",$id,max(1,(int)($inv->current_payment_stage ?? 1))));
                if ($independent_count > 0) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false,'برای این فاکتور از «ثبت تراکنش جدید» استفاده کنید؛ تراکنش‌های ردشده در سوابق باقی می‌مانند'); return; }

				if (SN_Helpers::has_receipt_upload($_FILES['receipt'] ?? [])) {
					$upload = SN_Helpers::upload_receipt($_FILES['receipt']); // phpcs:ignore
					if (empty($upload['success']) || empty($upload['url'])) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, (string) ($upload['message'] ?? 'خطا در آپلود فیش جدید')); return; }
					$new_receipt_url = (string) $upload['url'];
					$receipt_uploaded = true;
				}

                $totals = $this->sn_invoice_payment_totals($inv);
                $stage_no = max(1, (int) ($totals['stage_no'] ?? 1));
                $remaining = max(0, (float) ($totals['remaining'] ?? 0));
                if ($remaining <= 0.5 || ($totals['workflow_status'] ?? '') === 'completed') { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'این فاکتور قبلاً تسویه شده و قابل ارسال مجدد نیست'); return; }

                $stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $id, $stage_no));
                if (! $stage) {
                    $compat_due = (float) ($totals['due'] ?? 0) > 0.5 ? (float) $totals['due'] : $remaining;
                    if ($compat_due <= 0.5 || ! $this->sn_create_invoice_payment_stage($id, $stage_no, $stage_no === 1 ? (string) ($totals['plan'] ?? 'full') : 'partial', $compat_due, (int) ($inv->current_stage_issued_by_user_id ?? $inv->seller_id ?? 0), 'بازیابی مرحله ردشده برای ارسال مجدد به مالی')) {
                        $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'مرحله پرداخت ردشده قابل بازیابی نیست'); return;
                    }
                    $stage = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d AND stage_no=%d FOR UPDATE", $id, $stage_no));
                }
                if (! $stage || ! in_array((string) $stage->status, ['rejected','expired','pending_financial_approval','receipt_uploaded'], true)) {
                    $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'مرحله فعال در وضعیت قابل اصلاح و ارسال مجدد نیست'); return;
                }

                $stage_amount = $corrected_amount !== null ? $corrected_amount : max(0, (float) ($stage->requested_amount ?? ($totals['due'] ?? 0)));
                if ($stage_amount <= 0.5) { $stage_amount = $remaining; }
                if ($stage_amount - $remaining > 0.5) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'مبلغ اصلاحی نمی‌تواند بیشتر از مانده واقعی فاکتور باشد'); return; }

                $now = current_time('mysql');
                $corrections = [];
                $invoice_update = [
                    'status' => 'pending_financial_approval', 'invoice_status' => 'pending_financial_approval', 'payment_status' => 'pending_financial_approval',
                    'payment_workflow_status' => 'awaiting_financial_approval', 'current_due_amount' => $stage_amount,
                    'resend_to_financial_at' => $now, 'financial_return_state' => 'resent_after_return', 'resent_after_return_at' => $now, 'updated_at' => $now,
					'rejected_reason' => null, 'financial_reject_reason' => null, 'rejected_at' => null, 'financial_rejected_at' => null,
					'rejected_by' => null, 'financial_rejected_by' => null,
                ];
                if ($card_from !== '') { $invoice_update['manual_card_from'] = $card_from; $invoice_update['deposit_card_from_last4'] = $card_from; $corrections['card_from'] = $card_from; }
				if ($card_to !== '') { $invoice_update['manual_card_to'] = $card_to; $invoice_update['manual_card_to_number'] = $card_to_number !== '' ? $card_to_number : null; $invoice_update['deposit_card_to_last4'] = $card_to; $corrections['card_to'] = $card_to; }
                if ($corrected_amount !== null) { $invoice_update['manual_amount'] = $stage_amount; $invoice_update['deposit_amount'] = $stage_amount; $corrections['amount'] = $stage_amount; }
                if ($paid_at !== '') { $invoice_update['manual_paid_at_jalali'] = $paid_at; $invoice_update['deposit_jalali_datetime'] = $paid_at; $corrections['paid_at'] = $paid_at; }
                if ($receipt_uploaded) {
                    $invoice_update['receipt_urls'] = wp_json_encode($upload['urls']);
                    $invoice_update['receipt_url'] = $new_receipt_url; $invoice_update['receipt_file'] = $new_receipt_url; $invoice_update['receipt_source'] = 'seller_resubmit';
                    $invoice_update['pay_method'] = 'card'; $invoice_update['payment_source'] = 'seller_resubmit';
                }
                if (false === $wpdb->update($invoice_table, $this->sn_filter_existing_columns_fresh($invoice_table, $invoice_update), ['id' => $id])) {
                    $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'وضعیت فاکتور برای ارسال مجدد ذخیره نشد'); return;
                }

                $stage_type = $stage_amount >= $remaining - 0.5 ? 'remaining' : 'partial';
                if ($stage_no === 1 && $stage_amount >= $remaining - 0.5 && max(0, (float) ($totals['paid'] ?? 0)) <= 0.5) { $stage_type = 'full'; }
                $stage_update = [
                    'status' => 'pending_financial_approval', 'stage_type' => $stage_type, 'requested_amount' => $stage_amount,
                    'approved_by_user_id' => null, 'approved_at' => null, 'paid_at' => null, 'updated_at' => $now,
                ];
                if ($receipt_uploaded) { $stage_update['receipt_urls'] = wp_json_encode($upload['urls']); }
                if ($receipt_uploaded || $card_from !== '' || $card_to !== '') { $stage_update['pay_method'] = 'card'; $stage_update['payment_source'] = 'seller_resubmit'; }
                if (false === $wpdb->update($stage_table, $stage_update, ['id' => (int) $stage->id])) {
                    $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'مرحله پرداخت برای بررسی مجدد باز نشد'); return;
                }

                $pay_method = sanitize_key((string) ($stage_update['pay_method'] ?? ($stage->pay_method ?? ($inv->pay_method ?? 'card'))));
                if ($this->sn_table_exists_quiet($payments_table)) {
                    if ($pay_method !== 'online') {
                        $pending_id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$payments_table} WHERE invoice_id=%d AND payment_stage_no=%d AND status='pending' AND (authority IS NULL OR authority='') ORDER BY id DESC LIMIT 1 FOR UPDATE", $id, $stage_no));
                        $payment_data = $this->sn_filter_existing_columns($payments_table, [
                            'invoice_id' => $id, 'payment_stage_no' => $stage_no, 'amount' => $stage_amount, 'status' => 'pending', 'pay_method' => 'card',
                            'payment_source' => 'seller_resubmit', 'uploaded_by_type' => $is_converter ? 'converter' : 'seller', 'uploaded_by_user_id' => (int) $user->ID, 'updated_at' => $now, 'created_at' => $now,
                        ]);
                        if ($pending_id > 0) {
                            unset($payment_data['created_at']);
                            $payment_ok = false !== $wpdb->update($payments_table, $payment_data, ['id' => $pending_id]);
                        } else {
                            $payment_ok = (bool) $wpdb->insert($payments_table, $payment_data);
                        }
                        if (! $payment_ok) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'رکورد بررسی مجدد پرداخت ساخته نشد'); return; }
                    } else {
                        // Finance may reject an already verified gateway payment. When the
                        // seller corrects metadata and resubmits that same payment, restore
                        // its verification marker so downstream Dot/Woo hooks can close it
                        // normally after Finance approves it again.
                        $online_update = $this->sn_filter_existing_columns($payments_table, ['status'=>'verified','payment_source'=>'seller_resubmit','updated_at'=>$now]);
                        if ($online_update) {
                            $set=[]; $args=[];
                            foreach ($online_update as $col=>$value) { $set[] = "`{$col}`=%s"; $args[] = $value; }
                            $args[] = $id; $args[] = $stage_no;
                            $sql = "UPDATE {$payments_table} SET " . implode(', ', $set) . " WHERE invoice_id=%d AND payment_stage_no=%d AND status='rejected' AND COALESCE(authority,'')<>''";
                            if (false === $wpdb->query($wpdb->prepare($sql, ...$args))) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'وضعیت تراکنش درگاهی برای بررسی مجدد بازیابی نشد'); return; }
                        }
                    }
                }

                if (class_exists('SN_Dot_Flow') && method_exists(SN_Dot_Flow::instance(), 'financial_resubmit_apply_in_transaction')) {
                    $dot_result = (array) SN_Dot_Flow::instance()->financial_resubmit_apply_in_transaction($id, $note);
                    if (isset($dot_result['success']) && ! $dot_result['success']) {
                        $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, (string) ($dot_result['message'] ?? 'هماهنگ‌سازی دات‌فلو برای ارسال مجدد انجام نشد')); return;
                    }
                }

                if (false === $wpdb->query('COMMIT')) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'ثبت نهایی فیش‌ها انجام نشد'); return; }
                if ($receipt_uploaded) { SN_Helpers::commit_receipt_uploads($upload['urls']); }
                $this->sn_log_activity($id, (int) ($inv->lead_id ?? 0), 'seller_resend_to_financial', 'اصلاح و ارسال مجدد فاکتور ردشده برای بررسی مالی', [
                    'note' => $note, 'stage_no' => $stage_no, 'stage_amount' => $stage_amount, 'corrections' => $corrections,
                    'receipt_reuploaded' => $receipt_uploaded, 'old_receipt_url' => (string) ($inv->receipt_url ?? ($inv->receipt_file ?? '')),
                    'old_receipt_urls' => SN_Helpers::receipt_urls($inv), 'new_receipt_urls' => $receipt_uploaded ? $upload['urls'] : [],
                    'new_receipt_url' => $new_receipt_url, 'old_stage_status' => (string) $stage->status, 'new_stage_status' => 'pending_financial_approval',
                ]);
                SN_Helpers::send_json(true, $receipt_uploaded ? 'اصلاحات و فیش جدید ثبت شد و مرحله دوباره به صف تایید مالی برگشت' : 'اصلاحات ثبت شد و مرحله دوباره به صف تایید مالی برگشت', [
                    'receipt_reuploaded' => $receipt_uploaded, 'stage_no' => $stage_no, 'stage_amount' => $stage_amount,
                ]);
            }

			public function ajax_financial_invoices(): void
			{
				if (! $this->sn_can_view_finance()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$valid = check_ajax_referer('sn_admin', 'nonce', false) || check_ajax_referer('sn_public', 'nonce', false);
				if (! $valid) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$this->maybe_create_tables();
				$tab = sanitize_key($_POST['tab'] ?? 'needs_review');
				$page = max(1, absint($_POST['page'] ?? 1));
				$limit = min(100, max(10, absint($_POST['limit'] ?? 30)));
				$q = trim(sanitize_text_field(wp_unslash($_POST['q'] ?? '')));
				$q_english = trim(SN_Helpers::to_english_nums($q));
				$q_digits = preg_replace('/\D+/u', '', $q_english);
				$sort = sanitize_key($_POST['sort'] ?? 'deposit_newest');
				$can_approve = $this->sn_can_approve_payment();
				$can_reject = $this->sn_can_reject_payment();
				global $wpdb;

				$invoice_table = $wpdb->prefix . 'sn_invoices';
				$payment_table = $wpdb->prefix . 'sn_payments';
				$hr_table = $wpdb->prefix . 'sn_hr_profiles';
				$invoice_cols = $this->sn_table_columns($invoice_table);

				// Finance tabs share their predicates with the counters. Old receipt data
				// must not return a reviewed deposit (including partial payments) to the queue.
				$pending = "(COALESCE(i.status,'') IN ('pending_financial_approval','receipt_uploaded') OR COALESCE(i.payment_status,'') IN ('pending_financial_approval','receipt_uploaded') OR COALESCE(i.invoice_status,'') IN ('pending_financial_approval','receipt_uploaded'))";
				$closed = "(COALESCE(i.status,'') IN ('approved','paid','rejected','cancelled','payment_archived') OR COALESCE(i.payment_status,'') IN ('approved','paid','rejected','cancelled','payment_archived') OR COALESCE(i.invoice_status,'') IN ('approved','paid','rejected','cancelled','payment_archived'))";
				$receipt_uploaded = "(COALESCE(i.receipt_url,'')<>'' OR COALESCE(i.receipt_file,'')<>'')";
				$manual_info = "(COALESCE(i.manual_card_from,'')<>'' OR COALESCE(i.deposit_card_from_last4,'')<>'' OR COALESCE(i.manual_amount,0)>0 OR COALESCE(i.deposit_amount,0)>0)";
				$manual_deposit = "({$manual_info} AND NOT {$receipt_uploaded} AND COALESCE(i.pay_method,'') NOT IN ('online','gateway','zibal','zarinpal'))";
				$reviewed = "(COALESCE(i.approved_at,'')<>'' OR COALESCE(i.financial_reviewed_at,'')<>'' OR COALESCE(i.status,'')='partial_paid' OR COALESCE(i.payment_status,'')='partial_paid' OR COALESCE(i.invoice_status,'')='partial_paid')";
				$needs = "(NOT {$closed} AND ({$pending} OR (({$receipt_uploaded} OR {$manual_deposit}) AND NOT {$reviewed})))";
				$rejected = "(COALESCE(i.status,'')='rejected' OR COALESCE(i.payment_status,'')='rejected' OR COALESCE(i.invoice_status,'')='rejected')";
				$cancelled = "(COALESCE(i.status,'') IN ('cancelled','payment_archived') OR COALESCE(i.payment_status,'') IN ('cancelled','payment_archived') OR COALESCE(i.invoice_status,'') IN ('cancelled','payment_archived'))";
				$approved = "(NOT {$pending} AND NOT {$rejected} AND NOT {$cancelled} AND (COALESCE(i.status,'')='approved' OR COALESCE(i.payment_status,'')='approved' OR COALESCE(i.invoice_status,'')='approved' OR (COALESCE(i.approved_by,0)>0 AND COALESCE(i.approved_at,'')<>'')))";
				$returned = "(i.financial_return_state IN ('returned_to_seller','resent_after_return','cancelled_by_finance','cancelled_by_finance_refund'))";
				$online_paid = "(i.pay_method IN ('online','gateway','zibal','zarinpal') AND COALESCE(i.status,'') IN ('paid','approved','partial_paid') AND NOT {$pending} AND NOT {$rejected} AND NOT {$cancelled})";

				// One authoritative bucket per invoice: outcome first, then pending evidence.
				// Reuse the CASE for lists and grouped counters to prevent overlapping tabs.
				$review_queue = $needs;
				$finance_bucket = "CASE WHEN {$rejected} THEN 'rejected' WHEN {$approved} THEN 'approved' WHEN {$online_paid} THEN 'online_paid' WHEN {$review_queue} AND {$receipt_uploaded} THEN 'receipt_uploaded' WHEN {$review_queue} AND {$manual_deposit} THEN 'manual_deposit' WHEN {$review_queue} THEN 'needs_review' ELSE '' END";
				$needs = "({$finance_bucket}) IN ('needs_review','manual_deposit','receipt_uploaded')";
				$manual_deposit = "({$finance_bucket})='manual_deposit'";
				$receipt_uploaded = "({$finance_bucket})='receipt_uploaded'";
				$online_paid = "({$finance_bucket})='online_paid'";
				$approved = "({$finance_bucket})='approved'";
				$rejected = "({$finance_bucket})='rejected'";
				$all_finance = "({$finance_bucket})<>''";

				if ($tab === 'all') { $base_where = $all_finance; }
				elseif ($tab === 'online_paid') { $base_where = $online_paid; }
				elseif ($tab === 'approved') { $base_where = $approved; }
				elseif ($tab === 'rejected') { $base_where = $rejected; }
				elseif ($tab === 'manual_deposit') { $base_where = $manual_deposit; }
				elseif ($tab === 'receipt_uploaded') { $base_where = $receipt_uploaded; }
				else { $base_where = $needs; }

				$where_parts = ['(' . $base_where . ')'];
				$where_args = [];
				$join_hr = $this->sn_table_exists_quiet($hr_table);
				$join_payments = $this->sn_table_exists_quiet($payment_table);

				if ($q_english !== '') {
					// Keep search inside the selected tab; use 'all' for a global search.
					$like = '%' . $wpdb->esc_like($q_english) . '%';
					$digit_like = $q_digits !== '' ? '%' . $wpdb->esc_like($q_digits) . '%' : $like;
					$search = [];
					if ($q_digits !== '') {
						$search[] = 'CAST(i.id AS CHAR) LIKE %s'; $where_args[] = $digit_like;
						if (ctype_digit($q_digits)) { $search[] = 'i.id=%d'; $where_args[] = (int) $q_digits; }
					}
					foreach (['invoice_code','customer_name','province','city','financial_reject_reason','rejected_reason','manual_paid_at_jalali','payment_source','receipt_source'] as $col) {
						if (in_array($col, $invoice_cols, true)) { $search[] = "i.{$col} LIKE %s"; $where_args[] = $like; }
					}
					foreach (['customer_phone','manual_card_from','manual_card_to','manual_card_to_number','payment_card_number','deposit_card_from_last4','deposit_card_to_last4'] as $col) {
						if (in_array($col, $invoice_cols, true)) { $search[] = "i.{$col} LIKE %s"; $where_args[] = $digit_like; }
					}
					foreach (['manual_amount','deposit_amount','final_total','product_price','paid_total_amount','remaining_amount'] as $col) {
						if ($q_digits !== '' && in_array($col, $invoice_cols, true)) { $search[] = "CAST(i.{$col} AS CHAR) LIKE %s"; $where_args[] = $digit_like; }
					}
					$search[] = 'u.display_name LIKE %s'; $where_args[] = $like;
					$search[] = 'u.user_login LIKE %s'; $where_args[] = $like;
					if ($join_hr) { $search[] = 'hp.hr_display_name LIKE %s'; $where_args[] = $like; }
					if ($join_payments) {
						$search[] = "EXISTS (SELECT 1 FROM {$payment_table} sp WHERE sp.invoice_id=i.id AND (COALESCE(sp.ref_id,'') LIKE %s OR COALESCE(sp.payment_source,'') LIKE %s OR CAST(COALESCE(sp.amount,0) AS CHAR) LIKE %s))";
						$where_args[] = $like; $where_args[] = $like; $where_args[] = $digit_like;
					}
					$where_parts[] = '(' . implode(' OR ', $search) . ')';
				}
				$where = implode(' AND ', $where_parts);

				$join = "LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id";
				$seller_expr = "COALESCE(u.display_name, CONCAT('#', i.seller_id))";
				if ($join_hr) {
					$join .= " LEFT JOIN {$hr_table} hp ON hp.user_id=i.seller_id AND hp.is_active=1";
					$seller_expr = "COALESCE(NULLIF(hp.hr_display_name,''), u.display_name, CONCAT('#', i.seller_id))";
				}
				if ($join_payments) {
					$join .= " LEFT JOIN {$payment_table} p ON p.id=(SELECT p2.id FROM {$payment_table} p2 WHERE p2.invoice_id=i.id ORDER BY p2.id DESC LIMIT 1)";
				}

				$count_sql = "SELECT COUNT(DISTINCT i.id) FROM {$invoice_table} i {$join} WHERE {$where}";
				$sum_sql = "SELECT COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) FROM {$invoice_table} i {$join} WHERE {$where}";
				$total = (int) ($where_args ? $wpdb->get_var($wpdb->prepare($count_sql, ...$where_args)) : $wpdb->get_var($count_sql));
				$sum = (float) ($where_args ? $wpdb->get_var($wpdb->prepare($sum_sql, ...$where_args)) : $wpdb->get_var($sum_sql));
				$total_pages = max(1, (int) ceil($total / $limit));
				if ($page > $total_pages) { $page = $total_pages; }
				$offset = ($page - 1) * $limit;

				if ($join_payments) {
					$payment_newest = 'COALESCE(p.created_at,i.updated_at,i.created_at)';
					$payment_amount = 'COALESCE(p.amount,i.manual_amount,i.deposit_amount,0)';
				} else {
					$payment_newest = 'COALESCE(i.updated_at,i.created_at)';
					$payment_amount = 'COALESCE(i.manual_amount,i.deposit_amount,0)';
				}
				$order_map = [
					'deposit_newest' => $payment_newest . ' DESC, i.id DESC', 'deposit_oldest' => $payment_newest . ' ASC, i.id ASC',
					'newest' => 'i.updated_at DESC, i.id DESC', 'oldest' => 'i.updated_at ASC, i.id ASC',
					'invoice_asc' => 'i.invoice_code ASC, i.id ASC', 'invoice_desc' => 'i.invoice_code DESC, i.id DESC',
					'customer_asc' => 'i.customer_name ASC, i.id DESC', 'customer_desc' => 'i.customer_name DESC, i.id DESC',
					'seller_asc' => 'seller_name ASC, i.id DESC', 'seller_desc' => 'seller_name DESC, i.id DESC',
					'status_asc' => 'i.status ASC, i.id DESC', 'status_desc' => 'i.status DESC, i.id DESC',
					'phone_asc' => 'i.customer_phone ASC, i.id DESC', 'phone_desc' => 'i.customer_phone DESC, i.id DESC',
					'amount_desc' => 'COALESCE(i.final_total,i.product_price,0) DESC, i.id DESC', 'amount_asc' => 'COALESCE(i.final_total,i.product_price,0) ASC, i.id DESC',
					'payment_desc' => $payment_amount . ' DESC, i.id DESC', 'payment_asc' => $payment_amount . ' ASC, i.id DESC',
					'receipt_first' => "(COALESCE(i.receipt_url,'')<>'' OR COALESCE(i.receipt_file,'')<>'') DESC, i.updated_at DESC, i.id DESC",
					'manual_first' => "(COALESCE(i.manual_card_from,'')<>'' OR COALESCE(i.deposit_card_from_last4,'')<>'') DESC, i.updated_at DESC, i.id DESC",
				];
				$order = $order_map[$sort] ?? $order_map['deposit_newest'];

				if ($join_payments) {
					$payment_select = ', p.uploaded_by_type latest_uploaded_by_type, p.uploaded_by_user_id latest_uploaded_by_user_id, p.amount latest_payment_amount, p.status latest_payment_status, p.pay_method latest_payment_method, p.payment_source latest_payment_source, p.payment_stage_no latest_payment_stage_no, p.ref_id latest_payment_ref_id, p.created_at latest_payment_created_at';
				} else {
					$payment_select = ", '' latest_uploaded_by_type, 0 latest_uploaded_by_user_id, 0 latest_payment_amount, '' latest_payment_status, '' latest_payment_method, '' latest_payment_source, 1 latest_payment_stage_no, '' latest_payment_ref_id, '' latest_payment_created_at";
				}
				$select = "SELECT i.*, {$seller_expr} seller_name {$payment_select} FROM {$invoice_table} i {$join} WHERE {$where} ORDER BY {$order} LIMIT %d OFFSET %d";
				$query_args = array_merge($where_args, [$limit, $offset]);
				$rows = $wpdb->get_results($wpdb->prepare($select, ...$query_args), ARRAY_A) ?: [];

				// Marketing Dot Flow source invoices are created under dedicated system
				// sellers. Cache the marker once per seller so Finance can identify the
				// transaction without changing the proven finance queue predicate.
				$dot_marketing_sellers = [];
				foreach ($rows as $finance_row) {
					$sid = absint($finance_row['seller_id'] ?? 0);
					if ($sid > 0 && ! array_key_exists($sid, $dot_marketing_sellers)) {
						$dot_marketing_sellers[$sid] = (string) get_user_meta($sid, '_sn_dot_marketing_seller', true) === '1';
					}
				}

                $finance_transactions = [];
                $finance_invoice_ids = array_values(array_filter(array_map('intval',array_column($rows,'id'))));
                if ($finance_invoice_ids && $join_payments) {
                    $raw_transactions = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$payment_table} WHERE invoice_id IN (".implode(',',array_fill(0,count($finance_invoice_ids),'%d')).") ORDER BY id ASC",...$finance_invoice_ids),ARRAY_A) ?: [];
                    foreach ($raw_transactions as $transaction) { $finance_transactions[(int)$transaction['invoice_id']][] = $transaction; }
                }
				foreach ($rows as &$r) {
					$source = (string) (($r['latest_payment_source'] ?? '') ?: ($r['payment_source'] ?? '') ?: ($r['receipt_source'] ?? '') ?: ($r['latest_uploaded_by_type'] ?? ''));
					$r['status_label'] = $this->sn_invoice_review_status_label($r);
					$r['pay_method_label'] = SN_Helpers::pay_method_label((string) (($r['latest_payment_method'] ?? '') ?: ($r['pay_method'] ?? '')));
					$r['payment_source_label'] = SN_Helpers::payment_source_label($source);
					$receipt_url = (string) (($r['receipt_url'] ?? '') ?: ($r['receipt_file'] ?? ''));
					$manual_from = (string) (($r['manual_card_from'] ?? '') ?: ($r['deposit_card_from_last4'] ?? ''));
					$manual_to = $this->sn_manual_destination_card_display($r);
					$manual_amount = (string) (($r['manual_amount'] ?? '') ?: ($r['deposit_amount'] ?? ''));
					$manual_jalali = (string) (($r['manual_paid_at_jalali'] ?? '') ?: ($r['deposit_jalali_datetime'] ?? ''));
					$r['receipt_url'] = $receipt_url;
                    $r['receipt_urls'] = SN_Helpers::receipt_urls($r);
                    $r['receipt_count'] = count($r['receipt_urls']);
					$r['has_receipt'] = $receipt_url !== '';
					$payment_info_parts = [$receipt_url ? 'فیش بارگذاری شده' : 'اطلاعات واریز'];
					if ($manual_to !== '') { $payment_info_parts[] = '۴ رقم آخر کارت مقصد: ' . $manual_to; }
					if (! $receipt_url) {
						$manual_details = trim($manual_from . ' / ' . $manual_amount . ' / ' . $manual_jalali, " /");
						if ($manual_details !== '') { $payment_info_parts[] = $manual_details; }
					}
					$r['payment_info_text'] = implode(' | ', $payment_info_parts);
					$r['manual_card_from_display'] = $manual_from;
					$r['manual_card_to_display'] = $manual_to;
					$effective_status = (string) (($r['payment_status'] ?? '') ?: (($r['invoice_status'] ?? '') ?: ($r['status'] ?? '')));
					$status_blob = (string) ($r['status'] ?? '') . ' ' . (string) ($r['payment_status'] ?? '') . ' ' . (string) ($r['invoice_status'] ?? '');
					$is_pending_review = (in_array($effective_status, ['pending_financial_approval','receipt_uploaded'], true) || (bool) preg_match('/pending_financial_approval|receipt_uploaded/', $status_blob)) && ! (bool) preg_match('/\b(approved|paid|rejected|cancelled|payment_archived)\b/', $status_blob);
					$is_online_paid = in_array((string) ($r['pay_method'] ?? ''), ['online','gateway','zarinpal','zibal'], true) && (bool) preg_match('/\b(paid|approved)\b/', $status_blob) && ! (bool) preg_match('/\b(rejected|cancelled)\b/', $status_blob);
					$r['can_review'] = $is_pending_review || $is_online_paid;
					$r['can_approve_payment'] = $is_pending_review && $can_approve;
					$r['can_reject_payment'] = ($is_pending_review || $is_online_paid) && $can_reject;
					$r['can_cancel_invoice'] = $can_reject
						&& ! in_array((string) ($r['status'] ?? ''), ['cancelled','payment_archived'], true)
						&& ! in_array((string) ($r['payment_status'] ?? ''), ['cancelled','payment_archived'], true)
						&& ! in_array((string) ($r['invoice_status'] ?? ''), ['cancelled','payment_archived'], true);
					$r['can_reopen_financial'] = $tab === 'approved' && $can_approve && (bool) preg_match('/approved/', $status_blob);
					$r['financial_reject_reason'] = (string) ($r['financial_reject_reason'] ?? ($r['rejected_reason'] ?? ''));
					$reject_user_id = (int) ($r['financial_rejected_by'] ?? ($r['rejected_by'] ?? 0));
					$reject_user = $reject_user_id > 0 ? get_userdata($reject_user_id) : null;
					$r['financial_rejected_by_name'] = $reject_user ? (string) ($reject_user->display_name ?: $reject_user->user_login) : '';
					$r['financial_rejected_at'] = (string) ($r['financial_rejected_at'] ?? ($r['rejected_at'] ?? ''));
					$r['seller_response_note']=''; $r['seller_response_at']=''; $r['recontact_note_display']=(string)($r['recontact_note'] ?? '');
					$return_state = (string) ($r['financial_return_state'] ?? '');
					$is_resent_pending = $return_state === 'resent_after_return' && $is_pending_review;
					if ($is_resent_pending) { $r['status_label'] = 'در انتظار بررسی مجدد'; }
					$r['financial_return_label'] = $is_resent_pending ? 'اصلاح و ارسال مجدد' : ($return_state === 'returned_to_seller' ? 'برگشت به فروشنده' : (str_starts_with($return_state, 'cancelled_by_finance') ? 'لغو شده توسط مالی' : ''));
					$r['wc_order_id'] = (int) ($r['wc_order_id'] ?? 0);
					$payment_totals = $this->sn_invoice_payment_totals((object) $r);
					$current_payment_amount = (float) ($r['latest_payment_amount'] ?? 0);
					if ($current_payment_amount <= 0) { $current_payment_amount = (float) (($r['manual_amount'] ?? 0) ?: ($r['deposit_amount'] ?? 0) ?: ($payment_totals['due'] ?? 0)); }
					$r['transaction_summary'] = SN_Payment_Transactions::summary($finance_transactions[(int)$r['id']] ?? [],(int)$payment_totals['stage_no'],(float)$payment_totals['due']);
                    if ($r['transaction_summary']['independent']) {
                        $current_payment_amount = (float)$r['transaction_summary']['recorded_amount'];
                        $r['can_approve_payment'] = $r['can_approve_payment'] && $r['transaction_summary']['ready'];
                        $r['payment_info_text'] = 'تراکنش‌های ثبت‌شده؛ مشاهده ریز واریزها';
                    }
                    $r['invoice_total_amount'] = (float) $payment_totals['total'];
					$r['invoice_total_amount_fmt'] = SN_Helpers::format_price((float) $payment_totals['total']);
					$r['current_payment_amount'] = $current_payment_amount;
					$r['current_payment_amount_fmt'] = SN_Helpers::format_price($current_payment_amount);
					$r['approved_paid_amount'] = (float) $payment_totals['paid'];
					$r['approved_paid_amount_fmt'] = SN_Helpers::format_price((float) $payment_totals['paid']);
					$r['remaining_amount_value'] = (float) $payment_totals['remaining'];
					$r['remaining_amount_fmt'] = SN_Helpers::format_price((float) $payment_totals['remaining']);
					$r['finance_cancel_requires_refund_confirm'] = (float) $payment_totals['paid'] > 0.5;
					$r['is_fully_settled'] = (float) $payment_totals['remaining'] <= 0.5;
					$r['amount_fmt'] = $r['invoice_total_amount_fmt'];
					$r['product_name'] = $this->sn_invoice_items_label((int) $r['id'], (int) ($r['product_id'] ?? 0));
					$r['deposit_sort_at'] = (string) (($r['latest_payment_created_at'] ?? '') ?: ($r['updated_at'] ?? '') ?: ($r['created_at'] ?? ''));
					$r['deposit_date_label'] = $manual_jalali !== '' ? $manual_jalali : SN_Helpers::gregorian_to_jalali_date($r['deposit_sort_at']);
					$seller_id = absint($r['seller_id'] ?? 0);
					$r['is_dot_marketing'] = ! empty($dot_marketing_sellers[$seller_id]);
					$r['finance_tag'] = $r['is_dot_marketing'] ? 'مارکتینگ دات فلو' : '';
				}
				unset($r);

				$tab_counts = array_fill_keys(['needs_review','manual_deposit','receipt_uploaded','online_paid','approved','rejected'], 0);
				$count_rows = $wpdb->get_results("SELECT ({$finance_bucket}) AS finance_bucket, COUNT(*) AS invoice_count FROM {$invoice_table} i GROUP BY finance_bucket", ARRAY_A) ?: [];
				foreach ($count_rows as $count_row) {
					$key = (string) ($count_row['finance_bucket'] ?? '');
					if (array_key_exists($key, $tab_counts)) { $tab_counts[$key] = (int) $count_row['invoice_count']; }
				}
				$tab_counts['all'] = array_sum($tab_counts);
				$queue_total = $tab_counts['needs_review'] + $tab_counts['manual_deposit'] + $tab_counts['receipt_uploaded'];
				// The all total is computed before exposing the aggregate review queue.
				$tab_counts['needs_review'] = $queue_total;
				$kpi = $tab_counts + [
					'count' => $total, 'filtered_count' => $total, 'queue_total' => $queue_total,
					'amount' => $sum, 'amount_fmt' => SN_Helpers::format_price($sum),
					'returned_to_seller' => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$invoice_table} i WHERE {$returned}"),
					'needs_amount_fmt' => SN_Helpers::format_price((float) $wpdb->get_var("SELECT COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) FROM {$invoice_table} i WHERE {$needs}")),
					'approved_amount_fmt' => SN_Helpers::format_price((float) $wpdb->get_var("SELECT COALESCE(SUM(COALESCE(i.final_total,i.product_price,0)),0) FROM {$invoice_table} i WHERE {$approved}")),
				];
				SN_Helpers::send_json(true, '', ['items' => $rows, 'page' => $page, 'limit' => $limit, 'total' => $total, 'total_pages' => $total_pages, 'sort' => $sort, 'q' => $q, 'kpi' => $kpi, 'can_approve_payment' => $can_approve, 'can_reject_payment' => $can_reject]);
			}

			public function ajax_financial_invoice_details(): void
			{
				if (! is_user_logged_in()) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$valid = check_ajax_referer('sn_admin', 'nonce', false) || check_ajax_referer('sn_public', 'nonce', false);
				if (! $valid) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$invoice_id = absint($_POST['invoice_id'] ?? 0);
				if ($invoice_id < 1) { SN_Helpers::send_json(false, 'شناسه فاکتور نامعتبر است'); return; }
				$this->maybe_create_tables();
				global $wpdb;
				$hr_table = $wpdb->prefix . 'sn_hr_profiles';
				$details_join_hr = $this->sn_table_exists_quiet($hr_table);
				$details_seller_expr = $details_join_hr ? "COALESCE(NULLIF(hp.hr_display_name,''),u.display_name)" : "u.display_name";
				$details_hr_join = $details_join_hr ? " LEFT JOIN {$hr_table} hp ON hp.user_id=i.seller_id AND hp.is_active=1" : '';
				$invoice = $wpdb->get_row($wpdb->prepare("SELECT i.*, {$details_seller_expr} seller_name FROM {$wpdb->prefix}sn_invoices i LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id{$details_hr_join} WHERE i.id=%d LIMIT 1", $invoice_id));
				if (! $invoice) { SN_Helpers::send_json(false, 'فاکتور یافت نشد'); return; }
				if (! $this->sn_can_view_finance() && ! $this->sn_can_resend_invoice_sms($invoice)) { if (function_exists('status_header')) { status_header(403); } SN_Helpers::send_json(false, 'این فاکتور در محدوده دسترسی شما نیست'); return; }
				$is_dot_marketing = (int) ($invoice->seller_id ?? 0) > 0 && (string) get_user_meta((int) $invoice->seller_id, '_sn_dot_marketing_seller', true) === '1';
				$totals = $this->sn_invoice_payment_totals($invoice);
				$stage_table = $wpdb->prefix . 'sn_invoice_payment_stages';
				$payment_table = $wpdb->prefix . 'sn_payments';
				$stages = $this->sn_table_exists_quiet($stage_table) ? ($wpdb->get_results($wpdb->prepare("SELECT * FROM {$stage_table} WHERE invoice_id=%d ORDER BY stage_no ASC,id ASC", $invoice_id), ARRAY_A) ?: []) : [];
				$payments = $this->sn_table_exists_quiet($payment_table) ? ($wpdb->get_results($wpdb->prepare("SELECT * FROM {$payment_table} WHERE invoice_id=%d ORDER BY payment_stage_no ASC,id ASC", $invoice_id), ARRAY_A) ?: []) : [];
				$user_ids = [];
				foreach ($stages as $stage) { foreach (['issued_by_user_id','approved_by_user_id'] as $field) { $uid = absint($stage[$field] ?? 0); if ($uid) { $user_ids[] = $uid; } } }
				foreach ($payments as $payment) { $uid = absint($payment['uploaded_by_user_id'] ?? 0); if ($uid) { $user_ids[] = $uid; } }
				$user_ids = array_values(array_unique($user_ids));
				$user_names = [];
				if ($user_ids) { foreach (get_users(['include'=>$user_ids,'fields'=>['ID','display_name','user_login']]) as $u) { $user_names[(int)$u->ID] = (string) ($u->display_name ?: $u->user_login); } }
				$jalali_datetime = static function ($value): string {
					$value = trim((string) $value); if ($value === '') { return '—'; }
					return str_replace(' ', ' - ', SN_Helpers::gregorian_to_jalali_date($value));
				};
				$stage_status_labels = ['pending'=>'در انتظار پرداخت','receipt_uploaded'=>'فیش ثبت شده','pending_financial_approval'=>'در انتظار تایید مالی','paid'=>'پرداخت شده','approved'=>'تایید شده','rejected'=>'رد شده','cancelled'=>'لغو شده','expired'=>'منقضی'];
				$stage_type_labels = ['full'=>'پرداخت کامل','partial'=>'پیش‌پرداخت','remaining'=>'تکمیل مانده','final'=>'تسویه نهایی'];
				$stage_rows = [];
				foreach ($stages as $stage) {
					$status = sanitize_key((string) ($stage['status'] ?? 'pending'));
					$type = sanitize_key((string) ($stage['stage_type'] ?? 'partial'));
					$stage_rows[] = [
						'stage_no'=>(int)($stage['stage_no'] ?? 0),
						'stage_type'=>$type,
						'stage_type_label'=>$stage_type_labels[$type] ?? ($type ?: '—'),
                        'receipt_urls'=>SN_Helpers::receipt_urls($stage),
						'amount'=>(float)($stage['requested_amount'] ?? 0),
						'amount_fmt'=>SN_Helpers::format_price((float)($stage['requested_amount'] ?? 0)),
						'status'=>$status,
						'status_label'=>$stage_status_labels[$status] ?? ($status ?: '—'),
						'pay_method_label'=>SN_Helpers::pay_method_label((string)($stage['pay_method'] ?? '')),
						'payment_source_label'=>SN_Helpers::payment_source_label((string)($stage['payment_source'] ?? '')),
						'payment_ref_id'=>sanitize_text_field((string)($stage['payment_ref_id'] ?? '')),
						'issued_by_name'=>$user_names[absint($stage['issued_by_user_id'] ?? 0)] ?? '',
						'approved_by_name'=>$user_names[absint($stage['approved_by_user_id'] ?? 0)] ?? '',
						'created_at_jalali'=>$jalali_datetime($stage['created_at'] ?? ''),
						'paid_at_jalali'=>$jalali_datetime(($stage['paid_at'] ?? '') ?: ($stage['approved_at'] ?? '')),
						'note'=>sanitize_textarea_field((string)($stage['note'] ?? '')),
					];
				}
				$payment_status_labels = ['pending'=>'در انتظار','paid'=>'پرداخت شده','approved'=>'تایید شده','rejected'=>'رد شده','failed'=>'ناموفق','expired'=>'منقضی'];
				$payment_rows = [];
				foreach ($payments as $payment) {
					$status = sanitize_key((string)($payment['status'] ?? 'pending'));
					$payment_rows[] = [
						'id'=>(int)($payment['id'] ?? 0),
						'stage_no'=>(int)($payment['payment_stage_no'] ?? 1),
						'amount'=>(float)($payment['amount'] ?? 0),
						'amount_fmt'=>SN_Helpers::format_price((float)($payment['amount'] ?? 0)),
						'status'=>$status,
						'status_label'=>$payment_status_labels[$status] ?? ($status ?: '—'),
						'pay_method_label'=>SN_Helpers::pay_method_label((string)($payment['pay_method'] ?? '')),
						'payment_source_label'=>SN_Helpers::payment_source_label((string)($payment['payment_source'] ?? ($payment['uploaded_by_type'] ?? ''))),
						'ref_id'=>sanitize_text_field((string)($payment['ref_id'] ?? '')),
						'uploaded_by_name'=>$user_names[absint($payment['uploaded_by_user_id'] ?? 0)] ?? '',
						'created_at_jalali'=>$jalali_datetime($payment['created_at'] ?? ''),
					];
				}
				$activity_rows=[]; $activity_table=$wpdb->prefix.'sn_activity_logs';
				if ($this->sn_table_exists_quiet($activity_table)) {
					$raw_activity=$wpdb->get_results($wpdb->prepare("SELECT a.*,u.display_name,u.user_login FROM {$activity_table} a LEFT JOIN {$wpdb->users} u ON u.ID=a.user_id WHERE a.invoice_id=%d AND a.action IN ('payment_rejected','seller_resend_to_financial','invoice_recontact_requested','customer_payment_submitted','seller_payment_submitted','supervisor_payment_submitted','converter_payment_submitted','finance_stage_reconciled','financial_approval_reopened','invoice_payment_completed','invoice_partial_payment_approved') ORDER BY a.id DESC LIMIT 100",$invoice_id),ARRAY_A) ?: [];
					$activity_labels=['payment_rejected'=>'رد توسط مالی','seller_resend_to_financial'=>'اصلاح و ارسال مجدد برای مالی','invoice_recontact_requested'=>'ارتباط مجدد با کارشناس','customer_payment_submitted'=>'ثبت اطلاعات واریزی مشتری','seller_payment_submitted'=>'ثبت واریز فروشنده','supervisor_payment_submitted'=>'ثبت فیش سرپرست','converter_payment_submitted'=>'ثبت فیش تبدیل‌کننده','finance_stage_reconciled'=>'هماهنگ‌سازی مرحله مالی','financial_approval_reopened'=>'بازگشت تایید مالی به بررسی','invoice_payment_completed'=>'تایید و تکمیل واریزی','invoice_partial_payment_approved'=>'تایید پیش‌پرداخت'];
					foreach ($raw_activity as $a) { $ctx=json_decode((string)($a['context'] ?? ''),true); $ctx=is_array($ctx)?$ctx:[]; $note=isset($ctx['reason'])?(string)$ctx['reason']:(isset($ctx['note'])?(string)$ctx['note']:(string)($a['description'] ?? '')); $activity_rows[]=['action'=>(string)$a['action'],'label'=>$activity_labels[(string)$a['action']] ?? (string)$a['action'],'note'=>sanitize_textarea_field($note),'description'=>sanitize_textarea_field((string)($a['description'] ?? '')),'actor_name'=>(string)(($a['display_name'] ?? '') ?: ($a['user_login'] ?? '') ?: 'سیستم / مشتری'),'created_at_jalali'=>$jalali_datetime($a['created_at'] ?? '')]; }
				}

				SN_Helpers::send_json(true, '', [
					'transactions'=>SN_Payment_Transactions::rows($invoice),
                    'transaction_summary'=>SN_Payment_Transactions::summary(SN_Payment_Transactions::rows($invoice),(int)$totals['stage_no'],(float)$totals['due']),
                    'invoice'=>[
						'id'=>(int)$invoice->id,
						'invoice_code'=>(string)$invoice->invoice_code,
						'customer_name'=>(string)$invoice->customer_name,
						'customer_phone'=>(string)$invoice->customer_phone,
						'seller_name'=>(string)($invoice->seller_name ?: ('#'.(int)$invoice->seller_id)),
						'product_name'=>$this->sn_invoice_items_label((int)$invoice->id, (int)$invoice->product_id),
						'status'=>(string)$invoice->status,
						'status_label'=>SN_Helpers::status_label((string)$invoice->status),
						'receipt_url'=>(string)(($invoice->receipt_url ?? '') ?: ($invoice->receipt_file ?? '')),
                        'receipt_urls'=>SN_Helpers::receipt_urls($invoice),
						'financial_reject_reason'=>in_array((string)$invoice->status,['rejected','financial_rejected'],true) ? (string)(($invoice->financial_reject_reason ?? '') ?: ($invoice->rejected_reason ?? '')) : '',
						'total_amount'=>(float)$totals['total'],
						'total_amount_fmt'=>SN_Helpers::format_price((float)$totals['total']),
						'paid_amount'=>(float)$totals['paid'],
						'paid_amount_fmt'=>SN_Helpers::format_price((float)$totals['paid']),
						'remaining_amount'=>(float)$totals['remaining'],
						'remaining_amount_fmt'=>SN_Helpers::format_price((float)$totals['remaining']),
						'is_fully_settled'=>(float)$totals['remaining'] <= 0.5,
						'created_at_jalali'=>$jalali_datetime($invoice->created_at ?? ''),
						'is_dot_marketing'=>$is_dot_marketing,
						'finance_tag'=>$is_dot_marketing ? 'مارکتینگ دات فلو' : '',
					],
					'stages'=>$stage_rows,
					'payments'=>$payment_rows,
					'activities'=>$activity_rows,
				]);
			}


			private function sn_maybe_send_payment_sms($invoice, string $payment_type): void
			{
				// پیامک پرداخت اختیاری است؛ اگر پترن تنظیم نشده باشد هیچ رفتاری از سیستم فعلی تغییر نمی‌کند.
				$payment_type = $payment_type === 'card_to_card' ? 'card_to_card' : 'online';
				if (! class_exists('SN_SMS')) { return; }
				$phone = (string)($invoice->customer_phone ?? '');
				if (! $phone) { return; }
				$label = $payment_type === 'online' ? 'online' : 'card_to_card';
				try {
					$sms = new SN_SMS();
					$event = $payment_type === 'online' ? 'online_payment' : 'card_payment';
					if ($sms->event_pattern($event) === '') { return; }
					$ok = $sms->send_event_pattern($phone, $event, [
						'customer_name' => (string)($invoice->customer_name ?? ''),
						'invoice_code' => (string)($invoice->invoice_code ?? ''),
						'amount' => (string) preg_replace('/[^0-9]/', '', SN_Helpers::to_english_nums(SN_Helpers::format_price((float)($invoice->product_price ?? 0)))),
						'payment_type' => $label,
					]);
					if (! $ok) { $this->sn_log_activity((int)($invoice->id ?? 0), (int)($invoice->lead_id ?? 0), 'payment_sms_failed', $sms->get_last_error()); }

				} catch (\Throwable $e) {
					$this->sn_log_activity((int)($invoice->id ?? 0), (int)($invoice->lead_id ?? 0), 'payment_sms_failed', 'خطا در ارسال پیامک پرداخت: ' . $e->getMessage());
				}
			}


			private function sn_get_lucky_wheels(): array
			{
				$wheels = get_option('sn_lucky_wheels', []);
				return is_array($wheels) ? $wheels : [];
			}

			private function sn_pick_weighted_wheel_segment(array $segments): array
			{
				$total = 0.0;
				foreach ($segments as $s) { $total += max(0, (float)($s['chance'] ?? 0)); }
				if ($total <= 0) { return $segments[0] ?? []; }
				$rand = (wp_rand(1, 1000000) / 1000000) * $total;
				$cursor = 0.0;
				foreach ($segments as $s) {
					$cursor += max(0, (float)($s['chance'] ?? 0));
					if ($rand <= $cursor) { return $s; }
				}
				return end($segments) ?: [];
			}

			private function sn_invoice_product_ids($invoice): array
			{
				global $wpdb;
				$ids = [];
				$invoice_id = isset($invoice->id) ? absint($invoice->id) : 0;
				$table = $wpdb->prefix . 'sn_invoice_items';
				if ($invoice_id > 0 && $this->sn_table_exists_quiet($table)) {
					$rows = $wpdb->get_col($wpdb->prepare("SELECT product_id FROM {$table} WHERE invoice_id=%d", $invoice_id));
					foreach ((array) $rows as $pid) {
						$pid = absint($pid);
						if ($pid > 0) { $ids[] = $pid; }
					}
				}
				$fallback = isset($invoice->product_id) ? absint($invoice->product_id) : 0;
				if ($fallback > 0) { $ids[] = $fallback; }
				return array_values(array_unique($ids));
			}

			private function sn_invoice_public_feature_enabled($invoice, string $feature): bool
			{
				$feature = sanitize_key($feature);
				$option_map = [
					'wheel'  => 'sn_invoice_info_show_wheel',
					'coupon' => 'sn_invoice_info_show_coupon',
				];
				$meta_map = [
					'wheel'  => '_sn_has_lucky_wheel',
					'coupon' => '_sn_has_discount_coupon',
				];
				if (! isset($option_map[$feature], $meta_map[$feature])) { return false; }
				if (get_option($option_map[$feature], '1') !== '1') { return false; }
				foreach ($this->sn_invoice_product_ids($invoice) as $pid) {
					if (get_post_meta($pid, $meta_map[$feature], true) === '1') { return true; }
				}
				return false;
			}


			public function ajax_spin_invoice_wheel(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_spin_wheel', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$apply = sanitize_key($_POST['apply'] ?? 'spin_only');
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'spin_wheel');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice || in_array((string) $invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'گردونه برای این فاکتور فعال نیست'); return; }
				if (! $this->sn_invoice_public_feature_enabled($invoice, 'wheel')) { SN_Helpers::send_json(false, 'گردونه برای این فاکتور فعال نیست'); return; }
				$this->maybe_create_tables(); global $wpdb;
				$existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_wheel WHERE invoice_id=%d ORDER BY id DESC LIMIT 1", (int) $invoice->id));
				if ($existing) {
					$payload = json_decode((string) $existing->reward_payload, true);
					SN_Helpers::send_json(true, 'شما قبلاً از گردونه استفاده کرده‌اید.', [
						'reward_type'=>$existing->reward_type,
						'reward_value'=>$existing->reward_value,
						'summary'=>(string) $invoice->wheel_reward_summary,
						'used_discount'=>(int)$existing->used_discount,
						'payload'=>is_array($payload)?$payload:[],
					]);
					return;
				}
				$items = $wpdb->get_results($wpdb->prepare("SELECT product_id FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d", (int)$invoice->id));
				if (! $items) { $items = [(object)['product_id'=>(int)$invoice->product_id]]; }
				$eligible_wheel=false; $eligible_discount=false; $wheel_id='';
				foreach ($items as $it) {
					$pid=(int)$it->product_id;
					if (get_post_meta($pid, '_sn_has_lucky_wheel', true)==='1') { $eligible_wheel=true; if (!$wheel_id) { $wheel_id=(string)get_post_meta($pid, '_sn_wheel_id', true); } }
					if (get_post_meta($pid, '_sn_has_discount_coupon', true)==='1') { $eligible_discount=true; }
				}
				if (! $eligible_wheel) { SN_Helpers::send_json(false, 'برای محصولات این فاکتور گردونه تعریف نشده است'); return; }
				$wheels = $this->sn_get_lucky_wheels();
				$wheel = ($wheel_id && isset($wheels[$wheel_id])) ? $wheels[$wheel_id] : (is_array($wheels) ? reset($wheels) : null);
				$segment = $wheel && !empty($wheel['segments']) ? $this->sn_pick_weighted_wheel_segment((array)$wheel['segments']) : [];
				if ($segment) {
					$reward_type = sanitize_key($segment['type'] ?? 'discount_coupon');
					$reward_value = (string)($segment['value'] ?? '');
					$summary = sanitize_text_field($segment['label'] ?? 'جایزه گردونه');
					$free_product_id = absint($segment['product_id'] ?? 0);
					$discount_percent = $reward_type === 'discount_coupon' ? max(0, min(100, (float)$reward_value)) : 0;
				} else {
					$discount_percent = 0;
					$free_product_id = 0;
					$reward_type = 'empty_reward';
					$reward_value = '';
					$summary = 'بدون جایزه';
				}
				if (! in_array($reward_type, ['discount_coupon','free_product','empty_reward','text'], true)) { $reward_type = 'text'; }
				$payload = ['wheel_id'=>$wheel_id,'wheel_title'=>$wheel['title'] ?? '','segment'=>$segment,'discount_percent'=>$discount_percent,'free_product_id'=>$free_product_id];
				$wpdb->insert($wpdb->prefix . 'sn_invoice_wheel', ['invoice_id'=>(int)$invoice->id,'customer_id'=>(int)($invoice->customer_wp_id ?? 0),'reward_type'=>$reward_type,'reward_value'=>$reward_value,'reward_payload'=>wp_json_encode($payload, JSON_UNESCAPED_UNICODE),'used_discount'=>0,'created_at'=>current_time('mysql')]);
				$wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', ['wheel_reward_summary'=>$summary,'updated_at'=>current_time('mysql')]), ['id'=>(int)$invoice->id]);
				if ($apply === 'yes' && in_array($reward_type, ['discount_coupon','free_product'], true)) {
					$_POST['invoice_code'] = $code;
					$this->ajax_apply_invoice_wheel_reward();
					return;
				}
				SN_Helpers::send_json(true, 'نتیجه گردونه: ' . $summary, ['reward_type'=>$reward_type,'reward_value'=>$reward_value,'summary'=>$summary,'discount_percent'=>$discount_percent,'free_product_id'=>$free_product_id]);
			}


			public function ajax_apply_invoice_wheel_reward(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_apply_wheel', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'apply_wheel');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice || in_array((string)$invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'فاکتور قابل تغییر نیست'); return; }
				if ($this->sn_invoice_payment_totals($invoice)['paid'] > 0.5) { SN_Helpers::send_json(false, 'بعد از تایید اولین پرداخت، تخفیف فاکتور قابل تغییر نیست'); return; }
				if (! $this->sn_invoice_public_feature_enabled($invoice, 'wheel')) { SN_Helpers::send_json(false, 'گردونه برای این فاکتور فعال نیست'); return; }
				global $wpdb;
				$row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_wheel WHERE invoice_id=%d ORDER BY id DESC LIMIT 1", (int)$invoice->id));
				if (! $row) { SN_Helpers::send_json(false, 'ابتدا گردونه را بچرخانید'); return; }
				if ((int)$row->used_discount === 1) { SN_Helpers::send_json(false, 'این جایزه قبلاً اعمال شده است'); return; }
				$payload = json_decode((string)$row->reward_payload, true); if (!is_array($payload)) { $payload=[]; }
				$summary = (string)($invoice->wheel_reward_summary ?: 'جایزه گردونه');
				$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d ORDER BY id ASC", (int)$invoice->id), ARRAY_A);
				if (! $items) { $items = [['product_id'=>(int)$invoice->product_id,'qty'=>1,'unit_price'=>(float)$invoice->product_price,'total_price'=>(float)$invoice->product_price,'is_free'=>0]]; }
				$base_total = 0.0;
				foreach ($items as $it) { if (empty($it['is_free'])) { $base_total += (float)($it['total_price'] ?? 0); } }
				$current_discount = (float)($invoice->discount_amount ?? 0) + (float)($invoice->coupon_discount_amount ?? 0);
				$extra_discount = 0.0;
				if ($row->reward_type === 'discount_coupon') {
					$percent = max(0, min(100, (float)($payload['discount_percent'] ?? $row->reward_value)));
					$extra_discount = round(max(0, $base_total - $current_discount) * $percent / 100, 2);
					$summary = $summary . ' - اعمال شد';
				} elseif ($row->reward_type === 'free_product') {
					$free_product_id = absint($payload['free_product_id'] ?? $row->reward_value);
					if (!$free_product_id) { $free_product_id = absint(get_option('sn_wheel_free_product_id', 0)); }
					if ($free_product_id && function_exists('wc_get_product')) {
						$fp = wc_get_product($free_product_id);
						if ($fp) {
							$already = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d AND product_id=%d AND is_free=1", (int)$invoice->id, $free_product_id));
							if (! $already) {
								$wpdb->insert($wpdb->prefix . 'sn_invoice_items', ['invoice_id'=>(int)$invoice->id,'product_id'=>$free_product_id,'product_name'=>$fp->get_name(),'qty'=>1,'unit_price'=>0,'total_price'=>0,'is_free'=>1,'created_at'=>current_time('mysql')]);
							}
							$summary = 'محصول رایگان: ' . $fp->get_name();
						}
					}
				} else {
					$summary = 'بدون جایزه';
				}
				$new_discount_amount = (float)($invoice->discount_amount ?? 0) + $extra_discount;
				$discount_total = $new_discount_amount + (float)($invoice->coupon_discount_amount ?? 0);
				$final_total = max(0, $base_total - $discount_total);
				if ($final_total <= 0) { SN_Helpers::send_json(false, 'مبلغ نهایی فاکتور پس از تخفیف باید بیشتر از صفر باشد'); return; }
				$update = [
					'discount_amount' => $new_discount_amount,
					'original_total' => $base_total,
					'discount_total' => $discount_total,
					'final_total' => $final_total,
					'product_price' => $final_total,
					'wheel_reward_summary' => $summary,
					'updated_at'=>current_time('mysql'),
				];
				$wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', $update), ['id'=>(int)$invoice->id]);
				$sync = $this->sn_sync_unpaid_invoice_payment_total((int)$invoice->id, $final_total);
				if (empty($sync['success'])) { SN_Helpers::send_json(false, (string)($sync['message'] ?? 'همگام‌سازی مبلغ پرداخت انجام نشد')); return; }
				$wpdb->update($wpdb->prefix.'sn_invoice_wheel', ['used_discount'=>1], ['id'=>(int)$row->id]);
				SN_Helpers::send_json(true, 'جایزه روی فاکتور اعمال شد', ['summary'=>$summary,'final_total'=>$final_total,'discount_total'=>$discount_total]);
			}


			public function ajax_apply_invoice_coupon(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_apply_coupon', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$coupon_code = sanitize_text_field(wp_unslash($_POST['coupon_code'] ?? ''));
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'apply_coupon');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice || in_array((string)$invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'فاکتور قابل تغییر نیست'); return; }
				if ($this->sn_invoice_payment_totals($invoice)['paid'] > 0.5) { SN_Helpers::send_json(false, 'بعد از تایید اولین پرداخت، تخفیف فاکتور قابل تغییر نیست'); return; }
				if (! $this->sn_invoice_public_feature_enabled($invoice, 'coupon')) { SN_Helpers::send_json(false, 'کد تخفیف برای این فاکتور فعال نیست'); return; }
				if ($coupon_code === '') { SN_Helpers::send_json(false, 'کد تخفیف را وارد کنید'); return; }
				if (! function_exists('wc_get_coupon_id_by_code') || ! class_exists('WC_Coupon')) { SN_Helpers::send_json(false, 'ووکامرس فعال نیست'); return; }
				$coupon_id = wc_get_coupon_id_by_code($coupon_code);
				if (! $coupon_id) { SN_Helpers::send_json(false, 'کد تخفیف معتبر نیست'); return; }
				$coupon = new WC_Coupon($coupon_id);
				if (method_exists($coupon, 'get_date_expires') && $coupon->get_date_expires() && $coupon->get_date_expires()->getTimestamp() < time()) { SN_Helpers::send_json(false, 'تاریخ اعتبار کد تخفیف تمام شده است'); return; }
				if (method_exists($coupon, 'get_usage_limit') && $coupon->get_usage_limit() && $coupon->get_usage_count() >= $coupon->get_usage_limit()) { SN_Helpers::send_json(false, 'ظرفیت استفاده از این کد تخفیف تمام شده است'); return; }
				global $wpdb;
				$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d", (int)$invoice->id), ARRAY_A);
				if (!$items) { $items = [['product_id'=>(int)$invoice->product_id,'total_price'=>(float)$invoice->product_price,'qty'=>1,'is_free'=>0]]; }
				$allow_on_sale = get_option('sn_coupon_allow_on_sale', '0') === '1';
				$base = 0.0; $has_sale = false; $eligible = false;
				$product_ids = array_map('absint', (array) $coupon->get_product_ids());
				$excluded_ids = array_map('absint', (array) $coupon->get_excluded_product_ids());
				foreach ($items as $it) {
					if (! empty($it['is_free'])) { continue; }
					$pid = (int)($it['product_id'] ?? 0);
					if ($pid && in_array($pid, $excluded_ids, true)) { continue; }
					if (! empty($product_ids) && ! in_array($pid, $product_ids, true)) { continue; }
					$p = $pid && function_exists('wc_get_product') ? wc_get_product($pid) : null;
					if ($p && $p->is_on_sale()) { $has_sale = true; }
					$base += (float)($it['total_price'] ?? 0);
					$eligible = true;
				}
				if (! $eligible || $base <= 0) { SN_Helpers::send_json(false, 'این کد تخفیف برای محصولات این فاکتور قابل استفاده نیست'); return; }
				if ($has_sale && ! $allow_on_sale) { SN_Helpers::send_json(false, 'این کد تخفیف برای محصولات دارای تخفیف ویژه قابل استفاده نیست'); return; }
				if ($coupon->get_minimum_amount() && $base < (float)$coupon->get_minimum_amount()) { SN_Helpers::send_json(false, 'مبلغ فاکتور برای استفاده از این کد کافی نیست'); return; }
				if ($coupon->get_maximum_amount() && $base > (float)$coupon->get_maximum_amount()) { SN_Helpers::send_json(false, 'این کد برای مبلغ این فاکتور قابل استفاده نیست'); return; }
				$type = $coupon->get_discount_type(); $amount = (float)$coupon->get_amount();
				$discount = in_array($type, ['percent','recurring_percent'], true) ? round($base * $amount / 100, 2) : min($base, $amount);
				if ($discount <= 0) { SN_Helpers::send_json(false, 'مبلغ تخفیف قابل اعمال نیست'); return; }
				$other_discount = (float)($invoice->discount_amount ?? 0);
				$discount_total = $other_discount + $discount;
				$final_total = max(0, $base - $discount_total);
				if ($final_total <= 0) { SN_Helpers::send_json(false, 'مبلغ نهایی فاکتور پس از تخفیف باید بیشتر از صفر باشد'); return; }
				$wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', [
					'coupon_code'=>$coupon_code,
					'coupon_discount_amount'=>$discount,
					'original_total'=>$base,
					'discount_total'=>$discount_total,
					'final_total'=>$final_total,
					'product_price'=>$final_total,
					'updated_at'=>current_time('mysql'),
				]), ['id'=>(int)$invoice->id]);
				$sync = $this->sn_sync_unpaid_invoice_payment_total((int)$invoice->id, $final_total);
				if (empty($sync['success'])) { SN_Helpers::send_json(false, (string)($sync['message'] ?? 'همگام‌سازی مبلغ پرداخت انجام نشد')); return; }
				SN_Helpers::send_json(true, 'کد تخفیف اعمال شد', ['discount_amount'=>$discount,'final_total'=>$final_total,'discount_total'=>$discount_total]);
			}

			public function ajax_remove_invoice_coupon(): void
			{
				if (! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'نانس نامعتبر'); return; }
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				if (! $this->sn_rate_limit_public_or_json('invoice_remove_coupon', $code, 10, 10 * MINUTE_IN_SECONDS)) { return; }
				$access = $this->sn_validate_public_invoice_access($code, $this->sn_public_access_token(), 'remove_coupon');
				if (empty($access['success'])) { SN_Helpers::send_json(false, (string) $access['message']); return; }
				$invoice = $access['invoice'];
				if (! $invoice || in_array((string)$invoice->status, ['paid','approved'], true)) { SN_Helpers::send_json(false, 'فاکتور قابل تغییر نیست'); return; }
				if ($this->sn_invoice_payment_totals($invoice)['paid'] > 0.5) { SN_Helpers::send_json(false, 'بعد از تایید اولین پرداخت، تخفیف فاکتور قابل تغییر نیست'); return; }
				if (! $this->sn_invoice_public_feature_enabled($invoice, 'coupon')) { SN_Helpers::send_json(false, 'کد تخفیف برای این فاکتور فعال نیست'); return; }
				global $wpdb;
				$items = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoice_items WHERE invoice_id=%d", (int)$invoice->id), ARRAY_A);
				if (!$items) { $items = [['product_id'=>(int)$invoice->product_id,'total_price'=>(float)$invoice->product_price,'qty'=>1,'is_free'=>0]]; }
				$base = 0.0; $original_total = 0.0;
				foreach ($items as $it) {
					if (! empty($it['is_free'])) { continue; }
					$pid = (int)($it['product_id'] ?? 0);
					$qty = max(1, (int)($it['qty'] ?? 1));
					$product = $pid && function_exists('wc_get_product') ? wc_get_product($pid) : null;
					$regular = $product ? (float)$product->get_regular_price() : (float)($it['unit_price'] ?? 0);
					$base += (float)($it['total_price'] ?? 0);
					$original_total += $regular > 0 ? ($regular * $qty) : (float)($it['total_price'] ?? 0);
				}
				$other_discount = (float)($invoice->discount_amount ?? 0);
				$final_total = max(0, $base - $other_discount);
				$wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', [
					'coupon_code'=>null,
					'coupon_discount_amount'=>0,
					'original_total'=>$original_total,
					'discount_total'=>$other_discount,
					'final_total'=>$final_total,
					'product_price'=>$final_total,
					'updated_at'=>current_time('mysql'),
				]), ['id'=>(int)$invoice->id]);
				$sync = $this->sn_sync_unpaid_invoice_payment_total((int)$invoice->id, $final_total);
				if (empty($sync['success'])) { SN_Helpers::send_json(false, (string)($sync['message'] ?? 'همگام‌سازی مبلغ پرداخت انجام نشد')); return; }
				SN_Helpers::send_json(true, 'کد تخفیف لغو شد', ['final_total'=>$final_total,'discount_total'=>$other_discount]);
			}


			/** Unified operational scope helpers for launch reports. */
			private function sn_scope_seller_ids_for_panel(int $actor_id, string $context = ''): array
			{
				$actor_id = absint($actor_id);
				if ($actor_id < 1) { return []; }
				if (current_user_can('manage_options')) {
					return array_values(array_unique(array_map('intval', array_column($this->sn_hr_all_users_by_position('seller'), 'user_id'))));
				}
				$direct = array_map('intval', array_column($this->sn_get_direct_children($actor_id, 'seller'), 'user_id'));
				$desc = array_map('intval', array_column($this->sn_get_descendant_users($actor_id, 'seller'), 'user_id'));
				return array_values(array_unique(array_filter(array_merge($direct, $desc))));
			}

			private function sn_invoice_owner_fields(): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				$columns = $this->sn_table_columns($table);
				return array_values(array_intersect(['seller_id','original_seller_id','commission_seller_id','seller_user_id','sales_user_id','lead_seller_id','assigned_seller_id'], $columns));
			}

			private function sn_invoice_scope_where_for_sellers(array $seller_ids, string $alias = 'i'): array
			{
				$seller_ids = array_values(array_unique(array_filter(array_map('intval', $seller_ids))));
				$owner_fields = $this->sn_invoice_owner_fields();
				if (! $seller_ids || ! $owner_fields) { return ['1=0', []]; }
				$parts = [];
				$args = [];
				foreach ($owner_fields as $field) {
					$parts[] = "{$alias}.{$field} IN (" . implode(',', array_fill(0, count($seller_ids), '%d')) . ')';
					$args = array_merge($args, $seller_ids);
				}
				return ['(' . implode(' OR ', $parts) . ')', $args];
			}

			private function sn_scope_invoice_rows_for_panel(int $actor_id, string $context = '', int $limit = 200, array $filters = [], bool $force_scope = false): array
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_invoices';
				if (! $this->sn_table_exists_quiet($table)) { return []; }
				$limit = max(1, min(5000, $limit));
				$seller_ids = $this->sn_scope_seller_ids_for_panel($actor_id, $context);
				[$scope_where, $scope_args] = (current_user_can('manage_options') && ! $force_scope) ? ['1=1', []] : $this->sn_invoice_scope_where_for_sellers($seller_ids, 'i');
				$where = [$scope_where];
				$args = $scope_args;
				$date_from_raw = trim((string) ($filters['date_from'] ?? ''));
				$date_to_raw = trim((string) ($filters['date_to'] ?? ''));
				$date_from = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_from_raw) ? $date_from_raw : SN_Helpers::jalali_to_gregorian_date($date_from_raw);
				$date_to = preg_match('/^\d{4}-\d{2}-\d{2}$/', $date_to_raw) ? $date_to_raw : SN_Helpers::jalali_to_gregorian_date($date_to_raw);
				if ($date_from !== '') { $where[] = 'DATE(i.created_at) >= %s'; $args[] = $date_from; }
				if ($date_to !== '') { $where[] = 'DATE(i.created_at) <= %s'; $args[] = $date_to; }
				if (! empty($filters['seller_id'])) { $where[] = 'i.seller_id=%d'; $args[] = absint($filters['seller_id']); }
				$status_filter = sanitize_key((string) ($filters['status'] ?? ''));
				if ($status_filter !== '') {
					$status_map = [
						'pre_invoice' => ['pre_invoice'],
						'pending_payment' => ['pending_payment','pending'],
						'paid' => ['paid','online_paid','gateway_paid'],
						'approved' => ['approved','financial_approved'],
						'receipt_uploaded' => ['receipt_uploaded','pending_financial_approval','needs_finance_review'],
						'rejected' => ['rejected'],
						'cancelled' => ['cancelled','canceled'],
					];
					$statuses = $status_map[$status_filter] ?? [$status_filter];
					$status_parts = [];
					foreach (['status','invoice_status','payment_status'] as $field) {
						$status_parts[] = 'i.' . $field . ' IN (' . implode(',', array_fill(0, count($statuses), '%s')) . ')';
						$args = array_merge($args, $statuses);
					}
					$where[] = '(' . implode(' OR ', $status_parts) . ')';
				}
				if (! empty($filters['q'])) { $like = '%' . $wpdb->esc_like((string) $filters['q']) . '%'; $where[] = '(i.invoice_code LIKE %s OR i.customer_name LIKE %s OR i.customer_phone LIKE %s)'; $args = array_merge($args, [$like,$like,$like]); }
				$approved_condition = $this->sn_commission_paid_approved_invoice_condition('i');
				$sql = "SELECT i.*, COALESCE(NULLIF(hp.hr_display_name,''), u.display_name) seller_name, {$approved_condition} AS sn_is_approved
					FROM {$table} i
					LEFT JOIN {$wpdb->users} u ON u.ID=i.seller_id
					LEFT JOIN {$wpdb->prefix}sn_hr_profiles hp ON hp.user_id=i.seller_id AND hp.is_active=1
					WHERE " . implode(' AND ', $where) . "
					ORDER BY COALESCE(i.approved_at,i.financial_reviewed_at,i.paid_at,i.created_at) DESC, i.id DESC
					LIMIT %d";
				$args[] = $limit;
				return $wpdb->get_results($wpdb->prepare($sql, ...$args), ARRAY_A) ?: [];
			}

			private function sn_scope_invoice_stats(array $rows): array
			{
				$stats = ['count'=>0,'approved_count'=>0,'total'=>0.0,'approved_total'=>0.0,'repeat_action_count'=>0,'repeat_action_seller'=>0,'repeat_action_supervisor'=>0,'repeat_action_senior_supervisor'=>0];
				foreach ($rows as $row) {
					$amount = (float) (($row['final_total'] ?? 0) ?: ($row['product_price'] ?? 0) ?: ($row['paid_amount'] ?? 0));
					$stats['count']++;
					$stats['total'] += $amount;
					if (! empty($row['sn_is_approved']) || $this->sn_commission_invoice_is_approved_row($row)) { $stats['approved_count']++; $stats['approved_total'] += $amount; }
					$repeat = (string) ($row['paid_referral_status'] ?? $row['repeat_action_status'] ?? '');
					if ($repeat !== '') { $stats['repeat_action_count']++; }
					$actor = (string) ($row['referral_target_scope'] ?? $row['repeat_action_actor_scope'] ?? '');
					if ($actor === 'self' || $actor === 'seller') { $stats['repeat_action_seller']++; }
					if ($actor === 'supervisor') { $stats['repeat_action_supervisor']++; }
					if ($actor === 'senior_supervisor') { $stats['repeat_action_senior_supervisor']++; }
				}
				return $stats;
			}

