			private function sn_render_hierarchy_sales_breakdown(int $actor_id, string $context = ''): void
			{
				$groups = [];
				foreach (['senior_supervisor' => 'سرپرست‌های ارشد', 'supervisor' => 'سرپرست‌ها', 'seller' => 'فروشنده‌ها'] as $position => $label) {
					$children = current_user_can('manage_options') ? $this->sn_hr_all_users_by_position($position) : $this->sn_get_descendant_users($actor_id, $position);
					foreach ($children as $child) {
						$uid = (int)($child['user_id'] ?? 0); if ($uid < 1) { continue; }
						$seller_ids = $position === 'seller' ? [$uid] : array_values(array_unique(array_map('intval', array_column($this->sn_get_descendant_users($uid, 'seller'), 'user_id'))));
						if ($position !== 'seller') { $seller_ids = array_values(array_unique(array_merge($seller_ids, array_map('intval', array_column($this->sn_get_direct_children($uid, 'seller'), 'user_id'))))); }
						$rows = [];
						if ($seller_ids) { $rows = $this->sn_scope_invoice_rows_for_panel($uid, $position, 500, [], true); }
						$stats = $this->sn_scope_invoice_stats($rows);
						$groups[] = ['level'=>$label,'user_id'=>$uid,'sellers'=>count($seller_ids),'approved_count'=>$stats['approved_count'],'approved_total'=>$stats['approved_total'],'invoice_count'=>$stats['count']];
					}
				}
				?>
				<div class="sn-card"><h3>جمع فروش زیرگروه‌ها</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>سطح</th><th>نیرو</th><th>فروشنده‌های زیرمجموعه</th><th>فاکتور</th><th>تاییدشده</th><th>جمع فروش تاییدشده</th></tr></thead><tbody>
				<?php if (! $groups) : ?><tr><td colspan="6"><div class="sn-empty-state">زیرگروهی برای گزارش فروش پیدا نشد.</div></td></tr><?php endif; ?>
				<?php foreach ($groups as $g) : ?><tr><td><?php echo esc_html($g['level']); ?></td><td><?php echo esc_html($this->sn_user_label((int)$g['user_id'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$g['sellers'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$g['invoice_count'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$g['approved_count'])); ?></td><td><?php echo esc_html(SN_Helpers::format_price((float)$g['approved_total'])); ?></td></tr><?php endforeach; ?>
				</tbody></table></div></div>
				<?php
