			public function ajax_seller_mark_recontact_status(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$actor_id = get_current_user_id();
				$position = $this->sn_hr_position_for_user($actor_id);
				if (! current_user_can('manage_options') && ! in_array($position, ['seller','converter','supervisor','senior_supervisor','sales_manager'], true)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$invoice_id = absint($_POST['invoice_id'] ?? 0);
				$new_status = sanitize_key(wp_unslash($_POST['new_status'] ?? 'pending'));
				if (! in_array($new_status, ['pending','pre_invoice','pending_payment','callback_scheduled','customer_followed'], true)) { $new_status = 'pending'; }
				global $wpdb;
				$inv = $invoice_id ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id), ARRAY_A) : null;
				if (! $inv) { SN_Helpers::send_json(false, 'فاکتور پیدا نشد'); return; }
				$seller_id = $this->sn_commission_invoice_seller_id_from_row($inv);
				$is_converter_owner = $position === 'converter' && $seller_id === $actor_id;
				if (! current_user_can('manage_options') && ! $is_converter_owner && ! $this->sn_user_can_issue_invoice_for_seller($actor_id, $seller_id)) { SN_Helpers::send_json(false, 'این فاکتور در محدوده شما نیست'); return; }
				$update = [
					'status' => $new_status,
					'invoice_status' => $new_status,
					'updated_at' => current_time('mysql'),
				];
				if ($new_status === 'pending_payment') { $update['payment_status'] = 'pending_payment'; }
				$ok = $wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', $update), ['id'=>$invoice_id]) !== false;
				if ($ok) { $this->sn_log_activity($invoice_id, (int)($inv['lead_id'] ?? 0), 'recontact_status_updated_by_expert', 'کارشناس وضعیت ارتباط مجدد را تغییر داد', ['actor_user_id'=>$actor_id,'seller_id'=>$seller_id,'new_status'=>$new_status]); }
				SN_Helpers::send_json($ok, $ok ? 'وضعیت ارتباط مجدد ثبت شد.' : 'ذخیره وضعیت انجام نشد', ['new_status'=>$new_status, 'label'=>SN_Helpers::status_label($new_status)]);
			}

			private function sn_current_hr_is_hr(): bool
			{
				$user = wp_get_current_user();
				$position = $this->sn_hr_position_for_user((int) $user->ID);
				return current_user_can('manage_options') || in_array('sn_hr', (array) $user->roles, true) || $position === 'hr';
			}

			private function sn_find_sales_manager_for_user(int $user_id): int
			{
				global $wpdb;
				if ($user_id < 1 || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_profiles') || ! $this->sn_table_exists_quiet($wpdb->prefix . 'sn_hr_assignments')) {
					return 0;
				}
				$profile_ids = $this->sn_hr_profile_ids_for_user($user_id);
				$seen = [];
				for ($i = 0; $i < 12 && $profile_ids; $i++) {
					$ph = implode(',', array_fill(0, count($profile_ids), '%d'));
					$parents = $wpdb->get_results($wpdb->prepare("SELECT parent_profile_id FROM {$wpdb->prefix}sn_hr_assignments WHERE child_profile_id IN ({$ph}) AND is_current=1", ...$profile_ids), ARRAY_A) ?: [];
					$next = [];
					foreach ($parents as $r) {
						$pid = (int) ($r['parent_profile_id'] ?? 0);
						if ($pid < 1 || isset($seen[$pid])) { continue; }
						$seen[$pid] = true;
						$pos = (string) $wpdb->get_var($wpdb->prepare("SELECT pos.slug FROM {$wpdb->prefix}sn_hr_profiles p INNER JOIN {$wpdb->prefix}sn_hr_positions pos ON pos.id=p.position_id WHERE p.id=%d", $pid));
						$uid = (int) $wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$wpdb->prefix}sn_hr_profiles WHERE id=%d", $pid));
						if ($pos === 'sales_manager' && $uid > 0) { return $uid; }
						$next[] = $pid;
					}
					$profile_ids = $next;
				}
				return 0;
			}

			private function sn_ensure_extra_number_requests_table(): bool
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_extra_number_requests';
				require_once ABSPATH . 'wp-admin/includes/upgrade.php';
				$charset = $wpdb->get_charset_collate();
				dbDelta("CREATE TABLE {$table} (
					id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
					seller_id BIGINT UNSIGNED NOT NULL,
					manager_id BIGINT UNSIGNED DEFAULT NULL,
					phone VARCHAR(20) NOT NULL,
					customer_name VARCHAR(160) DEFAULT NULL,
					note TEXT DEFAULT NULL,
					status VARCHAR(40) NOT NULL DEFAULT 'pending',
					approved_by BIGINT UNSIGNED DEFAULT NULL,
					approved_at DATETIME DEFAULT NULL,
					rejected_by BIGINT UNSIGNED DEFAULT NULL,
					rejected_at DATETIME DEFAULT NULL,
					reject_reason TEXT DEFAULT NULL,
					lead_id BIGINT UNSIGNED DEFAULT NULL,
					created_at DATETIME NOT NULL,
					updated_at DATETIME NOT NULL,
					PRIMARY KEY (id),
					KEY seller_id (seller_id),
					KEY manager_id (manager_id),
					KEY phone (phone),
					KEY status (status),
					KEY created_at (created_at)
				) {$charset};");
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					return false;
				}
				$required = [
					'seller_id' => 'BIGINT UNSIGNED NOT NULL DEFAULT 0',
					'manager_id' => 'BIGINT UNSIGNED DEFAULT NULL',
					'phone' => 'VARCHAR(20) NOT NULL DEFAULT \'\'',
					'customer_name' => 'VARCHAR(160) DEFAULT NULL',
					'note' => 'TEXT DEFAULT NULL',
					'status' => "VARCHAR(40) NOT NULL DEFAULT 'pending'",
					'approved_by' => 'BIGINT UNSIGNED DEFAULT NULL',
					'approved_at' => 'DATETIME DEFAULT NULL',
					'rejected_by' => 'BIGINT UNSIGNED DEFAULT NULL',
					'rejected_at' => 'DATETIME DEFAULT NULL',
					'reject_reason' => 'TEXT DEFAULT NULL',
					'lead_id' => 'BIGINT UNSIGNED DEFAULT NULL',
					'created_at' => 'DATETIME NULL',
					'updated_at' => 'DATETIME NULL',
				];
				$cols = (array) $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);
				foreach ($required as $col => $def) {
					if (! in_array($col, $cols, true)) {
						$wpdb->query("ALTER TABLE {$table} ADD COLUMN {$col} {$def}");
						$cols[] = $col;
					}
				}
				return true;
			}

			public function ajax_seller_request_extra_number(): void
			{
				try {
					if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) {
						SN_Helpers::send_json(false, 'دسترسی غیرمجاز');
						return;
					}
					$user_id = get_current_user_id();
					$position = '';
					try { $position = $this->sn_hr_position_for_user($user_id); } catch (Throwable $e) { $position = ''; }
					if ($position !== 'seller' && ! in_array('sn_seller', (array) wp_get_current_user()->roles, true) && ! current_user_can('manage_options')) {
						SN_Helpers::send_json(false, 'این درخواست فقط برای فروشنده است');
						return;
					}
					if (! $this->sn_user_can_request_extra_number($user_id)) {
						SN_Helpers::send_json(false, 'دسترسی درخواست شماره برای این حساب در HR غیرفعال است.');
						return;
					}
					$phone = SN_Helpers::normalize_mobile(sanitize_text_field(wp_unslash($_POST['phone'] ?? '')));
					$name = sanitize_text_field(wp_unslash($_POST['customer_name'] ?? ''));
					$note = sanitize_textarea_field(wp_unslash($_POST['note'] ?? ''));
					if (! $phone || ! SN_Helpers::validate_mobile($phone)) {
						SN_Helpers::send_json(false, 'شماره موبایل معتبر نیست');
						return;
					}
					global $wpdb;
					if (! $this->sn_ensure_extra_number_requests_table()) {
						error_log('SN extra-number table readiness failed: ' . sanitize_text_field((string) $wpdb->last_error));
						SN_Helpers::send_json(false, 'جدول درخواست شماره آماده نیست. یک بار صفحه مدیریت/افزونه را باز کنید یا migration را اجرا کنید.');
						return;
					}
					$table = $wpdb->prefix . 'sn_extra_number_requests';
					$exists = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE seller_id=%d AND phone=%s AND status IN ('pending','approved')", $user_id, $phone));
					if ($exists) {
						SN_Helpers::send_json(false, 'برای این شماره قبلاً درخواست ثبت شده است');
						return;
					}
					$manager_id = 0;
					try { $manager_id = $this->sn_find_sales_manager_for_user($user_id); } catch (Throwable $e) { $manager_id = 0; }
					$data = $this->sn_filter_existing_columns($table, [
						'seller_id' => $user_id,
						'manager_id' => $manager_id ?: null,
						'phone' => $phone,
						'customer_name' => $name,
						'note' => $note,
						'status' => 'pending',
						'created_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
					]);
					$ok = $wpdb->insert($table, $data) !== false;
					if ($ok) {
						try { $this->sn_log_activity(null, null, 'extra_number_requested', 'درخواست اضافه کردن شماره توسط فروشنده ثبت شد', ['seller_id'=>$user_id,'manager_id'=>$manager_id,'phone'=>$phone]); } catch (Throwable $e) {}
						SN_Helpers::send_json(true, $manager_id > 0 ? 'درخواست ثبت شد و برای مدیر فروش ارسال شد.' : 'درخواست ثبت شد؛ مدیر فروش بالادستی پیدا نشد و مدیرکل می‌تواند آن را بررسی کند.', ['request_id' => (int) $wpdb->insert_id, 'manager_id' => $manager_id]);
						return;
					}
					error_log('SN extra-number request insert failed for seller ' . $user_id . ': ' . sanitize_text_field((string) $wpdb->last_error));
					SN_Helpers::send_json(false, 'ثبت درخواست انجام نشد؛ لطفاً دوباره تلاش کنید.');
				} catch (Throwable $e) {
					error_log('SN extra-number request exception: ' . sanitize_text_field($e->getMessage()));
					SN_Helpers::send_json(false, 'خطای داخلی هنگام ثبت درخواست شماره؛ لطفاً دوباره تلاش کنید.');
				}
			}

			public function ajax_manager_review_extra_number(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$actor_id = get_current_user_id();
				$position = $this->sn_hr_position_for_user($actor_id);
				if (! current_user_can('manage_options') && $position !== 'sales_manager') { SN_Helpers::send_json(false, 'فقط مدیر فروش مجاز است'); return; }
				$id = absint($_POST['request_id'] ?? 0);
				$decision = sanitize_key(wp_unslash($_POST['decision'] ?? ''));
				$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				if (! $id || ! in_array($decision, ['approve','reject'], true)) { SN_Helpers::send_json(false, 'داده نامعتبر است'); return; }
				global $wpdb;
				if (! $this->sn_ensure_extra_number_requests_table()) { SN_Helpers::send_json(false, 'جدول درخواست شماره آماده نیست'); return; }
				$table = $wpdb->prefix . 'sn_extra_number_requests';
				$wpdb->query('START TRANSACTION');
				$row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d FOR UPDATE", $id));
				if (! $row) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'درخواست پیدا نشد'); return; }
				if (! current_user_can('manage_options') && (int) $row->manager_id !== $actor_id) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'این درخواست در محدوده شما نیست'); return; }
				if ((string) $row->status !== 'pending') { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'این درخواست قبلاً بررسی شده است'); return; }
				if ($decision === 'reject') {
					$updated = $wpdb->update($table, ['status'=>'rejected','rejected_by'=>$actor_id,'rejected_at'=>current_time('mysql'),'reject_reason'=>$reason,'updated_at'=>current_time('mysql')], ['id'=>$id,'status'=>'pending']);
					if ($updated !== 1) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'وضعیت درخواست تغییر نکرد؛ دوباره بررسی کنید'); return; }
					$wpdb->query('COMMIT');
					$this->sn_log_activity(null, null, 'extra_number_rejected', 'درخواست اضافه کردن شماره رد شد', ['request_id'=>$id,'actor_id'=>$actor_id,'reason'=>$reason]);
					SN_Helpers::send_json(true, 'درخواست رد شد.', ['request_id'=>$id,'status'=>'rejected','reason'=>$reason]);
					return;
				}
				$lead_table = $wpdb->prefix . 'sn_leads';
				$phone = SN_Helpers::normalize_mobile((string) $row->phone);
				if (! SN_Helpers::validate_mobile($phone) || (int) $row->seller_id < 1) {
					$wpdb->query('ROLLBACK');
					SN_Helpers::send_json(false, 'شماره یا فروشندهٔ درخواست معتبر نیست؛ درخواست همچنان در انتظار است');
					return;
				}
				if (! $this->sn_table_exists_quiet($lead_table)) {
					$wpdb->query('ROLLBACK');
					SN_Helpers::send_json(false, 'جدول لیدهای فروشنده آماده نیست؛ درخواست همچنان در انتظار است');
					return;
				}
				// Lock existing records before reusing them; never transfer another seller's lead.
				$variants = array_values(array_unique([$phone, substr($phone, 1), '98' . substr($phone, 1), '+98' . substr($phone, 1), '0098' . substr($phone, 1)]));
				$placeholders = implode(',', array_fill(0, count($variants), '%s'));
				$existing = $wpdb->get_results($wpdb->prepare("SELECT id, seller_id FROM {$lead_table} WHERE phone IN ({$placeholders}) ORDER BY id ASC FOR UPDATE", ...$variants));
				if ($wpdb->last_error !== '') {
					error_log('SN extra-number lookup failed for request ' . $id . ': ' . sanitize_text_field((string) $wpdb->last_error));
					$wpdb->query('ROLLBACK');
					SN_Helpers::send_json(false, 'بررسی شمارهٔ موجود انجام نشد؛ درخواست همچنان در انتظار است');
					return;
				}
				$lead_id = 0;
				foreach ((array) $existing as $existing_lead) {
					if ((int) $existing_lead->seller_id !== (int) $row->seller_id) {
						$wpdb->query('ROLLBACK');
						SN_Helpers::send_json(false, (int) $existing_lead->seller_id > 0
							? 'این شماره قبلاً به فروشندهٔ دیگری تخصیص یافته است؛ انتقال باید از مسیر توزیع انجام شود. درخواست همچنان در انتظار است.'
							: 'این شماره قبلاً در بانک لیدها ثبت شده است؛ تخصیص آن باید از مسیر توزیع انجام شود. درخواست همچنان در انتظار است.');
						return;
					}
					if ($lead_id < 1) { $lead_id = (int) $existing_lead->id; }
				}
				$created_lead = false;
				if ($lead_id < 1) {
					$inserted = $wpdb->insert($lead_table, $this->sn_filter_existing_columns($lead_table, [
						'phone' => $phone,
						// Requests allow 160 characters, while the lead schema allows 120.
						'customer_name' => wp_html_excerpt((string) $row->customer_name, 120, ''),
						'seller_id' => (int) $row->seller_id,
						'supervisor_id' => (int) get_user_meta((int) $row->seller_id, 'sn_supervisor_id', true) ?: null,
						'status' => 'assigned',
						'lead_status' => '',
						'source_tag' => 'approved_extra_number_request',
						'extra_number_request_id' => $id,
						'note' => (string) $row->note,
						'imported_at' => current_time('mysql'),
						'assigned_at' => current_time('mysql'),
						'created_at' => current_time('mysql'),
						'updated_at' => current_time('mysql'),
					]));
					$lead_id = $inserted !== false ? (int) $wpdb->insert_id : 0;
					if ($lead_id < 1) {
						error_log('SN extra-number lead insert failed for request ' . $id . ': ' . sanitize_text_field((string) $wpdb->last_error));
						$wpdb->query('ROLLBACK');
						SN_Helpers::send_json(false, 'ثبت شماره در بانک لیدها انجام نشد؛ درخواست همچنان در انتظار است. جزئیات خطا در گزارش خطای سرور ثبت شد.');
						return;
					}
					$created_lead = true;
				}
				$updated = $wpdb->update($table, ['status'=>'approved','approved_by'=>$actor_id,'approved_at'=>current_time('mysql'),'lead_id'=>$lead_id,'updated_at'=>current_time('mysql')], ['id'=>$id,'status'=>'pending']);
				if ($updated !== 1) { $wpdb->query('ROLLBACK'); SN_Helpers::send_json(false, 'ثبت تایید درخواست انجام نشد؛ درخواست را دوباره بررسی کنید'); return; }
				$wpdb->query('COMMIT');
				if ($created_lead && class_exists('SN_Campaign_Tracking')) {
					try { SN_Campaign_Tracking::capture_lead($lead_id, $phone); }
					catch (Throwable $e) { error_log('SN extra-number campaign tracking failed for request ' . $id . ': ' . sanitize_text_field($e->getMessage())); }
				}
				$this->sn_log_activity(null, $lead_id, 'extra_number_approved', 'درخواست اضافه کردن شماره تایید و به لید فروشنده اضافه شد', ['request_id'=>$id,'actor_id'=>$actor_id,'seller_id'=>(int)$row->seller_id,'phone'=>(string)$row->phone]);
				SN_Helpers::send_json(true, 'درخواست تایید شد و شماره به لیدهای فروشنده اضافه شد.', ['lead_id'=>$lead_id,'request_id'=>$id,'status'=>'approved']);
			}

			private function sn_render_manager_extra_number_requests(int $manager_id): void
			{
				global $wpdb;
				$this->maybe_create_tables();
				if (! $this->sn_ensure_extra_number_requests_table()) { echo '<div class="sn-notice sn-error">جدول درخواست شماره آماده نیست.</div>'; return; }
				$table = $wpdb->prefix . 'sn_extra_number_requests';
				$where = current_user_can('manage_options') ? '1=1' : $wpdb->prepare('manager_id=%d', $manager_id);
				$rows = $wpdb->get_results("SELECT * FROM {$table} WHERE {$where} ORDER BY id DESC LIMIT 100") ?: [];
				?>
				<div class="sn-card"><h3>درخواست‌های اضافه کردن شماره</h3><div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>فروشنده</th><th>شماره</th><th>نام مشتری</th><th>یادداشت</th><th>وضعیت</th><th>زمان</th><th>اقدام</th></tr></thead><tbody>
				<?php if (! $rows) : ?><tr><td colspan="7"><div class="sn-empty-state">درخواستی ثبت نشده است.</div></td></tr><?php endif; ?>
				<?php foreach ($rows as $r) : ?><tr data-request-id="<?php echo esc_attr((string)(int)$r->id); ?>"><td><?php echo esc_html($this->sn_user_label((int)$r->seller_id)); ?></td><td><code><?php echo esc_html((string)$r->phone); ?></code></td><td><?php echo esc_html((string)$r->customer_name); ?></td><td><?php echo esc_html((string)$r->note); ?></td><td><span class="sn-badge"><?php echo esc_html((string)$r->status); ?></span></td><td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string)$r->created_at)); ?></td><td><?php if ((string)$r->status === 'pending') : ?><button type="button" class="sn-btn sn-btn-sm sn-extra-number-approve" data-id="<?php echo esc_attr((string)(int)$r->id); ?>">تایید</button> <button type="button" class="sn-btn sn-btn-sm sn-extra-number-reject" data-id="<?php echo esc_attr((string)(int)$r->id); ?>">رد</button><?php else : ?>—<?php endif; ?></td></tr><?php endforeach; ?>
				</tbody></table></div></div>
				<?php
			}

			private function sn_team_date_filters(string $prefix): array
			{
				return [
					'date_from' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET[$prefix . '_from'] ?? ''))),
					'date_to' => SN_Helpers::jalali_to_gregorian_date(sanitize_text_field(wp_unslash($_GET[$prefix . '_to'] ?? ''))),
				];
			}

			private function sn_distribution_assigned_count_for_seller(int $seller_id, array $filters): int
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_distribution_items';
				if (! $this->sn_table_exists_quiet($table)) { return 0; }
				$where = ['current_owner_user_id=%d'];
				$args = [$seller_id];
				if (! empty($filters['date_from'])) { $where[] = 'created_at >= %s'; $args[] = $filters['date_from'] . ' 00:00:00'; }
				if (! empty($filters['date_to'])) { $where[] = 'created_at <= %s'; $args[] = $filters['date_to'] . ' 23:59:59'; }
				return (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE " . implode(' AND ', $where), ...$args));
			}

			private function sn_extra_number_count_for_seller(int $seller_id, array $filters): int
			{
				global $wpdb;
				$table = $wpdb->prefix . 'sn_extra_number_requests';
				if (! $this->sn_table_exists_quiet($table)) { return 0; }
				$where = ['seller_id=%d','status=%s']; $args = [$seller_id, 'approved'];
				if (! empty($filters['date_from'])) { $where[] = 'approved_at >= %s'; $args[] = $filters['date_from'] . ' 00:00:00'; }
				if (! empty($filters['date_to'])) { $where[] = 'approved_at <= %s'; $args[] = $filters['date_to'] . ' 23:59:59'; }
				return (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE " . implode(' AND ', $where), ...$args));
			}

			private function sn_render_team_seller_daily_stats(int $actor_id, string $context = ''): void
			{
				$filters = $this->sn_team_date_filters('sn_team_date');
				$filter_date_from_value = sanitize_text_field(wp_unslash($_GET['sn_team_date_from'] ?? ''));
				$filter_date_to_value = sanitize_text_field(wp_unslash($_GET['sn_team_date_to'] ?? ''));
				$sellers = current_user_can('manage_options') ? array_map('intval', array_column($this->sn_hr_all_users_by_position('seller'), 'user_id')) : array_values(array_unique(array_map('intval', array_column($this->sn_get_descendant_users($actor_id, 'seller'), 'user_id'))));
				if ($this->sn_hr_position_for_user($actor_id) === 'seller') { $sellers = [$actor_id]; }
				$rows = [];
				foreach ($sellers as $seller_id) {
					$single = [$seller_id];
					$inv_count = $this->sn_sales_deputy_count_invoices($single, $filters);
					$paid_count = $this->sn_sales_deputy_count_invoices($single, $filters, 'paid');
					$total_amount = $this->sn_sales_deputy_sum_invoices($single, $filters);
					$paid_amount = $this->sn_sales_deputy_sum_payments($single, $filters);
					$rows[] = [
						'seller_id' => $seller_id,
						'label' => $this->sn_user_label($seller_id),
						'assigned' => $this->sn_distribution_assigned_count_for_seller($seller_id, $filters),
						'extra_approved' => $this->sn_extra_number_count_for_seller($seller_id, $filters),
						'invoices' => $inv_count,
						'paid' => $paid_count,
						'sales' => $paid_amount,
						'revenue' => $paid_amount,
						'rejected' => $this->sn_sales_deputy_count_invoices($single, $filters, 'rejected'),
						'total_amount' => $total_amount,
						'paid_amount' => $paid_amount,
					];
				}
				?>
				<div class="sn-card sn-team-daily-report"><h3>گزارش عملکرد فروشنده‌ها بر اساس بازه تاریخ</h3>
				<form method="get" class="sn-filter-bar"><label>از تاریخ<input type="text" class="sn-jalali-date" name="sn_team_date_from" value="<?php echo esc_attr($filter_date_from_value); ?>" placeholder="1403/02/18"></label><label>تا تاریخ<input type="text" class="sn-jalali-date" name="sn_team_date_to" value="<?php echo esc_attr($filter_date_to_value); ?>" placeholder="1403/02/18"></label><button type="submit" class="sn-btn">اعمال فیلتر</button></form>
				<div class="sn-table-wrap"><table class="sn-table"><thead><tr><th>فروشنده</th><th>دیتای تخصیص‌شده</th><th>درخواست شماره تاییدشده</th><th>فاکتور</th><th>تایید/پرداخت</th><th>رد/برگشت</th><th>جمع مبلغ</th><th>فروش تاییدشده</th><th>درصد شماره درخواستی</th></tr></thead><tbody>
				<?php if (! $rows) : ?><tr><td colspan="9"><div class="sn-empty-state">فروشنده‌ای در این محدوده پیدا نشد.</div></td></tr><?php endif; ?>
				<?php foreach ($rows as $r) : $den=max(1,(int)$r['assigned']+(int)$r['extra_approved']); $pct=round(((int)$r['extra_approved']/$den)*100,1); ?><tr><td><?php echo esc_html($r['label']); ?></td><td><?php echo esc_html(number_format_i18n((int)$r['assigned'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$r['extra_approved'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$r['invoices'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$r['paid'])); ?></td><td><?php echo esc_html(number_format_i18n((int)$r['rejected'])); ?></td><td><?php echo esc_html(SN_Helpers::format_price((float)$r['total_amount'])); ?></td><td><?php echo esc_html(SN_Helpers::format_price((float)$r['paid_amount'])); ?></td><td><?php echo esc_html(number_format_i18n($pct)); ?>٪</td></tr><?php endforeach; ?>
				</tbody></table></div></div>
				<?php
			}

			public function ajax_paid_referral_cancel(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				$invoice_id = absint($_POST['invoice_id'] ?? 0);
				$item_id = absint($_POST['item_id'] ?? 0);
				$reason = sanitize_textarea_field(wp_unslash($_POST['reason'] ?? ''));
				global $wpdb;
				$actor = get_current_user_id();
				$ok = false;
				if ($reason === '') { SN_Helpers::send_json(false, 'دلیل انصراف الزامی است'); return; }
				if (($invoice_id > 0) === ($item_id > 0)) { SN_Helpers::send_json(false, 'یک پرونده معتبر انتخاب کنید'); return; }
				if ($invoice_id > 0) {
					$inv = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_invoices WHERE id=%d", $invoice_id));
					if (! $inv) { SN_Helpers::send_json(false, 'فاکتور یافت نشد'); return; }
					$seller_id = (int) ($inv->seller_id ?? 0);
					if (! current_user_can('manage_options') && $seller_id !== $actor) { SN_Helpers::send_json(false, 'این مورد متعلق به شما نیست'); return; }
					$ok = $wpdb->update($wpdb->prefix.'sn_invoices', $this->sn_filter_existing_columns($wpdb->prefix.'sn_invoices', ['status'=>'cancelled','invoice_status'=>'cancelled','repeat_action_status'=>'cancelled_by_seller','repeat_action_cancel_reason'=>$reason,'updated_at'=>current_time('mysql')]), ['id'=>$invoice_id]) !== false;
					if ($ok) { $this->sn_log_activity($invoice_id, (int)($inv->lead_id ?? 0), 'paid_referral_cancelled_by_seller', 'فاکتور/اقدام مجدد توسط فروشنده کنسل شد', ['actor_user_id'=>$actor,'reason'=>$reason,'parent_invoice_id'=>(int)($inv->parent_invoice_id ?? 0)]); }
				}
				if ($item_id > 0 && $this->sn_table_exists_quiet($wpdb->prefix.'sn_distribution_items')) {
					$item = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}sn_distribution_items WHERE id=%d", $item_id));
					if (! $item || (string)($item->source_type??'') !== 'paid_invoice_referral' || (string)($item->workflow_kind??'') === 'invoice_payment_completion' || (! current_user_can('manage_options') && (int)($item->current_owner_user_id ?? 0) !== $actor)) { SN_Helpers::send_json(false, 'این پرونده قابل انصراف توسط شما نیست'); return; }
					if (in_array((string)($item->status??''), ['referral_cancelled','converted','lead_created','live_lead_created','archived'], true)) { SN_Helpers::send_json(false, 'وضعیت فعلی پرونده قابل انصراف نیست'); return; }
					$ok = $wpdb->update($wpdb->prefix.'sn_distribution_items', $this->sn_filter_existing_columns($wpdb->prefix.'sn_distribution_items', ['status'=>'referral_cancelled','seller_notes'=>trim((string)($item->seller_notes ?? '') . "\nدلیل انصراف: " . $reason),'updated_at'=>current_time('mysql')]), ['id'=>$item_id,'status'=>(string)$item->status]) === 1;
					if ($ok) { $this->sn_distribution_log($item_id, 'paid_referral_cancelled_by_seller', $actor, (int)($item->current_owner_user_id ?? 0), (int)($item->final_seller_user_id ?? 0), (string)($item->current_owner_position ?? ''), 'seller', 999, 'کنسل/انصراف نیاز به اقدام مجدد', ['reason'=>$reason,'previous_status'=>(string)$item->status,'ref_invoice_id'=>(int)($item->ref_invoice_id ?? 0)]); }
				}
				SN_Helpers::send_json((bool)$ok, $ok ? 'کنسل/انصراف ثبت شد.' : 'ثبت تغییر انجام نشد', $ok ? ['reason'=>$reason,'item_id'=>$item_id,'status'=>'referral_cancelled'] : []);
			}

			public function ajax_paid_referral_restore(): void
			{
				if (! is_user_logged_in() || ! check_ajax_referer('sn_public', 'nonce', false)) { SN_Helpers::send_json(false, 'دسترسی غیرمجاز'); return; }
				global $wpdb;
				$id = absint($_POST['item_id'] ?? 0);
				$actor = get_current_user_id();
				$table = $wpdb->prefix . 'sn_distribution_items';
				$item = $id && $this->sn_table_exists_quiet($table) ? $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d", $id)) : null;
				if (! $item || (string)($item->source_type??'') !== 'paid_invoice_referral' || (string)($item->workflow_kind??'') === 'invoice_payment_completion' || (string)($item->status??'') !== 'referral_cancelled' || (! current_user_can('manage_options') && (int)($item->current_owner_user_id??0) !== $actor)) { SN_Helpers::send_json(false, 'این پرونده در وضعیت قابل بازگردانی نیست'); return; }
				$restored = $wpdb->update($table, ['status'=>'needs_repeat_action','updated_at'=>current_time('mysql')], ['id'=>$id,'status'=>'referral_cancelled']);
				if ($restored !== 1) { SN_Helpers::send_json(false, 'بازگردانی پرونده انجام نشد'); return; }
				$this->sn_distribution_log($id, 'paid_referral_restored', $actor, (int)$item->current_owner_user_id, (int)$item->current_owner_user_id, (string)($item->current_owner_position??''), (string)($item->current_owner_position??''), 999, 'پرونده انصرافی بازگردانده شد', ['previous_status'=>'referral_cancelled','original_cancel_reason'=>(string)($item->seller_notes??'')]);
				SN_Helpers::send_json(true, 'پرونده بازگردانده شد', ['item_id'=>$id,'status'=>'needs_repeat_action']);
			}

			private function sn_payment_reward_table(): string
			{
				global $wpdb;
				return $wpdb->prefix . 'sn_payment_reward_claims';
			}

			/** Payment reward referrals are retired, regardless of old product/settings flags. */
			private function sn_payment_rewards_enabled(): bool
			{
				return false;
			}

			private function sn_invoice_has_payment_reward($invoice): bool
			{
				if (! $this->sn_payment_rewards_enabled()) { return false; }
				global $wpdb;
				$invoice_id = (int) (is_array($invoice) ? ($invoice['id'] ?? 0) : ($invoice->id ?? 0));
				$product_id = (int) (is_array($invoice) ? ($invoice['product_id'] ?? 0) : ($invoice->product_id ?? 0));
				if ($product_id > 0 && get_post_meta($product_id, '_sn_payment_reward_enabled', true) === '1') {
					return true;
				}
				if ($invoice_id < 1) {
					return false;
				}
				$items_table = $wpdb->prefix . 'sn_invoice_items';
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $items_table)) !== $items_table) {
					return false;
				}
				$product_ids = $wpdb->get_col($wpdb->prepare("SELECT product_id FROM {$items_table} WHERE invoice_id=%d", $invoice_id));
				foreach ((array) $product_ids as $pid) {
					if ((int) $pid > 0 && get_post_meta((int) $pid, '_sn_payment_reward_enabled', true) === '1') {
						return true;
					}
				}
				return false;
			}

			private function sn_payment_reward_invoice_product_label($invoice): array
			{
				global $wpdb;
				$invoice_id = (int) (is_array($invoice) ? ($invoice['id'] ?? 0) : ($invoice->id ?? 0));
				$product_id = (int) (is_array($invoice) ? ($invoice['product_id'] ?? 0) : ($invoice->product_id ?? 0));
				$product_name = $product_id > 0 ? (string) get_the_title($product_id) : '';
				$items_table = $wpdb->prefix . 'sn_invoice_items';
				if ($invoice_id > 0 && $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $items_table)) === $items_table) {
					$items = $wpdb->get_results($wpdb->prepare("SELECT product_id, product_name FROM {$items_table} WHERE invoice_id=%d ORDER BY id ASC", $invoice_id), ARRAY_A);
					foreach ((array) $items as $item) {
						$pid = (int) ($item['product_id'] ?? 0);
						if ($pid > 0 && get_post_meta($pid, '_sn_payment_reward_enabled', true) === '1') {
							$product_id = $pid;
							$product_name = (string) (($item['product_name'] ?? '') ?: get_the_title($pid));
							break;
						}
					}
					if ($product_name === '' && ! empty($items[0])) {
						$product_id = (int) ($items[0]['product_id'] ?? $product_id);
						$product_name = (string) (($items[0]['product_name'] ?? '') ?: ($product_id ? get_the_title($product_id) : ''));
					}
				}
				return ['product_id' => $product_id, 'product_name' => $product_name];
			}

			private function sn_send_payment_reward_sms(string $reward_phone, $invoice, string $product_name): array
			{
				if (! $this->sn_payment_rewards_enabled()) { return ['sent'=>0, 'status'=>'disabled', 'pattern'=>'', 'template'=>'', 'error'=>'']; }
				$reward_phone = SN_Helpers::normalize_mobile($reward_phone);
				$sms = class_exists('SN_SMS') ? new SN_SMS() : null;
				$pattern = $sms ? $sms->event_pattern('payment_reward') : '';
				$template = trim((string) get_option('sn_payment_reward_sms_template', 'سلام، یک جایزه از طرف {customer_name} برای شما ثبت شد. کد فاکتور: {invoice_code}'));
				$enabled = get_option('sn_payment_reward_sms_enabled', '1') === '1';
				if (! $enabled) {
					return ['sent' => 0, 'status' => 'disabled', 'pattern' => $pattern, 'template' => $template, 'error' => ''];
				}
				if (! class_exists('SN_SMS')) {
					return ['sent' => 0, 'status' => 'error', 'pattern' => $pattern, 'template' => $template, 'error' => 'SN_SMS class not found'];
				}
				$invoice_url = method_exists($this, 'sn_invoice_public_url') ? $this->sn_invoice_public_url($invoice) : '';
				$vars = [
					'{customer_name}' => (string) ($invoice->customer_name ?? ''),
					'{invoice_code}' => (string) ($invoice->invoice_code ?? ''),
					'{invoice_url}' => $invoice_url,
					'{reward_phone}' => $reward_phone,
					'{product_name}' => $product_name,
				];
				try {
					$sms = new SN_SMS();
					$ok = false;
					if ($pattern !== '') {
						$ok = (bool) $sms->send_event_pattern($reward_phone, 'payment_reward', [
							'customer_name' => (string) ($invoice->customer_name ?? ''),
							'invoice_code' => (string) ($invoice->invoice_code ?? ''),
							'invoice_url' => $invoice_url,
							'reward_phone' => $reward_phone,
							'product_name' => $product_name,
						]);
					} else {
						$message = strtr($template, $vars);
						$ok = method_exists($sms, 'send') ? (bool) $sms->send($reward_phone, $message) : false;
					}
					return ['sent' => $ok ? 1 : 0, 'status' => $ok ? 'sent' : 'failed', 'pattern' => $pattern, 'template' => $template, 'error' => $ok ? '' : $sms->get_last_error()];
				} catch (\Throwable $e) {
					return ['sent' => 0, 'status' => 'error', 'pattern' => $pattern, 'template' => $template, 'error' => $e->getMessage()];
				}
			}

			public function ajax_submit_payment_reward_contact(): void
			{
				if (! $this->sn_payment_rewards_enabled()) {
					SN_Helpers::send_json(false, 'ثبت جایزه پرداخت غیرفعال است');
					return;
				}
				if (! check_ajax_referer('sn_public', 'nonce', false)) {
					SN_Helpers::send_json(false, 'نانس نامعتبر');
					return;
				}
				$code = sanitize_text_field(wp_unslash($_POST['invoice_code'] ?? ''));
				$token = $this->sn_public_access_token();
				$reward_phone = SN_Helpers::normalize_mobile((string) wp_unslash($_POST['reward_phone'] ?? ''));
				if ($code === '') {
					SN_Helpers::send_json(false, 'کد فاکتور نامعتبر است');
					return;
				}
				if (! preg_match('/^09\d{9}$/', $reward_phone)) {
					SN_Helpers::send_json(false, 'شماره موبایل معتبر وارد کنید');
					return;
				}
				$access = $this->sn_validate_public_invoice_access($code, $token, 'payment_reward_contact');
				if (empty($access['success']) || empty($access['invoice'])) {
					SN_Helpers::send_json(false, (string) ($access['message'] ?? 'لینک فاکتور معتبر نیست'));
					return;
				}
				$invoice = $access['invoice'];
				$customer_phone = SN_Helpers::normalize_mobile((string) ($invoice->customer_phone ?? ''));
				if ($customer_phone !== '' && $reward_phone === $customer_phone) {
					SN_Helpers::send_json(false, 'شماره جایزه نباید همان شماره مشتری فاکتور باشد');
					return;
				}
				$status = (string) ($invoice->status ?? '');
				$payment_status = (string) ($invoice->payment_status ?? '');
				if (! in_array($status, ['paid', 'approved'], true) && ! in_array($payment_status, ['paid', 'approved'], true)) {
					SN_Helpers::send_json(false, 'ثبت شماره جایزه فقط بعد از پرداخت موفق فعال است');
					return;
				}
				if (! $this->sn_invoice_has_payment_reward($invoice)) {
					SN_Helpers::send_json(false, 'برای این محصول جایزه پرداخت فعال نیست');
					return;
				}
				global $wpdb;
				$table = $this->sn_payment_reward_table();
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					SN_Activator::activate();
				}
				$existing = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE invoice_id=%d LIMIT 1", (int) $invoice->id), ARRAY_A);
				if ($existing) {
					SN_Helpers::send_json(true, 'شماره جایزه قبلاً برای این فاکتور ثبت شده است', ['reward_phone' => (string) ($existing['reward_phone'] ?? '')]);
					return;
				}
				$product = $this->sn_payment_reward_invoice_product_label($invoice);
				$sms = $this->sn_send_payment_reward_sms($reward_phone, $invoice, (string) $product['product_name']);
				$data = [
					'invoice_id' => (int) $invoice->id,
					'invoice_code' => (string) ($invoice->invoice_code ?? $code),
					'product_id' => (int) $product['product_id'],
					'product_name' => (string) $product['product_name'],
					'customer_name' => (string) ($invoice->customer_name ?? ''),
					'customer_phone' => $customer_phone,
					'reward_phone' => $reward_phone,
					'sms_sent' => (int) $sms['sent'],
					'sms_status' => (string) $sms['status'],
					'sms_pattern' => (string) $sms['pattern'],
					'sms_template' => (string) $sms['template'],
					'sms_error' => (string) $sms['error'],
					'ip_address' => sanitize_text_field((string) ($_SERVER['REMOTE_ADDR'] ?? '')),
					'user_agent' => substr(sanitize_textarea_field((string) ($_SERVER['HTTP_USER_AGENT'] ?? '')), 0, 1000),
					'created_at' => current_time('mysql'),
					'updated_at' => current_time('mysql'),
				];
				$ok = $wpdb->insert($table, $data) !== false;
				if (! $ok) {
					SN_Helpers::send_json(false, 'ثبت شماره جایزه انجام نشد');
					return;
				}
				$this->sn_log_activity((int) $invoice->id, (int) ($invoice->lead_id ?? 0), 'payment_reward_contact_submitted', 'شماره دریافت‌کننده جایزه ثبت شد', ['reward_phone' => $reward_phone, 'sms_status' => $sms['status']]);
				SN_Helpers::send_json(true, 'شماره جایزه ثبت شد' . ((int) $sms['sent'] === 1 ? ' و پیامک ارسال شد.' : '.'), ['reward_phone' => $reward_phone, 'sms_status' => (string) $sms['status']]);
			}

			public function render_admin_payment_rewards(): void
			{
				if (! current_user_can('manage_options')) {
					wp_die('دسترسی غیرمجاز');
				}
				global $wpdb;
				$table = $this->sn_payment_reward_table();
				if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
					SN_Activator::activate();
				}
				$q = sanitize_text_field(wp_unslash($_GET['s'] ?? ''));
				$status = sanitize_text_field(wp_unslash($_GET['sms_status'] ?? ''));
				$where = '1=1';
				$args = [];
				if ($q !== '') {
					$like = '%' . $wpdb->esc_like($q) . '%';
					$where .= ' AND (invoice_code LIKE %s OR customer_name LIKE %s OR customer_phone LIKE %s OR reward_phone LIKE %s OR product_name LIKE %s)';
					array_push($args, $like, $like, $like, $like, $like);
				}
				if ($status !== '') {
					$where .= ' AND sms_status=%s';
					$args[] = $status;
				}
				$sql = "SELECT * FROM {$table} WHERE {$where} ORDER BY id DESC LIMIT 300";
				$rows = $args ? $wpdb->get_results($wpdb->prepare($sql, $args), ARRAY_A) : $wpdb->get_results($sql, ARRAY_A);
				$base_url = menu_page_url('sn-payment-rewards', false);
				?>
				<div class="wrap sn-admin-wrap">
					<h1>جوایز پرداختی</h1>
					<p>شماره‌هایی که بعد از پرداخت آنلاین موفق برای محصولات جایزه‌دار ثبت شده‌اند.</p>
					<form method="get" style="display:flex;gap:8px;align-items:end;flex-wrap:wrap;margin:14px 0">
						<input type="hidden" name="page" value="sn-payment-rewards">
						<label>جستجو<br><input type="search" name="s" value="<?php echo esc_attr($q); ?>" placeholder="فاکتور، مشتری، شماره"></label>
						<label>وضعیت پیامک<br><select name="sms_status"><option value="">همه</option><?php foreach (['sent'=>'ارسال شده','failed'=>'ناموفق','error'=>'خطا','disabled'=>'غیرفعال'] as $k=>$v) : ?><option value="<?php echo esc_attr($k); ?>" <?php selected($status, $k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label>
						<button class="button button-primary" type="submit">فیلتر</button>
						<a class="button" href="<?php echo esc_url($base_url); ?>">پاک کردن</a>
					</form>
					<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="margin:10px 0">
						<input type="hidden" name="action" value="sn_export_payment_rewards">
						<input type="hidden" name="s" value="<?php echo esc_attr($q); ?>">
						<input type="hidden" name="sms_status" value="<?php echo esc_attr($status); ?>">
						<?php wp_nonce_field('sn_export_payment_rewards'); ?>
						<button class="button" type="submit">خروجی CSV</button>
					</form>
					<table class="widefat striped">
						<thead><tr><th>ID</th><th>فاکتور</th><th>مشتری</th><th>شماره مشتری</th><th>شماره جایزه</th><th>محصول</th><th>وضعیت پیامک</th><th>خطا</th><th>تاریخ</th></tr></thead>
						<tbody>
						<?php if (! $rows) : ?><tr><td colspan="9">رکوردی ثبت نشده است.</td></tr><?php endif; ?>
						<?php foreach ($rows as $r) : ?>
							<tr>
								<td><?php echo esc_html((string) ($r['id'] ?? '')); ?></td>
								<td><code><?php echo esc_html((string) ($r['invoice_code'] ?? '')); ?></code></td>
								<td><?php echo esc_html((string) ($r['customer_name'] ?? '')); ?></td>
								<td><?php echo esc_html((string) ($r['customer_phone'] ?? '')); ?></td>
								<td><strong><?php echo esc_html((string) ($r['reward_phone'] ?? '')); ?></strong></td>
								<td><?php echo esc_html((string) ($r['product_name'] ?? '')); ?></td>
								<td><?php echo esc_html((string) ($r['sms_status'] ?? '')); ?></td>
								<td><?php echo esc_html((string) ($r['sms_error'] ?? '')); ?></td>
								<td><?php echo esc_html(SN_Helpers::gregorian_to_jalali_date((string) ($r['created_at'] ?? ''))); ?></td>
							</tr>
