			public function handle_export_payment_rewards(): void
			{
				if (! current_user_can('manage_options')) {
					wp_die('دسترسی غیرمجاز');
				}
				check_admin_referer('sn_export_payment_rewards');
				global $wpdb;
				$table = $this->sn_payment_reward_table();
				$q = sanitize_text_field(wp_unslash($_POST['s'] ?? ''));
				$status = sanitize_text_field(wp_unslash($_POST['sms_status'] ?? ''));
				$where = '1=1';
				$args = [];
				if ($q !== '') {
					$like = '%' . $wpdb->esc_like($q) . '%';
					$where .= ' AND (invoice_code LIKE %s OR customer_name LIKE %s OR customer_phone LIKE %s OR reward_phone LIKE %s OR product_name LIKE %s)';
					array_push($args, $like, $like, $like, $like, $like);
				}
				if ($status !== '') {
					$where .= ' AND sms_status=%s';
					$args[] = $status;
				}
				$sql = "SELECT * FROM {$table} WHERE {$where} ORDER BY id DESC";
				$rows = $args ? $wpdb->get_results($wpdb->prepare($sql, $args), ARRAY_A) : $wpdb->get_results($sql, ARRAY_A);
				nocache_headers();
				header('Content-Type: text/csv; charset=UTF-8');
				header('Content-Disposition: attachment; filename=sn-payment-rewards-' . SN_Helpers::tehran_format('Ymd-His') . '.csv');
				$out = fopen('php://output', 'w');
				fprintf($out, chr(0xEF) . chr(0xBB) . chr(0xBF));
				fputcsv($out, ['ID','invoice_code','customer_name','customer_phone','reward_phone','product_name','sms_status','sms_sent','sms_error','created_at']);
				foreach ((array) $rows as $r) {
					fputcsv($out, [
						$r['id'] ?? '',
						$r['invoice_code'] ?? '',
						$r['customer_name'] ?? '',
						$r['customer_phone'] ?? '',
						$r['reward_phone'] ?? '',
						$r['product_name'] ?? '',
						$r['sms_status'] ?? '',
						$r['sms_sent'] ?? '',
						$r['sms_error'] ?? '',
						$r['created_at'] ?? '',
					]);
				}
				fclose($out);
				exit;
			}


		}
